Object.assign(window.DEEP = window.DEEP || {}, {
 "L'équilibre": {"pos":"n.m. 阳性名词，复数 équilibres","s":"平衡；均衡。可指身体平衡（perdre l'équilibre 失去平衡），也可指生活、饮食中的平衡（un repas équilibré 均衡的一餐）。","ipa":"[e.ki.libʁ]","ph":"é [e]；qu [k]；-ibre 结尾的 e 不发音，只读 [libʁ]。l'équilibre 里 l' 是省音，连着读。","pi":"qu 读 [k]，不读 [kw]；结尾 -re 的 e 不发音；注意 r 是小舌音 [ʁ]。","et":"来自拉丁语 aequilibrium：aequus（相等）+ libra（天平）。","ex":[["L'équilibre est nécessaire.","平衡是必要的。"],["Il perd l'équilibre et tombe.","他失去平衡摔倒了。"]],"co":[["perdre l'équilibre","失去平衡"],["garder / retrouver son équilibre","保持 / 恢复平衡"],["un repas équilibré","均衡的一餐"]],"sy":[["stabilité","courant","稳定"],["déséquilibre","courant","反义：失衡"]],"fq":"中高频，日常常用。","me":"équi-（相等）+ libra（天平）：两边一样重。","tr":{"zh":"骑自行车需要平衡。","fr":"Il faut de l'équilibre pour faire du vélo.","alt":"Faire du vélo, ça demande de l'équilibre.","note":"il faut + 部分冠词 + 名词，表示「需要……」。"}},
 "Le bricolage": {"pos":"n.m. 阳性名词，一般不加复数","s":"手工活；自己动手修理、装修、做东西（DIY）。法国人周末常 faire du bricolage，修架子、刷墙、装灯等。","ipa":"[bʁi.kɔ.laʒ]","ph":"br [bʁ]；c 在 o 前读 [k]；-age 读 [aʒ]；结尾 e 不发音。","pi":"-age 读 [aʒ]；g 在 e 前读 [ʒ]，不是 [g]。","et":"来自动词 bricoler，再加后缀 -age。同族词：bricoleur（爱动手的人）、magasin de bricolage（五金建材店）。","ex":[["Il aime le bricolage.","他喜欢做手工修理。"],["Samedi, je fais du bricolage à la maison.","星期六我在家做点修修补补的活。"]],"co":[["faire du bricolage","做手工、修修补补"],["un magasin de bricolage","五金建材店"],["une boîte à outils","工具箱"]],"sy":[["travaux","courant","施工、装修（更大的工程）"],["DIY","familier","英语借词，年轻人说"]],"fq":"中频，日常常用。","me":"bricol-age：-age 常表示「活动」，如 jardin-age。","tr":{"zh":"我爸爸周末喜欢做手工活。","fr":"Mon père aime faire du bricolage le week-end.","alt":"Mon père, le week-end, il adore bricoler.","note":"faire du + 活动名称，表示做这项活动。"}},
 "Le canoë-kayak": {"pos":"n.m. 阳性名词，运动名称一般不加复数；复数 canoës-kayaks","s":"皮划艇运动，包括划艇（canoë）和皮艇（kayak）。说「划皮划艇」用 faire du canoë-kayak。","ipa":"[ka.nɔ.e.ka.jak]","ph":"canoë 读 [ka.nɔ.e]，ë 上面的两点表示 o 和 e 分开读；kayak 读 [ka.jak]，y 读 [j]；末尾 k 要发音。","pi":"ë 要和前面的 o 分开读成两个音节；kayak 末尾的 k 要发出来，不是不发音。","et":"canoë 经西班牙语 canoa 来自加勒比地区的原住民语言；kayak 来自因纽特语。","ex":[["Nous faisons du canoë-kayak.","我们划皮划艇。"],["Elle fait du canoë-kayak sur la rivière.","她在河上划皮划艇。"]],"co":[["faire du canoë-kayak","划皮划艇"],["un club de canoë-kayak","皮划艇俱乐部"],["descendre une rivière en kayak","划皮艇顺流而下"]],"sy":[["kayak","courant","皮艇（单词，坐着划双桨）"],["canoë","courant","划艇（单桨）"],["rafting","courant","漂流（不同的运动）"]],"fq":"低频，休闲运动话题。","me":"ca-no-ë：ë 上的两点提醒 o 和 e 分开读。","tr":{"zh":"夏天我们在河上划皮划艇。","fr":"En été, nous faisons du canoë-kayak sur la rivière.","alt":"L'été, on fait du canoë-kayak sur la rivière.","note":"faire du + 运动名称；口语中 on 常代替 nous。"}},
 "Le château de Versailles": {"pos":"n.m. 阳性名词（château），复数 châteaux","s":"凡尔赛宫，巴黎西边的王宫，路易十四扩建而成，是法国最有名的景点之一。château 平时指「城堡；宫殿」。","ipa":"[ʃɑ.to də vɛʁ.saj]","ph":"ch [ʃ]；â [ɑ]（常读成 [a]）；eau [o]；Versailles 里 -illes 读 [j]，结尾 -es 不发音，读 [vɛʁ.saj]。","pi":"châteaux 复数是 -eaux；Versailles 结尾 -lles 读 [j]，不发 s。","et":"château 来自拉丁语 castellum（小要塞）。Versailles 是地名。","ex":[["Le château de Versailles est grand.","凡尔赛宫很大。"],["Nous visitons le château de Versailles dimanche.","我们星期天参观凡尔赛宫。"]],"co":[["visiter le château de Versailles","参观凡尔赛宫"],["la galerie des Glaces","镜厅（凡尔赛宫内）"],["les jardins de Versailles","凡尔赛花园"]],"sy":[["palais","courant","宫殿（泛指）"],["château","courant","城堡、宫邸"]],"fq":"文化话题常见。","me":"Versailles 读 [vɛʁ.saj]：结尾像 aille。","tr":{"zh":"我想参观凡尔赛宫。","fr":"Je voudrais visiter le château de Versailles.","alt":"J'aimerais bien voir le château de Versailles.","note":"je voudrais + 动词原形，礼貌地表达想法。"}},
 "Le hip hop": {"pos":"n.m. 阳性名词，不加复数","s":"嘻哈（音乐与舞蹈文化）。可指音乐，也可指舞蹈：danser le hip hop。","ipa":"[ip.ɔp]","ph":"h 不发音；i [i]；p 在词尾要读出来；o [ɔ]。hip hop 的 h 是「嘘音 h」（h aspiré），所以 le 不省音，也不连读。","pi":"说 le hip hop，不是 l'hip hop；两个 h 都不发音，读起来像 [ip ɔp]。","et":"来自美国英语 hip hop，20 世纪 70 年代出现在纽约。","ex":[["J'adore le hip hop.","我爱嘻哈。"],["Elle danse le hip hop depuis dix ans.","她跳街舞已经十年了。"]],"co":[["écouter du hip hop","听嘻哈"],["danser le hip hop","跳街舞"],["un cours de hip hop","街舞课"]],"sy":[["rap","courant","说唱（只指音乐）"],["street dance","courant","街舞（英语借词）"]],"fq":"中频，年轻人常说。","me":"h 不出声：读起来就是「ip op」。","tr":{"zh":"我的朋友们爱听嘻哈。","fr":"Mes amis adorent écouter du hip hop.","alt":"Mes potes écoutent tout le temps du hip hop.","note":"écouter du + 音乐类型；potes 是口语，指朋友。"}},
 "Le jardinage": {"pos":"n.m. 阳性名词，一般不加复数","s":"园艺；种花种菜、打理花园。faire du jardinage = 做园艺活。","ipa":"[ʒaʁ.di.naʒ]","ph":"j [ʒ]；ar [aʁ]，r 是小舌音；-age [aʒ]，结尾 e 不发音。","pi":"j 读 [ʒ]，不是 [dʒ]；-age 读 [aʒ]。","et":"由 jardin（花园）+ 后缀 -age 构成。同族词：jardinier（园丁）、jardinière（花箱；女园丁）。","ex":[["Le jardinage est relaxant.","园艺让人放松。"],["Mon grand-père fait du jardinage tous les jours.","我外公每天都做园艺。"]],"co":[["faire du jardinage","做园艺"],["des outils de jardinage","园艺工具"],["des gants de jardinage","园艺手套"]],"sy":[["horticulture","soutenu","园艺学，较正式"],["potager","courant","菜园（名词）"]],"fq":"中频，日常话题。","me":"jardin + -age：「花园的活动」。","tr":{"zh":"春天我喜欢做园艺。","fr":"Au printemps, j'aime faire du jardinage.","alt":"Au printemps, j'adore jardiner.","note":"jardiner 是对应的动词，意思是「做园艺」。"}},
 "Le mont Saint-Michel": {"pos":"n.m. 阳性名词（mont），专有名词","s":"圣米歇尔山，诺曼底海边的小岛，山顶是修道院，涨潮时四周被海水包围。mont = 山；Saint-Michel = 圣米迦勒（大天使）。","ipa":"[mɔ̃ sɛ̃.mi.ʃɛl]","ph":"mont [mɔ̃]，t 不发音；Saint [sɛ̃]，ai+nt 读鼻化 [ɛ̃]，t 不发音；Michel [mi.ʃɛl]，ch 读 [ʃ]。","pi":"Michel 的 ch 读 [ʃ]，不读 [k]；mont 和 Saint 的 t 都不发音。","et":"mont 来自拉丁语 mons, montis（山）。Saint-Michel 取自大天使 Michel。","ex":[["Le mont Saint-Michel est beau.","圣米歇尔山很美。"],["Nous allons au mont Saint-Michel en Normandie.","我们去诺曼底的圣米歇尔山。"]],"co":[["visiter le mont Saint-Michel","参观圣米歇尔山"],["la baie du mont Saint-Michel","圣米歇尔山湾"],["l'abbaye du mont Saint-Michel","圣米歇尔山修道院"]],"sy":[["montagne","courant","山（普通名词，更大）"],["colline","courant","小山丘"]],"fq":"旅游话题常见。","me":"Saint-Michel = 「米歇尔」，山上有修道院。","tr":{"zh":"你去过圣米歇尔山吗？","fr":"Tu es déjà allé au mont Saint-Michel ?","alt":"Tu connais le mont Saint-Michel ?","note":"aller 的复合过去时用 être：je suis allé。"}},
 "Le moyen-âge": {"pos":"n.m. 阳性名词，不加复数","s":"中世纪（约公元 5 世纪到 15 世纪）。常见写法是 le Moyen Âge（首字母大写，不加连字符）；书上写作 moyen-âge。","ipa":"[mwa.jɛ̃.nɑʒ]","ph":"moyen 读 [mwa.jɛ̃]，-en 是鼻化音；âge 读 [ɑʒ]，常读成 [aʒ]。moyen 和 âge 连读时会多出一个 n：[mwa.jɛ̃.nɑʒ]。","pi":"moyen 的 -en 读鼻化 [jɛ̃]，不是 [ɛn]；âge 上有帽子符号，容易漏写。","et":"moyen 来自拉丁语 medianus（居中的）；âge 来自拉丁语 aetas（时代）。整体仿拉丁语 medium aevum（中间时代）。","ex":[["C'est un château du moyen-âge.","这是一座中世纪的城堡。"],["Au Moyen Âge, les gens vivaient dans des villages.","在中世纪，人们住在村庄里。"]],"co":[["au Moyen Âge","在中世纪"],["le haut Moyen Âge","中世纪早期"],["une ville du Moyen Âge","一座中世纪的城市"]],"sy":[["médiéval","courant","形容词：中世纪的"],["Antiquité","courant","古代（更早的时期）"]],"fq":"历史话题常见。","me":"moyen（中间）+ âge（时代）：「中间的时代」。","tr":{"zh":"这座教堂建于中世纪。","fr":"Cette église date du Moyen Âge.","alt":"Cette église a été construite au Moyen Âge.","note":"dater de = 追溯到；au Moyen Âge = 在中世纪。"}},
 "Le musée du Louvre": {"pos":"n.m. 阳性名词（musée），复数 musées","s":"卢浮宫博物馆，巴黎的世界著名艺术博物馆，里面有《蒙娜丽莎》。musée = 博物馆；du = de + le。","ipa":"[my.ze dy luvʁ]","ph":"mu- 在法语里读 [my]（嘴圆，发 ü）；sée [ze]，s 在元音间读 [z]；ou [u]；Louvre 结尾 -re 的 e 不发音，读 [luvʁ]。","pi":"musée 里 u 是 [y]，不是 [u]；Louvre 才是 [u]；s 读 [z]，不是 [s]。","et":"musée 来自希腊语 mouseion（缪斯的圣地）。Louvre 的来源不确定。","ex":[["La Joconde est au musée du Louvre.","《蒙娜丽莎》在卢浮宫博物馆。"],["Le musée du Louvre est fermé le mardi.","卢浮宫博物馆星期二闭馆。"]],"co":[["visiter le musée du Louvre","参观卢浮宫"],["entrer dans / sortir du musée","进入 / 离开博物馆"],["un billet pour le musée","博物馆门票"]],"sy":[["le Louvre","courant","简称，更常用"],["galerie","courant","画廊"]],"fq":"旅游话题常见。","me":"musée [my.ze]，Louvre [luvʁ]：u 和 ou 是两个不同的音。","tr":{"zh":"我们明天去卢浮宫博物馆。","fr":"Nous allons au musée du Louvre demain.","alt":"Demain, on va au Louvre.","note":"à + le = au；de + le = du。"}},
 "Le paddle": {"pos":"n.m. 阳性名词，复数 paddles","s":"桨板（站立式桨板运动，stand up paddle 的简称）。说「玩桨板」用 faire du paddle。","ipa":"[pa.dœl]","ph":"pa [pa]；dd 只读一个 [d]；-dle 读 [dœl]，le 前带一个轻的 [œ]。","pi":"不要按英语读 [pædəl]；法语读 [pa.dœl]，a 是 [a]；结尾的 l 要发出来。","et":"来自英语 paddle（桨）。法语里是外来词。","ex":[["J'aime faire du paddle.","我喜欢玩桨板。"],["Ils font du paddle sur le lac.","他们在湖上玩桨板。"]],"co":[["faire du paddle","玩桨板"],["une planche de paddle","一块桨板"],["louer un paddle","租一块桨板"]],"sy":[["kayak","courant","皮艇（另一种水上运动）"],["stand up paddle","courant","全称，英语借词"]],"fq":"低频，休闲运动话题。","me":"pa-dœl：像「怕多」，结尾有 l。","tr":{"zh":"我们在海上玩桨板。","fr":"Nous faisons du paddle sur la mer.","alt":"On fait du paddle en mer.","note":"faire du + 运动名称。"}},
 "Le parcours artistique": {"pos":"n.m. 阳性名词（parcours），单复数同形","s":"艺术经历；艺术之路，指一个人在艺术领域的发展过程。parcours 本义是「路线；行程」，引申为「经历」。","ipa":"[paʁ.kuʁ aʁ.tis.tik]","ph":"parcours 里 ar [aʁ]，ou [u]，结尾 -s 不发音，读 [paʁ.kuʁ]；artistique 读 [aʁ.tis.tik]，qu 读 [k]。","pi":"parcours 结尾 s 不发音；artistique 里 qu 读 [k]。parcours 单复数同形，要看冠词。","et":"parcours 来自动词 parcourir（par + courir）。artistique 由 artiste 加 -ique 而来。","ex":[["Son parcours artistique a commencé tôt.","他的艺术之路开始得很早。"],["Elle présente son parcours artistique.","她介绍自己的艺术经历。"]],"co":[["un parcours atypique","与众不同的经历"],["suivre un parcours","走一条路径、一段经历"],["un parcours de santé","健身步道"]],"sy":[["carrière","courant","职业生涯"],["trajectoire","soutenu","轨迹、发展路线"]],"fq":"中频，书面和介绍经历时常用。","me":"par-cours：「一路跑过去」的路线。","tr":{"zh":"她的艺术经历很有意思。","fr":"Son parcours artistique est très intéressant.","alt":"Son parcours dans l'art est super intéressant.","note":"son 用于阳性名词 parcours。"}},
 "Le parcours professionnel": {"pos":"n.m. 阳性名词（parcours），单复数同形","s":"职业经历；工作履历，指一个人工作过的公司、岗位的变化过程。面试时常说 parler de son parcours professionnel。","ipa":"[paʁ.kuʁ pʁɔ.fɛ.sjɔ.nɛl]","ph":"parcours 结尾 s 不发音；professionnel 读 [pʁɔ.fɛ.sjɔ.nɛl]，ss 读 [s]，-ionnel 读 [jɔ.nɛl]。","pi":"professionnel 有两个 n、两个 s，拼写要小心；parcours 末尾 s 不发音。","et":"parcours 来自 parcourir。professionnel 来自 profession（拉丁语 professio）+ -el。","ex":[["Son parcours professionnel est impressionnant.","他的职业经历令人印象深刻。"],["Parlez-moi de votre parcours professionnel.","请介绍一下您的职业经历。"]],"co":[["un parcours professionnel varié","丰富多样的职业经历"],["décrire son parcours professionnel","描述自己的职业经历"],["changer de parcours","换一条职业道路"]],"sy":[["carrière","courant","职业生涯"],["expérience professionnelle","courant","工作经验"]],"fq":"中频，求职场合常用。","me":"parcours（路线）+ professionnel（工作的）：工作的路线图。","tr":{"zh":"请介绍你的职业经历。","fr":"Présentez-moi votre parcours professionnel.","alt":"Parlez-moi de votre parcours professionnel.","note":"Présentez / Parlez 是 vous 的命令式，较礼貌。"}},
 "Le patrimoine": {"pos":"n.m. 阳性名词，复数 patrimoines","s":"文化遗产；传承下来的财富。le patrimoine culturel = 文化遗产；le patrimoine mondial = 世界遗产。也可指个人财产。","ipa":"[pa.tʁi.mwan]","ph":"pa [pa]；tr [tʁ]；moine 里 oi 读 [wa]，所以 -moine 读 [mwan]（n 要发音）。","pi":"-moine 读 [mwan]，不是鼻化音；oi 读 [wa]；结尾 e 不发音。","et":"来自拉丁语 patrimonium（父亲留下的财产）：pater（父亲）。","ex":[["Ce célèbre artiste fait partie du patrimoine français.","这位著名艺术家是法国文化遗产的一部分。"],["Le mont Saint-Michel est un patrimoine mondial.","圣米歇尔山是世界遗产。"]],"co":[["le patrimoine culturel","文化遗产"],["le patrimoine mondial de l'UNESCO","联合国教科文组织世界遗产"],["protéger le patrimoine","保护遗产"],["les Journées du patrimoine","文化遗产日"]],"sy":[["héritage","courant","遗产（更泛）"],["fortune","courant","财富、家产"]],"fq":"中频，文化话题常见。","me":"patri- = 父亲：「父辈留下的东西」。","tr":{"zh":"这座城堡是国家的文化遗产。","fr":"Ce château fait partie du patrimoine national.","alt":"Ce château, c'est un trésor du patrimoine national.","note":"faire partie de = 属于……的一部分。"}},
 "Le public": {"pos":"n.m. 阳性名词，复数 publics","s":"观众；公众。le public 指一场演出、比赛的观众整体，也指大众。en public = 当众。public 还是形容词（公共的；公开的），阴性 publique。","ipa":"[pyb.lik]","ph":"pu [py]（嘴圆，发 ü）；b [b]；-lic 结尾的 c 读 [k]，所以 public 读 [pyb.lik]。","pi":"u 读 [y]，不是 [u]；结尾 c 要发出来 [k]。le public 后动词用单数：Le public applaudit。","et":"来自拉丁语 publicus（属于人民的）。","ex":[["Le public applaudit.","观众在鼓掌。"],["Elle parle devant un large public.","她在很多观众面前讲话。"]],"co":[["le grand public","普通大众"],["en public","当众、公开地"],["un public nombreux","很多观众"],["ouvert au public","对公众开放"]],"sy":[["spectateurs","courant","观众（具体的人）"],["foule","courant","人群"]],"fq":"高频，日常常用。","me":"pub-lic：像英语 public，但 u 要噘嘴读 [y]。","tr":{"zh":"演出结束后，观众起立鼓掌。","fr":"À la fin du spectacle, le public applaudit debout.","alt":"Quand le spectacle finit, le public se lève et applaudit.","note":"le public 后接单数动词。"}},
 "Le saut à la perche": {"pos":"n.m. 阳性名词（saut），复数 sauts","s":"撑杆跳（田径项目）。saut = 跳；perche = 长杆；à la perche = 用杆子。其他跳项：saut en longueur（跳远）、saut en hauteur（跳高）。","ipa":"[so a la pɛʁʃ]","ph":"saut 读 [so]，au [o]，t 不发音；à [a]；la [la]；perche 读 [pɛʁʃ]，e 在 r 前读 [ɛ]，ch [ʃ]，结尾 e 不发音。","pi":"saut 的 t 不发音，和 sot [so] 同音；perche 的 ch 读 [ʃ]。","et":"saut 来自动词 sauter（拉丁语 saltare）；perche 来自拉丁语 pertica（长杆）。","ex":[["Le saut à la perche est impressionnant.","撑杆跳令人惊叹。"],["Il pratique le saut à la perche depuis longtemps.","他练撑杆跳很多年了。"]],"co":[["faire du saut à la perche","练撑杆跳"],["le saut en longueur","跳远"],["le saut en hauteur","跳高"]],"sy":[["athlétisme","courant","田径（大类）"],["saut","courant","跳跃（总称）"]],"fq":"低频，体育话题。","me":"saut（跳）+ perche（杆）：拿着杆子跳。","tr":{"zh":"她在学撑杆跳。","fr":"Elle apprend le saut à la perche.","alt":"Elle s'entraîne au saut à la perche.","note":"apprendre + 名词：学习某项运动。"}},
 "Un album": {"pos":"n.m. 阳性名词，复数 albums","s":"专辑（音乐）；相册；画册、漫画册。un album photo = 相册；un album de BD = 漫画书；un nouvel album = 新专辑。","ipa":"[al.bɔm]","ph":"al [al]；b [b]；-um 在法语外来词里读 [ɔm]，所以 album 读 [al.bɔm]。","pi":"-um 读 [ɔm]，不读 [ʌm]；l 和 b 都要发音。","et":"来自拉丁语 album（白色的板），源自 albus（白色）。","ex":[["J'écoute ce nouvel album.","我在听这张新专辑。"],["Nous regardons l'album photo de la famille.","我们在看家庭相册。"]],"co":[["un album photo","相册"],["sortir un album","发行专辑"],["un album de bande dessinée","漫画册"]],"sy":[["disque","courant","唱片、专辑"],["CD","familier","光盘专辑"],["recueil","soutenu","选集、文集"]],"fq":"中高频，日常常用。","me":"al-bum：像「白板」albus，白色的本子。","tr":{"zh":"她下个月发行新专辑。","fr":"Elle sort un nouvel album le mois prochain.","alt":"Son nouvel album sort le mois prochain.","note":"sortir 用作及物动词，意为「发行」。"}},
 "Un château": {"pos":"n.m. 阳性名词，复数 châteaux","s":"城堡；宫殿；庄园。法国卢瓦尔河一带有很多 château。葡萄酒产区的酒庄也叫 château。","ipa":"[ʃɑ.to]","ph":"ch [ʃ]；â [ɑ]（常读成 [a]）；eau [o]；结尾没有音。","pi":"复数是 châteaux，不是 châteaus；â 上有帽子符号；ch 读 [ʃ]。","et":"来自拉丁语 castellum（小要塞）。同族词：château fort（要塞城堡）。","ex":[["C'est un vieux château.","这是一座古老的城堡。"],["Nous visitons les châteaux de la Loire.","我们参观卢瓦尔河的城堡。"]],"co":[["un château fort","要塞城堡"],["un château de sable","沙堡"],["visiter un château","参观城堡"]],"sy":[["palais","courant","宫殿"],["forteresse","soutenu","要塞"]],"fq":"中高频，日常常用。","me":"château 的 ^ 像城堡的屋顶；复数 -eaux。","tr":{"zh":"山上有一座古老的城堡。","fr":"Il y a un vieux château sur la colline.","alt":"Sur la colline, il y a un très vieux château.","note":"il y a = 有；vieux 放在名词前。"}},
 "Un chemin": {"pos":"n.m. 阳性名词，复数 chemins","s":"路；小路；道路（泛指，比 route 小）。也可以指比喻意义的「路径、方法」：le bon chemin = 正确的路。chemin de fer = 铁路。","ipa":"[ʃə.mɛ̃]","ph":"ch [ʃ]；e 轻读 [ə]（快读时常省略）；-in 读鼻化 [ɛ̃]，n 不发音。","pi":"-in 是鼻化音 [ɛ̃]，不读 [in]；ch 读 [ʃ]，不读 [tʃ]。","et":"来自晚期拉丁语 caminus，可能源自高卢语。","ex":[["C'est le bon chemin.","这条路是对的。"],["Quel chemin prenons-nous ?","我们走哪条路？"]],"co":[["prendre un chemin","走一条路"],["demander son chemin","问路"],["en chemin","在路上"],["un chemin de fer","铁路"]],"sy":[["route","courant","公路（更大）"],["sentier","courant","小径"],["rue","courant","街道（城里）"]],"fq":"高频，日常常用。","me":"chemin 的结尾和 main（手）同音 [ɛ̃]。","tr":{"zh":"我迷路了，你知道去那儿的路吗？","fr":"Je suis perdu, tu connais le chemin ?","alt":"Je suis perdu, tu sais comment y aller ?","note":"connaître le chemin = 认识路。"}},
 "Un cirque": {"pos":"n.m. 阳性名词，复数 cirques","s":"马戏团；马戏表演。口语里 quel cirque ! = 真是一场闹剧，指乱哄哄的场面。也指地理上的「冰斗；圆谷」。","ipa":"[siʁk]","ph":"c 在 i 前读 [s]；i [i]；r 小舌音 [ʁ]；-que 读 [k]，结尾 e 不发音。","pi":"ci 的 c 读 [s]；结尾 -rque 读 [ʁk]，只有一个音节。","et":"来自拉丁语 circus（圆圈；竞技场）。英语 circus 同源。","ex":[["Les enfants aiment le cirque.","孩子们喜欢马戏团。"],["Le cirque arrive en ville demain.","马戏团明天来城里。"]],"co":[["aller au cirque","去看马戏"],["un clown de cirque","马戏团小丑"],["Quel cirque !","真是乱七八糟！（口语）"]],"sy":[["chapiteau","courant","马戏团大帐篷"],["spectacle","courant","演出"]],"fq":"中频，日常常用。","me":"cirque = circus：一圈圈的圆形场地。","tr":{"zh":"今晚我们带孩子去看马戏。","fr":"Ce soir, nous emmenons les enfants au cirque.","alt":"Ce soir, on emmène les enfants au cirque.","note":"emmener = 带（人）去某地。"}},
 "Un coup de foudre": {"pos":"n.m. 阳性名词（coup），复数 coups de foudre","s":"一见钟情；本义是「雷击」。avoir le coup de foudre pour qqn = 对某人一见钟情；也可以对东西：对某个房子或衣服一见倾心。","ipa":"[ku də fudʁ]","ph":"coup 读 [ku]，p 不发音；de 读 [də]，快读时 e 常省略；foudre 读 [fudʁ]，ou [u]，结尾 -re 的 e 不发音。","pi":"coup 的 p 不发音；复数是 coups de foudre，只有 coup 加 s。","et":"coup（打击）+ foudre（闪电；来自拉丁语 fulgur）。比喻意义由「被雷击中」而来。","ex":[["C'était un coup de foudre.","那是一见钟情。"],["J'ai eu le coup de foudre pour cette maison.","我对这栋房子一见钟情。"]],"co":[["avoir le coup de foudre","一见钟情"],["un coup de foudre pour qqn / qqch","对某人 / 某物一见钟情"],["l'amour au premier regard","第一眼就爱上（近义说法）"]],"sy":[["amour au premier regard","courant","一见钟情（直白说法）"],["béguin","familier","迷恋、暗恋"]],"fq":"中频，日常常用。","me":"coup（打击）+ foudre（闪电）：爱情像被雷劈中。","tr":{"zh":"我们一见面就一见钟情。","fr":"Quand nous nous sommes vus, c'était le coup de foudre.","alt":"On s'est vus et ça a été le coup de foudre.","note":"coup de foudre 常与 avoir le / un 连用。"}},
 "Un itinéraire": {"pos":"n.m. 阳性名词，复数 itinéraires","s":"路线；行程。旅行或开车的路线安排：un itinéraire touristique = 旅游路线；itinéraire bis = 替代路线。","ipa":"[i.ti.ne.ʁɛʁ]","ph":"i [i]；t [t]；é [e]；-aire 读 [ɛʁ]，结尾 e 不发音。","pi":"-aire 读 [ɛʁ]，不读 [ɛ.ʁə]；结尾 e 不发音；é 的重音符号要写。","et":"来自拉丁语 itinerarius，源自 iter, itineris（路、行程）。","ex":[["Voici notre itinéraire.","这是我们的行程。"],["Nous préparons l'itinéraire de nos vacances.","我们在准备假期的路线。"]],"co":[["planifier un itinéraire","规划路线"],["un itinéraire touristique","旅游路线"],["un itinéraire bis","备用路线"]],"sy":[["trajet","courant","一段路程"],["parcours","courant","路线、行程"],["route","courant","道路"]],"fq":"中频，旅行话题常用。","me":"itiné-raire：想「路」iter，带着路线图。","tr":{"zh":"我们先看一下路线吧。","fr":"Regardons d'abord l'itinéraire.","alt":"On regarde d'abord l'itinéraire ?","note":"Regardons 是 nous 的命令式，表示「我们……吧」。"}},
 "Un mariage": {"pos":"n.m. 阳性名词，复数 mariages","s":"婚礼；婚姻。aller à un mariage = 去参加婚礼；也可指婚姻状态。se marier = 结婚；être marié(e) = 已婚。","ipa":"[ma.ʁjaʒ]","ph":"ma [ma]；r 小舌音 [ʁ]；-ia 读 [ja]，所以 -riage 读 [ʁjaʒ]，只有两个音节；g [ʒ]。","pi":"mariage 只有两个音节：[ma.ʁjaʒ]；e 在词尾不发音。","et":"由动词 marier + -age 构成，marier 源自拉丁语 maritare（使结婚）。","ex":[["Le mariage est en été.","婚礼在夏天。"],["Ils fêtent vingt ans de mariage.","他们庆祝结婚二十周年。"]],"co":[["un mariage civil / religieux","民事 / 宗教婚礼"],["inviter à un mariage","邀请参加婚礼"],["un cadeau de mariage","结婚礼物"],["un anniversaire de mariage","结婚纪念日"]],"sy":[["noces","soutenu","婚庆（一般用复数）"],["union","soutenu","结合、结合体"]],"fq":"高频，日常常用。","me":"mari（丈夫）+ -age：成为夫妻的仪式。","tr":{"zh":"她下个月结婚。","fr":"Elle se marie le mois prochain.","alt":"Son mariage, c'est le mois prochain.","note":"se marier（结婚）是代词式动词。"}},
 "Un métier": {"pos":"n.m. 阳性名词，复数 métiers","s":"职业；行业；手艺。问职业常说 Quel est votre métier ? 或 Vous faites quoi comme métier ? métier 强调一门技能、手艺，如 un métier manuel。","ipa":"[me.tje]","ph":"mé [me]；-tier 读 [tje]，ti 读 [tj]，er 读 [e]，结尾 r 不发音。","pi":"结尾 -er 读 [e]，r 不发音；注意 é 上的重音符号不能漏。","et":"来自古法语 mestier，源自拉丁语 ministerium（服务；职责）。","ex":[["C'est un métier difficile.","这是一份困难的职业。"],["Quel métier veux-tu faire plus tard ?","你长大后想做什么工作？"]],"co":[["exercer un métier","从事一个职业"],["changer de métier","换工作"],["un métier manuel","体力、手艺类职业"],["apprendre un métier","学一门手艺"]],"sy":[["profession","courant","职业（更正式，表格里常用）"],["travail","courant","工作（泛指）"],["boulot","familier","活儿、工作（口语）"]],"fq":"极高频，日常常用。","me":"mé-tier：和 ministère 同源，都是「服务」。","tr":{"zh":"你想做什么职业？","fr":"Quel métier veux-tu faire ?","alt":"Tu veux faire quoi comme métier ?","note":"faire un métier = 从事某职业，口语常这样说。"}},
 "Un monument": {"pos":"n.m. 阳性名词，复数 monuments","s":"古迹；纪念碑；建筑名胜。un monument historique = 历史古迹，受国家保护的建筑，如巴黎圣母院、埃菲尔铁塔。","ipa":"[mɔ.ny.mɑ̃]","ph":"mo [mɔ]；nu [ny]（嘴圆，发 ü）；-ment 读鼻化 [mɑ̃]，t 不发音。","pi":"-ment 读 [mɑ̃]，t 不发音；nu 读 [ny]，不读 [nu]。","et":"来自拉丁语 monumentum，源自 monere（提醒；使记起）：留下来让人记起的东西。","ex":[["C'est un monument historique.","这是一处历史古迹。"],["Nous visitons les monuments de Paris.","我们参观巴黎的名胜古迹。"]],"co":[["un monument historique","历史古迹"],["visiter un monument","参观古迹"],["un monument aux morts","阵亡将士纪念碑"]],"sy":[["édifice","soutenu","大型建筑"],["site","courant","景点、遗址"],["statue","courant","雕像"]],"fq":"中频，旅游话题常用。","me":"monu-ment：让人「记住」（monere）的建筑。","tr":{"zh":"你最喜欢巴黎的哪座古迹？","fr":"Quel est ton monument préféré à Paris ?","alt":"Tu préfères quel monument à Paris ?","note":"Quel 与阳性名词配合；préféré 作形容词。"}},
 "Un paysage": {"pos":"n.m. 阳性名词，复数 paysages","s":"风景；景色；风光，指眼前看到的自然或乡村景象。un paysage magnifique = 壮丽的风景。也指绘画里的风景画。","ipa":"[pe.i.zaʒ]","ph":"pay- 读 [pe.i]，ay 读 [ei]，分成两个音节；s 在元音间读 [z]；-age 读 [aʒ]。","pi":"s 读 [z]，不读 [s]；pay- 要分成 [pe.i] 两个音节；拼写 paysage，y 不能少。","et":"由 pays（国家；地区）+ 后缀 -age 构成，意思是「一个地区的样子」。","ex":[["Le paysage est magnifique.","风景很壮丽。"],["Nous admirons le paysage depuis la montagne.","我们从山上欣赏风景。"]],"co":[["un paysage magnifique","壮丽的风景"],["admirer le paysage","欣赏风景"],["un changement de paysage","换换环境"],["un paysage de montagne","山景"]],"sy":[["vue","courant","景观、视野"],["panorama","courant","全景"],["décor","courant","背景、环境"]],"fq":"中高频，日常常用。","me":"pays + -age：一个「地方」的样子。","tr":{"zh":"从窗户看，风景真美。","fr":"Depuis la fenêtre, le paysage est très beau.","alt":"De la fenêtre, on a un super paysage.","note":"depuis 在这里表示「从……位置」。"}},
 "Un roi": {"pos":"n.m. 阳性名词，复数 rois；阴性 une reine","s":"国王。阴性是 reine（女王；王后）。也指国际象棋里的王，或扑克牌里的 K。les Rois mages = 东方三博士；galette des rois = 主显节国王饼。","ipa":"[ʁwa]","ph":"r 小舌音 [ʁ]；oi 读 [wa]；只有一个音节。","pi":"oi 读 [wa]，不读 [oi]；单数 roi 和复数 rois 读音相同，s 不发音。","et":"来自拉丁语 rex, regis（国王）。同族词：reine、royal、règne。","ex":[["C'est le roi de France.","他是法国国王。"],["Louis XIV est surnommé le Roi-Soleil.","路易十四被称为太阳王。"]],"co":[["le roi et la reine","国王和王后"],["la galette des rois","国王饼"],["le roi de la fête","聚会的主角"]],"sy":[["souverain","soutenu","君主"],["monarque","soutenu","君主"],["reine","courant","阴性：女王"]],"fq":"中频，日常常用。","me":"roi 读 [ʁwa]；同族 royal、règne。","tr":{"zh":"国王住在一座大城堡里。","fr":"Le roi habite dans un grand château.","alt":"Le roi vit dans un très grand château.","note":"habiter dans + 地点。"}},
 "Un roman": {"pos":"n.m. 阳性名词，复数 romans","s":"小说。un roman policier = 侦探小说；un roman d'amour = 爱情小说；un roman historique = 历史小说。小说作者是 un romancier / une romancière。","ipa":"[ʁɔ.mɑ̃]","ph":"r 小舌音 [ʁ]；o [ɔ]；-an 读鼻化 [ɑ̃]，n 不发音。","pi":"-an 是鼻化音 [ɑ̃]，n 不发音；roman 不是 [ʁo.man]。","et":"来自古法语 romanz，指用「罗曼语」（通俗语言）写成的作品，而不是拉丁语。同族词：romantique、romancier。","ex":[["Je lis un roman.","我读一本小说。"],["Ce roman policier est très bien écrit.","这本侦探小说写得很好。"]],"co":[["un roman policier","侦探小说"],["un roman d'amour","爱情小说"],["écrire un roman","写小说"],["un roman graphique","图像小说"]],"sy":[["nouvelle","courant","短篇小说"],["livre","courant","书（泛指）"],["récit","soutenu","叙述、故事"]],"fq":"高频，日常常用。","me":"roman：最初是「用罗曼语写的东西」，和 romance 同源。","tr":{"zh":"我正在读一本很好看的小说。","fr":"Je lis un roman très intéressant.","alt":"Je suis en train de lire un super roman.","note":"être en train de + 不定式 = 正在做某事。"}},
 "Un spectacle": {"pos":"n.m. 阳性名词，复数 spectacles","s":"演出；表演；场面。可以指戏剧、音乐会、舞蹈表演等。un spectacle de danse = 舞蹈表演。也可指眼前所见的景象。","ipa":"[spɛk.takl]","ph":"sp [sp]；ec 读 [ɛk]；ta [ta]；-cle 读 [kl]，结尾 e 不发音，整个词读 [spɛk.takl]。","pi":"结尾 -cle 读 [kl]，中间没有元音；注意 c 读 [k]。","et":"来自拉丁语 spectaculum，源自 spectare（看）。同族词：spectateur（观众）、spectaculaire。","ex":[["Le spectacle est génial.","演出太棒了。"],["Nous allons voir un spectacle ce soir.","我们今晚去看演出。"]],"co":[["aller voir un spectacle","去看演出"],["un spectacle de danse","舞蹈表演"],["un spectacle vivant","现场演出"],["donner un spectacle","表演"]],"sy":[["représentation","courant","一场演出"],["concert","courant","音乐会"],["show","familier","秀（英语借词）"]],"fq":"高频，日常常用。","me":"spect-：同 spectateur，「看」的东西。","tr":{"zh":"孩子们很喜欢这场演出。","fr":"Les enfants adorent ce spectacle.","alt":"Les enfants ont adoré le spectacle.","note":"adorer 后接名词时，表示「非常喜欢」。"}},
 "L'accrobranche": {"pos":"n.f. 阴性名词，一般不加复数","s":"树上探险；高空绳索运动，在树间的绳桥、滑索上攀爬。说「去玩」用 faire de l'accrobranche。","ipa":"[a.kʁɔ.bʁɑ̃ʃ]","ph":"cc 读一个 [k]；o [ɔ]；br [bʁ]；-an- 读鼻化 [ɑ̃]；ch [ʃ]；结尾 e 不发音。l' 省音。","pi":"cc 在 o 前读 [k]，不是 [ks]；-an 是鼻化音 [ɑ̃]；ch 读 [ʃ]。","et":"由 acro(bate)（杂技演员）和 branche（树枝）拼合而成，是 20 世纪末造的词。","ex":[["Nous faisons de l'accrobranche.","我们玩高空绳索探险。"],["Les enfants adorent l'accrobranche en forêt.","孩子们很爱在森林里玩树上探险。"]],"co":[["faire de l'accrobranche","玩树上探险"],["un parc d'accrobranche","树上探险乐园"],["une tyrolienne","滑索"]],"sy":[["escalade","courant","攀岩（不同的运动）"],["parcours aventure","courant","探险路线（类似的活动）"]],"fq":"低频，休闲话题。","me":"acro（杂技）+ branche（树枝）：在树枝间玩杂技。","tr":{"zh":"周末我们去玩树上探险。","fr":"Ce week-end, nous faisons de l'accrobranche.","alt":"Ce week-end, on va faire de l'accrobranche.","note":"faire de l'+ 元音开头的名词；faire du + 阳性名词。"}},
 "L'histoire": {"pos":"n.f. 阴性名词，复数 histoires","s":"历史；故事。l'histoire de France = 法国历史；raconter une histoire = 讲一个故事。口语里 une histoire 还可指「事儿；麻烦」：C'est une longue histoire。","ipa":"[is.twaʁ]","ph":"h 不发音；is [is]；-toire 读 [twaʁ]，oi 读 [wa]。histoire 的 h 是哑音 h，所以 la 省音成 l'。","pi":"h 不发音，省音写成 l'histoire，不是 la histoire；-oire 读 [waʁ]。","et":"来自拉丁语 historia，源自希腊语 historia（调查；叙述）。","ex":[["Il adore étudier l'histoire de France.","他喜欢研究法国历史。"],["Raconte-moi une histoire, s'il te plaît.","给我讲个故事吧。"]],"co":[["l'histoire de France","法国历史"],["raconter une histoire","讲故事"],["un cours d'histoire","历史课"],["une histoire drôle","一个笑话"]],"sy":[["récit","soutenu","叙述"],["conte","courant","童话、故事"],["passé","courant","过去"]],"fq":"极高频，日常常用。","me":"histoire = his + toire：同英语 story、history。","tr":{"zh":"我喜欢听我奶奶讲故事。","fr":"J'aime écouter les histoires de ma grand-mère.","alt":"J'adore quand ma grand-mère raconte des histoires.","note":"histoire 是阴性，所以用 les histoires, ma grand-mère。"}},
 "La cathédrale Notre-Dame": {"pos":"n.f. 阴性名词（cathédrale），复数 cathédrales","s":"巴黎圣母院，位于塞纳河中的西岱岛，是哥特式建筑，2019 年遭遇大火后修复。cathédrale = 主教座堂；Notre-Dame = 我们的圣母。","ipa":"[ka.te.dʁal nɔ.tʁə.dam]","ph":"ca [ka]；thé 读 [te]，th 读 [t]；-drale 读 [dʁal]；Notre 读 [nɔtʁ]；Dame 读 [dam]，结尾 e 不发音。","pi":"th 读 [t]，不是英语的 [θ]；Notre-Dame 里 -tre 的 e 快读时常省略。","et":"cathédrale 来自希腊语 kathedra（座椅）：主教的座椅所在地。Notre-Dame 意为「我们的夫人」。","ex":[["Je vois la cathédrale Notre-Dame.","我看到巴黎圣母院。"],["La cathédrale Notre-Dame est sur l'île de la Cité.","巴黎圣母院在西岱岛上。"]],"co":[["visiter la cathédrale","参观大教堂"],["une cathédrale gothique","哥特式大教堂"],["les tours de Notre-Dame","圣母院的钟楼"]],"sy":[["église","courant","教堂（泛指）"],["basilique","courant","大教堂（另一种称号）"]],"fq":"旅游话题常见。","me":"cathédrale ← kathedra（座椅）：主教坐的地方。","tr":{"zh":"我们从桥上看见巴黎圣母院。","fr":"Nous voyons la cathédrale Notre-Dame depuis le pont.","alt":"Du pont, on voit Notre-Dame.","note":"depuis le pont = 从桥上（位置起点）。"}},
 "La choucroute": {"pos":"n.f. 阴性名词，一般不加复数","s":"酸菜（阿尔萨斯特色的发酵卷心菜），常配香肠、猪肉和土豆。la choucroute garnie = 酸菜拼盘。","ipa":"[ʃu.kʁut]","ph":"chou 读 [ʃu]；croute 读 [kʁut]，ou [u]，结尾 e 不发音。","pi":"ch 读 [ʃ]；croûte 才有 ^，choucroute 没有；不要读成 [ʃu.kʁu.te]。","et":"来自阿尔萨斯语 sûrkrût（酸菜），法语里受 chou（卷心菜）和 croûte（外皮）影响而改写。","ex":[["Je mange de la choucroute.","我吃酸菜。"],["La choucroute est une spécialité alsacienne.","酸菜是阿尔萨斯的特色菜。"]],"co":[["une choucroute garnie","酸菜拼盘"],["de la choucroute et des saucisses","酸菜和香肠"],["une spécialité alsacienne","阿尔萨斯特色菜"]],"sy":[["chou","courant","卷心菜（原料）"],["sauerkraut","courant","德语说法，同一道菜"]],"fq":"低频，美食话题。","me":"chou（卷心菜）+ croûte：想成「卷心菜外皮」，好记。","tr":{"zh":"冬天我们爱吃酸菜拼盘。","fr":"En hiver, nous aimons manger de la choucroute garnie.","alt":"L'hiver, on adore la choucroute garnie.","note":"manger de la + 不可数食物（部分冠词）。"}},
 "La littérature": {"pos":"n.f. 阴性名词，复数 littératures","s":"文学。la littérature française = 法国文学；la littérature jeunesse = 儿童文学。也指某一主题的文献：la littérature scientifique。","ipa":"[li.te.ʁa.tyʁ]","ph":"li [li]；tt 读一个 [t]；é [e]；-ture 读 [tyʁ]，u 读 [y]，结尾 e 不发音。","pi":"tt 要写两个 t（littérature），读一个 [t]；-ure 里 u 读 [y]。","et":"来自拉丁语 litteratura，源自 littera（字母）。同族词：lettre、littéraire、littéral。","ex":[["J'étudie la littérature.","我学习文学。"],["Elle enseigne la littérature française.","她教法国文学。"]],"co":[["la littérature française","法国文学"],["un prix de littérature","文学奖"],["étudier la littérature","学文学"]],"sy":[["lettres","courant","文科（les lettres）"],["roman","courant","小说（更具体）"]],"fq":"中频，学习话题常用。","me":"litt-éra-ture：和 lettre（字母；信）同族。","tr":{"zh":"我姐姐在大学学文学。","fr":"Ma sœur étudie la littérature à l'université.","alt":"Ma sœur fait des études de lettres à la fac.","note":"fac 是 faculté 的口语简称。"}},
 "La retraite": {"pos":"n.f. 阴性名词，复数 retraites","s":"退休；退休金。prendre sa retraite = 退休；être à la retraite = 已退休；toucher sa retraite = 领退休金。也可指「撤退」：battre en retraite，或「静修」。","ipa":"[ʁə.tʁɛt]","ph":"re 读 [ʁə]；tr [tʁ]；ai 读 [ɛ]；-te 读 [t]，结尾 e 不发音。","pi":"ai 读 [ɛ]，不是 [ai]；注意 re- 开头的 r 是小舌音。","et":"来自动词 retraire（拉丁语 retrahere：向后拉），原义「退回」，引申为「从工作中退下来」。","ex":[["Il prend sa retraite bientôt.","他快要退休了。"],["Mes parents sont à la retraite depuis deux ans.","我父母已经退休两年了。"]],"co":[["prendre sa retraite","退休"],["être à la retraite","已退休"],["l'âge de la retraite","退休年龄"],["une maison de retraite","养老院"]],"sy":[["pension","courant","退休金（也指寄宿处）"],["repos","courant","休息"],["retiré(e)","courant","形容词：已退休的"]],"fq":"中频，日常常用。","me":"re-traite：往后撤，从工作中「撤」出来。","tr":{"zh":"我爷爷去年退休了。","fr":"Mon grand-père a pris sa retraite l'année dernière.","alt":"Mon grand-père est à la retraite depuis l'année dernière.","note":"prendre sa retraite 用 passé composé 表示动作已发生。"}},
 "La tour Eiffel": {"pos":"n.f. 阴性名词（tour），复数 tours","s":"埃菲尔铁塔，1889 年为世博会建成，高约 330 米，是巴黎的象征。注意 une tour 指「塔」是阴性，而 un tour 指「一圈；散步」是阳性。","ipa":"[tuʁ ɛ.fɛl]","ph":"tour 读 [tuʁ]，ou [u]；Eiffel 读 [ɛ.fɛl]，ei 读 [ɛ]，ff 读一个 [f]，el 读 [ɛl]。","pi":"Eiffel 的 ei 读 [ɛ]，不读 [ai]；tour 阴性，所以 la tour；与 le tour（一圈）区分。","et":"tour 来自拉丁语 turris（塔）。Eiffel 是设计公司创始人 Gustave Eiffel 的姓。","ex":[["La tour Eiffel est très haute.","埃菲尔铁塔非常高。"],["Nous montons en haut de la tour Eiffel.","我们登上埃菲尔铁塔顶。"]],"co":[["monter à la tour Eiffel","登上埃菲尔铁塔"],["une vue sur la tour Eiffel","能看到铁塔的景观"],["au pied de la tour Eiffel","在埃菲尔铁塔脚下"]],"sy":[["la Dame de fer","familier","「铁娘子」，铁塔的昵称"],["monument","courant","古迹、名胜"]],"fq":"旅游话题常见。","me":"la tour（塔，阴性）≠ le tour（一圈，阳性）。","tr":{"zh":"我们晚上在埃菲尔铁塔前拍照。","fr":"Le soir, nous prenons des photos devant la tour Eiffel.","alt":"Le soir, on fait des photos devant la tour Eiffel.","note":"prendre / faire des photos 都常用。"}},
 "La vie": {"pos":"n.f. 阴性名词，复数 vies","s":"生活；生命；人生。la vie quotidienne = 日常生活；gagner sa vie = 谋生；C'est la vie = 这就是生活。Quelle vie ! = 这日子！","ipa":"[vi]","ph":"v [v]；ie 读 [i]，结尾 e 不发音；只有一个音节。","pi":"-ie 结尾读 [i]，e 不发音；vie 和 vit（住；活）、vis（螺丝）读音相同。","et":"来自拉丁语 vita（生命）。同族词：vivre、vital、vivant。","ex":[["La vie est belle.","生活是美好的。"],["Elle gagne bien sa vie.","她收入不错。"]],"co":[["la vie quotidienne","日常生活"],["gagner sa vie","谋生、赚钱养活自己"],["en vie","活着"],["C'est la vie !","这就是生活！"]],"sy":[["existence","soutenu","存在、生活"],["quotidien","courant","日常"]],"fq":"极高频，日常常用。","me":"vie ← vita：vivre、vital 一家人。","tr":{"zh":"在大城市，生活很贵。","fr":"Dans une grande ville, la vie est chère.","alt":"En ville, la vie coûte cher.","note":"la vie est chère = 生活成本高。"}},
 "La vie familiale": {"pos":"n.f. 阴性名词（vie），复数 vies familiales","s":"家庭生活。指一个人与家人共同度过的日子，如陪孩子、吃晚饭、周末。形容词 familial（阴性 familiale）= 家庭的。","ipa":"[vi fa.mi.ljal]","ph":"vie [vi]；familiale 读 [fa.mi.ljal]，-lia- 读 [lja]，-le 的 e 不发音。","pi":"familiale 是阴性，因为 vie 是阴性；familial 的阳性复数是 familiaux。","et":"famille 来自拉丁语 familia；familial 由它加 -ial 而来。","ex":[["J'aime ma vie familiale.","我喜欢我的家庭生活。"],["Sa vie familiale est très heureuse.","他的家庭生活很幸福。"]],"co":[["une vie familiale heureuse","幸福的家庭生活"],["concilier vie familiale et vie professionnelle","兼顾家庭与工作"],["la vie de famille","家庭生活（另一种说法）"]],"sy":[["vie de famille","courant","同义说法，更口语"],["foyer","soutenu","家、家庭"]],"fq":"中频，日常常用。","me":"vie + familiale：形容词阴性，要加 -e。","tr":{"zh":"我很重视我的家庭生活。","fr":"J'accorde beaucoup d'importance à ma vie familiale.","alt":"Ma vie de famille, c'est très important pour moi.","note":"accorder de l'importance à = 重视。"}},
 "La vie personnelle": {"pos":"n.f. 阴性名词（vie），复数 vies personnelles","s":"个人生活；私生活。与工作或家庭相对，指自己的时间、爱好和感情生活。形容词 personnel(le) = 个人的。","ipa":"[vi pɛʁ.sɔ.nɛl]","ph":"vie [vi]；personnelle 读 [pɛʁ.sɔ.nɛl]，er 读 [ɛʁ]，-nn- 读一个 [n]，-elle 读 [ɛl]。","pi":"personnelle 有两个 n、两个 l；与 personnel（阳性，员工）形近。","et":"personnel 来自 personne（人）+ -el，personne 来自拉丁语 persona（面具；人物）。","ex":[["Ma vie personnelle est importante.","我的个人生活很重要。"],["Il parle rarement de sa vie personnelle.","他很少谈自己的私生活。"]],"co":[["séparer vie personnelle et vie professionnelle","把私生活与工作分开"],["la vie privée","私生活（更常用）"],["parler de sa vie personnelle","谈自己的私生活"]],"sy":[["vie privée","courant","私生活，更常说"],["intimité","soutenu","隐私"]],"fq":"中频，日常常用。","me":"personnelle = 「个人的」，阴性要配 vie。","tr":{"zh":"我不想谈我的私生活。","fr":"Je ne veux pas parler de ma vie personnelle.","alt":"Je préfère ne pas parler de ma vie privée.","note":"ne… pas 包住变位动词，后面接动词原形。"}},
 "La vie professionnelle": {"pos":"n.f. 阴性名词（vie），复数 vies professionnelles","s":"职业生活；职场生活。指一个人工作中的日子和事业。entrer dans la vie professionnelle = 步入职场。","ipa":"[vi pʁɔ.fɛ.sjɔ.nɛl]","ph":"vie [vi]；professionnelle 读 [pʁɔ.fɛ.sjɔ.nɛl]，ss 读 [s]，-ion- 读 [jɔ]，-nn- 读一个 [n]。","pi":"professionnelle 写两个 s、两个 n、两个 l，容易拼错；ss 读 [s]。","et":"profession 来自拉丁语 professio（公开声明）；加后缀 -el 成形容词。","ex":[["Sa vie professionnelle est bien remplie.","他的职业生活很充实。"],["Elle débute sa vie professionnelle à Lyon.","她在里昂开始自己的职业生涯。"]],"co":[["entrer dans la vie professionnelle","步入职场"],["une vie professionnelle chargée","忙碌的职业生活"],["équilibrer vie privée et vie professionnelle","平衡私人与职业生活"]],"sy":[["carrière","courant","职业生涯"],["travail","courant","工作"]],"fq":"中频，日常常用。","me":"vie + professionnelle：professionnel 要配阴性 vie。","tr":{"zh":"她的职业生活很忙。","fr":"Sa vie professionnelle est très chargée.","alt":"Elle est très prise par son travail.","note":"chargé(e) = 忙碌的、满满的。"}},
 "Une animation": {"pos":"n.f. 阴性名词，复数 animations","s":"活动；热闹气氛；动画。Il y a de l'animation dans la rue = 街上很热闹；un film d'animation = 动画片；une animation pour enfants = 儿童活动。","ipa":"[a.ni.ma.sjɔ̃]","ph":"a [a]；ni [ni]；ma [ma]；-tion 读 [sjɔ̃]，t 读 [s]，-on 读鼻化 [ɔ̃]。","pi":"-tion 读 [sjɔ̃]，t 读 [s]；结尾 n 不发音。","et":"来自拉丁语 animatio，源自 anima（气息；灵魂）。同族词：animer（使活跃）、animal（动物）。","ex":[["Il y a une animation dans la rue.","街上有活动。"],["Ce soir, il y a de l'animation sur la place.","今晚广场上很热闹。"]],"co":[["un film d'animation","动画片"],["une animation pour enfants","儿童活动"],["l'animation du quartier","街区的热闹气氛"],["un animateur / une animatrice","活动主持人；动画师"]],"sy":[["activité","courant","活动"],["dessin animé","courant","动画片（一般说法）"],["vie","courant","生气、热闹"]],"fq":"中频，日常常用。","me":"anima（灵魂）：让东西「活起来」。","tr":{"zh":"夏天，海边有很多活动。","fr":"En été, il y a beaucoup d'animations au bord de la mer.","alt":"L'été, la plage est pleine d'animations.","note":"beaucoup de + 复数名词。"}},
 "Une balade": {"pos":"n.f. 阴性名词，复数 balades","s":"散步；闲逛；兜风。一般比较轻松随意：faire une balade en forêt / à vélo / en voiture。口语很常用。","ipa":"[ba.lad]","ph":"ba [ba]；la [la]；-de 读 [d]，结尾 e 不发音。","pi":"balade（散步）和 ballade（民谣，叙事诗）读音一样，拼写不同；写 balade 只有一个 l。","et":"来自动词 se balader，可追溯到普罗旺斯语 balar（跳舞）。","ex":[["Nous faisons une petite balade.","我们去散散步。"],["Dimanche, on fait une balade en forêt.","星期天我们去森林里逛逛。"]],"co":[["faire une balade","散步、逛逛"],["une balade à vélo","骑车兜风"],["une balade en forêt","森林漫步"],["se balader","闲逛（动词）"]],"sy":[["promenade","courant","散步（更通用）"],["tour","familier","转一圈"],["randonnée","courant","徒步（更远更累）"]],"fq":"高频，日常常用，口语化。","me":"balade：想「慢悠悠地晃」，像 ballade 的轻松版。","tr":{"zh":"晚饭后我们去散个步吧。","fr":"Après le dîner, on fait une petite balade ?","alt":"Après dîner, on va se balader un peu ?","note":"on 在口语里常代替 nous。"}},
 "Une chanson": {"pos":"n.f. 阴性名词，复数 chansons","s":"歌曲；歌。une chanson d'amour = 情歌；chanter une chanson = 唱一首歌；la chanson française = 法语歌曲（传统）。","ipa":"[ʃɑ̃.sɔ̃]","ph":"ch [ʃ]；an 读鼻化 [ɑ̃]；s 读 [s]；on 读鼻化 [ɔ̃]。两个鼻化元音，n 都不发音。","pi":"an [ɑ̃] 和 on [ɔ̃] 是两个不同的鼻音；ch 读 [ʃ]。chanson 是阴性。","et":"来自拉丁语 cantio，源自 cantare（唱）。同族词：chanter、chanteur、chant。","ex":[["C'est ma chanson préférée.","这是我最喜欢的歌。"],["Elle chante une chanson française.","她在唱一首法语歌。"]],"co":[["une chanson d'amour","情歌"],["une chanson populaire","流行歌曲"],["chanter une chanson","唱歌"],["la chanson française","法语歌曲"]],"sy":[["morceau","courant","一首曲子"],["tube","familier","热门歌曲"],["air","courant","曲调"]],"fq":"高频，日常常用。","me":"chanson ← chanter：两个鼻音 [ɑ̃] [ɔ̃]。","tr":{"zh":"你知道这首歌吗？","fr":"Tu connais cette chanson ?","alt":"Tu connais cette chanson-là ?","note":"chanson 是阴性，用 cette。"}},
 "Une compétition": {"pos":"n.f. 阴性名词，复数 compétitions","s":"比赛；竞赛；竞争。体育比赛、考试、商业竞争都能用。participer à une compétition = 参加比赛；un esprit de compétition = 竞争精神。","ipa":"[kɔ̃.pe.ti.sjɔ̃]","ph":"com 读鼻化 [kɔ̃]，m 不发音；pé [pe]；ti [ti]；-tion 读 [sjɔ̃]。","pi":"com- 的 m 不发音，是鼻化音 [kɔ̃]；-tion 读 [sjɔ̃]；不是 [kɔm...]。","et":"来自拉丁语 competitio，源自 competere（一起追求）。同族词：compétitif、concurrence。","ex":[["Il gagne la compétition.","他赢得了比赛。"],["Elle participe à une compétition de natation.","她参加游泳比赛。"]],"co":[["participer à une compétition","参加比赛"],["gagner / perdre une compétition","赢 / 输比赛"],["une compétition sportive","体育比赛"],["l'esprit de compétition","竞争精神"]],"sy":[["concours","courant","竞赛、考试选拔"],["match","courant","一场比赛"],["concurrence","courant","商业竞争"]],"fq":"中频，日常常用。","me":"com-pét-ition：和 compete 同族，一起「追求」。","tr":{"zh":"她准备参加游泳比赛。","fr":"Elle se prépare pour une compétition de natation.","alt":"Elle s'entraîne pour une compétition de natation.","note":"se préparer pour = 为……做准备。"}},
 "Une exposition": {"pos":"n.f. 阴性名词，复数 expositions","s":"展览；展出。une exposition d'art = 艺术展；aller voir une exposition = 去看展。也可指「朝向」（l'exposition au sud = 朝南）和「曝光」。","ipa":"[ɛk.spo.zi.sjɔ̃]","ph":"ex 在这里读 [ɛk]；sp [sp]；o 读 [o]；s 在元音间读 [z]；-tion 读 [sjɔ̃]。","pi":"expo- 里 s 读 [z]，不读 [s]；-tion 读 [sjɔ̃]。口语常简称 une expo。","et":"来自拉丁语 expositio，源自 exponere（摆出来）。同族词：exposer、expo（简称）。","ex":[["Je visite une exposition d'art.","我参观一个艺术展。"],["Il y a une belle exposition au musée.","博物馆里有一个很棒的展览。"]],"co":[["visiter une exposition","参观展览"],["une exposition d'art","艺术展"],["une exposition temporaire","临时展览"],["l'exposition au soleil","日晒、朝向阳光"]],"sy":[["expo","familier","展览的简称"],["salon","courant","展销会"],["vernissage","courant","开幕式"]],"fq":"中频，日常常用。","me":"ex-position：把东西「摆出（ex）」来给人看。","tr":{"zh":"周六我们去看一个摄影展。","fr":"Samedi, nous allons voir une exposition de photos.","alt":"Samedi, on va à une expo photo.","note":"expo 是口语简称。"}},
 "Une oeuvre": {"pos":"n.f. 阴性名词，复数 œuvres；规范写法 œuvre（o 和 e 合写）","s":"作品；著作。une œuvre d'art = 艺术品；l'œuvre complète = 全集。les œuvres de charité = 慈善事业。书中写作 oeuvre。","ipa":"[œvʁ]","ph":"œu 读 [œ]；v [v]；r 小舌音 [ʁ]；结尾 e 不发音，只有一个音节 [œvʁ]。","pi":"œu 读 [œ]，不是 [u]；单数 œuvre 和复数 œuvres 读音相同 [œvʁ]。","et":"来自拉丁语 opera（工作；劳作），与 opéra（歌剧）同族。","ex":[["C'est une belle oeuvre.","这是一件美丽的作品。"],["Elle admire les œuvres de Monet.","她欣赏莫奈的作品。"]],"co":[["une œuvre d'art","艺术品"],["l'œuvre complète","全集"],["un chef-d'œuvre","杰作"],["mettre en œuvre","实施、付诸行动"]],"sy":[["ouvrage","soutenu","著作"],["travail","courant","工作成果"],["création","courant","创作"]],"fq":"中频，文化话题常用。","me":"œuvre ← opera：与 opéra 是亲戚，都是「作品」。","tr":{"zh":"这件作品我特别喜欢。","fr":"J'aime beaucoup cette œuvre.","alt":"Cette œuvre me plaît énormément.","note":"plaire à qqn = 令某人喜欢。"}},
 "Une peinture": {"pos":"n.f. 阴性名词，复数 peintures","s":"画；绘画；油漆。可指一幅画（une peinture à l'huile 油画），也可指涂料（une peinture blanche 白漆）。画家是 un peintre。","ipa":"[pɛ̃.tyʁ]","ph":"ein 读鼻化 [ɛ̃]；t [t]；u 读 [y]（嘴圆）；r 小舌音；结尾 e 不发音。","pi":"ein 读 [ɛ̃]，n 不发音；-ure 里 u 读 [y]，不读 [u]；peinture 写 ein。","et":"来自动词 peindre（拉丁语 pingere：画）。同族词：peintre、peint。","ex":[["Cette peinture est célèbre.","这幅画很有名。"],["Nous repeignons la chambre avec une peinture blanche.","我们用白漆重新粉刷房间。"]],"co":[["une peinture à l'huile","油画"],["une peinture murale","壁画"],["de la peinture fraîche","油漆未干"],["faire de la peinture","画画"]],"sy":[["tableau","courant","一幅画（具体的画）"],["toile","courant","画布；油画"],["dessin","courant","素描、线条画"]],"fq":"中高频，日常常用。","me":"peinture ← peindre：-eint- 读鼻音 [ɛ̃]。","tr":{"zh":"我很喜欢这幅画。","fr":"J'adore cette peinture.","alt":"Ce tableau me plaît beaucoup.","note":"cette + 阴性名词。"}},
 "Une photo (photographie)": {"pos":"n.f. 阴性名词，复数 photos / photographies","s":"照片；摄影。photo 是 photographie 的简称，口语里几乎只说 photo。prendre une photo = 拍照；une photo de famille = 全家福。photographie 也指摄影这门艺术。","ipa":"[fo.to]","ph":"ph 读 [f]；o 读 [o]；to [to]；两个音节。photographie 读 [fo.to.gʁa.fi]。","pi":"ph 读 [f]，不读 [p]；photo 是阴性（la photo）。","et":"来自希腊语 phôs, phōtós（光）+ graphein（写）：「用光来画」。","ex":[["Je prends une photo.","我拍一张照片。"],["Tu peux me prendre en photo ?","你能给我拍张照吗？"]],"co":[["prendre une photo","拍照"],["une photo de famille","全家福"],["un album photo","相册"],["en photo","在照片里"]],"sy":[["cliché","soutenu","照片（较书面）"],["image","courant","图片、画面"],["selfie","courant","自拍"]],"fq":"极高频，日常常用。","me":"photo = 光（phôs）：用光「写」下来。","tr":{"zh":"我可以拍张照吗？","fr":"Je peux prendre une photo ?","alt":"Je peux faire une photo ?","note":"prendre une photo 比 faire une photo 更标准。"}},
 "Une piste de danse": {"pos":"n.f. 阴性名词（piste），复数 pistes de danse","s":"舞池；跳舞的区域。aller sur la piste de danse = 下舞池。piste 单独也指「跑道；滑雪道；线索」。","ipa":"[pist də dɑ̃s]","ph":"piste 读 [pist]，结尾 e 不发音；de 读 [də]；danse 读 [dɑ̃s]，an 读鼻化 [ɑ̃]。","pi":"piste 里的 s 读 [s]，不要读成 [z]；danse 中 an 读 [ɑ̃]。","et":"piste 来自意大利语 pista，源自拉丁语 pistare（踩踏）。danse 来自动词 danser。","ex":[["Ils vont sur la piste de danse.","他们走上舞池。"],["La piste de danse est pleine de monde.","舞池里挤满了人。"]],"co":[["aller sur la piste de danse","下舞池"],["une piste de ski","滑雪道"],["une piste cyclable","自行车道"],["une piste d'atterrissage","着陆跑道"]],"sy":[["parquet","courant","舞池地板（俱乐部里的）"],["piste","courant","跑道、赛道"]],"fq":"低频，休闲话题。","me":"piste + danse：「跳舞用的跑道」。","tr":{"zh":"音乐一响，大家都下了舞池。","fr":"Dès que la musique commence, tout le monde va sur la piste de danse.","alt":"Quand la musique démarre, tout le monde danse.","note":"tout le monde 后动词用单数。"}},
 "Une visite": {"pos":"n.f. 阴性名词，复数 visites","s":"参观；拜访；探望；看病。une visite guidée = 导览参观；rendre visite à qqn = 拜访某人；une visite médicale = 体检。","ipa":"[vi.zit]","ph":"v [v]；i [i]；s 在元音间读 [z]；-te 读 [t]，结尾 e 不发音。","pi":"s 读 [z]，不读 [s]；rendre visite à qqn 里 visite 不加冠词。","et":"来自动词 visiter（拉丁语 visitare，源自 videre，看）。同族词：visiteur、visiter。","ex":[["La visite du musée est intéressante.","参观博物馆很有趣。"],["Je rends visite à ma grand-mère le dimanche.","我星期天去看望我奶奶。"]],"co":[["une visite guidée","有导游的参观"],["rendre visite à qqn","拜访某人"],["une visite médicale","体检"],["en visite","访问中"]],"sy":[["tour","familier","游览一圈"],["voyage","courant","旅行"],["passage","courant","路过、短暂停留"]],"fq":"高频，日常常用。","me":"visite ← voir（看）：去「看」某个地方或某个人。","tr":{"zh":"明天我们要去参观城堡。","fr":"Demain, nous visitons le château.","alt":"Demain, on fait la visite du château.","note":"visiter + 地点；rendre visite à + 人。"}},
 "Mon chéri / Ma chérie": {"pos":"n. 名词，阳性 chéri，阴性 chérie；复数 chéris / chéries","s":"亲爱的，对爱人、孩子或亲近的人的昵称。男性说 mon chéri，女性说 ma chérie。一般只用于家人和亲密的人。","ipa":"[ʃe.ʁi]","ph":"ch 读 [ʃ]；é 读 [e]；ri 读 [ʁi]。阳性 chéri 和阴性 chérie 读音相同。","pi":"阴性只多一个 e，读音完全一样；mon 对 chéri，ma 对 chérie，别搞混。","et":"来自动词 chérir（珍爱），源自形容词 cher（拉丁语 carus，珍贵的）。","ex":[["Bonjour mon chéri.","你好，亲爱的。"],["Ma chérie, tu viens dîner ?","亲爱的，你来吃晚饭吗？"]],"co":[["mon chéri / ma chérie","亲爱的"],["mon cher / ma chère","亲爱的（较正式）"],["mon amour","我的爱"]],"sy":[["mon amour","courant","我的爱"],["mon cœur","courant","我的心肝"],["ma puce","familier","小宝贝"]],"fq":"中频，亲密关系里常用。","me":"chéri ← cher：想成「cher = 珍贵」，所以是「被珍爱的人」。","tr":{"zh":"亲爱的，晚饭准备好了。","fr":"Ma chérie, le dîner est prêt.","alt":"Chérie, à table !","note":"对男性说 mon chéri，对女性说 ma chérie。"}},
 "Un acteur / Une actrice": {"pos":"n. 名词，acteur（阳）/ actrice（阴），复数 acteurs / actrices","s":"演员（电影、戏剧、电视都可以）。女演员是 une actrice，词尾变 -eur → -rice。引申义：acteur 也可指「参与者、重要角色」，如 les acteurs de l'économie。","ipa":"[ak.tœʁ] / [ak.tʁis]","ph":"c 读 [k]；-eur 读 [œʁ]；actrice 中 c 和 t 连读成 [ktʁ]，结尾 e 不发音。","pi":"-eur 的 r 要发（不像英语 actor 的弱化）；阳性 acteur 和阴性 actrice 的结尾不同，别写成 acteure。","et":"拉丁语 actor（行动者、表演者），来自 agere（做、行动）。同族：action, agir, acte。","ex":[["C'est un bon acteur.","他是个好演员。"],["Cette actrice joue dans un film français.","这位女演员在一部法国电影里演出。"]],"co":[["un acteur de cinéma / de théâtre","电影演员 / 戏剧演员"],["un acteur connu","一位知名演员"],["le rôle d'un acteur","演员的角色"]],"sy":[["comédien / comédienne","courant","演员，尤指舞台剧演员"],["vedette","courant","明星、主角"]],"fq":"高频，日常常用。","me":"acteur 来自 act（行动）：在台上「行动」的人。","tr":{"zh":"这位女演员很有名。","fr":"Cette actrice est très connue.","alt":"Cette actrice, elle est super connue.","note":"形容词 connue 要和阴性名词 actrice 配合，加 e。"}},
 "Une discothèque / Un club / Une boîte de nuit": {"pos":"n.f. 阴性名词 discothèque（复数 discothèques）；club 为 n.m.；boîte de nuit 为 n.f.","s":"夜店；迪厅。三个说法都指晚上跳舞喝酒的地方。discothèque 最标准，boîte de nuit 最常说，口语里常简称 une boîte（aller en boîte = 去夜店），club 稍时髦。","ipa":"[dis.kɔ.tɛk]","ph":"c 在 o 前读 [k]；th 读 [t]；è 读 [ɛ]，结尾 que 读 [k]。（club [klœb]；boîte de nuit [bwat.də.nɥi]）","pi":"th 不读 [θ]，读 [t]。boîte 的 oî 读 [wa]。club 的 u 读 [œ]，不是 [ʌ]。","et":"disque（唱片）+ -thèque（希腊语 thêkê，盒子、存放处），和 bibliothèque 同样构词。","ex":[["Nous allons en boîte de nuit.","我们去夜店。"],["Cette discothèque ferme à cinq heures du matin.","这家迪厅早上五点才关门。"]],"co":[["aller en boîte","去夜店"],["sortir en discothèque","出去泡迪厅"],["un club de jazz","爵士俱乐部"]],"sy":[["boîte","familier","夜店的口语简称"],["night-club","courant","夜总会（借自英语）"]],"fq":"中频，口语里常说 aller en boîte。","me":"disque + -thèque：放唱片的「盒子」，也就是放音乐的地方。","tr":{"zh":"周六晚上我们去夜店。","fr":"Samedi soir, nous allons en boîte de nuit.","alt":"Samedi soir, on va en boîte.","note":"说「去夜店」用 en boîte，介词是 en，不是 à。"}},
 "Un(e) artiste": {"pos":"n.m./n.f. 名词，阴阳同形（un artiste / une artiste），复数 artistes","s":"艺术家；艺人。可指画家、音乐家、演员等一切从事艺术的人。形容词是 artistique。也可指「很有艺术天分的人」。","ipa":"[aʁ.tist]","ph":"ar [aʁ]；t 读 [t]；-iste 读 [ist]，结尾 e 不发音。","pi":"阴阳同形，只靠冠词 un / une 区分。r 要用小舌音发出来。","et":"来自拉丁语 ars, artis（技艺、艺术）加后缀 -iste。同族：art, artisan, artistique。","ex":[["Cet artiste a beaucoup de talent.","这位艺术家很有才华。"],["Elle est artiste peintre.","她是画家。"]],"co":[["un artiste peintre","画家"],["un artiste de rue","街头艺人"],["un grand artiste","一位伟大的艺术家"]],"sy":[["créateur / créatrice","soutenu","创作者"],["peintre","courant","画家（更具体）"]],"fq":"高频，日常常用。","me":"art + iste：做 art（艺术）的人。","tr":{"zh":"她是一位很有才华的艺术家。","fr":"Elle est une artiste pleine de talent.","alt":"C'est une artiste qui a beaucoup de talent.","note":"表示职业时常省略冠词：Elle est artiste."}},
 "Un(e) athlète": {"pos":"n.m./n.f. 名词，阴阳同形（un athlète / une athlète），复数 athlètes","s":"运动员，尤指田径等竞技运动员。比 sportif 更强调「专业、高水平」。形容词是 athlétique（体格健壮的）。","ipa":"[a.tlɛt]","ph":"th 读 [t]；è 读 [ɛ]，结尾 -te 的 t 要读出。","pi":"th 读 [t]，不是 [θ]。开头 a 和 th 之间连得很紧，读 [a.tlɛt]。阴阳同形。","et":"来自希腊语 athlêtês（竞赛者），经拉丁语进入法语。同族：athlétisme（田径）。","ex":[["C'est un grand athlète.","他是一位伟大的运动员。"],["Cette athlète prépare les Jeux olympiques.","这位女运动员在备战奥运会。"]],"co":[["un athlète de haut niveau","高水平运动员"],["un athlète olympique","奥运会运动员"],["l'athlétisme","田径运动"]],"sy":[["sportif / sportive","courant","泛指爱运动或从事运动的人"],["champion / championne","courant","冠军"]],"fq":"中频。","me":"athlète 像英语 athlete，只是结尾多了个 è。","tr":{"zh":"这位运动员每天训练。","fr":"Cet athlète s'entraîne tous les jours.","alt":"Cet athlète s'entraîne chaque jour.","note":"athlète 阴阳同形，指女性时用 cette athlète。"}},
 "Un(e) débutant(e)": {"pos":"n.m./n.f. 名词，débutant（阳）/ débutante（阴），复数 débutants / débutantes；也可作形容词","s":"初学者；新手。débutant en anglais = 英语初学者。也可作形容词：un joueur débutant。对应动词 débuter（开始）。","ipa":"[de.by.tɑ̃] / [de.by.tɑ̃t]","ph":"é [e]；u 读 [y]（嘴唇圆、舌头靠前）；-ant 读鼻化音 [ɑ̃]；阴性 -ante 的 t 要发音。","pi":"u 是 [y]，不是 [u]。阳性结尾 -ant 的 t 不发音，阴性 -ante 则发 [t]。","et":"来自动词 débuter（开始），再加后缀 -ant。同族：début（开始）。","ex":[["Je suis un débutant en anglais.","我是英语初学者。"],["Il y a un cours pour débutants.","有一个初学者课程。"]],"co":[["un cours pour débutants","初学者课程"],["débutant en + 科目","某科目的初学者"],["un grand débutant","完全的新手"]],"sy":[["novice","soutenu","新手、没有经验的人"],["apprenant","courant","学习者"],["expert","courant","反义：行家"]],"fq":"中频，学习语境里常见。","me":"début（开始）+ -ant：刚「开始」的人。","tr":{"zh":"我在法语上是个初学者。","fr":"Je suis débutant en français.","alt":"Je suis un débutant en français.","note":"女生说 Je suis débutante。表示身份时可以省略 un。"}},
 "Un(e) DJ": {"pos":"n.m./n.f. 名词，阴阳同形（un DJ / une DJ），复数 DJ 或 DJs","s":"DJ；打碟的人，负责在夜店、派对放音乐。是借自英语的缩写，发音按字母读。也写作 deejay，但 DJ 最常见。","ipa":"[di.dʒi]","ph":"按字母读：D [di]，J 读英语式的 [dʒi]，不是法语字母 j 的 [ʒi]。","pi":"J 在这里读英语 [dʒi]，别读成法语字母名 [ʒi]。","et":"借自英语 DJ（disc jockey 的缩写）。","ex":[["Le DJ met de la musique.","DJ 在放音乐。"],["Ce DJ travaille dans une boîte à Paris.","这位 DJ 在巴黎的一家夜店工作。"]],"co":[["mixer / mixer des morceaux","混音，打碟"],["un DJ set","DJ 现场演出"],["un DJ résident","夜店驻场 DJ"]],"sy":[["disc-jockey","courant","全称，较少用"],["animateur / animatrice","courant","主持人、活动司仪"]],"fq":"中频，音乐与夜生活语境里常见。","me":"和英语一样读，只是字母读法改成 di-dji。","tr":{"zh":"今晚 DJ 在夜店放音乐。","fr":"Ce soir, le DJ met de la musique en boîte.","alt":"Ce soir, le DJ passe de la musique en boîte de nuit.","note":"mettre de la musique = 放音乐；de la 表示不可数的量。"}},
 "Un(e) écrivain(e)": {"pos":"n.m./n.f. 名词，écrivain（阳）/ écrivaine（阴），复数 écrivains / écrivaines","s":"作家；写书的人，尤指文学作品的作者。阴性写作 écrivaine（现在很通用），有时也说 une femme écrivain。","ipa":"[e.kʁi.vɛ̃] / [e.kʁi.vɛn]","ph":"é [e]；-ain 读鼻化音 [ɛ̃]；阴性 -aine 读 [ɛn]，n 要发。","pi":"é 开头容易漏重音符号；阳性结尾 -ain 的 n 不发音，阴性 -aine 要发 [n]。","et":"由动词 écrire（写）加后缀 -ain 构成，根源是拉丁语 scribere。","ex":[["Elle est écrivaine.","她是作家。"],["Cet écrivain a écrit dix romans.","这位作家写了十部小说。"]],"co":[["un écrivain célèbre","著名作家"],["un écrivain français","法国作家"],["devenir écrivain","成为作家"]],"sy":[["auteur / autrice","courant","作者（泛指任何作品的作者）"],["romancier / romancière","soutenu","小说家"]],"fq":"高频，日常常用。","me":"écri(re) + -vain：「写」东西的人。","tr":{"zh":"她想成为一名作家。","fr":"Elle veut devenir écrivaine.","alt":"Elle rêve de devenir écrivaine.","note":"表示职业时 devenir 后常不加冠词。"}},
 "Un(e) guide": {"pos":"n.m./n.f. 名词，阴阳同形（un guide / une guide），复数 guides","s":"导游；向导。注意：un guide 也可以指「指南书」，如 un guide touristique（旅游指南）。当「导游」时，阴阳同形，靠冠词区分。","ipa":"[ɡid]","ph":"gu 在 i 前读 [ɡ]，u 不发音；-de 的 d 要读出，结尾 e 不发音。","pi":"gu + i 里的 u 不发音，读 [ɡid]，不是 [ɡɥid]。","et":"借自意大利语 guida；与动词 guider（引导）同族。","ex":[["Le guide explique l'histoire.","导游讲解历史。"],["J'achète un guide de Paris.","我买一本巴黎指南。"]],"co":[["un guide touristique","导游；旅游指南"],["un guide de voyage","旅行指南"],["faire appel à un guide","请一位向导"]],"sy":[["accompagnateur / accompagnatrice","courant","陪同人员、领队"],["cicérone","soutenu","（书面）向导"]],"fq":"中频，旅行语境里常见。","me":"guide 读 [ɡid]，像英语 guide 的发音，但 u 不发音。","tr":{"zh":"导游带我们参观老城。","fr":"Le guide nous fait visiter la vieille ville.","alt":"Le guide nous emmène visiter le vieux quartier.","note":"faire visiter + 地点：带某人参观。"}},
 "Un(e) musicien(ne)": {"pos":"n.m./n.f. 名词，musicien（阳）/ musicienne（阴），复数 musiciens / musiciennes；也可作形容词","s":"音乐家；乐手；演奏者。泛指会演奏或创作音乐的人，不一定是知名音乐家。也可作形容词，表示「有音乐天赋的」。","ipa":"[my.zi.sjɛ̃] / [my.zi.sjɛn]","ph":"u 读 [y]；s 在元音间读 [z]；-ien 读 [jɛ̃]，阴性 -ienne 读 [jɛn]。","pi":"u 是 [y]；s 读 [z]；阴性有 nn，别写成 musicienne 少一个 n。阳性结尾的 n 不发音。","et":"来自 musique + -ien；musique 源自拉丁语 musica，再追溯到希腊语 mousikê（缪斯的艺术）。","ex":[["Ce musicien joue bien.","这位音乐家弹得很好。"],["Ma sœur est musicienne dans un orchestre.","我姐姐是管弦乐团的乐手。"]],"co":[["un musicien de rue","街头艺人"],["un bon musicien","出色的乐手"],["un musicien professionnel","职业乐手"]],"sy":[["instrumentiste","soutenu","乐器演奏者"],["compositeur / compositrice","courant","作曲家"]],"fq":"高频，日常常用。","me":"musique + -ien：玩音乐的人。","tr":{"zh":"我哥哥是职业音乐家。","fr":"Mon frère est musicien professionnel.","alt":"Mon frère est musicien de métier.","note":"表示职业，通常不加冠词。"}},
 "Un(e) scénariste": {"pos":"n.m./n.f. 名词，阴阳同形（un scénariste / une scénariste），复数 scénaristes","s":"编剧；剧本作者，尤指电影、电视、漫画的剧本。写剧本是 écrire un scénario。","ipa":"[se.na.ʁist]","ph":"sc 在 é 前读 [s]；é [e]；-iste 读 [ist]。","pi":"sc 读 [s]，c 不单独读；拼写里有 é，别漏掉重音。阴阳同形。","et":"来自 scénario（意大利语 scenario，剧本、场景）加后缀 -iste。","ex":[["Il est scénariste pour le cinéma.","他是电影编剧。"],["La scénariste a écrit une belle histoire.","这位编剧写了一个很美的故事。"]],"co":[["un scénariste de cinéma","电影编剧"],["écrire un scénario","写剧本"],["le scénariste d'un film","一部电影的编剧"]],"sy":[["auteur","courant","作者"],["dialoguiste","soutenu","对白编剧"]],"fq":"中频，影视话题里常见。","me":"scénario（剧本）+ iste：写剧本的人。","tr":{"zh":"这位编剧写了一部新电影。","fr":"Ce scénariste a écrit un nouveau film.","alt":"Ce scénariste a écrit le scénario d'un nouveau film.","note":"严格说是写剧本：écrire le scénario d'un film。"}},
 "Admirer": {"pos":"v. 动词，第一组（-er），助动词 avoir","s":"欣赏；钦佩；赞叹。可以欣赏一幅画、一处风景，也可以钦佩一个人。admirer + 名词，直接带宾语，不加介词。","ipa":"[ad.mi.ʁe]","ph":"d 读 [d]；i [i]；-er 读 [e]，r 不发音。","pi":"-er 结尾读 [e]，不要读出 r。注意拼写 admirer 只有一个 m。","et":"拉丁语 admirari（ad- + mirari，惊奇地看）。同族：admiration, admirable。","ex":[["J'admire ce tableau.","我很欣赏这幅画。"],["J'admire son courage.","我佩服他的勇气。"]],"co":[["admirer un paysage","欣赏风景"],["admirer quelqu'un pour sa patience","因某人的耐心而钦佩他"],["Je t'admire.","我佩服你。"]],"sy":[["apprécier","courant","欣赏、喜欢"],["respecter","courant","尊敬"],["mépriser","courant","反义：轻视"]],"fq":"中频，日常和书面语都用。","me":"和英语 admire 几乎一样，后面直接加宾语。","tr":{"zh":"我很欣赏这位艺术家。","fr":"J'admire beaucoup cet artiste.","alt":"J'admire vraiment cet artiste.","note":"admirer 后直接接宾语，不加 de 或 à。"}},
 "Bricoler": {"pos":"v. 动词，第一组（-er），助动词 avoir","s":"做手工活；修修补补；自己动手做（DIY）。可以不带宾语：Il aime bricoler。也可带宾语：bricoler une étagère。口语里也有「随便凑合着弄」的意思。","ipa":"[bʁi.kɔ.le]","ph":"br [bʁ]；c 在 o 前读 [k]；-er 读 [e]。","pi":"bri-co-ler 三个音节，c 读 [k] 不是 [s]。别和 bricole（小玩意儿）混淆。","et":"派生自 bricole（零碎事、小活儿）；同族：bricolage（手工活）、bricoleur（爱动手的人）。","ex":[["Il aime bricoler le dimanche.","他喜欢周日自己动手修东西。"],["Mon père bricole dans le garage.","我爸爸在车库里摆弄东西。"]],"co":[["aimer bricoler","喜欢自己动手"],["faire du bricolage","做手工活、DIY"],["un magasin de bricolage","五金建材店（DIY 店）"]],"sy":[["réparer","courant","修理"],["fabriquer","courant","制作"]],"fq":"中频，说家庭生活时常用。","me":"bricole（小零碎）+ -er：摆弄各种小零碎。","tr":{"zh":"周末我喜欢在家自己动手修东西。","fr":"Le week-end, j'aime bricoler à la maison.","alt":"Le week-end, j'adore bricoler chez moi.","note":"aimer + 不定式，直接接动词原形。"}},
 "Changer": {"pos":"v. 动词，第一组（-er），助动词 avoir；nous changeons","s":"改变；换。changer qch = 换掉某物；changer de + 名词（不加冠词）= 换成另一个。也可作不及物：Tout a changé。口语中 changer de 很常用，如 changer de travail、changer d'avis（改变主意）。","ipa":"[ʃɑ̃.ʒe]","ph":"ch 读 [ʃ]；an 读鼻化音 [ɑ̃]；g 在 e 前读 [ʒ]；-er 读 [e]。","pi":"nous changeons 要保留 e（nous changeons），保持 [ʒ] 的音。changer de + 无冠词名词：changer de voiture。","et":"来自晚期拉丁语 cambiare（交换），可能源自高卢语。","ex":[["Il veut changer de travail.","他想换工作。"],["Tout a changé en dix ans.","十年里一切都变了。"],["Je dois changer ma chemise.","我得换件衬衫。"]],"co":[["changer de travail / de ville","换工作 / 换城市"],["changer d'avis","改变主意"],["changer de l'argent","换钱"],["se changer","换衣服"]],"sy":[["modifier","courant","修改"],["remplacer","courant","替换"],["transformer","courant","改造、使转变"]],"fq":"极高频，日常常用。","me":"change 里有个 g 发 [ʒ]：想成「换」出一个新样子。","tr":{"zh":"我想换一座城市生活。","fr":"Je voudrais changer de ville.","alt":"J'aimerais changer de ville.","note":"changer de + 无冠词名词，表示「换成另一个」。"}},
 "Connaître": {"pos":"v. 动词，不规则，助动词 avoir；je connais, nous connaissons，过去分词 connu","s":"认识；了解；熟悉。connaître 接人、地方、作品，表示「认识、熟悉」。和 savoir 的区别：savoir 接事实或能力（je sais nager），connaître 接具体的人或事物。","ipa":"[kɔ.nɛtʁ]","ph":"c 在 o 前读 [k]；aî 读 [ɛ]；tre 读 [tʁ]，结尾 e 不发音。","pi":"î 上的帽子保留，但 -aître 里 aî 读 [ɛ]。别把 connaître 和 savoir 混用。","et":"拉丁语 cognoscere（co- + noscere，认识）。同族：connaissance（知识；相识）、reconnaître。","ex":[["Je connais bien cette ville.","我很了解这座城市。"],["Tu connais Marie ?","你认识玛丽吗？"],["Elle connaît ce film par cœur.","她对这部电影了如指掌。"]],"co":[["connaître quelqu'un","认识某人"],["faire connaître","让人知道、介绍"],["Enchanté de vous connaître.","很高兴认识您。"],["connaître par cœur","熟记"]],"sy":[["savoir","courant","知道（事实、技能）"],["reconnaître","courant","认出"],["ignorer","soutenu","反义：不知道"]],"fq":"极高频，日常常用。","me":"con-naître：与某人「共同」「出生」于认识里，也就是认得。","tr":{"zh":"你认识这位演员吗？","fr":"Tu connais cet acteur ?","alt":"Vous connaissez cet acteur ?","note":"接具体的人用 connaître，不用 savoir。"}},
 "Décider": {"pos":"v. 动词，第一组（-er），助动词 avoir","s":"决定。décider de + 动词原形 = 决定做某事；décider que + 从句；se décider = 下定决心。也可及物：décider quelque chose（决定某事）。","ipa":"[de.si.de]","ph":"é [e]；c 在 i 前读 [s]；i [i]；-er 读 [e]。","pi":"c 在 i 前读 [s]，不是 [k]。后面接动词原形要加 de：décider de partir，不是 décider partir。","et":"拉丁语 decidere（de- + caedere，切断），本义「一刀决断」。同族：décision, décisif。","ex":[["Je décide de partir.","我决定出发。"],["Ils ont décidé de se marier.","他们决定结婚。"],["Elle n'arrive pas à se décider.","她拿不定主意。"]],"co":[["décider de + 不定式","决定做……"],["décider que…","决定……（接从句）"],["se décider à","下决心去……"]],"sy":[["choisir","courant","选择"],["trancher","familier","拍板、做决断"],["hésiter","courant","反义：犹豫"]],"fq":"高频，日常常用。","me":"de-cide：像英语 decide，把选项「切」掉只剩一个。","tr":{"zh":"我决定明天去看医生。","fr":"Je décide d'aller chez le médecin demain.","alt":"J'ai décidé d'aller voir le médecin demain.","note":"décider de + 动词原形；de 遇到 a 变成 d'。"}},
 "Devenir": {"pos":"v. 动词，不规则，助动词 être；je deviens, nous devenons，过去分词 devenu","s":"成为；变成。可接名词（devenir médecin，不加冠词）或形容词（devenir grand）。变化规则同 venir。复合过去时用 être：il est devenu。","ipa":"[dəv.niʁ]","ph":"de 读弱 e [də]；ve 在口语中常省略，读 [dəv.niʁ]；-ir 读 [iʁ]。","pi":"助动词是 être，不是 avoir：elle est devenue。不要和 venir 的 viens 搞混：deviens。","et":"拉丁语 devenire（de- + venire，来到）。同族：venir, avenir, revenir。","ex":[["Il veut devenir médecin.","他想当医生。"],["Elle est devenue célèbre.","她成名了。"],["Il devient grand.","他长大了。"]],"co":[["devenir + 名词","成为……（职业不加冠词）"],["devenir fou / folle","变疯了"],["Que devenir ?","怎么办？（以后会怎样？）"]],"sy":[["se transformer","courant","转变成"],["tourner","familier","变得（常指变坏）"]],"fq":"极高频，日常常用。","me":"de- + venir：「来到」一个新的状态。","tr":{"zh":"我想成为一名老师。","fr":"Je veux devenir professeur.","alt":"Je voudrais devenir enseignant.","note":"表示职业，devenir 后通常不加冠词。"}},
 "Écrire": {"pos":"v. 动词，不规则，助动词 avoir；j'écris, nous écrivons，过去分词 écrit","s":"写；写信；写作。可接书写内容（écrire une lettre）、接对象（écrire à quelqu'un）。也可表示「写作」：Elle écrit pour un journal。","ipa":"[e.kʁiʁ]","ph":"é [e]；cr [kʁ]；-ire 读 [iʁ]，e 不发音。","pi":"过去分词是 écrit（t 不发音），不是 écrivé。nous écrivons 的 v 是新出现的音。","et":"拉丁语 scribere（写）。同族：écrivain, écriture, décrire。","ex":[["J'écris une lettre.","我写一封信。"],["Écris-moi quand tu arrives.","你到了就给我写信。"],["Il écrit très bien.","他字写得很好。"]],"co":[["écrire à quelqu'un","给某人写信"],["écrire un message / un mail","写消息 / 邮件"],["écrire au tableau","在黑板上写"],["Ça s'écrit comment ?","这个怎么拼？"]],"sy":[["rédiger","soutenu","起草、撰写"],["noter","courant","记下"],["lire","courant","反义：读"]],"fq":"极高频，日常常用。","me":"écri-: 想 écrivain 和 écriture，同一个词根。","tr":{"zh":"我给朋友写了一封信。","fr":"J'ai écrit une lettre à mon ami.","alt":"J'ai envoyé une lettre à mon ami.","note":"écrire à quelqu'un：给某人写，用 à 引出对象。"}},
 "Fermer": {"pos":"v. 动词，第一组（-er），助动词 avoir","s":"关；关闭。关门窗、关店、关灯、关机都可用。fermer à clé = 锁上。反义词是 ouvrir。商店「关门」也可说 fermer。","ipa":"[fɛʁ.me]","ph":"er 在词中读 [ɛʁ]；m [m]；结尾 -er 读 [e]，r 不发音。","pi":"词中间的 er 读 [ɛʁ]，结尾的 -er 读 [e]，同一个拼写两种读音。","et":"拉丁语 firmare（使牢固、使稳固），来自 firmus。同族：ferme（牢固的），affermir。","ex":[["Tu peux fermer la porte ?","你能关门吗？"],["Le magasin ferme à dix-neuf heures.","商店晚上七点关门。"],["Il a fermé les yeux.","他闭上了眼睛。"]],"co":[["fermer la porte / la fenêtre","关门 / 关窗"],["fermer à clé","锁上"],["fermer les yeux","闭眼"],["fermer la lumière","关灯（加拿大说法）"]],"sy":[["clore","soutenu","结束、封闭"],["éteindre","courant","关掉（灯、电器）"],["ouvrir","courant","反义：打开"]],"fq":"极高频，日常常用。","me":"fermer ← firm（牢固）：关好才牢固。","tr":{"zh":"出门前请关好窗户。","fr":"Ferme les fenêtres avant de sortir, s'il te plaît.","alt":"Pense à fermer les fenêtres avant de partir.","note":"avant de + 动词原形：在……之前。"}},
 "Grandir": {"pos":"v. 动词，第二组（-ir，-issons），助动词 avoir；je grandis, nous grandissons","s":"长大；长高；成长。指人或孩子「长高、成熟」。也可引申为「增长、变大」。注意：植物生长更常说 pousser，不说 grandir。","ipa":"[ɡʁɑ̃.diʁ]","ph":"gr [ɡʁ]；an 读鼻化音 [ɑ̃]；-ir 读 [iʁ]，r 要发。","pi":"第二组动词复数加 -iss-：nous grandissons，ils grandissent。助动词用 avoir：il a grandi。","et":"来自 grand（大）加后缀 -ir，即「变大」。拉丁语 grandis。","ex":[["Les enfants grandissent vite.","孩子们长得很快。"],["Tu as grandi !","你长高了！"],["Elle a grandi à Lyon.","她在里昂长大。"]],"co":[["grandir vite","长得快"],["grandir à + 地点","在……长大"],["grandir avec quelqu'un","和某人一起成长"]],"sy":[["pousser","courant","（植物）生长；孩子长高（口语）"],["croître","soutenu","增长"],["rapetisser","courant","反义：变小"]],"fq":"高频，日常常用。","me":"grand + -ir：变得 grand（大）。","tr":{"zh":"我的孩子长得很快。","fr":"Mes enfants grandissent vite.","alt":"Mes enfants poussent vite.","note":"第二组动词：ils grandissent，加 -issent。"}},
 "Jardiner": {"pos":"v. 动词，第一组（-er），助动词 avoir","s":"做园艺；在花园里干活。通常不带宾语：Elle jardine tous les week-ends。名词是 le jardinage（园艺）和 le jardinier（园丁）。","ipa":"[ʒaʁ.di.ne]","ph":"j 读 [ʒ]；ar [aʁ]；din [di]；-ner 读 [ne]。","pi":"j 读 [ʒ]（像 zh），不是 [dʒ]。ar 的 r 要发。","et":"来自 jardin（花园）加后缀 -er。jardin 源自古法语，词根是日耳曼语。","ex":[["Ma mère adore jardiner.","我妈妈爱做园艺。"],["Nous jardinons le dimanche.","我们周日做园艺。"]],"co":[["aimer jardiner","喜欢做园艺"],["faire du jardinage","做园艺"],["un jardinier","园丁"]],"sy":[["cultiver","courant","种植"],["bricoler","courant","做手工活（另一种爱好）"]],"fq":"中频，说爱好时常用。","me":"jardin（花园）+ -er：在花园里干活。","tr":{"zh":"周末我喜欢在花园里干活。","fr":"Le week-end, j'aime jardiner.","alt":"Le week-end, j'adore jardiner dans mon jardin.","note":"aimer + 动词原形；jardiner 一般不带宾语。"}},
 "Jouer": {"pos":"v. 动词，第一组（-er），助动词 avoir","s":"玩；演奏；比赛；扮演。关键搭配：jouer à + 游戏或运动（jouer au foot）；jouer de + 乐器（jouer du piano）；也可 jouer un rôle（扮演角色）。","ipa":"[ʒwe]","ph":"j [ʒ]；ou 在元音前读 [w]；-er 读 [e]。","pi":"jouer à 与 jouer de 容易混：运动用 à，乐器用 de。ou 在 -er 前读半元音 [w]，整个词是一个音节 [ʒwe]。","et":"拉丁语 iocari（开玩笑、玩耍），来自 iocus（玩笑）。同族：jeu, joue（不同源）。","ex":[["Les enfants jouent dans le parc.","孩子们在公园玩。"],["Il joue au tennis.","他打网球。"],["Elle joue de la guitare.","她弹吉他。"]],"co":[["jouer au foot / aux cartes","踢足球 / 打牌"],["jouer du piano / de la guitare","弹钢琴 / 吉他"],["jouer un rôle","扮演角色"],["jouer dans un film","在电影里演出"]],"sy":[["s'amuser","courant","玩得开心"],["interpréter","soutenu","演绎、扮演"]],"fq":"极高频，日常常用。","me":"à + 运动，de + 乐器：「à 玩游戏，de 玩乐器」。","tr":{"zh":"他每周六踢足球。","fr":"Il joue au football tous les samedis.","alt":"Il fait du foot le samedi.","note":"jouer à + le → au：jouer au football。"}},
 "Louer": {"pos":"v. 动词，第一组（-er），助动词 avoir","s":"租；租用，也可指「出租」。louer une voiture 通常是「租一辆车」（从别人那里租），也可能是「把车租出去」，要看上下文。另一个同形词 louer 是「赞美」，较书面。","ipa":"[lwe]","ph":"l [l]；ou 在元音前读 [w]；-er 读 [e]。整个词只有一个音节。","pi":"一个词两个意思：租 / 赞美。「租出去」常说 louer à quelqu'un，「租进来」说 louer 或 prendre en location。","et":"「租」来自拉丁语 locare（放置、出租）；「赞美」来自拉丁语 laudare，两个同形词不同源。","ex":[["Je vais louer une voiture.","我要租一辆车。"],["Ils louent un appartement à Paris.","他们在巴黎租了一间公寓。"],["Elle loue sa maison en été.","她夏天把房子租出去。"]],"co":[["louer une voiture / un appartement","租车 / 租公寓"],["à louer","出租（告示）"],["louer à quelqu'un","租给某人"],["louer quelqu'un","赞美某人（书面）"]],"sy":[["prendre en location","courant","租入"],["acheter","courant","买（对比）"],["féliciter","courant","祝贺、夸奖（对应「赞美」义）"]],"fq":"高频，生活场景里常用。","me":"louer 像 location（租赁）：同一个 lou-/loc- 根。","tr":{"zh":"我们想租一间公寓。","fr":"Nous voulons louer un appartement.","alt":"On cherche un appartement à louer.","note":"à louer 放在名词后，表示「待租的」。"}},
 "Naître": {"pos":"v. 动词，不规则，助动词 être；je nais, il naît，过去分词 né","s":"出生；诞生。常用复合过去时：Je suis né(e) en France。注意：说「我出生在……」用 je suis né，不是现在时。也可引申：un sentiment naît（感情产生）。","ipa":"[nɛtʁ]","ph":"aî 读 [ɛ]；tre 读 [tʁ]，结尾 e 不发音。","pi":"过去分词 né 要和主语配合：elle est née。助动词是 être。il naît 的 î 保留帽子。","et":"拉丁语 nascere（出生）。同族：naissance（出生）、nation（民族）、natal。","ex":[["Je suis né en France.","我在法国出生。"],["Elle est née le trois mai.","她是五月三日出生的。"],["Un bébé naît toutes les secondes.","每一秒钟都有一个婴儿出生。"]],"co":[["naître en / à + 地点","出生在……"],["Je suis né(e) le…","我出生于……"],["la date de naissance","出生日期"],["être né pour…","天生适合……"]],"sy":[["venir au monde","courant","来到世上"],["apparaître","courant","出现、产生"],["mourir","courant","反义：死去"]],"fq":"高频，说个人信息时常用。","me":"naître ↔ naissance ↔ natal：同一个 nas-/nat- 根。","tr":{"zh":"我妹妹在里昂出生。","fr":"Ma sœur est née à Lyon.","alt":"Ma petite sœur est née à Lyon.","note":"être 作助动词，过去分词 née 加 e，与 sœur 配合。"}},
 "Organiser": {"pos":"v. 动词，第一组（-er），助动词 avoir","s":"组织；筹办；安排。常用于办活动：organiser une fête, un voyage。也可用于安排时间、事情：organiser son travail。自反：s'organiser = 安排好自己的事。","ipa":"[ɔʁ.ɡa.ni.ze]","ph":"or [ɔʁ]；g 在 a 前读 [ɡ]；s 在元音间读 [z]；-er 读 [e]。","pi":"拼写是 z 音但写 s：organiser，s 读 [z]。英语里 organize 有 z，法语是 s。","et":"来自 organe（器官；机构）加后缀 -iser；organe 源自希腊语 organon（工具）。","ex":[["Nous allons organiser une fête.","我们要办一个派对。"],["Elle organise bien son travail.","她把工作安排得很好。"],["Il faut s'organiser.","得好好安排一下。"]],"co":[["organiser une fête / une soirée","举办派对 / 晚会"],["organiser un voyage","安排旅行"],["s'organiser","安排好自己的事"],["être bien organisé","很有条理"]],"sy":[["préparer","courant","准备"],["planifier","soutenu","规划"],["arranger","courant","安排、整理"]],"fq":"高频，日常常用。","me":"organ-iser：像把各个「器官」组织成一个整体。","tr":{"zh":"我们要为朋友筹办一个惊喜派对。","fr":"Nous allons organiser une fête surprise pour notre ami.","alt":"On va organiser une fête surprise pour notre ami.","note":"aller + 动词原形：近期将来。"}},
 "Ouvrir": {"pos":"v. 动词，不规则，助动词 avoir；j'ouvre, nous ouvrons，过去分词 ouvert","s":"打开；开（门、窗、盒子、店）。虽然是 -ir 结尾，变位却像 -er：j'ouvre, tu ouvres。商店「营业」也用 ouvrir：Le magasin ouvre à neuf heures。反义词是 fermer。","ipa":"[u.vʁiʁ]","ph":"ou [u]；v [v]；r 要发两次（vr 和结尾 r）。","pi":"j'ouvre 不加 -s；过去分词 ouvert 的 t 不发音。别写成 ouvri。","et":"来自拉丁语 aperire（打开）的演变。同族：ouverture, ouvert。","ex":[["Tu peux ouvrir la fenêtre ?","你能开窗吗？"],["La banque ouvre à neuf heures.","银行九点开门。"],["Il a ouvert une boîte.","他打开了一个盒子。"]],"co":[["ouvrir la porte / la fenêtre","开门 / 开窗"],["ouvrir un compte","开户"],["ouvrir les yeux","睁眼；留心"],["ouvrir l'esprit","开阔视野"]],"sy":[["débloquer","courant","打开、解除"],["fermer","courant","反义：关"]],"fq":"极高频，日常常用。","me":"j'ouvre 像第一组动词：ouvr-e, ouvr-es。","tr":{"zh":"请你打开窗户。","fr":"Tu peux ouvrir la fenêtre, s'il te plaît ?","alt":"Ouvre la fenêtre, s'il te plaît.","note":"Tu peux + 动词原形：礼貌请求。"}},
 "Participer": {"pos":"v. 动词，第一组（-er），助动词 avoir","s":"参加；参与。participer à + 名词 = 参加某活动：participer à un jeu, à une réunion。也可表示「分担」：participer aux frais（分摊费用）。","ipa":"[paʁ.ti.si.pe]","ph":"par [paʁ]；ti 读 [ti]，不是 [si]；c 在 i 前读 [s]；-er 读 [e]。","pi":"后面接 à，不是直接接宾语：participer à la fête。此处 ti 读 [ti]，c 读 [s]。","et":"拉丁语 participare（分享一份），来自 pars（部分）+ capere（拿）。同族：participant, participe。","ex":[["Je participe au jeu.","我参加游戏。"],["Elle participe à la réunion.","她参加会议。"],["Nous participons aux frais.","我们分摊费用。"]],"co":[["participer à + 名词","参加……"],["participer aux frais","分摊费用"],["participer à un concours","参加比赛"],["la participation","参与"]],"sy":[["prendre part à","soutenu","参加"],["assister à","courant","出席（不一定参与）"]],"fq":"高频，日常与工作中常用。","me":"part-ici-per：拿到一份（part）。","tr":{"zh":"我想参加这个比赛。","fr":"Je veux participer à ce concours.","alt":"J'aimerais participer à ce concours.","note":"participer à + 名词；à + ce 保持 à ce。"}},
 "Ressentir": {"pos":"v. 动词，第三组（-ir），助动词 avoir；je ressens, nous ressentons","s":"感受到；感觉到（内心的情感或身体的感觉）。ressentir de la joie / de la peur / de la douleur。比 sentir 更强调「内在感受」。自反 se ressentir de = 受……的影响。","ipa":"[ʁə.sɑ̃.tiʁ]","ph":"re 读弱 e [ʁə]；ss 读 [s]；en 读鼻化音 [ɑ̃]；-ir 读 [iʁ]。","pi":"变位像 sentir：je ressens（s 不发音），nous ressentons 的 t 要读出。re 读弱 e，不是 [ʁe]。","et":"re- + sentir（感觉）；sentir 来自拉丁语 sentire。同族：sentiment, sensation。","ex":[["Je ressens de la joie.","我感到喜悦。"],["Elle ressent une grande fatigue.","她觉得非常疲惫。"],["Il ressent de la peur.","他感到害怕。"]],"co":[["ressentir de la joie / de la peur","感到喜悦 / 害怕"],["ressentir une douleur","感到疼痛"],["ressentir le besoin de","感到有必要……"]],"sy":[["sentir","courant","感觉、闻到"],["éprouver","soutenu","体验、感到"]],"fq":"中频，常用于书面语，口语里 sentir 更常说。","me":"re- + sentir：把感受再「过一遍」，感受得更深。","tr":{"zh":"听这首歌时我感到平静。","fr":"Je ressens du calme quand j'écoute cette chanson.","alt":"Cette chanson me calme, je me sens bien.","note":"ressentir + de la / du + 抽象名词，表示感情。"}},
 "Rêver": {"pos":"v. 动词，第一组（-er），助动词 avoir","s":"做梦；梦想。rêver = 睡觉时做梦；rêver de + 名词或动词原形 = 梦想……。口语里也有「想象、做白日梦」的意思。名词是 le rêve（梦、梦想）。","ipa":"[ʁɛ.ve]","ph":"r [ʁ]；ê [ɛ]；v [v]；-er 读 [e]。","pi":"拼写有 ê；梦想用 rêver de，不是 rêver à。名词 rêve 的 ê 与动词相同。","et":"来源不确定。古法语 resver 有「游荡、胡思乱想」的意思。同族：rêve, rêverie。","ex":[["Je rêve de voyager.","我梦想去旅行。"],["J'ai rêvé de toi cette nuit.","昨晚我梦见了你。"],["Il rêve d'une maison au bord de la mer.","他梦想有一栋海边的房子。"]],"co":[["rêver de + 不定式 / 名词","梦想……、梦见……"],["faire un rêve","做个梦"],["rêver éveillé","白日梦"],["Tu rêves !","你做梦呢！（别想了）"]],"sy":[["souhaiter","soutenu","希望"],["désirer","soutenu","渴望"],["imaginer","courant","想象"]],"fq":"高频，日常常用。","me":"rêve 里的 ê 像一顶帽子：睡觉时「戴着帽子」做梦。","tr":{"zh":"我梦想在法国生活。","fr":"Je rêve de vivre en France.","alt":"J'ai envie de vivre en France, c'est mon rêve.","note":"rêver de + 动词原形。"}},
 "S'entraîner": {"pos":"v. 代动词（pronominal），助动词 être；je m'entraîne, nous nous entraînons","s":"训练；锻炼；练习。s'entraîner à + 动词原形 = 练习做某事；s'entraîner pour + 名词 = 为……训练。运动员训练、学生练习都可以用。","ipa":"[sɑ̃.tʁɛ.ne]","ph":"s' 和 en 连读：[sɑ̃]；aî 读 [ɛ]；n 要读；-er 读 [e]。","pi":"代动词，要带 se：je m'entraîne, il s'entraîne。î 上的帽子保留。名词是 un entraînement（训练）。","et":"en + traîner（拉、拖），本义「拉着前进」。traîner 来自拉丁语 trahere（拉）。同族：entraîneur（教练）。","ex":[["Il s'entraîne tous les jours.","他每天训练。"],["Je m'entraîne à parler français.","我在练习说法语。"],["Elle s'entraîne pour le marathon.","她在为马拉松训练。"]],"co":[["s'entraîner à + 不定式","练习做……"],["s'entraîner pour + 名词","为……训练"],["s'entraîner tous les jours","每天训练"],["un entraîneur","教练"]],"sy":[["s'exercer","soutenu","练习"],["pratiquer","courant","练习、从事"],["se préparer","courant","做准备"]],"fq":"高频，运动与学习话题里常用。","me":"en + traîner：被「拉」着一步步练到好。","tr":{"zh":"我每周三次练习说法语。","fr":"Je m'entraîne à parler français trois fois par semaine.","alt":"Je m'entraîne en français trois fois par semaine.","note":"s'entraîner à + 动词原形；me 要变成 m'。"}},
 "Se balader": {"pos":"v. 代动词（pronominal），助动词 être；je me balade, nous nous baladons","s":"散步；闲逛；溜达。比 se promener 更口语、更放松。名词是 une balade（散步、短途游玩）。可以步行，也可以骑车、开车。","ipa":"[sə.ba.la.de]","ph":"se 读弱 e [sə]；ba [ba]；la [la]；de [de]；-er 读 [e]。","pi":"这是代动词：je me balade, il se balade。名词 balade 只有一个 l。","et":"来源不确定。可能与方言词有关；同族：balade（散步）、baladeur（随身听）。","ex":[["Nous allons nous balader.","我们去逛逛。"],["Le dimanche, je me balade en ville.","周日我在城里闲逛。"],["On se balade au bord de la mer.","我们在海边溜达。"]],"co":[["faire une balade","去散步"],["se balader en ville","在城里闲逛"],["se balader à vélo","骑车兜风"],["aller se balader","去逛逛"]],"sy":[["se promener","courant","散步（更标准）"],["flâner","soutenu","闲逛、漫步"],["se déplacer","courant","移动、出行"]],"fq":"高频，口语里很常用。","me":"balade：想成 ballade（民谣）：悠闲的节奏。","tr":{"zh":"周日下午我们去海边逛逛。","fr":"Dimanche après-midi, nous allons nous balader au bord de la mer.","alt":"Dimanche après-midi, on va se balader au bord de la mer.","note":"aller + se + 动词原形：se 保持在动词原形前。"}},
 "Se marier": {"pos":"v. 代动词（pronominal），助动词 être；je me marie, nous nous marions","s":"结婚。se marier avec quelqu'un = 和某人结婚；se marier 单独使用也可以。marier quelqu'un = 为某人主持婚礼或把某人嫁出去（较少用）。名词是 le mariage（婚礼；婚姻）。","ipa":"[sə.ma.ʁje]","ph":"se 读弱 e [sə]；ma [ma]；ri 与 e 连成 [ʁje]。","pi":"代动词，要带 se：ils se marient。结婚用 se marier avec，不是 marier avec。复合时态：Ils se sont mariés。","et":"拉丁语 maritare，来自 maritus（丈夫、已婚的）。同族：mari（丈夫）、mariage。","ex":[["Ils vont se marier.","他们要结婚了。"],["Elle s'est mariée avec un Français.","她嫁给了一位法国人。"],["Je me marie en juin.","我六月结婚。"]],"co":[["se marier avec quelqu'un","和某人结婚"],["se marier en + 月份","某月结婚"],["le mariage","婚礼；婚姻"],["être marié(e)","已婚"]],"sy":[["épouser","courant","娶、嫁（直接接人）"],["divorcer","courant","反义：离婚"]],"fq":"高频，日常常用。","me":"mari（丈夫）-er：把自己变成「有丈夫」的状态。","tr":{"zh":"我姐姐明年六月结婚。","fr":"Ma sœur se marie en juin prochain.","alt":"Ma sœur va se marier en juin de l'année prochaine.","note":"se marier 用现在时也可表示近期将来。"}},
 "Venir": {"pos":"v. 动词，不规则，助动词 être；je viens, nous venons, ils viennent，过去分词 venu","s":"来。venir à / de + 地点；venir de + 动词原形 = 刚刚做完（近期过去）：Je viens de manger。venir + 动词原形 = 来做某事：Viens voir。","ipa":"[və.niʁ]","ph":"ve 读弱 e [və]；n [n]；-ir 读 [iʁ]。","pi":"助动词用 être：il est venu。venir de + 原形表示「刚刚」，不是「来自」。il vient / ils viennent 的重音要小心。","et":"拉丁语 venire（来）。同族：devenir, revenir, avenir, convenir。","ex":[["Tu peux venir avec moi.","你可以和我一起来。"],["Je viens de manger.","我刚吃完。"],["Elle vient de Chine.","她来自中国。"]],"co":[["venir de + 地点","来自……"],["venir de + 不定式","刚刚……"],["venir chercher quelqu'un","来接某人"],["Viens ici !","过来！"]],"sy":[["arriver","courant","到达"],["aller","courant","反义：去"],["passer","courant","顺便来"]],"fq":"极高频，日常常用。","me":"venir ← venue（场地）：事情发生的地方，人「来」那里。","tr":{"zh":"你今晚想来我家吗？","fr":"Tu veux venir chez moi ce soir ?","alt":"Tu viens chez moi ce soir ?","note":"venir chez + 人：到某人家来。"}},
 "Aquatique": {"pos":"adj. 形容词，阴阳同形（aquatique），复数 aquatiques","s":"水上的；水的；水中的。parc aquatique = 水上乐园；sport aquatique = 水上运动；animal aquatique = 水生动物。阴阳同形，不加 e。","ipa":"[a.kwa.tik]","ph":"a [a]；qu 在这里读 [kw]；a [a]；-tique 读 [tik]。","pi":"qu 通常读 [k]，但在 aqua- 里读 [kw]。重音落在最后一个音节。","et":"拉丁语 aquaticus，来自 aqua（水）。同族：aquarium, aquarelle。","ex":[["Nous allons dans un parc aquatique.","我们去水上乐园。"],["La natation est un sport aquatique.","游泳是一项水上运动。"],["La grenouille est un animal aquatique.","青蛙是水生动物。"]],"co":[["un parc aquatique","水上乐园"],["un sport aquatique","水上运动"],["un animal aquatique","水生动物"],["une plante aquatique","水生植物"]],"sy":[["marin","courant","海的"],["nautique","courant","航海的；水上的"],["terrestre","courant","反义：陆地的"]],"fq":"中频，旅游与自然话题里常见。","me":"aqua 就是「水」：aquarium 水族馆，aquatique 水中的。","tr":{"zh":"孩子们喜欢水上乐园。","fr":"Les enfants adorent le parc aquatique.","alt":"Les enfants aiment beaucoup le parc aquatique.","note":"aquatique 阴阳同形，修饰阳性 parc 时不加 e。"}},
 "Artistique": {"pos":"adj. 形容词，阴阳同形（artistique），复数 artistiques","s":"艺术的；有艺术性的。un talent artistique = 艺术天赋；une activité artistique = 艺术活动。阴阳同形，不加 e。","ipa":"[aʁ.tis.tik]","ph":"ar [aʁ]；tis [tis]；-tique 读 [tik]。","pi":"qu 在这里读 [k]：-tique 读 [tik]。重音在最后一个音节。","et":"来自 artiste + -ique，源头是拉丁语 ars（技艺、艺术）。同族：art, artiste。","ex":[["Elle a un talent artistique.","她有艺术天赋。"],["C'est un projet artistique.","这是一个艺术项目。"],["Il suit des cours artistiques.","他在上艺术课。"]],"co":[["un talent artistique","艺术天赋"],["une activité artistique","艺术活动"],["la direction artistique","艺术指导"],["un projet artistique","艺术项目"]],"sy":[["créatif / créative","courant","有创造力的"],["esthétique","soutenu","美学的、有美感的"]],"fq":"中频。","me":"art + iste + ique：和艺术有关的。","tr":{"zh":"她很有艺术天赋。","fr":"Elle a beaucoup de talent artistique.","alt":"Elle est très douée pour l'art.","note":"avoir du talent：有天分。"}},
 "Célibataire": {"pos":"adj. 形容词，阴阳同形（célibataire），复数 célibataires；也可作名词 un(e) célibataire","s":"单身的；未婚的。指目前没有结婚或没有伴侣。名词 un célibataire = 单身者。注意：不是「禁欲」。","ipa":"[se.li.ba.tɛʁ]","ph":"c 在 é 前读 [s]；é [e]；-aire 读 [ɛʁ]，r 要发。","pi":"c 读 [s]；结尾 -aire 读 [ɛʁ]，不是 [e]。阴阳同形。","et":"来自拉丁语 caelibatus，与 caelebs（未婚的）有关。同族：célibat（单身状态）。","ex":[["Il est célibataire.","他是单身。"],["Elle est célibataire depuis deux ans.","她单身两年了。"],["Un célibataire vit seul.","单身者独自生活。"]],"co":[["être célibataire","单身"],["rester célibataire","保持单身"],["un jeune célibataire","年轻单身者"],["le célibat","单身状态"]],"sy":[["seul(e)","courant","独自的（语气更宽泛）"],["marié(e)","courant","反义：已婚"],["libre","familier","（口语）没有伴"]],"fq":"高频，说个人状况时常用。","me":"célibat 里有 cél（天空）的错觉，其实意为「没有配偶」。","tr":{"zh":"我现在是单身。","fr":"Je suis célibataire en ce moment.","alt":"Je suis célibataire pour le moment.","note":"célibataire 阴阳同形，女生也说 Je suis célibataire。"}},
 "Connu(e)": {"pos":"adj. 形容词，connu（阳）/ connue（阴），复数 connus / connues","s":"知名的；有名的；已知的。是 connaître 的过去分词，作形容词用。Cet acteur est très connu = 这位演员很有名。connu de tous = 众所周知。","ipa":"[kɔ.ny]","ph":"c 读 [k]；on 在这里读 [ɔ] + n，注意 nn：con-nu 读 [kɔ.ny]；u 读 [y]。","pi":"阳性阴性读音相同；拼写阴性加 e：connue。u 读 [y]，不是 [u]。","et":"connaître（认识）的过去分词，拉丁语 cognoscere。同族：connaissance, reconnu。","ex":[["Cet acteur est très connu.","这位演员很有名。"],["Cette chanson est connue dans le monde entier.","这首歌全世界都知道。"],["Le problème est connu.","这个问题是已知的。"]],"co":[["très connu","非常有名"],["connu de tous","众所周知"],["bien connu","众所周知的"],["un fait connu","已知的事实"]],"sy":[["célèbre","courant","著名的"],["populaire","courant","受欢迎的"],["inconnu","courant","反义：不知名的"]],"fq":"高频，日常常用。","me":"connu = connaître 的「已被认识」形式。","tr":{"zh":"这家餐厅在当地很有名。","fr":"Ce restaurant est très connu dans la région.","alt":"Ce restaurant est très réputé par ici.","note":"connu 与名词 restaurant 配合，阳性不加 e。"}},
 "Culturel(le)": {"pos":"adj. 形容词，culturel（阳）/ culturelle（阴），复数 culturels / culturelles","s":"文化的；与文化有关的。un événement culturel = 文化活动；un centre culturel = 文化中心；la vie culturelle = 文化生活。","ipa":"[kyl.ty.ʁɛl]","ph":"c 读 [k]；u 读 [y]；-el 读 [ɛl]；阴性 -elle 读音相同。","pi":"u 读 [y]；阴性 -elle 双 l，读音与阳性相同。","et":"来自 culture + -el；culture 源自拉丁语 cultura（耕种、培养），来自 colere。","ex":[["C'est un événement culturel.","这是一场文化活动。"],["Il y a un centre culturel près d'ici.","这附近有一个文化中心。"],["La vie culturelle est riche à Paris.","巴黎的文化生活很丰富。"]],"co":[["un événement culturel","文化活动"],["un centre culturel","文化中心"],["la vie culturelle","文化生活"],["un échange culturel","文化交流"]],"sy":[["artistique","courant","艺术的"],["intellectuel","courant","智力的、知识的"]],"fq":"中频。","me":"culture + -el：与文化有关。","tr":{"zh":"这个城市有很多文化活动。","fr":"Cette ville a beaucoup d'activités culturelles.","alt":"Dans cette ville, il y a plein d'événements culturels.","note":"culturelles 与阴性复数 activités 配合。"}},
 "Francophone": {"pos":"adj. 形容词，阴阳同形（francophone），复数 francophones；也可作名词 un(e) francophone","s":"说法语的；法语区的。un pays francophone = 讲法语的国家；les francophones = 说法语的人。不一定指法国，也包括比利时、瑞士、加拿大魁北克、非洲部分国家等。","ipa":"[fʁɑ̃.kɔ.fɔn]","ph":"fr [fʁ]；an 读鼻化音 [ɑ̃]；c 在 o 前读 [k]；ph 读 [f]。","pi":"ph 读 [f]，不是 [p]。别把 francophone 和 français 混为一谈。","et":"franco-（法国的、法语的）+ -phone（希腊语 phônê，声音、语言）。","ex":[["C'est un pays francophone.","这是一个讲法语的国家。"],["Elle travaille dans un journal francophone.","她在一家法语报纸工作。"],["Les francophones sont nombreux en Afrique.","非洲有很多说法语的人。"]],"co":[["un pays francophone","讲法语的国家"],["le monde francophone","法语世界"],["la francophonie","法语国家共同体"],["un francophone","说法语的人"]],"sy":[["français","courant","法国的、法语的（范围较窄）"],["anglophone","courant","对照：说英语的"]],"fq":"中频，谈语言与文化时常见。","me":"franco + phone：像 telephone 的 phone，指「声音、语言」。","tr":{"zh":"加拿大魁北克是说法语的地区。","fr":"Le Québec est une région francophone du Canada.","alt":"Au Canada, le Québec est francophone.","note":"francophone 阴阳同形，修饰阴性 région 不加 e。"}},
 "Gratuit(e)": {"pos":"adj. 形容词，gratuit（阳）/ gratuite（阴），复数 gratuits / gratuites","s":"免费的。L'entrée est gratuite = 入场免费。注意：「免费」用 gratuit，不是 libre。","ipa":"[ɡʁa.tɥi]","ph":"gr [ɡʁ]；ui 读半元音加 [i]：[tɥi]；阳性结尾 t 不发音，阴性 gratuite 读 [ɡʁa.tɥit]。","pi":"阳性 gratuit 的 t 不发音，阴性 gratuite 要发 [t]。别和 libre（自由；空闲）混淆。","et":"拉丁语 gratuitus（无偿的、自发的），来自 gratus（令人愉快的）。同族：gratis, gratitude。","ex":[["L'entrée est gratuite.","入场免费。"],["Le musée est gratuit le dimanche.","博物馆周日免费。"],["C'est un cours gratuit.","这是一门免费课程。"]],"co":[["l'entrée est gratuite","入场免费"],["un service gratuit","免费服务"],["gratuit pour les enfants","儿童免费"],["gratuitement","免费地"]],"sy":[["gratis","familier","免费（口语）"],["payant","courant","反义：收费的"],["libre","courant","自由的；空闲的（不同义）"]],"fq":"高频，日常常用。","me":"gratuit ← gratis ← gratitude：不用付钱，只要说声谢谢。","tr":{"zh":"周日博物馆免费。","fr":"Le musée est gratuit le dimanche.","alt":"Le dimanche, l'entrée du musée est gratuite.","note":"le dimanche 表示「每个周日」。"}},
 "International(e)": {"pos":"adj. 形容词，international（阳）/ internationale（阴），复数 internationaux / internationales","s":"国际的。une école internationale = 国际学校；un vol international = 国际航班。阳性复数是 internationaux。","ipa":"[ɛ̃.tɛʁ.na.sjɔ.nal]","ph":"in 读鼻化音 [ɛ̃]；ter [tɛʁ]；ti 读 [sj]：-tion 读 [sjɔ̃]；阴性 -ale 读 [al]。","pi":"-tio- 里 t 读 [s]。阳性复数 internationaux，不是 internationals。","et":"inter-（之间）+ national；national 来自拉丁语 natio（民族），同族：nation, naître。","ex":[["C'est une école internationale.","这是一所国际学校。"],["J'ai un vol international.","我有一趟国际航班。"],["Ce sont des étudiants internationaux.","他们是国际学生。"]],"co":[["une école internationale","国际学校"],["un vol international","国际航班"],["les relations internationales","国际关系"],["un événement international","国际活动"]],"sy":[["mondial","courant","世界的"],["national","courant","反义：国内的"]],"fq":"高频，日常与新闻中常用。","me":"inter + national：国与国「之间」的。","tr":{"zh":"我们有很多国际学生。","fr":"Nous avons beaucoup d'étudiants internationaux.","alt":"Il y a beaucoup d'étudiants internationaux chez nous.","note":"阳性复数 internationaux，与 étudiants 配合。"}},
 "Libre": {"pos":"adj. 形容词，阴阳同形（libre），复数 libres","s":"空闲的；自由的；没人占用的。Tu es libre ce soir ? = 你今晚有空吗？Cette place est libre = 这个座位没人。libre de + 动词原形 = 可以自由地做。注意：「免费」不用 libre，要用 gratuit。","ipa":"[libʁ]","ph":"l [l]；i [i]；br [bʁ]，结尾 e 不发音。","pi":"别把 libre 当成「免费」。libre 和 librairie（书店）不同。","et":"拉丁语 liber（自由的）。同族：liberté, libérer。","ex":[["Tu es libre ce soir ?","你今晚有空吗？"],["Cette table est libre ?","这张桌子有人吗？"],["Vous êtes libre de choisir.","您可以自由选择。"]],"co":[["être libre ce soir","今晚有空"],["une place libre","空位"],["libre de + 动词原形","自由地……"],["le temps libre","空闲时间"]],"sy":[["disponible","courant","有空的、可用的"],["gratuit","courant","免费的（不同义）"],["occupé","courant","反义：忙的；占用的"]],"fq":"极高频，日常常用。","me":"libre ← liberté：自由，也就是有空。","tr":{"zh":"你周六有空吗？","fr":"Tu es libre samedi ?","alt":"T'es dispo samedi ?","note":"Tu es libre ? 问对方是否有空，也可说 disponible。"}},
 "Personnel(le)": {"pos":"adj. 形容词，personnel（阳）/ personnelle（阴），复数 personnels / personnelles","s":"个人的；私人的。un objet personnel = 个人物品；une opinion personnelle = 个人看法。注意：le personnel 作名词，指「员工；全体职员」。","ipa":"[pɛʁ.sɔ.nɛl]","ph":"per [pɛʁ]；son [sɔ]；nel [nɛl]；nn 读一个 [n]。","pi":"拼写有 nn：personnel，别写成 personel。阴性 personnelle 读音相同。","et":"来自拉丁语 personalis，源自 persona（面具；人）。同族：personne, personnage。","ex":[["C'est un objet personnel.","这是个人物品。"],["C'est mon opinion personnelle.","这是我个人的看法。"],["Le personnel est très aimable.","员工们很友好。"]],"co":[["un objet personnel","个人物品"],["une opinion personnelle","个人看法"],["le personnel","员工、全体人员"],["à titre personnel","就个人而言"]],"sy":[["privé","courant","私人的"],["individuel","courant","个人的"],["public","courant","反义：公共的"]],"fq":"高频，日常常用。","me":"personne + -el：属于某个「人」的。","tr":{"zh":"请不要碰我的个人物品。","fr":"Ne touchez pas mes objets personnels, s'il vous plaît.","alt":"Ne touchez pas à mes affaires personnelles, s'il vous plaît.","note":"toucher + 直接宾语；toucher à 也可，意思略不同。"}},
 "Premier / Première": {"pos":"adj. 形容词，premier（阳）/ première（阴），复数 premiers / premières；也可作名词","s":"第一的；首要的；最初的。放在名词前：le premier jour, la première fois。le premier mai = 五月一日（日期用序数）。也可作名词：le premier = 第一个。","ipa":"[pʁə.mje] / [pʁə.mjɛʁ]","ph":"pr [pʁ]；e 读弱 e [ə]；mi 与 e 连成 [mje]；阴性 -ière 读 [jɛʁ]。","pi":"阳性 premier 的 r 不发音，阴性 première 要发。日期里「一号」用 premier，其他日子用基数词。","et":"拉丁语 primarius（头等的、第一位的），来自 primus（第一）。同族：primaire, prime。","ex":[["C'est ma première fois.","这是我的第一次。"],["Le premier jour a été difficile.","第一天很难。"],["Nous sommes le premier mai.","今天是五月一日。"]],"co":[["la première fois","第一次"],["le premier jour","第一天"],["le premier mai","五月一日"],["en premier","首先；最先"]],"sy":[["initial","soutenu","最初的"],["principal","courant","主要的"],["dernier","courant","反义：最后的"]],"fq":"极高频，日常常用。","me":"prem- 像 premier ministre（首相）：排在第一位的。","tr":{"zh":"这是我第一次来法国。","fr":"C'est ma première fois en France.","alt":"C'est la première fois que je viens en France.","note":"première 与阴性名词 fois 配合。"}},
 "Professionnel(le)": {"pos":"adj. 形容词，professionnel（阳）/ professionnelle（阴），复数 professionnels / professionnelles；也可作名词","s":"职业的；专业的；工作上的。un rendez-vous professionnel = 工作约会；la vie professionnelle = 职业生涯。也可作名词：un professionnel = 专业人士。","ipa":"[pʁɔ.fɛ.sjɔ.nɛl]","ph":"pr [pʁ]；o [ɔ]；ss 读 [s]；-ionnel 读 [jɔnɛl]。","pi":"拼写有 nn：professionnel。-ss- 读 [s]。注意与 professeur 区分。","et":"来自 profession（职业），拉丁语 professio（公开声明；职业）。同族：professeur, profession。","ex":[["J'ai un rendez-vous professionnel.","我有一个工作上的约会。"],["C'est un musicien professionnel.","他是职业音乐家。"],["Elle a une grande expérience professionnelle.","她有丰富的工作经验。"]],"co":[["un rendez-vous professionnel","工作约会"],["la vie professionnelle","职业生涯"],["l'expérience professionnelle","工作经验"],["un professionnel","专业人士"]],"sy":[["pro","familier","（口语）专业的"],["amateur","courant","反义：业余的"],["personnel","courant","反义：个人的"]],"fq":"高频，工作话题里常见。","me":"profession + -nel：与「职业」相关的。","tr":{"zh":"我下周有一个工作约会。","fr":"J'ai un rendez-vous professionnel la semaine prochaine.","alt":"J'ai un rendez-vous de travail la semaine prochaine.","note":"professionnel 与阳性名词 rendez-vous 配合。"}},
 "Spécial(e)": {"pos":"adj. 形容词，spécial（阳）/ spéciale（阴），复数 spéciaux / spéciales","s":"特别的；特殊的。un jour spécial = 特别的一天。有时也带「古怪的」意思：口语里 Il est un peu spécial = 他有点怪。","ipa":"[spe.sjal]","ph":"sp [sp]；é [e]；c 在 i 前读 [s]；-ial 读 [jal]。","pi":"阳性复数是 spéciaux，不是 spécials。拼写有 é，别漏。","et":"拉丁语 specialis，来自 species（种类、外观）。同族：spécialité, spécialiste。","ex":[["C'est un jour spécial.","这是特别的一天。"],["Il est un peu spécial.","他有点特别（怪）。"],["Ce sont des offres spéciales.","这些是特价优惠。"]],"co":[["un jour spécial","特别的一天"],["une occasion spéciale","特殊场合"],["un prix spécial","特价"],["rien de spécial","没什么特别的"]],"sy":[["particulier","courant","特别的、特殊的"],["exceptionnel","courant","非凡的"],["ordinaire","courant","反义：普通的"]],"fq":"高频，日常常用。","me":"spécial ← species（种类）：与众不同的一类。","tr":{"zh":"今天对我来说是特别的一天。","fr":"Aujourd'hui est un jour spécial pour moi.","alt":"C'est un jour spécial pour moi, aujourd'hui.","note":"pour moi：对我来说。"}},
 "Sportif / Sportive": {"pos":"adj. 形容词，sportif（阳）/ sportive（阴），复数 sportifs / sportives；也可作名词","s":"爱运动的；运动的；体育的。Elle est très sportive = 她很爱运动。也指「体育的」：une activité sportive。名词 un sportif = 运动员，运动爱好者。","ipa":"[spɔʁ.tif] / [spɔʁ.tiv]","ph":"sp [sp]；or [ɔʁ]；ti [ti]；f 读 [f]；阴性变 v：[tiv]。","pi":"阳性 f，阴性 v：sportif / sportive。sp 开头不要在前面加 e。","et":"来自 sport + -if；sport 借自英语（英语又来自古法语 desport，意为消遣）。","ex":[["Elle est très sportive.","她非常爱运动。"],["Mon frère est sportif.","我哥哥爱运动。"],["Il fait une activité sportive tous les jours.","他每天都做运动。"]],"co":[["être sportif / sportive","爱运动"],["une activité sportive","体育活动"],["un événement sportif","体育赛事"],["un sportif de haut niveau","高水平运动员"]],"sy":[["athlétique","soutenu","体格健壮的"],["actif","courant","活跃的"],["sédentaire","courant","反义：久坐不动的"]],"fq":"高频，日常常用。","me":"sport + -if：喜欢 sport 的人。","tr":{"zh":"我姐姐非常爱运动。","fr":"Ma sœur est très sportive.","alt":"Ma sœur adore le sport, elle est très sportive.","note":"阴性 sportive，与 sœur 配合。"}},
 "Encore": {"pos":"adv. 副词","s":"再；还；仍然。三种常见用法：1）再一次（Encore une fois）；2）还有更多（Encore du gâteau ?）；3）仍然、还（Il dort encore）。ne… pas encore = 还没有。","ipa":"[ɑ̃.kɔʁ]","ph":"en 读鼻化音 [ɑ̃]；c 在 o 前读 [k]；or [ɔʁ]；结尾 e 不发音。","pi":"encore 不是 [ɑ̃.ko]，结尾 r 要发。ne… pas encore（还没）与 toujours（仍然）不同。","et":"一般认为来自拉丁语 hanc horam（此刻）。含义从「到这一刻为止」发展而来。","ex":[["Je veux encore du gâteau.","我还想吃蛋糕。"],["Il dort encore.","他还在睡。"],["Je n'ai pas encore mangé.","我还没吃饭。"]],"co":[["encore une fois","再一次"],["pas encore","还没有"],["encore du / de la + 名词","再来一点……"],["encore plus","更多"]],"sy":[["de nouveau","courant","再次"],["toujours","courant","仍然（不同用法）"],["déjà","courant","反义：已经"]],"fq":"极高频，日常常用。","me":"en-core：「还有一点」，可以再多要一次。","tr":{"zh":"我还想再看一遍这部电影。","fr":"Je veux voir ce film encore une fois.","alt":"J'ai envie de revoir ce film.","note":"encore une fois：再一次。"}},
 "Longtemps": {"pos":"adv. 副词，不变","s":"很久；长时间。长时间的意思，可以指过去、现在或将来：J'attends depuis longtemps。通常用在动词后面。pas longtemps = 没多久。","ipa":"[lɔ̃.tɑ̃]","ph":"lon 读鼻化音 [lɔ̃]；g 不发音；temps 读 [tɑ̃]，ps 不发音。","pi":"g 与 ps 都不发音：longtemps 读 [lɔ̃.tɑ̃]。别写成 long temps（一个词）。","et":"由 long（长）+ temps（时间）构成，原意「长时间」。","ex":[["J'attends depuis longtemps.","我等了很久。"],["Il n'habite pas ici depuis longtemps.","他住在这里没多久。"],["Ça dure longtemps.","这要持续很久。"]],"co":[["depuis longtemps","很久以来"],["pas longtemps","没多久"],["longtemps après / avant","很久以后 / 以前"],["pendant longtemps","很长时间"]],"sy":[["longuement","soutenu","长时间地（强调过程）"],["peu de temps","courant","反义：短时间"]],"fq":"高频，日常常用。","me":"long + temps：「长」的「时间」，合成一个词。","tr":{"zh":"我在这里等了很久。","fr":"J'attends ici depuis longtemps.","alt":"Ça fait longtemps que j'attends ici.","note":"depuis longtemps：表示从很久前持续到现在。"}},
 "Toujours": {"pos":"adv. 副词","s":"总是；一直；仍然。两层意思：1）总是（Il est toujours en retard）；2）仍然、还在（Tu habites toujours à Lyon ?）。toujours 与 encore 在「仍然」义上相近，口语里常换用。","ipa":"[tu.ʒuʁ]","ph":"t [t]；ou [u]；j [ʒ]；ou [u]；r 要发，结尾 s 不发音。","pi":"结尾的 s 不发音，r 要发：[tu.ʒuʁ]。别和 tout le temps 混淆。","et":"由 tous（所有）+ jours（日子）构成，原意「每一天」。","ex":[["Il est toujours en retard.","他总是迟到。"],["Tu habites toujours à Lyon ?","你还住在里昂吗？"],["Je t'aimerai toujours.","我会永远爱你。"]],"co":[["comme toujours","和往常一样"],["pour toujours","永远"],["toujours pas","仍然没有"],["depuis toujours","一直以来"]],"sy":[["tout le temps","courant","一直、老是"],["sans cesse","soutenu","不停地"],["jamais","courant","反义：从不"]],"fq":"极高频，日常常用。","me":"tous + jours：每一天，所以是「总是」。","tr":{"zh":"他总是很早起床。","fr":"Il se lève toujours très tôt.","alt":"Il se lève toujours de bonne heure.","note":"toujours 放在助动词或变位动词之后。"}},
 "Personne": {"pos":"pron. 不定代词（常与 ne 搭配），阳性单数；作名词时 une personne 为 n.f.","s":"没有人；谁也不。常与 ne 搭配：Je ne vois personne。单独回答也可：Qui est là ? — Personne. 注意另一个同形词 la personne = 人。","ipa":"[pɛʁ.sɔn]","ph":"per [pɛʁ]；s 读 [s]；on 在 nn 前读 [ɔ]；nn 读一个 [n]，结尾 e 不发音。","pi":"ne… personne 中，ne 与 personne 都要出现；单独回答时只说 personne。别把代词 personne 与名词 une personne 搞混。","et":"拉丁语 persona（面具；角色；人）。作为否定代词的用法，从「没有一个人」演变而来。","ex":[["Il n'y a personne.","没有人在。"],["Je ne connais personne ici.","我在这里谁也不认识。"],["Qui est là ? — Personne.","谁在那儿？——没人。"]],"co":[["ne… personne","没有人"],["personne d'autre","没有别人"],["Personne ne sait.","没人知道。"],["avant personne","（不常用）"]],"sy":[["nul","soutenu","没有任何人"],["quelqu'un","courant","反义：某人"],["tout le monde","courant","反义：所有人"]],"fq":"极高频，日常常用。","me":"personne = 没有一个 persona（人）。","tr":{"zh":"这里没有人。","fr":"Il n'y a personne ici.","alt":"Il n'y a personne.","note":"personne 作主语时：Personne ne vient；ne 放动词前。"}},
 "Quelqu'un": {"pos":"pron. 不定代词（阳性单数，无复数）","s":"某人；有人。指不确定的一个人。后面接形容词时用 quelqu'un de + 形容词（阳性不变）：quelqu'un de gentil。否定时用 personne，不用 quelqu'un。","ipa":"[kɛl.kœ̃]","ph":"qu [k]；e 读 [ɛ]；un 读鼻化元音 [œ̃]；整体是两个音节。","pi":"拼写里的撇号别漏掉：quelqu'un，不是 quelqu un。un 的鼻音不要读成 [ɑ̃] 或 [ɔ̃]。","et":"quelque + un，字面是「某一个」。","ex":[["Il y a quelqu'un à la porte.","门口有人。"],["Je cherche quelqu'un de sérieux.","我在找一个靠谱的人。"],["Quelqu'un a appelé ce matin.","今早有人打过电话。"]],"co":[["quelqu'un d'autre","别的人"],["quelqu'un de gentil","一个友善的人"],["C'est quelqu'un !","他可是个人物！"]],"sy":[["une personne","courant","一个人；名词，阴性"],["personne","courant","没有人（反义，要配 ne）"]],"fq":"极高频，日常常用。","me":"quelque + un：「某一个」，所以动词用单数。","tr":{"zh":"有人在敲门。","fr":"Quelqu'un frappe à la porte.","alt":"Y a quelqu'un qui frappe à la porte.","note":"quelqu'un 后动词用第三人称单数。"}},
 "Quelque chose": {"pos":"pron. 不定代词（阳性单数）","s":"某事；某物；什么东西。虽然 chose 是阴性，但 quelque chose 作阳性处理：quelque chose de bon（不是 bonne）。","ipa":"[kɛlk.ʃoz]","ph":"quelque 读 [kɛlk]，结尾的 e 不发音；chose 的 ch 读 [ʃ]，o 读 [o]，s 读 [z]。","pi":"chose 是阴性，但搭配形容词时用阳性 + de：quelque chose de beau。ch 是 [ʃ]，不是 [tʃ] 也不是 [k]。","et":"quelque（一些）+ chose（事物，来自拉丁语 causa）。","ex":[["J'ai quelque chose pour toi.","我有东西给你。"],["Tu veux boire quelque chose ?","你想喝点什么吗？"],["Il y a quelque chose d'étrange.","有点奇怪。"]],"co":[["quelque chose de + 形容词","某种……的东西"],["quelque chose à boire / à manger","有点喝的 / 吃的"],["Il y a quelque chose qui ne va pas.","有什么不对劲。"]],"sy":[["un truc","familier","东西，玩意儿"],["rien","courant","什么都没有（反义，要配 ne）"]],"fq":"极高频，日常常用。","me":"quelque chose de + 阳性形容词，记住这个固定格式。","tr":{"zh":"你想吃点什么吗？","fr":"Tu veux manger quelque chose ?","alt":"T'as envie de manger un truc ?","note":"quelque chose 作直接宾语放在动词后。"}},
 "Rien": {"pos":"pron. 否定不定代词（常配 ne）","s":"什么都没有；没什么。通常和 ne 一起用：Je ne vois rien。口语里 ne 常省略。单独回答时 Rien. 就是「没什么」。De rien = 不客气。","ipa":"[ʁjɛ̃]","ph":"r 是小舌音 [ʁ]；ien 读 [jɛ̃]；结尾 n 不发音，只留鼻化元音。","pi":"n 不发音。ien 是 [jɛ̃]，不是 [jɛn]。别忘了 ne：Je ne mange rien。","et":"来自拉丁语 rem（res「事物」的宾格），原意是「事物」，后来在否定句中才有「没有」之义。","ex":[["Je ne vois rien.","我什么也看不见。"],["Il n'y a rien dans le frigo.","冰箱里什么都没有。"],["Merci. — De rien !","谢谢。——不客气！"]],"co":[["ne… rien","什么都不……"],["de rien","不客气"],["rien du tout","完全没有"],["rien d'autre","没有别的"]],"sy":[["nul","soutenu","无；也可作形容词"],["pas grand-chose","courant","没什么大不了的东西"]],"fq":"极高频，日常常用。","me":"Rien 听起来像「里昂」[ʁjɛ̃]：什么都没有。","tr":{"zh":"我今天什么都没吃。","fr":"Je n'ai rien mangé aujourd'hui.","alt":"J'ai rien mangé aujourd'hui.","note":"复合时态中 rien 放在助动词和过去分词之间。"}},
 "Depuis": {"pos":"prép. 介词","s":"自从……；已经……（时间）。表示一个从过去开始、至今还在持续的动作，动词用现在时：J'habite ici depuis un an（我在这住了一年了，现在还住）。可接时间点（depuis 2020）或一段时间（depuis trois jours）。","ipa":"[də.pɥi]","ph":"de 弱读 [də]；p [p]；ui 是半元音加元音 [ɥi]，嘴唇先圆后展；s 不发音。","pi":"结尾的 s 不发音。ui 是 [ɥi]，不是 [wi]。持续到现在的动作用现在时，不要用复合过去时。","et":"de + puis（puis 来自拉丁语 postea，「之后」）。","ex":[["J'habite ici depuis un an.","我在这里住了一年了。"],["Il pleut depuis ce matin.","从今早起就一直在下雨。"],["Depuis quand tu apprends le français ?","你学法语学多久了？"]],"co":[["depuis + 一段时间 / 时间点","自从……；有……之久"],["depuis quand ?","从什么时候起？多久了？"],["depuis toujours","一直以来"],["depuis que + 从句","自从……以来"]],"sy":[["il y a","courant","……以前（指过去的时间点，不持续）"],["pendant","courant","在……期间（时间段内的动作，常已结束）"]],"fq":"极高频，日常常用。","me":"depuis = 从过去「出发」一直走到现在。","tr":{"zh":"我学法语已经两年了。","fr":"J'apprends le français depuis deux ans.","alt":"Ça fait deux ans que j'apprends le français.","note":"depuis 后用现在时表示持续至今。"}},
 "Pendant": {"pos":"prép. 介词","s":"在……期间；……的时候。指动作发生的一段时间，也可指持续了多久：J'ai dormi pendant deux heures。后面常接 le / la / mon + 名词，或直接接时间长度。","ipa":"[pɑ̃.dɑ̃]","ph":"en 和 an 都读鼻化元音 [ɑ̃]；d 要读出来；结尾 t 不发音。","pi":"结尾 t 不发音；两个鼻音相同，别读成 [pɛ̃.dɛ̃]。和 depuis 区分：pendant 常用于已结束的一段时间，depuis 表示持续到现在。","et":"来自动词 pendre（悬挂）的现在分词 pendant，原意是「悬着、延续着」。","ex":[["Je dors pendant le voyage.","我在旅途中睡觉。"],["Nous avons attendu pendant une heure.","我们等了一个小时。"],["Pendant les vacances, je lis beaucoup.","假期里我读很多书。"]],"co":[["pendant + 时间长度","持续……（时间）"],["pendant que + 从句","当……的时候"],["pendant ce temps","与此同时"],["pendant longtemps","很长时间"]],"sy":[["durant","soutenu","在……期间，较书面"],["depuis","courant","自从（持续到现在）"]],"fq":"极高频，日常常用。","me":"pendre（悬挂）：事情「挂」在一段时间上。","tr":{"zh":"暑假期间我在餐厅工作。","fr":"Pendant les vacances d'été, je travaille dans un restaurant.","alt":"L'été, pendant les vacances, je bosse dans un resto.","note":"pendant 后常接定冠词 + 名词。"}},
 "Avoir un enfant": {"pos":"loc. 动词短语（avoir，复合时态用 avoir）","s":"生孩子；要孩子；有一个孩子。可指「怀孕并生下」：Elle va avoir un enfant（她要生孩子了）。也可指「有孩子」：Ils ont deux enfants。「想要孩子」说 vouloir un enfant。","ipa":"[a.vwaʁ œ̃ nɑ̃.fɑ̃]","ph":"avoir 读 [a.vwaʁ]，oi 是 [wa]；un 和 enfant 连诵：un_enfant 读 [œ̃.nɑ̃.fɑ̃]。","pi":"un enfant 要连诵，n 连到 enfant 上。enfant 的 t 不发音。enfant 阴阳同形，由冠词决定性别。","et":"avoir 来自拉丁语 habere；enfant 来自拉丁语 infans「不会说话的」。","ex":[["Nous allons avoir un enfant en septembre.","我们九月要有孩子了。"],["Ils veulent avoir un enfant.","他们想要一个孩子。"],["Elle a eu un enfant à trente ans.","她三十岁时生了孩子。"]],"co":[["avoir un enfant avec quelqu'un","和某人生孩子"],["attendre un enfant","怀孕（较委婉）"],["avoir des enfants","有孩子"],["un enfant unique","独生子女"]],"sy":[["attendre un bébé","courant","怀着孕，快有宝宝"],["accoucher","courant","分娩，生产（具体生的动作）"]],"fq":"高频，日常常用。","me":"avoir + un enfant：连诵 un_enfant 一口气读。","tr":{"zh":"他们明年想要个孩子。","fr":"Ils veulent avoir un enfant l'année prochaine.","alt":"Ils aimeraient avoir un enfant l'an prochain.","note":"vouloir + 不定式 avoir。"}},
 "En plein air": {"pos":"loc. 副词短语（不变）","s":"户外；露天。指在室外进行的活动：manger en plein air、sport en plein air。也可作定语：une piscine en plein air。plein air 也可作名词：le plein air，意为户外。","ipa":"[ɑ̃ plɛ.nɛʁ]","ph":"en 读 [ɑ̃]；plein 与 air 连诵，ein 去鼻化，读 [plɛ.nɛʁ]；air 读 [ɛʁ]。","pi":"plein air 常连读成 [plɛ.nɛʁ]，注意 plein 的鼻音会变化。air 是 [ɛʁ]，别读成英语的 air。ai 读 [ɛ]。","et":"plein（满的，拉丁语 plenus）+ air（空气，拉丁语 aer）：字面是「在满满的空气里」。","ex":[["Nous mangeons en plein air.","我们在户外吃饭。"],["Les enfants jouent en plein air.","孩子们在户外玩耍。"],["J'aime faire du sport en plein air.","我喜欢在户外运动。"]],"co":[["en plein air","在户外，露天"],["un concert en plein air","露天音乐会"],["une activité de plein air","户外活动"],["un marché en plein air","露天市场"]],"sy":[["dehors","courant","外面，户外（更口语、更宽泛）"],["à l'extérieur","courant","在外面，室外"]],"fq":"中高频，日常常用。","me":"plein（满）+ air：身边「全是」新鲜空气。","tr":{"zh":"天气好的时候我们在户外吃饭。","fr":"Quand il fait beau, nous mangeons en plein air.","alt":"Quand il fait beau, on mange dehors.","note":"en plein air 是固定短语，plein 不变。"}},
 "Être en couple": {"pos":"loc. 动词短语（être）","s":"在恋爱中；是一对；有伴侣。指处于稳定的恋爱或同居关系，不一定结婚。问法：Tu es en couple ? 单身是 être célibataire。","ipa":"[ɛtʁ ɑ̃ kupl]","ph":"être 读 [ɛtʁ]，结尾 e 不发音；en 读 [ɑ̃]；couple 的 ou 读 [u]，结尾 le 轻读 [pl]。","pi":"couple 是阳性：un couple。ou 是 [u]。en couple 里 en 和 couple 之间不连诵。","et":"couple 来自拉丁语 copula（连接、纽带）。","ex":[["Ils sont en couple.","他们是一对。"],["Tu es en couple en ce moment ?","你现在有对象吗？"],["Elle est en couple depuis trois ans.","她谈了三年恋爱了。"]],"co":[["vivre en couple","同居，共同生活"],["en couple avec quelqu'un","和某人在一起"],["un couple heureux","幸福的一对"],["séparés / célibataire","分手 / 单身"]],"sy":[["être ensemble","familier","在一起（口语）"],["sortir avec quelqu'un","familier","和某人交往"],["être célibataire","courant","单身（反义）"]],"fq":"中高频，日常常用。","me":"couple：两个人「连」在一起。","tr":{"zh":"你们在一起多久了？","fr":"Vous êtes en couple depuis combien de temps ?","alt":"Ça fait combien de temps que vous êtes ensemble ?","note":"depuis + 时间表示持续至今。"}},
 "Faire connaissance": {"pos":"loc. 动词短语（faire，复合时态用 avoir）","s":"结识；认识（一个人）。可用 faire connaissance avec + 人，或 faire la connaissance de + 人。互相认识：Nous faisons connaissance。Enchanté 是见面时的招呼。","ipa":"[fɛʁ kɔ.nɛ.sɑ̃s]","ph":"faire 读 [fɛʁ]，ai 是 [ɛ]；connaissance 里 on 之后 n 双写读 [ɔ.n]；ai [ɛ]，an [ɑ̃]，c 读 [s]。","pi":"connaissance 拼写难：双 n、双 s，其中 ai 不是 [e]。faire connaissance 里 connaissance 前无冠词；faire la connaissance de 才有 la。","et":"connaissance 来自动词 connaître（认识），拉丁语 cognoscere。","ex":[["Nous allons faire connaissance.","我们来认识一下吧。"],["J'ai fait connaissance avec ses parents.","我认识了他的父母。"],["Ravi de faire votre connaissance.","很高兴认识您。"]],"co":[["faire connaissance avec quelqu'un","结识某人"],["faire la connaissance de quelqu'un","认识某人（见面）"],["Enchanté(e) de faire votre connaissance.","很高兴认识您。"],["une vieille connaissance","老熟人"]],"sy":[["rencontrer","courant","遇见，见到（不一定深入认识）"],["se présenter","courant","自我介绍"]],"fq":"中高频，日常常用。","me":"faire（做）+ connaissance（认识）：「做出」一次相识。","tr":{"zh":"我昨天结识了新邻居。","fr":"Hier, j'ai fait connaissance avec mes nouveaux voisins.","alt":"Hier, j'ai rencontré mes nouveaux voisins.","note":"复合过去时用 avoir：j'ai fait。"}},
 "Il y a": {"pos":"loc. 介词短语 / 非人称动词表达（不变）","s":"两个常用义：1）后接时间表示「……以前」：il y a deux ans = 两年前；2）il y a + 名词 = 有……（存在）。表示「以前」时，用复合过去时或过去时，不是现在时。","ipa":"[il.i.a]","ph":"il 的 l 与 y 连读：[il.i.a]；y 读 [i]；有时口语省略为 [ja]（y a）。","pi":"il y a + 时间 = 以前；depuis + 时间 = 持续到现在。别混淆。表示「有」时，后面接复数名词仍用 il y a，不变：Il y a des chats。","et":"il + y（那里，拉丁语 ibi）+ a（avoir 的第三人称单数）：字面是「它在那里有」。","ex":[["J'ai étudié en Allemagne il y a deux ans.","我两年前在德国学习。"],["Il y a un chat sur le canapé.","沙发上有一只猫。"],["Il est parti il y a dix minutes.","他十分钟前走的。"]],"co":[["il y a + 时间","……以前"],["il y a longtemps","很久以前"],["Il y a quelqu'un ?","有人吗？"],["Qu'est-ce qu'il y a ?","怎么了？"]],"sy":[["depuis","courant","自从（持续到现在，对比项）"],["voilà","courant","就在……，……了（指示）"]],"fq":"极高频，日常常用。","me":"il y a deux ans：从现在往回「数」，是过去的一个点。","tr":{"zh":"我三年前搬到了这里。","fr":"J'ai déménagé ici il y a trois ans.","alt":"Ça fait trois ans que j'ai déménagé ici.","note":"il y a + 时间配过去时态。"}},
 "La \"French Touch\"": {"pos":"loc. 名词短语 n.f.（借自英语）","s":"法式风格；法式魅力。一指 20 世纪 90 年代法国电子音乐风潮（如 Daft Punk、Air）；现在也泛指法国人在时尚、设计、美食里那种独特的优雅和巧思。","ipa":"[fʁɛntʃ tœtʃ]","ph":"French 读 [fʁɛntʃ]，r 为法语小舌音；touch 读 [tœtʃ]，ou 读 [œ]，ch 读 [tʃ]。","pi":"这是英语借词，但读音是法语化的：touch 里的 ou 读 [œ]，不是 [tu]。词前用阴性冠词 la。","et":"借自英语 French touch（法国的一笔、风格）。","ex":[["J'aime la French Touch.","我喜欢法式风格。"],["Ce restaurant a la French Touch.","这家餐厅有法式风味。"],["La French Touch a fait danser le monde entier.","法式电子乐让全世界跳起舞来。"]],"co":[["la French Touch musicale","法式电子音乐风潮"],["avoir la French Touch","有法式味道"],["une touche française","法式的点缀（对应的法语）"]],"sy":[["le style français","courant","法国风格"],["le chic français","courant","法式优雅"]],"fq":"中低频，媒体和时尚领域常见。","me":"touch 在法语里读 [tœtʃ]，像「特去」。","tr":{"zh":"这件外套很有法式风格。","fr":"Ce manteau a vraiment la French Touch.","alt":"Ce manteau a un style bien français.","note":"avoir la French Touch：有……的味道。"}},
 "Prendre sa retraite": {"pos":"loc. 动词短语（prendre，复合时态用 avoir）","s":"退休。物主形容词随主语变化：je prends ma retraite, il prend sa retraite。也说 partir à la retraite。已经退休了用 être à la retraite。","ipa":"[pʁɑ̃dʁ sa ʁə.tʁɛt]","ph":"prendre 读 [pʁɑ̃dʁ]，en 的位置是 an [ɑ̃]，结尾 e 不发音；retraite 读 [ʁə.tʁɛt]，ai 是 [ɛ]，结尾 e 不发音。","pi":"物主词要和主语一致：je prends ma retraite，nous prenons notre retraite。retraite 是阴性。prendre 的 nous / vous / ils 变位有变化：nous prenons, ils prennent。","et":"retraite 是 retraire（后退）的名词，拉丁语 retrahere，原意「撤退」。","ex":[["Mon père va prendre sa retraite.","我爸爸快要退休了。"],["Elle a pris sa retraite à soixante ans.","她六十岁退休。"],["Je prendrai ma retraite dans cinq ans.","我五年后退休。"]],"co":[["partir à la retraite","退休"],["être à la retraite","已退休"],["la retraite anticipée","提前退休"],["un retraité / une retraitée","退休的人"]],"sy":[["partir à la retraite","courant","退休（同义）"],["cesser de travailler","soutenu","停止工作"]],"fq":"中频，日常常用。","me":"retraite = re（回）+ traite：从工作中「撤退」。","tr":{"zh":"我奶奶去年退休了。","fr":"Ma grand-mère a pris sa retraite l'année dernière.","alt":"Ma grand-mère est partie à la retraite l'an dernier.","note":"prendre sa retraite 的 sa 随主语变化。"}},
 "Prendre son temps": {"pos":"loc. 动词短语（prendre，复合时态用 avoir）","s":"慢慢来；不着急；花时间。鼓励别人时常说 Prends ton temps。物主词随主语变化：je prends mon temps, tu prends ton temps。","ipa":"[pʁɑ̃dʁ sɔ̃ tɑ̃]","ph":"prendre 读 [pʁɑ̃dʁ]；son 读 [sɔ̃]；temps 读 [tɑ̃]，p 和 s 都不发音。","pi":"temps 结尾的 p、s 都不发音。物主词要对应主语：Prends ton temps（对 tu）。temps 为阳性。","et":"prendre 来自拉丁语 prehendere；temps 来自拉丁语 tempus。","ex":[["Tu peux prendre ton temps.","你可以慢慢来。"],["Prenez votre temps, je ne suis pas pressé.","您慢慢来，我不急。"],["Il prend toujours son temps pour manger.","他吃饭总是慢慢地吃。"]],"co":[["Prends ton temps !","别着急！慢慢来！"],["prendre tout son temps","完全不赶时间"],["prendre le temps de + 不定式","抽出时间做……"],["ne pas être pressé","不着急"]],"sy":[["ne pas se presser","courant","不要着急"],["flâner","courant","闲逛"],["se dépêcher","courant","赶快（反义）"]],"fq":"高频，日常常用。","me":"prendre son temps：像取东西一样「拿走」自己的时间。","tr":{"zh":"别着急，慢慢选。","fr":"Ne vous pressez pas, prenez votre temps pour choisir.","alt":"Pas de stress, prends ton temps pour choisir.","note":"对 vous 用 votre，对 tu 用 ton。"}},
 "Se changer les idées": {"pos":"loc. 代动词短语（se changer，复合时态用 être）","s":"散散心；换换脑子；转移一下注意力。去做别的事，让自己别再想烦心事：J'ai besoin de me changer les idées。les idées 是直接宾语，所以复合过去时中过去分词不变：Je me suis changé les idées。","ipa":"[sə ʃɑ̃.ʒe le.z‿i.de]","ph":"se 读 [sə]；changer 读 [ʃɑ̃.ʒe]，ch 是 [ʃ]，g 在 e 前读 [ʒ]；les idées 连诵 [le.zi.de]。","pi":"changer 要改变：nous nous changeons（保留 e）。les idées 在 les 与 idées 之间要连诵 z。代词随主语变：je me, tu te, nous nous。","et":"changer 来自晚期拉丁语 cambiare；idée 来自希腊语 idea「形象、观念」。","ex":[["J'ai besoin de me changer les idées.","我需要散散心。"],["Allons au cinéma pour nous changer les idées.","我们去看电影散散心吧。"],["Elle fait du sport pour se changer les idées.","她做运动来转换心情。"]],"co":[["avoir besoin de se changer les idées","需要散散心"],["pour se changer les idées","为了散心"],["se vider la tête","清空脑袋"],["se détendre","放松"]],"sy":[["se vider la tête","familier","放空脑袋"],["se distraire","courant","消遣，散心"],["s'aérer l'esprit","soutenu","让头脑透透气"]],"fq":"中频，日常口语常用。","me":"把脑子里的「想法」换掉：changer + les idées。","tr":{"zh":"周末我们去海边散散心吧。","fr":"Ce week-end, allons au bord de la mer pour nous changer les idées.","alt":"Ce week-end, on va à la mer pour se changer les idées.","note":"代词要对应主语：nous → nous changer。"}},
 "Du saucisson": {"pos":"n.m. 阳性名词，复数 saucissons（du 是部分冠词）","s":"干香肠；萨拉米式香肠。法国人常切片当开胃小吃或野餐吃，一般是风干、生食的。注意和 saucisse 区分：saucisse 通常是要煮或煎的鲜香肠。","ipa":"[so.si.sɔ̃]","ph":"au 读 [o]；ss 读 [s]；结尾 on 读鼻化元音 [ɔ̃]，n 不发音。","pi":"au 是 [o]，不是 [au]。ss 读清音 [s]。saucisson 不是 saucisse：一个干、一个鲜，别混用。","et":"来自 saucisse 加后缀 -on（表示「大」），saucisse 追溯到拉丁语 salsicia（盐渍的）。","ex":[["Je mange du saucisson.","我吃干香肠。"],["On achète du saucisson au marché.","我们在市场买干香肠。"],["Un apéro avec du saucisson et du fromage.","配着干香肠和奶酪的开胃酒小聚。"]],"co":[["une rondelle de saucisson","一片香肠"],["du saucisson sec","风干香肠"],["un apéro saucisson","香肠配开胃酒"],["couper le saucisson","切香肠"]],"sy":[["la saucisse","courant","鲜香肠（要加热）"],["le salami","courant","萨拉米"],["la charcuterie","courant","熟肉制品总称"]],"fq":"中频，饮食话题常用。","me":"saucisse 的「大号」：saucisse + -on。","tr":{"zh":"我想买一点干香肠。","fr":"Je voudrais acheter du saucisson.","alt":"Je prendrais un peu de saucisson.","note":"du 是部分冠词，表示不确定的量。"}},
 "Guignol": {"pos":"n.m. 阳性名词（专有名词），复数 guignols","s":"吉尼奥尔：法国里昂的经典木偶角色，19 世纪初由 Laurent Mourguet 创造。也指木偶戏本身：aller voir Guignol。口语里 faire le guignol = 装傻，逗乐；un guignol 也可指「小丑，不严肃的人」。","ipa":"[gi.ɲɔl]","ph":"gu 在 i 前读 [g]，u 不发音；gn 读 [ɲ]，像「尼」；结尾 ol 读 [ɔl]。","pi":"gui 读 [gi]，不读 [gɥi]。gn 是 [ɲ]，不是 [g.n]。","et":"来自里昂木偶角色 Guignol；该木偶由 Laurent Mourguet 在里昂创造。名字更早的来源不确定。","ex":[["Guignol était une marionnette célèbre.","吉尼奥尔是一个著名的木偶。"],["Les enfants adorent le théâtre de Guignol.","孩子们喜欢吉尼奥尔木偶戏。"],["Arrête de faire le guignol !","别装疯卖傻了！"]],"co":[["le théâtre de Guignol","吉尼奥尔木偶戏"],["une marionnette","木偶"],["faire le guignol","装傻逗乐"],["Lyon et Guignol","里昂与吉尼奥尔"]],"sy":[["une marionnette","courant","木偶（泛称）"],["un clown","courant","小丑，滑稽的人"]],"fq":"低频，文化词。","me":"Guignol 和里昂连在一起：里昂的木偶。","tr":{"zh":"孩子们去看木偶戏了。","fr":"Les enfants sont allés voir Guignol.","alt":"Les enfants sont allés voir un spectacle de marionnettes.","note":"aller 的复合时态用 être：sont allés。"}},
 "Le bord de mer": {"pos":"n.m. 阳性名词，复数 bords de mer","s":"海边；海滨。常见用法：au bord de la mer（在海边）、en bord de mer（临海的）。une station balnéaire 是海滨度假地。","ipa":"[bɔʁ də mɛʁ]","ph":"bord 读 [bɔʁ]，d 不发音；de 弱读 [də]；mer 读 [mɛʁ]，r 要读出，e 为 [ɛ]。","pi":"bord 结尾的 d 不发音。mer 的 r 要读出来，不像 bord 的 d。mer 是阴性：la mer，但 bord 是阳性。","et":"bord 来自法兰克语（日耳曼语）*bord「边，船边」；mer 来自拉丁语 mare。","ex":[["J'aime me promener en bord de mer.","我喜欢在海边散步。"],["Ils ont une maison au bord de la mer.","他们在海边有一栋房子。"],["Nous passons l'été au bord de la mer.","我们在海边度过夏天。"]],"co":[["au bord de la mer","在海边"],["en bord de mer","临海"],["une promenade en bord de mer","海边散步"],["une ville en bord de mer","海滨城市"]],"sy":[["la côte","courant","海岸，沿海"],["le littoral","soutenu","海岸地带"],["la plage","courant","海滩"]],"fq":"中频，旅行与度假话题常用。","me":"bord（边）+ mer（海）：海的边上。","tr":{"zh":"夏天我们想去海边。","fr":"En été, nous voulons aller au bord de la mer.","alt":"L'été, on veut aller à la mer.","note":"au bord de la mer：de la 里 mer 阴性。"}},
 "Le bulletin météo": {"pos":"n.m. 阳性名词，复数 bulletins météo","s":"天气预报（电台、电视、手机上的一段播报）。météo 在这里是名词作定语，所以不变：des bulletins météo。口语里常直接说 la météo。","ipa":"[byl.tɛ̃ me.te.o]","ph":"bulletin 读 [byl.tɛ̃]，u 读 [y]（圆唇），in 读鼻化元音 [ɛ̃]；météo 读 [me.te.o]，三个音节。","pi":"u 是 [y]，不是 [u]。bulletin 的 ll 读 [l]，不是 [j]。météo 的 o 单独成音节。","et":"bulletin 来自意大利语 bullettino（小公文），而 bulle 指印章、诏书；météo 是 météorologique（气象的）的缩写。","ex":[["J'écoute le bulletin météo à la radio.","我在广播里听天气预报。"],["Le bulletin météo annonce de la pluie.","天气预报说有雨。"],["Quel est le bulletin météo pour demain ?","明天的天气预报怎么样？"]],"co":[["écouter le bulletin météo","听天气预报"],["Le bulletin météo annonce…","天气预报说……"],["consulter le bulletin météo","查看天气预报"],["un bulletin météo à la radio","广播里的天气预报"]],"sy":[["la météo","courant","天气预报（口语常用）"],["les prévisions météo","courant","天气预测"]],"fq":"中频，日常常用。","me":"bulletin（简报）+ météo（天气）：一小段天气简报。","tr":{"zh":"我每天早上都看天气预报。","fr":"Chaque matin, je regarde le bulletin météo.","alt":"Tous les matins, je regarde la météo.","note":"météo 作定语不加 s。"}},
 "Le goût": {"pos":"n.m. 阳性名词，复数 goûts","s":"味道；味觉；口味；品味。1）食物的味道：un goût sucré；2）个人喜好：chacun ses goûts；3）审美品味：avoir bon goût。","ipa":"[gu]","ph":"g 读 [g]；oû 读 [u]，û 上的帽子（accent circonflexe）不改变发音；结尾 t 不发音。","pi":"结尾 t 不发音。oû 读 [u]，不要读成 [o]。动词 goûter 保留 û：goûter [gu.te]。","et":"来自拉丁语 gustus（品尝）。同族词：goûter（品尝；下午茶）、dégoût（厌恶）。","ex":[["Ce gâteau a un bon goût.","这个蛋糕味道很好。"],["Chacun ses goûts !","各有所好！"],["Elle a très bon goût.","她很有品味。"]],"co":[["avoir bon / mauvais goût","有品味 / 没品味"],["chacun ses goûts","各人喜好不同"],["un goût sucré / salé","甜味 / 咸味"],["goûter","品尝；下午茶（相关动词、名词）"]],"sy":[["la saveur","soutenu","滋味，风味"],["le sens du goût","courant","味觉"],["la préférence","courant","偏好"]],"fq":"高频，日常常用。","me":"goût = 英语 gusto 的亲戚，「品尝」。","tr":{"zh":"这道菜味道很好。","fr":"Ce plat a très bon goût.","alt":"Ce plat est très bon.","note":"avoir bon goût：味道好；也可指人有品味。"}},
 "Le soleil": {"pos":"n.m. 阳性名词，复数 soleils","s":"太阳；阳光。常用 Il y a du soleil（有太阳）、Il fait soleil（天晴，阳光足）。un coup de soleil = 晒伤。","ipa":"[sɔ.lɛj]","ph":"s 读 [s]；o 读开口 [ɔ]；eil 读 [ɛj]，像「埃伊」；结尾 l 不独立发音。","pi":"eil 读 [ɛj]，不读 [e.il]。soleil 里的 l 是半元音，不是 [l]。coup de soleil 里 coup 的 p 不发音。","et":"来自俗拉丁语 soliculus，是拉丁语 sol（太阳）的指小词。同族词：solaire、insolation。","ex":[["Le soleil brille aujourd'hui.","今天阳光灿烂。"],["Il y a beaucoup de soleil en été.","夏天阳光很多。"],["J'ai pris un coup de soleil.","我被晒伤了。"]],"co":[["il y a du soleil","有太阳"],["un coup de soleil","晒伤"],["au soleil","在太阳下"],["le lever / coucher du soleil","日出 / 日落"]],"sy":[["l'astre","littéraire","星体，诗意地指太阳"],["la lumière","courant","光线"]],"fq":"极高频，日常常用。","me":"soleil：和 solaire 同族，sol 是拉丁语的「太阳」。","tr":{"zh":"今天有太阳，我们去公园吧。","fr":"Il y a du soleil aujourd'hui, allons au parc.","alt":"Il fait beau aujourd'hui, on va au parc ?","note":"il y a du soleil：du 是部分冠词。"}},
 "Un accent": {"pos":"n.m. 阳性名词，复数 accents","s":"口音；重音；重音符号。1）说话的口音：un accent du sud；2）字母上的符号：accent aigu (é)、grave (è)、circonflexe (ê)；3）语调的重音。","ipa":"[ak.sɑ̃]","ph":"cc 在 e 前读 [ks]：ac-cent 读 [ak.sɑ̃]；结尾 ent 读鼻化元音 [ɑ̃]，t 不发音。","pi":"accent 里 cc 读 [ks]，所以是 [ak.sɑ̃]，别读 [a.sɑ̃]。结尾 ent 是 [ɑ̃]，t 不发音。","et":"来自拉丁语 accentus（声调，重音），由 ad + cantus（歌唱）构成。","ex":[["Il a l'accent du sud.","他有南方口音。"],["Elle parle français avec un accent chinois.","她说法语带着中国口音。"],["Il faut mettre un accent sur le e.","这个 e 上要加重音符。"]],"co":[["avoir un accent","有口音"],["un accent aigu / grave","锐音符 / 钝音符"],["l'accent du sud","南方口音"],["sans accent","没有口音；没有重音符"]],"sy":[["la prononciation","courant","发音"],["l'intonation","courant","语调"]],"fq":"高频，日常常用。","me":"ac + cent：accent 里藏着「唱」（cantus）。","tr":{"zh":"他说话带着英国口音。","fr":"Il parle avec un accent anglais.","alt":"Il a un accent anglais quand il parle.","note":"avec un accent + 形容词。"}},
 "Un adulte": {"pos":"n.m. 阳性名词（也作形容词）；阴性 une adulte；复数 adultes","s":"成年人；大人。不分男女，名词性别随人：un adulte / une adulte。也可作形容词：un chat adulte（成年的猫）。","ipa":"[a.dylt]","ph":"a 读 [a]；du 读 [dy]，u 为圆唇 [y]；lte 读 [lt]，结尾 e 不发音。","pi":"u 是 [y]，不是 [u]。结尾 -lte 要读出 [lt]，t 不静音。","et":"来自拉丁语 adultus（长大了的），是 adolescere（长大）的过去分词。","ex":[["C'est un adulte responsable.","这是个有责任感的成年人。"],["Les adultes travaillent, les enfants jouent.","大人们工作，孩子们玩。"],["Ce film n'est pas pour les adultes.","这部电影不是给大人看的。"]],"co":[["un adulte responsable","有责任感的成年人"],["un chat adulte","成年猫"],["devenir adulte","长大成人"],["entre adultes","成年人之间"]],"sy":[["un grand","familier","大人（小孩的说法）"],["un enfant","courant","孩子（反义）"]],"fq":"中高频，日常常用。","me":"adulte：ad + ult，已「长到」成熟。","tr":{"zh":"这家餐厅只接待成年人。","fr":"Ce restaurant accueille seulement les adultes.","alt":"Ce restaurant, c'est uniquement pour les adultes.","note":"les adultes：复数加 s，s 不发音。"}},
 "Un album photo": {"pos":"n.m. 阳性名词，复数 des albums photo（photo 不变）","s":"相册；影集。album 是阳性，photo 作定语，一般不加 s：des albums photo。看相册用 feuilleter un album photo（翻阅）。","ipa":"[al.bɔm fɔ.to]","ph":"album 读 [al.bɔm]，u 在这里不是 [y]，而是 [ɔ]，m 要读出；photo 读 [fɔ.to]，ph 为 [f]。","pi":"album 里 um 读 [ɔm]，不是 [ɔ̃]。photo 的 ph 是 [f]，不是 [p]。复数 photo 不加 s。","et":"album 来自拉丁语 album（白色板、空白册）；photo 是 photographie（希腊语 phôs「光」+ graphein「写」）的缩写。","ex":[["J'ai un bel album photo.","我有一本漂亮的相册。"],["Elle regarde l'album photo de la famille.","她翻看家庭相册。"],["Je prépare un album photo de nos vacances.","我在整理我们假期的相册。"]],"co":[["feuilleter un album photo","翻看相册"],["un album photo de famille","家庭相册"],["un album de mariage","婚礼相册"],["mettre des photos dans un album","把照片放进相册"]],"sy":[["un album","courant","相册（简称）"],["un livre photo","courant","照片书（印刷版）"]],"fq":"中频，日常常用。","me":"album = 白色的册子，等着贴照片。","tr":{"zh":"我们一起看相册吧。","fr":"Regardons l'album photo ensemble.","alt":"On regarde l'album photo ensemble ?","note":"regardons：对 nous 的祈使式。"}},
 "Un bébé": {"pos":"n.m. 阳性名词，复数 bébés（男孩女孩都用阳性）","s":"婴儿；宝宝。bébé 永远是阳性词，不管男女：une petite fille, c'est un bébé。动物的幼崽也可说 bébé animal，如 un bébé éléphant。","ipa":"[be.be]","ph":"两个 é 都读 [e]，闭口 e；两个音节，重音落在最后。","pi":"两个 é 都有重音符，不能漏。bébé 不管男女都是阳性：un bébé。","et":"来源不确定，一般认为是童音叠词（bé-bé）。","ex":[["Le bébé dort.","宝宝在睡觉。"],["Elle attend un bébé.","她怀孕了。"],["Le bébé a six mois.","宝宝六个月大。"]],"co":[["attendre un bébé","怀孕"],["un bébé de six mois","六个月大的宝宝"],["un bébé éléphant","小象（幼崽）"],["un siège bébé","婴儿座椅"]],"sy":[["un nourrisson","soutenu","婴儿（医学、较书面）"],["un petit","familier","小宝宝，小家伙"]],"fq":"高频，日常常用。","me":"bé-bé：叠音，像宝宝咿呀学语。","tr":{"zh":"宝宝已经睡着了。","fr":"Le bébé s'est déjà endormi.","alt":"Le bébé dort déjà.","note":"s'endormir 的复合时态用 être。"}},
 "Un blog": {"pos":"n.m. 阳性名词，复数 blogs","s":"博客；网络日志。借自英语。相关词：un blogueur / une blogueuse（博主）、bloguer（写博客）。","ipa":"[blɔg]","ph":"bl 连读 [bl]；o 读开口 [ɔ]；g 在结尾要读出来 [g]。","pi":"结尾 g 要发音 [g]，不像很多法语词的结尾辅音不发音。o 是 [ɔ]，不是英语的 [ɒ]。","et":"借自英语 blog，是 weblog（网络日志）的缩写。","ex":[["J'écris des articles sur mon blog.","我在博客上写文章。"],["Elle tient un blog de cuisine.","她经营一个美食博客。"],["Il lit des blogs de voyage.","他读旅行博客。"]],"co":[["tenir un blog","经营博客"],["un blog de cuisine / de voyage","美食 / 旅行博客"],["écrire sur un blog","在博客上写"],["un article de blog","博客文章"]],"sy":[["un site","courant","网站（更宽泛）"],["un journal en ligne","courant","网络日记"]],"fq":"中频，日常常用。","me":"blog = web + log，结尾 g 读出来。","tr":{"zh":"我想开一个旅行博客。","fr":"Je veux créer un blog de voyage.","alt":"J'ai envie de lancer un blog sur mes voyages.","note":"un blog de voyage：de + 名词，不加冠词。"}},
 "Un endroit": {"pos":"n.m. 阳性名词，复数 endroits","s":"地方；场所。很口语、很通用的「地方」，可指具体地点：un endroit calme。比 lieu 更随意，比 place（位置、座位、广场）更宽泛。","ipa":"[ɑ̃.dʁwa]","ph":"en 读 [ɑ̃]；droit 读 [dʁwa]，oi 是 [wa]；结尾 -oit 的 t 不发音。","pi":"结尾 t 不发音。oi 是 [wa]。和 droit（右边；权利）相似。","et":"由 en + droit 构成，原意是布料的「正面」（反义 envers）；后来引申为「地方」。","ex":[["C'est un endroit très calme.","这是个非常安静的地方。"],["Quel est ton endroit préféré ?","你最喜欢的地方是哪里？"],["Cet endroit est magnifique.","这个地方太美了。"]],"co":[["un endroit calme / tranquille","安静的地方"],["à cet endroit","在这个地方"],["à l'endroit / à l'envers","正面 / 反面"],["à quel endroit ?","在哪个地方？"]],"sy":[["un lieu","courant","地点，场所，较正式"],["un coin","familier","角落，小地方"],["un site","courant","场地、景点"]],"fq":"极高频，日常常用。","me":"en + droit：东西「摆正」的那个位置。","tr":{"zh":"这是个很适合休息的地方。","fr":"C'est un endroit idéal pour se reposer.","alt":"C'est un super endroit pour se reposer.","note":"idéal pour + 不定式。"}},
 "Un gadget": {"pos":"n.m. 阳性名词，复数 gadgets","s":"小玩意；小工具；新奇小器具。有时带贬义，指不太实用的东西：Ce n'est qu'un gadget。也指促销赠品。","ipa":"[gad.ʒɛt]","ph":"g 读 [g]；ad 读 [ad]；g 在 e 前读 [ʒ]，所以第二个 g 是 [ʒ]；结尾 et 读 [ɛt]。","pi":"第一个 g 读 [g]，第二个 g 读 [ʒ]，别两个都读一样。结尾 t 要读出来 [ɛt]。","et":"借自英语 gadget，原指小器械，更早的来源不确定。","ex":[["Ce gadget est très utile.","这个小玩意很有用。"],["Il achète tous les derniers gadgets.","他把最新的小玩意都买了。"],["Ce n'est qu'un gadget, ça ne sert à rien.","这只是个小玩意，没什么用。"]],"co":[["un gadget électronique","电子小玩意"],["un gadget publicitaire","促销赠品"],["acheter un gadget","买小玩意"],["un gadget inutile","没用的小玩意"]],"sy":[["un machin","familier","东西，玩意儿"],["un accessoire","courant","配件，附件"],["un bidule","familier","小东西"]],"fq":"中频，日常常用。","me":"gadget：g-g 两个 g，读音不同：[g] 和 [ʒ]。","tr":{"zh":"他的房间里有很多电子小玩意。","fr":"Il y a beaucoup de gadgets électroniques dans sa chambre.","alt":"Sa chambre est pleine de gadgets électroniques.","note":"beaucoup de + 复数名词。"}},
 "Un magnet": {"pos":"n.m. 阳性名词，复数 magnets","s":"冰箱贴；小磁贴。指带磁铁的装饰小件，常作旅行纪念品。普通的「磁铁」是 un aimant。","ipa":"[ma.ɲɛt]","ph":"ma 读 [ma]；gn 读 [ɲ]；et 读 [ɛt]，t 要读出来。","pi":"gn 读 [ɲ]，不是 [g.n]。结尾 t 要读出。「磁铁」是 aimant，不是 magnet。","et":"借自英语 magnet 的这种用法（装饰磁贴）；英语词来自希腊语 Magnēs lithos「马格尼西亚的石头」。","ex":[["Il y a un magnet sur le frigo.","冰箱上有个冰箱贴。"],["J'ai rapporté un magnet de Lisbonne.","我从里斯本带回一个冰箱贴。"],["Elle collectionne les magnets.","她收集冰箱贴。"]],"co":[["un magnet de frigo","冰箱贴"],["collectionner les magnets","收集冰箱贴"],["un magnet souvenir","纪念冰箱贴"],["coller un magnet","贴一个磁贴"]],"sy":[["un aimant","courant","磁铁（物理意义）"],["un souvenir","courant","纪念品"]],"fq":"中频，日常常用。","me":"magnet：贴在冰箱上的小纪念。","tr":{"zh":"我在每个城市都买一个冰箱贴。","fr":"J'achète un magnet dans chaque ville.","alt":"Dans chaque ville, je prends un magnet.","note":"chaque + 单数名词。"}},
 "Un mobilehome": {"pos":"n.m. 阳性名词，规范拼写 mobil-home，复数 mobil-homes","s":"移动房屋；度假用的活动板房（常见于法国露营地、海边）。不是能开走的房车，那个叫 un camping-car。规范拼写是 mobil-home，带连字符。","ipa":"[mɔ.bil.om]","ph":"mo 读 [mɔ]；bil 读 [bil]；home 读 [om]，h 不发音，e 不发音。","pi":"拼写是 mobil-home，没有 e（不是 mobile）。h 不发音。别和房车 camping-car 混淆。","et":"仿英语 mobile home 造的法语词，法语里写成 mobil-home（拼写与英语不同）。","ex":[["Nous dormons dans un mobilehome.","我们睡在移动房屋里。"],["Ils ont loué un mobil-home au camping.","他们在露营地租了一个活动房屋。"],["Le mobil-home est équipé d'une petite cuisine.","活动房屋配有一个小厨房。"]],"co":[["louer un mobil-home","租一个活动房屋"],["un mobil-home au camping","露营地的活动房屋"],["passer les vacances en mobil-home","在活动房屋里度假"],["un camping-car","房车（对比词）"]],"sy":[["un camping-car","courant","房车（能开动）"],["une caravane","courant","拖挂式房车"],["un bungalow","courant","平房式度假小屋"]],"fq":"中低频，度假话题常见。","me":"mobil-home：「可移动的家」，但其实多半停在原地。","tr":{"zh":"我们今年夏天要租一个活动房屋。","fr":"Cet été, nous allons louer un mobil-home.","alt":"Cet été, on loue un mobil-home.","note":"aller + 不定式表示近将来。"}},
 "Un mug": {"pos":"n.m. 阳性名词，复数 mugs","s":"马克杯；带把的大杯子。借自英语。比 une tasse（茶杯，咖啡杯）更大、更直筒，常用来喝热咖啡、茶、巧克力。","ipa":"[mœg]","ph":"m [m]；u 读 [œ]，像「额」带圆唇；g 在结尾要读出来 [g]。","pi":"u 读 [œ]，不是 [y] 也不是英语的 [ʌ]；g 要读出来。别读成 [my]。","et":"借自英语 mug。","ex":[["Je bois mon café dans un mug.","我用马克杯喝咖啡。"],["Il offre un mug à son collègue.","他送同事一个马克杯。"],["Ce mug est trop petit pour moi.","这个马克杯对我来说太小了。"]],"co":[["un mug de café / de thé","一杯咖啡 / 茶"],["boire dans un mug","用马克杯喝"],["un mug en céramique","陶瓷马克杯"],["laver les mugs","洗马克杯"]],"sy":[["une tasse","courant","茶杯，咖啡杯"],["un bol","courant","碗状大杯"],["un verre","courant","玻璃杯"]],"fq":"中频，日常常用。","me":"mug：[mœg]，像「么哥」。","tr":{"zh":"给我一杯热巧克力，用马克杯。","fr":"Donne-moi un chocolat chaud dans un mug.","alt":"Je prendrais un chocolat chaud dans un mug.","note":"donne-moi：祈使式带宾语 moi。"}},
 "Un objectif": {"pos":"n.m. 阳性名词，复数 objectifs（也可作形容词 objectif / objective）","s":"目标；目的；也指相机镜头。表示目标时：atteindre un objectif；相机镜头：l'objectif de l'appareil photo。形容词 objectif 的意思是「客观的」。","ipa":"[ɔb.ʒɛk.tif]","ph":"o 读 [ɔ]；b 读 [b]；j 读 [ʒ]；ec 读 [ɛk]；tif 读 [tif]，f 要读出来。","pi":"j 是 [ʒ]，不是 [dʒ]。结尾 f 读出来。名词是阳性：un objectif。","et":"来自拉丁语 objectivus，源于 objicere（放在前面，摆在……之前）。","ex":[["Mon objectif est d'apprendre le français.","我的目标是学习法语。"],["Nous avons atteint notre objectif.","我们达到了目标。"],["Cet appareil photo a un bon objectif.","这台相机的镜头很好。"]],"co":[["atteindre un objectif","达到目标"],["se fixer un objectif","给自己定目标"],["l'objectif d'un appareil photo","相机镜头"],["un objectif réaliste","现实的目标"]],"sy":[["un but","courant","目的，目标（更日常）"],["un projet","courant","计划，项目"],["une cible","courant","目标，靶子"]],"fq":"高频，日常和工作场合常用。","me":"objectif：objet（东西）前方的那个「靶子」。","tr":{"zh":"今年我的目标是学好法语。","fr":"Cette année, mon objectif est de bien apprendre le français.","alt":"Cette année, je veux vraiment progresser en français.","note":"mon objectif est de + 不定式。"}},
 "Un orage": {"pos":"n.m. 阳性名词，复数 orages","s":"雷雨；雷暴。伴随打雷闪电的暴雨，不是普通下雨。Il y a de l'orage（有雷雨）、un orage éclate（雷雨突然来了）。","ipa":"[ɔ.ʁaʒ]","ph":"o 读 [ɔ]；r 为小舌音 [ʁ]；age 读 [aʒ]，g 在 e 前读 [ʒ]，结尾 e 不发音。","pi":"orage 是阳性：un orage，不是 une orage。尽管以 -e 结尾。g 读 [ʒ]。","et":"由古法语 ore（风，来自拉丁语 aura）加后缀 -age 构成。","ex":[["Il y a un gros orage ce soir.","今晚有大雷雨。"],["Un orage éclate sur la ville.","一场雷雨在城市上空爆发。"],["J'ai peur pendant l'orage.","打雷下雨时我很害怕。"]],"co":[["un orage éclate","雷雨爆发"],["un temps d'orage","雷雨天气"],["Il y a de l'orage.","有雷雨。"],["un orage violent","猛烈的雷雨"]],"sy":[["une tempête","courant","风暴"],["une averse","courant","阵雨"],["le tonnerre","courant","雷声"]],"fq":"中高频，日常常用。","me":"orage 来自 ore（风）+ age：伴着风来的暴雨。","tr":{"zh":"傍晚会有雷雨。","fr":"Il va y avoir de l'orage en fin de journée.","alt":"Il y aura un orage ce soir.","note":"il va y avoir：近将来的 il y a。"}},
 "Un porte-clé": {"pos":"n.m. 阳性名词，常见拼写 un porte-clés，复数 des porte-clés（不变）","s":"钥匙扣；钥匙圈。常见拼写是 porte-clés（带 s），单复数同形；porte-clé 也常见。可作礼物或纪念品。","ipa":"[pɔʁt.kle]","ph":"porte 读 [pɔʁt]，e 不发音；clé 读 [kle]，é 为 [e]；结尾的 s 不发音。","pi":"porte-clés 的 s 不发音，所以单复数听起来一样。porte 的 t 要读出来。clé 的重音符不能漏。","et":"porter（携带）+ clé（钥匙，拉丁语 clavis）：字面是「携带钥匙的东西」。","ex":[["J'ai un porte-clé avec mes clés.","我有一个挂着钥匙的钥匙扣。"],["Il m'a offert un porte-clés de Paris.","他送了我一个巴黎钥匙扣。"],["Mon porte-clés est en forme de chat.","我的钥匙扣是猫的形状。"]],"co":[["un porte-clés en cuir","皮质钥匙扣"],["offrir un porte-clés","送一个钥匙扣"],["un porte-clés souvenir","纪念钥匙扣"],["accrocher ses clés au porte-clés","把钥匙挂在钥匙扣上"]],"sy":[["un porte-clefs","courant","另一种拼写"],["un anneau","courant","钥匙圈"]],"fq":"中低频，日常物品。","me":"porte（携带）+ clé（钥匙）：载着钥匙的东西。","tr":{"zh":"我的钥匙扣丢了。","fr":"J'ai perdu mon porte-clés.","alt":"J'ai paumé mon porte-clés.","note":"perdre 的复合时态用 avoir。"}},
 "Un radiateur": {"pos":"n.m. 阳性名词，复数 radiateurs","s":"暖气片；散热器。法国家庭常见的墙边暖气，也指汽车的水箱散热器。开暖气说 allumer le chauffage 或 allumer le radiateur。","ipa":"[ʁa.dja.tœʁ]","ph":"ra 读 [ʁa]；dia 读 [dja]；teur 读 [tœʁ]，eu 为 [œ]，r 要读出来。","pi":"-eur 是 [œʁ]，r 读出来。i 与 a 之间有半元音：[dja]，别分成 di-a。","et":"来自拉丁语 radiare（发出光线），radius 是「光线，射线」。同族词：radiation、radio。","ex":[["J'allume le radiateur parce qu'il fait froid.","太冷了，我开暖气。"],["Le radiateur de ma chambre ne marche plus.","我房间的暖气片坏了。"],["Mets ton manteau sur le radiateur.","把你的外套放在暖气片上。"]],"co":[["allumer / éteindre le radiateur","打开 / 关掉暖气"],["un radiateur électrique","电暖器"],["le radiateur est chaud / froid","暖气是热的 / 凉的"],["le radiateur d'une voiture","汽车散热器"]],"sy":[["le chauffage","courant","供暖（系统）"],["un convecteur","courant","对流式电暖器"]],"fq":"中频，日常常用。","me":"radiateur：向外「辐射」热量，和 radio 同族。","tr":{"zh":"房间很冷，请开一下暖气。","fr":"Il fait froid dans la chambre, allume le radiateur, s'il te plaît.","alt":"Il fait froid ici, tu peux allumer le radiateur ?","note":"allume：对 tu 的祈使式。"}},
 "Un rocher": {"pos":"n.m. 阳性名词，复数 rochers","s":"岩石；大石头；礁石。指较大的整块岩石，常见于海边、山里：un rocher sur la plage。小的石头是 caillou 或 pierre。","ipa":"[ʁɔ.ʃe]","ph":"r 为小舌音 [ʁ]；o 读 [ɔ]；ch 读 [ʃ]；er 读 [e]，结尾 r 不发音。","pi":"结尾 -er 读 [e]，r 不发音。ch 是 [ʃ]。和 roche（岩石，岩壁）相近。","et":"由 roche（岩石）加后缀 -er 构成。roche 的更早来源不确定。","ex":[["Il y a un gros rocher sur la plage.","海滩上有一块大岩石。"],["Les enfants grimpent sur un rocher.","孩子们爬上一块大石头。"],["Le phare est construit sur un rocher.","灯塔建在礁石上。"]],"co":[["un rocher sur la plage","海滩上的岩石"],["grimper sur un rocher","爬岩石"],["un rocher glissant","湿滑的岩石"],["le rocher de Gibraltar","直布罗陀巨岩"]],"sy":[["une roche","courant","岩石（材质，岩体）"],["un caillou","courant","小石头"],["une pierre","courant","石头"]],"fq":"中频，自然话题常用。","me":"roche + -er：一块「大块头」的石头。","tr":{"zh":"我们爬上了海边的岩石。","fr":"Nous avons grimpé sur les rochers au bord de la mer.","alt":"On a escaladé les rochers près de la mer.","note":"grimper sur + 地点。"}},
 "Un souvenir": {"pos":"n.m. 阳性名词，复数 souvenirs","s":"回忆；记忆中的事。J'ai de bons souvenirs = 我有美好的回忆。动词形式是 se souvenir de（记得）。信里写 Bon souvenir à ta mère 是「代我问候你妈妈」。","ipa":"[suv.niʁ]","ph":"sou 读 [su]；ve 弱读，甚至省略，整体 [suv.niʁ]；ir 读 [iʁ]，r 要读出来。","pi":"结尾 r 要读出来。souvenir 当名词是「回忆」，当「纪念品」时也一样写，意思看上下文。se souvenir 是代动词，复合时态用 être。","et":"来自拉丁语 subvenire（涌上心头，来到脑中）。","ex":[["J'ai de très bons souvenirs de mon enfance.","我有很多童年的美好回忆。"],["Je garde un souvenir heureux de ce voyage.","我对这次旅行留有愉快的回忆。"],["Bon souvenir à tes parents !","代我向你父母问好！"]],"co":[["un bon / mauvais souvenir","美好 / 糟糕的回忆"],["un souvenir d'enfance","童年回忆"],["garder un souvenir de","留有……的回忆"],["en souvenir de","为了纪念……"]],"sy":[["la mémoire","courant","记忆力，记忆"],["un rappel","courant","提醒"],["la réminiscence","littéraire","依稀的回忆"]],"fq":"极高频，日常常用。","me":"souvenir：sou（下）+ venir（来）：回忆从心底「涌上来」。","tr":{"zh":"那次旅行是我最美好的回忆。","fr":"Ce voyage est mon meilleur souvenir.","alt":"Ce voyage, c'est mon plus beau souvenir.","note":"meilleur 修饰名词，最高级。"}},
 "Un souvenir (de voyage)": {"pos":"n.m. 阳性名词，复数 souvenirs","s":"纪念品；旅行纪念品。从旅游地带回的小礼物：acheter un souvenir。作此义时，常说 un souvenir de + 地名。纪念品商店是 une boutique de souvenirs。","ipa":"[suv.niʁ]","ph":"sou 读 [su]；venir 读 [və.niʁ] 或快读 [vniʁ]；结尾 r 读出。","pi":"souvenir 同时有「回忆」和「纪念品」两个义，靠上下文判断。纪念品多是复数使用：des souvenirs。","et":"来自拉丁语 subvenire（涌上心头）；由「回忆」义引申为「帮助回忆的物品」。","ex":[["J'ai acheté des souvenirs de Norvège.","我买了挪威的纪念品。"],["Il rapporte un souvenir pour chaque ami.","他给每个朋友带回一份纪念品。"],["Cette boutique vend des souvenirs de Paris.","这家店卖巴黎纪念品。"]],"co":[["un souvenir de voyage","旅行纪念品"],["une boutique de souvenirs","纪念品商店"],["rapporter un souvenir","带回纪念品"],["un souvenir de + 地名","……的纪念品"]],"sy":[["un cadeau","courant","礼物"],["un objet souvenir","courant","纪念小物"]],"fq":"中高频，旅行话题常用。","me":"souvenir：能帮你「想起」旅行的小物件。","tr":{"zh":"我给妈妈买了一个纪念品。","fr":"J'ai acheté un souvenir pour ma mère.","alt":"J'ai pris un petit souvenir pour ma mère.","note":"pour + 人：给某人。"}},
 "Un volcan": {"pos":"n.m. 阳性名词，复数 volcans","s":"火山。可以是活火山 un volcan actif，也可以是休眠或死火山 un volcan endormi / éteint。火山喷发是 une éruption volcanique。","ipa":"[vɔl.kɑ̃]","ph":"v 读 [v]；ol 读 [ɔl]；can 读鼻化元音 [kɑ̃]，n 不发音。","pi":"结尾 an 读 [ɑ̃]，n 不发音。形容词是 volcanique。","et":"来自意大利语 vulcano，源自拉丁语 Vulcanus，罗马火神 Vulcain。","ex":[["Ce volcan est très grand.","这座火山很大。"],["Le volcan est entré en éruption.","火山爆发了。"],["Nous avons visité un volcan en Islande.","我们在冰岛参观了一座火山。"]],"co":[["un volcan actif / éteint","活火山 / 死火山"],["l'éruption d'un volcan","火山喷发"],["entrer en éruption","开始喷发"],["un cratère de volcan","火山口"]],"sy":[["un cratère","courant","火山口"],["la lave","courant","熔岩"]],"fq":"中频，自然、旅行话题。","me":"volcan 来自 Vulcain，罗马的火神。","tr":{"zh":"这座火山还很活跃。","fr":"Ce volcan est encore actif.","alt":"Ce volcan est toujours en activité.","note":"encore actif：仍然活跃。"}},
 "De la crème solaire": {"pos":"n.f. 阴性名词短语，复数 crèmes solaires（de la 为部分冠词）","s":"防晒霜。de la 表示「一些」，不确定的量：mettre de la crème solaire。防晒指数说 indice 30 / indice 50。晒伤用 un coup de soleil。","ipa":"[kʁɛm sɔ.lɛʁ]","ph":"crème 读 [kʁɛm]，è 为 [ɛ]，结尾 e 不发音；solaire 读 [sɔ.lɛʁ]，ai 为 [ɛ]，r 读出来。","pi":"crème 有重音符 è。solaire 的 ai 读 [ɛ]，别读 [e]。crème 阴性，solaire 随之不变。","et":"solaire 来自拉丁语 solaris（太阳的），sol 是太阳；crème 的来源不确定。","ex":[["Je mets de la crème solaire.","我涂防晒霜。"],["N'oublie pas ta crème solaire !","别忘了你的防晒霜！"],["Cette crème solaire a un indice 50.","这款防晒霜是 SPF 50。"]],"co":[["mettre de la crème solaire","涂防晒霜"],["une crème solaire indice 50","SPF 50 防晒霜"],["un coup de soleil","晒伤"],["se protéger du soleil","防晒"]],"sy":[["un écran solaire","courant","防晒乳（常见于加拿大）"],["l'huile solaire","courant","防晒油"]],"fq":"中频，夏季、度假话题。","me":"crème + solaire（太阳的）：抹给太阳看的霜。","tr":{"zh":"海滩上记得涂防晒霜。","fr":"N'oublie pas de mettre de la crème solaire à la plage.","alt":"À la plage, mets de la crème solaire.","note":"ne pas oublier de + 不定式。"}},
 "L'enfance": {"pos":"n.f. 阴性名词（单数为主）","s":"童年；儿童时期。强调那个人生阶段，常说 dans mon enfance（在我童年时）、un souvenir d'enfance（童年回忆）。","ipa":"[ɑ̃.fɑ̃s]","ph":"en 和 an 都读鼻化元音 [ɑ̃]；f 读 [f]；c 在 e 前读 [s]；结尾 e 不发音。l' 是省音，与 enfance 连着读。","pi":"两个鼻化元音一样，别读成 [ɛ̃]。结尾 c 读 [s]。enfance 阴性：l'enfance。","et":"来自拉丁语 infantia（不会说话的时期），同源 enfant、infant。","ex":[["L'enfance est une belle période.","童年是美好的时期。"],["J'ai passé mon enfance à la campagne.","我在乡下度过了童年。"],["Dans mon enfance, je jouais dehors.","小时候，我常在外面玩。"]],"co":[["dans mon enfance","在我小时候"],["un souvenir d'enfance","童年回忆"],["un ami d'enfance","儿时好友"],["la petite enfance","幼儿期"]],"sy":[["la jeunesse","courant","青年时期，青春"],["le jeune âge","soutenu","年幼时"]],"fq":"高频，日常常用。","me":"enfance = enfant + -ance：孩子的「时期」。","tr":{"zh":"我的童年是在海边度过的。","fr":"J'ai passé mon enfance au bord de la mer.","alt":"Mon enfance, je l'ai passée à la mer.","note":"passer son enfance + 地点。"}},
 "L'île de La Réunion": {"pos":"n.f. 阴性专有名词短语","s":"留尼汪岛：位于印度洋、马达加斯加以东的法国海外省（也是大区），属于欧元区和欧盟。居民叫 les Réunionnais。说「在留尼汪」用 à La Réunion，不用 en。","ipa":"[il də la ʁe.y.njɔ̃]","ph":"île 读 [il]，î 上的帽子不改变发音；Réunion 读 [ʁe.y.njɔ̃]，四个音节，é [e]，u [y]，ion [jɔ̃]。","pi":"île 有 î；不是 ile。Réunion 的 é 和 u 分开读，是四音节。L'île 里 le 的元音省音。说「在岛上」用 à La Réunion。","et":"île 来自拉丁语 insula；La Réunion 原名 île Bourbon，后改称 La Réunion，réunion 意为「聚合，团聚」。","ex":[["L'île de La Réunion est magnifique.","留尼汪岛很美。"],["Ils habitent à La Réunion.","他们住在留尼汪。"],["Il y a un volcan sur l'île de La Réunion.","留尼汪岛上有一座火山。"]],"co":[["à La Réunion","在留尼汪"],["un Réunionnais / une Réunionnaise","留尼汪人"],["l'océan Indien","印度洋"],["un département d'outre-mer","海外省"]],"sy":[["la Réunion","courant","留尼汪（省略 île de）"],["l'île Bourbon","courant","旧称：波旁岛"]],"fq":"中低频，地理、旅行话题。","me":"Réunion = 重新聚在一起：联合之岛。","tr":{"zh":"我想去留尼汪岛看火山。","fr":"Je veux aller à La Réunion pour voir le volcan.","alt":"J'aimerais aller sur l'île de La Réunion voir le volcan.","note":"岛名前用 à，不用 en。"}},
 "La canicule": {"pos":"n.f. 阴性名词，复数 canicules","s":"热浪；酷暑。夏季连续多日异常高温：Il fait très chaud pendant la canicule。法国官方预警里常见 alerte canicule。","ipa":"[ka.ni.kyl]","ph":"ca 读 [ka]；ni 读 [ni]；cule 读 [kyl]，u 为 [y]，圆唇；结尾 e 不发音。","pi":"u 读 [y]，不是 [u]。c 读 [k]，两个 c 都是。重音落在最后，canicule 三个音节。","et":"来自拉丁语 canicula（小狗星，指天狼星），古人认为天狼星与太阳同时升起的日子最热。","ex":[["Il fait très chaud pendant la canicule.","酷暑期间天气很热。"],["Il y a une alerte canicule dans le sud.","南部发布了高温预警。"],["Pendant la canicule, buvez beaucoup d'eau.","酷暑时多喝水。"]],"co":[["une vague de chaleur","热浪（同义说法）"],["une alerte canicule","高温预警"],["en pleine canicule","正值酷暑"],["la canicule de l'été","夏季的酷暑"]],"sy":[["une vague de chaleur","courant","热浪"],["la chaleur","courant","炎热"],["la fournaise","littéraire","酷热如炉"]],"fq":"中频，夏季新闻常见。","me":"canicule 里有 can- 「犬」：天狼星，是「狗星」的热天。","tr":{"zh":"热浪来了，大家待在家里。","fr":"Avec la canicule, tout le monde reste à la maison.","alt":"Il fait si chaud que tout le monde reste chez soi.","note":"avec + 名词，表示原因。"}},
 "La jeunesse": {"pos":"n.f. 阴性名词，复数 jeunesses（多用单数）","s":"青春；青年时期；也指「年轻人」这个群体：la jeunesse d'aujourd'hui。回忆自己年轻时：dans ma jeunesse。","ipa":"[ʒœ.nɛs]","ph":"j 读 [ʒ]；eu 读 [œ]；n 读 [n]；esse 读 [ɛs]，ss 读 [s]，结尾 e 不发音。","pi":"eu 读 [œ]，不是 [u]。ss 读 [s]。jeunesse 与 jeune（年轻的）不同，是名词。","et":"由 jeune 加后缀 -esse 构成；jeune 来自拉丁语 juvenis。","ex":[["Il a beaucoup d'énergie dans sa jeunesse.","他年轻时精力充沛。"],["La jeunesse d'aujourd'hui aime la musique électronique.","现在的年轻人喜欢电子音乐。"],["Elle a passé sa jeunesse à Lyon.","她的青年时代是在里昂度过的。"]],"co":[["dans ma jeunesse","在我年轻时"],["la jeunesse d'aujourd'hui","当今的年轻人"],["une auberge de jeunesse","青年旅舍"],["un ami de jeunesse","少年时的朋友"]],"sy":[["les jeunes","courant","年轻人"],["l'adolescence","courant","青春期"],["la verdeur","littéraire","朝气，青春活力"]],"fq":"中高频，日常常用。","me":"jeune + -esse：「年轻」的状态。","tr":{"zh":"我年轻时住在巴黎。","fr":"Dans ma jeunesse, j'habitais à Paris.","alt":"Quand j'étais jeune, j'habitais à Paris.","note":"过去的习惯用未完成过去时 j'habitais。"}},
 "La majorité": {"pos":"n.f. 阴性名词，复数 majorités","s":"多数；大多数；也指成年（法定 18 岁）和政治里的执政多数。la majorité des gens = 大多数人。la majorité 后的动词可单数也可复数。","ipa":"[ma.ʒɔ.ʁi.te]","ph":"ma 读 [ma]；jo 读 [ʒɔ]，j 为 [ʒ]；ri 读 [ʁi]；té 读 [te]；共四个音节。","pi":"j 读 [ʒ]。结尾 é 要读出来 [e]。la majorité des gens 后面动词可用单数或复数。","et":"来自拉丁语 major（更大的）加后缀 -ité。同族词：majeur（成年的）、majuscule。","ex":[["La majorité des gens sont d'accord.","大多数人同意。"],["Il aura la majorité à dix-huit ans.","他十八岁就成年了。"],["Le parti a obtenu la majorité.","该党获得了多数席位。"]],"co":[["la majorité des gens","大多数人"],["la majorité absolue","绝对多数"],["à la majorité","以多数票"],["atteindre la majorité","到达成年"]],"sy":[["la plupart","courant","大部分"],["la minorité","courant","少数（反义）"]],"fq":"高频，日常和新闻常见。","me":"major（更大）→ majorité：「更多」的那一边。","tr":{"zh":"大多数学生都喜欢这位老师。","fr":"La majorité des élèves aiment ce professeur.","alt":"La plupart des élèves adorent ce prof.","note":"la majorité des + 复数名词，动词常用复数。"}},
 "La météo": {"pos":"n.f. 阴性名词（météorologie 的缩写），常用单数","s":"天气预报；气象。口语常说 la météo 指预报：Qu'est-ce que dit la météo ? 说「天气」本身用 le temps，不是 la météo：Quel temps fait-il ?","ipa":"[me.te.o]","ph":"mé 读 [me]；té 读 [te]；o 读 [o]，三个音节，各自分开。","pi":"météo 的 o 单独成音节，不是 [meteo] 连成一个。别把 la météo（预报）与 le temps（天气）混用。météo 是阴性。","et":"météorologie 的缩写；meteōra 在希腊语里指「空中的现象」，加 logos「学问」。","ex":[["Je regarde la météo à la télévision.","我在电视上看天气预报。"],["La météo annonce de la pluie demain.","天气预报说明天有雨。"],["Que dit la météo pour ce week-end ?","周末天气预报怎么说？"]],"co":[["regarder / consulter la météo","看天气预报"],["la météo du week-end","周末天气预报"],["Qu'est-ce que dit la météo ?","天气预报怎么说？"],["la météo annonce…","天气预报说……"]],"sy":[["le bulletin météo","courant","天气预报播报"],["les prévisions","courant","预测"],["le temps","courant","天气本身"]],"fq":"极高频，日常常用。","me":"météo = 天气预报，temps = 天气本身。","tr":{"zh":"你看今天的天气预报了吗？","fr":"Tu as regardé la météo aujourd'hui ?","alt":"T'as vu la météo pour aujourd'hui ?","note":"la météo 作直接宾语。"}},
 "La moitié": {"pos":"n.f. 阴性名词，复数 moitiés","s":"一半；二分之一。la moitié du gâteau = 半个蛋糕。à moitié = 一半地。ma moitié（口语）可指「我的另一半」。形容词「半的」是 demi。","ipa":"[mwa.tje]","ph":"oi 读 [wa]；ti 在这里读 [tj]，ié 读 [je]，所以 moitié 是两个音节 [mwa.tje]。","pi":"oi 是 [wa]。结尾 ié 读 [je]，é 要读出来。moitié 是阴性。la moitié des gens 后动词单复数皆可。","et":"来自拉丁语 medietas（中间，一半），源自 medius（中间的）。","ex":[["Je mange la moitié du gâteau.","我吃了半个蛋糕。"],["La moitié des élèves est absente.","一半的学生缺席。"],["Il a fait le travail à moitié.","他只做了一半的工作。"]],"co":[["la moitié de + 名词","……的一半"],["à moitié","一半地，半"],["moitié-moitié","各一半"],["la moitié du temps","一半的时间"]],"sy":[["le demi","courant","半（用作名词）"],["la moitié","courant","一半（本词）"],["ma moitié","familier","我的另一半（指伴侣）"]],"fq":"高频，日常常用。","me":"moitié 里有 medi- 「中间」：正好切在中间。","tr":{"zh":"我们把蛋糕分成两半吧。","fr":"Partageons le gâteau en deux, chacun mange la moitié.","alt":"On coupe le gâteau en deux, moitié-moitié.","note":"moitié 阴性：la moitié。"}},
 "Une affiche": {"pos":"n.f. 阴性名词，复数 affiches","s":"海报；招贴；告示。贴在墙上的电影海报、广告、通告：une affiche de film。动词是 afficher（张贴）。à l'affiche = 正在上映、上演。","ipa":"[a.fiʃ]","ph":"a 读 [a]；ffi 双 f 读一个 [f]；che 的 ch 读 [ʃ]，结尾 e 不发音。","pi":"ff 只读一个 [f]。ch 是 [ʃ]，所以结尾是 [ʃ]。affiche 是阴性：une affiche。","et":"afficher（张贴）的名词；afficher 来自 ad + 动词，与 fixer（固定）同一族。","ex":[["Il y a une belle affiche sur le mur.","墙上有一张漂亮的海报。"],["Cette affiche de film est célèbre.","这张电影海报很有名。"],["Le film est à l'affiche depuis une semaine.","这部电影已经上映一周了。"]],"co":[["une affiche de film / de concert","电影 / 音乐会海报"],["être à l'affiche","正在上映"],["coller / accrocher une affiche","张贴海报"],["une affiche publicitaire","广告海报"]],"sy":[["un poster","courant","大幅海报（装饰用）"],["un panneau","courant","牌子，告示板"],["une pancarte","courant","标语牌"]],"fq":"中频，日常常用。","me":"affiche：afficher（张贴）的名词。","tr":{"zh":"他把海报贴在房间的墙上。","fr":"Il a accroché une affiche sur le mur de sa chambre.","alt":"Il a mis une affiche au mur dans sa chambre.","note":"accrocher：挂，张贴；复合时态用 avoir。"}},
 "Une bande dessinée": {"pos":"n.f. 阴性名词，复数 bandes dessinées；缩写 BD [be.de]","s":"漫画（法语区的连环画，如 Tintin、Astérix）。日常简称 une BD，读 [be.de]。看漫画用 lire une BD。日本漫画一般说 un manga。","ipa":"[bɑ̃d de.si.ne]","ph":"bande 读 [bɑ̃d]，an 为 [ɑ̃]，d 要读出来；dessinée 读 [de.si.ne]，ss 在元音间读 [s]，é 读 [e]。","pi":"bande 的 d 要读出来 [bɑ̃d]。dessinée 有阴性 -e，因为 bande 是阴性，所以 dessiné 要加 e。BD 是阴性：une BD。","et":"字面是「画出来的长条」：bande（条带）+ dessinée（画出的，dessiner 的过去分词）。","ex":[["Je lis une bande dessinée.","我读漫画。"],["Il adore les bandes dessinées de Tintin.","他喜欢丁丁历险记漫画。"],["Elle achète une BD à la librairie.","她在书店买了一本漫画。"]],"co":[["lire une BD","读漫画"],["un auteur de bandes dessinées","漫画家"],["un album de BD","漫画册"],["un festival de la bande dessinée","漫画节"]],"sy":[["une BD","courant","漫画（简称）"],["un manga","courant","日本漫画"],["un comic","familier","美国漫画"]],"fq":"高频，日常常用。","me":"bande（条）+ dessinée（画出的）：一条一条的画。","tr":{"zh":"周末我喜欢读漫画。","fr":"Le week-end, j'aime lire des bandes dessinées.","alt":"Le week-end, j'aime bien lire des BD.","note":"aimer + 不定式 lire。"}},
 "Une capitale": {"pos":"n.f. 阴性名词，复数 capitales","s":"首都；省会。la capitale de la France = 法国首都。也可作形容词（阴性 lettre capitale）指大写字母。注意：le capital（阳性）是「资本」。","ipa":"[ka.pi.tal]","ph":"ca 读 [ka]；pi 读 [pi]；tal 读 [tal]，l 要读出来；三个音节。","pi":"capitale（城市）是阴性，capital（资本）是阳性。a 读 [a]，不是 [e]。l 在结尾要读出来。","et":"来自拉丁语 capitalis，源于 caput（头）。同族词：capitaine、chapitre。","ex":[["Paris est la capitale de la France.","巴黎是法国的首都。"],["Quelle est la capitale du Canada ?","加拿大的首都是哪里？"],["Lyon n'est pas la capitale.","里昂不是首都。"]],"co":[["la capitale de + 国家","……的首都"],["en lettres capitales","用大写字母"],["une capitale européenne","欧洲的首都"],["la capitale mondiale de la mode","世界时尚之都"]],"sy":[["un chef-lieu","soutenu","行政中心，省会"],["une métropole","courant","大都市"]],"fq":"高频，日常常用。","me":"capitale 来自 caput（头）：国家的「头」。","tr":{"zh":"你去过法国的首都吗？","fr":"Tu es déjà allé dans la capitale de la France ?","alt":"T'as déjà visité Paris, la capitale ?","note":"aller 的复合时态用 être。"}},
 "Une discussion": {"pos":"n.f. 阴性名词，复数 discussions","s":"讨论；谈话；有时也指争论。avoir une discussion avec quelqu'un = 和某人谈一谈（也可能有点争执）。Pas de discussion ! = 别争了！","ipa":"[dis.ky.sjɔ̃]","ph":"dis 读 [dis]，s 读 [s]；cus 读 [ky]，u 为 [y]，s 不发音；sion 读 [sjɔ̃]，结尾鼻化元音 [ɔ̃]。","pi":"u 读 [y]，不是 [u]。ssion 读 [sjɔ̃]，不是英语的 [ʃən]。结尾 n 不发音，只留鼻音。","et":"来自拉丁语 discussio（摇动，辨析），源于 discutere（拆开，细察）。动词 discuter 同族。","ex":[["Nous avons une discussion intéressante.","我们进行了有趣的讨论。"],["On a eu une longue discussion hier soir.","我们昨晚谈了很久。"],["Pas de discussion, il faut y aller !","别争了，必须去！"]],"co":[["avoir une discussion avec quelqu'un","和某人谈话"],["une discussion animée","热烈的讨论"],["sans discussion possible","毫无争议地"],["engager la discussion","开始讨论"]],"sy":[["une conversation","courant","对话，聊天"],["un débat","courant","辩论"],["une dispute","courant","争吵"]],"fq":"高频，日常常用。","me":"discussion：dis（分开）+ cuter：把事情「拆开」来谈。","tr":{"zh":"我们昨天有一场很有趣的讨论。","fr":"Hier, nous avons eu une discussion très intéressante.","alt":"Hier, on a eu une super discussion.","note":"avoir 的复合过去时：nous avons eu。"}},
 "Une fête": {"pos":"n.f. 阴性名词，复数 fêtes","s":"派对；节日；庆祝活动。faire la fête = 狂欢、热闹地玩；la fête des mères = 母亲节；Bonne fête ! 用来祝贺人过「圣名日」或节日。","ipa":"[fɛt]","ph":"ê 读 [ɛ]；结尾 t 要发音。","pi":"t 要发出来；别和 festival（艺术节）、vacances（假期）混淆。","et":"来自拉丁语 festa（节日），同源 festin（盛宴）、festival。","ex":[["Nous organisons une grande fête.","我们办一个大派对。"],["Bonne fête, maman !","妈妈，节日快乐！"]],"co":[["faire la fête","狂欢；尽情玩乐"],["une fête d'anniversaire","生日派对"],["la fête nationale","国庆日"]],"sy":[["soirée","courant","晚会，侧重晚上"],["célébration","soutenu","庆典，较正式"]],"fq":"高频，日常常用。","me":"fête 上有帽子 ê，像戴着派对帽。","tr":{"zh":"周六我们在我家办派对。","fr":"Samedi, nous faisons une fête chez moi.","alt":"Samedi, on fait la fête chez moi.","note":"faire une fête 办派对；faire la fête 玩得尽兴。"}},
 "Une figurine": {"pos":"n.f. 阴性名词，复数 figurines","s":"小人偶、手办、小雕像，可以是玩具，也可以是收藏品。也指棋类或游戏里的小人物模型。","ipa":"[fi.gy.ʁin]","ph":"u 读 [y]（嘴唇圆起发 i）；g 在 u 前读 [g]；r 是小舌音 [ʁ]；重音在最后一个音节。","pi":"gu 里的 u 要读 [y]，不能读成 [u]；结尾 e 不发音，n 不鼻化。","et":"来自 figure（形象、人像）加指小后缀 -ine，意思是「小人像」。","ex":[["J'ai une petite figurine sur mon bureau.","我书桌上有个小手办。"],["Il collectionne les figurines de super-héros.","他收集超级英雄手办。"]],"co":[["collectionner les figurines","收集手办"],["une figurine en bois","木制小人偶"]],"sy":[["statuette","courant","小雕像，偏艺术品"],["poupée","courant","娃娃，多指玩偶"]],"fq":"中低频，谈爱好时常用。","me":"figure（人像）+ -ine（小）= 小人像。","tr":{"zh":"我弟弟有很多小手办。","fr":"Mon frère a beaucoup de figurines.","alt":"Mon petit frère a plein de figurines.","note":"beaucoup de 后面直接接名词，不加冠词。"}},
 "Une forêt": {"pos":"n.f. 阴性名词，复数 forêts","s":"森林。比 bois（小树林）大。la forêt tropicale = 热带雨林。","ipa":"[fɔ.ʁɛ]","ph":"ê 读 [ɛ]；结尾 t 不发音。","pi":"结尾 t 不发音；重音符 ê 不能漏写；是阴性：la forêt。","et":"来自中古拉丁语 forestis (silva)，指「（国王圈定的）林区」。","ex":[["Nous marchons dans la forêt.","我们在森林里散步。"],["Il y a des cerfs dans cette forêt.","这片森林里有鹿。"]],"co":[["se promener en forêt","在森林里散步"],["la forêt tropicale","热带雨林"],["un feu de forêt","森林火灾"]],"sy":[["bois","courant","树林，比 forêt 小"],["jungle","courant","丛林，指热带"]],"fq":"高频，日常常用。","me":"forêt 里藏着 for-，想「大片树林」。","tr":{"zh":"我们周末去森林散步。","fr":"Ce week-end, nous nous promenons en forêt.","alt":"Ce week-end, on va se balader en forêt.","note":"「在森林里」常说 en forêt，不加冠词。"}},
 "Une île": {"pos":"n.f. 阴性名词，复数 îles","s":"岛。une île déserte = 荒岛；les îles = 群岛、海岛地区。","ipa":"[il]","ph":"î 读 [i]，帽子符号不改变读音；l 要发音；只有一个音节。","pi":"只读 [il]，不要读成 [ilə]；元音开头，前面要省音：l'île，une île 要连读。","et":"来自拉丁语 insula，古法语 isle，s 后来消失，留下帽子符号 î。","ex":[["Nous allons sur une île pour les vacances.","我们去一座岛上度假。"],["Cette île est très petite.","这座岛非常小。"]],"co":[["une île déserte","荒岛"],["sur une île","在岛上"],["l'île de la Réunion","留尼汪岛"]],"sy":[["îlot","courant","小岛、小块区域"]],"fq":"中高频。","me":"î 的帽子 = 当年消失的 s（isle）。","tr":{"zh":"我想住在一座岛上。","fr":"Je voudrais vivre sur une île.","alt":"J'aimerais habiter sur une île.","note":"说「在岛上」用 sur une île。"}},
 "Une joue": {"pos":"n.f. 阴性名词，复数 joues","s":"脸颊。tendre l'autre joue = 另一边脸也给人打（比喻忍让）。donner une bise sur la joue = 亲脸颊（法国人打招呼的方式）。","ipa":"[ʒu]","ph":"j 读 [ʒ]；ou 读 [u]；结尾 e 不发音。","pi":"j 不读 [dʒ] 也不读 [j]；ou 和 u [y] 要分清。","et":"来自拉丁语 gabata（碗）的变体，意义经「鼓起的腮」转到脸颊，不太确定细节。","ex":[["Il a une tache sur la joue.","他脸颊上有个斑。"],["Elle embrasse sa grand-mère sur la joue.","她亲了亲奶奶的脸颊。"]],"co":[["embrasser sur la joue","亲脸颊"],["les joues rouges","红扑扑的脸"],["rougir jusqu'aux joues","脸红到耳根"]],"sy":[["bajoue","courant","动物或松垂的腮"]],"fq":"中频。","me":"joue 读 [ʒu]，像「啾」一下亲脸颊。","tr":{"zh":"她的脸颊很红。","fr":"Elle a les joues rouges.","alt":"Ses joues sont toutes rouges.","note":"身体部位前常用定冠词：les joues。"}},
 "Une luge": {"pos":"n.f. 阴性名词，复数 luges","s":"雪橇（小型，坐着滑雪坡用的）。faire de la luge = 玩雪橇。也指奥运项目「单人雪橇」。","ipa":"[lyʒ]","ph":"u 读 [y]；g 在 e 前读 [ʒ]；结尾 e 不发音。","pi":"u 读 [y]，不是 [u]；g 读 [ʒ]，不是 [g]。","et":"来自萨瓦地区方言 (Savoie)，意义是「雪橇」。","ex":[["Les enfants font de la luge dans la neige.","孩子们在雪地里玩雪橇。"],["Il achète une luge rouge.","他买了一架红色雪橇。"]],"co":[["faire de la luge","玩雪橇"],["une piste de luge","雪橇滑道"]],"sy":[["traîneau","courant","拉货或载人的大雪橇"]],"fq":"低频，冬天话题常用。","me":"luge [lyʒ]：想象「噜~」地滑下去。","tr":{"zh":"冬天我们去山上玩雪橇。","fr":"En hiver, nous faisons de la luge à la montagne.","alt":"L'hiver, on fait de la luge en montagne.","note":"运动、活动用 faire de + 冠词。"}},
 "Une marinière": {"pos":"n.f. 阴性名词，复数 marinières","s":"条纹水手衫，蓝白条纹的针织上衣，法国的经典单品。也有「à la marinière」做法（白葡萄酒煮贻贝）。","ipa":"[ma.ʁi.njɛʁ]","ph":"ni 后接 è 时，ni 读 [nj]；r 小舌音；结尾 r 要发。","pi":"结尾 -ère 读 [ɛʁ]，不是「额」；r 要发。","et":"来自 marin（水手），加 -ière，原本指水手的衣服。","ex":[["Il porte une marinière bleue et blanche.","他穿一件蓝白相间的水手衫。"],["Elle met une marinière avec un jean.","她穿水手衫配牛仔裤。"]],"co":[["une marinière à rayures","条纹水手衫"],["moules à la marinière","水手式贻贝"]],"sy":[["pull rayé","courant","条纹毛衣"]],"fq":"低频，服装话题。","me":"marin（水手）+ -ière = 水手穿的上衣。","tr":{"zh":"我喜欢这件条纹水手衫。","fr":"J'aime cette marinière.","alt":"Elle me plaît, cette marinière.","note":"cette + 阴性名词。"}},
 "Une odeur": {"pos":"n.f. 阴性名词，复数 odeurs","s":"气味。可好可坏：une bonne / mauvaise odeur。注意：odeur 是阴性，虽然读音像阳性词。","ipa":"[o.dœʁ]","ph":"o 读 [o]；eu 读 [œ]（r 前开口）；结尾 r 要发。","pi":"是阴性：une odeur，不是 un odeur；eu 在 r 前读 [œ]。","et":"来自拉丁语 odor（气味）。同源：odorat（嗅觉）、désodorisant（除臭剂）。","ex":[["Cette fleur a une bonne odeur.","这朵花味道很好闻。"],["Il y a une mauvaise odeur ici.","这里有股臭味。"]],"co":[["une bonne / mauvaise odeur","好闻 / 难闻的气味"],["sentir une odeur","闻到气味"],["une odeur de brûlé","烧焦味"]],"sy":[["parfum","courant","香气，多为好闻"],["puanteur","soutenu","恶臭"]],"fq":"高频。","me":"odeur 有 odor，像英语 odor。","tr":{"zh":"我闻到一股咖啡的香味。","fr":"Je sens une odeur de café.","alt":"Ça sent le café ici.","note":"odeur de + 名词；另可用 ça sent + 名词。"}},
 "Une personne âgée": {"pos":"n.f. 阴性名词词组，复数 personnes âgées","s":"老人；年纪较大的人。比 un vieux / une vieille 礼貌。personne 永远是阴性，即使指男人。","ipa":"[pɛʁ.sɔn.a.ʒe]","ph":"per 读 [pɛʁ]；son 读 [sɔn]（nn 前不是鼻音）；âgée 读 [a.ʒe]，g 读 [ʒ]。","pi":"personne 的 -on- 不是鼻化音，要读 [sɔn]；âgée 的两个 e 都要写对（阴性）。","et":"personne 来自拉丁语 persona（面具、角色）；âgée 来自 âge（年龄）。","ex":[["J'aide une personne âgée.","我帮助一位老人。"],["Les personnes âgées prennent le bus.","老人们坐公共汽车。"]],"co":[["aider une personne âgée","帮助老人"],["les personnes âgées","老年人"],["une personne âgée de 80 ans","一位 80 岁的老人"]],"sy":[["senior","courant","老年人（较中性）"],["vieux / vieille","familier","老头 / 老太，可能不礼貌"]],"fq":"高频，礼貌用语。","me":"âgée = 有「岁数」的人，礼貌说法。","tr":{"zh":"请给这位老人让个座。","fr":"Cédez la place à cette personne âgée, s'il vous plaît.","alt":"Laissez votre place à cette personne âgée.","note":"cédez 是 vous 的命令式。"}},
 "Une photo de classe": {"pos":"n.f. 阴性名词词组，复数 photos de classe","s":"班级合照，毕业照。photo 是 photographie 的缩写，是阴性；de classe 不变复数。","ipa":"[fo.to.də.klas]","ph":"ph 读 [f]；o 读 [o]；de 读弱音 [də]；a 读 [a]，结尾 -sse 的 s 读 [s]。","pi":"ph 读 [f]；是阴性，la photo；photos de classe 里 classe 不加 s。","et":"photo 来自希腊语 phôs（光）+ graphein（写）；classe 来自拉丁语 classis（等级）。","ex":[["Je regarde ma photo de classe.","我看我的班级合照。"],["Sur la photo de classe, il est au premier rang.","班级合照上，他在第一排。"]],"co":[["prendre une photo","拍照"],["la photo de groupe","合影"],["au premier rang","在第一排"]],"sy":[["photo de groupe","courant","合影，范围更广"]],"fq":"中频。","me":"photo = 光 + 写；一张「班级的光影」。","tr":{"zh":"你在班级合照上吗？","fr":"Tu es sur la photo de classe ?","alt":"Tu es sur la photo de classe, toi ?","note":"「在照片上」用 sur la photo。"}},
 "Une tente": {"pos":"n.f. 阴性名词，复数 tentes","s":"帐篷。monter / planter une tente = 搭帐篷；démonter la tente = 拆帐篷。faire du camping sous la tente = 住帐篷露营。","ipa":"[tɑ̃t]","ph":"en 读鼻化音 [ɑ̃]；t 在结尾要读；e 不发音。","pi":"-en- 读 [ɑ̃]（和 un 不同）；结尾 t 要发。","et":"来自拉丁语 tendere（拉开、张开），因为帐篷是拉开的布。同源：tendre。","ex":[["Je monte la tente pour camper.","我搭帐篷露营。"],["Nous dormons sous la tente.","我们睡在帐篷里。"]],"co":[["monter la tente","搭帐篷"],["dormir sous la tente","睡在帐篷里"],["une tente de camping","露营帐篷"]],"sy":[["chapiteau","courant","马戏团大帐篷"]],"fq":"中频。","me":"tente ← tendre（拉开）：把布拉开就是帐篷。","tr":{"zh":"我们晚上在湖边搭帐篷。","fr":"Le soir, nous montons la tente au bord du lac.","alt":"Le soir, on plante la tente près du lac.","note":"搭帐篷用 monter 或 planter。"}},
 "Des billes": {"pos":"n.f.pl. 阴性复数名词，单数 une bille","s":"弹珠；玻璃球。jouer aux billes = 玩弹珠。une bille 也指滚珠轴承里的小钢珠。","ipa":"[bij]","ph":"ill 读 [ij]（像「依」）；结尾 es 不发音；des 读 [de]。","pi":"-ille 读 [ij]，不是 [il]；des 与 les 后元音不连读，要读清。","et":"来自古法语，意为「圆木段」，后来指圆球，不太确定。","ex":[["Il joue aux billes à l'école.","他在学校玩弹珠。"],["J'ai perdu une bille bleue.","我弄丢了一颗蓝弹珠。"]],"co":[["jouer aux billes","玩弹珠"],["un sac de billes","一袋弹珠"],["un stylo à bille","圆珠笔"]],"sy":[["boule","courant","球，更大"]],"fq":"低频，童年话题。","me":"bille = 比利玩弹珠，读 [bij]。","tr":{"zh":"孩子们在院子里玩弹珠。","fr":"Les enfants jouent aux billes dans la cour.","alt":"Les gamins jouent aux billes dans la cour.","note":"jouer à + 冠词 + 游戏名，jouer aux = jouer à les。"}},
 "Des bonbons": {"pos":"n.m.pl. 阳性复数名词，单数 un bonbon","s":"糖果；单数 un bonbon 是一颗糖。法国人也说 des bonbons 指各种甜食。des bonbons 是复数，说「吃糖」。","ipa":"[bɔ̃.bɔ̃]","ph":"on 读鼻化音 [ɔ̃]，两个 on 都鼻化；结尾 s 不发音。","pi":"bon-bon 不要读成 [bɔn.bɔn]，n 不发。","et":"来自 bon（好）重叠而成，儿语般的形成方式。","ex":[["J'aime manger des bonbons.","我喜欢吃糖。"],["Il offre un bonbon à sa sœur.","他给妹妹一颗糖。"]],"co":[["manger des bonbons","吃糖"],["un paquet de bonbons","一包糖"],["des bonbons à la menthe","薄荷糖"]],"sy":[["sucrerie","courant","甜食总称"],["friandise","courant","小零食、甜点"]],"fq":"高频，日常常用。","me":"bon + bon = 好好，所以是糖。","tr":{"zh":"我不想吃太多糖。","fr":"Je ne veux pas manger trop de bonbons.","alt":"Je ne veux pas trop manger de bonbons.","note":"trop de + 名词，不加冠词。"}},
 "Des jouets": {"pos":"n.m.pl. 阳性复数名词，单数 un jouet","s":"玩具。jouet 来自动词 jouer（玩）。des jouets en bois = 木制玩具。","ipa":"[ʒwɛ]","ph":"j 读 [ʒ]；ou 在元音前读 [w]；et 读 [ɛ]；结尾 s、t 都不发音。","pi":"结尾 t 与 s 不发音；ou+e 读 [wɛ]。","et":"来自 jouer（玩）加后缀 -et，源于拉丁语 jocare（开玩笑、玩）。","ex":[["Les enfants jouent avec des jouets.","孩子们玩玩具。"],["Range tes jouets, s'il te plaît.","请把你的玩具收好。"]],"co":[["ranger les jouets","收拾玩具"],["un jouet en bois","木制玩具"],["un magasin de jouets","玩具店"]],"sy":[["jeu","courant","游戏，也可指玩具"]],"fq":"高频。","me":"jouer + -et = 用来玩的小东西。","tr":{"zh":"圣诞节他收到很多玩具。","fr":"À Noël, il reçoit beaucoup de jouets.","alt":"À Noël, il a plein de jouets.","note":"beaucoup de + 名词。"}},
 "Les cinq sens": {"pos":"n.m.pl. 阳性复数名词，单数 le sens","s":"五种感官：la vue（视）、l'ouïe（听）、l'odorat（嗅）、le goût（味）、le toucher（触）。sens 还有「意思」「方向」的意思。","ipa":"[sɛ̃k.sɑ̃s]","ph":"cinq 在 sens 前读 [sɛ̃k]；sens 读 [sɑ̃s]，这里 s 要发；les 与 cinq 不连读。","pi":"sens 结尾 s 读出来 [sɑ̃s]（意思、感官）；cinq 在辅音前有时读 [sɛ̃]，这里读 [sɛ̃k]。","et":"来自拉丁语 sensus（感觉）。同源：sentir、sensible。","ex":[["Nous avons cinq sens.","我们有五种感官。"],["Le goût est l'un des cinq sens.","味觉是五种感官之一。"]],"co":[["la vue, l'ouïe, l'odorat","视觉、听觉、嗅觉"],["le goût, le toucher","味觉、触觉"],["le sixième sens","第六感"]],"sy":[["sensation","courant","感觉"]],"fq":"中频，学校课程用语。","me":"sens ← sentir：用感官去「感」。","tr":{"zh":"你用哪种感官？","fr":"Quel sens utilises-tu ?","alt":"Tu utilises quel sens ?","note":"quel + 阳性名词。"}},
 "Les couleurs": {"pos":"n.f.pl. 阴性复数名词，单数 la couleur","s":"颜色。口语中问颜色：De quelle couleur est…？ 颜色名称常放在名词后，不变阴阳性（如 orange, marron）。","ipa":"[ku.lœʁ]","ph":"ou 读 [u]；eu 读 [œ]（r 前）；r 小舌音；结尾 s 不发音。","pi":"couleur 是阴性；eu 在 r 前读 [œ]；les 后元音省音不要错。","et":"来自拉丁语 color。同源：colorier、coloré。","ex":[["J'aime toutes les couleurs.","我喜欢所有颜色。"],["De quelle couleur est ta voiture ?","你的车是什么颜色？"]],"co":[["de quelle couleur","什么颜色"],["une couleur vive","鲜艳的颜色"],["les couleurs chaudes / froides","暖色 / 冷色"]],"sy":[["teinte","soutenu","色调"],["nuance","courant","深浅变化"]],"fq":"极高频。","me":"couleur ≈ color，多了 u 和 eu。","tr":{"zh":"你最喜欢哪种颜色？","fr":"Quelle est ta couleur préférée ?","alt":"T'aimes quelle couleur le plus ?","note":"quelle + 阴性名词。"}},
 "Un baiser / Un bisou": {"pos":"n.m. 阳性名词，复数 baisers / bisous","s":"吻。un baiser 比较正式或浪漫；un bisou 口语，亲昵，常对孩子、家人用。信末 Gros bisous = 抱抱亲亲。注意 bise：脸颊轻吻（打招呼）。","ipa":"[bɛ.ze] / [bi.zu]","ph":"baiser：ai 读 [ɛ]，s 在元音间读 [z]；bisou：i 读 [i]，s 读 [z]，ou 读 [u]。","pi":"s 在元音间读 [z]；bisou 的复数是 bisous（加 s），不是 bisoux；baiser 作动词时是粗俗意思，避免用。","et":"baiser 来自拉丁语 basiare（亲吻）；bisou 是 baiser 的口语变体，来自 bise。","ex":[["Je donne un bisou à ma mère.","我亲了妈妈一下。"],["Il lui envoie un baiser de loin.","他远远给她一个飞吻。"]],"co":[["faire un bisou","亲一下"],["gros bisous","（信末）亲亲抱抱"],["un baiser sur la joue","脸颊上的一吻"]],"sy":[["bise","familier","脸颊轻吻"],["câlin","courant","拥抱"]],"fq":"高频，日常常用。","me":"bisou 读 [bi.zu]，像「必啾」的亲吻声。","tr":{"zh":"晚安，给你一个亲亲！","fr":"Bonne nuit, je te fais un bisou !","alt":"Bonne nuit, gros bisous !","note":"faire un bisou à qqn = 亲某人一下。"}},
 "Un(e) adolescent(e)": {"pos":"n.m./n.f. 名词，阳阴同形，adolescent / adolescente，复数 adolescents / adolescentes","s":"青少年（约 12 至 18 岁）。可作形容词：les années adolescentes。口语缩写 ado。","ipa":"[a.dɔ.lɛ.sɑ̃]","ph":"sc 在 e 前读 [s]；-ent 读鼻化音 [ɑ̃]；阴性 adolescente 读 [a.dɔ.lɛ.sɑ̃t]，t 要发。","pi":"阳性结尾 -ent 读 [ɑ̃]，t 不发；阴性 -ente 发 t；sc 读 [s]。","et":"来自拉丁语 adolescere（成长、长大），-ent 是现在分词词尾。","ex":[["Mon fils est un adolescent.","我儿子是个青少年。"],["Ma fille est une adolescente heureuse.","我女儿是个快乐的少女。"]],"co":[["un ado","青少年（口语）"],["l'adolescence","青春期"],["une crise d'adolescence","青春期叛逆"]],"sy":[["jeune","courant","年轻人，范围更广"],["ado","familier","adolescent 的缩写"]],"fq":"中高频。","me":"adolescent ≈ adolescent，只差读音。","tr":{"zh":"这个少年喜欢打篮球。","fr":"Cet adolescent aime jouer au basket.","alt":"Cet ado adore le basket.","note":"cet 用在元音开头的阳性名词前。"}},
 "Arrêter": {"pos":"v. 动词，第一组 -er，助动词 avoir，j'ai arrêté","s":"停止；使停下；逮捕。arrêter de + 动词原形 = 不再做……；arrêter qqn = 拦下某人、逮捕某人；s'arrêter = 自己停下。","ipa":"[a.ʁɛ.te]","ph":"rr 读一个 [ʁ]；ê 读 [ɛ]；结尾 -er 读 [e]。","pi":"arrêter de + 原形（不是 arrêter à）；s'arrêter 要用代词动词；ê 要写对。","et":"来自拉丁语 ad- + restare（留下），古法语 arester。同源：rester、arrêt（站）。","ex":[["Je dois arrêter de travailler.","我必须停止工作。"],["Le bus s'arrête devant l'école.","公共汽车停在学校门口。"]],"co":[["arrêter de + inf.","不再……"],["s'arrêter de + inf.","停下来不……"],["arrêter un voleur","抓住小偷"],["arrête !","停！"]],"sy":[["cesser","soutenu","停止，较书面"],["stopper","courant","停下（受英语影响）"]],"fq":"极高频。","me":"arrêter = 到站（arrêt）= 停。","tr":{"zh":"别再玩手机了！","fr":"Arrête de jouer avec ton téléphone !","alt":"Arrête de regarder ton portable !","note":"arrêter de + 原形；Arrête = tu 的命令式，去掉 s。"}},
 "Coudre": {"pos":"v. 动词，第三组，助动词 avoir，j'ai cousu","s":"缝，缝纫。je couds, tu couds, il coud, nous cousons, ils cousent。coudre un bouton = 缝纽扣。","ipa":"[kudʁ]","ph":"ou 读 [u]；dr 结尾，e 不发；只有一个音节。","pi":"不规则变位：il coud（无 e），nous cousons（s 读 [z]）；过去分词 cousu。","et":"来自拉丁语 consuere（缝合）。同源：couture（缝纫）、couturier（裁缝师）。","ex":[["Elle apprend à coudre.","她学习缝纫。"],["Je couds un bouton à ma chemise.","我给衬衫缝一颗纽扣。"]],"co":[["coudre un bouton","缝纽扣"],["une machine à coudre","缝纫机"],["du fil et une aiguille","针线"]],"sy":[["recoudre","courant","重新缝上"]],"fq":"中低频。","me":"coudre ~ couture（缝纫）：同一家族。","tr":{"zh":"你会缝纽扣吗？","fr":"Tu sais coudre un bouton ?","alt":"Tu sais recoudre un bouton ?","note":"savoir + 原形 = 会做。"}},
 "Cueillir": {"pos":"v. 动词，第三组（变位像 -er），助动词 avoir，j'ai cueilli","s":"采摘（花、果）。je cueille, tu cueilles, il cueille, nous cueillons。也有「迎接，接走」的意思：cueillir qqn à la gare。","ipa":"[kœ.jiʁ]","ph":"cue 读 [kœ]；ill 读 [j]；-ir 读 [iʁ]；u 保持让 c 读 [k]。","pi":"cueill 中 ue 先后顺序别拼错；je 的变位是 cueille（像 -er 动词，有 e）。","et":"来自拉丁语 colligere（收集）。同源：collecte、collection。","ex":[["Je vais cueillir des fleurs.","我去摘花。"],["Nous cueillons des pommes en automne.","我们秋天摘苹果。"]],"co":[["cueillir des fleurs","摘花"],["cueillir des fruits","摘水果"],["cueillir des champignons","采蘑菇"]],"sy":[["ramasser","courant","捡起、拾起"],["récolter","courant","收获"]],"fq":"中频。","me":"cueillir ~ collection：「收集」花。","tr":{"zh":"孩子们在田里摘草莓。","fr":"Les enfants cueillent des fraises dans le champ.","alt":"Les enfants ramassent des fraises dans le champ.","note":"cueillir 变位像 -er：ils cueillent。"}},
 "Mourir": {"pos":"v. 动词，第三组，助动词 être，il est mort","s":"死亡。je meurs, tu meurs, il meurt, nous mourons, ils meurent。mourir de faim / de froid / d'ennui = 饿死、冻死、无聊死（夸张口语）。","ipa":"[mu.ʁiʁ]","ph":"ou 读 [u]；r 小舌；结尾 -ir 读 [iʁ]，r 要发。","pi":"助动词用 être：il est mort，elle est morte；词干不规则：meurs / mourons。","et":"来自拉丁语 mori（死）。同源：mort、mortel。","ex":[["La plante va mourir sans eau.","没有水植物会死。"],["Je meurs de faim !","我饿死了！"]],"co":[["mourir de faim","饿死；非常饿"],["mourir de rire","笑死"],["mourir de peur","吓死"]],"sy":[["décéder","soutenu","去世，正式"],["disparaître","courant","消失，也婉转指死"]],"fq":"高频，日常夸张说法很多。","me":"mourir ~ mortal（会死的）。","tr":{"zh":"我累死了！","fr":"Je meurs de fatigue !","alt":"Je suis mort de fatigue !","note":"mourir de + 名词，表示程度极强。"}},
 "Raconter": {"pos":"v. 动词，第一组 -er，助动词 avoir，j'ai raconté","s":"讲述，叙述（故事、经历）。raconter une histoire à qqn = 给某人讲故事；Qu'est-ce que tu racontes ? = 你在说什么呀（口语，也可表示不信）。","ipa":"[ʁa.kɔ̃.te]","ph":"r 小舌音；on 读鼻化音 [ɔ̃]；结尾 -er 读 [e]。","pi":"raconter 不是 dire：raconter 讲的是有情节的内容；on 鼻化，n 不发。","et":"来自 re- + 古法语 aconter（计算、叙述），源于 conter（讲）。","ex":[["Elle raconte une belle histoire.","她讲了一个美丽的故事。"],["Raconte-moi ta journée.","跟我讲讲你的一天。"]],"co":[["raconter une histoire","讲故事"],["raconter sa vie","说起自己的人生"],["Qu'est-ce que tu racontes ?","你在说什么呀？"]],"sy":[["conter","littéraire","讲述（书面）"],["narrer","soutenu","叙述"]],"fq":"高频。","me":"re- + conter：把故事「再讲」一遍。","tr":{"zh":"给我讲讲你的假期。","fr":"Raconte-moi tes vacances.","alt":"Dis-moi comment étaient tes vacances.","note":"命令式 + moi，用连字符。"}},
 "Retourner": {"pos":"v. 动词，第一组 -er，不及物用助动词 être (je suis retourné)，及物用 avoir","s":"回去，返回（到去过的地方）；翻转。retourner à Paris = 回巴黎；retourner la carte = 把牌翻过来。","ipa":"[ʁə.tuʁ.ne]","ph":"re 读弱音 [ʁə]；our 读 [uʁ]；结尾 -er 读 [e]。","pi":"retourner 是「回到去过的地方」，不同于 rentrer（回家）；不及物时助动词 être。","et":"来自 re- + tourner（转），字面义「再转回去」。","ex":[["Je vais retourner à la maison.","我要回家。"],["Elle est retournée au bureau.","她回办公室了。"]],"co":[["retourner à + 地点","回到某地"],["retourner une carte","翻牌"],["se retourner","转身"]],"sy":[["revenir","courant","回来（朝说话人）"],["rentrer","courant","回家"]],"fq":"高频。","me":"re- + tourner = 再转回。","tr":{"zh":"明年我想回意大利。","fr":"L'année prochaine, je voudrais retourner en Italie.","alt":"L'an prochain, j'aimerais retourner en Italie.","note":"国家名阴性 + en：en Italie。"}},
 "Rire": {"pos":"v. 动词，第三组，助动词 avoir，j'ai ri","s":"笑。je ris, tu ris, il rit, nous rions, ils rient。rire de qqn = 嘲笑某人；rire aux éclats = 哈哈大笑。","ipa":"[ʁiʁ]","ph":"两个 r 都是小舌音 [ʁ]；i 读 [i]；一个音节。","pi":"过去分词 ri（没有 t）；rire de qqn 带有嘲笑的意思；le rire 作名词也是「笑声」。","et":"来自拉丁语 ridere（笑）。同源：ridicule、sourire。","ex":[["J'aime rire avec mes amis.","我喜欢和朋友们笑。"],["Ils rient très fort.","他们笑得很大声。"]],"co":[["rire aux éclats","放声大笑"],["rire de qqn","嘲笑某人"],["rire de bon cœur","开怀大笑"],["éclater de rire","忍不住笑出来"]],"sy":[["sourire","courant","微笑"],["rigoler","familier","笑；开玩笑"]],"fq":"高频。","me":"rire 开头结尾都是 r：两头「拉」嘴角。","tr":{"zh":"这部电影让我们大笑。","fr":"Ce film nous fait rire.","alt":"Ce film nous a bien fait rire.","note":"faire rire qqn = 逗某人笑。"}},
 "Rougir": {"pos":"v. 动词，第二组 -ir，助动词 avoir，j'ai rougi","s":"脸红；变红。可因害羞、尴尬、生气。rougir de honte = 羞得脸红。变位：je rougis, nous rougissons。","ipa":"[ʁu.ʒiʁ]","ph":"ou 读 [u]；g 在 i 前读 [ʒ]；r 结尾要发。","pi":"第二组变位有 -iss-：nous rougissons；g 读 [ʒ]。","et":"来自 rouge（红）加 -ir，字面义「变红」。","ex":[["Il commence à rougir.","他开始脸红。"],["Elle rougit quand on la regarde.","有人看她时她就脸红。"]],"co":[["rougir de honte","羞红了脸"],["rougir de plaisir","高兴得脸红"],["faire rougir qqn","让某人脸红"]],"sy":[["s'empourprer","littéraire","脸涨红"]],"fq":"中低频。","me":"rouge + -ir = 变红。","tr":{"zh":"她一说话就脸红。","fr":"Elle rougit dès qu'elle parle.","alt":"Elle rougit quand elle prend la parole.","note":"dès que + 直陈式：一……就……。"}},
 "S'amuser": {"pos":"v. 代词动词，第一组 -er，助动词 être，je me suis amusé(e)","s":"玩得开心，找乐子。s'amuser à + 原形 = 玩着做……；Amuse-toi bien ! = 玩得开心！","ipa":"[sa.my.ze]","ph":"u 读 [y]；s 在元音间读 [z]；结尾 -er 读 [e]；s' 与 amuser 连读。","pi":"u 读 [y]；代词要变：je m'amuse, tu t'amuses, nous nous amusons。","et":"来自 amuser（逗乐），原义含「使消遣」，词源不太确定。","ex":[["Les enfants s'amusent bien.","孩子们玩得很开心。"],["Amuse-toi bien à la fête !","在派对上玩得开心！"]],"co":[["s'amuser bien","玩得很开心"],["Amuse-toi bien !","玩得开心！"],["s'amuser à + inf.","玩着做……"]],"sy":[["se divertir","soutenu","消遣"],["rigoler","familier","笑闹、玩"]],"fq":"高频。","me":"s'amuser ~ amusing：给自己找乐子。","tr":{"zh":"我们在海边玩得很开心。","fr":"Nous nous sommes bien amusés à la mer.","alt":"On s'est bien amusés à la mer.","note":"代词动词的过去分词和主语一致。"}},
 "S'asseoir": {"pos":"v. 代词动词，第三组，助动词 être，je me suis assis(e)","s":"坐下（动作）。je m'assieds / je m'assois, nous nous asseyons / assoyons。Asseyez-vous ! = 请坐。动作用 s'asseoir，状态用 être assis。","ipa":"[sa.swaʁ]","ph":"s'as 连读，ss 读 [s]；eoi 读 [wa]；结尾 -oir 读 [waʁ]，r 要发。","pi":"拼写 asseoir 里的 e 不发音；变位不规则，两种形式皆可；过去分词 assis。","et":"来自拉丁语 assidere（坐在旁边），同源 siège。","ex":[["Vous pouvez vous asseoir ici.","您可以坐在这里。"],["Assieds-toi, je t'en prie.","请坐。"]],"co":[["asseyez-vous","请坐（vous）"],["être assis","坐着（状态）"],["s'asseoir par terre","坐在地上"]],"sy":[["se mettre assis","familier","坐下，不太标准"]],"fq":"高频。","me":"asseoir 里 eoi 读 [wa]，像「挖」。","tr":{"zh":"请坐，我马上来。","fr":"Asseyez-vous, j'arrive tout de suite.","alt":"Installez-vous, j'arrive.","note":"命令式代词 vous 放在动词后。"}},
 "Se rappeler": {"pos":"v. 代词动词，第一组，助动词 être，je me suis rappelé(e)","s":"记得，想起。标准用法是直接接宾语：se rappeler quelque chose。口语里常说 se rappeler de，被很多人接受，但规范语法不推荐。","ipa":"[sə.ʁa.ple]","ph":"se 读弱音 [sə]；pp 读一个 [p]；结尾 -er 读 [e]。","pi":"je me rappelle ce jour（直接宾语）；je me souviens de ce jour（用 de）；两者不要混。","et":"由 re- + appeler（叫）组成，字面义「再叫回来」。","ex":[["Je me rappelle ce jour.","我记得那一天。"],["Tu te rappelles son nom ?","你记得他的名字吗？"]],"co":[["se rappeler qqch","记得某事"],["se rappeler que + 句子","想起……"],["Rappelle-moi demain.","明天再提醒我。"]],"sy":[["se souvenir de","courant","记得，用 de"],["se remémorer","soutenu","回想"]],"fq":"高频。","me":"re- + appeler：把记忆「叫回来」。","tr":{"zh":"我不记得他的名字了。","fr":"Je ne me rappelle plus son nom.","alt":"Je ne me souviens plus de son nom.","note":"se rappeler 后不加 de。"}},
 "Se souvenir": {"pos":"v. 代词动词，第三组，助动词 être，je me suis souvenu(e)","s":"记得，想起。结构：se souvenir de + 名词；se souvenir que + 句子。变位像 venir：je me souviens, nous nous souvenons。","ipa":"[sə.suv.niʁ]","ph":"se 读弱音 [sə]；ou 读 [u]；结尾 -ir 读 [iʁ]。","pi":"后面必须接 de：je me souviens de toi；变位像 venir，不是规则 -ir。","et":"来自拉丁语 subvenire（来到心里）。同源：venir、souvenir（纪念品；回忆）。","ex":[["Je me souviens de toi.","我记得你。"],["Il se souvient de son enfance.","他记得自己的童年。"]],"co":[["se souvenir de qqn / qqch","记得某人 / 某事"],["se souvenir que + 句子","记得……"],["je m'en souviens","我记得这个"]],"sy":[["se rappeler","courant","记得，直接接宾语"],["garder en mémoire","courant","记在心里"]],"fq":"高频。","me":"souvenir 也是名词「回忆」：souvenir ← venir 来。","tr":{"zh":"你还记得我们的第一次见面吗？","fr":"Tu te souviens de notre première rencontre ?","alt":"Tu te rappelles notre première rencontre ?","note":"se souvenir de + 名词。"}},
 "Sembler": {"pos":"v. 动词，第一组 -er，助动词 avoir，il a semblé","s":"似乎，看起来。il semble + 形容词 / que + 虚拟式或直陈式。Il me semble que… = 我觉得……（带有主观判断）。","ipa":"[sɑ̃.ble]","ph":"sem 读鼻化音 [sɑ̃]；mb 里 m 不发，ble 读 [ble]；结尾 -er 读 [e]。","pi":"sem- 读 [sɑ̃]，m 不发；sembler 后面直接接形容词，不加 être。","et":"来自拉丁语 similare（相似），同源 ressembler（像）、ensemble。","ex":[["Il semble fatigué.","他看起来很累。"],["Il me semble que tu as raison.","我觉得你是对的。"]],"co":[["il semble que + 句子","似乎……"],["sembler + 形容词","看起来……"],["Il me semble que…","我觉得……"]],"sy":[["paraître","courant","显得、看起来"],["avoir l'air","courant","看上去像"]],"fq":"中高频。","me":"sembler ~ resemble（像）。","tr":{"zh":"这个问题看起来很难。","fr":"Cette question semble difficile.","alt":"Cette question a l'air difficile.","note":"sembler + 形容词，形容词与主语一致。"}},
 "Sentir": {"pos":"v. 动词，第三组，助动词 avoir，j'ai senti","s":"闻到；感觉到；散发气味。je sens, tu sens, il sent, nous sentons。Ça sent bon = 闻起来很香；se sentir bien = 觉得舒服。","ipa":"[sɑ̃.tiʁ]","ph":"sen 读鼻化音 [sɑ̃]；t 读 [t]；结尾 -ir 读 [iʁ]。","pi":"三种用法：闻到（sentir qqch）、感觉到、散发（sentir bon）；je sens 是不规则变位，少了 t。","et":"来自拉丁语 sentire（感觉）。同源：sentiment、sens。","ex":[["Je sens une odeur bizarre dans la cuisine...","我在厨房里闻到一股怪味……"],["Je me sens très bien ici.","我在这里感觉很好。"]],"co":[["sentir bon / mauvais","闻起来香 / 臭"],["se sentir bien / mal","感觉好 / 不舒服"],["sentir le café","有咖啡味"],["sentir que + 句子","觉得……"]],"sy":[["humer","soutenu","吸气闻"],["ressentir","courant","感受（情感）"]],"fq":"极高频。","me":"sentir ~ sentiment：用感官去「感」。","tr":{"zh":"你闻到什么味道吗？","fr":"Tu sens quelque chose ?","alt":"Ça sent quoi, ici ?","note":"sentir qqch = 闻到，sentir bon = 闻着香。"}},
 "Toucher": {"pos":"v. 动词，第一组 -er，助动词 avoir，j'ai touché","s":"触摸，碰；也指打动、领取。toucher à qqch = 动某物；toucher de l'argent = 领钱；être touché = 被感动。","ipa":"[tu.ʃe]","ph":"ou 读 [u]；ch 读 [ʃ]；结尾 -er 读 [e]。","pi":"toucher qqch（碰到）和 toucher à qqch（动，摸索）不同；ch 读 [ʃ]。","et":"来自拉丁语 toccare（击打）的拟声词，起源不太确定。","ex":[["Ne pas toucher, s'il vous plaît.","请勿触摸。"],["Son histoire m'a beaucoup touché.","他的故事让我很感动。"]],"co":[["toucher à tout","什么都碰"],["toucher le salaire","领工资"],["Touchez du bois !","（敲木头）保佑别出事！"]],"sy":[["effleurer","soutenu","轻触"],["émouvoir","soutenu","感动"]],"fq":"高频。","me":"toucher = 「吐吸」：一碰就知道。","tr":{"zh":"不要摸这个，会烫手。","fr":"Ne touche pas ça, c'est chaud.","alt":"Touche pas ça, ça brûle !","note":"否定命令式：ne + 动词 + pas。"}},
 "Accessible": {"pos":"adj. 形容词，阴阳同形，复数 accessibles","s":"可到达的；无障碍的；容易理解的。accessible à tous = 人人可用。也指价格亲民：un prix accessible。","ipa":"[ak.sɛ.sibl]","ph":"cc 读 [ks]；ss 读 [s]；结尾 -ible 读 [ibl]，e 不发。","pi":"cc 读 [ks]；accessible à + 人；结尾 e 不发。","et":"来自拉丁语 accedere（走近）。同源：accès。","ex":[["Ce bâtiment est accessible à tous.","这栋楼人人可以进入。"],["Le prix est accessible.","价格很亲民。"]],"co":[["accessible à tous","人人可用"],["accessible en fauteuil roulant","轮椅可进入"],["un prix accessible","亲民的价格"]],"sy":[["abordable","courant","价格或人容易接近"],["inaccessible","courant","（反义）无法到达"]],"fq":"中高频。","me":"accessible ≈ accessible，几乎一样。","tr":{"zh":"这个博物馆对轮椅使用者无障碍。","fr":"Ce musée est accessible aux personnes en fauteuil roulant.","alt":"On peut entrer dans ce musée en fauteuil roulant.","note":"accessible à + 人。"}},
 "Authentique": {"pos":"adj. 形容词，阴阳同形，复数 authentiques","s":"真正的，正宗的，真实的。un restaurant authentique = 地道餐馆；un tableau authentique = 真迹。","ipa":"[o.tɑ̃.tik]","ph":"au 读 [o]；th 读 [t]；en 读 [ɑ̃]；结尾 -ique 读 [ik]。","pi":"th 读 [t]，不是 [θ]；au 读 [o]。","et":"来自希腊语 authentikos（真正的）。","ex":[["C'est un restaurant authentique.","这是一家正宗的餐厅。"],["Cette cuisine est vraiment authentique.","这种烹饪非常地道。"]],"co":[["un plat authentique","地道的菜"],["un document authentique","真实文件"],["un tableau authentique","真迹"]],"sy":[["vrai","courant","真的"],["original","courant","原版的"]],"fq":"中频。","me":"authentique ≈ authentic，th 读 t。","tr":{"zh":"我想吃正宗的法国菜。","fr":"Je voudrais manger de la cuisine française authentique.","alt":"J'aimerais goûter une vraie cuisine française.","note":"de la cuisine（部分冠词）。"}},
 "Complet / Complète": {"pos":"adj. 形容词，阳 complet / 阴 complète，复数 complets / complètes","s":"完整的；满的；丰盛的。Complet ! = 客满。un petit-déjeuner complet = 丰盛早餐。","ipa":"[kɔ̃.plɛ] / [kɔ̃.plɛt]","ph":"om 读鼻化音 [ɔ̃]；阳性结尾 t 不发；阴性 -ète 读 [ɛt]，t 要发。","pi":"阴性有重音 è：complète；阳性 t 不发。","et":"来自拉丁语 completus（充满的），同源 compléter。","ex":[["Mon petit-déjeuner est complet.","我的早餐很丰盛。"],["L'hôtel est complet ce soir.","今晚旅馆客满。"]],"co":[["un repas complet","完整的一餐"],["Complet !","（客）满了"],["un nom complet","全名"]],"sy":[["plein","courant","满的"],["entier","courant","整个的"]],"fq":"高频。","me":"complet ≈ complete；阴性多 è 加 t。","tr":{"zh":"这个房间已经客满了。","fr":"Cette salle est complète.","alt":"C'est complet pour ce soir.","note":"阴性 salle → complète。"}},
 "Couvert(e)": {"pos":"adj. 形容词，阳 couvert / 阴 couverte，复数 couverts / couvertes","s":"有云的，阴的；被覆盖的。Le ciel est couvert = 天阴了。couvert de + 名词 = 被……覆盖。也有名词 le couvert（餐具）。","ipa":"[ku.vɛʁ] / [ku.vɛʁt]","ph":"ou 读 [u]；ert 读 [ɛʁ]；阳性 t 不发，阴性 t 要发。","pi":"couvert 阳性 t 不发；是 couvrir 的过去分词；与 nuageux 区分。","et":"来自 couvrir（覆盖），源于拉丁语 cooperire。","ex":[["Le ciel est couvert.","天空是阴的。"],["La montagne est couverte de neige.","山上覆盖着雪。"]],"co":[["le ciel est couvert","天阴了"],["couvert de neige","被雪覆盖"],["mettre le couvert","摆餐具"]],"sy":[["nuageux","courant","多云的"],["gris","courant","灰蒙蒙的"]],"fq":"中高频。","me":"couvert = 云把天空「盖」住。","tr":{"zh":"今天天空阴沉沉的。","fr":"Aujourd'hui, le ciel est couvert.","alt":"Aujourd'hui, c'est tout gris.","note":"天气描述：le ciel est + 形容词。"}},
 "Ensoleillé(e)": {"pos":"adj. 形容词，阳 ensoleillé / 阴 ensoleillée，复数 ensoleillés / ensoleillées","s":"阳光明媚的，日照充足的。une journée ensoleillée = 晴天；une pièce ensoleillée = 向阳的房间。","ipa":"[ɑ̃.sɔ.le.je]","ph":"en 读 [ɑ̃]；sol 读 [sɔl]，l 与 e 连接成 [sɔ.le]；eill 读 [ɛj]，此处 [le.je]。","pi":"拼写长，别漏掉 ll 和 ei；是 soleil 的派生，需要阴性 -ée。","et":"来自 soleil（太阳），加前缀 en- 与后缀 -é。","ex":[["Il fait un temps ensoleillé.","天气晴朗。"],["C'est une journée ensoleillée.","这是一个晴天。"]],"co":[["une journée ensoleillée","晴朗的一天"],["un temps ensoleillé","晴朗的天气"],["une pièce ensoleillée","向阳的房间"]],"sy":[["clair","courant","晴朗的"],["radieux","soutenu","阳光灿烂的"]],"fq":"中频，天气话题。","me":"en + soleil + -é = 有太阳的。","tr":{"zh":"明天会是晴天。","fr":"Demain, la journée sera ensoleillée.","alt":"Demain, il y aura du soleil.","note":"天气可用 il y aura du soleil。"}},
 "Frais / Fraîche": {"pos":"adj. 形容词，阳 frais / 阴 fraîche，复数 frais / fraîches","s":"凉爽的；新鲜的；清新的。de l'eau fraîche = 凉水；un légume frais = 新鲜蔬菜；Il fait frais = 天气凉爽。","ipa":"[fʁɛ] / [fʁɛʃ]","ph":"ai / aî 读 [ɛ]；阳性结尾 s 不发；阴性 -che 读 [ʃ]。","pi":"阴性不规则：fraîche；复数阳性 frais 不变；les frais（费用）是另一个词。","et":"来自法兰克语 frisk（新鲜的）。同源英语 fresh。","ex":[["L'eau est très fraîche.","水很凉。"],["Je cherche du pain frais.","我在找新鲜的面包。"]],"co":[["il fait frais","天气凉爽"],["du pain frais","新鲜面包"],["de l'eau fraîche","凉水"],["servir frais","冰镇后饮用"]],"sy":[["froid","courant","冷的"],["récent","courant","新近的"]],"fq":"高频。","me":"frais ≈ fresh：同源。","tr":{"zh":"这瓶水很凉，真好。","fr":"Cette eau est bien fraîche, c'est bon.","alt":"Elle est bien fraîche, cette eau !","note":"阴性 eau → fraîche。"}},
 "Heureux / Heureuse": {"pos":"adj. 形容词，阳 heureux / 阴 heureuse，复数 heureux / heureuses","s":"幸福的，快乐的，高兴的。être heureux de + 原形 = 很高兴做……。比 content（满意）更强，比 joyeux 更日常。","ipa":"[œ.ʁø] / [œ.ʁøz]","ph":"h 不发音（哑 h）；eu 在词首读 [œ]，结尾读 [ø]；阴性 -se 读 [z]。","pi":"h 不发音，可与前面元音连读：un heureux enfant；阴性 heureuse 的 s 读 [z]。","et":"来自 heur（运气，源于拉丁语 augurium）加 -eux。同源：bonheur（幸福）、malheur（不幸）。","ex":[["Je suis très heureux aujourd'hui.","我今天很开心。"],["Elle est heureuse de te voir.","她很高兴见到你。"]],"co":[["heureux de + inf.","很高兴……"],["Heureusement !","幸好！"],["Heureux anniversaire !","（较少）生日快乐"],["une vie heureuse","幸福的生活"]],"sy":[["content","courant","满意的、高兴的"],["triste","courant","（反义）难过的"]],"fq":"高频。","me":"heur（好运）+ eux = 有好运的人。","tr":{"zh":"我很高兴认识你。","fr":"Je suis heureux de te connaître.","alt":"Ravi de te connaître !","note":"女生说 heureuse。"}},
 "Incroyable": {"pos":"adj. 形容词，阴阳同形，复数 incroyables","s":"难以置信的；不可思议的；了不起的。可好可坏：Incroyable ! = 太神了！/ 太离谱了！","ipa":"[ɛ̃.kʁwa.jabl]","ph":"in 读 [ɛ̃]；oy 读 [waj]；结尾 -able 读 [abl]，e 不发。","pi":"oy 读 [waj]；in 读 [ɛ̃]，不是 [in]；il / elle 同形。","et":"由 in- （否定）+ croyable（可信的）构成，croire（相信）。","ex":[["Cette histoire est incroyable !","这个故事太不可思议了！"],["Il a une chance incroyable.","他运气好得惊人。"]],"co":[["une histoire incroyable","难以置信的故事"],["Incroyable mais vrai !","难以置信但是真的！"],["un talent incroyable","惊人的才能"]],"sy":[["extraordinaire","courant","非凡的"],["génial","familier","很棒的"]],"fq":"高频，口语常用。","me":"in- + croyable = 不能相信。","tr":{"zh":"这个风景太美了，难以置信！","fr":"Ce paysage est incroyable !","alt":"Ce paysage est trop beau, c'est incroyable !","note":"感叹句可直接用形容词。"}},
 "Inoubliable": {"pos":"adj. 形容词，阴阳同形，复数 inoubliables","s":"难忘的。常用来形容旅行、夏天、相遇等。由 in- + oubliable 构成。","ipa":"[i.nu.bli.jabl]","ph":"in 在元音前读 [i.n]；ou 读 [u]；bli 读 [bli]；-able 读 [abl]。","pi":"inoubliable 里 in- 要读 [i.n]，不是鼻化；拼写别漏 ou。","et":"由 in- + oublier（忘记）+ -able 构成。","ex":[["Ce voyage était inoubliable.","这次旅行令人难忘。"],["Nous avons passé un été inoubliable.","我们度过了难忘的夏天。"]],"co":[["un souvenir inoubliable","难忘的回忆"],["un moment inoubliable","难忘的时刻"],["une soirée inoubliable","难忘的夜晚"]],"sy":[["mémorable","soutenu","值得记住的"],["marquant","courant","令人印象深刻的"]],"fq":"中频。","me":"in + oublier + able = 无法被忘记。","tr":{"zh":"那是一个难忘的夜晚。","fr":"C'était une soirée inoubliable.","alt":"Quelle soirée inoubliable !","note":"过去描述用未完成过去时 c'était。"}},
 "Jeune": {"pos":"adj. 形容词，阴阳同形，复数 jeunes；也可作名词 un jeune","s":"年轻的，年少的。plus jeune = 更年轻；les jeunes = 年轻人。反义 vieux。jeune 放名词前：un jeune homme。","ipa":"[ʒœn]","ph":"j 读 [ʒ]；eu 读 [œ]（n 前）；结尾 -e 不发，n 读出。","pi":"j 读 [ʒ]；eu 在这里读 [œ]；阴阳同形：une jeune fille。","et":"来自拉丁语 juvenis（年轻人），同源 juvénile、rajeunir。","ex":[["Mon frère est très jeune.","我弟弟很小。"],["Elle est plus jeune que moi.","她比我年轻。"]],"co":[["un jeune homme","年轻男子"],["une jeune fille","年轻女孩"],["les jeunes","年轻人"],["plus jeune que","比……年轻"]],"sy":[["petit","courant","年纪小的"],["vieux","courant","（反义）老的"]],"fq":"极高频。","me":"jeune ≈ juvenile；j 读 [ʒ]。","tr":{"zh":"她比她哥哥年轻三岁。","fr":"Elle est plus jeune que son frère de trois ans.","alt":"Elle a trois ans de moins que son frère.","note":"plus … que 比较。"}},
 "Local(e)": {"pos":"adj. 形容词，阳 local / 阴 locale，阳性复数 locaux，阴性复数 locales","s":"当地的，本地的。un produit local = 本地产品；les habitants locaux = 当地居民。阳性复数是 locaux。名词 un local = 场所、房间。","ipa":"[lɔ.kal]","ph":"o 读 [ɔ]；c 读 [k]；a 读 [a]；阴性 locale 读 [lɔ.kal]，发音同阳性。","pi":"阳性复数 locaux（-al → -aux）；阴性 locale 只多一个 e，读音不变。","et":"来自拉丁语 localis，同源 lieu（地方）、localiser。","ex":[["J'achète un produit local.","我买本地产品。"],["Nous mangeons dans un restaurant local.","我们在一家本地餐厅吃饭。"]],"co":[["un produit local","本地产品"],["les produits locaux","本地产品（复数）"],["l'heure locale","当地时间"],["une spécialité locale","当地特产"]],"sy":[["régional","courant","地区的"],["du coin","familier","附近的"]],"fq":"中高频。","me":"local ≈ local，复数记得 -aux。","tr":{"zh":"我喜欢买本地的蔬菜。","fr":"J'aime acheter des légumes locaux.","alt":"J'achète des légumes du coin.","note":"阳性复数 locaux。"}},
 "Neutre": {"pos":"adj. 形容词，阴阳同形，复数 neutres","s":"中性的；中立的；不带倾向的。une couleur neutre = 中性色（白、灰、米色）；rester neutre = 保持中立；le genre neutre 在法语里不存在。","ipa":"[nøtʁ]","ph":"eu 读 [ø]；tr 结尾，e 不发音，只读 [tʁ]。","pi":"eu 读 [ø]（开口小）；结尾 -tre 要读 [tʁ]，容易漏掉。","et":"来自拉丁语 neuter（两者都不是），同源 neutraliser。","ex":[["Cette couleur est neutre.","这个颜色很中性。"],["Il reste neutre dans la discussion.","他在讨论中保持中立。"]],"co":[["une couleur neutre","中性色"],["rester neutre","保持中立"],["un pays neutre","中立国"]],"sy":[["impartial","soutenu","公正的"],["objectif","courant","客观的"]],"fq":"中频。","me":"neutre ≈ neutral，ne- + uter。","tr":{"zh":"我想要一个中性色的包。","fr":"Je voudrais un sac de couleur neutre.","alt":"Je cherche un sac neutre, beige ou gris.","note":"de couleur neutre：颜色形容词放后。"}},
 "Pluvieux / Pluvieuse": {"pos":"adj. 形容词，阳 pluvieux / 阴 pluvieuse，复数 pluvieux / pluvieuses","s":"多雨的，下雨的。une journée pluvieuse = 雨天；un temps pluvieux = 雨天气。平时多说 Il pleut（在下雨）。","ipa":"[ply.vjø] / [ply.vjøz]","ph":"u 读 [y]；vi 在 eu 前读 [vj]；阳性 eux 读 [ø]；阴性 -se 读 [z]。","pi":"u 读 [y]；阳性 x 不发；阴性 s 读 [z]。","et":"来自拉丁语 pluviosus，同源 pluie（雨）、pleuvoir。","ex":[["C'est une journée pluvieuse.","这是一个多雨的日子。"],["L'automne est souvent pluvieux.","秋天常常多雨。"]],"co":[["une journée pluvieuse","雨天"],["un temps pluvieux","多雨的天气"],["une saison pluvieuse","雨季"]],"sy":[["humide","courant","潮湿的"],["sec","courant","（反义）干燥的"]],"fq":"中频。","me":"pluie + -eux = 有雨的。","tr":{"zh":"这个星期很多雨。","fr":"Cette semaine est très pluvieuse.","alt":"Il pleut beaucoup cette semaine.","note":"平时更常说 Il pleut。"}},
 "Quotidien(ne)": {"pos":"adj. 形容词，阳 quotidien / 阴 quotidienne，复数 quotidiens / quotidiennes","s":"每天的，日常的。la vie quotidienne = 日常生活；un quotidien（名词）= 日报。","ipa":"[kɔ.ti.djɛ̃] / [kɔ.ti.djɛn]","ph":"qu 读 [k]；dien 读 [djɛ̃]；阳性 -ien 为鼻化音；阴性 -ienne 读 [jɛn]，n 要发。","pi":"阳性 n 不发；阴性 nn 读 [n]；与 journalier 的含义接近。","et":"来自拉丁语 quotidianus（每日的），同源 cotidie。","ex":[["C'est mon travail quotidien.","这是我的日常工作。"],["La vie quotidienne est parfois difficile.","日常生活有时很不容易。"]],"co":[["la vie quotidienne","日常生活"],["un geste quotidien","日常动作"],["le quotidien","日常；日报"]],"sy":[["journalier","soutenu","每日的"],["habituel","courant","习惯性的"]],"fq":"中高频。","me":"quotidien ← 拉丁语「每天」。","tr":{"zh":"运动是我日常生活的一部分。","fr":"Le sport fait partie de ma vie quotidienne.","alt":"Je fais du sport tous les jours.","note":"faire partie de = 是……一部分。"}},
 "Spectaculaire": {"pos":"adj. 形容词，阴阳同形，复数 spectaculaires","s":"壮观的；惊人的；场面震撼的。常形容风景、比赛、进步等。","ipa":"[spɛk.ta.ky.lɛʁ]","ph":"sp 开头；ec 读 [ɛk]；u 读 [y]；结尾 -aire 读 [ɛʁ]。","pi":"u 读 [y]；结尾 -aire 读 [ɛʁ]，r 要发；别和 spectacle（演出）混。","et":"来自 spectacle（场面），源于拉丁语 spectaculum，与 spectare（看）同源。","ex":[["Le paysage est spectaculaire.","风景很壮观。"],["Il a fait des progrès spectaculaires.","他进步惊人。"]],"co":[["un paysage spectaculaire","壮观的风景"],["des progrès spectaculaires","惊人的进步"],["un spectacle spectaculaire","震撼的表演"]],"sy":[["impressionnant","courant","令人印象深刻的"],["grandiose","soutenu","宏伟的"]],"fq":"中频。","me":"spectacle + -aire = 像表演般震撼。","tr":{"zh":"山上的景色太壮观了。","fr":"La vue depuis la montagne est spectaculaire.","alt":"La vue d'en haut est incroyable.","note":"depuis = 从……（地点）。"}},
 "Typique": {"pos":"adj. 形容词，阴阳同形，复数 typiques","s":"典型的，有代表性的。un plat typique = 特色菜。C'est typique de + 人 = 这就是……的作风。","ipa":"[ti.pik]","ph":"y 读 [i]；结尾 -que 读 [k]，e 不发。","pi":"y 读 [i]；-que 读 [k]；typique de + 名词 / 人。","et":"来自希腊语 typikos，经拉丁语，来自 typos（印记、模型）。","ex":[["C'est un plat typique de la région.","这是这个地区的典型菜。"],["Ça, c'est typique de lui !","这就是他的作风！"]],"co":[["typique de + nom","……的典型"],["un plat typique","特色菜"],["C'est typique !","太典型了！"]],"sy":[["caractéristique","soutenu","有特色的"],["traditionnel","courant","传统的"]],"fq":"中高频。","me":"typique ≈ typical，只是结尾 -que。","tr":{"zh":"这是一种典型的法国早餐。","fr":"C'est un petit-déjeuner typique français.","alt":"C'est un petit-déjeuner bien français.","note":"typique 放名词后，形容词 français 也放后。"}},
 "À cette époque...": {"pos":"loc. 时间短语，阴性名词 une époque","s":"那时候……；在那个时代……。用于讲述过去的情境，后面常接未完成过去时。cette époque 指较长的某段时期，不是一个时刻。","ipa":"[a.sɛ.t‿e.pɔk]","ph":"cette 读 [sɛt]，t 与后面的 é 连读；époque 读 [e.pɔk]，qu 读 [k]。","pi":"époque 是阴性；结尾 que 读 [k]；cette 的 t 在元音前要连读。","et":"来自希腊语 epokhê（停顿、时间点），经拉丁语传入。","ex":[["À cette époque, je vivais à Paris.","那时候我住在巴黎。"],["À cette époque, il n'y avait pas de téléphone.","那时候还没有电话。"]],"co":[["à cette époque","那时"],["à l'époque","当时"],["à notre époque","在我们这个时代"],["l'époque moderne","现代"]],"sy":[["à ce moment-là","courant","在那个时刻"],["autrefois","courant","从前"]],"fq":"高频，讲故事常用。","me":"époque ≈ epoch：同源。","tr":{"zh":"那时候我们没有手机。","fr":"À cette époque, nous n'avions pas de portable.","alt":"À l'époque, on n'avait pas de portable.","note":"叙述背景用未完成过去时 avions。"}},
 "Comme un dieu": {"pos":"loc. 习语，副词短语","s":"字面是「像神一样」，口语里表示「好得不得了」。常和 chanter、jouer、cuisiner、danser 等动词连用，夸人做某事特别棒。语气偏口语、带夸张。","ipa":"[kɔ.mœ̃ djø]","ph":"comme 的 e 不发音，m 与 un 连读成 [mœ̃]；dieu 读 [djø]，ieu = [jø]。","pi":"dieu 的复数是 dieux（x 不发音）；Dieu 大写时指上帝。这个习语只用单数 dieu。","et":"dieu 来自拉丁语 deus（神）。同源词：divin（神圣的）、adieu（再见，字面「交给上帝」）。","ex":[["Il cuisine comme un dieu.","他做饭像神一样好。"],["Elle chante comme un dieu.","她唱歌好听得不得了。"],["Mon frère joue au foot comme un dieu.","我哥哥踢足球厉害极了。"]],"co":[["chanter comme un dieu","唱得极好"],["jouer comme un dieu","玩得 / 演奏得极好"],["Mon Dieu !","天哪！"],["Dieu merci","谢天谢地"]],"sy":[["très bien","courant","很好，最普通的说法"],["comme un chef","familier","像大厨一样，指做得很专业"],["à merveille","soutenu","好极了，较书面"]],"fq":"中频，口语里夸人时常用。","me":"「像神一样」= 好到不是凡人。","tr":{"zh":"我朋友弹钢琴弹得像神一样。","fr":"Mon ami joue du piano comme un dieu.","alt":"Mon pote joue du piano comme un dieu.","note":"jouer de + 乐器；comme un dieu 放在句末。"}},
 "Faire le fou": {"pos":"loc. 动词短语（faire 的固定搭配），fou 阳性单数","s":"胡闹，闹着玩，装疯卖傻。指故意做傻事、疯玩，并不是真的精神失常。主语是女性时说 faire la folle，多人时说 faire les fous。","ipa":"[fɛʁ lə fu]","ph":"faire 读 [fɛʁ]，ai = [ɛ]；le 的 e 读 [ə]；fou 读 [fu]，ou = [u]。","pi":"不要把它当成「发疯」（真的疯了说 devenir fou）。fou 要随主语变：fou / folle / fous / folles。","et":"fou 来自拉丁语 follis（风箱、鼓起的气囊），后来引申为「脑子空空的人」。","ex":[["Les enfants font les fous dans le jardin.","孩子们在花园里胡闹。"],["Arrête de faire le fou, on est au restaurant !","别闹了，我们在餐厅呢！"]],"co":[["faire le fou / la folle","胡闹"],["faire les fous","（一群人）疯玩"],["faire le clown","装小丑，逗人笑"],["devenir fou","发疯（真的）"]],"sy":[["faire le clown","courant","扮小丑逗乐"],["faire l'idiot","familier","装傻，做蠢事"],["déconner","argot","瞎闹、胡搞，很随便，慎用"]],"fq":"中频，口语。","me":"fou [fu] 像「福」：疯玩的孩子一脸「福气」。","tr":{"zh":"孩子们在雪地里疯玩。","fr":"Les enfants font les fous dans la neige.","alt":"Les gamins font les fous dans la neige.","note":"主语是复数，所以用 font les fous。"}},
 "Passer du temps": {"pos":"loc. 动词短语（passer + 部分冠词 du + temps）","s":"花时间，度过时光。后面常接 avec qqn、en famille、à + 动词原形，说明时间用在哪里。du 是部分冠词，表示「一些时间」。","ipa":"[pa.se dy tɑ̃]","ph":"passer 读 [pa.se]，ss = [s]，er = [e]；du 读 [dy]，u = [y]；temps 读 [tɑ̃]，p 和 s 都不发音。","pi":"temps 结尾 ps 不发音；du 的 u 是 [y]，不是 [u]。否定时 du 变 de：Je ne passe pas de temps…","et":"passer 来自 pas（步）加 -er，意思是「走过」。temps 来自拉丁语 tempus。","ex":[["C'est important de passer du temps en famille.","和家人共度时光很重要。"],["Je passe beaucoup de temps à lire.","我花很多时间看书。"]],"co":[["passer du temps avec qqn","和某人共度时光"],["passer du temps à + inf.","花时间做某事"],["passer beaucoup de temps","花很多时间"],["ne pas passer de temps","不花时间（否定用 de）"]],"sy":[["perdre du temps","courant","浪费时间（反义倾向）"],["consacrer du temps à","soutenu","把时间用于……，更正式"]],"fq":"高频，日常常用。","me":"passer = 让时间「走过」，du = 一点点。","tr":{"zh":"周末我喜欢和朋友待在一起。","fr":"Le week-end, j'aime passer du temps avec mes amis.","alt":"Le week-end, j'aime bien traîner avec mes potes.","note":"aimer + 动词原形；temps 前用 du。"}},
 "L'abonnement à internet": {"pos":"n.m. 阳性名词，复数 abonnements","s":"订阅，包月服务；这里指宽带 / 网络套餐。abonnement 也可用于杂志、地铁月票、健身房会员：un abonnement à un magazine、un abonnement de métro。后面用 à 引出服务。","ipa":"[a.bɔn.mɑ̃]","ph":"a-bon-ment：nn 读一个 [n]，o 读 [ɔ]；结尾 -ment 读鼻化 [ɑ̃]，t 不发音。","pi":"结尾 -ment 的 t 不发音；n 要拼两个 nn。internet 在法语里常小写。","et":"来自动词 abonner（订购）加后缀 -ment。同族词：s'abonner（订阅）、abonné(e)（订户）。","ex":[["J'ai pris un abonnement à internet rapide.","我办了高速宽带。"],["Il a un abonnement à la salle de sport.","他有健身房的会员。"]],"co":[["prendre / souscrire un abonnement","办理订阅 / 套餐"],["résilier un abonnement","取消订阅"],["un abonnement mensuel / annuel","月度 / 年度订阅"],["s'abonner à","订阅……"]],"sy":[["forfait","courant","套餐（手机、网络），更常指固定费用的包"],["souscription","soutenu","签约、认购，较书面"]],"fq":"中频，生活中常用。","me":"abonné 订户 + -ment：订阅这件事。","tr":{"zh":"我想取消我的网络订阅。","fr":"Je voudrais résilier mon abonnement à internet.","alt":"Je veux arrêter mon abonnement internet.","note":"résilier 是办理取消合同的标准动词。"}},
 "L'extérieur": {"pos":"n.m. 阳性名词，复数 extérieurs；也可作形容词 extérieur(e)","s":"外面，外部。à l'extérieur (de) 是「在……外面」，反义词 l'intérieur。也可指外表、外观；l'extérieur 有时指国外（不常用）。","ipa":"[ɛk.ste.ʁjœʁ]","ph":"ex 在这里读 [ɛks]；é = [e]；-ieur 读 [jœʁ]，r 要发音。","pi":"最后的 r 不要吞掉；ex- 读 [ɛks]，不是 [ɛgz]（在 exemple 里才是 [ɛgz]）。","et":"来自拉丁语 exterior（更靠外的），由 exter（外面）派生。反义词 intérieur 来自 interior。","ex":[["Les enfants jouent à l'extérieur.","孩子们在外面玩。"],["Il fait beau, mangeons à l'extérieur.","天气好，我们在外面吃吧。"]],"co":[["à l'extérieur (de)","在……外面"],["de l'extérieur","从外面"],["l'extérieur de la maison","房子外面"]],"sy":[["dehors","courant","外面，副词，口语最常说"],["l'intérieur","courant","反义：里面"]],"fq":"中高频，日常常用。","me":"ex- = 出去，extérieur = 往外的部分。","tr":{"zh":"我们在房子外面等你。","fr":"Nous t'attendons à l'extérieur de la maison.","alt":"On t'attend dehors.","note":"à l'extérieur de + 名词；单独用时说 dehors。"}},
 "L'intérieur": {"pos":"n.m. 阳性名词，复数 intérieurs；也可作形容词 intérieur(e)","s":"里面，内部。à l'intérieur (de) 是「在……里面」，反义词 l'extérieur。也指家里的内部布置：un intérieur chaleureux（温馨的家）。","ipa":"[ɛ̃.te.ʁjœʁ]","ph":"in 读鼻化 [ɛ̃]；té = [te]；-ieur 读 [jœʁ]。","pi":"开头 in- 是鼻化元音 [ɛ̃]，不要读成 [in]；结尾 r 要发音。","et":"来自拉丁语 interior（更靠里的），inter 的比较级形式。反义词 extérieur。","ex":[["Il pleut, restons à l'intérieur.","下雨了，我们待在里面。"],["L'intérieur de la voiture est propre.","车里面很干净。"]],"co":[["à l'intérieur (de)","在……里面"],["l'intérieur de la maison","房子里面"],["un intérieur confortable","舒适的室内布置"]],"sy":[["dedans","courant","里面，副词，口语"],["l'extérieur","courant","反义：外面"]],"fq":"中高频，日常常用。","me":"in- = 进去，intérieur = 往里的部分。","tr":{"zh":"孩子们在屋里玩。","fr":"Les enfants jouent à l'intérieur.","alt":"Les enfants jouent dedans.","note":"à l'intérieur 单独使用，后面不接 de。"}},
 "Le chauffage": {"pos":"n.m. 阳性名词，复数 chauffages","s":"暖气，供暖系统。法国常见 chauffage central（集中供暖）、chauffage au gaz / électrique。Allumer le chauffage = 开暖气。","ipa":"[ʃo.faʒ]","ph":"chau 读 [ʃo]；ff = [f]；age 读 [aʒ]，g 在 e 前读 [ʒ]，结尾 e 不发音。","pi":"chau- 是 [ʃo]，不是 [tʃau]；-age 读 [aʒ]，不要加 e 的音。","et":"由动词 chauffer（加热）加后缀 -age 构成；chauffer 来自拉丁语 calefacere（使变热）。","ex":[["Le chauffage est allumé en hiver.","冬天开暖气。"],["On a coupé le chauffage ce matin.","今天早上暖气停了。"]],"co":[["allumer / éteindre le chauffage","开 / 关暖气"],["le chauffage central","集中供暖"],["le chauffage au sol","地暖"],["les frais de chauffage","取暖费"]],"sy":[["radiateur","courant","暖气片，具体设备"],["climatisation","courant","空调，注意不是暖气"]],"fq":"中频，生活中常用。","me":"chauffer + -age：让屋子变热的「装置」。","tr":{"zh":"我冷，请开暖气。","fr":"J'ai froid, allume le chauffage, s'il te plaît.","alt":"J'ai froid, tu peux mettre le chauffage ?","note":"avoir froid（冷），不是 être froid。"}},
 "Le courrier": {"pos":"n.m. 阳性名词，复数 courriers","s":"信件，邮件（总称）。le courrier 指收到的信件，不分单封。courrier électronique = 电子邮件，口语里更常说 un mail。","ipa":"[ku.ʁje]","ph":"ou = [u]；rr = [ʁ]；ier 读 [je]，结尾 r 不发音。","pi":"结尾 -ier 读 [je]，r 不发音；rr 是一个 [ʁ]，不要读两遍。","et":"来自意大利语 corriere（信使），本义是跑腿送信的人，意思后来转为所送的信件。","ex":[["As-tu regardé le courrier aujourd'hui ?","你今天看信了吗？"],["Le facteur apporte le courrier le matin.","邮递员早上送信。"]],"co":[["relever le courrier","取信"],["envoyer un courrier","寄一封信"],["le courrier électronique","电子邮件"],["le courrier du matin","早上的邮件"]],"sy":[["lettre","courant","一封具体的信"],["mail","courant","电邮，口语常用"],["courriel","courant","电子邮件，魁北克和书面常用"]],"fq":"中高频，日常常用。","me":"courrier 里有 courir（跑）：跑着送来的信。","tr":{"zh":"你拿到今天的信了吗？","fr":"Tu as pris le courrier aujourd'hui ?","alt":"T'as récupéré le courrier ?","note":"courrier 是总称，通常不加复数。"}},
 "Le début": {"pos":"n.m. 阳性名词，复数 débuts","s":"开头，开始。au début = 起初；dès le début = 从一开始；复数 les débuts 指刚起步的阶段。反义词 la fin。","ipa":"[de.by]","ph":"dé = [de]；bu 读 [by]，u = [y]；结尾 t 不发音。","pi":"结尾 t 不发音；u 是 [y]，嘴唇要圆，不是 [u]。","et":"来自动词 débuter，由 de- 和 but（目标）构成。débuter 是「开始」，débutant(e) 是「新手」。","ex":[["C'est le début du film.","这是电影的开头。"],["Au début, je n'aimais pas ce travail.","一开始我不喜欢这份工作。"]],"co":[["au début","起初"],["au début de + 名词","在……开头"],["dès le début","从一开始"],["début mars","三月初"]],"sy":[["commencement","soutenu","开始，较书面"],["la fin","courant","反义：结尾"],["départ","courant","出发、开端"]],"fq":"极高频，日常常用。","me":"débuter 开始，début 是它的名词。","tr":{"zh":"我从头开始看这部电影。","fr":"Je regarde le film depuis le début.","alt":"Je regarde le film depuis le début, je ne veux rien rater.","note":"depuis le début = 从头至今。"}},
 "Le gaz": {"pos":"n.m. 阳性名词，单复数相同 gaz","s":"燃气，煤气，气体。le gaz 指家里做饭取暖用的燃气。une cuisinière à gaz = 燃气灶。汽车加的「汽油」不叫 gaz，要说 l'essence。","ipa":"[gɑz]","ph":"g 读 [g]；a 读 [ɑ]（或 [a]）；结尾 z 要发音。","pi":"单词结尾的 z 要读出来，这点和多数法语词尾辅音不同；复数不变，也是 gaz。","et":"17 世纪佛兰德化学家 van Helmont 根据希腊语 khaos（混沌）造出的词，后进入法语。","ex":[["Je cuisine au gaz.","我用煤气做饭。"],["La facture de gaz est chère en hiver.","冬天的燃气费很贵。"]],"co":[["cuisiner au gaz","用燃气做饭"],["la facture de gaz","燃气账单"],["le gaz naturel","天然气"],["une fuite de gaz","燃气泄漏"]],"sy":[["essence","courant","汽油，别和 gaz 混淆"],["électricité","courant","电，另一种能源"]],"fq":"中频，日常常用。","me":"gaz 的 z 要「嗡」出来，像气在响。","tr":{"zh":"我们家用燃气做饭。","fr":"Chez nous, on cuisine au gaz.","alt":"À la maison, on fait la cuisine au gaz.","note":"au gaz = 用燃气（à 表示方式）。"}},
 "Le loyer": {"pos":"n.m. 阳性名词，复数 loyers","s":"房租。每月交的租金，用 payer le loyer。动词 louer 既是「租入」也是「租出」，所以要靠上下文分清。","ipa":"[lwa.je]","ph":"oy 读 [wa] 并带出半元音 [j]：loy-er 分成 [lwa.je]；结尾 er = [e]，r 不发音。","pi":"loyer 的 oy 读 [wa]，和 loyal 一样；结尾 er 读 [e]，r 不发音。","et":"来自古法语 loier，源自拉丁语 locarium（出租的东西），与动词 louer（租）同族。","ex":[["Le loyer est cher dans cette ville.","这个城市的房租很贵。"],["Je paie mon loyer le cinq du mois.","我每月五号交房租。"]],"co":[["payer le loyer","交房租"],["un loyer mensuel","月租"],["un loyer modéré","租金适中（HLM 的 L 就是 loyer）"],["loyer + charges","房租加杂费"]],"sy":[["location","courant","租赁，行为或租来的房子"],["charges","courant","物业费 / 杂费，常与 loyer 并列"]],"fq":"中高频，租房时必学。","me":"loyer 和 louer：租房就要付 loyer。","tr":{"zh":"我每个月交六百欧元房租。","fr":"Je paie un loyer de six cents euros par mois.","alt":"Mon loyer, c'est six cents euros par mois.","note":"par mois = 每月。"}},
 "Le ménage": {"pos":"n.m. 阳性名词，复数 ménages","s":"家务，打扫。faire le ménage = 打扫房子；une femme de ménage 是保洁阿姨。另一义是「家庭、住户」或「夫妻」，如统计里的 un ménage = 一户。","ipa":"[me.naʒ]","ph":"mé = [me]；na = [na]；ge 读 [ʒ]，e 不发音。","pi":"-age 读 [aʒ]；ménage 是阳性，不要说 la ménage。注意不是「管理」，别和英语 manage 搞混。","et":"来自古法语 manage 或 mesnage，与「住所、家业」有关，拉丁语 mansio（停留处）的后代。","ex":[["Je fais le ménage tous les samedis.","我每个星期六做家务。"],["Nous faisons le ménage ensemble.","我们一起打扫。"]],"co":[["faire le ménage","做家务，打扫"],["une femme de ménage","保洁员"],["les produits ménagers","清洁用品"],["un jeune ménage","年轻夫妻"]],"sy":[["nettoyage","courant","清洁，行为本身"],["tâches ménagères","courant","家务活，多指日常杂活"],["foyer","soutenu","家庭、住户"]],"fq":"中高频，日常常用。","me":"ménage 里有 mén-，想到 maison：家里的事。","tr":{"zh":"周日我们一起做家务。","fr":"Le dimanche, nous faisons le ménage ensemble.","alt":"Le dimanche, on fait le ménage tous ensemble.","note":"faire le ménage 固定搭配，不用 faire du ménage。"}},
 "Le rez-de-chaussée": {"pos":"n.m. 阳性名词，单复数相同 des rez-de-chaussée","s":"底层，一楼（法国的一楼）。法国楼层从 rez-de-chaussée 开始，再往上才是 premier étage（二楼）。缩写常写 RDC。","ipa":"[ʁe.də.ʃo.se]","ph":"rez 读 [ʁe]，z 不发音；de 弱读 [də]；chaussée 读 [ʃo.se]，au 在 chaus 里读 [o]。","pi":"rez 的 z 不发音；常见读法中 de 会弱化或省略，听起来像 [ʁe.ʃo.se]。复数不变。","et":"rez 意为「齐平、贴着」（古法语 rez，「剃平」），chaussée 是「路面」，合起来是「与路面齐平的一层」。","ex":[["J'habite au rez-de-chaussée.","我住在一楼。"],["Le bureau est au rez-de-chaussée.","办公室在底层。"]],"co":[["au rez-de-chaussée","在底层"],["un appartement en rez-de-chaussée","一楼的公寓"],["le premier étage","二楼（法国的「一层楼」之上）"]],"sy":[["RDC","courant","缩写，常写在房产广告里"],["premier étage","courant","二楼，别和一楼混淆"]],"fq":"中频，租房、住宿常见。","me":"rez = 贴地，chaussée = 路：贴着路面的一层。","tr":{"zh":"我的公寓在一楼，有一个小花园。","fr":"Mon appartement est au rez-de-chaussée, avec un petit jardin.","alt":"J'habite en rez-de-chaussée, avec un petit jardin.","note":"法国一楼是 rez-de-chaussée，二楼才是 premier étage。"}},
 "Un bail": {"pos":"n.m. 阳性名词，复数 baux（不规则）","s":"租约，租赁合同。signer un bail = 签租约；un bail de trois ans = 三年租约。复数是 baux，不是 bails。","ipa":"[baj]","ph":"ail 读 [aj]，i 与 l 合成「亚」的尾音，l 不单独读。","pi":"复数是 baux [bo]，要特别记；ail = [aj]，l 不发 [l]。","et":"来自古法语 baillier（交付、给予），与「把房子交给承租人」有关。同源：bailleur（出租人）。","ex":[["J'ai signé un bail d'un an.","我签了一年的租约。"],["Le bail se termine en juin.","租约六月到期。"]],"co":[["signer un bail","签租约"],["résilier un bail","解除租约"],["un bail de trois ans","三年租约"],["renouveler le bail","续租"]],"sy":[["contrat de location","courant","租赁合同，说法更通用"],["bailleur / locataire","courant","房东 / 租客"]],"fq":"中频，租房时必用。","me":"bail 的复数 baux：和 chevaux 一样 -aux。","tr":{"zh":"我下个月续签租约。","fr":"Je renouvelle mon bail le mois prochain.","alt":"Mon bail est renouvelé le mois prochain.","note":"renouveler = 续签，更新。"}},
 "Un bateau": {"pos":"n.m. 阳性名词，复数 bateaux","s":"船，泛指各种船。比 navire（大船）、paquebot（邮轮）更日常。en bateau = 乘船；prendre le bateau = 坐船。","ipa":"[ba.to]","ph":"ba = [ba]；teau 读 [to]，eau = [o]。","pi":"eau 读 [o]，不发 e、a、u；复数 bateaux，x 不发音。","et":"来自古法语 batel，一般认为源自古英语 bāt，与英语 boat 同族。","ex":[["Nous avons fait un tour en bateau.","我们坐船游览了一圈。"],["Le bateau part à dix heures.","船十点出发。"]],"co":[["faire un tour en bateau","坐船游览"],["prendre le bateau","坐船"],["un bateau à voile","帆船"],["un bateau de pêche","渔船"]],"sy":[["navire","soutenu","大船，较书面"],["voilier","courant","帆船"],["paquebot","courant","邮轮、大客轮"]],"fq":"高频，日常常用。","me":"bat-eau：像 boat 加了水（eau）。","tr":{"zh":"我们坐船去那座小岛。","fr":"Nous allons sur l'île en bateau.","alt":"On va sur l'île en bateau.","note":"en bateau 不加冠词；坐车类似 en voiture。"}},
 "Un cadre": {"pos":"n.m. 阳性名词，复数 cadres","s":"画框，相框，框架。另有常用义：企业里的「管理层、白领干部」（un cadre）和「环境、背景」（le cadre de vie 生活环境）。看上下文区分。","ipa":"[kɑdʁ]","ph":"ca 读 [kɑ]；结尾 dre 读 [dʁ]，e 不发音。","pi":"结尾 -dre 的 e 不发音，只发 [dʁ]；不要加一个 [ə]。","et":"来自意大利语 quadro（方形），源自拉丁语 quadrum（方块）。同族词：carré（方形的）。","ex":[["J'ai mis une photo dans ce cadre.","我把照片放进这个相框。"],["Elle est cadre dans une banque.","她是银行的管理人员。"]],"co":[["un cadre photo","相框"],["un cadre supérieur","高管"],["dans le cadre de","在……范围内"],["le cadre de vie","生活环境"]],"sy":[["encadrement","courant","框架 / 管理层，较书面"],["tableau","courant","画，装框的画本身"]],"fq":"高频，多个义项都常用。","me":"cadre = 方方正正的框。","tr":{"zh":"他把全家福放进了相框。","fr":"Il a mis la photo de famille dans un cadre.","alt":"Il a encadré la photo de famille.","note":"encadrer 是动词「装框」。"}},
 "Un camping-car": {"pos":"n.m. 阳性名词，复数 camping-cars","s":"房车，旅居车。法国人常开着 camping-car 去度假，露营。词里虽有英语成分，但这个词是法语自己造的。","ipa":"[kɑ̃.piŋ.kaʁ]","ph":"cam 读鼻化 [kɑ̃]；ping 读 [piŋ]，ng 为 [ŋ]；car 读 [kaʁ]，r 要发。","pi":"ping 里的 ng 读 [ŋ]，g 不单独发；car 的 r 读法国式 [ʁ]。","et":"由 camping（露营）和 car（车）合成，是法语里的类英语词。camper 是「露营」。","ex":[["Ils voyagent en camping-car.","他们开房车旅行。"],["Nous louons un camping-car cet été.","今年夏天我们租一辆房车。"]],"co":[["voyager en camping-car","乘房车旅行"],["louer un camping-car","租房车"],["une aire de camping-car","房车营地"]],"sy":[["caravane","courant","拖挂式拖车房，不带发动机"],["fourgon aménagé","courant","改装的厢式车"]],"fq":"中频，旅游与度假话题常见。","me":"camping + car：露营 + 车。","tr":{"zh":"我们打算开房车去南法。","fr":"Nous allons dans le sud de la France en camping-car.","alt":"On part dans le sud en camping-car.","note":"en camping-car：乘坐交通工具用 en。"}},
 "Un centre commercial": {"pos":"n.m. 阳性名词，复数 centres commerciaux","s":"购物中心，大型商场。口语里也常简称 un centre co。比 grand magasin（百货公司）更像一整栋有很多店铺的综合体。","ipa":"[sɑ̃tʁ kɔ.mɛʁ.sjal]","ph":"centre 读 [sɑ̃tʁ]，结尾 re 不读 e；commercial 读 [kɔ.mɛʁ.sjal]，ci = [sj]。","pi":"复数 centres commerciaux：形容词 commercial 变 commerciaux。commercial 中的 c 在 i 前读 [s]。","et":"centre 来自拉丁语 centrum（圆心）；commercial 来自 commerce（贸易）加 -ial。","ex":[["Je vais faire les magasins au centre commercial.","我去购物中心逛街。"],["Le centre commercial ferme à vingt heures.","购物中心晚上八点关门。"]],"co":[["aller au centre commercial","去购物中心"],["faire les magasins","逛街购物"],["un grand centre commercial","大型购物中心"],["le centre-ville","市中心"]],"sy":[["galerie marchande","courant","商业街区，购物廊"],["grand magasin","courant","百货公司"],["centre co","familier","口语简称"]],"fq":"中高频，购物话题常用。","me":"centre + commercial：商业的中心。","tr":{"zh":"我们周六去购物中心。","fr":"Nous allons au centre commercial samedi.","alt":"On va au centre commercial samedi.","note":"samedi 前不加冠词时表示「这个周六」。"}},
 "Un coussin": {"pos":"n.m. 阳性名词，复数 coussins","s":"靠垫，垫子。放在沙发、椅子上的软垫，也可以是座垫。和 oreiller（睡觉用的枕头）不同。","ipa":"[ku.sɛ̃]","ph":"cou = [ku]；ssin 读 [sɛ̃]，ss = [s]，in = 鼻化 [ɛ̃]。","pi":"ss 读清音 [s]，不要读成 [z]；in 是鼻化元音，n 不发音。","et":"来自古法语 coissin，可能与拉丁语 coxa（髋、臀）有关，垫在臀下的东西。此说有一定不确定性。","ex":[["Il y a un coussin sur la chaise.","椅子上有个靠垫。"],["J'ai acheté deux coussins pour le canapé.","我给沙发买了两个靠垫。"]],"co":[["un coussin de canapé","沙发靠垫"],["une housse de coussin","靠垫套"],["un coussin chauffant","加热垫"]],"sy":[["oreiller","courant","枕头，睡觉用"],["traversin","courant","长枕"]],"fq":"中频，家居话题常见。","me":"cou-ssin：坐在上面软软的。","tr":{"zh":"沙发上有三个靠垫。","fr":"Il y a trois coussins sur le canapé.","alt":"Sur le canapé, il y a trois coussins.","note":"il y a + 复数名词，动词仍用单数 a。"}},
 "Un espace vert": {"pos":"n.m. 阳性名词，复数 espaces verts","s":"绿地，公共绿化空间。指城市里的公园、草坪、花园等，市政规划里常说 les espaces verts。vert 要随复数加 s。","ipa":"[ɛs.pas vɛʁ]","ph":"espace 读 [ɛs.pas]，e 不发音；vert 读 [vɛʁ]，t 不发音。","pi":"vert 结尾的 t 不发音，r 发音；这里 espace 是阳性，不是阴性。","et":"espace 来自拉丁语 spatium（空间）；vert 来自拉丁语 viridis（绿色的）。","ex":[["J'aime me promener dans cet espace vert.","我喜欢在这片绿地散步。"],["La ville a créé de nouveaux espaces verts.","城市新建了一些绿地。"]],"co":[["entretenir les espaces verts","养护绿地"],["un espace vert public","公共绿地"],["se promener dans un espace vert","在绿地散步"]],"sy":[["parc","courant","公园"],["jardin public","courant","公共花园"],["pelouse","courant","草坪"]],"fq":"中频，城市与居住话题常见。","me":"espace（空间）+ vert（绿）：绿色的空间。","tr":{"zh":"我家附近有很多绿地。","fr":"Il y a beaucoup d'espaces verts près de chez moi.","alt":"Près de chez moi, il y a pas mal de verdure.","note":"beaucoup de 后名词用复数，且不带冠词。"}},
 "Un état des lieux": {"pos":"n.m. 阳性名词，复数 des états des lieux","s":"房屋状况清单，交接验房。租房入住和退租时，房东和租客一起检查房子并记录状况，称为 faire l'état des lieux。也可泛指「现状评估」。","ipa":"[e.ta de ljø]","ph":"état 读 [e.ta]，t 在词中读，结尾不读；des 读 [de]；lieux 读 [ljø]，x 不发音。","pi":"lieux 的 x 不发音，读 [ljø]；复数时 état 和 lieux 都保留，只给第一个加 s。","et":"état 来自拉丁语 status（状态）；lieu 来自拉丁语 locus（地点）。合起来是「地点的状态」。","ex":[["Nous faisons l'état des lieux demain.","我们明天做房屋交接。"],["L'état des lieux d'entrée est très important.","入住时的验房记录非常重要。"]],"co":[["faire / dresser un état des lieux","做房屋交接清单"],["l'état des lieux d'entrée / de sortie","入住 / 退租验房"],["signer l'état des lieux","签验房单"]],"sy":[["inventaire","courant","清单，物品清点"],["bilan","courant","总结、评估"]],"fq":"中频，租房时必用。","me":"état（状态）+ lieux（地方）：地方的状态。","tr":{"zh":"退租前要做一次验房。","fr":"Il faut faire un état des lieux avant de partir.","alt":"On doit faire l'état des lieux avant de rendre l'appartement.","note":"il faut + 动词原形 = 必须。"}},
 "Un évier": {"pos":"n.m. 阳性名词，复数 éviers","s":"水槽，厨房洗碗池。厨房的叫 un évier，浴室洗手的叫 un lavabo，不要混用。","ipa":"[e.vje]","ph":"é = [e]；vier 读 [vje]，ier = [je]，r 不发音。","pi":"结尾 -ier 读 [je]，r 不发音；évier 是厨房专用，浴室说 lavabo。","et":"来自古法语 evier，源自拉丁语 aquarium（与水相关的容器）。同族词：eau（水，拉丁语 aqua）。","ex":[["La vaisselle sale est dans l'évier.","脏碗在水池里。"],["L'évier est bouché.","水槽堵了。"]],"co":[["l'évier de la cuisine","厨房水槽"],["un évier en inox","不锈钢水槽"],["déboucher l'évier","疏通水槽"]],"sy":[["lavabo","courant","洗手池，浴室用"],["bac","courant","槽，盆"]],"fq":"中频，家居话题常见。","me":"évier：厨房「洗」东西的池，e-vi-er 连读很顺。","tr":{"zh":"水槽堵了，我去叫水管工。","fr":"L'évier est bouché, j'appelle le plombier.","alt":"L'évier est bouché, je vais appeler le plombier.","note":"être bouché 表示被堵住。"}},
 "Un garage": {"pos":"n.m. 阳性名词，复数 garages","s":"车库；也指汽车修理厂。Je vais au garage 可能是「去车库」，也可能是「去修车厂」。","ipa":"[ga.ʁaʒ]","ph":"ga = [ga]；rage 读 [ʁaʒ]，g 在 e 前读 [ʒ]，结尾 e 不发音。","pi":"g 在 a 前读 [g]，在 -age 里读 [ʒ]；r 是法语小舌音，不是英语 r。","et":"由动词 garer（停放、停靠）加后缀 -age 构成。同族词：garer, se garer（停车）。","ex":[["Je gare ma voiture dans le garage.","我把车停在车库。"],["Ma voiture est au garage.","我的车在修理厂。"]],"co":[["garer la voiture au garage","把车停进车库"],["un garage à vélos","自行车库"],["aller au garage","去修车厂 / 车库"],["un garagiste","修车师傅"]],"sy":[["parking","courant","停车场，公共的"],["box","courant","带门的独立车位"],["atelier","courant","维修作坊"]],"fq":"高频，日常常用。","me":"garer + -age：停车的地方。","tr":{"zh":"我的车在修理厂，明天才取。","fr":"Ma voiture est au garage, je la récupère demain.","alt":"Ma voiture est au garage, je la prends demain.","note":"être au garage 可指「在修理厂」。"}},
 "Un grenier": {"pos":"n.m. 阳性名词，复数 greniers","s":"阁楼，顶层堆放杂物的地方。以前也指粮仓。放旧东西、旧家具：les vieilles choses dans le grenier。比 mansarde（可住人的阁楼房间）更偏储藏。","ipa":"[gʁə.nje]","ph":"gre 读 [gʁə]，e 轻读；nier 读 [nje]，ier = [je]，r 不发音。","pi":"开头的 gre- 中的 e 很轻，有时听起来像 [gʁ]；结尾 -ier 的 r 不发音。","et":"来自拉丁语 granarium（粮仓），源于 granum（谷粒）。同族词：grain（谷粒）、grange（谷仓）。","ex":[["Il y a de vieilles choses dans le grenier.","阁楼里有旧东西。"],["On range les valises au grenier.","行李箱放在阁楼里。"]],"co":[["monter au grenier","上阁楼"],["un grenier à foin","干草仓"],["ranger dans le grenier","放进阁楼"]],"sy":[["combles","courant","屋顶下的空间，总称"],["mansarde","courant","可住人的阁楼房间"],["cave","courant","反义：地窖"]],"fq":"中频，家居与老房子话题常见。","me":"grenier 里有 grain：存谷子的地方，后来存旧物。","tr":{"zh":"我在阁楼里找到了旧照片。","fr":"J'ai trouvé de vieilles photos dans le grenier.","alt":"J'ai déniché des vieilles photos au grenier.","note":"de vieilles photos：形容词在复数名词前，用 de。"}},
 "Un HLM": {"pos":"n.m. 阳性名词（正式是阴性 une HLM），复数 des HLM（不变）","s":"廉租房，社会住房。HLM = Habitation à Loyer Modéré（租金适中的住房）。口语里常说 un HLM，指一栋社会住房楼；现在官方更常说 logement social。","ipa":"[aʃ.ɛl.ɛm]","ph":"按字母读：H [aʃ]，L [ɛl]，M [ɛm]；三个字母连读成 [aʃ.ɛl.ɛm]。","pi":"H 字母读 [aʃ]，不是英语的「艾奇」；缩写复数不变，也不加 s。","et":"缩写，来自 Habitation à Loyer Modéré，20 世纪中叶起在法国使用的社会住房名称。","ex":[["Il a grandi dans un HLM.","他在廉租房里长大。"],["Elle habite dans une HLM en banlieue.","她住在郊区的社会住房里。"]],"co":[["habiter dans un HLM","住在廉租房"],["un logement social","社会住房"],["une demande de HLM","申请廉租房"],["un loyer modéré","适中的租金"]],"sy":[["logement social","courant","社会住房，较正式的说法"],["cité","familier","（常带贬义）社区住宅区"],["immeuble","courant","公寓楼，泛指"]],"fq":"中频，社会与居住话题常见。","me":"H-L-M：Habitation à Loyer Modéré。","tr":{"zh":"他们住在一套廉租房里。","fr":"Ils habitent dans un HLM.","alt":"Ils vivent en HLM.","note":"habiter dans + 住处；HLM 可阳可阴，需看语境。"}},
 "Un lavabo": {"pos":"n.m. 阳性名词，复数 lavabos","s":"洗手池，洗脸盆，多指浴室里的。厨房的洗碗槽是 évier。公共场所里 les lavabos 有时也指洗手间。","ipa":"[la.va.bo]","ph":"三个音节 la-va-bo，各自读 [la]、[va]、[bo]；结尾 o 读 [o]，重音落在最后。","pi":"法语词重音在最后一个音节；不要把 bo 读成 [bu]。","et":"来自拉丁语 lavabo（「我将洗」），拉丁弥撒中洗手礼的第一个词，后来用来指洗手盆。同族：laver（洗）。","ex":[["Je me lave les mains au lavabo.","我在洗手池洗手。"],["Le lavabo de la salle de bain fuit.","浴室的洗手池漏水。"]],"co":[["se laver les mains au lavabo","在洗手池洗手"],["un lavabo en céramique","陶瓷洗手池"],["boucher / déboucher le lavabo","堵塞 / 疏通洗手池"]],"sy":[["évier","courant","厨房水槽，别和 lavabo 混淆"],["vasque","courant","台盆，造型更讲究"]],"fq":"中频，家居话题常见。","me":"lavabo 里有 laver：洗的地方。","tr":{"zh":"你可以在洗手池里洗手。","fr":"Tu peux te laver les mains au lavabo.","alt":"Va te laver les mains au lavabo.","note":"se laver les mains：身体部位前用定冠词 les。"}},
 "Un lave-vaisselle": {"pos":"n.m. 阳性名词，复数 des lave-vaisselle（不变）","s":"洗碗机。由 laver（洗）+ vaisselle（餐具、碗碟）构成，所以 vaisselle 在复数里不加 s。用法：mettre dans le lave-vaisselle（放进洗碗机）。","ipa":"[lav.vɛ.sɛl]","ph":"lave 的 e 不发音，v 读 [v]，与 vaisselle 的 v 连在一起，听起来是拉长的 v；vaisselle 读 [vɛ.sɛl]。","pi":"lave 与 vaisselle 的 v 相接，要拉长一点；复数不变：des lave-vaisselle。","et":"复合词：laver + vaisselle。vaisselle 本身来自拉丁语 vascella（小容器），可作参考。","ex":[["Mets les verres dans le lave-vaisselle.","把杯子放进洗碗机。"],["Le lave-vaisselle est en panne.","洗碗机坏了。"]],"co":[["mettre dans le lave-vaisselle","放进洗碗机"],["vider le lave-vaisselle","清空洗碗机"],["lancer le lave-vaisselle","启动洗碗机"],["faire la vaisselle","洗碗"]],"sy":[["machine à laver","courant","洗衣机，别和洗碗机混淆"],["faire la vaisselle à la main","courant","手洗碗"]],"fq":"中频，家居话题常见。","me":"lave + vaisselle：洗 + 餐具。","tr":{"zh":"你可以把杯子放进洗碗机吗？","fr":"Tu peux mettre les verres dans le lave-vaisselle ?","alt":"Tu peux ranger les verres dans le lave-vaisselle ?","note":"pouvoir + 动词原形，礼貌请求。"}},
 "Un lieu": {"pos":"n.m. 阳性名词，复数 lieux（不规则，x）","s":"地方，场所。lieu 比 endroit 稍正式。常见搭配：avoir lieu（举行、发生）、au lieu de（而不是）、en premier lieu（首先）。","ipa":"[ljø]","ph":"ieu 读 [jø]，i 变半元音 [j]，eu = [ø]，只有一个音节。","pi":"复数是 lieux，x 不发音，读法相同 [ljø]；不要说 lieus。","et":"来自拉丁语 locus（地方）。同族词：local（当地的）、localiser（定位）。","ex":[["C'est un lieu magnifique.","这是个迷人的地方。"],["La réunion a lieu à dix heures.","会议十点举行。"],["Au lieu de partir, il est resté.","他没有走，反而留下了。"]],"co":[["avoir lieu","举行；发生"],["au lieu de","而不是"],["en premier lieu","首先"],["un lieu de travail","工作场所"]],"sy":[["endroit","courant","地方，口语最常用"],["place","courant","位置、座位"],["site","courant","地点、网站"]],"fq":"极高频，日常常用。","me":"lieu 的 ieu = [jø]，像「约」。","tr":{"zh":"活动在市中心举行。","fr":"L'événement a lieu au centre-ville.","alt":"L'événement se passe en centre-ville.","note":"avoir lieu 是固定搭配，主语是事件。"}},
 "Un logement": {"pos":"n.m. 阳性名词，复数 logements","s":"住所，住房。指任何可以住的地方：公寓、房子、宿舍。比 appartement 更泛。chercher un logement = 找房。","ipa":"[lɔʒ.mɑ̃]","ph":"lo 读 [lɔ]；ge 里 g 读 [ʒ]，e 只用来让 g 变软，本身不发音；ment 读 [mɑ̃]。","pi":"-ment 读鼻化 [ɑ̃]，t 不发音；中间 e 不读，所以是 [lɔʒ.mɑ̃]，不是 [lɔ.ʒə.mɑ̃]。","et":"由动词 loger（住）加后缀 -ment 构成；loger 来自 loge（小屋）。同族：logis（住所，较书面）。","ex":[["Je cherche un logement en ville.","我在市里找住处。"],["Le logement coûte cher à Paris.","巴黎的住房很贵。"]],"co":[["chercher un logement","找房子"],["un logement étudiant","学生住房"],["un logement social","社会住房"],["l'aide au logement","住房补贴"]],"sy":[["appartement","courant","公寓，更具体"],["habitation","soutenu","住宅，较书面"],["chez-soi","courant","自己的家"]],"fq":"高频，居住话题常用。","me":"loger + -ment：住的地方。","tr":{"zh":"我正在为明年找住房。","fr":"Je cherche un logement pour l'année prochaine.","alt":"Je cherche où loger l'année prochaine.","note":"chercher + 名词，不加介词。"}},
 "Un loisir": {"pos":"n.m. 阳性名词，常用复数 des loisirs","s":"休闲，业余爱好。常用复数：les loisirs 指休闲活动；avoir des loisirs = 有空闲。单数 un loisir 多指一项爱好；à loisir = 从容地、尽兴地。","ipa":"[lwa.ziʁ]","ph":"oi 读 [wa]；s 在元音之间读 [z]；结尾 r 要发。","pi":"s 读 [z]，不是 [s]；结尾 r 要读出来；不要读成 [lwaʒiʁ]。","et":"来自古法语 leisir，拉丁语 licere（被允许），本义是「有空可做」。英语 leisure 与它同源。","ex":[["Quel est ton loisir préféré ?","你最喜欢的休闲活动是什么？"],["Il a peu de loisirs en semaine.","他平时没什么空闲活动。"]],"co":[["un loisir préféré","最喜欢的休闲活动"],["les loisirs","休闲活动"],["un parc de loisirs","游乐园"],["à loisir","从容地，尽兴地"]],"sy":[["passe-temps","courant","消遣，爱好"],["hobby","courant","爱好，借自英语"],["activité","courant","活动，更泛"]],"fq":"中频，兴趣话题常用。","me":"loisir = 有 s 的空闲，s 读 z。","tr":{"zh":"我的爱好是读书和骑自行车。","fr":"Mes loisirs, c'est la lecture et le vélo.","alt":"Comme loisirs, j'aime lire et faire du vélo.","note":"loisirs 多用复数；c'est 后可接名词。"}},
 "Un mètre carré (m²)": {"pos":"n.m. 阳性名词，复数 mètres carrés","s":"平方米，面积单位，写作 m²。说房子大小时用：50 m² 读作 cinquante mètres carrés。找房时常见 le prix au mètre carré（每平方米价格）。","ipa":"[mɛtʁ ka.ʁe]","ph":"mètre 读 [mɛtʁ]，e 不发音；carré 读 [ka.ʁe]，rr = 一个 [ʁ]。","pi":"复数时两个词都变：mètres carrés；读 50 m² 时，mètres 加 s。","et":"mètre 来自希腊语 metron（尺度）；carré 来自拉丁语 quadratus（方形的）。","ex":[["Cet appartement fait 50 mètres carrés.","这套公寓有五十平方米。"],["Le prix au mètre carré est élevé.","每平方米的价格很高。"]],"co":[["faire 50 m²","有 50 平方米"],["le prix au mètre carré","每平方米价格"],["un mètre cube","一立方米"],["la surface en m²","平方米面积"]],"sy":[["surface","courant","面积"],["superficie","courant","面积，较书面"]],"fq":"中频，租房与房产话题常见。","me":"m² = mètre + carré (²)。","tr":{"zh":"这套公寓有四十五平方米。","fr":"Cet appartement fait quarante-cinq mètres carrés.","alt":"L'appartement fait 45 m².","note":"faire + 数量 + 单位，表示大小。"}},
 "Un meuble à télé": {"pos":"n.m. 阳性名词，复数 meubles à télé","s":"电视柜。口语常说 un meuble télé 或 un meuble TV。meuble 是「家具」，一件家具。télé 是 télévision 的口语缩写。","ipa":"[mœbl a te.le]","ph":"meuble 读 [mœbl]，eu 在这里是 [œ]，结尾 le 不读 e；à 读 [a]；télé 读 [te.le]。","pi":"meuble 的 eu 读 [œ]，嘴形比 [ø] 更开；télé 两个音节都读 [e]，不要读成「特累」。","et":"meuble 来自拉丁语 mobilis（可移动的），因为家具是可搬动的财产。télé 是 télévision 的缩写。","ex":[["La télévision est sur le meuble à télé.","电视放在电视柜上。"],["Nous avons acheté un nouveau meuble télé.","我们买了一个新电视柜。"]],"co":[["un meuble télé","电视柜"],["un meuble de rangement","收纳柜"],["acheter un meuble","买家具"],["un meuble en bois","木质家具"]],"sy":[["meuble TV","courant","电视柜，最常说"],["buffet","courant","餐边柜"],["commode","courant","五斗柜"]],"fq":"中频，家居话题常见。","me":"meuble 像「可动的」，因为家具能搬。","tr":{"zh":"我们需要一个新电视柜。","fr":"Nous avons besoin d'un nouveau meuble télé.","alt":"On a besoin d'un nouveau meuble TV.","note":"avoir besoin de + 名词。"}},
 "Un porte-manteau": {"pos":"n.m. 阳性名词，复数 porte-manteaux 或 porte-manteau","s":"衣帽架，挂外套的架子或挂钩。porte- 是「挂、载」，manteau 是「大衣」。要挂在衣架上的是 cintre（衣架），墙上的挂钩常叫 patère。","ipa":"[pɔʁt.mɑ̃.to]","ph":"porte 读 [pɔʁt]，e 不发音；man 读 [mɑ̃]；teau 读 [to]。","pi":"manteau 里 an 是鼻化 [ɑ̃]，eau 是 [o]。英语 portmanteau（混合词、旧式行李箱）和这里意思不同。","et":"由动词 porter（拿、挂）和 manteau（大衣）合成。manteau 来自拉丁语 mantellum（斗篷）。","ex":[["Accroche ton manteau sur le porte-manteau.","把大衣挂在衣帽架上。"],["Il y a un porte-manteau près de la porte.","门边有一个衣帽架。"]],"co":[["accrocher son manteau","挂大衣"],["un porte-manteau mural","墙上挂钩"],["un porte-manteau sur pied","立式衣帽架"]],"sy":[["patère","courant","墙上挂钩"],["cintre","courant","衣架（挂在柜子里的）"],["penderie","courant","衣橱"]],"fq":"中频，家居话题常见。","me":"porte + manteau：「扛」大衣的架子。","tr":{"zh":"你的外套在衣帽架上。","fr":"Ton manteau est sur le porte-manteau.","alt":"Ton manteau est accroché au porte-manteau.","note":"accroché 过去分词作形容词，表示被挂着。"}},
 "Un potager": {"pos":"n.m. 阳性名词，复数 potagers","s":"菜园，家里种蔬菜的小园子。完整说法是 un jardin potager。和 jardin d'agrément（观赏的花园）相对。","ipa":"[pɔ.ta.ʒe]","ph":"po 读 [pɔ]；ta 读 [ta]；ger 读 [ʒe]，g 在 e 前读 [ʒ]，结尾 r 不发音。","pi":"结尾 -er 读 [e]，r 不发音；g 读 [ʒ]，不是 [g]。","et":"来自 potage（汤，蔬菜煮的汤），因为菜园里种的是做汤用的蔬菜。potage 来自 pot（锅）。","ex":[["Nous cultivons des tomates dans le potager.","我们在菜园里种番茄。"],["Mon grand-père a un petit potager.","我爷爷有一个小菜园。"]],"co":[["un jardin potager","菜园"],["cultiver un potager","种菜园"],["les légumes du potager","菜园里的蔬菜"],["un potager bio","有机菜园"]],"sy":[["jardin","courant","花园，更泛"],["verger","courant","果园"],["carré de légumes","courant","一小块菜地"]],"fq":"中频，花园与饮食话题常见。","me":"potager ← potage：种做汤蔬菜的地方。","tr":{"zh":"他们在菜园里种了很多蔬菜。","fr":"Ils cultivent beaucoup de légumes dans leur potager.","alt":"Ils ont plein de légumes dans leur potager.","note":"beaucoup de + 名词，不加冠词。"}},
 "Un sèche-linge": {"pos":"n.m. 阳性名词，复数 des sèche-linge（不变）","s":"烘干机。sèche 是 sécher（弄干）的变位形式，linge 是「待洗或洗好的衣物、织物」。机器连着用：lave-linge 是洗衣机（也叫 machine à laver）。","ipa":"[sɛʃ.lɛ̃ʒ]","ph":"sèche 读 [sɛʃ]，ch = [ʃ]，结尾 e 不发音；linge 读 [lɛ̃ʒ]，in = [ɛ̃]，g = [ʒ]。","pi":"è 读 [ɛ]，ch 读 [ʃ]；linge 的 in 是鼻化元音，n 不发音。复数不变。","et":"复合词：sécher（弄干）+ linge。linge 来自拉丁语 lineus（亚麻制的）。","ex":[["Je mets les vêtements dans le sèche-linge.","我把衣服放进烘干机。"],["Le sèche-linge est en panne.","烘干机坏了。"]],"co":[["mettre au sèche-linge","放进烘干机"],["un sèche-linge à condensation","冷凝式烘干机"],["étendre le linge","晾衣服"],["le lave-linge","洗衣机"]],"sy":[["machine à laver","courant","洗衣机，不是烘干机"],["séchoir","courant","晾衣架 / 烘干设备"]],"fq":"中频，家居话题常见。","me":"sèche + linge：弄干 + 衣物。","tr":{"zh":"衣服在烘干机里。","fr":"Les vêtements sont dans le sèche-linge.","alt":"Les vêtements sont au sèche-linge.","note":"dans le + 家电，表示在里面。"}},
 "Un séjour": {"pos":"n.m. 阳性名词，复数 séjours","s":"客厅（房产广告里常用）；也指逗留、短期居住：un séjour de trois jours。titre de séjour 是居留许可。口语里客厅常说 salon，séjour更像租房广告术语。","ipa":"[se.ʒuʁ]","ph":"sé 读 [se]；jour 读 [ʒuʁ]，j = [ʒ]，ou = [u]，r 要发。","pi":"j 读 [ʒ]；结尾 r 要发音；不要和 jour 的意思混淆，séjour = 住一段时间。","et":"来自古法语 sejor，动词 séjourner（逗留）与之同族。来源细节不确定。","ex":[["Il y a un grand canapé dans le séjour.","客厅里有一张大沙发。"],["Nous avons fait un séjour de deux semaines en Corse.","我们在科西嘉住了两周。"]],"co":[["un séjour de + 时间","逗留……"],["un titre de séjour","居留许可"],["la salle de séjour","起居室"],["un séjour linguistique","语言游学"]],"sy":[["salon","courant","客厅，口语常用"],["salle de séjour","courant","起居室"],["voyage","courant","旅行"]],"fq":"中频，居住与旅行都会遇到。","me":"séjour 里有 jour：住上几天。","tr":{"zh":"我们的客厅很亮。","fr":"Notre séjour est très lumineux.","alt":"Notre salon est très lumineux.","note":"lumineux 是形容词，阳性单数与 séjour 一致。"}},
 "Un siècle": {"pos":"n.m. 阳性名词，复数 siècles","s":"世纪，一百年。序数词 + siècle：le vingt et unième siècle（21 世纪），书写常用罗马数字加 e：le XXIe siècle。","ipa":"[sjɛkl]","ph":"si 读 [sj]，è 读 [ɛ]，cl 读 [kl]，结尾 e 不发音；整个词只有一个音节。","pi":"siècle 的 -cle 结尾读 [kl]，e 不发音；读 21e 时是 vingt et unième，不是 vingt et un。","et":"来自拉丁语 saeculum（一代人、一个时代）。同源词：séculaire（百年的）、英语 secular。","ex":[["Nous sommes au 21e siècle.","我们现在在 21 世纪。"],["Cette maison date du dix-neuvième siècle.","这栋房子建于十九世纪。"]],"co":[["au vingt et unième siècle","在 21 世纪"],["au début du siècle","世纪初"],["il y a un siècle","一百年前"],["le siècle dernier","上个世纪"]],"sy":[["époque","courant","时代"],["an","courant","年，短得多"]],"fq":"中频，历史和年代话题常用。","me":"siècle ← saeculum：一百年。","tr":{"zh":"这座城堡建于十五世纪。","fr":"Ce château date du quinzième siècle.","alt":"Ce château a été construit au quinzième siècle.","note":"dater de + 时期，表示起源于。"}},
 "Un sofa": {"pos":"n.m. 阳性名词，复数 sofas","s":"沙发。比 canapé 稍少用，语气更时髦或较书面。canapé 是日常最常用的说法；sofa 有时指更舒适的软沙发。","ipa":"[sɔ.fa]","ph":"so 读 [sɔ]；fa 读 [fa]；两个短音节，重音落在最后。","pi":"o 读 [ɔ]，不是英语的 [oʊ]；结尾 a 清晰读 [a]。","et":"借自阿拉伯语 ṣuffa（长凳），经土耳其语等进入欧洲语言。","ex":[["Le chat dort sur le sofa.","猫睡在沙发上。"],["Ils ont acheté un grand sofa en cuir.","他们买了一张大皮沙发。"]],"co":[["un sofa en cuir","皮沙发"],["s'asseoir sur le sofa","坐在沙发上"],["un sofa d'angle","转角沙发"]],"sy":[["canapé","courant","沙发，最常说"],["divan","courant","无靠背或矮沙发"],["banquette","courant","长椅式座位"]],"fq":"中低频，canapé 更常用。","me":"sofa 与英语 sofa 拼写相同，只是读音短一点。","tr":{"zh":"孩子们坐在沙发上看电视。","fr":"Les enfants regardent la télé sur le sofa.","alt":"Les enfants regardent la télé sur le canapé.","note":"sur le + 家具，表示在上面。"}},
 "Un studio": {"pos":"n.m. 阳性名词，复数 studios","s":"单间公寓，一室户。通常是一个主房间加小厨房和卫生间。另有义：录音棚、摄影棚、工作室（un studio d'enregistrement）。","ipa":"[sty.djo]","ph":"stu 读 [sty]，u = [y]；dio 读 [djo]，io = [jo]。","pi":"u 是 [y]（嘴唇圆起来），不是 [u]；和英语 studio 发音差别明显。","et":"借自意大利语 studio（学习、工作室），拉丁语 studium（努力、学习）。","ex":[["Il habite dans un petit studio.","他住在一个小单间。"],["Nous cherchons un studio près de l'université.","我们在大学附近找单间公寓。"]],"co":[["louer un studio","租单间公寓"],["un studio meublé","带家具的单间"],["un studio d'enregistrement","录音棚"],["un studio de cinéma","电影摄影棚"]],"sy":[["T1","courant","一居室，通常有独立厨房"],["appartement","courant","公寓，泛指"],["chambre de bonne","courant","小阁楼房间"]],"fq":"高频，租房话题常用。","me":"studio：只有一个房间，像「工作室」。","tr":{"zh":"我刚租了一个带家具的单间。","fr":"Je viens de louer un studio meublé.","alt":"Je viens de prendre un studio meublé.","note":"venir de + 动词原形 = 刚刚做完。"}},
 "Un T1, un T2, ...": {"pos":"n.m. 阳性名词，复数 des T1, des T2","s":"T1、T2……是房型代号，T 来自 type。T2 表示两个主要房间（客厅 + 一间卧室），不计厨房和卫生间；T3 就是客厅加两间卧室。也说 un deux-pièces、un trois-pièces。","ipa":"[te.œ̃], [te.dø]","ph":"T 读 [te]；1 读 un [œ̃]，2 读 deux [dø]，3 读 trois [tʁwa]；所以 T2 读 [te dø]。","pi":"法语说 T 二，不是「T two」；T2 不等于「两居室含厨房」，要看是否算厨房。","et":"T 是 type（类型）的缩写，在房产广告里表示房间数。较老的写法是 F2、F3。","ex":[["Je loue un T2 avec ma copine.","我和女朋友租了一套两居室。"],["Ils cherchent un T3 près du centre.","他们在市中心附近找一套三居室。"]],"co":[["louer un T2","租一套 T2"],["un deux-pièces","两室的公寓"],["un appartement de type T3","T3 户型的公寓"],["un T1 bis","有隔间的一居室"]],"sy":[["deux-pièces","courant","两室公寓，口语等同于 T2"],["studio","courant","单间，没有独立房间"]],"fq":"中频，租房广告中必见。","me":"T 加数字：T1、T2……数字是主要房间数。","tr":{"zh":"我想租一套 T3，要有阳台。","fr":"Je voudrais louer un T3 avec un balcon.","alt":"Je cherche un T3 avec un balcon.","note":"avec + 名词，表示带有。"}},
 "Un tabouret": {"pos":"n.m. 阳性名词，复数 tabourets","s":"凳子，没有靠背的单人座位。chaise 有靠背；tabouret 无靠背，常用于吧台或厨房，如 un tabouret de bar（吧台凳）。","ipa":"[ta.bu.ʁɛ]","ph":"ta 读 [ta]；bou 读 [bu]；ret 读 [ʁɛ]，结尾 t 不发音。","pi":"结尾 -et 读 [ɛ]，t 不发音；ou 读 [u]，不要读成 [o]。","et":"是 tabour（tambour 的旧形式，鼓）的小词，因为早期的凳子像一面小鼓的形状。","ex":[["Assieds-toi sur ce tabouret.","坐在这张凳子上。"],["Il y a trois tabourets au bar.","吧台有三张凳子。"]],"co":[["un tabouret de bar","吧台凳"],["s'asseoir sur un tabouret","坐在凳子上"],["un tabouret de cuisine","厨房凳"]],"sy":[["chaise","courant","有靠背的椅子"],["banc","courant","长凳"],["pouf","courant","软墩"]],"fq":"中低频，家居话题可见。","me":"tabouret = 小鼓（tabour）形状的凳子。","tr":{"zh":"他坐在吧台前的高凳上。","fr":"Il est assis sur un tabouret de bar.","alt":"Il est installé sur un tabouret au bar.","note":"être assis sur：描述正坐着的状态。"}},
 "Un tapis": {"pos":"n.m. 阳性名词，单复数相同 tapis","s":"地毯，垫子。可大可小：un tapis de salon（客厅地毯）。也指各种垫状物：tapis roulant（传送带 / 跑步机）、tapis de souris（鼠标垫）。","ipa":"[ta.pi]","ph":"ta 读 [ta]；pis 读 [pi]，结尾 s 不发音。","pi":"结尾 s 不发音；单复数同形 tapis，复数只靠冠词区分：des tapis。","et":"来自古法语 tapiz，源于希腊语 tapētion（小地毯）。同族词：tapisserie（挂毯）。","ex":[["J'ai acheté un tapis pour le salon.","我给客厅买了一块地毯。"],["Il y a un tapis rouge devant la porte.","门前有一块红地毯。"]],"co":[["un tapis de bain","浴室脚垫"],["un tapis roulant","传送带；跑步机"],["un tapis de souris","鼠标垫"],["mettre sur le tapis","把话题摆上台面"]],"sy":[["moquette","courant","满铺地毯"],["carpette","courant","小块地垫"]],"fq":"中频，家居话题常见。","me":"tapis 的 s 不发音，像「踏披」。","tr":{"zh":"我想买一块新地毯放在客厅。","fr":"Je voudrais acheter un nouveau tapis pour le salon.","alt":"J'aimerais prendre un nouveau tapis pour le salon.","note":"pour + 名词，表示用途。"}},
 "Un tiroir": {"pos":"n.m. 阳性名词，复数 tiroirs","s":"抽屉。ouvrir / fermer un tiroir（开 / 关抽屉）。tiroir-caisse 是收银机的钱箱。","ipa":"[ti.ʁwaʁ]","ph":"ti 读 [ti]；roir 读 [ʁwaʁ]，oi = [wa]，两个 r 都要发。","pi":"结尾 -oir 读 [waʁ]，r 要发音，不是 [wa]；注意 oi 读 [wa]。","et":"来自动词 tirer（拉）加后缀 -oir（表示工具、容器），意思是「可以拉出的东西」。","ex":[["Les clés sont dans le premier tiroir.","钥匙在第一个抽屉里。"],["Il range ses chaussettes dans le tiroir.","他把袜子放在抽屉里。"]],"co":[["ouvrir / fermer un tiroir","开 / 关抽屉"],["le premier tiroir","第一个抽屉"],["un tiroir-caisse","收银机钱箱"],["fouiller dans un tiroir","翻抽屉"]],"sy":[["casier","courant","格子、柜格"],["commode","courant","有抽屉的柜子"]],"fq":"中频，家居话题常见。","me":"tirer + -oir：拉出来的东西。","tr":{"zh":"你的钥匙在最上面的抽屉里。","fr":"Tes clés sont dans le tiroir du haut.","alt":"Tes clés, elles sont dans le tiroir du haut.","note":"du haut：顶部的，用 de + le 缩合。"}},
 "Un transat": {"pos":"n.m. 阳性名词，复数 transats","s":"躺椅，折叠沙滩椅。海边、花园里躺着晒太阳的椅子。是 transatlantique 的口语缩写。","ipa":"[tʁɑ̃.zat]","ph":"tran 读 [tʁɑ̃]，an = 鼻化 [ɑ̃]；s 在元音之间读 [z]；at 读 [at]，t 在这里要发音。","pi":"s 读 [z]；结尾 t 要发音（和多数词尾 t 不发音不同）。","et":"缩略自 transatlantique，原指大西洋邮轮甲板上的折叠躺椅。","ex":[["Je me repose sur le transat au soleil.","我躺在阳光下的躺椅上休息。"],["On a mis deux transats dans le jardin.","我们在花园里放了两把躺椅。"]],"co":[["s'allonger sur un transat","躺在躺椅上"],["un transat de plage","沙滩椅"],["un transat pliant","折叠躺椅"]],"sy":[["chaise longue","courant","躺椅，更通用"],["bain de soleil","courant","日光浴躺椅"]],"fq":"中低频，度假话题可见。","me":"transat ← transatlantique：邮轮甲板上的躺椅。","tr":{"zh":"我们躺在花园的躺椅上看书。","fr":"Nous lisons sur des transats dans le jardin.","alt":"On lit sur les transats dans le jardin.","note":"des transats：不定冠词复数。"}},
 "L'architecture": {"pos":"n.f. 阴性名词，复数 architectures","s":"建筑，建筑学；也指建筑风格或整体结构。人是 un architecte。可用于比喻，如 l'architecture d'un programme（程序的结构）。","ipa":"[aʁ.ʃi.tɛk.tyʁ]","ph":"ar 读 [aʁ]；chi 读 [ʃi]，ch = [ʃ]；tec 读 [tɛk]；ture 读 [tyʁ]，u = [y]，结尾 r 要发。","pi":"architecture 里的 ch 读 [ʃ]，不是 [k]（对比 orchestre 的 ch 读 [k]）；结尾 -ture 读 [tyʁ]。","et":"来自希腊语 arkhi-（首领）+ tektōn（工匠），经拉丁语 architectura 进入法语，意思是「主建筑师的工作」。","ex":[["J'aime l'architecture de ce bâtiment.","我喜欢这栋楼的建筑风格。"],["Elle étudie l'architecture à Lyon.","她在里昂学建筑。"]],"co":[["étudier l'architecture","学建筑"],["l'architecture moderne","现代建筑"],["l'architecture gothique","哥特式建筑"],["un architecte","建筑师"]],"sy":[["construction","courant","建造，工程"],["urbanisme","courant","城市规划"]],"fq":"中频，艺术和城市话题常见。","me":"architecte → architecture：建筑师做的事。","tr":{"zh":"我很喜欢这座城市的建筑。","fr":"J'aime beaucoup l'architecture de cette ville.","alt":"J'adore l'architecture de cette ville.","note":"aimer beaucoup + 名词；L' 是 la 的省音。"}},
 "L'électricité": {"pos":"n.f. 阴性名词，不可数（无复数）","s":"电，电力。家里的电费说 la facture d'électricité。一般不加复数。panne d'électricité = 停电。","ipa":"[e.lɛk.tʁi.si.te]","ph":"é 读 [e]；lec 读 [lɛk]；tri 读 [tʁi]；ci 读 [si]；té 读 [te]，共六个音节。","pi":"词很长，六个音节要读清；ci 里的 c 读 [s]，lec 里的 c 读 [k]。","et":"由 électrique（电的）加 -ité 构成；électrique 来自希腊语 ēlektron（琥珀），因为摩擦琥珀会产生静电。","ex":[["J'ai payé la facture d'électricité.","我付了电费。"],["Il y a une panne d'électricité dans le quartier.","这个街区停电了。"]],"co":[["la facture d'électricité","电费单"],["une panne d'électricité","停电"],["couper l'électricité","断电"],["économiser l'électricité","省电"]],"sy":[["courant","courant","电流，口语也说 le courant"],["énergie","courant","能源"]],"fq":"高频，日常常用。","me":"électrique + -ité：电的性质，即电。","tr":{"zh":"我们家没电了。","fr":"Nous n'avons plus d'électricité à la maison.","alt":"On a plus de courant à la maison.","note":"ne… plus de + 名词，表示再没有……。"}},
 "La fin": {"pos":"n.f. 阴性名词，复数 fins","s":"结尾，末尾，结局。à la fin 是「最后、终于」；en fin de compte 是「说到底」；mettre fin à 是「结束」。fin 同时是形容词「细的、精致的」。","ipa":"[fɛ̃]","ph":"f 读 [f]；in 读鼻化 [ɛ̃]，n 不发音。","pi":"和 faim（饿）、feint（假装的）发音相同；注意拼写区别。","et":"来自拉丁语 finis（边界、终点）。同族词：final、finir（结束）、infini（无限的）。","ex":[["J'attends la fin de l'histoire.","我在等故事的结局。"],["À la fin, tout le monde a applaudi.","最后大家都鼓掌了。"]],"co":[["à la fin","最后；终于"],["la fin de + 名词","……的结尾"],["en fin de compte","说到底"],["mettre fin à","结束"]],"sy":[["conclusion","courant","结论"],["terme","soutenu","终点，较书面"],["le début","courant","反义：开头"]],"fq":"极高频，日常常用。","me":"fin = finish：和英语 finish 同根。","tr":{"zh":"电影的结局让我很惊讶。","fr":"La fin du film m'a beaucoup surpris.","alt":"La fin du film m'a vraiment surpris.","note":"surprendre 的过去分词 surpris，与 m'（我）搭配。"}},
 "La superficie": {"pos":"n.f. 阴性名词，复数 superficies","s":"面积，表面积。说房子或土地大小时用：la superficie totale、la superficie habitable（居住面积）。同义词 surface 更日常。","ipa":"[sy.pɛʁ.fi.si]","ph":"su 读 [sy]；per 读 [pɛʁ]；fi 读 [fi]；cie 读 [si]，e 不发音。","pi":"u 是 [y]；结尾 -cie 读 [si]，不是 [sje]；重音在最后一个音节。","et":"来自拉丁语 superficies（表面），由 super（在……之上）+ facies（面貌）构成。形容词 superficiel 同源。","ex":[["La superficie totale est de 100 m².","总面积是一百平方米。"],["Quelle est la superficie de ce terrain ?","这块地多大？"]],"co":[["la superficie totale","总面积"],["la superficie habitable","居住面积"],["une superficie de + 数量","面积为……"],["en superficie","按面积计算"]],"sy":[["surface","courant","面积，最日常"],["étendue","soutenu","范围，较书面"],["taille","courant","尺寸，大小"]],"fq":"中频，房产和地理话题常见。","me":"super（上面）+ ficie（面）：上面的那层面。","tr":{"zh":"这座花园的面积是两百平方米。","fr":"La superficie de ce jardin est de deux cents mètres carrés.","alt":"Ce jardin fait deux cents mètres carrés.","note":"être de + 数量，表示大小。"}},
 "La taille": {"pos":"n.f. 阴性名词，复数 tailles","s":"大小，尺寸；衣服的尺码；人的身高或腰围。Quelle taille faites-vous ? 是问尺码；de taille moyenne 是中等个头；tour de taille 是腰围。","ipa":"[taj]","ph":"ai 加 ll 合起来读 [aj]；整词 [taj]，结尾 e 不发音。","pi":"taille 中的 ille 读 [aj]，l 不读 [l]；不要读成 [tail]。","et":"来自动词 tailler（切、裁），拉丁语 taliare（切割）；本义是切割出的尺寸。同族词：tailleur（裁缝）。","ex":[["Quelle est la taille de ta chambre ?","你的房间多大？"],["Je fais du 38 en taille de pantalon.","我的裤子穿 38 码。"]],"co":[["la taille de + 名词","……的大小"],["de taille moyenne","中等大小 / 个头"],["quelle taille ?","什么尺码？"],["le tour de taille","腰围"]],"sy":[["dimension","courant","尺寸，更技术"],["grandeur","soutenu","大小，较书面"],["pointure","courant","鞋码，专指鞋"]],"fq":"高频，日常常用。","me":"taille ← tailler：切成的大小。","tr":{"zh":"你穿什么尺码的衣服？","fr":"Quelle taille de vêtements portez-vous ?","alt":"Tu fais quelle taille ?","note":"faire + 尺码，是问尺码的口语说法。"}},
 "Une activité": {"pos":"n.f. 阴性名词，复数 activités","s":"活动，行动，也指职业活动或活跃状态。une activité physique（体育活动）、une activité professionnelle（职业活动）。en activité = 在职、在运作。","ipa":"[ak.ti.vi.te]","ph":"ac 读 [ak]；ti 读 [ti]，这里 t 读 [t]，不是 [s]；vi 读 [vi]；té 读 [te]。","pi":"-tivité 里的 ti 读 [ti]，不读 [si]；重音在最后。","et":"来自拉丁语 activitas，由 activus（积极的，active）而来；同族：actif、agir（行动）。","ex":[["C'est une activité très amusante.","这是个非常有趣的活动。"],["Elle pratique plusieurs activités après l'école.","她放学后参加好几项活动。"]],"co":[["une activité physique","体育活动"],["une activité de loisir","休闲活动"],["une activité professionnelle","职业活动"],["en activité","在职；在运作"]],"sy":[["occupation","courant","事务，消遣"],["passe-temps","courant","消遣"],["loisir","courant","业余爱好"]],"fq":"极高频，日常常用。","me":"actif + -ité：活跃的事。","tr":{"zh":"你喜欢做什么活动？","fr":"Quelles activités aimes-tu faire ?","alt":"T'aimes faire quoi comme activités ?","note":"quelles + 阴性复数名词，作疑问形容词。"}},
 "Une agence immobilière": {"pos":"n.f. 阴性名词，复数 agences immobilières","s":"房产中介公司，负责租房、买房、卖房。agence 是「机构、办事处」，immobilière 是阴性形容词，修饰 agence。里面的人叫 un agent immobilier。","ipa":"[a.ʒɑ̃s i.mɔ.bi.ljɛʁ]","ph":"ag-en-ce：g 在 e 前读 [ʒ]，an/en 读鼻化 [ɑ̃]；immobilière：i 与 m 连读成 [i.mɔ]，-ière 读 [jɛʁ]。","pi":"immobilière 末尾的 -re 不发音节，只有 [jɛʁ]；agence 是阴性，所以形容词也要阴性。","et":"agence 与 agent 同族，来自拉丁语 agere（做、办事）；immobilier 与 immeuble（楼房）同源，字面是「不能移动的（财产）」。","ex":[["Nous sommes allés à l'agence immobilière.","我们去了房产中介。"],["Cette agence immobilière a beaucoup d'appartements à louer.","这家中介有很多公寓出租。"],["Les frais d'agence sont chers.","中介费很贵。"]],"co":[["contacter une agence immobilière","联系房产中介"],["les frais d'agence","中介费"],["un agent immobilier","房产经纪人"]],"sy":[["agent immobilier","courant","指人（经纪人）；agence 指公司"],["agence","courant","泛指机构，如 agence de voyage（旅行社）"]],"fq":"中频，找房时常用。","me":"agence（办事处）+ immobilier（不动产）= 专办「不会动的财产」的机构。","tr":{"zh":"我明天要去房产中介看房子。","fr":"Demain, je vais à l'agence immobilière pour visiter un appartement.","alt":"Demain, je passe à l'agence immobilière voir un appartement.","note":"aller à + 地点；形容词 immobilière 跟 agence 一起用阴性。"}},
 "Une annonce immobilière": {"pos":"n.f. 阴性名词，复数 annonces immobilières","s":"房源广告、房屋租售信息，网上或报纸上都有。annonce 是「告示、启事」，不一定是商业广告。","ipa":"[a.nɔ̃s i.mɔ.bi.ljɛʁ]","ph":"an-nonce：nn 在一起，annonce 读 [a.nɔ̃s]，第二个音节 on 读鼻化 [ɔ̃]；c 在 e 前读 [s]，结尾的 e 不发音。","pi":"annonce 里的 nn 不是两个 n 音，只读一次 n；注意 annonce 是阴性。","et":"annonce 来自动词 annoncer（宣布），源于拉丁语 annuntiare。immobilière 见 agence immobilière。","ex":[["J'ai lu une annonce immobilière intéressante.","我读到一则有意思的房源广告。"],["Je cherche un studio sur les annonces immobilières.","我在房源广告里找单间公寓。"]],"co":[["passer une annonce","发布广告"],["répondre à une annonce","回复广告"],["une petite annonce","分类广告"]],"sy":[["petite annonce","courant","报纸或网站上的小广告"],["publicité / pub","courant","商业广告，更偏推销"]],"fq":"中频，找房时很常见。","me":"annonce = 向大家宣布（annoncer）一间房子要出租。","tr":{"zh":"我在网上找到一则很好的房源广告。","fr":"J'ai trouvé une très bonne annonce immobilière sur Internet.","alt":"J'ai déniché une super annonce immobilière en ligne.","note":"trouver 过去时用 avoir：j'ai trouvé。"}},
 "Une armoire": {"pos":"n.f. 阴性名词，复数 armoires","s":"衣柜、大柜子，独立摆放的家具，里面放衣服或床单。不是嵌入墙里的壁橱（那是 un placard）。","ipa":"[aʁ.mwaʁ]","ph":"ar [aʁ]；oi 读 [wa]；结尾 e 不发音。","pi":"oi 读 [wa]，不要读成 [oi]；armoire 是阴性（une armoire）。","et":"来自拉丁语 armarium（放工具、武器的柜子），与 arme（武器）同族。","ex":[["Mes vêtements sont dans l'armoire.","我的衣服在衣柜里。"],["Il y a une grande armoire dans ma chambre.","我的房间里有一个大衣柜。"]],"co":[["ranger dans l'armoire","放进衣柜"],["une armoire à pharmacie","药柜"],["une armoire à glace","带镜子的衣柜；（口语）大块头男人"]],"sy":[["placard","courant","嵌入墙壁的壁橱"],["penderie","courant","专门挂衣服的衣柜"],["commode","courant","有抽屉的矮柜"]],"fq":"中频，家居词汇。","me":"armoire ← arme：从前用来放武器的柜子。","tr":{"zh":"你的毛衣在衣柜里。","fr":"Ton pull est dans l'armoire.","alt":"Ton pull, il est dans l'armoire.","note":"dans + 地点：在……里。"}},
 "Une assurance": {"pos":"n.f. 阴性名词，复数 assurances","s":"保险，如 assurance maladie（医疗保险）、assurance habitation（房屋保险）。另一个意思是「自信」：avec assurance = 自信地。","ipa":"[a.sy.ʁɑ̃s]","ph":"a-su-rance：ss 在元音间读 [s]；u 读 [y]；an 读鼻化 [ɑ̃]；c 读 [s]，结尾 e 不发音。","pi":"u 读 [y]（嘴圆，发 yu 的感觉），不是 [u]；ss 读清音 [s]。","et":"来自动词 assurer（使确定），assurer 来自 a- + sûr（确定的），拉丁语 securus。","ex":[["Il faut une assurance pour l'appartement.","公寓需要买保险。"],["Elle parle avec assurance.","她说话很自信。"]],"co":[["prendre / souscrire une assurance","买保险"],["une assurance habitation","房屋保险"],["une assurance maladie","医疗保险"],["une assurance auto","车险"]],"sy":[["mutuelle","courant","补充医疗保险"],["garantie","courant","保证；保修"]],"fq":"高频，生活和租房常用。","me":"assurer = 让你「放心」；assurance = 让你放心的东西。","tr":{"zh":"你必须买一份房屋保险。","fr":"Vous devez prendre une assurance habitation.","alt":"Il faut que tu prennes une assurance habitation.","note":"devoir + 动词原形；il faut que 后接虚拟式。"}},
 "Une avenue": {"pos":"n.f. 阴性名词，复数 avenues","s":"大道，宽阔的城市大街，常有树。名字前用 sur l'avenue：Il habite sur l'avenue Victor-Hugo。比 rue（街）宽、通常更重要。","ipa":"[av.ny]","ph":"a-ve-nue：av [av]；nue 读 [ny]，u 是 [y]；结尾 e 不发音。","pi":"u 读 [y]，不是 [u]；只有两个音节 [av.ny]，e 不要读出来。","et":"来自古法语动词 avenir（到达、走来），源于拉丁语 advenire，与 venir 同根；原指通往某处的路。","ex":[["Il habite sur une grande avenue.","他住在一条大道上。"],["Le magasin est au bout de l'avenue.","商店在大道的尽头。"]],"co":[["au bout de l'avenue","在大道的尽头"],["une avenue bordée d'arbres","两旁种树的大道"],["sur l'avenue des Champs-Élysées","在香榭丽舍大道上"]],"sy":[["boulevard","courant","林荫大道，常常更宽"],["rue","courant","普通街道，较窄"],["allée","courant","小路、林荫小道"]],"fq":"中频，地址和问路常用。","me":"a-venue：从四面「来到」（venir）的宽路。","tr":{"zh":"我住在大道旁边的一栋楼里。","fr":"J'habite dans un immeuble à côté de l'avenue.","alt":"J'habite près de l'avenue, dans un immeuble.","note":"habiter + 地点，不加介词时直接接地点。"}},
 "Une buanderie": {"pos":"n.f. 阴性名词，复数 buanderies","s":"洗衣房、洗衣间，家里放洗衣机、晾衣服的小房间。公寓楼里也可以指公用洗衣房。","ipa":"[bɥɑ̃.dʁi]","ph":"bu-an-de-rie：ua 连成半元音 [ɥa]，an 读鼻化 [ɑ̃]，-rie 读 [ʁi]。","pi":"bu 与 an 要连在一起读 [bɥɑ̃]，不要分成 bu-a-n；注意 n 不再发音。","et":"来自古法语动词 buer（用草木灰水洗衣），加后缀 -erie（表示场所）。","ex":[["La machine à laver est dans la buanderie.","洗衣机在洗衣房里。"],["Nous avons une petite buanderie à la cave.","我们在地下室有一间小洗衣房。"]],"co":[["dans la buanderie","在洗衣房里"],["une buanderie commune","公用洗衣房"],["étendre le linge à la buanderie","在洗衣房晾衣服"]],"sy":[["laverie","courant","自助洗衣店（公共）"],["lingerie","soutenu","放衣物的房间；也指女士内衣"]],"fq":"较低频，家居词汇。","me":"bu-an-derie：想到「洗衣」(buer) 的房间。","tr":{"zh":"洗衣机在洗衣房里。","fr":"La machine à laver est dans la buanderie.","alt":"La machine à laver, c'est dans la buanderie.","note":"dans + 地点；machine à laver 是阴性。"}},
 "Une cabine (de bateau)": {"pos":"n.f. 阴性名词，复数 cabines","s":"船舱，船上的小房间或卧室。cabine 还可以指小间：cabine d'essayage（试衣间）、cabine téléphonique（电话亭）、cabine d'avion（机舱）。","ipa":"[ka.bin]","ph":"ca [ka]；bi 读 [bi]；n 要发音：[bin]，结尾 e 不发音但 n 清楚。","pi":"最后的 -ine 读 [in]，不是鼻化音；cabine 的 c 读 [k]。","et":"与 cabane（小木屋）和英语 cabin 同一家族，来源细节不确定。","ex":[["Notre cabine est petite mais confortable.","我们的船舱小但舒适。"],["Où est la cabine d'essayage ?","试衣间在哪里？"]],"co":[["une cabine de bateau","船舱"],["une cabine d'essayage","试衣间"],["une cabine téléphonique","电话亭"],["une cabine d'avion","飞机客舱"]],"sy":[["couchette","courant","卧铺、铺位"],["chambre","courant","房间（陆地上）"]],"fq":"中频，旅行与购物常见。","me":"cabine = 船上的「小房间」，想到 cabane 就记住了。","tr":{"zh":"我们的船舱在二层。","fr":"Notre cabine est au deuxième pont.","alt":"Notre cabine se trouve au deuxième pont.","note":"船上的「层」用 pont（甲板）。"}},
 "Une cave": {"pos":"n.f. 阴性名词，复数 caves","s":"地窖、地下室储藏间，常用来放酒、食物和杂物。法国公寓楼常有每户一间的 cave。「山洞」要说 une grotte。","ipa":"[kav]","ph":"c 在 a 前读 [k]；v 读 [v]；结尾 e 不发音：[kav]。","pi":"只有一个音节 [kav]；v 要发，不要漏；cave 不是「山洞」。","et":"来自拉丁语 cavus（空的、凹的）。同源：caverne（洞穴）。","ex":[["Nous gardons le vin dans la cave.","我们把酒放在地窖里。"],["Mon vélo est à la cave.","我的自行车在地下室里。"]],"co":[["descendre à la cave","下到地下室"],["une cave à vin","酒窖"],["une cave voûtée","拱顶地窖"]],"sy":[["sous-sol","courant","地下层（整层）"],["cellier","soutenu","存放酒和食物的阴凉小间"],["grotte","courant","山洞（自然形成）"]],"fq":"中频，居住话题常用。","me":"cave ← cavus（空洞）：楼下那个「空」的地方。","tr":{"zh":"我把旧家具放在地下室里。","fr":"Je mets mes vieux meubles à la cave.","alt":"Mes vieux meubles, je les range à la cave.","note":"à la cave：在地下室（用 à）。"}},
 "Une colocation": {"pos":"n.f. 阴性名词，复数 colocations","s":"合租（几个人一起租一套房）。vivre en colocation = 合租生活。口语缩写 la coloc。","ipa":"[kɔ.lɔ.ka.sjɔ̃]","ph":"co-lo-ca-tion：-tion 读 [sjɔ̃]；前两个 o 读开口 [ɔ]。","pi":"-tion 读 [sjɔ̃]，不是 [ʃən]；与 location 只差前缀 co-。","et":"co-（共同）+ location（租赁）。同族：colocataire（室友）。","ex":[["Je vis en colocation avec deux amis.","我和两个朋友合租。"],["Elle cherche une colocation près de l'université.","她在大学附近找合租房。"]],"co":[["vivre en colocation","合租生活"],["chercher une colocation","找合租房"],["une colocation étudiante","学生合租"]],"sy":[["coloc","familier","合租（口语缩略）"],["location","courant","租赁（泛称）"]],"fq":"中频，学生与年轻人常用。","me":"co（一起）+ location（租）= 一起租。","tr":{"zh":"我想找一个合租的房子。","fr":"Je voudrais trouver une colocation.","alt":"Je cherche une coloc.","note":"vivre en colocation：用 en，不用 dans。"}},
 "Une croisière": {"pos":"n.f. 阴性名词，复数 croisières","s":"游轮旅行、乘邮轮度假。partir en croisière = 去坐游轮。也可以指在河上或海上的观光航行。","ipa":"[kʁwa.zjɛʁ]","ph":"cr 连读 [kʁ]；oi 读 [wa]；s 在元音间读 [z]；-ière 读 [jɛʁ]。","pi":"oi 读 [wa]，s 读 [z]（不是 [s]）。croisière 是阴性。","et":"来自动词 croiser（交叉、巡航），croiser 来自 croix（十字）。","ex":[["Ils partent en croisière cet été.","他们今年夏天坐游轮。"],["Nous avons fait une croisière sur le Nil.","我们在尼罗河上坐过游轮。"]],"co":[["partir en croisière","去坐游轮"],["faire une croisière","做一次游轮旅行"],["un bateau de croisière","游轮"],["vitesse de croisière","巡航速度"]],"sy":[["voyage en bateau","courant","坐船旅行（泛指）"],["traversée","courant","渡海、横渡（从一点到另一点）"]],"fq":"中频，旅游话题。","me":"cro-isière ← croix：船在海上「划过十字」。","tr":{"zh":"我们明年想坐游轮。","fr":"Nous voulons faire une croisière l'année prochaine.","alt":"L'année prochaine, on veut partir en croisière.","note":"on 在口语中代替 nous。"}},
 "Une cuisine américaine": {"pos":"n.f. 阴性名词，复数 cuisines américaines","s":"开放式厨房，厨房和客厅之间没有墙，常用一个吧台隔开。注意：cuisine américaine 也可以指「美式菜肴」，要看上下文。","ipa":"[kɥi.zin a.me.ʁi.kɛn]","ph":"cui 读 [kɥi]；s 在元音间读 [z]；américaine：é [e]，-aine 读 [ɛn]。","pi":"cuisine 里 s 读 [z]；américaine 的 -aine 读 [ɛn]，不是 [ɑ̃]。","et":"cuisine 来自拉丁语 coquina（厨房），源于 coquere（煮）；américaine 指这种布局来自美国式住宅。","ex":[["J'adore cette cuisine américaine ouverte.","我喜欢这个开放式厨房。"],["Dans une cuisine américaine, on parle avec les invités.","在开放式厨房里，可以和客人聊天。"]],"co":[["une cuisine américaine ouverte","开放式厨房"],["un bar de cuisine américaine","开放式厨房的吧台"],["la cuisine américaine","美式料理（另一意思）"]],"sy":[["cuisine ouverte","courant","开放式厨房，同义"],["cuisine fermée","courant","封闭式厨房（反义）"]],"fq":"中频，租房广告常见。","me":"「美式」生活：厨房和客厅连成一片。","tr":{"zh":"我想要一个开放式厨房。","fr":"Je voudrais une cuisine américaine.","alt":"J'aimerais avoir une cuisine ouverte sur le salon.","note":"voudrais 是 vouloir 的条件式，更礼貌。"}},
 "Une cuisine équipée": {"pos":"n.f. 阴性名词，复数 cuisines équipées","s":"设备齐全的厨房，带橱柜，常有灶台、冰箱、洗碗机等。租房广告里很常见，表示「厨房可以直接用」。","ipa":"[kɥi.zin e.ki.pe]","ph":"é-qui-pée：qu 读 [k]；é 读 [e]；结尾 -ée 读 [e]，不发 e。","pi":"qu 读 [k]：[e.ki.pe]；équipée 与 cuisine 都是阴性，形容词加 -e。","et":"équipée 是动词 équiper（装备）的阴性过去分词；équiper 本义是给船配备人员和物资。","ex":[["L'appartement a une cuisine équipée.","公寓有设备齐全的厨房。"],["Elle rêve d'une cuisine équipée avec un grand frigo.","她梦想有一间带大冰箱的齐全厨房。"]],"co":[["une cuisine entièrement équipée","全套设备的厨房"],["louer un appartement avec cuisine équipée","租带齐全厨房的公寓"],["équiper une cuisine","给厨房配齐设备"]],"sy":[["cuisine aménagée","courant","装好橱柜的厨房，不一定有电器"],["cuisine meublée","courant","有家具的厨房"]],"fq":"中频，租房广告常见。","me":"équipée = 配好了装备，像一支队伍（équipe）。","tr":{"zh":"这套公寓有设备齐全的厨房。","fr":"Cet appartement a une cuisine équipée.","alt":"Dans cet appartement, la cuisine est équipée.","note":"équipée 要和 cuisine 一样用阴性。"}},
 "Une entrée": {"pos":"n.f. 阴性名词，复数 entrées","s":"入口；玄关（进门处）。还指前菜（餐厅里的 entrée，主菜前的第一道）和入场：entrée libre（免费入场）。","ipa":"[ɑ̃.tʁe]","ph":"en 读鼻化 [ɑ̃]；tr [tʁ]；ée 读 [e]。","pi":"ent 的 t 不是结尾，en 读 [ɑ̃]；-ée 读 [e]，不读 e。entrée 在餐厅是前菜，不是主菜。","et":"来自动词 entrer（进入），源于拉丁语 intrare。反义：sortie（出口）。","ex":[["Laisse tes chaussures dans l'entrée.","把鞋放在玄关。"],["En entrée, je prends une salade.","前菜我要一份沙拉。"]],"co":[["l'entrée de l'immeuble","楼的入口"],["entrée libre","免费入场"],["entrée, plat, dessert","前菜、主菜、甜点"],["une porte d'entrée","大门"]],"sy":[["hall","courant","大楼门厅"],["vestibule","soutenu","门廊、小门厅"],["sortie","courant","出口（反义）"]],"fq":"极高频，日常常用。","me":"entrée = 「进」去的地方，也是饭桌上先「进」的菜。","tr":{"zh":"你可以把伞放在玄关。","fr":"Tu peux mettre ton parapluie dans l'entrée.","alt":"Pose ton parapluie dans l'entrée.","note":"mettre / poser + 物品 + dans l'entrée。"}},
 "Une génération": {"pos":"n.f. 阴性名词，复数 générations","s":"一代人，同一时期出生或同一年龄层的人（如 la génération Z）；也指技术或产品的「一代」。de génération en génération = 代代相传。","ipa":"[ʒe.ne.ʁa.sjɔ̃]","ph":"gé [ʒe]；né [ne]；ra [ʁa]；-tion 读 [sjɔ̃]。","pi":"g 在 é 前读 [ʒ]；-tion 读 [sjɔ̃]；四个音节，重音在最后。","et":"来自拉丁语 generatio（生出），源于 generare，与 genre、génétique 同族。","ex":[["C'est la nouvelle génération.","这是新一代。"],["Ma grand-mère et moi, nous sommes de deux générations différentes.","我和奶奶是两代不同的人。"]],"co":[["la jeune génération","年轻一代"],["de génération en génération","代代相传"],["la génération Z","Z 世代"],["la dernière génération","最新一代（产品）"]],"sy":[["époque","courant","时代、时期"],["classe d'âge","courant","年龄层"]],"fq":"中频，社会话题常用。","me":"génération ← générer：不断「生出」新人。","tr":{"zh":"年轻一代用手机很熟练。","fr":"La jeune génération utilise très bien son téléphone.","alt":"Les jeunes d'aujourd'hui sont très à l'aise avec leur téléphone.","note":"génération 是阴性名词，所以用 la。"}},
 "Une horloge": {"pos":"n.f. 阴性名词，复数 horloges","s":"挂钟、大钟（墙上或塔上的）。手表叫 une montre，闹钟叫 un réveil。l'horloge biologique = 生物钟。","ipa":"[ɔʁ.lɔʒ]","ph":"h 不发音；or [ɔʁ]；lo [lɔ]；ge 读 [ʒ]，结尾 e 不发音：[ɔʁ.lɔʒ]。","pi":"h 是哑音：l'horloge 要省音，读 [lɔʁ.lɔʒ]；horloge 是阴性。","et":"来自拉丁语 horologium，希腊语 hōrologion（hōra「时间」+ legein「说」）。","ex":[["L'horloge indique midi.","钟指向中午。"],["Il y a une vieille horloge dans le salon.","客厅里有一座老钟。"]],"co":[["une horloge murale","挂钟"],["l'horloge biologique","生物钟"],["l'horloge parlante","报时电话"],["régler comme une horloge","像钟一样准"]],"sy":[["pendule","courant","摆钟、台钟"],["montre","courant","手表"],["réveil","courant","闹钟"]],"fq":"较低频，家居与时间话题。","me":"hor-loge：想到 heure（小时）的钟。","tr":{"zh":"墙上的钟停了。","fr":"L'horloge murale s'est arrêtée.","alt":"La pendule du mur ne marche plus.","note":"s'arrêter 是代动词，过去时用 être。"}},
 "Une location": {"pos":"n.f. 阴性名词，复数 locations","s":"出租、租赁，也指租来的东西：une location de vacances（度假租赁）、location de voiture（租车）。可以是租入或租出，看语境。","ipa":"[lɔ.ka.sjɔ̃]","ph":"lo [lɔ]；ca [ka]；-tion 读 [sjɔ̃]。","pi":"-tion 读 [sjɔ̃]，不是 [ʃən]；location 不是「地点」（地点是 lieu）。","et":"来自拉丁语 locatio，源于 locare（安置、出租），与 lieu 的拉丁词根 locus 同族。","ex":[["C'est une location de vacances.","这是度假租赁。"],["Nous prenons une location de voiture pour le week-end.","我们周末租一辆车。"]],"co":[["une location de vacances","度假租赁"],["une location de voiture","租车"],["en location","出租中；租来的"],["louer / mettre en location","出租"]],"sy":[["bail","courant","租约"],["loyer","courant","房租"],["louer","courant","动词，租入或租出"]],"fq":"高频，租房与旅游常用。","me":"location 是「租」，不是英语的「地点」。","tr":{"zh":"我们在海边租了一套公寓。","fr":"Nous avons pris une location au bord de la mer.","alt":"On a loué un appartement au bord de la mer.","note":"prendre une location = 租下；louer 更常用。"}},
 "Une machine à laver": {"pos":"n.f. 阴性名词，复数 machines à laver","s":"洗衣机。在店里或说明书里常叫 lave-linge。faire une machine = 洗一批衣服（口语）。","ipa":"[ma.ʃin a la.ve]","ph":"ma-chine：ch 读 [ʃ]；à 与 laver 连读成 [a la.ve]；-er 读 [e]。","pi":"ch 读 [ʃ]；à 带重音符号，是介词；machine 是阴性。","et":"machine 来自拉丁语 machina，希腊语 mēkhanē；laver 来自拉丁语 lavare。","ex":[["La machine à laver est en panne.","洗衣机坏了。"],["Je fais une machine de linge blanc.","我洗一批白衣服。"]],"co":[["faire une machine","洗一批衣服（口语）"],["mettre le linge dans la machine","把衣服放进洗衣机"],["la machine à laver est en panne","洗衣机坏了"]],"sy":[["lave-linge","courant","洗衣机（标准名称）"],["lave-vaisselle","courant","洗碗机"],["sèche-linge","courant","烘干机"]],"fq":"高频，家务话题。","me":"machine à laver = 专门「洗」(laver) 的机器。","tr":{"zh":"我的洗衣机坏了。","fr":"Ma machine à laver est en panne.","alt":"Ma machine à laver ne marche plus.","note":"en panne = 坏了；panne 是阴性。"}},
 "Une métropole": {"pos":"n.f. 阴性名词，复数 métropoles","s":"大都市，一个国家或地区里重要的大城市，如 Paris, Lyon。la France métropolitaine = 法国本土。","ipa":"[me.tʁɔ.pɔl]","ph":"mé [me]；tro [tʁɔ]；pole [pɔl]，o 都读开口 [ɔ]，l 要发音。","pi":"结尾 -ole 读 [ɔl]，l 要发出；métropole 是阴性。","et":"来自希腊语 mētropolis（mētēr「母亲」+ polis「城市」），原指「母城」。同源英语 metropolis。","ex":[["Paris est une grande métropole.","巴黎是一座大都会。"],["Beaucoup de jeunes veulent vivre dans une métropole.","很多年轻人想住在大都市。"]],"co":[["une grande métropole","大都市"],["la France métropolitaine","法国本土"],["une métropole européenne","欧洲大都市"]],"sy":[["grande ville","courant","大城市（更口语）"],["capitale","courant","首都"],["agglomération","soutenu","城市群、都市区"]],"fq":"中频，城市话题。","me":"méTROPOLE：mère-城，是「大城」的老家。","tr":{"zh":"里昂是法国的一座大都市。","fr":"Lyon est une grande métropole française.","alt":"Lyon, c'est une grande ville de France.","note":"français 的阴性是 française。"}},
 "Une offre": {"pos":"n.f. 阴性名词，复数 offres","s":"提供、报价；优惠；职位招聘。une offre d'emploi = 招聘启事 / 工作邀约；une offre spéciale = 特价。l'offre et la demande = 供给与需求。","ipa":"[ɔfʁ]","ph":"o [ɔ]；ff 读一个 [f]；结尾 -fre 读 [fʁ]，e 不发音。","pi":"只有一个音节 [ɔfʁ]；ff 不要读成两遍；offre 是阴性。","et":"来自动词 offrir（提供），源于拉丁语 offerre（送上）。","ex":[["J'ai reçu une offre d'emploi.","我收到一份工作邀约。"],["Il y a une offre spéciale sur les chaussures.","鞋子有特价优惠。"]],"co":[["une offre d'emploi","招聘信息；工作邀约"],["une offre spéciale","特价优惠"],["l'offre et la demande","供给与需求"],["accepter / refuser une offre","接受 / 拒绝报价"]],"sy":[["proposition","courant","提议"],["promotion / promo","courant","促销"],["demande","courant","需求（反义）"]],"fq":"高频，购物和工作都常用。","me":"offre ← offrir：递上一份「礼物」。","tr":{"zh":"我看到一份有意思的工作邀约。","fr":"J'ai vu une offre d'emploi intéressante.","alt":"Je suis tombé sur une offre d'emploi intéressante.","note":"voir 过去分词 vu。"}},
 "Une personne": {"pos":"n.f. 阴性名词，复数 personnes（一直是阴性，即使指男人）","s":"人。une personne 永远是阴性，即使指男人：C'est une personne gentille。另外 personne 还是不定代词：ne… personne / personne ne = 没有人。","ipa":"[pɛʁ.sɔn]","ph":"per [pɛʁ]；son 读 [sɔn]：o 是口音 [ɔ]，n 要发出，不是鼻化 [ɔ̃]；结尾 e 不发音。","pi":"onne 读 [ɔn]，不是鼻化音；une personne 是阴性，指男人也用阴性。","et":"来自拉丁语 persona（演员的面具，后来指「人物」）。","ex":[["Il y a une personne à la porte.","门口有一个人。"],["C'est une personne très gentille.","他是个很善良的人。"],["Personne ne vient.","没有人来。"]],"co":[["une personne âgée","老人"],["par personne","每人"],["en personne","亲自"],["ne… personne","没有人"]],"sy":[["gens","courant","人们（复数，不用数字）"],["individu","soutenu","个人"],["homme","courant","男人；人类"]],"fq":"极高频，日常常用。","me":"personne：从舞台「面具」到「人」；ne… personne 却是「没有人」。","tr":{"zh":"桌子是给四个人订的。","fr":"La table est réservée pour quatre personnes.","alt":"On a réservé une table pour quatre personnes.","note":"quatre personnes：复数加 s，personne 为阴性。"}},
 "Une plante": {"pos":"n.f. 阴性名词，复数 plantes","s":"植物，家里的盆栽、绿植；也指脚掌：la plante du pied。une plante verte = 绿植；une plante d'intérieur = 室内植物。","ipa":"[plɑ̃t]","ph":"pl [pl]；an 读鼻化 [ɑ̃]；结尾 t 要发音：[plɑ̃t]（因为后面有 e）。","pi":"plante 的 t 要读出来，不同于 plan [plɑ̃]；an 是鼻化音。","et":"来自拉丁语 planta（嫩枝、幼苗）。同族：planter（种）、plantation。","ex":[["J'ai acheté une belle plante verte.","我买了一盆漂亮的绿植。"],["Il faut arroser les plantes tous les jours.","植物每天都要浇水。"]],"co":[["arroser les plantes","给植物浇水"],["une plante verte","绿植"],["une plante d'intérieur","室内植物"],["la plante du pied","脚掌"]],"sy":[["végétal","soutenu","植物（科学用语）"],["fleur","courant","花"],["arbre","courant","树"]],"fq":"中频，居家话题常用。","me":"plante ← planter：被「种」下去的东西。","tr":{"zh":"我每周给植物浇两次水。","fr":"J'arrose mes plantes deux fois par semaine.","alt":"Deux fois par semaine, j'arrose mes plantes.","note":"arroser 是第一组动词。"}},
 "Une plateforme": {"pos":"n.f. 阴性名词，复数 plateformes（也写 plate-forme）","s":"平台。常指网络平台：une plateforme en ligne（在线平台）、plateforme de streaming。也指石油平台 plateforme pétrolière。火车站的「站台」要说 quai。","ipa":"[plat.fɔʁm]","ph":"plate [plat]；forme [fɔʁm]；两个词合成一个：[plat.fɔʁm]。","pi":"t 要读出来；站台不用 plateforme，而用 quai；plateforme 是阴性。","et":"由 plat（平的）+ forme（形状）组成，字面「平的形」。","ex":[["Tu peux t'inscrire sur la plateforme de l'université.","你可以在大学平台上注册。"],["Cette plateforme permet de réserver un logement.","这个平台可以预订住宿。"]],"co":[["une plateforme en ligne","在线平台"],["une plateforme de streaming","流媒体平台"],["s'inscrire sur une plateforme","在平台上注册"]],"sy":[["site","courant","网站"],["quai","courant","车站站台"],["estrade","soutenu","小讲台"]],"fq":"中频，网络话题常用。","me":"plate-forme = 「平」(plat) 的「形」(forme)，一块平台。","tr":{"zh":"你要在这个平台上注册。","fr":"Tu dois t'inscrire sur cette plateforme.","alt":"Il faut que tu t'inscrives sur cette plateforme.","note":"s'inscrire sur / à：在……注册。"}},
 "Une résidence (universitaire)": {"pos":"n.f. 阴性名词，复数 résidences universitaires","s":"学生宿舍、大学生公寓楼。résidence 本身是「住所、住宅区」：résidence principale（主要住所）、résidence secondaire（度假屋）。","ipa":"[ʁe.zi.dɑ̃s]","ph":"ré [ʁe]；si 读 [zi]（s 在元音间读 [z]）；dence 读 [dɑ̃s]。","pi":"s 读 [z]；-dence 里 en 读鼻化 [ɑ̃]；résidence 是阴性。","et":"来自拉丁语 residere（坐下、留下），re- + sedere（坐）。","ex":[["Elle vit dans une résidence universitaire.","她住在大学宿舍。"],["Ils ont une résidence secondaire à la montagne.","他们在山里有一间度假屋。"]],"co":[["une résidence universitaire","大学生宿舍"],["une résidence principale","主要住所"],["une résidence secondaire","度假屋、第二住所"],["le lieu de résidence","居住地"]],"sy":[["cité U","familier","大学城宿舍（cité universitaire 的缩写）"],["foyer","courant","宿舍、公寓（学生、工人）"],["logement","courant","住处"]],"fq":"中频，学生生活常见。","me":"résid-ence：想到 resident（居民）。","tr":{"zh":"我在大学宿舍里有一间房。","fr":"J'ai une chambre dans une résidence universitaire.","alt":"Je loge dans une résidence universitaire.","note":"avoir une chambre dans + 地点。"}},
 "Une table de chevet": {"pos":"n.f. 阴性名词，复数 tables de chevet","s":"床头柜。chevet 是床头、枕头那一端。也说 une table de nuit。un livre de chevet = 经常放在枕边读的书。","ipa":"[tabl də ʃə.vɛ]","ph":"table [tabl]；de 读弱音 [də]；chevet：ch [ʃ]，e 读弱音 [ə]，-et 读 [ɛ]，t 不发音。","pi":"chevet 里 ch 读 [ʃ]，结尾 t 不发音；整个词组是阴性（la table）。","et":"chevet 来自拉丁语 capitium（头的一端），与 caput（头）同族。","ex":[["Mon livre est sur ma table de chevet.","我的书在床头柜上。"],["Il y a une lampe sur la table de chevet.","床头柜上有一盏灯。"]],"co":[["une lampe de chevet","床头灯"],["un livre de chevet","枕边书"],["une table de chevet en bois","木头床头柜"]],"sy":[["table de nuit","courant","同义，床头柜"],["chevet","soutenu","床头（本义）"]],"fq":"中频，卧室用品。","me":"chevet = 床的「头」，旁边放着一张小桌子。","tr":{"zh":"我把手机放在床头柜上。","fr":"Je pose mon téléphone sur la table de chevet.","alt":"Mon téléphone, je le mets sur la table de chevet.","note":"poser = 放（平放）。"}},
 "Une véranda": {"pos":"n.f. 阴性名词，复数 vérandas","s":"玻璃阳光房，加在房子外面或后面的玻璃房间，冬天也能晒太阳。比 balcon（阳台）封闭，比 serre（温室）更适合居住。","ipa":"[ve.ʁɑ̃.da]","ph":"vé [ve]；ran 读鼻化 [ʁɑ̃]；da [da]。三个音节，重音在最后。","pi":"an 读鼻化音 [ɑ̃]，不是 [an]；v 读 [v]；结尾 a 要读出来。","et":"借自英语 veranda，更早的来源有争议，来源不确定。","ex":[["Nous mangeons souvent dans la véranda.","我们常在阳光房里吃饭。"],["La véranda est pleine de plantes.","阳光房里全是植物。"]],"co":[["dans la véranda","在阳光房里"],["une véranda vitrée","玻璃阳光房"],["agrandir la maison avec une véranda","用阳光房扩建房子"]],"sy":[["serre","courant","温室（种植物）"],["jardin d'hiver","courant","冬季花园，类似阳光房"],["balcon","courant","阳台（开放式）"]],"fq":"较低频，居住话题。","me":"véranda：想象一个全是玻璃的小房间，阳光满屋。","tr":{"zh":"我们在阳光房里喝咖啡。","fr":"Nous buvons le café dans la véranda.","alt":"On prend le café dans la véranda.","note":"prendre le café = 喝咖啡（常用说法）。"}},
 "Des étagères": {"pos":"n.f.pl. 阴性名词复数（单数 une étagère）","s":"架子、搁板、书架的层板。une étagère 是墙上或柜子里的架子，也指一整个小书架。","ipa":"[e.ta.ʒɛʁ]","ph":"é [e]；ta [ta]；gè [ʒɛʁ]：g 在 è 前读 [ʒ]；les étagères 要连读：[le.ze.ta.ʒɛʁ]。","pi":"g 读 [ʒ]；les étagères 之间要连读 [z]；单数 une étagère。","et":"étagère 来自 étage（层）+ 后缀 -ère；étage 来自古法语 estage。","ex":[["J'ai mis mes livres sur les étagères.","我把书放在架子上。"],["Il y a trois étagères dans le placard.","壁橱里有三层搁板。"]],"co":[["une étagère à livres","书架"],["monter des étagères","安装架子"],["sur l'étagère du haut","在最上层的架子上"]],"sy":[["rayon","courant","货架；书架的层"],["bibliothèque","courant","书柜"],["rangement","courant","收纳（泛指）"]],"fq":"中频，家居词汇。","me":"étagère = étage 的小家具：一层一层的架子。","tr":{"zh":"你可以把书放在最上面的架子上。","fr":"Tu peux mettre les livres sur l'étagère du haut.","alt":"Pose les livres sur l'étagère du haut.","note":"du haut = 最上面的。"}},
 "Des placards": {"pos":"n.m.pl. 阳性名词复数（单数 un placard）","s":"壁橱、橱柜，嵌在墙里或厨房里的柜子。placard à balais = 放扫帚的小间。mettre au placard = 把某人或某事搁置、冷落（比喻）。","ipa":"[pla.kaʁ]","ph":"pla [pla]；card [kaʁ]；结尾 d 不发音，r 要发 [ʁ]。","pi":"placard 的 d 不发音；placard 是阳性（un placard）。","et":"与 plaque、plaquer（贴上）同一家族，来源细节不确定。","ex":[["Range les assiettes dans les placards.","把盘子放进橱柜。"],["Les placards de la cuisine sont trop petits.","厨房的橱柜太小了。"]],"co":[["ranger dans les placards","放进橱柜"],["un placard à balais","放扫帚的小间"],["mettre quelqu'un au placard","把某人冷落（比喻）"]],"sy":[["armoire","courant","独立大衣柜"],["penderie","courant","挂衣柜"],["meuble de rangement","courant","收纳家具"]],"fq":"中频，家居词汇。","me":"placard：d 不读，想成 pla-CAR。","tr":{"zh":"盘子在厨房的橱柜里。","fr":"Les assiettes sont dans les placards de la cuisine.","alt":"Les assiettes, c'est dans les placards de la cuisine.","note":"de la cuisine 说明哪里的橱柜。"}},
 "Des plaques (de cuisson)": {"pos":"n.f.pl. 阴性名词复数（单数 une plaque de cuisson）","s":"灶台、炉头，指做饭用的加热面板（电的、燃气的或电磁的）。plaque 的本义是「板、片」，所以 plaque de cuisson = 烹饪用的板。","ipa":"[plak də kɥi.sɔ̃]","ph":"plaque：qu 读 [k]，结尾 e 不发音：[plak]；cuisson：cui 读 [kɥi]，ss 读 [s]，结尾 on 读鼻化 [ɔ̃]。","pi":"plaque 的 qu 读 [k]；cuisson 的 ss 读 [s]；单数 plaque，复数 plaques，s 不发音。","et":"来源不确定，与 plaquer（贴上、压平）同族；cuisson 来自动词 cuire（煮）。","ex":[["Je fais chauffer l'eau sur les plaques.","我在灶台上烧水。"],["Les plaques de cuisson sont à induction.","灶台是电磁炉。"]],"co":[["une plaque de cuisson","灶台"],["une plaque à induction","电磁炉"],["une plaque d'immatriculation","车牌"],["une plaque de chocolat","一块巧克力"]],"sy":[["table de cuisson","courant","灶台（更正式）"],["cuisinière","courant","带烤箱的炉灶"],["four","courant","烤箱"]],"fq":"中频，厨房话题。","me":"plaque = 板；烹饪用的板就是灶台。","tr":{"zh":"灶台还很烫。","fr":"Les plaques de cuisson sont encore chaudes.","alt":"Les plaques sont encore bien chaudes.","note":"chaudes 与 plaques 一致，阴性复数。"}},
 "Des réparations": {"pos":"n.f.pl. 阴性名词复数（单数 une réparation）","s":"维修、修理，修东西的工作。faire des réparations = 做维修；en réparation = 在维修中。动词是 réparer。","ipa":"[ʁe.pa.ʁa.sjɔ̃]","ph":"ré [ʁe]；pa [pa]；ra [ʁa]；-tions 读 [sjɔ̃]，结尾 s 不发音。","pi":"-tion 读 [sjɔ̃]；两个 r 都要读 [ʁ]；单复数同音。","et":"来自拉丁语 reparatio，源于 reparare（re- 再 + parare 准备、整理）。","ex":[["Il faut faire des réparations dans la maison.","房子需要维修。"],["Le plombier fait des réparations dans la salle de bains.","水管工在浴室里做维修。"]],"co":[["faire des réparations","做维修"],["en réparation","维修中"],["un atelier de réparation","维修店"],["les frais de réparation","维修费用"]],"sy":[["rénovation","courant","翻新（范围更大）"],["travaux","courant","工程、装修"],["dépannage","courant","紧急修理"]],"fq":"中频，居家话题常用。","me":"réparation = 重新（ré-）整理好（parer）。","tr":{"zh":"房东要做一些维修。","fr":"Le propriétaire doit faire des réparations.","alt":"Le propriétaire va devoir faire quelques réparations.","note":"devoir + 动词原形：必须。"}},
 "Des rideaux": {"pos":"n.m.pl. 阳性名词复数（单数 un rideau）","s":"窗帘。还有 rideau de douche（浴帘）、rideau de fer（卷帘门；le rideau de fer 也指冷战时的「铁幕」）。","ipa":"[ʁi.do]","ph":"ri [ʁi]；deaux 读 [do]，eau 读 [o]，结尾 x 不发音。","pi":"eaux 读 [o]，复数 x 不发音；单数 rideau，复数 rideaux。","et":"来自动词 rider（起皱、打褶）+ -eau，原指窗帘打褶的样子。","ex":[["Ferme les rideaux s'il te plaît.","请把窗帘拉上。"],["Les rideaux du salon sont bleus.","客厅的窗帘是蓝色的。"]],"co":[["tirer / fermer les rideaux","拉上窗帘"],["ouvrir les rideaux","拉开窗帘"],["un rideau de douche","浴帘"],["accrocher des rideaux","挂窗帘"]],"sy":[["voilage","courant","薄纱窗帘"],["store","courant","百叶帘、卷帘"],["tenture","soutenu","厚重的挂布"]],"fq":"中频，家居词汇。","me":"rideaux：一幅幅「打褶」(rider) 的布。","tr":{"zh":"晚上我把窗帘拉上。","fr":"Le soir, je ferme les rideaux.","alt":"Le soir, je tire les rideaux.","note":"fermer / tirer les rideaux 都可以。"}},
 "Des volets": {"pos":"n.m.pl. 阳性名词复数（单数 un volet）","s":"窗外的护窗板、百叶窗，装在窗外两侧的木板或铁板，可以开合。volets roulants = 卷帘窗。volet 也可指「部分」，如 un volet d'un plan。","ipa":"[vɔ.lɛ]","ph":"vo [vɔ]；let 读 [lɛ]，结尾 t 不发音；复数 s 不发音。","pi":"volet 结尾 t 不发音；volet 与 voler（飞）读音接近，注意区分。","et":"来源不确定；原指可以开合的小板。","ex":[["J'ouvre les volets le matin.","我早上打开百叶窗。"],["Les volets sont fermés, il n'y a personne.","护窗板关着，没有人。"]],"co":[["ouvrir / fermer les volets","打开 / 关上护窗板"],["des volets roulants","卷帘窗"],["des volets en bois","木制护窗板"]],"sy":[["persienne","courant","有活动叶片的百叶窗"],["store","courant","窗帘、卷帘"]],"fq":"中频，居家话题。","me":"volet：窗外那块能开合的「板」，结尾 t 不读。","tr":{"zh":"晚上我把护窗板关上。","fr":"Le soir, je ferme les volets.","alt":"Le soir, je ferme mes volets.","note":"les volets 表示窗外的护窗板。"}},
 "Les charges": {"pos":"n.f.pl. 阴性名词复数（单数 une charge）","s":"租房里的杂费，如水、暖气、楼梯清洁、公共部分电费。loyer + charges = 房租加杂费。charges comprises (cc) = 含杂费。charge 本义是「负担」。","ipa":"[ʃaʁʒ]","ph":"ch 读 [ʃ]；a 读 [a]；r [ʁ]；ge 读 [ʒ]，结尾 e 不发音：[ʃaʁʒ]。","pi":"ch 读 [ʃ]；les charges 前不连读；租房时 charges 和 loyer 不同。","et":"来自动词 charger（装载），源于拉丁语 carricare（装车），与 carrus（车）同族。","ex":[["Les charges sont comprises dans le loyer.","杂费含在房租里。"],["Le loyer est de 600 euros, plus 80 euros de charges.","房租 600 欧，另加 80 欧杂费。"]],"co":[["charges comprises","含杂费"],["les charges de copropriété","物业管理费"],["le loyer plus les charges","房租加杂费"],["prendre en charge","负责；承担费用"]],"sy":[["frais","courant","费用（泛称）"],["loyer","courant","房租，不含 charges"],["dépenses","courant","开销"]],"fq":"高频，租房必备。","me":"charges = 房子的「负担」：每月要付的小费用。","tr":{"zh":"房租是七百欧，杂费另算。","fr":"Le loyer est de sept cents euros, charges non comprises.","alt":"C'est 700 euros de loyer, sans les charges.","note":"charges non comprises = 不含杂费。"}},
 "Un canapé-lit / Un clic-clac": {"pos":"n.m. 阳性名词，复数 canapés-lits / clic-clac（clic-clac 不变）","s":"沙发床，白天是沙发，晚上可以变成床。un clic-clac 是一种可以拉平的沙发床，名字来自「咔嗒」声。","ipa":"[ka.na.pe.li]","ph":"canapé-lit：[ka.na.pe.li]，canapé 的 é 读 [e]，lit 的 t 不发音；clic-clac [klik.klak]，两个 c 都读 [k]。","pi":"lit 的 t 不发音；clic-clac 读 [klik.klak]；都是阳性。","et":"canapé 来自拉丁语 conopeum，希腊语 kōnōpeion（蚊帐），后来指有帐子的沙发；lit 来自拉丁语 lectus（床）；clic-clac 是拟声词。","ex":[["Mes amis dorment sur le canapé-lit.","我的朋友睡沙发床。"],["Nous avons un clic-clac dans le salon pour les invités.","客厅里有一张沙发床给客人用。"]],"co":[["ouvrir le canapé-lit","打开沙发床"],["dormir sur un clic-clac","睡在沙发床上"],["un canapé-lit deux places","双人沙发床"]],"sy":[["canapé convertible","courant","可变床的沙发，同义"],["futon","courant","日式床垫"],["lit pliant","courant","折叠床"]],"fq":"中频，家居与待客话题。","me":"canapé（沙发）+ lit（床）= 沙发床；clic-clac = 「咔嗒」一下变成床。","tr":{"zh":"我们有一张沙发床给客人睡。","fr":"Nous avons un canapé-lit pour les invités.","alt":"On a un clic-clac pour les invités.","note":"pour + 人：为某人用。"}},
 "Un étudiant étranger / Une étudiante étrangère": {"pos":"n.m. / n.f. 名词，复数 étudiants étrangers / étudiantes étrangères","s":"外国留学生。étudiant 是男生，étudiante 是女生；形容词 étranger（阳）/ étrangère（阴）跟着改。更中性的说法是 étudiant international。","ipa":"[e.ty.djɑ̃ e.tʁɑ̃.ʒe]","ph":"étudiant：u 读 [y]，-iant 读 [jɑ̃]；étranger：an 读 [ɑ̃]，g 在 e 前读 [ʒ]，-er 读 [e]；阴性 étudiante [e.ty.djɑ̃t]，étrangère [e.tʁɑ̃.ʒɛʁ]。","pi":"étranger 是「外国的」，étrange 是「奇怪的」，别混；阴性要读出 t 和 r：étudiante, étrangère。","et":"étudiant 来自拉丁语 studere（努力、学习）；étranger 来自古法语 estrange，拉丁语 extraneus（外部的）。","ex":[["Il est étudiant étranger en France.","他是在法国的外国学生。"],["Cette étudiante étrangère parle très bien français.","这位外国留学生法语说得很好。"]],"co":[["un étudiant étranger","男留学生"],["une étudiante étrangère","女留学生"],["un étudiant en échange","交换生"],["un visa étudiant","学生签证"]],"sy":[["étudiant international","courant","国际学生，更中性"],["élève","courant","中小学生"]],"fq":"中频，留学与学习话题。","me":"étudiant + étranger：想成「来自外面（extra）的学生」。","tr":{"zh":"她是在法国学习的外国留学生。","fr":"C'est une étudiante étrangère qui étudie en France.","alt":"Elle est étudiante étrangère en France.","note":"étudiante étrangère：阴性两处都要加 e。"}},
 "Un(e) architecte": {"pos":"n.m. / n.f. 名词，阴阳同形：un architecte / une architecte，复数 architectes","s":"建筑师。男女同形，只改冠词：un architecte / une architecte。architecte d'intérieur = 室内设计师。","ipa":"[aʁ.ʃi.tɛkt]","ph":"ar [aʁ]；chi 读 [ʃi]；tecte 读 [tɛkt]，结尾 ct 两个音都读 [kt]。","pi":"ch 在这里读 [ʃ]（和 archéologue 里的 [k] 不同）；结尾 -ct 要发 [kt]。","et":"来自希腊语 arkhitektōn（arkhi- 首领 + tektōn 工匠），经拉丁语传入。","ex":[["Mon frère est architecte.","我哥哥是建筑师。"],["Une architecte a dessiné notre maison.","一位女建筑师设计了我们的房子。"]],"co":[["un cabinet d'architecte","建筑事务所"],["un architecte d'intérieur","室内设计师"],["faire appel à un architecte","请建筑师"]],"sy":[["urbaniste","courant","城市规划师"],["ingénieur","courant","工程师"],["décorateur","courant","装饰师"]],"fq":"中频，职业话题。","me":"archi-tecte：「首席」(arkhi) 的「工匠」(tektōn)。","tr":{"zh":"我姐姐是一位建筑师。","fr":"Ma sœur est architecte.","alt":"Ma sœur est architecte de métier.","note":"职业前不加冠词：Elle est architecte。"}},
 "Un(e) colocataire": {"pos":"n.m. / n.f. 名词，阴阳同形：un colocataire / une colocataire，复数 colocataires","s":"室友，合租同一套房的人。男女同形，只改冠词。口语缩写 un coloc / une coloc。","ipa":"[kɔ.lɔ.ka.tɛʁ]","ph":"co-lo-ca-taire：-aire 读 [ɛʁ]；前两个 o 读 [ɔ]。","pi":"-aire 读 [ɛʁ]，不是 [aiʁ]；colocataire 男女同形。","et":"co-（共同）+ locataire（租户）。同族：colocation。","ex":[["Ma colocataire est très sympa.","我的室友很友好。"],["Mon colocataire fait la cuisine ce soir.","我的室友今晚做饭。"]],"co":[["chercher un colocataire","找室友"],["mon colocataire / ma colocataire","我的室友"],["partager avec un colocataire","和室友分享"]],"sy":[["coloc","familier","室友（口语）"],["camarade de chambre","courant","舍友"],["locataire","courant","租户"]],"fq":"中频，学生生活常见。","me":"co + locataire = 一起租房的人。","tr":{"zh":"我的室友今晚不在家。","fr":"Mon colocataire n'est pas à la maison ce soir.","alt":"Mon coloc n'est pas là ce soir.","note":"女室友用 ma colocataire。"}},
 "Un(e) habitant(e)": {"pos":"n.m. / n.f. 名词，阳性 habitant，阴性 habitante；复数 habitants","s":"居民，住在某地的人。les habitants de Paris = 巴黎居民。par habitant = 人均。chez l'habitant = 住在当地人家里。","ipa":"[a.bi.tɑ̃]","ph":"h 不发音；a-bi-tant：-ant 读 [ɑ̃]，t 不发音；阴性 habitante [a.bi.tɑ̃t]，t 要发音。","pi":"h 是哑音，要连读：les habitants [le.za.bi.tɑ̃]；阴性才发 t。","et":"来自动词 habiter（居住），源于拉丁语 habitare。","ex":[["Cette ville a beaucoup d'habitants.","这座城市有很多居民。"],["Les habitants du quartier sont très accueillants.","街区的居民都很热情。"]],"co":[["les habitants de la ville","城市居民"],["par habitant","人均"],["chez l'habitant","住在当地人家"],["un habitant du quartier","街区居民"]],"sy":[["résident","soutenu","居住者（正式）"],["citoyen","courant","公民"],["population","courant","人口"]],"fq":"中频，城市话题。","me":"habit-ant：「住」(habiter) 在那里的人。","tr":{"zh":"这个小镇有三千居民。","fr":"Cette petite ville compte trois mille habitants.","alt":"Il y a trois mille habitants dans ce petit village.","note":"compter 在这里表示「共有」。"}},
 "Un(e) locataire": {"pos":"n.m. / n.f. 名词，阴阳同形：un locataire / une locataire，复数 locataires","s":"租户，付房租住在别人房子里的人。反义词是 propriétaire。男女同形，只改冠词。","ipa":"[lɔ.ka.tɛʁ]","ph":"lo [lɔ]；ca [ka]；taire 读 [tɛʁ]。","pi":"locataire 不是房东，而是租房的人；与 propriétaire 区分。","et":"来自拉丁语 locare（出租、安放），同族：location、louer。","ex":[["Le locataire paie son loyer.","租户交房租。"],["Elle est locataire d'un petit studio.","她租了一间小单间。"]],"co":[["être locataire","是租户"],["un locataire et un propriétaire","租户与房东"],["trouver un locataire","找到租客"]],"sy":[["sous-locataire","courant","转租户"],["occupant","courant","住户"],["preneur","soutenu","承租人（法律用语）"]],"fq":"中频，租房话题。","me":"locataire = 「租」房子的人（location → 租）。","tr":{"zh":"我是这套公寓的租户。","fr":"Je suis locataire de cet appartement.","alt":"Je loue cet appartement.","note":"职业或身份前不加冠词：je suis locataire。"}},
 "Un(e) propriétaire": {"pos":"n.m. / n.f. 名词，阴阳同形：un propriétaire / une propriétaire，复数 propriétaires","s":"房东；业主，拥有房子或东西的人。出租房子的叫 propriétaire，也叫 bailleur（法律用语）。devenir propriétaire = 买房成为业主。","ipa":"[pʁɔ.pʁi.e.tɛʁ]","ph":"pro [pʁɔ]；pri [pʁi]；é [e]；taire 读 [tɛʁ]；i 和 é 分开读。","pi":"四个音节，i-é 之间有小停顿；propriétaire 男女同形；与 locataire 不同。","et":"来自拉丁语 proprietarius，源于 proprius（自己的），与 propre、propriété 同族。","ex":[["Le propriétaire a vendu l'appartement.","房东卖掉了公寓。"],["Ils sont propriétaires d'une petite maison.","他们是一栋小房子的业主。"]],"co":[["devenir propriétaire","成为业主"],["le propriétaire de l'appartement","公寓的房东"],["un propriétaire foncier","地主"]],"sy":[["bailleur","soutenu","出租人（法律）"],["proprio","familier","房东（口语）"],["patron","courant","老板（店主）"]],"fq":"中频，居住话题常用。","me":"propri-étaire：拥有「自己的」(propre) 东西的人。","tr":{"zh":"我们的房东很友好。","fr":"Notre propriétaire est très sympa.","alt":"Notre proprio est vraiment sympa.","note":"Notre 是阳性/阴性单数通用。"}},
 "Un(e) voisin(e)": {"pos":"n.m. / n.f. 名词，阳性 voisin，阴性 voisine；复数 voisins","s":"邻居。voisin 也可以是形容词：la ville voisine（邻近的城市）。voisin d'à côté = 隔壁邻居；voisin de palier = 同层邻居。","ipa":"[vwa.zɛ̃]","ph":"voi 读 [vwa]；s 在元音间读 [z]；-in 读鼻化 [ɛ̃]；阴性 voisine [vwa.zin]，n 要发音。","pi":"voisin 的 n 不发音，voisine 的 n 要发音；s 读 [z]。","et":"来自拉丁语 vicinus（邻近的），源于 vicus（村、街区）。","ex":[["Mon voisin fait beaucoup de bruit.","我的邻居很吵。"],["Ma voisine du dessus travaille la nuit.","楼上的邻居晚上工作。"]],"co":[["un voisin de palier","同层邻居"],["le voisin du dessus / du dessous","楼上 / 楼下邻居"],["un voisin d'à côté","隔壁邻居"],["la ville voisine","邻近的城市"]],"sy":[["voisinage","courant","邻里；附近"],["riverain","soutenu","沿街或沿河的居民"]],"fq":"高频，日常常用。","me":"voisin：与 vicinity（附近）同族，就是「附近的人」。","tr":{"zh":"我的邻居很吵，我睡不着。","fr":"Mon voisin fait du bruit, je n'arrive pas à dormir.","alt":"Mon voisin est bruyant, je ne dors pas.","note":"ne… pas 包住动词；arriver à + 动词原形。"}},
 "Une couette / Une couverture": {"pos":"n.f. 阴性名词，复数 couettes / couvertures","s":"couette 是羽绒被、被子，法国人睡觉常用它代替被单和毯子；couverture 是毯子，也可以指书的封面。couette 的复数 des couettes 也指两侧的小辫子。","ipa":"[kwɛt] / [ku.vɛʁ.tyʁ]","ph":"couette：ou 与 e 连成 [wɛ]，读 [kwɛt]；couverture：ou 读 [u]，u 读 [y]，读 [ku.vɛʁ.tyʁ]。","pi":"couette 里的 ou+e 读 [wɛ]，而 couverture 的 ou 读 [u]；两个词都是阴性。","et":"couette 来自古法语，源于拉丁语 culcita（垫子、褥子）；couverture 来自动词 couvrir（盖），源于拉丁语 cooperire。","ex":[["J'ai froid, je prends une couverture.","我冷，拿条毯子。"],["En hiver, je dors sous une grosse couette.","冬天我盖一条厚被子睡觉。"]],"co":[["une housse de couette","被套"],["prendre une couverture","拿条毯子"],["la couverture d'un livre","书的封面"],["une couverture chauffante","电热毯"]],"sy":[["duvet","courant","鸭绒被"],["plaid","courant","沙发毯"],["édredon","soutenu","鸭绒被褥（旧式）"]],"fq":"中频，卧室用品。","me":"couette：盖得「软软」的；couverture：couvrir（盖）的东西。","tr":{"zh":"你冷的话，我给你拿条毯子。","fr":"Si tu as froid, je te donne une couverture.","alt":"Si t'as froid, je t'apporte une couverture.","note":"si + 现在时 + 现在时/将来时。"}},
 "Déménager": {"pos":"v. 第一组动词，助动词 avoir：j'ai déménagé；nous déménageons","s":"搬家，从一处住所搬到另一处。déménager à Lyon = 搬到里昂；déménager de Paris = 从巴黎搬走。也可以直接接家具：déménager un meuble（搬走家具）。","ipa":"[de.me.na.ʒe]","ph":"dé [de]；mé [me]；na [na]；ger 读 [ʒe]：g 在 e 前读 [ʒ]。","pi":"nous déménageons 要加 e 保持 [ʒ]；反义词是 emménager（搬进），不要混。","et":"dé-（离开）+ ménage（家庭、家当）+ -er，字面是「把家当搬走」。反义：emménager。","ex":[["Nous allons déménager le mois prochain.","我们下个月搬家。"],["Ils ont déménagé à Marseille l'an dernier.","他们去年搬到马赛了。"],["Aide-moi à déménager ce canapé.","帮我搬这张沙发。"]],"co":[["déménager à + 城市","搬到某城市"],["déménager de + 地方","从某地搬走"],["un camion de déménagement","搬家卡车"],["un déménagement","搬家（名词）"]],"sy":[["emménager","courant","搬进新家（反义）"],["changer de logement","courant","换住处"],["quitter","courant","离开"]],"fq":"高频，居住话题常用。","me":"dé-ménager：把「家」(ménage) 搬「走」。","tr":{"zh":"我们明年要搬到巴黎。","fr":"Nous allons déménager à Paris l'année prochaine.","alt":"L'année prochaine, on déménage à Paris.","note":"aller + 动词原形表示最近将来；déménager à + 城市。"}},
 "Donner": {"pos":"v. 第一组动词，助动词 avoir：j'ai donné","s":"给。donner qch à qn = 把某物给某人。还有 donner sur（窗户朝向）、donner rendez-vous（约定见面）、donner un cours（上课）。","ipa":"[dɔ.ne]","ph":"don 读 [dɔn]：nn 使 o 保持口腔音 [ɔ]，不是鼻化 [ɔ̃]；ner 读 [ne]，-er 读 [e]。","pi":"donner 的 on 不是鼻化音 [ɔ̃]，读 [dɔ.ne]；给人要用 à：donner à quelqu'un。","et":"来自拉丁语 donare（赠送），源于 donum（礼物）。同族：don、donateur、pardonner。","ex":[["Je vais te donner un conseil.","我给你一个建议。"],["La fenêtre donne sur le jardin.","窗户朝着花园。"],["Il m'a donné rendez-vous à midi.","他约我中午见面。"]],"co":[["donner qch à qn","把某物给某人"],["donner rendez-vous","约定见面"],["donner sur la rue / le jardin","朝向街 / 花园"],["donner envie","让人想要"]],"sy":[["offrir","courant","赠送（礼物）"],["fournir","courant","提供"],["filer","familier","给（口语，递给）"]],"fq":"极高频，日常常用。","me":"donner ← don：把「礼物」递给别人。","tr":{"zh":"你可以把书给我吗？","fr":"Tu peux me donner le livre ?","alt":"Tu me donnes le livre, s'il te plaît ?","note":"me / te 放在动词前表示「给我 / 给你」。"}},
 "Exister": {"pos":"v. 第一组动词，助动词 avoir：j'ai existé","s":"存在。il existe… = 有……（强调确实存在）。Ça n'existe pas = 没有这种东西。主语是事物或人：Les dragons n'existent pas。","ipa":"[ɛɡ.zis.te]","ph":"ex 在元音前读 [ɛɡz]；is [is]；ter 读 [te]。重音在最后。","pi":"x 读 [ɡz]，不是 [ks]；il existe 的 e 结尾不读；动词用 avoir。","et":"来自拉丁语 existere（站出来、出现）。同族：existence、existant。","ex":[["Les dragons n'existent pas.","龙不存在。"],["Il existe une solution simple.","有一个简单的办法。"],["Ça n'existe plus.","那已经不存在了。"]],"co":[["il existe…","有……"],["ça n'existe pas","没有这种东西"],["exister encore","仍然存在"],["faire exister","使成真"]],"sy":[["il y a","courant","口语里更常用的「有」"],["être","courant","是；存在"],["se trouver","courant","位于"]],"fq":"中频，各种话题。","me":"ex-ister：「站」(sistere) 「出来」(ex-)，就是存在。","tr":{"zh":"这样的餐馆已经不存在了。","fr":"Ce genre de restaurant n'existe plus.","alt":"Ce genre de resto, ça n'existe plus.","note":"ne… plus 表示「不再」。"}},
 "Gérer": {"pos":"v. 第一组动词，é→è：je gère, nous gérons；助动词 avoir：j'ai géré","s":"管理；处理，负责安排。gérer son budget（管钱）、gérer un problème（处理问题）。口语里 Je gère ! = 我搞得定！","ipa":"[ʒe.ʁe]","ph":"gé [ʒe]；rer [ʁe]；变位时第一个 é 变 è：je gère [ʒɛʁ]。","pi":"je gère / ils gèrent 里是 è [ɛ]，nous gérons 里是 é；g 读 [ʒ]。","et":"来自拉丁语 gerere（承担、办理）。同族：gestion、gérant。","ex":[["Il sait bien gérer son équipe.","他很会管理团队。"],["Je gère mon budget avec une application.","我用一个应用管理预算。"],["Pas de souci, je gère !","没问题，我搞定！"]],"co":[["gérer son budget","管理预算"],["gérer son temps","管理时间"],["gérer un problème","处理问题"],["savoir gérer","懂得处理"]],"sy":[["diriger","courant","领导、经营"],["s'occuper de","courant","负责处理"],["administrer","soutenu","管理（行政）"]],"fq":"中频，工作与生活常用。","me":"gérer ← gestion：用手「办理」好。","tr":{"zh":"你会管理你的时间吗？","fr":"Tu sais gérer ton temps ?","alt":"Tu arrives à bien gérer ton temps ?","note":"savoir + 动词原形：会做某事。"}},
 "Livrer": {"pos":"v. 第一组动词，助动词 avoir：j'ai livré","s":"送货；交付。livrer un colis à domicile = 送包裹上门。se faire livrer = 请人送货。se livrer à 是另一个用法，意思是「沉溺于、倾诉」。","ipa":"[li.vʁe]","ph":"li [li]；vrer 读 [vʁe]，vr 连读；-er 读 [e]。","pi":"vr 要连读，不要在中间加 e；不要与 livre（书）弄混。","et":"来自拉丁语 liberare（解放、交出），原义是「交到某人手里」。同族：livraison。","ex":[["Le facteur va livrer le colis demain.","邮递员明天送包裹。"],["On peut se faire livrer les courses à la maison.","可以让人把采购的东西送到家。"]],"co":[["livrer à domicile","送货上门"],["se faire livrer","请人送货"],["livrer un colis","送包裹"],["la livraison","送货（名词）"]],"sy":[["apporter","courant","带来（不一定是商业）"],["expédier","courant","寄出"],["remettre","courant","交给"]],"fq":"中频，网购与生活常用。","me":"livrer ≠ livre（书）：livrer 是把东西交到你手里。","tr":{"zh":"他们明天会把沙发送到家。","fr":"Ils vont livrer le canapé à la maison demain.","alt":"Ils nous livrent le canapé demain.","note":"aller + 动词原形：最近将来。"}},
 "Manquer": {"pos":"v. 第一组动词，助动词 avoir：j'ai manqué","s":"缺少；错过；想念。manquer de + 名词 = 缺少某物。manquer le bus = 错过公交车。Tu me manques = 我想你（主语是被想念的人）。","ipa":"[mɑ̃.ke]","ph":"man 读鼻化 [mɑ̃]；quer 读 [ke]：qu 读 [k]，-er 读 [e]。","pi":"Tu me manques 是「我想你」，不是「你想我」；manquer de 后面不加冠词。","et":"来自意大利语 mancare（缺少），源于拉丁语 mancus（残缺的）。","ex":[["Le sel manque dans ce plat.","这道菜缺盐。"],["Tu me manques beaucoup.","我很想你。"],["J'ai manqué le dernier train.","我错过了末班车。"]],"co":[["manquer de + 名词","缺少……"],["manquer à quelqu'un","被某人想念"],["manquer le bus","错过公交车"],["il manque…","缺少……"]],"sy":[["rater","courant","错过（口语感）"],["avoir besoin de","courant","需要"],["faire défaut","soutenu","缺乏"]],"fq":"高频，日常常用。","me":"manquer：Tu me manques = 你「缺」在我身边。","tr":{"zh":"我很想你。","fr":"Tu me manques beaucoup.","alt":"Tu me manques trop.","note":"主语是被想念的人：tu me manques。"}},
 "Paraître": {"pos":"v. 第三组动词，不规则：je parais, il paraît, nous paraissons；过去分词 paru；助动词 avoir","s":"似乎；显得；看起来。paraître + 形容词：Tu parais fatigué。il paraît que… = 听说……。也指书或杂志「出版」。","ipa":"[pa.ʁɛtʁ]","ph":"pa [pa]；raî 读 [ʁɛ]；tre 读 [tʁ]。î 读 [ɛ]。","pi":"il paraît 保留 î；paraître 与 apparaître（突然出现）不同；paraître 读 [pa.ʁɛtʁ]。","et":"来自拉丁语 parescere（开始显现），源于 parere（显出）。同族：apparaître, disparaître, apparence。","ex":[["Tu parais fatigué.","你看起来累了。"],["Il paraît qu'il va pleuvoir demain.","听说明天要下雨。"],["Son nouveau livre paraît en mars.","他的新书三月出版。"]],"co":[["paraître + 形容词","显得……"],["il paraît que…","听说……"],["à ce qu'il paraît","据说"],["paraître en mars","三月出版"]],"sy":[["sembler","courant","似乎，几乎同义"],["avoir l'air","courant","看起来"],["apparaître","courant","出现、浮现"]],"fq":"中频，口语与书面都用。","me":"paraître ≈ 显出来给你看；à ce qu'il paraît = 据说。","tr":{"zh":"你看起来有点累。","fr":"Tu parais un peu fatigué.","alt":"T'as l'air un peu fatigué.","note":"paraître + 形容词，形容词与主语一致。"}},
 "Partager": {"pos":"v. 第一组动词，助动词 avoir：j'ai partagé；nous partageons","s":"分享；分担；共用。partager une pizza = 分着吃披萨。partager un appartement = 合租公寓。partager l'avis de qn = 同意某人的看法。","ipa":"[paʁ.ta.ʒe]","ph":"par [paʁ]；ta [ta]；ger 读 [ʒe]：g 在 e 前读 [ʒ]。","pi":"nous partageons 要加 e 保持 [ʒ]；partager avec qn（和某人）。","et":"part（部分）+ 后缀 -ager，源于拉丁语 partiri（分）。同族：partie、partage。","ex":[["Je veux partager cette pizza avec toi.","我想和你分着吃这个披萨。"],["Elle partage un appartement avec deux amies.","她和两个朋友合租一套公寓。"],["Je partage ton avis.","我同意你的看法。"]],"co":[["partager avec quelqu'un","和某人分享"],["partager un appartement","合租公寓"],["partager l'avis de quelqu'un","同意某人的看法"],["partager en deux","分成两份"]],"sy":[["diviser","courant","分开"],["répartir","soutenu","分配"],["mettre en commun","courant","共用"]],"fq":"高频，日常常用。","me":"partager = 把 part（一份）给别人。","tr":{"zh":"我们一起吃这个蛋糕吧。","fr":"Partageons ce gâteau.","alt":"On partage ce gâteau ?","note":"Partageons ：nous 的命令式，意思是「我们一起……」。"}},
 "Poser": {"pos":"v. 第一组动词，助动词 avoir：j'ai posé","s":"放下；放置；提（问题）。poser son sac sur la table = 把包放在桌上。poser une question = 提问。se poser = 停落；（问题）出现。","ipa":"[po.ze]","ph":"po 读 [po]（闭口 o）；s 在元音间读 [z]；-er 读 [e]。","pi":"s 读 [z]，不是 [s]；问问题要用 poser une question，不能说 faire une question。","et":"来自晚期拉丁语 pausare（停下、放下），受 ponere（放）影响。同族：pause、position、composer。","ex":[["Tu peux poser ton sac sur la table.","你可以把包放在桌上。"],["Je voudrais poser une question.","我想问个问题。"],["Il a posé sa candidature.","他递交了申请。"]],"co":[["poser une question","提问"],["poser son sac / ses clés","放下包 / 钥匙"],["poser sa candidature","递交申请"],["poser un problème","带来问题"]],"sy":[["mettre","courant","放；穿（更泛）"],["placer","courant","安放"],["déposer","courant","放下；交存"]],"fq":"极高频，日常常用。","me":"poser ≈ 轻轻「摆」下，如 pose 一个动作。","tr":{"zh":"我可以问你一个问题吗？","fr":"Je peux te poser une question ?","alt":"Je peux vous poser une question ?","note":"poser une question à qn：向某人提问。"}},
 "Prêter": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir","s":"借出；借给别人。prêter qqch à qqn = 把东西借给某人。注意：法语「借入」是 emprunter，「借出」才是 prêter，中文都说「借」，容易混。","ipa":"[pʁɛ.te]","ph":"pr 中的 r 是小舌音 [ʁ]；ê [ɛ]；-er 读 [e]，r 不发音。","pi":"不要把 prêter（借出）和 emprunter（借入）弄反。ê 读 [ɛ]，结尾 -er 的 r 不发音。","et":"来自拉丁语 praestare（提供，保证），与 prêt（贷款；准备好的）同源。","ex":[["Peux-tu me prêter ton stylo ?","你可以借我你的笔吗？"],["Je te prête mon vélo ce week-end.","这个周末我把自行车借给你。"],["Il m'a prêté cent euros.","他借给了我一百欧元。"]],"co":[["prêter qqch à qqn","把某物借给某人"],["prêter de l'argent","借钱给别人"],["prêter attention à","留意；注意"],["prêter serment","宣誓"]],"sy":[["emprunter","courant","反义：借入（向别人借）"],["donner","courant","给（不用还）"],["louer","courant","租（要付钱）"]],"fq":"高频，日常常用。","me":"prêter = 借出去，像「把笔递出去」；emprunter 的 em- 像「拿进来」。","tr":{"zh":"你能借我你的自行车吗？","fr":"Tu peux me prêter ton vélo ?","alt":"Tu me prêtes ton vélo ?","note":"prêter qqch à qqn；me 代替 à moi，放在动词前。"}},
 "Ranger": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir；ranger 变位时 g 后加 e（nous rangeons）","s":"整理；收拾；把东西放回原处。ranger sa chambre = 整理房间；ranger ses affaires = 收拾东西。也可指排列、归类。","ipa":"[ʁɑ̃.ʒe]","ph":"r 是小舌音 [ʁ]；an 读鼻化音 [ɑ̃]；g 在 e 前读 [ʒ]；-er 读 [e]。","pi":"nous rangeons 要保留 e，才能让 g 继续读 [ʒ]。an 是鼻化音，n 不单独发。","et":"来自 rang（行列，队伍）加动词词尾：把东西排成「行」。rang 源自法兰克语。","ex":[["Tu dois ranger ta chambre.","你得整理房间。"],["Range tes affaires dans le sac.","把你的东西放进包里。"],["Nous rangeons les livres par thème.","我们按主题给书归类。"]],"co":[["ranger sa chambre","整理房间"],["ranger ses affaires","收拾东西"],["ranger qqch dans un tiroir","把某物收进抽屉"],["ranger par ordre alphabétique","按字母顺序排列"]],"sy":[["ordonner","soutenu","使有序；整理"],["mettre en ordre","courant","整理好"],["ranger / jeter","courant","对比：收好 / 扔掉"]],"fq":"高频，日常家务常用。","me":"ranger ← rang（一行）：把东西排成一行。","tr":{"zh":"吃完饭后，我们整理厨房。","fr":"Après le repas, nous rangeons la cuisine.","alt":"Après manger, on range la cuisine.","note":"nous rangeons 保留 e；口语常用 on 代替 nous。"}},
 "Rénover": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir","s":"翻新；改造；修缮（房子、建筑、旧物）。也可比喻为革新、更新（rénover un parti, une méthode）。","ipa":"[ʁe.nɔ.ve]","ph":"ré [ʁe]；o 读开音 [ɔ]；v 读 [v]；-er 读 [e]。","pi":"只有一个 n（rénover），不要写成 rénnover。re- 读 [ʁe]，开头的 é 不可读成 [ə]。","et":"来自拉丁语 renovare：re-（再）+ novus（新的）。同族：nouveau（新的）、innover（创新）、rénovation（翻新）。","ex":[["Ils vont rénover leur vieille maison.","他们要翻新老房子。"],["On a rénové la cuisine l'année dernière.","我们去年翻新了厨房。"],["Cet hôtel vient d'être rénové.","这家酒店刚刚翻新完。"]],"co":[["rénover un appartement","翻新公寓"],["des travaux de rénovation","翻新工程"],["un bâtiment rénové","翻新过的建筑"],["rénover à neuf","彻底翻新"]],"sy":[["restaurer","courant","修复（古物、古建筑）"],["réparer","courant","修理（坏了的东西）"],["moderniser","courant","使现代化"]],"fq":"中频，谈论住房时常用。","me":"re- + nov-：让它「再变新」。和 nouveau 同根。","tr":{"zh":"我们想明年翻新浴室。","fr":"Nous voulons rénover la salle de bains l'année prochaine.","alt":"On veut refaire la salle de bains l'an prochain.","note":"vouloir + 动词原形；口语可用 refaire（重做）代替。"}},
 "S'occuper de": {"pos":"v.pr. 代词式动词，第一组，助动词 être；后接 de","s":"照看；负责；处理。s'occuper de qqn = 照顾某人；s'occuper de qqch = 负责某事。问候时 Vous vous occupez de quoi ? 也可问「你做什么工作」。","ipa":"[sɔ.ky.pe də]","ph":"s'o- 连读：s'occuper 读 [sɔ.ky.pe]；cc 读一个 [k]；u 读 [y]（嘴唇圆、舌头前）。","pi":"cc 只读一个 [k]。u 读 [y]，不是 [u]。别漏掉 de：s'occuper de。复合时助动词用 être：je me suis occupé de。","et":"来自拉丁语 occupare（占据，占有）。同族：occupé（忙碌的；被占用的）、une occupation（占用；活动）。","ex":[["Tu peux t'occuper de mon chien ce weekend ?","这个周末你能照看我的狗吗？"],["Je m'occupe des courses.","购物的事我来管。"],["Qui s'occupe des enfants ?","谁在照看孩子们？"]],"co":[["s'occuper des enfants","照看孩子"],["s'occuper de la cuisine","负责做饭"],["Occupe-toi de tes affaires !","管好你自己的事！"],["Je m'en occupe.","我来处理。"]],"sy":[["prendre soin de","courant","照顾（更强调关心）"],["gérer","courant","管理，处理"],["se charger de","courant","负责，承担"]],"fq":"高频，日常常用。","me":"s'occuper de = 「占住」一件事，让它由你负责。","tr":{"zh":"我来负责订餐厅。","fr":"Je m'occupe de réserver le restaurant.","alt":"Je m'occupe de la réservation du restaurant.","note":"s'occuper de + 动词原形 或 + 名词；me 要随主语变化。"}},
 "Se cultiver": {"pos":"v.pr. 代词式动词，第一组，助动词 être","s":"提高自身修养；充实自己；增长见识（读书、看展览、旅行等）。指个人学习文化知识。cultiver 本义是耕种，此处是「让自己的头脑成长」。","ipa":"[sə.kyl.ti.ve]","ph":"se 读 [sə]；u 读 [y]；l 和 t 相连 [kyl.ti]；-er 读 [e]。","pi":"u 读 [y]，不是 [u]。je me cultive、tu te cultives，反身代词随人称变。注意区分 se cultiver（自我提高）和 cultiver（种植）。","et":"来自拉丁语 colere（耕种，照料），中世纪拉丁语 cultivare。同族：la culture（文化）、l'agriculture（农业）。","ex":[["Il lit beaucoup pour se cultiver.","他多读书来充实自己。"],["Je vais au musée pour me cultiver.","我去博物馆增长见识。"],["Elle aime se cultiver en voyageant.","她喜欢通过旅行充实自己。"]],"co":[["se cultiver en lisant","通过读书提高修养"],["pour se cultiver","为了充实自己"],["une personne cultivée","有教养的人"],["cultiver la terre","耕地"]],"sy":[["s'instruire","soutenu","学习，求知"],["apprendre","courant","学习（更宽泛）"],["s'enrichir","soutenu","丰富自己"]],"fq":"中频，谈兴趣爱好时常用。","me":"文化 culture 像庄稼：要「耕」自己的头脑。","tr":{"zh":"为了充实自己，我每周去看展览。","fr":"Pour me cultiver, je vais voir une exposition chaque semaine.","alt":"Pour me cultiver, je vais à une expo toutes les semaines.","note":"pour + 动词原形 表目的；反身代词 me 要放在动词原形前。"}},
 "Se soigner": {"pos":"v.pr. 代词式动词，第一组，助动词 être","s":"治疗自己；调养；保重身体（吃药、看医生、休息）。Soigne-toi bien ! = 好好保重！也指注意自己的外表（se soigner = 打扮得体）。","ipa":"[sə.swa.ɲe]","ph":"oi 读 [wa]；gn 读 [ɲ]（像中文「娘」的开头）；-er 读 [e]。","pi":"oi 读 [wa]，不是 [oi]；gn 读 [ɲ]，不是 g + n 两个音。","et":"来自法兰克语 *sunnjan（关心，操心）。同族：le soin（照料）、soigneux（仔细的）。","ex":[["Il faut bien se soigner quand on est malade.","生病时要好好调养。"],["Elle se soigne avec des tisanes.","她用草药茶调养身体。"],["Soigne-toi bien !","好好保重！"]],"co":[["se soigner contre le rhume","治疗感冒"],["se faire soigner","去接受治疗"],["Soigne-toi bien !","好好保重！"],["prendre soin de soi","照顾好自己"]],"sy":[["se guérir","courant","痊愈（强调结果）"],["se reposer","courant","休息"],["prendre soin de soi","courant","照顾自己"]],"fq":"中频，谈健康时常用。","me":"soin（照料）：se soigner = 给自己「照料」。","tr":{"zh":"你感冒了，要好好休息和调养。","fr":"Tu es enrhumé, repose-toi et soigne-toi bien.","alt":"T'es enrhumé, repose-toi et soigne-toi.","note":"肯定命令式中，反身代词放在动词后：soigne-toi。"}},
 "Sécher": {"pos":"v. 动词，第一组（-er），及物或不及物；助动词 avoir","s":"晾干；弄干；变干。及物：sécher le linge（晾衣服）；不及物：le linge sèche（衣服在干）。口语中 sécher un cours = 逃课；sécher à l'examen = 答不出来（卡壳）。","ipa":"[se.ʃe]","ph":"é [e]；ch 读 [ʃ]；-er 读 [e]。变位时 é 会变 è：je sèche [sɛʃ]。","pi":"ch 读 [ʃ]，像「西」。je sèche、tu sèches，é 变成 è，但 nous séchons 保持 é。","et":"来自拉丁语 siccare（使干），siccus（干的）。同族：sec（干的）、la sécheresse（干旱）、le sèche-linge（烘干机）。","ex":[["Les vêtements sèchent dehors.","衣服在外面晾着。"],["Je sèche mes cheveux avec un sèche-cheveux.","我用吹风机吹头发。"],["Il a séché le cours d'histoire.","他逃了历史课。"]],"co":[["sécher le linge","晾衣服"],["se sécher les cheveux","吹干头发"],["sécher les cours","逃课（口语）"],["un sèche-cheveux","吹风机"]],"sy":[["essuyer","courant","擦干（用毛巾等）"],["assécher","soutenu","使干涸"],["sécher les cours","familier","逃课；正式说 être absent"]],"fq":"中频，日常生活常用。","me":"sec（干）的动词形式：使它变成 sec。","tr":{"zh":"我的衣服在阳台上晾干。","fr":"Mes vêtements sèchent sur le balcon.","alt":"Mes vêtements sèchent au balcon.","note":"sécher 在这里是不及物动词，主语是衣服本身。"}},
 "Signer": {"pos":"v.t. 及物动词，第一组（-er），助动词 avoir","s":"签字；签名；署名。signer un contrat / un chèque / un document = 签合同 / 支票 / 文件。也可不接宾语：Signez ici. = 请在这里签字。","ipa":"[si.ɲe]","ph":"s 在词首读 [s]；gn 读 [ɲ]；-er 读 [e]。","pi":"gn 读 [ɲ]，不是 [ɡn]：si-gne，g 不单独发。同族词 signature 读 [si.ɲa.tyʁ]。","et":"来自拉丁语 signare（做标记），signum（记号，标志）。同族：un signe（记号）、la signature（签名）、un signal（信号）。","ex":[["Vous devez signer ce document en bas.","您得在下面签字。"],["Elle a signé le contrat hier.","她昨天签了合同。"],["Signez ici, s'il vous plaît.","请在这里签字。"]],"co":[["signer un contrat","签合同"],["signer un chèque","开支票并签字"],["signer en bas de la page","在页尾签字"],["signer une pétition","在请愿书上签名"]],"sy":[["parapher","soutenu","签姓名缩写（在页边）"],["apposer sa signature","soutenu","签上自己的名字（正式）"],["écrire son nom","courant","写下名字"]],"fq":"中频，办手续时常用。","me":"signer ← signe：在文件上留下你的「记号」。","tr":{"zh":"请在每一页上签字。","fr":"Signez sur chaque page, s'il vous plaît.","alt":"Vous pouvez signer sur chaque page ?","note":"命令式 vous 形：Signez。"}},
 "Sortir + COD": {"pos":"v.t. 及物用法，第三组（sortir），助动词 avoir；不及物时用 être","s":"把某物拿出去；拿出来（sortir qqch）。接直接宾语时助动词用 avoir：J'ai sorti la poubelle。不接宾语时是「出去」，助动词用 être：Je suis sorti。","ipa":"[sɔʁ.tiʁ]","ph":"s [s]；o 开音 [ɔ]；r 小舌音 [ʁ]；t [t]；-ir 读 [iʁ]，结尾 r 要发音。","pi":"结尾的 r 要读出来：sortir [sɔʁ.tiʁ]。助动词会变：Je suis sorti（出去了）/ J'ai sorti la voiture（把车开出来）。je sors 的 s 不发音。","et":"来自古法语 sortir（出来，结果），词源不完全确定。同族：la sortie（出口）、ressortir（再出来）。","ex":[["Je sors les poubelles.","我去倒垃圾。"],["Elle sort son téléphone de son sac.","她从包里拿出手机。"],["Il a sorti la voiture du garage.","他把车从车库开出来了。"]],"co":[["sortir la poubelle","把垃圾拿出去"],["sortir qqch de son sac","从包里拿出某物"],["sortir le chien","带狗出去遛"],["sortir de la maison","走出房子"]],"sy":[["retirer","courant","取出；撤回"],["enlever","courant","拿掉；脱掉"],["rentrer","courant","反义：拿进来；回家"]],"fq":"极高频，日常常用。","me":"sortir + 宾语 = 「拿到外面」；助动词 avoir。","tr":{"zh":"晚上我把垃圾拿出去。","fr":"Le soir, je sors la poubelle.","alt":"Le soir, c'est moi qui sors la poubelle.","note":"sortir + 直接宾语：复合时用 avoir（j'ai sorti la poubelle）。"}},
 "Actif / Active": {"pos":"adj. 形容词，阴性 active，复数 actifs / actives","s":"积极的；活跃的；忙碌的。une personne active = 积极行动的人，也指「在职的人」；la population active = 劳动人口。反义：passif（被动的）、inactif（不活跃的）。","ipa":"[ak.tif] / [ak.tiv]","ph":"阳性 actif：f 读 [f]；阴性 active：v 读 [v]。ct 都读出来：[k.t]。","pi":"阳性 -if，阴性 -ive，结尾 f 变 v（actif → active）。t 和 c 都要发音，不是 [a.tif]。","et":"来自拉丁语 activus（活动的），agere（做，行动）。同族：l'action（行动）、l'activité（活动）、agir（行动）。","ex":[["Elle est très active dans son travail.","她工作非常积极。"],["Mon grand-père reste très actif.","我爷爷一直很活跃。"],["C'est un homme actif et dynamique.","他是个积极又有干劲的人。"]],"co":[["être actif / active","积极；有活力"],["la vie active","职业生涯"],["la population active","劳动人口"],["la voix active","（语法）主动语态"]],"sy":[["dynamique","courant","有干劲的"],["énergique","courant","精力充沛的"],["passif","courant","反义：被动的"]],"fq":"中频，日常和工作场合常用。","me":"actif ← action：爱行动的人。","tr":{"zh":"我外婆虽然八十岁了，还是很活跃。","fr":"Ma grand-mère a quatre-vingts ans, mais elle est encore très active.","alt":"Ma grand-mère a 80 ans mais elle reste très active.","note":"形容词与主语（ma grand-mère）一致，用阴性 active。"}},
 "Âgé(e)": {"pos":"adj. 形容词，阴性 âgée，复数 âgés / âgées","s":"年长的；上了年纪的。比 vieux 委婉、有礼貌。une personne âgée = 老年人。也可表年龄：Il est âgé de dix ans. = 他十岁。","ipa":"[ɑ.ʒe]","ph":"â 读后 a [ɑ]（嘴张大）；g 在 e 前读 [ʒ]；é 读 [e]。","pi":"â 上的帽子表示曾经有 s（aage），不改变意思。注意阴性 âgée、复数 âgés。年龄用 être âgé de ... ans 的格式。","et":"来自 âge（年龄），âge 来自古法语 aage，源自拉丁语 aetaticum（年纪）。","ex":[["Mon grand-père est très âgé.","我爷爷年纪很大了。"],["Elle aide une dame âgée.","她帮助一位上年纪的女士。"],["Il est âgé de dix ans.","他十岁。"]],"co":[["une personne âgée","老年人"],["être âgé de ... ans","年龄是……岁"],["les personnes âgées","老年人（群体）"],["plus âgé que moi","比我年长"]],"sy":[["vieux / vieille","courant","老的（语气更直接）"],["senior","courant","老年人（较中性）"],["jeune","courant","反义：年轻的"]],"fq":"中频，礼貌场合常用。","me":"âgé ← âge：「有了岁数」，礼貌地说老。","tr":{"zh":"我邻居年纪很大了，我常帮她买东西。","fr":"Ma voisine est très âgée, je l'aide souvent à faire ses courses.","alt":"Ma voisine est âgée, alors je l'aide pour ses courses.","note":"voisine 是阴性，所以用 âgée。"}},
 "Agréable": {"pos":"adj. 形容词，阴阳性同形，复数 agréables","s":"令人愉快的；舒适的；讨人喜欢的。可用于天气、地方、人、声音、味道。une soirée agréable = 愉快的夜晚；une personne agréable = 好相处的人。","ipa":"[a.ɡʁe.abl]","ph":"a [a]；gr [ɡʁ]；é [e]；a [a]；结尾 -ble 的 e 轻读：[a.ɡʁe.a.bl]。","pi":"é 和 a 分开读，不合成一个音：a-gré-a-ble。阴阳性相同：un jour agréable / une journée agréable。常和 « c'est agréable de + 动词原形 » 一起用。","et":"来自动词 agréer（接受，认可）加后缀 -able；agréer 源自 à gré（合心意），gré 来自拉丁语 gratum（受欢迎的）。同族：gré。","ex":[["C'est une journée très agréable.","这是很愉快的一天。"],["Il est agréable de se promener ici.","在这里散步很惬意。"],["Elle est très agréable avec tout le monde.","她对谁都很和气。"]],"co":[["une surprise agréable","惊喜"],["agréable à vivre","住着舒服"],["il est agréable de + inf.","……很舒服 / 很愉快"],["agréable à regarder","赏心悦目"]],"sy":[["sympa","familier","好的；友好的"],["plaisant","soutenu","令人愉快的"],["désagréable","courant","反义：令人不快的"]],"fq":"高频，日常常用。","me":"agréable：agré- + able = 「可以让人满意」。","tr":{"zh":"夏天在海边散步很惬意。","fr":"En été, il est agréable de se promener au bord de la mer.","alt":"L'été, c'est agréable de se balader au bord de la mer.","note":"il est agréable de + 动词原形；口语可说 c'est agréable de。"}},
 "Aménagé(e)": {"pos":"adj. 形容词（过去分词），阴性 aménagée，复数 aménagés / aménagées","s":"布置好的；改造过的；设有设施的。指空间被安排、装修好以便使用：un grenier aménagé = 改成住房的阁楼；une cuisine aménagée = 带橱柜设备的厨房。","ipa":"[a.me.na.ʒe]","ph":"a-mé-na-gé：每个音节清楚；g 在 e 前读 [ʒ]；结尾 é [e]。","pi":"只有一个 n，不要写成 amménagé。动词是 aménager，-ger 变位时需保留 e（nous aménageons）。","et":"来自动词 aménager，由 à + ménage（家务，家庭）组成；ménage 源自古法语 manage，意为「住所」。","ex":[["Le sous-sol est bien aménagé.","地下室布置得很好。"],["Ils ont acheté un appartement aménagé.","他们买了一套装修好的公寓。"],["La cuisine est aménagée avec goût.","厨房布置得很有品位。"]],"co":[["une cuisine aménagée","带设备的厨房"],["des combles aménagés","改造过的阁楼"],["bien aménagé","布置得好"],["un espace aménagé","已整理好的空间"]],"sy":[["équipé","courant","配备齐全的"],["installé","courant","安装好的"],["arrangé","courant","整理好的"]],"fq":"中频，租房、买房时常用。","me":"aménagé ← ménage：把家安排得井井有条。","tr":{"zh":"我们的阁楼已经改造成卧室了。","fr":"Notre grenier est aménagé en chambre.","alt":"Notre grenier a été transformé en chambre.","note":"aménagé en + 名词：被改成……"}},
 "Ancien(ne)": {"pos":"adj. 形容词，阴性 ancienne，复数 anciens / anciennes","s":"旧的；古老的（放在名词后）；以前的，前任的（放在名词前）。un bâtiment ancien = 古老的建筑；mon ancien professeur = 我以前的老师。位置不同意思不同。","ipa":"[ɑ̃.sjɛ̃]","ph":"an 读鼻化音 [ɑ̃]；ci 读 [sj]；en 读鼻化音 [ɛ̃]。阴性 ancienne 读 [ɑ̃.sjɛn]。","pi":"放在名词前 = 以前的（un ancien élève）；放在名词后 = 古老的（une ville ancienne）。阴性 ancienne 的 n 要发音。","et":"来自古法语 ancien，源于通俗拉丁语 *anteanus（在前面的），ante（之前）。同族：antique（古代的）、l'ancêtre（祖先）。","ex":[["C'est un ancien bâtiment.","这是一栋旧建筑。"],["Mon ancien collègue habite à Lyon.","我以前的同事住在里昂。"],["Elle collectionne les meubles anciens.","她收藏古董家具。"]],"co":[["un ancien élève","校友；前学生"],["une ville ancienne","古城"],["l'Antiquité / l'histoire ancienne","古代史"],["son ancienne adresse","他以前的地址"]],"sy":[["vieux","courant","老的，旧的（更口语）"],["antique","soutenu","古代的"],["ex-","courant","前任的（ex-mari）"]],"fq":"高频，日常常用。","me":"ancien ← ante（之前）：「在前面的」，所以是过去的。","tr":{"zh":"我以前的老师现在在巴黎教书。","fr":"Mon ancien professeur enseigne maintenant à Paris.","alt":"Mon ancien prof travaille à Paris maintenant.","note":"ancien 放在名词前表示「以前的」。"}},
 "Animé(e)": {"pos":"adj. 形容词（过去分词），阴性 animée，复数 animés / animées","s":"热闹的；充满活力的；有人气的。常说街区、街道、聚会、讨论 animé。un dessin animé = 动画片；une discussion animée = 热烈的讨论。","ipa":"[a.ni.me]","ph":"a [a]；ni [ni]；mé [me]：三个音节都是清晰的开口音。","pi":"一个 n 一个 m：animé。小心别和 anémie（贫血）混淆。动画片说 un dessin animé，不要漏掉 animé。","et":"来自拉丁语 animare（赋予生命），anima（气息，灵魂）。同族：un animal（动物）、l'âme（灵魂）、animer（使活跃）。","ex":[["Le centre-ville est très animé le soir.","晚上市中心很热闹。"],["On a eu une discussion animée.","我们进行了一场热烈的讨论。"],["Les enfants regardent un dessin animé.","孩子们在看动画片。"]],"co":[["un quartier animé","热闹的街区"],["une rue animée","热闹的街道"],["un dessin animé","动画片"],["une discussion animée","热烈的讨论"]],"sy":[["vivant","courant","有生气的"],["bruyant","courant","嘈杂的"],["calme","courant","反义：安静的"]],"fq":"中频，描述地方时常用。","me":"animé ← anima（灵魂）：地方「有了灵魂」，所以热闹。","tr":{"zh":"周六晚上这条街非常热闹。","fr":"Le samedi soir, cette rue est très animée.","alt":"Le samedi soir, ça bouge dans cette rue.","note":"rue 是阴性，所以 animée。"}},
 "Bizarre": {"pos":"adj. 形容词，阴阳性同形，复数 bizarres","s":"奇怪的；古怪的；不寻常的。指不合常理、让人觉得别扭的人或事。C'est bizarre. = 真奇怪。语气比 étrange 更口语。","ipa":"[bi.zaʁ]","ph":"z 读 [z]；结尾 -arre 读 [aʁ]；e 不发音；rr 读一个 [ʁ]。","pi":"bizarre 要写 rr（两个 r）和两个 z 都要读 [z]：b-i-z-a-r-r-e，注意只有一个 z 但读 [z]。英语是 bizarre，法语拼写相同。","et":"来自意大利语 bizzarro（易怒的）或西班牙语 bizarro（勇敢的），词源有争议，来源不确定。","ex":[["Ce bruit est bizarre.","这个声音很怪。"],["C'est bizarre, il n'est pas là.","奇怪，他不在。"],["Il a un comportement bizarre.","他的行为很古怪。"]],"co":[["c'est bizarre","真奇怪"],["Bizarre, bizarre !","怪了，怪了！"],["un comportement bizarre","古怪的行为"],["se sentir bizarre","觉得不舒服 / 怪怪的"]],"sy":[["étrange","courant","奇怪的（稍正式）"],["curieux","soutenu","怪异的；好奇的"],["louche","familier","可疑的"]],"fq":"高频，口语常用。","me":"和英语 bizarre 一模一样，读 [bi.zaʁ]。","tr":{"zh":"奇怪，我的钥匙不在包里。","fr":"C'est bizarre, mes clés ne sont pas dans mon sac.","alt":"Bizarre, je ne trouve plus mes clés.","note":"C'est bizarre, + 句子：表示感到意外。"}},
 "Chic": {"pos":"adj. 形容词，阴阳性同形，不变（复数也是 chic）","s":"时髦的；优雅的；体面的。形容衣着、餐厅、人。也可表示「大方、厚道」：C'est chic de ta part. = 你真大方。也作名词 le chic = 风度。","ipa":"[ʃik]","ph":"ch 读 [ʃ]；i [i]；c 在结尾读 [k]。","pi":"ch 读 [ʃ]；结尾 c 要读 [k]。作形容词时不变化：des robes chic（不加 s）。","et":"词源不确定，可能来自德语 Schick（技巧），19 世纪进入法语。","ex":[["Elle porte une robe très chic.","她穿一条很时髦的裙子。"],["On dîne dans un restaurant chic.","我们在一家高档餐厅吃饭。"],["C'est chic de ta part !","你真厚道！"]],"co":[["une tenue chic","优雅的装扮"],["un quartier chic","高档街区"],["bon chic bon genre (BCBG)","上流体面派"],["Chic alors !","太好了！"]],"sy":[["élégant","courant","优雅的"],["classe","familier","有品位的"],["ringard","familier","反义：过时的、土气的"]],"fq":"中频，日常常用。","me":"chic [ʃik]：像「西克」，看起来就很潇洒。","tr":{"zh":"你今天穿得很优雅！","fr":"Tu es très chic aujourd'hui !","alt":"T'es vraiment chic aujourd'hui !","note":"chic 不变化，阴阳性单复数相同。"}},
 "Clair(e)": {"pos":"adj. 形容词，阴性 claire，复数 clairs / claires","s":"清澈的；明亮的；浅色的；清楚的。l'eau claire = 清水；une chambre claire = 明亮的房间；une réponse claire = 清楚的回答；bleu clair = 浅蓝（颜色不变化）。","ipa":"[klɛʁ]","ph":"cl [kl]；ai 读 [ɛ]；r 读 [ʁ]。阴性 claire 读音相同 [klɛʁ]。","pi":"阴阳性读音相同，只是拼写多了 e。bleu clair、vert clair 这类颜色词组不变化：des robes bleu clair。","et":"来自拉丁语 clarus（明亮的，清楚的）。同族：la clarté（光亮）、éclairer（照亮）、clarifier（澄清）。","ex":[["L'eau de la rivière est très claire.","河水很清澈。"],["Ma chambre est claire et grande.","我的房间明亮又大。"],["Je voudrais une chemise bleu clair.","我想要一件浅蓝色衬衫。"]],"co":[["l'eau claire","清水"],["une réponse claire","明确的回答"],["bleu clair / vert clair","浅蓝 / 浅绿"],["c'est clair !","很清楚！/ 明白了！"]],"sy":[["lumineux","courant","明亮的"],["limpide","soutenu","清澈的"],["sombre","courant","反义：暗的"]],"fq":"高频，日常常用。","me":"clair：像 clear，一眼透明。","tr":{"zh":"这间房间又大又明亮。","fr":"Cette chambre est grande et claire.","alt":"La chambre est grande et il y a beaucoup de lumière.","note":"chambre 是阴性，用 claire。"}},
 "Coloré(e)": {"pos":"adj. 形容词（过去分词），阴性 colorée，复数 colorés / colorées","s":"色彩丰富的；颜色鲜艳的；生动的。des vêtements colorés = 色彩鲜艳的衣服；un marché coloré = 五彩缤纷的集市。也可形容文字或语言「生动有趣」。","ipa":"[kɔ.lɔ.ʁe]","ph":"两个 o 都读开音 [ɔ]；r 读 [ʁ]；结尾 é 读 [e]。","pi":"co-lo-ré：每个 o 都读 [ɔ]，不是 [o]；只有一个 l。名词是 la couleur，动词 colorer。","et":"来自拉丁语 color（颜色）；coloré 为 colorer 的过去分词。同族：la couleur（颜色）、colorier（涂颜色）、le coloriage（涂色）。","ex":[["J'aime porter des vêtements colorés.","我喜欢穿颜色鲜艳的衣服。"],["Le marché est très coloré.","集市色彩缤纷。"],["Elle a un style coloré et joyeux.","她的风格鲜艳又快乐。"]],"co":[["des vêtements colorés","鲜艳的衣服"],["un marché coloré","色彩缤纷的集市"],["un style coloré","生动的风格"],["des fruits colorés","颜色鲜艳的水果"]],"sy":[["vif","courant","鲜艳的（颜色）"],["multicolore","courant","多种颜色的"],["terne","courant","反义：暗淡的"]],"fq":"中频，描述衣服、地方时常用。","me":"colo-ré：有 color（颜色）的。","tr":{"zh":"我喜欢这条颜色鲜艳的围巾。","fr":"J'aime cette écharpe colorée.","alt":"Elle me plaît, cette écharpe toute colorée.","note":"écharpe 是阴性，用 colorée。"}},
 "Commerçant(e)": {"pos":"adj. 形容词，阴性 commerçante，复数 commerçants / commerçantes；也作名词（商人）","s":"商业繁华的；店铺多的（形容街区、街道）。une rue commerçante = 商店林立的街；un quartier commerçant = 商业区。作名词 un commerçant = 商人、店主。","ipa":"[kɔ.mɛʁ.sɑ̃]","ph":"com [kɔm]；er 读 [ɛʁ]；ç 读 [s]；ant 读鼻化音 [ɑ̃]。阴性 commerçante 读 [kɔ.mɛʁ.sɑ̃t]。","pi":"ç 读 [s]，要保留下面的小勾；ant 的 t 不发音。注意有两个 m、一个 r。阴性 -ante 的 t 要发音。","et":"来自 commerce（商业），源自拉丁语 commercium：com-（一起）+ merx（商品）。同族：la marchandise（商品）、le marché（市场）。","ex":[["C'est une rue commerçante.","这是一条商业街。"],["Mon père est commerçant.","我爸爸是做生意的。"],["Le quartier est très commerçant.","这个街区商业很繁荣。"]],"co":[["une rue commerçante","商业街"],["un quartier commerçant","商业区"],["un petit commerçant","小店主"],["les commerçants du quartier","街区的店主们"]],"sy":[["marchand","soutenu","商人"],["boutiquier","courant","店主"],["résidentiel","courant","对比：居住区的"]],"fq":"中频，谈城市时常用。","me":"commerce + ant：到处是「商业」的街区。","tr":{"zh":"我们的街区商店很多，很方便。","fr":"Notre quartier est très commerçant, c'est pratique.","alt":"Dans notre quartier, il y a plein de commerces, c'est pratique.","note":"commerçant 描述街区；描述街道用 commerçante。"}},
 "Commun(e)": {"pos":"adj. 形容词，阴性 commune，复数 communs / communes","s":"共同的；公共的；常见的。un ami commun = 共同的朋友；les transports en commun = 公共交通；le point commun = 共同点。也可指平常的，如 un nom commun = 普通名词。","ipa":"[kɔ.mœ̃]","ph":"o 读开音 [ɔ]；mu 在这里读 [mœ̃]，un 读鼻化音 [œ̃]。阴性 commune 读 [kɔ.myn]。","pi":"阳性 commun 结尾是鼻音 [œ̃]，阴性 commune 却读 [myn]，音变很大。在 en commun 中也要这样读。","et":"来自拉丁语 communis（共同的）：com-（一起）+ munus（任务，责任）。同族：la commune（市镇）、la communauté（团体）、communiquer（沟通）。","ex":[["Nous avons un ami commun.","我们有一个共同的朋友。"],["On a beaucoup de points communs.","我们有很多共同点。"],["Je prends les transports en commun.","我坐公共交通。"]],"co":[["en commun","共同；公共"],["un point commun","共同点"],["les transports en commun","公共交通"],["une pièce commune","公共空间"]],"sy":[["partagé","courant","共享的"],["collectif","courant","集体的"],["personnel","courant","反义：个人的"]],"fq":"高频，日常常用。","me":"commun = com + un：大家「一起」拥有。","tr":{"zh":"我们有很多共同点，所以相处得很好。","fr":"Nous avons beaucoup de points communs, donc nous nous entendons bien.","alt":"On a plein de points communs, alors on s'entend bien.","note":"points 是复数，所以 communs 也加 s。"}},
 "Compliqué(e)": {"pos":"adj. 形容词（过去分词），阴性 compliquée，复数 compliqués / compliquées","s":"复杂的；麻烦的；难的。可形容问题、事情、关系、人。C'est compliqué. = 这事复杂。une situation compliquée = 棘手的局面。","ipa":"[kɔ̃.pli.ke]","ph":"com 读鼻化音 [kɔ̃]；pli [pli]；qu 读 [k]；é 读 [e]。","pi":"com- 是鼻化音，m 不单独发；qu 读 [k]，不是 [kw]。阴性 compliquée 读音不变。","et":"来自拉丁语 complicare（折叠在一起）：com-（一起）+ plicare（折）。同族：plier（折叠）、le pli（褶）、impliquer（牵涉）。","ex":[["Cet exercice est trop compliqué.","这道题太复杂了。"],["C'est compliqué à expliquer.","这很难解释。"],["Leur histoire est compliquée.","他们的关系很复杂。"]],"co":[["une situation compliquée","复杂的局面"],["c'est compliqué","这很复杂"],["compliqué à + inf.","难以……"],["se compliquer la vie","自找麻烦"]],"sy":[["difficile","courant","难的"],["complexe","soutenu","复杂的（更书面）"],["simple","courant","反义：简单的"]],"fq":"高频，日常常用。","me":"compliqué = 折叠 (plier) 到一起：绕来绕去。","tr":{"zh":"这个问题太复杂，我解释不了。","fr":"Ce problème est trop compliqué, je ne peux pas l'expliquer.","alt":"C'est trop compliqué, je ne sais pas l'expliquer.","note":"trop + 形容词：太……；problème 是阳性，用 compliqué。"}},
 "Épais / Épaisse": {"pos":"adj. 形容词，阴性 épaisse，复数 épais / épaisses","s":"厚的；浓的；粗的。un livre épais = 厚书；une soupe épaisse = 浓汤；un brouillard épais = 浓雾。反义：mince（薄的）、fin（细的）。","ipa":"[e.pɛ] / [e.pɛs]","ph":"阳性 épais：ai 读 [ɛ]，结尾 s 不发音；阴性 épaisse：ss 读 [s]，所以读 [e.pɛs]。","pi":"阳性 épais 的 s 不发音，阴性 épaisse 的 s 要发音。名词是 l'épaisseur（厚度）。拼写开头是 é，不要漏掉重音。","et":"来自拉丁语 spissus（稠的，密的），古法语 espes。同族：l'épaisseur（厚度）、épaissir（变稠）。","ex":[["Ce livre est très épais.","这本书很厚。"],["J'aime la soupe épaisse en hiver.","我冬天喜欢喝浓汤。"],["Il y a un brouillard épais ce matin.","今早有浓雾。"]],"co":[["un livre épais","厚书"],["un brouillard épais","浓雾"],["des cheveux épais","浓密的头发"],["une épaisse couche de neige","厚厚一层雪"]],"sy":[["gros","courant","大的，粗的"],["dense","courant","稠密的"],["mince","courant","反义：薄的"]],"fq":"中频，日常描述东西时常用。","me":"épais (s 静音) / épaisse (s 发音)：「厚」的阴性更厚实。","tr":{"zh":"冬天我喜欢穿厚外套。","fr":"L'hiver, j'aime porter un manteau épais.","alt":"En hiver, je mets un gros manteau.","note":"manteau 是阳性，用 épais。"}},
 "Équipé(e)": {"pos":"adj. 形容词（过去分词），阴性 équipée，复数 équipés / équipées","s":"配备齐全的；有设备的。une cuisine équipée = 设备齐全的厨房；un appartement bien équipé = 设施完备的公寓。动词 équiper = 配备。","ipa":"[e.ki.pe]","ph":"é [e]；qui 读 [ki]（u 不发音）；pé [pe]。","pi":"qu 读 [k]，u 不发音：é-qui-pé。开头 é 不是 [ɛ]，要读闭口的 [e]。","et":"来自动词 équiper，源自古法语 eschipier（装备船只），最终来自古北欧语 skip（船）。同族：l'équipe（团队）、l'équipement（设备）。","ex":[["La salle de sport est bien équipée.","健身房设备齐全。"],["Nous cherchons une cuisine équipée.","我们在找设备齐全的厨房。"],["Il est équipé d'un bon casque.","他配有一个好头盔。"]],"co":[["une cuisine équipée","设备齐全的厨房"],["bien équipé","设备好"],["être équipé de","配有……"],["mal équipé","设备差"]],"sy":[["aménagé","courant","布置好的"],["muni de","soutenu","配备有"],["meublé","courant","带家具的"]],"fq":"中频，租房、体育时常用。","me":"équipé ← équipe：一整套「队伍」的装备。","tr":{"zh":"这间厨房设备齐全，什么都有。","fr":"Cette cuisine est bien équipée : il y a tout.","alt":"C'est une cuisine bien équipée, il y a tout ce qu'il faut.","note":"cuisine 是阴性，用 équipée。"}},
 "Essentiel(le)": {"pos":"adj. 形容词，阴性 essentielle，复数 essentiels / essentielles","s":"必不可少的；最重要的；本质的。L'eau est essentielle à la vie. = 水对生命至关重要。作名词 l'essentiel = 最重要的东西；L'essentiel, c'est de... = 重要的是……","ipa":"[e.sɑ̃.sjɛl]","ph":"es [e]；ss 读 [s]；en 读鼻化音 [ɑ̃]；ti 在这里读 [sj]；el [ɛl]。阴性 essentielle 读 [e.sɑ̃.sjɛl]，与阳性同音。","pi":"ti 读 [sj]，不是 [ti]（和 essentiel、patient 同类）。后接 à 或 pour：essentiel à la vie。阴阳性读音一样。","et":"来自拉丁语 essentia（本质），essentialis。同族：l'essence（本质；汽油）、l'essentiel。","ex":[["L'eau est essentielle à la vie.","水是生命必需的。"],["L'essentiel, c'est d'être heureux.","重要的是快乐。"],["C'est un point essentiel.","这是个关键点。"]],"co":[["essentiel à / pour","对……必不可少"],["l'essentiel","要点；最重要的东西"],["l'essentiel, c'est de + inf.","重要的是……"],["un besoin essentiel","基本需求"]],"sy":[["indispensable","courant","不可缺少的"],["fondamental","soutenu","根本的"],["secondaire","courant","反义：次要的"]],"fq":"高频，日常和写作常用。","me":"essentiel ← essence：这件事的「本质」。","tr":{"zh":"重要的是你过得开心。","fr":"L'essentiel, c'est que tu sois heureux.","alt":"Le principal, c'est que tu sois content.","note":"c'est que 后常用虚拟式（sois）。"}},
 "Étrange": {"pos":"adj. 形容词，阴阳性同形，复数 étranges","s":"奇怪的；不寻常的；陌生的。比 bizarre 稍正式。Il est étrange que + 虚拟式 = 奇怪的是……；un bruit étrange = 怪声；une impression étrange = 奇怪的感觉。","ipa":"[e.tʁɑ̃ʒ]","ph":"é [e]；tr [tʁ]；an 读鼻化音 [ɑ̃]；ge 读 [ʒ]，e 不发音。","pi":"不要和 étranger（外国的）混淆。étrange 结尾是 [ɑ̃ʒ]，étranger 结尾是 [ɑ̃.ʒe]。","et":"来自拉丁语 extraneus（外来的），与 étranger 同源。古义是「外面的」，后来变为「陌生的，奇怪的」。","ex":[["C'est une situation très étrange.","这是个非常奇怪的情况。"],["J'ai un sentiment étrange.","我有一种奇怪的感觉。"],["Il est étrange qu'il ne réponde pas.","奇怪的是他不回答。"]],"co":[["c'est étrange","真奇怪"],["une impression étrange","奇怪的感觉"],["il est étrange que + subj.","奇怪的是……"],["chose étrange","怪事"]],"sy":[["bizarre","courant","奇怪的（更口语）"],["curieux","soutenu","奇怪的；好奇的"],["normal","courant","反义：正常的"]],"fq":"中频，日常和书面都用。","me":"étrange 和 étranger 同根：「外面来的」就觉得怪。","tr":{"zh":"这很奇怪，他从来不迟到。","fr":"C'est étrange, il n'est jamais en retard.","alt":"C'est bizarre, il n'est jamais en retard d'habitude.","note":"ne ... jamais 表示「从不」。"}},
 "Étranger / Étrangère": {"pos":"adj. 形容词，阴性 étrangère，复数 étrangers / étrangères；也作名词（外国人）","s":"外国的；陌生的。une langue étrangère = 外语；un étudiant étranger = 外国学生。作名词 un étranger / une étrangère = 外国人、陌生人。à l'étranger = 在国外。","ipa":"[e.tʁɑ̃.ʒe] / [e.tʁɑ̃.ʒɛʁ]","ph":"阳性 étranger：-er 读 [e]，r 不发音；阴性 étrangère：-ère 读 [ɛʁ]，r 发音。an 读鼻化音 [ɑ̃]；g 读 [ʒ]。","pi":"阳性 -er 的 r 不发音，阴性 -ère 的 r 发音。à l'étranger（在国外）用名词形式，不加 pays。不要和 étrange（奇怪的）混淆。","et":"来自古法语 estrangier，源于拉丁语 extraneus（外来的），extra（外面）。同族：étrange（奇怪的）。","ex":[["J'aime étudier les langues étrangères.","我喜欢学外语。"],["Elle voyage souvent à l'étranger.","她经常出国。"],["C'est un étranger dans notre village.","他是我们村里的外乡人。"]],"co":[["une langue étrangère","外语"],["à l'étranger","在国外"],["un pays étranger","外国"],["les affaires étrangères","外交事务"]],"sy":[["inconnu","courant","陌生的"],["étrange","courant","易混：奇怪的"],["national","courant","反义：本国的"]],"fq":"高频，日常常用。","me":"étranger = extra（外面）+ ger：来自「外面」的人。","tr":{"zh":"我想去国外学习一门外语。","fr":"Je voudrais aller étudier une langue étrangère à l'étranger.","alt":"Je voudrais partir à l'étranger pour apprendre une langue.","note":"à l'étranger 表示「在 / 去国外」，不加冠词变化。"}},
 "Historique": {"pos":"adj. 形容词，阴阳性同形，复数 historiques；也作名词 un historique（沿革）","s":"历史的；有历史意义的；历史上真实存在的。un monument historique = 历史古迹；un événement historique = 重大的历史事件；le centre historique = 老城区。","ipa":"[is.tɔ.ʁik]","ph":"h 不发音；his 读 [is]；to 读 [tɔ]；ri 读 [ʁi]；que 读 [k]。","pi":"h 是哑音：un événement historique 要连读，l'historique。结尾 -que 读 [k]，不是 [kə]。不要和 historien（历史学家）混淆。","et":"来自希腊语 historia（探究，历史）经拉丁语 historicus。同族：l'histoire（历史；故事）、l'historien（历史学家）。","ex":[["Nous avons visité le centre historique.","我们参观了历史中心。"],["C'est un monument historique.","这是一处历史古迹。"],["Ce jour est historique pour notre pays.","这一天对我们国家具有历史意义。"]],"co":[["un monument historique","历史古迹"],["le centre historique","老城区"],["un moment historique","历史性时刻"],["un roman historique","历史小说"]],"sy":[["ancien","courant","古老的"],["mémorable","soutenu","难忘的"],["moderne","courant","反义：现代的"]],"fq":"中频，旅游和学习时常用。","me":"historique ← histoire：和历史相关的。","tr":{"zh":"我们周末参观了城市的历史中心。","fr":"Ce week-end, nous avons visité le centre historique de la ville.","alt":"Ce week-end, on a visité le vieux centre de la ville.","note":"visiter 用于参观地点，不用于拜访人。"}},
 "Indispensable": {"pos":"adj. 形容词，阴阳性同形，复数 indispensables","s":"不可缺少的；必需的。indispensable à / pour = 对……必不可少。比 essentiel 更侧重「缺了就不行」。il est indispensable de + 动词原形 = 必须……","ipa":"[ɛ̃.dis.pɑ̃.sabl]","ph":"in 读鼻化音 [ɛ̃]；dis [dis]；pen 读鼻化音 [pɑ̃]；sa [sa]；结尾 -ble 轻读 [bl]。","pi":"in- 在 d 前读 [ɛ̃]，n 不单独发。拼写是 -able，不是 -eble。il est indispensable que + 虚拟式。","et":"由前缀 in-（否定）+ dispensable（可免除的）构成；dispenser 来自拉丁语 dispensare（分配；免除）。意思是「不能被免除的」。","ex":[["Un bon manteau est indispensable en hiver.","冬天好大衣是必需的。"],["Ton aide est indispensable.","你的帮助必不可少。"],["Il est indispensable de réserver.","必须预订。"]],"co":[["indispensable à / pour","对……必不可少"],["il est indispensable de + inf.","必须……"],["il est indispensable que + subj.","……是必须的"],["rendre indispensable","使成为必需"]],"sy":[["essentiel","courant","必不可少的"],["nécessaire","courant","必要的"],["inutile","courant","反义：没用的"]],"fq":"高频，日常常用。","me":"in- + dispens-able：不能被「免掉」的东西。","tr":{"zh":"旅行时护照是必不可少的。","fr":"Le passeport est indispensable pour voyager.","alt":"Pour voyager, il faut absolument un passeport.","note":"indispensable pour + 动词原形：为了……必需。"}},
 "Insolite": {"pos":"adj. 形容词，阴阳性同形，复数 insolites","s":"不寻常的；奇特的；出人意料的（多半是有趣的，带正面色彩）。un lieu insolite = 与众不同的地方；un voyage insolite = 奇特的旅行。比 bizarre 更中性、有时是褒义。","ipa":"[ɛ̃.sɔ.lit]","ph":"in 读鼻化音 [ɛ̃]；so 读 [sɔ]（s 在这里是词内的首音，读 [s]）；li [li]；t 读 [t]。","pi":"in- 读鼻化音，s 读 [s] 不是 [z]。结尾 t 要发音：[lit]。","et":"来自拉丁语 insolitus：in-（否定）+ solitus（惯常的），soleo（习惯于）。意思是「不寻常的」。","ex":[["Nous avons dormi dans un lieu insolite.","我们住在一个很特别的地方。"],["C'est un cadeau insolite.","这是一份别致的礼物。"],["Il a eu une idée insolite.","他想到了一个奇特的主意。"]],"co":[["un lieu insolite","奇特的地方"],["un voyage insolite","奇特的旅行"],["une idée insolite","新奇的主意"],["des vacances insolites","与众不同的假期"]],"sy":[["original","courant","独特的"],["inhabituel","courant","不寻常的"],["banal","courant","反义：平常的"]],"fq":"中频，旅游和广告里常用。","me":"in-（不）+ solite（惯常）：不是平常那样。","tr":{"zh":"我们想找一个与众不同的地方过夜。","fr":"Nous voulons trouver un lieu insolite pour dormir.","alt":"On cherche un endroit insolite pour passer la nuit.","note":"trouver un lieu insolite pour + 动词原形。"}},
 "Lumineux / Lumineuse": {"pos":"adj. 形容词，阴性 lumineuse，复数 lumineux / lumineuses","s":"明亮的；采光好的；发光的。un appartement lumineux = 光线好的公寓；un sourire lumineux = 灿烂的笑容；une idée lumineuse = 绝妙的点子。","ipa":"[ly.mi.nø] / [ly.mi.nøz]","ph":"lu 读 [ly]（u 是 [y]）；mi [mi]；neux 读 [nø]，x 不发音；阴性 lumineuse 读 [ly.mi.nøz]，s 读 [z]。","pi":"阳性 lumineux 的 x 不发音；阴性 lumineuse 的 s 读 [z]。阳性复数还是 lumineux（不变）。u 读 [y]，不是 [u]。","et":"来自拉丁语 luminosus，lumen（光）。同族：la lumière（光）、illuminer（照亮）、le luminaire（灯具）。","ex":[["Mon appartement est très lumineux.","我的公寓很明亮。"],["Elle a un sourire lumineux.","她的笑容灿烂。"],["Quelle idée lumineuse !","多么绝妙的主意！"]],"co":[["un appartement lumineux","明亮的公寓"],["une pièce lumineuse","明亮的房间"],["un sourire lumineux","灿烂的笑容"],["une enseigne lumineuse","发光招牌"]],"sy":[["clair","courant","明亮的"],["ensoleillé","courant","阳光充足的"],["sombre","courant","反义：昏暗的"]],"fq":"中频，租房、描述空间时常用。","me":"lumi-neux：lumière（光）+ 满满的 -eux。","tr":{"zh":"我喜欢这间采光很好的客厅。","fr":"J'aime ce salon très lumineux.","alt":"J'adore ce salon, il est super lumineux.","note":"salon 是阳性，用 lumineux。"}},
 "Meilleur(e)": {"pos":"adj. 形容词，bon 的比较级 / 最高级，阴性 meilleure，复数 meilleurs / meilleures","s":"更好的；最好的。bon（好）的比较级：meilleur(e) que = 比……好；加定冠词变最高级：le meilleur = 最好的。注意：形容词用 meilleur，副词 bien 才用 mieux。","ipa":"[mɛ.jœʁ]","ph":"ei 读 [ɛ]；ll 读 [j]；eu 读 [œ]；r 读 [ʁ]。阴性 meilleure 读 [mɛ.jœʁ]，同音。","pi":"不能说 plus bon，要用 meilleur。meilleur 修饰名词；mieux 修饰动词。例：Il chante mieux. / C'est un meilleur chanteur.","et":"来自拉丁语 melior（更好的），bonus（好）的比较级。同族：améliorer（改善）、l'amélioration（改进）。","ex":[["C'est mon meilleur ami.","他是我最好的朋友。"],["Ce gâteau est meilleur que l'autre.","这块蛋糕比那块好吃。"],["Meilleurs vœux !","最美好的祝愿！"]],"co":[["mon meilleur ami","我最好的朋友"],["meilleur que","比……好"],["Meilleurs vœux !","最美好的祝愿！"],["le meilleur moyen de + inf.","……的最好办法"]],"sy":[["supérieur","soutenu","更优的"],["mieux","courant","副词：更好地"],["pire","courant","反义：更糟的"]],"fq":"极高频，日常常用。","me":"bon → meilleur（不规则）：别说 plus bon。","tr":{"zh":"这是我吃过的最好吃的蛋糕。","fr":"C'est le meilleur gâteau que j'aie jamais mangé.","alt":"C'est le meilleur gâteau que j'ai jamais mangé.","note":"le meilleur ... que + 虚拟式（j'aie），口语也用直陈式。"}},
 "Meublé(e)": {"pos":"adj. 形容词（过去分词），阴性 meublée，复数 meublés / meublées；也作名词 un meublé（带家具的房）","s":"带家具的。un appartement meublé = 带家具的公寓（租房常见）。反义：non meublé / vide。动词 meubler = 布置家具。","ipa":"[mœ.ble]","ph":"meu 读 [mœ]（嘴唇圆，类似「莫」）；blé 读 [ble]。","pi":"meubl- 连续辅音 b + l：[mœ.ble]。与 meuble（家具）同形但词性不同：un meuble（名词）。","et":"来自 meuble（家具），源自拉丁语 mobilis（可移动的）。同族：le meuble（家具）、l'ameublement（家具陈设）、mobile（可移动的）。","ex":[["Je cherche un appartement meublé.","我在找带家具的公寓。"],["La chambre est meublée simplement.","房间的家具很简单。"],["Il loue un petit meublé près de la gare.","他在车站附近租了一间带家具的小屋。"]],"co":[["un appartement meublé","带家具的公寓"],["une location meublée","带家具出租"],["non meublé","不带家具"],["un studio meublé","带家具的单间"]],"sy":[["équipé","courant","配备齐全的"],["vide","courant","反义：空的"],["aménagé","courant","布置好的"]],"fq":"中频，租房时常用。","me":"meuble（家具）+ é：放了家具的。","tr":{"zh":"我想租一间带家具的小公寓。","fr":"Je voudrais louer un petit appartement meublé.","alt":"Je cherche à louer un petit appart meublé.","note":"appartement 是阳性，用 meublé。"}},
 "Moyen(ne)": {"pos":"adj. 形容词，阴性 moyenne，复数 moyens / moyennes","s":"平均的；中等的；一般的。de taille moyenne = 中等个子；la température moyenne = 平均气温；une moyenne = 平均数；un moyen = 办法（名词）。","ipa":"[mwa.jɛ̃]","ph":"oy 读 [waj]，这里 moyen 读 [mwa.jɛ̃]；en 读鼻化音 [ɛ̃]。阴性 moyenne 读 [mwa.jɛn]。","pi":"阴性 moyenne 的 n 要发音。moyen 的 oy 读 [waj]，所以是 [mwa.jɛ̃]，不是 [mɔ.jɛ̃]。","et":"来自拉丁语 medianus（居中的），medius（中间）。同族：le milieu（中间）、le Moyen Âge（中世纪）、un moyen（手段）。","ex":[["Il est de taille moyenne.","他身高中等。"],["La température moyenne est de vingt degrés.","平均气温是二十度。"],["J'ai une note moyenne en maths.","我数学成绩一般。"]],"co":[["de taille moyenne","中等个子"],["en moyenne","平均来说"],["la classe moyenne","中产阶级"],["le Moyen Âge","中世纪"]],"sy":[["ordinaire","courant","普通的"],["médiocre","courant","平庸的"],["extrême","courant","反义：极端的"]],"fq":"高频，日常常用。","me":"moyen ← 中间（medius）：不高不低。","tr":{"zh":"我的数学成绩只是一般。","fr":"Mes résultats en maths sont moyens.","alt":"En maths, j'ai des résultats moyens.","note":"résultats 是复数，所以 moyens 加 s。"}},
 "Normal(e)": {"pos":"adj. 形容词，阴性 normale，复数 normaux / normales","s":"正常的；普通的；合理的。C'est normal. = 这很正常（也可表示「应该的」）。阳性复数 normaux（不是 normals）。","ipa":"[nɔʁ.mal]","ph":"no 读开音 [nɔ]；r 读 [ʁ]；ma [mal]；l 要发音。","pi":"阳性复数 normaux，不是 normals。l 在结尾要读出来：[nɔʁ.mal]。和英语 normal 很像，但重音和元音不同。","et":"来自拉丁语 normalis，norma（规则，标准）。同族：la norme（标准）、anormal（不正常的）、normalement（正常来说）。","ex":[["C'est tout à fait normal.","这完全正常。"],["Il est normal d'avoir peur.","感到害怕很正常。"],["Les résultats sont normaux.","结果正常。"]],"co":[["c'est normal","这很正常"],["il est normal que + subj.","……是正常的"],["tout à fait normal","完全正常"],["la vie normale","正常生活"]],"sy":[["habituel","courant","惯常的"],["ordinaire","courant","普通的"],["anormal","courant","反义：不正常的"]],"fq":"极高频，日常常用。","me":"normal = norma（规则）：合乎规矩，所以正常。","tr":{"zh":"孩子哭了，这很正常。","fr":"C'est normal que les enfants pleurent.","alt":"C'est normal si les enfants pleurent.","note":"c'est normal que 后用虚拟式（pleurent）。"}},
 "Peuplé(e)": {"pos":"adj. 形容词（过去分词），阴性 peuplée，复数 peuplés / peuplées","s":"人口多的；有人居住的。une ville très peuplée = 人口稠密的城市；la région la moins peuplée = 人口最少的地区。动词 peupler = 使有人居住。","ipa":"[pø.ple]","ph":"peu 读 [pø]；ple 读 [ple]；é 结尾读 [e]。","pi":"peuplé 的 eu 读 [ø]，不是 [u]。别和 peu（少）混淆，但读音相近。","et":"来自拉丁语 populus（人民），动词 peupler 源自古法语 pople。同族：le peuple（人民）、la population（人口）、populaire。","ex":[["C'est la ville la plus peuplée du pays.","这是全国人口最多的城市。"],["Cette région est peu peuplée.","这个地区人口稀少。"],["Le pays est très peuplé.","这个国家人口稠密。"]],"co":[["très peuplé","人口稠密"],["peu peuplé","人口稀少"],["la ville la plus peuplée","人口最多的城市"],["densément peuplé","人口密集"]],"sy":[["habité","courant","有人住的"],["désert","courant","反义：荒无人烟的"],["densément peuplé","courant","人口密集的"]],"fq":"中频，地理话题常用。","me":"peuple（人民）+ é：「住满人」的地方。","tr":{"zh":"这个国家北部人口很少。","fr":"Le nord du pays est peu peuplé.","alt":"Dans le nord du pays, il y a peu d'habitants.","note":"peu peuplé：人口少；très peuplé：人口多。"}},
 "Pire": {"pos":"adj. 形容词，mauvais 的比较级 / 最高级，阴阳性同形，复数 pires；也作名词 le pire（最坏的情况）","s":"更糟的；最糟的。比较：pire que = 比……糟；加定冠词：le pire = 最糟的。le pire = 最坏的事。常用 C'est pire. = 更糟了。mauvais 也可用，plus mauvais 是常见的说法，pire 常指程度更重。","ipa":"[piʁ]","ph":"p [p]；i [i]；r 读 [ʁ]，结尾要发音。","pi":"pire 是形容词（更糟），pis 是副词（更差，如 tant pis）。别误说 plus pire。","et":"来自拉丁语 pejor（更坏的），malus（坏）的比较级。同族：empirer（恶化）、pis。","ex":[["C'est la pire journée de ma vie.","这是我一生中最糟的一天。"],["Ce film est pire que l'autre.","这部电影比那部还糟。"],["Le pire, c'est qu'il ne l'a pas dit.","最糟的是他没说。"]],"co":[["le pire","最糟糕的事"],["pire que","比……更糟"],["au pire","最坏的情况下"],["craindre le pire","担心最坏的情况"]],"sy":[["plus mauvais","courant","更差的"],["horrible","courant","糟糕的"],["meilleur","courant","反义：更好的"]],"fq":"高频，日常常用。","me":"pire = pire than：bon → meilleur，mauvais → pire。","tr":{"zh":"最糟的是我忘了带钥匙。","fr":"Le pire, c'est que j'ai oublié mes clés.","alt":"Le pire, c'est que j'ai oublié les clés.","note":"le pire, c'est que + 句子。"}},
 "Populaire": {"pos":"adj. 形容词，阴阳性同形，复数 populaires","s":"受欢迎的；大众的；平民的。un chanteur populaire = 受欢迎的歌手；un quartier populaire = 平民区；la culture populaire = 大众文化。注意：le langage populaire = 口语、俗语。","ipa":"[pɔ.py.lɛʁ]","ph":"po [pɔ]；pu 读 [py]（u 是 [y]）；laire 读 [lɛʁ]。","pi":"u 读 [y]，不是 [u]。un quartier populaire 不是「受欢迎的区」，而是「平民区」，别望文生义。","et":"来自拉丁语 popularis（属于人民的），populus（人民）。同族：le peuple（人民）、la population（人口）、peuplé（人口多的）。","ex":[["C'est un chanteur très populaire.","他是一位很受欢迎的歌手。"],["Elle habite dans un quartier populaire.","她住在平民区。"],["Ce plat est très populaire en France.","这道菜在法国很受欢迎。"]],"co":[["très populaire","非常受欢迎"],["un quartier populaire","平民区"],["la culture populaire","大众文化"],["la musique populaire","流行音乐"]],"sy":[["connu","courant","有名的"],["à la mode","courant","时髦的"],["impopulaire","courant","反义：不受欢迎的"]],"fq":"高频，日常常用。","me":"populaire ← peuple：人民喜欢的，或属于人民的。","tr":{"zh":"这首歌在年轻人中很受欢迎。","fr":"Cette chanson est très populaire chez les jeunes.","alt":"Cette chanson plaît beaucoup aux jeunes.","note":"chez les jeunes：在年轻人当中。"}},
 "Sec / Sèche": {"pos":"adj. 形容词，阴性 sèche，复数 secs / sèches","s":"干燥的；干的；（语气）冷淡的。un climat sec = 干燥的气候；des cheveux secs = 干枯的头发；une réponse sèche = 生硬冷淡的回答；du pain sec = 干面包。","ipa":"[sɛk] / [sɛʃ]","ph":"阳性 sec：e 读 [ɛ]，c 读 [k]；阴性 sèche：è 读 [ɛ]，ch 读 [ʃ]。","pi":"阳性结尾 c 读 [k]，阴性变成 ch 读 [ʃ]：sec [sɛk] / sèche [sɛʃ]。阴性要加重音符 è。","et":"来自拉丁语 siccus（干的）。同族：sécher（弄干）、la sécheresse（干旱）、le sèche-linge（烘干机）。","ex":[["Le climat ici est très sec.","这里的气候很干燥。"],["J'ai la peau sèche en hiver.","我冬天皮肤干燥。"],["Elle m'a répondu d'un ton sec.","她用生硬的语气回答我。"]],"co":[["un climat sec","干燥气候"],["à sec","干涸；没钱（口语）"],["fruits secs","干果"],["un ton sec","生硬的语气"]],"sy":[["aride","soutenu","干旱的"],["desséché","courant","干透的"],["humide","courant","反义：潮湿的"]],"fq":"高频，日常常用。","me":"sec → sèche：阴性换成 ch，音变 [k] → [ʃ]。","tr":{"zh":"冬天我的皮肤很干。","fr":"En hiver, j'ai la peau très sèche.","alt":"L'hiver, ma peau est très sèche.","note":"peau 是阴性，所以用 sèche。"}},
 "Seul(e)": {"pos":"adj. 形容词，阴性 seule，复数 seuls / seules","s":"独自的；孤单的；唯一的。Il habite seul. = 他一个人住；le seul problème = 唯一的问题（放在名词前表示「唯一」）。tout seul = 完全独自、自己（口语）。","ipa":"[sœl]","ph":"s [s]；eu 读 [œ]（在 l 前读开音）；l 要发音。","pi":"放在名词前：le seul ami = 唯一的朋友；放在名词后或谓语：un homme seul = 孤单的人。形容词要与主语一致：Elle est seule。","et":"来自拉丁语 solus（单独的）。同族：la solitude（孤独）、un solo（独奏）、solitaire（孤独的）。","ex":[["Il habite tout seul.","他一个人住。"],["C'est la seule solution.","这是唯一的办法。"],["Elle se sent seule ici.","她在这里觉得孤单。"]],"co":[["tout seul / toute seule","一个人；独自"],["le seul / la seule","唯一的"],["se sentir seul","觉得孤单"],["pas seulement","不只是"]],"sy":[["solitaire","soutenu","孤独的"],["unique","courant","唯一的"],["accompagné","courant","反义：有人陪伴的"]],"fq":"极高频，日常常用。","me":"seul ← solus：孤零零一个「solo」。","tr":{"zh":"她一个人住在巴黎。","fr":"Elle vit seule à Paris.","alt":"Elle habite toute seule à Paris.","note":"seule 与主语 elle 一致；toute seule 更口语。"}},
 "Solidaire": {"pos":"adj. 形容词，阴阳性同形，复数 solidaires","s":"团结互助的；互相支持的；有连带关系的。être solidaire de qqn = 与某人站在一起；un projet solidaire = 带有互助性质的项目；une économie solidaire = 互助经济。","ipa":"[sɔ.li.dɛʁ]","ph":"so 读 [sɔ]；li [li]；daire 读 [dɛʁ]。","pi":"solidaire 是「互相支持」，不是英语的 solidary 或 solid（坚固的）。坚固用 solide。法语多说 être solidaire de qqn。","et":"来自拉丁语 solidus（坚固的），在法律中指「共同承担」。同族：la solidarité（团结）、solide（坚固的）。","ex":[["Ce projet est très solidaire.","这个项目很有互助精神。"],["Nous sommes solidaires de nos voisins.","我们与邻居们站在一起。"],["Les élèves sont solidaires.","学生们互相支持。"]],"co":[["être solidaire de qqn","支持某人"],["une économie solidaire","互助经济"],["un geste solidaire","团结互助的举动"],["rester solidaires","保持团结"]],"sy":[["uni","courant","团结的"],["fraternel","soutenu","兄弟般的"],["égoïste","courant","反义：自私的"]],"fq":"中频，社会话题常用。","me":"solidaire ← solide：大家抱成一团，才坚固。","tr":{"zh":"在困难的时候，邻居们互相帮助。","fr":"Dans les moments difficiles, les voisins sont solidaires.","alt":"Quand c'est dur, les voisins se serrent les coudes.","note":"se serrer les coudes = 互相扶持（口语固定说法）。"}},
 "Superbe": {"pos":"adj. 形容词，阴阳性同形，复数 superbes","s":"极好的；绝美的；壮观的。多形容景色、天气、房子、人。Il fait un temps superbe. = 天气棒极了。也可用作书面语的「傲慢的」，较少见。","ipa":"[sy.pɛʁb]","ph":"su 读 [sy]（u 是 [y]）；per 读 [pɛʁ]；结尾 -be 的 b 要发音：[b]。","pi":"u 读 [y]，不是 [u]。结尾 b 要读 [b]：su-perbe [sy.pɛʁb]，e 轻或不发音。","et":"来自拉丁语 superbus（骄傲的），super（在上面）。同族：super（极好的）、la supériorité（优越）、supérieur（上级的）。","ex":[["La vue depuis la montagne est superbe.","从山上看风景极美。"],["Il fait un temps superbe aujourd'hui.","今天天气好极了。"],["Elle a une voix superbe.","她的嗓音很美。"]],"co":[["un temps superbe","好天气"],["une vue superbe","绝美的景色"],["une journée superbe","美好的一天"],["superbe de + nom","……非常棒"]],"sy":[["magnifique","courant","壮丽的"],["splendide","soutenu","灿烂的"],["horrible","courant","反义：糟糕的"]],"fq":"中频，日常赞美时常用。","me":"superbe ← super：「超棒」的升级版。","tr":{"zh":"从窗户望出去，景色极美。","fr":"La vue depuis la fenêtre est superbe.","alt":"On a une vue superbe depuis la fenêtre.","note":"vue 是阴性，superbe 阴阳同形。"}},
 "Tranquille": {"pos":"adj. 形容词，阴阳性同形，复数 tranquilles","s":"安静的；平静的；安心的。un quartier tranquille = 安静的街区；Laisse-moi tranquille ! = 别烦我！Sois tranquille. = 放心吧。口语中也可说「没问题」。","ipa":"[tʁɑ̃.kil]","ph":"tr [tʁ]；an 读鼻化音 [ɑ̃]；qu 读 [k]；ill 在这里读 [il]（不是 [ij]）。","pi":"tranquille 的 ill 读 [il]，不是 [ij]，是例外（还有 ville、mille）。qu 读 [k]。","et":"来自拉丁语 tranquillus（平静的）。同族：la tranquillité（平静）、tranquilliser（使安心）。","ex":[["Ce quartier est très tranquille.","这个街区非常安静。"],["Laisse-moi tranquille, s'il te plaît.","请别烦我。"],["Sois tranquille, je m'en occupe.","放心，我来处理。"]],"co":[["un endroit tranquille","安静的地方"],["laisser qqn tranquille","别打扰某人"],["Sois tranquille !","放心吧！"],["avoir la conscience tranquille","问心无愧"]],"sy":[["calme","courant","安静的"],["paisible","soutenu","平和的"],["bruyant","courant","反义：吵闹的"]],"fq":"高频，日常常用。","me":"tranquille：像 tranquil，一个很平静的地方。","tr":{"zh":"我想找一个安静的地方读书。","fr":"Je cherche un endroit tranquille pour lire.","alt":"Je voudrais un coin tranquille pour lire.","note":"chercher un endroit + 形容词 + pour + 动词原形。"}},
 "Vivant(e)": {"pos":"adj. 形容词，阴性 vivante，复数 vivants / vivantes","s":"活着的；有生气的；热闹的。un être vivant = 生物；une langue vivante = 现行语言（活的语言）；un quartier vivant = 热闹的街区；bon vivant = 乐天派。","ipa":"[vi.vɑ̃]","ph":"vi [vi]；vant 读鼻化音 [vɑ̃]，t 不发音。阴性 vivante 读 [vi.vɑ̃t]，t 要发音。","pi":"阴性 vivante 的 t 要发音，阳性不发。vivant 作形容词时是「活着的」，不是动词 vivre 的变位。","et":"来自动词 vivre（生活）的现在分词，拉丁语 vivere。同族：la vie（生命）、vif（活泼的）、survivre（幸存）。","ex":[["Ce quartier est très vivant.","这个街区很有活力。"],["Les langues vivantes sont utiles.","现行语言很有用。"],["Mon grand-père est encore vivant.","我爷爷还健在。"]],"co":[["un quartier vivant","热闹的街区"],["une langue vivante","现行语言（外语课程）"],["un être vivant","生物"],["de son vivant","在世时"]],"sy":[["animé","courant","热闹的"],["en vie","courant","活着"],["mort","courant","反义：死的"]],"fq":"高频，日常常用。","me":"vivant = vivre + ant：「正在活着」。","tr":{"zh":"我喜欢住在热闹的街区。","fr":"J'aime habiter dans un quartier vivant.","alt":"J'aime vivre dans un quartier animé.","note":"quartier 是阳性，用 vivant。"}},
 "Ailleurs": {"pos":"adv. 副词，不变","s":"别处；在别的地方。aller ailleurs = 去别处；partout ailleurs = 其他任何地方。d'ailleurs = 再说；而且（引出补充）；par ailleurs = 另外，此外（书面）。","ipa":"[a.jœʁ]","ph":"ai 读 [a]；ill 读 [j]；eu 读 [œ]；r 读 [ʁ]，s 不发音。","pi":"s 不发音：ailleurs [a.jœʁ]；ill 读 [j]。d'ailleurs 是固定词，意思是「再说」，不是「从别处」。","et":"来自俚语拉丁语 aliorsum，由 alius（别的）演变而来，古法语 ailleurs。同族：autre（别的）。","ex":[["Je voudrais aller ailleurs.","我想去别的地方。"],["Il n'est pas ici, cherchons ailleurs.","他不在这儿，我们去别处找。"],["D'ailleurs, il n'a jamais téléphoné.","再说，他从来没打过电话。"]],"co":[["aller ailleurs","去别处"],["d'ailleurs","再说；顺便说一句"],["par ailleurs","此外"],["partout ailleurs","其他任何地方"]],"sy":[["autre part","courant","别的地方"],["là-bas","courant","那边"],["ici","courant","反义：这里"]],"fq":"高频，日常常用。","me":"ailleurs ← alius：「另一个」地方。","tr":{"zh":"这里太吵，我们去别处吧。","fr":"C'est trop bruyant ici, allons ailleurs.","alt":"Y a trop de bruit ici, on va ailleurs.","note":"allons ailleurs：命令式 nous 形，意为「我们去……吧」。"}},
 "Mieux": {"pos":"adv. 副词，bien 的比较级 / 最高级，不变；也作名词 le mieux（最好的）","s":"更好地；更好。bien（好）的比较级：mieux que = 比……好；加定冠词：le mieux = 最好。Je me sens mieux. = 我感觉好些了。aller mieux = （身体）好转。","ipa":"[mjø]","ph":"mi 读 [mj]；eux 读 [ø]，x 不发音。","pi":"mieux（副词）修饰动词；meilleur（形容词）修饰名词。不要说 plus bien。mieux 的 x 不发音。","et":"来自拉丁语 melius（更好地），bene（好）的比较级。同族：meilleur（更好的）。","ex":[["Je me sens beaucoup mieux aujourd'hui.","我今天感觉好多了。"],["Elle chante mieux que moi.","她唱得比我好。"],["C'est mieux ainsi.","这样更好。"]],"co":[["aller mieux","好转；身体好些了"],["de mieux en mieux","越来越好"],["tant mieux","太好了"],["faire de son mieux","尽力而为"]],"sy":[["meilleur","courant","形容词：更好的"],["plutôt","courant","更倾向于"],["pire","courant","对比：更糟的（形容词）"]],"fq":"极高频，日常常用。","me":"bien → mieux；bon → meilleur：两条线别混。","tr":{"zh":"我今天感觉比昨天好多了。","fr":"Je me sens beaucoup mieux qu'hier.","alt":"Je vais mieux qu'hier.","note":"mieux 修饰动词 sentir；beaucoup 加强语气。"}},
 "À l'air libre": {"pos":"loc. 固定短语（à + l'air + libre）","s":"在露天；在户外；在开阔的地方。常指动物、人在自然中的状态：des poules élevées à l'air libre = 放养的母鸡；vivre à l'air libre = 过户外生活。","ipa":"[a.lɛʁ.libʁ]","ph":"à l'air：à + l'air 连读 [a.lɛʁ]；libre 读 [libʁ]，结尾 -bre 轻读。","pi":"air 读 [ɛʁ]，别写成 aire。à l'air libre 里 libre 放在 air 后面。别和 en plein air（在户外）混。","et":"由 à（在）+ l'air（空气）+ libre（自由的）组成：「在自由的空气里」。libre 源自拉丁语 liber（自由的）。","ex":[["Les poules vivent à l'air libre.","母鸡在户外生活。"],["Nous mangeons à l'air libre en été.","夏天我们在户外吃饭。"],["Ces enfants jouent à l'air libre.","这些孩子在户外玩耍。"]],"co":[["vivre à l'air libre","在户外生活"],["des poules élevées à l'air libre","放养的母鸡"],["un spectacle à l'air libre","露天表演"],["en plein air","在户外"]],"sy":[["en plein air","courant","在户外（更常用）"],["dehors","courant","在外面"],["à l'intérieur","courant","反义：在室内"]],"fq":"中频，描述生活方式时常用。","me":"à l'air libre = 在「自由的空气」里。","tr":{"zh":"夏天我们喜欢在户外吃饭。","fr":"En été, nous aimons manger à l'air libre.","alt":"L'été, on aime bien manger dehors.","note":"aimer + 动词原形；à l'air libre 是固定短语，不变。"}},
 "À proximité de": {"pos":"loc. prép. 介词短语，后接名词；不变","s":"在……附近；离……很近。比 près de 稍正式，多见于地址、租房、旅游介绍。à proximité = 在附近（不接 de 时单独用）。","ipa":"[a.pʁɔk.si.mi.te də]","ph":"pro 读 [pʁɔ]；x 读 [ks]；i 读 [i]；mi [mi]；té [te]。de 前常有连读：de + 辅音开头读 [də]。","pi":"x 在这里读 [ks]：proximité [pʁɔk.si.mi.te]。别漏掉 de：à proximité de la gare。也可单独用：à proximité。","et":"来自拉丁语 proximitas（邻近），proximus（最近的）。同族：proche（近的）、approcher（靠近）、la proximité。","ex":[["Le parc est à proximité de l'école.","公园在学校附近。"],["Il y a un supermarché à proximité.","附近有一家超市。"],["L'hôtel est à proximité de la gare.","酒店在车站附近。"]],"co":[["à proximité de la gare","在车站附近"],["à proximité","在附近"],["à proximité immédiate","紧邻"],["les commerces de proximité","社区小店"]],"sy":[["près de","courant","靠近（日常说法）"],["à côté de","courant","紧挨着"],["loin de","courant","反义：远离"]],"fq":"中频，房产和旅游广告里常用。","me":"proximité = proche + ité：很近的地方。","tr":{"zh":"我们的酒店就在海滩附近。","fr":"Notre hôtel est à proximité de la plage.","alt":"Notre hôtel est tout près de la plage.","note":"à proximité de + 名词；口语可用 près de。"}},
 "Aussi ... que": {"pos":"loc. 比较结构：aussi + 形容词 / 副词 + que","s":"和……一样……（同等比较）。aussi grand que moi = 和我一样高。否定时常变成 pas aussi ... que / pas si ... que = 不如……那么……。","ipa":"[o.si ... kə]","ph":"aussi 读 [o.si]；ss 读 [s]；que 读 [kə]，遇元音时省音：qu'elle。","pi":"aussi 只用于形容词和副词，名词用 autant de。例：aussi grand（形容词），autant de livres（名词）。que 后接重读人称代词：que moi（不是 que je）。","et":"由 aussi（也，同样）+ que 构成。aussi 来自 al + si，意为「同样地」，来源可靠但不必记忆。","ex":[["Il est aussi grand que moi.","他和我一样高。"],["Elle parle aussi vite que son frère.","她说话和哥哥一样快。"],["Ce n'est pas aussi cher que je pensais.","没有我想的那么贵。"]],"co":[["aussi ... que moi / toi","和我 / 你一样……"],["pas aussi ... que","不如……那样"],["aussi bien que","和……一样好"],["aussi vite que possible","尽可能快"]],"sy":[["autant de ... que","courant","和……一样多（名词）"],["plus ... que","courant","更……"],["moins ... que","courant","没有……那么……"]],"fq":"极高频，比较句常用。","me":"aussi + 形容词 + que = 「as + adj + as」。","tr":{"zh":"我姐姐和我妈妈一样高。","fr":"Ma sœur est aussi grande que ma mère.","alt":"Ma sœur est grande comme ma mère.","note":"形容词 grande 要和 sœur 一致，用阴性。"}},
 "Autant de ... que": {"pos":"loc. 比较结构：autant de + 名词 + que","s":"和……一样多的……（同等数量比较）。J'ai autant de travail que toi. = 我的工作和你一样多。否定常说 pas autant de ... que = 没有……那么多。","ipa":"[o.tɑ̃ də ... kə]","ph":"au 读 [o]；tan 读鼻化音 [ɑ̃]；t 不发音；de 读 [də]，遇元音时省音：d'amis。","pi":"名词前才用 autant de（数量），形容词前用 aussi。autant de 后名词不加冠词：autant de livres（不是 autant des livres）。que 后接 toi / moi 等重读代词。","et":"由 aut-（同样）+ tant（那么多）构成，来自拉丁语 aliud tantum。可靠的构词：au- + tant，意为「同样多」。","ex":[["J'ai autant de travail que toi.","我的工作和你一样多。"],["Il mange autant de fruits que de légumes.","他吃的水果和蔬菜一样多。"],["Elle n'a pas autant d'amis que lui.","她的朋友没有他多。"]],"co":[["autant de ... que","和……一样多"],["pas autant de ... que","没有……那么多"],["autant que possible","尽可能多地"],["autant dire que","可以说是"]],"sy":[["aussi ... que","courant","和……一样（形容词 / 副词）"],["plus de ... que","courant","比……多"],["moins de ... que","courant","比……少"]],"fq":"高频，比较句常用。","me":"autant de + 名词 = 「as much / as many as」。","tr":{"zh":"我的书和你的一样多。","fr":"J'ai autant de livres que toi.","alt":"J'ai le même nombre de livres que toi.","note":"autant de + 无冠词名词 + que。"}},
 "La périphérie de": {"pos":"loc. 短语（n.f. 阴性名词 + de），复数 périphéries","s":"……的周边；郊区；外围。la périphérie de la ville = 市郊。也指圈子、系统的「外围」。巴黎的环城大道叫 le boulevard périphérique（常缩写 le périph'）。","ipa":"[pe.ʁi.fe.ʁi]","ph":"é [e]；ph 读 [f]；r 是小舌音 [ʁ]；结尾 ie 读 [i]。la 和 de 单独读 [la]、[də]。","pi":"ph 读 [f]，不是 [p]+[h]；词尾 e 不发音但这里是 ie → [i]；périphérie 的重音符号在两个 é 上。","et":"来自希腊语 peripheria（圆周），由 peri（周围）+ pherein（携带、转）构成。同源：périmètre、périscope。","ex":[["Ils habitent à la périphérie de la ville.","他们住在市郊。"],["Il y a un grand centre commercial en périphérie de Lyon.","里昂郊区有一个大型商场。"],["Je prends le périphérique pour éviter le centre.","我走环城路，避开市中心。"]],"co":[["à la périphérie de la ville","在市郊"],["en périphérie","在外围、在郊区"],["le boulevard périphérique","环城大道"],["la périphérie du cercle","圆的边缘"]],"sy":[["banlieue","courant","近郊（卫星城镇），比 périphérie 更口语、更常用"],["alentours","courant","附近、四周（复数）"],["centre","courant","反义：中心"]],"fq":"中频，描述城市时常用。","me":"péri-（周围）+ phérie：绕着中心转一圈的地方。","tr":{"zh":"我们的房子在小城的郊区。","fr":"Notre maison est à la périphérie de la petite ville.","alt":"On habite en périphérie, pas loin de la petite ville.","note":"à la périphérie de + 名词；泛指郊区可说 en périphérie。"}},
 "La plupart de": {"pos":"loc. 短语（n.f. 阴性名词形式），后接 de + 名词","s":"大多数；绝大部分。la plupart des gens = 大多数人。后面接复数名词时，动词用复数：La plupart des gens aiment…。也可单独用：La plupart sont partis。","ipa":"[la.ply.paʁ.də]","ph":"plupart 读 [ply.paʁ]：u [y]，r 要发出来，结尾 -t 不发音；de 在元音前缩成 d'，如 la plupart d'entre nous。","pi":"u 是 [y]（嘴唇圆起来发「衣」），不是 [u]；词尾 t 不发音；后面是 des（de + les），不是 de les。","et":"由 plus（更多）+ part（部分）构成：「更大的一份」。","ex":[["La plupart des gens aiment le chocolat.","大多数人爱巧克力。"],["La plupart de mes amis habitent à Paris.","我大多数朋友住在巴黎。"],["La plupart du temps, je prends le bus.","大多数时候我坐公交车。"]],"co":[["la plupart des gens","大多数人"],["la plupart du temps","大多数时候"],["la plupart d'entre nous","我们中的大多数人"],["pour la plupart","大部分都是"]],"sy":[["la majorité de","courant","多数；更偏数量统计"],["beaucoup de","courant","很多；不一定超过一半"],["la plupart du temps / le plus souvent","courant","多半、通常"]],"fq":"极高频，日常常用。","me":"plu(s) + part：「更多的那一部分」。","tr":{"zh":"大多数学生中午在食堂吃饭。","fr":"La plupart des élèves mangent à la cantine le midi.","alt":"Presque tous les élèves mangent à la cantine à midi.","note":"la plupart des + 复数名词 → 动词用复数。"}},
 "Mettre en contact": {"pos":"loc. 动词短语（mettre，不规则动词，助动词 avoir）","s":"牵线搭桥；把两个人（或单位）联系上。mettre A en contact avec B = 让 A 和 B 取得联系。自己联系上别人用 se mettre en contact avec / prendre contact avec。","ipa":"[mɛtʁ.ɑ̃.kɔ̃.takt]","ph":"mettre 读 [mɛtʁ]，结尾 -re 弱化；en [ɑ̃]；contact 的 -ct 都要发：[kɔ̃.takt]。en 和 contact 之间一般不连读。","pi":"contact 结尾的 c 和 t 都要读出来 [takt]，这和很多法语词的不发音结尾不同；m 在 contact 里不存在，别拼成 contract。","et":"mettre 来自拉丁语 mittere（放、送）；contact 来自拉丁语 contactus（接触，con- 一起 + tangere 碰）。","ex":[["Je vais vous mettre en contact avec le directeur.","我给您和主任牵个线。"],["Une amie m'a mis en contact avec un traducteur.","一位朋友帮我联系上了一个翻译。"],["Je me suis mis en contact avec l'école par mail.","我通过邮件联系了学校。"]],"co":[["mettre quelqu'un en contact avec…","让某人和……联系上"],["se mettre en contact avec","与……取得联系"],["entrer en contact","开始联系、接触"],["rester en contact","保持联系"]],"sy":[["présenter","courant","介绍（人）认识"],["contacter","courant","联系（直接宾语）：Je vais le contacter"],["relier","soutenu","连接；多用于物，不太用于人"]],"fq":"中频，工作和日常都常用。","me":"mettre（放）+ en contact（接触）：把两个人「放到」一起。","tr":{"zh":"我可以让您和我的律师联系上。","fr":"Je peux vous mettre en contact avec mon avocat.","alt":"Je peux vous passer les coordonnées de mon avocat.","note":"mettre qqn en contact avec qqn：两个对象，用 avec 连接。"}},
 "Rendre un service à": {"pos":"loc. 动词短语（rendre，规则 -re 动词，助动词 avoir）","s":"帮（某人）一个忙。rendre service à qqn = 帮忙（不带冠词，更泛）；rendre un service à qqn = 帮一个具体的忙。请求时常说 Tu peux me rendre un service ?","ipa":"[ʁɑ̃dʁ.œ̃.sɛʁ.vis.a]","ph":"rendre 读 [ʁɑ̃dʁ]；un 读 [œ̃]；service 读 [sɛʁ.vis]（词尾 ce 读 [s]，e 不发音）；à 读 [a]。rendre un 之间有轻微连读感，但 d 不发 [t]。","pi":"service 的重音在最后一个音节 [vis]；rendre 的 en 是 [ɑ̃]；别和 servir（服务）的变位混淆。","et":"rendre 来自拉丁语 reddere（还、给回）；service 来自拉丁语 servitium（服务）。「把一个服务还回去/给出去」。","ex":[["Tu peux me rendre un service ?","你能帮我个忙吗？"],["Il m'a rendu un grand service.","他帮了我一个大忙。"],["Merci, tu m'as rendu service !","谢谢，你帮了我大忙！"]],"co":[["rendre un service à quelqu'un","帮某人一个忙"],["rendre service","帮忙、有用"],["Merci du service !","谢谢帮忙！（也可反讽）"],["rendre un petit service","帮个小忙"]],"sy":[["aider","courant","帮助；最普通"],["donner un coup de main","familier","搭把手"],["obliger","soutenu","施惠于人：Vous m'obligeriez beaucoup"]],"fq":"高频，日常常用。","me":"rendre（还）+ service：你帮我，我欠你一个人情。","tr":{"zh":"我邻居昨天帮了我一个大忙。","fr":"Mon voisin m'a rendu un grand service hier.","alt":"Hier, mon voisin m'a bien dépanné.","note":"rendre 的过去分词是 rendu；间接宾语 me/m' 放在助动词前。"}},
 "Un bon plan": {"pos":"loc. n.m. 阳性名词短语，复数 de bons plans","s":"好主意；好办法；划算的好去处或好消息。口语里常指便宜又好的餐厅、折扣、小窍门。Bon plan ! = 好主意！","ipa":"[œ̃.bɔ̃.plɑ̃]","ph":"un [œ̃]；bon [bɔ̃]，n 不发音，只表示鼻化；plan [plɑ̃]。un 和 bon 之间不连读。","pi":"bon 在这里是鼻化元音 [bɔ̃]，不要读成 [bɔn]；复数 de bons plans 中 bons 的 s 不发音。","et":"plan 来自拉丁语 planus（平的），本义是「平面图」，后来引申为「计划、办法」。","ex":[["Ce restaurant est un bon plan.","这家餐厅是个好选择。"],["Tu connais un bon plan pour voyager pas cher ?","你知道便宜旅行的好办法吗？"],["Le cinéma est gratuit le mardi : c'est un bon plan !","周二电影院免费，真划算！"]],"co":[["un bon plan","好办法、好去处"],["les bons plans","优惠信息、实用小窍门"],["un mauvais plan","糟糕的主意"],["donner un bon plan","分享个好门路"]],"sy":[["une bonne idée","courant","好主意；更中性"],["une bonne affaire","courant","划算的买卖"],["un tuyau","familier","小道消息、内幕提示"]],"fq":"高频，口语和年轻人用语。","me":"plan = 「计划」：一个好计划就是「好门路」。","tr":{"zh":"我有个好门路：周日博物馆免费。","fr":"J'ai un bon plan : le musée est gratuit le dimanche.","alt":"Bon plan : le dimanche, le musée est gratuit.","note":"un bon plan 口语常用；冒号后面直接说内容。"}},
 "Le caractère": {"pos":"n.m. 阳性名词，复数 caractères","s":"性格；脾气。avoir bon / mauvais caractère = 脾气好 / 差；avoir du caractère = 有个性、有主见。也指文字的「字符」：un caractère chinois = 汉字。","ipa":"[ka.ʁak.tɛʁ]","ph":"c 在 a 前读 [k]；ch 在这里也读 [k]（不是 [ʃ]）；-ère 读 [ɛʁ]。四个音节：ca-rac-tère，重音在最后。","pi":"ch 读 [k]，不是 [ʃ]；r 要发小舌音；avoir du caractère 不是「性格好」，而是「有个性、不好欺负」。","et":"来自希腊语 kharaktêr（刻印、特征），经拉丁语 character 进入法语。同源：caractériser、caractéristique。","ex":[["Il a un bon caractère.","他性格很好。"],["Elle a du caractère !","她很有个性！"],["Ce mot s'écrit avec quatre caractères.","这个词用四个字符写成。"]],"co":[["avoir bon / mauvais caractère","脾气好 / 差"],["avoir du caractère","有个性"],["un caractère fort / faible","性格强 / 弱"],["un caractère chinois","一个汉字"]],"sy":[["tempérament","soutenu","禀性、气质"],["personnalité","courant","个性（整体）"],["nature","courant","天性：de nature calme"]],"fq":"高频，日常和书面都常用。","me":"caractère：「性格」像刻在人身上的印记（希腊语本义「刻印」）。","tr":{"zh":"我姐姐脾气很好，大家都喜欢她。","fr":"Ma sœur a bon caractère, tout le monde l'aime bien.","alt":"Ma sœur est très sympa, elle a un bon caractère.","note":"avoir bon caractère 常省略冠词；有个性则说 avoir du caractère。"}},
 "Le collège": {"pos":"n.m. 阳性名词，复数 collèges","s":"法国的初中，招收 11–15 岁学生，共四年（六年级到九年级，法语叫 la sixième 到 la troisième）。aller au collège = 上初中。也可指某些机构，如 le Collège de France（法兰西公学院）。","ipa":"[kɔ.lɛʒ]","ph":"c [k]；o [ɔ]；è [ɛ]；ge 读 [ʒ]，词尾 e 不发音。三个音节：co-lège 其实只有两个：[kɔ.lɛʒ]。","pi":"collège 不是英语的 college（大学），法语的「大学」是 l'université（口语 la fac）；ll 只读一个 [l]。","et":"来自拉丁语 collegium（同事团体、共同体）。同源：collègue（同事）。","ex":[["Elle va au collège.","她上初中。"],["Mon frère est en troisième au collège.","我弟弟在读初三。"],["Les élèves du collège ont cours de huit heures à seize heures.","初中生从八点上课到十六点。"]],"co":[["aller au collège","上初中"],["un collégien / une collégienne","初中生"],["le professeur du collège","初中老师"],["entrer en sixième","升入初一（进入 collège）"]],"sy":[["lycée","courant","高中（15–18 岁）"],["école primaire","courant","小学"],["université / fac","courant","大学（fac 为口语）"]],"fq":"高频，谈到学校时必会。","me":"collège 和 collègue（同事）同源：一群在一起的人。","tr":{"zh":"我女儿明年上初中。","fr":"Ma fille entre au collège l'année prochaine.","alt":"L'an prochain, ma fille sera au collège.","note":"entrer au collège = 升入初中；au = à + le。"}},
 "Le lycée": {"pos":"n.m. 阳性名词，复数 lycées","s":"高中，招收 15–18 岁学生，共三年：seconde、première、terminale，最后参加 le baccalauréat（高中毕业会考，常说 le bac）。aller au lycée = 上高中。","ipa":"[li.se]","ph":"y 在这里读 [i]；c 在 é 前读 [s]；é 读 [e]。两个音节：ly-cée。","pi":"y 读 [i]，不要读成 [j] 或 [y]；cée 读 [se]，不是 [ke]；和 collège（初中）别混。","et":"来自希腊语 Lukeion（亚里士多德在雅典讲学的地方），经拉丁语 lycaeum 传入法语。","ex":[["Il étudie au lycée.","他在上高中。"],["Elle passe le bac à la fin du lycée.","她高中毕业时参加会考。"],["Mon lycée est près de la gare.","我的高中离火车站很近。"]],"co":[["aller au lycée","上高中"],["un lycéen / une lycéenne","高中生"],["un lycée professionnel","职业高中"],["la classe de terminale","高三"]],"sy":[["collège","courant","初中"],["bahut","familier","（学校、高中）俚语说法"]],"fq":"高频，谈学校时必会。","me":"lycée [li.se]：想「立刻上课」，高中要备考 bac。","tr":{"zh":"他高中毕业后想学医。","fr":"Après le lycée, il veut étudier la médecine.","alt":"Une fois le lycée fini, il veut faire médecine.","note":"étudier la médecine / faire médecine 都可以，后者更口语。"}},
 "Le Petit Nicolas": {"pos":"n.m. 阳性专有名词（书名、人物名）","s":"《小淘气尼古拉》：法国经典儿童幽默小说系列，作者 René Goscinny（文）与 Jean-Jacques Sempé（图），讲一个小学男孩和同学们的日常趣事。也指书中的小主人公 le petit Nicolas。","ipa":"[lə.pə.ti.ni.kɔ.la]","ph":"le [lə]；petit 的 t 在这里读出来 [pə.ti]（后面是 Nicolas，元音，所以连读不需要，t 本来就读）；Nicolas 词尾 s 不发音：[ni.kɔ.la]。","pi":"Nicolas 结尾的 s 不发音；ni 读 [ni]，不是 [ni:]；petit 第一个 e 弱读 [pə]，说快了常被吞掉。","et":"Nicolas 来自希腊语 Nikolaos（nikê 胜利 + laos 人民）。petit 来自古法语，意为「小」。","ex":[["Le Petit Nicolas est un livre célèbre.","《小淘气尼古拉》是一本著名的书。"],["Mon fils lit Le Petit Nicolas avant de dormir.","我儿子睡前读《小淘气尼古拉》。"],["Dans Le Petit Nicolas, les histoires se passent à l'école.","《小淘气尼古拉》里的故事发生在学校。"]],"co":[["lire Le Petit Nicolas","读《小淘气尼古拉》"],["les histoires du Petit Nicolas","小淘气尼古拉的故事"],["un livre pour enfants","儿童读物"],["Goscinny et Sempé","戈西尼与桑佩（作者与插画家）"]],"sy":[["Astérix","courant","同一作者 Goscinny 的另一经典漫画系列"],["Tintin","courant","另一部法语经典漫画（比利时）"]],"fq":"文化常识；法国人几乎人人读过。","me":"petit + Nicolas：「小」尼古拉，永远在调皮捣蛋。","tr":{"zh":"我小时候很喜欢读《小淘气尼古拉》。","fr":"Quand j'étais petit, j'adorais lire Le Petit Nicolas.","alt":"Petit, je lisais tout le temps Le Petit Nicolas.","note":"书名首字母大写并用斜体；用未完成过去时 j'étais / j'adorais 讲小时候。"}},
 "Le physique": {"pos":"n.m. 阳性名词，单数常用（le physique）","s":"外貌；身材；体格。avoir un beau physique = 外形好。au physique = 在外貌方面。注意：la physique（阴性）是「物理学」；physique 作形容词 = 身体的、物理的。","ipa":"[fi.zik]","ph":"ph 读 [f]；y 读 [i]；s 在两元音间读 [z]；-que 读 [k]，e 不发音。两个音节：phy-sique。","pi":"le physique（外貌）和 la physique（物理学）性别不同、意思也不同；ph 读 [f]；s 读 [z]，不是 [s]。","et":"来自希腊语 phusikos（关于自然的），phusis = 自然。「外貌」是指身体的自然状态。","ex":[["Il a un physique sportif.","他身材健美。"],["Elle a le physique d'une danseuse.","她有舞蹈演员的身材。"],["Au physique, il ressemble à son père.","外貌上，他像他爸爸。"]],"co":[["avoir un beau physique","外形好"],["avoir le physique de l'emploi","外形和职业很搭"],["au physique et au moral","身体和精神方面"],["un physique avantageux","出众的外形"]],"sy":[["apparence","courant","外表（偏整体印象）"],["corps","courant","身体"],["allure","courant","外观、风度"]],"fq":"中频，描述人时常用。","me":"le physique = 身体；la physique = 物理。阳性的是「人」，阴性的是「学科」。","tr":{"zh":"他外形好，但是性格不太好。","fr":"Il a un beau physique, mais il n'a pas très bon caractère.","alt":"Il est beau, mais il a un mauvais caractère.","note":"mais 连接对比；avoir un beau physique 搭配固定。"}},
 "Napoléon": {"pos":"n.m. 阳性专有名词（人名）","s":"拿破仑：Napoléon Bonaparte（1769–1821），法国军事家，1804 年称帝，称 Napoléon Ier。法国人常提到他的法典（le Code civil）和战争。也可指其侄子 Napoléon III。","ipa":"[na.pɔ.le.ɔ̃]","ph":"na [na]；po [pɔ]；lé [le]；on 在 é 之后单独读 [ɔ̃]，所以 -léon 是两个音节：[le.ɔ̃]。","pi":"Napoléon 的 -éon 不是 [eɔn]，而是 [e.ɔ̃]；结尾 n 不发音，只使元音鼻化；o 在 po 里是开口 [ɔ]。","et":"名字来自意大利语 Napoleone，更早来源不确定。形容词：napoléonien。","ex":[["Napoléon est un empereur français.","拿破仑是法国皇帝。"],["Napoléon est né en Corse en 1769.","拿破仑 1769 年出生在科西嘉。"],["On visite le tombeau de Napoléon aux Invalides.","人们在荣军院参观拿破仑的墓。"]],"co":[["Napoléon Bonaparte","拿破仑·波拿巴"],["l'époque napoléonienne","拿破仑时代"],["le Code Napoléon","拿破仑法典"],["l'armée de Napoléon","拿破仑的军队"]],"sy":[["l'Empereur","soutenu","「皇帝」，指拿破仑本人"],["Bonaparte","courant","他的姓氏"]],"fq":"文化常识；历史和旅游中常见。","me":"Napo + léon：像「雷昂」（léon，狮子）一样的名字。","tr":{"zh":"拿破仑是一位著名的法国皇帝。","fr":"Napoléon est un célèbre empereur français.","alt":"Napoléon, c'est un empereur français très connu.","note":"empereur 前面是 un；国籍形容词 français 不大写。"}},
 "Un article": {"pos":"n.m. 阳性名词，复数 articles","s":"文章；报道；条款；商品。un article de journal = 报纸文章；un article défini / indéfini = 定冠词 / 不定冠词（语法）；un article de sport = 运动用品。","ipa":"[aʁ.tikl]","ph":"ar [aʁ]；ti [ti]；cle 结尾 [kl]，e 弱化几乎不发音。两个音节：ar-ticle。","pi":"结尾 -cle 读 [kl]，不是 [kəl]；很多人把 article 拼成 articule；它的意思不只是「冠词」。","et":"来自拉丁语 articulus（小关节、小部分），articulus 是 artus（关节）的指小词。同源：articuler。","ex":[["J'ai lu un article dans le journal.","我在报纸上读了一篇文章。"],["Cet article parle de l'écologie.","这篇文章讲生态问题。"],["Ce magasin vend des articles de sport.","这家店卖运动用品。"]],"co":[["un article de journal / de presse","报纸文章"],["un article défini / indéfini","定冠词 / 不定冠词"],["un article de sport","运动用品"],["à l'article 3","在第三条"]],"sy":[["texte","courant","文本（更泛）"],["papier","familier","（记者用语）稿子、文章"],["produit","courant","产品、商品"]],"fq":"高频，日常和书面都常用。","me":"article：「一小段」——文章中的一部分、法条中的一条。","tr":{"zh":"我昨天读了一篇关于旅游的文章。","fr":"Hier, j'ai lu un article sur le tourisme.","alt":"J'ai lu un article sur les voyages hier.","note":"lire un article sur + 主题。"}},
 "Un cliché": {"pos":"n.m. 阳性名词，复数 clichés","s":"陈词滥调；刻板印象；老一套。也指照片底片或一张照片（用于摄影，较书面）。Ce n'est qu'un cliché = 这只是个老套的刻板印象。","ipa":"[kli.ʃe]","ph":"cl [kl]；i [i]；ché 读 [ʃe]：ch [ʃ]，é [e]。两个音节：cli-ché。","pi":"ch 读 [ʃ]，不是 [k]；é 是闭口 [e]，结尾没有 [j]；注意不要和 clic（点击声）混。","et":"原为印刷术语（印刷版），后来指「被印刷很多次的东西」，引申为「老套的想法」。","ex":[["C'est un cliché sur les Français.","这是对法国人的刻板印象。"],["Ce film est plein de clichés.","这部电影全是老套情节。"],["Il a pris de beaux clichés de la montagne.","他拍了一些漂亮的山景照片。"]],"co":[["un cliché sur…","关于……的刻板印象"],["tomber dans les clichés","落入俗套"],["un cliché éculé","陈腐的老套"],["un cliché de la montagne","一张山景照片（书面）"]],"sy":[["stéréotype","soutenu","刻板印象（更学术）"],["lieu commun","soutenu","老生常谈"],["idée reçue","courant","固有想法"]],"fq":"中频，谈文化和电影时常用。","me":"cliché：「咔嚓」一次一次印出来的 = 千篇一律。","tr":{"zh":"说法国人都爱吃蜗牛，这是个刻板印象。","fr":"Dire que tous les Français mangent des escargots, c'est un cliché.","alt":"Les Français et leurs escargots, c'est un cliché !","note":"Dire que…, c'est… 是常见句型：「说……，这是……」。"}},
 "Un cochon": {"pos":"n.m. 阳性名词，复数 cochons；雌性 une truie（母猪）","s":"猪（活的动物，日常说法）。也骂人或形容：脏的人、好色的人（familier）。un cochon d'Inde = 豚鼠。吃的猪肉是 le porc。","ipa":"[kɔ.ʃɔ̃]","ph":"c [k]；o [ɔ]；ch [ʃ]；结尾 on 是鼻化元音 [ɔ̃]，n 不发音。","pi":"ch 读 [ʃ]，不是 [k]；结尾 -on 读鼻音 [ɔ̃]；骂人时 cochon 比较粗，别随便对人说。","et":"来源不确定，可能来自拟声或古法语方言。同族：cochonnerie（脏东西）。","ex":[["Le cochon est rose.","猪是粉红色的。"],["Il mange comme un cochon.","他吃饭像头猪。"],["Mon fils a un cochon d'Inde.","我儿子养了一只豚鼠。"]],"co":[["un cochon d'Inde","豚鼠"],["manger comme un cochon","吃相很差"],["un cochon rose","粉色小猪"],["une tirelire cochon","猪形存钱罐"]],"sy":[["porc","courant","猪肉；也指养殖的猪"],["goret","familier","小猪"],["truie","courant","母猪"]],"fq":"高频，动物词汇必会。","me":"cochon = 「可爱又脏的猪」，cochon d'Inde 是豚鼠（不是印度猪）。","tr":{"zh":"农场里有一头很大的猪。","fr":"Il y a un très gros cochon dans la ferme.","alt":"À la ferme, il y a un énorme cochon.","note":"il y a + 名词；gros 在名词前。"}},
 "Un compliment": {"pos":"n.m. 阳性名词，复数 compliments","s":"赞美；夸奖；恭维。faire un compliment à qqn = 夸某人。复数 mes compliments = 我的祝贺。动词是 complimenter（夸奖）。","ipa":"[kɔ̃.pli.mɑ̃]","ph":"com 读 [kɔ̃]（m 在 p 前使元音鼻化）；pli [pli]；ment 读 [mɑ̃]。三个音节：com-pli-ment。","pi":"m 不发音，只是使 o 鼻化：[kɔ̃]；结尾 -ment 读 [mɑ̃]；不要和 complément（补语）混。","et":"来自西班牙语 cumplimiento（礼貌之举）（16 世纪），具体来源有争议。同族：complimenter。","ex":[["Il me fait un compliment.","他夸奖了我。"],["Merci pour ton compliment, c'est gentil.","谢谢你的夸奖，你真好。"],["Tous mes compliments pour ton examen !","祝贺你考试通过！"]],"co":[["faire un compliment à quelqu'un","夸奖某人"],["recevoir un compliment","收到夸奖"],["Mes compliments !","祝贺你！"],["un compliment sincère","真诚的赞美"]],"sy":[["éloge","soutenu","颂扬、称赞"],["félicitations","courant","祝贺（复数）"],["flatterie","courant","奉承；带贬义"]],"fq":"高频，日常常用。","me":"compliment ≈ 「完全满意」的话；别和 complément 混。","tr":{"zh":"他对我的法语夸了几句。","fr":"Il m'a fait un compliment sur mon français.","alt":"Il m'a dit que mon français était bien.","note":"faire un compliment à qqn sur qqch：夸某人某方面。"}},
 "Un corbeau": {"pos":"n.m. 阳性名词，复数 corbeaux","s":"乌鸦（常指渡鸦，较大）；小一些的乌鸦叫 une corneille。比喻：写匿名信的人（le corbeau）。La Fontaine 的寓言《乌鸦和狐狸》（Le Corbeau et le Renard）家喻户晓。","ipa":"[kɔʁ.bo]","ph":"or [ɔʁ]；b [b]；eau 读 [o]。两个音节：cor-beau。","pi":"-eau 读 [o]；复数 corbeaux 的 x 不发音；corbeau 和 corbeille（篮子）拼写相近，意思无关。","et":"来自拉丁语 corvus（渡鸦）加指小后缀；同源：corneille 等鸟名。","ex":[["Le corbeau est un oiseau noir.","乌鸦是一种黑色的鸟。"],["Un corbeau a volé le fromage dans la fable.","寓言里，一只乌鸦叼走了奶酪。"],["Un corbeau envoie des lettres anonymes au village.","一个写匿名信的人给村子寄信。"]],"co":[["un corbeau noir","黑乌鸦"],["le corbeau et le renard","乌鸦与狐狸（寓言）"],["croasser (cri du corbeau)","乌鸦叫"],["un vol de corbeaux","一群乌鸦"]],"sy":[["corneille","courant","小乌鸦、秃鼻乌鸦"],["oiseau","courant","鸟（上位词）"]],"fq":"中频，动物词汇；寓言里常见。","me":"cor-beau：黑黑的「美鸟」，想起乌鸦嘴里的奶酪。","tr":{"zh":"窗外有一只乌鸦在叫。","fr":"Un corbeau croasse dehors, devant la fenêtre.","alt":"Il y a un corbeau qui crie derrière la fenêtre.","note":"croasser = 乌鸦叫；il y a… qui + 动词 是口语常见结构。"}},
 "Un costume-cravate": {"pos":"n.m. 阳性名词，复数 des costumes-cravates（两部分都加 s）","s":"西装加领带的一整套（男士正装）。un costume 单独就指男士西装；une cravate 是领带。法语的 costume 也可指演出服装、民族服装（costume traditionnel）。","ipa":"[kɔs.tym.kʁa.vat]","ph":"cos [kɔs]；tume 读 [tym]：u [y]；cra [kʁa]；vate 读 [vat]，结尾 -e 不发音。","pi":"u 读 [y]（嘴圆）；costume 的 s 读 [s]；和英语 costume（戏服）有点不同：法语里常指西装。","et":"costume 来自意大利语 costume（习惯），源自拉丁语 consuetudo；cravate 来自 Cravate = 克罗地亚人，17 世纪克罗地亚雇佣兵戴的颈巾。","ex":[["Il porte un costume-cravate.","他穿着西装打着领带。"],["Pour l'entretien, il met un costume-cravate.","面试时，他穿西装系领带。"],["Je n'aime pas le costume-cravate au bureau.","我不喜欢办公室里穿西装打领带。"]],"co":[["porter un costume-cravate","穿西装打领带"],["être en costume-cravate","穿着西装打领带"],["un costume sombre","深色西装"],["une cravate rouge","红色领带"]],"sy":[["tenue de ville","courant","正式的日常装束"],["complet","courant","（男士）成套西装"],["tailleur","courant","（女士）套装"]],"fq":"中频，描述穿着时常用。","me":"costume + cravate：两件东西，一个连字符，一整套正装。","tr":{"zh":"面试时，我穿了西装打领带。","fr":"Pour l'entretien, j'ai mis un costume-cravate.","alt":"À l'entretien, j'étais en costume-cravate.","note":"mettre 的过去分词是 mis；在……时穿着用 être en + 衣物。"}},
 "Un criquet": {"pos":"n.m. 阳性名词，复数 criquets","s":"蝗虫；蚂蚱（成群时造成灾害）。书里的「蟋蟀」其实对应 un grillon，不是 criquet。小的草蜢常叫 une sauterelle。","ipa":"[kʁi.kɛ]","ph":"cr [kʁ]；i [i]；quet 读 [kɛ]：qu [k]，et [ɛ]，t 不发音。","pi":"结尾 -et 读 [ɛ]，t 不发音；英语 cricket 指蟋蟀或板球，但法语 criquet 是蝗虫，蟋蟀是 grillon；板球叫 le cricket [kʁi.kɛt]（t 要发音）。","et":"可能来自拟声词 cri-cri（昆虫的叫声）；来源不完全确定。","ex":[["Le criquet saute dans l'herbe.","蝗虫在草里跳。"],["Des criquets ont détruit les récoltes.","蝗虫毁了庄稼。"],["Le soir, on entend le grillon, pas le criquet.","晚上能听到蟋蟀叫，不是蝗虫。"]],"co":[["un nuage de criquets","蝗群"],["un criquet pèlerin","沙漠蝗虫"],["un criquet qui saute","一只蹦跳的蝗虫"]],"sy":[["sauterelle","courant","蚱蜢、草蜢"],["grillon","courant","蟋蟀（不是蝗虫）"],["locuste","littéraire","书面：蝗虫"]],"fq":"低频，昆虫词汇。","me":"criquet 会 cri（叫）？不！叫的是 grillon；criquet 是蹦的蝗虫。","tr":{"zh":"草里有一只蝗虫在跳。","fr":"Un criquet saute dans l'herbe.","alt":"Il y a un criquet qui saute dans l'herbe.","note":"sauter 是规则 -er 动词；dans l'herbe：在草里。"}},
 "Un défaut": {"pos":"n.m. 阳性名词，复数 défauts","s":"缺点；毛病；瑕疵。Chacun a ses défauts = 人人都有缺点。反义词是 une qualité。另有「缺乏」义：faire défaut = 缺少；à défaut de = 如果没有……。","ipa":"[de.fo]","ph":"dé [de]；faut 读 [fo]：au 读 [o]，t 不发音。两个音节：dé-faut。","pi":"结尾 -aut 读 [o]，t 不发音；和 défaite（失败）发音接近，别混淆；不是英语的 default（默认）。","et":"来自古法语 defaute，源自动词 défaillir/faillir（缺少），拉丁语 fallere（欺骗、不足）。同族：faute、faillir。","ex":[["La jalousie est un défaut.","嫉妒是一种缺点。"],["Ce produit a un défaut de fabrication.","这个产品有制造缺陷。"],["Le courage lui fait défaut.","他缺乏勇气。"]],"co":[["avoir des défauts","有缺点"],["un défaut de fabrication","制造缺陷"],["à défaut de","如果没有……就"],["faire défaut","缺少"]],"sy":[["imperfection","soutenu","不完美"],["travers","soutenu","小毛病"],["qualité","courant","反义：优点"]],"fq":"高频，日常和书面都常用。","me":"dé-faut：「没做好」的部分，想到 faute（错误）。","tr":{"zh":"每个人都有缺点，我也有。","fr":"Tout le monde a des défauts, moi aussi.","alt":"Chacun a ses défauts, moi aussi j'en ai.","note":"tout le monde 是单数，动词用 a；j'en ai 里的 en 代替 des défauts。"}},
 "Un divan": {"pos":"n.m. 阳性名词，复数 divans","s":"长沙发；榻（常指没有靠背或靠背很低的长沙发，可当床用）。日常说「沙发」更常用 un canapé。心理分析师的躺椅也叫 le divan：aller chez un psy, s'allonger sur le divan。","ipa":"[di.vɑ̃]","ph":"di [di]；van 读 [vɑ̃]：an 是鼻化元音，n 不发音。两个音节：di-van。","pi":"van 读 [vɑ̃]，不要读成 [van]；divan 比 canapé 更文艺或老式。","et":"来自土耳其语 divan，源自波斯语 dīwān（会议室，铺垫的长椅）。同源：英语 divan。","ex":[["Je dors sur le divan.","我睡在长沙发上。"],["Le chat est couché sur le divan.","猫躺在长沙发上。"],["Le psychanalyste demande au patient de s'allonger sur le divan.","心理分析师请病人躺在榻上。"]],"co":[["s'allonger sur le divan","躺在长沙发上"],["un divan-lit","沙发床"],["dormir sur le divan","睡在沙发上"],["un divan en cuir","皮沙发"]],"sy":[["canapé","courant","沙发（最常用）"],["sofa","courant","沙发（外来词）"],["banquette","courant","长凳座"]],"fq":"中低频，日常多用 canapé。","me":"divan [di.vɑ̃]：像英语 divan，躺着聊心事的地方。","tr":{"zh":"我喜欢躺在沙发上看书。","fr":"J'aime lire allongé sur le canapé.","alt":"J'adore lire sur le divan, bien allongé.","note":"日常说 canapé 更自然；divan 稍老式。"}},
 "Un éléphant": {"pos":"n.m. 阳性名词，复数 éléphants；雌象 une éléphante","s":"大象。des éléphants d'Afrique / d'Asie = 非洲象 / 亚洲象。比喻：une mémoire d'éléphant = 记性极好；un éléphant dans un magasin de porcelaine = 笨手笨脚闯祸的人。","ipa":"[e.le.fɑ̃]","ph":"é [e]；lé [le]；ph 读 [f]；an 读 [ɑ̃]，t 不发音。三个音节：é-lé-phant。","pi":"ph 读 [f]；结尾 -ant 读 [ɑ̃]，t 不发音；英语 elephant 结尾 [nt] 要发出来，法语不要；与元音前缩写：l'éléphant。","et":"来自拉丁语 elephantus，源自希腊语 elephas（象，也指象牙）。","ex":[["L'éléphant a de grandes oreilles.","大象有大耳朵。"],["Un éléphant pèse plusieurs tonnes.","一头大象有好几吨重。"],["Elle a une mémoire d'éléphant.","她记性好得惊人。"]],"co":[["un éléphant d'Afrique / d'Asie","非洲象 / 亚洲象"],["avoir une mémoire d'éléphant","记性极好"],["un éléphant dans un magasin de porcelaine","瓷器店里的大象（笨手笨脚）"],["la trompe de l'éléphant","象鼻"]],"sy":[["pachyderme","soutenu","厚皮动物（书面）"],["mammouth","courant","猛犸象"]],"fq":"高频，动物词汇必会。","me":"é-lé-phant：三个 é/e 音，像大象走路「咚——咚——咚」。","tr":{"zh":"大象的鼻子很长。","fr":"L'éléphant a une très longue trompe.","alt":"La trompe de l'éléphant est très longue.","note":"elephant 前用 l'（省音）；trompe 是象鼻（也指喇叭）。"}},
 "Un intérêt": {"pos":"n.m. 阳性名词，复数 intérêts","s":"兴趣；利益；利息。avoir de l'intérêt pour = 对……有兴趣；dans ton intérêt = 为你好；les intérêts = 银行利息。avoir intérêt à + 动词原形 = 最好、应该（有必要）。","ipa":"[ɛ̃.te.ʁɛ]","ph":"in 读 [ɛ̃]；té [te]；rêt 读 [ʁɛ]：ê [ɛ]，t 不发音。三个音节：in-té-rêt。","pi":"in- 读鼻化元音 [ɛ̃]；结尾 t 不发音；avoir intérêt à 不是「有兴趣」，而是「最好……」。","et":"来自拉丁语 interest（「这关系到……」，interesse 的第三人称单数）。同族：intéresser、intéressant。","ex":[["Il a un intérêt pour l'art.","他对艺术有兴趣。"],["Tu as intérêt à partir tout de suite.","你最好马上走。"],["Ce projet n'a aucun intérêt.","这个项目一点意思也没有。"]],"co":[["avoir intérêt à + inf.","最好、有必要做某事"],["dans l'intérêt de…","为了……的利益"],["porter de l'intérêt à…","对……感兴趣"],["un taux d'intérêt","利率"]],"sy":[["curiosité","courant","好奇心"],["passion","courant","热情（更强烈）"],["avantage","courant","好处"]],"fq":"高频，日常和书面都常用。","me":"intérêt ≈ inter + est：「关系到我」= 我有兴趣。","tr":{"zh":"你最好早一点出门，路上堵车。","fr":"Tu as intérêt à partir plus tôt, il y a des embouteillages.","alt":"Si j'étais toi, je partirais plus tôt, ça bouchonne.","note":"avoir intérêt à + 动词原形，口气偏强硬。"}},
 "Un lapin": {"pos":"n.m. 阳性名词，复数 lapins；雌兔 une lapine","s":"兔子（家兔）。野兔是 un lièvre。亲昵称呼：mon petit lapin。口语里 poser un lapin à qqn = 放某人鸽子，约好了不到。","ipa":"[la.pɛ̃]","ph":"la [la]；pin 读 [pɛ̃]：in 是鼻化元音，n 不发音。两个音节：la-pin。","pi":"-in 读 [ɛ̃]，不是 [in]；poser un lapin 是「放鸽子」，和兔子本身无关。","et":"来源不确定；同族：lapereau（小兔）、lapine（母兔）。","ex":[["Le lapin mange une carotte.","兔子在吃胡萝卜。"],["Elle m'a posé un lapin hier soir.","她昨晚放了我鸽子。"],["Le lapin court dans le jardin.","兔子在花园里跑。"]],"co":[["poser un lapin à quelqu'un","放某人鸽子"],["mon petit lapin","我的小宝贝（昵称）"],["un lapin blanc","白兔"],["un terrier de lapin","兔子洞"]],"sy":[["lièvre","courant","野兔"],["lapereau","courant","小兔子"]],"fq":"高频，动物词汇必会。","me":"la-pin：想象小兔「啪」一下躲进洞里。","tr":{"zh":"他又放了我鸽子！","fr":"Il m'a encore posé un lapin !","alt":"Il m'a encore fait faux bond !","note":"poser un lapin 是固定说法；posé 是 poser 的过去分词。"}},
 "Un lion": {"pos":"n.m. 阳性名词，复数 lions；雌狮 une lionne","s":"狮子。le roi des animaux = 百兽之王。比喻：la part du lion = 最大的一份；courageux comme un lion = 勇猛如狮。小狮子叫 un lionceau。","ipa":"[ljɔ̃]","ph":"li 在这里 i 变成半元音 [j]，合起来 [ljɔ̃]，一个音节；on 读 [ɔ̃]，n 不发音。","pi":"lion 只有一个音节 [ljɔ̃]，不要读成 [li.ɔ̃]；结尾 n 不发音。","et":"来自拉丁语 leo, leonis（狮）。形容词：léonin。","ex":[["Le lion est le roi des animaux.","狮子是百兽之王。"],["La lionne chasse pour ses petits.","母狮为幼崽捕猎。"],["Il a eu la part du lion.","他拿了最大的一份。"]],"co":[["le roi des animaux","百兽之王"],["la part du lion","最大的一份"],["une crinière de lion","狮子的鬃毛"],["se battre comme un lion","拼死战斗"]],"sy":[["fauve","courant","猛兽（大型猫科）"],["félin","soutenu","猫科动物"]],"fq":"高频，动物词汇必会。","me":"lion [ljɔ̃]：听起来像英语 lion，也像一声低吼。","tr":{"zh":"狮子在草原上睡觉。","fr":"Le lion dort dans la savane.","alt":"Dans la savane, le lion fait la sieste.","note":"dans la savane：在草原上；faire la sieste = 午睡。"}},
 "Un lynx": {"pos":"n.m. 阳性名词，单复数同形：des lynx","s":"猞猁（一种大型野猫，耳尖有簇毛）。以视力敏锐出名：avoir des yeux de lynx = 目光锐利，什么都看得见。","ipa":"[lɛ̃ks]","ph":"l [l]；y 与 n 结合读鼻化元音 [ɛ̃]；x 读 [ks]。整个词一个音节 [lɛ̃ks]。","pi":"x 要发音 [ks]；复数不加 s，也是 lynx；y+n 读 [ɛ̃]，不是 [in]。","et":"来自拉丁语 lynx，源自希腊语 lunx（猞猁）。","ex":[["Le lynx a de grands yeux.","猞猁有大眼睛。"],["Dans le Jura, il y a quelques lynx.","汝拉山区有一些猞猁。"],["Il a des yeux de lynx : il voit tout !","他眼睛像猞猁，什么都看得见！"]],"co":[["avoir des yeux de lynx","目光锐利"],["un lynx boréal","欧亚猞猁"],["le lynx des montagnes","山地猞猁"]],"sy":[["chat sauvage","courant","野猫"],["félin","soutenu","猫科动物"]],"fq":"低频，动物词汇。","me":"lynx [lɛ̃ks]：x 要发出来，和 linx 一起变成一声短促的「林克斯」。","tr":{"zh":"他的眼睛像猞猁一样锐利。","fr":"Il a des yeux de lynx.","alt":"Rien ne lui échappe, il a des yeux de lynx.","note":"avoir des yeux de lynx 是固定说法。"}},
 "Un mannequin": {"pos":"n.m. 阳性名词，复数 mannequins；女模特也用 un mannequin","s":"模特（时装模特，男女都用 un mannequin）；橱窗里的人台。Elle est mannequin = 她是模特（职业不加冠词）。也可说 un mannequin de vitrine。","ipa":"[man.kɛ̃]","ph":"mann 读 [man]（nn 只读一个 n）；quin 读 [kɛ̃]：qu [k]，in [ɛ̃]。两个音节：man-nequin → [man.kɛ̃]。","pi":"nn 只发一个 n；qu 读 [k]；结尾 -in 读鼻化元音；女模特也是阳性 un mannequin。","et":"来自荷兰语 manneken（小人），法语 16 世纪借入。同源：英语 mannequin。","ex":[["Il est grand, beau, et musclé, il peut devenir mannequin.","他又高又帅又健壮，可以当模特。"],["Elle est mannequin à Paris.","她在巴黎做模特。"],["Le mannequin de la vitrine porte une robe rouge.","橱窗里的人台穿着红裙子。"]],"co":[["devenir mannequin","当模特"],["être mannequin","是模特（职业）"],["un mannequin de vitrine","橱窗人台"],["un défilé de mannequins","模特走秀"]],"sy":[["modèle","courant","模特（也指艺术模特、模型）"],["top-modèle","courant","超模"],["figurine","courant","小人像"]],"fq":"中频，谈时尚和工作时常用。","me":"mannequin = manne（人）+ -quin（小）：小人儿。","tr":{"zh":"她十八岁时开始做模特。","fr":"Elle est devenue mannequin à dix-huit ans.","alt":"À dix-huit ans, elle a commencé comme mannequin.","note":"devenir 的过去分词 devenu，助动词用 être：elle est devenue。"}},
 "Un ouistiti": {"pos":"n.m. 阳性名词，复数 ouistitis","s":"绢毛猴；狨猴（南美的小猴子）。口语里 un drôle de ouistiti = 怪人。注意：le ouistiti，前面不省音（不说 l'ouistiti）。","ipa":"[wis.ti.ti]","ph":"oui 读 [wi]（半元音 w + i）；s 读 [s]；ti-ti 读 [ti.ti]。三个音节：ouis-ti-ti。","pi":"oui 读 [wi]，不是 [u.i]；以 oui 开头的词前不省音：le ouistiti，不是 l'ouistiti；s 要发音。","et":"拟声词，模仿这种猴子的叫声；确切来源不完全确定。","ex":[["Le ouistiti est un petit singe.","绢毛猴是一种小猴子。"],["Le ouistiti saute d'arbre en arbre.","绢毛猴在树间跳来跳去。"],["Tu es un drôle de ouistiti, toi !","你真是个怪人！"]],"co":[["un petit ouistiti","一只小绢毛猴"],["un drôle de ouistiti","怪家伙（口语）"],["un ouistiti à pinceaux","白耳狨猴（动物名）"]],"sy":[["singe","courant","猴子（泛指）"],["marmouset","littéraire","小孩、小个子（古）"]],"fq":"低频，动物词汇。","me":"ouis-ti-ti：连说 oui-oui 像小猴叽叽喳喳。","tr":{"zh":"绢毛猴很小，也很爱动。","fr":"Le ouistiti est tout petit et très actif.","alt":"Ce petit singe, le ouistiti, bouge sans arrêt.","note":"le ouistiti：oui- 开头不省音；tout petit 的 tout 在这里是副词，不变形。"}},
 "Un photomaton": {"pos":"n.m. 阳性名词，复数 photomatons","s":"自动照相亭，拍证件照的地方（原为商标名，后成为普通名词）。也说 une cabine photo。faire des photos d'identité dans un photomaton = 在自动照相亭拍证件照。","ipa":"[fo.to.ma.tɔ̃]","ph":"ph 读 [f]；o [o]；to [to]；ma [ma]；ton 读 [tɔ̃]，n 不发音。四个音节：pho-to-ma-ton。","pi":"ph 读 [f]；结尾 -on 是鼻化 [ɔ̃]；与 photocopie（复印）等词一样，photo 的 o 读闭口 [o]。","et":"由 photo + -maton（来自 automate，自动装置）构成的商标词，20 世纪 20 年代出现。","ex":[["Je prends une photo dans le photomaton.","我在照相亭里拍照。"],["Il faut des photos d'identité : allons au photomaton !","需要证件照，我们去照相亭吧！"],["Le photomaton est en panne.","自动照相亭坏了。"]],"co":[["une photo de photomaton","照相亭拍的照片"],["une photo d'identité","证件照"],["une cabine photo","照相亭"],["être en panne","出故障"]],"sy":[["cabine photo","courant","照相亭（中性说法）"],["photographe","courant","摄影师，需要人工拍照"]],"fq":"中低频，办证件时会用到。","me":"photo + maton（automate）：自动拍照的机器。","tr":{"zh":"我需要去自动照相亭拍证件照。","fr":"Je dois aller au photomaton pour mes photos d'identité.","alt":"Je vais faire mes photos d'identité au photomaton.","note":"aller au photomaton：au = à + le；pour + 名词表示目的。"}},
 "Un renard": {"pos":"n.m. 阳性名词，复数 renards；雌狐 une renarde","s":"狐狸。在寓言里代表狡猾：rusé comme un renard。也可比喻狡猾的人：un vieux renard。《狐狸的故事》Le Roman de Renart 里的狐狸叫 Renart，后来这个名字变成了普通名词。","ipa":"[ʁə.naʁ]","ph":"re 弱读 [ʁə]；nard 读 [naʁ]：d 不发音，r 要发出 [ʁ]。两个音节：re-nard。","pi":"结尾 d 不发音，但 r 要发；re 很弱，说快了几乎消失；写法 renard，不是 reynard。","et":"来自中世纪故事集的主角 Renart（日耳曼人名 Raginhard），这个专名取代了旧词 goupil。","ex":[["Le renard est très intelligent.","狐狸很聪明。"],["Dans la fable, le renard flatte le corbeau.","寓言里，狐狸奉承乌鸦。"],["Un renard rôde près du poulailler.","一只狐狸在鸡舍附近转悠。"]],"co":[["rusé comme un renard","像狐狸一样狡猾"],["un vieux renard","老狐狸"],["le renard et le corbeau","狐狸与乌鸦"],["la chasse au renard","猎狐"]],"sy":[["goupil","littéraire","狐（古词，书面）"],["fin / malin","courant","狡猾的、聪明的"]],"fq":"中频，动物和寓言里常见。","me":"renard：「狐狸 renard 和乌鸦 corbeau」，寓言里的老搭档。","tr":{"zh":"那只狐狸晚上来我们花园。","fr":"Le soir, un renard vient dans notre jardin.","alt":"Un renard passe dans notre jardin chaque soir.","note":"le soir：每天晚上；vient 是 venir 的现在时。"}},
 "Un réseau social": {"pos":"n.m. 阳性名词词组，复数 des réseaux sociaux","s":"社交网络；社交媒体（Instagram、TikTok、Facebook 等）。日常常用复数：sur les réseaux sociaux，口语缩成 sur les réseaux。un réseau 本身指网络、网状系统。","ipa":"[ʁe.zo.sɔ.sjal]","ph":"ré [ʁe]；seau 读 [zo]：s 在元音间读 [z]，eau [o]；social 读 [sɔ.sjal]：ci 读 [sj]。","pi":"réseau 里 s 读 [z]；复数两个词都加 x/s：réseaux sociaux；social 的 -ial 读 [jal]，阳性复数变 sociaux。","et":"réseau 来自古法语 resel，拉丁语 reticulum（小网）；social 来自拉丁语 socialis（同伴的）。","ex":[["Instagram est un réseau social.","Instagram 是一个社交网络。"],["Il passe trop de temps sur les réseaux sociaux.","他在社交网络上花太多时间。"],["Ma mère n'aime pas les réseaux sociaux.","我妈妈不喜欢社交媒体。"]],"co":[["sur les réseaux sociaux","在社交网络上"],["un réseau de transport","交通网"],["un réseau wifi","Wi-Fi 网络"],["un réseau d'amis","朋友圈"]],"sy":[["médias sociaux","courant","社交媒体"],["appli","familier","应用程序（口语）"],["réseau","courant","口语缩写：les réseaux"]],"fq":"高频，日常生活常用。","me":"réseau = 小「网」，social = 「社交」：社交的网。","tr":{"zh":"年轻人常常在社交网络上聊天。","fr":"Les jeunes discutent souvent sur les réseaux sociaux.","alt":"Les jeunes passent leur temps sur les réseaux.","note":"sur 搭配 réseaux sociaux；复数 réseaux sociaux 都加 x。"}},
 "Un rictus": {"pos":"n.m. 阳性名词，单复数同形：des rictus","s":"冷笑；怪笑；嘴角抽动的僵硬表情（常含痛苦、嘲讽或恶意）。un rictus de douleur = 痛苦得龇牙咧嘴。它不是友好的微笑，别当 sourire 用。","ipa":"[ʁik.tys]","ph":"ric [ʁik]；tus 读 [tys]：u [y]，结尾 -us 的 s 要发 [s]。","pi":"结尾 -us 的 s 要读出来 [s]，和很多不发音的结尾 s 不同；u 读 [y]；意思是冷笑，不是「微笑」。","et":"来自拉丁语 rictus（张开的嘴），出自动词 ringi（龇牙）。","ex":[["Il a un rictus bizarre.","他有一个古怪的冷笑。"],["Un rictus de douleur apparaît sur son visage.","他脸上露出痛苦的表情。"],["Le méchant sourit avec un rictus cruel.","坏人带着残忍的冷笑。"]],"co":[["un rictus de douleur","痛苦的龇牙咧嘴"],["un rictus cruel","残忍的冷笑"],["avoir un rictus aux lèvres","嘴角带着冷笑"],["un rictus de dégoût","厌恶的表情"]],"sy":[["sourire","courant","微笑（友好）"],["grimace","courant","鬼脸、痛苦表情"],["ricanement","soutenu","讥笑（声音）"]],"fq":"低频，多见于文学和描述。","me":"rictus：嘴巴「咧开」，但不是笑：是冷笑。","tr":{"zh":"他嘴角带着一丝冷笑。","fr":"Il avait un rictus au coin des lèvres.","alt":"Un petit rictus lui tordait la bouche.","note":"au coin des lèvres：在嘴角；avoir 用未完成过去时描写。"}},
 "Un sosie": {"pos":"n.m. 阳性名词，复数 sosies（男女都用 un sosie）","s":"长得几乎一模一样的人；替身；翻版。le sosie de quelqu'un = 某人的翻版。不是双胞胎，而是「碰巧很像的人」。","ipa":"[sɔ.zi]","ph":"so [sɔ]；sie 读 [zi]：s 在元音间读 [z]，ie 读 [i]。两个音节：so-sie。","pi":"第二个 s 读 [z]，不是 [s]；结尾 -ie 读 [i]；后面一般接 de：le sosie de…。","et":"来自 Sosie，古罗马戏剧家普劳图斯和莫里哀《安菲特里翁》里的仆人，神被变成了他的样子。","ex":[["Il est le sosie de mon frère.","他是我哥哥的翻版。"],["Tu as vu ? C'est le sosie de l'acteur !","你看到没？那个人和演员一模一样！"],["Elle a un sosie dans mon bureau.","我办公室里有人和她长得一模一样。"]],"co":[["le sosie de quelqu'un","某人的翻版"],["avoir un sosie","有长得像的人"],["un sosie parfait","几乎一模一样的人"],["un sosie de célébrité","名人替身"]],"sy":[["double","courant","分身、同样的人或物"],["jumeau","courant","双胞胎"],["portrait craché","familier","活脱脱的翻版（人像）"]],"fq":"中低频，日常描述长相时用。","me":"sosie 来自戏剧里的人物 Sosie：他的「替身」把他取代了。","tr":{"zh":"那个男人长得和我的老师一模一样。","fr":"Cet homme est le sosie de mon professeur.","alt":"Cet homme ressemble trait pour trait à mon professeur.","note":"le sosie de + 人；ressembler à + 人（à 不是 de）。"}},
 "Un tobogan": {"pos":"n.m. 阳性名词，复数 toboggans（标准拼写是 toboggan，两个 g）","s":"滑梯（游乐场、游泳池）。标准拼写是 un toboggan，书中的 tobogan 少一个 g。也指雪橇或水上滑道：un toboggan aquatique。","ipa":"[tɔ.bɔ.gɑ̃]","ph":"to [tɔ]；bo [bɔ]；gan 读 [gɑ̃]：g 是硬音 [g]，an [ɑ̃]，n 不发音。三个音节：to-bog-gan。","pi":"g 读硬音 [g]，不是 [ʒ]；结尾 -an 是鼻化元音；标准拼写是 toboggan（gg）。","et":"借自英语 toboggan，源自北美原住民语言，经加拿大法语传入。","ex":[["L'enfant joue sur le tobogan.","孩子在滑梯上玩。"],["Les enfants font la queue pour le toboggan.","孩子们排队等着玩滑梯。"],["À la piscine, il y a un grand toboggan aquatique.","游泳池有一个大型水上滑梯。"]],"co":[["glisser sur le toboggan","从滑梯上滑下来"],["un toboggan aquatique","水上滑梯"],["monter au toboggan","爬上滑梯"],["un toboggan de jardin","花园滑梯"]],"sy":[["glissoire","courant","（加拿大法语）冰上滑道"],["luge","courant","雪橇"]],"fq":"中频，亲子和儿童场景常用。","me":"to-bog-gan：嘴里发「博干」，一路滑下去。","tr":{"zh":"孩子们在滑梯上玩得很开心。","fr":"Les enfants s'amusent beaucoup sur le toboggan.","alt":"Les enfants adorent glisser sur le toboggan.","note":"s'amuser 是代词式动词；sur le toboggan 是「在滑梯上」。"}},
 "Un visage": {"pos":"n.m. 阳性名词，复数 visages","s":"脸；面容。比 la figure（口语）和 le visage 更文雅、更中性。比喻：le vrai visage de… = ……的真面目；un visage connu = 熟悉的面孔。","ipa":"[vi.zaʒ]","ph":"vi [vi]；sage 读 [zaʒ]：s 在元音间读 [z]，g 在 e 前读 [ʒ]，结尾 e 不发音。","pi":"s 读 [z]；g 读 [ʒ]；结尾 e 不发音；别把 visage 说成 [vi.sa.ʒe]。","et":"来自古法语 vis（脸），拉丁语 visus（视觉、外表）加后缀 -age。同源：vis-à-vis、visible。","ex":[["Elle a un beau visage.","她有一张漂亮的脸。"],["Son visage est tout rouge.","他的脸红透了。"],["Je ne connais pas ce visage.","我不认识这张脸。"]],"co":[["un visage souriant","笑脸"],["un visage pâle","苍白的脸"],["le vrai visage de…","……的真面目"],["à visage découvert","不遮脸、公开"]],"sy":[["figure","familier","脸（日常口语）：se laver la figure"],["face","soutenu","面部、正面"],["tête","courant","头"]],"fq":"高频，日常常用。","me":"visage ← vis（看）：被「看见」的那部分。","tr":{"zh":"她的脸上带着微笑。","fr":"Elle a un sourire sur le visage.","alt":"Son visage souriait.","note":"un sourire sur le visage：脸上带着微笑。"}},
 "De la chance": {"pos":"n.f. 阴性名词（部分冠词 de la），复数 chances","s":"运气。avoir de la chance = 运气好；Quelle chance ! = 真幸运！pas de chance = 运气不好；Bonne chance ! = 祝你好运。也指「可能性」：une chance sur deux = 一半的机会。","ipa":"[ʃɑ̃s]","ph":"ch 读 [ʃ]；an 读 [ɑ̃]；ce 读 [s]，e 不发音。单音节：[ʃɑ̃s]。","pi":"avoir de la chance 里用部分冠词，不说 avoir chance；ch 读 [ʃ]；英语 chance 多指机会，法语 chance 主要是「好运」。","et":"来自古法语 cheance，拉丁语 cadentia（落下），指骰子落下的结果；同源：choir、déchéance。","ex":[["J'ai de la chance aujourd'hui.","我今天运气好。"],["Bonne chance pour ton examen !","祝你考试好运！"],["Avec un peu de chance, il fera beau demain.","运气好的话，明天会晴。"]],"co":[["avoir de la chance","运气好"],["Bonne chance !","祝你好运！"],["pas de chance","运气不好"],["avoir une chance de + inf.","有机会做某事"]],"sy":[["bonheur","courant","幸福；有时指好运"],["veine","familier","走运：avoir de la veine"],["bol","familier","好运：avoir du bol"]],"fq":"极高频，日常常用。","me":"chance ← 骰子落下 (cadere)：落下是好点数，就是 chance。","tr":{"zh":"你运气真好，刚赶上末班车！","fr":"Tu as de la chance, tu as eu le dernier bus !","alt":"Quelle chance, tu as attrapé le dernier bus !","note":"avoir de la chance；Quelle chance ! 是感叹句。"}},
 "L'apparence": {"pos":"n.f. 阴性名词，复数 apparences","s":"外表；外貌；表象。en apparence = 表面上；les apparences sont trompeuses = 外表会骗人；sauver les apparences = 保全面子。常和 aspect、allure 对比。","ipa":"[a.pa.ʁɑ̃s]","ph":"a [a]；pa [pa]；rence 读 [ʁɑ̃s]：en [ɑ̃]，c 读 [s]，结尾 e 不发音。l'apparence 读 [la.pa.ʁɑ̃s]。","pi":"拼写有 pp（apparence），但只读一个 [p]；-ence 读 [ɑ̃s]，不是 [ɛnse]；与 apparent 同族。","et":"来自晚期拉丁语 apparentia，源自 apparere（出现）；同族：apparaître、apparemment、apparent。","ex":[["L'apparence est importante.","外表很重要。"],["Les apparences sont trompeuses.","表象会骗人。"],["En apparence, il est calme, mais il est inquiet.","表面上他很平静，其实在担心。"]],"co":[["en apparence","表面上"],["les apparences sont trompeuses","外表会骗人"],["sauver les apparences","保全面子"],["soigner son apparence","注意自己的外表"]],"sy":[["aspect","courant","外观、样子"],["allure","courant","神态、外形"],["réalité","courant","反义：现实、真相"]],"fq":"中高频，日常和书面都常用。","me":"apparence ← apparaître：「出现」在你眼前的样子。","tr":{"zh":"表面上他很高兴，其实不是。","fr":"En apparence, il est content, mais en réalité, non.","alt":"Il a l'air content, mais ce n'est qu'une apparence.","note":"en apparence 对比 en réalité。"}},
 "L'école primaire": {"pos":"n.f. 阴性名词词组，复数 des écoles primaires","s":"小学（法国 6–11 岁，五年：CP 到 CM2）。官方名称是 l'école élémentaire，日常常说 l'école primaire 或 le primaire。在小学教书的老师叫 un professeur des écoles。","ipa":"[e.kɔl.pʁi.mɛʁ]","ph":"école 读 [e.kɔl]（l' 与 école 省音）；primaire 读 [pʁi.mɛʁ]：ai 读 [ɛ]，re 弱化。","pi":"école 开头是 é；l'école 的 l' 与元音省音；primaire 的 ai 读 [ɛ]，不是 [ɛj]。","et":"école 来自拉丁语 schola，源自希腊语 skholê（闲暇、学习）；primaire 来自拉丁语 primarius（第一的）。","ex":[["Mon fils est à l'école primaire.","我儿子上小学。"],["À l'école primaire, les enfants apprennent à lire.","孩子们在小学学阅读。"],["Elle enseigne à l'école primaire depuis dix ans.","她在小学教书已经十年了。"]],"co":[["aller à l'école primaire","上小学"],["un élève de l'école primaire","小学生"],["en primaire","上小学时、在小学阶段"],["l'école maternelle","幼儿园（3–6 岁）"]],"sy":[["école élémentaire","courant","小学（官方名称）"],["primaire","courant","（le primaire）小学阶段"],["collège","courant","下一阶段：初中"]],"fq":"高频，谈学校时必会。","me":"primaire ← premier：第一阶段的学校。","tr":{"zh":"我女儿明年开始上小学。","fr":"Ma fille entre à l'école primaire l'année prochaine.","alt":"L'an prochain, ma fille sera à l'école primaire.","note":"entrer à l'école primaire；l'année prochaine 表示时间。"}},
 "La personnalité": {"pos":"n.f. 阴性名词，复数 personnalités","s":"个性；人格；性格特质。avoir une forte personnalité = 个性很强。另指「名人、要人」：une personnalité politique = 政界要人。双重人格叫 une double personnalité。","ipa":"[pɛʁ.sɔ.na.li.te]","ph":"per [pɛʁ]；so [sɔ]；na [na]；li [li]；té [te]。五个音节，重音在最后。","pi":"只有一个 n：personnalité，两个 n 的是 personne 的变体；per- 读 [pɛʁ]；与 caractère 的区别：personnalité 偏整体印象。","et":"来自 personnel，拉丁语 persona（面具、角色）；同族：personne、personnel、personnage。","ex":[["Elle a une forte personnalité.","她个性很强。"],["Ce chanteur est une personnalité très connue.","这位歌手是个很有名的人物。"],["Les jumeaux ont des personnalités différentes.","这对双胞胎性格不同。"]],"co":[["avoir une forte personnalité","个性很强"],["une personnalité politique","政界要人"],["un trouble de la personnalité","人格障碍"],["manquer de personnalité","缺乏个性"]],"sy":[["caractère","courant","性格、脾气"],["tempérament","soutenu","气质"],["célébrité","courant","名人"]],"fq":"高频，日常和书面都常用。","me":"personne + -alité：一个人的「面具」：他呈现给世界的样子。","tr":{"zh":"她很有个性，不怕说出自己的想法。","fr":"Elle a beaucoup de personnalité, elle n'a pas peur de dire ce qu'elle pense.","alt":"Elle a une forte personnalité et elle dit ce qu'elle pense.","note":"avoir beaucoup de personnalité = avoir une forte personnalité。"}},
 "La physionomie": {"pos":"n.f. 阴性名词，复数 physionomies","s":"面貌；相貌；脸部的特征与表情。多指脸的整体神情：une physionomie sympathique。也可指事物的外观：la physionomie d'une ville。être bon physionomiste = 善于记住人脸。","ipa":"[fi.zjɔ.nɔ.mi]","ph":"phy 读 [fi]；sio 读 [zjɔ]：s 读 [z]；no [nɔ]；mie [mi]。四个音节：phy-sio-no-mie。","pi":"ph 读 [f]；s 读 [z]；sio 要连成 [zjɔ]；不要和 physiologie（生理学）或 physique 混。","et":"来自希腊语 phusiognômonia（physis 自然 + gnômôn 判断者），原指从脸判断性格。同源：英语 physiognomy。","ex":[["Il a une physionomie intéressante.","他的相貌很有意思。"],["La physionomie de la ville a beaucoup changé.","这座城市的面貌变化很大。"],["Je suis mauvais physionomiste : j'oublie tous les visages.","我记不住人脸，看过就忘。"]],"co":[["une physionomie ouverte","神情开朗的脸"],["une physionomie sympathique","让人有好感的相貌"],["la physionomie d'une ville","一座城市的面貌"],["être bon physionomiste","善于认人脸"]],"sy":[["visage","courant","脸（最普通）"],["traits","courant","五官（复数）"],["faciès","soutenu","面相（有时含贬义）"]],"fq":"低频，多见于书面和描写。","me":"physio（自然）+ nomie：从脸的「自然」特征看人。","tr":{"zh":"他有一张让人有好感的脸。","fr":"Il a une physionomie très sympathique.","alt":"Il a un visage qui inspire confiance.","note":"une physionomie sympathique：sympathique 在法语里指「让人喜欢的」。"}},
 "Une cigale": {"pos":"n.f. 阴性名词，复数 cigales","s":"蝉（夏天在南法鸣叫，是普罗旺斯的象征）。La Fontaine 寓言《蝉和蚂蚁》（La Cigale et la Fourmi）中，蝉整个夏天唱歌，冬天没饭吃。","ipa":"[si.gal]","ph":"ci 读 [si]；ga 读 [gal]：g 是硬音 [g]，l 要发出来。两个音节：ci-gale → [si.gal]。","pi":"g 读硬音 [g]，不是 [ʒ]；c 读 [s]；结尾 -e 不发音，l 要读。","et":"来自普罗旺斯语 cigala，源自拉丁语 cicada（蝉）。英语 cicada 也同源。","ex":[["La cigale chante en été.","蝉在夏天鸣叫。"],["En Provence, on entend les cigales l'été.","夏天在普罗旺斯能听到蝉鸣。"],["La cigale n'a rien à manger en hiver.","蝉在冬天没有东西吃。"]],"co":[["le chant des cigales","蝉鸣"],["la cigale et la fourmi","蝉与蚂蚁（寓言）"],["une cigale en Provence","普罗旺斯的蝉"],["chanter comme une cigale","不停歌唱"]],"sy":[["grillon","courant","蟋蟀（也会叫，但不同虫）"],["fourmi","courant","寓言中的反面角色：勤劳的蚂蚁"]],"fq":"中低频，夏天、南法和寓言中常见。","me":"cigale：夏天 si-gal，「西—嘎」地叫。","tr":{"zh":"夏天，蝉在树上叫个不停。","fr":"En été, les cigales chantent sans arrêt dans les arbres.","alt":"L'été, on entend les cigales partout.","note":"en été：在夏天；chanter 规则动词。"}},
 "Une fable": {"pos":"n.f. 阴性名词，复数 fables","s":"寓言（短小的故事，常用动物，末尾有道理 la morale）。la fable de La Fontaine 是法国学生必读。也可指「编造的故事」：C'est une fable = 这是瞎编的。","ipa":"[fabl]","ph":"f [f]；a [a]；ble 读 [bl]，结尾 -e 不发音，l 与 b 连着读。单音节：[fabl]。","pi":"结尾 -ble 读 [bl]，不要加 [ə]；a 读 [a]，不是 [e]；与英语 fable 拼写同，读音不同。","et":"来自拉丁语 fabula（故事），源自 fari（说）。同族：fabuleux、affabuler。","ex":[["Je lis une fable de La Fontaine.","我读一篇拉封丹寓言。"],["Cette fable a une morale simple.","这则寓言的寓意很简单。"],["À l'école, on apprend une fable par cœur.","在学校要背一篇寓言。"]],"co":[["une fable de La Fontaine","拉封丹寓言"],["la morale de la fable","寓言的寓意"],["apprendre une fable par cœur","背诵寓言"],["une fable animalière","动物寓言"]],"sy":[["conte","courant","故事、童话"],["légende","courant","传说"],["apologue","littéraire","寓言（书面）"]],"fq":"中频，文学和学校里常见。","me":"fable ← fabula：讲出来的故事，像「fa-bl」一样简短。","tr":{"zh":"我们今天在课堂上读了一篇寓言。","fr":"Aujourd'hui, nous avons lu une fable en classe.","alt":"On a lu une fable en cours aujourd'hui.","note":"lu 是 lire 的过去分词；en classe = 在课上。"}},
 "Une fée": {"pos":"n.f. 阴性名词，复数 fées","s":"仙女；仙子（童话里有魔法的女性）。le conte de fées = 童话；la fée Clochette = 小叮当；une bonne fée = 善良的仙女。形容词：féerique（如仙境般的）。","ipa":"[fe]","ph":"单音节 [fe]：f [f]，ée 读 [e]，不要拖音。复数 fées 也读 [fe]，s 不发音。","pi":"fée 只有一个音节，不是 [fe.e]；注意阴性词尾 -ée 读 [e]；和 fait [fɛ] 发音不同（é 闭口）。","et":"来自拉丁语 fata（命运女神，复数），经古法语 fae 发展而来。英语 fairy 也出自古法语 faerie。","ex":[["La fée est magique.","仙女有魔法。"],["La fée touche Cendrillon avec sa baguette magique.","仙女用魔杖碰了碰灰姑娘。"],["Ma fille adore les contes de fées.","我女儿喜欢童话。"]],"co":[["un conte de fées","童话"],["une baguette de fée","仙女的魔杖"],["une bonne fée","善良仙女"],["la fée Carabosse","恶仙女（卡拉博斯）"]],"sy":[["sorcière","courant","女巫"],["magicienne","courant","女魔法师"],["elfe","courant","精灵"]],"fq":"中频，童话和儿童读物中常见。","me":"fée [fe]：一声「fe」，魔杖一挥。","tr":{"zh":"仙女用魔法让南瓜变成马车。","fr":"La fée change la citrouille en carrosse avec sa magie.","alt":"Avec sa baguette, la fée transforme la citrouille en carrosse.","note":"changer A en B = 把 A 变成 B。"}},
 "Une fossette (sur le menton, sur les joues)": {"pos":"n.f. 阴性名词，复数 fossettes","s":"酒窝（脸颊或下巴上的小凹陷）。avoir des fossettes = 有酒窝。fossette 是 fosse（坑）的指小形式，意思是「小坑」。","ipa":"[fɔ.sɛt]","ph":"fos 读 [fɔs]：ss 读 [s]，不是 [z]；-ette 读 [ɛt]，t 要发音。两个音节：fos-sette → [fɔ.sɛt]。","pi":"ss 读清音 [s]；-ette 的 t 要发出来（[ɛt]）；fosse 开头的 o 是开口 [ɔ]。","et":"由 fosse（坑，来自拉丁语 fossa）+ 指小后缀 -ette 构成：「小坑」。","ex":[["Il a une fossette sur la joue.","他脸颊上有个酒窝。"],["Quand elle sourit, des fossettes apparaissent.","她一笑就出现酒窝。"],["Le bébé a une petite fossette au menton.","宝宝下巴上有个小酒窝。"]],"co":[["une fossette sur la joue","脸颊上的酒窝"],["une fossette au menton","下巴上的凹窝"],["avoir des fossettes","有酒窝"],["creuser une fossette","挖出酒窝（笑时显现）"]],"sy":[["creux","courant","凹陷"],["fosse","courant","坑（大）"]],"fq":"中低频，描述长相时用。","me":"fossette = fosse（坑）+ -ette（小）：脸上的小坑。","tr":{"zh":"她笑的时候，脸上有两个小酒窝。","fr":"Quand elle sourit, elle a deux petites fossettes sur les joues.","alt":"Son sourire fait apparaître deux fossettes.","note":"quand + 现在时；sur les joues 用复数。"}},
 "Une fourmi": {"pos":"n.f. 阴性名词，复数 fourmis","s":"蚂蚁。象征勤劳。avoir des fourmis dans les jambes = 腿发麻（像有蚂蚁爬），也指坐不住。《蝉和蚂蚁》（La Cigale et la Fourmi）里蚂蚁平时存粮过冬。","ipa":"[fuʁ.mi]","ph":"ou 读 [u]；r 读 [ʁ]；mi 读 [mi]。两个音节：four-mi。","pi":"ou 读 [u]，不是 [o]；r 要发出来；fourmi 和 four（烤箱）开头一样，但意思不同。","et":"来自拉丁语 formica（蚂蚁）。同族：fourmilière（蚁丘）、fourmiller（挤满、乱爬）。","ex":[["La fourmi travaille beaucoup.","蚂蚁很勤劳。"],["J'ai des fourmis dans les jambes.","我的腿发麻了。"],["Une fourmi porte une feuille sur son dos.","一只蚂蚁背着一片叶子。"]],"co":[["une fourmilière","蚁丘、蚁巢"],["avoir des fourmis dans les jambes","腿发麻；坐不住"],["travailleur comme une fourmi","像蚂蚁一样勤劳"],["la cigale et la fourmi","蝉与蚂蚁"]],"sy":[["insecte","courant","昆虫（上位词）"],["cigale","courant","寓言中的对立角色：蝉"]],"fq":"中频，动物词汇必会。","me":"fourmi：\"four-mi\"，一大群围着烤箱「four」的小东西。","tr":{"zh":"桌子上有很多小蚂蚁。","fr":"Il y a beaucoup de petites fourmis sur la table.","alt":"La table est pleine de petites fourmis.","note":"beaucoup de + 名词；petit 在名词前，复数 petites。"}},
 "Une grimace": {"pos":"n.f. 阴性名词，复数 grimaces","s":"鬼脸；做怪相；（痛苦或不满时）皱起的脸。faire une grimace = 做鬼脸（可以是逗人玩）；faire la grimace = 不高兴地皱眉。动词：grimacer。","ipa":"[gʁi.mas]","ph":"gr 读 [gʁ]：g 是硬音 [g]；i [i]；ma [ma]；ce 读 [s]，e 不发音。两个音节：gri-mace。","pi":"g 读 [g]，不是 [ʒ]；结尾 -ce 读 [s]；faire la grimace 不是做鬼脸玩，而是「不乐意」。","et":"可能来自日耳曼语 *grima（面具）；来源有争议。同族：grimacer。","ex":[["L'enfant fait une grimace.","孩子做了个鬼脸。"],["Il fait la grimace quand il mange des légumes.","他一吃蔬菜就皱眉头。"],["Elle a fait une grimace de douleur.","她疼得龇牙咧嘴。"]],"co":[["faire une grimace","做鬼脸"],["faire la grimace","皱眉不高兴"],["une grimace de douleur","痛苦的表情"],["faire des grimaces","扮鬼脸"]],"sy":[["mimique","soutenu","面部表情"],["moue","courant","撅嘴（不高兴）"],["rictus","soutenu","冷笑、僵硬的表情"]],"fq":"中频，日常、亲子常用。","me":"grimace：想象小孩对你扮「gri-mace」。","tr":{"zh":"孩子对着镜子做鬼脸。","fr":"L'enfant fait des grimaces devant le miroir.","alt":"Le petit fait des grimaces dans le miroir.","note":"faire des grimaces 用复数表示「扮各种鬼脸」。"}},
 "Une passion": {"pos":"n.f. 阴性名词，复数 passions","s":"热情；酷爱；激情。avoir la passion de qqch = 酷爱某事；par passion = 出于热爱。La musique est ma passion = 音乐是我的最爱。比 loisir（业余爱好）强烈得多。","ipa":"[pa.sjɔ̃]","ph":"pa [pa]；ssion 读 [sjɔ̃]：ss 读 [s]，io 读 [jɔ̃]，n 不发音。两个音节：pas-sion → [pa.sjɔ̃]。","pi":"ss 读 [s]；-ion 读 [jɔ̃]，不是 [i.ɔn]；意思比「爱好」强烈。","et":"来自拉丁语 passio（受苦），源自 pati（忍受），宗教上指耶稣受难 la Passion。同族：passionné、passionnant。","ex":[["La musique est ma passion.","音乐是我的爱好。"],["Il a une passion pour les voitures anciennes.","他酷爱老爷车。"],["Elle fait ce métier par passion.","她出于热爱做这份工作。"]],"co":[["avoir une passion pour…","对……充满热情"],["par passion","出于热爱"],["vivre sa passion","追求自己的热爱"],["une passion dévorante","炽烈的热情"]],"sy":[["hobby / loisir","courant","爱好（不那么强烈）"],["enthousiasme","courant","热情"],["fièvre","littéraire","狂热"]],"fq":"高频，日常常用。","me":"passion ← pati（受苦）：爱到愿意受累的程度。","tr":{"zh":"我对摄影有一种热情。","fr":"J'ai une vraie passion pour la photographie.","alt":"La photo, c'est ma passion.","note":"avoir une passion pour + 名词。"}},
 "Une qualité": {"pos":"n.f. 阴性名词，复数 qualités","s":"优点；品质；质量。La patience est une qualité = 耐心是优点。反义词 un défaut。de bonne qualité = 质量好；en qualité de = 以……的身份。","ipa":"[ka.li.te]","ph":"qu 读 [k]；a [a]；li [li]；té [te]。三个音节：qua-li-té。","pi":"qu 读 [k]，不读 [kw]；结尾 -té 读 [te]；与英语 quality 拼写接近但读音差别大。","et":"来自拉丁语 qualitas（性质），西塞罗由 qualis（怎样的）造出来。同族：qualifier、qualificatif。","ex":[["La patience est une qualité.","耐心是一种品质。"],["Ce tissu est de très bonne qualité.","这块布料质量很好。"],["Elle a beaucoup de qualités.","她有很多优点。"]],"co":[["les qualités et les défauts","优点和缺点"],["de bonne / mauvaise qualité","质量好 / 差"],["le rapport qualité-prix","性价比"],["en qualité de…","以……的身份"]],"sy":[["atout","courant","优势、长处"],["vertu","soutenu","美德"],["défaut","courant","反义：缺点"]],"fq":"高频，日常和书面都常用。","me":"qualité ↔ défaut：好与坏，一对反义词。","tr":{"zh":"诚实是他最大的优点。","fr":"L'honnêteté est sa plus grande qualité.","alt":"Sa plus grande qualité, c'est l'honnêteté.","note":"sa plus grande qualité：最高级 le/la plus + 形容词。"}},
 "Une queue de cheval": {"pos":"n.f. 阴性名词词组，复数 des queues de cheval","s":"马尾辫（把头发扎在脑后）。字面是「马的尾巴」。se faire une queue de cheval = 扎马尾。注意 faire la queue 是「排队」，queue 本义是尾巴。","ipa":"[kø.də.ʃ(ə).val]","ph":"queue 读 [kø]（ue 不发音）；de 弱读 [də]；cheval 读 [ʃə.val]：ch [ʃ]，e 常弱化。说快了像 [kød.ʃval]。","pi":"queue 读 [kø]，不是 [kjue]；ch 读 [ʃ]；de 与 cheval 之间常不发 e。","et":"queue 来自拉丁语 cauda（尾巴）；cheval 来自拉丁语 caballus（马）。","ex":[["Elle a les cheveux attachés en queue de cheval.","她把头发扎成马尾。"],["Je me fais une queue de cheval pour courir.","我扎个马尾去跑步。"],["Sa queue de cheval est très longue.","她的马尾辫很长。"]],"co":[["se faire une queue de cheval","扎马尾"],["attacher ses cheveux en queue de cheval","把头发扎成马尾"],["une queue de cheval haute / basse","高 / 低马尾"],["faire la queue","排队"]],"sy":[["couette","courant","（小孩的）羊角辫"],["chignon","courant","发髻"],["natte","courant","辫子"]],"fq":"中频，描述发型时常用。","me":"queue de cheval：真的像马尾巴一样甩来甩去。","tr":{"zh":"跑步的时候，她总是扎马尾。","fr":"Quand elle court, elle attache toujours ses cheveux en queue de cheval.","alt":"Pour courir, elle se fait toujours une queue de cheval.","note":"attacher ses cheveux en queue de cheval：en + 形状。"}},
 "Des goûts": {"pos":"n.m.pl. 阳性名词复数（单数 le goût）","s":"喜好；品味；口味。avoir les mêmes goûts = 品味相同；des goûts et des couleurs = 各人所好。单数 un goût 也指味道：le goût du sucre = 糖的味道。","ipa":"[gu]","ph":"g 读硬音 [g]；où 的 û 读 [u]（重音符号不改变读音）；复数 -ts 不发音。des goûts 读 [de.gu]。","pi":"û 读 [u]，和 goût 单数同音；复数的 s 不发音，听不出单复数区别；g 读 [g]。","et":"来自拉丁语 gustus（尝）。同族：goûter（尝；下午茶）、dégoûter、dégoût。","ex":[["Nous avons les mêmes goûts.","我们口味相同。"],["Il a des goûts de luxe.","他的品味很奢侈。"],["Des goûts et des couleurs, on ne discute pas.","各人所好，无须争论。"]],"co":[["avoir les mêmes goûts","品味相同"],["des goûts et des couleurs","各人口味不同"],["avoir bon / mauvais goût","品味好 / 差"],["des goûts musicaux","音乐喜好"]],"sy":[["préférences","courant","偏好"],["penchants","soutenu","倾向"],["saveur","soutenu","滋味"]],"fq":"高频，日常常用。","me":"goûts ← 尝：goûter 一下就知道自己的口味。","tr":{"zh":"我们的品味很不一样。","fr":"Nous n'avons pas du tout les mêmes goûts.","alt":"On n'a pas les mêmes goûts, toi et moi.","note":"avoir les mêmes goûts；否定用 ne… pas du tout。"}},
 "Les canons de beauté": {"pos":"n.m.pl. 阳性名词复数短语（单数 un canon de beauté）","s":"审美标准；美的典范。les canons de beauté changent avec les époques = 审美标准随时代变化。canon = 标准、规范（希腊语 kanôn）。口语里 Elle est canon = 她超美。","ipa":"[ka.nɔ̃.də.bo.te]","ph":"les 读 [le]；ca [ka]；non 读 [nɔ̃]：鼻化元音，n 不发音；de [də]；beauté 读 [bo.te]：eau [o]，té [te]。","pi":"canon 的 on 是鼻化元音 [nɔ̃]；canon 也是「大炮」（常拼 canon 的同形词）；beauté 的 eau 读 [o]。","et":"canon 来自希腊语 kanôn（直尺、标准），经拉丁语 canon 传入。同源：英语 canon。","ex":[["Les canons de beauté changent avec le temps.","审美标准随时间变化。"],["Elle correspond aux canons de beauté actuels.","她符合现在的审美标准。"],["Ce mannequin est un vrai canon de beauté.","这位模特是真正的美人。"]],"co":[["répondre aux canons de beauté","符合审美标准"],["les canons de la mode","时尚标准"],["Elle est canon.","她超美（口语）"],["un canon de beauté","美的典范"]],"sy":[["critères de beauté","courant","审美标准（中性）"],["modèle","courant","范例"],["idéal","soutenu","理想"]],"fq":"中频，谈社会、时尚时用。","me":"canon = 尺子：用来量「美」的那把尺。","tr":{"zh":"审美标准在每个国家都不一样。","fr":"Les canons de beauté sont différents dans chaque pays.","alt":"Chaque pays a ses propres canons de beauté.","note":"chaque + 单数名词；les canons 用复数。"}},
 "Un contrôleur / Une contrôleuse": {"pos":"n. 名词，contrôleur 阳性 / contrôleuse 阴性，复数 contrôleurs / contrôleuses","s":"查票员；检查员。在火车、地铁上查票的人就是 contrôleur。也可指各种检查人员，如 contrôleur aérien（空中交通管制员）。","ipa":"[kɔ̃.tʁo.lœʁ]","ph":"on 读鼻化 [ɔ̃]；ô 读 [o]；eur 读 [œʁ]，阴性 -euse 读 [øz]。","pi":"结尾 -eur 的 r 要轻轻发出；ô 上有长音符，别写成 controleur。阴性是 contrôleuse，不是 contrôleure。","et":"来自 contrôle（核对、检查），再加后缀 -eur 表示做这件事的人。","ex":[["Le contrôleur du train vérifie les tickets.","火车上的查票员检查车票。"],["La contrôleuse est très polie.","这位女查票员很有礼貌。"]],"co":[["un contrôleur de train","火车查票员"],["un contrôleur aérien","空中交通管制员"],["montrer son billet au contrôleur","向查票员出示车票"]],"sy":[["vérificateur","soutenu","核查人员，比较书面"],["inspecteur","courant","检查员、督察"]],"fq":"中频，出行时常见。","me":"contrôle + -eur：「负责检查的人」。","tr":{"zh":"查票员请我给他看车票。","fr":"Le contrôleur me demande mon billet.","alt":"Le contrôleur veut voir mon billet.","note":"demander qqch à qqn：向某人要某物。"}},
 "Un créateur / Une créatrice (de mode)": {"pos":"n. 名词，créateur 阳性 / créatrice 阴性，复数 créateurs / créatrices","s":"创造者；设计师。un créateur de mode 是时装设计师；也可说 un créateur d'entreprise（创业者）。注意阴性是 créatrice，不是 créateuse。","ipa":"[kʁe.a.tœʁ]","ph":"cré [kʁe]；é 和 a 分成两个音节 [e.a]；-eur 读 [œʁ]；阴性 -trice 读 [tʁis]。","pi":"créateur 有 4 个音节，é 和 a 要分开读，不要连成一个音。阴性是 -trice，不是 -euse。","et":"来自拉丁语 creator（创造者），源于 creare（创造）。同族：créer、création、créatif。","ex":[["Elle est créatrice de mode.","她是时装设计师。"],["Ce créateur dessine des robes.","这位设计师设计裙子。"]],"co":[["un créateur de mode","时装设计师"],["une créatrice de bijoux","珠宝设计师"],["un créateur d'entreprise","创业者"]],"sy":[["styliste","courant","造型设计师，更偏服装"],["couturier","soutenu","高级时装设计师"]],"fq":"中频，时尚与工作话题常用。","me":"créer（创造）→ créateur：「创造的人」；阴性换成 -trice。","tr":{"zh":"我姐姐想成为时装设计师。","fr":"Ma sœur veut devenir créatrice de mode.","alt":"Ma sœur rêve d'être créatrice de mode.","note":"表示职业时，通常不加冠词：devenir créatrice。"}},
 "Une mule / Un âne": {"pos":"mule：n.f. 阴性名词，复数 mules；âne：n.m. 阳性名词，复数 ânes","s":"une mule 是骡；un âne 是驴。âne 还可骂人「笨蛋」，如 Quel âne ! 另外 une mule 也指一种后跟敞开的拖鞋。","ipa":"[myl] / [ɑn]","ph":"mule：u 读 [y]（嘴唇圆起），结尾 e 不发音；âne：â 读 [ɑ]，结尾 e 不发音。","pi":"mule 的 u 是 [y]，不是 [u]。âne 以元音开头，un âne 要连读，读成 [œ̃.nɑn]。","et":"mule 来自拉丁语 mula；âne 来自拉丁语 asinus。","ex":[["L'âne est un animal têtu.","驴是一种固执的动物。"],["La mule porte les sacs.","骡子驮着袋子。"],["Tu es têtu comme une mule.","你像骡子一样固执。"]],"co":[["têtu comme une mule","像骡子一样固执"],["un âne gris","一头灰驴"],["monter à dos d'âne","骑驴"]],"sy":[["baudet","familier","驴（口语）"],["cheval","courant","马，不要混淆"]],"fq":"中低频，动物话题和习语里出现。","me":"mule 的 u 要嘟嘴；骡和驴都「固执」。","tr":{"zh":"这头驴不想走路。","fr":"Cet âne ne veut pas marcher.","alt":"L'âne refuse d'avancer.","note":"âne 以元音开头，所以用 cet，不用 ce。"}},
 "Bâiller": {"pos":"v. 动词，第一组（-er 规则动词），助动词 avoir","s":"打哈欠。累了或无聊时用。也有 une porte qui bâille（门微微开着）这种书面比喻用法。","ipa":"[bɑ.je]","ph":"â 读 [ɑ]（嘴张大）；-ill- 读 [j]；结尾 -er 读 [e]。","pi":"â 上有长音符，别写成 bailler。-ill- 读 [j]，不是 [l]。","et":"来源不确定。同族：un bâillement（哈欠）。","ex":[["Je suis fatigué, je bâille.","我累了，打哈欠。"],["Il bâille pendant le cours.","他上课时打哈欠。"]],"co":[["bâiller d'ennui","无聊得打哈欠"],["bâiller à se décrocher la mâchoire","哈欠打得下巴快掉了"],["un bâillement","一个哈欠"]],"sy":[["s'ennuyer","courant","感到无聊，常是打哈欠的原因"]],"fq":"中低频，日常口语。","me":"â 的长音符像张大的嘴，就是哈欠。","tr":{"zh":"他一整晚都在打哈欠。","fr":"Il bâille toute la soirée.","alt":"Il n'arrête pas de bâiller ce soir.","note":"n'arrête pas de + 动词原形：一直在做某事。"}},
 "Compter sur": {"pos":"v. 动词短语，第一组（-er），助动词 avoir；后接 sur + 人或事","s":"指望；依靠；相信某人会做到。compter sur qqn = 靠某人；compter sur qqn pour + 动词原形 = 指望某人去做某事。单独的 compter 还有「数数、算」的意思。","ipa":"[kɔ̃.te syʁ]","ph":"om 读鼻化 [ɔ̃]，p 不发音；结尾 -er 读 [e]；sur 的 u 读 [y]。","pi":"compter 里的 p 不发音（读 [kɔ̃.te]）。sur 的 u 是 [y]，不是 [u]。","et":"来自拉丁语 computare（计算）。同族：le compte、le comptable。","ex":[["Je compte sur toi !","我指望你！"],["Tu peux compter sur moi.","你可以依靠我。"],["On compte sur lui pour le repas.","大家指望他来准备饭菜。"]],"co":[["compter sur qqn","指望某人"],["compter sur qqn pour + inf.","指望某人去做某事"],["On peut compter sur lui.","他靠得住。"],["ne pas compter sur","别指望"]],"sy":[["se fier à","courant","相信、信赖"],["faire confiance à","courant","信任"],["miser sur","soutenu","押注于、寄希望于"]],"fq":"高频，日常常用。","me":"「把你算进我的计划里」，所以就是依靠你。","tr":{"zh":"明天我指望你来帮我。","fr":"Demain, je compte sur toi pour m'aider.","alt":"Demain, je compte sur ton aide.","note":"compter sur qqn pour + 动词原形。"}},
 "Décrire": {"pos":"v. 动词，第三组（不规则），助动词 avoir；过去分词 décrit；nous décrivons","s":"描述；描写；形容。décrire qqn / qqch à qqn = 向某人描述某人或某物。变位与 écrire 相同：je décris, nous décrivons, j'ai décrit。","ipa":"[de.kʁiʁ]","ph":"dé [de]；cri [kʁi]；结尾 -re 读 [ʁ]，e 不发音。","pi":"变位别记成 décrire-ons，正确是 nous décrivons。过去分词是 décrit，t 不发音。","et":"来自拉丁语 describere：de-（向下）+ scribere（写）。同族：écrire、la description。","ex":[["Peux-tu décrire cette personne ?","你能描述这个人吗？"],["Il décrit sa maison à son ami.","他向朋友描述自己的房子。"],["Elle a décrit le voleur à la police.","她向警察描述了小偷。"]],"co":[["décrire qqn / qqch","描述某人 / 某物"],["décrire qqch à qqn","向某人描述某事"],["décrire en détail","详细描述"],["une description","一段描述"]],"sy":[["raconter","courant","讲述（故事），重点在事件"],["dépeindre","littéraire","描绘，文学用语"]],"fq":"高频，学习与日常交流常用。","me":"dé- + crire：和 écrire 一起记，「写下来」就是描述。","tr":{"zh":"请你描述一下你的房间。","fr":"Décris-moi ta chambre, s'il te plaît.","alt":"Tu peux me décrire ta chambre ?","note":"命令式 décris；me 放在动词后：décris-moi。"}},
 "Défiler": {"pos":"v. 动词，第一组（-er），助动词 avoir","s":"走秀；列队行进；（画面、人群）一个接一个经过。défiler dans la rue = 在街上游行；Les images défilent = 画面滚动。","ipa":"[de.fi.le]","ph":"dé [de]；fi [fi]；结尾 -er 读 [e]。","pi":"i 是 [i]，嘴角向两边拉开。别把 défiler 和 filer（飞快溜走）混淆。","et":"由 dé- + filer（排成一列行进）构成，与 file（队列）同族。同族：un défilé、un défilé de mode。","ex":[["Les mannequins défilent sur le podium.","模特在台上走秀。"],["Les soldats défilent dans la rue.","士兵们在街上列队行进。"]],"co":[["défiler sur le podium","在 T 台上走秀"],["un défilé de mode","时装秀"],["faire défiler la page","滚动页面"]],"sy":[["marcher","courant","走路，一般意义"],["parader","courant","炫耀地走、游行"]],"fq":"中频，时尚和新闻里常见。","me":"dé + file：大家排成「一条线」走过去。","tr":{"zh":"孩子们在街上游行。","fr":"Les enfants défilent dans la rue.","alt":"Les enfants font un défilé dans la rue.","note":"défiler 不及物，后面不能直接接宾语（要滚动页面用 faire défiler）。"}},
 "Échanger": {"pos":"v. 动词，第一组（-er），助动词 avoir；nous échangeons","s":"交换；交流。échanger A contre B = 用 A 换 B；échanger des messages = 互发消息；échanger sur un sujet = 交流看法。商店里「换货」也用它。","ipa":"[e.ʃɑ̃.ʒe]","ph":"é [e]；ch [ʃ]；an 读鼻化 [ɑ̃]；g 在 e 前读 [ʒ]。","pi":"nous échangeons 要保留 e，让 g 继续读 [ʒ]。ch 读 [ʃ]，不是 [k]。","et":"由 é-（ex-）+ change 构成，change 来自拉丁语 cambiare。同族：changer、un échange。","ex":[["Nous échangeons nos numéros de téléphone.","我们交换电话号码。"],["Je voudrais échanger ce pull.","我想换这件毛衣。"]],"co":[["échanger A contre B","用 A 换 B"],["échanger des idées","交流想法"],["échanger un regard","互相看一眼"]],"sy":[["changer","courant","更换、改变，范围更广"],["troquer","soutenu","以物易物"]],"fq":"高频，日常常用。","me":"é + change：从「你手里」换到「我手里」。","tr":{"zh":"我们可以交换座位吗？","fr":"On peut échanger nos places ?","alt":"Vous voulez qu'on échange nos places ?","note":"on 在口语里常代替 nous；échanger 直接带宾语。"}},
 "Être attiré par": {"pos":"v. 动词短语：être + 过去分词 attiré(e)(s) + par；attiré 随主语变阴阳性、单复数","s":"被……吸引。可指被人或事物吸引，如 être attiré par la musique。动词原形 attirer = 吸引。这里要用 par，不用 à。","ipa":"[ɛtʁ a.ti.ʁe paʁ]","ph":"être [ɛtʁ]；attiré [a.ti.ʁe]，tt 只读一个 [t]；par [paʁ]。","pi":"attiré 的 tt 只发一个 [t]。主语是女性时要写 attirée，发音不变。","et":"attirer 由 à + tirer（拉）构成，所以是「拉过来」。同族：attirant、l'attraction（吸引力）。","ex":[["Il est attiré par la musique classique.","他被古典音乐吸引。"],["Elle est attirée par les voyages.","她对旅行很着迷。"]],"co":[["être attiré(e) par qqch","被某物吸引"],["être attiré(e) par qqn","被某人吸引"],["attirer l'attention","引起注意"]],"sy":[["être séduit par","courant","被……打动、迷住"],["s'intéresser à","courant","对……感兴趣"]],"fq":"中频，描述兴趣与感情时常用。","me":"attirer = à + tirer：被「拉」向它。","tr":{"zh":"我被这座城市吸引。","fr":"Je suis attiré par cette ville.","alt":"Cette ville m'attire beaucoup.","note":"女性说 je suis attirée。"}},
 "Forger": {"pos":"v. 动词，第一组（-er），助动词 avoir；nous forgeons","s":"锻造（金属）；也可比喻为「铸就、培养」，如 forger son caractère（磨炼性格）、forger un mot（造一个词）。","ipa":"[fɔʁ.ʒe]","ph":"for [fɔʁ]；g 在 e 前读 [ʒ]；结尾 -er 读 [e]。","pi":"nous forgeons 要保留 e，才能让 g 继续读 [ʒ]。for 里的 o 是开口 [ɔ]。别和 forcer（强迫）混淆。","et":"来自拉丁语 fabricare，经古法语 forgier。同族：la forge（铁匠铺）、le forgeron（铁匠）。","ex":[["Le forgeron forge le métal.","铁匠锻造金属。"],["Elle se forge un avenir.","她为自己铸造未来。"]],"co":[["forger un outil","打造一件工具"],["se forger un caractère","磨炼出性格"],["forger des liens","建立联系"]],"sy":[["fabriquer","courant","制造，范围更广"],["façonner","soutenu","塑造"]],"fq":"中低频，多见于书面和比喻。","me":"forge（铁匠铺）→ forger：在火里「打铁」。","tr":{"zh":"铁匠正在打一把刀。","fr":"Le forgeron forge un couteau.","alt":"Le forgeron est en train de forger un couteau.","note":"forge 与 forger 是同一个词根。"}},
 "Nécessiter": {"pos":"v. 动词，第一组（-er），助动词 avoir；主要用第三人称","s":"需要；要求（事物才会「需要」某物）。主语多是事物，如 Ce travail nécessite du temps。比 avoir besoin de 更书面，主语通常不是人。","ipa":"[ne.se.si.te]","ph":"né [ne]；cé 中的 c 读 [s]；ssi 读 [si]；结尾 -er 读 [e]。","pi":"拼写 nécessiter 里有 c 和 ss，记住「一个 c，两个 s」。主语是人时用 avoir besoin de，不用 nécessiter。","et":"来自 nécessité（必要），源于拉丁语 necessitas。同族：nécessaire、la nécessité。","ex":[["Ce travail nécessite beaucoup de temps.","这项工作需要很多时间。"],["Cette opération nécessite du calme.","这项操作需要冷静。"]],"co":[["nécessiter du temps","需要时间"],["nécessiter de l'attention","需要专注"],["si nécessaire","如有必要"]],"sy":[["demander","courant","需要，更口语"],["exiger","soutenu","要求，语气更强"],["avoir besoin de","courant","需要，主语是人"]],"fq":"中频，书面和正式场合常用。","me":"nécessiter 里有「necessity」：事物自己说「我需要」。","tr":{"zh":"这个项目需要很多钱。","fr":"Ce projet nécessite beaucoup d'argent.","alt":"Ce projet demande beaucoup d'argent.","note":"口语里常用 demander 代替 nécessiter。"}},
 "Rigoler": {"pos":"v. 动词，第一组（-er），助动词 avoir","s":"笑；开玩笑；玩乐。口语词，比 rire 随意。rigoler 也可以是「开玩笑」：Je ne rigole pas = 我不是开玩笑。","ipa":"[ʁi.ɡɔ.le]","ph":"ri [ʁi]；g 在 o 前读 [ɡ]；go [ɡɔ]；结尾 -er 读 [e]。","pi":"法语 r 是喉音 [ʁ]，别发成中文的 l 或 r。g 在 o 前读硬音 [ɡ]，不是 [ʒ]。","et":"来源不确定，与 rire（笑）意思相近。同族：la rigolade、rigolo（好笑的）。","ex":[["Nous rigolons beaucoup avec lui.","我们和他一起笑得很开心。"],["Tu rigoles ? C'est vrai ?","你在开玩笑吗？是真的吗？"],["Ils ont bien rigolé hier soir.","他们昨晚玩得很开心。"]],"co":[["rigoler de qqch","笑话某事"],["Tu rigoles !","你开玩笑吧！"],["pour rigoler","闹着玩"]],"sy":[["rire","courant","笑，通用"],["plaisanter","courant","开玩笑"],["se marrer","familier","笑得开心，更俚俗"]],"fq":"高频，口语常用。","me":"rigoler 听起来像「笑得咯咯响」，比 rire 随意。","tr":{"zh":"我们笑了一整晚。","fr":"On a rigolé toute la soirée.","alt":"Nous avons ri toute la soirée.","note":"rigoler 偏口语，正式场合用 rire。"}},
 "Se cacher": {"pos":"v. 代词式动词，第一组（-er），复合时态助动词 être；je me cache, tu te caches","s":"躲藏；藏起来。se cacher de qqn = 躲着某人；se cacher de qqn pour faire = 背着某人做某事。及物形式 cacher qqch = 藏起某物。","ipa":"[sə ka.ʃe]","ph":"se [sə]；ca [ka]；ch [ʃ]；结尾 -er 读 [e]。","pi":"ch 读 [ʃ]，像中文「吸」的音，不是 [tʃ]。复合过去时用 être：il s'est caché。","et":"se（自己）+ cacher（藏）；来源不必深究。同族：une cachette（藏身处）、cache-cache（捉迷藏）。","ex":[["Le chat se cache sous le lit.","猫躲在床下。"],["Les enfants se cachent dans le jardin.","孩子们躲在花园里。"],["Il se cache de ses parents.","他躲着父母。"]],"co":[["se cacher derrière / sous","躲在……后面 / 下面"],["se cacher de qqn","躲着某人"],["jouer à cache-cache","玩捉迷藏"]],"sy":[["se dissimuler","soutenu","隐藏自己，更书面"],["se planquer","familier","躲起来，口语"]],"fq":"中频，日常常用。","me":"cache + -ette：cachette 就是躲藏的小地方。","tr":{"zh":"孩子们躲在门后。","fr":"Les enfants se cachent derrière la porte.","alt":"Les enfants sont cachés derrière la porte.","note":"se cacher 里 se 随主语变：je me cache。"}},
 "Se sentir": {"pos":"v. 代词式动词，第三组（不规则），助动词 être；je me sens, nous nous sentons","s":"感觉（自己的状态）。后接形容词或副词：Je me sens bien / fatigué。注意 se sentir 说「自己感到」，sentir 才是「闻」或「感觉到某物」。","ipa":"[sə sɑ̃.tiʁ]","ph":"sen 读鼻化 [sɑ̃]，n 不单独发；ti [ti]；结尾 -ir 读 [iʁ]。","pi":"je me sens 里的 sens，结尾 s 不发音，读 [sɑ̃]。不要说成 je sens bien，那是「我闻起来很好」。","et":"来自拉丁语 sentire（感觉）。同族：le sentiment、le sens、sentir。","ex":[["Je me sens bien aujourd'hui.","我今天感觉很好。"],["Elle se sent un peu fatiguée.","她感觉有点累。"],["Tu te sens mieux ?","你感觉好点了吗？"]],"co":[["se sentir bien / mal","感觉良好 / 不舒服"],["se sentir chez soi","有宾至如归的感觉"],["se sentir fatigué(e)","感觉累"],["se sentir mieux","感觉好些"]],"sy":[["ressentir","soutenu","感受到某种情绪"],["aller","courant","状况如何，如 Comment ça va ?"]],"fq":"极高频，日常常用。","me":"se sentir = 感觉「自己」：me / te / se 都指向自己。","tr":{"zh":"今天我感觉很好。","fr":"Aujourd'hui, je me sens très bien.","alt":"Aujourd'hui, ça va super bien.","note":"se sentir + 形容词或副词（bien / mal / mieux）。"}},
 "Amusant(e)": {"pos":"adj. 形容词，阳性 amusant，阴性 amusante，复数 amusants / amusantes","s":"有趣的；好玩的。形容让人开心或发笑的人、事、游戏。比 drôle（滑稽，让人笑）更偏「好玩」。","ipa":"[a.my.zɑ̃]","ph":"a [a]；mu [my]，嘴唇圆起；s 在元音间读 [z]；-ant 读 [ɑ̃]。阴性 amusante 读 [a.my.zɑ̃t]。","pi":"mu 的 u 读 [y]，不是 [u]。s 读 [z]，不是 [s]。阴性的 t 要读出来。","et":"由 amuser（使开心）+ -ant 构成。同族：un amusement、s'amuser（玩得开心）。","ex":[["Ce jeu est très amusant.","这个游戏很有趣。"],["Elle est amusante, cette fille.","这个女孩很有意思。"]],"co":[["très amusant","非常有趣"],["une histoire amusante","一个有趣的故事"],["Ce n'est pas amusant.","这一点也不好玩。"]],"sy":[["drôle","courant","好笑、滑稽"],["marrant","familier","好玩、好笑，更口语"],["divertissant","soutenu","令人愉快的消遣"]],"fq":"高频，日常常用。","me":"amuser + -ant：让人开心的东西。","tr":{"zh":"这部电影很有趣。","fr":"Ce film est vraiment amusant.","alt":"Ce film est super marrant.","note":"阴性加 e：une histoire amusante。"}},
 "Atypique": {"pos":"adj. 形容词，阴阳性同形，复数 atypiques","s":"不典型的；不寻常的；别具一格的。法语里常是褒义或中性，如 un parcours atypique（与众不同的经历）。","ipa":"[a.ti.pik]","ph":"a [a]；ty [ti]（y 读 [i]）；pique [pik]，结尾 e 不发音。","pi":"ty 中的 y 读 [i]，不是 [y]。qu 读 [k]。","et":"来自希腊语：a-（否定）+ typique（典型的，来自 typos「印记、类型」）。同族：le type、typique。","ex":[["C'est une maison atypique.","这是一栋特别的房子。"],["Il a un parcours atypique.","他的经历很特别。"]],"co":[["un profil atypique","非典型的背景"],["un parcours atypique","与众不同的经历"],["un lieu atypique","别具一格的地方"]],"sy":[["original","courant","独特的"],["inhabituel","courant","不寻常的"],["singulier","soutenu","奇特的"]],"fq":"中频，多见于描述人和地方。","me":"a- + typique：「不典型」，a- 表示否定。","tr":{"zh":"他的职业很特别。","fr":"Son métier est atypique.","alt":"Il fait un métier pas banal.","note":"atypique 阴阳性同形，不用加 e。"}},
 "Chaleureux / Chaleureuse": {"pos":"adj. 形容词，阳性 chaleureux，阴性 chaleureuse，复数 chaleureux / chaleureuses","s":"热情的；温馨的。形容人亲切友好，也形容地方让人感到温暖舒适，如 un accueil chaleureux（热情的接待）。不是指天气热。","ipa":"[ʃa.lø.ʁø]","ph":"ch [ʃ]；eu 读 [ø]；结尾 x 不发音；阴性 chaleureuse 读 [ʃa.lø.ʁøz]。","pi":"不是「天气热」，天气热用 chaud。阳性复数不变，仍是 chaleureux，结尾 x 不读。","et":"由 chaleur（热）+ -eux 构成，chaleur 来自拉丁语 calor。同族：chaud、chaleureusement。","ex":[["Ce restaurant est chaleureux.","这家餐厅很温馨。"],["Elle m'a fait un accueil chaleureux.","她热情地接待了我。"]],"co":[["un accueil chaleureux","热情的接待"],["une ambiance chaleureuse","温馨的氛围"],["chaleureusement","热情地（副词）"]],"sy":[["accueillant","courant","好客的"],["cordial","soutenu","诚恳亲切的"],["froid","courant","冷淡的，反义"]],"fq":"中频，描述人与场所常用。","me":"chaleur（热）→ 人心里的「暖」。","tr":{"zh":"他们对我们很热情。","fr":"Ils sont très chaleureux avec nous.","alt":"Ils nous ont super bien accueillis.","note":"chaleureux 阳性复数不变。"}},
 "Compétent(e)": {"pos":"adj. 形容词，阳性 compétent，阴性 compétente，复数 compétents / compétentes","s":"有能力的；称职的；内行的。形容在专业上靠得住的人，如 un médecin compétent。反义词是 incompétent。","ipa":"[kɔ̃.pe.tɑ̃]","ph":"com 读鼻化 [kɔ̃]；pé [pe]；tent 读鼻化 [tɑ̃]，阴性 compétente 读 [kɔ̃.pe.tɑ̃t]。","pi":"拼写别丢 é：compétent。结尾的 -ent 读 [ɑ̃]，不是 [ɛnt]，t 不发音。","et":"来自拉丁语 competens（合适的）。同族：la compétence。","ex":[["C'est un médecin compétent.","他是一位能干的医生。"],["Elle est très compétente en informatique.","她在电脑方面很在行。"]],"co":[["être compétent en / dans","在……方面有能力"],["une équipe compétente","称职的团队"],["incompétent","不称职的"]],"sy":[["capable","courant","有能力的，更通用"],["doué","courant","有天赋的"],["calé","familier","懂行的、学得好"]],"fq":"中频，工作场合常用。","me":"和英语 competent 几乎一样，注意 é。","tr":{"zh":"我们的老师很称职。","fr":"Notre professeur est très compétent.","alt":"Notre prof, il est vraiment très bon.","note":"compétent 阴性加 e：compétente。"}},
 "Costaud": {"pos":"adj. 形容词（口语），阳性 costaud，阴性 costaude，复数 costauds；也可作名词 un costaud","s":"壮实的；结实的；有力的。多形容身体强壮的人，也可形容物品耐用，如 un tissu costaud。口语词。","ipa":"[kɔs.to]","ph":"cos [kɔs]；taud 读 [to]，au 是 [o]，结尾 d 不发音。阴性 costaude 读 [kɔs.tod]。","pi":"阳性结尾 -aud 的 d 不发音。阴性 costaude 的 d 才读出来。","et":"来源不确定，口语词。","ex":[["Mon frère est très costaud.","我哥哥很壮。"],["Ce sac est costaud.","这个包很结实。"]],"co":[["un gars costaud","一个壮汉"],["être costaud en maths","数学很强"],["un matériau costaud","耐用的材料"]],"sy":[["fort","courant","强壮的，通用"],["robuste","soutenu","结实、强健"],["baraqué","familier","身材魁梧的"]],"fq":"中频，口语常用。","me":"读起来「扣斯拖」，听着就很结实。","tr":{"zh":"他很壮，能搬很重的东西。","fr":"Il est costaud, il peut porter des choses lourdes.","alt":"Il est costaud, il porte tout !","note":"costaud 是口语，写作可换 fort。"}},
 "Dégarni(e)": {"pos":"adj. 形容词，阳性 dégarni，阴性 dégarnie，复数 dégarnis / dégarnies","s":"指头发稀疏的，尤其是前额或头顶。常说 un front dégarni（发际线后退的额头）或 avoir le crâne dégarni。也可指货架、房间「空了」。","ipa":"[de.ɡaʁ.ni]","ph":"dé [de]；ga 中 g 在 a 前读 [ɡ]；ni [ni]。","pi":"ga 读 [ɡa]，不要读成 [ʒa]。阴性 dégarnie 读音和阳性相同。","et":"由 dé- + garni 构成（dé- 表示去掉，garnir 表示配备、装饰）。同族：garnir、la garniture。","ex":[["Il est dégarni du front.","他前额的头发稀疏了。"],["Il a le crâne dégarni.","他头顶的头发很稀少。"]],"co":[["un front dégarni","发际线后退的额头"],["un crâne dégarni","头发稀疏的头顶"],["des rayons dégarnis","空荡荡的货架"]],"sy":[["chauve","courant","秃头的，更彻底"],["clairsemé","soutenu","稀疏的"]],"fq":"中低频，描述外貌时用。","me":"dé + garni：头发这块「装饰」被拿掉了。","tr":{"zh":"我爸爸头发有点稀疏。","fr":"Mon père est un peu dégarni.","alt":"Mon père perd ses cheveux.","note":"dégarni 比 chauve 委婉。"}},
 "Déguisé(e)": {"pos":"adj. 形容词（déguiser 的过去分词），阳性 déguisé，阴性 déguisée，复数 déguisés / déguisées","s":"化装的；乔装的。常说 déguisé en + 名词：扮成……，如 déguisé en pirate。孩子过节或派对上常用。","ipa":"[de.ɡi.ze]","ph":"dé [de]；gui 中 u 不发音，读 [ɡi]；s 在元音间读 [z]；é [e]。","pi":"gui 里的 u 不发音，读 [ɡi]。s 读 [z]，不是 [s]。后面接 en，不接 comme。","et":"由 dé- + guise（样子、方式）构成。同族：se déguiser、un déguisement（化装服）。","ex":[["Il est déguisé en pirate.","他扮成海盗。"],["Les enfants sont déguisés pour la fête.","孩子们为聚会化了装。"]],"co":[["déguisé en + nom","扮成……"],["une fête déguisée","化装舞会"],["un déguisement","化装服；扮装"]],"sy":[["costumé","courant","穿着戏服的"],["travesti","soutenu","乔装改扮的"]],"fq":"中频，节日、派对时常用。","me":"dé + guise：把「本来的样子」换掉。","tr":{"zh":"我女儿扮成了公主。","fr":"Ma fille est déguisée en princesse.","alt":"Ma fille s'est déguisée en princesse.","note":"déguisé en + 名词，en 后不加冠词。"}},
 "Détendu(e)": {"pos":"adj. 形容词（détendre 的过去分词），阳性 détendu，阴性 détendue，复数 détendus / détendues","s":"放松的；松弛的；气氛轻松的。形容人心情放松，也形容气氛轻松，如 une ambiance détendue。反义词 tendu（紧张的）。","ipa":"[de.tɑ̃.dy]","ph":"dé [de]；ten 读鼻化 [tɑ̃]；du [dy]，u 嘴唇圆起。","pi":"ten 读 [tɑ̃]，不是 [tɛn]。结尾 u 读 [y]。别把 détendu 和 attendu（等待的）搞混。","et":"来自动词 détendre：dé-（去除）+ tendre（拉紧）。反义词 tendu。","ex":[["Je suis détendu pendant les vacances.","度假时我很放松。"],["L'ambiance est détendue.","气氛很轻松。"]],"co":[["être détendu(e)","放松"],["une ambiance détendue","轻松的气氛"],["se détendre","放松自己"]],"sy":[["relax","familier","轻松随意的"],["calme","courant","平静的"],["tendu","courant","紧张的，反义"]],"fq":"高频，日常常用。","me":"tendu（绷紧）→ dé-tendu（放松）。","tr":{"zh":"周末我总是很放松。","fr":"Le week-end, je suis toujours détendu.","alt":"Le week-end, je suis relax.","note":"女性写 détendue，读音不变。"}},
 "Discipliné(e)": {"pos":"adj. 形容词，阳性 discipliné，阴性 disciplinée，复数 disciplinés / disciplinées","s":"守纪律的；自律的；听话的。可形容人，也可形容宠物或学生，如 un chien discipliné。反义词是 indiscipliné。","ipa":"[di.si.pli.ne]","ph":"di [di]；sci 中 sc 读 [s]，ci [si]；pli [pli]；né [ne]。","pi":"sci 里的 sc 读 [s]，不是 [sk]。四个音节，每个都清楚读出。","et":"来自 discipline（纪律），源于拉丁语 disciplina（教导）；加 -é 成形容词。","ex":[["Ce chien est très discipliné.","这只狗很听话。"],["Elle est disciplinée, elle étudie chaque jour.","她很自律，每天学习。"]],"co":[["un élève discipliné","守纪律的学生"],["un sportif discipliné","自律的运动员"],["indiscipliné","不守纪律的"]],"sy":[["obéissant","courant","听话的"],["sérieux","courant","认真的"],["rigoureux","soutenu","严谨的"]],"fq":"中频，描述性格时用。","me":"discipline + -é：身上有「纪律」。","tr":{"zh":"我的学生都很守纪律。","fr":"Mes élèves sont très disciplinés.","alt":"Mes élèves sont sages et disciplinés.","note":"复数加 s：disciplinés。"}},
 "Discret / Discrète": {"pos":"adj. 形容词，阳性 discret，阴性 discrète，复数 discrets / discrètes","s":"谨慎的；低调的；不引人注意的。形容人不多话、不爱出风头，也形容守口如瓶；也可形容服饰、颜色素雅。","ipa":"[dis.kʁɛ]","ph":"dis [dis]；cret 读 [kʁɛ]，结尾 t 不发音；阴性 discrète 读 [dis.kʁɛt]。","pi":"阳性结尾 t 不发音，阴性 discrète 才读 [t]，并且 è 带重音符。","et":"来自拉丁语 discretus（分开的，有分寸的）。同族：la discrétion、discrètement。","ex":[["Elle est très discrète au travail.","她在工作中很低调。"],["Il est discret, il ne dit rien.","他很谨慎，什么都不说。"]],"co":[["être discret / discrète","低调；守口如瓶"],["un bijou discret","低调的首饰"],["discrètement","悄悄地"]],"sy":[["réservé","courant","内敛的"],["effacé","soutenu","不引人注意的"],["bavard","courant","多话的，反义"]],"fq":"中频，描述性格时常用。","me":"discret = 不吵闹的人，阴性多了 -te 的发音。","tr":{"zh":"他是个很低调的人。","fr":"C'est quelqu'un de très discret.","alt":"Il est du genre discret.","note":"quelqu'un de + 形容词（阳性）。"}},
 "Efficace": {"pos":"adj. 形容词，阴阳性同形，复数 efficaces","s":"有效的；高效的。可形容人（做事有效率）、方法、药物、机器，如 un médicament efficace。","ipa":"[e.fi.kas]","ph":"é 读 [e]；ff 只读一个 [f]；ca 读 [ka]（c 在 a 前读 [k]）；ce 读 [s]，结尾 e 不发音。","pi":"efficace 中间的 c 读 [k]，结尾的 c 读 [s]，两个 c 发音不同。ff 要写双 f。","et":"来自拉丁语 efficax（有效的），源于 efficere（完成）。同族：l'efficacité。","ex":[["Cette machine est efficace.","这台机器很高效。"],["Ce médicament est très efficace.","这种药很有效。"]],"co":[["un moyen efficace","有效的办法"],["très efficace","很有效"],["l'efficacité","效率；效果"]],"sy":[["performant","courant","性能好的"],["utile","courant","有用的"],["inefficace","courant","无效的，反义"]],"fq":"高频，工作和生活都常用。","me":"effic- 的 ff 要写双；读起来像「埃-fi-卡斯」。","tr":{"zh":"这个方法很有效。","fr":"Cette méthode est très efficace.","alt":"Cette méthode marche vraiment bien.","note":"efficace 阴阳性同形。"}},
 "Ennuyeux / Ennuyeuse": {"pos":"adj. 形容词，阳性 ennuyeux，阴性 ennuyeuse，复数 ennuyeux / ennuyeuses","s":"无聊的；烦人的。可形容电影、课程等让人觉得乏味，也可形容人讨厌、烦。有时也指「麻烦的」：C'est ennuyeux = 这很麻烦。","ipa":"[ɑ̃.nɥi.jø]","ph":"en 读鼻化 [ɑ̃]；nu 在这里读 [nɥi]（u 和 y 连成一个半元音）；yeux 读 [jø]；阴性 ennuyeuse 读 [ɑ̃.nɥi.jøz]。","pi":"ennuyeux 的拼写难：双 n、uy。结尾 x 不发音。","et":"来自动词 ennuyer，源于俗拉丁语 inodiare（「令人厌烦」，来自 in odio）。同族：l'ennui（无聊）、s'ennuyer。","ex":[["Ce film est ennuyeux.","这部电影很无聊。"],["Ce cours est vraiment ennuyeux.","这门课真无聊。"],["C'est ennuyeux, j'ai perdu mes clés.","真麻烦，我把钥匙丢了。"]],"co":[["un film ennuyeux","一部无聊的电影"],["C'est ennuyeux !","真麻烦！"],["s'ennuyer","感到无聊"]],"sy":[["barbant","familier","烦人的，枯燥的"],["lassant","courant","令人厌倦的"],["passionnant","courant","引人入胜的，反义"]],"fq":"高频，日常常用。","me":"ennui（无聊）+ -eux：充满无聊的。","tr":{"zh":"这本书太无聊了。","fr":"Ce livre est trop ennuyeux.","alt":"Ce livre est vraiment barbant.","note":"ennuyeux 阳性复数不变。"}},
 "Extraverti(e)": {"pos":"adj. 形容词，阳性 extraverti，阴性 extravertie，复数 extravertis / extraverties","s":"外向的。形容爱交际、爱说话的性格。也写作 extroverti(e)。反义词是 introverti(e)（内向的）。","ipa":"[ɛk.stʁa.vɛʁ.ti]","ph":"ex 读 [ɛks]；tra 读 [tʁa]；ver 读 [vɛʁ]；ti 读 [ti]。","pi":"ex 读 [ɛks]，不是 [ɛɡz]。ver 里的 r 要发出来。","et":"由 extra-（外）+ verti（来自拉丁语 vertere，转向）构成；词由 20 世纪心理学传入。同族：introverti。","ex":[["Elle parle beaucoup, elle est extravertie.","她话很多，很外向。"],["Mon frère est très extraverti.","我弟弟非常外向。"]],"co":[["un caractère extraverti","外向的性格"],["extraverti ou introverti","外向还是内向"],["très extraverti(e)","非常外向"]],"sy":[["sociable","courant","好交际的"],["expansif","soutenu","热情奔放的"],["introverti","courant","内向的，反义"]],"fq":"中频，谈性格时用。","me":"extra-（向外）+ verti（转）：朝外转的人。","tr":{"zh":"她很外向，朋友很多。","fr":"Elle est extravertie, elle a beaucoup d'amis.","alt":"Elle est très sociable, elle a plein d'amis.","note":"阴性加 e：extravertie。"}},
 "Fainéant(e)": {"pos":"adj. 形容词，也可作名词，阳性 fainéant，阴性 fainéante，复数 fainéants / fainéantes","s":"懒惰的；游手好闲的。也可作名词：un fainéant（懒汉）。语气比较重，带贬义。","ipa":"[fɛ.ne.ɑ̃]","ph":"fai 读 [fɛ]；né 读 [ne]；ant 读 [ɑ̃]，结尾 t 不发音；阴性 fainéante 读 [fɛ.ne.ɑ̃t]。","pi":"常被误认为 fait néant（什么也不做）。写法是 fainéant。éa 要分开读 [e.ɑ̃]。","et":"来自古法语 faignant（装样子），源于 feindre；后被民间误解为 fait néant，所以拼写变了。","ex":[["Il ne veut pas travailler, il est fainéant.","他不想工作，很懒。"],["Quel fainéant !","真是个懒汉！"]],"co":[["un fainéant","懒汉"],["être fainéant(e)","很懒"],["la fainéantise","懒惰"]],"sy":[["paresseux","courant","懒的，较中性"],["flemmard","familier","懒鬼，口语"],["travailleur","courant","勤劳的，反义"]],"fq":"中频，带责备语气。","me":"民间说法 fait néant：「什么也不做」，好记但不是真来源。","tr":{"zh":"他太懒了，什么都不做。","fr":"Il est trop fainéant, il ne fait rien.","alt":"Il est flemmard, il ne fait rien.","note":"fainéant 比 paresseux 更贬义。"}},
 "Grossier / Grossière": {"pos":"adj. 形容词，阳性 grossier，阴性 grossière，复数 grossiers / grossières","s":"粗鲁的；粗俗的；粗糙的。形容人没礼貌或话粗俗，如 un mot grossier（脏话）。也指做工粗糙，如 une erreur grossière（明显的错误）。","ipa":"[ɡʁo.sje]","ph":"gros 读 [ɡʁo]，ss 读 [s]，与 -ier 连成 [sje]；阴性 grossière 读 [ɡʁo.sjɛʁ]。","pi":"grossier 里的 ss 读 [s]，不是 [z]。别和 gros（大的，胖的）混淆，语义不同。","et":"由 gros + -ier 构成，gros 来自拉丁语 grossus（粗、厚）。同族：la grossièreté（粗鲁）。","ex":[["Ce mot est grossier.","这个词很粗俗。"],["Il est grossier avec la vendeuse.","他对女售货员很粗鲁。"]],"co":[["un mot grossier","脏话"],["être grossier avec qqn","对某人粗鲁"],["une erreur grossière","明显的错误"]],"sy":[["impoli","courant","没礼貌的"],["vulgaire","courant","粗俗的"],["poli","courant","有礼貌的，反义"]],"fq":"中频，常用于评价言行。","me":"gros（大）+ -ier：粗大、粗糙，所以粗鲁。","tr":{"zh":"别对老师那么粗鲁。","fr":"Ne sois pas grossier avec le professeur.","alt":"Ne parle pas comme ça au prof, c'est grossier.","note":"avec qqn 表示对某人的态度。"}},
 "Indécis(e)": {"pos":"adj. 形容词，阳性 indécis，阴性 indécise，复数 indécis / indécises","s":"犹豫不决的；拿不定主意的。形容人下不了决心，也可形容结果、形势不明朗，如 un résultat indécis。","ipa":"[ɛ̃.de.si]","ph":"in 读鼻化 [ɛ̃]；dé 读 [de]；cis 读 [si]，结尾 s 不发音；阴性 indécise 读 [ɛ̃.de.siz]。","pi":"阳性 indécis 结尾 s 不发音；阴性 indécise 的 s 读 [z]。in- 是鼻化元音，不要读成 [in]。","et":"由 in-（否定）+ décis（来自拉丁语 decisus，decidere 的过去分词）构成。同族：décider、la décision。","ex":[["Je ne sais pas quoi choisir, je suis indécis.","我不知道选什么，很犹豫。"],["Elle est indécise.","她拿不定主意。"]],"co":[["rester indécis(e)","仍然犹豫不决"],["un électeur indécis","未决定投谁的选民"],["l'indécision","犹豫不决"]],"sy":[["hésitant","courant","犹豫的"],["irrésolu","soutenu","优柔寡断的"],["décidé","courant","果断的，反义"]],"fq":"中频，日常对话里常用。","me":"in- + décis：还没「做出决定」。","tr":{"zh":"我还没决定，我很犹豫。","fr":"Je n'ai pas décidé, je suis indécis.","alt":"Je ne sais pas encore, j'hésite.","note":"女性说 je suis indécise。"}},
 "Jaloux / Jalouse": {"pos":"adj. 形容词，阳性 jaloux，阴性 jalouse，复数 jaloux / jalouses","s":"嫉妒的；吃醋的；羡慕的。être jaloux de qqn = 嫉妒某人；être jaloux de qqch = 羡慕某物。也可指爱情里吃醋。","ipa":"[ʒa.lu]","ph":"j 读 [ʒ]；a [a]；lou 读 [lu]；结尾 x 不发音；阴性 jalouse 读 [ʒa.luz]。","pi":"j 读 [ʒ]，不是英语 [dʒ]。阳性结尾 x 不发音，阴性 s 读 [z]。","et":"来自古法语 gelos，源于希腊语 zelos（热忱、嫉妒）。同族：la jalousie（嫉妒；百叶窗）。","ex":[["Il est jaloux de son ami.","他嫉妒他的朋友。"],["Elle est jalouse de ma réussite.","她嫉妒我的成功。"]],"co":[["être jaloux de qqn","嫉妒某人"],["une scène de jalousie","吃醋吵闹"],["la jalousie","嫉妒"]],"sy":[["envieux","soutenu","羡慕的、眼红的"],["possessif","courant","占有欲强的"]],"fq":"高频，日常常用。","me":"jaloux 听起来像「加路」，阳性 x 不读。","tr":{"zh":"他嫉妒我的新车。","fr":"Il est jaloux de ma nouvelle voiture.","alt":"Il envie ma nouvelle voiture.","note":"jaloux de + 名词。"}},
 "Laïque": {"pos":"adj. 形容词，阴阳性同形，复数 laïques；也可作名词（俗人）","s":"世俗的；政教分离的。在法国指国家和宗教分开，如 l'école laïque（世俗学校）。也可指不属于神职的普通人。","ipa":"[la.ik]","ph":"laï 的 ï 上有分音符，读成两个音 [la.i]；que 读 [k]，结尾 e 不发音。","pi":"ï 上的两点表示要分开读，a 和 i 不连读。别读成 [lɛk]。","et":"来自拉丁语 laicus，源于希腊语 laikos（属于人民的）。同族：la laïcité（政教分离原则）。","ex":[["La France est un pays laïque.","法国是个世俗国家。"],["L'école publique est laïque.","公立学校是世俗的。"]],"co":[["l'école laïque","世俗学校"],["un État laïque","世俗国家"],["la laïcité","政教分离"]],"sy":[["séculier","soutenu","世俗的，教会用语"],["religieux","courant","宗教的，反义"]],"fq":"中频，在文化、社会话题里常见。","me":"laï- 的两点：把 a 和 i 分开读。","tr":{"zh":"公立学校不属于任何宗教。","fr":"L'école publique est laïque.","alt":"À l'école publique, il n'y a pas de religion.","note":"laïque 阴阳性同形。"}},
 "Le/La même": {"pos":"adj. 形容词（常与冠词连用），阴阳性同形 même，复数 les mêmes","s":"同样的；同一个。le même + 名词 = 同一个……；la même chose = 同样的东西。放在名词前表示「同一」，放在名词后或代词后表示「正是、本身」，如 lui-même。","ipa":"[mɛm]","ph":"ê 读 [ɛ]；m 读 [m]，结尾 e 不发音，所以以 [m] 收尾。","pi":"même 的 ê 有重音符，别写成 meme。复数 les mêmes 的 s 不发音。别和 pareil 混：même 更强调「同一个」。","et":"来自俗拉丁语 metipsimus，意为「同一个」。同族：quand même、tout de même。","ex":[["Nous avons la même voiture.","我们有同一辆车。"],["Ils habitent dans la même rue.","他们住在同一条街上。"],["C'est la même chose.","是一样的东西。"]],"co":[["le même + nom","同一个……"],["la même chose","同样的东西"],["en même temps","同时"],["quand même","还是；毕竟"]],"sy":[["identique","soutenu","完全相同的"],["pareil","courant","一样的"],["différent","courant","不同的，反义"]],"fq":"极高频，日常常用。","me":"même = 「就是它」，ê 像一顶小帽子。","tr":{"zh":"我们读同一本书。","fr":"Nous lisons le même livre.","alt":"On lit le même livre.","note":"même 随名词性别用冠词：le même / la même / les mêmes。"}},
 "Maigre": {"pos":"adj. 形容词，阴阳性同形，复数 maigres","s":"瘦的；瘦弱的；也指「少的、微薄的」，如 un maigre salaire（微薄的薪水）。形容人偏瘦，有时略带贬义。","ipa":"[mɛɡʁ]","ph":"ai 读 [ɛ]；g 读 [ɡ]；re 与 g 连读成 [ɡʁ]，结尾 e 不发音。","pi":"g 要读出来，是 [mɛɡʁ]，不是 [mɛʁ]。ai 读 [ɛ]。","et":"来自拉丁语 macer（瘦的）。同族：maigrir（变瘦）、la maigreur（消瘦）。","ex":[["Ce chat est très maigre.","这只猫很瘦。"],["Il a un maigre salaire.","他的薪水很微薄。"]],"co":[["maigre comme un clou","瘦得像根钉子"],["un maigre salaire","微薄的薪水"],["maigrir","变瘦"]],"sy":[["mince","courant","苗条，较褒义"],["svelte","soutenu","修长的"],["gros","courant","胖的，反义"]],"fq":"中频，日常常用。","me":"maigre → maigrir：越来越瘦。","tr":{"zh":"他太瘦了，应该多吃点。","fr":"Il est trop maigre, il doit manger plus.","alt":"Il est tout maigre, il faut qu'il mange plus.","note":"maigre 偏中性略贬义，褒义用 mince。"}},
 "Maniaque": {"pos":"adj. 形容词，阴阳性同形，复数 maniaques；也可作名词 un / une maniaque","s":"有洁癖的；吹毛求疵的；一丝不苟到过分的。形容对整洁、规矩特别讲究的人，口语里很常用。也可指「狂热者」，如 un maniaque du sport。","ipa":"[ma.njak]","ph":"ma [ma]；nia 读 [nja]；que 读 [k]，结尾 e 不发音。","pi":"ni 在这里读 [nj]，不是两个音节。口语里多是「爱整洁、爱挑剔」，不一定是「疯子」。","et":"来自 manie（狂热），源于希腊语 mania（疯狂）。同族：la manie。","ex":[["Il range tout, il est maniaque.","他什么都收拾，是个强迫症。"],["Elle est maniaque de la propreté.","她对清洁特别讲究。"]],"co":[["être maniaque","很爱整洁，爱挑剔"],["maniaque de l'ordre","对整齐近乎偏执"],["une manie","怪癖；习惯"]],"sy":[["méticuleux","soutenu","一丝不苟的"],["perfectionniste","courant","完美主义的"],["pointilleux","courant","吹毛求疵的"]],"fq":"中频，口语常用。","me":"mania → maniaque：对某件事「着了魔」。","tr":{"zh":"我爸爸对整洁很讲究。","fr":"Mon père est maniaque de l'ordre.","alt":"Mon père est très maniaque, il range tout.","note":"maniaque de + 名词。"}},
 "Obligatoire": {"pos":"adj. 形容词，阴阳性同形，复数 obligatoires","s":"必须的；强制的；义务的。指法律或规定要求做的事，如 l'école obligatoire。反义词是 facultatif（可选的）。","ipa":"[ɔ.bli.ɡa.twaʁ]","ph":"ob 的 b 与 li 连读成 [ɔ.bli]；ga 读 [ɡa]；toire 读 [twaʁ]，oi 读 [wa]。","pi":"oi 读 [wa]，不是 [ɔi]。结尾 -re 的 r 要读，e 不发音。","et":"来自拉丁语 obligatorius，源于 obligare（束缚）。同族：obliger、l'obligation。","ex":[["L'école est obligatoire.","上学是义务的。"],["Le casque est obligatoire.","必须戴头盔。"]],"co":[["obligatoire pour tous","人人必须"],["un cours obligatoire","必修课"],["rendre obligatoire","使成为强制"]],"sy":[["indispensable","courant","必不可少的"],["obligé","courant","被迫的"],["facultatif","courant","可选的，反义"]],"fq":"高频，规定、通知里很常见。","me":"obliger（强迫）→ obligatoire：不得不做。","tr":{"zh":"在这里，戴口罩是必须的。","fr":"Ici, le masque est obligatoire.","alt":"Ici, il faut obligatoirement porter un masque.","note":"obligatoire 阴阳性同形。"}},
 "Ordonné(e)": {"pos":"adj. 形容词（ordonner 的过去分词），阳性 ordonné，阴性 ordonnée，复数 ordonnés / ordonnées","s":"整齐的；有条理的；井井有条的。可形容人（爱整洁）或房间、工作安排。反义词 désordonné（凌乱的）。","ipa":"[ɔʁ.dɔ.ne]","ph":"or 读 [ɔʁ]；do 读 [dɔ]（开口 o）；nné 读 [ne]，双 n 只读一个。","pi":"双 n 只读一个 [n]。别把它和 ordonnance（处方）混淆；ordonné 作形容词是「整齐」。","et":"来自 ordre（顺序、秩序），源于拉丁语 ordo；ordonner = 使有序。同族：désordonné。","ex":[["Ma chambre est toujours ordonnée.","我的房间总是很整齐。"],["Il est très ordonné dans son travail.","他工作很有条理。"]],"co":[["une personne ordonnée","有条理的人"],["un bureau ordonné","整齐的办公桌"],["désordonné","凌乱的，反义"]],"sy":[["rangé","courant","收拾好的"],["organisé","courant","有组织的"],["bordélique","familier","乱七八糟的，反义（较粗俗）"]],"fq":"中频，描述房间和性格时用。","me":"ordre（顺序）+ -é：每样东西都有位置。","tr":{"zh":"我妹妹很有条理。","fr":"Ma sœur est très ordonnée.","alt":"Ma sœur est super organisée.","note":"阴性加 e：ordonnée。"}},
 "Original(e)": {"pos":"adj. 形容词，阳性 original，阴性 originale，复数 originaux / originales","s":"独特的；原创的；新颖的；原始的。形容想法、人或礼物别致有创意；也指「原版的、原本的」，如 la version originale（原版，常缩写 VO）。","ipa":"[ɔ.ʁi.ʒi.nal]","ph":"o 读 [ɔ]；ri [ʁi]；gi 读 [ʒi]，g 在 i 前读 [ʒ]；nal [nal]；阴性 originale 读音相同。","pi":"阳性复数是 originaux，不是 originals。g 读 [ʒ]。","et":"来自拉丁语 originalis，源于 origo（起源）。同族：l'origine、originaire。","ex":[["Ton idée est très originale.","你的想法很有创意。"],["Je préfère les films en version originale.","我更喜欢看原版电影。"]],"co":[["une idée originale","有创意的想法"],["la version originale (VO)","原版"],["un cadeau original","别致的礼物"]],"sy":[["unique","courant","独一无二的"],["novateur","soutenu","创新的"],["banal","courant","平庸的，反义"]],"fq":"高频，日常常用。","me":"origine（起源）+ -al：「来自源头」就是独特的。","tr":{"zh":"这个礼物很有创意。","fr":"Ce cadeau est très original.","alt":"Ce cadeau, c'est original !","note":"阳性复数 originaux。"}},
 "Pareil": {"pos":"adj. 形容词，阳性 pareil，阴性 pareille，复数 pareils / pareilles；口语里也单独说 Pareil !","s":"相同的；一样的；如此的。C'est pareil = 一样；pareil à = 和……一样。口语里常单独说 Pareil !（我也一样）。","ipa":"[pa.ʁɛj]","ph":"pa [pa]；reil 读 [ʁɛj]，-eil 读 [ɛj]；阴性 pareille 读音相同。","pi":"-eil 读 [ɛj]，l 不单独发。阴性 pareille 与阳性读音一样。","et":"来自俗拉丁语，源于拉丁语 par（相等的）。同族：le pair、une paire、comparer。","ex":[["C'est exactement pareil.","完全一样。"],["Ces deux sacs sont pareils.","这两个包一样。"],["Pareil pour moi.","我也一样。"]],"co":[["C'est pareil.","都一样。"],["pareil à","和……一样"],["Pareil pour moi.","我也是。"]],"sy":[["identique","soutenu","完全相同的"],["semblable","courant","相似的"],["le même","courant","同一个"]],"fq":"极高频，口语常用。","me":"par（相等）→ pareil：一对「成双」的东西。","tr":{"zh":"你的和我的一样。","fr":"Le tien est pareil au mien.","alt":"Le tien, c'est pareil que le mien.","note":"书面用 pareil à；口语里常说 pareil que。"}},
 "Parfait(e)": {"pos":"adj. 形容词，阳性 parfait，阴性 parfaite，复数 parfaits / parfaites","s":"完美的；极好的；十分合适的。口语里 Parfait ! = 太好了！好的！也可作加强语气：un parfait inconnu（完全陌生的人）。","ipa":"[paʁ.fɛ]","ph":"par 读 [paʁ]；fait 读 [fɛ]，结尾 t 不发音；阴性 parfaite 读 [paʁ.fɛt]。","pi":"阳性 parfait 的 t 不发音，阴性 parfaite 才读出 t。ai 读 [ɛ]。","et":"来自拉丁语 perfectus（完成的），源于 perficere。同族：parfaitement、la perfection。","ex":[["Ce repas est parfait.","这顿饭很完美。"],["Parfait, à demain !","好的，明天见！"]],"co":[["Parfait !","太好了！好的！"],["un parfait inconnu","完全陌生的人"],["parfaitement","完全地；当然"],["le parfait bonheur","完美的幸福"]],"sy":[["idéal","courant","理想的"],["impeccable","courant","无可挑剔的"],["génial","familier","太棒了"]],"fq":"极高频，日常常用。","me":"par-fait：「完全做完了」，所以完美。","tr":{"zh":"这个主意很完美。","fr":"Cette idée est parfaite.","alt":"C'est une idée parfaite.","note":"阴性 parfaite，t 要读出来。"}},
 "Pessimiste": {"pos":"adj. 形容词，阴阳性同形，复数 pessimistes；也可作名词 un / une pessimiste","s":"悲观的；爱往坏处想的。也可作名词：un pessimiste（悲观的人）。反义词是 optimiste。","ipa":"[pɛ.si.mist]","ph":"pe 读 [pɛ]；ss 读 [s]；mis 读 [mis]；te 读 [t]，结尾 e 不发音。","pi":"ss 读 [s]；结尾 -iste 读 [ist]，不是 [istɛ]。拼写别漏掉双 s。","et":"来自拉丁语 pessimus（最坏的），加后缀 -iste。反义词 optimiste 来自 optimus（最好的）。","ex":[["Il voit tout en noir, il est pessimiste.","他把一切都看得很黑，很悲观。"],["Ne sois pas si pessimiste !","别这么悲观！"]],"co":[["voir tout en noir","把一切看得很黑暗"],["un pessimiste","悲观的人"],["le pessimisme","悲观"]],"sy":[["défaitiste","soutenu","失败主义的"],["négatif","courant","消极的"],["optimiste","courant","乐观的，反义"]],"fq":"中频，描述性格时用。","me":"pessimus（最坏）：总想着最坏的结果。","tr":{"zh":"别这么悲观，会好起来的。","fr":"Ne sois pas si pessimiste, ça va aller.","alt":"Arrête d'être pessimiste, ça va aller.","note":"ne sois pas = 别……（否定命令式）。"}},
 "Peureux / Peureuse": {"pos":"adj. 形容词，阳性 peureux，阴性 peureuse，复数 peureux / peureuses","s":"胆小的；容易害怕的。形容人或动物容易受惊。口气比 lâche（懦弱）轻。","ipa":"[pø.ʁø]","ph":"peu 读 [pø]；reux 读 [ʁø]，结尾 x 不发音；阴性 peureuse 读 [pø.ʁøz]。","pi":"eu 读 [ø]，嘴唇圆起，不是 [u]。阳性结尾 x 不发音。","et":"由 peur（害怕）+ -eux 构成，peur 来自拉丁语 pavor。同族：avoir peur、apeuré。","ex":[["Mon chien est peureux.","我的狗很胆小。"],["Elle est peureuse, elle a peur du noir.","她很胆小，怕黑。"]],"co":[["un enfant peureux","胆小的孩子"],["avoir peur de","害怕……"],["peureux comme un lapin","胆小如兔"]],"sy":[["craintif","soutenu","胆怯的"],["trouillard","familier","胆小鬼，口语"],["courageux","courant","勇敢的，反义"]],"fq":"中频，日常常用，多用于孩子与动物。","me":"peur + -eux：「充满害怕」。","tr":{"zh":"我的猫很胆小。","fr":"Mon chat est très peureux.","alt":"Mon chat a peur de tout.","note":"阴性 peureuse，x 变 se。"}},
 "Poli(e)": {"pos":"adj. 形容词，阳性 poli，阴性 polie，复数 polis / polies","s":"有礼貌的；客气的。être poli avec qqn = 对某人有礼貌。也是 polir（打磨）的过去分词，如 une pierre polie（磨光的石头）。","ipa":"[pɔ.li]","ph":"po 读 [pɔ]（开口 o）；li 读 [li]；阴性 polie 读音相同。","pi":"poli 的 o 是开口音 [ɔ]。阴性写 polie，但读音不变。别和 joli（漂亮的）混淆。","et":"来自拉丁语 politus（打磨光滑的），源于 polire。同族：poliment、la politesse、polir。","ex":[["Cet enfant est très poli.","这个孩子很有礼貌。"],["Sois poli avec la dame.","对那位女士要有礼貌。"]],"co":[["être poli avec qqn","对某人有礼貌"],["la politesse","礼貌"],["poliment","有礼貌地"]],"sy":[["courtois","soutenu","彬彬有礼的"],["aimable","courant","和善的"],["impoli","courant","没礼貌的，反义"]],"fq":"极高频，日常常用。","me":"poli：像石头被打磨过，所以举止光滑、不刺人。","tr":{"zh":"请对邻居有礼貌。","fr":"Sois poli avec les voisins.","alt":"Sois gentil et poli avec les voisins.","note":"avec qqn：对某人。"}},
 "Radin(e)": {"pos":"adj. 形容词（口语），阳性 radin，阴性 radine，复数 radins / radines；也作名词 un radin","s":"吝啬的；小气的。口语词，形容不愿花钱的人，也可作名词：un radin（小气鬼）。语气带贬义。","ipa":"[ʁa.dɛ̃]","ph":"ra 读 [ʁa]；din 读鼻化 [dɛ̃]；阴性 radine 读 [ʁa.din]，n 要读出。","pi":"阳性 radin 末尾 in 是鼻化 [ɛ̃]；阴性 radine 末尾读 [din]，n 要发出来。","et":"来源不确定，口语词。","ex":[["Il ne veut pas payer, il est radin.","他不肯付钱，很小气。"],["Ne sois pas radin !","别这么小气！"]],"co":[["un radin","小气鬼"],["être radin avec qqn","对某人小气"],["ne pas être radin","出手大方"]],"sy":[["avare","courant","吝啬的，更正式"],["pingre","soutenu","吝啬、抠门"],["généreux","courant","慷慨的，反义"]],"fq":"中频，口语常用，带贬义。","me":"radin 听起来像「抠门」，快速把钱收回去。","tr":{"zh":"他很小气，从不请客。","fr":"Il est radin, il n'invite jamais.","alt":"Il est radin, il ne paie jamais pour les autres.","note":"radin 是口语，正式场合用 avare。"}},
 "Respectueux / Respectueuse": {"pos":"adj. 形容词，阳性 respectueux，阴性 respectueuse，复数 respectueux / respectueuses","s":"尊重人的；恭敬的。être respectueux envers / avec qqn = 对某人有礼貌、尊重；être respectueux de qqch = 遵守、尊重某事。","ipa":"[ʁɛs.pɛk.tɥø]","ph":"res 读 [ʁɛs]；pec 读 [pɛk]；tueux 读 [tɥø]，结尾 x 不发音；阴性 respectueuse 读 [ʁɛs.pɛk.tɥøz]。","pi":"tue 读 [tɥ]，不是 [tu]。阳性结尾 x 不发音。","et":"由 respect（来自拉丁语 respectus，回头看、顾及）加 -ueux 构成。同族：le respect、respecter。","ex":[["Il est respectueux avec les autres.","他对别人很尊重。"],["Elle est respectueuse des règles.","她遵守规则。"]],"co":[["être respectueux de qqch","尊重 / 遵守某事"],["respectueux envers qqn","对某人恭敬"],["respectueusement","恭敬地"]],"sy":[["poli","courant","有礼貌的"],["déférent","soutenu","恭敬顺从的"],["irrespectueux","courant","不尊重人的，反义"]],"fq":"中频，描述性格和态度时用。","me":"respect + -ueux：满是「尊重」。","tr":{"zh":"孩子们应该尊重老人。","fr":"Les enfants doivent être respectueux envers les personnes âgées.","alt":"Les enfants doivent respecter les personnes âgées.","note":"respectueux envers / avec qqn。"}},
 "Ringard(e)": {"pos":"adj. 形容词（口语），阳性 ringard，阴性 ringarde，复数 ringards / ringardes；也作名词 un ringard","s":"老土的；过时的；不时髦的。口语里指穿着、音乐、想法等已经落伍。语气偏随意，有时带贬义。","ipa":"[ʁɛ̃.ɡaʁ]","ph":"rin 读鼻化 [ʁɛ̃]；gard 读 [ɡaʁ]，g 读 [ɡ]；阴性 ringarde 读 [ʁɛ̃.ɡaʁd]。","pi":"ring 中 in 是鼻化 [ɛ̃]，g 要单独读 [ɡ]。阳性结尾 d 不发音，阴性 ringarde 的 d 才读。","et":"来源不确定，口语词。","ex":[["Ce pantalon est ringard.","这条裤子很土。"],["Sa musique est ringarde.","他的音乐很过时。"]],"co":[["un style ringard","老土的风格"],["C'est ringard !","好土啊！"],["avoir l'air ringard","看起来很土"]],"sy":[["démodé","courant","过时的"],["has-been","familier","过气的"],["branché","familier","时髦的，反义"]],"fq":"中频，口语常用。","me":"ringard 听起来有点「老派」。","tr":{"zh":"这件外套有点过时了。","fr":"Ce manteau est un peu ringard.","alt":"Ce manteau fait un peu ringard.","note":"faire + 形容词：看起来……（口语）。"}},
 "Sobre": {"pos":"adj. 形容词，阴阳性同形，复数 sobres","s":"朴素的；简洁的；清醒的（没喝醉）。形容服饰、装修素雅不花哨；也指饮酒有节制或没醉的人。","ipa":"[sɔbʁ]","ph":"so 读 [sɔ]（开口 o）；bre 读 [bʁ]，结尾 e 不发音，所以只有一个音节 [sɔbʁ]。","pi":"o 是开口音 [ɔ]，不是 [o]。别读成两个音节 [so.bʁə]。","et":"来自拉丁语 sobrius（没喝醉的、节制的）。同族：la sobriété、sobrement。","ex":[["Il porte des vêtements sobres.","他穿着朴素的衣服。"],["Elle reste sobre à la fête.","她在派对上保持清醒。"]],"co":[["un style sobre","简洁的风格"],["rester sobre","保持清醒；保持节制"],["sobrement","朴素地；节制地"]],"sy":[["simple","courant","简单的"],["discret","courant","低调的"],["ivre","courant","喝醉的，反义"]],"fq":"中频，描述风格与饮酒时用。","me":"sobre ≈ sober：英法几乎一样，但法语多指「朴素」。","tr":{"zh":"我喜欢朴素的房间。","fr":"J'aime les chambres sobres.","alt":"J'aime quand la chambre est simple et sobre.","note":"sobre 阴阳性同形。"}},
 "Têtu(e)": {"pos":"adj. 形容词，阳性 têtu，阴性 têtue，复数 têtus / têtues","s":"固执的；倔强的。形容人不肯改变主意，如 têtu comme une mule（像骡子一样倔）。可用于孩子、动物，带点无奈语气。","ipa":"[te.ty]","ph":"tê 读 [te]（ê 此处读 [e]）；tu 读 [ty]，u 嘴唇圆起；阴性 têtue 读音相同。","pi":"têtu 的 u 读 [y]，不是 [u]。ê 上有长音符，别写成 tetu。阴性 têtue 读音不变。","et":"由 tête（头）+ -u 构成，字面是「头很硬的」。同族：la tête、entêté。","ex":[["Mon fils est très têtu.","我儿子很固执。"],["Elle est têtue comme une mule.","她像骡子一样倔。"]],"co":[["têtu comme une mule","倔得像骡子"],["un enfant têtu","固执的孩子"],["s'entêter","固执己见"]],"sy":[["entêté","courant","固执的，更强"],["obstiné","soutenu","顽固的"],["buté","courant","顽固、不肯让步"]],"fq":"中频，描述性格时常用。","me":"tête + -u：脑袋像石头一样硬。","tr":{"zh":"我的朋友很固执，不听别人的。","fr":"Mon ami est têtu, il n'écoute personne.","alt":"Mon ami est têtu comme une mule.","note":"ne… personne：不听任何人。"}},
 "Timide": {"pos":"adj. 形容词，阴阳性同形，复数 timides；也可作名词 un / une timide","s":"害羞的；腼腆的；胆怯的。形容人在陌生人面前不好意思开口。也可形容迹象不明显：un timide sourire（腼腆的微笑）。","ipa":"[ti.mid]","ph":"ti 读 [ti]；mide 读 [mid]，d 要读出来，结尾 e 不发音。","pi":"结尾 d 要发 [d]，不要吞掉。第一个 i 读 [i]，嘴角拉开。","et":"来自拉丁语 timidus，源于 timere（害怕）。同族：la timidité、intimider。","ex":[["Le petit garçon est timide.","小男孩很害羞。"],["Elle est trop timide pour parler.","她太害羞，不敢说话。"]],"co":[["être timide","害羞"],["un sourire timide","腼腆的微笑"],["la timidité","害羞"],["trop timide pour + inf.","太害羞而不敢……"]],"sy":[["réservé","courant","内敛的"],["craintif","soutenu","胆怯的"],["extraverti","courant","外向的，反义"]],"fq":"高频，日常常用。","me":"timid ≈ 英语 timid：同源，一看就懂。","tr":{"zh":"他很害羞，不敢跟女孩说话。","fr":"Il est timide, il n'ose pas parler aux filles.","alt":"Il est trop timide pour parler aux filles.","note":"oser + 动词原形：敢于。"}},
 "Unique": {"pos":"adj. 形容词，阴阳性同形，复数 uniques","s":"独一无二的；唯一的。un enfant unique 指独生子；une chance unique 指唯一的机会。口语里也可夸「独特、绝妙」。","ipa":"[y.nik]","ph":"u 读 [y]（嘴唇圆起）；ni 读 [ni]；que 读 [k]，结尾 e 不发音。","pi":"开头 u 读 [y]，不是英语 unique 的 [ju]。qu 读 [k]。","et":"来自拉丁语 unicus，源于 unus（一）。同族：un、unir、l'unité。","ex":[["Ce tableau est unique.","这幅画是独一无二的。"],["Je suis fille unique.","我是独生女。"]],"co":[["un enfant unique","独生子"],["une occasion unique","唯一的机会"],["une pièce unique","孤品"]],"sy":[["seul","courant","唯一的"],["exceptionnel","courant","出色的"],["banal","courant","平凡的，反义"]],"fq":"高频，日常常用。","me":"unique = un + -ique：「只有一个」。","tr":{"zh":"这是一次独一无二的经历。","fr":"C'est une expérience unique.","alt":"C'est une expérience vraiment unique.","note":"unique 阴阳性同形。"}},
 "Surtout": {"pos":"adv. 副词，不变","s":"尤其；特别是；最重要的是。用来突出一点：J'aime les fruits, surtout les pommes. 也常用于叮嘱：Surtout, ne dis rien !（千万别说！）","ipa":"[syʁ.tu]","ph":"u [y]（嘴唇圆起发 yu）；r 是小舌音 [ʁ]；ou [u]；结尾 t 不发音。","pi":"第一个 u 读 [y]，不是 [u]；结尾 t 不发音。别和 surtout 拆开写成 sur tout。","et":"由 sur（在……之上）+ tout（全部）构成，字面是「高于一切」，所以表示「尤其」。","ex":[["J'aime les fruits, surtout les pommes.","我喜欢水果，尤其是苹果。"],["Surtout, n'oublie pas ton passeport !","千万别忘了你的护照！"],["Il fait froid, surtout le matin.","天很冷，尤其是早上。"]],"co":[["surtout pas","千万别；绝不"],["surtout que + 从句","尤其因为……（口语）"],["surtout pour + 名词","尤其是为了……"]],"sy":[["notamment","soutenu","特别是（正式，用于举例）"],["en particulier","courant","尤其是"],["spécialement","courant","特别地"]],"fq":"极高频，日常常用。","me":"sur + tout = 在「所有」之上 = 最要紧。","tr":{"zh":"我爱旅行，尤其爱去意大利。","fr":"J'adore voyager, surtout en Italie.","alt":"J'aime beaucoup voyager, surtout aller en Italie.","note":"surtout 放在要强调的成分前面。"}},
 "Au milieu de": {"pos":"loc. prép. 介词短语（milieu 为阳性名词，复数 milieux）","s":"在……中间；在……当中。可指空间（au milieu de la pièce）也可指时间（au milieu de la nuit，半夜里）。后面接名词，de 要和冠词缩合。","ipa":"[o.mi.ljø.də]","ph":"au [o]；ieu 读 [jø]；结尾 de 弱读 [də]，口语里 e 常脱落。","pi":"de + le 要缩合成 du：au milieu du jardin；de + les 变 des：au milieu des arbres。milieu 复数是 milieux，不是 milieus。","et":"milieu 来自古法语 mi（中间，拉丁语 medius）+ lieu（地方），字面是「中间的地方」。","ex":[["La table est au milieu de la pièce.","桌子在房间中央。"],["Il s'est réveillé au milieu de la nuit.","他半夜醒了。"],["Elle est au milieu des enfants.","她在孩子们当中。"]],"co":[["au milieu du jardin","在花园中央"],["au milieu de la nuit","在半夜"],["en plein milieu de","正中间（更强调）"],["au beau milieu de","恰恰在……当中"]],"sy":[["au centre de","courant","在……中心（更偏位置）"],["parmi","courant","在……之中（多个人或物）"],["entre","courant","在两者之间，别混用"]],"fq":"高频，日常常用。","me":"mi（半）+ lieu（地方）：站在「半当中的地方」。","tr":{"zh":"猫睡在床中间。","fr":"Le chat dort au milieu du lit.","alt":"Le chat est couché en plein milieu du lit.","note":"de + le → du：au milieu du lit。"}},
 "Autour de": {"pos":"loc. prép. 介词短语","s":"围绕；在……周围；大约（用于数量或时间）。Autour de la maison = 房子周围。Autour de 18 h = 大约下午六点。","ipa":"[o.tuʁ.də]","ph":"au [o]；our 读 [uʁ]；t 要发音；de 弱读 [də]。","pi":"tour 里的 t 发音，别漏掉。表示「大约」时和 vers、environ 意思相近。别和 alentour（副词，周围）混淆。","et":"由 à + l'entour 演变而来；tour 来自拉丁语 tornus（车床、圆圈），所以有「绕一圈」的意思。","ex":[["Il y a des arbres autour de la maison.","房子周围有树。"],["On s'assoit tous autour de la table.","我们都围着桌子坐下。"],["Je rentre autour de huit heures.","我八点左右回家。"]],"co":[["autour de la table","围着桌子"],["autour de nous","在我们周围"],["autour de midi","中午前后"],["tourner autour de","绕着……转"]],"sy":[["environ","courant","大约（放在数字前）"],["aux alentours de","soutenu","在……附近；大约"],["tout autour","courant","四周围一圈"]],"fq":"高频，日常常用。","me":"au + tour：绕着转一圈（tour 就是「圈」）。","tr":{"zh":"孩子们围着桌子玩。","fr":"Les enfants jouent autour de la table.","alt":"Les enfants sont en train de jouer autour de la table.","note":"autour de 后面接地点，也可接大约的时间。"}},
 "Avec mesure": {"pos":"loc. adv. 副词短语（mesure 为阴性名词）","s":"适度地；有节制地。强调不过量、不极端。常和吃喝、花钱、玩笑连用：boire avec mesure（适量喝酒）。","ipa":"[a.vɛk.mə.zyʁ]","ph":"avec 的 c 读 [k]；e 在 mesure 里弱读，常说成 [mzyʁ]；s 在元音间读 [z]；u 读 [y]。","pi":"mesure 里的 s 读 [z]，不是 [s]；avec 末尾的 c 要发音 [k]；avec 和 mesure 之间没有联诵。","et":"mesure 来自拉丁语 mensura（测量），与 mesurer（测量）同源；avec 来自拉丁语 apud hoc。","ex":[["Il faut boire de l'alcool avec mesure.","喝酒要适度。"],["Elle dépense son argent avec mesure.","她花钱有分寸。"],["Utilisez ce produit avec mesure.","请适量使用这个产品。"]],"co":[["boire avec mesure","适量地喝酒"],["sans mesure","无节制地"],["dans la mesure du possible","尽可能"],["prendre la mesure de","掂量；认清"]],"sy":[["avec modération","courant","适度地（最常见）"],["raisonnablement","courant","合理地；有分寸地"],["sans excès","courant","不过度"]],"fq":"中频，书面和提醒语里常见。","me":"mesure = 量尺：用尺子量好再用，就是适度。","tr":{"zh":"糖要适量吃。","fr":"Il faut manger du sucre avec mesure.","alt":"Mange du sucre, mais avec mesure.","note":"avec + 无冠词名词，构成副词短语。"}},
 "Avoir la tête de l'emploi": {"pos":"loc. verbale 动词短语（avoir 是 être 以外最常用的助动词，复合时态用 avoir）","s":"长得就像那个角色；外表正好符合那份工作或身份。可褒可贬，口语里常带点打趣。例如一个人一看就像老师、医生或坏人。","ipa":"[a.vwaʁ.la.tɛt.də.lɑ̃.plwa]","ph":"tête 的 ê 读 [ɛ]；emploi 里 em 读鼻化 [ɑ̃]，oi 读 [wa]；de l'emploi 中 l' 与 emploi 连读。","pi":"tête 的 ê 读开音 [ɛ]，不是 [e]；emploi 鼻化 [ɑ̃] 后面再接 [plwa]，别漏掉 p。tête 是阴性，所以是 la tête。","et":"tête 来自拉丁语 testa（陶罐，后指脑袋）；emploi 来自 employer，拉丁语 implicare（卷入、使用）。","ex":[["Il a la tête de l'emploi pour ce travail.","他的样子很适合这份工作。"],["Avec ses lunettes, il a la tête de l'emploi.","戴着眼镜，他就是那个样子。"],["Elle a vraiment la tête de l'emploi !","她真是长得像那个角色！"]],"co":[["avoir la tête de l'emploi","样子很像那个角色"],["ne pas avoir la tête de l'emploi","不像那个角色"],["pour le rôle","扮演这个角色"]],"sy":[["être taillé pour le rôle","courant","天生适合这个角色"],["avoir le physique de l'emploi","courant","外形符合要求（几乎同义）"],["coller au personnage","familier","很贴合角色"]],"fq":"中频，口语里常见。","me":"头（tête）的样子正合工作（emploi）：一眼就看出来。","tr":{"zh":"他一副老师的样子。","fr":"Il a la tête de l'emploi : on dirait un professeur.","alt":"Il a vraiment la tête d'un professeur.","note":"tête de + 名词：像……的样子。"}},
 "Avoir une mémoire d'éléphant": {"pos":"loc. verbale 动词短语（mémoire 为阴性名词，复数 mémoires）","s":"记性极好，什么都记得。成语，把人比作大象。通常是夸人，有时也暗示对方记仇、不忘旧事。","ipa":"[a.vwaʁ.yn.me.mwaʁ.de.le.fɑ̃]","ph":"mémoire 读 [me.mwaʁ]；éléphant 读 [e.le.fɑ̃]，ph 读 [f]，结尾 -ant 读鼻化 [ɑ̃]，t 不发音。","pi":"éléphant 的 ph 读 [f]；-ant 里的 t 不发音。mémoire 阴性，用 une。mémoire 作「回忆录」时是阳性 un mémoire（意思不同）。","et":"mémoire 来自拉丁语 memoria；éléphant 来自希腊语 elephas（象，也指象牙）。「象不忘事」是欧洲民间的说法。","ex":[["Il se souvient de tout, il a une mémoire d'éléphant.","他什么都记得，记性像大象。"],["Elle a une mémoire d'éléphant pour les visages.","她记人脸的本事特别强。"],["Attention, mon père a une mémoire d'éléphant !","小心，我爸爸什么都记得！"]],"co":[["une excellente mémoire","极好的记性"],["avoir bonne mémoire","记性好"],["avoir la mémoire courte","健忘；记性差"],["perdre la mémoire","失忆"]],"sy":[["avoir une mémoire de fer","courant","记性极好（铁一般）"],["avoir une tête de linotte","familier","丢三落四（反义）"],["avoir un trou de mémoire","courant","一时想不起来"]],"fq":"中频，口语成语。","me":"想象一头大象，一辈子都不忘事。","tr":{"zh":"我外婆记性特别好。","fr":"Ma grand-mère a une mémoire d'éléphant.","alt":"Ma grand-mère n'oublie jamais rien, elle a une mémoire d'éléphant.","note":"d'éléphant 是固定搭配，不用冠词。"}},
 "C'est l'enfer": {"pos":"loc. 固定表达（enfer 为阳性名词，复数 enfers）","s":"真是地狱！太糟糕了！夸张地形容很难受、很麻烦的处境，如堵车、加班、挤地铁。语气强烈但很常用，不涉及宗教。","ipa":"[sɛ.lɑ̃.fɛʁ]","ph":"c'est 读 [sɛ]，t 不发音；l'enfer 中 l 与 enfer 连读：[lɑ̃.fɛʁ]；en 读鼻化 [ɑ̃]；r 是小舌音，结尾 r 要发。","pi":"enfer 结尾的 r 要发音 [ʁ]；en 读 [ɑ̃]，不是「恩」。enfer 以元音开头，所以是 l'enfer，不是 le enfer。","et":"enfer 来自拉丁语 infernus（下界的），与英语 inferno 同源。","ex":[["Je suis bloqué dans l'ascenseur, c'est l'enfer !","我被困在电梯里，真是地狱！"],["Le métro à huit heures, c'est l'enfer.","早上八点的地铁，简直是地狱。"],["Ces vacances avec la famille, c'était l'enfer.","和家人度过的假期，太折磨人了。"]],"co":[["c'est l'enfer","真是地狱"],["l'enfer sur terre","人间地狱"],["vivre un enfer","过着痛苦的日子"],["aller en enfer","下地狱"]],"sy":[["c'est la galère","familier","真是倒霉、麻烦"],["c'est horrible","courant","真可怕"],["c'est un cauchemar","courant","简直是噩梦"]],"fq":"中高频，口语常用。","me":"l'enfer：想到 inferno，火烧般难受。","tr":{"zh":"周五晚上开车太折磨人了。","fr":"Conduire le vendredi soir, c'est l'enfer.","alt":"Le vendredi soir sur la route, c'est l'enfer !","note":"c'est + 名词，用来下判断。"}},
 "Être de mauvaise/bonne humeur": {"pos":"loc. verbale 动词短语（humeur 为阴性名词，复数 humeurs）","s":"心情不好／心情好。Être de bonne humeur = 心情好；être de mauvaise humeur = 心情不好、脾气差。humeur 是阴性，所以形容词用 bonne / mauvaise。","ipa":"[ɛtʁ.də.mo.vɛz.y.mœʁ]","ph":"mauvaise 读 [mo.vɛz]，au [o]，s 在元音间读 [z]；humeur 的 h 不发音，读 [y.mœʁ]；bonne 读 [bɔn]。","pi":"humeur 的 h 不发音，所以 de bonne humeur 中 bonne 与 humeur 不隔开；mauvaise 里的 s 读 [z]。humeur 是阴性，别写成 bon humeur。","et":"humeur 来自拉丁语 humor（液体）。古人认为体液决定性情，所以后来有「心情」之意；与英语 humor、mood 不同，要小心。","ex":[["Je suis de bonne humeur ce matin.","今天早上我心情很好。"],["Pourquoi es-tu de mauvaise humeur ?","你为什么心情不好？"],["Mon chef est de mauvaise humeur aujourd'hui.","我老板今天心情不好。"]],"co":[["être de bonne / mauvaise humeur","心情好 / 不好"],["être d'humeur à + 动词","有心情做……"],["changer d'humeur","情绪变化"],["avoir de l'humeur","耍脾气"]],"sy":[["être content / contrarié","courant","高兴 / 恼火"],["être grognon","familier","爱发牢骚，不开心"],["avoir le moral","courant","情绪好（与 bon moral 相关）"]],"fq":"高频，日常常用。","me":"humeur 与英语 humor 同形，但意思是「心情」，不是幽默。","tr":{"zh":"他今天心情很好，因为放假了。","fr":"Il est de très bonne humeur aujourd'hui, car il est en vacances.","alt":"Il est de bonne humeur parce qu'il part en vacances.","note":"de + 无冠词的 bonne / mauvaise humeur。"}},
 "Être taillé pour le rôle": {"pos":"loc. verbale 动词短语（taillé 为过去分词作形容词，随主语变化性数）","s":"天生适合这个角色（或这份职位）。字面是「被裁剪得适合这个角色」，指能力、性格或外形正好合适。taillé 要与主语的性数一致：elle est taillée pour le rôle。","ipa":"[ɛtʁ.ta.je.puʁ.lə.ʁol]","ph":"taillé 读 [ta.je]，ill 在这里读 [j]；pour 读 [puʁ]；rôle 的 ô 读 [o]，结尾 le 读 [l]。","pi":"taillé 里的 ill 读 [j]，不要读成 [l]；rôle 的 ô 是闭音 [o]；阴性要加 e：taillée；复数加 s：taillés。","et":"tailler 来自晚期拉丁语 taliare（切、削），由 talea（细枝）演变；rôle 本指演员台词所写的纸卷（rotulus 的小卷）。","ex":[["Il est parfait, il est taillé pour le rôle.","他很完美，天生适合这个角色。"],["Elle est taillée pour ce métier.","她天生适合这个职业。"],["Ils sont taillés pour la course.","他们天生适合跑步。"]],"co":[["être taillé pour + 名词","天生适合……"],["être taillé pour + 动词","适合做……"],["taillé dans le roc","（比喻）坚硬、结实"]],"sy":[["avoir la tête de l'emploi","courant","外表就像那份工作"],["être fait pour","courant","生来就为……"],["être l'homme de la situation","courant","正是合适的人"]],"fq":"中频，常见于口语和媒体。","me":"像量身定做的衣服（tailler 就是裁剪）：刚好合身。","tr":{"zh":"她天生适合当老师。","fr":"Elle est taillée pour être professeure.","alt":"Elle est vraiment faite pour être professeure.","note":"taillée 阴性要加 e，和主语一致。"}},
 "Être têtu comme un âne / Être une tête de mule": {"pos":"loc. verbale 动词短语（têtu 形容词，阴性 têtue；âne 阳性名词；mule 阴性名词）","s":"固执得像驴／像骡子，死不改主意。Être têtu comme un âne 和 être une tête de mule 都是常用说法，含贬义，也可带点亲昵地吐槽。","ipa":"[ɛtʁ.te.ty.kɔm.œ̃.nɑn]","ph":"têtu 读 [te.ty]，ê 在这里读闭音 [e]，u 读 [y]；comme un 连读成 [kɔ.mœ̃]；âne 读 [ɑn]（â 是长音 a）；mule 读 [myl]。","pi":"têtu 的 u 读 [y]，不是 [u]。âne 是 âne，不要写成 ane。阴性 têtue 读音相同。tête de mule 中 mule 的 u 也读 [y]。","et":"têtu 由 tête（头）+ 后缀 -u（有……的）构成，字面是「有头的，认死理的」。âne 来自拉丁语 asinus。","ex":[["Il ne veut pas changer d'avis, il est têtu comme un âne.","他不肯改变主意，倔得像头驴。"],["Ma fille est une vraie tête de mule.","我女儿是个地道的倔脾气。"],["Ne sois pas si têtu !","别这么固执！"]],"co":[["têtu comme une mule","像骡子一样倔"],["avoir la tête dure","脑袋硬，不听劝"],["faire sa tête de mule","耍倔脾气"],["avoir un caractère têtu","性格固执"]],"sy":[["obstiné","soutenu","执着的，固执的"],["entêté","courant","固执的（比 têtu 稍正式）"],["buté","courant","拧着不让步的"]],"fq":"中频，口语常用。","me":"驴和骡子都以「不肯动」闻名：想到它们就记住了。","tr":{"zh":"我弟弟倔得像头驴。","fr":"Mon frère est têtu comme un âne.","alt":"Mon frère est une vraie tête de mule.","note":"têtu 的阴性是 têtue：Elle est têtue。"}},
 "Être/Se sentir bien dans sa peau": {"pos":"loc. verbale 动词短语（peau 为阴性名词，复数 peaux；se sentir 为代词式动词）","s":"自在；对自己满意；觉得做自己很舒服。字面是「在自己的皮肤里感觉好」。反义：être mal dans sa peau（别扭、不自在、自我感觉差）。","ipa":"[sə.sɑ̃.tiʁ.bjɛ̃.dɑ̃.sa.po]","ph":"bien 读 [bjɛ̃]；dans 读 [dɑ̃]，s 不发音；peau 读 [po]，eau 读 [o]；sa 读 [sa]，注意 sa 与 peau 之间的 sa.po。","pi":"peau 只读 [po]，不要读出 a 或 u；dans 的 s 不发音。sa 随着主语变化：dans ma peau / dans ta peau / dans sa peau / dans notre peau。","et":"peau 来自拉丁语 pellis（皮）；se sentir 由 sentir（感觉，拉丁语 sentire）加代词构成。","ex":[["Elle est très confiante, elle se sent bien dans sa peau.","她很自信，对自己很满意。"],["Je ne suis pas bien dans ma peau en ce moment.","最近我觉得不自在。"],["À quarante ans, il est enfin bien dans sa peau.","四十岁了，他终于对自己满意了。"]],"co":[["être bien dans sa peau","自在，对自己满意"],["être mal dans sa peau","别扭，不自在"],["se sentir bien dans sa peau","觉得自在"],["avoir la peau dure","命硬；很顽强（不同的成语）"]],"sy":[["être à l'aise","courant","觉得自在（更广泛）"],["s'assumer","courant","接受自己"],["être épanoui","soutenu","活得充实、舒展"]],"fq":"中高频，日常谈心理状态时常用。","me":"把自己的皮（peau）当成最舒服的衣服：穿着很自在。","tr":{"zh":"自从换了工作，我觉得自在多了。","fr":"Depuis que j'ai changé de travail, je me sens mieux dans ma peau.","alt":"Depuis mon nouveau travail, je suis bien dans ma peau.","note":"sa / ma / ta 要与主语对应。"}},
 "Faire du [taille]": {"pos":"loc. verbale 动词短语（faire + du + 尺码数字，du 是部分冠词 de + le 的缩合）","s":"穿……码（衣服、鞋的尺码）。Je fais du 42 = 我穿 42 码。也可用于问尺码：Vous faites quelle taille ? 注意用 faire，不用 porter 或 avoir。","ipa":"[fɛʁ.dy.tɑj]","ph":"faire 读 [fɛʁ]；du 读 [dy]，u 读 [y]；taille 读 [taj]，ill 读 [j]。","pi":"faire 里的 ai 读 [ɛ]，不是 [ai]；du 的 u 读 [y]。尺码前面用 du，不说 «à» 或 «en»；taille 的 ille 读 [aj]。","et":"faire 来自拉丁语 facere；taille 来自 tailler（切、裁），本义是「裁剪的尺寸」。","ex":[["Je fais du 42.","我穿 42 码。"],["Elle fait du 38 en chaussures.","她的鞋穿 38 码。"],["Tu fais quelle taille ?","你穿几码？"]],"co":[["faire du 38 / du 42","穿 38 码 / 42 码"],["faire du S / du M / du L","穿 S / M / L 码"],["quelle taille faites-vous ?","您穿几码？"],["faire une taille de plus","大一码"]],"sy":[["porter du 42","courant","穿 42 码（同义，稍书面）"],["chausser du 42","courant","鞋穿 42 码（专指鞋）"],["avoir la taille","courant","身材尺寸合适"]],"fq":"中高频，买衣服时常用。","me":"faire du + 数字：你的身体「做出」几码。","tr":{"zh":"我穿 40 码，你呢？","fr":"Je fais du 40, et toi ?","alt":"Moi, je fais du 40. Et toi, tu fais quelle taille ?","note":"faire du + 尺码：口语里最自然。"}},
 "Faire la gueule": {"pos":"loc. verbale 动词短语（gueule 为阴性名词，复数 gueules）","s":"拉长脸；赌气；板着脸不高兴。这是口语里很常见的说法，带有点粗俗的感觉。gueule 本指动物的嘴，用在人身上比较不礼貌，对长辈或陌生人要避免。","ipa":"[fɛʁ.la.gœl]","ph":"gueule 读 [gœl]，gu 里的 u 不发音，ue 与 l 合起来是 [œl]；faire 读 [fɛʁ]。","pi":"gueule 的 g 读 [g]，u 不发音（和 gu-i 类似）；eu 读 [œ]，不是 [u]。此词偏粗俗，正式场合要换成 faire la tête 或 bouder。","et":"gueule 来自拉丁语 gula（喉咙、嘴），本指动物的嘴；用于人时是俚俗的说法。","ex":[["Pourquoi tu fais la gueule ?","你为什么拉着脸？"],["Il fait la gueule depuis ce matin.","他从早上起就一直板着脸。"],["Arrête de faire la gueule, on est en vacances !","别拉着脸了，我们在度假！"]],"co":[["faire la gueule à quelqu'un","对某人摆脸色"],["arrête de faire la gueule","别拉着脸了"],["avoir une sale gueule","长得难看；脸色很差（俗）"],["ferme ta gueule","闭嘴（非常粗鲁）"]],"sy":[["faire la tête","familier","赌气，不理人（较温和）"],["bouder","courant","闹别扭，生闷气"],["être de mauvaise humeur","courant","心情不好（中性说法）"]],"fq":"中高频，仅限口语，偏粗俗。","me":"gueule 是「嘴」，拉长了嘴就是在生气。","tr":{"zh":"你怎么一整天都拉着脸？","fr":"Pourquoi tu fais la gueule toute la journée ?","alt":"Pourquoi tu fais la tête toute la journée ?","note":"faire la gueule 偏粗俗，faire la tête 更温和。"}},
 "Faire un clin d'oeil": {"pos":"loc. verbale 动词短语（un clin d'œil 为阳性名词，复数 des clins d'œil）","s":"眨眼示意；向某人使眼色。多用来表示默契、开玩笑或暗示。Faire un clin d'œil à quelqu'un = 对某人眨眼。clin d'œil 也能指「一瞬间」：en un clin d'œil。","ipa":"[fɛʁ.œ̃.klɛ̃.dœj]","ph":"clin 读鼻化 [klɛ̃]；d'œil 读 [dœj]，œil 读 [œj]；faire 读 [fɛʁ]；un 与 clin 之间要停一下。","pi":"正规写法是 clin d'œil，œ 是一个连写字母；œil 读 [œj]，结尾 l 不读 [l]。复数是 des clins d'œil（œil 不变）。","et":"clin 来自动词 cliner（眨眼，古法语），再加上 œil（眼睛，拉丁语 oculus）。","ex":[["Il me fait un clin d'œil.","他对我眨了眨眼。"],["Elle m'a fait un clin d'œil pour dire merci.","她朝我眨眼表示谢谢。"],["En un clin d'œil, tout était fini.","转眼之间，一切都结束了。"]],"co":[["faire un clin d'œil à quelqu'un","对某人眨眼"],["en un clin d'œil","一眨眼的工夫"],["un clin d'œil complice","会意的一眨眼"],["un petit clin d'œil","小小的暗示、致敬"]],"sy":[["cligner de l'œil","courant","眨眼（动作本身）"],["faire signe","courant","示意（更广）"],["en un instant","courant","一瞬间（对应 en un clin d'œil）"]],"fq":"中频，日常常用。","me":"clin d'œil = 眼睛一「clin」：一眨眼。","tr":{"zh":"她笑着对我眨了眨眼。","fr":"Elle m'a fait un clin d'œil en souriant.","alt":"Elle m'a fait un petit clin d'œil avec un sourire.","note":"faire un clin d'œil à + 人；人称代词放在 faire 前。"}},
 "Faire un signe": {"pos":"loc. verbale 动词短语（signe 为阳性名词，复数 signes）","s":"打个招呼；示意；做个手势。Faire un signe à quelqu'un 可以是挥手、点头，也可以是「联系某人」：Fais-moi un signe（给我个信儿）。","ipa":"[fɛʁ.œ̃.siɲ]","ph":"signe 读 [siɲ]，gn 读 [ɲ]（像「尼」的鼻音），g 不单独读；e 不发音；faire 读 [fɛʁ]。","pi":"signe 里的 gn 读 [ɲ]，不是 [g] + [n]；结尾 e 不发音。signe 是阳性名词：un signe。","et":"signe 来自拉丁语 signum（记号、标记），同源词有 signal、signature、signifier。","ex":[["Fais-moi un signe quand tu arrives.","你到了跟我打个招呼。"],["Il m'a fait un signe de la main.","他朝我挥了挥手。"],["Elle a fait un signe de la tête pour dire oui.","她点头表示同意。"]],"co":[["faire un signe de la main","挥手示意"],["faire un signe de la tête","点头示意"],["faire signe à quelqu'un","联系某人；向某人示意"],["un signe de la main","招手的动作"]],"sy":[["saluer","courant","问候，打招呼"],["donner de ses nouvelles","courant","报个平安"],["faire un geste","courant","做个动作"]],"fq":"高频，日常常用。","me":"signe 与英语 sign 同源：给出一个「记号」。","tr":{"zh":"到家了给我个信儿。","fr":"Fais-moi signe quand tu es rentré.","alt":"Fais-moi un petit signe quand tu es à la maison.","note":"Fais-moi signe 是常用口语，表示「联系我」。"}},
 "Tirer la langue": {"pos":"loc. verbale 动词短语（tirer 为第一组 -er 规则动词，复合时态用 avoir；langue 为阴性名词）","s":"吐舌头；伸出舌头（医生检查时、做鬼脸时）。tirer la langue à quelqu'un 是向某人做鬼脸。比喻义：tirer la langue 也可指「累得吐舌头，非常辛苦或缺钱」。","ipa":"[ti.ʁe.la.lɑ̃ɡ]","ph":"tirer 读 [ti.ʁe]，-er 读 [e]，不发 r；langue 读 [lɑ̃ɡ]，an 读鼻化 [ɑ̃]，gu 里 u 不发音；la 与 langue 之间读 [la.lɑ̃ɡ]。","pi":"tirer 的结尾 r 不发音（读 [e]）；langue 的 gu 读 [ɡ]，u 不发音；an 读鼻化音，不是「安」。langue 既指「舌头」也指「语言」，看上下文。","et":"tirer 的来源不确定；langue 来自拉丁语 lingua，同源词有 linguistique、bilingue。","ex":[["Le docteur me demande de tirer la langue.","医生让我伸出舌头。"],["L'enfant tire la langue à sa sœur.","孩子对姐姐吐舌头。"],["Ce mois-ci, on tire la langue : plus d'argent !","这个月我们手头很紧：没钱了！"]],"co":[["tirer la langue à quelqu'un","对某人吐舌头做鬼脸"],["tirer la langue (比喻)","很辛苦；手头紧"],["tirer les cheveux","扯头发"],["avoir la langue bien pendue","能说会道"]],"sy":[["faire une grimace","courant","做鬼脸"],["tirer le diable par la queue","familier","穷得叮当响"],["être à bout","courant","累到极点"]],"fq":"中频，日常常用。","me":"tirer（拉）+ langue（舌头）：把舌头拉出来。","tr":{"zh":"那个小男孩对我做了个鬼脸。","fr":"Ce petit garçon m'a tiré la langue.","alt":"Le petit garçon m'a fait une grimace en tirant la langue.","note":"tirer la langue à + 人。"}},
 "Tous les jours": {"pos":"loc. adv. 副词短语（tous 为 tout 的阳性复数形式；jour 为阳性名词）","s":"每天；天天。表示每一天都发生的习惯。tous les jours 和 chaque jour 差不多，tous les jours 在口语里更常用。","ipa":"[tus.le.ʒuʁ]","ph":"tous 这里读 [tus]，s 要发音（作形容词时 tous 读 [tu]，作代词时读 [tus]）；les 读 [le]；jours 读 [ʒuʁ]，结尾 s 不发音。","pi":"tous les jours 里的 tous 作限定词，实际读 [tu]：[tu.le.ʒuʁ]；jours 的 s 不发音。别写成 tout les jours 或 tout le jours。","et":"tous 来自拉丁语 totus（全部）；jour 来自拉丁语 diurnus（白天的），同源词有 journal。","ex":[["Je bois du café tous les jours.","我每天喝咖啡。"],["Elle fait du sport tous les jours.","她每天做运动。"],["Ouvert tous les jours sauf le lundi.","除周一外每天营业。"]],"co":[["tous les jours","每天"],["tous les deux jours","每两天一次"],["tous les matins / tous les soirs","每天早上 / 每天晚上"],["de tous les jours","日常的"]],"sy":[["chaque jour","courant","每天（略正式）"],["quotidiennement","soutenu","每日地（书面）"],["chaque matin","courant","每天早上"]],"fq":"极高频，日常常用。","me":"tous + les + jours：「所有的日子」就是每天。","tr":{"zh":"我们每天都在同一家咖啡馆见面。","fr":"On se retrouve tous les jours dans le même café.","alt":"Tous les jours, on se voit au même café.","note":"tous les + 复数名词：每个……。"}},
 "Tout le monde": {"pos":"pron. indéf. 不定代词，单数（语法上按第三人称单数处理）","s":"所有人；大家；每个人。注意：虽然意思是「大家」，动词要用第三人称单数：Tout le monde est là，不是 sont。le monde 本义是「世界」，在这里固定指「人们」。","ipa":"[tu.lə.mɔ̃d]","ph":"tout 读 [tu]，结尾 t 不发音（只在联诵时发）；monde 读 [mɔ̃d]，on 读鼻化 [ɔ̃]，d 要发音。","pi":"动词用单数：Tout le monde est content，不要说 sont。形容词也用单数：Tout le monde est fatigué。monde 的 d 要发音 [d]，tout 的 t 不发音。","et":"tout 来自拉丁语 totus；monde 来自拉丁语 mundus（宇宙、世界）。","ex":[["Tout le monde est là.","大家都在。"],["Bonjour à tout le monde !","大家好！"],["Tout le monde aime le chocolat.","人人都爱巧克力。"]],"co":[["tout le monde est là","所有人都在"],["comme tout le monde","和大家一样"],["pas tout le monde","不是所有人"],["tout le monde sait que…","人人都知道……"]],"sy":[["chacun","courant","每个人（强调个体）"],["tous","courant","所有人（作代词，读 [tus]）"],["personne","courant","没有人（反义）"]],"fq":"极高频，日常常用。","me":"tout le monde = 整个世界的人，但动词只认「一个世界」，所以用单数。","tr":{"zh":"大家都很开心。","fr":"Tout le monde est content.","alt":"Tout le monde est heureux.","note":"tout le monde 后动词和形容词都用单数。"}},
 "Tout le temps": {"pos":"loc. adv. 副词短语（temps 为阳性名词，单复数同形）","s":"一直；总是；老是。表示不间断或非常频繁，常带点抱怨：Il parle tout le temps（他老是说个不停）。不要和 tous les temps 混淆。","ipa":"[tu.lə.tɑ̃]","ph":"tout 读 [tu]；le 弱读 [lə]；temps 读 [tɑ̃]，em 读鼻化 [ɑ̃]，p 和 s 都不发音。","pi":"temps 的 p 和 s 都不发音；整个短语读 [tu.lə.tɑ̃]。别写成 tout les temps 或 tous le temps。","et":"tout 来自拉丁语 totus；temps 来自拉丁语 tempus（时间），同源词有 temporel。","ex":[["Il parle tout le temps.","他一直在说话。"],["Elle regarde son téléphone tout le temps.","她老是看手机。"],["Je pense à toi tout le temps.","我一直在想你。"]],"co":[["tout le temps","一直；总是"],["tout le temps du monde","有的是时间"],["en même temps","同时"],["de temps en temps","有时候；偶尔"]],"sy":[["toujours","courant","总是（更中性）"],["sans arrêt","courant","不停地"],["en permanence","soutenu","持续地，长期地"]],"fq":"极高频，日常常用。","me":"tout le temps：所有的时间都用上了，也就是一直。","tr":{"zh":"我儿子老是饿。","fr":"Mon fils a faim tout le temps.","alt":"Mon fils a toujours faim.","note":"tout le temps 放在句尾最自然。"}},
 "Du métal": {"pos":"n.m. 阳性名词，复数 métaux（-al 变 -aux）；du 是部分冠词（de + le）","s":"金属。不可数时用部分冠词 du métal（一种材料）；可数时指某一种金属：un métal précieux（贵金属）。Cette boîte est en métal = 这个盒子是金属做的。","ipa":"[me.tal]","ph":"é 读 [e]；a 读 [a]；结尾 l 要发音 [l]；重音落在最后一个音节。","pi":"复数是 métaux，不是 métals。结尾 l 要发音。du métal 里 du 读 [dy]，u 读 [y]。metal 这个英语词也指重金属音乐，法语 le métal 也有这个用法。","et":"来自拉丁语 metallum，又来自希腊语 metallon（矿井、矿石）；与英语 metal 同源。","ex":[["Cette boîte est en métal.","这个盒子是金属的。"],["Le fer est un métal.","铁是一种金属。"],["J'aime la musique métal.","我喜欢金属音乐。"]],"co":[["en métal","金属制的"],["un métal précieux","贵金属"],["un détecteur de métaux","金属探测器"],["du métal lourd / heavy metal","重金属音乐"]],"sy":[["l'acier","courant","钢（一种合金）"],["le fer","courant","铁"],["l'alliage","soutenu","合金"]],"fq":"中频，日常和科学里都常用。","me":"与英语 metal 几乎一样，只是 é 带重音。","tr":{"zh":"这把钥匙是金属做的。","fr":"Cette clé est en métal.","alt":"Cette clé est faite en métal.","note":"材料用 en：en métal / en bois。"}},
 "L'espace": {"pos":"n.m. 阳性名词，复数 espaces；l' 是 le 的省音","s":"空间；太空；间隔。l'espace 单独用常指太空（l'espace = outer space）；un espace 则是某个空间、场地或间隔：un espace vert（绿地）。","ipa":"[ɛs.pas]","ph":"es 读 [ɛs]；p 要发音；ace 读 [as]，c 在 e 前读 [s]；结尾 e 不发音；l' 与 espace 连读：[lɛs.pas]。","pi":"espace 是阳性名词，不要说 une espace（印刷术语 une espace 是阴性，但那是另一个意思：字距）。结尾 e 不发音。","et":"来自拉丁语 spatium（空间、距离），同源词有 spatial、spacieux。","ex":[["Les étoiles sont dans l'espace.","星星在太空里。"],["Il n'y a pas assez d'espace ici.","这里没有足够的空间。"],["Cette ville a beaucoup d'espaces verts.","这座城市有很多绿地。"]],"co":[["l'espace (extra-atmosphérique)","太空"],["un espace vert","绿地，公园"],["l'espace de travail","工作空间"],["manquer d'espace","空间不够"]],"sy":[["la place","courant","空位，位置"],["le cosmos","soutenu","宇宙"],["la distance","courant","距离"]],"fq":"高频，日常和科学里都常用。","me":"与英语 space 同源：去掉 e 和 ace 对应 space。","tr":{"zh":"宇航员在太空中工作。","fr":"Les astronautes travaillent dans l'espace.","alt":"Les astronautes sont en mission dans l'espace.","note":"dans l'espace：在太空里。"}},
 "Le futur": {"pos":"n.m. 阳性名词，复数 futurs；也作形容词 futur / future","s":"未来；将来。le futur 也是语法里的「将来时」。dans le futur = 在未来。作形容词时放在名词前或后：le futur président（未来的总统），ma future femme（我未来的妻子）。","ipa":"[fy.tyʁ]","ph":"两个 u 都读 [y]（嘴唇圆起）；r 是小舌音 [ʁ]，结尾 r 要发音。","pi":"两个 u 都读 [y]，不是 [u]。结尾 r 要发。le futur 是名词，l'avenir 是更日常的「前途」的说法。","et":"来自拉丁语 futurus（将要……的），是 esse（是）的将来分词，与英语 future 同源。","ex":[["Le futur est plein de surprises.","未来充满惊喜。"],["Dans un futur proche, tout changera.","在不久的将来，一切都会改变。"],["Il pense à son futur métier.","他在想自己将来的职业。"]],"co":[["dans un futur proche","在不久的将来"],["dans le futur","在未来"],["le futur simple","简单将来时"],["le futur proche","近将来时（aller + 动词）"]],"sy":[["l'avenir","courant","未来、前途（更常用）"],["demain","courant","明天；将来"],["le passé","courant","过去（反义）"]],"fq":"高频，日常和语法里都常见。","me":"两个 u：futur 要念 [fy.tyʁ]，嘴唇都要圆。","tr":{"zh":"我想知道未来会是什么样。","fr":"Je me demande comment sera le futur.","alt":"Je me demande ce que le futur nous réserve.","note":"se demander comment + 将来时/条件式。"}},
 "Le passé": {"pos":"n.m. 阳性名词，复数 passés；也作形容词 passé / passée，和过去分词同形","s":"过去；往事；语法里的「过去时」。le passé = 过去那段时间。作介词用：passé minuit（过了午夜）。passé composé 是复合过去时。","ipa":"[pa.se]","ph":"pa 读 [pa]；ss 读 [s]；结尾 é 读 [e]。","pi":"ss 读 [s]，不是 [z]；结尾 é 读 [e]，不是「瑞」。le passé 与 passer（经过，度过）同源，注意拼写。","et":"passer 来自拉丁语 passus（步、步伐），le passé 是它的过去分词名词化；同源词有 passage、passeport。","ex":[["J'aime lire des histoires sur le passé.","我喜欢读关于过去的故事。"],["Il pense trop au passé.","他总是想着过去。"],["Le passé composé se forme avec avoir ou être.","复合过去时用 avoir 或 être 构成。"]],"co":[["dans le passé","在过去"],["le passé composé","复合过去时"],["par le passé","以前；过去曾经"],["tourner la page du passé","翻过过去的一页"]],"sy":[["l'histoire","courant","历史"],["autrefois","soutenu","从前（副词）"],["le futur","courant","未来（反义）"]],"fq":"高频，日常和语法里都常见。","me":"passé：「走过去了」的时间。","tr":{"zh":"我们别再谈过去了。","fr":"Ne parlons plus du passé.","alt":"On ne parle plus du passé, d'accord ?","note":"parler de + le → du：du passé。"}},
 "Le présent": {"pos":"n.m. 阳性名词，复数 présents；也作形容词 présent / présente（在场的）","s":"现在；当下；语法里的「现在时」。vivre dans le présent = 活在当下。作形容词时是「在场的」：Il est présent à la réunion。注意：un présent 还可作「礼物」，较书面。","ipa":"[pʁe.zɑ̃]","ph":"pr 读 [pʁ]；é 读 [e]；s 在元音间读 [z]；结尾 -ent 读鼻化 [ɑ̃]，t 不发音。","pi":"-ent 在这里读 [ɑ̃]，t 不发音；s 读 [z]，不是 [s]。现在时是 le présent，不要和英语 present（礼物）直接对译：礼物日常用 un cadeau。","et":"来自拉丁语 praesens（在场的），由 prae（在前）+ esse（是）构成，与英语 present 同源。","ex":[["Nous vivons dans le présent.","我们活在当下。"],["Au présent, il est médecin.","现在他是医生。"],["Tous les élèves sont présents.","所有学生都在场。"]],"co":[["à présent","现在；目前"],["le présent de l'indicatif","直陈式现在时"],["jusqu'à présent","到目前为止"],["vivre au présent","活在当下"]],"sy":[["maintenant","courant","现在（副词）"],["actuellement","courant","目前（副词）"],["le cadeau","courant","礼物（不要用 présent 说礼物）"]],"fq":"高频，日常和语法里都常见。","me":"présent：此时此地「在场」的时间。","tr":{"zh":"到目前为止，一切顺利。","fr":"Jusqu'à présent, tout va bien.","alt":"Pour l'instant, tout va bien.","note":"jusqu'à présent 是固定搭配。"}},
 "Le système solaire": {"pos":"n.m. 阳性名词，复数 systèmes solaires（solaire 是形容词，阴阳同形）","s":"太阳系：太阳和围绕它转的行星、卫星等。法语里 système 是阳性名词，虽然以 -e 结尾。le système solaire 常与 les planètes（行星）连用。","ipa":"[sis.tɛm.sɔ.lɛʁ]","ph":"système 读 [sis.tɛm]，è 读 [ɛ]，y 读 [i]；solaire 读 [sɔ.lɛʁ]，ai 读 [ɛ]，结尾 r 要发。","pi":"système 以 -e 结尾却是阳性：un système。système 的 y 读 [i]；solaire 的 ai 读 [ɛ]，结尾 r 要发音。","et":"système 来自希腊语 sustēma（组合），solaire 来自拉丁语 solaris，由 sol（太阳）而来。","ex":[["La Terre est dans le système solaire.","地球在太阳系里。"],["Huit planètes tournent autour du Soleil dans le système solaire.","太阳系里有八颗行星绕着太阳转。"],["Mars est une planète du système solaire.","火星是太阳系的一颗行星。"]],"co":[["une planète du système solaire","太阳系的一颗行星"],["dans le système solaire","在太阳系中"],["étudier le système solaire","研究太阳系"],["hors du système solaire","太阳系之外"]],"sy":[["la galaxie","courant","星系（比太阳系大）"],["l'univers","courant","宇宙"],["le cosmos","soutenu","宇宙；太空"]],"fq":"中频，科学、地理课里常见。","me":"système（体系）+ solaire（太阳的）= 太阳家族。","tr":{"zh":"木星是太阳系中最大的行星。","fr":"Jupiter est la plus grande planète du système solaire.","alt":"Dans le système solaire, Jupiter est la planète la plus grosse.","note":"la plus grande + 名词：最高级。"}},
 "Un appareil": {"pos":"n.m. 阳性名词，复数 appareils","s":"设备；器械；仪器；家电。泛指某种有用途的机器：un appareil photo（照相机）、un appareil électrique（电器）。也指牙套（un appareil dentaire）。","ipa":"[a.pa.ʁɛj]","ph":"pp 读一个 [p]；-eil 读 [ɛj]，结尾 l 不读 [l]；r 是小舌音。","pi":"appareil 的 pp 只读一个 [p]；-eil 读 [ɛj]，不是 [ɛl]。appareil 是阳性，不要说 une appareil。","et":"来自动词 appareiller（装备、准备），源自拉丁语 apparare（准备、安排），同源词有 appareil photo。","ex":[["C'est un appareil très utile.","这是个很有用的设备。"],["Je prends une photo avec mon appareil.","我用我的相机拍照。"],["Cet appareil ne marche plus.","这个设备坏了，不能用了。"]],"co":[["un appareil photo","照相机"],["un appareil électrique","电器"],["un appareil dentaire","牙套"],["un appareil auditif","助听器"]],"sy":[["une machine","courant","机器（更泛）"],["un outil","courant","工具"],["un gadget","familier","小玩意儿"]],"fq":"高频，日常常用。","me":"appareil 里有 pareil（相同）：同一套「配好的」东西。","tr":{"zh":"这个设备怎么用？","fr":"Comment fonctionne cet appareil ?","alt":"Comment on utilise cet appareil ?","note":"fonctionner：运转，用于机器。"}},
 "Un drapeau": {"pos":"n.m. 阳性名词，复数 drapeaux（-eau 的复数加 x）","s":"旗帜；国旗。le drapeau français 是蓝白红三色旗。比喻中 sous le drapeau 指在军队服役。更小的旗或三角旗用 un fanion。","ipa":"[dʁa.po]","ph":"dr 读 [dʁ]；eau 读 [o]；整个词读 [dʁa.po]；结尾不发音。","pi":"复数是 drapeaux，不是 drapeaus。eau 只读 [o]。别和 drap（床单）混淆：drapeau 是旗，drap 是布。","et":"来自 drap（布、织物），加指小后缀 -eau，字面是「一小块布」。","ex":[["Le drapeau est bleu, blanc, rouge.","旗是蓝白红三色。"],["Ils agitent des drapeaux dans le stade.","他们在体育场里挥舞旗帜。"],["Chaque pays a son drapeau.","每个国家都有自己的国旗。"]],"co":[["le drapeau français","法国国旗"],["hisser le drapeau","升旗"],["un drapeau blanc","白旗"],["mettre le drapeau en berne","降半旗"]],"sy":[["l'étendard","littéraire","军旗，旗帜（书面）"],["la bannière","soutenu","旗帜；横幅"],["le fanion","courant","小三角旗"]],"fq":"中高频，日常常用。","me":"drap（布）+ eau：一小块布，挂起来就是旗。","tr":{"zh":"国旗在学校门口。","fr":"Le drapeau est devant l'école.","alt":"Il y a un drapeau à l'entrée de l'école.","note":"devant 表示在……前面。"}},
 "Un GPS": {"pos":"n.m. 阳性名词，不变（缩写词，复数仍写 des GPS）","s":"GPS 导航仪；全球定位系统。法语里读字母：「热-佩-艾斯」。可以指车载导航仪或手机里的导航功能：suivre le GPS（跟着导航走）。","ipa":"[ʒe.pe.ɛs]","ph":"按字母读：G [ʒe]，P [pe]，S [ɛs]；三个字母连读成一个词。","pi":"法语字母 G 读 [ʒe]，不是英语的 [dʒi]；P 读 [pe]；S 读 [ɛs]。所以 GPS 读 [ʒe.pe.ɛs]。是阳性：un GPS。","et":"缩写自英语 Global Positioning System（全球定位系统），借用并按法语字母读音。","ex":[["Utilise le GPS pour trouver la route.","用 GPS 找路。"],["Mon GPS ne marche plus.","我的导航坏了。"],["Je suis le GPS depuis une heure.","我跟着导航走了一个小时。"]],"co":[["suivre le GPS","跟着导航走"],["un GPS de voiture","车载导航"],["mettre l'adresse dans le GPS","把地址输入导航"],["se fier au GPS","相信导航"]],"sy":[["un navigateur","courant","导航仪"],["une carte","courant","地图"],["un plan","courant","（城市）平面图"]],"fq":"高频，日常常用。","me":"读字母：热-佩-艾斯，别用英语读法。","tr":{"zh":"我的导航说要往左转。","fr":"Mon GPS dit de tourner à gauche.","alt":"D'après mon GPS, il faut tourner à gauche.","note":"tourner à gauche：向左转。"}},
 "Un hologramme": {"pos":"n.m. 阳性名词，复数 hologrammes","s":"全息图；全息影像：用激光拍出的立体图像。也指信用卡、证件上防伪的小标志。近几年也常说 un hologramme 的演唱会、讲座。","ipa":"[ɔ.lɔ.ɡʁam]","ph":"h 不发音；o 读开音 [ɔ]；gr 读 [ɡʁ]；结尾 mme 读 [m]，e 不发音；重音落在最后音节。","pi":"h 不发音，所以 un hologramme 要联诵：[œ̃.nɔ.lɔ.ɡʁam]；两个 o 都读开音 [ɔ]；mm 只读一个 [m]。","et":"来自希腊语 holos（整体）+ gramma（写下的东西），字面是「完整的记录」。同源词有 télégramme、programme。","ex":[["J'ai vu un hologramme au musée.","我在博物馆看到了全息图。"],["La carte bancaire a un petit hologramme.","银行卡上有一个小全息标志。"],["Le chanteur est apparu en hologramme.","歌手以全息影像的形式出现。"]],"co":[["un hologramme en 3D","三维全息图"],["en hologramme","以全息影像的形式"],["projeter un hologramme","投射全息影像"],["un hologramme de sécurité","防伪全息标"]],"sy":[["une projection","courant","投影"],["une image 3D","courant","三维图像"],["un reflet","courant","倒影，反光"]],"fq":"中低频，科技话题里出现。","me":"holo（整体）+ gramme（写）：把「整个」物体写下来。","tr":{"zh":"孩子们很喜欢这个全息影像。","fr":"Les enfants adorent cet hologramme.","alt":"Cet hologramme plaît beaucoup aux enfants.","note":"adorer + 名词：非常喜欢。"}},
 "Un logiciel": {"pos":"n.m. 阳性名词，复数 logiciels","s":"软件；应用程序。un logiciel 是计算机里装的程序，例如文字处理软件。复数 des logiciels；一个软件包也可说 une application（手机 app）或 un programme。","ipa":"[lɔ.ʒi.sjɛl]","ph":"lo 读开音 [lɔ]；gi 读 [ʒi]，g 在 i 前读 [ʒ]；ciel 读 [sjɛl]，结尾 l 要发音。","pi":"g 在 i 前读 [ʒ]，不是 [g]；ciel 读 [sjɛl]，结尾 l 要发。注意不要说 un software，法语用 un logiciel。","et":"由 logique（逻辑）与 matériel（硬件）合成的新词（1970 年代），故与 matériel 相对：logiciel = 软件，matériel = 硬件。","ex":[["J'installe un nouveau logiciel.","我安装一个新软件。"],["Ce logiciel est gratuit.","这个软件是免费的。"],["Mon ordinateur a besoin d'une mise à jour du logiciel.","我的电脑需要更新软件。"]],"co":[["installer un logiciel","安装软件"],["un logiciel libre","开源软件"],["mettre à jour un logiciel","更新软件"],["un logiciel de traitement de texte","文字处理软件"]],"sy":[["un programme","courant","程序（更泛）"],["une application","courant","应用（多指手机 app）"],["le matériel","courant","硬件（反义）"]],"fq":"高频，日常和工作里常用。","me":"logiciel：由 logique 而来，就是「逻辑」的东西，看不见摸不着。","tr":{"zh":"你用哪个软件做视频？","fr":"Quel logiciel utilises-tu pour faire des vidéos ?","alt":"Tu fais tes vidéos avec quel logiciel ?","note":"Quel + 阳性名词：Quel logiciel。"}},
 "Un paiement": {"pos":"n.m. 阳性名词，复数 paiements","s":"付款；支付。强调付钱这个动作或手续：le paiement par carte（刷卡付款）。也可写作 payement（旧写法，少用）。动词是 payer。","ipa":"[pɛ.mɑ̃]","ph":"ai 读 [ɛ]；整词读 [pɛ.mɑ̃]，中间没有 [j] 音；-ment 读鼻化 [ɑ̃]，t 不发音。","pi":"paiement 读 [pɛ.mɑ̃]，没有 [j] 的音；-ment 读 [mɑ̃]，t 不发音。拼写别漏 i：paiement，不是 payement（旧式）。","et":"来自动词 payer（付款，拉丁语 pacare「使平静、满足」）加后缀 -ment，表示动作。","ex":[["Le paiement est rapide.","付款很快。"],["Le paiement se fait par carte.","用银行卡付款。"],["Le paiement en ligne est sécurisé.","网上支付是安全的。"]],"co":[["le paiement par carte","刷卡支付"],["le paiement en ligne","网上支付"],["le paiement en espèces","现金支付"],["effectuer un paiement","完成一次付款"]],"sy":[["le règlement","soutenu","结算；付款（较正式）"],["le versement","soutenu","汇款；缴款"],["l'achat","courant","购买"]],"fq":"高频，购物、网络里常用。","me":"payer + -ment = 「付款」这个动作。","tr":{"zh":"你想用哪种方式付款？","fr":"Quel mode de paiement préférez-vous ?","alt":"Vous voulez payer comment ?","note":"mode de paiement：付款方式。"}},
 "Un proche": {"pos":"n.m. 阳性名词，复数 proches（多用复数 les proches）；也作形容词 proche","s":"亲近的人；家人和密友。常用复数：mes proches = 我的亲人和好友。比 membre de la famille 更宽，包括亲近的朋友。形容词 proche 意为「近的」。","ipa":"[pʁɔʃ]","ph":"pr 读 [pʁ]；o 读开音 [ɔ]；ch 读 [ʃ]；结尾 e 不发音。","pi":"ch 读 [ʃ]，不是 [tʃ]；o 是开音 [ɔ]，不要读成 [o]。名词 un proche 是阳性，女性也可用 une proche（少见）。","et":"来自拉丁语 propius（更近），是 prope（近）的比较级；同源词有 approcher（靠近）。","ex":[["Je passe du temps avec un proche.","我和一位亲人共度时光。"],["Il a perdu un proche l'an dernier.","他去年失去了一位亲人。"],["Je ne dis rien à mes proches.","我对亲近的人什么都没说。"]],"co":[["un proche (de la famille)","亲近的人"],["mes proches","我的亲友"],["être proche de","与……亲近；靠近"],["un parent proche","近亲"]],"sy":[["un ami","courant","朋友"],["un parent","courant","亲戚（或父母）"],["l'entourage","soutenu","周围的亲友"]],"fq":"中频，日常和新闻里常见。","me":"proche = 离你「近」的人。","tr":{"zh":"我想把这个好消息告诉我的亲友。","fr":"Je veux annoncer cette bonne nouvelle à mes proches.","alt":"Je veux dire cette bonne nouvelle à mes proches.","note":"mes proches：多用复数。"}},
 "Un robot": {"pos":"n.m. 阳性名词，复数 robots","s":"机器人。可以是工厂里的机械臂、家里的扫地机，也可以是科幻里的机器人。un robot de cuisine 是厨房料理机。形容词用 robotisé。","ipa":"[ʁɔ.bo]","ph":"r 是小舌音 [ʁ]；o 读开音 [ɔ]；bot 里的 t 不发音，ot 读 [o]。","pi":"结尾 -ot 读 [o]，t 不发音；r 是小舌音，不是中文的「r」。第一个 o 读 [ɔ]，第二个读 [o]。","et":"来自捷克语 robota（强制劳动），1920 年由剧作家恰佩克的戏剧传入，各语言通用。","ex":[["Ce robot fait le ménage.","这个机器人做家务。"],["Un robot aide à la cuisine.","一个机器人在厨房帮忙。"],["On voit des robots dans cette usine.","这家工厂里有很多机器人。"]],"co":[["un robot ménager","家用机器人"],["un robot de cuisine","料理机"],["un robot aspirateur","扫地机器人"],["un robot industriel","工业机器人"]],"sy":[["un automate","soutenu","自动机，自动装置"],["un androïde","soutenu","人形机器人"],["une machine","courant","机器"]],"fq":"高频，日常和科技话题里常用。","me":"与英语 robot 同源，但读法是 [ʁɔ.bo]。","tr":{"zh":"这个机器人会说三种语言。","fr":"Ce robot parle trois langues.","alt":"Ce robot sait parler trois langues.","note":"parler + 语言，不加冠词。"}},
 "Un salon": {"pos":"n.m. 阳性名词，复数 salons","s":"1. 展会；博览会（le salon du livre）。2. 客厅（家里的起居室，也说 le séjour）。3. 沙龙；美发店（salon de coiffure）。注意：「客厅」和「展会」是同一个词。","ipa":"[sa.lɔ̃]","ph":"sa 读 [sa]；lon 读鼻化 [lɔ̃]，n 不发音。","pi":"-on 读鼻化 [ɔ̃]，不要读出 n。salon 和 sale（脏的）、salle（厅）容易混淆：salle à manger（餐厅），salon（客厅）。","et":"来自意大利语 salone（大厅），是 sala（厅）的加大形式；法语里 salle 与 salon 同源。","ex":[["Je vais au salon de l'agriculture à Paris.","我去巴黎的农业展。"],["Nous regardons la télé dans le salon.","我们在客厅看电视。"],["Elle va au salon de coiffure.","她去美发店。"]],"co":[["le salon de l'auto","车展"],["le salon du livre","书展"],["un salon de coiffure","美发店"],["un salon de thé","茶室"]],"sy":[["le séjour","courant","起居室（客厅）"],["la salle de séjour","courant","起居室"],["l'exposition","courant","展览"]],"fq":"高频，日常常用。","me":"salon 来自大厅 salle：客厅和展会都是「大厅」。","tr":{"zh":"我们在客厅等你。","fr":"On t'attend dans le salon.","alt":"On est dans le salon, viens nous rejoindre.","note":"dans le salon：在客厅里。"}},
 "L'énergie solaire": {"pos":"n.f. 阴性名词（énergie 阴性，复数 énergies；solaire 形容词，阴阳同形）","s":"太阳能：来自阳光的能源。énergie 以元音开头，所以 la 变 l'。常和 les panneaux solaires（太阳能板）连用。属于 énergie renouvelable（可再生能源）。","ipa":"[e.nɛʁ.ʒi.sɔ.lɛʁ]","ph":"é 读 [e]；ner 读 [nɛʁ]；gie 读 [ʒi]，g 在 i 前读 [ʒ]；solaire 读 [sɔ.lɛʁ]，ai 读 [ɛ]。","pi":"énergie 开头的 é 有重音；g 读 [ʒ]；energie 结尾 e 不发音。énergie 是阴性，所以是 l'énergie solaire，形容词 solaire 阴阳同形。","et":"énergie 来自希腊语 energeia（活动、力量）；solaire 来自拉丁语 solaris，由 sol（太阳）而来。","ex":[["L'énergie solaire est écologique.","太阳能很环保。"],["Cette maison utilise l'énergie solaire.","这座房子使用太阳能。"],["Les panneaux captent l'énergie solaire.","这些板子吸收太阳能。"]],"co":[["un panneau solaire","太阳能板"],["l'énergie renouvelable","可再生能源"],["produire de l'énergie solaire","生产太阳能"],["l'énergie éolienne","风能"]],"sy":[["l'énergie renouvelable","courant","可再生能源（更大的类别）"],["l'énergie nucléaire","courant","核能（对比）"],["l'électricité","courant","电"]],"fq":"中频，环保、科技话题里常见。","me":"solaire 来自 sol（太阳）：想到 Soleil。","tr":{"zh":"太阳能比煤更环保。","fr":"L'énergie solaire est plus écologique que le charbon.","alt":"L'énergie solaire pollue moins que le charbon.","note":"plus ... que：比较级。"}},
 "L'intelligence artificielle (IA)": {"pos":"n.f. 阴性名词（intelligence 阴性，artificielle 为阴性形容词；IA 为缩写）","s":"人工智能。缩写 IA 读字母 [i.a]。一般指能做判断、生成文字或图像的计算机系统。注意英语缩写是 AI，法语是 IA（顺序相反）。","ipa":"[ɛ̃.tɛ.li.ʒɑ̃s.aʁ.ti.fi.sjɛl]","ph":"in 读鼻化 [ɛ̃]；gence 读 [ʒɑ̃s]；artificielle 读 [aʁ.ti.fi.sjɛl]，ci 读 [sj]，-elle 读 [ɛl]；IA 读 [i.a]。","pi":"法语缩写是 IA，不是 AI；intelligence 与 artificielle 都要用阴性。artificielle 里 ti 读 [ti]，ci 读 [sj]，别混。","et":"intelligence 来自拉丁语 intelligentia（理解力），由 inter（在……之间）+ legere（挑选、阅读）；artificiel 来自 art（人工、技艺）。","ex":[["L'intelligence artificielle est fascinante.","人工智能很迷人。"],["L'IA aide beaucoup de gens au travail.","人工智能在工作中帮助很多人。"],["Cette application utilise l'intelligence artificielle.","这个应用使用了人工智能。"]],"co":[["l'IA générative","生成式人工智能"],["utiliser l'IA","使用人工智能"],["un outil d'IA","人工智能工具"],["les risques de l'IA","人工智能的风险"]],"sy":[["l'apprentissage automatique","soutenu","机器学习（更专业）"],["un robot","courant","机器人"],["un algorithme","courant","算法"]],"fq":"高频，近年新闻、日常里很常见。","me":"法语缩写是 IA（intelligence artificielle），和英语 AI 顺序相反。","tr":{"zh":"人工智能会改变我们的工作。","fr":"L'intelligence artificielle va changer notre travail.","alt":"L'IA va transformer notre façon de travailler.","note":"aller + 动词原形：近将来。"}},
 "La reconnaissance faciale": {"pos":"n.f. 阴性名词（reconnaissance 阴性；faciale 为 facial 的阴性形式，阳性复数 faciaux）","s":"人脸识别：用摄像头识别一个人的脸。用于手机解锁、门禁和安检。reconnaissance 也可表示「感激」（avoir de la reconnaissance），要看上下文。","ipa":"[ʁə.kɔ.nɛ.sɑ̃s.fa.sjal]","ph":"re 读 [ʁə]；connaissance 读 [kɔ.nɛ.sɑ̃s]，ai 读 [ɛ]，-ance 读 [ɑ̃s]；faciale 读 [fa.sjal]，ci 读 [sj]。","pi":"connaissance 里 nn 只读一个 [n]；ai 读 [ɛ]；faciale 的 c 读 [s]。注意 reconnaissance 是阴性，所以是 la reconnaissance faciale。","et":"reconnaissance 来自 reconnaître（认出），由 re-（再）+ connaître（认识，拉丁语 cognoscere）；facial 来自拉丁语 facies（脸）。","ex":[["Mon téléphone a la reconnaissance faciale.","我的手机有人脸识别。"],["La reconnaissance faciale ouvre la porte.","人脸识别可以开门。"],["Certains pays limitent la reconnaissance faciale.","有些国家限制人脸识别。"]],"co":[["activer la reconnaissance faciale","启用人脸识别"],["un système de reconnaissance faciale","人脸识别系统"],["la reconnaissance vocale","语音识别"],["la reconnaissance des formes","图像识别"]],"sy":[["l'identification","soutenu","识别；鉴定"],["la biométrie","soutenu","生物识别"],["le déverrouillage","courant","解锁"]],"fq":"中频，科技话题里常见。","me":"re + connaître：再次「认出」+ 脸（face）。","tr":{"zh":"我用人脸识别解锁手机。","fr":"Je déverrouille mon téléphone avec la reconnaissance faciale.","alt":"J'ouvre mon téléphone grâce à la reconnaissance faciale.","note":"avec / grâce à + 名词：借助……。"}},
 "La santé mentale": {"pos":"n.f. 阴性名词（santé 阴性，不可数；mentale 为 mental 的阴性形式，阳性复数 mentaux）","s":"心理健康。santé 是「健康」；mentale 表示精神的、心理的。常和 la santé physique（身体健康）对比。prendre soin de sa santé mentale = 关心自己的心理健康。","ipa":"[sɑ̃.te.mɑ̃.tal]","ph":"santé 读 [sɑ̃.te]，an 读鼻化 [ɑ̃]，é 读 [e]；mentale 读 [mɑ̃.tal]，en 读鼻化 [ɑ̃]，a 读 [a]，l 要发音。","pi":"两个鼻化音 [ɑ̃] 都不要读出 n；mentale 的 e 不发音；mental 阳性复数是 mentaux，不是 mentals。","et":"santé 来自拉丁语 sanitas（健康），同源词有 sanitaire；mental 来自拉丁语 mens（心、思想）。","ex":[["La santé mentale est importante.","心理健康很重要。"],["Il prend soin de sa santé mentale.","他很注意自己的心理健康。"],["Le sport aide la santé mentale.","运动有益于心理健康。"]],"co":[["la santé mentale","心理健康"],["prendre soin de sa santé mentale","关爱心理健康"],["un problème de santé mentale","心理健康问题"],["la santé physique","身体健康"]],"sy":[["le bien-être","courant","幸福感，舒适"],["le moral","courant","情绪，士气"],["la psychologie","courant","心理学"]],"fq":"中频，新闻和日常里越来越常见。","me":"santé（健康）+ mentale（心灵的）= 心灵的健康。","tr":{"zh":"睡眠对心理健康很重要。","fr":"Le sommeil est important pour la santé mentale.","alt":"Bien dormir, c'est bon pour la santé mentale.","note":"important pour + 名词。"}},
 "La science-fiction": {"pos":"n.f. 阴性名词（science 阴性，fiction 阴性；带连字符，复合名词，复数 sciences-fictions，较少用）","s":"科幻：科幻小说、电影等类型。常缩写为 SF（读 [ɛs.ɛf]）。un film de science-fiction = 科幻电影；un roman de science-fiction = 科幻小说。","ipa":"[sjɑ̃s.fik.sjɔ̃]","ph":"science 读 [sjɑ̃s]，sc 读 [s]，ie 读 [j]，-ence 读 [ɑ̃s]；fiction 读 [fik.sjɔ̃]，ct 读 [ks]，tion 读 [sjɔ̃]。","pi":"science 里的 sc 读 [s]，c 不读 [k]；fiction 的 tion 读 [sjɔ̃]，不是 [ʃɔ̃]；两个词都是阴性。","et":"science 来自拉丁语 scientia（知识）；fiction 来自拉丁语 fictio（捏造）。science-fiction 是 19 世纪末从英语借来的复合词。","ex":[["J'adore les films de science-fiction.","我爱科幻电影。"],["Elle lit un roman de science-fiction.","她在读一本科幻小说。"],["Ce monde ressemble à de la science-fiction.","这个世界像科幻一样。"]],"co":[["un film de science-fiction","科幻电影"],["un roman de science-fiction","科幻小说"],["la SF","科幻（缩写）"],["un auteur de science-fiction","科幻作家"]],"sy":[["l'anticipation","soutenu","科幻（偏预测未来的作品）"],["le fantastique","courant","奇幻"],["le fantasy","courant","奇幻（魔幻）"]],"fq":"中频，影视和阅读话题里常见。","me":"science + fiction：以科学为基础编出来的故事。","tr":{"zh":"我们晚上看一部科幻电影吧。","fr":"On regarde un film de science-fiction ce soir ?","alt":"Ce soir, on voit un film de science-fiction ?","note":"film de + 类型。"}},
 "La station spatiale internationale (ISS)": {"pos":"n.f. 阴性名词（station 阴性，spatiale 与 internationale 都是阴性形容词；ISS 为缩写）","s":"国际空间站：绕地球运行的大型载人空间站，简称 l'ISS，读字母 [i.ɛs.ɛs]。航天员在上面做实验、长期生活。","ipa":"[sta.sjɔ̃.spa.sjal.ɛ̃.tɛʁ.na.sjɔ.nal]","ph":"station 读 [sta.sjɔ̃]，tion 读 [sjɔ̃]；spatiale 读 [spa.sjal]，ti 读 [sj]；internationale 读 [ɛ̃.tɛʁ.na.sjɔ.nal]；ISS 读 [i.ɛs.ɛs]。","pi":"-tion / -tiale 里的 t 读 [s]：station [sta.sjɔ̃]，spatiale [spa.sjal]；in- 读鼻化 [ɛ̃]。三个词都用阴性形式，冠词是 la。","et":"station 来自拉丁语 statio（停留、驻地）；spatial 来自 espace（空间，拉丁语 spatium）；international 由 inter-（之间）+ national 构成。","ex":[["L'ISS est dans l'espace.","国际空间站在太空中。"],["Des astronautes vivent sur la station spatiale internationale.","航天员生活在国际空间站上。"],["On voit parfois l'ISS passer dans le ciel.","有时能看到国际空间站飞过天空。"]],"co":[["à bord de l'ISS","在国际空间站上"],["une mission sur l'ISS","国际空间站任务"],["une station spatiale","空间站"],["en orbite autour de la Terre","绕地球轨道运行"]],"sy":[["la station orbitale","soutenu","轨道站"],["le vaisseau spatial","courant","宇宙飞船"],["la fusée","courant","火箭"]],"fq":"中低频，科学和新闻里出现。","me":"ISS = 国际（international）空间（spatiale）站（station）。","tr":{"zh":"航天员在国际空间站上工作。","fr":"Les astronautes travaillent sur la station spatiale internationale.","alt":"Les astronautes sont en mission sur l'ISS.","note":"sur la station：在空间站上。"}},
 "La technologie": {"pos":"n.f. 阴性名词，复数 technologies","s":"技术；科技。la technologie 泛指科技，也可指某种技术（une technologie nouvelle）。形容词是 technologique。","ipa":"[tɛk.nɔ.lɔ.ʒi]","ph":"tech 读 [tɛk]，ch 读 [k]（不是 [ʃ]）；no 读 [nɔ]；lo 读 [lɔ]；gie 读 [ʒi]。","pi":"tech- 里的 ch 读 [k]，不是 [ʃ]；g 在 i 前读 [ʒ]。technologie 是阴性：la technologie。","et":"来自希腊语 tekhnē（技艺）+ logos（学问）+ 后缀 -ie，字面是「技艺之学」。","ex":[["La technologie avance vite.","科技发展很快。"],["Cette technologie est très récente.","这项技术很新。"],["Les enfants aiment la technologie.","孩子们喜欢科技。"]],"co":[["les nouvelles technologies","新技术"],["une technologie de pointe","尖端技术"],["la technologie moderne","现代科技"],["la haute technologie","高科技"]],"sy":[["la technique","courant","技术、技巧（更偏方法）"],["la science","courant","科学"],["l'innovation","courant","创新"]],"fq":"高频，日常常用。","me":"techno + logie：技艺 + 学问。","tr":{"zh":"科技让我们的生活更简单。","fr":"La technologie rend notre vie plus simple.","alt":"Grâce à la technologie, la vie est plus facile.","note":"rendre + 名词 + 形容词：使……变得。"}},
 "Une antenne": {"pos":"n.f. 阴性名词，复数 antennes","s":"天线（电视、手机用的）；触角（昆虫的）。être à l'antenne = 在直播中。une antenne-relais 是通信基站。","ipa":"[ɑ̃.tɛn]","ph":"an 读鼻化 [ɑ̃]；tenne 读 [tɛn]，nn 只读一个 [n]，结尾 e 不发音。","pi":"第一个 an 是鼻化音 [ɑ̃]，不读 n；但 -nne 里的 n 要读出来 [tɛn]。阴性：une antenne。","et":"来自拉丁语 antenna（船桅上的横杆），后来用于昆虫的触角，再用于无线电天线。","ex":[["La radio a une grande antenne.","收音机有一根大天线。"],["Cette antenne reçoit la télévision.","这根天线可以收电视信号。"],["Les papillons ont deux antennes.","蝴蝶有两根触角。"]],"co":[["une antenne parabolique","碟形天线"],["une antenne-relais","信号基站"],["être à l'antenne","正在直播"],["l'antenne de télévision","电视天线"]],"sy":[["un émetteur","soutenu","发射器"],["un récepteur","soutenu","接收器"],["une parabole","courant","碟形天线（口语）"]],"fq":"中频，日常常用。","me":"antenne 像虫子的触角，向外伸出去「听」信号。","tr":{"zh":"我的手机在这里没有信号。","fr":"Mon téléphone ne capte pas ici.","alt":"Il n'y a pas de réseau ici sur mon téléphone.","note":"capter：接收到信号。"}},
 "Une cachette": {"pos":"n.f. 阴性名词，复数 cachettes","s":"藏身处；隐蔽的地方。也指藏东西的地方。en cachette = 偷偷地，背着别人。动词是 cacher（藏）。","ipa":"[ka.ʃɛt]","ph":"ca 读 [ka]；ch 读 [ʃ]；ette 读 [ɛt]，tt 只读一个 [t]，结尾 e 不发音。","pi":"ch 读 [ʃ]；-tte 里的 t 要发音 [t]，所以不要漏掉；e 不发音。cachette 是阴性：une cachette。","et":"来自 cacher（藏）加指小后缀 -ette，字面是「小小的藏身处」。cacher 来自拉丁语 coactare（压）。","ex":[["Le chat a une bonne cachette.","猫有个好藏身处。"],["Les enfants cherchent une cachette pour jouer.","孩子们在找地方躲起来玩。"],["Il fume en cachette.","他偷偷地抽烟。"]],"co":[["en cachette","偷偷地"],["trouver une cachette","找到藏身处"],["une cachette secrète","秘密的藏身处"],["jouer à cache-cache","玩捉迷藏"]],"sy":[["une planque","familier","藏身处（口语）"],["un refuge","courant","避难所"],["un abri","courant","遮蔽处"]],"fq":"中频，日常常用。","me":"cacher + -ette：一个「小小的」藏身处。","tr":{"zh":"我找到了一个好藏身处。","fr":"J'ai trouvé une bonne cachette.","alt":"J'ai déniché une super cachette.","note":"trouver 的过去分词 trouvé。"}},
 "Une fusée": {"pos":"n.f. 阴性名词，复数 fusées","s":"火箭；烟花（信号弹也叫 fusée）。une fusée spatiale 是太空火箭。lancer une fusée = 发射火箭。fusée éclairante 是照明弹。","ipa":"[fy.ze]","ph":"fu 读 [fy]，u 圆唇；s 在元音间读 [z]；ée 读 [e]。","pi":"u 读 [y]，不是 [u]；s 读 [z]，不是 [s]。fusée 是阴性，结尾 -ée 读 [e]，不要读出 e。","et":"来自古法语 fusée，源自拉丁语 fusus（纺锤），因为形状像纺锤。","ex":[["La fusée va sur la lune.","火箭飞向月球。"],["On lance la fusée demain matin.","明天早上发射火箭。"],["Le ciel brille de fusées le 14 juillet.","七月十四日，天空被烟花照亮。"]],"co":[["lancer une fusée","发射火箭"],["une fusée spatiale","太空火箭"],["une fusée de feu d'artifice","烟花"],["une fusée éclairante","照明弹"]],"sy":[["un missile","courant","导弹"],["une navette spatiale","courant","航天飞机"],["un vaisseau spatial","courant","宇宙飞船"]],"fq":"中频，日常常用。","me":"fusée 的样子像纺锤 fuseau：细长向上飞。","tr":{"zh":"火箭明天发射。","fr":"La fusée décolle demain.","alt":"On lance la fusée demain.","note":"décoller：起飞；lancer：发射。"}},
 "Une imprimante 3D": {"pos":"n.f. 阴性名词，复数 imprimantes 3D","s":"3D 打印机。imprimante 是「打印机」，3D 读 [trwa.de]（trois D）。动词是 imprimer（打印）。用 une imprimante 3D 可以做出立体的东西。","ipa":"[ɛ̃.pʁi.mɑ̃t.tʁwa.de]","ph":"im 读鼻化 [ɛ̃]；pri 读 [pʁi]；man 读 [mɑ̃]；te 读 [t]，结尾 e 不发音；3D 读 [tʁwa.de]。","pi":"im- 读鼻化 [ɛ̃]，不是「因」；-ante 里 an 读 [ɑ̃]，te 读 [t]；3D 是 trois D，读作 [tʁwa.de]。imprimante 是阴性。","et":"imprimante 来自动词 imprimer，拉丁语 imprimere（压印），加后缀 -ante（做……的东西）。","ex":[["Il fabrique un objet avec une imprimante 3D.","他用 3D 打印机做东西。"],["Cette imprimante 3D coûte cher.","这台 3D 打印机很贵。"],["Nous imprimons un jouet en 3D.","我们用 3D 打印一个玩具。"]],"co":[["imprimer en 3D","3D 打印"],["une pièce imprimée en 3D","3D 打印的零件"],["une imprimante laser","激光打印机"],["une imprimante couleur","彩色打印机"]],"sy":[["une photocopieuse","courant","复印机"],["un traceur","soutenu","绘图仪"],["un scanner","courant","扫描仪"]],"fq":"中低频，科技话题里常见。","me":"imprimer 一层一层，印出来一个立体（3D）的东西。","tr":{"zh":"我们学校有一台 3D 打印机。","fr":"Notre école a une imprimante 3D.","alt":"Il y a une imprimante 3D dans notre école.","note":"avoir 表示拥有。"}},
 "Une innovation": {"pos":"n.f. 阴性名词，复数 innovations","s":"创新；新发明；新做法。指新的想法、产品或方法。une grande innovation = 一项重大创新。动词是 innover（创新）。","ipa":"[i.nɔ.va.sjɔ̃]","ph":"in 在这里读 [i.n]，不是鼻化音（因为 nn 双写，一个 n 属于下一个音节）；no 读 [nɔ]；va 读 [va]；tion 读 [sjɔ̃]。","pi":"innovation 里 inn- 读 [i.n]，不鼻化，和 in- 读 [ɛ̃] 不同；tion 读 [sjɔ̃]，不是 [ʃɔ̃]。阴性：une innovation。","et":"来自拉丁语 innovatio，由 in-（进入）+ novus（新的）构成，同源词有 nouveau、novateur。","ex":[["C'est une grande innovation.","这是一项重大创新。"],["Cette entreprise aime l'innovation.","这家公司喜欢创新。"],["Chaque année, il y a de nouvelles innovations.","每年都有新的创新成果。"]],"co":[["une innovation technologique","技术创新"],["encourager l'innovation","鼓励创新"],["une grande innovation","重大创新"],["une innovation majeure","重大创新（主要）"]],"sy":[["une invention","courant","发明（从无到有）"],["une nouveauté","courant","新东西"],["un progrès","courant","进步"]],"fq":"中频，工作和新闻里常用。","me":"in + nov：进入「新」（nouveau）的领域。","tr":{"zh":"这是一项很了不起的创新。","fr":"C'est une innovation remarquable.","alt":"C'est vraiment une super innovation.","note":"remarquable：了不起，值得注意。"}},
 "Une nouveauté": {"pos":"n.f. 阴性名词，复数 nouveautés","s":"新事物；新品；新鲜感。商店里的 les nouveautés 指新上市的商品（新款、新书、新片）。ce n'est pas une nouveauté = 这不是什么新鲜事。","ipa":"[nu.vo.te]","ph":"nou 读 [nu]；veau 读 [vo]；té 读 [te]；整个词读 [nu.vo.te]，重音落在最后。","pi":"eau 读 [o]；nouveauté 来自 nouveau 的阳性前形式 nouvel，不要写成 nouvauté。阴性名词：une nouveauté。","et":"由 nouveau（新的）+ 后缀 -té（表示性质）构成。nouveau 来自拉丁语 novellus，由 novus（新的）而来。","ex":[["Il y a une nouveauté dans le magasin.","店里有新品。"],["Cette application est une vraie nouveauté.","这款应用是真正的新东西。"],["Les nouveautés arrivent en septembre.","新品九月上市。"]],"co":[["les nouveautés","新品；新上市的东西"],["ce n'est pas une nouveauté","这不是什么新鲜事"],["une nouveauté technologique","科技新品"],["la nouveauté du jour","今日新品"]],"sy":[["une innovation","courant","创新"],["une nouvelle","courant","新消息（不同义）"],["la primeur","soutenu","初次、新鲜（尤指蔬果）"]],"fq":"中频，购物和日常里常见。","me":"nouveau + té：「新」的性质。","tr":{"zh":"这家书店有很多新书。","fr":"Cette librairie a beaucoup de nouveautés.","alt":"Il y a plein de nouveautés dans cette librairie.","note":"beaucoup de + 复数名词。"}},
 "Une tablette": {"pos":"n.f. 阴性名词，复数 tablettes","s":"平板电脑（une tablette tactile）；一块（巧克力）；小板、搁板。une tablette de chocolat = 一板巧克力。注意：药片也可叫 un comprimé，tablette 较少。","ipa":"[ta.blɛt]","ph":"ta 读 [ta]；bl 读 [bl]；ette 读 [ɛt]，tt 只读一个 [t]，结尾 e 不发音。","pi":"-ette 读 [ɛt]，t 要发音；e 不发音。tablette 是阴性，不要说 un tablette。","et":"来自 table（桌，板）加指小后缀 -ette，字面是「小板」。table 来自拉丁语 tabula。","ex":[["Je regarde un film sur ma tablette.","我在平板上看电影。"],["Elle mange une tablette de chocolat.","她吃了一板巧克力。"],["Mon fils joue sur la tablette.","我儿子在玩平板。"]],"co":[["une tablette tactile","触屏平板电脑"],["une tablette de chocolat","一板巧克力"],["sur ma tablette","在我的平板上"],["une tablette graphique","手写板"]],"sy":[["un ordinateur portable","courant","笔记本电脑"],["un smartphone","courant","智能手机"],["un iPad","familier","苹果平板（品牌，常泛指）"]],"fq":"高频，日常常用。","me":"tablette = 小小的 table（板）。","tr":{"zh":"我用平板看书。","fr":"Je lis des livres sur ma tablette.","alt":"Je lis sur ma tablette.","note":"sur ma tablette：在平板上。"}},
 "Un cosmonaute / Un astronaute": {"pos":"n.m. / n.f. 名词，阴阳同形（une astronaute），复数 cosmonautes / astronautes","s":"宇航员；航天员。cosmonaute 原指苏联／俄罗斯的宇航员，astronaute 指美国及欧洲的；今天两者在日常法语里常通用。女性用 une astronaute / une cosmonaute。","ipa":"[kɔs.mɔ.not] / [as.tʁɔ.not]","ph":"cosmonaute：cos [kɔs]，mo [mɔ]，naute [not]，au 读 [o]；astronaute：as [as]，tro [tʁɔ]，naute [not]。","pi":"au 读 [o]，不是「奥乌」；两个词都以 -aute [ot] 结尾，e 不发音。名词阴阳同形，用冠词表示性别：un / une astronaute。","et":"cosmonaute 来自希腊语 kosmos（宇宙）+ nautēs（水手）；astronaute 来自希腊语 astron（星）+ nautēs，字面是「宇宙的水手」「星际水手」。","ex":[["L'astronaute voyage dans l'espace.","宇航员在太空中旅行。"],["Ma fille rêve de devenir astronaute.","我女儿梦想成为宇航员。"],["Le cosmonaute est revenu sur Terre.","那位宇航员回到了地球。"]],"co":[["devenir astronaute","成为宇航员"],["un astronaute américain","美国宇航员"],["un cosmonaute russe","俄罗斯宇航员"],["une mission d'astronautes","宇航员任务"]],"sy":[["un spationaute","soutenu","航天员（法国航天局常用的词）"],["un taïkonaute","soutenu","中国宇航员"],["un pilote","courant","飞行员"]],"fq":"中频，日常常用。","me":"astro（星）+ naute（水手）：在星海里航行的人。","tr":{"zh":"我儿子长大想当宇航员。","fr":"Mon fils veut devenir astronaute.","alt":"Plus tard, mon fils veut être astronaute.","note":"devenir + 无冠词的职业名词。"}},
 "Un décorateur / Une décoratrice": {"pos":"n.m. / n.f. 名词，阳性 décorateur，阴性 décoratrice（-teur 变 -trice），复数 décorateurs / décoratrices","s":"装饰师；室内设计师；布景师。un décorateur d'intérieur = 室内装饰师；décorateur de théâtre = 舞台美术师。动词是 décorer（装饰）。","ipa":"[de.kɔ.ʁa.tœʁ] / [de.kɔ.ʁa.tʁis]","ph":"dé 读 [de]；co 读 [kɔ]；ra 读 [ʁa]；-teur 读 [tœʁ]；阴性 -trice 读 [tʁis]，ce 读 [s]。","pi":"阳性 -teur 读 [tœʁ]，结尾 r 要发音；阴性 -trice 是 [tʁis]。不要把阴性写成 décoratrise。é 要有重音。","et":"来自拉丁语 decorator，由 decorare（装饰）而来，同源词有 décor、décoration、décorer。","ex":[["Le décorateur choisit les couleurs.","装饰师挑选颜色。"],["Ma sœur est décoratrice d'intérieur.","我姐姐是室内装饰师。"],["La décoratrice prépare le décor du film.","布景师在准备电影的布景。"]],"co":[["un décorateur d'intérieur","室内装饰师"],["un décorateur de théâtre","舞台美术师"],["une décoratrice de mariage","婚礼布置师"],["faire appel à un décorateur","请装饰师帮忙"]],"sy":[["un designer","courant","设计师"],["un architecte d'intérieur","courant","室内建筑师（更专业）"],["un scénographe","soutenu","舞美设计师"]],"fq":"中低频，职业话题里出现。","me":"décor（布景）+ -ateur：做布景的人。","tr":{"zh":"装饰师给我们的客厅换了颜色。","fr":"Le décorateur a changé les couleurs de notre salon.","alt":"Le décorateur a refait notre salon avec de nouvelles couleurs.","note":"décorateur 阳性，décoratrice 阴性。"}},
 "Un tapis roulant / Un tapis de course": {"pos":"n.m. 阳性名词，复数 des tapis roulants / des tapis de course（tapis 本身单复数同形）","s":"跑步机。两种说法都常用：tapis roulant 字面是「会滚动的地毯」，tapis de course 字面是「跑步用的垫子」。tapis roulant 还可指机场的传送带、自动人行道。","ipa":"[ta.pi ʁu.lɑ̃] / [ta.pi də kuʁs]","ph":"tapis 结尾 s 不发音；roulant 的 ou 读 [u]，-ant 读鼻化 [ɑ̃]，t 不发音；course 结尾 e 不发音。","pi":"tapis 的 s 不发音（不是 [ta.pis]）；roulant 里的 r 是小舌音 [ʁ]。","et":"tapis 来自希腊语 tapētion（小地毯）；roulant 是 rouler（滚动）的现在分词；course 是 courir（跑）的名词。","ex":[["Il court sur le tapis roulant.","他在跑步机上跑步。"],["Je fais trente minutes de tapis de course à la salle de sport.","我在健身房跑三十分钟跑步机。"],["Prends le tapis roulant pour aller à la porte B.","坐自动人行道去 B 登机口。"]],"co":[["courir sur un tapis roulant","在跑步机上跑步"],["monter sur / descendre du tapis roulant","上 / 下跑步机"],["le tapis roulant des bagages","行李传送带"]],"sy":[["tapis de course","courant","专指健身用的跑步机"],["tapis roulant","courant","也指传送带、自动人行道"]],"fq":"中频，健身房和机场里常见。","me":"tapis 是垫子，roulant 是滚动：一块一直在滚的垫子，你在上面跑。","tr":{"zh":"我每天早上在跑步机上跑三十分钟。","fr":"Je cours trente minutes sur le tapis roulant tous les matins.","alt":"Tous les matins, je fais trente minutes de tapis de course.","note":"courir sur + 名词；trente minutes 前不需要介词。"}},
 "Un(e) enseignant(e)": {"pos":"n.m./f. 名词，阳性 enseignant，阴性 enseignante，复数 enseignants / enseignantes","s":"教师（从小学到大学的统称）。男女同词，用冠词和词尾区分：un enseignant / une enseignante。比 professeur 更中性、更正式，行政和新闻里常用；口语里常说 prof。","ipa":"[ɑ̃.sɛ.ɲɑ̃]","ph":"en 读鼻化 [ɑ̃]；ei 读 [ɛ]；gn 读 [ɲ]（像汉语「娘」里 ni 的音）；ant 读 [ɑ̃]，t 不发音。","pi":"gn 不是 [g]+[n]，是一个音 [ɲ]；阳性结尾的 t 不发音，阴性 enseignante 才发 [t]。","et":"enseigner（教）+ -ant（做……的人）。enseigner 来自拉丁语 insignare，词根 signum（记号）。同族：enseigne（招牌）、signe（标记）。","ex":[["Mon enseignant est très gentil.","我的老师很友善。"],["Elle est enseignante dans une école primaire.","她是小学老师。"],["Les enseignants préparent leurs cours.","老师们在备课。"]],"co":[["devenir enseignant(e)","成为教师"],["le métier d'enseignant","教师这个职业"],["un enseignant-chercheur","大学教研人员"]],"sy":[["professeur","courant","中学、大学老师；口语缩写 prof"],["instituteur / institutrice","courant","小学老师的旧称；现在官方叫 professeur des écoles"],["maître / maîtresse","courant","孩子们对小学老师的称呼"]],"fq":"高频，学校和新闻里常用。","me":"enseigne-ant：用「标记」（signe）把知识指给你看的人。","tr":{"zh":"我妈妈是中学老师。","fr":"Ma mère est enseignante dans un collège.","alt":"Ma mère, elle est prof au collège.","note":"说职业时通常不加冠词：elle est enseignante。"}},
 "Un(e) vétérinaire": {"pos":"n.m./f. 名词，阴阳同形：un vétérinaire / une vétérinaire，复数 vétérinaires","s":"兽医。男女同形，只靠冠词区分。口语常缩写成 un véto 或 un vét。去看兽医说 aller chez le vétérinaire。","ipa":"[ve.te.ʁi.nɛʁ]","ph":"两个 é 都读 [e]；in 在元音前不鼻化，读 [i.n]；-aire 读 [ɛʁ]。","pi":"不是 [vɛ.tɛ…]，前两个音节都是 [e]；-aire 结尾读 [ɛʁ]，r 要发。","et":"来自拉丁语 veterinarius（与役畜有关的），源自 veterinae（役畜）。","ex":[["Le vétérinaire soigne mon chien.","兽医给我的狗看病。"],["Elle est vétérinaire depuis dix ans.","她当兽医十年了。"],["Je dois emmener mon chat chez le vétérinaire.","我得带我的猫去看兽医。"]],"co":[["aller chez le vétérinaire","去看兽医"],["un cabinet vétérinaire","宠物诊所"],["emmener son chat chez le vétérinaire","带猫去看兽医"]],"sy":[["véto","familier","vétérinaire 的口语缩写"]],"fq":"中频，养宠物的人常用。","me":"veterinarius 与「役畜」有关：照顾动物的医生。","tr":{"zh":"明天我的狗要去看兽医。","fr":"Demain, mon chien va chez le vétérinaire.","alt":"Demain, j'emmène mon chien chez le véto.","note":"去某人那里看病用 chez + 人。"}},
 "Communiquer": {"pos":"v. 第一组动词（-er），助动词 avoir；nous communiquons","s":"交流；沟通；传达。可以不带宾语：Ils communiquent bien；也可 communiquer avec qqn（和某人沟通）或 communiquer qqch à qqn（把某事告知某人）。","ipa":"[kɔ.my.ni.ke]","ph":"c 在 o 前读 [k]；u 读 [y]；qu 读 [k]；-er 读 [e]，r 不发音。","pi":"qu 读 [k]；u 要圆唇读 [y]，不是 [u]；结尾 -er 读 [e]。","et":"来自拉丁语 communicare（共享、告知），源自 communis（共同的）。同族：commun、communauté、communication。","ex":[["Nous aimons communiquer.","我们喜欢交流。"],["Elle communique avec ses parents par vidéo.","她通过视频和父母联系。"],["Ils ne communiquent plus depuis la dispute.","吵架以后他们就不再沟通了。"]],"co":[["communiquer avec quelqu'un","和某人沟通"],["communiquer par téléphone / par mail","通过电话 / 邮件联系"],["communiquer une information à quelqu'un","把消息告诉某人"]],"sy":[["échanger","courant","交换（意见、信息）"],["parler","courant","说话，比 communiquer 更日常"],["informer","courant","通知，强调单向告知"]],"fq":"高频，日常和工作中都常用。","me":"commun-iquer：把东西变成「共同的」，就是交流。","tr":{"zh":"我们通过邮件联系。","fr":"Nous communiquons par mail.","alt":"On se contacte par mail.","note":"communiquer par + 方式；avec + 人。"}},
 "Envoyer": {"pos":"v. 第一组动词（-er），助动词 avoir；不规则将来式 j'enverrai","s":"寄；发送；派遣。envoyer un message / un colis / un mail；也可 envoyer qqn quelque part（派某人去某处）。将来时和条件式词干不规则：j'enverrai, j'enverrais。","ipa":"[ɑ̃.vwa.je]","ph":"en 读鼻化 [ɑ̃]；oy 读 [wa.j]；-er 读 [e]。","pi":"将来时是 enverrai（不是 envoierai）；je vais envoyer 是常用的近将来说法。","et":"来自晚期拉丁语 inviare（使上路），源自 via（路）。同族：voie、voyage。","ex":[["Je vais envoyer un message.","我要发一条消息。"],["Elle m'a envoyé une carte postale.","她给我寄了一张明信片。"],["Je t'enverrai l'adresse demain.","我明天把地址发给你。"]],"co":[["envoyer un mail / un colis","发邮件 / 寄包裹"],["envoyer quelque chose à quelqu'un","把某物寄给某人"],["envoyer quelqu'un chercher quelque chose","派某人去取某物"]],"sy":[["expédier","courant","寄出（货物、邮件），更偏邮寄"],["adresser","soutenu","寄出、致送，较书面"],["balancer","familier","随手发 / 扔，如 balance-moi le lien"]],"fq":"极高频，日常常用。","me":"en-voyer：把东西放到「路」（voie）上送走。","tr":{"zh":"你可以把照片发给我吗？","fr":"Tu peux m'envoyer les photos ?","alt":"Tu m'envoies les photos ?","note":"me / m' 在动词前，表示「发给我」。"}},
 "Évoluer": {"pos":"v. 第一组动词（-er），助动词 avoir","s":"演变；发展；进化。指事物、情况随时间逐步变化，不一定是变好：La situation évolue。也用于生物进化。","ipa":"[e.vɔ.lɥe]","ph":"é 读 [e]；o 读 [ɔ]；u 在元音前读半元音 [ɥ]，所以 -uer 是 [ɥe]；r 不发音。","pi":"lu-er 中的 u 读 [ɥ]（类似快速的「于」），不是 [u]。","et":"来自拉丁语 evolvere（展开），源自 volvere（卷、转）。同族：évolution、révolution。","ex":[["Le monde va évoluer.","世界会不断演变。"],["Les mentalités évoluent vite.","观念变化得很快。"],["Mon travail évolue dans le bon sens.","我的工作在朝好的方向发展。"]],"co":[["évoluer rapidement / lentement","变化得快 / 慢"],["la situation évolue","形势在发展变化"],["évoluer dans un milieu","在某个环境中生活、发展"]],"sy":[["changer","courant","改变，更笼统"],["se développer","courant","发展、壮大"],["progresser","courant","进步，一定是向好"]],"fq":"中高频，新闻和讨论里常见。","me":"évoluer 里有 e-vol-uer，想想 évolution：一步步展开。","tr":{"zh":"城市变化得很快。","fr":"La ville évolue très vite.","alt":"La ville change vite.","note":"évoluer 常用副词修饰：vite, lentement。"}},
 "Gaspiller": {"pos":"v. 第一组动词（-er），助动词 avoir","s":"浪费（水、食物、钱、时间、才能）。强调毫无必要地用掉。常和 de l'eau, de la nourriture, de l'argent 搭配。名词是 le gaspillage。","ipa":"[gas.pi.je]","ph":"g 在 a 前读 [g]；-ill- 在这里读 [j]；-er 读 [e]。","pi":"gaspiller 里的 -ill- 读 [j]，不是 [il]（和 ville, mille 不同）。","et":"来源不确定（可能与方言或普罗旺斯语有关）；词族：gaspillage（浪费）、gaspilleur（浪费的人）。","ex":[["Il ne faut pas gaspiller l'eau.","不要浪费水。"],["On gaspille trop de nourriture.","我们浪费了太多食物。"],["Il a gaspillé son argent en une semaine.","他一周就把钱花光了。"]],"co":[["gaspiller l'eau / la nourriture","浪费水 / 食物"],["gaspiller son argent / son talent","浪费钱 / 才华"],["le gaspillage alimentaire","食物浪费"]],"sy":[["perdre","courant","perdre son temps 浪费时间；不用于水和食物"],["dilapider","soutenu","挥霍（钱财）"]],"fq":"中频，环保话题常用。","me":"gaspi（口语缩写）= 浪费：Pas de gaspi ! 不要浪费！","tr":{"zh":"别浪费食物。","fr":"Ne gaspille pas la nourriture.","alt":"Pas de gaspi, finis ton assiette !","note":"命令式否定：ne + 动词 + pas。"}},
 "Imprimer": {"pos":"v. 第一组动词（-er），助动词 avoir","s":"打印；印刷。imprimer un document / une photo。也可指「留下印记」（较书面）。名词：une imprimante（打印机）、une impression（印刷；印象）。","ipa":"[ɛ̃.pʁi.me]","ph":"im 在 p 前读鼻化 [ɛ̃]；r 读 [ʁ]；-er 读 [e]。","pi":"im- 读鼻化 [ɛ̃]，不发 m；别和 imprimante 里的 [ɛ̃] 搞混发成 [im]。","et":"来自拉丁语 imprimere（压入），源自 premere（压）。同族：presse、pression、impression。","ex":[["Je dois imprimer un document.","我得打印一份文件。"],["Tu peux imprimer mon billet de train ?","你能帮我打印火车票吗？"],["L'imprimante ne veut plus imprimer.","打印机打不出来了。"]],"co":[["imprimer un document / un billet","打印文件 / 票"],["une imprimante","打印机"],["imprimer en couleur / en noir et blanc","彩色 / 黑白打印"]],"sy":[["tirer","courant","tirer une photo 洗照片、印出"],["éditer","soutenu","出版，不等于打印"]],"fq":"中高频，办公和日常常用。","me":"im-primer：用力「压」（premere）出痕迹。","tr":{"zh":"你可以帮我打印这份文件吗？","fr":"Tu peux m'imprimer ce document ?","alt":"Tu peux imprimer ce document pour moi ?","note":"m' 是间接宾语：给我打印。"}},
 "Paniquer": {"pos":"v. 第一组动词（-er），助动词 avoir；nous paniquons","s":"惊慌；恐慌；慌了神。可以不带宾语：Ne panique pas ! 也可及物，意为「使惊慌」（paniquer qqn，口语）。","ipa":"[pa.ni.ke]","ph":"qu 读 [k]；-er 读 [e]；每个元音都清晰。","pi":"qu 读 [k]；不要读成英语 panic 的 [ˈpænɪk]，三个音节都是短元音。","et":"来自 panique，源自希腊语 panikos（牧神潘 Pan 引起的恐惧）。","ex":[["Il ne faut pas paniquer.","不要惊慌。"],["Ne panique pas, tout va bien.","别慌，一切都好。"],["Elle panique avant chaque examen.","她每次考试前都会慌。"]],"co":[["ne panique pas !","别慌！"],["paniquer pour rien","无谓地慌张"],["être pris(e) de panique","陷入恐慌"]],"sy":[["s'affoler","courant","慌乱、乱了手脚"],["flipper","familier","吓得发慌"]],"fq":"中频，口语里很常用。","me":"Pan 神突然出现，大家 panique。","tr":{"zh":"别慌，我来帮你。","fr":"Ne panique pas, je vais t'aider.","alt":"Pas de panique, je t'aide.","note":"命令式否定 + 近将来 je vais + 动词。"}},
 "Réfléchir": {"pos":"v. 第二组动词（-ir），助动词 avoir；nous réfléchissons","s":"思考；考虑。常和 à 连用：réfléchir à qqch（思考某事）。Laisse-moi réfléchir = 让我想想。较少数情况下指「反射」（光、镜子）。","ipa":"[ʁe.fle.ʃiʁ]","ph":"ré 读 [ʁe]；é 读 [e]；ch 读 [ʃ]；结尾 -ir 读 [iʁ]，r 要发。","pi":"ch 读 [ʃ]，不是 [k]；注意 r 是小舌音 [ʁ]；réfléchir à（不是 sur 也不是直接接宾语）。","et":"来自拉丁语 reflectere（折回），词根 flectere（弯曲）。思想「折回来」想一遍。同族：reflet（倒影）、réflexion。","ex":[["Il faut réfléchir avant de parler.","说话前要想一想。"],["Je réfléchis à ma réponse.","我在考虑我的答案。"],["Laisse-moi réfléchir un instant.","让我想一会儿。"]],"co":[["réfléchir à quelque chose","思考某事"],["réfléchir avant d'agir","三思而后行"],["laisser réfléchir","给时间考虑"],["tout bien réfléchi","仔细想过之后"]],"sy":[["penser","courant","想，更宽泛；penser à 想到"],["songer","soutenu","思索、梦想"],["cogiter","familier","苦思冥想（带玩笑）"]],"fq":"高频，日常常用。","me":"re-fléchir：把思路「折回」再想一遍。","tr":{"zh":"我需要想一想再回答你。","fr":"J'ai besoin de réfléchir avant de te répondre.","alt":"Laisse-moi réfléchir, je te réponds après.","note":"avant de + 动词原形。"}},
 "Remplacer": {"pos":"v. 第一组动词（-er），助动词 avoir；nous remplaçons","s":"替换；取代；代替。remplacer A par B（用 B 换掉 A）；也可指接替某人的位置：remplacer un collègue。","ipa":"[ʁɑ̃.pla.se]","ph":"rem 读鼻化 [ʁɑ̃]；p 要发；ç/c 在 e 前读 [s]；-er 读 [e]。","pi":"em 在 p 前读鼻化 [ɑ̃]；nous 变位时 c 要加软音符：remplaçons。","et":"re- + 古法语 emplacer（安置），源自 place（位置）。字面意思：放回原来的位置上。","ex":[["Je vais remplacer mon téléphone.","我要换手机。"],["Il remplace son collègue malade.","他在代替生病的同事。"],["Remplacez le sucre par du miel.","用蜂蜜代替糖。"]],"co":[["remplacer A par B","用 B 取代 A"],["remplacer quelqu'un","代替某人"],["se faire remplacer","找人代班"]],"sy":[["changer","courant","更换，如 changer d'ampoule"],["substituer","soutenu","替代，较书面"]],"fq":"高频，日常常用。","me":"re-emplacer：重新放一个到「位置」上。","tr":{"zh":"我想把旧手机换掉。","fr":"Je veux remplacer mon vieux téléphone.","alt":"Je veux changer de téléphone.","note":"remplacer + 直接宾语；changer de + 名词不加冠词。"}},
 "S'abonner": {"pos":"v.pron. 代动词（第一组），复合时态用 être：je me suis abonné(e)；后接 à","s":"订阅；订购；办年卡。s'abonner à une chaîne / un magazine / un service。名词：un abonnement（订阅）、un abonné（订户）。","ipa":"[sa.bɔ.ne]","ph":"s' + abonner 连读：s'a 读 [sa]；onn 读 [ɔn]（-nn- 前 o 读开口 [ɔ]）；-er 读 [e]。","pi":"不要省略 à：s'abonner à（不是 s'abonner de）；abonné 要和主语性别一致。","et":"与古法语 bonne（界限）有关，本义是划定期限的约定。词族：abonnement、désabonner。来源细节不确定。","ex":[["Je m'abonne à cette chaîne Youtube.","我订阅了这个 YouTube 频道。"],["Elle s'est abonnée à un magazine.","她订了一本杂志。"],["Tu devrais t'abonner à la newsletter.","你应该订阅这份通讯。"]],"co":[["s'abonner à une chaîne / un magazine","订阅频道 / 杂志"],["s'abonner à la newsletter","订阅电子通讯"],["un abonnement mensuel","月度订阅"]],"sy":[["souscrire","courant","souscrire un abonnement 办理订阅"],["suivre","courant","在社交网络上关注"]],"fq":"中频，网络时代常用。","me":"abonné = 「订户」，反义词是 se désabonner。","tr":{"zh":"你订阅这个频道了吗？","fr":"Tu es abonné à cette chaîne ?","alt":"Tu t'es abonné à cette chaîne ?","note":"être abonné à 表示「已订阅」状态；s'abonner 强调订阅这个动作。"}},
 "Se désabonner": {"pos":"v.pron. 代动词（第一组），复合时态用 être：je me suis désabonné(e)；后接 de","s":"取消订阅；退订。se désabonner de qqch。注意介词是 de，与 s'abonner à 不同。网站邮件底部常见 Se désabonner 按钮。","ipa":"[sə de.za.bɔ.ne]","ph":"dés- 后接元音 a，s 读 [z]：[de.za]；se 读 [sə]；-er 读 [e]。","pi":"dés + a 中 s 发 [z]，不是 [s]；介词是 de，不是 à。","et":"dé-（取消）+ abonner。dé- 表示「反向动作」，如 défaire, découvrir。","ex":[["Je vais me désabonner de ce site.","我要退订这个网站。"],["Tu peux te désabonner de la newsletter.","你可以退订这份通讯。"],["Elle s'est désabonnée de la chaîne.","她取消了对这个频道的订阅。"]],"co":[["se désabonner d'une newsletter","退订通讯"],["se désabonner d'une chaîne","取消订阅频道"],["le lien de désabonnement","退订链接"]],"sy":[["résilier","soutenu","终止合同（résilier un abonnement）"],["annuler","courant","取消"]],"fq":"中频，网络上常用。","me":"dés-abonner：把「订阅」撤销。","tr":{"zh":"我想退订这些邮件。","fr":"Je veux me désabonner de ces mails.","alt":"Je voudrais arrêter de recevoir ces mails.","note":"se désabonner de + 名词。"}},
 "Se perdre": {"pos":"v.pron. 代动词（第三组 -dre），复合时态用 être：je me suis perdu(e)","s":"迷路；走丢。也可比喻「迷失、困惑」：se perdre dans les détails（陷入细节）。perdre 本身是「丢失；输」。","ipa":"[sə pɛʁdʁ]","ph":"se 读 [sə]；perdre 读 [pɛʁdʁ]，er 读 [ɛʁ]；结尾 -dre 的 e 不发音。","pi":"perdre 结尾 e 不发音；性别一致：elle s'est perdue。","et":"来自拉丁语 perdere（丢失）。同族：perte（损失）、perdant（输家）。","ex":[["J'ai peur de me perdre dans la forêt.","我怕在森林里迷路。"],["Nous nous sommes perdus en ville.","我们在城里迷路了。"],["Elle s'est perdue dans ses pensées.","她陷入了沉思。"]],"co":[["se perdre en ville / en forêt","在城里 / 森林里迷路"],["se perdre dans les détails","陷入细节"],["Je suis perdu(e).","我迷路了 / 我糊涂了"]],"sy":[["s'égarer","soutenu","走错路、迷失，较书面"],["être paumé(e)","familier","迷路 / 不知所措"]],"fq":"高频，旅行时必用。","me":"perdre 是「丢」，se perdre 是「把自己丢了」。","tr":{"zh":"我在这个城市迷路了。","fr":"Je me suis perdu dans cette ville.","alt":"Je suis perdu, je ne trouve plus ma rue.","note":"代动词用 être，过去分词和主语一致。"}},
 "Se repérer": {"pos":"v.pron. 代动词（第一组），复合时态用 être；je me repère, nous nous repérons","s":"辨明方向；找准位置；弄清状况。se repérer dans une ville / dans un texte。也可及物 repérer（发现、注意到）。名词：un repère（标志物；参照点）。","ipa":"[sə ʁə.pe.ʁe]","ph":"se 读 [sə]；re 读 [ʁə]；pé 读 [pe]；ré 读 [ʁe]；-er 读 [e]。","pi":"变位时重音节的 é 变 è：je me repère，但 nous nous repérons；两个 r 都读小舌音。","et":"re- + repère（标志、参照点）。repère 的来源不确定；词族：repérer、repérage。","ex":[["Le GPS aide à se repérer.","GPS 帮助定位。"],["Je n'arrive pas à me repérer sur cette carte.","我在这张地图上找不到位置。"],["Il se repère facilement grâce aux étoiles.","他靠星星很容易找准方向。"]],"co":[["se repérer sur une carte","在地图上找位置"],["se repérer dans une ville","在城市里辨明方向"],["un point de repère","参照点；标志物"]],"sy":[["s'orienter","courant","辨别方向"],["se situer","courant","确定自己的位置"]],"fq":"中频，旅行和说明书里常见。","me":"repère（标志物）+ se：靠标志物找到自己。","tr":{"zh":"没有地图，我很难找准方向。","fr":"Sans carte, j'ai du mal à me repérer.","alt":"Sans plan, je n'arrive pas à me repérer.","note":"avoir du mal à + 动词原形。"}},
 "Télécharger": {"pos":"v. 第一组动词（-er），助动词 avoir；nous téléchargeons","s":"下载（文件、应用、歌曲）。télécharger un fichier / une appli / un film。反义词：téléverser 或 mettre en ligne（上传）。","ipa":"[te.le.ʃaʁ.ʒe]","ph":"té 读 [te]；lé 读 [le]；ch 读 [ʃ]；g 在 e 前读 [ʒ]；-er 读 [e]。","pi":"nous 变位要保留 e：téléchargeons（让 g 仍读 [ʒ]）；ch 不是 [k]。","et":"télé-（远，希腊语 tēle）+ charger（装载）。charger 来自晚期拉丁语 carricare（装车）。","ex":[["Je veux télécharger une application.","我想下载一个应用。"],["Tu peux télécharger le fichier ici.","你可以在这里下载文件。"],["Elle télécharge un film pour le voyage.","她为旅途下载了一部电影。"]],"co":[["télécharger un fichier / une appli","下载文件 / 应用"],["télécharger gratuitement","免费下载"],["un téléchargement","一次下载"]],"sy":[["charger","courant","加载 / 装载，不等于下载"],["téléverser","soutenu","上传（反义词）"]],"fq":"高频，网络时代常用。","me":"télé-charger：从远处装进来。","tr":{"zh":"我先下载这个应用，然后再用。","fr":"Je télécharge d'abord cette application, puis je l'utilise.","alt":"Je commence par télécharger l'appli.","note":"commencer par + 动词原形：先做某事。"}},
 "Autonome": {"pos":"adj. 形容词，阴阳同形：autonome；复数 autonomes","s":"自主的；独立的；自动驾驶的。une voiture autonome（自动驾驶汽车）；un enfant autonome（能自理的孩子）；être autonome（能自己做事）。","ipa":"[o.tɔ.nɔm]","ph":"au 读 [o]；o 读 [ɔ]；结尾 -ome 读 [ɔm]，m 要发。","pi":"au 读 [o]，不是 [au]；结尾 m 要发音。","et":"来自希腊语 autonomos（auto「自己」+ nomos「法律」）。同族：autonomie、automatique。","ex":[["La voiture est autonome.","这辆车是自动驾驶的。"],["À dix ans, elle est déjà très autonome.","十岁时她已经很独立了。"],["Je veux être autonome financièrement.","我想在经济上独立。"]],"co":[["une voiture autonome","自动驾驶汽车"],["devenir autonome","变得独立"],["autonome en énergie","能源自给的"]],"sy":[["indépendant(e)","courant","独立的，更宽泛"],["automatique","courant","自动的，不一定自主"]],"fq":"中频，科技和教育话题常用。","me":"auto（自己）+ nome（规则）：自己定规矩。","tr":{"zh":"我儿子已经很独立了。","fr":"Mon fils est déjà très autonome.","alt":"Mon fils se débrouille déjà tout seul.","note":"autonome 阴阳同形。"}},
 "Conscient(e)": {"pos":"adj. 形容词，阴性 consciente，复数 conscients / conscientes","s":"意识到的；清醒的。常用 être conscient de + 名词 / que + 从句。也指「有意识的、神志清醒的」：Le blessé est conscient。","ipa":"[kɔ̃.sjɑ̃]","ph":"con 读鼻化 [kɔ̃]；sci 读 [sj]；-ent 读鼻化 [ɑ̃]，t 不发音；阴性 -ente 读 [ɑ̃t]。","pi":"sc 在 i 前读 [s]；阳性结尾 t 不发音；阴性 consciente 才发 [t]。","et":"来自拉丁语 conscius（知道的），源自 conscire（共同知晓）。同族：conscience（意识；良心）、inconscient。","ex":[["Il est conscient du problème.","他意识到了问题。"],["Elle est consciente de ses erreurs.","她知道自己的错误。"],["Le patient est conscient.","病人神志清醒。"]],"co":[["être conscient de quelque chose","意识到某事"],["être conscient que + 从句","意识到……"],["devenir conscient","变得有意识"]],"sy":[["averti(e)","soutenu","有所警觉的"],["lucide","courant","清醒的、头脑清楚的"]],"fq":"中频，讨论问题时常用。","me":"con-scient：「一同知道」，和 conscience（意识）同家。","tr":{"zh":"我很清楚这个风险。","fr":"Je suis conscient du risque.","alt":"Je sais bien que c'est risqué.","note":"conscient de + 名词。"}},
 "Intelligent(e)": {"pos":"adj. 形容词，阴性 intelligente，复数 intelligents / intelligentes","s":"聪明的；有智慧的。可修饰人或物：un élève intelligent；une idée intelligente（聪明的主意）；un téléphone intelligent 也可指智能的（更常说 smartphone）。","ipa":"[ɛ̃.te.li.ʒɑ̃]","ph":"in 读鼻化 [ɛ̃]；t 读 [t]；g 在 e 前读 [ʒ]；ent 读 [ɑ̃]，t 不发音。","pi":"g 读 [ʒ]，不是 [g]；阳性末尾 t 不发音，阴性 intelligente 才发 [t]。","et":"来自拉丁语 intelligens，源自 intelligere（理解，inter「在……之间」+ legere「选择、读」）。同族：intelligence、intellectuel。","ex":[["Cet enfant est très intelligent.","这个孩子很聪明。"],["Elle a eu une idée intelligente.","她想到了一个聪明的主意。"],["Mon chat est plus intelligent que mon chien.","我的猫比我的狗聪明。"]],"co":[["très / assez intelligent(e)","很 / 相当聪明"],["une idée intelligente","聪明的主意"],["l'intelligence artificielle","人工智能"]],"sy":[["malin / maligne","familier","机灵的、精明的"],["brillant(e)","courant","出色的、才华出众的"],["bête","familier","笨的（反义）"]],"fq":"极高频，日常常用。","me":"intelligent 和英语 intelligent 几乎一样，注意发音。","tr":{"zh":"你的主意真聪明。","fr":"Ton idée est vraiment intelligente.","alt":"C'est une idée intelligente, bravo !","note":"形容词和名词的性数一致：idée 是阴性。"}},
 "Métallique": {"pos":"adj. 形容词，阴阳同形：métallique；复数 métalliques","s":"金属的；金属制的；像金属的。une porte métallique（金属门）；un bruit métallique（金属般的声响）。名词是 le métal（金属）。","ipa":"[me.ta.lik]","ph":"é 读 [e]；a 读 [a]；ll 在这里读单个 [l]；-ique 读 [ik]，qu 读 [k]。","pi":"ll 只读一个 [l]；结尾 -que 读 [k]，e 不发音。","et":"métal（金属）+ -ique。métal 来自拉丁语 metallum，源自希腊语 metallon（矿）。","ex":[["La porte est métallique.","门是金属的。"],["Il y a un bruit métallique dans la cuisine.","厨房里有金属的声响。"],["Elle porte une montre métallique.","她戴着一块金属表。"]],"co":[["un objet métallique","金属物品"],["un bruit métallique","金属般的声响"],["une structure métallique","金属结构"]],"sy":[["en métal","courant","金属制的（更常用的口语说法）"],["en fer / en acier","courant","铁制的 / 钢制的"]],"fq":"中频。","me":"métal + -ique：像英语 metallic。","tr":{"zh":"这把椅子是金属的。","fr":"Cette chaise est métallique.","alt":"Cette chaise est en métal.","note":"métallique 阴阳同形；也可说 en métal。"}},
 "Nombreux / Nombreuse": {"pos":"adj. 形容词，阳性 nombreux，阴性 nombreuse，复数 nombreux / nombreuses","s":"众多的；数量多的。主要用于复数：Les visiteurs sont nombreux。de nombreux + 复数名词 = 许多：de nombreux touristes。阴性单数少用，如 une famille nombreuse（大家庭）。","ipa":"[nɔ̃.bʁø]","ph":"on 读鼻化 [ɔ̃]；br 读 [bʁ]；eux 读 [ø]，x 不发音；阴性 nombreuse 读 [nɔ̃.bʁøz]，s 读 [z]。","pi":"阳性 -eux 的 x 不发音；阴性 nombreuse 的 s 发 [z]；别写成 nombreu。","et":"nombre（数）+ -eux。nombre 来自拉丁语 numerus。","ex":[["Les visiteurs sont nombreux.","参观者很多。"],["De nombreux touristes viennent ici.","许多游客来这里。"],["C'est une famille nombreuse.","这是一个大家庭。"]],"co":[["de nombreux + 复数名词","许多……"],["être nombreux","人数很多"],["une famille nombreuse","多子女家庭"]],"sy":[["beaucoup de","courant","许多（更口语）"],["multiple","soutenu","多重的、众多的"],["rare","courant","稀少（反义）"]],"fq":"高频，书面语和日常都常用。","me":"nombre（数）+ eux：数量很多的。","tr":{"zh":"今天来的人很多。","fr":"Aujourd'hui, les gens sont nombreux.","alt":"Il y a beaucoup de monde aujourd'hui.","note":"nombreux 通常配复数；单数集体名词要小心。"}},
 "Sain(e)": {"pos":"adj. 形容词，阴性 saine，复数 sains / saines","s":"健康的；有益健康的；健全的。une alimentation saine（健康饮食）；sain et sauf（平安无事）。形容人和事物都可；指人身体好常用 en bonne santé。","ipa":"[sɛ̃]","ph":"ain 读鼻化 [ɛ̃]；结尾 n 不发音；阴性 saine 读 [sɛn]，n 要发。","pi":"sain / saint / sein / ceint 同音 [sɛ̃]，拼写不同；阳性不发 n，阴性才发 [n]。","et":"来自拉丁语 sanus（健康的）。同族：santé、sanitaire。","ex":[["Manger des fruits est sain.","吃水果有益健康。"],["Elle a une vie très saine.","她的生活方式很健康。"],["Ils sont rentrés sains et saufs.","他们平安回来了。"]],"co":[["une alimentation saine","健康饮食"],["sain et sauf","平安无事"],["un esprit sain dans un corps sain","健全的精神寓于健康的身体"]],"sy":[["bon pour la santé","courant","对健康有益的"],["en bonne santé","courant","（人）健康的"],["malsain","courant","不健康的（反义）"]],"fq":"中频，饮食和生活话题常用。","me":"sain 和 santé 同族：sain → santé。","tr":{"zh":"我想吃得更健康。","fr":"Je veux manger sain.","alt":"Je veux avoir une alimentation plus saine.","note":"manger sain：sain 在这里作副词用法，不变。"}},
 "Secret / Secrète": {"pos":"adj. 形容词，阳性 secret，阴性 secrète，复数 secrets / secrètes","s":"秘密的；保密的；隐蔽的。un document secret（机密文件）；une recette secrète（秘方）。也是名词：un secret（秘密）。","ipa":"[sə.kʁɛ]","ph":"se 读 [sə]；cr 读 [kʁ]；阳性 -et 读 [ɛ]，t 不发音；阴性 secrète 读 [sə.kʁɛt]，t 要发。","pi":"阴性有重音符：secrète（不是 secrette）；阳性结尾 t 不发音。","et":"来自拉丁语 secretus（分开的），源自 secernere（分离）。同族：secrétaire（最初是掌握秘密的人）。","ex":[["C'est un document secret.","这是一份机密文件。"],["Elle a une recette secrète.","她有一个秘方。"],["Gardons ça secret !","我们保密吧！"]],"co":[["un document secret","机密文件"],["garder un secret","保守秘密"],["en secret","秘密地"],["un agent secret","特工"]],"sy":[["confidentiel / confidentielle","soutenu","保密的，文件和业务里用"],["caché(e)","courant","藏起来的"],["public / publique","courant","公开的（反义）"]],"fq":"中高频。","me":"secrète 带一个 è：t 要发出来。","tr":{"zh":"这是一个秘密，别告诉任何人。","fr":"C'est un secret, ne le dis à personne.","alt":"Garde ça pour toi, c'est secret.","note":"ne… personne：不告诉任何人。"}},
 "Solaire": {"pos":"adj. 形容词，阴阳同形：solaire；复数 solaires","s":"太阳的；太阳能的。un panneau solaire（太阳能板）；la crème solaire（防晒霜）；le système solaire（太阳系）；l'énergie solaire（太阳能）。","ipa":"[sɔ.lɛʁ]","ph":"so 读 [sɔ]；laire 读 [lɛʁ]，r 要发。","pi":"-aire 读 [ɛʁ]，r 不能省；阴阳同形，不加 e。","et":"来自拉丁语 solaris，源自 sol（太阳）。同族：soleil、solarium。","ex":[["J'utilise un panneau solaire.","我用太阳能板。"],["N'oublie pas la crème solaire !","别忘了防晒霜！"],["La Terre fait partie du système solaire.","地球属于太阳系。"]],"co":[["un panneau solaire","太阳能板"],["la crème solaire","防晒霜"],["l'énergie solaire","太阳能"],["le système solaire","太阳系"]],"sy":[["lunaire","courant","月亮的（对应词）"],["photovoltaïque","soutenu","光伏的（技术词）"]],"fq":"中频，环保和夏天话题里常见。","me":"sol- 同 soleil：太阳。","tr":{"zh":"我家屋顶上有太阳能板。","fr":"Il y a des panneaux solaires sur le toit de ma maison.","alt":"Ma maison a des panneaux solaires sur le toit.","note":"il y a + 复数名词。"}},
 "Spatial(e)": {"pos":"adj. 形容词，阴性 spatiale，阳性复数 spatiaux，阴性复数 spatiales","s":"太空的；空间的。la station spatiale（空间站）；l'agence spatiale（航天局）；une fusée spatiale。也可指「空间上的」（les relations spatiales）。","ipa":"[spa.sjal]","ph":"sp 读 [sp]；ti 在这里读 [sj]；阳性 spatial 读 [spa.sjal]，l 要发。","pi":"阳性复数是 spatiaux，不是 spatials；t 在这里读 [s]。","et":"来自拉丁语 spatium（空间、间隔）。同族：espace（空间；太空）。","ex":[["La station spatiale est grande.","空间站很大。"],["Elle rêve de devenir astronaute dans l'agence spatiale.","她梦想在航天局当宇航员。"],["Les missions spatiales coûtent cher.","太空任务花费很高。"]],"co":[["la station spatiale","空间站"],["une mission spatiale","太空任务"],["une navette spatiale","航天飞机"],["l'agence spatiale","航天局"]],"sy":[["cosmique","soutenu","宇宙的"],["l'espace","courant","太空（名词）"]],"fq":"中频，科技新闻里常见。","me":"spatial ← espace：太空的。","tr":{"zh":"他想参加太空任务。","fr":"Il veut participer à une mission spatiale.","alt":"Il rêve de faire une mission spatiale.","note":"participer à + 名词。"}},
 "Technologique": {"pos":"adj. 形容词，阴阳同形：technologique；复数 technologiques","s":"技术的；科技的。un progrès technologique（技术进步）；une innovation technologique（科技创新）。名词是 la technologie（科技）。","ipa":"[tɛk.nɔ.lɔ.ʒik]","ph":"tech 读 [tɛk]；ch 在这里读 [k]；g 在 i 前读 [ʒ]；-que 读 [k]。","pi":"tech- 的 ch 读 [k]，不是 [ʃ]；g 读 [ʒ]。","et":"来自希腊语 tekhnē（技艺）+ logos（学问）+ -ique。同族：technique、technologie。","ex":[["C'est un progrès technologique.","这是技术进步。"],["Cette entreprise fait de l'innovation technologique.","这家公司做科技创新。"],["Nous vivons dans un monde très technologique.","我们生活在一个科技很发达的世界。"]],"co":[["un progrès technologique","技术进步"],["une innovation technologique","科技创新"],["l'évolution technologique","技术演变"]],"sy":[["technique","courant","技术性的，更偏方法"],["high-tech","familier","高科技的"]],"fq":"中频，新闻和工作里常见。","me":"techno-logique：技艺 + 学问。","tr":{"zh":"科技进步很快。","fr":"Le progrès technologique est très rapide.","alt":"La technologie avance vite.","note":"progrès 是阳性名词。"}},
 "Avoir peur de...": {"pos":"loc.v. 动词短语，avoir 是不规则动词；avoir peur de + 名词 / 动词原形","s":"害怕……。avoir peur de + 名词 / 动词原形：J'ai peur des chiens；J'ai peur de tomber。后接从句用 avoir peur que + 虚拟式。peur 是名词，所以不说 être peur。","ipa":"[a.vwaʁ pœʁ də]","ph":"avoir 读 [a.vwaʁ]；peur 读 [pœʁ]，eu 读 [œ]；de 读 [də]，遇元音省音：d'un chien。","pi":"用 avoir，不是 être；peur 是阴性名词，不变；de 遇元音要省音成 d'。","et":"peur 来自拉丁语 pavor（恐惧）。同族：apeurer、peureux。","ex":[["J'ai peur de l'obscurité.","我怕黑。"],["Elle a peur de prendre l'avion.","她怕坐飞机。"],["N'aie pas peur !","别害怕！"]],"co":[["avoir peur de + 名词","害怕某物"],["avoir peur de + 动词原形","害怕做某事"],["avoir peur que + 虚拟式","担心……"],["faire peur à quelqu'un","吓到某人"]],"sy":[["craindre","soutenu","畏惧、担心"],["flipper","familier","吓得发慌"]],"fq":"极高频，日常常用。","me":"法语用「拥有」恐惧：avoir peur，不是「是」恐惧。","tr":{"zh":"我怕蜘蛛。","fr":"J'ai peur des araignées.","alt":"Les araignées me font peur.","note":"de + les 缩合为 des。"}},
 "C'est la panique !": {"pos":"loc. 固定感叹语；panique 为阴性名词（la panique）","s":"一片恐慌！乱成一团！在突发混乱时的口语说法，也可开玩笑地用：Demain, l'examen, c'est la panique ! 相近说法 C'est la catastrophe !","ipa":"[sɛ la pa.nik]","ph":"c'est 读 [sɛ]，t 不发音；la 读 [la]；panique 读 [pa.nik]，qu 读 [k]。","pi":"panique 是阴性名词，用 la，不要用 le；qu 读 [k]。","et":"panique 来自希腊语 panikos，源自牧神 Pan。","ex":[["Quand le feu commence, c'est la panique !","着火时一片恐慌！"],["Le train est en retard, c'est la panique !","火车晚点了，乱成一团！"],["Pas de panique !","别慌！"]],"co":[["c'est la panique","一片恐慌"],["pas de panique !","别慌！"],["être pris(e) de panique","陷入恐慌"]],"sy":[["c'est le chaos","courant","一片混乱"],["c'est la catastrophe","courant","糟了"]],"fq":"中频，口语里很常用。","me":"Pan 神一出现，大家就 la panique。","tr":{"zh":"考试明天开始，我完全慌了！","fr":"L'examen est demain, c'est la panique !","alt":"L'examen, c'est demain, je panique !","note":"c'est + 冠词 + 名词，口语里常用的感叹结构。"}},
 "Demander son chemin": {"pos":"loc.v. 动词短语；demander 第一组动词；所有格随主语变化：mon / ton / son / notre / leur chemin","s":"问路。所有格要和主语一致：Je demande mon chemin，Elle demande son chemin。问具体地点用 demander le chemin de la gare（问去火车站的路）。","ipa":"[də.mɑ̃.de sɔ̃ ʃə.mɛ̃]","ph":"demander 读 [də.mɑ̃.de]；son 读鼻化 [sɔ̃]；ch 读 [ʃ]；chemin 读 [ʃə.mɛ̃]。","pi":"所有格是 mon / ton / son 等，跟主语走，不是 le；ch 读 [ʃ]；min 读鼻化 [mɛ̃]。","et":"demander 来自拉丁语 demandare（托付）；chemin 来自高卢-罗曼语词，来源不确定。","ex":[["Je dois demander mon chemin.","我得问路。"],["Elle demande son chemin à un passant.","她向一个路人问路。"],["Excusez-moi, pour aller à la gare, s'il vous plaît ?","打扰一下，请问去火车站怎么走？"]],"co":[["demander son chemin à quelqu'un","向某人问路"],["demander le chemin de la gare","问去火车站的路"],["chercher son chemin","找路"]],"sy":[["demander la route","courant","也可以说，更偏开车"],["se renseigner","courant","打听消息"]],"fq":"高频，旅行时必备。","me":"法语问路带上「自己的」路：mon / ton / son chemin。","tr":{"zh":"我迷路了，我得问路。","fr":"Je suis perdu, je dois demander mon chemin.","alt":"Je me suis perdu, je vais demander mon chemin.","note":"所有格 mon 随主语 je。"}},
 "Être accro à": {"pos":"loc.v. 动词短语；être 不规则动词；形容词 accro 阴阳同形，复数 accros","s":"对……上瘾；迷上了。口语说法，可指烟、酒，也常指手机、游戏、剧集：accro au chocolat。accro 是 accroché 的缩写。后面接 à（à + le = au）。","ipa":"[ɛtʁ a.kʁo a]","ph":"être 读 [ɛtʁ]；accro 读 [a.kʁo]，cc 在这里读单个 [k]；à 读 [a]。","pi":"accro 的 cc 读一个 [k]；结尾 o 不发音为 [o]；à + le 要缩合成 au。","et":"accro 是 accroché（被钩住）的缩写；accrocher 与 croc（钩子）有关。","ex":[["Il est accro à son téléphone.","他迷上了手机。"],["Je suis accro au chocolat.","我对巧克力上了瘾。"],["Elle est accro à cette série.","她迷上了这部剧。"]],"co":[["être accro à son téléphone","手机成瘾"],["être accro au sport","迷上运动"],["devenir accro","上瘾"]],"sy":[["être dépendant(e) de","courant","依赖（较中性）"],["être mordu(e) de","familier","热衷于"],["être addict à","familier","上瘾（受英语影响）"]],"fq":"中频，口语常用。","me":"accro ← accroché：被「钩住」放不下。","tr":{"zh":"我对咖啡上瘾了。","fr":"Je suis accro au café.","alt":"Je ne peux pas me passer de café.","note":"à + le = au；accro à + 名词。"}},
 "Faire une recherche": {"pos":"loc.v. 动词短语；faire 不规则动词；recherche 为阴性名词，复数 des recherches","s":"做调查；搜索；查一查。faire une recherche sur internet / sur Google（上网搜索）；faire des recherches sur qqch（对某事做研究）。faire de la recherche 则指「从事科研」。","ipa":"[fɛʁ yn ʁə.ʃɛʁʃ]","ph":"faire 读 [fɛʁ]；une 读 [yn]；recherche 读 [ʁə.ʃɛʁʃ]，ch 读 [ʃ]。","pi":"ch 读 [ʃ]，不是 [k]；recherche 是阴性名词，用 une；表示研究用复数 des recherches。","et":"re- + chercher（寻找）。chercher 来自拉丁语 circare（四处走）。","ex":[["Je dois faire une recherche sur internet.","我得上网查一查。"],["Elle fait des recherches sur l'histoire de Paris.","她在研究巴黎的历史。"],["Il fait de la recherche en biologie.","他从事生物学研究。"]],"co":[["faire une recherche sur internet","上网搜索"],["faire des recherches sur…","对……做研究"],["un moteur de recherche","搜索引擎"],["la recherche scientifique","科学研究"]],"sy":[["chercher","courant","找、查"],["googler","familier","谷歌一下"],["enquêter","soutenu","调查"]],"fq":"高频，学习和工作中常用。","me":"re-chercher：再三去找，就是搜索。","tr":{"zh":"我想在网上查一些信息。","fr":"Je veux faire une recherche sur internet.","alt":"Je vais chercher des infos sur internet.","note":"faire une recherche sur + 主题。"}},
 "Passer X heures": {"pos":"loc.v. 动词短语；passer 第一组动词，助动词 avoir；X 为数字：deux, trois…","s":"花（若干）小时；待了几个小时。passer + 时长 + à + 动词原形 / 地点：passer deux heures à lire；passer trois heures au bureau。强调时间在做某事中度过。","ipa":"[pa.se œʁ]","ph":"passer 读 [pa.se]，ss 读 [s]；heures 读 [œʁ]，h 不发音，遇数字连读：deux heures 读 [dø.zœʁ]。","pi":"heure 是阴性名词，数字后用复数 heures；deux heures 要连读 z；h 不发音。","et":"passer 来自晚期拉丁语 passare，源自 passus（步）；heure 来自拉丁语 hora，源自希腊语。","ex":[["J'ai passé deux heures dans le métro.","我在地铁里待了两个小时。"],["Elle passe trois heures à étudier.","她花三个小时学习。"],["Nous avons passé cinq heures à la plage.","我们在海滩待了五个小时。"]],"co":[["passer deux heures à + 动词原形","花两小时做某事"],["passer du temps avec quelqu'un","和某人共度时光"],["passer la journée / la soirée","度过一天 / 一晚"]],"sy":[["consacrer du temps à","soutenu","把时间用于"],["rester","courant","待着；rester deux heures"]],"fq":"极高频，日常常用。","me":"passer = 让时间「过去」：passer deux heures。","tr":{"zh":"我每天花一个小时看书。","fr":"Je passe une heure à lire chaque jour.","alt":"Chaque jour, je lis pendant une heure.","note":"passer + 时长 + à + 动词原形。"}},
 "Perdre du/son temps": {"pos":"loc.v. 动词短语；perdre 第三组动词（-dre），助动词 avoir；temps 为阳性名词，单复数同形","s":"浪费时间；耽误时间。perdre son temps 指白费时间（所有格随主语变化）；perdre du temps 指「损失了一些时间」。常见结构：perdre son temps à + 动词原形。","ipa":"[pɛʁdʁ dy / sɔ̃ tɑ̃]","ph":"perdre 读 [pɛʁdʁ]，结尾 e 不发音；du 读 [dy]；son 读 [sɔ̃]；temps 读 [tɑ̃]，ps 不发音。","pi":"temps 结尾 ps 不发音；所有格 mon / ton / son 随主语变；du 是部分冠词。","et":"perdre 来自拉丁语 perdere；temps 来自拉丁语 tempus。","ex":[["Je ne veux pas perdre mon temps.","我不想浪费时间。"],["Tu perds du temps avec ce jeu.","你在这个游戏上浪费时间。"],["Il perd son temps à regarder des vidéos.","他把时间浪费在看视频上。"]],"co":[["perdre son temps à + 动词原形","把时间浪费在做某事上"],["ne pas perdre de temps","不浪费时间"],["perdre un temps fou","浪费大量时间"]],"sy":[["gaspiller son temps","courant","浪费时间，语气稍重"],["traîner","familier","磨蹭"],["gagner du temps","courant","节省时间（反义）"]],"fq":"高频，日常常用。","me":"perdre = 丢，丢掉的是 son temps。","tr":{"zh":"别在手机上浪费时间。","fr":"Ne perds pas ton temps sur ton téléphone.","alt":"Arrête de perdre du temps avec ton portable.","note":"命令式否定；所有格 ton 对应 tu。"}},
 "Du boeuf bourguignon": {"pos":"n.m. 阳性名词，不可数时用部分冠词 du；复数 bœufs（bœuf 的复数读 [bø]）","s":"勃艮第红酒炖牛肉，法国经典家常菜：牛肉、红酒、胡萝卜、洋葱、蘑菇慢炖。du 是部分冠词，表示「一些」。正确拼写是 bœuf（书上写作 boeuf）。","ipa":"[bœf buʁ.gi.ɲɔ̃]","ph":"bœuf 读 [bœf]，f 要发；bourguignon 读 [buʁ.gi.ɲɔ̃]，ou 读 [u]，gu 读 [g]，gn 读 [ɲ]，on 鼻化。","pi":"bœuf 单数 f 要发，复数 bœufs 读 [bø]；gn 读 [ɲ]；bourguignon 里的 u 不发音，gu 读 [g]。","et":"bœuf 来自拉丁语 bos, bovis（牛）；bourguignon 是 Bourgogne（勃艮第）的形容词，意为「勃艮第式的」。","ex":[["Le boeuf bourguignon est un plat français.","勃艮第炖牛肉是一道法国菜。"],["Ma grand-mère prépare du boeuf bourguignon le dimanche.","我奶奶周日做勃艮第炖牛肉。"],["Je prends le boeuf bourguignon avec des pommes de terre.","我点勃艮第炖牛肉配土豆。"]],"co":[["du boeuf bourguignon","（一些）勃艮第炖牛肉"],["faire mijoter un boeuf bourguignon","慢炖勃艮第牛肉"],["un plat mijoté","炖菜"]],"sy":[["un bœuf mode","soutenu","另一道传统炖牛肉"],["un ragoût","courant","炖菜（更泛指）"]],"fq":"中频，菜单和美食话题里常见。","me":"bourguignon = 来自 Bourgogne 的：勃艮第式。","tr":{"zh":"周日我们吃勃艮第炖牛肉。","fr":"Dimanche, nous mangeons du boeuf bourguignon.","alt":"Dimanche, on mange du bœuf bourguignon.","note":"manger du + 阳性名词：吃一些……。"}},
 "Du confit de canard": {"pos":"n.m. 阳性名词，du 为部分冠词；confit 复数 confits","s":"油封鸭，法国西南部的名菜：把鸭腿用鸭油低温慢煮保存。通常说 du confit de canard 或 un confit de canard（一份油封鸭）。confit 作形容词也有「浸渍的」意思，如 fruits confits（蜜饯）。","ipa":"[kɔ̃.fi də ka.naʁ]","ph":"confit 读 [kɔ̃.fi]，on 鼻化，t 不发音；de 读 [də]；canard 读 [ka.naʁ]，d 不发音，r 要发。","pi":"confit 的 t 不发音；canard 的 d 不发音但 r 要发。","et":"confit 是 confire（浸渍、保存）的过去分词，confire 来自拉丁语 conficere（制成）。canard 的来源不确定。","ex":[["C'est du confit de canard.","这是油封鸭。"],["Le confit de canard est une spécialité du Sud-Ouest.","油封鸭是法国西南部的特色菜。"],["Je prends du confit de canard avec des pommes sautées.","我点油封鸭配煎土豆。"]],"co":[["du confit de canard","（一些）油封鸭"],["une cuisse de canard confite","油封鸭腿"],["des fruits confits","蜜饯水果"]],"sy":[["un magret de canard","courant","鸭胸肉（另一道名菜）"],["une cuisse de canard","courant","鸭腿"]],"fq":"中低频，餐厅菜单里常见。","me":"confit ← confire：用油「封」住保存。","tr":{"zh":"我今晚想吃油封鸭。","fr":"Ce soir, je veux manger du confit de canard.","alt":"Ce soir, j'ai envie de confit de canard.","note":"avoir envie de + 名词（不加冠词）。"}},
 "Du jambon": {"pos":"n.m. 阳性名词，du 为部分冠词；复数 jambons","s":"火腿。jambon blanc（熟火腿，法国最常见）、jambon cru（生火腿）、jambon fumé（烟熏火腿）。不可数时用 du jambon；一片用 une tranche de jambon。","ipa":"[ʒɑ̃.bɔ̃]","ph":"j 读 [ʒ]；am 在 b 前读鼻化 [ɑ̃]；on 读鼻化 [ɔ̃]；n 不发音。","pi":"两个鼻化音不同：jam 读 [ɑ̃]，bon 读 [ɔ̃]；j 读 [ʒ]。","et":"jambe（腿）+ -on。jambe 来自晚期拉丁语 gamba（腿）。","ex":[["Je fais un sandwich au jambon.","我做火腿三明治。"],["Tu veux du jambon ou du fromage ?","你要火腿还是奶酪？"],["Elle achète quatre tranches de jambon blanc.","她买四片熟火腿。"]],"co":[["une tranche de jambon","一片火腿"],["du jambon blanc / cru / fumé","熟 / 生 / 烟熏火腿"],["un sandwich au jambon","火腿三明治"]],"sy":[["la charcuterie","courant","冷盘肉制品总称"],["le saucisson","courant","香肠，另一种肉制品"]],"fq":"高频，日常饮食常用。","me":"jambon 来自 jambe（腿）：猪腿做的。","tr":{"zh":"我想要两片火腿。","fr":"Je voudrais deux tranches de jambon.","alt":"Deux tranches de jambon, s'il vous plaît.","note":"une tranche de + 无冠词名词。"}},
 "Du persil": {"pos":"n.m. 阳性名词，du 为部分冠词；复数 persils（少用）","s":"欧芹，一种常见的香草，用来调味和装饰。通常不可数：du persil；一把可以说 un bouquet de persil。le persil plat 是平叶欧芹，le persil frisé 是卷叶欧芹。","ipa":"[pɛʁ.si]","ph":"per 读 [pɛʁ]；sil 读 [si]，结尾 l 不发音。","pi":"结尾 -il 的 l 不发音，所以读 [pɛʁ.si]，不是 [pɛʁ.sil]（同类：outil, fusil）。","et":"来自拉丁语 petroselinum，源自希腊语 petroselinon（岩芹）。","ex":[["Il y a du persil dans la soupe.","汤里有欧芹。"],["Ajoute un peu de persil sur les pommes de terre.","在土豆上撒一点欧芹。"],["Je coupe le persil très fin.","我把欧芹切得很细。"]],"co":[["du persil frais","新鲜欧芹"],["hacher du persil","把欧芹切碎"],["un bouquet de persil","一把欧芹"]],"sy":[["la coriandre","courant","香菜，和欧芹长得像但味道不同"],["la ciboulette","courant","细香葱"]],"fq":"中频，做饭时常用。","me":"persil 的 l 是哑的，读起来像「佩尔西」。","tr":{"zh":"请在汤里加一点欧芹。","fr":"Ajoute un peu de persil dans la soupe, s'il te plaît.","alt":"Mets un peu de persil dans la soupe.","note":"un peu de + 无冠词名词。"}},
 "Du porc": {"pos":"n.m. 阳性名词，du 为部分冠词；复数 porcs（指猪）","s":"猪肉。指肉时不可数：du porc；指动物是 un porc 或 un cochon。côtelette de porc（猪排）、rôti de porc（烤猪肉）。","ipa":"[pɔʁ]","ph":"p 读 [p]；o 读开口 [ɔ]；r 读 [ʁ]；结尾 c 不发音。","pi":"porc 的 c 不发音，只读 [pɔʁ]；别读成 [pɔʁk]。","et":"来自拉丁语 porcus（猪）。同族：porcin（猪的）。","ex":[["Je mange du porc.","我吃猪肉。"],["Il cuit un rôti de porc au four.","他在烤箱里烤猪肉。"],["Elle ne mange pas de porc.","她不吃猪肉。"]],"co":[["du porc / de la viande de porc","猪肉"],["une côtelette de porc","猪排"],["un rôti de porc","烤猪肉"],["ne pas manger de porc","不吃猪肉"]],"sy":[["le cochon","courant","猪（动物），也可指肉"],["le bœuf","courant","牛肉，对比词"]],"fq":"高频，饮食话题常用。","me":"porc 的 c 是哑的：「波尔」。","tr":{"zh":"我不吃猪肉，只吃鸡肉。","fr":"Je ne mange pas de porc, seulement du poulet.","alt":"Pas de porc pour moi, je mange du poulet.","note":"否定句中 du 变成 de：ne… pas de porc。"}},
 "Du vin (blanc, rosé, rouge)": {"pos":"n.m. 阳性名词，du 为部分冠词；复数 vins（指不同种类的酒）","s":"葡萄酒。du vin blanc / rosé / rouge：白 / 桃红 / 红葡萄酒。un verre de vin（一杯葡萄酒）；un vin 指一种酒，如 un bon vin。","ipa":"[vɛ̃]","ph":"v 读 [v]；in 读鼻化 [ɛ̃]；n 不发音。rosé 读 [ʁo.ze]。","pi":"vin 的 n 不发音；颜色形容词放后面：vin rouge（不是 rouge vin）。","et":"来自拉丁语 vinum（酒）。同族：vigne（葡萄藤）、vinaigre（醋）。","ex":[["Je bois du vin.","我喝葡萄酒。"],["Elle préfère le vin blanc.","她更喜欢白葡萄酒。"],["Un verre de vin rouge, s'il vous plaît.","请来一杯红葡萄酒。"]],"co":[["du vin rouge / blanc / rosé","红 / 白 / 桃红葡萄酒"],["un verre de vin","一杯葡萄酒"],["une bouteille de vin","一瓶葡萄酒"],["du vin chaud","热红酒"]],"sy":[["la bière","courant","啤酒，对比词"],["le pinard","familier","红酒（口语）"]],"fq":"极高频，法国饮食文化的核心词。","me":"vin 和英语 wine 同源：v 对 w。","tr":{"zh":"晚饭时我想喝一杯红酒。","fr":"Au dîner, je voudrais un verre de vin rouge.","alt":"Je prendrais bien un verre de vin rouge ce soir.","note":"un verre de + 无冠词名词。"}},
 "Le cadre": {"pos":"n.m. 阳性名词，复数 des cadres","s":"环境；背景；框；管理人员。这里取「环境」义：un cadre agréable（舒适的环境）。还有「画框」un cadre photo，以及公司里的「中高层员工」un cadre。dans le cadre de = 在……范围内。","ipa":"[kadʁ]","ph":"ca 读 [ka]；-dre 读 [dʁ]，e 不发音，整体一个音节。","pi":"cadre 只有两个音 [ka] + [dʁ]，结尾 e 不发音；一词多义，需看语境。","et":"来自意大利语 quadro（方形），源自拉丁语 quadrus（方的）。同族：quadrilatère。","ex":[["Ce restaurant est dans un cadre magnifique.","这家餐厅环境很美。"],["Elle est cadre dans une grande entreprise.","她在一家大公司当中层管理。"],["Dans le cadre du projet, nous travaillons ensemble.","在这个项目的框架下，我们一起工作。"]],"co":[["un cadre agréable / de vie","舒适的环境 / 生活环境"],["dans le cadre de","在……框架内"],["un cadre photo","相框"],["un cadre supérieur","高级管理人员"]],"sy":[["l'environnement","courant","环境，更泛"],["le décor","courant","布景、景致"],["le contexte","courant","背景、语境"]],"fq":"高频，多义词。","me":"cadre = 框：把景色和人都框在里面。","tr":{"zh":"这家酒店的环境很舒适。","fr":"Cet hôtel a un cadre très agréable.","alt":"Le cadre de cet hôtel est très agréable.","note":"cadre 是阳性：un cadre。"}},
 "Le jaune/blanc d'oeuf": {"pos":"n.m. 阳性名词，le jaune d'œuf（蛋黄）/ le blanc d'œuf（蛋白）；复数 les jaunes / les blancs d'œufs","s":"蛋黄 / 蛋白。le jaune d'œuf 是蛋黄，le blanc d'œuf 是蛋白。一个蛋是 un œuf，几个蛋是 des œufs。做菜时常说 séparer les blancs des jaunes（把蛋白和蛋黄分开）。","ipa":"[ʒon dœf] / [blɑ̃ dœf]","ph":"jaune 读 [ʒon]，au 读 [o]；blanc 读 [blɑ̃]，c 不发音；d'œuf 读 [dœf]，f 要发。","pi":"œuf 单数读 [œf]，f 要发；复数 œufs 读 [ø]，f 和 s 都不发音。","et":"jaune 来自拉丁语 galbinus（淡黄的）；blanc 来自日耳曼语（法兰克语）；œuf 来自拉丁语 ovum。","ex":[["Je sépare le blanc et le jaune d'oeuf.","我把蛋白和蛋黄分开。"],["Ajoutez deux jaunes d'œufs à la sauce.","往酱里加两个蛋黄。"],["Elle monte les blancs d'œufs en neige.","她把蛋白打发成雪状。"]],"co":[["séparer le blanc du jaune","把蛋白和蛋黄分开"],["monter les blancs en neige","把蛋白打发"],["un jaune d'œuf","一个蛋黄"]],"sy":[["le vitellus","littéraire","卵黄（科学用语）"],["l'albumen","soutenu","蛋白（科学用语）"]],"fq":"中频，做饭时常用。","me":"jaune = 黄，blanc = 白：颜色直接指蛋的两部分。","tr":{"zh":"用蛋黄做酱，蛋白留下来。","fr":"Utilise le jaune d'œuf pour la sauce, garde le blanc.","alt":"Mets le jaune dans la sauce et garde le blanc.","note":"祈使句，tu 形：utilise 没有 s。"}},
 "Un avis": {"pos":"n.m. 阳性名词，复数 des avis（s 不发音，单复数同形）","s":"意见；看法；评价；通知。给出看法：À mon avis, … = 我认为……。也指网上的评论：un avis client（顾客评价）。还指通知：un avis de passage（通知单）。","ipa":"[a.vi]","ph":"a 读 [a]；vi 读 [vi]；结尾 s 不发音。","pi":"avis 的 s 不发音；单复数同形 un avis / des avis。","et":"来自古法语 à vis（依我看），vis 来自拉丁语 visum（看来的）。同族：visage、viser。","ex":[["Quel est ton avis ?","你怎么看？"],["À mon avis, c'est une bonne idée.","我认为这是个好主意。"],["Les avis sur ce restaurant sont excellents.","这家餐厅的评价很好。"]],"co":[["à mon avis","依我看"],["donner son avis","发表意见"],["changer d'avis","改变主意"],["être du même avis","意见相同"]],"sy":[["l'opinion","courant","观点，较正式"],["le point de vue","courant","观点、角度"],["le commentaire","courant","评论"]],"fq":"极高频，日常常用。","me":"avis ← à vis：「在我看来」。","tr":{"zh":"你对这部电影怎么看？","fr":"Quel est ton avis sur ce film ?","alt":"Tu en penses quoi, de ce film ?","note":"avis sur + 事物；avis 的 s 不发音。"}},
 "Un bois": {"pos":"n.m. 阳性名词，复数 des bois（s 不发音，单复数同形）","s":"树林；小森林。比 forêt（森林）小：un petit bois。bois 还指木头（材料）：du bois（不加 un）。le bois de Boulogne 是巴黎西部著名的公园树林。","ipa":"[bwa]","ph":"b 读 [b]；ois 读 [wa]；结尾 s 不发音。","pi":"bois 的 s 不发音，读 [bwa]；和动词 boire 的 je bois 同音。","et":"来自日耳曼语（法兰克语）的词，一般认为词根是 *busk；英语 bush 与此同源。","ex":[["Il y a un petit bois près de chez moi.","我家附近有一片小树林。"],["Nous nous promenons dans le bois.","我们在树林里散步。"],["Cette table est en bois.","这张桌子是木头做的。"]],"co":[["un petit bois","小树林"],["se promener dans les bois","在林子里散步"],["en bois","木制的"],["le bois de Boulogne","布洛涅森林公园"]],"sy":[["la forêt","courant","森林，比 bois 大"],["un bosquet","soutenu","小树丛"]],"fq":"高频，一词多义。","me":"bois [bwa]，像英语 bush 的远亲。","tr":{"zh":"我们周末去树林里散步。","fr":"Ce week-end, nous nous promenons dans le bois.","alt":"Ce week-end, on va se balader dans les bois.","note":"se promener 是代动词，nous nous promenons。"}},
 "Un chou": {"pos":"n.m. 阳性名词，复数 des choux（-ou 名词中少数加 x 的）","s":"卷心菜；甘蓝。还有：chou-fleur（花椰菜）、choux de Bruxelles（抱子甘蓝）、chou à la crème（奶油泡芙）。mon chou 是对亲近的人的爱称，意为「我的宝贝」。","ipa":"[ʃu]","ph":"ch 读 [ʃ]；ou 读 [u]。","pi":"复数是 choux（加 x），不是 chous；ch 读 [ʃ]，不是 [k]。","et":"来自拉丁语 caulis（茎；卷心菜）。","ex":[["Le chou est bon.","卷心菜很好吃。"],["Je prépare une soupe au chou.","我做卷心菜汤。"],["Viens ici, mon chou !","过来，我的宝贝！"]],"co":[["un chou-fleur","花椰菜"],["des choux de Bruxelles","抱子甘蓝"],["un chou à la crème","奶油泡芙"],["mon chou","亲爱的"]],"sy":[["la salade","courant","生菜，不同蔬菜"],["mon cœur","courant","亲爱的（爱称）"]],"fq":"中频。","me":"chou = 「舒」：一个圆圆的卷心菜。","tr":{"zh":"我买了一个卷心菜做汤。","fr":"J'ai acheté un chou pour faire de la soupe.","alt":"J'ai pris un chou pour la soupe.","note":"pour + 动词原形：表示目的。"}},
 "Un croque-monsieur": {"pos":"n.m. 阳性名词，复合词（用连字符），复数 des croque-monsieur 或 des croque-monsieurs","s":"火腿奶酪热三明治：两片吐司夹火腿和奶酪，烤到金黄。咖啡馆的经典菜。加一个煎蛋就是 un croque-madame。","ipa":"[kʁɔk.mə.sjø]","ph":"croque 读 [kʁɔk]，qu 读 [k]；monsieur 读 [mə.sjø]，这个词发音特殊，不读 [mɔ̃.sjœʁ]。","pi":"monsieur 的发音是 [mə.sjø]；croque 结尾的 e 不发音；连字符不能漏。","et":"croquer（脆响地咬）+ monsieur（先生）：来自咖啡馆的叫法。","ex":[["Je prépare un croque-monsieur.","我做一个火腿奶酪三明治。"],["Elle commande un croque-monsieur et un café.","她点了一份火腿奶酪三明治和一杯咖啡。"],["Un croque-madame, c'est un croque-monsieur avec un œuf.","croque-madame 就是加了蛋的 croque-monsieur。"]],"co":[["un croque-monsieur au jambon","火腿奶酪三明治"],["un croque-madame","加煎蛋的三明治"],["commander un croque-monsieur","点一份 croque-monsieur"]],"sy":[["un sandwich chaud","courant","热三明治"],["un croque-madame","courant","加蛋的版本"]],"fq":"中频，咖啡馆菜单常见。","me":"croque（咬）+ monsieur：咬一口「先生」三明治。","tr":{"zh":"我中午要吃一个火腿奶酪三明治。","fr":"À midi, je mange un croque-monsieur.","alt":"Ce midi, je prends un croque-monsieur.","note":"à midi：中午；prendre 也可表示「点」。"}},
 "Un jambon-beurre": {"pos":"n.m. 阳性名词，复合词（连字符），复数 des jambons-beurre","s":"火腿黄油三明治：长棍面包夹火腿片和黄油，是法国最经典的快餐。面包店常见。也可说 un sandwich jambon-beurre。","ipa":"[ʒɑ̃.bɔ̃ bœʁ]","ph":"jambon 读 [ʒɑ̃.bɔ̃]；beurre 读 [bœʁ]，eu 读 [œ]，rr 读一个 [ʁ]，结尾 e 不发音。","pi":"beurre 的 eu 读 [œ]，不是 [u]；rr 只读一个 r；复数 jambons-beurre 是 jambon 加 s。","et":"jambon + beurre。beurre 来自拉丁语 butyrum，源自希腊语 boutyron（黄油）。","ex":[["Je prends un jambon-beurre à la boulangerie.","我在面包店买火腿黄油三明治。"],["Un jambon-beurre et un café, s'il vous plaît.","请来一个火腿黄油三明治和一杯咖啡。"],["Le jambon-beurre est mon sandwich préféré.","火腿黄油三明治是我最爱的三明治。"]],"co":[["un sandwich jambon-beurre","火腿黄油三明治"],["un jambon-beurre-fromage","加奶酪的版本"],["acheter un jambon-beurre","买一个火腿黄油三明治"]],"sy":[["un sandwich","courant","三明治（泛指）"],["un croque-monsieur","courant","热的火腿奶酪三明治"]],"fq":"中频，快餐场景常用。","me":"jambon + beurre：就是名字里的两样东西。","tr":{"zh":"中午我想吃一个火腿黄油三明治。","fr":"À midi, je veux un jambon-beurre.","alt":"Ce midi, j'ai envie d'un jambon-beurre.","note":"avoir envie de + 名词：de + un 变 d'un。"}},
 "Un litchi": {"pos":"n.m. 阳性名词，复数 des litchis；也拼 un letchi","s":"荔枝。外壳粗糙带红色，果肉白色多汁。常见于亚洲餐厅和水果摊：un litchi, des litchis。也作配料：des litchis au sirop（糖水荔枝）。","ipa":"[li.tʃi]","ph":"li 读 [li]；tch 读 [tʃ]（像「七」的 q 音）；i 读 [i]。","pi":"tch 合起来读 [tʃ]（像英语 church 开头的音），不是 [t] + [ʃ] 分开读；复数加 s，s 不发音。","et":"来自汉语「荔枝」（lìzhī）。","ex":[["Le litchi est sucré.","荔枝很甜。"],["J'achète des litchis au marché.","我在市场买荔枝。"],["Elle adore les litchis au sirop.","她爱吃糖水荔枝。"]],"co":[["un litchi frais","新鲜荔枝"],["des litchis au sirop","糖水荔枝"],["un jus de litchi","荔枝汁"]],"sy":[["le longane","courant","龙眼，相近的水果"],["le ramboutan","courant","红毛丹，相近的水果"]],"fq":"低频，水果店和亚洲餐厅里常见。","me":"litchi 就是汉语「荔枝」，tch 对应 zh/q 的感觉。","tr":{"zh":"我最喜欢的水果是荔枝。","fr":"Mon fruit préféré, c'est le litchi.","alt":"Mon fruit préféré est le litchi.","note":"c'est + 名词 在口语中用来强调。"}},
 "Un plat": {"pos":"n.m. 阳性名词，复数 des plats；作形容词 plat(e) 意为「平的」","s":"菜肴；一道菜；盘子。un plat principal（主菜）；le plat du jour（今日特色菜）。也指盛菜的大盘：un plat à four（烤盘）。形容词 plat 表示扁平的。","ipa":"[pla]","ph":"pl 读 [pl]；a 读 [a]；结尾 t 不发音。","pi":"plat 的 t 不发音，读 [pla]；复数 plats 的 t 和 s 都不发音。","et":"来自晚期拉丁语 plattus，源自希腊语 platys（扁平的）。本义是扁平的大盘。","ex":[["C'est un plat délicieux.","这是一道美味的菜。"],["Quel est le plat du jour ?","今日特色菜是什么？"],["Je prends le poulet comme plat principal.","主菜我点鸡肉。"]],"co":[["le plat principal","主菜"],["le plat du jour","今日特色菜"],["un plat cuisiné","现成菜肴"],["un plat à four","烤盘"]],"sy":[["le repas","courant","一顿饭"],["l'assiette","courant","盘子"]],"fq":"极高频，餐厅里必会。","me":"plat = 平的大盘子，端上桌的就是一道 plat。","tr":{"zh":"今日特色菜是什么？","fr":"Quel est le plat du jour ?","alt":"C'est quoi, le plat du jour ?","note":"quel 与阳性名词 plat 配合。"}},
 "Un poireau": {"pos":"n.m. 阳性名词，复数 des poireaux（-eau 加 x）","s":"韭葱（大葱状的蔬菜，白色根茎，绿色叶）。常用来煮汤、做 poireaux vinaigrette。口语 faire le poireau = 傻等、久等。","ipa":"[pwa.ʁo]","ph":"oi 读 [wa]；r 读 [ʁ]；eau 读 [o]。","pi":"poireau 的 oi 读 [wa]，别和 poire（梨）搞混；复数是 poireaux。","et":"来自古法语 porreau，源自拉丁语 porrum（韭葱）。","ex":[["J'achète un poireau.","我买一根韭葱。"],["La soupe aux poireaux est délicieuse.","韭葱汤很好喝。"],["J'ai fait le poireau devant la gare.","我在车站前傻等了很久。"]],"co":[["une soupe aux poireaux","韭葱汤"],["des poireaux vinaigrette","油醋汁韭葱"],["faire le poireau","久等（口语）"]],"sy":[["l'oignon","courant","洋葱，对比蔬菜"],["la ciboule","courant","小葱"]],"fq":"中频，做饭时常用。","me":"poireau ≠ poire：poire 是梨，poireau 是韭葱。","tr":{"zh":"我用韭葱做汤。","fr":"Je fais une soupe avec des poireaux.","alt":"Je prépare une soupe aux poireaux.","note":"soupe aux poireaux：aux = à + les。"}},
 "Un poulailler": {"pos":"n.m. 阳性名词，复数 des poulaillers","s":"鸡舍；鸡窝。养母鸡的小屋或围栏：les poules sont dans le poulailler。口语里 le poulailler 也指剧院最高处的廉价座位。","ipa":"[pu.la.je]","ph":"ou 读 [u]；ai 读 [a]；-ill- 读 [j]；er 读 [e]。","pi":"poulailler 里的 -ill- 读 [j]，不是 [il]；ou 读 [u]。","et":"poule（母鸡）+ -ailler（场所后缀）。poule 来自拉丁语 pulla（小母鸡）。","ex":[["Les poules sont dans le poulailler.","母鸡在鸡舍里。"],["Mon grand-père a construit un poulailler.","我爷爷盖了一个鸡舍。"],["Elle ferme le poulailler le soir.","她晚上把鸡舍关上。"]],"co":[["un poulailler en bois","木制鸡舍"],["fermer le poulailler","关上鸡舍"],["les poules du poulailler","鸡舍里的母鸡"]],"sy":[["l'enclos","courant","围栏"],["la basse-cour","courant","家禽饲养场"]],"fq":"中低频，农村和农场话题里常见。","me":"poule + -ailler：母鸡住的地方。","tr":{"zh":"母鸡晚上回到鸡舍。","fr":"Le soir, les poules rentrent dans le poulailler.","alt":"Les poules rentrent au poulailler le soir.","note":"rentrer dans / à：回到……里。"}},
 "Un problème d'argent": {"pos":"n.m. 阳性名词，复数 problèmes d'argent","s":"钱的问题；经济困难。problème 以 -e 结尾，却是阳性（希腊语来源的 -ème 词多为阳性）。常说 avoir des problèmes d'argent（手头紧）。","ipa":"[pʁɔ.blɛm.daʁ.ʒɑ̃]","ph":"problème：è [ɛ]，结尾 -me 的 e 不发音；d'argent 是 de + argent 省音；argent 的 -ent 读鼻化 [ɑ̃]，t 不发音。","pi":"problème 是阳性，不要说 une problème；argent 结尾 -ent 读 [ɑ̃]，不发 t。","et":"problème 来自希腊语 próblēma（摆在面前的难题），经拉丁语进入法语；argent 来自拉丁语 argentum（银）。","ex":[["Il a un problème d'argent.","他有金钱问题。"],["Nous avons des problèmes d'argent ce mois-ci.","这个月我们手头紧。"],["Un problème d'argent, ça arrive à tout le monde.","钱的问题，谁都会遇到。"]],"co":[["avoir un problème d'argent","有经济困难"],["un problème de santé / de temps","健康 / 时间问题"],["résoudre un problème","解决问题"],["pas de problème !","没问题！"]],"sy":[["difficulté financière","soutenu","经济困难，更书面"],["être fauché","familier","没钱，口语（形容词）"]],"fq":"高频，日常常用。","me":"problème 看似阴性却是阳性：un problème，像 un système、un thème。","tr":{"zh":"我们这个月有一点钱的问题。","fr":"Nous avons un petit problème d'argent ce mois-ci.","alt":"Ce mois-ci, on est un peu juste côté argent.","note":"problème d'argent 中 problème 为阳性，d' 后面不加冠词。"}},
 "Un pyjama": {"pos":"n.m. 阳性名词，复数 pyjamas","s":"睡衣（上衣加裤子的套装）。法语里 pyjama 是单数名词，一整套就是 un pyjama，不像英语常用复数。","ipa":"[pi.ʒa.ma]","ph":"py [pi]；j [ʒ]；每个 a 都读 [a]；结尾 a 清楚发音。","pi":"y 读 [i]，不是 [j]；j 读 [ʒ]（像「日」的浊音），不是英语 /dʒ/。","et":"来自印地语/乌尔都语 pāy-jāma（宽松的裤子），经英语 pyjamas 传入法语。","ex":[["Je mets mon pyjama pour dormir.","我穿睡衣睡觉。"],["Il reste en pyjama toute la matinée.","他整个早上都穿着睡衣。"],["Elle a un pyjama rose.","她有一套粉红色睡衣。"]],"co":[["mettre / enlever son pyjama","穿上 / 脱下睡衣"],["être en pyjama","穿着睡衣"],["une soirée pyjama","睡衣派对"],["un pyjama en coton","棉质睡衣"]],"sy":[["chemise de nuit","courant","睡裙，不是套装"],["nuisette","courant","吊带短睡裙"]],"fq":"中高频，日常常用。","me":"pyjama 一套就是 un pyjama：法语不说「一条睡衣裤」。","tr":{"zh":"孩子们还穿着睡衣。","fr":"Les enfants sont encore en pyjama.","alt":"Les enfants n'ont pas encore changé de pyjama.","note":"être en + 衣物 表示穿着：en pyjama。"}},
 "Un radis": {"pos":"n.m. 阳性名词，复数 radis（单复数同形）","s":"小萝卜（红皮、圆形，生吃，常蘸黄油和盐）。法国常见的开胃小菜。注意不是中国的白萝卜（那是 radis blanc / daikon）。","ipa":"[ʁa.di]","ph":"r 是小舌音 [ʁ]；a [a]；i [i]；结尾 s 不发音。","pi":"结尾 s 不发音；单复数都写 radis，读音也一样。","et":"来自意大利语 radice，源自拉丁语 radix（根）。同源：racine（根）。","ex":[["Je mange un radis.","我吃一个小萝卜。"],["Les radis sont croquants.","小萝卜脆脆的。"],["Il achète une botte de radis au marché.","他在市场买了一把小萝卜。"]],"co":[["une botte de radis","一把小萝卜"],["radis beurre","黄油小萝卜（经典吃法）"],["un radis noir / blanc","黑萝卜 / 白萝卜"],["ne pas avoir un radis","一分钱也没有（口语）"]],"sy":[["navet","courant","芜菁，另一种根菜"],["carotte","courant","胡萝卜"]],"fq":"中频，饮食话题常用。","me":"radis ← radix（根）：和 racine 同一个根。","tr":{"zh":"我在市场买了一把小萝卜。","fr":"J'ai acheté une botte de radis au marché.","alt":"J'ai pris des radis au marché.","note":"une botte de + 复数名词：一把……"}},
 "Un style": {"pos":"n.m. 阳性名词，复数 styles","s":"风格；文体；作风。可指穿衣风格、写作风格、体育动作风格。avoir du style = 有品位、有格调。","ipa":"[stil]","ph":"st [st]；y 读 [i]；l 要发音；结尾 e 不发音。","pi":"y 读 [i]，不是英语的 [aɪ]；l 要读出来：[stil]。","et":"来自拉丁语 stilus（书写用的尖笔）。拼写里的 y 是后来受希腊语影响加上的。","ex":[["J'aime son style.","我喜欢他的风格。"],["Elle a beaucoup de style.","她很有品位。"],["Ce n'est pas mon style.","这不是我的风格。"]],"co":[["avoir du style","有格调"],["ce n'est pas mon style","这不合我的口味"],["un style de vie","生活方式"],["en style libre","自由泳"]],"sy":[["genre","courant","类型、风格，更口语"],["manière","courant","方式、做法"],["allure","courant","外表、气质"]],"fq":"高频，日常常用。","me":"style ← stilus（笔）：写出来的「笔调」就是风格。","tr":{"zh":"我喜欢你的穿衣风格。","fr":"J'aime ton style vestimentaire.","alt":"Ton style, j'adore !","note":"style vestimentaire = 穿衣风格。"}},
 "De la crème": {"pos":"n.f. 阴性名词，不可数，常用 de la crème，复数 crèmes","s":"奶油；乳脂；护肤霜。做菜时指 crème fraîche（法式酸奶油）或 crème liquide（淡奶油）；也指 une crème（一杯奶咖，如 un café crème）。de la 是部分冠词，表示「一些」。","ipa":"[kʁɛm]","ph":"c [k]；r [ʁ]；è [ɛ]；结尾 -me 的 e 不发音。","pi":"è 读 [ɛ]，不是 [i]；注意重音符号 è。","et":"来源复杂，与拉丁语/希腊语里「涂油」一类的词混合而成，不能简单概括。同族词：crémeux（奶油般的）、crèmerie（乳品店）、écrémer（撇去奶油）。","ex":[["Je mets de la crème dans mon café.","我在咖啡里加奶油。"],["Elle met de la crème sur ses mains.","她在手上涂护手霜。"],["Je prends un café crème.","我要一杯奶咖。"]],"co":[["de la crème fraîche","酸奶油"],["de la crème chantilly / fouettée","打发的鲜奶油"],["une crème dessert","奶油布丁（杯装甜点）"],["une crème solaire","防晒霜"]],"sy":[["lait","courant","牛奶，更稀"],["chantilly","courant","打发奶油"]],"fq":"高频，饮食和日用品常用。","me":"crème 和英语 cream 一个意思；è 带重音，读 [ɛ]。","tr":{"zh":"你要在咖啡里加奶油吗？","fr":"Tu veux de la crème dans ton café ?","alt":"Un peu de crème dans ton café ?","note":"部分冠词 de la 表示不确定的量；否定后变 de：pas de crème。"}},
 "De la farine": {"pos":"n.f. 阴性名词，不可数，常用 de la farine，复数 farines（指不同种类）","s":"面粉。做蛋糕、面包、可丽饼都要用。法国面粉按 T45、T55 等型号分，farine de blé = 小麦粉，farine complète = 全麦粉。","ipa":"[fa.ʁin]","ph":"f [f]；a [a]；r [ʁ]；in 在这里读 [in]（后面有元音，不是鼻化）；结尾 e 不发音。","pi":"-ine 读 [in]，不是鼻化 [ɛ̃]。","et":"来自拉丁语 farina（粗磨的谷粉），与 far（一种谷物）有关。","ex":[["J'ai besoin de farine pour le gâteau.","我做蛋糕需要面粉。"],["Ajoute 200 grammes de farine.","加 200 克面粉。"],["Il n'y a plus de farine.","面粉没有了。"]],"co":[["de la farine de blé","小麦粉"],["de la farine complète","全麦粉"],["tamiser la farine","筛面粉"],["de la farine de sarrasin","荞麦粉"]],"sy":[["fécule","courant","淀粉（如土豆淀粉）"],["semoule","courant","粗粒麦粉"]],"fq":"中高频，烹饪常用。","me":"farine 里有 fa-ri-ne：想到「法」国的面粉。","tr":{"zh":"我需要两百克面粉和三个鸡蛋。","fr":"J'ai besoin de deux cents grammes de farine et de trois œufs.","alt":"Il me faut 200 g de farine et trois œufs.","note":"量词 + de + 无冠词名词：200 grammes de farine。"}},
 "De la mie de pain": {"pos":"n.f. 阴性名词，不可数，复数 mies","s":"面包心；面包里软的部分，对应硬的 croûte（面包皮）。也指做成碎屑的面包糠（chapelure 更常用）。","ipa":"[mi.də.pɛ̃]","ph":"mie [mi]；de 弱读 [də]；pain 读鼻化 [pɛ̃]，n 不发音。","pi":"mie 读 [mi]，e 不发音；pain 是鼻化元音，不要发 n。","et":"mie 来自拉丁语 mica（小碎块、碎屑）。","ex":[["J'aime la mie de pain.","我喜欢吃面包心。"],["Il enlève la croûte et mange seulement la mie.","他去掉面包皮，只吃面包心。"],["Les enfants font des boulettes avec la mie.","孩子们用面包心搓小球。"]],"co":[["la croûte et la mie","面包皮和面包心"],["de la mie de pain fraîche","新鲜面包心"],["faire des boulettes de mie","用面包心搓小球"]],"sy":[["croûte","courant","反义：面包皮"],["chapelure","courant","面包糠"],["miette","courant","碎屑，同源词"]],"fq":"中低频，烹饪和饮食话题。","me":"mie 和 miette（面包屑）同一家：都是「小碎块」。","tr":{"zh":"我喜欢吃面包心，不喜欢吃面包皮。","fr":"J'aime la mie, mais je n'aime pas la croûte.","alt":"Je préfère la mie de pain à la croûte.","note":"aimer + 定冠词 la 表示泛指喜欢。préférer A à B：喜欢 A 胜过 B。"}},
 "De la nourriture": {"pos":"n.f. 阴性名词，不可数，常用 de la nourriture","s":"食物；吃的东西（总称）。也可指「伙食」。指一顿具体的菜用 un plat，指单个食品用 un aliment。","ipa":"[nu.ʁi.tyʁ]","ph":"ou [u]；rr 读一个 [ʁ]；u 读 [y]（嘴唇圆、舌位前）；结尾 -ure 读 [yʁ]，e 不发音。","pi":"nourriture 里的 ou 读 [u]，结尾 u 读 [y]，注意区分；不要说成英语的 nutriture。","et":"来自动词 nourrir（拉丁语 nutrire，喂养）加后缀 -ture。","ex":[["J'aime la nourriture.","我喜欢食物。"],["La nourriture est très bonne ici.","这里的饭菜很好吃。"],["Il n'y a plus de nourriture pour le chat.","猫的食物没有了。"]],"co":[["de la nourriture pour chien / chat","狗粮 / 猫粮"],["la nourriture bio","有机食品"],["la nourriture de rue","街头小吃"],["manquer de nourriture","缺少食物"]],"sy":[["aliment","courant","单个食品"],["bouffe","familier","吃的，口语"],["repas","courant","一顿饭，不是食物本身"]],"fq":"高频，日常常用。","me":"nourriture ← nourrir（喂养）：喂你的东西。","tr":{"zh":"我觉得法国的食物很好吃。","fr":"Je trouve que la nourriture française est très bonne.","alt":"La bouffe française, c'est vraiment bon.","note":"nourriture 为单数名词，形容词 française 与它同为阴性单数。"}},
 "De la paille": {"pos":"n.f. 阴性名词，不可数，复数 pailles（指吸管等具体的根）","s":"稻草；麦秆；草编材料；也指吸管（une paille）。吃饭时「一根吸管」是 une paille，很常用。","ipa":"[paj]","ph":"-aille 读 [aj]；ll 不是 [l]，是类似英语 y 的音；结尾 e 不发音。","pi":"-aille 读 [aj]，不要读成 [pal] 或 [paje]。","et":"来自拉丁语 palea（谷壳、麦秆）。","ex":[["Le chapeau est en paille.","帽子是草编的。"],["Je bois mon jus avec une paille.","我用吸管喝果汁。"],["Les vaches dorment sur de la paille.","牛睡在稻草上。"]],"co":[["un chapeau de paille","草帽"],["une paille en plastique / en papier","塑料吸管 / 纸吸管"],["une botte de paille","一捆稻草"],["tirer à la courte paille","抽签（抽到短草的人输）"]],"sy":[["chaume","soutenu","稻茬、茅草屋顶"],["foin","courant","干草（给牲畜的草料）"]],"fq":"中频。","me":"paille ← palea：像「爬」草，稻草 paille [paj]。","tr":{"zh":"请给我一根吸管。","fr":"Une paille, s'il vous plaît.","alt":"Je peux avoir une paille, s'il vous plaît ?","note":"吸管是可数的：une paille / des pailles；稻草不可数：de la paille。"}},
 "De la poudre": {"pos":"n.f. 阴性名词，不可数，复数 poudres","s":"粉末；火药；化妆粉。poudre blanche 常指白色粉末（有时暗指毒品，看上下文）。在厨房里：poudre d'amande（杏仁粉）、sucre en poudre（细砂糖）。","ipa":"[pudʁ]","ph":"ou [u]；dr [dʁ]；结尾 e 不发音，所以只有一个音节。","pi":"只有一个音节 [pudʁ]；结尾 e 不发音，不要读成 poudre [pu.dʁə]。","et":"来自拉丁语 pulvis（灰尘，属格 pulveris）。同源：pulvériser（粉碎）。","ex":[["C'est de la poudre blanche.","这是白色粉末。"],["Je mets du sucre en poudre sur le gâteau.","我在蛋糕上撒糖粉。"],["Elle met de la poudre sur son visage.","她在脸上扑粉。"]],"co":[["en poudre","粉状的"],["du sucre en poudre","细砂糖"],["du lait en poudre","奶粉"],["de la poudre à canon","火药"]],"sy":[["poussière","courant","灰尘"],["farine","courant","面粉，是粉的一种"]],"fq":"中频。","me":"poudre 只有一个音节，想像 pudr：轻轻一扑。","tr":{"zh":"我在蛋糕上撒了一点糖粉。","fr":"J'ai mis un peu de sucre en poudre sur le gâteau.","alt":"J'ai saupoudré le gâteau de sucre.","note":"en poudre = 粉状的；saupoudrer 是「撒粉」。"}},
 "De la volaille": {"pos":"n.f. 阴性名词，常作不可数，复数 volailles","s":"家禽；禽肉（鸡、鸭、鹅、火鸡等）。可指活的家禽，也指做菜用的禽肉。poulet 是其中一种。","ipa":"[vɔ.laj]","ph":"v [v]；o 读 [ɔ]；-aille 读 [aj]；结尾 e 不发音。","pi":"-aille 读 [aj]，ll 不读 [l]。","et":"来自拉丁语 volatilia（会飞的东西），与 voler（飞）同源。","ex":[["Le poulet est une volaille.","鸡是家禽。"],["Nous mangeons de la volaille ce soir.","今晚我们吃禽肉。"],["Il élève des volailles à la ferme.","他在农场养家禽。"]],"co":[["de la volaille rôtie","烤禽肉"],["élever des volailles","养家禽"],["la cour de la volaille / la basse-cour","家禽院"],["un marchand de volaille","禽肉商"]],"sy":[["poulet","courant","鸡，具体一种"],["gibier","courant","野味，与家禽相对"]],"fq":"中频，菜场和菜谱常见。","me":"volaille ← voler：会「飞」的东西（虽然很多飞不远）。","tr":{"zh":"我们今晚吃禽肉和蔬菜。","fr":"Ce soir, nous mangeons de la volaille avec des légumes.","alt":"Ce soir, on prend de la volaille et des légumes.","note":"de la volaille 表示「一些禽肉」，不可数；avec des légumes 表示一般的量。"}},
 "L'attente": {"pos":"n.f. 阴性名词，复数 attentes","s":"等待；等候。表示等的这件事或这段时间。salle d'attente = 候诊室、候车室。dans l'attente de = 期待着、等待着（较正式）。","ipa":"[a.tɑ̃t]","ph":"l'attente 前面是 la 省音为 l'；tt 读一个 [t]；-en- 读鼻化 [ɑ̃]；结尾 te 的 e 不发音，t 要读出来。","pi":"attente 里的 t 要读出来 [a.tɑ̃t]，不像 attend [a.tɑ̃] 结尾不发音；en 读 [ɑ̃]，不是 [ɛ̃]。","et":"来自动词 attendre（等待，拉丁语 attendere）的名词形式。同族：attendre、attentif。","ex":[["L'attente est longue.","等待的时间很长。"],["Il y a une heure d'attente.","要等一个小时。"],["Je suis dans l'attente de votre réponse.","我在等您的答复。"]],"co":[["la salle d'attente","候诊室 / 候车室"],["une liste d'attente","等候名单"],["en attente","待处理的"],["dans l'attente de","等待着……"]],"sy":[["patience","courant","耐心，不是等待本身"],["délai","courant","期限、等待期"],["espoir","courant","希望"]],"fq":"中高频，日常和公文都常见。","me":"attente ← attendre：把 d 换成 t，加上 e。","tr":{"zh":"医生的候诊室里要等很久。","fr":"L'attente est longue dans la salle d'attente du médecin.","alt":"On attend longtemps chez le médecin.","note":"attente 是名词（阴性），attendre 是动词，不要混淆。"}},
 "La cuisson": {"pos":"n.f. 阴性名词，复数 cuissons","s":"烹饪的过程；火候；烹煮时间。着重「煮或烤到什么程度」。如牛排要说 la cuisson du steak：saignant（三分熟）、à point（五分熟）、bien cuit（全熟）。","ipa":"[kɥi.sɔ̃]","ph":"cui 读 [kɥi]（唇圆再滑到 i）；ss [s]；on 读鼻化 [ɔ̃]，n 不发音。","pi":"cui 读 [kɥi]，不是 [ku.i] 或英语 quick；-on 是鼻化元音，不发 n。","et":"来自动词 cuire（拉丁语 coquere）加后缀 -son。","ex":[["La cuisson est rapide.","烹饪很快。"],["Quelle cuisson pour le steak ?","牛排要几分熟？"],["Le temps de cuisson est de vingt minutes.","烹饪时间是二十分钟。"]],"co":[["le temps de cuisson","烹饪时间"],["la cuisson du steak","牛排的火候"],["une cuisson à la vapeur","蒸"],["une cuisson à point","恰到好处的熟度"]],"sy":[["cuisine","courant","烹饪、厨房，范围更广"],["préparation","courant","准备工作"]],"fq":"中频，菜谱和餐厅常见。","me":"cuisson ← cuire：cuire + son，加热的过程。","tr":{"zh":"这块肉的烹饪时间是二十分钟。","fr":"Le temps de cuisson de cette viande est de vingt minutes.","alt":"Cette viande cuit pendant vingt minutes.","note":"le temps de cuisson 是固定搭配，指烹饪所需时间。"}},
 "La nutrition": {"pos":"n.f. 阴性名词，复数 nutritions（很少用）","s":"营养；营养学。指身体摄取、利用食物的过程，也指学科。une nutritionniste = 营养师。比 alimentation（饮食）更偏科学。","ipa":"[ny.tʁi.sjɔ̃]","ph":"u 读 [y]；tr [tʁ]；-tion 读 [sjɔ̃]，不是 [ʃən]；on 鼻化。","pi":"-tion 读 [sjɔ̃]；u 读 [y]，不是 [ju]；重音落在最后一个音节。","et":"来自拉丁语 nutritio（喂养），与 nourrir（养）同源。","ex":[["La nutrition est importante.","营养很重要。"],["Elle étudie la nutrition à l'université.","她在大学学营养学。"],["Une bonne nutrition aide les enfants à grandir.","良好的营养帮助孩子成长。"]],"co":[["une bonne nutrition","良好的营养"],["la nutrition animale","动物营养"],["un expert en nutrition","营养专家"],["les conseils de nutrition","营养建议"]],"sy":[["alimentation","courant","饮食、日常吃什么"],["nourriture","courant","食物本身"]],"fq":"中频，健康话题常见。","me":"nutrition 和英语 nutrition 几乎一样，只是读 [ny.tʁi.sjɔ̃]。","tr":{"zh":"好的营养对孩子很重要。","fr":"Une bonne nutrition est très importante pour les enfants.","alt":"Bien manger, c'est important pour les enfants.","note":"nutrition 是阴性，所以用 une bonne nutrition。"}},
 "Une ambiance": {"pos":"n.f. 阴性名词，复数 ambiances","s":"氛围；气氛；场面。多指人与场所带来的感觉。放松好玩的场合常说 il y a de l'ambiance（很热闹）。书上译成 vibe，口语里很常用。","ipa":"[ɑ̃.bjɑ̃s]","ph":"am 读鼻化 [ɑ̃]；bi 读 [bj]；ance 读 [ɑ̃s]，c 读 [s]。","pi":"an / am 都读 [ɑ̃]；结尾 -ance 的 c 读 [s]，e 不发音。","et":"来自 ambiant（周围的），源自拉丁语 ambiens（环绕的）。","ex":[["L'ambiance à mon bureau n'est pas terrible.","我办公室的氛围不太好。"],["Il y a une super ambiance ce soir.","今晚气氛超棒。"],["J'aime l'ambiance de ce quartier.","我喜欢这个街区的氛围。"]],"co":[["il y a de l'ambiance","很热闹"],["une bonne / mauvaise ambiance","好 / 坏的氛围"],["mettre l'ambiance","活跃气氛"],["une ambiance familiale","家庭般的气氛"]],"sy":[["atmosphère","courant","气氛，略正式或指整体"],["climat","soutenu","氛围、大环境"],["vibe","familier","借自英语，口语"]],"fq":"高频，日常常用。","me":"ambiance：你周围（ambi-，四周）的感觉。","tr":{"zh":"这家咖啡馆的氛围很好。","fr":"L'ambiance de ce café est très agréable.","alt":"Il y a une super ambiance dans ce café.","note":"ambiance 是阴性：une bonne ambiance。"}},
 "Une atmosphère": {"pos":"n.f. 阴性名词，复数 atmosphères","s":"大气层；气氛。本义是地球的大气，引申为一个场所或场合的整体气氛。可用于好的或不好的氛围，比 ambiance 稍正式一点。","ipa":"[at.mɔs.fɛʁ]","ph":"at [at]；mos 读 [mɔs]；phère 读 [fɛʁ]（ph = f），r 要读出来；结尾 e 不发音。","pi":"ph 读 [f]；结尾 r 发音：[fɛʁ]；开头 at 不是 [ɑ̃]。","et":"来自希腊语 atmós（水汽）和 sphaîra（球），经新拉丁语进入法语。","ex":[["L'atmosphère de ce bar est géniale.","这家酒吧的气氛很棒。"],["Il y a une atmosphère tendue dans la salle.","房间里气氛紧张。"],["L'atmosphère de la Terre protège la vie.","地球的大气层保护生命。"]],"co":[["une atmosphère détendue / tendue","轻松 / 紧张的气氛"],["une atmosphère chaleureuse","温馨的气氛"],["l'atmosphère terrestre","地球大气层"],["changer d'atmosphère","换换气氛"]],"sy":[["ambiance","courant","氛围，更日常、更口语"],["climat","soutenu","氛围、大环境"]],"fq":"中高频。","me":"atmosphère = atmos（水汽）+ sphère（球）：包着地球的球。","tr":{"zh":"这个餐厅的气氛很温馨。","fr":"L'atmosphère de ce restaurant est très chaleureuse.","alt":"On se sent bien dans ce restaurant, l'atmosphère est chaleureuse.","note":"形容词 chaleureuse 要与阴性名词 atmosphère 配合。"}},
 "Une betterave": {"pos":"n.f. 阴性名词，复数 betteraves","s":"甜菜；常指红甜菜（betterave rouge），法国常熟食做沙拉或配菜。工业上还有糖用甜菜（betterave sucrière），用来制糖。","ipa":"[bɛt.ʁav]","ph":"e 读 [ɛ]；tt 读一个 [t]；r [ʁ]；ave 读 [av]；结尾 e 不发音。","pi":"betterave 不是 bette（一种叶菜）；两个 t 只读一个 [t]；注意 [ʁ] 的音。","et":"由 bette（叶用甜菜）和 rave（块根，拉丁语 rapa）合成。","ex":[["La betterave est rouge.","甜菜是红色的。"],["Je fais une salade de betterave.","我做一份甜菜沙拉。"],["On fait du sucre avec la betterave.","人们用甜菜制糖。"]],"co":[["une salade de betterave","甜菜沙拉"],["une betterave rouge","红甜菜"],["la betterave sucrière","糖用甜菜"],["du jus de betterave","甜菜汁"]],"sy":[["bette","courant","叶用甜菜"],["radis","courant","小萝卜，另一种红色根菜"]],"fq":"中低频，饮食话题。","me":"bette + rave：一棵「甜菜」加一个「根」。","tr":{"zh":"我今天晚上做甜菜沙拉。","fr":"Ce soir, je fais une salade de betterave.","alt":"Ce soir, c'est salade de betterave.","note":"salade de + 无冠词名词：…… 沙拉。"}},
 "Une conserve": {"pos":"n.f. 阴性名词，复数 conserves","s":"罐头；腌制保存的食品。une boîte de conserve = 罐头盒。conserves 复数常指自制或买来的罐头和腌渍品。en conserve = 罐装的。","ipa":"[kɔ̃.sɛʁv]","ph":"con 读鼻化 [kɔ̃]；ser 读 [sɛʁ]；v [v]；结尾 e 不发音。","pi":"con 是鼻化元音，n 不发音；注意 r 和 v 连着读 [ʁv]。","et":"来自动词 conserver（保存，拉丁语 conservare）。同族：conservation（保存）、conservateur（保守的；防腐剂）。","ex":[["Ma grand-mère prépare des conserves de légumes.","我外婆做蔬菜罐头。"],["Je mange des petits pois en conserve.","我吃罐装豌豆。"],["Il ouvre une boîte de conserve.","他打开一个罐头。"]],"co":[["une boîte de conserve","罐头盒"],["en conserve","罐装的"],["faire des conserves","自制罐头 / 腌渍"],["de la conserve de thon","金枪鱼罐头"]],"sy":[["bocal","courant","玻璃罐，家庭自制常用"],["boîte","courant","盒、罐"]],"fq":"中频，饮食话题。","me":"conserve ← conserver：「保存」下来的食物。","tr":{"zh":"我外婆每年夏天做番茄罐头。","fr":"Ma grand-mère fait des conserves de tomates tous les étés.","alt":"Chaque été, ma grand-mère met des tomates en conserve.","note":"mettre … en conserve = 把……做成罐头。"}},
 "Une courge": {"pos":"n.f. 阴性名词，复数 courges","s":"南瓜类蔬菜的统称：西葫芦、南瓜、倭瓜等都属于 courge。指南瓜时常说 le potiron 或 la citrouille；一般饭桌上说 une courge 也可。","ipa":"[kuʁʒ]","ph":"ou 读 [u]；r [ʁ]；ge 读 [ʒ]；结尾 e 不发音。","pi":"ou [u]，ge [ʒ]；整个词只有一个音节 [kuʁʒ]。","et":"来自拉丁语 cucurbita（葫芦、瓜），经古法语变化而来。","ex":[["Je mange une courge.","我吃南瓜。"],["La soupe de courge est délicieuse.","南瓜汤很好喝。"],["Elle cultive des courges dans son jardin.","她在花园里种南瓜。"]],"co":[["une soupe de courge","南瓜汤"],["une courge butternut","奶油南瓜"],["des graines de courge","南瓜籽"],["une purée de courge","南瓜泥"]],"sy":[["potiron","courant","南瓜"],["citrouille","courant","南瓜（万圣节那种）"],["courgette","courant","西葫芦，是 courge 的小型兄弟"]],"fq":"中低频，秋天常见。","me":"courge 和 courgette（小的）同一家，一个大，一个小。","tr":{"zh":"我秋天喜欢喝南瓜汤。","fr":"En automne, j'aime la soupe de courge.","alt":"À l'automne, je prends souvent de la soupe de courge.","note":"en automne 和 à l'automne 都可以。"}},
 "Une couronne": {"pos":"n.f. 阴性名词，复数 couronnes","s":"王冠；花环；圈状面包或糕点。le roi porte une couronne。也可以指货币（瑞典克朗 couronne suédoise）。une couronne de fleurs = 花环。","ipa":"[ku.ʁɔn]","ph":"ou [u]；rr 读一个 [ʁ]；o 读 [ɔ]；nn 读 [n]（元音后双 n 不鼻化）；结尾 e 不发音。","pi":"-onne 读 [ɔn]，n 要读出来，不是鼻化 [ɔ̃]；couronne 的 ou 读 [u]。","et":"来自拉丁语 corona（花冠、冠）。同源：英语 crown、corona。","ex":[["Le roi porte une couronne.","国王戴着王冠。"],["Elle fait une couronne de fleurs.","她编一个花环。"],["Nous mangeons une couronne briochée.","我们吃一个圈形的布里欧修。"]],"co":[["une couronne de fleurs","花环"],["la couronne du roi","国王的王冠"],["une couronne de Noël","圣诞花环"],["la petite / grande couronne","巴黎近郊 / 远郊"]],"sy":[["diadème","soutenu","头冠、冠冕"],["guirlande","courant","花环、彩带"]],"fq":"中频。","me":"couronne ← corona：和英语 crown 同源。","tr":{"zh":"公主头上戴着一顶金色的王冠。","fr":"La princesse porte une couronne dorée sur la tête.","alt":"La princesse a une couronne en or sur la tête.","note":"porter 既可表示戴，也可表示拿、背。"}},
 "Une crêpe": {"pos":"n.f. 阴性名词，复数 crêpes","s":"可丽饼；薄饼。法国人常在 2 月 2 日 la Chandeleur（圣烛节）吃。甜的加糖或果酱，咸的叫 galette（荞麦做）。","ipa":"[kʁɛp]","ph":"cr [kʁ]；ê 读 [ɛ]；p 要读出来；结尾 e 不发音。","pi":"ê 读 [ɛ]，不是 [e] 或 [i]；p 要读出来，不像 [kʁɛ]。","et":"来自古法语 crespe，源自拉丁语 crispa（卷曲的），形容薄饼边缘卷起的样子。","ex":[["Je mange une crêpe au sucre.","我吃一张糖可丽饼。"],["On mange des crêpes à la Chandeleur.","圣烛节我们吃可丽饼。"],["Tu préfères la crêpe au chocolat ou à la confiture ?","你更喜欢巧克力还是果酱可丽饼？"]],"co":[["une crêpe au sucre / au chocolat","糖 / 巧克力可丽饼"],["faire sauter une crêpe","翻面可丽饼"],["une crêperie","可丽饼店"],["la pâte à crêpes","可丽饼面糊"]],"sy":[["galette","courant","荞麦咸饼，常配火腿、鸡蛋"],["pancake","courant","美式松饼，更厚"]],"fq":"中高频，饮食话题常用。","me":"crêpe ← crispa：边缘「卷」起来的饼。","tr":{"zh":"我想要一张糖可丽饼。","fr":"Je voudrais une crêpe au sucre, s'il vous plaît.","alt":"Je vais prendre une crêpe au sucre.","note":"voudrais 比 veux 更客气。"}},
 "Une endive": {"pos":"n.f. 阴性名词，复数 endives","s":"菊苣芽；法国的白色苦味小叶球蔬菜。生吃做沙拉，也可焗烤（endives au jambon，火腿焗菊苣）。味道微苦。","ipa":"[ɑ̃.div]","ph":"en 读鼻化 [ɑ̃]；d [d]；i [i]；v [v]；结尾 e 不发音。","pi":"en 读 [ɑ̃]，不是 [ɛn]；v 要读出来，别吞掉。","et":"经中世纪拉丁语 endivia 进入法语，更早的来源不确定。","ex":[["L'endive est un peu amère.","菊苣有点苦。"],["Je prépare une salade d'endives.","我做一份菊苣沙拉。"],["Elle fait des endives au jambon.","她做火腿焗菊苣。"]],"co":[["une salade d'endives","菊苣沙拉"],["des endives au jambon","火腿焗菊苣"],["une endive braisée","焖菊苣"],["une endive amère","苦菊苣"]],"sy":[["chicorée","courant","菊苣，相近的苦菜"],["salade","courant","生菜、沙拉菜"]],"fq":"中低频，北法常见。","me":"endive 的 en 读 [ɑ̃]：「昂」迪夫，苦苦的小白菜。","tr":{"zh":"我喜欢吃菊苣沙拉，虽然有点苦。","fr":"J'aime la salade d'endives, même si c'est un peu amer.","alt":"J'adore les endives en salade, même un peu amères.","note":"même si 后面接直陈式：même si c'est… 。"}},
 "Une étoile": {"pos":"n.f. 阴性名词，复数 étoiles","s":"星星；恒星。也指明星（une étoile du cinéma）、星级（hôtel quatre étoiles）、星形。dormir à la belle étoile = 露天过夜。","ipa":"[e.twal]","ph":"é [e]；oi 读 [wa]；l 要读出来；结尾 e 不发音。","pi":"oi 读 [wa]，不是 [ɔi]；é 的重音符号不要漏掉。","et":"来自拉丁语 stella（星星），词头加了 é-。同源：英语 stellar。","ex":[["Je vois une étoile dans le ciel.","我在天上看到一颗星。"],["Il y a beaucoup d'étoiles ce soir.","今晚有很多星星。"],["Cet hôtel a quatre étoiles.","这家酒店是四星级。"]],"co":[["une étoile filante","流星"],["dormir à la belle étoile","露天睡觉"],["un hôtel quatre étoiles","四星级酒店"],["une étoile de mer","海星"]],"sy":[["astre","soutenu","天体"],["vedette","courant","明星（影视）"]],"fq":"高频，日常常用。","me":"étoile ← stella：去掉 s，加上 é。","tr":{"zh":"今晚天上有很多星星。","fr":"Ce soir, il y a beaucoup d'étoiles dans le ciel.","alt":"Ce soir, le ciel est plein d'étoiles.","note":"beaucoup de + 名词，étoile 省音为 d'étoiles。"}},
 "Une étoile Michelin": {"pos":"n.f. 阴性名词，复数 étoiles Michelin","s":"米其林星；米其林指南给餐厅的荣誉，最高三星。une étoile 是「一星」。Michelin 作为专名不加 s。一家得星的餐厅叫 un restaurant étoilé。","ipa":"[e.twal.miʃ.lɛ̃]","ph":"étoile 读 [e.twal]；Michelin 读 [miʃ.lɛ̃]，ch 读 [ʃ]，in 读鼻化 [ɛ̃]。","pi":"Michelin 里的 ch 读 [ʃ]，不是 [k] 或英语 [tʃ]；结尾 in 是鼻化元音。","et":"étoile 来自拉丁语 stella；Michelin 是创始人米其林兄弟（Michelin）的姓氏。","ex":[["Ce restaurant a une étoile Michelin.","这家餐厅有一颗米其林星。"],["Ce chef a deux étoiles Michelin.","这位主厨有两颗米其林星。"],["Un restaurant étoilé coûte souvent cher.","米其林星级餐厅通常很贵。"]],"co":[["un restaurant étoilé","有星的餐厅"],["un chef étoilé","获星主厨"],["trois étoiles Michelin","米其林三星"],["perdre une étoile","丢掉一颗星"]],"sy":[["guide Michelin","courant","米其林指南"],["restaurant gastronomique","courant","美食餐厅"]],"fq":"中频，美食话题常见。","me":"étoile + Michelin：天上的星，落进了盘子里。","tr":{"zh":"这位主厨的餐厅有两颗米其林星。","fr":"Le restaurant de ce chef a deux étoiles Michelin.","alt":"Ce chef a un restaurant avec deux étoiles Michelin.","note":"数字 deux 后 étoiles 取复数，Michelin 不变。"}},
 "Une formule": {"pos":"n.f. 阴性名词，复数 formules","s":"套餐；固定组合；公式。餐厅里 la formule midi 指午餐套餐（如 plat + dessert 或 entrée + plat）。也指数学、化学公式，还有 formule de politesse（书信结尾客套语）。","ipa":"[fɔʁ.myl]","ph":"f [f]；o 读 [ɔ]；r [ʁ]；u 读 [y]；l 要读出来；结尾 e 不发音。","pi":"u 读 [y]；结尾 l 要读出来：[fɔʁ.myl]。","et":"来自拉丁语 formula（forma 的指小词，小形式、规定的式样）。同族：forme、format。","ex":[["Je choisis la formule midi.","我选午餐套餐。"],["Il y a une formule à douze euros.","有一个十二欧元的套餐。"],["Quelle est la formule chimique de l'eau ?","水的化学式是什么？"]],"co":[["la formule midi","午餐套餐"],["une formule à 15 euros","15 欧套餐"],["une formule de politesse","客套语"],["une formule magique","咒语"]],"sy":[["menu","courant","套餐，更常用"],["offre","courant","优惠、方案"]],"fq":"中高频，餐厅和商店常见。","me":"formule ← forma：一种固定的「形式」，套餐就是固定组合。","tr":{"zh":"我要选十二欧元的午餐套餐。","fr":"Je prends la formule midi à douze euros.","alt":"Je vais prendre la formule du midi, à douze euros.","note":"prendre 点餐：je prends = 我要。"}},
 "Une galette": {"pos":"n.f. 阴性名词，复数 galettes","s":"圆而扁的饼。在布列塔尼指荞麦咸饼（galette de sarrasin），可包火腿、奶酪、鸡蛋；也指其他扁圆饼，如 galette des rois（国王饼）、galette de riz（米饼）。","ipa":"[ga.lɛt]","ph":"g 读 [g]；a [a]；l [l]；e 读 [ɛ]；tt 读一个 [t]；结尾 e 不发音。","pi":"-ette 读 [ɛt]，t 要读出来，e 不发音；g 读 [g]（硬音）。","et":"来自 galet（扁圆的小石子）加后缀 -ette，指像小卵石的圆饼。","ex":[["J'adore les galettes bretonnes.","我爱布列塔尼荞麦饼。"],["Je prends une galette jambon-fromage.","我要一份火腿奶酪荞麦饼。"],["Cette galette est faite avec de la farine de sarrasin.","这张饼用荞麦粉做成。"]],"co":[["une galette au sarrasin","荞麦饼"],["une galette complète","全配荞麦饼（火腿、奶酪、蛋）"],["une galette de riz","米饼"],["une galette saucisse","香肠荞麦饼（雷恩特色）"]],"sy":[["crêpe","courant","可丽饼，通常指甜的"],["biscuit","courant","饼干"]],"fq":"中频，美食话题。","me":"galette ← galet（小圆石）：扁扁圆圆像石子。","tr":{"zh":"我要一份火腿奶酪荞麦饼。","fr":"Je voudrais une galette jambon-fromage.","alt":"Une galette jambon-fromage, s'il vous plaît.","note":"jambon-fromage 作为组合，不加冠词和连词。"}},
 "Une galette des rois": {"pos":"n.f. 阴性名词，复数 galettes des rois","s":"国王饼；1 月 6 日主显节前后吃的杏仁酥饼。饼里藏着一颗小瓷偶（la fève），谁吃到谁当「国王」，戴上纸王冠。","ipa":"[ga.lɛt.de.ʁwa]","ph":"galette 读 [ga.lɛt]；des 读 [de]；rois 读 [ʁwa]，oi 读 [wa]，s 不发音。","pi":"rois 读 [ʁwa]，结尾 s 不发音；des 读 [de]，不是 [dɛs]。","et":"galette 来自 galet；rois 指《圣经》里的三王（les Rois mages），因此叫「国王饼」。","ex":[["Nous mangeons une galette des rois.","我们吃国王饼。"],["Qui a trouvé la fève dans la galette ?","谁在饼里吃到了小瓷偶？"],["En janvier, les boulangeries vendent des galettes des rois.","一月里，面包店卖国王饼。"]],"co":[["tirer les rois","分国王饼"],["trouver la fève","吃到小瓷偶"],["une galette frangipane","杏仁奶油馅国王饼"],["la fête des Rois / l'Épiphanie","主显节"]],"sy":[["brioche des rois","courant","南法的国王面包"],["gâteau des rois","courant","国王糕，南法说法"]],"fq":"中低频，一月常见。","me":"galette + rois：一个饼，一个国王，一颗藏起来的小瓷偶。","tr":{"zh":"一月我们家总是吃国王饼。","fr":"En janvier, nous mangeons toujours une galette des rois en famille.","alt":"En janvier, chez nous, c'est galette des rois.","note":"en janvier = 在一月，月份前用 en。"}},
 "Une liste de courses": {"pos":"n.f. 阴性名词，复数 listes de courses","s":"购物清单；去超市或市场前写下要买的东西。les courses（复数）指日常采购，faire les courses = 去采购、买菜。","ipa":"[list.də.kuʁs]","ph":"liste 读 [list]；de 弱读 [də]；courses 读 [kuʁs]，ou 读 [u]，s 在 -rse 后读 [s]，结尾 e 不发音。","pi":"liste 和 courses 的结尾 e 都不发音；ou 读 [u]。","et":"liste 来自意大利语 lista（条、行）；course 来自 courir（跑），古义「跑腿办事」。","ex":[["Je fais une liste de courses.","我列一张购物清单。"],["N'oublie pas la liste de courses !","别忘了购物清单！"],["J'ai écrit du lait et des œufs sur ma liste de courses.","我在购物清单上写了牛奶和鸡蛋。"]],"co":[["faire une liste de courses","列购物清单"],["faire les courses","去买菜 / 采购"],["cocher la liste","在清单上打钩"],["ajouter à la liste","加到清单里"]],"sy":[["liste","courant","清单，更宽泛"],["pense-bête","courant","备忘条"]],"fq":"高频，日常常用。","me":"courses ← courir：为了买东西来回「跑」。","tr":{"zh":"出门前我先写好购物清单。","fr":"Avant de sortir, je fais ma liste de courses.","alt":"Avant d'aller au supermarché, j'écris ma liste de courses.","note":"avant de + 动词原形：在……之前。"}},
 "Une nappe": {"pos":"n.f. 阴性名词，复数 nappes","s":"桌布。吃饭时铺在桌上；也指一层平铺的东西，如 une nappe d'eau（水面）、une nappe de brouillard（一层雾）。","ipa":"[nap]","ph":"n [n]；a [a]；pp 读一个 [p]；结尾 e 不发音。","pi":"只有一个音节 [nap]；注意 p 要读出来。","et":"来自拉丁语 mappa（一块布）；开头 m 变成 n。同源：英语 napkin（餐巾）、map（地图）。","ex":[["La nappe est sur la table.","桌布在桌子上。"],["Je mets une nappe blanche.","我铺一块白桌布。"],["Il y a une tache sur la nappe.","桌布上有一块污渍。"]],"co":[["mettre la nappe","铺桌布"],["une nappe en papier","纸桌布"],["une nappe de brouillard","一层雾"],["une tache sur la nappe","桌布上的污渍"]],"sy":[["serviette","courant","餐巾，不是桌布"],["set de table","courant","餐垫"]],"fq":"中频，家居饮食话题。","me":"nappe：napkin 的祖先，铺在桌上的一块布。","tr":{"zh":"请把白桌布铺在桌子上。","fr":"Mets la nappe blanche sur la table, s'il te plaît.","alt":"Tu peux mettre la nappe blanche sur la table ?","note":"mets 是 mettre 的 tu 命令式（保留 s）。"}},
 "Une portion": {"pos":"n.f. 阴性名词，复数 portions","s":"一份；一人份食物；部分。点菜时 une portion de frites = 一份薯条。不是一块蛋糕（那是 une part）。","ipa":"[pɔʁ.sjɔ̃]","ph":"por 读 [pɔʁ]；-tion 读 [sjɔ̃]；on 鼻化 [ɔ̃]，n 不发音。","pi":"-tion 读 [sjɔ̃]，不是 [ʃən]；portion 和 英语 portion 拼写一样，读音不同。","et":"来自拉丁语 portio（份、部分）。同源：proportion、part。","ex":[["Je prends une petite portion.","我吃一小份。"],["Une portion de frites, s'il vous plaît.","请给我一份薯条。"],["Cette portion est trop grande pour moi.","这一份对我来说太多了。"]],"co":[["une petite / grande portion","小份 / 大份"],["une portion de frites","一份薯条"],["une portion individuelle","单人份"],["la taille de la portion","份量"]],"sy":[["part","courant","一块、一份（蛋糕、披萨）"],["ration","courant","配给量、一日份"],["quantité","courant","数量"]],"fq":"中高频，餐厅常见。","me":"portion ← partie：一份是整体里的一「部分」。","tr":{"zh":"这一份太多了，我只吃一半。","fr":"Cette portion est trop grande, je ne mange que la moitié.","alt":"C'est trop pour moi, je mange la moitié de la portion.","note":"ne … que = 只……，表示限制。"}},
 "Une roue": {"pos":"n.f. 阴性名词，复数 roues","s":"轮子；车轮；轮形的东西。la grande roue = 摩天轮；la roue de secours = 备胎；une roue de fromage = 一整轮奶酪。","ipa":"[ʁu]","ph":"r 小舌音 [ʁ]；ou 读 [u]；结尾 e 不发音。","pi":"ou 读 [u]，不是 [o]；只有一个音节 [ʁu]。","et":"来自拉丁语 rota（轮子）。同源：英语 rotate，法语 rouler（滚动）。","ex":[["La voiture a quatre roues.","汽车有四个轮子。"],["Le vélo a une roue crevée.","自行车有一个轮子爆了。"],["Nous montons dans la grande roue.","我们坐上摩天轮。"]],"co":[["une roue de voiture / de vélo","汽车 / 自行车轮子"],["la grande roue","摩天轮"],["la roue de secours","备胎"],["une roue de fromage","一整轮奶酪"]],"sy":[["pneu","courant","轮胎，不是整个轮子"],["rond","courant","圆圈"]],"fq":"中高频，日常常用。","me":"roue ← rota：转起来的轮，和 rouler 一家。","tr":{"zh":"我的自行车前轮漏气了。","fr":"La roue avant de mon vélo est crevée.","alt":"J'ai crevé la roue avant de mon vélo.","note":"roue avant = 前轮，roue arrière = 后轮。"}},
 "Une roulotte": {"pos":"n.f. 阴性名词，复数 roulottes","s":"大篷车；旧时马拉的有轮小屋，马戏团和流浪艺人住的那种。也指房车式的小屋。现代旅游房车更常说 une caravane。","ipa":"[ʁu.lɔt]","ph":"r [ʁ]；ou [u]；l [l]；o 读 [ɔ]；tt 读一个 [t]；结尾 e 不发音。","pi":"ou 读 [u]；-otte 读 [ɔt]，t 要读出来，别和 [ʁu.lo] 混淆。","et":"由 rouler（滚动）加指小后缀构成，指带轮子的小屋。","ex":[["Ils dorment dans une roulotte.","他们睡在大篷车里。"],["La roulotte du cirque est colorée.","马戏团的大篷车很多彩。"],["Un cheval tire la roulotte.","一匹马拉着大篷车。"]],"co":[["une roulotte de cirque","马戏团大篷车"],["vivre en roulotte","住在大篷车里"],["une roulotte tirée par un cheval","马拉大篷车"],["une roulotte de camping","露营小车"]],"sy":[["caravane","courant","拖挂房车，现代常用"],["camping-car","courant","自行式房车"]],"fq":"低频，多见于故事和旅游。","me":"roulotte ← rouler：会「滚」的小屋。","tr":{"zh":"这家人住在一辆旧大篷车里。","fr":"Cette famille vit dans une vieille roulotte.","alt":"Cette famille habite dans une vieille roulotte.","note":"vieille 是 vieux 的阴性形式，放在名词前。"}},
 "Une saveur": {"pos":"n.f. 阴性名词，复数 saveurs","s":"味道；风味；特色的滋味。比 goût 更文雅，偏向某种食物的特色味道（甜、酸、咸）。une glace à deux saveurs = 双味冰淇淋。","ipa":"[sa.vœʁ]","ph":"s [s]；a [a]；v [v]；eu 读 [œ]（结尾带 r 时开口）；r 要读出来 [ʁ]。","pi":"-eur 读 [œʁ]，r 要发音；不要读成 [sa.vœ]。","et":"来自拉丁语 sapor（味道），与 savoir（知道，本义「有味道」）有关联，但不必深究。同族：savoureux（美味的）。","ex":[["C'est une bonne saveur.","这是一种很好的味道。"],["Cette glace a une saveur de vanille.","这款冰淇淋有香草味。"],["Il aime les saveurs fortes.","他喜欢浓烈的味道。"]],"co":[["une saveur sucrée / salée","甜 / 咸的味道"],["une saveur de vanille","香草味"],["manquer de saveur","缺乏风味"],["savoureux","美味的（形容词）"]],"sy":[["goût","courant","味道，更常用、更宽泛"],["arôme","soutenu","香气"],["parfum","courant","香味、口味"]],"fq":"中频，美食话题。","me":"saveur → savoureux：有味道的东西才「好吃」。","tr":{"zh":"我喜欢这款冰淇淋的香草味。","fr":"J'aime la saveur de vanille de cette glace.","alt":"Cette glace a une bonne saveur de vanille.","note":"saveur de + 名词 表示什么味。"}},
 "Des cornichons": {"pos":"n.m.pl. 阳性复数名词，单数 un cornichon","s":"小黄瓜；腌黄瓜（醋渍）。法国人配肉冷盘、肉酱和火腿吃。也可以指傻瓜（口语里的 cornichon，带点玩笑）。","ipa":"[kɔʁ.ni.ʃɔ̃]","ph":"cor 读 [kɔʁ]；ni [ni]；chon 读 [ʃɔ̃]，ch 读 [ʃ]，on 鼻化，n 不发音。","pi":"ch 读 [ʃ]，不是 [k]；结尾 -on 是鼻化元音；复数 s 不发音。","et":"由 corne（角）和指小后缀 -ichon 构成，因小黄瓜弯弯像小角。","ex":[["Je mange des cornichons.","我吃腌黄瓜。"],["Il met des cornichons dans son sandwich.","他在三明治里放腌黄瓜。"],["Le pâté est servi avec des cornichons.","肉酱配腌黄瓜上桌。"]],"co":[["des cornichons au vinaigre","醋渍小黄瓜"],["un bocal de cornichons","一罐腌黄瓜"],["du pâté et des cornichons","肉酱配腌黄瓜"],["quel cornichon !","真是个傻瓜！（口语）"]],"sy":[["concombre","courant","黄瓜，新鲜大个"],["pickles","familier","英语借词，指腌菜"]],"fq":"中频，饮食话题。","me":"corne + -ichon：小角状的黄瓜。","tr":{"zh":"我在三明治里放了一点腌黄瓜。","fr":"J'ai mis quelques cornichons dans mon sandwich.","alt":"Je mets des cornichons dans mon sandwich.","note":"quelques + 复数名词 = 几个、一些。"}},
 "Des fruits rouges / Des fruits des bois": {"pos":"n.m.pl. 阳性复数名词，单数 un fruit rouge","s":"红色浆果；野果。fruits rouges 指草莓、覆盆子、樱桃、红醋栗等红色水果；fruits des bois 指树莓、蓝莓、黑莓等林中小浆果。两者常互换，常用来做甜点、果酱。","ipa":"[fʁɥi.ʁuʒ] / [fʁɥi.de.bwa]","ph":"fruits 读 [fʁɥi]，ts 不发音；rouges 读 [ʁuʒ]；des 读 [de]；bois 读 [bwa]，s 不发音。","pi":"fruits 的 ui 读 [ɥi]，结尾 ts 都不发音；bois 的 oi 读 [wa]。","et":"fruit 来自拉丁语 fructus；rouge 来自拉丁语 rubeus（红）；bois（树林）来源不确定，但常说是日耳曼语。","ex":[["J'adore les fruits rouges.","我爱红色浆果。"],["Elle prépare une tarte aux fruits rouges.","她做一个红色浆果挞。"],["Je prends une glace aux fruits des bois.","我要一个野果冰淇淋。"]],"co":[["une tarte aux fruits rouges","红色浆果挞"],["un coulis de fruits rouges","红色浆果酱汁"],["une glace aux fruits des bois","野果冰淇淋"],["une confiture de fruits rouges","红色浆果果酱"]],"sy":[["baies","soutenu","浆果，较学术"],["petits fruits","courant","小浆果（总称）"]],"fq":"中频，美食话题。","me":"红色的水果 = fruits rouges；林里的 = fruits des bois。","tr":{"zh":"我最爱红色浆果挞。","fr":"Ma tarte préférée, c'est la tarte aux fruits rouges.","alt":"Je préfère la tarte aux fruits rouges.","note":"tarte aux = tarte à + les，缩合成 aux。"}},
 "Des fruits secs": {"pos":"n.m.pl. 阳性复数名词，单数 un fruit sec","s":"干果；坚果。包括杏仁、核桃、榛子等坚果，也包括葡萄干、无花果干等果干。严格的坚果叫 fruits à coque，果干叫 fruits séchés。日常对话两者常混说。","ipa":"[fʁɥi.sɛk]","ph":"fruits 读 [fʁɥi]，ts 不发音；secs 读 [sɛk]，c 读 [k]，s 不发音。","pi":"secs 里 c 要读出来 [sɛk]，s 不发音；fruits 的 ts 不发音。","et":"fruit 来自拉丁语 fructus；sec 来自拉丁语 siccus（干的）。","ex":[["J'aime les fruits secs.","我喜欢干果。"],["Il mange des fruits secs comme goûter.","他把干果当点心吃。"],["Elle ajoute des fruits secs dans le gâteau.","她在蛋糕里加干果。"]],"co":[["un mélange de fruits secs","混合干果"],["des fruits secs et des noix","干果和核桃"],["des fruits à coque","坚果"],["des fruits séchés","果干"]],"sy":[["noix","courant","核桃，也泛指坚果"],["fruits séchés","courant","果干，更准确"]],"fq":"中频。","me":"fruit + sec：不含水分的「干」果。","tr":{"zh":"下午我喜欢吃一点干果当点心。","fr":"L'après-midi, j'aime manger des fruits secs au goûter.","alt":"Au goûter, je prends souvent des fruits secs.","note":"au goûter = 当下午点心；goûter 也是名词。"}},
 "Des haricots": {"pos":"n.m.pl. 阳性复数名词，单数 un haricot","s":"豆子；菜豆。haricots verts = 四季豆；haricots blancs = 白芸豆；haricots rouges = 红芸豆。h 是「有音 h」（h aspiré），所以复数前不连读。","ipa":"[a.ʁi.ko]","ph":"h 不发音，但是「有音 h」：les haricots 读 [le a.ʁi.ko]，中间不连读；ri 读 [ʁi]；结尾 t 和 s 都不发音。","pi":"h 不发音却不连读：des haricots 是 [de a.ʁi.ko]，不是 [de.za.ʁi.ko]；结尾 -ots 全不发音。","et":"来源不确定（常有人提到阿兹特克语，但不确定），不要照字面拆解。","ex":[["Les haricots sont verts.","豆子是绿色的。"],["Je prépare des haricots verts avec du beurre.","我用黄油炒四季豆。"],["Mon plat préféré, c'est le cassoulet aux haricots blancs.","我最爱的菜是白豆炖肉锅。"]],"co":[["des haricots verts","四季豆"],["des haricots blancs / rouges","白芸豆 / 红芸豆"],["des haricots secs","干豆"],["courir sur le haricot","烦人（口语）"]],"sy":[["légumineuse","courant","豆类（总称）"],["pois","courant","豌豆"],["lentilles","courant","扁豆"]],"fq":"中高频，饮食话题。","me":"haricot 的 h 像一堵墙：des | haricots，中间不连读。","tr":{"zh":"我今天晚上做四季豆配鱼。","fr":"Ce soir, je fais des haricots verts avec du poisson.","alt":"Ce soir, c'est poisson et haricots verts.","note":"haricot 是有音 h，所以 des haricots 不连读。"}},
 "Des herbes": {"pos":"n.f.pl. 阴性复数名词，单数 une herbe","s":"香草；草本香料植物（罗勒、百里香、欧芹等）；也指草。herbes de Provence = 普罗旺斯香草；fines herbes = 细香草（碎的混合香草）。herbe 单数多指草地上的草。","ipa":"[ɛʁb]","ph":"h 不发音；e 读 [ɛ]；r [ʁ]；b [b]；结尾 e 不发音。les herbes 要连读：[le.zɛʁb]。","pi":"h 不发音，是「无音 h」，所以 des herbes 读 [de.zɛʁb]，要连读；整个词只有一个音节。","et":"来自拉丁语 herba（草）。同源：英语 herb、herbal，法语 herbier（植物标本集）。","ex":[["J'ajoute des herbes.","我加一些香草。"],["Il met des herbes de Provence sur la viande.","他在肉上撒普罗旺斯香草。"],["Elle fait pousser des herbes sur son balcon.","她在阳台种香草。"]],"co":[["des herbes de Provence","普罗旺斯香草"],["des fines herbes","混合细香草"],["des herbes aromatiques","芳香草本植物"],["une tisane aux herbes","香草茶"]],"sy":[["aromates","courant","香辛料植物"],["épices","courant","香料，多是种子或粉，不同于香草"]],"fq":"中高频，烹饪常用。","me":"herbes ≈ 英语 herbs：只是 h 不发音。","tr":{"zh":"我在阳台上种了几种香草。","fr":"Je fais pousser plusieurs herbes aromatiques sur mon balcon.","alt":"J'ai des herbes aromatiques sur mon balcon.","note":"faire pousser = 种植、使生长。"}},
 "Des produits laitiers": {"pos":"n.m.pl. 阳性复数名词，单数 un produit laitier","s":"乳制品；牛奶、奶酪、酸奶、黄油等。laitier 是形容词（乳的），阴性 laitière，所以单数说 un produit laitier，复数两个词都加 s。","ipa":"[pʁɔ.dɥi.lɛ.tje]","ph":"pro 读 [pʁɔ]；duits 读 [dɥi]，ui 读 [ɥi]，ts 不发音；lai 读 [lɛ]；tiers 读 [tje]，ers 读 [je]，s 不发音。","pi":"ui 读 [ɥi]；laitiers 里 ai 读 [ɛ]；复数 s 不发音；两个词都要加 s。","et":"produit 来自 produire（拉丁语 producere）；laitier 来自 lait（拉丁语 lac, lactis）加后缀 -ier。","ex":[["Le lait et le fromage sont des produits laitiers.","牛奶和奶酪是乳制品。"],["Je ne mange pas de produits laitiers.","我不吃乳制品。"],["Il y a un rayon de produits laitiers au supermarché.","超市有乳制品区。"]],"co":[["le rayon produits laitiers","乳制品货架"],["sans produits laitiers","不含乳制品"],["allergique aux produits laitiers","对乳制品过敏"],["des produits laitiers frais","新鲜乳制品"]],"sy":[["laitages","courant","乳制品，更日常"],["crèmerie","courant","乳品店"]],"fq":"中频，健康和购物话题。","me":"produits + lait-ier：来自「牛奶」的产品。","tr":{"zh":"我对乳制品过敏，所以不吃奶酪。","fr":"Je suis allergique aux produits laitiers, donc je ne mange pas de fromage.","alt":"Je ne supporte pas les produits laitiers, alors pas de fromage pour moi.","note":"ne … pas de + 名词：否定后冠词变 de。"}},
 "Des saucisses": {"pos":"n.f.pl. 阴性复数名词，单数 une saucisse","s":"香肠（生的或煮过的，需要加热吃）。saucisse 通常要煎或烤；saucisson 是硬的干香肠，可以直接切片吃，别混淆。","ipa":"[so.sis]","ph":"s [s]；au 读 [o]；ss 读 [s]；i [i]；结尾 e 不发音；复数 s 不发音。","pi":"au 读 [o]，不是 [au]；saucisse 和 saucisson 是两种不同的香肠。","et":"来自拉丁语 salsicia，由 salsus（用盐腌的）而来。同源：sel（盐）。","ex":[["J'achète des saucisses.","我买香肠。"],["Nous faisons griller des saucisses au barbecue.","我们在烧烤时烤香肠。"],["Elle mange des saucisses avec des lentilles.","她吃香肠配扁豆。"]],"co":[["des saucisses de Toulouse","图卢兹香肠"],["des saucisses grillées","烤香肠"],["une saucisse-purée","香肠配土豆泥"],["des saucisses de Strasbourg","斯特拉斯堡香肠"]],"sy":[["saucisson","courant","干香肠，直接切片吃"],["merguez","courant","北非辣味羊肉香肠"],["chipolata","courant","细小的猪肉香肠"]],"fq":"中高频，烹饪和购物话题。","me":"saucisse ← salsus（咸的）：用盐腌出来的肉。","tr":{"zh":"我们周末烧烤时烤香肠。","fr":"Ce week-end, nous faisons griller des saucisses au barbecue.","alt":"Ce week-end, on fait un barbecue avec des saucisses.","note":"faire griller = 烤。"}},
 "Les inégalités sociales": {"pos":"n.f.pl. 阴性复数名词，单数 une inégalité sociale","s":"社会不平等；社会中的收入、教育、机会等方面的差距。新闻、政治、社会学里常见。inégalité 是阴性，形容词 sociales 要相应变阴性复数。","ipa":"[i.ne.ga.li.te.sɔ.sjal]","ph":"in 在这里读 [i.n]，不是鼻化（因为 in- 后面是元音 é）；é [e]；g [g]；-té 读 [te]；sociales 读 [sɔ.sjal]，ci 读 [sj]，结尾 es 的 e 不发音，l 要读出来。","pi":"inégalités 开头的 in- 读 [i.n]，不是鼻化 [ɛ̃]；注意 g 读 [g]，不是 [ʒ]。","et":"inégalité 来自拉丁语 inaequalitas（in- 否定 + aequalis 相等）；social 来自拉丁语 socialis（社会的，源于 socius 伙伴）。","ex":[["Il y a des inégalités sociales.","存在社会不平等。"],["Le gouvernement veut réduire les inégalités sociales.","政府想减少社会不平等。"],["Les inégalités sociales augmentent dans ce pays.","这个国家的社会不平等在加剧。"]],"co":[["réduire les inégalités sociales","减少社会不平等"],["lutter contre les inégalités","对抗不平等"],["les inégalités de revenus","收入不平等"],["l'égalité des chances","机会平等"]],"sy":[["injustice sociale","courant","社会不公"],["fracture sociale","courant","社会断裂"],["égalité","courant","反义词：平等"]],"fq":"中频，新闻和讨论中常见。","me":"inégalités = in- + égalité：「不平等」，开头 i-n-é 连读。","tr":{"zh":"政府必须减少社会不平等。","fr":"Le gouvernement doit réduire les inégalités sociales.","alt":"Il faut que le gouvernement réduise les inégalités sociales.","note":"devoir + 动词原形 表示「必须」。"}},
 "Un \"poké\" / \"poké bowl\"": {"pos":"n.m. 阳性名词，复数 pokés / poké bowls（外来词）","s":"夏威夷鱼生拌饭碗；生鱼块（鲑鱼、金枪鱼）配米饭、蔬菜、牛油果等的盖饭。近年在法国城市很流行。poké 本是夏威夷语「切块」。","ipa":"[pɔ.ke]","ph":"poké 读 [pɔ.ke]，é 读 [e]；bowl 读 [bol]，借自英语，ow 读 [o]。","pi":"é 要读出来 [e]，别读成英语的 [poʊ.keɪ]；bowl 读 [bol]，不要读成 [baul]。","et":"来自夏威夷语 poke（切成块），经英语传入法语。bowl 来自英语，意为「碗」。","ex":[["Je mange un poké bowl ce midi.","我中午吃波奇碗。"],["Il commande un poké au saumon.","他点了一份三文鱼波奇饭。"],["Ce restaurant sert de bons poké bowls.","这家餐厅的波奇碗很好吃。"]],"co":[["un poké bowl au saumon / au thon","三文鱼 / 金枪鱼波奇碗"],["un poké végétarien","素波奇碗"],["commander un poké","点一份波奇碗"],["un bar à poké","波奇碗餐厅"]],"sy":[["bol de riz","courant","饭碗，更泛指"],["sushi","courant","寿司，不同的日式料理"],["buddha bowl","courant","素食碗，类似的菜式"]],"fq":"中低频，年轻人和城市餐厅常见。","me":"poké = 夏威夷话「切块」：切好的鱼块盖在饭上。","tr":{"zh":"今天中午我想吃三文鱼波奇碗。","fr":"Ce midi, j'ai envie d'un poké bowl au saumon.","alt":"Ce midi, je prends un poké au saumon.","note":"avoir envie de + 名词 / 动词原形：想要。"}},
 "Un bistro / bistrot": {"pos":"n.m. 阳性名词，复数 bistros / bistrots","s":"小酒馆；法式小餐馆；街角咖啡馆。供应简单的家常菜、咖啡和酒，气氛随意。和英国的 pub 不完全一样：bistro 更偏吃饭。","ipa":"[bis.tʁo]","ph":"bis 读 [bis]，s 要读；tro 读 [tʁo]；bistrot 的结尾 t 不发音，两种拼写读音相同。","pi":"bistrot 结尾 t 不发音；bis 里的 s 要读出来：[bis.tʁo]。","et":"来源不确定。有人说来自俄语 bystro（快点），但这个说法并不可靠。","ex":[["Nous mangeons dans un bistro.","我们在小酒馆吃饭。"],["Il y a un petit bistrot au coin de la rue.","街角有一家小酒馆。"],["On se retrouve au bistrot après le travail.","下班后我们在小酒馆见。"]],"co":[["un bistrot de quartier","街区小酒馆"],["un bistrot parisien","巴黎小酒馆"],["manger au bistrot","在小酒馆吃饭"],["un repas de bistrot","小酒馆式家常饭"]],"sy":[["café","courant","咖啡馆，更偏喝东西"],["brasserie","courant","大型啤酒馆餐厅"],["troquet","familier","小酒馆，口语"]],"fq":"中频，日常和旅游常用。","me":"bistro 两种拼写 bistro / bistrot，读音一样。","tr":{"zh":"我们下班后在街角的小酒馆见。","fr":"On se retrouve au bistrot du coin après le travail.","alt":"On se voit au petit bistrot du coin après le boulot.","note":"se retrouver = 约好见面；du coin = 街角的。"}},
 "Ajouter": {"pos":"v. 动词，第一组（-er），助动词 avoir；j'ajoute, nous ajoutons, j'ai ajouté","s":"添加；加上；补充说。ajouter du sel = 加盐；ajouter que … = 补充说……。ajouter A à B = 把 A 加到 B 里。","ipa":"[a.ʒu.te]","ph":"a [a]；j 读 [ʒ]；ou 读 [u]；ter 读 [te]；结尾 -er 读 [e]，r 不发音。","pi":"j 读 [ʒ]，不是 [dʒ]；结尾 -er 读 [e]；第一人称 j'ajoute 中 j' 后面 a 省音。","et":"来自拉丁语 adjuxtare（靠近放，由 juxta「紧挨着」而来）。","ex":[["J'ajoute du sel.","我加盐。"],["Elle ajoute un peu de sucre dans le thé.","她在茶里加一点糖。"],["Il ajoute qu'il sera en retard.","他补充说他会迟到。"]],"co":[["ajouter du sel / du sucre","加盐 / 糖"],["ajouter A à B","把 A 加到 B"],["ajouter que…","补充说……"],["ajouter un ami sur…","把朋友加到……"]],"sy":[["rajouter","courant","再添加"],["additionner","courant","把数相加"],["enlever","courant","反义：去掉"]],"fq":"高频，日常和菜谱常用。","me":"ajouter：a + joute，靠着一起放。","tr":{"zh":"请再加一点盐。","fr":"Ajoute un peu de sel, s'il te plaît.","alt":"Tu peux rajouter un peu de sel ?","note":"命令式 tu 形式 ajoute 不加 s（第一组动词）。"}},
 "Cuire": {"pos":"v. 动词，第三组（不规则），助动词 avoir；je cuis, nous cuisons, j'ai cuit","s":"煮；烤；烹熟（让食物受热变熟）。可及物（cuire le riz）也可不及物（le riz cuit）。常说 faire cuire + 食物：煮、烤。","ipa":"[kɥiʁ]","ph":"cui 读 [kɥi]；结尾 r 要读出来 [ʁ]；整个词只有一个音节。","pi":"cui 读 [kɥi]，不是 [ku.i]；r 要发音。cuire 是不规则动词，分词是 cuit，不是 cuiré。","et":"来自拉丁语 coquere（煮）。同源：cuisine、cuisson、biscuit（「煮两次」的饼）。","ex":[["Je fais cuire les pâtes.","我煮意面。"],["Les pommes de terre cuisent depuis vingt minutes.","土豆已经煮了二十分钟。"],["Le gâteau est cuit.","蛋糕烤好了。"]],"co":[["faire cuire des pâtes","煮意面"],["cuire à feu doux","小火慢煮"],["bien cuit","全熟"],["cuire au four","用烤箱烤"]],"sy":[["faire cuire","courant","煮、烤（更常用）"],["bouillir","courant","煮沸、水开"],["rôtir","courant","烤肉"]],"fq":"高频，烹饪必备。","me":"cuire → cuisine → cuisson：同一家，都和「火候」有关。","tr":{"zh":"我把意面煮十分钟。","fr":"Je fais cuire les pâtes pendant dix minutes.","alt":"Je laisse cuire les pâtes dix minutes.","note":"faire cuire + 食物，表示「把食物煮熟」。"}},
 "Cultiver": {"pos":"v. 动词，第一组（-er），助动词 avoir；je cultive, nous cultivons, j'ai cultivé","s":"种植；耕种；培养。cultiver des tomates = 种番茄；cultiver son esprit = 提升修养；se cultiver = 提高自己的文化修养。","ipa":"[kyl.ti.ve]","ph":"cul 读 [kyl]，u 读 [y]；ti [ti]；结尾 -er 读 [e]。","pi":"u 读 [y]，不是 [u]；t 读 [t]，不是 [s]（和 -tion 不同）；结尾 r 不发音。","et":"来自中世纪拉丁语 cultivare，源自 cultus（耕作的、被照料的）。同源：culture、agriculture。","ex":[["Mon grand-père cultive des tomates.","我爷爷种番茄。"],["Ils cultivent du blé dans cette région.","他们在这个地区种小麦。"],["Elle aime se cultiver en lisant.","她喜欢通过读书提升自己。"]],"co":[["cultiver des légumes","种蔬菜"],["cultiver la terre","耕地"],["se cultiver","提高文化修养"],["cultiver une amitié","维护友谊"]],"sy":[["planter","courant","栽种，只指种下去"],["faire pousser","courant","使生长、种"],["élever","courant","养（动物）"]],"fq":"中频，农业和文化话题。","me":"cultiver：从 culture 来，「种」地和「培养」人用同一个词。","tr":{"zh":"我爷爷在花园里种番茄和豆子。","fr":"Mon grand-père cultive des tomates et des haricots dans son jardin.","alt":"Mon grand-père fait pousser des tomates et des haricots dans son jardin.","note":"植物是 cultiver，动物是 élever。"}},
 "Dessiner": {"pos":"v. 动词，第一组（-er），助动词 avoir；je dessine, nous dessinons, j'ai dessiné","s":"画（线条、素描、图）；设计。用铅笔或笔画线条是 dessiner；用颜料上色是 peindre。dessiner un plan = 画图纸。","ipa":"[de.si.ne]","ph":"de 读 [de]；ss 读 [s]；i [i]；ner 读 [ne]；结尾 -er 读 [e]。","pi":"dessiner 的 e 读 [e]（不是 [ə]）；ss 读 [s]，不是 [z]；结尾 r 不发音。","et":"来自意大利语 disegnare，源自拉丁语 designare（标出、指定）。同源：dessin（图画）、dessein（意图）、design。","ex":[["Je dessine une fleur.","我画一朵花。"],["L'enfant dessine un chat.","孩子画了一只猫。"],["Il dessine très bien.","他画得很好。"]],"co":[["dessiner un portrait","画肖像"],["dessiner au crayon","用铅笔画"],["un dessin animé","动画片"],["dessiner un plan","画一张图纸"]],"sy":[["peindre","courant","用颜料画"],["tracer","courant","画线条"],["croquer","courant","速写"]],"fq":"高频，日常常用。","me":"dessiner → dessin：画的东西就是 un dessin。","tr":{"zh":"我女儿喜欢用彩色铅笔画画。","fr":"Ma fille aime dessiner avec des crayons de couleur.","alt":"Ma fille adore dessiner aux crayons de couleur.","note":"aimer + 动词原形：喜欢做某事。"}},
 "Enfourner": {"pos":"v. 动词，第一组（-er），助动词 avoir；j'enfourne, nous enfournons, j'ai enfourné","s":"放进烤箱；把面包、蛋糕等送进炉里烤。菜谱常用：enfourner à 180 degrés。口语里也可以夸张地说「塞进嘴里、吞下」。","ipa":"[ɑ̃.fuʁ.ne]","ph":"en 读鼻化 [ɑ̃]；four 读 [fuʁ]，ou 读 [u]；ner 读 [ne]。","pi":"en 读 [ɑ̃]；four 的 r 要读出来；整个词有三个音节 [ɑ̃.fuʁ.ne]。","et":"由 en-（放进）+ four（炉、烤箱，拉丁语 furnus）+ -er 构成。反义词：défourner（取出）。","ex":[["J'enfourne le gâteau.","我把蛋糕放进烤箱。"],["Enfournez à 180 degrés pendant trente minutes.","放进烤箱，180 度烤三十分钟。"],["Le boulanger enfourne le pain.","面包师把面包放进炉里。"]],"co":[["enfourner un gâteau / du pain","把蛋糕 / 面包放进烤箱"],["enfourner à 180 °C","放进 180 度的烤箱"],["préchauffer le four","预热烤箱"],["mettre au four","放进烤箱"]],"sy":[["mettre au four","courant","放进烤箱，更日常"],["défourner","courant","反义：从烤箱取出"]],"fq":"中低频，菜谱常见。","me":"enfourner = en + four：放「进」four（烤箱）里。","tr":{"zh":"把蛋糕放进烤箱，烤三十分钟。","fr":"Enfourne le gâteau et laisse-le cuire trente minutes.","alt":"Mets le gâteau au four pendant trente minutes.","note":"命令式 enfourne（tu）第一组动词不加 s。"}},
 "Fondre": {"pos":"v. 动词，第三组（规则变位 -dre），助动词 avoir；je fonds, il fond, nous fondons, j'ai fondu","s":"融化；熔化；溶解。le chocolat fond = 巧克力化了。也可以说「消失、迅速减少」，fondre en larmes = 泪如雨下；fondre sur = 扑向。faire fondre = 使融化。","ipa":"[fɔ̃dʁ]","ph":"fon 读鼻化 [fɔ̃]；dre 读 [dʁ]；结尾 e 不发音。","pi":"fon 是鼻化元音；变位时 il fond 结尾 d 不发音，nous fondons 才读 d。","et":"来自拉丁语 fundere（倾倒、熔化）。同源：英语 fuse、found；法语 fonte、fondue。","ex":[["Le chocolat fond au soleil.","巧克力在阳光下融化。"],["Je fais fondre du beurre dans la poêle.","我在锅里化黄油。"],["La neige a fondu.","雪化了。"]],"co":[["faire fondre du beurre","化黄油"],["fondre au soleil / à la chaleur","遇热融化"],["fondre en larmes","泪如雨下"],["fondre dans la bouche","入口即化"]],"sy":[["dégeler","courant","解冻、化冻"],["se liquéfier","soutenu","液化"],["durcir","courant","反义：变硬"]],"fq":"中高频，烹饪和天气话题。","me":"fondre → fondue：奶酪「融化」成的法式火锅。","tr":{"zh":"先在锅里把黄油化开。","fr":"D'abord, fais fondre le beurre dans la poêle.","alt":"Commence par faire fondre le beurre dans la poêle.","note":"faire fondre = 使融化，fondre 单用是「自己化开」。"}},
 "Gonfler": {"pos":"v. 动词，第一组（-er），助动词 avoir；je gonfle, nous gonflons, j'ai gonflé","s":"膨胀；鼓起；发起来；使充气。可及物（gonfler un ballon = 给气球打气）也可不及物（la pâte gonfle = 面团发起来）。书上义为面包「发起来」。","ipa":"[ɡɔ̃.fle]","ph":"g 读 [g]；on 读鼻化 [ɔ̃]；fl [fl]；结尾 -er 读 [e]。","pi":"on 是鼻化元音，n 不发音；g 读 [g] 而不是 [ʒ]；结尾 r 不发音。","et":"来自拉丁语 conflare（吹在一起、鼓起来），由 con- 和 flare（吹）构成。","ex":[["Le pain va gonfler.","面包会发起来。"],["Je gonfle le ballon.","我给气球打气。"],["Mon pied a gonflé après la chute.","我的脚摔后肿了。"]],"co":[["gonfler un ballon / un pneu","给气球 / 轮胎充气"],["la pâte gonfle","面团发起来"],["avoir le ventre gonflé","肚子胀"],["gonfler à la chaleur","遇热膨胀"]],"sy":[["lever","courant","面团发酵、涨起来"],["enfler","courant","肿起来"],["dégonfler","courant","反义：放气、消肿"]],"fq":"中频，烹饪和日常话题。","me":"gonfler：想像 f-l-e 吹气，气球鼓起来。","tr":{"zh":"面团放在暖处，会发起来。","fr":"Mets la pâte dans un endroit chaud, elle va gonfler.","alt":"Laisse la pâte au chaud, elle va gonfler.","note":"aller + 动词原形：表示即将发生的事。"}},
 "Mélanger": {"pos":"v.t. 第一组动词（-er），助动词 avoir","s":"混合；搅拌；把东西弄混。做菜时 mélanger A et B = 把 A 和 B 拌在一起。也可表示「弄乱、搞混」（mélanger des papiers）。","ipa":"[me.lɑ̃.ʒe]","ph":"é [e]；an [ɑ̃]；g 在 e 前读 [ʒ]；结尾 -er 读 [e]。","pi":"an 是鼻化音 [ɑ̃]，不要读成 [an]；-er 不发 r。","et":"来自 mêler（混合）的词族，加后缀 -anger；同族：mélange（混合物）。","ex":[["Je mélange les ingrédients.","我把配料拌匀。"],["Ne mélange pas tes affaires avec les miennes.","别把你的东西和我的混在一起。"]],"co":[["mélanger A avec / et B","把 A 和 B 混合"],["bien mélanger","充分搅拌"],["se mélanger","混在一起"]],"sy":[["mêler","soutenu","混合，比 mélanger 书面"],["remuer","courant","搅动（不一定混合）"],["touiller","familier","用勺子搅（口语）"]],"fq":"高频，做饭常用。","me":"mélange（混合）+ -er：一个「混」字就是 mélanger。","tr":{"zh":"把面粉和鸡蛋拌在一起。","fr":"Mélange la farine et les œufs.","alt":"Mélange bien la farine avec les œufs.","note":"mélanger A et B / A avec B。"}},
 "Mettre": {"pos":"v.t. 第三组不规则动词，助动词 avoir","s":"放；放置；穿上（衣服）；花（时间）。mettre la table = 摆桌子；mettre un manteau = 穿上外套；mettre 10 minutes = 花了 10 分钟。","ipa":"[mɛtʁ]","ph":"e 在 tt 前读 [ɛ]；结尾 -tre 读 [tʁ]，e 不发音。","pi":"现在时 je mets / tu mets / il met：单数的 t 不发音；nous mettons、ils mettent 才读 t。过去分词 mis。","et":"来自拉丁语 mittere（送，放）。同族：permettre、promettre、remettre、admettre。","ex":[["Je mets le plat sur la table.","我把菜放在桌上。"],["Mets ton manteau, il fait froid.","把外套穿上，天冷。"],["Ça met une heure pour y aller.","到那里要一个小时。"]],"co":[["mettre la table","摆桌子"],["mettre un vêtement","穿上衣服"],["se mettre à + inf.","开始做某事"],["mettre du temps","花时间"]],"sy":[["poser","courant","放（平放），较具体"],["placer","courant","安置"],["enfiler","courant","套上（衣服）"]],"fq":"极高频，日常最常用动词之一。","me":"mettre 像 permettre、promettre 的「根」：mettre = 放。","tr":{"zh":"我把牛奶放在冰箱里。","fr":"Je mets le lait dans le frigo.","alt":"Je range le lait au frigo.","note":"mettre + 东西 + 地点；现在时 je mets。"}},
 "Peser": {"pos":"v.t./v.i. 第一组动词（-er），助动词 avoir","s":"称重；重（多少）。Je pèse 60 kilos = 我体重 60 公斤。也可表示「权衡」（peser le pour et le contre）。","ipa":"[pə.ze]","ph":"词首 pe [pə]；s 在元音间读 [z]。变位时 e 变 è：je pèse [pɛz]。","pi":"s 读 [z]，不是 [s]；je pèse、ils pèsent 有重音符号，nous pesons 没有。","et":"来自拉丁语 pensare（称重，权衡）。同族：poids（重量）、pesée（称重）。","ex":[["Je dois peser la farine.","我得称一下面粉。"],["Combien tu pèses ?","你多重？"]],"co":[["peser les fruits","称水果"],["peser le pour et le contre","权衡利弊"],["se peser","称自己体重"]],"sy":[["soupeser","courant","用手掂量"],["évaluer","courant","评估"]],"fq":"中频。","me":"poids（重量）和 peser 是一家：p-s 开头。","tr":{"zh":"请称一下这些苹果。","fr":"Pesez ces pommes, s'il vous plaît.","alt":"Vous pouvez peser ces pommes, s'il vous plaît ?","note":"变位 e→è：je pèse。"}},
 "Planter": {"pos":"v.t. 第一组动词（-er），助动词 avoir","s":"种植；栽；插（钉子、帐篷）。planter un arbre = 种树；planter une tente = 搭帐篷。口语 planter qqn = 放某人鸽子；ça plante = 电脑死机。","ipa":"[plɑ̃.te]","ph":"an [ɑ̃]；结尾 -er 读 [e]。","pi":"an 是鼻化音，不读 [an]；pl 连读成一个辅音群。","et":"来自拉丁语 plantare（栽）。同族：plante（植物）、plantation（种植园）。","ex":[["Nous plantons des légumes dans le potager.","我们在菜园里种蔬菜。"],["Il a planté un arbre dans le jardin.","他在花园里种了一棵树。"]],"co":[["planter un arbre","种树"],["planter une tente","搭帐篷"],["planter un clou","钉钉子"]],"sy":[["semer","courant","播种（种子）"],["enfoncer","courant","打入，插入"],["poser un lapin","familier","放鸽子"]],"fq":"中频。","me":"plante（植物）+ -er：把植物放进土里。","tr":{"zh":"春天我们种花。","fr":"Au printemps, nous plantons des fleurs.","alt":"Au printemps, on plante des fleurs.","note":"planter 种幼苗或树；semer 才是播种子。"}},
 "Préchauffer": {"pos":"v.t. 第一组动词（-er），助动词 avoir","s":"预热（烤箱）。几乎只用于烤箱：préchauffer le four à 180 degrés。食谱里常见命令式或 Il faut + 不定式。","ipa":"[pʁe.ʃo.fe]","ph":"pré [pʁe]；ch [ʃ]；au [o]；结尾 -er 读 [e]。","pi":"ch 读 [ʃ]（像「西」），不是 [k]；au 读 [o]。","et":"pré-（预先）+ chauffer（加热）。chauffer 来自拉丁语 calefacere。","ex":[["Il faut préchauffer le four.","要预热烤箱。"],["Préchauffez le four à 180 degrés.","把烤箱预热到 180 度。"]],"co":[["préchauffer le four","预热烤箱"],["préchauffer à 200 °C","预热到 200 度"]],"sy":[["chauffer","courant","加热（没有「预先」的意思）"],["faire chauffer","courant","加热"]],"fq":"中频，食谱常见。","me":"pré（先）+ chauffer（热）：先热一下。","tr":{"zh":"先把烤箱预热到 180 度。","fr":"Préchauffez d'abord le four à 180 degrés.","alt":"D'abord, on préchauffe le four à 180 degrés.","note":"食谱常用命令式 préchauffez。"}},
 "Verser": {"pos":"v.t. 第一组动词（-er），助动词 avoir","s":"倒；注入；（钱）支付、汇入。verser du lait dans une tasse = 往杯里倒牛奶；verser de l'argent = 汇款。","ipa":"[vɛʁ.se]","ph":"ver [vɛʁ]；s 在辅音后读 [s]；结尾 -er 读 [e]。","pi":"er 在词中读 [ɛʁ]，在结尾读 [e]；s 读 [s]，不是 [z]。","et":"来自拉丁语 versare（转动，翻转）。同族：verse（倾盆而下 il pleut à verse）。","ex":[["Je verse de l'eau dans le verre.","我往杯里倒水。"],["Verse-moi un peu de vin, s'il te plaît.","请给我倒一点酒。"]],"co":[["verser A dans B","把 A 倒进 B"],["verser du sel","加盐"],["il pleut à verse","下倾盆大雨"],["se verser un verre","给自己倒一杯"]],"sy":[["servir","courant","斟（饮料）、上菜"],["remplir","courant","装满"]],"fq":"高频，日常常用。","me":"verser 的 ver- 和 verre（杯子）长得像：往 verre 里 verser。","tr":{"zh":"请给我倒一杯水。","fr":"Verse-moi un verre d'eau, s'il te plaît.","alt":"Tu peux me verser de l'eau ?","note":"命令式 verse-moi：第二人称单数 -er 动词去掉 s。"}},
 "Healthy": {"pos":"adj. 不变形（借自英语，口语）","s":"健康的，对身体好的（多指饮食、生活方式）。口语常说 un repas healthy、manger healthy。不变形，阴阳性、单复数都用 healthy。","ipa":"[ɛl.ti]","ph":"h 不发音；ea 读 [ɛ]；th 常读 [t]；结尾 y 读 [i]。","pi":"法语里 th 一般不读英语的 [θ]，多读 [t]；h 不发音。","et":"直接借自英语 healthy；法语正式说法是 sain 或 bon pour la santé。","ex":[["Je mange un repas healthy.","我吃一顿健康餐。"],["Elle fait du sport et mange healthy.","她运动，也吃得健康。"]],"co":[["manger healthy","吃得健康"],["un repas healthy","健康餐"],["un mode de vie healthy","健康的生活方式"]],"sy":[["sain","courant","健康的（正式、标准）"],["équilibré","courant","均衡的"],["bon pour la santé","courant","对健康有益"]],"fq":"中频，口语和广告里常见；正式场合用 sain。","me":"就是英语 healthy，只是 h 不发音。","tr":{"zh":"我想吃得健康一点。","fr":"Je veux manger plus sain.","alt":"Je veux manger healthy.","note":"标准法语更常说 sain；healthy 偏口语、潮流。"}},
 "Acide": {"pos":"adj. 阴阳性同形（un goût acide / une pomme acide）；也作 n.m. 酸","s":"酸的；酸性的。形容柠檬、醋的酸味。也可以指人说话尖刻（un ton acide）。n.m. 酸（un acide）。","ipa":"[a.sid]","ph":"c 在 i 前读 [s]；结尾 e 不发音。","pi":"c 读 [s]，不是 [k]；重音在最后一个音节 [sid]。","et":"来自拉丁语 acidus（酸的）。同族：acidité。","ex":[["Le citron est acide.","柠檬是酸的。"],["Cette sauce est trop acide.","这个酱太酸了。"]],"co":[["un goût acide","酸味"],["un fruit acide","酸的水果"],["la pluie acide","酸雨"]],"sy":[["aigre","courant","酸腐的（常带不愉快）"],["sucré","courant","反义：甜的"]],"fq":"中频。","me":"acide 就是英语 acid，多了个 e。","tr":{"zh":"这个橙子太酸了。","fr":"Cette orange est trop acide.","alt":"Cette orange est vraiment trop acide.","note":"acide 阴阳性相同。"}},
 "Aimable": {"pos":"adj. 阴阳性同形，复数 aimables","s":"亲切的；和蔼的；有礼貌的。形容人友善客气。礼貌用语 Vous êtes très aimable = 您真好心。","ipa":"[ɛ.mabl]","ph":"ai [ɛ]；-able 读 [abl]，结尾 e 不发音。","pi":"ai 读 [ɛ]，不是 [ai]；注意不是「可爱」：可爱用 mignon。","et":"来自拉丁语 amabilis（值得爱的），源自 amare（爱）。同族：aimer、amical。","ex":[["Le serveur est aimable.","服务员很亲切。"],["Merci, vous êtes très aimable.","谢谢，您真好心。"]],"co":[["une personne aimable","亲切的人"],["Vous êtes trop aimable.","您太客气了。"],["être aimable avec qqn","对某人友善"]],"sy":[["gentil","courant","好心的（更日常）"],["sympathique","courant","讨人喜欢的"],["aimable","soutenu","用于礼貌表达"]],"fq":"中频，礼貌场合常用。","me":"aim + able：值得 aimer（爱）的人。","tr":{"zh":"售货员很亲切。","fr":"La vendeuse est très aimable.","alt":"La vendeuse est vraiment gentille.","note":"aimable 阴阳性同形。"}},
 "Alcoolisé(e)": {"pos":"adj. 阴性 alcoolisée，复数 alcoolisés","s":"含酒精的。une boisson alcoolisée = 含酒精的饮料；反义 sans alcool（无酒精的）。","ipa":"[al.kɔ.li.ze]","ph":"al [al]；cool 在这里读 [kɔ]，不是 [kul]；结尾 é [e]。","pi":"alcoolisé 里的 oo 读 [ɔ]，别读成英语 cool。","et":"alcool + 动词后缀 -iser，再变过去分词 -é。alcool 源自阿拉伯语 al-kuḥl。","ex":[["C'est une boisson alcoolisée.","这是含酒精的饮料。"],["Ce cocktail n'est pas alcoolisé.","这杯鸡尾酒不含酒精。"]],"co":[["une boisson alcoolisée","含酒精饮料"],["non alcoolisé / sans alcool","无酒精的"],["un cocktail alcoolisé","含酒精的鸡尾酒"]],"sy":[["sans alcool","courant","反义：无酒精"],["fort","courant","（酒）烈的"]],"fq":"中频。","me":"alcool + -isé：被「酒精化」了的饮料。","tr":{"zh":"这杯饮料含酒精吗？","fr":"Cette boisson est alcoolisée ?","alt":"Il y a de l'alcool dans cette boisson ?","note":"阴性加 -e：alcoolisée。"}},
 "Amer / Amère": {"pos":"adj. 阳性 amer，阴性 amère，复数 amers / amères","s":"苦的；痛苦的；愤愤不平的。形容咖啡、巧克力的苦味，也可指人心里苦涩（un souvenir amer）。","ipa":"[a.mɛʁ]","ph":"amer 读 [a.mɛʁ]，结尾 r 要读；amère 读 [a.mɛʁ]，几乎同音。","pi":"阳性 amer 的 r 要发；阳阴性读音相同，只靠拼写区分。","et":"来自拉丁语 amarus（苦的）。同族：amertume（苦味）。","ex":[["Le café est amer.","咖啡是苦的。"],["Cette tisane est un peu amère.","这杯花草茶有点苦。"],["Il garde un souvenir amer de cette année.","他对那一年的记忆很苦涩。"]],"co":[["un goût amer","苦味"],["du chocolat amer","黑巧克力（较苦）"],["un souvenir amer","苦涩的回忆"]],"sy":[["âpre","soutenu","涩而刺口"],["doux","courant","反义：温和、甜"],["sucré","courant","反义：甜"]],"fq":"中频。","me":"amer 像 mère 的音：阴性 amère 与 mère 押韵。","tr":{"zh":"黑咖啡有点苦。","fr":"Le café noir est un peu amer.","alt":"Le café noir, c'est un peu amer.","note":"阴性 amère 有 è。"}},
 "Doré(e)": {"pos":"adj. 阴性 dorée，复数 dorés","s":"金黄色的；镀金的。做菜指烤到金黄（bien doré）；也指金色的东西（des cheveux dorés）。","ipa":"[dɔ.ʁe]","ph":"d [d]；o 读 [ɔ]；r [ʁ]；é [e]。","pi":"r 是小舌音 [ʁ]；doré 不是 [dore] 而是 [dɔ.ʁe]。","et":"来自 dorer（镀金），源自 or（金），拉丁语 aurum。","ex":[["Le pain est bien doré.","面包烤得金黄。"],["Elle a des cheveux dorés.","她有一头金黄色的头发。"]],"co":[["bien doré","烤得金黄"],["faire dorer","煎（烤）到金黄"],["le soleil doré","金色的阳光"]],"sy":[["jaune","courant","黄色的"],["en or","courant","金做的"],["grillé","courant","烤焦黄的"]],"fq":"中频，做饭和描写常用。","me":"doré ← or（金）：「变成金色」。","tr":{"zh":"让洋葱炒到金黄。","fr":"Fais dorer les oignons.","alt":"Laisse les oignons dorer.","note":"faire dorer = 煎到金黄。"}},
 "Élevé(e)": {"pos":"adj. 阴性 élevée，复数 élevés","s":"高的（水平、比率、价格）；教养的。le taux est élevé = 比率高。bien élevé = 有教养；mal élevé = 没教养。","ipa":"[el.ve]","ph":"é [e]；l；e 读 [ə] 常省略，所以 [el.ve]；结尾 é [e]。","pi":"élevé 只用于抽象的高（水平、价格）；人的身高、山高用 grand / haut。","et":"来自 élever（抬高、养育），拉丁语 elevare。","ex":[["Le taux d'obésité est de plus en plus élevé.","肥胖率越来越高。"],["C'est un enfant bien élevé.","这是个有教养的孩子。"]],"co":[["un prix élevé","高价"],["un niveau élevé","高水平"],["bien / mal élevé","有 / 没教养"]],"sy":[["haut","courant","高的（具体）"],["important","courant","大的（量）"],["bas","courant","反义：低的"]],"fq":"高频，新闻和数据里常见。","me":"élevé ← élever：抬高了的。","tr":{"zh":"这家餐厅价格太高。","fr":"Les prix de ce restaurant sont trop élevés.","alt":"Ce restaurant est trop cher.","note":"élevé 一致：prix 复数，所以 élevés。"}},
 "Épicé(e)": {"pos":"adj. 阴性 épicée，复数 épicés","s":"辣的；加了香料的。法语 épicé 指香料味重、带辣味，不一定很辣（fort 才是很辣）。","ipa":"[e.pi.se]","ph":"é [e]；c 在 é 前读 [s]；结尾 é [e]。","pi":"c 读 [s]；辣可以说 épicé 或 piquant，注意 épicé 是「有香料」，不一定是辣椒的辣。","et":"来自 épice（香料），拉丁语 species（种类，货物）。","ex":[["Ce plat est très épicé.","这道菜很辣。"],["Je n'aime pas la cuisine épicée.","我不喜欢辣的菜。"]],"co":[["un plat épicé","辣的菜"],["très / peu épicé","很辣 / 不太辣"],["la cuisine épicée","重口味的菜"]],"sy":[["piquant","courant","辣而刺口"],["fort","courant","味道很冲、很辣"],["relevé","soutenu","调味很足的"]],"fq":"中频，点菜常用。","me":"épice（香料）+ -é：加了香料的。","tr":{"zh":"我不能吃太辣的东西。","fr":"Je ne peux pas manger trop épicé.","alt":"Je supporte mal les plats trop épicés.","note":"manger épicé 副词用法，不变形。"}},
 "Exceptionnel(le)": {"pos":"adj. 阴性 exceptionnelle，复数 exceptionnels","s":"非凡的；特别棒的；例外的。可褒义（太棒了），也可指「特殊的、例外的」（un cas exceptionnel）。","ipa":"[ɛk.sɛp.sjɔ.nɛl]","ph":"ex 读 [ɛks]；ti 读 [sj]；nn 只读一个 [n]；阴性 -elle 读 [ɛl]。","pi":"ti 读 [sj]，不是 [ti]；nn 虽写两个，只发一个 n。","et":"来自 exception（例外），拉丁语 exceptio，源自 excipere（取出）。","ex":[["Ce repas est exceptionnel.","这顿饭太棒了。"],["Ce n'est pas normal, c'est un cas exceptionnel.","这不正常，是个例外。"]],"co":[["un talent exceptionnel","非凡的才能"],["à titre exceptionnel","作为例外"],["un moment exceptionnel","难忘的时刻"]],"sy":[["extraordinaire","courant","非凡的"],["formidable","courant","了不起的"],["génial","familier","超棒的"]],"fq":"高频，口语和书面都常用。","me":"exception + -nel：「例外」的，所以很特别。","tr":{"zh":"这个景色太美了。","fr":"Cette vue est exceptionnelle.","alt":"Cette vue est vraiment magnifique.","note":"阴性 exceptionnelle，两个 l 和两个 n。"}},
 "Fondu(e)": {"pos":"adj.（fondre 的过去分词）阴性 fondue，复数 fondus","s":"融化的；化开的。du fromage fondu = 融化的奶酪。fondre 是第三组动词，过去分词 fondu：La glace a fondu = 冰淇淋化了。","ipa":"[fɔ̃.dy]","ph":"on [ɔ̃] 鼻化；u [y]（嘴圆，发 i 的音）。","pi":"u 读 [y]，不是 [u]；on 鼻化，不读 n。","et":"来自动词 fondre，拉丁语 fundere（倾泻，熔化）。同族：fondue（奶酪火锅）。","ex":[["Il y a du fromage fondu sur la pizza.","披萨上有融化的奶酪。"],["La neige a fondu.","雪化了。"]],"co":[["du fromage fondu","融化的奶酪"],["du beurre fondu","融化的黄油"],["fondre au soleil","在太阳下融化"]],"sy":[["liquide","courant","液态的"],["gelé / congelé","courant","反义：冰冻的"]],"fq":"中频。","me":"fondu 像 fondue（奶酪火锅）：奶酪被融化。","tr":{"zh":"我喜欢吃融化的奶酪。","fr":"J'aime le fromage fondu.","alt":"J'adore le fromage fondu.","note":"fondu 来自 fondre；阴性 fondue。"}},
 "Obèse": {"pos":"adj. 阴阳性同形，复数 obèses","s":"肥胖的（医学用语，体重严重超标）。比 gros 正式，也比较直接；对人说话要小心。也可作名词 un obèse。","ipa":"[ɔ.bɛz]","ph":"o 读 [ɔ]；è 读 [ɛ]；s 在元音间读 [z]。","pi":"s 读 [z]；è 带重音符号。注意这个词有点刺耳，当面说不礼貌。","et":"来自拉丁语 obesus（吃得胖的）。同族：obésité（肥胖）。","ex":[["Le chat est obèse.","这只猫很胖。"],["Le médecin dit qu'il est obèse.","医生说他肥胖。"]],"co":[["devenir obèse","变得肥胖"],["un enfant obèse","肥胖儿童"],["l'obésité","肥胖症"]],"sy":[["gros","courant","胖的（更日常）"],["en surpoids","courant","超重的，更委婉"],["maigre","courant","反义：瘦的"]],"fq":"中频，医学和新闻中常见。","me":"obèse ≈ 英语 obese。","tr":{"zh":"医生说这只狗太胖了。","fr":"Le vétérinaire dit que le chien est obèse.","alt":"Le vétérinaire trouve que le chien est en surpoids.","note":"obèse 阴阳性同形。"}},
 "Religieux / Religieuse": {"pos":"adj. 阳性 religieux，阴性 religieuse，复数 religieux / religieuses","s":"宗教的；虔诚的。une fête religieuse = 宗教节日。名词：un religieux / une religieuse = 修士 / 修女。","ipa":"[ʁə.li.ʒjø]","ph":"re [ʁə]；gi 读 [ʒj]；eux [ø]；阴性 -euse 读 [øz]。","pi":"阳性 x 不发音；阴性 religieuse 的 s 读 [z]；gi 读 [ʒj]。","et":"来自 religion，拉丁语 religio。","ex":[["C'est une fête religieuse.","这是宗教节日。"],["Il est très religieux.","他非常虔诚。"]],"co":[["une fête religieuse","宗教节日"],["un mariage religieux","宗教婚礼"],["une école religieuse","教会学校"]],"sy":[["pieux","soutenu","虔诚的"],["laïque","courant","反义：世俗的"],["croyant","courant","信教的"]],"fq":"中频。","me":"religion → religieux：-ion 变 -ieux。","tr":{"zh":"圣诞节是宗教节日。","fr":"Noël est une fête religieuse.","alt":"À Noël, on fête une tradition religieuse.","note":"修饰阴性名词用 religieuse。"}},
 "Salé(e)": {"pos":"adj. 阴性 salée，复数 salés；也作 n.m. le salé 咸味","s":"咸的；加了盐的。trop salé = 太咸。le salé = 咸味食物（对 le sucré 甜食）。也指「价格很贵」（l'addition est salée，口语）。","ipa":"[sa.le]","ph":"s [s]；a [a]；结尾 é [e]。","pi":"salé 开头是 s 不是 z；别和 sale [sal]（脏的）混：salé 有 é。","et":"来自 sel（盐），拉丁语 sal。同族：saler、salade。","ex":[["La soupe est trop salée.","汤太咸了。"],["Je préfère le salé au sucré.","我更喜欢咸的，不喜欢甜的。"]],"co":[["trop salé","太咸"],["le salé et le sucré","咸的和甜的"],["une addition salée","天价账单（口语）"]],"sy":[["salin","soutenu","含盐的"],["sucré","courant","反义：甜的"],["fade","courant","反义：淡而无味"]],"fq":"高频，饮食日常用语。","me":"sel + é：加了 sel 的。","tr":{"zh":"这个汤有点咸。","fr":"Cette soupe est un peu salée.","alt":"La soupe est trop salée pour moi.","note":"阴性 salée，与 soupe 一致。"}},
 "Sédentaire": {"pos":"adj. 阴阳性同形，复数 sédentaires","s":"久坐的；不爱活动的；定居的。un mode de vie sédentaire = 久坐不动的生活方式。反义 actif / nomade。","ipa":"[se.dɑ̃.tɛʁ]","ph":"é [e]；en 读 [ɑ̃]；结尾 -aire 读 [ɛʁ]。","pi":"en 是 [ɑ̃]，不读 [ɛn]；-aire 读 [ɛʁ]。","et":"来自拉丁语 sedentarius，源自 sedere（坐）。同族：siège（座位）。","ex":[["Il a un mode de vie sédentaire.","他生活方式久坐。"],["Un travail sédentaire est mauvais pour le dos.","久坐的工作对背不好。"]],"co":[["un mode de vie sédentaire","久坐的生活方式"],["un travail sédentaire","久坐的工作"],["des peuples sédentaires","定居民族"]],"sy":[["inactif","courant","不活跃的"],["actif","courant","反义：好动的"],["nomade","courant","反义：游牧的"]],"fq":"中频，健康话题中常见。","me":"sédentaire ← sedere（坐）：一直坐着的。","tr":{"zh":"办公室工作让人久坐。","fr":"Le travail de bureau est sédentaire.","alt":"Un travail de bureau, c'est sédentaire.","note":"sédentaire 阴阳性同形。"}},
 "Souriant(e)": {"pos":"adj. 阴性 souriante，复数 souriants","s":"笑容满面的；爱笑的；和蔼的。形容人总带微笑。souriant 是 sourire（微笑）的现在分词变成的形容词。","ipa":"[su.ʁjɑ̃]","ph":"ou [u]；r [ʁ]；ia 读 [ja]，这里 -iant 读 [jɑ̃]；t 不发音。","pi":"结尾 -ant 读 [ɑ̃]，t 不发音；阴性 souriante 才发 [t]。","et":"来自动词 sourire（sous- + rire，微笑）。","ex":[["Elle est toujours souriante.","她总是笑容满面。"],["Le vendeur est très souriant.","售货员总是笑眯眯的。"]],"co":[["un visage souriant","笑脸"],["rester souriant","保持微笑"],["une hôtesse souriante","笑容可掬的空姐"]],"sy":[["joyeux","courant","快乐的"],["aimable","courant","亲切的"],["grincheux","courant","反义：爱发牢骚的"]],"fq":"中频。","me":"sourire（微笑）→ souriant：正在微笑的。","tr":{"zh":"我们的老师总是笑眯眯的。","fr":"Notre professeur est toujours souriant.","alt":"Notre prof a toujours le sourire.","note":"souriant 随主语变化阴阳性。"}},
 "Sucré(e)": {"pos":"adj. 阴性 sucrée，复数 sucrés；也作 n.m. le sucré 甜食","s":"甜的；加了糖的。un thé sucré = 加糖的茶；pas sucré = 不甜。le sucré = 甜食，对 le salé。","ipa":"[sy.kʁe]","ph":"su 读 [sy]（u 是圆唇的 i）；cr [kʁ]；结尾 é [e]。","pi":"u 读 [y]，不是 [u]；别和 doux（柔和；甜度低）混。","et":"来自 sucre（糖）+ -é；sucre 经意大利语 zucchero，源自阿拉伯语 sukkar。","ex":[["Le gâteau est sucré.","蛋糕是甜的。"],["Je prends mon café non sucré.","我的咖啡不加糖。"]],"co":[["un goût sucré","甜味"],["non sucré","不加糖"],["le sucré et le salé","甜与咸"]],"sy":[["doux","courant","温和的，甜度轻"],["sirupeux","courant","糖浆般的，太甜"],["salé","courant","反义：咸的"]],"fq":"高频，饮食常用。","me":"sucre + é：加了 sucre 的。","tr":{"zh":"这杯茶不够甜。","fr":"Ce thé n'est pas assez sucré.","alt":"Il manque du sucre dans ce thé.","note":"阴性 sucrée，与名词一致。"}},
 "Transformé(e)": {"pos":"adj.（transformer 的过去分词）阴性 transformée，复数 transformés","s":"加工过的；变了样的。les aliments transformés = 加工食品。也指「被改变的」（une ville transformée）。","ipa":"[tʁɑ̃s.fɔʁ.me]","ph":"tr [tʁ]；an 读 [ɑ̃]；s 读 [s]；or 读 [ɔʁ]；结尾 é [e]。","pi":"an 是 [ɑ̃]；ns 连读成 [s]；transformé 的 r 要发。","et":"trans-（变化）+ forme（形状）+ -é。拉丁语 transformare。","ex":[["La nourriture transformée est souvent très salée.","加工食品通常很咸。"],["La ville est complètement transformée.","这座城市完全变样了。"]],"co":[["des aliments transformés","加工食品"],["un produit transformé","加工产品"],["transformé en…","变成……"]],"sy":[["industriel","courant","工业生产的"],["brut","courant","反义：未加工的"],["naturel","courant","反义：天然的"]],"fq":"中频，营养话题常见。","me":"trans-forme：改变了 forme（形状）。","tr":{"zh":"我少吃加工食品。","fr":"Je mange peu d'aliments transformés.","alt":"J'évite les produits transformés.","note":"peu de + 名词。"}},
 "Vegan / Végan / Végane": {"pos":"adj. 阴阳性：vegan 不变；végan 阳性（复数 végans）；végane 阴性（复数 véganes）；也作名词","s":"纯素的；纯素食者（不吃任何动物制品，包括奶、蛋、蜂蜜）。vegan 来自英语；végan / végane 是法语化拼写。végétarien 只是不吃肉。","ipa":"[ve.ɡan]","ph":"vegan 读 [ve.ɡan]；végan 常读 [ve.ɡɑ̃]；végane 读 [ve.ɡan]；g 读 [ɡ]。","pi":"végétarien 不是 vegan，不要混；g 是 [ɡ]，不是 [ʒ]。","et":"借自英语 vegan，由 vegetarian 缩写而来；法语又造了 végan / végane。","ex":[["Mon ami est végan.","我的朋友是纯素食者。"],["Elle suit un régime vegan.","她吃纯素饮食。"]],"co":[["un régime vegan","纯素饮食"],["un plat végan","纯素菜"],["devenir végan","成为纯素者"]],"sy":[["végétalien","courant","纯素食的（传统说法）"],["végétarien","courant","素食者（可吃蛋奶）"]],"fq":"中频，近年越来越常见。","me":"vegan ← vegetarian 缩短，只留头尾。","tr":{"zh":"她的饮食是纯素的。","fr":"Son alimentation est végane.","alt":"Elle est végane.","note":"修饰阴性 alimentation 用 végane。"}},
 "Être \"plein à craquer\"": {"pos":"loc. 固定短语（être + plein à craquer）","s":"挤得满满的；满得要爆了。形容公交车、房间、包、剧院等东西或人塞得很满。口语常用，也说 être bondé。","ipa":"[plɛ̃ a kʁa.ke]","ph":"plein [plɛ̃]（ein 鼻化）；à [a]；craquer [kʁa.ke]。","pi":"plein 的 ein 读 [ɛ̃]；craquer 的 qu 读 [k]；结尾 -er 读 [e]。","et":"plein（满）+ craquer（发出爆裂声）：满得快要「裂开」。","ex":[["Le bus est plein à craquer.","公交车挤爆了。"],["Ma valise est pleine à craquer.","我的行李箱塞得满满的。"]],"co":[["plein à craquer","满得快裂开"],["être bondé","挤满了人"],["une salle pleine à craquer","座无虚席的大厅"]],"sy":[["bondé","courant","挤满人的"],["complet","courant","客满的"],["vide","courant","反义：空的"]],"fq":"中频，口语常用。","me":"满到「咔嚓」一声要裂开：craquer。","tr":{"zh":"今晚的地铁挤满了人。","fr":"Le métro est plein à craquer ce soir.","alt":"Ce soir, le métro est bondé.","note":"plein 与主语一致：pleine / pleins。"}},
 "De l'asthme": {"pos":"n.m. 阳性名词，无复数常用","s":"哮喘。常说 avoir de l'asthme 或 faire de l'asthme（有哮喘）；une crise d'asthme = 哮喘发作。asthme 前用部分冠词 de l'。","ipa":"[asm]","ph":"asthme 读 [asm]：th 不发音，结尾 e 不发音。","pi":"th 不发音；整个词只有一个音节 [asm]。","et":"来自希腊语 asthma（喘息），经拉丁语入法语。","ex":[["Elle fait de l'asthme.","她有哮喘。"],["Il a une crise d'asthme.","他哮喘发作了。"]],"co":[["avoir de l'asthme","患哮喘"],["une crise d'asthme","哮喘发作"],["un inhalateur pour l'asthme","哮喘吸入器"]],"sy":[["allergie","courant","过敏（不是哮喘）"],["essoufflement","courant","气喘吁吁"]],"fq":"中频，健康话题常用。","me":"asthme 里 th 静音：只读 [asm]。","tr":{"zh":"我儿子有哮喘。","fr":"Mon fils a de l'asthme.","alt":"Mon fils fait de l'asthme.","note":"avoir de l'asthme：部分冠词 de l'。"}},
 "Du désinfectant": {"pos":"n.m. 阳性名词，复数 désinfectants","s":"消毒剂。涂在伤口、擦桌子、洗手都能用。du 是部分冠词，表示「一些」。","ipa":"[de.zɛ̃.fɛk.tɑ̃]","ph":"dé [de]；sin 读 [zɛ̃]（s 在元音间读 [z]）；fec [fɛk]；tant [tɑ̃]。","pi":"désinfectant 中 s 读 [z]；结尾 -ant 读 [ɑ̃]，t 不发音；c 要发 [k]。","et":"dés- + infecter + -ant：「去除感染」。","ex":[["Mets du désinfectant sur la plaie.","在伤口上涂消毒剂。"],["J'ai acheté du désinfectant pour les mains.","我买了洗手消毒液。"]],"co":[["mettre du désinfectant","涂消毒剂"],["un désinfectant pour les mains","手部消毒液"],["désinfecter une plaie","给伤口消毒"]],"sy":[["antiseptique","courant","防腐消毒剂（医学）"],["gel hydroalcoolique","courant","免洗洗手液"]],"fq":"中频，疫情后更常见。","me":"dés-（去除）+ infect：去掉感染。","tr":{"zh":"请给我一些消毒剂。","fr":"Donnez-moi du désinfectant, s'il vous plaît.","alt":"Vous auriez du désinfectant ?","note":"du + 不可数名词。"}},
 "Du sirop": {"pos":"n.m. 阳性名词，复数 sirops","s":"糖浆；药水（sirop pour la toux 止咳糖浆）；糖浆饮料（加水喝的 sirop de menthe 薄荷糖浆）。","ipa":"[si.ʁo]","ph":"s [s]；r [ʁ]；op 读 [o]，结尾 p 不发音。","pi":"结尾 p 不发音；sirop 读 [si.ʁo]，不是 [siʁɔp]。","et":"来自中世纪拉丁语 siropus，源自阿拉伯语 sharāb（饮料）。","ex":[["Prends ce sirop pour la toux.","喝这个止咳糖浆。"],["Je voudrais un sirop de menthe.","我想要一杯薄荷糖浆饮料。"]],"co":[["du sirop pour la toux","止咳糖浆"],["un sirop de grenadine","石榴糖浆"],["sirop d'érable","枫糖浆"]],"sy":[["médicament","courant","药"],["jus","courant","果汁（不是糖浆）"]],"fq":"中频。","me":"sirop 末尾 p 静音，读 [si.ʁo]。","tr":{"zh":"他每晚喝一勺止咳糖浆。","fr":"Il prend une cuillère de sirop chaque soir.","alt":"Chaque soir, il prend une cuillerée de sirop.","note":"prendre du sirop：吃药用 prendre。"}},
 "Du tonus": {"pos":"n.m. 阳性名词，不可数（s 要读）","s":"活力；精神；肌肉张力。avoir du tonus = 精神饱满；donner du tonus = 让人有精神。","ipa":"[tɔ.nys]","ph":"o 读 [ɔ]；n；u [y]；结尾 s 要读 [s]。","pi":"tonus 结尾 s 要发音 [s]；u 读 [y]，不是 [u]。","et":"来自拉丁语 tonus（张力，音调），源自希腊语 tonos。同族：ton（语调）。","ex":[["Ce jus d'orange donne du tonus.","这杯橙汁让人有精神。"],["Elle a beaucoup de tonus le matin.","她早上精力充沛。"]],"co":[["avoir du tonus","精力充沛"],["donner du tonus","让人有精神"],["manquer de tonus","缺乏活力"]],"sy":[["énergie","courant","能量"],["tonicité","soutenu","肌肉张力"],["pêche","familier","精神头"]],"fq":"中频。","me":"tonus 与英语 tone 同源：把身体「调紧」就有精神。","tr":{"zh":"早餐让我整天有精神。","fr":"Le petit-déjeuner me donne du tonus toute la journée.","alt":"Avec un bon petit-déj, j'ai la pêche toute la journée.","note":"donner du tonus à qqn。"}},
 "Le bras": {"pos":"n.m. 阳性名词，复数 bras（同形）","s":"手臂；胳膊。avoir mal au bras = 手臂疼。le bras droit = 右手臂，也指「得力助手」。","ipa":"[bʁa]","ph":"b；r [ʁ]；as 读 [a]，结尾 s 不发音。","pi":"结尾 s 不发音；单复数同形：un bras / des bras。","et":"来自拉丁语 bracchium，源自希腊语。同族：brassard（臂章）。","ex":[["Mon bras est cassé.","我的手臂断了。"],["Elle porte le bébé dans ses bras.","她把宝宝抱在怀里。"]],"co":[["avoir mal au bras","手臂疼"],["dans les bras de qqn","在某人怀里"],["le bras droit","得力助手"],["les bras croisés","双臂交叉"]],"sy":[["main","courant","手（不是手臂）"],["épaule","courant","肩膀"],["membre","soutenu","肢体"]],"fq":"高频，身体部位常用。","me":"bras 末尾 s 静音，像「布拉」。","tr":{"zh":"我的右手臂疼。","fr":"J'ai mal au bras droit.","alt":"Mon bras droit me fait mal.","note":"avoir mal au + 阳性部位。"}},
 "Le cerveau": {"pos":"n.m. 阳性名词，复数 cerveaux","s":"大脑；脑。也比喻聪明人或幕后主谋（le cerveau de l'opération）。","ipa":"[sɛʁ.vo]","ph":"c 在 e 前读 [s]；er 读 [ɛʁ]；eau 读 [o]。","pi":"c 读 [s]；复数 cerveaux（x 不发音），不是 cerveaus。","et":"来自拉丁语 cerebellum（小脑），为 cerebrum 的指小词。","ex":[["Le cerveau est complexe.","大脑很复杂。"],["Il est le cerveau de l'équipe.","他是团队的大脑。"]],"co":[["le cerveau humain","人脑"],["une fuite des cerveaux","人才流失"],["se creuser le cerveau","绞尽脑汁"]],"sy":[["tête","courant","头"],["cervelle","courant","脑髓（也指食物）"],["matière grise","familier","脑力"]],"fq":"中频。","me":"cerveau 像 cerebral（大脑的）：词根相同。","tr":{"zh":"睡眠对大脑很重要。","fr":"Le sommeil est important pour le cerveau.","alt":"Dormir, c'est important pour le cerveau.","note":"复数 cerveaux。"}},
 "Le cou": {"pos":"n.m. 阳性名词，复数 cous","s":"脖子；颈部。avoir mal au cou = 脖子疼。je me suis tordu le cou = 我扭了脖子。","ipa":"[ku]","ph":"c [k]；ou [u]；结尾 u 之后没有其他音。","pi":"cou 是 [ku]，不要和 coup [ku]（一下，打击）混：同音词，靠上下文区分。","et":"来自拉丁语 collum（脖子）。同族：col（衣领）、collier（项链）。","ex":[["Elle a un long cou.","她有一个长脖子。"],["Il a mal au cou ce matin.","他今天早上脖子疼。"]],"co":[["avoir mal au cou","脖子疼"],["un tour de cou","围脖"],["sauter au cou de qqn","扑上去抱住某人"]],"sy":[["nuque","courant","后颈"],["gorge","courant","喉咙"],["col","courant","衣领"]],"fq":"中频，身体部位。","me":"cou ← collum：col、collier 同族，都在「脖子」处。","tr":{"zh":"我脖子很僵。","fr":"J'ai le cou raide.","alt":"J'ai mal au cou, il est tout raide.","note":"cou 与 coup 同音，别写错。"}},
 "Le dos": {"pos":"n.m. 阳性名词，复数 dos（同形）","s":"背；后背。avoir mal au dos = 背疼。au dos de = 在……背面。","ipa":"[do]","ph":"d [d]；os 读 [o]，结尾 s 不发音。","pi":"s 不发音；单复数同形：le dos / les dos。","et":"来自拉丁语 dorsum（背）。同族：dorsal（背部的）、endosser（背负）。","ex":[["Il a mal au dos.","他背疼。"],["Elle porte un sac sur le dos.","她背着一个包。"]],"co":[["avoir mal au dos","背疼"],["sur le dos","在背上"],["de dos","背对着"],["tourner le dos","转身背对"]],"sy":[["épaule","courant","肩膀"],["reins","courant","腰"],["derrière","courant","后面"]],"fq":"高频，身体部位常用。","me":"dos 只读 [do]，s 静音：像「朵」。","tr":{"zh":"我背很疼。","fr":"J'ai très mal au dos.","alt":"Mon dos me fait très mal.","note":"avoir mal au + 阳性部位。"}},
 "Le romarin": {"pos":"n.m. 阳性名词，复数 romarins","s":"迷迭香（香草，做肉、烤土豆很常用）。常说 du romarin（部分冠词）。","ipa":"[ʁɔ.ma.ʁɛ̃]","ph":"r [ʁ]；o [ɔ]；ma [ma]；rin 读 [ʁɛ̃]（in 鼻化）。","pi":"结尾 -in 读 [ɛ̃]，不读 [in]；两个 r 都要发。","et":"来自拉丁语 ros marinus（「海的露水」）。","ex":[["Je cuisine avec du romarin.","我用迷迭香做菜。"],["Le poulet est rôti avec du romarin.","烤鸡里放了迷迭香。"]],"co":[["du romarin frais","新鲜迷迭香"],["poulet au romarin","迷迭香烤鸡"],["une branche de romarin","一枝迷迭香"]],"sy":[["thym","courant","百里香，另一种香草"],["herbes de Provence","courant","普罗旺斯香草"]],"fq":"中频，烹饪用词。","me":"ros marinus = 海的露水：romarin。","tr":{"zh":"我在土豆上放了迷迭香。","fr":"Je mets du romarin sur les pommes de terre.","alt":"J'ajoute du romarin aux pommes de terre.","note":"du romarin：部分冠词。"}},
 "Le rythme cardiaque": {"pos":"n.m. 阳性名词，复数 rythmes cardiaques","s":"心率；心跳节奏。也说 la fréquence cardiaque（更医学）。rythme cardiaque rapide = 心跳快。","ipa":"[ʁitm kaʁ.djak]","ph":"rythme 读 [ʁitm]：y 读 [i]，th 不发音，e 不发音；cardiaque 读 [kaʁ.djak]，qu 读 [k]。","pi":"rythme 里 th 是静音，y 读 [i]；cardiaque 的 -iaque 读 [jak]。","et":"rythme 来自希腊语 rhuthmos；cardiaque 来自希腊语 kardia（心）。同族：cardiologue（心脏科医生）。","ex":[["Son rythme cardiaque est rapide.","他的心率很快。"],["Mon rythme cardiaque s'accélère quand je cours.","我跑步时心率加快。"]],"co":[["un rythme cardiaque rapide / lent","心率快 / 慢"],["mesurer le rythme cardiaque","测心率"],["troubles du rythme cardiaque","心律失常"]],"sy":[["fréquence cardiaque","soutenu","心率（医学）"],["pouls","courant","脉搏"],["battements du cœur","courant","心跳"]],"fq":"中频，健康话题。","me":"rythme（节奏）+ cardiaque（心）：心的节奏。","tr":{"zh":"运动时我的心率会变快。","fr":"Mon rythme cardiaque s'accélère quand je fais du sport.","alt":"Quand je fais du sport, mon cœur bat plus vite.","note":"rythme 是阳性；形容词 cardiaque 阴阳性同形。"}},
 "Le SAMU": {"pos":"n.m. 阳性名词（缩写，也可写 Samu）","s":"急救中心（Service d'aide médicale urgente）。法国拨 15 叫 SAMU，派医生和救护车。le SAMU arrive = 急救人员赶到。","ipa":"[sa.my]","ph":"SAMU 按单词读 [sa.my]，不是逐个字母读；u 读 [y]。","pi":"读成一个词 [sa.my]；u 读 [y]；法国急救电话是 15，欧盟通用是 112。","et":"缩写：Service d'Aide Médicale Urgente。","ex":[["Le SAMU arrive vite.","急救中心很快赶到。"],["Appelez le SAMU, c'est urgent !","打电话叫 SAMU，很紧急！"]],"co":[["appeler le SAMU","叫急救"],["le 15","SAMU 的电话号码"],["l'équipe du SAMU","急救队"]],"sy":[["les pompiers","courant","消防员（电话 18）"],["une ambulance","courant","救护车"],["les urgences","courant","急诊室"]],"fq":"中频，紧急情况。","me":"SAMU 读成「萨缪」，拨 15。","tr":{"zh":"快打电话叫急救！","fr":"Appelez vite le SAMU !","alt":"Vite, appelez le 15 !","note":"祈使句 appelez + le SAMU。"}},
 "Le sommeil": {"pos":"n.m. 阳性名词，不可数","s":"睡眠；睡意。avoir sommeil = 想睡觉；avoir le sommeil léger = 睡得浅。注意 avoir sommeil 前没有冠词。","ipa":"[sɔ.mɛj]","ph":"o 读 [ɔ]；mm 读一个 m；eil 读 [ɛj]。","pi":"-eil 读 [ɛj]，l 不单独读；avoir sommeil 不加 le。","et":"来自拉丁语 somniculus 一系，源自 somnus（睡眠）。同族：somnoler（打瞌睡）、somnifère（安眠药）。","ex":[["Le sommeil est important.","睡眠很重要。"],["J'ai sommeil, je vais me coucher.","我困了，我去睡觉。"]],"co":[["avoir sommeil","想睡觉"],["avoir le sommeil léger / lourd","睡得浅 / 沉"],["manquer de sommeil","睡眠不足"],["un trouble du sommeil","睡眠障碍"]],"sy":[["repos","courant","休息"],["dodo","familier","睡觉（儿语）"],["somme","littéraire","小睡"]],"fq":"高频，日常常用。","me":"sommeil 像 somnolent：som- 都是「睡」。","tr":{"zh":"我睡眠不足。","fr":"Je manque de sommeil.","alt":"Je ne dors pas assez.","note":"manquer de + 名词，不加冠词。"}},
 "Le tabac": {"pos":"n.m. 阳性名词，复数 tabacs","s":"烟草；烟；也指烟草店（le tabac，卖烟、邮票、彩票的店）。le tabac est mauvais pour la santé。","ipa":"[ta.ba]","ph":"ta [ta]；bac 读 [ba]，结尾 c 不发音。","pi":"结尾 c 不发音，不读 [tabak]。","et":"来自西班牙语 tabaco。","ex":[["Le tabac est mauvais pour la santé.","烟草有害健康。"],["Je vais au tabac acheter des timbres.","我去烟草店买邮票。"]],"co":[["fumer du tabac","吸烟"],["un bureau de tabac","烟草店"],["arrêter le tabac","戒烟"]],"sy":[["cigarette","courant","香烟"],["nicotine","courant","尼古丁"]],"fq":"中频。","me":"tabac 末尾 c 静音：像「塔巴」。","tr":{"zh":"我想戒烟。","fr":"Je veux arrêter le tabac.","alt":"Je voudrais arrêter de fumer.","note":"arrêter le tabac / arrêter de fumer。"}},
 "Le thym": {"pos":"n.m. 阳性名词，复数 thyms（少用）","s":"百里香（香草）。du thym = 一些百里香。常和 laurier（月桂）一起煮汤、炖菜。","ipa":"[tɛ̃]","ph":"th 读 [t]；ym 读鼻化音 [ɛ̃]。","pi":"thym 读 [tɛ̃]，y 与 m 合成鼻化音，m 不发音；和 teint、tain 同音。","et":"来自拉丁语 thymum，源自希腊语 thumon。","ex":[["J'aime l'odeur du thym.","我喜欢百里香的味道。"],["Ajoute un peu de thym dans la soupe.","在汤里加一点百里香。"]],"co":[["du thym frais","新鲜百里香"],["thym et laurier","百里香和月桂"],["du thym séché","干百里香"]],"sy":[["romarin","courant","迷迭香"],["laurier","courant","月桂叶"]],"fq":"中频，烹饪用词。","me":"thym 读 [tɛ̃]，和 ten 近似。","tr":{"zh":"我在汤里放了百里香。","fr":"J'ai mis du thym dans la soupe.","alt":"J'ai ajouté du thym à la soupe.","note":"mettre du thym dans…"}},
 "Le ventre": {"pos":"n.m. 阳性名词，复数 ventres","s":"肚子；腹部。avoir mal au ventre = 肚子疼；avoir le ventre plat = 小腹平坦。口语 avoir mal au ventre 最常说。","ipa":"[vɑ̃tʁ]","ph":"v；en 读 [ɑ̃]；tre 读 [tʁ]，结尾 e 不发音。","pi":"en 读 [ɑ̃]；整个词一个音节；和 ventre 近的 vent（风）要区分。","et":"来自拉丁语 venter（肚子）。同族：ventral（腹部的）。","ex":[["J'ai mal au ventre.","我肚子疼。"],["Il a le ventre plein.","他吃饱了。"]],"co":[["avoir mal au ventre","肚子疼"],["ventre plat","平坦的小腹"],["à plat ventre","趴着"],["un mal de ventre","腹痛"]],"sy":[["estomac","courant","胃"],["abdomen","soutenu","腹部（医学）"],["bide","familier","肚腩"]],"fq":"高频，身体部位常用。","me":"ventre 像 ventral：「腹部」。","tr":{"zh":"吃完饭我肚子疼。","fr":"J'ai mal au ventre après le repas.","alt":"Après manger, mon ventre me fait mal.","note":"avoir mal au ventre。"}},
 "Un accident": {"pos":"n.m. 阳性名词，复数 accidents","s":"事故；意外。un accident de voiture = 车祸；par accident = 偶然、不小心。","ipa":"[ak.si.dɑ̃]","ph":"cc 读 [ks]；i [i]；dent 读 [dɑ̃]，nt 的 t 不发音。","pi":"cc 在 i 前读 [ks]，不是 [k]；结尾 -ent 读 [ɑ̃]。","et":"来自拉丁语 accidens（发生的事），源自 accidere（发生）。","ex":[["Il y a eu un accident.","发生了一起事故。"],["Elle a eu un accident de voiture.","她出了车祸。"]],"co":[["un accident de voiture","车祸"],["par accident","偶然地"],["un accident du travail","工伤"],["avoir un accident","出事故"]],"sy":[["incident","courant","小事故"],["catastrophe","courant","灾难"],["hasard","courant","偶然"]],"fq":"高频，新闻和日常常用。","me":"accident 像英语 accident，但 cc 读 [ks]。","tr":{"zh":"路上发生了一起事故。","fr":"Il y a eu un accident sur la route.","alt":"Il y a eu un accident en chemin.","note":"il y a eu：passé composé 的 il y a。"}},
 "Un animal domestique": {"pos":"n.m. 阳性名词，复数 animaux domestiques","s":"宠物；家养动物。口语常简称 un animal 或 un animal de compagnie。domestique 阴阳性同形。","ipa":"[a.ni.mal dɔ.mɛs.tik]","ph":"animal 读 [a.ni.mal]；domestique 读 [dɔ.mɛs.tik]，qu 读 [k]。","pi":"复数 animaux domestiques（animal → animaux）；animal 末尾 l 要读。","et":"animal 来自拉丁语 animal（有生命的）；domestique 来自拉丁语 domesticus，源自 domus（家）。","ex":[["J'ai un animal domestique.","我有一只宠物。"],["Les animaux domestiques sont interdits ici.","这里禁止带宠物。"]],"co":[["un animal de compagnie","宠物（更常用）"],["un animal sauvage","野生动物"],["avoir un animal à la maison","家里养宠物"]],"sy":[["animal de compagnie","courant","宠物（最常用）"],["bête","familier","动物，口语"],["animal sauvage","courant","反义：野生动物"]],"fq":"中频。","me":"domestique ← domus（家）：住在家里的动物。","tr":{"zh":"你有宠物吗？","fr":"Tu as un animal domestique ?","alt":"Tu as un animal de compagnie ?","note":"animal 的复数是 animaux。"}},
 "Un antibiotique": {"pos":"n.m. 阳性名词，复数 antibiotiques","s":"抗生素。常说 prendre des antibiotiques = 吃抗生素。注意：对病毒（感冒、流感）无效。","ipa":"[ɑ̃.ti.bjɔ.tik]","ph":"an 读 [ɑ̃]；ti [ti]；bio 读 [bjɔ]；tique 读 [tik]。","pi":"an 读 [ɑ̃]；io 在这里读 [jɔ]；qu 读 [k]。","et":"anti-（反对）+ biotique（生命的），希腊语 bios（生命）：「对抗生命（细菌）」。","ex":[["Le médecin m'a donné un antibiotique.","医生给我开了抗生素。"],["Je prends des antibiotiques depuis deux jours.","我吃抗生素两天了。"]],"co":[["prendre un antibiotique","吃抗生素"],["une cure d'antibiotiques","抗生素疗程"],["sous antibiotiques","正在服用抗生素"]],"sy":[["médicament","courant","药"],["traitement","courant","治疗"],["antiviral","soutenu","抗病毒药"]],"fq":"中频，就医常用。","me":"anti + bio：对抗「生命」(细菌)。","tr":{"zh":"医生让我吃抗生素。","fr":"Le médecin me prescrit des antibiotiques.","alt":"Le médecin m'a prescrit des antibiotiques.","note":"prescrire à qqn。"}},
 "Un incendie": {"pos":"n.m. 阳性名词，复数 incendies","s":"火灾；大火。un incendie de forêt = 森林火灾。比 feu 更强调破坏性大火。","ipa":"[ɛ̃.sɑ̃.di]","ph":"in 读 [ɛ̃]；c 读 [s]；en 读 [ɑ̃]；die 读 [di]。","pi":"in 和 en 都是鼻化音 [ɛ̃] [ɑ̃]，别读成 [in] [ɛn]；c 读 [s]。","et":"来自拉丁语 incendium，源自 incendere（点燃）。","ex":[["Un incendie a détruit la maison.","一场火灾毁了房子。"],["Les pompiers éteignent l'incendie.","消防员扑灭大火。"]],"co":[["un incendie de forêt","森林火灾"],["éteindre un incendie","扑灭火灾"],["un début d'incendie","起火"],["déclarer un incendie","发生火灾"]],"sy":[["feu","courant","火"],["sinistre","soutenu","灾祸"],["flammes","courant","火焰"]],"fq":"中频，新闻常见。","me":"in-cend：英语 incense（燃烧）同源，「点着」。","tr":{"zh":"森林里发生了大火。","fr":"Un grand incendie a eu lieu dans la forêt.","alt":"Il y a eu un énorme incendie dans la forêt.","note":"avoir lieu = 发生。"}},
 "Un malaise": {"pos":"n.m. 阳性名词，复数 malaises","s":"不适；头晕；昏厥。faire un malaise = 突然不舒服甚至昏倒。也可指「不自在、尴尬气氛」（un malaise dans le groupe）。","ipa":"[ma.lɛz]","ph":"ma [ma]；laise 读 [lɛz]，ai 读 [ɛ]，s 读 [z]。","pi":"s 读 [z]；ai 读 [ɛ]；不是「悲伤」（那是 tristesse）。","et":"mal（坏）+ aise（舒适）：「不舒服」。","ex":[["Il a fait un malaise.","他突然昏倒了。"],["Elle a ressenti un malaise dans le train.","她在火车上觉得不舒服。"]],"co":[["faire un malaise","昏倒、突然不适"],["ressentir un malaise","感到不适"],["un malaise général","普遍的不安"]],"sy":[["évanouissement","courant","昏厥"],["étourdissement","courant","头晕"],["gêne","courant","尴尬"]],"fq":"中频，就医、新闻常见。","me":"mal + aise：不舒服。","tr":{"zh":"他在街上突然昏倒了。","fr":"Il a fait un malaise dans la rue.","alt":"Il s'est évanoui dans la rue.","note":"faire un malaise 是固定搭配。"}},
 "Un masque de nuit": {"pos":"n.m. 阳性名词，复数 masques de nuit","s":"眼罩（睡觉用）。也说 un masque de sommeil。飞机、旅行常用。","ipa":"[mask də nɥi]","ph":"masque 读 [mask]；de 弱读 [də]；nuit 读 [nɥi]（u 与 i 连读）。","pi":"qu 读 [k]；nuit 的 u 读 [ɥ]，快速滑到 i；t 不发音。","et":"masque 经意大利语 maschera，来源可能为阿拉伯语；这里仅以「masque + de + nuit」构成词组。","ex":[["Ils distribuent des masques de nuit dans l'avion.","飞机上发眼罩。"],["Je dors avec un masque de nuit.","我戴着眼罩睡觉。"]],"co":[["mettre un masque de nuit","戴眼罩"],["un masque de sommeil","眼罩"],["des bouchons d'oreilles","耳塞"]],"sy":[["masque de sommeil","courant","眼罩"],["bandeau","courant","头带、眼罩"]],"fq":"中频，旅行常用。","me":"masque 遮住 + 夜 nuit = 夜晚用的面罩。","tr":{"zh":"我睡觉时戴眼罩。","fr":"Je dors avec un masque de nuit.","alt":"Je mets un masque de nuit pour dormir.","note":"avec + 名词，表示戴着。"}},
 "Un médecin généraliste": {"pos":"n.m. 阳性名词，复数 médecins généralistes","s":"全科医生。médecin 常用阳性，女医生也常说 une médecin；généraliste 阴阳性同形。常简称 un généraliste。","ipa":"[med.sɛ̃ ʒe.ne.ʁa.list]","ph":"médecin 读 [med.sɛ̃]；généraliste 读 [ʒe.ne.ʁa.list]；g 读 [ʒ]。","pi":"médecin 结尾 -cin 读 [sɛ̃]，不是 [kin]；généraliste 的 g 读 [ʒ]。","et":"médecin 来自拉丁语 medicus（医生）；généraliste 来自 général（一般的）+ -iste。","ex":[["Je vais voir mon médecin généraliste.","我去看全科医生。"],["Un généraliste soigne les maladies courantes.","全科医生治疗常见病。"]],"co":[["consulter un médecin généraliste","看全科医生"],["prendre rendez-vous chez le généraliste","预约全科医生"],["un médecin spécialiste","专科医生"]],"sy":[["généraliste","courant","全科医生（简称）"],["docteur","courant","医生（称呼）"],["spécialiste","courant","反义：专科医生"]],"fq":"中频，就医常用。","me":"généraliste = 通才医生：什么都看一点。","tr":{"zh":"我先去看全科医生。","fr":"Je vais d'abord voir mon médecin généraliste.","alt":"Je consulte d'abord mon généraliste.","note":"voir un médecin = 看医生。"}},
 "Un médecin traitant": {"pos":"n.m. 阳性名词，复数 médecins traitants","s":"家庭医生；指定医生（法国医保要求每人登记一位固定医生）。负责日常诊疗并转诊专科。","ipa":"[med.sɛ̃ tʁɛ.tɑ̃]","ph":"médecin 读 [med.sɛ̃]；traitant 读 [tʁɛ.tɑ̃]，ai 读 [ɛ]，结尾 t 不发音。","pi":"traitant 是 -ant，读 [ɑ̃]；ai 读 [ɛ]。","et":"traitant 是 traiter（治疗）的现在分词，用作形容词：「负责治疗的」。","ex":[["Mon médecin traitant est en vacances.","我的家庭医生在度假。"],["Il faut déclarer un médecin traitant.","要登记一位指定医生。"]],"co":[["déclarer un médecin traitant","登记指定医生"],["voir son médecin traitant","看家庭医生"],["changer de médecin traitant","换家庭医生"]],"sy":[["généraliste","courant","全科医生"],["médecin de famille","courant","家庭医生"],["spécialiste","courant","专科医生"]],"fq":"中频，法国医保常用。","me":"traitant ← traiter：负责「治疗」你的人。","tr":{"zh":"我要预约家庭医生。","fr":"Je veux prendre rendez-vous avec mon médecin traitant.","alt":"Je voudrais un rendez-vous avec mon médecin traitant.","note":"prendre rendez-vous avec/chez。"}},
 "Un muscle": {"pos":"n.m. 阳性名词，复数 muscles","s":"肌肉。avoir mal aux muscles = 肌肉酸痛；se faire un muscle = 拉伤肌肉（口语）。形容词 musclé = 肌肉发达的。","ipa":"[myskl]","ph":"mu 读 [my]；scle 读 [skl]，结尾 e 不发音。","pi":"u 读 [y]；sc 读 [sk]，muscle 只有两个音节 [myskl]。","et":"来自拉丁语 musculus（小老鼠），因肌肉收缩像小老鼠在皮下跑。","ex":[["Ce muscle est fort.","这块肌肉很强。"],["J'ai mal aux muscles après le sport.","运动后我肌肉酸痛。"]],"co":[["avoir mal aux muscles","肌肉酸痛"],["se faire un muscle","拉伤肌肉"],["muscler son corps","锻炼肌肉"],["un muscle du bras","手臂肌肉"]],"sy":[["biceps","courant","肱二头肌"],["tendon","courant","肌腱"],["force","courant","力量"]],"fq":"中频，运动和健康话题。","me":"musculus = 小老鼠：muscle。","tr":{"zh":"跑步后我的腿部肌肉很酸。","fr":"J'ai mal aux muscles des jambes après la course.","alt":"Mes jambes sont courbaturées après la course.","note":"avoir mal aux + 复数部位。"}},
 "Un oreiller": {"pos":"n.m. 阳性名词，复数 oreillers","s":"枕头。dormir sans oreiller = 不用枕头睡。oreiller 与 oreille（耳朵）同源，因为头靠着它，耳朵贴着它。","ipa":"[ɔ.ʁɛ.je]","ph":"o 读 [ɔ]；r [ʁ]；ei 读 [ɛ]；ll 读 [j]；结尾 er 读 [e]。","pi":"ill 读 [j]：oreiller 是 [ɔ.ʁɛ.je]；结尾 -er 的 r 不发音。","et":"来自 oreille（耳朵）+ -ier；oreille 拉丁语 auricula。","ex":[["J'ai un nouvel oreiller.","我有一个新枕头。"],["Il dort avec deux oreillers.","他睡觉用两个枕头。"]],"co":[["un oreiller moelleux","柔软的枕头"],["une taie d'oreiller","枕套"],["se battre à coups d'oreillers","打枕头仗"]],"sy":[["coussin","courant","靠垫"],["traversin","courant","长枕"],["polochon","familier","长枕、枕头"]],"fq":"中频，生活常用。","me":"oreiller ← oreille：靠着耳朵的东西。","tr":{"zh":"我需要一个软一点的枕头。","fr":"J'ai besoin d'un oreiller plus doux.","alt":"Il me faut un oreiller plus moelleux.","note":"avoir besoin de + 名词。"}},
 "Un produit": {"pos":"n.m. 阳性名词，复数 produits","s":"产品；商品。也指「成分、制剂」，如 un produit de beauté（化妆品）、un produit chimique（化学品）。","ipa":"[pʁɔ.dɥi]","ph":"pr 中的 r 是小舌音 [ʁ]；ui 读 [ɥi]，嘴唇先圆后展；结尾 t 不发音。","pi":"结尾 t 不发音；ui 不是「乌-衣」两个音，要连成一个滑音。","et":"来自拉丁语 producere（向前带出、生产）的过去分词 productum。同源：produire（生产）、production。","ex":[["C'est un nouveau produit.","这是一个新产品。"],["Ce produit est très bon pour la peau.","这个产品对皮肤很好。"],["Les produits de nettoyage sont sous l'évier.","清洁用品在水槽下面。"]],"co":[["un produit frais / local","新鲜 / 本地产品"],["un produit de beauté","化妆品"],["les produits laitiers","乳制品"],["un produit d'entretien","清洁用品"]],"sy":[["article","courant","商品，强调买卖的单件东西"],["marchandise","soutenu","货物，较正式"]],"fq":"高频，日常和购物常用。","me":"pro-（向前）+ duit（带）：被「带出来」的东西就是产品。","tr":{"zh":"我想买这个产品。","fr":"Je voudrais acheter ce produit.","alt":"Je veux prendre ce produit.","note":"produit 的 t 不发音；vouloir 的条件式 je voudrais 更礼貌。"}},
 "Un remboursement": {"pos":"n.m. 阳性名词，复数 remboursements","s":"退款；报销；偿还。买东西退钱、看病后医保退回费用、还债都可以用。动词是 rembourser。","ipa":"[ʁɑ̃.buʁ.sə.mɑ̃]","ph":"rem- 读鼻化元音 [ɑ̃]；bour [buʁ]；-se- 中的 e 轻读；-ment 读 [mɑ̃]。","pi":"-ment 结尾读 [mɑ̃]，t 不发；rem- 的 m 不单独发音，只让元音鼻化。","et":"由动词 rembourser（re- + 古法语 embourser，「把钱放回钱袋」，来自 bourse 钱袋）加后缀 -ment 构成。","ex":[["J'attends un remboursement.","我在等退款。"],["Je demande le remboursement de mon billet.","我申请退我的票款。"],["La Sécu paie une partie du remboursement.","社保支付报销的一部分。"]],"co":[["demander un remboursement","申请退款"],["un remboursement intégral","全额退款"],["le remboursement des soins","医疗费用报销"],["en attente de remboursement","等待退款"]],"sy":[["restitution","soutenu","归还（物品、钱）"],["avoir","courant","购物抵用券，不是现金退款"]],"fq":"中高频，购物、医疗常见。","me":"re-（回）+ bourse（钱袋）：钱回到钱袋里。","tr":{"zh":"我还没收到退款。","fr":"Je n'ai pas encore reçu mon remboursement.","alt":"Je n'ai toujours pas été remboursé.","note":"ne… pas encore 表示「还没」，复合过去时用 avoir。"}},
 "Un rêve": {"pos":"n.m. 阳性名词，复数 rêves","s":"梦；梦想。睡觉时的梦用 faire un rêve，愿望、理想也叫 un rêve。动词是 rêver（做梦；梦想）。","ipa":"[ʁɛv]","ph":"r 是小舌音 [ʁ]；ê 读开口 [ɛ]；v 读 [v]，结尾的 e 不发音。","pi":"ê 读 [ɛ]，不是 [e]；r 要发小舌音，别发成中文的「r」。","et":"来源不确定（古法语 resver「游荡、胡思乱想」，进一步来源有争议）。同源词：rêver、rêverie。","ex":[["J'ai fait un beau rêve.","我做了一个美梦。"],["Mon rêve, c'est de voyager en Italie.","我的梦想是去意大利旅行。"],["C'est un rêve devenu réalité.","这是梦想成真。"]],"co":[["faire un rêve","做梦"],["faire de beaux rêves","做个好梦"],["un rêve d'enfant","儿时的梦想"],["en rêve","在梦中"]],"sy":[["cauchemar","courant","噩梦，反义"],["songe","littéraire","梦，文学用词"],["désir","courant","愿望"]],"fq":"高频，日常常用。","me":"rêve 带帽子 ê，像一朵睡梦中的云。","tr":{"zh":"昨晚我做了一个奇怪的梦。","fr":"Cette nuit, j'ai fait un rêve bizarre.","alt":"J'ai fait un drôle de rêve hier soir.","note":"梦用 faire un rêve，不用 avoir。"}},
 "Un rhume": {"pos":"n.m. 阳性名词，复数 rhumes","s":"感冒（轻微的，鼻塞流涕）。普通感冒说 un rhume；流感是 la grippe，发烧更重。","ipa":"[ʁym]","ph":"rh 中 h 不发音，只读 [ʁ]；u 读 [y]，嘴唇圆起；m 读出来。","pi":"rh 的 h 是哑音；u 是 [y]，不是「乌」。拼写别漏 h。","et":"来自拉丁语 rheuma（流体，鼻涕），源于希腊语 rheuma「流」。同源：rhumatisme。","ex":[["J'ai attrapé un rhume.","我感冒了。"],["Elle a un gros rhume.","她重感冒了。"],["Je prends du sirop pour mon rhume.","我吃糖浆治感冒。"]],"co":[["attraper un rhume","得感冒"],["avoir un rhume","感冒了"],["un rhume des foins","花粉症"],["être enrhumé","感冒了（形容词）"]],"sy":[["grippe","courant","流感，比 rhume 重"],["refroidissement","soutenu","着凉、受寒"]],"fq":"中高频，生病话题必学。","me":"rhume 以 rh 开头：鼻子「流」(希腊语 rheuma) 出水。","tr":{"zh":"我感冒了，不想出门。","fr":"J'ai un rhume, je ne veux pas sortir.","alt":"Je suis enrhumé, je reste à la maison.","note":"说「感冒」用 avoir un rhume 或 être enrhumé。"}},
 "Un sondage": {"pos":"n.m. 阳性名词，复数 sondages","s":"民意调查；抽样调查。也指「探测、钻探」。常见 un sondage d'opinion（民意调查）。","ipa":"[sɔ̃.daʒ]","ph":"son 读鼻化元音 [ɔ̃]；d [d]；age 读 [aʒ]，g 在 a 后读 [ʒ]。","pi":"-age 读 [aʒ]，结尾 e 不发音；son 的 n 不单独发音。","et":"来自动词 sonder（探测）加后缀 -age。sonder 的更早来源不确定。","ex":[["Je réponds à un sondage.","我在回答一份调查。"],["Selon un sondage, 60 % des Français aiment le café.","据一项调查，60% 的法国人爱喝咖啡。"],["On fait un sondage dans la rue.","我们在街上做调查。"]],"co":[["selon un sondage","根据一项调查"],["faire un sondage","做调查"],["répondre à un sondage","回答调查"],["un sondage d'opinion","民意调查"]],"sy":[["enquête","courant","调查，范围更广，也指警方调查"],["étude","courant","研究"]],"fq":"中频，新闻里常见。","me":"sonder（探）+ -age：用问题去「探」大家的想法。","tr":{"zh":"这个调查很有意思。","fr":"Ce sondage est très intéressant.","alt":"Ce sondage est vraiment intéressant.","note":"sondage 是阳性，用 ce。"}},
 "Un témoin": {"pos":"n.m. 阳性名词，复数 témoins（男女同形，女证人也说 un témoin）","s":"证人；目击者。也指「见证、证明」，如婚礼上的 témoin（证婚人）；还有「指示灯」，如 un témoin lumineux（仪表盘指示灯）。","ipa":"[te.mwɛ̃]","ph":"té [te]；oi 读 [wa]，但这里 oin 读 [wɛ̃]；结尾鼻化。","pi":"oin 读 [wɛ̃]，不是 [wa-n]；n 不单独发音。女证人也用阳性 un témoin。","et":"来自拉丁语 testimonium（证据，证词）。同源：témoigner（作证）、témoignage。","ex":[["La police cherche un témoin.","警方在找证人。"],["Elle était témoin de l'accident.","她是事故的目击者。"],["Il a été témoin à leur mariage.","他是他们婚礼的证婚人。"]],"co":[["un témoin oculaire","目击证人"],["appeler un témoin","传唤证人"],["être témoin de","目睹……"],["un témoin lumineux","指示灯"]],"sy":[["spectateur","courant","观众，不一定要作证"],["observateur","soutenu","观察者"]],"fq":"中频，新闻和日常均有。","me":"témoin 里有 moi：证人说「我看到了」。","tr":{"zh":"我是这起事故的目击者。","fr":"Je suis témoin de cet accident.","alt":"J'ai vu l'accident, je suis témoin.","note":"témoin 不分阴阳，女性也说 un témoin。"}},
 "Un vol": {"pos":"n.m. 阳性名词，复数 vols","s":"两个常用意思：1) 盗窃；2) 飞行；航班。看上下文判断：un vol de portable（手机被偷），un vol Paris-Rome（巴黎到罗马的航班）。","ipa":"[vɔl]","ph":"v [v]；o 读开口 [ɔ]；l 要读出来。","pi":"结尾 l 发音；两个意思拼写相同，要靠上下文区分。","et":"「飞行」义来自动词 voler（拉丁语 volare，飞）；「盗窃」义一般认为源自猎鹰术语，说法不完全确定。","ex":[["J'ai déclaré un vol.","我报了失窃。"],["Mon vol part à huit heures.","我的航班八点起飞。"],["Il y a eu un vol dans l'immeuble.","这栋楼发生了盗窃。"]],"co":[["un vol à l'arraché","抢夺（抢包）"],["un vol direct","直飞航班"],["porter plainte pour vol","因盗窃报案"],["un vol retardé / annulé","航班延误 / 取消"]],"sy":[["cambriolage","courant","入室盗窃"],["larcin","littéraire","小偷小摸"]],"fq":"极高频，旅行和安全话题都用。","me":"vol 一个词：鸟「飞」走了，钱包也「飞」走了。","tr":{"zh":"我的航班被取消了。","fr":"Mon vol a été annulé.","alt":"On a annulé mon vol.","note":"被动态 être + 过去分词；on a annulé 是口语替代。"}},
 "De l'anxiété": {"pos":"n.f. 阴性名词，复数 anxiétés（常不可数，前面用 de l'）","s":"焦虑；不安。可指心理疾病，也指一般的紧张。形容词是 anxieux / anxieuse。","ipa":"[ɑ̃k.sje.te]","ph":"an 读鼻化 [ɑ̃]；x 读 [ks]；ié 读 [je]；结尾 é [e]。","pi":"x 读 [ks]，不要漏掉 k；an 的 n 不单独发音；é 在结尾读 [e]。","et":"来自拉丁语 anxietas（忧虑），源于 anxius（忧心的）。同源：anxieux。","ex":[["Il souffre d'anxiété.","他患有焦虑症。"],["J'ai de l'anxiété avant les examens.","考试前我会焦虑。"],["Elle prend des médicaments contre l'anxiété.","她吃抗焦虑的药。"]],"co":[["souffrir d'anxiété","受焦虑之苦"],["une crise d'anxiété","焦虑发作"],["avoir de l'anxiété","感到焦虑"],["calmer l'anxiété","缓解焦虑"]],"sy":[["angoisse","courant","更强烈的焦虑，带恐惧"],["stress","courant","压力、紧张，更口语"],["inquiétude","courant","担心，较轻"]],"fq":"中频，健康话题常见。","me":"anxiété ≈ anxiety：x 读 [ks]，像英文一样。","tr":{"zh":"她对考试感到焦虑。","fr":"Elle ressent de l'anxiété avant l'examen.","alt":"Elle est anxieuse à cause de l'examen.","note":"不可数用部分冠词 de l'；形容词 anxieuse 是阴性。"}},
 "De la fièvre": {"pos":"n.f. 阴性名词，复数 fièvres（常不可数，前面用 de la）","s":"发烧；发热。说「发烧了」用 avoir de la fièvre；量体温是 la température。高烧 une forte fièvre。","ipa":"[fjɛvʁ]","ph":"fi 读 [fj]；è 读 [ɛ]；vre 读 [vʁ]，结尾的 e 几乎不发音。","pi":"ièvre 只有一个音节；è 是开口 [ɛ]；结尾 e 不发音。","et":"来自拉丁语 febris（发热）。同源：fébrile（发热的）。","ex":[["L'enfant a de la fièvre.","孩子发烧了。"],["Tu as de la fièvre ? Tu es chaud.","你发烧了吗？你很烫。"],["La fièvre est tombée ce matin.","今早烧退了。"]],"co":[["avoir de la fièvre","发烧"],["une forte fièvre","高烧"],["faire de la fièvre","发烧（口语）"],["baisser la fièvre","退烧"]],"sy":[["température","courant","体温；avoir de la température 也表示发烧"],["fébrilité","soutenu","发热状态；也指焦躁"]],"fq":"高频，看病必学。","me":"fièvre 与 febris 同源，像「发热」的 fébrile。","tr":{"zh":"我女儿昨晚发烧了。","fr":"Ma fille a eu de la fièvre cette nuit.","alt":"Ma fille a fait de la fièvre cette nuit.","note":"发烧用 avoir de la fièvre，不要说 avoir une fièvre。"}},
 "De la toux": {"pos":"n.f. 阴性名词，只有单数形式 toux（复数同形）","s":"咳嗽。动词是 tousser。说「咳嗽」常用 avoir de la toux 或 avoir la toux；一阵咳嗽用 une quinte de toux。","ipa":"[tu]","ph":"只读 [tu]；ou [u]；结尾 x 不发音。","pi":"结尾 x 不发音；toux 不读 [tuks]；和 tout [tu] 同音。","et":"来自拉丁语 tussis（咳嗽）。同源：tousser、antitussif。","ex":[["Il a beaucoup de toux.","他咳得很厉害。"],["J'ai une toux sèche depuis hier.","我从昨天起干咳。"],["Ce sirop calme la toux.","这个糖浆止咳。"]],"co":[["une toux sèche / grasse","干咳 / 有痰的咳"],["un sirop contre la toux","止咳糖浆"],["une quinte de toux","一阵咳嗽"],["avoir une toux persistante","咳嗽不止"]],"sy":[["tousser","courant","动词，咳嗽"],["rhume","courant","感冒，常伴咳嗽"]],"fq":"中频，生病时常用。","me":"toux 和 tout 同音 [tu]，一个字母 x 不发音。","tr":{"zh":"我咳嗽已经三天了。","fr":"J'ai de la toux depuis trois jours.","alt":"Ça fait trois jours que je tousse.","note":"depuis + 时间段，表示「从……起至今」。"}},
 "La carte vitale": {"pos":"n.f. 阴性名词，复数 cartes vitales","s":"法国医保卡（绿色芯片卡），看病、买药时出示，用来报销医疗费用。vitale 是形容词，意为「生命攸关的」。","ipa":"[kaʁt vi.tal]","ph":"carte 中 r 读 [ʁ]，t 读出，结尾 e 不发音；vitale 读 [vi.tal]，a 开口。","pi":"carte 的 t 要读；vitale 重音在最后一个发音音节 [tal]。","et":"carte 来自拉丁语 charta（纸）；vital 来自拉丁语 vitalis，源于 vita（生命）。","ex":[["N'oubliez pas votre carte vitale.","别忘了带医保卡。"],["Je présente ma carte vitale au médecin.","我向医生出示医保卡。"],["J'ai perdu ma carte vitale.","我把医保卡丢了。"]],"co":[["présenter sa carte vitale","出示医保卡"],["renouveler la carte vitale","更新医保卡"],["perdre sa carte vitale","丢失医保卡"]],"sy":[["carte de sécurité sociale","courant","社保卡，更泛指"],["mutuelle","courant","补充保险，不是同一张卡"]],"fq":"中频，在法国就医必用。","me":"vitale ← vie：关系到「生命」的卡。","tr":{"zh":"请出示您的医保卡。","fr":"Présentez votre carte vitale, s'il vous plaît.","alt":"Votre carte vitale, s'il vous plaît.","note":"祈使句 présentez 用 vous 形式，礼貌。"}},
 "La colonne vertébrale": {"pos":"n.f. 阴性名词，复数 colonnes vertébrales","s":"脊柱；脊椎。字面是「椎骨组成的柱子」。日常说背痛常用 avoir mal au dos；医学上才说 colonne vertébrale。也比喻「支柱、骨干」。","ipa":"[kɔ.lɔn vɛʁ.te.bʁal]","ph":"colonne 的 nn 前读 [lɔn]，n 要读出来；vertébrale 读 [vɛʁ.te.bʁal]。","pi":"colonne 里的 n 要发音，不是鼻化；vertébrale 是形容词，要配阴性 -e。","et":"colonne 来自拉丁语 columna（柱）；vertébral 来自拉丁语 vertebra（椎骨），源于 vertere（转动）。","ex":[["Il a mal à la colonne vertébrale.","他脊柱疼。"],["Le médecin examine ma colonne vertébrale.","医生检查我的脊柱。"],["Elle fait du yoga pour sa colonne vertébrale.","她做瑜伽保护脊柱。"]],"co":[["avoir mal à la colonne vertébrale","脊柱疼"],["une lésion de la colonne vertébrale","脊柱损伤"],["la colonne vertébrale d'un projet","项目的支柱"]],"sy":[["dos","courant","背部，日常更常说"],["épine dorsale","soutenu","脊梁，也有「支柱」的意思"]],"fq":"低中频，医学话题用。","me":"colonne（柱子）+ vertèbre（椎骨）：身体里的一根柱子。","tr":{"zh":"医生说我的脊柱有问题。","fr":"Le médecin dit que j'ai un problème à la colonne vertébrale.","alt":"Le médecin dit que ma colonne vertébrale a un problème.","note":"mal à + 部位；这里是 problème à。"}},
 "La digestion": {"pos":"n.f. 阴性名词，复数 digestions","s":"消化。动词是 digérer。常说 avoir une bonne / mauvaise digestion（消化好 / 不好）。","ipa":"[di.ʒɛs.tjɔ̃]","ph":"di [di]；g 在 e/i 前读 [ʒ]；-stion 读 [stjɔ̃]。","pi":"g 读 [ʒ]，不是 [g]；-tion 这里读 [tjɔ̃]，因为前面有 s，不读 [sjɔ̃]。","et":"来自拉丁语 digestio，源于 digerere（分开、分解）。同源：digérer、indigestion。","ex":[["La digestion est difficile.","消化很困难。"],["J'ai une bonne digestion.","我消化很好。"],["Le thé aide la digestion.","茶有助于消化。"]],"co":[["une bonne / mauvaise digestion","消化好 / 不好"],["aider la digestion","助消化"],["des problèmes de digestion","消化问题"],["un trouble digestif","消化障碍"]],"sy":[["transit","courant","肠道运转，更口语"],["indigestion","courant","消化不良，一次性的"]],"fq":"中频，健康和饮食话题常见。","me":"di- 分开 + gerere 带：把食物「分开」处理。","tr":{"zh":"饭后喝茶有助于消化。","fr":"Un thé après le repas aide la digestion.","alt":"Un thé après manger, ça aide à digérer.","note":"aider + 名词，或 aider à + 动词原形。"}},
 "La gorge": {"pos":"n.f. 阴性名词，复数 gorges","s":"喉咙；嗓子。avoir mal à la gorge = 喉咙痛。也指「峡谷」，如 les gorges du Verdon。","ipa":"[ɡɔʁʒ]","ph":"g 在 o 前读 [g]；o 开口 [ɔ]；r [ʁ]；ge 读 [ʒ]。","pi":"首个 g 读 [g]，末尾 ge 读 [ʒ]，同一个词两个音；o 是 [ɔ]。","et":"来自晚期拉丁语 gurga（喉咙，漩涡）。同源：gorgée（一口）、engorger。","ex":[["J'ai mal à la gorge.","我喉咙痛。"],["Il a la gorge sèche.","他嗓子干。"],["Elle s'éclaircit la gorge avant de parler.","她清了清嗓子再说话。"]],"co":[["avoir mal à la gorge","喉咙痛"],["avoir la gorge serrée","喉头发紧"],["se racler la gorge","清嗓子"],["des pastilles pour la gorge","喉糖"]],"sy":[["gosier","soutenu","咽喉，较文雅"],["cou","courant","脖子，外部"]],"fq":"高频，看病常用。","me":"gorge 的两个 g 读音不同：g-o-r-ge → [ɡ] … [ʒ]。","tr":{"zh":"我喉咙痛，不能说话。","fr":"J'ai mal à la gorge, je ne peux pas parler.","alt":"J'ai la gorge qui me fait mal, je ne peux pas parler.","note":"avoir mal à + 定冠词 + 部位。"}},
 "La lavande": {"pos":"n.f. 阴性名词，复数 lavandes","s":"薰衣草；薰衣草香。法国普罗旺斯的象征，常用于香包、精油、蜂蜜。也可指淡紫色 (bleu lavande)。","ipa":"[la.vɑ̃d]","ph":"la [la]；van 读鼻化 [vɑ̃]；d 读 [d]，e 不发音。","pi":"an 是鼻化元音 [ɑ̃]；结尾 d 发音，因为后面有 e。","et":"来自意大利语 lavanda，源于拉丁语 lavare（洗），因为用来给洗涤品增香。","ex":[["La lavande sent très bon.","薰衣草很香。"],["Les champs de lavande sont magnifiques en été.","夏天的薰衣草田很美。"],["Je mets un sachet de lavande dans l'armoire.","我在衣柜里放一个薰衣草香包。"]],"co":[["un champ de lavande","薰衣草田"],["l'huile essentielle de lavande","薰衣草精油"],["le miel de lavande","薰衣草蜂蜜"],["un sachet de lavande","薰衣草香包"]],"sy":[["lavandin","courant","杂交薰衣草，更常见于商品"],["violet","courant","紫色，颜色词"]],"fq":"中频，旅游和生活话题。","me":"lavande ← laver：洗过的衣服闻起来是薰衣草味。","tr":{"zh":"普罗旺斯的薰衣草很有名。","fr":"La lavande de Provence est très célèbre.","alt":"La lavande de Provence, tout le monde la connaît.","note":"la lavande 是阴性。"}},
 "La médecine": {"pos":"n.f. 阴性名词，复数 médecines（多为单数）","s":"医学；医术。étudier la médecine = 学医。注意：médecin 是「医生」(人)，médicament 是「药」。","ipa":"[med.sin]","ph":"mé [me]；d [d]；ci 读 [si]，c 在 i 前读 [s]；结尾 e 不发音。","pi":"médecine 读 [med.sin]，不是 [me.də.sin]；médecin（医生）读 [med.sɛ̃]，别混。","et":"来自拉丁语 medicina，源于 medicus（医生）。同源：médecin、médical、médicament。","ex":[["Il étudie la médecine.","他学医。"],["Elle fait des études de médecine.","她在读医学。"],["La médecine a beaucoup progressé.","医学进步很大。"]],"co":[["faire des études de médecine","读医学"],["la médecine générale","全科医学"],["la médecine douce","自然疗法"],["la médecine du travail","职业健康医学"]],"sy":[["médecin","courant","医生，指人，别混"],["médicament","courant","药，别混"]],"fq":"中频，学习和健康话题。","me":"médecine（学科）/ médecin（人）/ médicament（药），三个词同一个根。","tr":{"zh":"我的哥哥在学医。","fr":"Mon frère étudie la médecine.","alt":"Mon frère fait médecine.","note":"faire médecine 是口语，意为「读医学系」。"}},
 "La peau": {"pos":"n.f. 阴性名词，复数 peaux","s":"皮肤；皮；水果的皮。ma peau est sèche（皮肤干），la peau d'une banane（香蕉皮）。","ipa":"[po]","ph":"只读 [po]；eau 读 [o]，结尾不发 u。","pi":"eau 三个字母读一个 [o]；复数 peaux，x 不发音。","et":"来自拉丁语 pellis（兽皮，皮肤）。同源：pelage（毛皮）、pelure（果皮）。","ex":[["Ma peau est sèche.","我的皮肤很干。"],["Il a la peau claire.","他皮肤白。"],["J'ai la peau qui gratte.","我皮肤发痒。"]],"co":[["avoir la peau sèche / grasse","皮肤干 / 油"],["une peau sensible","敏感肌"],["les soins de la peau","护肤"],["avoir la peau douce","皮肤光滑"]],"sy":[["épiderme","soutenu","表皮，医学用词"],["cuir","courant","皮革；cuir chevelu 是头皮"]],"fq":"高频，美容和健康话题常用。","me":"peau 与 po 同音；一个 [o] 就是全部。","tr":{"zh":"冬天我的皮肤很干。","fr":"En hiver, ma peau est très sèche.","alt":"L'hiver, j'ai la peau très sèche.","note":"avoir la peau + 形容词，说皮肤状态。"}},
 "La poitrine": {"pos":"n.f. 阴性名词，复数 poitrines","s":"胸部；胸口。可指整个胸腔（有心脏、肺的位置），也可指女性胸部。看病时说 j'ai mal à la poitrine（胸口疼）。","ipa":"[pwa.tʁin]","ph":"oi 读 [wa]；tr 读 [tʁ]；ine 读 [in]，结尾 e 不发音。","pi":"oi 读 [wa]，不是「奥伊」；ine 的 n 要读出来。","et":"来自拉丁语 pectorina，源于 pectus（胸）。同源：pectoraux（胸肌）。","ex":[["Il a une douleur à la poitrine.","他胸口疼。"],["Elle a de la toux et mal à la poitrine.","她咳嗽，胸口也疼。"],["Je respire mal, j'ai la poitrine serrée.","我呼吸困难，胸口发紧。"]],"co":[["avoir mal à la poitrine","胸口疼"],["la poitrine serrée","胸闷"],["une douleur à la poitrine","胸痛"],["la tour de poitrine","胸围"]],"sy":[["torse","courant","躯干上半部，男性常用"],["thorax","soutenu","胸腔，医学用词"],["sein","courant","乳房，别混"]],"fq":"中频，看病常用。","me":"poitrine 与 pectus（胸）同源：想想 pectoraux（胸肌）。","tr":{"zh":"我胸口疼，需要看医生。","fr":"J'ai mal à la poitrine, je dois voir un médecin.","alt":"J'ai une douleur à la poitrine, il faut que je consulte.","note":"devoir + 动词原形 = 必须。"}},
 "La respiration": {"pos":"n.f. 阴性名词，复数 respirations","s":"呼吸。动词是 respirer。可以说 une respiration calme / difficile。","ipa":"[ʁɛs.pi.ʁa.sjɔ̃]","ph":"res 读 [ʁɛs]；pi [pi]；ra [ʁa]；-tion 读 [sjɔ̃]，鼻化。","pi":"-tion 读 [sjɔ̃]；两个 r 都是小舌音 [ʁ]；重音在最后一个音节。","et":"来自拉丁语 respiratio，源于 respirare（再呼吸）。同源：respirer、respiratoire。","ex":[["Sa respiration est calme.","他的呼吸很平静。"],["J'ai une respiration difficile.","我呼吸困难。"],["Retiens ta respiration.","屏住呼吸。"]],"co":[["retenir sa respiration","屏住呼吸"],["une respiration difficile","呼吸困难"],["la respiration artificielle","人工呼吸"],["reprendre sa respiration","喘口气"]],"sy":[["souffle","courant","气息，更口语"],["haleine","soutenu","口气，呼出的气"]],"fq":"中频，运动和健康话题。","me":"re-（再）+ spirare（吹气）：一进一出再呼吸。","tr":{"zh":"跑步后我的呼吸很快。","fr":"Ma respiration est rapide après la course.","alt":"Après la course, je respire vite.","note":"respiration 是名词，respirer 是动词。"}},
 "La tête": {"pos":"n.f. 阴性名词，复数 têtes","s":"头；脑袋。也有「脑子」「领头位置」之意：à la tête de l'entreprise（在公司领导位置）。","ipa":"[tɛt]","ph":"ê 读开口 [ɛ]；t [t]，结尾 e 不发音。","pi":"ê 读 [ɛ]；两个 t 都发音，但词尾 e 不发。","et":"来自晚期拉丁语 testa（壶，瓦片），后来用来指「脑袋」。同源：têtu（固执）。","ex":[["J'ai mal à la tête.","我头疼。"],["Il a la tête dure.","他很固执。"],["Baisse la tête, il y a une porte basse.","低头，这儿门很矮。"]],"co":[["avoir mal à la tête","头疼"],["faire la tête","板着脸，生气"],["en tête","在前面"],["se casser la tête","绞尽脑汁"]],"sy":[["crâne","courant","头颅（骨头）"],["caboche","familier","脑袋，有点幽默"],["tronche","argot","脑袋；脸，随意口语"]],"fq":"极高频，日常常用。","me":"tête 上的帽子 ê，像戴了一顶帽子的头。","tr":{"zh":"我头很疼，想躺下。","fr":"J'ai très mal à la tête, je veux m'allonger.","alt":"J'ai un mal de tête horrible, je vais m'allonger.","note":"avoir mal à la tête 与 avoir un mal de tête 都可。"}},
 "Une agression": {"pos":"n.f. 阴性名词，复数 agressions","s":"袭击；攻击；侵犯。可指肢体暴力，也可指言语攻击。动词是 agresser，形容词是 agressif。","ipa":"[a.ɡʁɛ.sjɔ̃]","ph":"a [a]；g 读 [g]；gr 读 [gʁ]；ssion 读 [sjɔ̃]。","pi":"ss 读 [s]；-ion 读 [jɔ̃]；g 在 a、r 前读 [g]。","et":"来自拉丁语 aggressio，源于 aggredi（走向，攻击）。同源：agresser、agressif。","ex":[["C'est une agression grave.","这是一起严重的袭击事件。"],["Il a été victime d'une agression dans la rue.","他在街上遭到袭击。"],["Elle a porté plainte après l'agression.","袭击之后她报了案。"]],"co":[["être victime d'une agression","遭到袭击"],["une agression physique / verbale","肢体 / 言语攻击"],["porter plainte pour agression","因袭击报案"],["une agression sexuelle","性侵犯"]],"sy":[["attaque","courant","攻击，范围更广"],["violence","courant","暴力"]],"fq":"中频，新闻和安全话题。","me":"agression ≈ aggression：两个 g 的英文，法文只写一个。","tr":{"zh":"昨晚街上发生了一起袭击。","fr":"Il y a eu une agression dans la rue hier soir.","alt":"Hier soir, quelqu'un a été agressé dans la rue.","note":"il y a eu = 过去发生了。"}},
 "Une allergie": {"pos":"n.f. 阴性名词，复数 allergies","s":"过敏。常用 avoir une allergie à + 过敏源，形容词是 allergique（à）。","ipa":"[a.lɛʁ.ʒi]","ph":"ll 读 [l]；er 读 [ɛʁ]；g 在 i 前读 [ʒ]；ie 读 [i]。","pi":"g 读 [ʒ]；重音落在最后一个音节 [ʒi]；介词用 à，不是 de。","et":"来自德语 Allergie，由希腊语 allos（其他）+ ergon（作用）构成，于 20 世纪初由医学家造出。","ex":[["Il a une allergie au pollen.","他对花粉过敏。"],["Je suis allergique aux chats.","我对猫过敏。"],["Elle a une allergie aux arachides.","她对花生过敏。"]],"co":[["avoir une allergie à","对……过敏"],["une allergie alimentaire","食物过敏"],["une allergie au pollen","花粉过敏"],["faire une réaction allergique","出现过敏反应"]],"sy":[["intolérance","courant","不耐受，不一定是免疫反应"],["rhume des foins","courant","花粉症"]],"fq":"中高频，看病和饮食常用。","me":"allergie ≈ allergy：g 读 [ʒ]，后面 -ie 简单。","tr":{"zh":"我对牛奶过敏。","fr":"J'ai une allergie au lait.","alt":"Je suis allergique au lait.","note":"allergie à + 冠词：à + le = au。"}},
 "Une ambulance": {"pos":"n.f. 阴性名词，复数 ambulances","s":"救护车。法国叫救护车可打 15（SAMU）或 112。ambulance 也可指医院的转运车。","ipa":"[ɑ̃.by.lɑ̃s]","ph":"am 读鼻化 [ɑ̃]；bu 读 [by]；lan 读 [lɑ̃]；ce 读 [s]。","pi":"u 读 [y]，不是「乌」；两个鼻化元音 am、an 不读出 m、n。","et":"来自拉丁语 ambulare（走动），原指「移动的医院」(hôpital ambulant)。","ex":[["L'ambulance est là.","救护车到了。"],["Appelez une ambulance, vite !","快叫救护车！"],["L'ambulance arrive en dix minutes.","救护车十分钟到。"]],"co":[["appeler une ambulance","叫救护车"],["monter dans l'ambulance","上救护车"],["une ambulance privée","私人救护车"],["le chauffeur d'ambulance","救护车司机"]],"sy":[["SAMU","courant","紧急医疗救助服务，打 15"],["pompiers","courant","消防员，也出救护（打 18）"]],"fq":"中频，紧急情况用。","me":"ambulance ≈ ambulance，意思同英语，但读音是法语的。","tr":{"zh":"快叫救护车！","fr":"Appelez vite une ambulance !","alt":"Vite, appelez une ambulance !","note":"祈使句 appelez：vous 形式。"}},
 "Une brûlure": {"pos":"n.f. 阴性名词，复数 brûlures","s":"烧伤；烫伤；灼痛。une brûlure d'estomac 指胃灼热（烧心）。动词是 brûler。","ipa":"[bʁy.lyʁ]","ph":"br 读 [bʁ]；û 读 [y]；lu 读 [ly]；r [ʁ]。","pi":"û 和 u 一样读 [y]；两个 [y] 圆唇；结尾 re 读 [ʁ]。","et":"由动词 brûler（烧）加后缀 -ure 构成。brûler 的更早来源不确定。","ex":[["J'ai une brûlure sur la main.","我手上烧伤了。"],["Elle a une brûlure au deuxième degré.","她是二度烧伤。"],["Mets de l'eau froide sur la brûlure.","往烫伤处冲冷水。"]],"co":[["une brûlure au premier / deuxième degré","一度 / 二度烧伤"],["une brûlure d'estomac","胃灼热"],["soigner une brûlure","处理烧伤"],["une crème pour les brûlures","烧伤药膏"]],"sy":[["échaudure","soutenu","烫伤，用热水"],["coup de soleil","courant","晒伤"]],"fq":"中频，生活和医疗用。","me":"brûlure ← brûler：û 的小帽子像火焰。","tr":{"zh":"我做饭时烫伤了手。","fr":"Je me suis brûlé la main en cuisinant.","alt":"Je me suis fait une brûlure à la main en cuisinant.","note":"se brûler 用代词式，后面接身体部位不加所有格。"}},
 "Une cigarette": {"pos":"n.f. 阴性名词，复数 cigarettes","s":"香烟；烟。抽烟说 fumer une cigarette；口语常用 clope（familier）。","ipa":"[si.ɡa.ʁɛt]","ph":"ci 读 [si]；g 读 [g]；a [a]；rette 读 [ʁɛt]。","pi":"ci 的 c 读 [s]；g 在 a 前读 [g]；tt 双写只读一个 t。","et":"来自 cigare（雪茄）加指小后缀 -ette，意思是「小雪茄」。","ex":[["Il fume une cigarette.","他抽一支烟。"],["Je ne fume plus de cigarettes.","我不再抽烟了。"],["Un paquet de cigarettes coûte cher.","一包烟很贵。"]],"co":[["fumer une cigarette","抽烟"],["un paquet de cigarettes","一包烟"],["une cigarette électronique","电子烟"],["allumer une cigarette","点烟"]],"sy":[["clope","familier","烟，口语"],["tabac","courant","烟草；也指烟草店"],["cigare","courant","雪茄，别混"]],"fq":"中频，生活用词。","me":"cigare + -ette：「小」雪茄就是香烟。","tr":{"zh":"他每天抽十支烟。","fr":"Il fume dix cigarettes par jour.","alt":"Il fume une dizaine de clopes par jour.","note":"par jour = 每天。"}},
 "Une douleur": {"pos":"n.f. 阴性名词，复数 douleurs","s":"疼痛；痛苦。可指身体疼，也指心里难过。比 mal 更正式、更像医学用词。","ipa":"[du.lœʁ]","ph":"ou 读 [u]；eu 读 [œ]；r 读 [ʁ]。","pi":"eu 在 r 前读 [œ]，不读 [ø]；注意 douleur 阴性，不是阳性。","et":"来自拉丁语 dolor（痛）。同源：douloureux（疼的）、condoléances（慰问）。","ex":[["J'ai une douleur au bras.","我手臂疼。"],["Où est la douleur ?","哪里疼？"],["Elle ressent une douleur vive.","她感到剧痛。"]],"co":[["avoir une douleur à","某处疼"],["une douleur vive / sourde","剧痛 / 隐痛"],["calmer la douleur","止痛"],["un médicament contre la douleur","止痛药"]],"sy":[["mal","courant","疼，日常口语：avoir mal"],["souffrance","soutenu","痛苦，偏精神层面"]],"fq":"极高频，看病必学。","me":"douleur ← dolor；同源 condoléances（慰问）：对疼痛的同情。","tr":{"zh":"我的背一直疼。","fr":"J'ai une douleur au dos depuis longtemps.","alt":"J'ai mal au dos depuis longtemps.","note":"une douleur à/au + 部位；avoir mal à/au 更口语。"}},
 "Une étude": {"pos":"n.f. 阴性名词，复数 études","s":"研究；调查报告。复数 les études 指「学业」，faire des études = 读大学、念书。","ipa":"[e.tyd]","ph":"é 读 [e]；tu 读 [ty]；d 读出 [d]，e 不发音。","pi":"u 是 [y]，嘴唇要圆；结尾 d 因后面有 e 要读出来；复数 études 指学业。","et":"来自拉丁语 studium（热情，学习）。同源：étudier、étudiant、studieux。","ex":[["D'après une étude, il faudrait dormir 8h par nuit.","据一项研究，每晚应睡八小时。"],["Elle fait des études de droit.","她读法律。"],["Cette étude est très sérieuse.","这项研究非常严谨。"]],"co":[["faire des études","读大学、求学"],["d'après une étude","据一项研究"],["une étude scientifique","科学研究"],["une étude de marché","市场调研"]],"sy":[["recherche","courant","研究，强调过程"],["enquête","courant","调查"],["analyse","courant","分析"]],"fq":"高频，学习和新闻常用。","me":"étude ← studium，étudier：e 开头，英语 study 是 stu-。","tr":{"zh":"据一项研究，咖啡有益健康。","fr":"D'après une étude, le café est bon pour la santé.","alt":"Selon une étude, le café fait du bien.","note":"d'après / selon + 名词，表示「据……」。"}},
 "Une formation": {"pos":"n.f. 阴性名词，复数 formations","s":"培训；学习课程；教育背景。也指「形成」或「队形」。faire une formation = 参加培训。","ipa":"[fɔʁ.ma.sjɔ̃]","ph":"for 读 [fɔʁ]；ma [ma]；-tion 读 [sjɔ̃]。","pi":"-tion 读 [sjɔ̃]；formation 里 o 是开口 [ɔ]。","et":"来自拉丁语 formatio，源于 formare（塑造），form- 即「形状」。同源：former、forme。","ex":[["Je fais une formation en anglais.","我在参加英语培训。"],["Il suit une formation professionnelle.","他在上职业培训。"],["Quelle est votre formation ?","您是什么教育背景？"]],"co":[["suivre une formation","上培训课"],["la formation continue","继续教育"],["une formation professionnelle","职业培训"],["une formation en ligne","线上培训"]],"sy":[["stage","courant","实习；短期培训"],["cours","courant","课程"],["apprentissage","courant","学习；学徒制"]],"fq":"高频，工作和学习话题。","me":"formation ← former：把人「塑造」成有技能的人。","tr":{"zh":"我下个月要参加一个培训。","fr":"Je vais faire une formation le mois prochain.","alt":"Le mois prochain, je pars en formation.","note":"aller + 原形 = 近将来时；partir en formation 是常用说法。"}},
 "Une indigestion": {"pos":"n.f. 阴性名词，复数 indigestions","s":"消化不良；吃坏肚子（吃撑了）。偶发的一次，不是长期问题。常说 faire une indigestion de + 食物（吃多了某食物）。","ipa":"[ɛ̃.di.ʒɛs.tjɔ̃]","ph":"in 读鼻化 [ɛ̃]；g 在 e 前读 [ʒ]；-stion 读 [stjɔ̃]。","pi":"in 读 [ɛ̃]，不读 [in]；-stion 的 t 读 [t]。","et":"由否定前缀 in- + digestion（消化）构成。","ex":[["Il a une indigestion.","他消化不良。"],["J'ai fait une indigestion de chocolat.","我巧克力吃多了，肚子不舒服。"],["Après la fête, elle a une indigestion.","聚会后她吃撑了。"]],"co":[["avoir une indigestion","消化不良"],["faire une indigestion de","吃……吃撑了"],["une indigestion de chocolat","巧克力吃多了"]],"sy":[["mal au ventre","courant","肚子疼，更泛"],["intoxication alimentaire","courant","食物中毒，更严重"]],"fq":"低中频，口语里能听到。","me":"in- 不 + digestion 消化 = 消化不了。","tr":{"zh":"我吃太多蛋糕，消化不良。","fr":"J'ai mangé trop de gâteau, j'ai une indigestion.","alt":"J'ai trop mangé de gâteau, j'ai mal au ventre.","note":"manger trop de + 名词（不加冠词）。"}},
 "Une infection": {"pos":"n.f. 阴性名词，复数 infections","s":"感染；炎症。细菌或病毒引起。常见：une infection urinaire（泌尿感染），une infection de l'oreille（耳部感染）。","ipa":"[ɛ̃.fɛk.sjɔ̃]","ph":"in 读 [ɛ̃]；fec 读 [fɛk]；-tion 读 [sjɔ̃]。","pi":"in 读 [ɛ̃]；fec 的 c 读 [k]；-tion 读 [sjɔ̃]。","et":"来自拉丁语 infectio，源于 inficere（染上）。同源：infecter、infectieux。","ex":[["C'est une petite infection.","这是个小感染。"],["Il a une infection à l'oreille.","他耳朵感染。"],["L'infection se soigne avec des antibiotiques.","感染用抗生素治疗。"]],"co":[["une infection urinaire","泌尿道感染"],["soigner une infection","治疗感染"],["une infection virale / bactérienne","病毒 / 细菌感染"],["attraper une infection","感染上"]],"sy":[["inflammation","courant","炎症，红肿"],["contagion","courant","传染"]],"fq":"中频，医学常用。","me":"infection ≈ infection：in- 里面 + fect 做 = 被「做」进了身体。","tr":{"zh":"医生说这是细菌感染。","fr":"Le médecin dit que c'est une infection bactérienne.","alt":"D'après le médecin, c'est une infection bactérienne.","note":"dire que + 陈述句。"}},
 "Une infraction": {"pos":"n.f. 阴性名词，复数 infractions","s":"违法行为；违规。从交通违章到轻罪都可称为 infraction。常见 commettre une infraction（犯法）。","ipa":"[ɛ̃.fʁak.sjɔ̃]","ph":"in 读 [ɛ̃]；fra 读 [fʁa]；c 读 [k]；-tion 读 [sjɔ̃]。","pi":"in 读 [ɛ̃]；c 读 [k]，不能省；-tion 读 [sjɔ̃]。","et":"来自拉丁语 infractio，源于 infringere（打破）。同源：enfreindre（违反）。","ex":[["Il a commis une infraction.","他犯了违法行为。"],["Rouler trop vite est une infraction.","超速是违法的。"],["La police constate l'infraction.","警方认定违规行为。"]],"co":[["commettre une infraction","违法"],["une infraction au code de la route","违反交通法规"],["constater une infraction","认定违法"],["en infraction","违规的状态"]],"sy":[["délit","courant","轻罪"],["crime","courant","重罪"],["contravention","courant","罚单、轻微违章"]],"fq":"中频，新闻和法律话题。","me":"infraction：in-+ fract-（打碎）：把规则打破。","tr":{"zh":"闯红灯是违法行为。","fr":"Griller un feu rouge est une infraction.","alt":"Passer au rouge, c'est une infraction.","note":"动词原形可以当主语。"}},
 "Une inondation": {"pos":"n.f. 阴性名词，复数 inondations","s":"洪水；水灾；淹水。动词是 inonder。屋里漏水淹了也可以说 une inondation。","ipa":"[i.nɔ̃.da.sjɔ̃]","ph":"i [i]；non 读鼻化 [nɔ̃]；da [da]；-tion 读 [sjɔ̃]。","pi":"inon 中的 on 是鼻化 [ɔ̃]，n 不单独发音；首 i 单独一个音节。","et":"来自拉丁语 inundatio，源于 inundare（泛滥），源自 unda（波浪）。同源：onde（波）、ondulation。","ex":[["Il y a une inondation dans la rue.","街上发洪水。"],["L'inondation a détruit des maisons.","洪水毁了一些房子。"],["Il y a eu des inondations après la pluie.","下雨后发生了水灾。"]],"co":[["une zone inondable","易淹地区"],["un risque d'inondation","洪水风险"],["être touché par une inondation","遭受洪灾"],["inonder la cave","淹了地下室"]],"sy":[["crue","courant","河水上涨"],["déluge","littéraire","洪水，大雨"]],"fq":"中频，新闻常见。","me":"in- + unda（波浪）：被浪淹没。","tr":{"zh":"大雨之后有洪水。","fr":"Il y a eu une inondation après la grosse pluie.","alt":"Après l'orage, la ville a été inondée.","note":"inonder 的被动式 être inondé。"}},
 "Une insomnie": {"pos":"n.f. 阴性名词，复数 insomnies","s":"失眠。常说 avoir des insomnies（失眠）或 faire de l'insomnie（失眠，口语）。","ipa":"[ɛ̃.sɔm.ni]","ph":"in 读 [ɛ̃]；som 读 [sɔm]，m 读出；nie 读 [ni]。","pi":"in 读 [ɛ̃]；som 中 m 要发音，不是鼻化。","et":"来自拉丁语 insomnia，由 in-（无）+ somnus（睡眠）构成。同源：somnoler、somnifère。","ex":[["Je fais de l'insomnie.","我失眠。"],["Elle a des insomnies depuis un mois.","她失眠一个月了。"],["Les écrans causent des insomnies.","屏幕会导致失眠。"]],"co":[["souffrir d'insomnie","受失眠之苦"],["avoir des insomnies","失眠"],["une nuit d'insomnie","失眠的夜晚"],["un remède contre l'insomnie","治失眠的方法"]],"sy":[["nuit blanche","courant","一夜没睡"],["somnifère","courant","安眠药"]],"fq":"中频，健康话题常见。","me":"in-（无）+ somnus（睡）= 没睡着。","tr":{"zh":"最近我总是失眠。","fr":"En ce moment, je fais de l'insomnie.","alt":"Ces temps-ci, j'ai du mal à dormir.","note":"faire de l'insomnie 与 avoir des insomnies 都对。"}},
 "Une migraine": {"pos":"n.f. 阴性名词，复数 migraines","s":"偏头痛。比普通头痛 mal de tête 更严重，常伴恶心、怕光。","ipa":"[mi.ɡʁɛn]","ph":"mi [mi]；gr 读 [gʁ]；ai 读 [ɛ]；ne 读 [n]。","pi":"ai 读 [ɛ]；n 读出来，不是鼻化 [ɛ̃]；g 读 [g]。","et":"来自希腊语 hemikrania（半边头），经拉丁语 hemicrania。","ex":[["Elle a une forte migraine.","她偏头痛很厉害。"],["J'ai souvent des migraines.","我常常偏头痛。"],["La lumière me donne la migraine.","光线让我头疼。"]],"co":[["avoir la migraine","偏头痛"],["une migraine violente","剧烈偏头痛"],["donner la migraine","让人头疼"],["prendre un médicament contre la migraine","吃偏头痛药"]],"sy":[["mal de tête","courant","头疼，较轻"],["céphalée","soutenu","头痛，医学术语"]],"fq":"中频，健康话题。","me":"migraine ← 半(hemi) + 颅(krania)：半边头痛。","tr":{"zh":"我今天偏头痛，想休息。","fr":"J'ai la migraine aujourd'hui, je veux me reposer.","alt":"Aujourd'hui j'ai une migraine, je vais me reposer.","note":"avoir la migraine 是常用固定说法。"}},
 "Une mutuelle": {"pos":"n.f. 阴性名词，复数 mutuelles","s":"补充医疗保险；互助保险组织。法国医保（Sécu）只报销一部分，余下由 mutuelle 付。","ipa":"[my.tɥɛl]","ph":"mu 读 [my]；tuel 读 [tɥɛl]。","pi":"u 是 [y]；uel 里 u 和 e 连成 [ɥɛ]；结尾 l 读出来。","et":"由形容词 mutuel（相互的，来自拉丁语 mutuus）变成名词，指互助保险社。","ex":[["Ma mutuelle paie le reste.","我的补充保险付剩下的部分。"],["Je cherche une mutuelle pas chère.","我在找便宜的补充保险。"],["Ma mutuelle rembourse les lunettes.","我的补充保险报销眼镜。"]],"co":[["avoir une mutuelle","有补充保险"],["changer de mutuelle","换补充保险"],["une mutuelle santé","健康互助保险"],["la mutuelle d'entreprise","公司统一的补充保险"]],"sy":[["assurance santé","courant","健康保险，更泛"],["Sécurité sociale","courant","社保，国家基本医保"]],"fq":"中频，在法国生活必学。","me":"mutuelle ← mutuel：大家「互相」出钱的保险。","tr":{"zh":"您有补充保险吗？","fr":"Avez-vous une mutuelle ?","alt":"Vous avez une mutuelle ?","note":"倒装疑问 Avez-vous 较正式，口语只用升调。"}},
 "Une ordonnance": {"pos":"n.f. 阴性名词，复数 ordonnances","s":"处方；医嘱。医生开的药方。也有「命令、法令」之意（如 une ordonnance du gouvernement）。","ipa":"[ɔʁ.dɔ.nɑ̃s]","ph":"or 读 [ɔʁ]；do 读 [dɔ]；nan 读鼻化 [nɑ̃]；ce 读 [s]。","pi":"ordonnance 里 on 前面的 n 要读；nan 才是鼻化，不是 [nɔ̃]。","et":"来自动词 ordonner（安排，命令），源于拉丁语 ordo（秩序）。同源：ordre、ordinaire。","ex":[["Voici votre ordonnance.","这是您的处方。"],["Il faut une ordonnance pour ce médicament.","这个药需要处方。"],["Le médecin rédige une ordonnance.","医生开处方。"]],"co":[["sur ordonnance","凭处方"],["faire une ordonnance","开处方"],["renouveler une ordonnance","续开处方"],["en vente libre / sans ordonnance","无需处方（非处方药）"]],"sy":[["prescription","soutenu","处方，较正式"],["recette","courant","食谱，别混"]],"fq":"中高频，看病取药常用。","me":"ordonnance ← ordre：医生下的「命令」。","tr":{"zh":"没有处方我不能给您这个药。","fr":"Je ne peux pas vous donner ce médicament sans ordonnance.","alt":"Sans ordonnance, je ne peux pas vous le donner.","note":"sans + 名词，不加冠词。"}},
 "Une pilule contraceptive": {"pos":"n.f. 阴性名词，复数 pilules contraceptives","s":"避孕药。日常常简称 la pilule。pilule 本身也是「药丸」，contraceptive 说明是避孕用。","ipa":"[pi.lyl kɔ̃.tʁa.sɛp.tiv]","ph":"pilule 读 [pi.lyl]；contraceptive 读 [kɔ̃.tʁa.sɛp.tiv]，c 在 e 前读 [s]。","pi":"u 读 [y]；contraceptive 中的 on 是鼻化 [ɔ̃]；形容词 -ive 要配阴性。","et":"pilule 来自拉丁语 pilula（小球）；contraceptif 由 contra-（反对）+ conception（受孕）构成。","ex":[["Elle prend la pilule contraceptive.","她服用避孕药。"],["Elle a arrêté la pilule.","她停了避孕药。"],["Le médecin lui prescrit la pilule.","医生给她开避孕药。"]],"co":[["prendre la pilule","服用避孕药"],["arrêter la pilule","停药"],["la pilule du lendemain","紧急避孕药"],["une pilule contraceptive","避孕药"]],"sy":[["pilule","courant","常用简称"],["contraceptif","soutenu","避孕药，医学词"]],"fq":"中频，健康话题。","me":"contra-（反对）+ cept-（受孕）+ pilule（小丸）。","tr":{"zh":"她每天晚上吃避孕药。","fr":"Elle prend la pilule tous les soirs.","alt":"Chaque soir, elle prend sa pilule.","note":"避孕药用定冠词 la pilule。"}},
 "Une piqûre": {"pos":"n.f. 阴性名词，复数 piqûres","s":"叮咬；蜇伤；注射（打针）。une piqûre de moustique（蚊子叮咬），faire une piqûre（打针）。","ipa":"[pi.kyʁ]","ph":"pi [pi]；qû 读 [ky]；re 读 [ʁ]，e 不发音。","pi":"qû 里 u 不单独读，qu 读 [k]，û 读 [y]；piqûre 与 pique 相近但不同。","et":"由动词 piquer（刺，叮）加后缀 -ure 构成。","ex":[["C'est une piqûre de moustique.","这是蚊子叮咬。"],["L'infirmière me fait une piqûre.","护士给我打针。"],["Ça gratte, j'ai une piqûre.","很痒，我被叮了。"]],"co":[["une piqûre de moustique / d'abeille","蚊子 / 蜜蜂叮咬"],["faire une piqûre","打针"],["se faire piquer","被叮"],["une piqûre de rappel","加强针"]],"sy":[["morsure","courant","咬伤（动物）"],["injection","soutenu","注射，医学用语"],["vaccin","courant","疫苗"]],"fq":"中频，生活和医疗用。","me":"piqûre ← piquer：û 的帽子像针尖。","tr":{"zh":"我被蚊子叮了，很痒。","fr":"J'ai une piqûre de moustique, ça gratte.","alt":"Un moustique m'a piqué, ça me gratte.","note":"ça gratte 是口语，意为「很痒」。"}},
 "Une tension": {"pos":"n.f. 阴性名词，复数 tensions","s":"血压；紧张；张力。看病时 la tension = 血压；ma tension est haute 指血压高；也指人际关系紧张。","ipa":"[tɑ̃.sjɔ̃]","ph":"ten 读鼻化 [tɑ̃]；-sion 读 [sjɔ̃]。","pi":"ten 读 [tɑ̃]，不是 [tɛ̃]；-sion 读 [sjɔ̃]。","et":"来自拉丁语 tensio，源于 tendere（拉紧）。同源：tendre、tension、intention。","ex":[["Sa tension est haute.","她血压高。"],["Le médecin prend ma tension.","医生量我的血压。"],["Il y a de la tension entre eux.","他们之间气氛紧张。"]],"co":[["prendre la tension","量血压"],["avoir de la tension","血压高"],["une tension artérielle","动脉血压"],["faire baisser la tension","降压"]],"sy":[["pression","courant","压力；pression artérielle 也指血压"],["stress","courant","压力、紧张"]],"fq":"中频，看病和关系话题。","me":"tension ≈ tension：拉紧的弦，血管里也被拉紧。","tr":{"zh":"医生帮我量了血压。","fr":"Le médecin m'a pris la tension.","alt":"Le médecin a pris ma tension.","note":"prendre la tension = 量血压。"}},
 "Une victime": {"pos":"n.f. 阴性名词，复数 victimes（男女都用阴性 une victime）","s":"受害者；伤亡者。即使是男性，也用 une victime（阴性）。常见于新闻：les victimes de l'accident。","ipa":"[vik.tim]","ph":"vic 读 [vik]；ti 读 [ti]；me 读 [m]，e 不发音。","pi":"男性受害者也说 une victime，不要改成 un victime。ti 在这里读 [ti]，不是 [si]。","et":"来自拉丁语 victima（祭品）。同源：victimiser。","ex":[["Il y a une victime.","有一名受害者。"],["Les victimes sont à l'hôpital.","受害者在医院。"],["Il est victime d'un vol.","他是盗窃的受害者。"]],"co":[["être victime de","成为……的受害者"],["une victime d'accident","事故受害者"],["aider les victimes","帮助受害者"],["jouer les victimes","装可怜、扮受害者"]],"sy":[["blessé","courant","伤者"],["mort","courant","死者"],["sinistré","soutenu","灾民"]],"fq":"中高频，新闻常见。","me":"victime 永远阴性，像「她」一样站在新闻里。","tr":{"zh":"他是这起事故的受害者。","fr":"Il est victime de cet accident.","alt":"C'est une victime de l'accident.","note":"être victime de 不加冠词。"}},
 "Des bouchons d'oreille": {"pos":"n.m.pl. 阳性复数名词，单数 un bouchon d'oreille","s":"耳塞。bouchon 本义是「塞子、瓶塞」。也可说 des boules Quies（品牌，常通用）。","ipa":"[bu.ʃɔ̃ dɔ.ʁɛj]","ph":"bou 读 [bu]；chon 读 [ʃɔ̃]；d'oreille 读 [dɔ.ʁɛj]，-eille 读 [ɛj]。","pi":"ch 读 [ʃ]；-eille 读 [ɛj]，l 不单独读 [l]；d' 与 oreille 连读。","et":"bouchon 来自 bouche（口，塞住口）的派生；oreille 来自拉丁语 auricula（小耳朵）。","ex":[["Je dors avec des bouchons d'oreille.","我戴耳塞睡觉。"],["Mets des bouchons d'oreille au concert.","在音乐会上戴耳塞。"],["Il me faut des bouchons d'oreille pour nager.","我游泳需要耳塞。"]],"co":[["mettre des bouchons d'oreille","戴耳塞"],["une paire de bouchons d'oreille","一副耳塞"],["des bouchons en mousse","海绵耳塞"],["dormir avec des bouchons","戴耳塞睡"]],"sy":[["boules Quies","courant","品牌名，常当作耳塞的统称"],["casque anti-bruit","courant","降噪耳机"]],"fq":"中低频，旅行和睡眠话题。","me":"bouchon（塞子）+ oreille（耳朵）= 塞耳朵的塞子。","tr":{"zh":"我睡觉要戴耳塞。","fr":"Je dors avec des bouchons d'oreille.","alt":"Pour dormir, je mets des bouchons d'oreille.","note":"avec + 复数名词，用 des。"}},
 "Des courbatures": {"pos":"n.f.pl. 阴性复数名词，单数 une courbature（多用复数）","s":"肌肉酸痛（运动后）。常用复数：avoir des courbatures。发烧、流感时全身酸痛也这样说。","ipa":"[kuʁ.ba.tyʁ]","ph":"cour 读 [kuʁ]；ba [ba]；tu 读 [ty]；re 读 [ʁ]。","pi":"ou 读 [u]；u 读 [y]；两者不要混；常用复数，不是 une courbature。","et":"来自 courber（弯）+ 后缀，意思是「身体弯曲时的疼」；确切来源有争议。","ex":[["J'ai des courbatures après le sport.","运动后我肌肉酸痛。"],["Il a des courbatures dans les jambes.","他腿上肌肉酸痛。"],["Prends un bain chaud pour tes courbatures.","泡个热水澡缓解酸痛。"]],"co":[["avoir des courbatures","肌肉酸痛"],["des courbatures aux jambes","腿部酸痛"],["soulager des courbatures","缓解酸痛"],["des courbatures et de la fièvre","全身酸痛加发烧"]],"sy":[["douleur musculaire","courant","肌肉疼痛，较通用"],["fatigue","courant","疲劳"]],"fq":"中低频，运动话题。","me":"courbatures ← courber：身体弯曲后，肌肉酸。","tr":{"zh":"跑完步我全身酸痛。","fr":"Après la course, j'ai des courbatures partout.","alt":"J'ai mal partout après avoir couru.","note":"partout = 到处、全身。"}},
 "Des pastilles": {"pos":"n.f.pl. 阴性复数名词，单数 une pastille","s":"含片；喉糖；小圆片。pastilles pour la gorge 是喉糖。也指「小圆片」，如 pastille de menthe（薄荷糖）。","ipa":"[pas.tij]","ph":"pas 读 [pas]；til 在此读 [tij]，-ille 读 [ij]。","pi":"-ille 读 [ij]，l 不单独发；ville 是例外，不要混。","et":"来自西班牙语 pastilla（小面团），源于拉丁语 pastillus（小面包）。","ex":[["J'achète des pastilles pour la gorge.","我买喉糖。"],["Elle suce une pastille à la menthe.","她含着薄荷糖。"],["Ces pastilles calment la toux.","这些含片能止咳。"]],"co":[["des pastilles pour la gorge","喉糖"],["une pastille de menthe","薄荷糖"],["sucer une pastille","含一粒糖"],["des pastilles contre la toux","止咳含片"]],"sy":[["bonbon","courant","糖，普通糖"],["comprimé","courant","药片，要吞下"]],"fq":"中低频，看病和购物。","me":"pastille 像「小小的糖」(pasta 面团) 含在嘴里。","tr":{"zh":"我喉咙痛，买了喉糖。","fr":"J'ai mal à la gorge, j'ai acheté des pastilles.","alt":"Comme j'ai la gorge qui pique, j'ai pris des pastilles.","note":"j'ai acheté 是复合过去时。"}},
 "Des vertiges": {"pos":"n.m.pl. 阳性复数名词，单数 un vertige","s":"眩晕；头晕。avoir des vertiges 指头晕目眩；avoir le vertige 指恐高，在高处头晕。","ipa":"[vɛʁ.tiʒ]","ph":"ver 读 [vɛʁ]；ti 读 [ti]；ge 读 [ʒ]。","pi":"g 读 [ʒ]；avoir le vertige（恐高）和 avoir des vertiges（头晕）有区别。","et":"来自拉丁语 vertigo，源于 vertere（转）。同源：vertigineux（令人眩晕的）。","ex":[["J'ai des vertiges ce matin.","我今早头晕。"],["Elle a le vertige en haut de la tour.","她在塔顶恐高。"],["Ce médicament donne des vertiges.","这个药会让人头晕。"]],"co":[["avoir des vertiges","头晕"],["avoir le vertige","恐高"],["donner le vertige","让人眩晕"],["souffrir de vertiges","常头晕"]],"sy":[["étourdissement","soutenu","眩晕感"],["malaise","courant","不舒服，昏厥感"]],"fq":"中频，看病用。","me":"vertige ← vertere（转）：世界在转。","tr":{"zh":"我站起来就头晕。","fr":"J'ai des vertiges quand je me lève.","alt":"Quand je me lève, la tête me tourne.","note":"la tête me tourne = 头晕（口语）。"}},
 "Les chevilles": {"pos":"n.f.pl. 阴性复数名词，单数 la cheville","s":"脚踝。se fouler la cheville = 扭伤脚踝。cheville 也指「木栓、销子」。","ipa":"[ʃə.vij]","ph":"ch 读 [ʃ]；e 轻读 [ə]；-ille 读 [ij]。","pi":"-ille 读 [ij]；ch 读 [ʃ]；第一个 e 轻读，甚至省略。","et":"来自拉丁语 cavicula（小钉、小销），指踝骨如销子。","ex":[["Elle a une cheville fragile.","她脚踝脆弱。"],["Je me suis foulé la cheville.","我扭伤了脚踝。"],["Mes chevilles sont gonflées.","我的脚踝肿了。"]],"co":[["se fouler la cheville","扭伤脚踝"],["avoir les chevilles gonflées","脚踝肿"],["une entorse à la cheville","脚踝扭伤"],["avoir les chevilles qui enflent","自大（比喻）"]],"sy":[["pied","courant","脚，整个脚"],["jambe","courant","腿"]],"fq":"中频，运动和健康话题。","me":"chevilles ← cavicula：一根小销钉连接脚和腿。","tr":{"zh":"踢球时我扭伤了脚踝。","fr":"Je me suis foulé la cheville en jouant au foot.","alt":"Je me suis tordu la cheville au foot.","note":"se fouler la cheville 用代词式，身体部位用定冠词。"}},
 "Les cuisses": {"pos":"n.f.pl. 阴性复数名词，单数 la cuisse","s":"大腿。cuisse de poulet 是鸡腿。和 jambe（整条腿）、mollet（小腿肚）区分。","ipa":"[kɥis]","ph":"cui 读 [kɥi]；ss 读 [s]；e 不发音。","pi":"uis 连读成 [ɥi]；跟 cuire（烹饪）发音相近但不同。","et":"来自拉丁语 coxa（髋、大腿）。","ex":[["Il a mal aux cuisses.","他大腿疼。"],["Je mange une cuisse de poulet.","我吃一只鸡腿。"],["Elle fait des squats pour les cuisses.","她做深蹲练大腿。"]],"co":[["avoir mal aux cuisses","大腿疼"],["une cuisse de poulet","鸡腿"],["des cuisses de grenouille","蛙腿"],["muscler ses cuisses","锻炼大腿"]],"sy":[["jambe","courant","整条腿"],["mollet","courant","小腿肚"]],"fq":"中频，运动和饮食话题。","me":"cuisse 里有 cui-，像烤好的鸡腿 (cuisse de poulet)。","tr":{"zh":"爬完山我大腿很疼。","fr":"J'ai mal aux cuisses après la randonnée.","alt":"Après la rando, mes cuisses me font mal.","note":"mal aux + 复数名词（à + les = aux）。"}},
 "Les épaules": {"pos":"n.f.pl. 阴性复数名词，单数 l'épaule","s":"肩膀。hausser les épaules = 耸肩。常用于疼痛、紧张和背负责任（比喻）。","ipa":"[e.pol]","ph":"é 读 [e]；pau 读 [po]；le 读 [l]，e 不发音。","pi":"au 读 [o]；épaule 中 e 不读，结尾 [l] 要读。","et":"来自拉丁语 spatula（小铲、肩胛骨）。同源：spatule（铲子）。","ex":[["Mes épaules sont tendues.","我的肩膀很紧。"],["Il hausse les épaules.","他耸了耸肩。"],["Elle porte son sac sur l'épaule.","她把包背在肩上。"]],"co":[["avoir mal aux épaules","肩膀疼"],["hausser les épaules","耸肩"],["avoir les épaules larges","肩膀宽"],["un mal d'épaule","肩痛"]],"sy":[["omoplate","soutenu","肩胛骨"],["bras","courant","手臂"]],"fq":"中频，健康和运动话题。","me":"épaule ← spatula：肩胛骨像一把小铲子。","tr":{"zh":"坐了一整天，我的肩膀很紧。","fr":"Après une journée assise, j'ai les épaules tendues.","alt":"J'ai passé la journée assis, mes épaules sont tendues.","note":"avoir les épaules + 形容词，说明肩膀状态。"}},
 "Les genoux": {"pos":"n.m.pl. 阳性复数名词，单数 le genou（复数加 x）","s":"膝盖。être à genoux = 跪着；sur les genoux de qqn = 坐在某人腿上。","ipa":"[ʒə.nu]","ph":"ge 读 [ʒə]，e 轻读；nou 读 [nu]；x 不发音。","pi":"复数是 genoux，不是 genous；x 不发音；单复数发音相同。","et":"来自拉丁语 genuculum（小膝），源于 genu（膝）。同源：génuflexion（屈膝）。","ex":[["Mes genoux me font mal.","我膝盖疼。"],["L'enfant s'assoit sur mes genoux.","孩子坐在我腿上。"],["Il est tombé à genoux.","他跪倒在地。"]],"co":[["avoir mal aux genoux","膝盖疼"],["à genoux","跪着"],["sur les genoux","坐在腿上"],["se blesser au genou","膝盖受伤"]],"sy":[["rotule","courant","髌骨"],["articulation","courant","关节"]],"fq":"中频，运动和健康话题。","me":"genou ← genu：膝盖，复数加 x。","tr":{"zh":"下楼时我的膝盖很疼。","fr":"J'ai mal aux genoux quand je descends l'escalier.","alt":"Mes genoux me font mal dans l'escalier.","note":"quand + 现在时，表示一般情况。"}},
 "Les jambes": {"pos":"n.f.pl. 阴性复数名词，单数 la jambe","s":"腿（从髋到脚）。avoir mal aux jambes = 腿疼。jambe 指整条腿；cuisse 是大腿。","ipa":"[ʒɑ̃b]","ph":"j 读 [ʒ]；am 读鼻化 [ɑ̃]；b 要读出来，e 不发音。","pi":"am 里的 m 不发音，但后面的 b 要读 [b]；这点和 jam 不同。","et":"来自晚期拉丁语 gamba（马的后腿），源于希腊语 kampe（弯曲）。同源：jambon（火腿）。","ex":[["Mes jambes sont fatiguées.","我的腿很累。"],["Il croise les jambes.","他翘着腿。"],["Elle a de longues jambes.","她腿很长。"]],"co":[["avoir mal aux jambes","腿疼"],["croiser les jambes","翘二郎腿"],["jambes lourdes","腿沉"],["les jambes en l'air","腿朝天"]],"sy":[["patte","familier","腿（动物），口语里也用于人"],["pied","courant","脚，别混"],["guibole","argot","腿，口语俚语"]],"fq":"极高频，日常常用。","me":"jambes ← gamba；火腿 jambon 就是腿做成的。","tr":{"zh":"我走了一整天，腿很累。","fr":"J'ai marché toute la journée, mes jambes sont fatiguées.","alt":"J'ai marché toute la journée, j'ai les jambes en compote.","note":"avoir les jambes en compote 是口语，指累得腿软。"}},
 "Les paupières": {"pos":"n.f.pl. 阴性复数名词，单数 la paupière","s":"眼皮；眼睑。fermer les paupières = 闭眼。形容困倦用 avoir les paupières lourdes。","ipa":"[po.pjɛʁ]","ph":"pau 读 [po]；pi 读 [pj]；è 读 [ɛ]；r 读 [ʁ]。","pi":"au 读 [o]；-ière 读 [jɛʁ]；复数 s 不发音。","et":"来自拉丁语 palpebra（眼皮）。同源：palpiter（跳动）。","ex":[["Ses paupières sont lourdes.","他眼皮很沉。"],["Elle ferme les paupières.","她闭上了眼皮。"],["J'ai une paupière qui tremble.","我有一只眼皮在跳。"]],"co":[["avoir les paupières lourdes","困得睁不开眼"],["fermer les paupières","闭眼"],["une paupière gonflée","眼皮肿"],["un tic à la paupière","眼皮抽动"]],"sy":[["cil","courant","睫毛，别混"],["œil","courant","眼睛"]],"fq":"中低频，健康和描写话题。","me":"paupières 读起来像 pau-pière：闭眼时嘴唇也闭上。","tr":{"zh":"我困得眼皮很沉。","fr":"J'ai sommeil, mes paupières sont lourdes.","alt":"Je tombe de sommeil, j'ai les paupières lourdes.","note":"avoir sommeil = 困了。"}},
 "Les pieds": {"pos":"n.m.pl. 阳性复数名词，单数 un pied，复数 pieds","s":"脚；脚掌。也指「底部」，如 le pied de la montagne（山脚）。身体部位通常用定冠词或物主词：J'ai mal aux pieds。","ipa":"[pje]","ph":"p+ie 读 [pje]；结尾 ds/d、s 都不发音。复数 pieds 与单数同音。","pi":"结尾的 -s 不发音，单复数听不出区别，靠冠词 le / les 分辨。les pieds 读 [le pje]，pieds 以辅音开头，所以 les 不连读。","et":"来自拉丁语 pes, pedis（脚）。同源：pédale（踏板）、piéton（行人）。","ex":[["Mes pieds sont froids.","我的脚很冷。"],["J'ai mal aux pieds.","我脚疼。"],["Il va au travail à pied.","他步行去上班。"]],"co":[["aller à pied","步行去"],["avoir mal aux pieds","脚疼"],["pieds nus","光着脚"]],"sy":[["patte","familier","(动物的)爪、脚；口语里可指人的脚"]],"fq":"高频，日常常用。","me":"pied 像 pédale 的「脚踏」：脚踩的东西。","tr":{"zh":"我的脚很疼，因为我走了很多路。","fr":"J'ai mal aux pieds parce que j'ai beaucoup marché.","alt":"J'ai mal aux pieds, j'ai trop marché.","note":"身体部位疼：avoir mal à + 定冠词（aux = à + les）。"}},
 "Les pompiers": {"pos":"n.m.pl. 阳性复数名词，单数 un pompier，复数 pompiers","s":"消防员。法国的 pompiers 也负责大部分急救和救护车出勤，所以遇到事故、急病常常打 18 找他们。","ipa":"[pɔ̃.pje]","ph":"om 在 p 前读鼻化音 [ɔ̃]；ie 读 [je]；结尾 -ers 的 r、s 不发音。","pi":"-iers 结尾只读 [je]，r 和 s 都不发音；别把 om 读成 [ɔm]。","et":"来自 pompe（水泵）加后缀 -ier：用水泵灭火的人。","ex":[["Appelez les pompiers !","请叫消防员！"],["Les pompiers arrivent dans dix minutes.","消防员十分钟后到。"],["Mon oncle est pompier.","我叔叔是消防员。"]],"co":[["appeler les pompiers","叫消防员"],["une caserne de pompiers","消防站"],["le camion de pompiers","消防车"]],"sy":[["sapeur-pompier","soutenu","正式全称，消防员"],["secouriste","courant","急救员（不一定是消防员）"]],"fq":"中高频，日常常用。","me":"pompier = pompe（水泵）+ -ier：拿水泵的人。","tr":{"zh":"出事了，快叫消防员！","fr":"Il y a un accident, appelez vite les pompiers !","alt":"Il y a un problème, appelez les pompiers, vite !","note":"法国消防电话是 18，欧洲统一急救号是 112。"}},
 "Les premiers secours": {"pos":"n.m.pl. 阳性复数名词，一般只用复数","s":"急救；初步救助。指在医生到达前的第一时间救护：donner les premiers secours（做急救）。注意 secours 单复数同形，结尾 s 不发音。","ipa":"[prə.mje.sə.kuʁ]","ph":"premiers [prə.mje]，结尾 -rs 不发音；secours [sə.kuʁ]，ours 读 [uʁ]，s 不发音。","pi":"premiers 的 -ers 不发音；secours 的结尾 -s 不发音，别读成 [sə.kuʁs]。","et":"premier 来自拉丁语 primarius（第一的）；secours 来自动词 secourir（救助），源于拉丁语 succurrere（跑去帮助）。","ex":[["J'ai appris les premiers secours.","我学过急救。"],["Il sait faire les premiers secours.","他会做急救。"],["Un cours de premiers secours est obligatoire.","急救课是必修的。"]],"co":[["donner les premiers secours","做急救"],["un stage de premiers secours","急救培训"],["appeler les secours","叫救援"]],"sy":[["gestes de premiers secours","courant","急救动作"],["soins d'urgence","courant","紧急医疗处理"]],"fq":"中频，健康与安全话题常用。","me":"premiers（第一）+ secours（救援）= 先到的救援。","tr":{"zh":"我想学急救。","fr":"Je voudrais apprendre les premiers secours.","alt":"J'aimerais suivre un cours de premiers secours.","note":"通常带 les：les premiers secours。"}},
 "Les urgences": {"pos":"n.f.pl. 阴性复数名词，单数 une urgence，复数 urgences","s":"急诊（室）。aux urgences = 在急诊；单数 une urgence = 紧急情况：C'est une urgence。","ipa":"[yʁ.ʒɑ̃s]","ph":"u [y]；r [ʁ]；g 在 e 前读 [ʒ]；en 读鼻化音 [ɑ̃]；结尾 -ces 里 c 读 [s]，e 不发音。","pi":"u 是 [y]，不是 [u]；en 读 [ɑ̃]，不是「恩」。aux urgences 需要连读：aux [oz] urgences。","et":"来自拉丁语 urgere（催促、逼迫）。同源：urgent（紧急的）。","ex":[["Il est aux urgences.","他在急诊室。"],["Allez aux urgences tout de suite !","马上去急诊！"],["C'est une urgence.","这是紧急情况。"]],"co":[["aller aux urgences","去急诊"],["les urgences médicales","医疗急救"],["en cas d'urgence","紧急情况下"]],"sy":[["service des urgences","soutenu","急诊科（正式）"],["les urgences","courant","急诊（最常用）"]],"fq":"高频，医疗话题必备。","me":"urgence ← urgent：一听就是「赶紧」。","tr":{"zh":"我的儿子发烧了，我们去急诊。","fr":"Mon fils a de la fièvre, on va aux urgences.","alt":"Mon fils est malade, on file aux urgences.","note":"aller + aux urgences：aux = à + les。"}},
 "Un accident de voiture / de la route": {"pos":"n.m. 阳性名词，复数 accidents","s":"车祸；交通事故。un accident de voiture 指汽车事故，un accident de la route 范围更大，指任何道路交通事故（含摩托、自行车）。","ipa":"[ak.si.dɑ̃]","ph":"cc 在 i 前读 [ks]；en 读鼻化音 [ɑ̃]；结尾 t 不发音。","pi":"accident 里 -cc- 读 [ks]；结尾 -ent 读 [ɑ̃]，t 不发音。","et":"来自拉丁语 accidens（偶然发生的事）。同源：accidentel（意外的）。","ex":[["Il a eu un accident de voiture.","他出了车祸。"],["Il y a eu un accident sur l'autoroute.","高速公路上发生了事故。"],["Elle est blessée dans un accident de la route.","她在交通事故中受伤了。"]],"co":[["avoir un accident","出事故"],["un accident grave","严重事故"],["un accident mortel","致命事故"]],"sy":[["collision","soutenu","碰撞"],["carambolage","courant","连环相撞"]],"fq":"高频，日常新闻常见。","me":"ac-ci-dent：像英语 accident，注意 cc 读 [ks]。","tr":{"zh":"昨天我朋友出了车祸。","fr":"Hier, mon ami a eu un accident de voiture.","alt":"Mon ami a eu un accident de voiture hier.","note":"「出事故」用 avoir un accident，不用 faire。"}},
 "Un formateur / Une formatrice": {"pos":"n.m./f. 名词，阳 formateur，阴 formatrice，复数 formateurs / formatrices","s":"培训师；教员（给成人做职业培训的人）。和 professeur（学校老师）不同，formateur 多用于企业、机构的培训。","ipa":"[fɔʁ.ma.tœʁ] / [fɔʁ.ma.tʁis]","ph":"o 读 [ɔ]；-eur [œʁ]，阴性 -trice 读 [tʁis]，c 读 [s]。","pi":"formateur 的 -eur 读 [œʁ]，r 要发；阴性 formatrice 结尾 e 不发音。","et":"来自 former（培养、塑造），拉丁语 formare；-ateur 表示做这件事的人。","ex":[["Le formateur est très gentil.","培训师很友善。"],["Ma formatrice parle clairement.","我的培训师讲得很清楚。"],["Il est formateur dans une grande entreprise.","他在一家大公司做培训师。"]],"co":[["un formateur en informatique","电脑培训师"],["une formatrice de français","法语培训师"],["devenir formateur","成为培训师"]],"sy":[["professeur","courant","老师（学校）"],["instructeur","courant","教练、指导员"]],"fq":"中频，工作与学习场景。","me":"former（培养）+ -ateur：培养别人的人。","tr":{"zh":"我们的培训师明天来。","fr":"Notre formatrice arrive demain.","alt":"La formatrice vient demain.","note":"阴性用 formatrice，不是 formateuse。"}},
 "Une tisane / Une infusion": {"pos":"n.f. 阴性名词，复数 tisanes / infusions","s":"花草茶；草本茶，不含茶叶、多无咖啡因，常在晚上或不舒服时喝。une infusion 更通用，指用热水泡出来的任何植物饮品（包括茶）。","ipa":"[ti.zan] / [ɛ̃.fy.zjɔ̃]","ph":"tisane：s 在两元音之间读 [z]；infusion：in 读 [ɛ̃]，u [y]，sion 读 [zjɔ̃]。","pi":"tisane 的 s 读 [z]，不是 [s]；infusion 的 -sion 读 [zjɔ̃]，别读 [ʃɔ̃]。","et":"tisane 来自希腊语 ptisanê（大麦水）；infusion 来自拉丁语 infundere（倒入、泡）。","ex":[["Je bois une tisane le soir.","晚上我喝花草茶。"],["Tu veux une infusion à la menthe ?","你要薄荷茶吗？"],["Cette tisane aide à dormir.","这种花草茶助眠。"]],"co":[["une tisane à la menthe / au tilleul","薄荷茶 / 椴树茶"],["faire une infusion","泡一杯茶"],["boire une tisane","喝花草茶"]],"sy":[["thé","courant","茶（含茶叶，有咖啡因）"],["décoction","soutenu","煎煮的草药汁"]],"fq":"中频，日常与饮食话题。","me":"tisane：像「提神」的反面，是晚上喝的助眠茶。","tr":{"zh":"我睡前喝一杯花草茶。","fr":"Je bois une tisane avant de dormir.","alt":"Avant de me coucher, je prends une infusion.","note":"avant de + 动词原形，表示「……之前」。"}},
 "Alerter": {"pos":"v. 动词，第一组 -er，助动词 avoir；alerter qqn","s":"报警；通知；提醒（有危险的人）。alerter la police = 报警，也可用于提醒人注意风险：alerter l'opinion（引起公众关注）。","ipa":"[a.lɛʁ.te]","ph":"al-er-ter；er 在音节中读 [ɛʁ]；结尾 -er 读 [e]。","pi":"结尾 -er 读 [e]，r 不发音；中间的 er 要发 [ɛʁ]。","et":"来自意大利语 all'erta（在警戒中），再来自 erta（高处、瞭望）。名词 alerte。","ex":[["Il faut alerter la police.","要报警。"],["J'ai alerté mes voisins.","我通知了邻居。"],["Il alerte les secours.","他通知救援队。"]],"co":[["alerter la police / les pompiers","报警 / 叫消防员"],["alerter les médias","通知媒体"],["une alerte","警报"]],"sy":[["prévenir","courant","通知、告知"],["avertir","soutenu","警告、提醒"]],"fq":"中频，紧急话题常用。","me":"alerter ← alerte：看到「警报」就是 alerter。","tr":{"zh":"我马上通知消防员。","fr":"J'alerte tout de suite les pompiers.","alt":"Je préviens les pompiers tout de suite.","note":"alerter + 直接宾语（人 / 机构）。"}},
 "Approuver": {"pos":"v. 动词，第一组 -er，助动词 avoir；approuver qqch / qqn","s":"赞成；同意；批准。approuver une décision = 赞成一个决定；也可表示官方批准：approuver un plan。","ipa":"[a.pʁu.ve]","ph":"pp 读一个 [p]；ou [u]；结尾 -er 读 [e]。","pi":"pp 只发一个 [p]；ou 是 [u]；别把 -er 读成 [ɛʁ]。","et":"来自拉丁语 approbare（认可），prob- 同 prouver（证明）。名词 approbation。","ex":[["J'approuve cette décision.","我同意这个决定。"],["Mes parents n'approuvent pas mon choix.","我父母不赞成我的选择。"],["Le conseil a approuvé le projet.","委员会批准了这个项目。"]],"co":[["approuver une idée","赞成一个想法"],["approuver un projet","批准项目"],["approuver de la tête","点头赞同"]],"sy":[["être d'accord","courant","同意（更口语）"],["désapprouver","soutenu","反对、不赞成（反义）"]],"fq":"中频，书面和日常都用。","me":"approuver 里有 prouver：证明对，所以「赞成」。","tr":{"zh":"我完全赞成你的想法。","fr":"J'approuve complètement ton idée.","alt":"Je suis tout à fait d'accord avec ton idée.","note":"approuver 后直接接宾语，不加介词 de。"}},
 "Conseiller": {"pos":"v. 动词，第一组 -er，助动词 avoir；conseiller qqch à qqn / conseiller de + 原形","s":"建议；推荐。conseiller qqch à qqn = 向某人推荐某物；conseiller à qqn de faire = 建议某人做。名词 un conseiller / une conseillère 是「顾问」。","ipa":"[kɔ̃.sɛ.je]","ph":"on 鼻化 [ɔ̃]；ei 读 [ɛ]；ill 读 [j]；结尾 -er [e]。","pi":"conseiller 中 -eill- 读 [ɛj]，不要读 [l]；on 不是「翁」而是鼻化 [ɔ̃]。","et":"来自拉丁语 consiliare（商议），源于 consilium（商议）。名词 un conseil（建议）。","ex":[["Je vous conseille ce livre.","我推荐您这本书。"],["Je te conseille de dormir.","我建议你睡一会儿。"],["Qu'est-ce que tu me conseilles ?","你有什么建议给我？"]],"co":[["conseiller qqch à qqn","向某人推荐某物"],["conseiller de + 原形","建议做某事"],["Je te conseille de...","我建议你……"]],"sy":[["recommander","courant","推荐"],["suggérer","courant","提议"],["déconseiller","courant","不建议（反义）"]],"fq":"高频，日常常用。","me":"conseil（建议）加 -er，变成动词。","tr":{"zh":"我建议你去看医生。","fr":"Je te conseille d'aller voir un médecin.","alt":"À ta place, j'irais voir un médecin.","note":"conseiller à qqn de + 原形：人用 à，动作用 de。"}},
 "Déconseiller": {"pos":"v. 动词，第一组 -er，助动词 avoir；déconseiller qqch à qqn / déconseiller de + 原形","s":"劝阻；不推荐。déconseiller qqch à qqn = 劝某人别买 / 别做；常见被动形式 est déconseillé（不建议）。","ipa":"[de.kɔ̃.sɛ.je]","ph":"dé [de]；con [kɔ̃]；eill [ɛj]；结尾 -er [e]。","pi":"dé- 读 [de]，不是 [də]；其余发音同 conseiller。","et":"前缀 dé-（反向）加 conseiller（建议）= 反过来建议。","ex":[["Je déconseille ce restaurant.","我不建议去这家餐厅。"],["Je te déconseille de partir seul.","我劝你别一个人走。"],["Ce produit est déconseillé aux enfants.","这个产品不建议儿童使用。"]],"co":[["déconseiller qqch à qqn","劝某人别……"],["déconseiller de + 原形","不建议做……"],["être fortement déconseillé","强烈不建议"]],"sy":[["dissuader","soutenu","劝阻"],["conseiller","courant","建议（反义）"]],"fq":"中频，购物与健康话题常见。","me":"dé- + conseiller：反过来建议，就是劝你别去。","tr":{"zh":"医生劝我别吃太多糖。","fr":"Le médecin me déconseille de manger trop de sucre.","alt":"Le médecin m'a dit d'éviter le sucre.","note":"déconseiller à qqn de + 原形。"}},
 "Digérer": {"pos":"v. 动词，第一组 -er，助动词 avoir；变位：je digère, nous digérons","s":"消化。也用于比喻：难以接受、消化不了某个消息，如 Je n'ai pas digéré cette nouvelle（我没法接受这个消息）。","ipa":"[di.ʒe.ʁe]","ph":"g 在 é 前读 [ʒ]；é [e]；r [ʁ]；结尾 -er [e]。","pi":"g 读 [ʒ]，不是 [g]；变位时重音符号变化：je digère, nous digérons。","et":"来自拉丁语 digerere（分开、消化）。名词 la digestion（消化），形容词 digestif。","ex":[["J'ai du mal à digérer.","我消化不良。"],["Je ne digère pas le lait.","我消化不了牛奶。"],["Il n'a pas digéré son échec.","他没能接受自己的失败。"]],"co":[["bien / mal digérer","消化好 / 消化不好"],["avoir du mal à digérer","难以消化"],["digérer une nouvelle","接受某消息"]],"sy":[["assimiler","soutenu","吸收、消化（也指知识）"],["supporter","courant","忍受"]],"fq":"中频，健康话题常用。","me":"digérer → digestion：看到 -tion 想到「消化」。","tr":{"zh":"我吃太多，消化不了。","fr":"J'ai trop mangé, je digère mal.","alt":"J'ai trop mangé, j'ai du mal à digérer.","note":"digérer 的变位：je digère，nous digérons。"}},
 "Estimer": {"pos":"v. 动词，第一组 -er，助动词 avoir；estimer qqch / estimer que...","s":"估计；估价；认为。estimer le prix = 估价；j'estime que... = 我认为……（较书面）；也可表示「尊重」：estimer qqn。","ipa":"[ɛs.ti.me]","ph":"es 读 [ɛs]；t 读 [t]；i [i]；结尾 -er [e]。","pi":"开头 es- 读 [ɛs]，不是「艾斯」；别漏掉 s。","et":"来自拉丁语 aestimare（估价）。同源：英语 estimate；名词 une estimation。","ex":[["Je vais estimer le prix.","我来估一下价格。"],["J'estime que c'est trop cher.","我认为这太贵了。"],["On estime la distance à dix kilomètres.","据估计距离是十公里。"]],"co":[["estimer le prix","估价"],["estimer que + 陈述句","认为……"],["être estimé","受尊敬"]],"sy":[["évaluer","courant","评估"],["penser","courant","认为"],["juger","soutenu","判断"]],"fq":"中频，书面和工作中常见。","me":"estimer ≈ 英语 estimate，一个意思：估算。","tr":{"zh":"我估计这需要两个小时。","fr":"J'estime que ça va prendre deux heures.","alt":"Je pense que ça prendra deux heures.","note":"estimer que 后面用陈述式。"}},
 "Être allergique à": {"pos":"loc. 动词短语，être 变位；allergique 为 adj.，阴性 allergique 不变，复数 allergiques","s":"对……过敏。后接 à + 名词：Il est allergique à la poussière。allergique 阴阳性同形，只加 s 变复数。","ipa":"[ɛtʁ a.lɛʁ.ʒik a]","ph":"allergique：ll 读 [l]；er 读 [ɛʁ]；g 读 [ʒ]；-ique 读 [ik]；à 单独读 [a]。","pi":"allergique 的 g 读 [ʒ]；结尾 -ique 读 [ik]，e 不发音；à 后接 les 要变 aux，接 le 变 au。","et":"allergie 来自希腊语 allos（其他）+ ergon（作用）：异常反应。","ex":[["Je suis allergique aux chats.","我对猫过敏。"],["Elle est allergique à la pénicilline.","她对青霉素过敏。"],["Tu es allergique aux noix ?","你对坚果过敏吗？"]],"co":[["allergique au pollen","对花粉过敏"],["allergique aux arachides","对花生过敏"],["une réaction allergique","过敏反应"]],"sy":[["intolérant à","courant","不耐受（不等于过敏）"]],"fq":"中频，健康话题必备。","me":"allergique à + 对象：à 就是「对」。","tr":{"zh":"我儿子对花生过敏。","fr":"Mon fils est allergique aux arachides.","alt":"Mon fils fait une allergie aux cacahuètes.","note":"à + les 合并成 aux。"}},
 "Éviter": {"pos":"v. 动词，第一组 -er，助动词 avoir；éviter qqch / éviter de + 原形","s":"避免；躲开。éviter le sucre = 避免吃糖；éviter de faire = 避免做某事；éviter qqn = 躲着某人。","ipa":"[e.vi.te]","ph":"é [e]；v [v]；i [i]；结尾 -er [e]。","pi":"éviter + 原形时用 de：éviter de fumer；别写成 éviter fumer。","et":"来自拉丁语 evitare（避开）。","ex":[["Il faut éviter le sucre.","要避免糖。"],["Évitez de sortir la nuit.","请避免夜间外出。"],["J'évite les embouteillages.","我躲开塞车。"]],"co":[["éviter de + 原形","避免做……"],["éviter un accident","避免事故"],["éviter les heures de pointe","避开高峰期"]],"sy":[["esquiver","soutenu","躲闪"],["fuir","courant","逃避"]],"fq":"高频，日常常用。","me":"éviter ≈ 英语 evade：躲开。","tr":{"zh":"请避免在这里吸烟。","fr":"Évitez de fumer ici, s'il vous plaît.","alt":"Ne fumez pas ici, s'il vous plaît.","note":"éviter de + 原形。"}},
 "Fumer": {"pos":"v. 动词，第一组 -er，助动词 avoir","s":"吸烟；抽烟。可不带宾语（Il fume），也可带宾语（fumer une cigarette）。也有「冒烟」「熏制」的意思。","ipa":"[fy.me]","ph":"f [f]；u 读 [y]（嘴唇拢圆发「衣」）；m [m]；结尾 -er [e]。","pi":"u 是 [y]，不是 [u]；il fume 与 ils fument 同音。","et":"来自拉丁语 fumare（冒烟），源于 fumus（烟）。名词 la fumée（烟）。","ex":[["Il est interdit de fumer ici.","这里禁止吸烟。"],["Mon père ne fume plus.","我爸爸不再抽烟了。"],["Tu fumes beaucoup ?","你抽很多烟吗？"]],"co":[["fumer une cigarette","抽一支烟"],["arrêter de fumer","戒烟"],["zone non-fumeur","禁烟区"]],"sy":[["griller une clope","argot","抽一根烟（俚语）"]],"fq":"高频，日常常用。","me":"fumer ← fumée：冒烟的动作。","tr":{"zh":"我已经戒烟了。","fr":"J'ai arrêté de fumer.","alt":"Je ne fume plus.","note":"arrêter de + 原形：戒掉……"}},
 "Prescrire": {"pos":"v. 动词，不规则（第三组），助动词 avoir；过去分词 prescrit；变位同 écrire","s":"开处方；规定。le médecin prescrit un médicament = 医生开药；也可指正式规定：prescrire des règles。","ipa":"[pʁɛs.kʁiʁ]","ph":"pres 读 [pʁɛs]；cr 读 [kʁ]；结尾 -ire 读 [iʁ]。","pi":"变位同 écrire：je prescris, il prescrit, nous prescrivons；过去分词是 prescrit，不是 prescrité。","et":"来自拉丁语 praescribere（预先写下）：pré- 前 + scribere 写。","ex":[["Le médecin va prescrire un sirop.","医生会开糖浆。"],["Il m'a prescrit des antibiotiques.","他给我开了抗生素。"],["Cette règle est prescrite par la loi.","这条规则由法律规定。"]],"co":[["prescrire un médicament","开药"],["une ordonnance","处方"],["prescrire du repos","建议休息"]],"sy":[["ordonner","courant","(医生)嘱咐"],["recommander","courant","推荐"]],"fq":"中频，医疗话题常用。","me":"pré- + écrire：事先写下的就是处方。","tr":{"zh":"医生给我开了药。","fr":"Le médecin m'a prescrit des médicaments.","alt":"Le médecin m'a fait une ordonnance.","note":"过去分词 prescrit，和 écrit 同型。"}},
 "Protéger": {"pos":"v. 动词，第一组 -er，助动词 avoir；变位：je protège, nous protégeons","s":"保护；保卫。protéger qqn de/contre qqch = 保护某人免受……；也可指保护环境：protéger la nature。","ipa":"[pʁɔ.te.ʒe]","ph":"pro 读 [pʁɔ]；té [te]；g 在 e 前读 [ʒ]；结尾 -er [e]。","pi":"变位时重音与 g 的写法：je protège, nous protégeons（在 o 前加 e 保持 [ʒ]）。","et":"来自拉丁语 protegere（遮盖、保护）：pro- 在前 + tegere 遮盖。","ex":[["Ce manteau me protège du froid.","这件大衣保护我不受寒。"],["Il faut protéger la nature.","要保护大自然。"],["Elle protège son frère.","她保护她弟弟。"]],"co":[["protéger du froid / du soleil","防寒 / 防晒"],["protéger l'environnement","保护环境"],["se protéger","保护自己"]],"sy":[["défendre","courant","保卫"],["abriter","courant","遮蔽"]],"fq":"中高频，日常常用。","me":"pro-（前面）+ teg（盖）：盖在前面保护你。","tr":{"zh":"这顶帽子能防晒。","fr":"Ce chapeau me protège du soleil.","alt":"Avec ce chapeau, je suis à l'abri du soleil.","note":"protéger qqn de qqch。"}},
 "Rembourser": {"pos":"v. 动词，第一组 -er，助动词 avoir；rembourser qqn / qqch","s":"退还；偿还；报销。le magasin rembourse le client = 商店退款给顾客；la Sécurité sociale rembourse les soins = 医保报销医疗费。","ipa":"[ʁɑ̃.buʁ.se]","ph":"rem 读鼻化音 [ʁɑ̃]；b [b]；our 读 [uʁ]；s 读 [s]；结尾 -er [e]。","pi":"rem- 读 [ʁɑ̃]，不是 [ʁɛm]；ou 是 [u]；不要和 emprunter（借入）混淆。","et":"由前缀 re- 加 embourser（把钱放进钱包）而来，bourse 为「钱包」。同源：bourse（奖学金；证券交易所）。","ex":[["Le magasin va me rembourser.","商店会退款给我。"],["La mutuelle rembourse les médicaments.","互助保险报销药费。"],["Je dois rembourser mon ami.","我得还朋友钱。"]],"co":[["se faire rembourser","要求退款"],["rembourser un prêt","还贷款"],["un remboursement","退款；报销"]],"sy":[["restituer","soutenu","归还"],["payer","courant","支付"]],"fq":"中频，购物与医疗话题。","me":"re- + bourse（钱包）：把钱放回你的钱包。","tr":{"zh":"我想让他们退款。","fr":"Je voudrais me faire rembourser.","alt":"Je veux qu'on me rembourse.","note":"se faire rembourser = 要求退款 / 获得退款。"}},
 "Respirer": {"pos":"v. 动词，第一组 -er，助动词 avoir","s":"呼吸。respirer profondément = 深呼吸；也可表示「松一口气」：Je respire enfin。","ipa":"[ʁɛs.pi.ʁe]","ph":"res 读 [ʁɛs]；pi [pi]；r [ʁ]；结尾 -er [e]。","pi":"开头 re 读 [ʁɛ]，不是 [ʁə]；两个 r 都要发。","et":"来自拉丁语 respirare（再次呼吸）：re- 重复 + spirare 呼吸。同源：inspirer（吸气）、expirer（呼气）、respiration（呼吸）。","ex":[["Il faut bien respirer.","要好好呼吸。"],["Respire profondément !","深呼吸！"],["Je respire mal avec ce rhume.","我感冒了，呼吸不顺。"]],"co":[["respirer profondément","深呼吸"],["respirer par le nez","用鼻子呼吸"],["la respiration","呼吸"]],"sy":[["inspirer","courant","吸气"],["expirer","courant","呼气"]],"fq":"中高频，日常常用。","me":"respirer ≈ respiration：呼吸。","tr":{"zh":"慢慢呼吸，别紧张。","fr":"Respire lentement, ne stresse pas.","alt":"Respire doucement, calme-toi.","note":"祈使句 tu 形式去掉 s：respire。"}},
 "Ronfler": {"pos":"v. 动词，第一组 -er，助动词 avoir","s":"打鼾；打呼噜。也可指发动机、炉子发出低沉的轰鸣声。","ipa":"[ʁɔ̃.fle]","ph":"r [ʁ]；on 鼻化 [ɔ̃]；f [f]；l [l]；结尾 -er [e]。","pi":"on 是鼻化音 [ɔ̃]；fl 连读 [fl]，中间不加元音。","et":"拟声词，来自模仿声音；同家族：ronronner（猫打呼噜）。","ex":[["Mon père ronfle beaucoup.","我爸爸打鼾很厉害。"],["Tu ronfles la nuit !","你夜里打鼾！"],["Il ronfle déjà dans le train.","他在火车上已经在打鼾了。"]],"co":[["ronfler fort","打鼾很响"],["un ronflement","鼾声"],["ronfler comme un sonneur","鼾声如雷"]],"sy":[["ronronner","courant","(猫)打呼噜，不是人"]],"fq":"中低频，日常口语。","me":"ronfler 的 r-on-fl 像鼾声的节奏。","tr":{"zh":"我老公打鼾，我睡不着。","fr":"Mon mari ronfle, je n'arrive pas à dormir.","alt":"Mon mari ronfle trop, je ne dors pas.","note":"ne pas arriver à + 原形：做不到。"}},
 "S'étirer": {"pos":"v. 代词式动词（第一组 -er），助动词 être；je m'étire, tu t'étires","s":"伸展；伸懒腰；拉伸身体。起床或运动时常用：s'étirer le matin。","ipa":"[se.ti.ʁe]","ph":"s' 读 [s]；é [e]；t [t]；i [i]；r [ʁ]；结尾 -er [e]。","pi":"代词式动词要带反身代词：je m'étire, tu t'étires；复合时过去分词与主语配合。","et":"来自 étirer（拉长），源于 tirer（拉）加前缀 é-。","ex":[["J'aime m'étirer le matin.","我喜欢早上伸懒腰。"],["Le chat s'étire sur le canapé.","猫在沙发上伸懒腰。"],["Étirez-vous avant le sport.","运动前请先拉伸。"]],"co":[["s'étirer les jambes","拉伸双腿"],["s'étirer en se levant","起床时伸懒腰"],["un étirement","拉伸"]],"sy":[["s'allonger","courant","躺下、伸长"],["se détendre","courant","放松"]],"fq":"中低频，日常与运动话题。","me":"s'étirer：像拉 tire-bouchon，把身体拉开。","tr":{"zh":"运动前先拉伸一下。","fr":"Étirez-vous un peu avant de faire du sport.","alt":"Avant le sport, on s'étire.","note":"代词式动词的祈使句：Étirez-vous。"}},
 "S'infecter": {"pos":"v. 代词式动词（第一组 -er），助动词 être；il s'infecte","s":"被感染；伤口发炎。常用于伤口、割伤：La plaie s'infecte。","ipa":"[sɛ̃.fɛk.te]","ph":"s' 读 [s]；in 读 [ɛ̃]；f [f]；ec 读 [ɛk]；结尾 -er [e]。","pi":"in 读鼻化音 [ɛ̃]；infecter 的 -ct- 都发音：[fɛk.te]。","et":"来自拉丁语 inficere（浸染），名词 une infection（感染）。","ex":[["La plaie risque de s'infecter.","伤口有可能感染。"],["Sa blessure s'est infectée.","他的伤口感染了。"],["Désinfectez pour éviter que ça s'infecte.","请消毒，免得感染。"]],"co":[["risquer de s'infecter","有感染的风险"],["une plaie infectée","感染的伤口"],["désinfecter une plaie","给伤口消毒"]],"sy":[["s'enflammer","courant","发炎"],["contracter","soutenu","染上(疾病)"]],"fq":"中低频，医疗话题。","me":"infecter ≈ infect：英语同源，是「感染」。","tr":{"zh":"如果不消毒，伤口会感染。","fr":"Si tu ne désinfectes pas, la plaie va s'infecter.","alt":"Sans désinfectant, la plaie risque de s'infecter.","note":"risquer de + 原形：有……的风险。"}},
 "Se brûler": {"pos":"v. 代词式动词（第一组 -er），助动词 être；je me brûle","s":"烫伤自己；灼伤。se brûler la main = 烫伤手（身体部位前用定冠词）。brûler 本身指「燃烧；烧焦」。","ipa":"[sə bʁy.le]","ph":"se 读 [sə]；br [bʁ]；û 读 [y]；l [l]；结尾 -er [e]。","pi":"û 仍读 [y]；注意 se brûler la main，不写 sa main。过去：Je me suis brûlé la main，分词不配合。","et":"来源不确定（brûler 的词源学界有争议）。同族词：brûlure（烧伤）、brûlant（滚烫的）。","ex":[["Fais attention à ne pas te brûler.","小心别烫到自己。"],["Je me suis brûlé la main.","我烫伤了手。"],["Il s'est brûlé avec la soupe.","他被汤烫到了。"]],"co":[["se brûler la main","烫伤手"],["se brûler avec de l'eau chaude","被开水烫到"],["une brûlure","烫伤"]],"sy":[["s'ébouillanter","courant","被开水烫"],["s'échauder","soutenu","被热水烫伤（较书面）"]],"fq":"中频，日常与家庭话题。","me":"brûler = 烧，se brûler = 烧到自己。","tr":{"zh":"小心，别烫到手。","fr":"Attention, ne te brûle pas la main.","alt":"Fais gaffe, tu vas te brûler la main.","note":"身体部位前用定冠词，不用 ta / ma。"}},
 "Se dégrader": {"pos":"v. 代词式动词（第一组 -er），助动词 être；il se dégrade","s":"恶化；变差；损坏。la situation se dégrade = 局势恶化；也用于天气、健康、关系变差。","ipa":"[sə de.ɡʁa.de]","ph":"se [sə]；dé [de]；gr 读 [ɡʁ]；a [a]；d [d]；结尾 -er [e]。","pi":"gr 读 [ɡʁ]，别读成 [ʒʁ]；dégrader 的 g 在 r 前读 [ɡ]。","et":"来自拉丁语 degradare：de- 向下 + gradus（级、台阶），指「降级」。同源：grade（等级）。","ex":[["La situation se dégrade.","情况正在恶化。"],["Sa santé se dégrade vite.","他的健康迅速恶化。"],["Le temps se dégrade ce soir.","今晚天气会变坏。"]],"co":[["la situation se dégrade","情况恶化"],["le temps se dégrade","天气变坏"],["une dégradation","恶化；损坏"]],"sy":[["empirer","courant","变糟"],["s'aggraver","courant","加重"],["s'améliorer","courant","好转（反义）"]],"fq":"中频，新闻与健康话题。","me":"dé- + grade：往下降一级，所以变差。","tr":{"zh":"他的健康正在恶化。","fr":"Sa santé se dégrade.","alt":"Son état empire.","note":"代词式动词表示「自己变坏」。"}},
 "Soulager": {"pos":"v. 动词，第一组 -er，助动词 avoir；变位：je soulage, nous soulageons；se soulager 表示「减轻自己」","s":"缓解；减轻（疼痛、压力）；让人放心。soulager la douleur = 缓解疼痛；être soulagé = 松了一口气。","ipa":"[su.la.ʒe]","ph":"ou 读 [u]；l [l]；a [a]；g 读 [ʒ]；结尾 -er [e]。","pi":"nous soulageons 要加 e 保持 [ʒ]；soulagé 阴性 soulagée，复数 soulagés。","et":"来自拉丁语 subleviare（使变轻）；同源 léger（轻）。","ex":[["Oh là là j'ai vraiment eu peur. Maintenant je suis soulagé.","天哪，我真的很害怕。现在我松了一口气。"],["Ce médicament soulage la douleur.","这种药能缓解疼痛。"],["Cela me soulage de le savoir.","知道这点我就放心了。"]],"co":[["soulager la douleur","缓解疼痛"],["être soulagé","松了一口气"],["un soulagement","缓解；宽慰"]],"sy":[["calmer","courant","镇静、缓和"],["apaiser","soutenu","安抚"]],"fq":"中频，日常与健康话题。","me":"sou- + léger（轻）：让负担变轻。","tr":{"zh":"这种药能缓解头痛。","fr":"Ce médicament soulage le mal de tête.","alt":"Ce médicament calme mon mal de tête.","note":"形容词 soulagé 作表语：Je suis soulagé。"}},
 "Tousser": {"pos":"v. 动词，第一组 -er，助动词 avoir","s":"咳嗽。名词是 la toux（咳嗽）。tousser un peu / beaucoup = 轻 / 重咳。","ipa":"[tu.se]","ph":"t [t]；ou [u]；ss 读 [s]；结尾 -er [e]。","pi":"ou 读 [u]；ss 是清音 [s]，不要读成 [z]；动词 tousser 与名词 toux 拼写不同。","et":"来自拉丁语 tussire（咳嗽），源于 tussis（咳嗽）。","ex":[["Il n'arrête pas de tousser.","他一直在咳嗽。"],["Je tousse depuis deux jours.","我已经咳嗽两天了。"],["Elle tousse la nuit.","她夜里咳嗽。"]],"co":[["tousser fort","咳得厉害"],["n'arrête pas de tousser","不停咳嗽"],["une toux sèche / grasse","干咳 / 有痰咳嗽"]],"sy":[["s'éclaircir la gorge","courant","清嗓子"]],"fq":"中频，健康话题。","me":"tousser ← toux，tou(x) 的声音就像咳嗽。","tr":{"zh":"我感冒了，一直咳嗽。","fr":"Je suis enrhumé et je tousse tout le temps.","alt":"J'ai un rhume, je tousse sans arrêt.","note":"tout le temps = 一直。"}},
 "Allongé(e)": {"pos":"adj. 形容词，阳 allongé，阴 allongée，复数 allongés / allongées","s":"躺着的；伸长的。表示人的姿势：être allongé sur le lit。过去分词 allongé 来自 allonger（拉长、使躺下）。","ipa":"[a.lɔ̃.ʒe]","ph":"a [a]；l [l]；on 鼻化 [ɔ̃]；g 读 [ʒ]；é [e]。阴性 -ée 读音同。","pi":"on 读 [ɔ̃]，不是「昂」；性数配合：elle est allongée。","et":"来自 allonger（伸长），源于 long（长）加前缀 a-。","ex":[["Il est allongé sur le lit.","他躺在床上。"],["Elle reste allongée toute la journée.","她一整天都躺着。"],["Restez allongé, s'il vous plaît.","请保持躺着。"]],"co":[["être allongé sur le dos / le côté","仰躺 / 侧躺"],["rester allongé","一直躺着"],["s'allonger","躺下"]],"sy":[["couché","courant","躺着的（睡觉）"],["étendu","soutenu","平躺的"]],"fq":"中频，健康与日常话题。","me":"a-long-é：长长地躺着。","tr":{"zh":"请躺着别动。","fr":"Restez allongé, ne bougez pas.","alt":"Ne bougez pas, restez allongé.","note":"对女性说 Restez allongée。"}},
 "Antiseptique": {"pos":"adj./n.m. 形容词，阴阳同形 antiseptique，复数 antiseptiques","s":"抗菌的；消毒的。un antiseptique = 消毒剂。用于伤口、手部：une crème antiseptique。","ipa":"[ɑ̃.ti.sɛp.tik]","ph":"an 读 [ɑ̃]；ti [ti]；sep 读 [sɛp]；tique 读 [tik]。","pi":"an 读鼻化 [ɑ̃]；p 要发：[sɛp.tik]；e 在 ep 中读 [ɛ]。","et":"来自希腊语 anti（反）+ septikos（使腐烂的）。同源：英语 antiseptic。","ex":[["Utilisez un spray antiseptique.","请使用抗菌喷雾。"],["Cette crème est antiseptique.","这种药膏有消毒作用。"],["J'ai acheté un antiseptique.","我买了一瓶消毒剂。"]],"co":[["un spray antiseptique","抗菌喷雾"],["une crème antiseptique","消毒药膏"],["un produit antiseptique","消毒产品"]],"sy":[["désinfectant","courant","消毒剂"],["antibactérien","courant","抗菌的"]],"fq":"中低频，医疗话题。","me":"anti- + septique：对抗腐败。","tr":{"zh":"我在伤口上涂了消毒药膏。","fr":"J'ai mis une crème antiseptique sur la plaie.","alt":"J'ai appliqué un antiseptique sur ma blessure.","note":"mettre sur = 涂在……上。"}},
 "Copieux / Copieuse": {"pos":"adj. 形容词，阳 copieux，阴 copieuse，复数 copieux / copieuses","s":"丰盛的；量大的。多用于饭菜：un repas copieux。与 riche 不同，copieux 强调分量多。","ipa":"[kɔ.pjø] / [kɔ.pjøz]","ph":"c 读 [k]；o 读 [ɔ]；pie 读 [pjø]；阴性结尾 -euse 读 [øz]。","pi":"阳性 copieux 的 x 不发音；阴性 copieuse 的 s 读 [z]。","et":"来自拉丁语 copiosus（富足的），源于 copia（丰富）。同源：英语 copious。","ex":[["C'est un repas copieux.","这是丰盛的一餐。"],["Le petit-déjeuner est copieux.","早餐很丰盛。"],["Elle prépare une salade copieuse.","她做了一份分量很足的沙拉。"]],"co":[["un repas copieux","丰盛的一餐"],["un petit-déjeuner copieux","丰盛的早餐"],["une portion copieuse","分量足的一份"]],"sy":[["abondant","soutenu","丰富的"],["généreux","courant","分量大方的"]],"fq":"中低频，饮食话题。","me":"copieux ≈ copious：量大。","tr":{"zh":"这份早餐很丰盛。","fr":"Ce petit-déjeuner est vraiment copieux.","alt":"Le petit-déjeuner est bien copieux.","note":"形容词与名词性数配合：une portion copieuse。"}},
 "Corporel(le)": {"pos":"adj. 形容词，阳 corporel，阴 corporelle，复数 corporels / corporelles","s":"身体的；肉体的。soins corporels = 身体护理；expression corporelle = 肢体表达。不同于 physique 的广义「物理的」。","ipa":"[kɔʁ.pɔ.ʁɛl]","ph":"cor 读 [kɔʁ]；po [pɔ]；rel 读 [ʁɛl]；阴性 -elle 读 [ɛl]，e 不发音。","pi":"两个 r 都要发；阴性 corporelle 读音与阳性相同。","et":"来自拉丁语 corporalis，源于 corpus（身体）。同源：corps、corpulent。","ex":[["C'est un soin corporel.","这是身体护理。"],["Il fait de l'expression corporelle.","他练习肢体表达。"],["Elle a une hygiène corporelle impeccable.","她的个人卫生无可挑剔。"]],"co":[["l'hygiène corporelle","个人卫生"],["les soins corporels","身体护理"],["l'expression corporelle","肢体表达"]],"sy":[["physique","courant","身体的；物理的"],["charnel","littéraire","肉体的、肉欲的"]],"fq":"中低频，健康与美容话题。","me":"corp(s) + -orel：关于身体。","tr":{"zh":"个人卫生很重要。","fr":"L'hygiène corporelle est très importante.","alt":"Il est important de bien se laver.","note":"hygiène 阴性，所以 corporelle。"}},
 "Enrhumé(e)": {"pos":"adj. 形容词，阳 enrhumé，阴 enrhumée，复数 enrhumés / enrhumées","s":"感冒的；伤风的。être enrhumé = 感冒了。名词 un rhume；动词 s'enrhumer（感冒）。","ipa":"[ɑ̃.ʁy.me]","ph":"en 读 [ɑ̃]；rh 读 [ʁ]（h 不发音）；u [y]；mé [me]。","pi":"rh 中的 h 不发音；u 读 [y]；别与 un rhume 的 rhume [ʁym] 混淆。","et":"来自 rhume（感冒），源于希腊语 rheuma（流动），加前缀 en- 构成形容词。","ex":[["Je suis un peu enrhumé.","我有点感冒。"],["Elle est enrhumée depuis lundi.","她从周一起感冒了。"],["Vous êtes enrhumés ?","你们感冒了吗？"]],"co":[["être enrhumé","感冒"],["un peu enrhumé","有点感冒"],["attraper un rhume","得感冒"]],"sy":[["grippé","courant","得流感的"],["avoir un rhume","courant","感冒（更常用）"]],"fq":"中频，健康话题。","me":"en + rhume：身上带着感冒。","tr":{"zh":"我感冒了，不想出门。","fr":"Je suis enrhumé, je n'ai pas envie de sortir.","alt":"J'ai un rhume, je reste à la maison.","note":"être enrhumé / avoir un rhume 都可以。"}},
 "Inconscient(e)": {"pos":"adj. 形容词，阳 inconscient，阴 inconsciente，复数 inconscients / inconscientes","s":"昏迷的；失去意识的；无意识的。也指「轻率的、不顾后果的」：Tu es inconscient !（你太不负责了！）。","ipa":"[ɛ̃.kɔ̃.sjɑ̃]","ph":"in 读 [ɛ̃]；con 读 [kɔ̃]；scient 读 [sjɑ̃]；阴性 -ente 读 [ɑ̃t]。","pi":"阳性 -ent 读 [ɑ̃]，t 不发音；sc 在 i 前读 [s]；注意阴性 inconsciente 的 t 要发音。","et":"来自拉丁语 in-（否定）+ conscius（知道的）。同源：conscient（有意识的）。","ex":[["Le blessé est inconscient.","伤者昏迷了。"],["Elle est tombée, elle est inconsciente.","她摔倒了，已失去意识。"],["Tu es inconscient de conduire si vite !","你开这么快太不要命了！"]],"co":[["perdre connaissance","失去意识（更常用）"],["être inconscient du danger","没意识到危险"],["l'inconscient","潜意识"]],"sy":[["évanoui","courant","晕倒的"],["imprudent","courant","轻率的"],["conscient","courant","有意识的（反义）"]],"fq":"中频，医疗与新闻常用。","me":"in- + conscient：没有意识。","tr":{"zh":"他摔倒后失去了意识。","fr":"Après sa chute, il est inconscient.","alt":"Il est tombé et il a perdu connaissance.","note":"阴性 inconsciente 要发出 t。"}},
 "Moderne": {"pos":"adj. 形容词，阴阳同形 moderne，复数 modernes","s":"现代的；新式的。une maison moderne = 现代化的房子；l'art moderne = 现代艺术。","ipa":"[mɔ.dɛʁn]","ph":"m [m]；o 读 [ɔ]；der 读 [dɛʁ]；ne 读 [n]，结尾 e 不发音。","pi":"d 之后是 [ɛʁn]，不是 [dɛrn]；阴性同阳性，不加 e。","et":"来自晚期拉丁语 modernus，源于 modo（刚刚）。同源：英语 modern。","ex":[["Cette maison est très moderne.","这座房子很现代。"],["J'aime l'art moderne.","我喜欢现代艺术。"],["C'est une cuisine moderne.","这是个现代化厨房。"]],"co":[["l'art moderne","现代艺术"],["la vie moderne","现代生活"],["une cuisine moderne","现代化厨房"]],"sy":[["contemporain","soutenu","当代的"],["récent","courant","新的、最近的"],["ancien","courant","古老的（反义）"]],"fq":"高频，日常常用。","me":"moderne ≈ modern：词形几乎相同。","tr":{"zh":"他住在一间很现代的公寓里。","fr":"Il habite dans un appartement très moderne.","alt":"Son appartement est vraiment moderne.","note":"形容词放在名词之后。"}},
 "Musculaire": {"pos":"adj. 形容词，阴阳同形 musculaire，复数 musculaires","s":"肌肉的。une douleur musculaire = 肌肉疼痛；la masse musculaire = 肌肉量。","ipa":"[mys.ky.lɛʁ]","ph":"m [m]；u 读 [y]；s 读 [s]；c 读 [k]；aire 读 [ɛʁ]。","pi":"u 读 [y]，不是 [u]；结尾 -aire 读 [ɛʁ]，不要读 [e.ʁə]。","et":"来自拉丁语 musculus（小老鼠；肌肉），因肌肉跳动像小老鼠。名词 le muscle。","ex":[["C'est une douleur musculaire.","这是肌肉疼痛。"],["Il a une bonne masse musculaire.","他肌肉量很好。"],["La fatigue musculaire est normale.","肌肉疲劳很正常。"]],"co":[["une douleur musculaire","肌肉疼痛"],["la fatigue musculaire","肌肉疲劳"],["la masse musculaire","肌肉量"]],"sy":[["musclé","courant","肌肉发达的"]],"fq":"中低频，运动与健康话题。","me":"muscul-aire：来自 muscle。","tr":{"zh":"运动后我有肌肉酸痛。","fr":"Après le sport, j'ai des douleurs musculaires.","alt":"Après le sport, j'ai mal aux muscles.","note":"douleur 阴性，复数 douleurs。"}},
 "Naturel(le)": {"pos":"adj. 形容词，阳 naturel，阴 naturelle，复数 naturels / naturelles","s":"天然的；自然的；不做作的。un produit naturel = 天然产品；Il est naturel de... = 这很自然。","ipa":"[na.ty.ʁɛl]","ph":"na [na]；tu 读 [ty]；rel 读 [ʁɛl]；阴性 -elle 读 [ɛl]。","pi":"u 读 [y]；阴性 naturelle 双 l 但只读一个 [l]。","et":"来自拉丁语 naturalis，源于 natura（自然）。同源：英语 natural。","ex":[["Ce produit est naturel.","这个产品是天然的。"],["C'est tout à fait naturel.","这完全是自然的。"],["Elle a une beauté naturelle.","她有天然的美。"]],"co":[["un produit naturel","天然产品"],["la lumière naturelle","自然光"],["naturellement","自然地；当然"]],"sy":[["biologique","courant","有机的"],["artificiel","courant","人造的（反义）"]],"fq":"高频，日常常用。","me":"naturel ≈ natural。","tr":{"zh":"我只用天然的产品。","fr":"J'utilise seulement des produits naturels.","alt":"Je n'utilise que des produits naturels.","note":"ne… que = 只有。"}},
 "Profond(e)": {"pos":"adj. 形容词，阳 profond，阴 profonde，复数 profonds / profondes","s":"深的；深刻的。un sommeil profond = 深度睡眠；un lac profond = 深湖；une profonde tristesse = 深深的悲伤。","ipa":"[pʁɔ.fɔ̃] / [pʁɔ.fɔ̃d]","ph":"pro 读 [pʁɔ]；fond 读 [fɔ̃]，阳性 d 不发音；阴性 -onde 读 [ɔ̃d]，d 要发。","pi":"阳性 profond 的 d 不发音，阴性 profonde 的 d 要发音；on 是鼻化音 [ɔ̃]。","et":"来自拉丁语 profundus：pro- + fundus（底）。同源：fond、profondeur、英语 profound。","ex":[["C'est un sommeil profond.","这是深度睡眠。"],["Cette piscine est très profonde.","这个泳池很深。"],["Respirez profondément.","请深呼吸。"]],"co":[["un sommeil profond","深度睡眠"],["respirer profondément","深呼吸"],["une voix profonde","低沉的声音"]],"sy":[["intense","courant","强烈的"],["superficiel","courant","表面的（反义）"]],"fq":"中高频，日常常用。","me":"pro + fond：「底」就是 fond。","tr":{"zh":"这个湖很深。","fr":"Ce lac est très profond.","alt":"Ce lac est vraiment profond.","note":"阴性 profonde 的 d 要发音。"}},
 "Reposé(e)": {"pos":"adj. 形容词，阳 reposé，阴 reposée，复数 reposés / reposées","s":"休息好的；精神饱满的。se sentir reposé = 感觉休息好了。来自动词 se reposer（休息）。","ipa":"[ʁə.po.ze]","ph":"re 读 [ʁə]；po [po]；s 在两元音间读 [z]；é [e]。","pi":"s 读 [z]，不是 [s]；re- 弱读 [ʁə]；别和 repos（休息，名词）混淆。","et":"来自 reposer，由 re- + poser（放）构成，字面为「放下」。名词 le repos。","ex":[["Je me sens reposé.","我感觉精神饱满。"],["Elle a l'air reposée.","她看起来休息得很好。"],["Après les vacances, nous sommes reposés.","假期过后我们都休息好了。"]],"co":[["se sentir reposé","感觉休息好"],["avoir l'air reposé","看起来精神"],["bien reposé","休息得很好"]],"sy":[["en forme","courant","状态好"],["frais","courant","精神饱满的"],["fatigué","courant","累的（反义）"]],"fq":"中频，日常常用。","me":"repos + é：休息之后的状态。","tr":{"zh":"睡了十个小时，我感觉很精神。","fr":"J'ai dormi dix heures, je me sens reposé.","alt":"Après dix heures de sommeil, je suis bien reposé.","note":"se sentir + 形容词。"}},
 "Suffisant(e)": {"pos":"adj. 形容词，阳 suffisant，阴 suffisante，复数 suffisants / suffisantes","s":"足够的。C'est suffisant = 这就够了。也可指「自负的」（书面）：un air suffisant。","ipa":"[sy.fi.zɑ̃]","ph":"su 读 [sy]；ffi 读 [fi]；s 读 [z]；ant 读 [ɑ̃]；阴性 -ante 读 [ɑ̃t]。","pi":"suf-fi-sant 中间 s 读 [z]；ff 只发一个 [f]；阳性 -ant 读 [ɑ̃]，t 不发音。","et":"来自拉丁语 sufficiens，源于 sufficere（足够）。同源：suffire（足够）、英语 sufficient。","ex":[["Ce temps est suffisant.","这些时间足够了。"],["Deux heures, c'est suffisant.","两小时就够了。"],["Les preuves ne sont pas suffisantes.","证据不够。"]],"co":[["c'est suffisant","这就够了"],["pas suffisant","不够"],["suffisamment","足够地"]],"sy":[["assez","courant","够"],["insuffisant","courant","不足的（反义）"]],"fq":"中高频，日常常用。","me":"suffisant ≈ sufficient。","tr":{"zh":"这些钱够吗？","fr":"Est-ce que cet argent est suffisant ?","alt":"Ça suffit, cet argent ?","note":"suffire 是动词，suffisant 是形容词。"}},
 "Traditionnel(le)": {"pos":"adj. 形容词，阳 traditionnel，阴 traditionnelle，复数 traditionnels / traditionnelles","s":"传统的。un plat traditionnel = 传统菜；une fête traditionnelle = 传统节日。","ipa":"[tʁa.di.sjɔ.nɛl]","ph":"tra [tʁa]；di [di]；tion 读 [sjɔ]；nel 读 [nɛl]；阴性 -elle 读 [ɛl]。","pi":"-tionnel 读 [sjɔ.nɛl]：因为 nn 双写，on 不鼻化；双 n 与双 l 各只发一个音。","et":"来自 tradition（传统），源于拉丁语 traditio（传递）。","ex":[["C'est un plat traditionnel.","这是一道传统菜。"],["Nous faisons une fête traditionnelle.","我们办一场传统庆典。"],["Elle porte un costume traditionnel.","她穿着传统服装。"]],"co":[["un plat traditionnel","传统菜"],["une fête traditionnelle","传统节日"],["la médecine traditionnelle","传统医学"]],"sy":[["classique","courant","经典的"],["moderne","courant","现代的（反义）"]],"fq":"高频，日常常用。","me":"tradition + -nel：关于传统的。","tr":{"zh":"这是一道传统的法国菜。","fr":"C'est un plat français traditionnel.","alt":"C'est un plat traditionnel de chez nous.","note":"traditionnel 双 n；名词 tradition 只有一个 n。"}},
 "Doucement": {"pos":"adv. 副词，不变化","s":"轻轻地；慢慢地；温和地。parler doucement = 小声说话；Doucement ! = 慢点！","ipa":"[dus.mɑ̃]","ph":"d [d]；ou 读 [u]；c 读 [s]；e 不发音；ment 读 [mɑ̃]。","pi":"中间的 e 不发音：dou-ce-ment 读作 [dus.mɑ̃]；结尾 -ment 的 t 不发音。","et":"由形容词 doux（温和的）阴性 douce + -ment 构成副词。","ex":[["Parlez doucement, s'il vous plaît.","请小声说话。"],["Roule doucement, il y a du verglas.","开慢点，有结冰。"],["Il ferme doucement la porte.","他轻轻关上门。"]],"co":[["parler doucement","小声说话"],["Doucement !","慢点！"],["tout doucement","慢慢地"]],"sy":[["lentement","courant","慢慢地"],["calmement","courant","平静地"],["fort","courant","大声地（反义）"]],"fq":"高频，日常常用。","me":"douce + ment：温和地。","tr":{"zh":"请轻轻关门。","fr":"Fermez la porte doucement, s'il vous plaît.","alt":"Ferme la porte tout doucement.","note":"副词通常放在动词后面。"}},
 "\"Au secours !\" / \"À l'aide !\"": {"pos":"loc. 感叹语，不变化","s":"救命！紧急求助时喊的话。Au secours 与 À l'aide 意思相同，前者更常用；也可用于夸张：Au secours, j'ai oublié mes clés !","ipa":"[o sə.kuʁ] / [a lɛd]","ph":"Au 读 [o]；secours 读 [sə.kuʁ]，s 不发音；aide 读 [ɛd]，ai 读 [ɛ]。","pi":"secours 的结尾 s 不发音；à l'aide 读 [a lɛd]：l' 与 aide 连成一个音节，ai 读 [ɛ]，e 不发音。","et":"secours 源于 secourir，拉丁语 succurrere（跑去帮助）；aide 来自 aider，拉丁语 adjutare（帮助）。","ex":[["Il a crié \"Au secours !\".","他大喊「救命！」。"],["À l'aide ! Quelqu'un m'entend ?","救命！有人听见吗？"],["Au secours, je suis en retard !","天啊，我迟到了！"]],"co":[["appeler au secours","呼救"],["crier à l'aide","喊救命"],["venir à l'aide de qqn","来帮某人"]],"sy":[["À l'aide !","courant","救命（同义）"],["Aidez-moi !","courant","帮帮我！"]],"fq":"中频，紧急时刻必用。","me":"Au secours = 「向救援」。","tr":{"zh":"救命！有人掉进水里了！","fr":"Au secours ! Quelqu'un est tombé dans l'eau !","alt":"À l'aide ! Quelqu'un est tombé à l'eau !","note":"Au secours !（感叹语）常加感叹号。"}},
 "De l'exercice physique": {"pos":"loc. 名词短语（部分冠词），exercice 为阳性","s":"体育锻炼；运动。faire de l'exercice (physique) = 锻炼身体；部分冠词 de l'，表示「一些」不可数的运动量。","ipa":"[də lɛɡ.zɛʁ.sis fi.zik]","ph":"de l' 读 [də l]；exercice 读 [ɛɡ.zɛʁ.sis]，x 读 [ɡz]；physique 读 [fi.zik]，ph 读 [f]，y 读 [i]。","pi":"exercice 中 x 读 [ɡz]；ph 读 [f]；注意 exercice 是阳性：un exercice。","et":"exercice 来自拉丁语 exercitium（训练）；physique 来自希腊语 physikos（自然的）。","ex":[["Il fait de l'exercice physique tous les jours.","他每天做体育锻炼。"],["Je ne fais pas assez d'exercice.","我运动不够。"],["L'exercice physique est bon pour la santé.","体育锻炼有益健康。"]],"co":[["faire de l'exercice","锻炼身体"],["de l'exercice physique","体育锻炼"],["pratiquer une activité physique","进行体育活动"]],"sy":[["sport","courant","运动"],["activité physique","courant","体育活动"]],"fq":"高频，健康与日常话题。","me":"de l'exercice = 一点运动。","tr":{"zh":"我每天都想多做运动。","fr":"Je veux faire plus d'exercice physique chaque jour.","alt":"Je veux bouger davantage tous les jours.","note":"faire de l'exercice：部分冠词表示数量。"}},
 "En conséquence": {"pos":"loc. 副词短语，不变化","s":"因此；所以；相应地。书面和正式用语，引出结果；也可指「照此办理」：agir en conséquence（相应地行动）。","ipa":"[ɑ̃ kɔ̃.se.kɑ̃s]","ph":"en 读 [ɑ̃]；con 读 [kɔ̃]；sé 读 [se]；quen 读 [kɑ̃]；ce 读 [s]。","pi":"con-sé-quence 中 qu 读 [k]；en 与 con 都是鼻化音；别与 par conséquent 搞混（含义相近）。","et":"来自拉丁语 consequentia（随之而来），源于 consequi（跟着）。同源：conséquent。","ex":[["En conséquence, nous devons annuler.","因此，我们必须取消。"],["Il pleut, en conséquence, on reste ici.","下雨，所以我们留在这里。"],["Prévenez-nous, et nous agirons en conséquence.","请告诉我们，我们会相应处理。"]],"co":[["agir en conséquence","相应地行动"],["en conséquence de","由于"],["par conséquent","因此"]],"sy":[["donc","courant","所以"],["par conséquent","soutenu","因此"],["alors","courant","于是"]],"fq":"中频，多见于正式文本。","me":"en + conséquence：作为结果。","tr":{"zh":"天气不好，所以我们取消活动。","fr":"Le temps est mauvais, en conséquence, nous annulons l'activité.","alt":"Il fait mauvais, donc on annule.","note":"en conséquence 位于句首或句中，常用逗号隔开。"}},
 "Être en (pleine) forme": {"pos":"loc. 动词短语，être 变位；forme 为阴性名词","s":"状态极佳；精神很好。être en forme = 状态不错；être en pleine forme = 状态非常好。反义：ne pas être en forme（状态不好）。","ipa":"[ɛtʁ ɑ̃ plɛn fɔʁm]","ph":"être 读 [ɛtʁ]；en 读 [ɑ̃]；pleine 读 [plɛn]；forme 读 [fɔʁm]。","pi":"plein 阳性读 [plɛ̃]，阴性 pleine 读 [plɛn]；forme 是阴性，所以 pleine。","et":"forme 来自拉丁语 forma（形状）；这里引申为「身体状态」。","ex":[["Je suis en pleine forme aujourd'hui !","我今天状态特别好！"],["Tu es en forme ce matin ?","你今早状态好吗？"],["Il n'est pas en forme.","他状态不好。"]],"co":[["être en pleine forme","状态极佳"],["retrouver la forme","恢复状态"],["garder la forme","保持健康"]],"sy":[["aller bien","courant","身体好"],["avoir la pêche","familier","精力充沛"]],"fq":"高频，日常口语。","me":"en forme = 处于好的「形态」。","tr":{"zh":"我今天感觉特别好。","fr":"Je suis en pleine forme aujourd'hui.","alt":"Aujourd'hui, j'ai la pêche !","note":"pleine 要与 forme 配合，用阴性。"}},
 "Faire la/une grasse matinée": {"pos":"loc. 动词短语，faire 变位；matinée 为阴性名词","s":"睡懒觉；睡到很晚。faire la grasse matinée 为固定表达，grasse 在这里指「(时间)长而舒适」；une grasse matinée 也可用。","ipa":"[fɛʁ la ɡʁas ma.ti.ne]","ph":"faire 读 [fɛʁ]；grasse 读 [ɡʁas]，ss 读 [s]；matinée 读 [ma.ti.ne]，结尾 -ée 读 [e]。","pi":"grasse 的 ss 读 [s]；不是 grosse（大）；matinée 与 matin 不同：matin 是早上，matinée 强调整个上午。","et":"gras 原义「肥的」，引申为「丰盛、慵懒」；matinée 来自 matin（早晨）加后缀 -ée，表示整段时间。","ex":[["J'adore faire la grasse matinée le dimanche.","我星期天爱睡懒觉。"],["On a fait la grasse matinée hier.","我们昨天睡了懒觉。"],["Tu fais une grasse matinée demain ?","你明天睡懒觉吗？"]],"co":[["faire la grasse matinée","睡懒觉"],["le dimanche matin","星期天早上"],["se lever tard","晚起"]],"sy":[["dormir tard","courant","睡得晚"],["traîner au lit","familier","赖床"]],"fq":"中频，日常口语。","me":"grasse matinée = 「胖胖的」上午，睡得很舒服。","tr":{"zh":"周末我想睡懒觉。","fr":"Ce week-end, je veux faire la grasse matinée.","alt":"Ce week-end, je dors tard.","note":"grasse 是 gras 的阴性，修饰 matinée。"}},
 "Garder son calme": {"pos":"loc. 动词短语，garder 第一组 -er；son 随主语变：garder mon / ton / son calme","s":"保持冷静。物主词随主语变化：Garde ton calme（你要冷静）；Gardons notre calme（我们要冷静）。","ipa":"[ɡaʁ.de sɔ̃ kalm]","ph":"garder 读 [ɡaʁ.de]；son 读 [sɔ̃]；calme 读 [kalm]，结尾 e 不发音。","pi":"calme 结尾 e 不发音，读 [kalm]；物主词要与主语一致：Je garde mon calme。","et":"calme 来自意大利语 calma，可追溯到希腊语 kauma（炎热、午间的静止）。","ex":[["Il faut garder son calme.","要保持冷静。"],["Gardez votre calme, s'il vous plaît.","请保持冷静。"],["Elle garde son calme en toute situation.","她任何情况下都保持冷静。"]],"co":[["garder son calme","保持冷静"],["perdre son calme","失去冷静"],["rester calme","保持平静"]],"sy":[["rester calme","courant","保持平静"],["se maîtriser","soutenu","克制自己"],["perdre son sang-froid","courant","失去冷静（反义）"]],"fq":"中高频，日常常用。","me":"garder（保持）+ calme：把平静留住。","tr":{"zh":"出事时要保持冷静。","fr":"En cas de problème, il faut garder son calme.","alt":"Quand il y a un souci, restez calmes.","note":"son 随主语变化：mon, ton, son, notre, votre, leur。"}},
 "Tout d'abord, ...": {"pos":"loc. 副词短语，不变化，用于句首","s":"首先……。用于列举步骤或论点的第一项，后接 ensuite（然后）、puis（接着）、enfin（最后）。","ipa":"[tu da.bɔʁ]","ph":"tout 读 [tu]，t 不发音；d' 读 [d]；abord 读 [a.bɔʁ]，结尾 d 不发音。","pi":"tout 的 t 不发音；abord 的 d 不发音；d'abord 要连读成 [da.bɔʁ]。","et":"tout + d'abord；abord 来自 aborder（靠岸），拉丁语 ad- 到 + bord 边：「靠到边」，引申为「起初」。","ex":[["Tout d'abord, merci de votre visite.","首先，感谢您的来访。"],["Tout d'abord, lavez-vous les mains.","首先，请洗手。"],["Tout d'abord, je voudrais vous présenter ma famille.","首先，我想向您介绍我的家人。"]],"co":[["tout d'abord… ensuite… enfin","首先……然后……最后"],["d'abord","首先"],["pour commencer","首先、开始时"]],"sy":[["d'abord","courant","首先（更简单）"],["premièrement","soutenu","第一点"],["pour commencer","courant","首先"]],"fq":"高频，演讲与写作常用。","me":"tout d'abord：先说「所有的」第一件事。","tr":{"zh":"首先，我想谢谢大家。","fr":"Tout d'abord, je voudrais remercier tout le monde.","alt":"D'abord, merci à tous.","note":"句首后面用逗号。"}},
 "Un nouveau regard sur": {"pos":"loc. 名词短语，regard 为阳性名词；nouveau 修饰 regard，阴性 nouvelle","s":"看待……的新视角。un nouveau regard sur la vie = 对生活的新看法；regard 表示「目光；看法」，sur 后接对象。","ipa":"[œ̃ nu.vo ʁə.ɡaʁ syʁ]","ph":"un 读 [œ̃]；nouveau 读 [nu.vo]；regard 读 [ʁə.ɡaʁ]，d 不发音；sur 读 [syʁ]。","pi":"regard 的 d 不发音；un 要读 [œ̃]；sur 的 u 读 [y]；不是 sous。","et":"regard 来自动词 regarder（看），由 re- + garder（守护、留意）构成；nouveau 来自拉丁语 novellus（新的）。","ex":[["Cela donne un nouveau regard sur la vie.","这给生活带来了新的视角。"],["Ce film offre un nouveau regard sur la guerre.","这部电影对战争提供了新的视角。"],["J'ai un nouveau regard sur mon travail.","我对工作有了新看法。"]],"co":[["un nouveau regard sur","对……的新视角"],["jeter un regard sur","看一眼"],["porter un regard sur","审视"]],"sy":[["point de vue","courant","观点"],["perspective","soutenu","视角"]],"fq":"中频，多见于书面语。","me":"nouveau（新）+ regard（目光）+ sur（对于）。","tr":{"zh":"这次旅行让我对世界有了新的看法。","fr":"Ce voyage m'a donné un nouveau regard sur le monde.","alt":"Ce voyage a changé ma façon de voir le monde.","note":"regard sur + 对象。"}},
 "(Rubrique) Horoscope": {"pos":"n.m. 阳性名词，复数 horoscopes","s":"星座运势（版块）。horoscope 指根据星座做出的运势预测；报纸或网站里的 rubrique horoscope 就是星座运势栏目。","ipa":"[ɔ.ʁɔ.skɔp]","ph":"h 不发音；o 读 [ɔ]；r [ʁ]；sc 读 [sk]；结尾 -ope 读 [ɔp]。","pi":"开头 h 不发音，要和前面的词连读：un horoscope [œ̃.nɔ.ʁɔs.kɔp]；rubrique 读 [ʁy.bʁik]，u 读 [y]。","et":"来自希腊语 hôroskopos：hôra（时刻）+ skopos（观察者）。同源：英语 horoscope。","ex":[["Il regarde son horoscope.","他看自己的星座运势。"],["Je lis l'horoscope tous les matins.","我每天早上都看星座运势。"],["Mon horoscope dit que j'aurai de la chance.","我的星座运势说我会走运。"]],"co":[["lire son horoscope","看星座运势"],["la rubrique horoscope","星座运势栏目"],["un signe astrologique","星座"]],"sy":[["astrologie","courant","占星术"],["prévisions","courant","预测"]],"fq":"中频，媒体与日常话题。","me":"horo（时刻）+ scope（观察）：观察时刻与星星。","tr":{"zh":"我每天早上读报纸上的星座运势。","fr":"Tous les matins, je lis l'horoscope dans le journal.","alt":"Je regarde mon horoscope dans le journal chaque matin.","note":"horoscope 为阳性：mon horoscope。"}},
 "(Rubrique) Humour": {"pos":"n.m. 阳性名词，复数 humours（少用）","s":"幽默；幽默感。报刊、网站上的 la rubrique humour 指「幽默版块」。avoir de l'humour = 有幽默感。","ipa":"[y.muʁ]","ph":"h 不发音；u [y]；ou [u]；结尾 r 读小舌音 [ʁ]。","pi":"h 是哑音，不要读成 [h]；u [y] 嘴唇要圆，别读成 ou；拼写有 u：humour，不是英语 humor。","et":"借自英语 humour，更早可追溯到拉丁语 humor（液体；体液，古人认为体液决定性情）。","ex":[["La rubrique humour me fait rire.","幽默版块让我发笑。"],["Il a beaucoup d'humour.","他很有幽默感。"]],"co":[["avoir de l'humour","有幽默感"],["l'humour noir","黑色幽默"],["le sens de l'humour","幽默感"]],"sy":[["l'esprit","courant","风趣、机智"],["la drôlerie","soutenu","滑稽、有趣"],["le sérieux","courant","反义：严肃"]],"fq":"中频，日常和媒体都常见。","me":"h 不发音，听起来像「u-mour」，和 amour 有点像，但意思是「幽默」。","tr":{"zh":"我喜欢这个版块，因为它很幽默。","fr":"J'aime cette rubrique parce qu'elle est pleine d'humour.","alt":"J'aime bien cette rubrique, elle est drôle.","note":"être plein d'humour = 很幽默；humour 的 h 不发音，所以用 d'humour。"}},
 "Du succès": {"pos":"n.m. 阳性名词，单复数同形 succès","s":"成功；受欢迎。avoir du succès = 受欢迎、走红；réussir 是动词「成功」，succès 是名词。书中 du 是部分冠词，表示「一些成功」。","ipa":"[syk.sɛ]","ph":"第一个 c 读 [k]，第二个 c 读 [s]；ès 读 [ɛ]；结尾 s 不发音。","pi":"结尾 s 不发音；复数还是 succès；不要和英语 success 的结尾混淆。","et":"来自拉丁语 successus（结果、进展），源于 succedere（接着发生）。","ex":[["Ce film a beaucoup de succès.","这部电影很成功。"],["Bonne chance et bon succès !","祝你好运，一切顺利！"]],"co":[["avoir du succès","受欢迎"],["un grand succès","大获成功"],["avec succès","成功地"],["sans succès","没有成功"]],"sy":[["la réussite","courant","成功（个人的成就）"],["l'échec","courant","反义：失败"],["le triomphe","soutenu","大获全胜"]],"fq":"高频，日常常用。","me":"suc-cès：两个 c 一个 [k] 一个 [s]，最后 s 静音。","tr":{"zh":"这首歌在年轻人中很受欢迎。","fr":"Cette chanson a beaucoup de succès chez les jeunes.","alt":"Cette chanson marche très bien chez les jeunes.","note":"avoir du succès / beaucoup de succès；succès 是阳性。"}},
 "Le grand écran": {"pos":"n.m. 阳性名词，复数 les grands écrans","s":"大银幕，指电影院的银幕，也借指「电影」。sortir sur grand écran = 在电影院上映。注意口语里常省略冠词：sur grand écran。","ipa":"[ɡʁɑ̃.t‿e.kʁɑ̃]","ph":"grand 结尾的 d 在元音前连读成 [t]：grand écran；an [ɑ̃]；é [e]。","pi":"单独说 grand 时 d 不发音，遇到元音开头的 écran 要连读 [t]；écran 以 é 开头，有重音符。","et":"grand 来自拉丁语 grandis；écran 来自古法语 escran，源于中古荷兰语 scherm（屏障）。","ex":[["Ce film sort sur le grand écran.","这部电影将在大银幕上映。"],["J'aime voir les films sur grand écran.","我喜欢在大银幕上看电影。"]],"co":[["sur grand écran","在大银幕上"],["adapter un livre pour le grand écran","把书改编成电影"],["une star du grand écran","电影明星"]],"sy":[["le cinéma","courant","电影；电影院"],["le petit écran","courant","反义：电视"],["le septième art","soutenu","第七艺术（电影）"]],"fq":"中频，影视话题里常见。","me":"大 (grand) + 屏幕 (écran) = 电影院里的大银幕，对比 le petit écran（电视）。","tr":{"zh":"这部小说将被改编成电影。","fr":"Ce roman va être adapté pour le grand écran.","alt":"On va faire un film de ce roman.","note":"adapter pour le grand écran = 改编成电影；adapter 后接 pour 或 à。"}},
 "Le petit écran": {"pos":"n.m. 阳性名词，复数 les petits écrans","s":"小银幕，指电视，也借指「电视界」。à la télévision 是「在电视上」，passer sur le petit écran 是「在电视上播出」，带一点媒体圈的口吻。","ipa":"[pə.ti.t‿e.kʁɑ̃]","ph":"petit 结尾 t 在元音前连读 [t]：petit écran；e 在 pe- 读弱的 [ə]；an [ɑ̃]。","pi":"单独说 petit 时 t 不发音，后面接 écran 要读出 [t]；注意 écran 的 an 是鼻化音，不发 n。","et":"petit 的词源不确定；écran 来自古法语 escran，源于中古荷兰语 scherm（屏障）。","ex":[["Il travaille pour le petit écran.","他为电视工作。"],["Cet acteur est très connu au petit écran.","这位演员在电视上很有名。"]],"co":[["au petit écran","在电视上"],["une star du petit écran","电视明星"],["passer sur le petit écran","在电视上播出"]],"sy":[["la télévision","courant","电视"],["la télé","familier","电视（口语）"],["le grand écran","courant","反义：电影"]],"fq":"中频，影视话题里常见。","me":"小 (petit) 屏幕 = 家里的电视；大屏幕 (grand) = 电影院。","tr":{"zh":"这个节目明晚在电视上播出。","fr":"Cette émission passe demain soir sur le petit écran.","alt":"Cette émission passe à la télé demain soir.","note":"passer à la télé 更口语；passer sur le petit écran 更像媒体用语。"}},
 "Un attentat": {"pos":"n.m. 阳性名词，复数 attentats","s":"袭击；恐怖袭击；谋杀企图。通常指蓄意的暴力事件，多见于新闻。un attentat à la bombe = 炸弹袭击；un attentat contre qqn = 针对某人的行刺。","ipa":"[a.tɑ̃.ta]","ph":"tt 只读一个 [t]；en [ɑ̃]；结尾 t 不发音。","pi":"结尾 t 不发音；an/en 都读鼻化音 [ɑ̃]；不要读成 attaque（攻击，[a.tak]）。","et":"来自动词 attenter（企图、冒犯，拉丁语 attentare）加后缀 -at。","ex":[["Ils ont parlé d'un attentat aux informations.","新闻里谈到一起袭击事件。"],["Il y a eu un attentat à Paris.","巴黎发生了一起袭击事件。"]],"co":[["un attentat à la bombe","炸弹袭击"],["un attentat terroriste","恐怖袭击"],["échapper à un attentat","躲过行刺"],["revendiquer un attentat","宣称对袭击负责"]],"sy":[["l'attaque","courant","攻击（范围更广）"],["l'agression","courant","袭击、侵犯（针对个人）"],["le meurtre","courant","谋杀"]],"fq":"中频，主要出现在新闻里。","me":"at-ten-tat：连着三个 t，像一连串的「敲击」声，意思很严肃。","tr":{"zh":"新闻里说昨晚发生了一起袭击事件。","fr":"Aux informations, ils disent qu'il y a eu un attentat hier soir.","alt":"À la télé, on dit qu'il y a eu un attentat hier soir.","note":"il y a eu 是 il y a 的复合过去时，表示已发生的事件。"}},
 "Un contenu": {"pos":"n.m. 阳性名词，复数 contenus","s":"内容；所含之物。可指书、文章、视频的内容，也可指容器里装的东西：le contenu de la boîte。网络上 créer du contenu = 做内容。","ipa":"[kɔ̃.tə.ny]","ph":"on [ɔ̃]；te 里的 e 常弱读或省略 [kɔ̃t.ny]；u [y]。","pi":"u 读 [y]，嘴唇要圆；结尾不发音；不要和 content（满意的，[kɔ̃.tɑ̃]）混淆。","et":"contenir（容纳，拉丁语 continere）的过去分词 contenu 名词化。","ex":[["Le contenu de ce livre est intéressant.","这本书的内容很有趣。"],["Je regarde le contenu de la boîte.","我看盒子里的东西。"]],"co":[["le contenu d'un livre / d'un article","书 / 文章的内容"],["créer du contenu","创作内容"],["le contenu du sac","包里的东西"],["le contenu et la forme","内容与形式"]],"sy":[["le sujet","courant","主题"],["la teneur","soutenu","含量；要旨"],["le contenant","courant","反义：容器"]],"fq":"高频，日常和网络都常用。","me":"contenir + u = 被「包含」的东西 = 内容。","tr":{"zh":"这个视频的内容很有意思。","fr":"Le contenu de cette vidéo est très intéressant.","alt":"Cette vidéo est vraiment intéressante.","note":"contenu 是阳性：le contenu。"}},
 "Un crime": {"pos":"n.m. 阳性名词，复数 crimes","s":"犯罪；重罪；罪行。比 délit（轻罪）更严重，常指杀人等重罪。commettre un crime = 犯罪。le crime 也可泛指「犯罪现象」。","ipa":"[kʁim]","ph":"cr [kʁ]；i [i]；m 读 [m]；结尾 e 不发音。","pi":"单音节，别在结尾加元音；r 是小舌音 [ʁ]；i 读 [i]，不是 [aj]。","et":"来自拉丁语 crimen（指控、罪行）。同源：criminel。","ex":[["La police enquête sur un crime.","警方调查一起犯罪。"],["Il a commis un crime.","他犯了罪。"]],"co":[["commettre un crime","犯罪"],["un crime de guerre","战争罪行"],["la scène du crime","犯罪现场"],["un roman policier / un film de crime","推理小说 / 犯罪片"]],"sy":[["le délit","courant","轻罪、违法行为"],["le meurtre","courant","谋杀"],["l'infraction","courant","违法行为"]],"fq":"高频，新闻和影视里常见。","me":"crime 和英语 crime 拼写一样，但读 [kʁim]，r 在喉咙。","tr":{"zh":"警察到了犯罪现场。","fr":"La police est arrivée sur la scène du crime.","alt":"La police est arrivée sur les lieux du crime.","note":"arriver 用 être：La police est arrivée。"}},
 "Un dessin animé": {"pos":"n.m. 阳性名词，复数 dessins animés（两部分都加 s）","s":"动画片；卡通。dessin = 画；animé = 活动起来的。看动画片：regarder un dessin animé。","ipa":"[dɛ.sɛ̃ a.ni.me]","ph":"e 在 dessin 里读 [ɛ]；ss 在元音间读 [s]；in [ɛ̃]；animé 的 é 读 [e]。","pi":"dessin 里的 ss 读 [s]，不是 [z]；in 是鼻化音 [ɛ̃]，不发 n；复数两个词都要加 s：des dessins animés。","et":"dessin 来自动词 dessiner（来自意大利语 disegno）；animé 来自拉丁语 animare（赋予生命）。","ex":[["Les enfants regardent un dessin animé.","孩子们看动画片。"],["Mon dessin animé préféré est très drôle.","我最喜欢的动画片很好笑。"]],"co":[["regarder un dessin animé","看动画片"],["un dessin animé japonais","日本动画片"],["un personnage de dessin animé","动画片角色"]],"sy":[["le film d'animation","courant","动画电影（更偏电影）"],["le manga","courant","日本漫画 / 动漫"],["le cartoon","familier","卡通（外来词）"]],"fq":"高频，日常常用，尤其和孩子有关。","me":"画 (dessin) + 动起来 (animé) = 画会动，就是动画片。","tr":{"zh":"周日早上孩子们看动画片。","fr":"Le dimanche matin, les enfants regardent un dessin animé.","alt":"Le dimanche matin, les enfants regardent des dessins animés.","note":"dessin animé 复数：dessins animés。"}},
 "Un documentaire": {"pos":"n.m. 阳性名词，复数 documentaires","s":"纪录片。也可作形容词「文献的、记录性的」：un film documentaire。regarder un documentaire sur… = 看关于……的纪录片。","ipa":"[dɔ.ky.mɑ̃.tɛʁ]","ph":"o [ɔ]；u [y]；en [ɑ̃]；aire [ɛʁ]。","pi":"en 读 [ɑ̃]，不是 [ɛ̃]；结尾 -aire 读 [ɛʁ]，r 要发；u 读 [y]。","et":"来自 document（文件，拉丁语 documentum，「教导的东西」）加 -aire，指以实录为基础的影片。","ex":[["Nous regardons un documentaire sur les animaux.","我们看动物纪录片。"],["Ce documentaire est très instructif.","这部纪录片很有教育意义。"]],"co":[["un documentaire sur…","关于……的纪录片"],["tourner un documentaire","拍纪录片"],["un documentaire animalier","动物纪录片"]],"sy":[["le reportage","courant","报道（时间更短）"],["le film","courant","电影（泛指）"],["la fiction","courant","反义：虚构作品"]],"fq":"中频，影视话题里常见。","me":"document + aire：用「文件」说话的片子，就是纪录片。","tr":{"zh":"昨晚我看了一部关于海洋的纪录片。","fr":"Hier soir, j'ai regardé un documentaire sur la mer.","alt":"Hier soir, j'ai vu un documentaire sur l'océan.","note":"un documentaire sur + 主题。"}},
 "Un épisode": {"pos":"n.m. 阳性名词，复数 épisodes","s":"一集（剧集）；插曲；事件的一个阶段。un épisode de série = 剧集的一集。也可指人生或历史上的一段插曲。","ipa":"[e.pi.zɔd]","ph":"é [e]；s 在元音间读 [z]；o [ɔ]；结尾 d 读 [d]，e 不发音。","pi":"s 读 [z]，不是 [s]；开头 é 有重音符；不要把 ep 读成 [ɛp]。","et":"来自希腊语 epeisodion（歌队歌唱之间的插入段），经拉丁语进入法语。","ex":[["C'est le premier épisode de la série.","这是剧集的第一集。"],["Je n'ai pas vu le dernier épisode.","我没看最后一集。"]],"co":[["le premier / le dernier épisode","第一集 / 最后一集"],["un épisode de série","剧集的一集"],["regarder un épisode","看一集"]],"sy":[["le chapitre","courant","章节（书）"],["la saison","courant","一季（包含多集）"],["la scène","courant","场景"]],"fq":"中频，看剧时常用。","me":"épi-sode：像「插曲」，一集一集地播。","tr":{"zh":"我每周看一集这部剧。","fr":"Je regarde un épisode de cette série chaque semaine.","alt":"Je regarde un épisode de cette série par semaine.","note":"chaque semaine = par semaine。"}},
 "Un média": {"pos":"n.m. 阳性名词，复数 médias","s":"媒体；传播工具。单数 un média 指一种媒体（电视、报纸、网站），复数 les médias 泛指「媒体」。les médias sociaux = 社交媒体。","ipa":"[me.dja]","ph":"é [e]；di + a 合成 [dja]；结尾不发 s（复数时）。","pi":"重音在最后一个音节 [dja]；é 有重音符；中文常说「媒体」时是复数用法：les médias。","et":"借自英语 media，源于拉丁语 medium（中间物，手段）的复数。","ex":[["C'est un nouveau média.","这是新媒体。"],["Les médias parlent de cette affaire.","媒体在谈论这起事件。"]],"co":[["les médias sociaux","社交媒体"],["les médias traditionnels","传统媒体"],["un média en ligne","网络媒体"],["les grands médias","主流媒体"]],"sy":[["la presse","courant","新闻界、报刊"],["les médias de masse","courant","大众媒体"],["le support","courant","载体、介质"]],"fq":"高频，新闻里常用。","me":"média = 「中间」(medium)：在信息和人之间传递的东西。","tr":{"zh":"年轻人更多使用网络媒体。","fr":"Les jeunes utilisent plus les médias en ligne.","alt":"Les jeunes préfèrent les médias en ligne.","note":"média 单数阳性；常用复数 les médias。"}},
 "Un menu": {"pos":"n.m. 阳性名词，复数 menus","s":"菜单；套餐；应用里的菜单栏。在餐厅 le menu 常是「套餐」，le menu à 20 euros = 20 欧套餐；点菜的单子叫 la carte。电脑和应用里的 menu 是「选项菜单」。","ipa":"[mə.ny]","ph":"me 里的 e 读弱的 [ə]；u [y]；结尾不发音。","pi":"u 读 [y]，不是 ou；餐厅里 menu（套餐）和 carte（菜单）不是一回事；复数 menus 不加 x。","et":"来自形容词 menu（细小的，拉丁语 minutus），指详细列出的清单。","ex":[["Tu peux accéder aux paramètres depuis le menu de l'application.","你可以从应用的菜单进入设置。"],["Je prends le menu à quinze euros.","我点十五欧的套餐。"]],"co":[["le menu du jour","今日套餐"],["un menu déroulant","下拉菜单"],["le menu principal","主菜单"],["un menu enfant","儿童套餐"]],"sy":[["la carte","courant","餐厅的菜单（可单点）"],["la formule","courant","套餐（午餐常用）"],["l'option","courant","选项"]],"fq":"极高频，日常常用。","me":"menu = 「细小的」清单：把一顿饭分成一小项一小项。","tr":{"zh":"请点开应用的菜单。","fr":"Ouvre le menu de l'application, s'il te plaît.","alt":"Clique sur le menu de l'appli, s'il te plaît.","note":"appli 是 application 的口语缩写。"}},
 "Un podcast": {"pos":"n.m. 阳性名词，复数 podcasts","s":"播客；可下载或在线收听的音频节目。écouter un podcast = 听播客；un épisode de podcast = 一期播客。","ipa":"[pɔd.kast]","ph":"o [ɔ]；d 读 [d]；a [a]；st 在结尾读出，结尾 t 也读 [t]。","pi":"结尾 st 都要发音 [st]；不要读成英语的 [ˈpɒdkɑːst]，元音要短；和 podcasteur（做播客的人）区分。","et":"借自英语 podcast，由 iPod 和 broadcast 混合而成。","ex":[["J'écoute un podcast dans le train.","我在火车上听播客。"],["Ce podcast parle d'histoire.","这个播客讲历史。"]],"co":[["écouter un podcast","听播客"],["un podcast sur…","关于……的播客"],["s'abonner à un podcast","订阅播客"]],"sy":[["l'émission de radio","courant","广播节目"],["le livre audio","courant","有声书"],["la baladodiffusion","soutenu","官方推荐的法语说法（少用）"]],"fq":"中频，年轻人常用。","me":"pod + cast：口袋里的广播，st 都要读出来。","tr":{"zh":"我做饭时听播客。","fr":"J'écoute un podcast quand je cuisine.","alt":"J'écoute des podcasts en cuisinant.","note":"quand + 现在时；en cuisinant 是现在分词，表示同时进行。"}},
 "Un reportage": {"pos":"n.m. 阳性名词，复数 reportages","s":"新闻报道；专题报道。指记者到现场拍摄或采写的报道，如 un reportage à la télé。不是「报告」（rapport）。","ipa":"[ʁə.pɔʁ.taʒ]","ph":"re 读弱的 [ʁə]；o [ɔ]；r 在音节尾读 [ʁ]；g 在 -age 里读 [ʒ]。","pi":"-age 读 [aʒ]，g 是 [ʒ]，不是 [ɡ]；不要和 rapport（报告）混淆；结尾 e 不发音。","et":"来自动词 reporter（带回、汇报）加后缀 -age，受英语 report 影响。","ex":[["J'ai vu un bon reportage hier.","我昨天看了一个好报道。"],["Il fait un reportage sur la pollution.","他在做关于污染的报道。"]],"co":[["faire un reportage","做报道"],["un reportage photo","摄影报道"],["un reportage sur…","关于……的报道"],["un grand reportage","深度报道"]],"sy":[["le rapport","courant","报告（官方、工作用）"],["l'article","courant","文章"],["le documentaire","courant","纪录片"]],"fq":"中频，媒体话题里常用。","me":"re-port-age：记者「带回」(reporter) 现场的消息。","tr":{"zh":"我在电视上看了一个关于巴黎的报道。","fr":"J'ai regardé un reportage sur Paris à la télé.","alt":"J'ai vu un reportage sur Paris à la télévision.","note":"à la télé = 在电视上。"}},
 "Un senior": {"pos":"n.m. 阳性名词，复数 seniors；也可作形容词，阴性 senior（不变）","s":"老年人；银发族，一般指 60 岁以上的人。比 un vieux 礼貌得多。le tarif senior = 老年人优惠价。体育里 senior 也指「成年组运动员」。","ipa":"[se.njɔʁ]","ph":"s 在词首读 [s]；e [e]；-ior 读 [njɔʁ]，r 要发。","pi":"结尾 r 要发音 [ʁ]；不要读成英语的 [ˈsiːniər]；重音在最后一个音节。","et":"借自拉丁语 senior（更年长的），是 senex（老的）的比较级。","ex":[["Ce journal est pour les seniors.","这份报纸面向老年人。"],["Il y a un tarif senior au cinéma.","电影院有老年人优惠价。"]],"co":[["un tarif senior","老年人优惠价"],["un club de seniors","老年人俱乐部"],["les seniors actifs","活跃的银发族"]],"sy":[["une personne âgée","courant","老年人（礼貌）"],["un retraité","courant","退休的人"],["un aîné","soutenu","长辈、年长者"]],"fq":"中频，社会和营销用语里常见。","me":"senior 来自拉丁语 senex（老），所以是「年长的人」。","tr":{"zh":"这家公司给老年人提供优惠。","fr":"Cette entreprise offre des réductions aux seniors.","alt":"Cette entreprise fait des réductions pour les seniors.","note":"offrir qqch à qqn：offrir des réductions aux seniors。"}},
 "(La presse) culturelle": {"pos":"n.f. 阴性名词，la presse 为阴性，复数 les presses；形容词 culturel(le)","s":"文化类媒体；文化报刊。la presse 指「报刊、新闻界」；culturelle 说明类型：谈电影、书、展览、音乐的报刊。","ipa":"[pʁɛs kyl.ty.ʁɛl]","ph":"presse 里 e [ɛ]，ss [s]；culturelle 里 u [y]，elle 读 [ɛl]，ll 读 [l]。","pi":"culturelle 是阴性，要和阴性名词 la presse 配合；ss 读 [s]；结尾 elle 的 e 不发音，但 [ɛl] 要读出。","et":"presse 来自 presser（拉丁语 pressare，按压），指印刷机；culturel 来自 culture（拉丁语 cultura）。","ex":[["J'aime la presse culturelle.","我喜欢文化类报刊。"],["Elle lit la presse culturelle le week-end.","她周末读文化类报刊。"]],"co":[["la presse écrite","纸质媒体"],["la presse spécialisée","专业报刊"],["lire la presse","读报刊"]],"sy":[["la presse spécialisée","courant","专业类报刊"],["la presse people","courant","八卦小报"],["la presse généraliste","courant","综合性报刊"]],"fq":"中频，谈媒体时常用。","me":"press（按压）+ culture：用印刷机印出来的「文化」。","tr":{"zh":"我喜欢读文化类报刊。","fr":"J'aime lire la presse culturelle.","alt":"J'adore lire la presse culturelle.","note":"la presse 用单数，泛指「报刊」。"}},
 "(La presse) féminine": {"pos":"n.f. 阴性名词，形容词 féminin / féminine","s":"女性杂志；面向女性读者的报刊（时尚、美容、生活）。féminine 是阴性形容词，和 la presse 配合；阳性是 féminin。","ipa":"[pʁɛs fe.mi.nin]","ph":"presse [pʁɛs]；féminine 里 é [e]，i [i]，nine 读 [nin]，结尾 e 不发音。","pi":"féminine 结尾读 [nin]，不是鼻化音；阳性 féminin 结尾是 [nɛ̃]，不要混。","et":"féminin 来自拉丁语 femininus，源于 femina（女人）。","ex":[["Elle lit la presse féminine.","她读女性杂志。"],["La presse féminine parle de mode.","女性杂志谈时尚。"]],"co":[["un magazine féminin","女性杂志"],["la presse magazine","杂志类报刊"],["la presse masculine","男性杂志"]],"sy":[["le magazine féminin","courant","女性杂志"],["la presse people","courant","八卦小报"],["la presse masculine","courant","对应：男性杂志"]],"fq":"中频，谈媒体时用。","me":"fémin-ine：阴性词尾 -ine 读 [in]，像「宜宁」。","tr":{"zh":"我姐姐每个月买一本女性杂志。","fr":"Ma sœur achète un magazine de la presse féminine chaque mois.","alt":"Ma sœur achète un magazine féminin tous les mois.","note":"chaque mois = tous les mois。"}},
 "(La presse) people": {"pos":"n.f. 阴性名词；people 作形容词不变（不加 s、不分阴阳性）","s":"八卦小报；明星八卦杂志。people 借自英语，在法语里是形容词，意为「名人的」：une star people、un magazine people。","ipa":"[pʁɛs pi.pœl]","ph":"presse [pʁɛs]；people 读 [pi.pœl]，是英语借词，法语里 eo 读 [i]，结尾 [œl]。","pi":"people 的发音偏英语，第一音节 [pi]；people 在法语里不变形，不加 s；千万别写成 peuple（人民，[pœpl]）。","et":"people 借自英语，原义是「人们」，法语里转指「名人」。","ex":[["La presse people parle des stars.","八卦小报谈论明星。"],["Ce magazine people est très connu.","这本八卦杂志很有名。"]],"co":[["un magazine people","八卦杂志"],["une star people","名人"],["la rubrique people","名人版块"]],"sy":[["la presse à scandale","courant","爆料小报（略带贬义）"],["la presse du cœur","courant","爱情八卦杂志"],["la presse à sensation","courant","耸人听闻的报刊"]],"fq":"中频，口语和媒体里常见。","me":"people ≠ peuple：前者是「名人」，后者是「人民」。","tr":{"zh":"她不看八卦杂志。","fr":"Elle ne lit pas la presse people.","alt":"Elle ne lit jamais les magazines people.","note":"ne… pas 包住动词，la presse people 是直接宾语。"}},
 "(La presse) sportive": {"pos":"n.f. 阴性名词，形容词 sportif / sportive","s":"体育报刊；体育类媒体。sportive 是阴性形容词，与 la presse 配合；阳性是 sportif。L'Équipe 是法国著名的体育日报。","ipa":"[pʁɛs spɔʁ.tiv]","ph":"presse [pʁɛs]；sportive 里 o [ɔ]，r [ʁ]，t [t]，v [v]，结尾 e 不发音。","pi":"sport 单独读 [spɔʁ]，t 不发音；阴性 sportive 里 t 要发出来 [spɔʁ.tiv]；结尾 v 读 [v]，阳性 sportif 结尾是 [f]。","et":"sport 来自英语，英语又源自古法语 desport（消遣）；加后缀 -if / -ive。","ex":[["Il achète la presse sportive.","他买体育报刊。"],["La presse sportive parle du match.","体育报刊谈论这场比赛。"]],"co":[["un journal sportif","体育报纸"],["l'actualité sportive","体育新闻"],["la rubrique sport","体育版块"]],"sy":[["la presse spécialisée","courant","专业报刊"],["le journal de sport","courant","体育报纸"],["la rubrique sport","courant","体育版块"]],"fq":"中频，谈体育和媒体时用。","me":"sportif (f) → sportive (v)：f 变 v，阴性更「软」。","tr":{"zh":"我爸爸每天早上读体育报刊。","fr":"Mon père lit la presse sportive tous les matins.","alt":"Mon père lit le journal de sport chaque matin.","note":"tous les matins = chaque matin。"}},
 "(Rubrique) Beauté": {"pos":"n.f. 阴性名词，复数 beautés","s":"美容版块；美；美丽。la rubrique beauté 是杂志里谈护肤、化妆的栏目。beauté 单独用是「美」，也可指美人（une beauté）。","ipa":"[bo.te]","ph":"eau 读 [o]；t [t]；é [e]。","pi":"eau 读 [o]，不发 e/a/u；结尾 é 读 [e]，不是 [ɛ]；拼写是 beauté，不是 beauty。","et":"来自古法语 beauté，源自拉丁语 bellitas，bellus（美的）的派生词。","ex":[["Elle écrit pour la rubrique beauté.","她为美容版块写稿。"],["Les produits de beauté sont chers.","美容产品很贵。"]],"co":[["un produit de beauté","美容产品"],["un institut de beauté","美容院"],["un concours de beauté","选美比赛"],["la rubrique beauté","美容栏目"]],"sy":[["la beauté","courant","美（泛指）"],["le charme","courant","魅力"],["la laideur","courant","反义：丑"]],"fq":"中频，日常常用。","me":"beau + té：「美」加名词词尾 -té，和 santé、liberté 一样。","tr":{"zh":"她喜欢读美容版块。","fr":"Elle aime lire la rubrique beauté.","alt":"Elle adore la rubrique beauté.","note":"rubrique beauté 里 beauté 作定语，不变。"}},
 "(Rubrique) Bourse": {"pos":"n.f. 阴性名词，复数 bourses","s":"股市版块；证券交易所。la Bourse（大写）指交易所；la bourse 也有「钱包、奖学金」的意思：une bourse d'études = 奖学金。","ipa":"[buʁs]","ph":"ou [u]；r [ʁ]；s [s]；结尾 e 不发音。","pi":"ou 读 [u]；单音节，不要在结尾加元音；注意 bourse 的多义：股市、奖学金、钱包。","et":"来自拉丁语 bursa（皮袋、钱包），源自希腊语 byrsa（皮）。","ex":[["Il suit la rubrique bourse.","他关注股市版块。"],["La Bourse de Paris est ouverte.","巴黎证券交易所开市了。"]],"co":[["la Bourse de Paris","巴黎证券交易所"],["jouer en Bourse","炒股"],["une bourse d'études","奖学金"],["le cours de la Bourse","股市行情"]],"sy":[["le marché boursier","courant","股票市场"],["le portefeuille","courant","钱包；投资组合"],["la finance","courant","金融"]],"fq":"中频，经济新闻里常见。","me":"bourse ← bursa（钱包）：放钱的地方，也是交易的地方。","tr":{"zh":"他每天早上看股市版块。","fr":"Il lit la rubrique bourse tous les matins.","alt":"Il regarde la bourse chaque matin.","note":"la Bourse 大写指具体的交易所。"}},
 "(Rubrique) Économie": {"pos":"n.f. 阴性名词，复数 économies","s":"经济版块；经济；节约。faire des économies = 省钱。l'économie 指国家的「经济」，une économie 单数也可以指「节省」。","ipa":"[e.kɔ.nɔ.mi]","ph":"é [e]；c [k]；o [ɔ]；n [n]；o [ɔ]；mie 读 [mi]。","pi":"第一个音是 é，不是 e；注意 économie 里的 o 读 [ɔ]；faire des économies 是「省钱」，不是「做经济」。","et":"来自希腊语 oikonomia（管理家务），由 oikos（家）和 nomos（规则）构成。","ex":[["La rubrique économie est intéressante.","经济版块很有意思。"],["Nous faisons des économies pour partir en vacances.","我们存钱去度假。"]],"co":[["faire des économies","省钱"],["l'économie mondiale","世界经济"],["la rubrique économie","经济栏目"],["une économie de temps","节省时间"]],"sy":[["l'épargne","courant","储蓄"],["la finance","courant","金融"],["la crise","courant","反义/相关：危机"]],"fq":"高频，新闻和日常都常用。","me":"éco + nomie：管理「家」的规则，从家到国家都是经济。","tr":{"zh":"我们在省钱去旅行。","fr":"On fait des économies pour voyager.","alt":"On met de l'argent de côté pour voyager.","note":"on = nous（口语）；faire des économies 用复数。"}},
 "(Rubrique) Santé": {"pos":"n.f. 阴性名词，复数 santés（少用）","s":"健康版块；健康。la rubrique santé 谈医疗、保健。Santé ! 也是干杯用语，意思是「干杯！」。être en bonne santé = 身体好。","ipa":"[sɑ̃.te]","ph":"s [s]；an [ɑ̃]；t [t]；é [e]。","pi":"an 读鼻化音 [ɑ̃]，不发 n；结尾 é 读 [e]；Santé ! 干杯时说，不是「健康」的问候。","et":"来自拉丁语 sanitas（健康），同源：sain（健康的）、sanitaire。","ex":[["La rubrique santé donne des conseils.","健康版块给出建议。"],["Il est en bonne santé.","他身体很好。"]],"co":[["être en bonne santé","身体健康"],["à votre santé !","祝您健康！（干杯）"],["un problème de santé","健康问题"],["la rubrique santé","健康栏目"]],"sy":[["la forme","courant","状态、精神"],["le bien-être","courant","舒适、幸福"],["la maladie","courant","反义：疾病"]],"fq":"极高频，日常常用。","me":"santé = sain 的名词：「健康」，像 sanity。","tr":{"zh":"他最近身体很好。","fr":"Il est en bonne santé ces derniers temps.","alt":"Il va bien en ce moment.","note":"en bonne santé 固定搭配，santé 前用 en。"}},
 "L'actualité": {"pos":"n.f. 阴性名词，复数 actualités（常用复数指新闻节目）","s":"时事；新闻；当下的事。l'actualité 是「当前发生的事」。les actualités 常指电视新闻节目。d'actualité = 最近的、热门的。","ipa":"[ak.tɥa.li.te]","ph":"c [k]；tua 读 [tɥa]（u 变成半元音）；li [li]；té [te]。l' 与 a 省音。","pi":"tua 读 [tɥa]，嘴唇从圆到开；结尾 é 读 [e]；actualité 是「当下发生的事」，不是「真实」（réalité）。","et":"来自 actuel（拉丁语 actualis，源自 actus，行动）加后缀 -ité。注意法语 actuel 是「现在的」，不是「实际的」。","ex":[["Il lit l'actualité sur son téléphone.","他在手机上看新闻。"],["C'est un sujet d'actualité.","这是个热门话题。"]],"co":[["suivre l'actualité","关注时事"],["un sujet d'actualité","热门话题"],["l'actualité sportive","体育新闻"],["d'actualité","当前的"]],"sy":[["les infos","familier","新闻（口语）"],["les nouvelles","courant","消息"],["les informations","courant","新闻、信息"]],"fq":"高频，日常和新闻里都常用。","me":"actuel（现在的）+ ité：「现在发生的事」，别和 réalité 混。","tr":{"zh":"我每天早上在手机上看新闻。","fr":"Je suis l'actualité sur mon téléphone chaque matin.","alt":"Je regarde les infos sur mon portable tous les matins.","note":"suivre l'actualité = 关注时事；actuel 是「当下的」。"}},
 "L'écriture": {"pos":"n.f. 阴性名词，复数 écritures","s":"写作；书写；文字；笔迹。l'écriture 可指写字的方式（笔迹）、写作的风格、或一种文字系统：l'écriture chinoise。","ipa":"[e.kʁi.tyʁ]","ph":"é [e]；cr [kʁ]；i [i]；tu [ty]；r [ʁ]；结尾 e 不发音。l' 在元音前省音。","pi":"u 读 [y]，不是 [u]；结尾 -ure 读 [yʁ]；写字、写作、文字系统要看上下文。","et":"来自拉丁语 scriptura，源自 scribere（写）。同源：écrire、écrivain。","ex":[["L'écriture de cet article est très bonne.","这篇文章写得很好。"],["Je n'arrive pas à lire son écriture.","我看不懂他的笔迹。"]],"co":[["l'écriture d'un roman","写小说"],["une écriture claire","清晰的笔迹"],["l'écriture chinoise","汉字书写"],["un atelier d'écriture","写作工坊"]],"sy":[["le style","courant","风格"],["la plume","littéraire","文笔"],["la calligraphie","soutenu","书法"]],"fq":"高频，日常常用。","me":"écrire（写）+ ture：「写」的名词形式，和 culture 一样词尾。","tr":{"zh":"我喜欢她的笔迹。","fr":"J'aime son écriture.","alt":"Elle a une belle écriture, j'adore.","note":"阴性名词以元音开头时，物主词用 son，不用 sa：son écriture。"}},
 "La coupe du monde": {"pos":"n.f. 阴性名词，复数 coupes du monde","s":"世界杯。常特指足球世界杯 la Coupe du monde（大写）。coupe 本意是「杯子；奖杯」，也有「剪、切」的意思：une coupe de cheveux = 发型。","ipa":"[kup dy mɔ̃d]","ph":"ou [u]；p 读 [p]；du 的 u 读 [y]；monde 里 on [ɔ̃]，d 读 [d]，结尾 e 不发音。","pi":"coupe（杯）和 coup（一下）读音一样，拼写不同；u 读 [y]；monde 的 on 是鼻化音。","et":"coupe 来自拉丁语 cuppa（杯）；monde 来自拉丁语 mundus（世界）。","ex":[["La France a gagné la coupe du monde.","法国赢得了世界杯。"],["On regarde la Coupe du monde ensemble.","我们一起看世界杯。"]],"co":[["gagner la coupe du monde","赢得世界杯"],["la coupe du monde de football","足球世界杯"],["une coupe de champagne","一杯香槟"],["une coupe de cheveux","发型"]],"sy":[["le Mondial","familier","世界杯（口语）"],["le championnat","courant","锦标赛"],["le trophée","courant","奖杯"]],"fq":"高频，体育话题里很常见。","me":"coupe = 杯；coupe du monde = 全世界争夺的杯。","tr":{"zh":"我们一起看世界杯比赛。","fr":"On regarde le match de la coupe du monde ensemble.","alt":"On regarde le Mondial ensemble.","note":"le match 阳性；coupe 阴性。"}},
 "La liberté de presse": {"pos":"n.f. 阴性名词；常见说法是 la liberté de la presse","s":"新闻自由；出版自由，指媒体自由发表而不受审查。在法语里更常说 la liberté de la presse，书里是省略冠词的说法，意思相同。","ipa":"[li.bɛʁ.te də pʁɛs]","ph":"i [i]；e 在 -bɛʁ- 读 [ɛ]；é [e]；de 读弱的 [də]；presse [pʁɛs]。","pi":"liberté 结尾 é 读 [e]；de 读弱的 [də]；presse 的 ss 读 [s]；liberté 是阴性。","et":"liberté 来自拉丁语 libertas（自由），源自 liber（自由的）；presse 见 presser（拉丁语 pressare）。","ex":[["La liberté de presse est importante.","新闻自由很重要。"],["Il défend la liberté de la presse.","他捍卫新闻自由。"]],"co":[["défendre la liberté de la presse","捍卫新闻自由"],["la liberté d'expression","言论自由"],["la liberté de la presse","新闻自由"],["une atteinte à la liberté de la presse","对新闻自由的侵犯"]],"sy":[["la liberté d'expression","courant","言论自由"],["l'indépendance","courant","独立性"],["la censure","courant","反义：审查"]],"fq":"中频，新闻和政治话题里常用。","me":"liberté = libre + té：自由；对比 censure（审查）。","tr":{"zh":"新闻自由在民主国家很重要。","fr":"La liberté de la presse est importante dans une démocratie.","alt":"La liberté de la presse, c'est essentiel dans un pays démocratique.","note":"标准说法 la liberté de la presse，带冠词。"}},
 "La presse (papier, en ligne)": {"pos":"n.f. 阴性名词，复数 presses（指印刷机时）","s":"新闻界；报刊；媒体。la presse écrite = 纸质报刊，la presse en ligne = 网络媒体。la presse 也有「印刷机」的意思；pressé(e) 是「着急的」。","ipa":"[pʁɛs]","ph":"pr [pʁ]；e [ɛ]；ss [s]；结尾 e 不发音。","pi":"单音节 [pʁɛs]；ss 读 [s]，不是 [z]；和 pressé（匆忙的，[pʁe.se]）区分。","et":"来自动词 presser（按压，拉丁语 pressare），原指印刷机的压印。","ex":[["La presse en ligne est très populaire.","网络媒体很受欢迎。"],["Je lis la presse tous les jours.","我每天读报刊。"]],"co":[["la presse écrite","纸质媒体"],["la presse en ligne","网络媒体"],["une conférence de presse","新闻发布会"],["un article de presse","新闻文章"]],"sy":[["les médias","courant","媒体"],["le journal","courant","报纸"],["la presse quotidienne","courant","日报"]],"fq":"高频，日常和新闻里常用。","me":"presse = 压 (press)：以前报纸靠印刷机压出来。","tr":{"zh":"我每天在网上读报刊。","fr":"Je lis la presse en ligne tous les jours.","alt":"Je lis les journaux sur internet chaque jour.","note":"la presse 用单数泛指整个新闻界。"}},
 "La télé-réalité": {"pos":"n.f. 阴性名词，常用单数","s":"真人秀。télé（电视）+ réalité（现实）组成，借自英语 reality TV。常用于说人们生活被拍摄的节目，如 Koh-Lanta。le programme de télé-réalité = 真人秀节目。","ipa":"[te.le.ʁe.a.li.te]","ph":"té [te]；lé [le]；ré [ʁe]；a [a]；li [li]；té [te]，每个音节都清晰。","pi":"有连字符，写成 télé-réalité；réalité 里 é 和 a 分开读 [ʁe.a]；三个 é 都有重音符。","et":"télé（希腊语 tele，远）+ réalité（拉丁语 realitas）；是英语 reality TV 的仿造词。","ex":[["Elle n'aime pas la télé-réalité.","她不喜欢真人秀。"],["Mon frère regarde la télé-réalité.","我哥哥看真人秀。"]],"co":[["une émission de télé-réalité","真人秀节目"],["un candidat de télé-réalité","真人秀选手"],["regarder la télé-réalité","看真人秀"]],"sy":[["la téléréalité","courant","另一种拼法，不带连字符"],["le jeu télévisé","courant","电视游戏节目"],["l'émission","courant","节目"]],"fq":"中频，日常常用。","me":"télé（电视）+ réalité（现实）= 把现实搬上电视。","tr":{"zh":"我不喜欢看真人秀。","fr":"Je n'aime pas regarder la télé-réalité.","alt":"La télé-réalité, ça ne me plaît pas.","note":"ne… pas 包住 aime；regarder 用原形。"}},
 "La voix": {"pos":"n.f. 阴性名词，单复数同形 voix","s":"声音（人的嗓音）；声部；意见、投票。une voix grave = 低沉的声音；à haute voix = 大声地；les voix 也指选举中的票数。","ipa":"[vwa]","ph":"v [v]；oi 读 [wa]；结尾 x 不发音。","pi":"结尾 x 不发音；oi 读 [wa]，不是 [wɔ]；voix（声音）和 voie（路）和 voir（看）读音接近，不要混。","et":"来自拉丁语 vox, vocis（声音）。同源：vocal、voyelle。","ex":[["J'aime la voix du présentateur.","我喜欢主持人的声音。"],["Il parle à voix basse.","他小声说话。"]],"co":[["à haute voix","大声地"],["à voix basse","小声地"],["une belle voix","好听的嗓音"],["perdre sa voix","失声"]],"sy":[["le son","courant","声音（泛指）"],["la parole","courant","说话、话语"],["le vote","courant","投票（voix 的另一义）"]],"fq":"高频，日常常用。","me":"voix 读 [vwa]，x 不发音，像 voir 的前半。","tr":{"zh":"我喜欢这位歌手的声音。","fr":"J'aime la voix de ce chanteur.","alt":"Ce chanteur a une voix magnifique.","note":"la voix 阴性；复数 des voix 形式不变。"}},
 "Une \"fake news\"": {"pos":"n.f. 阴性名词（在法语里常用阴性：une fake news），复数 des fake news","s":"假新闻；虚假信息。借自英语，在法语里常按阴性使用：une fake news；复数一般不变：des fake news。官方更推荐说 une information fallacieuse 或 une infox。","ipa":"[fɛk njuz]","ph":"fake 读 [fɛk]（不是英语的 [feɪk]）；news 读 [njuz]，ew 读 [ju]，s 读 [z]。","pi":"发音带英语味但 fake 读 [fɛk]；news 的 s 读 [z]；性别可阴可阳，但常用阴性。","et":"借自英语 fake news；fake 一词的起源不确定。","ex":[["C'est une fake news sur internet.","这是网上的假新闻。"],["Il ne faut pas partager les fake news.","不要转发假新闻。"]],"co":[["partager une fake news","转发假新闻"],["lutter contre les fake news","打击假新闻"],["une fake news virale","疯传的假新闻"]],"sy":[["une infox","courant","官方推荐的法语词"],["un canular","courant","恶作剧、假消息"],["une rumeur","courant","谣言"]],"fq":"中频，网络和新闻里常见。","me":"fake（假）+ news（新闻）；法语里说成 une fake news。","tr":{"zh":"这条消息是假新闻，别转发。","fr":"Cette information est une fake news, ne la partage pas.","alt":"C'est une fake news, ne la partage pas.","note":"ne… pas + 命令式：ne la partage pas。"}},
 "Une archive": {"pos":"n.f. 阴性名词，复数 archives（常用复数）","s":"档案；档案馆。常用复数 les archives，如 aux archives = 在档案馆。也指资料库、旧照片、旧文件。电脑里的 une archive 是「压缩包」。","ipa":"[aʁ.ʃiv]","ph":"ar [aʁ]；ch 读 [ʃ]；i [i]；v [v]；结尾 e 不发音。","pi":"ch 在这里读 [ʃ]，不是 [k]（这是 archive 的特点，注意与 archéologie [aʁ.ke.ɔ.lɔ.ʒi] 区分）；archive 是阴性。","et":"来自拉丁语 archivum，源自希腊语 arkheion（官府、公署）。","ex":[["J'ai trouvé cette photo dans les archives.","我在档案里找到了这张照片。"],["Les archives de la ville sont ouvertes au public.","市档案馆向公众开放。"]],"co":[["les archives nationales","国家档案馆"],["consulter les archives","查阅档案"],["des images d'archives","资料影像"],["une archive audio","音频存档"]],"sy":[["les documents","courant","文件"],["le dossier","courant","文件夹、档案"],["la mémoire","littéraire","记忆"]],"fq":"中频，新闻和学习里常见。","me":"archive 的 ch 读 [ʃ]，像 arc-hive。","tr":{"zh":"我在档案馆里找到了老照片。","fr":"J'ai trouvé de vieilles photos dans les archives.","alt":"J'ai déniché des vieilles photos aux archives.","note":"de vieilles photos：形容词在复数名词前用 de。"}},
 "Une chaîne (de télé)": {"pos":"n.f. 阴性名词，复数 chaînes","s":"电视频道；链条；连锁店。une chaîne de télé = 电视频道。une chaîne 单独也指「链条」「连锁」：une chaîne de magasins。changer de chaîne = 换台。","ipa":"[ʃɛn]","ph":"ch [ʃ]；aî 读 [ɛ]；n [n]；结尾 e 不发音。","pi":"aî 读 [ɛ]，不是 [ai]；chaîne 和 chêne（橡树）同音；ch 读 [ʃ]。","et":"来自拉丁语 catena（链）。电视频道的意思是因为节目「连成一条」。","ex":[["Quelle est ta chaîne préférée ?","你最喜欢哪个频道？"],["Je change de chaîne.","我换台。"]],"co":[["changer de chaîne","换台"],["une chaîne de télévision","电视频道"],["une chaîne YouTube","YouTube 频道"],["une chaîne de magasins","连锁商店"]],"sy":[["le canal","courant","频道（官方）"],["la télévision","courant","电视"],["le réseau","courant","网络、网点"]],"fq":"高频，日常常用。","me":"chaîne = 链：一个频道一个频道连成链。","tr":{"zh":"我们换个频道吧。","fr":"On change de chaîne ?","alt":"Si on changeait de chaîne ?","note":"changer de + 名词（不带冠词）：changer de chaîne。"}},
 "Une distraction": {"pos":"n.f. 阴性名词，复数 distractions","s":"消遣；娱乐；走神。une distraction 可以是「放松的活动」，也可以是「一时的疏忽」：Par distraction, il a oublié ses clés。","ipa":"[dis.tʁak.sjɔ̃]","ph":"dis [dis]；tr [tʁ]；a [a]；ct 读 [k]；ti 读 [sj]；on [ɔ̃]。","pi":"ti 在这里读 [sj]，不是 [ti]；-tion 结尾读 [sjɔ̃]；结尾 n 不发音。","et":"来自拉丁语 distractio，源自 distrahere（拉开、使分心）。同源：distrait（心不在焉的）、distraire。","ex":[["Le sport est une bonne distraction.","运动是很好的消遣。"],["Il a oublié ses clés par distraction.","他因为走神忘了钥匙。"]],"co":[["par distraction","因为分心"],["avoir besoin de distractions","需要消遣"],["une distraction pour les enfants","孩子的娱乐"],["une source de distraction","娱乐的来源"]],"sy":[["le divertissement","courant","娱乐"],["le loisir","courant","休闲"],["l'inattention","courant","不专心"]],"fq":"中频，日常常用。","me":"dis + traction：被「拉开」注意力 = 放松或走神。","tr":{"zh":"看电影是我最喜欢的消遣。","fr":"Regarder des films est ma distraction préférée.","alt":"Mon passe-temps préféré, c'est regarder des films.","note":"préférée 与阴性名词 distraction 配合。"}},
 "Une émission": {"pos":"n.f. 阴性名词，复数 émissions","s":"节目（广播或电视）；发射；排放。une émission de télé = 电视节目。也可指「排放」：l'émission de gaz = 气体排放。","ipa":"[e.mi.sjɔ̃]","ph":"é [e]；mi [mi]；ss 读 [s]；ion 读 [jɔ̃]，整个结尾读 [sjɔ̃]。","pi":"ss 读 [s]，不是 [z]；结尾 -ion 读 [jɔ̃]，不发 n；é 在词首有重音符。","et":"来自拉丁语 emissio，源自 emittere（送出）。同源：émettre（发射、播出）。","ex":[["C'est mon émission préférée.","这是我最喜欢的节目。"],["Cette émission passe le soir.","这个节目在晚上播出。"]],"co":[["une émission de télé / de radio","电视 / 广播节目"],["regarder une émission","看节目"],["une émission en direct","直播节目"],["une émission de gaz","气体排放"]],"sy":[["le programme","courant","节目表中的内容"],["le show","familier","秀、节目"],["la diffusion","courant","播出"]],"fq":"高频，日常常用。","me":"émission ← émettre：把节目「发出去」。","tr":{"zh":"这个节目周四晚上播出。","fr":"Cette émission passe le jeudi soir.","alt":"Cette émission est diffusée le jeudi soir.","note":"le jeudi soir = 每周四晚上；passer = 播出。"}},
 "Une enquête": {"pos":"n.f. 阴性名词，复数 enquêtes","s":"调查；侦查；问卷调查。une enquête policière = 警方调查；une enquête d'opinion = 民意调查；记者的「调查报道」也叫 enquête。","ipa":"[ɑ̃.kɛt]","ph":"en 读 [ɑ̃]；qu 读 [k]；ê 读 [ɛ]；t 读 [t]；结尾 e 不发音。","pi":"en 读 [ɑ̃]，不是 [ɛ̃]；qu 读 [k]；ê 有重音符 ^，拼写别漏掉。","et":"来自古法语 enqueste，源自拉丁语 inquirere（探究）。同源：enquêter、inquisition（来自拉丁语 inquisitio）。","ex":[["Le journaliste fait une enquête.","记者在做调查。"],["La police ouvre une enquête.","警方展开调查。"]],"co":[["mener une enquête","进行调查"],["ouvrir une enquête","展开调查"],["une enquête policière","警方调查"],["une enquête d'opinion","民意调查"]],"sy":[["le sondage","courant","民意调查、抽样调查"],["l'investigation","soutenu","调查、侦查"],["la recherche","courant","研究、寻找"]],"fq":"高频，新闻里常用。","me":"en-quête：一场「寻找」(quête) 真相的行动。","tr":{"zh":"警察对这起事件展开了调查。","fr":"La police a ouvert une enquête sur cette affaire.","alt":"La police enquête sur cette affaire.","note":"enquêter sur = 调查；ouvrir une enquête = 展开调查。"}},
 "Une interview": {"pos":"n.f. 阴性名词，复数 interviews","s":"采访；访谈。une interview 指记者对某人的访谈。求职面试一般不说 interview，要说 un entretien (d'embauche)。faire une interview = 做采访。","ipa":"[ɛ̃.tɛʁ.vju]","ph":"in 读 [ɛ̃]；ter [tɛʁ]；view 读 [vju]，是英语借词。","pi":"第一个音是鼻化音 [ɛ̃]，不是 [in]；view 的 ew 读 [ju]；求职「面试」不常说 interview，要说 entretien。","et":"英语 interview 本身源自古法语 entrevue（会面），所以是「借回来」的词。","ex":[["J'ai lu une interview de cet acteur.","我读了这位演员的采访。"],["Elle donne une interview à la radio.","她在电台接受采访。"]],"co":[["faire une interview","做采访"],["donner une interview","接受采访"],["une interview exclusive","独家采访"],["une interview en direct","现场采访"]],"sy":[["l'entretien","courant","访谈；面试"],["la rencontre","courant","会面"],["la conversation","courant","谈话"]],"fq":"高频，媒体里常用。","me":"inter + view：两个人之间「互相看」= 一问一答。","tr":{"zh":"她在电视上接受了一个采访。","fr":"Elle a donné une interview à la télévision.","alt":"Elle a accordé une interview à la télé.","note":"donner / accorder une interview = 接受采访。"}},
 "Une rubrique": {"pos":"n.f. 阴性名词，复数 rubriques","s":"栏目；版块；专栏。报纸和网站的固定栏目，如 la rubrique sport。也可指「类别」：ranger sous une rubrique。","ipa":"[ʁy.bʁik]","ph":"r [ʁ]；u 读 [y]；b [b]；r [ʁ]；i [i]；q 读 [k]；结尾 e 不发音。","pi":"u 读 [y]；两个 r 都是小舌音 [ʁ]；结尾 que 读 [k]，不是 [kə]。","et":"来自拉丁语 rubrica（红土；红色标题），因为古代标题常用红色书写。","ex":[["Je lis la rubrique sport.","我读体育栏目。"],["Cette rubrique parle de cuisine.","这个栏目讲烹饪。"]],"co":[["la rubrique sport / culture / météo","体育 / 文化 / 天气栏目"],["tenir une rubrique","负责一个专栏"],["sous la rubrique…","在……栏目下"]],"sy":[["la chronique","soutenu","专栏（连载的评论）"],["la section","courant","部分、栏目"],["la catégorie","courant","类别"]],"fq":"中频，媒体里常用。","me":"rubrique ← rubrica（红）：以前栏目标题是红色的。","tr":{"zh":"我先读体育栏目。","fr":"Je commence par lire la rubrique sport.","alt":"Je lis d'abord la rubrique sport.","note":"commencer par + 动词原形。"}},
 "(Rubrique) Faits divers": {"pos":"n.m.pl. 阳性复数名词（固定用复数）：les faits divers","s":"社会新闻；琐碎的社会事件，如事故、小罪案、奇闻。les faits divers 是报纸里的一个固定栏目，常带点戏剧性。","ipa":"[fɛ di.vɛʁ]","ph":"faits 读 [fɛ]，结尾 -ts 不发音；divers 读 [di.vɛʁ]，结尾 s 不发音，r 读 [ʁ]。","pi":"faits 里的 ai 读 [ɛ]，结尾 ts 不发音；fait 单独说也是 [fɛ]；divers 里的 r 要发音，s 不发音。","et":"fait 来自拉丁语 factum（做过的事）；divers 来自拉丁语 diversus（不同的）。","ex":[["Je lis toujours les faits divers.","我总是读社会新闻。"],["Les faits divers passent à la fin du journal.","社会新闻在新闻节目的最后播出。"]],"co":[["la rubrique des faits divers","社会新闻栏目"],["un fait divers","一则社会新闻"],["les faits divers du jour","今日社会新闻"]],"sy":[["l'actualité locale","courant","本地新闻"],["les nouvelles","courant","消息"],["la chronique judiciaire","soutenu","司法新闻"]],"fq":"中频，新闻话题里常见。","me":"fait（事）+ divers（各种）= 各种各样的小事。","tr":{"zh":"我爷爷每天读社会新闻。","fr":"Mon grand-père lit les faits divers tous les jours.","alt":"Mon grand-père lit les faits divers chaque jour.","note":"les faits divers 固定用复数；fait 单数时是 un fait divers。"}},
 "Les élections présidentielles": {"pos":"n.f.pl. 阴性复数名词；présidentielles 是 présidentiel 的阴性复数","s":"总统选举；总统大选。法国每五年举行一次。présidentielles 是阴性复数形容词，与 les élections 配合。也常简称 la présidentielle。","ipa":"[e.lɛk.sjɔ̃ pʁe.zi.dɑ̃.sjɛl]","ph":"élections 读 [e.lɛk.sjɔ̃]；présidentielles 读 [pʁe.zi.dɑ̃.sjɛl]，ti 读 [sj]，en 读 [ɑ̃]，elles 读 [ɛl]。","pi":"élections 结尾 s 不发音，后接元音才连读 [z]；présidentielles 里 s 在元音间读 [z]；ti 读 [sj]。","et":"élection 来自拉丁语 electio（选择）；président 来自拉丁语 praesidens（坐在前面的人）。","ex":[["Les élections présidentielles approchent.","总统选举临近了。"],["Les Français votent pour les élections présidentielles.","法国人为总统大选投票。"]],"co":[["voter aux élections","参加选举投票"],["un candidat à la présidentielle","总统候选人"],["le premier / le second tour","第一轮 / 第二轮"],["gagner les élections","赢得选举"]],"sy":[["la présidentielle","familier","总统大选（简称）"],["le scrutin","soutenu","投票"],["les législatives","courant","议会选举"]],"fq":"中频，新闻和政治话题里常见。","me":"élection + présidentielle：选出总统 = 总统选举。","tr":{"zh":"总统选举在春天举行。","fr":"Les élections présidentielles ont lieu au printemps.","alt":"La présidentielle a lieu au printemps.","note":"avoir lieu = 举行；复数主语 → ont lieu。"}},
 "Les infos / Les informations": {"pos":"n.f.pl. 阴性复数名词；infos 是 informations 的口语缩写","s":"新闻；资讯。les informations（缩写 les infos）既指电视广播的新闻节目，也指各种消息。单数 une information 是「一条消息」。","ipa":"[ɛ̃.fo] / [ɛ̃.fɔʁ.ma.sjɔ̃]","ph":"infos：in 读 [ɛ̃]，o 读 [o]，结尾 s 不发音；informations：in [ɛ̃]，for [fɔʁ]，ma [ma]，tions 读 [sjɔ̃]。","pi":"infos 结尾 s 不发音，o 是长音 [o]；informations 的 -tions 读 [sjɔ̃]，不是 [tjɔ̃]；une information 单数的 information 也是阴性。","et":"来自拉丁语 informatio（形成观念，说明），源自 informare（赋予形态；告知）。infos 是缩写。","ex":[["Je regarde les infos tous les soirs.","我每晚看新闻。"],["Quelles sont les informations du jour ?","今天有什么新闻？"]],"co":[["regarder les infos","看新闻"],["les informations de 20 heures","晚八点新闻"],["une information importante","一条重要消息"],["demander des informations","咨询信息"]],"sy":[["les actualités","courant","时事新闻"],["les nouvelles","courant","消息"],["le journal télévisé","courant","电视新闻节目"]],"fq":"极高频，日常常用。","me":"infos = informations 去掉后半截，像「新闻」的昵称。","tr":{"zh":"你看了今晚的新闻吗？","fr":"Tu as regardé les infos ce soir ?","alt":"T'as vu les infos ce soir ?","note":"t'as 是口语缩写，口语省略 tu 的 u。"}},
 "Les nouvelles": {"pos":"n.f.pl. 阴性复数名词，单数 une nouvelle","s":"新闻；消息。les nouvelles 指各种消息；une bonne nouvelle = 一个好消息；donner de ses nouvelles = 报平安，说近况。单数 une nouvelle 还有「短篇小说」的意思。","ipa":"[nu.vɛl]","ph":"n [n]；ou [u]；v [v]；elle 读 [ɛl]；结尾 s 不发音。","pi":"ou 读 [u]；-elle 读 [ɛl]，ll 读 [l]；les nouvelles 结尾 s 不发音。","et":"来自 nouveau（新的），阴性形式 nouvelle，拉丁语 novellus（新的）的派生词。","ex":[["Il regarde les nouvelles à la télé.","他在电视上看新闻。"],["Tu as de bonnes nouvelles ?","你有好消息吗？"]],"co":[["avoir de bonnes nouvelles","有好消息"],["donner de ses nouvelles","报平安"],["prendre des nouvelles de qqn","问候某人近况"],["une bonne / mauvaise nouvelle","好消息 / 坏消息"]],"sy":[["les infos","familier","新闻（口语）"],["les informations","courant","新闻、资讯"],["le message","courant","消息、短信"]],"fq":"极高频，日常常用。","me":"nouvelle = 新的 (nouveau) 东西 = 消息。","tr":{"zh":"你有你妈妈的消息吗？","fr":"Tu as des nouvelles de ta mère ?","alt":"T'as des nouvelles de ta mère ?","note":"avoir des nouvelles de qqn = 有某人的消息。"}},
 "Miss France": {"pos":"n.f. 阴性专有名词；也指当选者，常不变","s":"法国小姐（选美比赛及其冠军）。Miss France 既是比赛的名字，也是冠军的头衔：Miss France 2024。miss 来自英语，是对未婚女子的称呼缩写。","ipa":"[mis fʁɑ̃s]","ph":"miss 读 [mis]，ss 读 [s]；France 读 [fʁɑ̃s]，an 读 [ɑ̃]，c 读 [s]。","pi":"miss 的 ss 读 [s]，不是 [z]；France 里 an 是鼻化音 [ɑ̃]，c 读 [s]；Miss 的 M 大写。","et":"miss 借自英语，是 mistress（夫人）的缩写；France 的来历与法兰克人（Francs）有关。","ex":[["Elle regarde l'élection de Miss France.","她看法国小姐选美。"],["Miss France est élue chaque année.","法国小姐每年选出。"]],"co":[["l'élection de Miss France","法国小姐选美"],["une candidate à Miss France","法国小姐参赛者"],["être élue Miss France","当选法国小姐"]],"sy":[["un concours de beauté","courant","选美比赛"],["la reine de beauté","courant","选美皇后"],["le mannequin","courant","模特"]],"fq":"中频，法国文化话题里常见。","me":"Miss + France：法国的「小姐」，注意 ss 读 [s]。","tr":{"zh":"每年十二月她都看法国小姐选美。","fr":"Chaque année en décembre, elle regarde Miss France.","alt":"Tous les ans en décembre, elle regarde l'élection de Miss France.","note":"Miss France 是节目名，前面不加冠词。"}},
 "Un \"gamer\"": {"pos":"n.m./n.f. 名词，阳性和阴性同形（un gamer / une gamer 或 une gameuse），复数 gamers","s":"游戏玩家；爱玩电子游戏的人。借自英语，口语和网络上常用。阴性可说 une gameuse；一般泛指爱打游戏的人。","ipa":"[ɡɛ.mœʁ]","ph":"g 读 [ɡ]；a 读 [ɛ]（英语 game 的借音）；mer 读 [mœʁ]，结尾 r 要发。","pi":"发音是 [ɡɛ.mœʁ]，不是英语的 [ˈɡeɪmər]；结尾 r 读 [ʁ]。","et":"借自英语 gamer，由 game（游戏）加 -er 构成。","ex":[["Mon frère est un vrai gamer.","我哥哥是个真正的玩家。"],["Elle joue en ligne avec d'autres gamers.","她和其他玩家在线上玩。"]],"co":[["un gamer passionné","狂热的玩家"],["un gamer professionnel","职业玩家"],["jouer en ligne","在线玩游戏"]],"sy":[["un joueur","courant","玩家（更常用）"],["un joueur de jeux vidéo","courant","电子游戏玩家"],["un geek","familier","技术迷、宅"]],"fq":"中频，年轻人口语里常见。","me":"game + er：玩 game 的人。","tr":{"zh":"我弟弟每天晚上都打游戏，他是个玩家。","fr":"Mon petit frère joue tous les soirs, c'est un vrai gamer.","alt":"Mon petit frère passe ses soirées à jouer, c'est un gamer.","note":"c'est un vrai gamer：c'est + 名词。"}},
 "Un auditeur / Une auditrice": {"pos":"n.m./n.f. 阳性 un auditeur，阴性 une auditrice","s":"听众（广播、讲座）；旁听生。l'auditeur d'une radio = 电台听众。阳性 auditeur，阴性 auditrice。电视观众不用 auditeur，用 téléspectateur。","ipa":"[o.di.tœʁ] / [o.di.tʁis]","ph":"au 读 [o]；di [di]；阳性 -teur 读 [tœʁ]；阴性 -trice 读 [tʁis]。","pi":"au 读 [o]；阳性结尾 [tœʁ]，阴性结尾 [tʁis]；不要把 audi- 读成 [ɔ.di]。","et":"来自拉丁语 auditor，源自 audire（听）。同源：audio、audition。","ex":[["L'auditeur écoute la radio.","听众在听广播。"],["Les auditeurs appellent l'émission.","听众给节目打电话。"]],"co":[["un auditeur de radio","广播听众"],["un auditeur libre","旁听生"],["chers auditeurs","亲爱的听众们"]],"sy":[["le public","courant","公众、观众（集体）"],["le spectateur","courant","观众"],["le téléspectateur","courant","电视观众"]],"fq":"中频，广播话题里常见。","me":"audi- = 听（audio）+ -teur：「听的人」。","tr":{"zh":"听众给电台打电话。","fr":"Les auditeurs téléphonent à la radio.","alt":"Les auditeurs appellent la radio.","note":"téléphoner à qqn；appeler qqn 不加 à。"}},
 "Un narrateur / Une narratrice": {"pos":"n.m./n.f. 阳性 un narrateur，阴性 une narratrice","s":"叙述者；旁白。在小说、纪录片、电影里讲故事的那个声音。阳性 narrateur，阴性 narratrice。le narrateur 可以是作者，也可以是故事里的人物。","ipa":"[na.ʁa.tœʁ] / [na.ʁa.tʁis]","ph":"na [na]；rra 读 [ʁa]；阳性 -teur 读 [tœʁ]，阴性 -trice 读 [tʁis]。","pi":"narrateur 拼写里有两个 r，只读一个 [ʁ]；结尾 -teur 的 r 要发音；阴性变成 -trice。","et":"来自拉丁语 narrator，源自 narrare（讲述）。同源：narration、narrer。","ex":[["Le narrateur raconte l'histoire.","叙述者讲述故事。"],["La narratrice est une vieille dame.","叙述者是一位老太太。"]],"co":[["un narrateur omniscient","全知叙述者"],["la voix du narrateur","叙述者的声音"],["un narrateur fiable","可靠的叙述者"]],"sy":[["le conteur","courant","讲故事的人"],["le récitant","soutenu","朗诵者、旁白者"],["la voix off","courant","画外音"]],"fq":"中频，文学和影视里常见。","me":"narrer = 讲述；narrateur = 讲故事的人。","tr":{"zh":"叙述者讲了一个关于海的故事。","fr":"Le narrateur raconte une histoire sur la mer.","alt":"Le narrateur nous raconte une histoire de mer.","note":"raconter une histoire = 讲故事。"}},
 "Un spectateur / Une spectatrice": {"pos":"n.m./n.f. 阳性 un spectateur，阴性 une spectatrice","s":"观众（剧院、电影院、体育场）；旁观者。les spectateurs 是现场观看的人。看电视的人叫 un téléspectateur。阴性 spectatrice。","ipa":"[spɛk.ta.tœʁ] / [spɛk.ta.tʁis]","ph":"sp [sp]；e 读 [ɛ]；ct 读 [kt]；阳性 -teur [tœʁ]，阴性 -trice [tʁis]。","pi":"ct 要读成 [kt]，两个音都发；阳性结尾 r 要发；阴性结尾 -trice 读 [tʁis]。","et":"来自拉丁语 spectator，源自 spectare（观看）。同源：spectacle、spectateur。","ex":[["Le spectateur applaudit à la fin.","观众在结束时鼓掌。"],["Les spectateurs entrent dans la salle.","观众进入大厅。"]],"co":[["un spectateur de théâtre","剧院观众"],["les spectateurs applaudissent","观众鼓掌"],["rester spectateur","袖手旁观"]],"sy":[["le public","courant","公众、观众（集体）"],["le téléspectateur","courant","电视观众"],["le témoin","courant","目击者"]],"fq":"中频，日常常用。","me":"spectacle（演出）+ -ateur：看演出的人。","tr":{"zh":"观众都站起来鼓掌。","fr":"Tous les spectateurs se lèvent et applaudissent.","alt":"Les spectateurs se lèvent pour applaudir.","note":"se lever 是代词动词：se lèvent。"}},
 "Un téléspectateur / Une téléspectatrice": {"pos":"n.m./n.f. 阳性 un téléspectateur，阴性 une téléspectatrice","s":"电视观众。télé（电视）+ spectateur（观众）。看电视的人叫 téléspectateur，现场观众叫 spectateur。阴性 téléspectatrice。","ipa":"[te.le.spɛk.ta.tœʁ] / [te.le.spɛk.ta.tʁis]","ph":"té [te]；lé [le]；然后读 spectateur [spɛk.ta.tœʁ]；阴性 -trice 读 [tʁis]。","pi":"té 和 lé 都有重音符；spectateur 里 ct 读 [kt]；结尾 -teur 的 r 要发音；阴性 -trice。","et":"télé（希腊语 tele，远）+ spectateur（拉丁语 spectator）。","ex":[["Des millions de téléspectateurs regardent le match.","数百万电视观众看这场比赛。"],["Les téléspectateurs aiment cette série.","电视观众喜欢这部剧。"]],"co":[["des millions de téléspectateurs","数百万电视观众"],["l'audience des téléspectateurs","收视率"],["un téléspectateur fidèle","忠实的电视观众"]],"sy":[["le spectateur","courant","观众"],["l'internaute","courant","网民"],["l'auditeur","courant","听众"]],"fq":"中频，媒体话题里常见。","me":"télé + spectateur：看「电视」的观众。","tr":{"zh":"数百万电视观众在看世界杯。","fr":"Des millions de téléspectateurs regardent la coupe du monde.","alt":"Des millions de gens regardent la coupe du monde à la télé.","note":"des millions de + 复数名词。"}},
 "Un(e) envoyé(e) spécial(e)": {"pos":"n.m./n.f. 阳性 un envoyé spécial，阴性 une envoyée spéciale","s":"特派记者；特使。envoyé 是动词 envoyer 的过去分词，作名词用，spécial 说明是为特殊任务派出的。常见：notre envoyé spécial à… = 本报驻……的特派记者。","ipa":"[ɑ̃.vwa.je spe.sjal]","ph":"en 读 [ɑ̃]；voy 读 [vwa.j]；é 读 [e]；spécial 读 [spe.sjal]，ci 读 [sj]。","pi":"envoyé 里 oy 读 [wa.j]；阴性 envoyée 的 -ée 读音不变；spécial 里 c 读 [s]，阴性 spéciale 的结尾 le 读 [l]。","et":"envoyer 来自俗拉丁语 inviare（上路），源自 via（路）；spécial 来自拉丁语 specialis。","ex":[["L'envoyé spécial est à Paris.","特派记者在巴黎。"],["Notre envoyée spéciale nous parle de Londres.","我们的特派记者给我们讲伦敦的情况。"]],"co":[["notre envoyé spécial à…","本报驻……的特派记者"],["un envoyé spécial de l'ONU","联合国特使"],["une envoyée spéciale","女特派记者"]],"sy":[["le correspondant","courant","驻外记者"],["le reporter","courant","记者"],["l'émissaire","soutenu","特使"]],"fq":"中频，新闻里常见。","me":"envoyé（派出）+ spécial（特别的）= 被特别派出的人。","tr":{"zh":"我们的特派记者正在伦敦。","fr":"Notre envoyé spécial se trouve à Londres.","alt":"Notre envoyé spécial est à Londres en ce moment.","note":"se trouver = 位于/处于；女记者说 envoyée spéciale。"}},
 "Un(e) internaute": {"pos":"n.m./n.f. 名词，阳性阴性同形：un internaute / une internaute，复数 internautes","s":"网民；上网的人。阴阳性同形，靠冠词区分：un internaute（男）、une internaute（女）。指使用互联网的人。","ipa":"[ɛ̃.tɛʁ.not]","ph":"in 读 [ɛ̃]；ter 读 [tɛʁ]；au 读 [o]；t 读 [t]；结尾 e 不发音。","pi":"第一个音是鼻化音 [ɛ̃]；au 读 [o]；结尾 -naute 读 [not]，t 要发音，e 不发音。","et":"由 internet 和 -naute（希腊语 nautes，水手；如 astronaute）构成，意思是「在网上航行的人」。","ex":[["L'internaute visite un site web.","网民访问一个网站。"],["Les internautes donnent leur avis en ligne.","网民在线上发表意见。"]],"co":[["un internaute averti","有经验的网民"],["les internautes français","法国网民"],["l'avis des internautes","网民的意见"]],"sy":[["l'utilisateur","courant","用户"],["le cybernaute","soutenu","网上冲浪者（少用）"],["le surfeur","familier","网上冲浪的人"]],"fq":"中频，网络话题里常见。","me":"internet + naute：像宇航员 (astronaute)，在网上「航行」的人。","tr":{"zh":"网民在网上分享他们的意见。","fr":"Les internautes partagent leurs opinions en ligne.","alt":"Les internautes donnent leur avis sur internet.","note":"en ligne = 在线上；donner son avis = 发表意见。"}},
 "\"Liker\" / Aimer": {"pos":"v.t. 及物动词（第一组，-er）；助动词 avoir","s":"liker = 在社交网络上「点赞」，口语、来自英语 like。aimer = 喜欢；爱；aimer + 名词/动词原形。aimer bien = 比较喜欢；aimer beaucoup = 很喜欢。","ipa":"[laj.ke] / [ɛ.me]","ph":"liker：i 读 [aj]（按英语 like），-er 读 [e]，r 不发。aimer：ai 读 [ɛ]，结尾 -er 读 [e]。","pi":"-er 结尾的 r 不发音；liker 的 i 读 [aj]，不是 [i]。例句里常写成 liké（点赞过了），也可直接说 mettre un j'aime。","et":"liker 来自英语 to like（网络用语）；aimer 来自拉丁语 amare（爱）。","ex":[["Beaucoup de gens ont \"liké\" ma publication.","很多人给我的帖子点了赞。"],["J'aime beaucoup ce film.","我很喜欢这部电影。"],["Elle aime lire le soir.","她喜欢晚上看书。"]],"co":[["liker une photo / une publication","给照片 / 帖子点赞"],["aimer bien","挺喜欢"],["aimer + 动词原形","喜欢做某事"],["Je n'aime pas ça.","我不喜欢这个。"]],"sy":[["adorer","courant","非常喜欢，比 aimer 更强"],["apprécier","courant","欣赏，较温和"],["détester","courant","反义：讨厌"]],"fq":"aimer 极高频；liker 是新的口语词，常见于网络。","me":"liker = like 加 -er，英语词直接穿上法语动词的外衣。","tr":{"zh":"我喜欢你的照片，我给它点了赞。","fr":"J'aime ta photo, je l'ai likée.","alt":"Elle me plaît, ta photo. Je l'ai likée.","note":"liker 按第一组变位；复合过去时：j'ai liké / likée（le 指照片，阴性可加 e）。"}},
 "Augmenter": {"pos":"v. 动词（第一组，-er）；及物 / 不及物；助动词 avoir","s":"增加；上涨。及物：augmenter les prix（涨价）；不及物：Les prix augmentent（价格上涨）。augmenter qqn = 给某人加薪。","ipa":"[oɡ.mɑ̃.te]","ph":"au 读 [o]；g 读 [ɡ]；en 读鼻化音 [ɑ̃]；结尾 -er 读 [e]。","pi":"au 读 [o]，不是 [au]；en 是鼻化元音 [ɑ̃]，别读成 [ɛn]。反义词是 diminuer。","et":"来自晚期拉丁语 augmentare，源于 augere（增加）。同族：augmentation。","ex":[["Le prix de l'essence va augmenter.","汽油价格将上涨。"],["Mon patron a augmenté mon salaire.","我的老板给我加了薪。"],["Le nombre d'élèves augmente chaque année.","学生人数每年都在增加。"]],"co":[["augmenter les prix","涨价"],["augmenter le salaire","加薪"],["augmenter de 10 %","上涨 10%"],["une augmentation de salaire","加薪"]],"sy":[["monter","courant","上升，较口语"],["hausser","soutenu","提高（价格、声音）"],["diminuer","courant","反义：减少"]],"fq":"高频，新闻和日常都常用。","me":"aug- 像 August（八月，逐渐增长的夏天）：越来越多。","tr":{"zh":"房租又涨了。","fr":"Le loyer a encore augmenté.","alt":"Le loyer a augmenté, encore une fois.","note":"不及物用法：主语是涨的东西，不用 se。"}},
 "Commenter": {"pos":"v. 动词（第一组，-er）；及物；助动词 avoir","s":"评论；解说；在网上留言。commenter un article / un match = 评论文章 / 解说比赛。名词 un commentaire = 评论。","ipa":"[kɔ.mɑ̃.te]","ph":"c 读 [k]；o 读 [ɔ]；mm 只读一个 [m]；en 读 [ɑ̃]；-er 读 [e]。","pi":"mm 不要读成两个 m；en 是鼻化元音 [ɑ̃]。注意：commenter 是及物动词，不加介词（英语 comment on 需要 on，法语不需要）。","et":"来自拉丁语 commentari（思考，写评论）。同族：commentaire、commentateur。","ex":[["Tu peux commenter cet article.","你可以评论这篇文章。"],["Il commente le match à la radio.","他在广播里解说比赛。"],["Je ne veux pas commenter.","我不想发表评论。"]],"co":[["commenter une vidéo","评论一个视频"],["laisser un commentaire","留下一条评论"],["sans commentaire","无可奉告"],["commenter l'actualité","评论时事"]],"sy":[["expliquer","courant","解释，不一定是评论"],["critiquer","courant","批评，偏负面"],["réagir","courant","作出反应，回应"]],"fq":"较高频，网络和新闻里常用。","me":"comment-er：用 comment（怎么）去谈「怎么样」。","tr":{"zh":"她在我的视频下留言了。","fr":"Elle a commenté ma vidéo.","alt":"Elle a laissé un commentaire sous ma vidéo.","note":"commenter 直接带宾语，不加 sur / à。"}},
 "Diffuser": {"pos":"v.t. 及物动词（第一组，-er）；助动词 avoir","s":"播出；传播；散发。diffuser un film / un match = 播放电影 / 转播比赛；diffuser une information = 传播消息；也可指香味、光线的散发。","ipa":"[di.fy.ze]","ph":"i 读 [i]；u 读 [y]（嘴唇圆、舌位前）；s 在两个元音间读 [z]；-er 读 [e]。","pi":"u 读 [y]，不是 [u]；s 读 [z]，不是 [s]。","et":"来自拉丁语 diffundere（向四处倾倒、散开）。同族：diffusion、diffuseur。","ex":[["La chaîne va diffuser le match.","频道将转播比赛。"],["Ce film est diffusé ce soir à 21 h.","这部电影今晚 21 点播出。"],["Ils diffusent de la musique dans le magasin.","他们在商店里播放音乐。"]],"co":[["diffuser une émission","播出节目"],["diffuser une information","传播信息"],["être diffusé en direct","被直播"],["la diffusion","播出；传播"]],"sy":[["émettre","courant","发射，播送"],["répandre","courant","散布，传开"],["passer","familier","播放（passer un film）"]],"fq":"中频，媒体用语。","me":"dif-fus-er：像 diffuseur（香薰扩散器），把东西「扩散」出去。","tr":{"zh":"这个节目每晚都播出。","fr":"Cette émission est diffusée tous les soirs.","alt":"On passe cette émission tous les soirs.","note":"被动 être diffusé(e)；on passe 更口语。"}},
 "Diminuer": {"pos":"v. 动词（第一组，-er）；及物 / 不及物；助动词 avoir","s":"减少；下降。diminuer le prix = 降价；Le bruit diminue = 噪音变小。也可说 diminuer de 5 % = 降低 5%。","ipa":"[di.mi.nɥe]","ph":"u 在 i 后读半元音 [ɥ]（嘴唇圆，快速滑过）；-er 读 [e]。","pi":"nu 读 [nɥe]，不是 [nue]，也不是 [nyer]；-er 的 r 不发音。","et":"来自拉丁语 diminuere / deminuere，源于 minus（更少）。同族：minimum、minute、diminution。","ex":[["La température va diminuer ce soir.","今晚气温会下降。"],["Il faut diminuer la vitesse.","必须降低速度。"],["Le nombre de touristes a diminué.","游客人数减少了。"]],"co":[["diminuer de moitié","减少一半"],["diminuer les dépenses","减少开支"],["une diminution des prix","价格下降"],["diminuer la vitesse","减速"]],"sy":[["baisser","courant","降低，较口语"],["réduire","courant","缩减（主动减）"],["augmenter","courant","反义：增加"]],"fq":"较高频，日常和新闻都常用。","me":"di-minu-er：里面有 minus（少），所以是「变少」。","tr":{"zh":"我想减少糖的摄入。","fr":"Je veux diminuer ma consommation de sucre.","alt":"Je veux manger moins de sucre.","note":"diminuer 可带宾语，也可单独作不及物。"}},
 "Poster": {"pos":"v. 动词（第一组，-er）；及物；助动词 avoir","s":"在网上发帖，发布（照片、评论）。也可指「寄出」（poster une lettre = 投寄信件）。另有 se poster = 站岗，就位。","ipa":"[pɔs.te]","ph":"o 读 [ɔ]；s 读 [s]，后接 t；-er 读 [e]。","pi":"不要和英语 poster（海报）混淆：法语的「海报」是 une affiche。-er 的 r 不发音。","et":"上网的「发帖」义来自英语 to post；「寄信」义来自 poste（邮政），意大利语 posta。","ex":[["Il a posté une photo sur Instagram.","他在 Instagram 上发了一张照片。"],["Je dois poster cette lettre.","我得寄这封信。"],["Elle poste des vidéos tous les jours.","她每天都发视频。"]],"co":[["poster un message","发一条消息"],["poster un commentaire","发评论"],["poster une lettre","寄信"],["un post","一篇帖子（口语）"]],"sy":[["publier","courant","发布，更通用"],["envoyer","courant","发送，寄"],["partager","courant","分享"]],"fq":"中高频，社交网络常见。","me":"poster = post 加 -er；寄信靠 la poste（邮局）。","tr":{"zh":"我昨天发了一张新照片。","fr":"J'ai posté une nouvelle photo hier.","alt":"Hier, j'ai mis une nouvelle photo en ligne.","note":"mettre en ligne 是更口语的换法。"}},
 "Recevoir": {"pos":"v. 动词（第三组，不规则）；助动词 avoir；过去分词 reçu","s":"收到；接待客人。recevoir un message = 收到消息；recevoir des amis = 招待朋友；recevoir un appel = 接到电话。","ipa":"[ʁə.sə.vwaʁ]","ph":"r 是小舌音 [ʁ]；re- 读 [ʁə]；ce 读 [sə]；oi 读 [wa]；结尾 r 发音。","pi":"结尾 r 要发（不同于 -er 动词）。变位：je reçois, nous recevons；c 在 o/u 前要写成 ç 才读 [s]：je reçois, reçu。","et":"来自拉丁语 recipere（接收）。同族：réception、récepteur、recette。","ex":[["J'ai reçu un message.","我收到一条消息。"],["Nous recevons des amis ce soir.","今晚我们招待朋友。"],["Il reçoit beaucoup d'emails.","他收到很多电子邮件。"]],"co":[["recevoir un colis / un mail","收到包裹 / 邮件"],["recevoir des amis","招待朋友"],["recevoir un cadeau","收到礼物"],["bien recevoir qqn","好好招待某人"]],"sy":[["obtenir","courant","获得（主动争取）"],["accueillir","courant","迎接，接待"],["envoyer","courant","反义：发送"]],"fq":"极高频。","me":"re + cevoir：「拿回来」→ 收到；ç 记 reçu。","tr":{"zh":"你收到我的邮件了吗？","fr":"Tu as reçu mon mail ?","alt":"Mon mail, tu l'as reçu ?","note":"过去分词 reçu；邮件 mail 是阳性。"}},
 "Sensibiliser": {"pos":"v.t. 及物动词（第一组，-er）；助动词 avoir","s":"使人意识到；提高……的认识。固定搭配 sensibiliser qqn à qqch = 让某人关注 / 重视某事。也可指使对光、过敏等敏感（较专业）。","ipa":"[sɑ̃.si.bi.li.ze]","ph":"sen 读 [sɑ̃]；s 读 [s]；i 读 [i]；-er 读 [e]。","pi":"s 在 sen- 开头读 [s]，在最后的 -iser 里读 [z]；介词是 à（sensibiliser à），不是 sur。","et":"来自 sensible（敏感的）加 -iser。sensible 来自拉丁语 sensibilis（可感觉的）。","ex":[["Il faut sensibiliser les gens à ce problème.","必须让人们认识到这个问题。"],["L'école sensibilise les enfants à l'écologie.","学校让孩子们重视环保。"],["Cette campagne sensibilise le public.","这个宣传活动提高了公众的意识。"]],"co":[["sensibiliser qqn à qqch","让某人关注某事"],["une campagne de sensibilisation","宣传 / 提高认识的活动"],["sensibiliser le public","提高公众意识"],["être sensible à","对……敏感"]],"sy":[["informer","courant","告知，较中性"],["éveiller","soutenu","唤醒（意识）"],["conscientiser","soutenu","使有觉悟，较少用"]],"fq":"中频，常见于社会、环保话题。","me":"sensible + -iser：让人变得「敏感」起来。","tr":{"zh":"我们应该让孩子重视垃圾分类。","fr":"On doit sensibiliser les enfants au tri des déchets.","alt":"Il faut apprendre aux enfants à trier les déchets.","note":"sensibiliser qqn à + 名词；à + le = au。"}},
 "Souhaiter": {"pos":"v.t. 及物动词（第一组，-er）；助动词 avoir","s":"祝愿；希望。souhaiter + 名词 = 祝；souhaiter + 动词原形 / que + 虚拟式 = 希望。比 vouloir 更礼貌、更含蓄。","ipa":"[swɛ.te]","ph":"ou 读 [u]，接 ai 滑成 [wɛ]；h 不发音；-er 读 [e]。","pi":"h 是哑音，别发 h；ou + ai 连读成 [wɛ]，不是 [u.ɛ] 两个音。souhaiter que 后面用虚拟式：Je souhaite qu'il vienne。","et":"来自古法语 souhaidier，更早的来源不确定。同族：un souhait（愿望）。","ex":[["Je te souhaite un bon anniversaire.","祝你生日快乐。"],["Je souhaite partir tôt demain.","我希望明天早点走。"],["Nous souhaitons que tout se passe bien.","我们希望一切顺利。"]],"co":[["souhaiter un bon anniversaire","祝生日快乐"],["souhaiter bonne chance","祝好运"],["souhaiter que + 虚拟式","希望……"],["à tes souhaits !","（对打喷嚏的人）祝你健康！"]],"sy":[["espérer","courant","盼望，希望会发生"],["désirer","soutenu","渴望，较正式"],["vouloir","courant","想要，更直接"]],"fq":"较高频，常用于问候和礼貌表达。","me":"souhait = sou + hait：一个小小的「愿望」。","tr":{"zh":"我祝你假期愉快。","fr":"Je te souhaite de bonnes vacances.","alt":"Bonnes vacances, je te souhaite le meilleur !","note":"souhaiter à qqn de/que；祝福物用复数 de bonnes vacances。"}},
 "Suivre": {"pos":"v. 动词（第三组，不规则）；助动词 avoir；过去分词 suivi","s":"跟随；关注（账号）；上（课）；遵守。suivre un cours = 上课；suivre un compte = 关注账号；suivre un conseil = 听从建议。","ipa":"[sɥivʁ]","ph":"s 读 [s]；ui 读 [ɥi]；v 读 [v]；结尾 -vre 读 [vʁ]，e 不发音。","pi":"je suis 既是 suivre 的「我跟随」，也是 être 的「我是」，要看语境。变位：je suis, tu suis, il suit, nous suivons。","et":"来自通俗拉丁语 sequere，对应拉丁语 sequi（跟随）。同族：suite、suivant、poursuivre。","ex":[["Je suis beaucoup de comptes.","我关注了很多账号。"],["Elle suit un cours de français.","她在上法语课。"],["Suivez-moi, s'il vous plaît.","请跟我来。"]],"co":[["suivre un cours","上课"],["suivre les conseils","听从建议"],["suivre un régime","节食"],["à suivre","未完待续"]],"sy":[["accompagner","courant","陪伴"],["obéir","courant","服从"],["devancer","soutenu","反向：走在前面"]],"fq":"极高频。","me":"suivre — suite（后续）：一个跟着一个。","tr":{"zh":"我关注她的账号。","fr":"Je suis son compte.","alt":"Je la suis sur Instagram.","note":"je suis 可能是 être 或 suivre，看语境。"}},
 "Connecté(e)": {"pos":"adj. 形容词，阴性 connectée，复数 connecté(e)s","s":"联网的；在线的；智能的（设备）。une montre connectée = 智能手表；être connecté = 在线。","ipa":"[kɔ.nɛk.te]","ph":"o 读 [ɔ]；nn 只读一个 [n]；e 读 [ɛ]，c 读 [k]；-é 读 [e]。","pi":"-é 读 [e]，阴性 -ée 读音不变；别拼成 conecté。","et":"来自 connecter（连接），拉丁语 connectere（连在一起）。同族：connexion、déconnecté。","ex":[["Il a une montre connectée.","他有一块智能手表。"],["Je ne suis pas connecté en ce moment.","我现在不在线。"],["Elle habite dans une maison connectée.","她住在一所智能房子里。"]],"co":[["un objet connecté","智能设备"],["être connecté à internet","连着互联网"],["une enceinte connectée","智能音箱"],["rester connecté","保持在线"]],"sy":[["intelligent","courant","智能的（英语 smart 的常用替代）"],["en ligne","courant","在线"],["déconnecté","courant","反义：断线的"]],"fq":"较高频，科技话题常见。","me":"connecté：像被一根线接（connecter）上了网。","tr":{"zh":"我买了一个智能音箱。","fr":"J'ai acheté une enceinte connectée.","alt":"Je me suis offert une enceinte connectée.","note":"形容词随名词变阴性：enceinte 阴性，所以 connectée。"}},
 "Digital(e)": {"pos":"adj. 形容词，阴性 digitale，阳性复数 digitaux","s":"数字的；数字化的。在「数码、网络」义上与 numérique 接近，但 numérique 更标准。digital 也用于营销（le marketing digital）。","ipa":"[di.ʒi.tal]","ph":"g 在 i 前读 [ʒ]；i 读 [i]；结尾 -al 读 [al]。","pi":"g 在 i 前读 [ʒ]，不是 [ɡ]。阳性复数是 digitaux，不是 digitals。","et":"拉丁语 digitalis（手指的），来自 digitus（手指）；「数字」义经由英语 digital 流行。","ex":[["C'est une entreprise digitale.","这是一家数字化公司。"],["Je travaille dans le marketing digital.","我在数字营销行业工作。"],["Les outils digitaux changent notre vie.","数字工具改变了我们的生活。"]],"co":[["le marketing digital","数字营销"],["l'ère digitale","数字时代"],["une empreinte digitale","指纹"],["un outil digital","数字工具"]],"sy":[["numérique","courant","最标准的「数字的」"],["électronique","courant","电子的"],["analogique","courant","反义：模拟的"]],"fq":"中频，商业与科技用语。","me":"digital 来自 digit（手指）：先用手指数数，再到数字。","tr":{"zh":"我们公司在做数字化转型。","fr":"Notre entreprise fait sa transformation digitale.","alt":"Notre entreprise passe au numérique.","note":"法语里 numérique 更常用，digital 也很常见。"}},
 "Hebdomadaire": {"pos":"adj. 形容词（阴阳同形），复数 hebdomadaires；也是名词 un hebdomadaire = 周刊","s":"每周的。un magazine hebdomadaire = 周刊；日常口语常缩成 un hebdo。例：un rendez-vous hebdomadaire = 每周一次的约会。","ipa":"[ɛb.dɔ.ma.dɛʁ]","ph":"h 不发音；e 读 [ɛ]；bd 连读 [bd]；o 读 [ɔ]；-aire 读 [ɛʁ]。","pi":"开头 h 不发音，但 e 读 [ɛ]；bd 连在一起，音节是 ɛb.dɔ。拼写很难：heb-do-ma-daire，对着读音拆开记。","et":"来自希腊语 hebdomas（七，一组七天），经拉丁语 hebdomadarius。同族：hebdo（缩略）。","ex":[["Je lis un magazine hebdomadaire.","我读一本周刊。"],["Nous avons une réunion hebdomadaire le lundi.","我们每周一开例会。"],["C'est un hebdo très connu.","这是一本很有名的周刊。"]],"co":[["un magazine hebdomadaire","周刊"],["une réunion hebdomadaire","周会"],["le rythme hebdomadaire","每周的频率"],["un abonnement hebdomadaire","每周订阅"]],"sy":[["chaque semaine","courant","每周（副词短语，更口语）"],["mensuel","courant","每月的"],["quotidien","courant","每天的"]],"fq":"中低频，书面和媒体用语。","me":"hebdo = 七天：像 week 里的 seven 一样，七天一次。","tr":{"zh":"我每周开一次会。","fr":"J'ai une réunion hebdomadaire.","alt":"J'ai une réunion chaque semaine.","note":"hebdomadaire 阴阳同形；口语多用 chaque semaine。"}},
 "Intellectuel(le)": {"pos":"adj. 形容词，阴性 intellectuelle；也可作名词 un intellectuel（知识分子）","s":"脑力的；智力的；知识分子的。un travail intellectuel = 脑力劳动；un intellectuel = 知识分子（名词）。","ipa":"[ɛ̃.tɛ.lɛk.tɥɛl]","ph":"in 读鼻化 [ɛ̃]；t 读 [t]；e 读 [ɛ]；ll 读一个 [l]；tuel 读 [tɥɛl]。","pi":"in 是鼻化元音 [ɛ̃]，别读成 [in]；-ue- 读 [ɥɛ]；阴性 intellectuelle 在 l 后加 e，读音基本不变。","et":"拉丁语 intellectualis，来自 intelligere（理解）。同族：intelligent、intellect。","ex":[["C'est un travail intellectuel.","这是脑力工作。"],["Elle a une vie très intellectuelle.","她的生活很有思想性。"],["Les intellectuels parlent souvent de politique.","知识分子常常谈政治。"]],"co":[["un travail intellectuel","脑力劳动"],["une activité intellectuelle","智力活动"],["un effort intellectuel","脑力付出"],["la propriété intellectuelle","知识产权"]],"sy":[["mental","courant","精神的，头脑的"],["cérébral","soutenu","大脑的，偏理性"],["manuel","courant","反义：体力的"]],"fq":"中频，书面和正式场合常用。","me":"intellect + uel：和 intelligent 同家族，动脑的。","tr":{"zh":"他更喜欢脑力工作。","fr":"Il préfère le travail intellectuel.","alt":"Il aime mieux un travail intellectuel qu'un travail manuel.","note":"préférer + 定冠词 + 名词（le travail intellectuel）。"}},
 "Interactif / Interactive": {"pos":"adj. 形容词，阳性 interactif，阴性 interactive","s":"互动的；交互式的。un jeu interactif = 互动游戏；un tableau interactif = 互动白板。指能相互作用、让用户参与。","ipa":"[ɛ̃.tɛ.ʁak.tif] / [ɛ̃.tɛ.ʁak.tiv]","ph":"in 读鼻化 [ɛ̃]；e 读 [ɛ]；r 读 [ʁ]；-if 读 [if]，阴性 -ive 读 [iv]。","pi":"in 读 [ɛ̃]；阳性结尾 f 读 [f]，阴性变 v 读 [v]（-if → -ive）。","et":"inter- + actif（活跃的），拉丁语 inter（在……之间）和 activus。同族：interaction、agir。","ex":[["Ce jeu vidéo est très interactif.","这款游戏互动性很强。"],["Nous avons une carte interactive de la ville.","我们有一张城市互动地图。"],["C'est un cours interactif en ligne.","这是一门在线互动课程。"]],"co":[["un jeu interactif","互动游戏"],["une carte interactive","互动地图"],["un écran interactif","互动屏幕"],["un cours interactif","互动课"]],"sy":[["participatif","courant","参与式的"],["dynamique","courant","有活力的"],["passif","courant","反义：被动的"]],"fq":"中频，科技和教育里常见。","me":"inter + actif：大家一起 act（行动）。","tr":{"zh":"这个应用很有互动性。","fr":"Cette application est très interactive.","alt":"C'est une appli vraiment interactive.","note":"application 阴性，所以用 interactive。"}},
 "Mensuel(le)": {"pos":"adj. 形容词，阴性 mensuelle；也是名词 un mensuel（月刊）","s":"每月的；按月的。un abonnement mensuel = 月度订阅；un salaire mensuel = 月薪。un mensuel = 月刊。","ipa":"[mɑ̃.sɥɛl]","ph":"en 读鼻化 [ɑ̃]；s 读 [s]；ue 读 [ɥɛ]；ll 读一个 [l]。","pi":"en 读 [ɑ̃]，不是 [ɛn]；-uel 读 [ɥɛl]；阴性 mensuelle 读音不变。","et":"来自拉丁语 mensualis，源于 mensis（月）。同族：mois、semestre。","ex":[["C'est un abonnement mensuel.","这是按月订阅。"],["Mon salaire mensuel est de 2 000 euros.","我的月薪是 2000 欧元。"],["Nous payons un loyer mensuel.","我们按月付房租。"]],"co":[["un abonnement mensuel","月度订阅"],["un salaire mensuel","月薪"],["un paiement mensuel","按月付款"],["un magazine mensuel","月刊"]],"sy":[["par mois","courant","每月（短语，更口语）"],["hebdomadaire","courant","每周的"],["annuel","courant","每年的"]],"fq":"中高频，账单、订阅中常见。","me":"mensuel：和 mois（月）同根，拼写里藏着 mens。","tr":{"zh":"月租是 500 欧元。","fr":"Le loyer mensuel est de 500 euros.","alt":"Le loyer, c'est 500 euros par mois.","note":"mensuel 修饰阳性 loyer，不变。"}},
 "Nerveux / Nerveuse": {"pos":"adj. 形容词，阳性 nerveux，阴性 nerveuse，阳性复数 nerveux","s":"紧张的；神经质的；易激动的。être nerveux = 紧张。注意：一般不指「胆小」，更像是「紧张不安」。","ipa":"[nɛʁ.vø] / [nɛʁ.vøz]","ph":"e 读 [ɛ]；r 读 [ʁ]；eux 读 [ø]；阴性 -se 读 [z]。","pi":"阳性 nerveux 结尾的 x 不发音；阴性 nerveuse 的 s 读 [z]。-eu- 读 [ø]，不是 [u]。","et":"来自拉丁语 nervosus，源于 nervus（神经，筋）。同族：nerf（神经）、énervé（烦躁的）。","ex":[["Il est un peu nerveux avant l'examen.","考试前他有点紧张。"],["Elle est nerveuse quand elle parle en public.","她当众讲话时会紧张。"],["Ne sois pas nerveux, tout ira bien.","别紧张，一切都会好的。"]],"co":[["être nerveux / nerveuse","紧张"],["un rire nerveux","紧张的笑"],["une dépression nerveuse","神经衰弱 / 精神崩溃"],["le système nerveux","神经系统"]],"sy":[["stressé","familier","有压力的，口语常说"],["inquiet","courant","担心的"],["calme","courant","反义：平静的"]],"fq":"中高频，日常常用。","me":"nerv-eux：神经（nerf）绷得紧紧的。","tr":{"zh":"上台前我有点紧张。","fr":"Je suis un peu nerveux avant de monter sur scène.","alt":"Je stresse un peu avant de monter sur scène.","note":"avant de + 动词原形。"}},
 "Sonore": {"pos":"adj. 形容词（阴阳同形），复数 sonores","s":"声音的；有声的；响亮的。un effet sonore = 音效；la pollution sonore = 噪音污染；une alarme sonore = 声音警报。","ipa":"[sɔ.nɔʁ]","ph":"s 读 [s]；两个 o 都读 [ɔ]；结尾 -re 读 [ɔʁ]，e 不发音。","pi":"结尾 r 要发音，e 不发音；两个 o 都是开口 [ɔ]，别读成 [o]。","et":"来自拉丁语 sonorus，源于 sonus（声音）。同族：son、sonner、résonner。","ex":[["L'effet sonore est très fort.","音效很大。"],["Il y a trop de pollution sonore en ville.","城里的噪音污染太多。"],["Le réveil a une alarme sonore.","闹钟有声音提醒。"]],"co":[["un effet sonore","音效"],["la pollution sonore","噪音污染"],["un signal sonore","声音信号"],["des ondes sonores","声波"]],"sy":[["bruyant","courant","吵闹的"],["audible","courant","听得见的"],["silencieux","courant","反义：安静的"]],"fq":"中频，技术和说明里常见。","me":"sonore 里有 son（声音）：一听就懂。","tr":{"zh":"这个手机有声音提醒。","fr":"Ce téléphone a une alerte sonore.","alt":"Le téléphone émet une alerte sonore.","note":"sonore 阴阳同形。"}},
 "Télévisé(e)": {"pos":"adj. 形容词，阴性 télévisée，复数 télévisé(e)s","s":"电视播出的；电视上的。le journal télévisé = 电视新闻（常缩成 le JT）；un débat télévisé = 电视辩论。","ipa":"[te.le.vi.ze]","ph":"t 读 [t]；é 读 [e]；l 读 [l]；s 在元音间读 [z]；-é 读 [e]。","pi":"s 在两个元音间读 [z]，不是 [s]；有三个 é，别漏掉重音。","et":"来自 télévision + -é。télévision 由希腊语 tele（远）和拉丁语 visio（看见）组成。","ex":[["Je regarde le journal télévisé.","我看电视新闻。"],["Ce débat télévisé est très suivi.","这场电视辩论很多人看。"],["Le match sera télévisé en direct.","比赛将在电视上直播。"]],"co":[["le journal télévisé","电视新闻"],["un débat télévisé","电视辩论"],["une émission télévisée","电视节目"],["télévisé en direct","电视直播"]],"sy":[["à la télé","familier","在电视上，口语"],["diffusé","courant","播出的"],["radiophonique","soutenu","广播的"]],"fq":"中频，媒体用语。","me":"télé（远）+ visé（看）：远处看得见的。","tr":{"zh":"总统的讲话在电视上播出了。","fr":"Le discours du président a été télévisé.","alt":"Le discours du président est passé à la télé.","note":"被动式的形容词用法，要性数配合。"}},
 "En direct": {"pos":"loc. 短语（loc. adv. / adj.），不变","s":"直播地；实时地。une émission en direct = 直播节目；Je vous parle en direct de Paris. = 我在巴黎现场向您报道。也可指「不经中转的」。","ipa":"[ɑ̃.di.ʁɛkt]","ph":"en 读鼻化 [ɑ̃]；di 读 [di]；r 读 [ʁ]；ect 读 [ɛkt]，结尾 c 和 t 都发音。","pi":"direct 的结尾 ct 全部要发音 [ɛkt]，别吞掉；en 是鼻化元音 [ɑ̃]。","et":"direct 来自拉丁语 directus（笔直的），同族：direction、diriger。","ex":[["Cette émission est en direct.","这个节目是直播。"],["Le match passe en direct à 20 h.","比赛 20 点直播。"],["Elle parle en direct avec ses fans.","她正在和粉丝直播。"]],"co":[["en direct de + 地点","从某地直播"],["regarder en direct","看直播"],["un direct","一场直播（名词）"],["en différé","录播"]],"sy":[["en live","familier","直播（英语借词）"],["en temps réel","courant","实时地"],["en différé","courant","反义：录播的"]],"fq":"高频，新闻、网络常用。","me":"en direct = 笔直（direct）送到你眼前，没有延迟。","tr":{"zh":"他们正在网上直播。","fr":"Ils sont en direct sur internet.","alt":"Ils font un live sur internet.","note":"en direct 不变，当副词短语。"}},
 "Être en contact": {"pos":"loc. verbale 动词短语（être + en contact）","s":"保持联系；有接触。être en contact avec qqn = 与某人有联系。强调「现在有联系」，比 rester en contact 更像一个状态。","ipa":"[ɛtʁ ɑ̃ kɔ̃.takt]","ph":"être 读 [ɛtʁ]；en 读 [ɑ̃]；contact 读 [kɔ̃.takt]，结尾 ct 都发音。","pi":"contact 结尾 ct 要发音 [kt]；on 读鼻化 [ɔ̃]。介词用 avec：en contact avec qqn。","et":"contact 来自拉丁语 contactus（接触）。同族：contacter（联系）、contagieux。","ex":[["Je suis en contact avec mes amis.","我和朋友们保持联系。"],["Elle est en contact avec le directeur.","她和经理保持联系。"],["Nous sommes en contact par mail.","我们通过邮件联系。"]],"co":[["être en contact avec qqn","和某人保持联系"],["entrer en contact","取得联系"],["rester en contact","保持联系"],["perdre le contact","失去联系"]],"sy":[["être en relation","courant","有联系，较正式"],["être joignable","courant","能联系上的"],["être sans nouvelles","courant","反义：没有消息"]],"fq":"高频，日常和工作常用。","me":"en contact = 手碰手（contact）的联系。","tr":{"zh":"你还和你的老同学有联系吗？","fr":"Tu es toujours en contact avec tes anciens camarades ?","alt":"Tu gardes contact avec tes anciens camarades ?","note":"être en contact avec + 人。"}},
 "Faire la une / Être à la une": {"pos":"loc. verbale 动词短语；la une 是阴性名词","s":"上头条；登上头版。la une = 报纸第一版。faire la une = 成为头条；être à la une = 正在头条上。","ipa":"[fɛʁ la yn] / [ɛtʁ a la yn]","ph":"faire 读 [fɛʁ]；une 读 [yn]；la une 之间不省音、不连读。","pi":"la une 不省略成 l'une；une 读 [yn]，u 是 [y]，不是 [u]。阴性冠词 la 不变。","et":"la une 是 la première page（头版）的简称，une 是数字 un 的阴性，指报纸的「第一版」。","ex":[["Cette histoire fait la une des journaux.","这件事上了报纸头条。"],["Le président est à la une aujourd'hui.","总统今天上了头条。"],["Elle fait la une des magazines.","她登上了杂志封面。"]],"co":[["faire la une des journaux","登上报纸头条"],["être à la une","正在头条"],["la une du journal","报纸头版"],["la une du site","网站首页焦点"]],"sy":[["faire les gros titres","courant","成为大标题"],["faire le buzz","familier","引发热议"],["passer inaperçu","courant","反义：没引起注意"]],"fq":"中频，新闻用语。","me":"la une = 第 1 页：数字 1（une）就是头条。","tr":{"zh":"这则新闻今天上了头条。","fr":"Cette nouvelle fait la une aujourd'hui.","alt":"Aujourd'hui, cette nouvelle est à la une.","note":"la une 固定搭配，不加 de，除非后接报纸。"}},
 "Rester en contact": {"pos":"loc. verbale 动词短语；rester 第一组，助动词 être","s":"保持联系（以后也不断联）。rester en contact avec qqn = 和某人保持联系。强调「保持下去」，有未来感。","ipa":"[ʁɛs.te ɑ̃ kɔ̃.takt]","ph":"rester 读 [ʁɛs.te]；en 读 [ɑ̃]；contact 读 [kɔ̃.takt]。","pi":"rester 的复合过去时用 être：Je suis resté en contact。ct 要发音。","et":"rester 来自拉丁语 restare（留下）；contact 来自拉丁语 contactus。","ex":[["Nous allons rester en contact.","我们会保持联系。"],["Reste en contact avec moi.","和我保持联系。"],["Ils sont restés en contact après le voyage.","旅行后他们一直保持联系。"]],"co":[["rester en contact avec qqn","和某人保持联系"],["restons en contact","我们保持联系吧"],["rester en contact par mail","通过邮件保持联系"],["garder le contact","保持联系"]],"sy":[["garder contact","courant","保持联系，较口语"],["se tenir au courant","courant","互通消息"],["perdre de vue","courant","反义：失去联系"]],"fq":"高频，告别时常用。","me":"rester = 留下；rester en contact = 人走了，联系还留着。","tr":{"zh":"回国后我们继续保持联系吧。","fr":"Restons en contact après ton retour.","alt":"On reste en contact quand tu seras rentré(e).","note":"命令式第一人称复数 restons。"}},
 "Du matériel": {"pos":"n.m. 阳性名词，复数 matériels（常用单数，不可数）","s":"设备；器材；用具。du matériel 是部分冠词，指一批不可数的「设备」。le matériel de bureau = 办公用品；du matériel informatique = 电脑设备。形容词 matériel(le) 则是「物质的」。","ipa":"[ma.te.ʁjɛl]","ph":"a 读 [a]；t 读 [t]；é 读 [e]；r 读 [ʁ]；-iel 读 [jɛl]。","pi":"du 在这里是部分冠词（de + le），表示「一些」，别当成介词。matériel 是阳性，不是 matériaux（材料）。","et":"来自拉丁语 materialis，源于 materia（物质、木料）。同族：matière、matériau。","ex":[["J'ai besoin de matériel pour travailler.","我需要工作设备。"],["Il achète du matériel de sport.","他买运动器材。"],["Le matériel est dans le garage.","设备在车库里。"]],"co":[["du matériel informatique","电脑设备"],["du matériel de bureau","办公用品"],["du matériel de sport","运动器材"],["louer du matériel","租设备"]],"sy":[["équipement","courant","装备，成套设备"],["outil","courant","工具，单个"],["fournitures","courant","文具、供应品"]],"fq":"较高频，工作和生活常见。","me":"matériel 来自 matière（物质）：实实在在的东西。","tr":{"zh":"我们需要新的办公设备。","fr":"Nous avons besoin de nouveau matériel de bureau.","alt":"Il nous faut du nouveau matériel pour le bureau.","note":"matériel 不可数，用 du。"}},
 "L'immobilier": {"pos":"n.m. 阳性名词，常用单数","s":"房地产；不动产。travailler dans l'immobilier = 做房地产；une agence immobilière = 房产中介。作形容词 immobilier(ère) 也有「不动产的」之意。","ipa":"[i.mɔ.bi.lje]","ph":"i 读 [i]；m 读 [m]；o 读 [ɔ]；-ier 读 [je]；l' 与 i 缩合。","pi":"l'immobilier 里 mm 读一个 [m]；结尾 -ier 读 [je]，r 不发音。注意：immobilier 是房地产，immobile 是「不动的」。","et":"来自 immobile（不动的），加后缀 -ier；拉丁语 immobilis。反义 mobilier（家具、动产）。","ex":[["L'immobilier est cher ici.","这里房产很贵。"],["Il travaille dans l'immobilier.","他在房地产行业工作。"],["Les prix de l'immobilier montent.","房价在上涨。"]],"co":[["le marché immobilier","房地产市场"],["une agence immobilière","房产中介"],["un prêt immobilier","房贷"],["investir dans l'immobilier","投资房地产"]],"sy":[["la pierre","familier","房产（investir dans la pierre）"],["le logement","courant","住房，居住的场所"],["le mobilier","courant","反向：家具、动产"]],"fq":"高频，经济、生活话题常见。","me":"immobilier = 不会动（immobile）的财产：房子搬不走。","tr":{"zh":"我想投资房地产。","fr":"Je veux investir dans l'immobilier.","alt":"J'aimerais acheter de l'immobilier.","note":"investir dans + 名词。"}},
 "Le covoiturage": {"pos":"n.m. 阳性名词，复数 covoiturages","s":"拼车；顺风车。faire du covoiturage = 拼车出行。动词 covoiturer = 拼车。常说 une application de covoiturage = 拼车软件。","ipa":"[ko.vwa.ty.ʁaʒ]","ph":"co 读 [ko]；voi 读 [vwa]；tu 读 [ty]；r 读 [ʁ]；-age 读 [aʒ]。","pi":"voi 读 [vwa]；u 读 [y]；-age 读 [aʒ]，g 读 [ʒ]。名词阳性：le covoiturage（-age 结尾多为阳性）。","et":"由 co-（一起）+ voiturage 构成，voiture 来自拉丁语 vectura（运输）。","ex":[["Je fais du covoiturage pour aller au travail.","我拼车上班。"],["Le covoiturage coûte moins cher.","拼车更便宜。"],["On propose un covoiturage pour le week-end.","我们为周末提供拼车。"]],"co":[["faire du covoiturage","拼车"],["une application de covoiturage","拼车软件"],["une place de covoiturage","拼车座位 / 拼车停车位"],["covoiturer avec qqn","和某人拼车"]],"sy":[["autopartage","courant","共享租车，与拼车不同"],["taxi","courant","出租车"],["transport en commun","courant","公共交通"]],"fq":"中频，环保、通勤话题常见。","me":"co + voiture + age：大家共坐一辆车。","tr":{"zh":"为了省钱，我们去拼车。","fr":"Pour économiser, on fait du covoiturage.","alt":"Pour payer moins, on partage la voiture.","note":"faire du + 名词 表示参与某活动。"}},
 "Le minimum": {"pos":"n.m. 阳性名词，复数 minimums 或 minima","s":"最低限度；最小值。le minimum syndical = 最起码的；au minimum = 至少；faire le minimum = 只做最低要求。","ipa":"[mi.ni.mɔm]","ph":"m 读 [m]；i 读 [i]；-um 读 [ɔm]（不是 [œm]）。","pi":"结尾 -um 读 [ɔm]，不读 [um] 或 [œ̃]。复数 minimums 和 minima 都可以。","et":"来自拉丁语 minimum（最小），源于 minimus。同族：minute、diminuer、minimal。","ex":[["C'est le minimum à faire.","这是最起码要做的。"],["Il faut au minimum dix euros.","至少需要十欧元。"],["Elle fait toujours le minimum.","她总是只做最低限度。"]],"co":[["au minimum","至少"],["le minimum vital","最低生活保障"],["un minimum de + 名词","起码的……"],["faire le minimum","只做最基本的"]],"sy":[["le moins","courant","最少，较口语"],["le seuil","courant","门槛"],["le maximum","courant","反义：最大值"]],"fq":"高频，日常和工作常见。","me":"minimum 里有 mini：「迷你」到不能再小。","tr":{"zh":"这是你至少应该做的。","fr":"C'est le minimum que tu puisses faire.","alt":"Tu devrais au moins faire ça.","note":"le minimum que + 虚拟式。"}},
 "Le recyclage": {"pos":"n.m. 阳性名词，复数 recyclages","s":"回收；再利用；（职业）进修培训。le recyclage du papier = 纸张回收；le recyclage professionnel = 职业再培训。动词 recycler。","ipa":"[ʁə.si.klaʒ]","ph":"re 读 [ʁə]；cy 读 [si]；cl 读 [kl]；-age 读 [aʒ]。","pi":"c 在 y 前读 [s]，在 l 前读 [k]：re-cy-clage 读 [ʁə.si.klaʒ]。-age 结尾的名词通常是阳性。","et":"由 re-（再）+ cycle（循环）+ -age 构成。cycle 来自希腊语 kyklos（圆）。","ex":[["Le recyclage est important.","回收很重要。"],["Nous faisons le recyclage du verre.","我们做玻璃回收。"],["Il suit un recyclage professionnel.","他在接受职业再培训。"]],"co":[["le recyclage du papier / du verre","纸 / 玻璃回收"],["un centre de recyclage","回收中心"],["une poubelle de recyclage","回收垃圾桶"],["un recyclage professionnel","职业再培训"]],"sy":[["tri","courant","分类（le tri sélectif）"],["réutilisation","courant","再利用"],["déchets","courant","垃圾（反向）"]],"fq":"中高频，环保话题常见。","me":"re + cycle：东西再转一圈（cycle）。","tr":{"zh":"回收对环境有好处。","fr":"Le recyclage est bon pour l'environnement.","alt":"Recycler, c'est bon pour la planète.","note":"bon pour + 名词。"}},
 "Un achat": {"pos":"n.m. 阳性名词，复数 achats","s":"购买；买来的东西。faire un achat = 买东西；un bon achat = 买得值；faire des achats = 购物。","ipa":"[a.ʃa]","ph":"a 读 [a]；ch 读 [ʃ]；结尾 -at 的 t 不发音。","pi":"结尾 t 不发音，读 [a.ʃa]；ch 读 [ʃ]。别和 acheter（买，动词）混淆。","et":"来自动词 acheter（买）的名词形式，acheter 源自拉丁语 *accaptare（取得）。","ex":[["C'est un bon achat.","这是一次不错的购买。"],["J'ai fait un gros achat hier.","我昨天买了件大东西。"],["Elle fait des achats en ligne.","她网上购物。"]],"co":[["faire un achat","买东西"],["un achat en ligne","网购"],["un bon / mauvais achat","买得值 / 不值"],["le pouvoir d'achat","购买力"]],"sy":[["acquisition","soutenu","购置，较正式"],["emplette","littéraire","采购（少用）"],["vente","courant","反义：销售"]],"fq":"高频，购物话题常用。","me":"achat 去掉 ter 就是 acheter 的名词：买一下就是 achat。","tr":{"zh":"这是我今年最大的一笔支出。","fr":"C'est mon plus gros achat de l'année.","alt":"C'est la plus grosse dépense de mon année.","note":"最高级 le plus gros 修饰阳性名词 achat。"}},
 "Un atelier": {"pos":"n.m. 阳性名词，复数 ateliers","s":"工作坊；作坊；工作室。un atelier de peinture = 画室；un atelier d'écriture = 写作工作坊；un atelier mécanique = 修理车间。","ipa":"[a.tə.lje]","ph":"a 读 [a]；te 读 [tə]（轻读，有时省略）；-lier 读 [lje]。","pi":"-ier 读 [je]，r 不发音；te 中的 e 很轻，说话快时几乎消失。","et":"来自古法语 astelier，源于 astele（碎木片），拉丁语 astula。原指木匠的工作场所。","ex":[["Il travaille dans un atelier.","他在作坊里工作。"],["Nous participons à un atelier de cuisine.","我们参加烹饪工作坊。"],["Elle a un atelier de peinture chez elle.","她家里有一个画室。"]],"co":[["un atelier de peinture","画室"],["un atelier d'écriture","写作工作坊"],["participer à un atelier","参加工作坊"],["un atelier de réparation","维修作坊"]],"sy":[["studio","courant","工作室"],["usine","courant","工厂，更大"],["garage","courant","汽车修理厂"]],"fq":"中频，生活和文化活动里常见。","me":"atelier：艺术家和工匠待的地方，像 artist 的 a。","tr":{"zh":"周六我去参加一个陶艺工作坊。","fr":"Samedi, je vais à un atelier de poterie.","alt":"Samedi, j'ai un atelier de poterie.","note":"aller à + 名词，à + un 不缩合。"}},
 "Un emploi": {"pos":"n.m. 阳性名词，复数 emplois","s":"工作；职位；用法。chercher un emploi = 找工作；un emploi à temps plein = 全职；le mode d'emploi = 使用说明；l'emploi d'un mot = 词的用法。","ipa":"[ɑ̃.plwa]","ph":"em 读鼻化 [ɑ̃]；oi 读 [wa]；结尾无音。","pi":"em 在这里读 [ɑ̃]，不是 [ɛm]；oi 读 [wa]。别和 travail、job 混淆：emploi 偏指「职位 / 岗位」，较正式。","et":"来自动词 employer（使用，雇用），拉丁语 implicare（卷入，使用）。同族：employé、employeur。","ex":[["Il cherche un emploi.","他在找工作。"],["Elle a trouvé un emploi à Lyon.","她在里昂找到了工作。"],["Je lis le mode d'emploi.","我在读使用说明。"]],"co":[["chercher un emploi","找工作"],["un emploi à temps plein / partiel","全职 / 兼职"],["le mode d'emploi","使用说明"],["l'emploi du temps","时间表，课程表"]],"sy":[["travail","courant","工作，较宽泛"],["poste","courant","职位，具体岗位"],["boulot","familier","活儿，口语"]],"fq":"极高频，求职话题里必备。","me":"emploi 来自 employer（使用）：把人「用」起来。","tr":{"zh":"我正在找一份兼职工作。","fr":"Je cherche un emploi à temps partiel.","alt":"Je cherche un petit boulot à mi-temps.","note":"à temps partiel = 兼职。"}},
 "Un emprunt": {"pos":"n.m. 阳性名词，复数 emprunts","s":"贷款；借用（的东西）；外来词。faire un emprunt = 贷款；un emprunt bancaire = 银行贷款；un emprunt à l'anglais = 借自英语的词。","ipa":"[ɑ̃.pʁœ̃]","ph":"em 读 [ɑ̃]；pr 读 [pʁ]；un 读 [œ̃]；结尾 t 不发音。","pi":"t 不发音；两个鼻化元音 [ɑ̃] 和 [œ̃] 连在一起：em-prunt。别和 prêt（借出的钱）搞混：emprunt 是借入，prêt 是借出。","et":"来自动词 emprunter（借入）。同族：emprunteur（借款人）；对比 prêter（借出）。更早的来源不确定。","ex":[["J'ai fait un emprunt à la banque.","我向银行贷款。"],["Il rembourse son emprunt chaque mois.","他每个月还贷款。"],["Ce mot est un emprunt à l'anglais.","这个词是借自英语的。"]],"co":[["faire un emprunt","贷款"],["un emprunt bancaire","银行贷款"],["rembourser un emprunt","还贷款"],["un emprunt à une langue","借词"]],"sy":[["crédit","courant","信贷，贷款"],["prêt","courant","反义：借出，贷出的款"],["dette","courant","债务"]],"fq":"中频，银行和语言话题常见。","me":"emprunt = 借入；prêt = 借出，p 在后面。","tr":{"zh":"他向银行贷款买了房子。","fr":"Il a fait un emprunt à la banque pour acheter sa maison.","alt":"Il a emprunté de l'argent à la banque pour sa maison.","note":"emprunter à qqn：向某人借。"}},
 "Un incinérateur": {"pos":"n.m. 阳性名词，复数 incinérateurs","s":"焚化炉；垃圾焚烧厂。用于烧垃圾或医疗废物。动词 incinérer = 焚烧；une incinération = 焚化。","ipa":"[ɛ̃.si.ne.ʁa.tœʁ]","ph":"in 读鼻化 [ɛ̃]；c 在 i 前读 [s]；é 读 [e]；r 读 [ʁ]；-eur 读 [œʁ]。","pi":"in 读 [ɛ̃]；c 读 [s]，不是 [k]；结尾 -eur 读 [œʁ]，r 要发音。","et":"来自拉丁语 incinerare（化为灰烬），源于 cinis（灰）。同族：incinérer、cendre。","ex":[["Les déchets finissent dans l'incinérateur.","垃圾最终进了焚化炉。"],["Cet incinérateur produit de l'électricité.","这座焚烧厂会发电。"],["On a construit un incinérateur près de la ville.","城市附近建了一座焚化炉。"]],"co":[["un incinérateur de déchets","垃圾焚化炉"],["brûler à l'incinérateur","在焚化炉里烧"],["l'incinération des déchets","垃圾焚烧"],["une usine d'incinération","垃圾焚烧厂"]],"sy":[["four crématoire","soutenu","火葬炉（特定用途）"],["décharge","courant","垃圾场"],["recyclage","courant","回收，相反的处理方式"]],"fq":"低频，环保话题里出现。","me":"incin-érateur：里面有 cinis（灰），烧成灰的机器。","tr":{"zh":"这座城市有一座垃圾焚化厂。","fr":"Cette ville a un incinérateur de déchets.","alt":"Il y a un incinérateur de déchets dans cette ville.","note":"阳性名词，用 un。"}},
 "Un kit": {"pos":"n.m. 阳性名词，复数 kits","s":"套装；工具包；组合装。un kit de réparation = 维修工具包；un kit de premiers secours = 急救包；un kit mains libres = 免提装置。","ipa":"[kit]","ph":"k 读 [k]；i 读 [i]；t 读 [t]，结尾 t 要发音。","pi":"结尾 t 要发音：[kit]，和很多不发音的 -t 结尾词不同（如 achat）。i 读 [i]，不要读成英语的 [ɪ] 那种松音。","et":"来自英语 kit（成套工具），法语借词。","ex":[["J'ai acheté un kit de réparation.","我买了一套维修工具。"],["Il y a un kit de premiers secours dans la voiture.","车里有一个急救包。"],["Ce kit contient tout le nécessaire.","这个套装包含所有必需品。"]],"co":[["un kit de réparation","维修工具包"],["un kit de premiers secours","急救包"],["un kit mains libres","免提套件"],["monter un meuble en kit","组装拆装式家具"]],"sy":[["trousse","courant","小包，工具包"],["ensemble","courant","一套，一组"],["coffret","courant","盒装套装"]],"fq":"中频，购物与技术话题常见。","me":"kit：英语直接借来的，一个小「包」装好所有东西。","tr":{"zh":"我需要一个急救包。","fr":"J'ai besoin d'un kit de premiers secours.","alt":"Il me faut une trousse de secours.","note":"avoir besoin de + 名词，de + un 不缩合。"}},
 "Un objet": {"pos":"n.m. 阳性名词，复数 objets","s":"物品；东西；对象；目的。un objet utile = 有用的东西；un objet perdu = 失物；l'objet de la réunion = 会议的主题。","ipa":"[ɔb.ʒɛ]","ph":"o 读 [ɔ]；b 读 [b]；j 读 [ʒ]；et 读 [ɛ]；结尾 t 不发音。","pi":"结尾 t 不发音；bj 连读 [bʒ]。别和英语 object 的发音搞混。","et":"来自拉丁语 objectum（放在前面的东西），源于 objicere。同族：objectif、objection。","ex":[["C'est un objet très utile.","这是个很有用的东西。"],["Il a perdu un objet important.","他丢了一件重要的东西。"],["L'objet de ce courriel est clair.","这封邮件的主题很清楚。"]],"co":[["un objet connecté","智能设备"],["un objet perdu","失物"],["les objets d'art","艺术品"],["l'objet d'un mail","邮件主题"]],"sy":[["chose","courant","东西，更泛"],["truc","familier","玩意儿，口语"],["article","courant","商品，物品"]],"fq":"极高频。","me":"objet：英语 object 去掉 c，t 不发音。","tr":{"zh":"桌子上有一件奇怪的东西。","fr":"Il y a un objet bizarre sur la table.","alt":"Il y a un truc bizarre sur la table.","note":"objet 阳性，形容词 bizarre 阴阳同形。"}},
 "Un pneu": {"pos":"n.m. 阳性名词，复数 pneus","s":"轮胎。un pneu crevé = 爆胎；un pneu de vélo = 自行车胎；changer un pneu = 换胎。是 pneumatique 的缩写。","ipa":"[pnø]","ph":"p 和 n 连读 [pn]；eu 读 [ø]，只有一个音节。","pi":"开头 pn- 要两个音一起读 [pn]；eu 读 [ø]，不是 [u]。复数 pneus 的 s 不发音。","et":"pneu 是 pneumatique 的缩写，来自希腊语 pneuma（空气、气息）。","ex":[["Mon vélo a un pneu crevé.","我的自行车轮胎扎破了。"],["Il change un pneu de la voiture.","他在给汽车换轮胎。"],["Les pneus sont trop usés.","轮胎磨损太厉害了。"]],"co":[["un pneu crevé","爆胎"],["changer un pneu","换轮胎"],["gonfler un pneu","给轮胎打气"],["un pneu neige","雪地胎"]],"sy":[["roue","courant","车轮（不只是橡胶）"],["chambre à air","courant","内胎"],["jante","courant","轮毂"]],"fq":"中频，汽车话题常见。","me":"pneu：pneumatique 的缩写，里面充满空气（pneuma）。","tr":{"zh":"我的汽车需要换轮胎。","fr":"Ma voiture a besoin de nouveaux pneus.","alt":"Je dois changer les pneus de ma voiture.","note":"avoir besoin de + 复数名词。"}},
 "Un tutoriel": {"pos":"n.m. 阳性名词，复数 tutoriels","s":"教程；教学视频；使用指南。regarder un tutoriel = 看教程；un tutoriel vidéo = 视频教程。口语里常说 un tuto。","ipa":"[ty.tɔ.ʁjɛl]","ph":"tu 读 [ty]；to 读 [tɔ]；-riel 读 [ʁjɛl]。","pi":"tu 读 [ty]，不是 [tu]；-iel 读 [jɛl]。别和英语 tutorial 的发音混淆。","et":"来自英语 tutorial，法语化为 tutoriel。tutor 来自拉丁语 tutor（保护者，监护人）。","ex":[["Je regarde un tutoriel sur internet.","我在网上看教程。"],["Il y a un tutoriel pour monter l'étagère.","有一个组装书架的教程。"],["Elle a fait un tuto pour les débutants.","她为初学者做了一个教程。"]],"co":[["un tutoriel vidéo","视频教程"],["suivre un tutoriel","跟着教程做"],["un tuto","教程（口语缩写）"],["un tutoriel pas à pas","分步教程"]],"sy":[["tuto","familier","教程，口语缩写"],["guide","courant","指南"],["didacticiel","soutenu","教学软件，加拿大常用"]],"fq":"中频，网络学习里常见。","me":"tutoriel：像 tutor（导师）亲手教你。","tr":{"zh":"我在网上找了一个做蛋糕的教程。","fr":"J'ai trouvé un tutoriel pour faire un gâteau.","alt":"J'ai trouvé un tuto de gâteau sur internet.","note":"pour + 动词原形 表示目的。"}},
 "Un véhicule": {"pos":"n.m. 阳性名词，复数 véhicules","s":"车辆；交通工具。比 voiture 范围更大，包括汽车、卡车、摩托车。un véhicule électrique = 电动车；un véhicule de location = 租赁车。","ipa":"[ve.i.kyl]","ph":"vé 读 [ve]；h 不发音，所以 é 和 i 要分开读 [ve.i]；-cule 读 [kyl]，e 不发音。","pi":"h 不发音，但 é 与 i 要分成两个音节 [ve.i]，别读成 [vɛ.ikyl]；u 读 [y]。","et":"来自拉丁语 vehiculum，源于 vehere（运送）。同族：véhiculer（传播，运送）。","ex":[["J'ai acheté un nouveau véhicule.","我买了一辆新车。"],["Ce véhicule est très économique.","这辆车很省钱。"],["Les véhicules électriques sont de plus en plus nombreux.","电动车越来越多。"]],"co":[["un véhicule électrique","电动车"],["un véhicule d'occasion","二手车"],["un véhicule de service","公务车"],["un véhicule utilitaire","商用车"]],"sy":[["voiture","courant","汽车，更常说"],["engin","courant","机械设备"],["bagnole","familier","车，口语"]],"fq":"较高频，交通与新闻里常见。","me":"véhicule：vehere（运送）的东西，什么都能载。","tr":{"zh":"这辆车停在哪里？","fr":"Où est garé ce véhicule ?","alt":"Cette voiture est garée où ?","note":"être garé = 被停放，被动。"}},
 "L'électronique": {"pos":"n.f. 阴性名词（单数）；也是形容词 électronique","s":"电子产品；电子学。acheter de l'électronique = 买电子产品；un magasin d'électronique = 电子产品店。作形容词意为「电子的」：un livre électronique。","ipa":"[e.lɛk.tʁɔ.nik]","ph":"é 读 [e]；e 读 [ɛ]；c 读 [k]；tr 读 [tʁ]；o 读 [ɔ]；-ique 读 [ik]。","pi":"开头 l' 与 é 缩合；é-lec-tro-nique：-ique 读 [ik]，e 不发音。别漏掉第一个 é 的重音。","et":"来自 électron（电子）加 -ique；électron 来自希腊语 elektron（琥珀）。同族：électricité。","ex":[["J'achète de l'électronique en ligne.","我在网上买电子产品。"],["Il travaille dans l'électronique.","他在电子行业工作。"],["Cette boutique vend de l'électronique.","这家店卖电子产品。"]],"co":[["un magasin d'électronique","电子产品店"],["l'électronique grand public","消费类电子产品"],["un ingénieur en électronique","电子工程师"],["un livre électronique","电子书"]],"sy":[["high-tech","courant","高科技产品"],["informatique","courant","计算机，信息技术"],["numérique","courant","数字的"]],"fq":"较高频，购物和科技话题常见。","me":"électro-nique：从「琥珀」（elektron）摩擦起电开始。","tr":{"zh":"我想买一些电子产品。","fr":"Je voudrais acheter de l'électronique.","alt":"J'aimerais acheter des appareils électroniques.","note":"acheter de l'électronique：de 表示不定量。"}},
 "L'escrime": {"pos":"n.f. 阴性名词（单数）","s":"击剑运动。faire de l'escrime = 练击剑；un fleuret = 花剑；une épée = 重剑；un sabre = 佩剑。une salle d'escrime = 击剑馆。","ipa":"[ɛs.kʁim]","ph":"es 读 [ɛs]；c 读 [k]；r 读 [ʁ]；-ime 读 [im]，e 不发音。","pi":"sc 读 [sk]，不要读成 [ʃ] 或 [s]；结尾 e 不发音，i 读 [i]。记住 escrime 是阴性。","et":"来自古法语 escremie，可能借自意大利语 scherma（击剑），再往前的来源不确定。","ex":[["Il fait de l'escrime.","他练击剑。"],["Elle gagne une médaille en escrime.","她在击剑中赢得了奖牌。"],["L'escrime est un sport olympique.","击剑是奥运会项目。"]],"co":[["faire de l'escrime","练击剑"],["un cours d'escrime","击剑课"],["l'escrime à l'épée","重剑"],["un champion d'escrime","击剑冠军"]],"sy":[["épée","courant","重剑，指武器"],["fleuret","courant","花剑"],["duel","courant","决斗"]],"fq":"中低频，体育话题里出现。","me":"escrime 读 [ɛs.kʁim]，像 crime 前面加 es。","tr":{"zh":"我儿子每周练一次击剑。","fr":"Mon fils fait de l'escrime une fois par semaine.","alt":"Mon fils a un cours d'escrime chaque semaine.","note":"练某项运动：faire de + 定冠词（de l'escrime）。"}},
 "La consommation": {"pos":"n.f. 阴性名词，复数 consommations","s":"消费；消耗；饮料。la consommation d'eau = 用水量；la société de consommation = 消费社会；在咖啡馆，une consommation = 一份饮品。","ipa":"[kɔ̃.sɔ.ma.sjɔ̃]","ph":"con 读鼻化 [kɔ̃]；so 读 [sɔ]；mm 读一个 [m]；ma 读 [ma]；-tion 读 [sjɔ̃]。","pi":"mm 只读一个 [m]；-tion 读 [sjɔ̃]，别读成 [tion]。别和 consumer（消耗殆尽，较少用）弄混，常用动词是 consommer。","et":"来自拉丁语 consummatio（总计，完成），同族：consommer、consommateur。","ex":[["La consommation d'eau augmente.","用水量在增加。"],["Il faut réduire la consommation d'énergie.","必须减少能源消耗。"],["Je prends une consommation au café.","我在咖啡馆点了一份饮料。"]],"co":[["la consommation d'énergie","能源消耗"],["la société de consommation","消费社会"],["les biens de consommation","消费品"],["réduire sa consommation","减少消耗"]],"sy":[["dépense","courant","开支"],["usage","courant","使用"],["production","courant","反义：生产"]],"fq":"高频，经济和环保话题常见。","me":"consommation 来自 consommer：东西被「吃完、用光」。","tr":{"zh":"我们应该减少塑料的使用。","fr":"On doit réduire la consommation de plastique.","alt":"Il faut consommer moins de plastique.","note":"la consommation de + 名词。"}},
 "La décoration": {"pos":"n.f. 阴性名词，复数 décorations","s":"装饰；装潢；布置。la décoration de la maison = 家里的装饰；la décoration de Noël = 圣诞装饰；也可指勋章（une décoration militaire）。","ipa":"[de.kɔ.ʁa.sjɔ̃]","ph":"dé 读 [de]；co 读 [kɔ]；ra 读 [ʁa]；-tion 读 [sjɔ̃]。","pi":"第一个 é 重音不要漏；-tion 读 [sjɔ̃]，别读成 [tion]；décoration 阴性。","et":"来自拉丁语 decoratio，源于 decorare（装饰）。同族：décorer、décor、décorateur。","ex":[["J'aime la décoration de ta maison.","我喜欢你家的装饰。"],["Nous faisons la décoration de Noël.","我们在布置圣诞装饰。"],["Elle travaille dans la décoration.","她从事室内装饰工作。"]],"co":[["la décoration d'intérieur","室内装潢"],["la décoration de Noël","圣诞装饰"],["une décoration murale","墙面装饰"],["un objet de décoration","装饰品"]],"sy":[["décor","courant","布景，装饰环境"],["ornement","soutenu","装饰物，较正式"],["aménagement","courant","布置，规划"]],"fq":"较高频，居家话题常见。","me":"décoration = décor + ation：把房间弄得「有 décor」。","tr":{"zh":"我想换一下客厅的装饰。","fr":"Je veux changer la décoration du salon.","alt":"J'ai envie de refaire le salon.","note":"changer + 直接宾语。"}},
 "La mécanique": {"pos":"n.f. 阴性名词，复数 mécaniques","s":"机械；机械学；机械装置。aimer la mécanique = 喜欢机械；la mécanique d'une montre = 手表的机芯；也指汽车修理方面的事。","ipa":"[me.ka.nik]","ph":"mé 读 [me]；c 读 [k]；a 读 [a]；-nique 读 [nik]。","pi":"拼写里的 c 读 [k]，-que 读 [k]，e 不发音；注意 mé 的重音 é。别和 mécanicien（机械师）混淆，那是人。","et":"来自拉丁语 mechanica，源于希腊语 mekhanē（机器、装置）。同族：mécanicien、mécanisme。","ex":[["Il aime la mécanique.","他喜欢机械。"],["Elle fait de la mécanique dans un garage.","她在汽车修理厂做机修。"],["La mécanique de cette montre est très précise.","这块表的机芯非常精确。"]],"co":[["la mécanique automobile","汽车机械"],["un problème de mécanique","机械故障"],["la mécanique quantique","量子力学"],["la mécanique de précision","精密机械"]],"sy":[["mécanisme","courant","机构，机制"],["moteur","courant","发动机"],["technique","courant","技术"]],"fq":"中频，汽车和技术话题常见。","me":"mécanique：和 machine 同一个希腊词根（mekhanē）。","tr":{"zh":"我对汽车机械很感兴趣。","fr":"Je m'intéresse à la mécanique automobile.","alt":"Je suis passionné de mécanique auto.","note":"s'intéresser à + 名词。"}},
 "La mode": {"pos":"n.f. 阴性名词，复数 modes；注意 le mode（方式、模式）是阳性","s":"时尚；流行；风气。être à la mode = 流行；la mode féminine = 女装潮流；une semaine de la mode = 时装周。le mode（阳性）= 方式，如 le mode d'emploi。","ipa":"[mɔd]","ph":"m 读 [m]；o 读 [ɔ]；d 读 [d]；结尾 e 不发音。","pi":"la mode（阴性，时尚）和 le mode（阳性，方式）读音相同、性别不同；o 读 [ɔ]，不是 [o]。","et":"来自拉丁语 modus（方式，尺度），后来演变出「风尚」义。同族：moderne、modèle、à la mode。","ex":[["Elle aime beaucoup la mode.","她很喜欢时尚。"],["Ce manteau est à la mode.","这件大衣很流行。"],["La mode change tous les ans.","时尚每年都在变。"]],"co":[["être à la mode","流行"],["passer de mode","过时"],["la mode féminine / masculine","女装 / 男装潮流"],["un magazine de mode","时尚杂志"]],"sy":[["tendance","courant","趋势"],["style","courant","风格"],["vogue","littéraire","流行，风行（en vogue）"]],"fq":"高频，日常生活常用。","me":"mode = modus（方式）：大家都用同一种「方式」穿衣。","tr":{"zh":"这个夏天，这种颜色很流行。","fr":"Cet été, cette couleur est à la mode.","alt":"Cet été, c'est la couleur du moment.","note":"être à la mode：à + la，不缩合。"}},
 "La philosophie": {"pos":"n.f. 阴性名词，复数 philosophies","s":"哲学；人生观。étudier la philosophie = 学哲学；une philosophie de vie = 人生哲学；在法国高中，la philo 是毕业班必修课，常缩成 la philo。","ipa":"[fi.lɔ.zɔ.fi]","ph":"ph 读 [f]；i 读 [i]；o 读 [ɔ]；s 在元音间读 [z]；最后一个 -phie 读 [fi]。","pi":"ph 读 [f]，不是 [p]；s 读 [z]，不是 [s]。-phie 结尾的名词多为阴性。","et":"来自希腊语 philosophia：philos（爱）+ sophia（智慧），字面是「爱智慧」。","ex":[["J'étudie la philosophie.","我学哲学。"],["Elle a un cours de philo le lundi.","她周一有哲学课。"],["C'est ma philosophie de vie.","这就是我的人生哲学。"]],"co":[["étudier la philosophie","学哲学"],["un cours de philo","哲学课"],["une philosophie de vie","人生观"],["prendre les choses avec philosophie","以平常心面对"]],"sy":[["philo","familier","哲学（缩写）"],["sagesse","courant","智慧"],["pensée","courant","思想"]],"fq":"中频，学校和思想话题里常见。","me":"philo（爱）+ sophie（智慧）：爱智慧的人 = 哲学家。","tr":{"zh":"我喜欢上哲学课。","fr":"J'aime les cours de philosophie.","alt":"J'adore mon cours de philo.","note":"philo 是口语缩写。"}},
 "Une catégorie": {"pos":"n.f. 阴性名词，复数 catégories","s":"类别；类型；等级。une nouvelle catégorie = 新类别；dans quelle catégorie ? = 属于哪一类？ 体育里指组别（catégorie d'âge）。","ipa":"[ka.te.ɡɔ.ʁi]","ph":"ca 读 [ka]；té 读 [te]；g 读 [ɡ]；o 读 [ɔ]；-rie 读 [ʁi]。","pi":"g 在 o 前读 [ɡ]；三个重音位置：ca-té-go-rie，é 不能漏。类似英语 category，但词尾是 -ie，不是 -y。","et":"来自希腊语 kategoria（断言，范畴），经拉丁语 categoria。同族：catégorique、catégoriser。","ex":[["Il y a une nouvelle catégorie.","有一个新类别。"],["Dans quelle catégorie est-ce que tu joues ?","你在哪个组别比赛？"],["Ces produits sont de la même catégorie.","这些产品属于同一类。"]],"co":[["une catégorie d'âge","年龄组"],["dans la même catégorie","同一类别"],["une catégorie socioprofessionnelle","职业类别"],["classer par catégories","按类别分类"]],"sy":[["type","courant","类型"],["genre","courant","种类"],["classe","courant","等级，班级"]],"fq":"较高频，分类场景常见。","me":"catégorie 像 category，但结尾 -ie 变法语：同一个希腊词。","tr":{"zh":"你的商品属于哪个类别？","fr":"Votre produit est de quelle catégorie ?","alt":"Votre produit, c'est quelle catégorie ?","note":"être de + 名词：属于某类。"}},
 "Une caution": {"pos":"n.f. 阴性名词，复数 cautions","s":"押金；保证金；担保人。payer une caution = 付押金；se porter caution = 做担保；la caution d'un appartement = 房屋押金。","ipa":"[ko.sjɔ̃]","ph":"au 读 [o]；-tion 读 [sjɔ̃]。","pi":"au 读 [o]，不是 [au]；-tion 读 [sjɔ̃]。别和 garantie（质保）混淆：caution 是押金或担保人。","et":"来自拉丁语 cautio（小心，保证），源于 cavere（当心）。同族：précaution、cautionner。","ex":[["Il faut payer une caution.","要付押金。"],["Mon père s'est porté caution pour moi.","我父亲给我做了担保。"],["La caution sera rendue à la fin du bail.","押金会在租约结束时退还。"]],"co":[["verser une caution","付押金"],["rendre la caution","退还押金"],["se porter caution","做担保人"],["une caution de loyer","房租押金"]],"sy":[["dépôt de garantie","soutenu","保证金（正式）"],["garant","courant","担保人"],["arrhes","courant","定金"]],"fq":"中频，租房和贷款里常见。","me":"caution 来自 cautio（小心）：押金让你不敢乱来。","tr":{"zh":"租房时要先付一笔押金。","fr":"Pour louer un appartement, il faut payer une caution.","alt":"Pour louer, on demande une caution.","note":"pour + 动词原形：为了做某事。"}},
 "Une décharge": {"pos":"n.f. 阴性名词，复数 décharges","s":"垃圾场；放电；免责。une décharge publique = 公共垃圾场；une décharge électrique = 电击；signer une décharge = 签免责声明。","ipa":"[de.ʃaʁʒ]","ph":"dé 读 [de]；ch 读 [ʃ]；a 读 [a]；rge 读 [ʁʒ]，e 不发音。","pi":"ch 读 [ʃ]；r 要发音 [ʁ]，接着 [ʒ]；别和 déchet（垃圾，一件）混淆：décharge 是堆放垃圾的地方。","et":"来自动词 décharger（卸下），由 dé- + charger（装载）构成。charger 来自晚期拉丁语 carricare。","ex":[["C'est une grande décharge.","这是一个大垃圾场。"],["Il a reçu une décharge électrique.","他被电击了一下。"],["Les déchets sont jetés dans une décharge.","垃圾被倒进垃圾场。"]],"co":[["une décharge publique","公共垃圾场"],["une décharge sauvage","非法倾倒点"],["une décharge électrique","电击"],["signer une décharge","签免责声明"]],"sy":[["dépotoir","courant","垃圾堆，也指脏乱的地方"],["déchetterie","courant","垃圾回收站，有分类"],["poubelle","courant","垃圾桶，较小"]],"fq":"中频，环保话题里常见。","me":"décharge = 卸（dé-）下货物（charge）：垃圾卸在这里。","tr":{"zh":"那边有一个非法垃圾场。","fr":"Il y a une décharge sauvage là-bas.","alt":"Là-bas, quelqu'un a fait une décharge sauvage.","note":"décharge sauvage = 非法倾倒点。"}},
 "Une déchetterie": {"pos":"n.f. 阴性名词，复数 déchetteries（也拼作 déchèterie）","s":"废品回收站；垃圾分类站。市民把大件垃圾、旧家具、电器、纸张送去分类处理。官方拼法 déchèterie 也很常见。","ipa":"[de.ʃɛ.tʁi]","ph":"dé 读 [de]；ch 读 [ʃ]；e 读 [ɛ]；t 读 [t]；r 读 [ʁ]；-rie 读 [ʁi]。","pi":"ch 读 [ʃ]；拼写有 déchetterie（tt）和 déchèterie（è）两种，读音相近。别和 décharge 混淆。","et":"由 déchet（垃圾）+ -erie（地点后缀）构成。déchet 来自古法语 déchoir（掉落，失落）。","ex":[["Je vais à la déchetterie.","我去废品回收站。"],["On apporte les vieux meubles à la déchetterie.","我们把旧家具送到回收站。"],["La déchetterie ferme à 18 h.","回收站 18 点关门。"]],"co":[["aller à la déchetterie","去废品回收站"],["déposer à la déchetterie","送去回收站"],["une déchetterie municipale","市政回收站"],["les horaires de la déchetterie","回收站开放时间"]],"sy":[["décharge","courant","垃圾场，无分类"],["point de collecte","courant","回收点"],["recyclerie","courant","旧物回收再售店"]],"fq":"中频，生活和环保话题常见。","me":"déchet + -erie：就像 boulangerie 是做面包的地方。","tr":{"zh":"周末我要把旧电视送去回收站。","fr":"Ce week-end, je porte ma vieille télé à la déchetterie.","alt":"Ce week-end, je vais jeter ma vieille télé à la déchetterie.","note":"porter qqch à + 地点。"}},
 "Une dizaine": {"pos":"n.f. 阴性名词，复数 dizaines","s":"十来个；大约十个。une dizaine de + 名词 = 大约十个……。也可指「一个十位数」或「十个一组」。动词一致：une dizaine de personnes sont venues。","ipa":"[di.zɛn]","ph":"di 读 [di]；z 读 [z]；-aine 读 [ɛn]。","pi":"z 读 [z]；-aine 读 [ɛn]，e 不发音。别漏掉 de：une dizaine de + 名词（不是 une dizaine + 名词）。","et":"由 dix（十）加后缀 -aine 构成。dix 来自拉丁语 decem。同族：une douzaine、une vingtaine。","ex":[["Il y a une dizaine de personnes.","大约有十个人。"],["J'ai invité une dizaine d'amis.","我邀请了十来个朋友。"],["Elle a une dizaine d'années.","她大约十岁。"]],"co":[["une dizaine de personnes","十来个人"],["une dizaine de jours","十来天"],["une dizaine d'euros","十来欧元"],["une quinzaine","十五个左右"]],"sy":[["environ dix","courant","大约十个"],["une douzaine","courant","十二个左右，一打"],["dix","courant","准确的十"]],"fq":"较高频，日常估数时常用。","me":"dizaine = dix + -aine：一堆「十」的东西，大概就是十来个。","tr":{"zh":"我们大约来了十个人。","fr":"Nous sommes une dizaine.","alt":"On est à peu près dix.","note":"une dizaine de + 复数名词；de 后无冠词。"}},
 "Une échelle": {"pos":"n.f. 阴性名词，复数 échelles","s":"梯子。也可指「等级、规模」：une échelle de salaires（工资等级）、à grande échelle（大规模地）。","ipa":"[e.ʃɛl]","ph":"é [e]；ch [ʃ]；e 在 l 前读 [ɛ]；结尾 l 要发音。","pi":"ch 读 [ʃ]（像「西」），不是 [k]；结尾 l 要读出来；是阴性：une échelle。","et":"拉丁语 scala（梯子）。同源：escalier（楼梯）、escalade（攀爬）。","ex":[["J'utilise une échelle pour monter.","我用梯子爬上去。"],["Ne reste pas sous l'échelle !","别站在梯子下面！"]],"co":[["monter sur une échelle","爬上梯子"],["une échelle double","人字梯"],["à grande échelle","大规模地"]],"sy":[["escabeau","courant","小折梯（带踏板，能自己站稳）"]],"fq":"中频，日常常用。","me":"échelle 和 escalier 都来自 scala：都是「往上爬」的东西。","tr":{"zh":"把梯子拿给我，我要换灯泡。","fr":"Donne-moi l'échelle, je dois changer l'ampoule.","alt":"Passe-moi l'échelle, je change l'ampoule.","note":"changer une ampoule = 换灯泡；échelle 是阴性。"}},
 "Une marque": {"pos":"n.f. 阴性名词，复数 marques","s":"品牌；牌子。也指「记号、痕迹」：une marque sur le mur（墙上的印子）。动词 marquer = 做记号；进球。","ipa":"[maʁk]","ph":"ar [aʁ]（r 是喉音）；qu 读 [k]；结尾 e 不发音。","pi":"qu 读 [k]，不是 [kw]；结尾 e 不发音；是阴性：une marque。","et":"来自日耳曼语（古北欧语 merki，记号），经意大利语进入法语。同族：marquer（做记号）、démarquer。","ex":[["C'est ma marque préférée.","这是我最喜欢的品牌。"],["Quelle marque de lait tu achètes ?","你买哪个牌子的牛奶？"]],"co":[["une grande marque","大牌"],["une marque de vêtements","服装品牌"],["à vos marques !","各就各位！（赛跑口令）"]],"sy":[["label","courant","标签、品质标志"],["enseigne","courant","店铺招牌、连锁店名"]],"fq":"高频，日常常用。","me":"marque 里有 mark：一个「记号」，就是牌子。","tr":{"zh":"你更喜欢哪个品牌？","fr":"Tu préfères quelle marque ?","alt":"Quelle marque tu préfères ?","note":"quelle + 阴性名词；口语里常把疑问词放后面。"}},
 "Une mercerie": {"pos":"n.f. 阴性名词，复数 merceries","s":"针线杂货店，卖线、纽扣、布料、缝纫和编织用品。le mercier / la mercière = 开这种店的人。","ipa":"[mɛʁ.sə.ʁi]","ph":"er [ɛʁ]；c 在 e 前读 [s]；中间的 e 常弱读甚至省略：[mɛʁ.sri]。","pi":"c 读 [s]，不是 [k]；不要和 merci（谢谢）混淆。","et":"来自 mercier（卖杂货的人），源自拉丁语 merx（商品）。同源：marchand、marché、commerce。","ex":[["J'achète du fil à la mercerie.","我在杂货店买线。"],["Cette mercerie vend de la laine et des boutons.","这家杂货店卖毛线和纽扣。"]],"co":[["aller à la mercerie","去针线店"],["un article de mercerie","缝纫用品"],["acheter des boutons en mercerie","在杂货店买纽扣"]],"sy":[["boutique de couture","courant","缝纫用品店（说明性的说法）"]],"fq":"低频，缝纫、编织时才用。","me":"mercerie 和 marché 同根 merx：买卖「商品」。","tr":{"zh":"我要去针线店买线和纽扣。","fr":"Je vais à la mercerie acheter du fil et des boutons.","alt":"Je passe à la mercerie pour du fil et des boutons.","note":"acheter du fil：du = de + le，表示不定量。"}},
 "Une pièce": {"pos":"n.f. 阴性名词，复数 pièces","s":"房间（une pièce 指任何一个房间）；硬币；零件；一件（à la pièce = 按件）；剧本（une pièce de théâtre）。意思很多，要看语境。","ipa":"[pjɛs]","ph":"p-i-è 连读成 [pjɛ]；è [ɛ]；c 在 e 前读 [s]；结尾 e 不发音。","pi":"è 是开口的 [ɛ]；注意 pièce 里的 c 读 [s]。","et":"来自中世纪拉丁语 pettia（一块、一片），可能源自高卢语。同族：pièce détachée（零件）。","ex":[["La maison a trois pièces.","这栋房子有三间房。"],["Tu as une pièce de un euro ?","你有一欧元硬币吗？"],["On va voir une pièce de théâtre.","我们去看一出戏剧。"]],"co":[["un deux-pièces","两居室"],["une pièce de monnaie","硬币"],["une pièce de rechange","备用零件"],["une pièce de théâtre","戏剧"]],"sy":[["chambre","courant","卧室，不是任意房间"],["salle","courant","大厅、专用的房间（salle de bains）"]],"fq":"极高频，日常常用。","me":"pièce = 一「片」：一间房、一个硬币、一个零件。","tr":{"zh":"我们的公寓有四个房间。","fr":"Notre appartement a quatre pièces.","alt":"On a un appartement de quatre pièces.","note":"pièce 指房间时包括客厅和卧室。"}},
 "Une scie": {"pos":"n.f. 阴性名词，复数 scies","s":"锯子。动词 scier = 锯。une scie électrique = 电锯。口语里 c'est une scie 也指「老调重弹的歌」。","ipa":"[si]","ph":"sc 在 i 前读 [s]；ie 读 [i]；整词只有一个音。","pi":"只有一个音节 [si]，和 si（如果）、ci 同音；sc 不要读成 [sk]。","et":"来自动词 scier，源自拉丁语 secare（切、割）。同族：section、secteur、insecte。","ex":[["Je coupe le bois avec une scie.","我用锯子锯木头。"],["Mon père a une scie électrique.","我爸爸有一把电锯。"]],"co":[["une scie à bois","木工锯"],["une scie électrique","电锯"],["scier une planche","锯一块木板"]],"sy":[["scie sauteuse","courant","线锯、曲线锯"]],"fq":"低频，说工具时用。","me":"scie 读 [si]，和 si 一样；锯 = secare 「切」。","tr":{"zh":"你有锯子吗？我要锯这块木板。","fr":"Tu as une scie ? Je dois couper cette planche.","alt":"T'as une scie ? Je dois scier cette planche.","note":"t'as 是 tu as 的口语缩读。"}},
 "Une tendance": {"pos":"n.f. 阴性名词，复数 tendances","s":"趋势；倾向；潮流。la tendance du moment = 当下的流行。avoir tendance à + 动词原形 = 总是爱……。","ipa":"[tɑ̃.dɑ̃s]","ph":"en [ɑ̃]，an [ɑ̃]，两个鼻化元音；c 在 e 前读 [s]；结尾 e 不发音。","pi":"en 和 an 都读鼻化 [ɑ̃]，不要读出 n；不要读成英语的 [ˈtɛndənsi]。","et":"来自动词 tendre（伸向），源自拉丁语 tendere。同族：tendu、attention、intention。","ex":[["C'est la nouvelle tendance.","这是新趋势。"],["J'ai tendance à oublier mes clés.","我老是忘带钥匙。"]],"co":[["avoir tendance à + inf.","有……的倾向"],["la tendance actuelle","目前的趋势"],["être à la mode / dans la tendance","走在潮流中"]],"sy":[["mode","courant","时尚、流行"],["évolution","courant","变化、发展"]],"fq":"高频，日常和新闻都常用。","me":"tendance ← tendre：朝某个方向「伸过去」。","tr":{"zh":"最近大家都有喝茶的趋势。","fr":"Ces temps-ci, la tendance, c'est de boire du thé.","alt":"En ce moment, tout le monde se met au thé.","note":"c'est de + 动词原形 用来说明趋势是什么。"}},
 "Une tondeuse": {"pos":"n.f. 阴性名词，复数 tondeuses","s":"割草机（une tondeuse à gazon）；也指理发推子（une tondeuse à cheveux）。动词 tondre = 修剪草坪、剪毛。","ipa":"[tɔ̃.døz]","ph":"on [ɔ̃] 鼻化；eu [ø]；s 在两个元音之间读 [z]。","pi":"s 读 [z]，不是 [s]；on 不发 n；eu 是圆唇的 [ø]。","et":"来自动词 tondre，源自拉丁语 tondere（剪毛）。同族：tonsure（剃发）。","ex":[["Je passe la tondeuse dans le jardin.","我用割草机修剪花园。"],["Il coupe les cheveux avec une tondeuse.","他用推子剪头发。"]],"co":[["passer la tondeuse","推割草机"],["une tondeuse à gazon","割草机"],["une tondeuse électrique","电动割草机"]],"sy":[["rasoir","courant","剃须刀"]],"fq":"低频，花园话题中用。","me":"tondeuse 里有 tond-：tondre 「剪」，加 -euse 变成「剪的机器」。","tr":{"zh":"星期六早上他用割草机修剪草坪。","fr":"Le samedi matin, il passe la tondeuse sur la pelouse.","alt":"Samedi matin, il tond la pelouse.","note":"passer la tondeuse = 推割草机；tondre la pelouse = 剪草坪。"}},
 "Des déchets": {"pos":"n.m.pl. 阳性复数名词，单数 un déchet","s":"垃圾；废物；废料。une poubelle 是垃圾桶，les déchets 是里面的东西。常说 trier les déchets（垃圾分类）。","ipa":"[de.ʃɛ]","ph":"dé [de]；ch [ʃ]；e 读开口 [ɛ]；结尾 t 和 s 都不发音。","pi":"结尾 -ets 全不发音，整词读 [deʃɛ]；是阳性：un déchet，不是 une déchet。","et":"来自动词 déchoir（掉落、衰落）的旧词形，指「掉落下来的东西」。","ex":[["Il y a trop de déchets.","垃圾太多了。"],["On trie les déchets à la maison.","我们在家给垃圾分类。"]],"co":[["trier les déchets","垃圾分类"],["réduire ses déchets","减少垃圾"],["des déchets plastiques","塑料垃圾"],["un déchet","一件废物"]],"sy":[["ordures","courant","生活垃圾（常用复数）"],["poubelle","courant","垃圾桶，不是垃圾本身"]],"fq":"高频，环保话题里很常用。","me":"déchet ← déchoir：从东西上「掉下来」的废料。","tr":{"zh":"我们应该少扔垃圾。","fr":"Nous devons produire moins de déchets.","alt":"Il faut faire moins de déchets.","note":"moins de + 名词，名词前不加冠词。"}},
 "Des économies": {"pos":"n.f.pl. 阴性复数名词，单数 une économie","s":"积蓄；节省下来的钱。faire des économies = 存钱、省钱。注意：单数 l'économie 指「经济」或「节约」。","ipa":"[e.kɔ.nɔ.mi]","ph":"é [e]；o 读 [ɔ]；结尾 -ies 都不发音，只读 [mi]。","pi":"重音在最后一个音节 -mi；复数 s 不发音，所以 des économies 和 des économie 听不出区别；用 des 连读，s 读 [z]：[dez‿e.kɔ.nɔ.mi]。","et":"来自希腊语 oikonomia（管理家务），经拉丁语进入法语。同族：économe（节俭的）、économiser。","ex":[["Je fais des économies pour les vacances.","我为假期攒钱。"],["Elle a des économies à la banque.","她在银行有存款。"]],"co":[["faire des économies","攒钱、省钱"],["économies d'énergie","节能"],["mettre de l'argent de côté","把钱存起来"]],"sy":[["épargne","soutenu","储蓄（较正式）"],["pécule","soutenu","一小笔积蓄"]],"fq":"高频，日常常用。","me":"économie 的希腊词根是「管家」：管好家里的钱，就是省钱。","tr":{"zh":"他每个月都存一点钱。","fr":"Chaque mois, il fait des économies.","alt":"Tous les mois, il met un peu d'argent de côté.","note":"faire des économies 用复数表示存钱。"}},
 "Un acheteur / Une acheteuse": {"pos":"n. 名词，阳性 acheteur，阴性 acheteuse","s":"买家；购买者。阳性 un acheteur，阴性 une acheteuse。与 un client（顾客，常去某家店的人）不同，acheteur 强调「买东西的人」。","ipa":"[aʃ.tœʁ] / [aʃ.tøz]","ph":"ach [aʃ]，e 不发音；阳性结尾 -eur [œʁ]；阴性 -euse [øz]，s 读 [z]。","pi":"ch 读 [ʃ]；中间 e 不发音，读 [aʃ.tœʁ]；阳性 -eur 和阴性 -euse 的元音不同。","et":"来自动词 acheter（买），加后缀 -eur / -euse 表示做这个动作的人。acheter 来自拉丁语 accaptare（取得）。","ex":[["L'acheteur visite la maison.","买家来看房。"],["Elle est une bonne acheteuse.","她很会买东西。"]],"co":[["un acheteur potentiel","潜在买家"],["un acheteur en ligne","网购买家"],["trouver un acheteur","找到买主"]],"sy":[["client / cliente","courant","顾客"],["consommateur","courant","消费者"],["vendeur","courant","反义词：卖家"]],"fq":"中频，买卖房子、车时常用。","me":"acheter + -eur：「做买这个动作的人」，反义 vendeur。","tr":{"zh":"卖家在等买家的回答。","fr":"Le vendeur attend la réponse de l'acheteur.","alt":"Le vendeur attend que l'acheteur réponde.","note":"attendre que + 虚拟式；这里用名词更简单。"}},
 "Un(e) bénévole": {"pos":"n. 名词，阴阳同形，复数 bénévoles","s":"志愿者；义工。阴阳同形：un bénévole / une bénévole。也可作形容词，如 un travail bénévole（义务工作）。","ipa":"[be.ne.vɔl]","ph":"每个 é 都是 [e]，中间 é 也是；o 读开口 [ɔ]；结尾 e 不发音，l 要读出来。","pi":"三个音节都不要弱化；结尾 l 要发音；重音在最后一个音节。","et":"来自拉丁语 benevolus（有善意的），由 bene（好）+ velle（愿意）构成。同族：bienveillant。","ex":[["Elle est bénévole dans une association.","她在一个协会做志愿者。"],["Les bénévoles distribuent des repas.","志愿者们在发放餐食。"]],"co":[["travailler comme bénévole","做志愿者"],["une association de bénévoles","志愿者协会"],["faire du bénévolat","做志愿服务"]],"sy":[["volontaire","courant","自愿的人；也指志愿兵"],["salarié","courant","反义词：领工资的员工"]],"fq":"中频，社会话题里常用。","me":"bene（好）+ vol（愿意）：怀着好意，自愿做事。","tr":{"zh":"我周末在医院做志愿者。","fr":"Le week-end, je suis bénévole à l'hôpital.","alt":"Je fais du bénévolat à l'hôpital le week-end.","note":"说职业或身份时不用冠词：je suis bénévole。"}},
 "Un(e) client(e)": {"pos":"n. 名词，阳性 client，阴性 cliente，复数 clients / clientes","s":"顾客；客户。阳性 un client，阴性 une cliente。在商店、餐厅、银行、酒店都用。","ipa":"[kli.jɑ̃]","ph":"cl [kl]；ie 读 [j]；ent 读鼻化 [ɑ̃]，t 不发音；阴性 cliente [kli.jɑ̃t]，t 要读出。","pi":"阳性结尾 -ent 读 [ɑ̃]，t 不发；阴性 cliente 的 t 要发音；不是英语的 client [ˈklaɪənt]。","et":"来自拉丁语 cliens（依附者、受保护的人）。同族：clientèle（顾客群）。","ex":[["Le client est content.","顾客很满意。"],["La cliente demande le prix.","女顾客在问价格。"]],"co":[["un client fidèle","老顾客"],["le service client","客服"],["un nouveau client","新客户"],["le client est roi","顾客就是上帝"]],"sy":[["consommateur","courant","消费者（泛指）"],["usager","courant","公共服务的使用者"]],"fq":"极高频，日常常用。","me":"client 的 -ent 读 [ɑ̃]，所以是「克里扬」，不是英语的 client。","tr":{"zh":"这家面包店有很多老顾客。","fr":"Cette boulangerie a beaucoup de clients fidèles.","alt":"Dans cette boulangerie, il y a plein de clients fidèles.","note":"beaucoup de + 名词；plein de 是口语。"}},
 "Consommer": {"pos":"v. 及物动词，第一组（-er），助动词 avoir","s":"消费；吃喝；使用（电、油）。consommer de l'eau = 用水。une voiture qui consomme beaucoup = 很费油的车。","ipa":"[kɔ̃.sɔ.me]","ph":"con 读鼻化 [kɔ̃]；第二个 o 读 [ɔ]；mm 只读一个 [m]；结尾 -er 读 [e]。","pi":"mm 不要读两遍；con 里不发 n；词尾 -er 读 [e]，r 不发音。","et":"来自拉丁语 consummare（完成、总计）；同族：consommation（消费）、consommateur（消费者）。","ex":[["Il faut consommer des fruits.","要多吃水果。"],["Cette voiture consomme trop d'essence.","这辆车太费油。"]],"co":[["consommer de l'énergie","耗能"],["à consommer avant le...","最好在……之前食用"],["consommer local","消费本地产品"]],"sy":[["manger","courant","吃，指具体动作"],["utiliser","courant","使用"]],"fq":"高频，日常和新闻常用。","me":"con + sommer：把东西「合计、用完」，就是消耗。","tr":{"zh":"我们应该少用一点电。","fr":"Nous devrions consommer moins d'électricité.","alt":"On devrait consommer moins d'électricité.","note":"devrions 是条件式，表示委婉的建议。"}},
 "Créer": {"pos":"v. 及物动词，第一组（-er），助动词 avoir","s":"创造；创建；设计。créer une entreprise = 创办公司；créer un compte = 创建账号；créer des bijoux = 设计首饰。","ipa":"[kʁe.e]","ph":"cr [kʁ]；第一个 é [e]；后面 er 也读 [e]；两个元音相连：[kʁe.e]。","pi":"两个 [e] 要读两下，不要合成一个；r 是喉音；变位 je crée / il crée 的 e 结尾不发音。","et":"来自拉丁语 creare（创造）。同族：créateur、création、créatif、récréation。","ex":[["Elle aime créer des bijoux.","她喜欢设计首饰。"],["Il veut créer son entreprise.","他想创办自己的公司。"]],"co":[["créer une entreprise","创办公司"],["créer un compte","创建账号"],["créer des emplois","创造就业"]],"sy":[["inventer","courant","发明（原来没有的东西）"],["fabriquer","courant","制造"],["détruire","courant","反义词：毁掉"]],"fq":"高频，日常常用。","me":"créer 是 [kʁe.e]：两个 e 相连，像在「创」两次。","tr":{"zh":"他想创办一家小公司。","fr":"Il veut créer une petite entreprise.","alt":"Il a envie de monter sa petite boîte.","note":"vouloir + 动词原形；monter sa boîte 是口语。"}},
 "Économiser": {"pos":"v. 及物动词，第一组（-er），助动词 avoir","s":"节省；存钱。économiser de l'argent = 存钱；économiser l'eau = 节约用水。économiser pour + 名词 / 动词原形 = 为……攒钱。","ipa":"[e.kɔ.nɔ.mi.ze]","ph":"é [e]；o 读 [ɔ]；mi [mi]；s 在两个元音之间读 [z]；结尾 -er [e]。","pi":"s 读 [z]，不是 [s]；五个音节，重音在最后一个。","et":"来自 économie（经济；节约），再加动词后缀 -iser。économie 来自希腊语 oikonomia（管理家务）。","ex":[["Je veux économiser de l'argent.","我想存钱。"],["On économise de l'énergie avec ces lampes.","用这些灯可以节约能源。"]],"co":[["économiser de l'argent","存钱"],["économiser l'eau","节约用水"],["économiser pour un voyage","为旅行攒钱"]],"sy":[["épargner","soutenu","储蓄（较正式）"],["gaspiller","courant","反义词：浪费"],["dépenser","courant","反义词：花钱"]],"fq":"高频，日常常用。","me":"économie → économiser：把「经济」变成动作，就是省。","tr":{"zh":"我想存钱买一辆自行车。","fr":"Je veux économiser pour acheter un vélo.","alt":"Je mets de l'argent de côté pour m'acheter un vélo.","note":"pour + 动词原形 表示目的。"}},
 "Emprunter": {"pos":"v. 及物动词，第一组（-er），助动词 avoir","s":"借入（向别人借东西）：emprunter un livre à la bibliothèque = 从图书馆借书。借出去是 prêter。也指走某条路：emprunter cette rue。","ipa":"[ɑ̃.pʁœ̃.te]","ph":"em 读鼻化 [ɑ̃]；un 读鼻化 [œ̃]；r 是喉音；结尾 -er 读 [e]。","pi":"em 和 un 两个鼻化元音不要读出 m 和 n；别和 prêter（借出）搞混：emprunter = 借来，prêter = 借出。","et":"来自古法语 empruntier，源自拉丁语 in + promutuari（借）。词根 prunt- 同族：un emprunt（借款）。","ex":[["Je peux emprunter ton stylo ?","我可以借你的笔吗？"],["Il emprunte de l'argent à la banque.","他向银行借钱。"]],"co":[["emprunter à quelqu'un","向某人借"],["emprunter un livre","借书"],["emprunter un chemin","走某条路"],["un emprunt","借款"]],"sy":[["prêter","courant","反义词：借出"],["louer","courant","租"]],"fq":"高频，日常常用。","me":"em-prunter：借「进来」；prêter 是借「出去」。","tr":{"zh":"我可以向你借一支笔吗？","fr":"Je peux t'emprunter un stylo ?","alt":"Tu peux me prêter un stylo ?","note":"emprunter à 某人；prêter à 某人 方向相反。"}},
 "Jeter": {"pos":"v. 及物动词，第一组（-er），变位 je jette，助动词 avoir","s":"扔；丢掉。jeter à la poubelle = 扔进垃圾桶。也可以是「投、抛」：jeter une pierre。注意变位：je jette，nous jetons。","ipa":"[ʒə.te]","ph":"j [ʒ]；第一个 e 很轻 [ə]；结尾 -er 读 [e]；变位 il jette 读 [ʒɛt]。","pi":"变位要双写 t：je jette, tu jettes, ils jettent；nous jetons 和 vous jetez 不双写；j 是 [ʒ]，不是 [dʒ]。","et":"来自拉丁语 jactare（扔）。同族：projet、objet、sujet（都来自 jacere）。","ex":[["Il ne faut pas jeter le pain.","不要扔面包。"],["Je jette les papiers à la poubelle.","我把纸扔进垃圾桶。"]],"co":[["jeter à la poubelle","扔进垃圾桶"],["jeter un coup d'œil","瞥一眼"],["se jeter à l'eau","下定决心去做"],["ne pas jeter de papier par terre","不要乱扔纸"]],"sy":[["lancer","courant","投、掷（有目标）"],["balancer","familier","随手扔掉"]],"fq":"高频，日常常用。","me":"jeter 变位时 t 要双写：je jette，好像「叠」了两下。","tr":{"zh":"请把垃圾扔进垃圾桶。","fr":"Jette les déchets dans la poubelle, s'il te plaît.","alt":"Tu peux jeter ça à la poubelle ?","note":"祈使句 jette 去掉 s（第一组动词）。"}},
 "Mettre ... en valeur": {"pos":"v. 动词短语，mettre 为不规则动词，助动词 avoir","s":"突出；使显眼；衬托。mettre quelque chose en valeur = 让某物更好看、更被重视。还可用于人：mettre ses qualités en valeur。","ipa":"[mɛtʁ ɑ̃ va.lœʁ]","ph":"mettre [mɛtʁ]，tt 读一个 [t]；en 读鼻化 [ɑ̃]；valeur [va.lœʁ]。","pi":"中间的 ... 表示放入宾语：mettre ce tableau en valeur；en 不发 n 的音，读 [ɑ̃]；变位按 mettre：je mets, nous mettons。","et":"mettre 来自拉丁语 mittere；valeur 来自 valoir（值），源自拉丁语 valere（强壮、有价值）。","ex":[["Cette lumière met le tableau en valeur.","这盏灯让画更突出。"],["Il faut mettre tes qualités en valeur.","你得把自己的优点展示出来。"]],"co":[["mettre en valeur un produit","突出一件产品"],["mettre ses talents en valeur","展现才华"],["être mis en valeur","被突出"]],"sy":[["souligner","courant","强调、突出"],["valoriser","courant","提升价值"]],"fq":"中频，日常和商务都常用。","me":"mettre + en + valeur：把东西放到「有价值」的位置上。","tr":{"zh":"这条项链很好地衬托了她的裙子。","fr":"Ce collier met bien sa robe en valeur.","alt":"Ce collier met sa robe en valeur.","note":"宾语放在 mettre 和 en valeur 之间。"}},
 "Mettre en ligne": {"pos":"v. 动词短语，mettre 为不规则动词，助动词 avoir","s":"上传；发布到网上（视频、文章、照片）。mettre une vidéo en ligne = 把视频发到网上。上传文件的技术说法是 téléverser。","ipa":"[mɛtʁ ɑ̃ liɲ]","ph":"mettre [mɛtʁ]；en [ɑ̃]；gn 读 [ɲ]（像「尼」）；结尾 e 不发音。","pi":"ligne 里的 gn 读 [ɲ]，不是 [gn]；en ligne 的 en 读 [ɑ̃]；变位按 mettre：j'ai mis。","et":"mettre 来自拉丁语 mittere；ligne 来自拉丁语 linea（线）。en ligne 在法语里指「在网络上」。","ex":[["Je vais mettre la vidéo en ligne.","我要把视频上传。"],["Le professeur a mis les notes en ligne.","老师把成绩发到网上了。"]],"co":[["mettre en ligne un site","让网站上线"],["être en ligne","在线"],["acheter en ligne","网上购物"]],"sy":[["publier","courant","发布"],["téléverser","soutenu","上传文件（技术说法）"],["poster","courant","发帖"]],"fq":"中频，网络话题常用。","me":"ligne = 网线：把东西放到「线上」。","tr":{"zh":"我今晚把照片发到网上。","fr":"Ce soir, je mets mes photos en ligne.","alt":"Ce soir, je poste mes photos.","note":"mettre en ligne 是固定表达，宾语放在 mettre 后面。"}},
 "Modifier": {"pos":"v. 及物动词，第一组（-er），助动词 avoir","s":"修改；更改。modifier un mot de passe = 改密码。je modifie / nous modifions；注意不要写成 modifer。","ipa":"[mɔ.di.fje]","ph":"o 读 [ɔ]；di [di]；fi 与后面的 -er 连成 [fje]；结尾 -er 读 [e]。","pi":"il modifie 读 [mɔ.di.fi]，nous modifions 读 [mɔ.di.fjɔ̃]；nous modifions 有两个 i，写时别漏掉。","et":"来自拉丁语 modificare（调整），由 modus（方式、尺度）构成。同族：mode、moderne、modèle。","ex":[["Je dois modifier mon mot de passe.","我得改密码。"],["Elle modifie son rendez-vous.","她更改了预约时间。"]],"co":[["modifier un mot de passe","改密码"],["modifier un horaire","改时间表"],["sauf modification","如无更改"]],"sy":[["changer","courant","改变（更口语）"],["corriger","courant","改正（错误）"]],"fq":"高频，日常和网络常用。","me":"modifier ← mode：换一种「方式」。","tr":{"zh":"我想改一下我的预约。","fr":"Je voudrais modifier mon rendez-vous.","alt":"J'aimerais changer mon rendez-vous.","note":"je voudrais + 动词原形，比 je veux 更礼貌。"}},
 "Recycler": {"pos":"v. 及物动词，第一组（-er），助动词 avoir","s":"回收利用；循环使用。recycler le plastique = 回收塑料。也可用于人：se recycler = 进修、转行。","ipa":"[ʁə.si.kle]","ph":"re [ʁə]（轻读）；c 在 i 前读 [s]；cl [kl]；结尾 -er 读 [e]。","pi":"第一个 e 很轻 [ʁə]；c 读 [s]，后一个 c 读 [k]；不要读成英语的 recycle [ˌriːˈsaɪkl]。","et":"由前缀 re-（再）加 cycle（循环），cycle 来自希腊语 kyklos（圆圈）。同族：cycle、cyclone、bicyclette。","ex":[["Nous devons recycler le plastique.","我们要回收塑料。"],["Ces bouteilles sont recyclées.","这些瓶子是回收的。"]],"co":[["recycler du papier","回收纸张"],["le papier recyclé","再生纸"],["se recycler","进修、转行学习"]],"sy":[["réutiliser","courant","再次使用（不经过加工）"],["trier","courant","分类"]],"fq":"高频，环保话题里很常用。","me":"re + cycle：再转一圈。","tr":{"zh":"你要把旧报纸拿去回收。","fr":"Tu dois recycler les vieux journaux.","alt":"Il faut recycler les vieux journaux.","note":"devoir + 动词原形 表示应该做。"}},
 "Rendre un service": {"pos":"v. 动词短语，rendre 为第三组动词，助动词 avoir","s":"帮忙；帮一个忙。rendre service à quelqu'un 或 rendre un service à quelqu'un。Tu peux me rendre un service ? = 你能帮我个忙吗？","ipa":"[ʁɑ̃dʁ œ̃ sɛʁ.vis]","ph":"rendre [ʁɑ̃dʁ]，en 读 [ɑ̃]；un 连读 [œ̃]；service 读 [sɛʁ.vis]，结尾 -ce 读 [s]。","pi":"rendre 里的 en 读 [ɑ̃]，e 在结尾不发音；service 的 c 是 [s]，结尾 e 不发音；给谁帮忙用 à：rendre service à Paul。","et":"rendre 来自拉丁语 reddere（还、给）；service 来自拉丁语 servitium（服务）。同族：servir、serveur。","ex":[["Tu peux me rendre un service ?","你能帮我个忙吗？"],["Merci, tu m'as rendu service.","谢谢，你帮了我大忙。"]],"co":[["rendre service à quelqu'un","帮助某人"],["rendre un petit service","帮个小忙"],["demander un service","请求帮忙"]],"sy":[["aider","courant","帮助，更常用"],["dépanner","familier","帮人救急"]],"fq":"高频，日常常用。","me":"rendre = 把一个「忙」还给别人。","tr":{"zh":"你能帮我个忙，照看一下我的猫吗？","fr":"Tu peux me rendre un service et garder mon chat ?","alt":"Tu peux me rendre service ? Garde mon chat.","note":"rendre un service à 某人，me 放在 rendre 前面。"}},
 "Réparer": {"pos":"v. 及物动词，第一组（-er），助动词 avoir","s":"修理；修复。réparer un vélo = 修自行车。也可表示补救：réparer une erreur（弥补错误）。","ipa":"[ʁe.pa.ʁe]","ph":"ré [ʁe]；pa [pa]；ra [ʁa] 在词尾 -er 前读 [ʁe]；整词 [ʁe.pa.ʁe]。","pi":"两个 r 都是喉音；不要读成英语的 repair；结尾 -er 读 [e]，r 不发音。","et":"来自拉丁语 reparare（重新准备），由 re-（再）+ parare（准备）构成。同族：préparer、réparation。","ex":[["Je vais réparer mon vélo.","我要修自行车。"],["Il répare des ordinateurs.","他修电脑。"]],"co":[["réparer une voiture","修车"],["faire réparer son téléphone","把手机送去修"],["réparer une erreur","弥补错误"]],"sy":[["arranger","courant","修好、整理"],["dépanner","courant","应急修理"],["casser","courant","反义词：弄坏"]],"fq":"高频，日常常用。","me":"ré + parer：重新「准备好」，就是修好了。","tr":{"zh":"你能修好我的手机吗？","fr":"Tu peux réparer mon téléphone ?","alt":"Tu peux me réparer mon téléphone ?","note":"faire réparer = 送去让人修，不是自己修。"}},
 "Repasser (un vêtement)": {"pos":"v. 及物动词，第一组（-er），助动词 avoir；指「再来」时助动词用 être","s":"熨烫（衣服）：repasser une chemise。口语里常说 faire le repassage。注意：repasser 还有「再经过、再来」的意思，如 je repasse demain（我明天再来）。","ipa":"[ʁə.pa.se]","ph":"re [ʁə]；pa [pa]；ss 读 [s]；结尾 -er 读 [e]。","pi":"ss 读清音 [s]，不是 [z]；第一个 re 很轻；注意熨衣和「再来」两个意思，靠语境区分。","et":"由前缀 re-（再）+ passer（经过）构成，原意是「再次从上面经过」。","ex":[["Je dois repasser ma chemise.","我得熨衬衫。"],["Elle repasse ses vêtements le dimanche.","她星期天熨衣服。"]],"co":[["repasser une chemise","熨衬衫"],["un fer à repasser","熨斗"],["faire le repassage","熨衣服（家务）"],["je repasse demain","我明天再来"]],"sy":[["défroisser","courant","把皱褶弄平"]],"fq":"中频，日常常用。","me":"re + passer：熨斗在衣服上「再过一遍」。","tr":{"zh":"我明天早上要熨这条裤子。","fr":"Demain matin, je dois repasser ce pantalon.","alt":"Demain matin, il faut que je repasse ce pantalon.","note":"括号里 un vêtement 只是提示宾语是衣服。"}},
 "Réutiliser": {"pos":"v. 及物动词，第一组（-er），助动词 avoir","s":"重复利用；再次使用。réutiliser un sac = 再用同一个袋子。常和 recycler 一起出现：réutiliser 不经过加工，recycler 要经过加工。","ipa":"[ʁe.y.ti.li.ze]","ph":"ré [ʁe]；u 读 [y]；ti [ti]；li [li]；s 在两个元音之间读 [z]；结尾 -er [e]。","pi":"ré 和 u 之间要断开读 [ʁe.y]；u 读 [y]（嘴圆），不是 [u]；s 读 [z]。","et":"由 ré-（再）+ utiliser（使用）构成；utiliser 来自 utile，源自拉丁语 utilis（有用的）。","ex":[["Tu peux réutiliser ce sac.","你可以重复使用这个袋子。"],["On réutilise les bouteilles en verre.","我们重复使用玻璃瓶。"]],"co":[["réutiliser un objet","再次使用物品"],["réutiliser l'eau","再利用水"],["un sac réutilisable","可重复使用的袋子"]],"sy":[["recycler","courant","回收再造"],["jeter","courant","反义词：扔掉"]],"fq":"中频，环保话题常用。","me":"ré + utiliser：「再」用一次。","tr":{"zh":"我们可以再次使用这些瓶子。","fr":"On peut réutiliser ces bouteilles.","alt":"On peut s'en resservir.","note":"on peut + 动词原形；s'en resservir 是口语说法。"}},
 "Rivaliser": {"pos":"v. 不及物动词，第一组（-er），助动词 avoir","s":"较量；竞争；媲美。常说 rivaliser avec quelqu'un（和某人竞争）、rivaliser de + 名词（在……方面争胜）。","ipa":"[ʁi.va.li.ze]","ph":"ri [ʁi]；va [va]；li [li]；s 在两个元音之间读 [z]；结尾 -er 读 [e]。","pi":"s 读 [z]；用于人时多接 avec：rivaliser avec lui；此词偏书面，日常多说 être en concurrence。","et":"来自 rival（对手），源自拉丁语 rivalis，原指「共用同一条河的人」，由 rivus（河）而来。","ex":[["Les deux équipes vont rivaliser.","两支队伍将展开较量。"],["Ce café rivalise avec les meilleurs.","这家咖啡馆可以和最好的比。"]],"co":[["rivaliser avec quelqu'un","和某人竞争"],["rivaliser de talent","在才华上互相较劲"],["un rival","对手"]],"sy":[["concurrencer","courant","与……竞争（商业）"],["se mesurer à","soutenu","与……较量"]],"fq":"低频，偏书面。","me":"rival 一词来自「共用一条河」的人，难免要争。","tr":{"zh":"这两家餐厅相互竞争。","fr":"Ces deux restaurants rivalisent.","alt":"Ces deux restaurants sont en concurrence.","note":"rivaliser 后面接 avec，不接直接宾语。"}},
 "Se détendre": {"pos":"v. 代词式动词，第三组（-dre），复合时态用 être","s":"放松；休息。se détendre après le travail = 下班后放松。变位：je me détends, il se détend；复合过去时：je me suis détendu(e)。","ipa":"[sə de.tɑ̃dʁ]","ph":"se [sə]；dé [de]；en 读鼻化 [ɑ̃]；结尾 -dre 读 [dʁ]。","pi":"tend 里的 en 读 [ɑ̃]，d 在 je me détends 中不发音；复合时态助动词是 être，要和主语性数配合。","et":"由前缀 dé-（解除）+ tendre（拉紧）构成，原意是「松开」。同族：tension（紧张）、détente（放松）。","ex":[["J'aime me détendre le week-end.","我喜欢周末放松。"],["Il se détend en écoutant de la musique.","他听音乐来放松。"]],"co":[["se détendre un peu","放松一下"],["un moment de détente","放松的时刻"],["Détends-toi !","放松点！"]],"sy":[["se reposer","courant","休息（身体）"],["se relaxer","courant","放松（更口语）"],["se stresser","courant","反义：紧张"]],"fq":"高频，日常常用。","me":"dé-tendre：把绷紧的弦「松开」。","tr":{"zh":"下班后我听音乐放松一下。","fr":"Après le travail, je me détends en écoutant de la musique.","alt":"Après le boulot, je me détends avec de la musique.","note":"en + 现在分词 表示同时做的方式。"}},
 "Tricoter": {"pos":"v. 及物或不及物动词，第一组（-er），助动词 avoir","s":"编织；织毛衣。tricoter un pull = 织一件毛衣。名词：le tricot（针织品；编织活）。","ipa":"[tʁi.kɔ.te]","ph":"tr [tʁ]；i [i]；c 在 o 前读 [k]；o 读 [ɔ]；结尾 -er 读 [e]。","pi":"tr 的 r 是喉音；c 读 [k]；动词 tricoter 与 tricot（[tʁi.ko]，t 不发）读音有区别。","et":"来源不确定；词族：tricot（针织品）、tricoteuse（织毛衣的女人）。","ex":[["Ma grand-mère aime tricoter.","我外婆喜欢织毛衣。"],["Elle tricote un pull pour son fils.","她给儿子织一件毛衣。"]],"co":[["tricoter un pull","织毛衣"],["une aiguille à tricoter","毛衣针"],["de la laine à tricoter","编织用毛线"]],"sy":[["coudre","courant","缝纫（不是编织）"],["broder","courant","刺绣"]],"fq":"中频，兴趣爱好话题常用。","me":"tricot 是织好的东西，tricoter 就是「做 tricot」。","tr":{"zh":"冬天我外婆给我织围巾。","fr":"En hiver, ma grand-mère me tricote une écharpe.","alt":"L'hiver, ma grand-mère me fait une écharpe en laine.","note":"me 是间接宾语：织给我。"}},
 "Voler": {"pos":"v. 第一组（-er），助动词 avoir；及物（偷）或不及物（飞）","s":"有两个意思：1）飞：un oiseau vole；2）偷：voler un portefeuille。靠语境区分：voler 后面有宾语多半是「偷」，没宾语多半是「飞」。","ipa":"[vɔ.le]","ph":"v [v]；o 读 [ɔ]；l [l]；结尾 -er 读 [e]。","pi":"「飞」和「偷」同形同音，要靠宾语判断；偷的人是 un voleur，被偷用 se faire voler。","et":"来自拉丁语 volare（飞）。「偷」的意思来自猎鹰「飞去抓猎物」，从中引申而来。同族：volant（方向盘；飞行的）、volaille（家禽）。","ex":[["L'oiseau vole dans le ciel.","鸟在天上飞。"],["On m'a volé mon vélo.","有人偷了我的自行车。"]],"co":[["voler dans le ciel","在天上飞"],["voler quelque chose à quelqu'un","偷某人的某物"],["se faire voler","被偷"],["un voleur","小偷"]],"sy":[["dérober","soutenu","窃取"],["piquer","familier","顺手牵羊；偷"],["cambrioler","courant","入室盗窃"]],"fq":"极高频，日常常用。","me":"voler 想象一只鸟：飞过去，叼走东西。","tr":{"zh":"昨天有人偷了我的手机。","fr":"Hier, on m'a volé mon téléphone.","alt":"Hier, quelqu'un m'a piqué mon téléphone.","note":"on m'a volé + 物：被偷用 on 开头的句子。"}},
 "Abîmé(e)": {"pos":"adj. 形容词，阴性 abîmée，复数 abîmés / abîmées","s":"损坏的；弄坏的；磨损的。可说物件、衣服、书，也可说人的身体状态（比较口语）。abîmer = 弄坏。","ipa":"[a.bi.me]","ph":"a [a]；î 读 [i]；m [m]；é [e]；阴性 abîmée 读音相同。","pi":"î 上的帽子（accent circonflexe）不改变读音，仍读 [i]；注意阴性 abîmée 多一个 e，但读音不变。","et":"来自 abîme（深渊），表示「掉进深渊」，后来引申为「被毁坏」。abîme 来自晚期拉丁语 abyssimus。","ex":[["Ce livre est un peu abîmé.","这本书有点旧损。"],["Mes chaussures sont abîmées.","我的鞋子磨坏了。"]],"co":[["un livre abîmé","破损的书"],["un fruit abîmé","有点烂的水果"],["abîmer un objet","弄坏东西"]],"sy":[["cassé","courant","断了、坏了"],["endommagé","soutenu","受损的（较正式）"],["usé","courant","磨旧的"]],"fq":"中频，日常常用。","me":"abîmé = 掉进 abîme（深渊）的东西：已经坏了。","tr":{"zh":"这条裤子有点磨坏了，我要扔掉。","fr":"Ce pantalon est abîmé, je vais le jeter.","alt":"Ce pantalon est tout abîmé, je le jette.","note":"形容词和名词配合：un pantalon abîmé。"}},
 "Annuel(le)": {"pos":"adj. 形容词，阴性 annuelle，复数 annuels / annuelles","s":"每年的；一年一次的。un événement annuel = 年度活动；un contrat annuel = 年度合同。名词是 un an / une année，副词是 annuellement。","ipa":"[a.nɥɛl]","ph":"a [a]；nu 读 [nɥ]（u 变成半元音）；el 读 [ɛl]；阴性 annuelle 读音相同，结尾 e 不发音。","pi":"nn 只读一个 [n]；u 在 [ɛ] 前变成半元音 [ɥ]；阳性和阴性读音一样，只在拼写上区别（-el / -elle）。","et":"来自拉丁语 annuus（每年的），由 annus（年）构成。同族：an、année、anniversaire。","ex":[["C'est un événement annuel.","这是年度活动。"],["La réunion annuelle a lieu en mai.","年会在五月举行。"]],"co":[["un rapport annuel","年度报告"],["un abonnement annuel","年卡"],["une fête annuelle","一年一度的节日"]],"sy":[["mensuel","courant","每月的"],["hebdomadaire","courant","每周的"],["quotidien","courant","每天的"]],"fq":"中频，日常和商务都用。","me":"annuel ← annus：和 an（年）、anniversaire（周年）同家。","tr":{"zh":"我们每年有一次家庭聚会。","fr":"Nous avons une réunion de famille annuelle.","alt":"Chaque année, on se retrouve en famille.","note":"annuelle 要和阴性名词 réunion 配合。"}},
 "Compulsif / Compulsive": {"pos":"adj. 形容词，阳性 compulsif，阴性 compulsive，复数 compulsifs / compulsives","s":"强迫性的；控制不住的。un achat compulsif = 冲动消费；un comportement compulsif = 强迫行为。多用于描述不受控的习惯。","ipa":"[kɔ̃.pyl.sif] / [kɔ̃.pyl.siv]","ph":"com 读鼻化 [kɔ̃]；u 读 [y]；阳性结尾 -if 读 [if]；阴性 -ive 读 [iv]。","pi":"com 里的 m 不发音，只表示鼻化；阳性 f，阴性 v，读音不同；u 读 [y]，不是 [u]。","et":"来自拉丁语 compellere（强迫）的过去分词 compulsus；同族：compulsion（强迫）、impulsif（冲动的）。","ex":[["C'est un achat compulsif.","这是冲动消费。"],["Elle a un besoin compulsif de ranger.","她有强迫性的整理欲。"]],"co":[["un achat compulsif","冲动消费"],["un acheteur compulsif","购物成瘾的人"],["un comportement compulsif","强迫行为"]],"sy":[["impulsif","courant","冲动的（性格）"],["irrépressible","soutenu","无法抑制的"]],"fq":"低频，多用于心理或消费话题。","me":"compulsif ← compulsion：一种推着你走的力量。","tr":{"zh":"他有强迫性的购物习惯。","fr":"Il a une habitude d'achat compulsive.","alt":"Il fait des achats compulsifs.","note":"habitude 是阴性，所以用 compulsive。"}},
 "Convivial(e)": {"pos":"adj. 形容词，阴性 conviviale，阳性复数 conviviaux","s":"热闹友好的；气氛融洽的。un repas convivial = 大家一起吃、气氛轻松的饭。也用于软件：convivial = 好用易上手（user-friendly）。","ipa":"[kɔ̃.vi.vjal]","ph":"con 读鼻化 [kɔ̃]；vi [vi]；vial 读 [vjal]；阴性 conviviale 读音相同。","pi":"阳性复数是 conviviaux，不是 convivials；con 的 n 不发音；和英语 convivial（欢乐的）相近，但法语更常说「气氛温暖」。","et":"来自拉丁语 convivium（宴会），由 con-（一起）+ vivere（生活）构成。同族：convive（宾客）。","ex":[["Ce restaurant est très convivial.","这家餐厅气氛很友好。"],["On a passé un moment convivial.","我们度过了融洽的时光。"]],"co":[["un moment convivial","融洽的时刻"],["un lieu convivial","让人轻松的地方"],["une ambiance conviviale","友好的气氛"]],"sy":[["chaleureux","courant","热情的、温暖的"],["sympa","familier","友好、不错"],["accueillant","courant","好客的"]],"fq":"中频，日常常用。","me":"con + vivre：大家「一起生活」、一起吃饭。","tr":{"zh":"我喜欢这家小酒吧的气氛，很温暖。","fr":"J'aime l'ambiance de ce petit bar, elle est très conviviale.","alt":"Ce petit bar a une ambiance vraiment conviviale.","note":"conviviale 与阴性名词 ambiance 配合。"}},
 "Créatif / Créative": {"pos":"adj. 形容词，阳性 créatif，阴性 créative，复数 créatifs / créatives","s":"有创造力的；有创意的。un enfant créatif = 有创造力的孩子。也可作名词：un créatif = 创意人员。","ipa":"[kʁe.a.tif] / [kʁe.a.tiv]","ph":"cr [kʁ]；é [e]；a [a]；阳性 -tif 读 [tif]；阴性 -tive 读 [tiv]。","pi":"é 和 a 要分开读 [e.a]；阳性 f 和阴性 v 读音不同；r 是喉音。","et":"来自 créer（创造），源自拉丁语 creare；加后缀 -if / -ive。","ex":[["Mon frère est très créatif.","我哥哥很有创意。"],["C'est une idée très créative.","这是个很有创意的想法。"]],"co":[["une personne créative","有创意的人"],["un esprit créatif","创造性思维"],["des loisirs créatifs","手工创意活动"]],"sy":[["inventif","courant","善于发明的"],["original","courant","独特的"],["imaginatif","courant","富有想象力的"]],"fq":"高频，日常常用。","me":"créer → créatif：「创」+ -tif：爱创造的。","tr":{"zh":"我的朋友们都很有创意。","fr":"Tous mes amis sont très créatifs.","alt":"Mes amis sont super créatifs.","note":"形容词要和主语配合，复数加 s。"}},
 "D'occasion": {"pos":"adj. 形容词短语，不变（阴阳、单复数相同）","s":"二手的。用于买来的旧物：une voiture d'occasion。形容词短语不变化：des vêtements d'occasion。名词 une occasion = 机会；便宜货。","ipa":"[dɔ.ka.zjɔ̃]","ph":"d' 连读 o；cc 读 [k]；as 在两个元音之间，s 读 [z]；ion 读 [jɔ̃]；结尾 n 不发音。","pi":"d'occasion 要读成一个整体 [dɔ.ka.zjɔ̃]；s 读 [z]；这个短语不随性别、数量变化。","et":"occasion 来自拉丁语 occasio（时机）。d'occasion 字面是「碰上机会的」。","ex":[["J'achète des vêtements d'occasion.","我买二手衣服。"],["Ils ont une voiture d'occasion.","他们有一辆二手车。"]],"co":[["une voiture d'occasion","二手车"],["acheter d'occasion","买二手"],["un marché d'occasion","二手市场"]],"sy":[["de seconde main","courant","二手（更书面）"],["neuf","courant","反义词：全新的"]],"fq":"高频，日常常用。","me":"d'occasion：碰到「机会」才买到的旧货。","tr":{"zh":"我喜欢买二手书。","fr":"J'aime acheter des livres d'occasion.","alt":"J'adore chiner des livres d'occasion.","note":"d'occasion 放在名词后，不变形。"}},
 "De seconde main": {"pos":"adj. 形容词短语，不变（阴阳、单复数相同）","s":"二手的；转手的。des vêtements de seconde main = 二手衣服。与 d'occasion 意思相近，更常用于衣服、书、环保话题。也可说「间接得来的」信息：une information de seconde main。","ipa":"[də s(ə).ɡɔ̃d mɛ̃]","ph":"de [də]；seconde 读 [s(ə).ɡɔ̃d]，c 读 [g]；on 读 [ɔ̃]；main 读 [mɛ̃]。","pi":"seconde 里的 c 读 [g]，不是 [k]；main 读 [mɛ̃]，ain 不发 n；短语不随性数变化。","et":"main（手）来自拉丁语 manus；seconde 来自拉丁语 secundus（第二）。字面意思是「第二只手」，即转手。","ex":[["J'achète des livres de seconde main.","我买二手书。"],["Cette boutique vend des vêtements de seconde main.","这家店卖二手衣服。"]],"co":[["des vêtements de seconde main","二手衣服"],["acheter de seconde main","买二手"],["une boutique de seconde main","二手店"]],"sy":[["d'occasion","courant","二手的"],["friperie","courant","旧衣店"]],"fq":"中频，二手和环保话题常用。","me":"seconde main：字面是「第二只手」，东西到了第二个主人手里。","tr":{"zh":"她的衣服大多是二手的。","fr":"La plupart de ses vêtements sont de seconde main.","alt":"Presque tous ses vêtements sont d'occasion.","note":"la plupart de + 复数名词，动词用复数。"}},
 "Dépensier / Dépensière": {"pos":"adj. 形容词，阳性 dépensier，阴性 dépensière，复数 dépensiers / dépensières","s":"花钱大手大脚的；爱花钱的。il est dépensier = 他花钱没节制。可作名词：un dépensier / une dépensière（挥霍的人）。","ipa":"[de.pɑ̃.sje] / [de.pɑ̃.sjɛʁ]","ph":"dé [de]；pen 读鼻化 [pɑ̃]；s 在 i 前读 [s]；阳性 -ier [je]；阴性 -ière [jɛʁ]。","pi":"阳性 -ier 读 [je]，阴性 -ière 读 [jɛʁ]；en 读 [ɑ̃]，n 不发音；不要拼成 dépensié。","et":"来自动词 dépenser（花钱），源自拉丁语 dispensare（分发）；加后缀 -ier。同族：dépense（支出）。","ex":[["Elle est très dépensière.","她很爱花钱。"],["Mon frère n'est pas dépensier.","我哥哥花钱不大手大脚。"]],"co":[["être dépensier","花钱大手大脚"],["une personne dépensière","爱花钱的人"],["faire de grosses dépenses","大笔开销"]],"sy":[["gaspilleur","courant","浪费的人"],["économe","courant","反义词：节俭的"],["radin","familier","反义词：小气的"]],"fq":"中频，日常常用。","me":"dépenser + -ier：天生「爱花」的人。","tr":{"zh":"我姐姐太爱花钱了。","fr":"Ma sœur est trop dépensière.","alt":"Ma sœur dépense trop, elle est vraiment dépensière.","note":"dépensière 与 sœur（阴性）配合。"}},
 "Dynamique": {"pos":"adj. 形容词，阴阳同形，复数 dynamiques；也是名词 la dynamique","s":"有活力的；积极向上的。une équipe dynamique = 充满活力的团队。名词 la dynamique = 动力；推动力。","ipa":"[di.na.mik]","ph":"dy [di]；na [na]；mi [mi]；结尾 -que 读 [k]，e 不发音。","pi":"y 读 [i]，不是 [aɪ]；重音在最后一个音节；阴阳性不变，只加 s 变复数。","et":"来自希腊语 dynamikos（有力量的），源自 dynamis（力量）。同族：dynamite、dynastie。","ex":[["C'est une équipe dynamique.","这是一支有活力的团队。"],["Ma grand-mère est très dynamique.","我外婆精力非常旺盛。"]],"co":[["une personne dynamique","有活力的人"],["une équipe dynamique","有活力的团队"],["un jeune cadre dynamique","年轻有为的干部"]],"sy":[["énergique","courant","精力充沛的"],["actif","courant","积极的、活跃的"],["mou","courant","反义词：软弱无力的"]],"fq":"中频，日常常用。","me":"dynamique 和 dynamite 同源：像炸药一样有力。","tr":{"zh":"我们的新老师非常有活力。","fr":"Notre nouvelle professeure est très dynamique.","alt":"Notre nouvelle prof est super dynamique.","note":"dynamique 阴阳同形，不加 e。"}},
 "Écologique": {"pos":"adj. 形容词，阴阳同形，复数 écologiques","s":"环保的；生态的。un produit écologique = 环保产品。也可说 écolo（口语，环保的、环保人士）。","ipa":"[e.kɔ.lɔ.ʒik]","ph":"é [e]；两个 o 都读 [ɔ]；g 在 i 前读 [ʒ]；结尾 -que 读 [k]。","pi":"g 读 [ʒ]，不是 [g]；结尾 que 读 [k]；注意 écologique 与 économique 的结尾相同但中间不同，别混淆。","et":"来自希腊语 oikos（家）+ logos（学问），原意是「研究家园」，指生态学。同族：économie（oikos + nomos）。","ex":[["C'est un produit écologique.","这是环保产品。"],["Le vélo est un moyen de transport écologique.","自行车是环保的交通方式。"]],"co":[["un produit écologique","环保产品"],["un geste écologique","环保的举动"],["la crise écologique","生态危机"]],"sy":[["écolo","familier","环保（口语）"],["vert","courant","绿色的、环保的"],["durable","courant","可持续的"]],"fq":"高频，环保话题常用。","me":"éco + logique：研究「家」的学问，所以是生态。","tr":{"zh":"骑自行车比开车更环保。","fr":"Le vélo est plus écologique que la voiture.","alt":"Le vélo, c'est plus écolo que la voiture.","note":"plus ... que 表示比较。"}},
 "Fait maison": {"pos":"adj. 形容词短语；fait 是 faire 的过去分词，maison 不变","s":"自制的；家庭自制的。un gâteau fait maison = 自己做的蛋糕。餐厅菜单上 fait maison 表示「本店自制」。","ipa":"[fɛ mɛ.zɔ̃]","ph":"fait 读 [fɛ]，t 不发音；maison 读 [mɛ.zɔ̃]，ai 读 [ɛ]，s 读 [z]，on 读鼻化 [ɔ̃]。","pi":"fait 里的 t 不发音；maison 的 s 读 [z]，不是 [s]；阴性仍写 fait maison（有时写 faite maison，但较少）。","et":"fait 来自拉丁语 factum（做成的）；maison 来自拉丁语 mansio（住所）。","ex":[["Ce gâteau est fait maison.","这个蛋糕是自制的。"],["Je préfère la cuisine faite maison.","我更喜欢家里做的菜。"]],"co":[["un plat fait maison","自家做的菜"],["du pain fait maison","自制面包"],["fait maison par le chef","由主厨自制"]],"sy":[["artisanal","courant","手工的"],["industriel","courant","反义词：工业生产的"]],"fq":"高频，吃饭话题常用。","me":"fait + maison：「在家做出来的」。","tr":{"zh":"我们的蛋糕和面包都是自制的。","fr":"Nos gâteaux et notre pain sont faits maison.","alt":"Tout est fait maison ici.","note":"与复数主语配合：sont faits maison。"}},
 "Neuf / Neuve": {"pos":"adj. 形容词，阳性 neuf，阴性 neuve，复数 neufs / neuves","s":"全新的；没用过的。une voiture neuve = 新车。注意：neuf 也是数字「九」；quoi de neuf ? = 有什么新鲜事？","ipa":"[nœf] / [nœv]","ph":"阳性 neuf：eu [œ]，f 要读 [f]；阴性 neuve：f 变 v，读 [nœv]。","pi":"neuf（新的）和 neuf（数字九）同形同音，靠语境区分；阳性 f，阴性 v；和 nouveau（新的，刚出现的）不同。","et":"来自拉丁语 novus（新的）。同族：nouveau、nouvelle、rénover、innovation。","ex":[["Les voitures neuves coûtent trop cher.","新车太贵了。"],["Il a un vélo neuf.","他有一辆新自行车。"]],"co":[["à neuf","翻新、重新"],["quoi de neuf ?","有什么新鲜事？"],["flambant neuf","崭新的"],["remettre à neuf","翻新"]],"sy":[["nouveau","courant","新的（刚出现、新近的）"],["d'occasion","courant","反义词：二手的"],["vieux","courant","反义词：旧的、老的"]],"fq":"极高频，日常常用。","me":"neuf = 新的 = nouveau 的亲戚，都来自 novus。","tr":{"zh":"你的鞋子是新的吗？","fr":"Tes chaussures sont neuves ?","alt":"Elles sont neuves, tes chaussures ?","note":"chaussures 是阴性复数，所以用 neuves。"}},
 "Social(e)": {"pos":"adj. 形容词，阴性 sociale，阳性复数 sociaux，阴性复数 sociales","s":"社会的；社交的。les réseaux sociaux = 社交网络；la sécurité sociale = 社会保障；un travailleur social = 社工。","ipa":"[sɔ.sjal]","ph":"so [sɔ]；ci 读 [sj]；al 读 [al]；结尾 l 要读出。","pi":"阳性复数是 sociaux，不是 socials；c 在 i 前读 [s]；结尾 l 要发音。","et":"来自拉丁语 socialis（同伴的），源自 socius（伙伴）。同族：société、associer、sociologie。","ex":[["Il travaille dans le secteur social.","他在社会服务领域工作。"],["J'utilise les réseaux sociaux tous les jours.","我每天都用社交网络。"]],"co":[["les réseaux sociaux","社交网络"],["la sécurité sociale","社会保障"],["un problème social","社会问题"],["les sciences sociales","社会科学"]],"sy":[["collectif","courant","集体的"],["public","courant","公共的"]],"fq":"高频，新闻和日常常用。","me":"social ← socius（伙伴）：和「同伴」有关的。","tr":{"zh":"社交网络对年轻人很重要。","fr":"Les réseaux sociaux sont importants pour les jeunes.","alt":"Les réseaux sociaux comptent beaucoup pour les jeunes.","note":"réseaux 是阳性复数，所以用 sociaux。"}},
 "Avoir besoin d'aide": {"pos":"loc.v. 动词短语，avoir 助动词","s":"需要帮助。avoir besoin de + 名词 / 动词原形；avoir besoin d'aide = 需要帮忙。问别人：Tu as besoin d'aide ? = 你需要帮忙吗？","ipa":"[a.vwaʁ bə.zwɛ̃ dɛd]","ph":"avoir [a.vwaʁ]；besoin 读 [bə.zwɛ̃]，oi 读 [wa]；d'aide 读 [dɛd]，ai 读 [ɛ]。","pi":"besoin 里的 s 读 [z]，oin 读 [wɛ̃]；aide 的 e 不发音；de 遇到元音要省音：d'aide。","et":"besoin 来自古法语 besoing，词源不太确定；aide 来自拉丁语 adjutare（帮助）。","ex":[["J'ai besoin d'aide pour mes devoirs.","我做作业需要帮助。"],["Tu as besoin d'aide ?","你需要帮忙吗？"]],"co":[["avoir besoin de quelqu'un","需要某人"],["avoir besoin de + inf.","需要做某事"],["demander de l'aide","请求帮助"]],"sy":[["demander de l'aide","courant","寻求帮助"],["être en difficulté","courant","遇到困难"]],"fq":"极高频，日常常用。","me":"besoin：b-e-s-o-i-n，想像「我必须要」的感觉。","tr":{"zh":"我搬家需要帮忙。","fr":"J'ai besoin d'aide pour déménager.","alt":"Tu peux m'aider à déménager ?","note":"avoir besoin de + 动词原形；de 遇元音变 d'。"}},
 "Avoir l'embarras du choix": {"pos":"loc.v. 固定短语，avoir 助动词","s":"选择太多，不知道选哪个（挑花眼）。常用在餐厅、商店、礼物等场合。不含贬义，表示「选择很多」。","ipa":"[a.vwaʁ lɑ̃.ba.ʁa dy ʃwa]","ph":"avoir [a.vwaʁ]；l'embarras 读 [lɑ̃.ba.ʁa]，em 读 [ɑ̃]，s 不发音；du [dy]；choix 读 [ʃwa]，x 不发音。","pi":"embarras 里的 s 不发音；choix 的 x 不发音；ch 读 [ʃ]；embarras 不是「尴尬」，而是「麻烦、犹豫」。","et":"embarras 来自动词 embarrasser（妨碍）；choix 来自动词 choisir，源自日耳曼语 kausjan（尝、选）。","ex":[["Au restaurant, on a l'embarras du choix.","在餐厅有很多选择。"],["Pour les cadeaux, j'ai l'embarras du choix.","挑礼物时我挑花了眼。"]],"co":[["avoir l'embarras du choix","挑花眼"],["un grand choix","很多选择"],["faire un choix","做选择"]],"sy":[["avoir beaucoup de choix","courant","选择很多"],["hésiter","courant","犹豫"]],"fq":"中频，日常常用。","me":"embarras du choix：被「选择」绊住了脚。","tr":{"zh":"在这家商店我挑花了眼。","fr":"Dans ce magasin, on a l'embarras du choix.","alt":"Il y a tellement de choix dans ce magasin !","note":"固定短语，embarras 不能换。"}},
 "Avoir la main verte": {"pos":"loc.v. 固定短语，avoir 助动词","s":"擅长种植；有绿手指。指很会养花草、种菜的人。ma mère a la main verte = 我妈妈很会种花草。","ipa":"[a.vwaʁ la mɛ̃ vɛʁt]","ph":"avoir [a.vwaʁ]；la [la]；main 读 [mɛ̃]；verte 读 [vɛʁt]，t 要发音。","pi":"main 里的 ain 读 [ɛ̃]，不发 n；verte 是阴性，t 要读出（阴性形式）；不要说 le pouce vert（那是英语的 green thumb）。","et":"main 来自拉丁语 manus；vert 来自拉丁语 viridis（绿色）。字面意思：手是绿色的，像沾了植物。","ex":[["Ma mère a la main verte.","我妈妈很会种花草。"],["Avec lui, toutes les plantes poussent : il a la main verte.","有他在，所有植物都长得好：他有绿手指。"]],"co":[["avoir la main verte","擅长种植"],["faire pousser des plantes","让植物长起来"],["jardiner","做园艺"]],"sy":[["avoir le sens du jardinage","courant","有园艺天赋"]],"fq":"中频，日常常用。","me":"绿手 = 摸过的花草都长得好。","tr":{"zh":"我外婆很会种花草。","fr":"Ma grand-mère a la main verte.","alt":"Ma grand-mère s'y connaît en plantes.","note":"与英语不同，法语说「绿色的手」，不是 pouce（拇指）。"}},
 "Être à découvert": {"pos":"loc.v. 固定短语，être 助动词","s":"账户透支；银行账户里的钱是负数。mon compte est à découvert = 我的账户透支了。也可表示「暴露、没有遮盖」：à découvert = 在露天。","ipa":"[ɛtʁ a de.ku.vɛʁ]","ph":"être [ɛtʁ]；à [a]；dé [de]；cou [ku]；vert 读 [vɛʁ]，结尾 t 不发音。","pi":"découvert 里的 t 不发音，读 [de.ku.vɛʁ]；découvert 不是 découvrir（发现）的变位，意思是「透支」；不要把 découvert 当成「被发现」。","et":"découvert 是 découvrir 的过去分词，来自 dé-（去掉）+ couvrir（盖）。「透支」的意思是账户上「没有保护」。","ex":[["Mon compte est à découvert.","我的账户透支了。"],["Il est à découvert depuis trois jours.","他账户透支三天了。"]],"co":[["être à découvert","账户透支"],["un découvert bancaire","银行透支"],["autorisation de découvert","透支额度"]],"sy":[["être dans le rouge","familier","账户在红字里（口语）"],["être fauché","familier","身无分文"]],"fq":"中频，银行、金钱话题常用。","me":"découvert：钱「没盖住」，账户露出了窟窿。","tr":{"zh":"我这个月又透支了。","fr":"Ce mois-ci, je suis encore à découvert.","alt":"Ce mois-ci, mon compte est encore dans le rouge.","note":"être à découvert 是固定短语，découvert 不变形。"}},
 "De l'artisanat": {"pos":"n.m. 阳性名词，不可数，常用部分冠词 de l'","s":"手工艺品；手工业。de l'artisanat local = 当地手工艺品。常用 de l' 表示不定量。un artisan = 手工艺人；工匠。","ipa":"[aʁ.ti.za.na]","ph":"ar [aʁ]；ti [ti]；s 在两个元音之间读 [z]；na [na]；结尾 t 不发音。","pi":"s 读 [z]，不是 [s]；结尾 t 不发音；是阳性，不可数：de l'artisanat，不说 des artisanats。","et":"来自 artisan（手工艺人），源自意大利语 artigiano；加后缀 -at 表示行业。同族：art、artiste。","ex":[["J'ai acheté de l'artisanat local.","我买了当地的手工艺品。"],["Cette région est connue pour son artisanat.","这个地区以手工艺闻名。"]],"co":[["l'artisanat local","当地手工艺"],["acheter de l'artisanat","买手工艺品"],["un marché d'artisanat","手工艺市场"],["un artisan","手工艺人"]],"sy":[["fait main","courant","手工做的"],["industrie","courant","反义：工业"]],"fq":"中频，旅行话题常用。","me":"artisan + at：手工艺人做的东西。","tr":{"zh":"我想买一点当地的手工艺品。","fr":"Je voudrais acheter de l'artisanat local.","alt":"Je cherche de l'artisanat du coin.","note":"不可数名词用 de l'：de l'artisanat。"}},
 "Du kayak": {"pos":"n.m. 阳性名词，复数 kayaks，常用 faire du kayak","s":"皮划艇；划皮划艇这项运动。faire du kayak = 划皮划艇。也指船：un kayak = 一只皮划艇。","ipa":"[ka.jak]","ph":"k [k]；a [a]；y 读 [j]；a [a]；结尾 k 要读出。","pi":"结尾 k 要发音；y 在这里读 [j]；是阳性：un kayak。","et":"来自因纽特语 qajaq，经欧洲其他语言进入法语。","ex":[["Nous faisons du kayak sur la rivière.","我们在河上划皮划艇。"],["Il a loué un kayak pour la journée.","他租了一只皮划艇用一天。"]],"co":[["faire du kayak","划皮划艇"],["un kayak double","双人皮划艇"],["une sortie en kayak","皮划艇出游"]],"sy":[["canoë","courant","独木舟（用单桨）"],["aviron","courant","赛艇"]],"fq":"中频，运动话题常用。","me":"kayak 前后都是 ka：[ka.jak]，像左右对称。","tr":{"zh":"周末我们去河上划皮划艇。","fr":"Ce week-end, nous faisons du kayak sur la rivière.","alt":"Ce week-end, on fait du kayak sur la rivière.","note":"faire du + 运动：faire du kayak。"}},
 "Du rhum": {"pos":"n.m. 阳性名词，不可数，复数 rhums","s":"朗姆酒。du rhum = 一些朗姆酒；un rhum = 一杯朗姆酒。常用于甜点和鸡尾酒：un baba au rhum（朗姆蛋糕）。","ipa":"[ʁɔm]","ph":"rh 读 [ʁ]，h 不发音；u 读 [ɔ]；m 读 [m]。","pi":"h 不发音，rh 读 [ʁ]；u 读 [ɔ]，不是 [y]；和英语 rum 相比，法语读 [ʁɔm]。","et":"来自英语 rum；法语拼写加了 h，读音仍是 [ʁɔm]。","ex":[["Il boit un verre de rhum.","他喝一杯朗姆酒。"],["Le gâteau est au rhum.","这个蛋糕有朗姆酒味。"]],"co":[["un verre de rhum","一杯朗姆酒"],["un baba au rhum","朗姆蛋糕"],["un punch au rhum","朗姆潘趣酒"]],"sy":[["alcool","courant","酒（总称）"],["whisky","courant","威士忌"]],"fq":"中频，饮料话题常用。","me":"rhum 读 [ʁɔm]，像「若姆」：u 不读 u。","tr":{"zh":"他在咖啡里加了一点朗姆酒。","fr":"Il met un peu de rhum dans son café.","alt":"Il ajoute un peu de rhum à son café.","note":"un peu de + 不可数名词，不加冠词。"}},
 "L'arc de Triomphe": {"pos":"n.m. 阳性名词，专有名称，l'Arc de Triomphe","s":"凯旋门，巴黎的著名纪念碑，位于戴高乐广场（星形广场）。普通名词 un arc = 拱门；un arc de triomphe = 凯旋门（泛指）。","ipa":"[aʁk də tʁi.jɔ̃f]","ph":"arc 读 [aʁk]，结尾 c 要读；de [də]；Triomphe 读 [tʁi.jɔ̃f]，ph 读 [f]，e 不发音。","pi":"arc 的 c 要发音；ph 读 [f]；o 在 m 前读鼻化 [ɔ̃]，m 不发音；常把 l'arc de Triomphe 说成 l'Arc de Triomphe（专有名称首字母大写）。","et":"arc 来自拉丁语 arcus（弓、拱）；triomphe 来自拉丁语 triumphus（凯旋仪式）。1806 年拿破仑下令修建，纪念法军的胜利。","ex":[["L'arc de Triomphe est célèbre.","凯旋门很有名。"],["On monte en haut de l'arc de Triomphe.","我们爬到凯旋门顶上。"]],"co":[["monter à l'arc de Triomphe","爬上凯旋门"],["la place Charles-de-Gaulle","戴高乐广场"],["les Champs-Élysées","香榭丽舍大街"]],"sy":[["la tour Eiffel","courant","埃菲尔铁塔，另一座巴黎名胜"],["le Louvre","courant","卢浮宫"]],"fq":"中频，旅游话题常用。","me":"arc（拱）+ triomphe（凯旋）：胜利者走过的门。","tr":{"zh":"我们从凯旋门走到香榭丽舍大街。","fr":"Nous marchons de l'arc de Triomphe aux Champs-Élysées.","alt":"On descend les Champs-Élysées depuis l'arc de Triomphe.","note":"l'arc 是阳性；专有名称里 Triomphe 大写。"}},
 "Le Pont Alexandre III": {"pos":"n.m. 阳性专有名词（桥名），一般不用复数","s":"巴黎塞纳河上最华丽的桥，1900 年世博会前后建成，以俄国沙皇亚历山大三世命名，象征法俄友好。Pont Alexandre III 读作 Pont Alexandre trois，桥名里的 III 读基数词 trois，不读「第三」。","ipa":"[pɔ̃ a.lɛk.sɑ̃dʁ tʁwa]","ph":"pont [pɔ̃]，t 不发音；Alexandre：x 读 [ks]，an 读 [ɑ̃]，结尾 -dre 读 [dʁ]；III = trois [tʁwa]。","pi":"pont 的 t 不发；Alexandre 的 x 要读 [ks]；桥名后面的罗马数字读 trois，不是 troisième。","et":"pont 来自拉丁语 pons；Alexandre 是人名，来自希腊语 Alexandros；桥名纪念沙皇亚历山大三世。","ex":[["Le Pont Alexandre III est très beau.","亚历山大三世桥很美。"],["Nous traversons le Pont Alexandre III à pied.","我们步行过亚历山大三世桥。"]],"co":[["traverser le pont","过桥"],["sur le Pont Alexandre III","在亚历山大三世桥上"],["près du Grand Palais","在大皇宫附近"]],"sy":[["pont","courant","桥（普通名词）"]],"fq":"专有名词，旅游时常见。","me":"Alexandre + trois：金色雕像的桥，记住「三世」读 trois。","tr":{"zh":"我们在亚历山大三世桥上拍照。","fr":"Nous prenons des photos sur le Pont Alexandre III.","alt":"On prend des photos sur le Pont Alexandre III.","note":"桥名前常加 le；sur 表示「在……上」。"}},
 "Le tourisme": {"pos":"n.m. 阳性名词，通常不加复数","s":"旅游业；旅游。指整个行业或旅游这件事，不是「游客」（游客是 un touriste）。常见搭配：faire du tourisme（观光游览）。","ipa":"[tu.ʁism]","ph":"ou [u]；r 是小舌音 [ʁ]；-isme 读 [ism]，结尾 e 不发音。","pi":"tourisme 的 ou 读 [u]；结尾的 -me 轻读，不要读成「tourisme-e」；不要和 touriste 混淆。","et":"由 tour（旅行、周游）加后缀 -isme 构成，同族词：touriste、touristique。","ex":[["Le tourisme est important pour la ville.","旅游业对这座城市很重要。"],["Nous faisons du tourisme à Lyon.","我们在里昂观光。"],["Le tourisme de masse pose des problèmes.","大众旅游带来了一些问题。"]],"co":[["faire du tourisme","观光游览"],["le tourisme de masse","大众旅游"],["l'office de tourisme","旅游局，游客中心"],["le tourisme vert","生态旅游，乡村游"]],"sy":[["voyage","courant","旅行（一次具体的行程）"],["touriste","courant","游客（人）"]],"fq":"中高频，日常和新闻都常用。","me":"tour（转一圈）+ isme：到处转转就是旅游业。","tr":{"zh":"旅游业在这个地区很重要。","fr":"Le tourisme est très important dans cette région.","alt":"Ici, le tourisme, c'est très important.","note":"表示泛指的行业时用定冠词 le。"}},
 "Un audioguide": {"pos":"n.m. 阳性名词，复数 audioguides","s":"语音导览器。在博物馆、景点租借的耳机加讲解设备，也可以指手机上的语音导览应用。常说 louer un audioguide（租一个语音导览）。","ipa":"[o.djo.ɡid]","ph":"au [o]；di 在这里读 [dj]；gu 在 e/i 前读 [ɡ]，所以 guide 是 [ɡid]。","pi":"audio 的 au 读 [o]，不是 [au]；gui 里的 u 不发音，只让 g 保持硬音。","et":"audio-（拉丁语 audire「听」）加 guide（向导）构成的合成词。","ex":[["L'audioguide coûte 5 euros.","语音导览五欧元。"],["Je prends un audioguide en français.","我拿一个法语的语音导览。"]],"co":[["louer un audioguide","租语音导览器"],["un audioguide en anglais","英语语音导览"],["visiter avec un audioguide","用语音导览参观"]],"sy":[["guide","courant","导游（人）或指南书"],["visite guidée","courant","有人带领的导览参观"]],"fq":"旅游场景中常用。","me":"audio（听）+ guide（向导）：耳朵里的导游。","tr":{"zh":"我想租一个英语语音导览。","fr":"Je voudrais louer un audioguide en anglais.","alt":"Je peux avoir un audioguide en anglais, s'il vous plaît ?","note":"je voudrais 比 je veux 更礼貌。"}},
 "Un bâtiment": {"pos":"n.m. 阳性名词，复数 bâtiments","s":"建筑物；楼房。泛指任何建好的房子或大楼（办公楼、学校、住宅楼），比 maison（住宅）更广。也指「船只」时多见于军舰、大型船：un bâtiment de guerre。","ipa":"[bɑ.ti.mɑ̃]","ph":"â 读 [ɑ]；-ti- 读 [ti]；-ment 读鼻化元音 [mɑ̃]，t 不发音。","pi":"结尾 -ment 的 -nt 不发音，只读 [mɑ̃]；â 上的帽子别漏写；不要写成 batiment。","et":"来自动词 bâtir（建造）加后缀 -ment；â 里的帽子表示古法语里曾经有的 s。","ex":[["C'est un grand bâtiment moderne.","这是一栋现代化的大楼。"],["Ce bâtiment date du XIXe siècle.","这栋建筑建于十九世纪。"]],"co":[["un bâtiment ancien / moderne","古老的 / 现代的建筑"],["un bâtiment public","公共建筑"],["le secteur du bâtiment","建筑业"]],"sy":[["immeuble","courant","楼房（多层住宅或办公楼）"],["édifice","soutenu","宏伟的建筑物"],["construction","courant","建造；建筑物"]],"fq":"高频，日常常用。","me":"bâtir（盖）+ ment：盖出来的东西就是 bâtiment。","tr":{"zh":"这栋楼很旧，但是很漂亮。","fr":"Ce bâtiment est très vieux, mais il est très joli.","alt":"C'est un vieux bâtiment, mais il est superbe.","note":"ce 加阳性名词；这里的 il 指代 bâtiment。"}},
 "Un canard": {"pos":"n.m. 阳性名词，复数 canards；母鸭 une cane","s":"鸭子。une cane 是母鸭，un caneton 是小鸭。口语里 canard 也可指「报纸」（有点嘲讽）或「假消息」。","ipa":"[ka.naʁ]","ph":"c 在 a 前读 [k]；结尾的 d 不发音，读 [naʁ]。","pi":"canard 的 d 不发音；不要读成 [ka.nar.d]；阴性是 cane，不是 canarde。","et":"来源不确定，可能与拟声（鸭叫声）有关。同族词：caneton（小鸭）、canarder（从暗处射击）。","ex":[["Il y a un canard dans le parc.","公园里有一只鸭子。"],["Les canetons suivent la cane.","小鸭跟着母鸭。"]],"co":[["un canard laqué","烤鸭（北京烤鸭）"],["un confit de canard","油封鸭"],["une mare aux canards","鸭塘"]],"sy":[["cane","courant","母鸭"],["oie","courant","鹅，和鸭子不同"]],"fq":"中频，生活和美食里常见。","me":"canard 的 d 沉默，像鸭子安静地游。","tr":{"zh":"孩子们在池塘里看鸭子。","fr":"Les enfants regardent les canards dans l'étang.","alt":"Les enfants regardent des canards sur l'étang.","note":"regarder 后面直接跟宾语，不加 à。"}},
 "Un circuit (de voyage)": {"pos":"n.m. 阳性名词，复数 circuits","s":"旅行线路；环线之旅。指事先安排好的、有多个停靠点的行程，常含交通和住宿。也指电路（circuit électrique）和赛车场（circuit automobile）。","ipa":"[siʁ.kɥi]","ph":"c 在 i 前读 [s]；-cuit 读 [kɥi]，u 是圆唇的 [ɥ]，t 不发音。","pi":"最后的 t 不发音；uit 的 u 要圆唇，读 [ɥi]，不要读成 [kui]。","et":"来自拉丁语 circuitus（绕圈走），由 circum（周围）和 ire（走）而来。","ex":[["Nous avons prévu un circuit au Vietnam.","我们计划了越南之旅。"],["Le circuit dure dix jours.","这条线路为期十天。"]],"co":[["faire un circuit","走一条线路旅行"],["un circuit organisé","跟团游"],["un circuit électrique","电路"],["un circuit court","短链条销售（产地直销）"]],"sy":[["voyage organisé","courant","跟团旅行"],["itinéraire","courant","路线，行程安排"],["parcours","courant","路程，路线"]],"fq":"中频，旅游场景常用。","me":"circuit 像 circle：转一圈再回来。","tr":{"zh":"我们订了一个十天的旅行线路。","fr":"Nous avons réservé un circuit de dix jours.","alt":"On a réservé un circuit de dix jours.","note":"un circuit de + 时间：表示线路的时长。"}},
 "Un coup de soleil": {"pos":"n.m. 阳性名词，复数 coups de soleil（coup 加 s，soleil 不变）","s":"晒伤。字面是「太阳的一击」。动词搭配：prendre / attraper un coup de soleil（被晒伤）。不要说 une brûlure du soleil。","ipa":"[ku də sɔ.lɛj]","ph":"coup 的 p 不发音，读 [ku]；de 轻读 [də]；soleil 的 -eil 读 [ɛj]。","pi":"coup 里的 p 不发音；soleil 的 -eil 读 [ɛj]，l 不单独发音。","et":"coup（一击）来自拉丁语 colpus 一系，soleil 来自拉丁语 soliculus（太阳的小形式）。字面 = 太阳的一击。","ex":[["J'ai attrapé un coup de soleil.","我被晒伤了。"],["Mets de la crème, sinon tu auras un coup de soleil.","涂防晒霜，不然你会晒伤。"]],"co":[["prendre / attraper un coup de soleil","被晒伤"],["avoir un coup de soleil sur le nez","鼻子晒伤了"],["la crème solaire","防晒霜"]],"sy":[["bronzage","courant","晒黑（不是晒伤）"],["insolation","courant","中暑，日射病"]],"fq":"夏天和海边场景常用。","me":"太阳打了你一拳 = 晒伤。","tr":{"zh":"他在海滩上被晒伤了。","fr":"Il a pris un coup de soleil à la plage.","alt":"Il a attrapé un coup de soleil sur la plage.","note":"过去时用 avoir + 过去分词 pris / attrapé。"}},
 "Un courant d'air": {"pos":"n.m. 阳性名词，复数 courants d'air","s":"穿堂风；过堂风。门窗开着时屋里窜过的冷风，法国人常说怕 courant d'air。courant 另有「水流、电流」的意思。","ipa":"[ku.ʁɑ̃ dɛʁ]","ph":"cou [ku]；-rant 读 [ʁɑ̃]，t 不发音；d'air 缩读，d' 与 air 连读成 [dɛʁ]。","pi":"courant 的 -nt 不发音；d'air 是省音 de + air，不要分开读 [də ɛʁ]。","et":"courant 是动词 courir（跑，流动）的现在分词，来自拉丁语 currere；air 来自拉丁语 aer。字面 = 跑动的空气。","ex":[["Ferme la porte, il y a un courant d'air.","关门，有穿堂风。"],["Je n'aime pas les courants d'air.","我不喜欢穿堂风。"]],"co":[["il y a un courant d'air","有穿堂风"],["faire un courant d'air","让风穿过（开两扇窗）"],["un courant électrique","电流"]],"sy":[["vent","courant","风（户外）"],["brise","courant","微风"]],"fq":"中频，居家常说。","me":"courir（跑）+ air：空气跑过房间。","tr":{"zh":"把窗户关上，有穿堂风。","fr":"Ferme la fenêtre, il y a un courant d'air.","alt":"Ferme la fenêtre, ça fait un courant d'air.","note":"命令式 ferme 的 tu 形没有 s。"}},
 "Un crabe": {"pos":"n.m. 阳性名词，复数 crabes","s":"螃蟹。海边常见，也作菜名：du crabe（蟹肉）。口语里 marcher comme un crabe 指横着走。","ipa":"[kʁɑb]","ph":"cr 连读 [kʁ]；a 读后元音 [ɑ]；结尾 b 要发音，e 不发。","pi":"r 是小舌音，要从喉咙发出；b 要读出来，别丢掉；这个词只有一个音节。","et":"借自日耳曼语，与英语 crab 同源。","ex":[["J'ai vu un crabe sur la plage.","我在海滩上看到一只螃蟹。"],["On mange du crabe à Noël.","我们圣诞节吃蟹。"]],"co":[["un crabe de mer","海蟹"],["de la chair de crabe","蟹肉"],["marcher comme un crabe","像螃蟹一样横着走"]],"sy":[["homard","courant","龙虾，不是螃蟹"],["tourteau","courant","黄道蟹（大海蟹）"]],"fq":"中低频，海边和美食里出现。","me":"crabe 和英语 crab 几乎一样，多读一个 e 不发音。","tr":{"zh":"孩子在岩石上找到一只小螃蟹。","fr":"L'enfant trouve un petit crabe sur les rochers.","alt":"Le petit a trouvé un petit crabe sur les rochers.","note":"petit 放在名词前面。"}},
 "Un dauphin": {"pos":"n.m. 阳性名词，复数 dauphins","s":"海豚。历史上 le Dauphin 是法国国王长子（王储）的头衔，所以首字母大写时指王储。口语里 dauphin 也可指「接班人」。","ipa":"[do.fɛ̃]","ph":"au 读 [o]；ph 读 [f]；结尾 in 读鼻化元音 [ɛ̃]，n 不发音。","pi":"ph 读 [f]，不是 [p]；au 读 [o]；结尾 -in 是鼻化音，不是 [in]。","et":"来自拉丁语 delphinus，源自希腊语 delphis。王储称号来自 Dauphiné 地区领主的徽记（海豚），来源可靠。","ex":[["Le dauphin saute dans l'eau.","海豚跃出水面。"],["Nous avons vu des dauphins en mer.","我们在海上看到了海豚。"]],"co":[["un dauphin à nez de bouteille","宽吻海豚"],["nager avec les dauphins","与海豚同游"],["le Dauphin de France","法国王储"]],"sy":[["baleine","courant","鲸鱼，不是海豚"],["requin","courant","鲨鱼"]],"fq":"中频，动物主题常见。","me":"dauphin 和 dolphin 同根：d-l-ph 的影子。","tr":{"zh":"海豚是很聪明的动物。","fr":"Le dauphin est un animal très intelligent.","alt":"Les dauphins sont des animaux très intelligents.","note":"泛指一类动物用定冠词 le / les。"}},
 "Un désert": {"pos":"n.m. 阳性名词，复数 déserts；作形容词时 désert(e) 意为「无人的」","s":"沙漠；荒漠。也比喻人烟稀少的地方：un désert médical（缺医少药的地区）。形容词 désert 指「荒无人烟的」，如 une plage déserte。","ipa":"[de.zɛʁ]","ph":"dé [de]；s 在元音之间读 [z]；-ert 读 [ɛʁ]，t 不发音。","pi":"désert 是 [de.zɛʁ]（一个 s），dessert（甜点）是 [de.sɛʁ]（两个 s，读 [s]）；t 不发音。","et":"来自拉丁语 desertum（被抛弃的地方），由 deserere（抛弃）而来。同族：déserter（逃离）。","ex":[["Il fait chaud dans le désert.","沙漠里很热。"],["Le Sahara est un grand désert.","撒哈拉是一片大沙漠。"]],"co":[["traverser le désert","穿越沙漠"],["le désert du Sahara","撒哈拉沙漠"],["une île déserte","无人岛"]],"sy":[["dune","courant","沙丘"],["steppe","courant","草原，干草地"]],"fq":"中频，地理主题常见。","me":"一个 s = 沙漠；两个 s = 甜点。","tr":{"zh":"在沙漠里，白天很热，晚上很冷。","fr":"Dans le désert, il fait chaud le jour et froid la nuit.","alt":"Dans le désert, il fait très chaud le jour, mais très froid la nuit.","note":"天气用 il fait；le jour / la nuit 表示白天 / 夜晚。"}},
 "Un devis": {"pos":"n.m. 阳性名词，单复数同形 devis","s":"报价单；估价单。在装修、修车、旅行社订行程前要的书面价格估算，常说 demander un devis（要报价）。和 facture（发票）不同：devis 是事前报价，facture 是事后收款。","ipa":"[də.vi]","ph":"de 读 [də]；vi 读 [vi]；结尾的 s 不发音。","pi":"结尾 s 不发音，所以单复数同音；别把 devis 和 facture（发票）混用；也不要把 de 读成 [de]。","et":"与动词 deviser（计划，详细安排）同源，原意是「安排好的清单」。","ex":[["J'ai demandé un devis pour les travaux.","我请求了装修报价。"],["Le devis est gratuit.","报价是免费的。"]],"co":[["demander un devis","要报价单"],["faire un devis","开报价单"],["accepter / signer un devis","接受 / 签署报价单"],["un devis gratuit","免费报价"]],"sy":[["estimation","courant","估价（不一定是书面的）"],["facture","courant","发票，付款后开"]],"fq":"中频，装修和订服务时常用。","me":"devis 事前报价，facture 事后收钱。","tr":{"zh":"我想要一份厨房装修的报价单。","fr":"Je voudrais un devis pour refaire la cuisine.","alt":"Pouvez-vous me faire un devis pour la cuisine, s'il vous plaît ?","note":"pour + 动词原形表示目的。"}},
 "Un fleuve": {"pos":"n.m. 阳性名词，复数 fleuves","s":"大河；直接流入大海的河。法语区分：fleuve 流入海（la Seine、la Loire），rivière 流入另一条河。中文都叫「河」，注意区别。","ipa":"[flœv]","ph":"fl 连读 [fl]；eu 读 [œ]（闭口前的开音）；v 要发音，结尾 e 不发。","pi":"eu 在 v 前读 [œ]，嘴形比 [ø] 更开；结尾 -ve 的 v 要读出来；fleuve 是阳性。","et":"来自拉丁语 fluvius（河），与 fluere（流）同源。","ex":[["Le fleuve est très long.","这条河很长。"],["La Loire est un fleuve.","卢瓦尔河是一条大河。"]],"co":[["un fleuve se jette dans la mer","大河流入大海"],["le long du fleuve","沿着河边"],["traverser le fleuve","渡河"],["un fleuve de lave","熔岩流"]],"sy":[["rivière","courant","河（流入另一条河）"],["ruisseau","courant","小溪"]],"fq":"中频，地理主题常见。","me":"fleuve → flow：流向海洋的那条大河。","tr":{"zh":"这条大河流入大海。","fr":"Ce fleuve se jette dans la mer.","alt":"Le fleuve finit dans la mer.","note":"se jeter dans = 汇入、流入。"}},
 "Un moulin": {"pos":"n.m. 阳性名词，复数 moulins","s":"磨坊；风车；磨。un moulin à vent 是风车磨坊，un moulin à eau 是水磨坊。也指家用小磨：un moulin à café（咖啡研磨机）、un moulin à poivre（胡椒研磨瓶）。巴黎的 Moulin Rouge 是著名歌舞厅。","ipa":"[mu.lɛ̃]","ph":"ou [u]；-in 读鼻化元音 [ɛ̃]，n 不发音。","pi":"ou 读 [u]；结尾 -in 是鼻化音 [ɛ̃]，不是 [in]；moulin 是「磨坊」，不要和 moule（贻贝）混。","et":"来自晚期拉丁语 molinum，源自 mola（磨石）。同族：moudre（磨碎）、meunier（磨坊主）。","ex":[["C'est un vieux moulin.","这是一座老磨坊。"],["Le moulin tourne avec le vent.","风车随风转动。"]],"co":[["un moulin à vent","风车"],["un moulin à eau","水磨坊"],["un moulin à café","咖啡研磨机"],["le Moulin Rouge","红磨坊"]],"sy":[["éolienne","courant","风力发电机"],["minoterie","soutenu","面粉厂"]],"fq":"中低频，旅游和乡村主题里常见。","me":"moulin 与 moudre 同族：磨，磨，磨。","tr":{"zh":"我们在山上参观了一座老风车。","fr":"Nous avons visité un vieux moulin à vent dans la montagne.","alt":"On a visité un vieux moulin à vent en montagne.","note":"moulin à vent：à 表示用途 / 方式。"}},
 "Un office de tourisme": {"pos":"n.m. 阳性名词，复数 offices de tourisme","s":"旅游局；游客服务中心。城镇里给游客发地图、介绍景点、推荐住宿的机构。也可以说 un office du tourisme。简称 l'OT。","ipa":"[ɔ.fis də tu.ʁism]","ph":"office 读 [ɔ.fis]，c 在 e 前读 [s]；de 轻读；tourisme [tu.ʁism]。","pi":"office 的 c 读 [s]；注意 office 在这里是阳性，不要说 une office。","et":"office 来自拉丁语 officium（职责，服务）；tourisme 见 tour + -isme。","ex":[["L'office de tourisme est près de la gare.","旅游局在火车站附近。"],["Demande une carte à l'office de tourisme.","去游客中心要一张地图。"]],"co":[["aller à l'office de tourisme","去游客服务中心"],["demander un plan à l'office de tourisme","向游客中心要地图"],["l'office du tourisme","旅游局（另一种说法）"]],"sy":[["syndicat d'initiative","courant","小城镇的旅游接待处（较老的说法）"],["point information","courant","信息点"]],"fq":"旅游时常见。","me":"office = 办公室；tourisme = 旅游：旅游办公室。","tr":{"zh":"我们先去旅游局拿地图。","fr":"Nous allons d'abord à l'office de tourisme chercher un plan.","alt":"On passe d'abord à l'office de tourisme pour prendre un plan.","note":"un plan 指城市地图；une carte 指较大范围的地图。"}},
 "Un palais": {"pos":"n.m. 阳性名词，单复数同形 palais","s":"宫殿；宫。如 le palais de l'Élysée（总统府）。另一个常用意思是「上颚；味觉」：avoir le palais fin（口味刁）。还有 le Palais de Justice（法院）。","ipa":"[pa.lɛ]","ph":"pa [pa]；-lais 读 [lɛ]，ai 读 [ɛ]，结尾 s 不发音。","pi":"结尾 -ais 读 [ɛ]，s 不发音，所以单复数同音；别把它和 palace（英语的酒店）混。","et":"来自拉丁语 palatium，源自罗马的帕拉丁山（Palatium）。英语 palace 同源。","ex":[["Le roi habite dans un palais.","国王住在宫殿里。"],["Nous visitons le palais de Versailles.","我们参观凡尔赛宫。"]],"co":[["un palais royal","王宫"],["le palais de l'Élysée","爱丽舍宫"],["avoir le palais fin","味觉灵敏，口味挑剔"]],"sy":[["château","courant","城堡"],["manoir","courant","庄园住宅"]],"fq":"中频，历史和旅游里常见。","me":"palais 与 palace 同源，但读 [pa.lɛ]。","tr":{"zh":"我们明天参观宫殿。","fr":"Nous visitons le palais demain.","alt":"On va visiter le palais demain.","note":"visiter 用于参观地方，rendre visite à 用于拜访人。"}},
 "Un passeport": {"pos":"n.m. 阳性名词，复数 passeports","s":"护照。出国要带，常说 contrôle des passeports（护照检查）。注意：passeport 是护照，carte d'identité 是身份证。","ipa":"[pas.pɔʁ]","ph":"ss 读 [s]；-port 读 [pɔʁ]，t 不发音。","pi":"port 的 t 不发音，读 [pɔʁ]；中间 ss 读清音 [s]；不要把 passeport 的 e 读出来。","et":"由 passer（通过）+ port（港口）构成，原指通过港口的许可证。","ex":[["N'oublie pas ton passeport.","别忘了带护照。"],["Mon passeport est valable cinq ans.","我的护照有效期五年。"]],"co":[["renouveler son passeport","换发护照"],["un passeport valide / périmé","有效 / 过期的护照"],["le contrôle des passeports","护照检查"],["présenter son passeport","出示护照"]],"sy":[["carte d'identité","courant","身份证"],["visa","courant","签证"]],"fq":"中高频，旅行必备词。","me":"passer + port：过港口就要看护照。","tr":{"zh":"我的护照在包里。","fr":"Mon passeport est dans mon sac.","alt":"J'ai mon passeport dans mon sac.","note":"dans + 容器，表示在……里面。"}},
 "Un phare": {"pos":"n.m. 阳性名词，复数 phares","s":"灯塔；汽车大灯。un phare 在海边指灯塔，在路上指车头灯：allumer les phares（开大灯）。","ipa":"[faʁ]","ph":"ph 读 [f]；a 读 [a]；r 小舌音 [ʁ]，结尾 e 不发音。","pi":"ph 读 [f]，不是 [p]；整个词只有一个音节。","et":"来自拉丁语 pharus，源自希腊语 Pharos（亚历山大港的法罗斯岛，岛上有著名灯塔）。","ex":[["Le phare guide les bateaux.","灯塔为船只引路。"],["Allume tes phares, il fait nuit.","开大灯，天黑了。"]],"co":[["un phare de voiture","汽车大灯"],["allumer les phares","开车灯"],["le gardien du phare","灯塔守护人"],["les feux de croisement","近光灯（对比：远光灯 les pleins phares）"]],"sy":[["lanterne","courant","灯笼，小灯"],["feu","courant","信号灯，车灯"]],"fq":"中频，海边和驾驶里常见。","me":"phare ≈ Pharos，亚历山大港那座灯塔。","tr":{"zh":"晚上，灯塔为船只引路。","fr":"La nuit, le phare guide les bateaux.","alt":"Le soir, le phare montre le chemin aux bateaux.","note":"guider 是及物动词，直接接宾语。"}},
 "Un pont": {"pos":"n.m. 阳性名词，复数 ponts","s":"桥。另一个常用意思：faire le pont，指在两个假日之间多休一天，凑成长假。船上的 pont 是甲板。","ipa":"[pɔ̃]","ph":"on 读鼻化元音 [ɔ̃]；结尾 t 不发音。","pi":"t 不发音，读 [pɔ̃]，不要读成 [pɔnt]；on 是鼻化音，别发出 n。","et":"来自拉丁语 pons, pontis（桥）。同族：ponton（浮桥）。","ex":[["Nous traversons le pont.","我们过桥。"],["Lundi est férié, on fait le pont.","星期一是假日，我们连休。"]],"co":[["traverser le pont","过桥"],["faire le pont","（放假）搭桥休假"],["un pont suspendu","吊桥"],["sous le pont","桥下"]],"sy":[["passerelle","courant","人行天桥，小桥"],["viaduc","courant","高架桥"]],"fq":"极高频，日常常用。","me":"pont 的 t 沉默：像桥下的水悄悄流过。","tr":{"zh":"过了桥就是火车站。","fr":"La gare est juste après le pont.","alt":"Une fois le pont traversé, on voit la gare.","note":"juste 加在介词前，强调「紧挨着」。"}},
 "Un port": {"pos":"n.m. 阳性名词，复数 ports","s":"港口；码头。un port de pêche 是渔港，un port de plaisance 是游艇码头。也指电脑接口：un port USB。","ipa":"[pɔʁ]","ph":"o 读 [ɔ]；r 小舌音；结尾 t 不发音。","pi":"port 的 t 不发音，读 [pɔʁ]；别把 port 和 porte（门）混：porte 读 [pɔʁt]，t 要发。","et":"来自拉丁语 portus（港口，入口）。同族：porte（门）、passeport。","ex":[["Les bateaux sont dans le port.","船在港口里。"],["Marseille est un grand port.","马赛是一个大港。"]],"co":[["un port de pêche","渔港"],["un port de plaisance","游艇港"],["arriver à bon port","平安到达"],["un port USB","USB 接口"]],"sy":[["quai","courant","码头边的岸壁，站台"],["havre","littéraire","避风港"]],"fq":"高频，海边和旅行里常见。","me":"port 的 t 不读；porte 的 t 才读。","tr":{"zh":"渔船早上回到港口。","fr":"Les bateaux de pêche rentrent au port le matin.","alt":"Le matin, les pêcheurs reviennent au port.","note":"rentrer au port：回港；au = à + le。"}},
 "Un quiz": {"pos":"n.m. 阳性名词，单复数同形 quiz","s":"知识问答；小测验。电视节目、课堂游戏和手机应用里都常见。比 examen（考试）轻松，常带游戏性质。","ipa":"[kwiz]","ph":"qu 读 [kw]；i 读 [i]；z 要发音，读 [z]。","pi":"qu 在这里读 [kw]，不是 [k]；z 要读出来；词尾不加 -s 也读 [z]。","et":"借自英语 quiz。英语里的 quiz 来源不确定。","ex":[["Nous avons fait un quiz ce matin.","我们今早做了一个小测验。"],["J'adore les quiz à la télé.","我爱看电视上的问答节目。"]],"co":[["faire un quiz","做一个测验"],["un quiz de culture générale","常识问答"],["un quiz en ligne","在线测验"]],"sy":[["jeu-questionnaire","courant","问答游戏，官方说法"],["test","courant","测验，更正式一点"],["questionnaire","courant","问卷"]],"fq":"中频，娱乐和教学中常用。","me":"quiz 来自英语，读 [kwiz]：像「夸兹」。","tr":{"zh":"晚上我们在酒吧做一个小问答。","fr":"Ce soir, nous faisons un quiz au bar.","alt":"Ce soir, on fait un quiz au bar.","note":"faire un quiz：做 / 玩问答。"}},
 "Un récit": {"pos":"n.m. 阳性名词，复数 récits","s":"叙述；故事；记述。指把事情讲出来的文字或口述，比如游记 un récit de voyage。比 histoire（故事）更强调「讲述」本身。","ipa":"[ʁe.si]","ph":"r 小舌音；é [e]；c 在 i 前读 [s]；结尾 t 不发音。","pi":"t 不发音，读 [ʁe.si]；c 读 [s]；récit 和 réciter（背诵）同族，别把 récit 读成 [ʁe.sit]。","et":"来自动词 réciter（背诵，叙述），源自拉丁语 recitare。","ex":[["C'est un récit de voyage intéressant.","这是一篇有趣的游记。"],["Il fait le récit de sa journée.","他讲述了自己的一天。"]],"co":[["un récit de voyage","游记"],["faire le récit de","讲述……"],["un récit de vie","人生叙述，自传体讲述"],["un récit court","短篇叙事"]],"sy":[["histoire","courant","故事，经过"],["conte","courant","童话，民间故事"],["narration","soutenu","叙述（文学术语）"]],"fq":"中频，书面语和写作里常见。","me":"récit 来自 réciter：把经过「背」出来讲。","tr":{"zh":"我正在读一篇关于非洲的游记。","fr":"Je lis un récit de voyage sur l'Afrique.","alt":"Je suis en train de lire un récit de voyage en Afrique.","note":"sur 加主题，表示「关于」。"}},
 "Un rêve d'enfant": {"pos":"n.m. 阳性名词，复数 rêves d'enfant（enfant 不变）","s":"儿时的梦想；童年的心愿。rêve 是梦或梦想，d'enfant 说明是孩提时就有的愿望。也可以说 un rêve de gosse（口语）。","ipa":"[ʁɛv dɑ̃.fɑ̃]","ph":"rêve [ʁɛv]，ê 读 [ɛ]，v 发音；d'enfant 缩读，d' 与 enfant 连成 [dɑ̃.fɑ̃]，两个 an 都读 [ɑ̃]。","pi":"rêve 里的 ê 读 [ɛ]，不是 [e]；enfant 两个 an 都是鼻化音，t 不发音；d'enfant 要省音。","et":"rêve 的来源不确定（古法语 resver）；enfant 来自拉丁语 infans（还不会说话的）。","ex":[["Mon rêve d'enfant, c'était de devenir pompier.","我儿时的梦想是当消防员。"],["Voir la mer, c'est un rêve d'enfant.","看到大海是我儿时的梦想。"]],"co":[["réaliser un rêve d'enfant","实现儿时的梦想"],["faire un rêve","做一个梦"],["un rêve devenu réalité","成真的梦想"]],"sy":[["rêve de gosse","familier","孩提时的梦想（口语）"],["souhait","courant","愿望"]],"fq":"中频，聊天和叙述中常用。","me":"rêve + enfant：小时候做的大梦。","tr":{"zh":"去日本是我儿时的梦想。","fr":"Aller au Japon, c'est un rêve d'enfant.","alt":"Partir au Japon, c'était mon rêve d'enfant.","note":"名词 + d' + 名词，说明类型，不用冠词。"}},
 "Un road trip": {"pos":"n.m. 阳性名词，复数 road trips","s":"公路旅行；自驾游。借自英语，指开车一路玩一路逛，不定点停留。法语里也可说 un voyage en voiture。常用动词：faire un road trip。","ipa":"[ʁod.tʁip]","ph":"road 按法语读 [ʁod]；trip 读 [tʁip]，p 要发音。","pi":"road 的 oa 不读英语的 [oʊ]，法语里读 [o]；r 是小舌音；trip 的 p 要读出来。","et":"借自英语 road trip（road 道路 + trip 旅行）。","ex":[["Nous allons faire un road trip aux États-Unis.","我们要去美国公路旅行。"],["Un road trip en Corse, c'est génial.","科西嘉岛的自驾游太棒了。"]],"co":[["faire un road trip","做一次公路旅行"],["partir en road trip","出发去自驾游"],["un road trip entre amis","朋友间的公路旅行"]],"sy":[["voyage en voiture","courant","开车旅行（法语说法）"],["périple","soutenu","长途旅行，曲折行程"]],"fq":"中频，年轻人常说。","me":"road（路）+ trip（旅程）：一路开一路玩。","tr":{"zh":"今年夏天我们要开车去西班牙。","fr":"Cet été, nous faisons un road trip en Espagne.","alt":"Cet été, on part en road trip en Espagne.","note":"国家名阴性前用 en：en Espagne。"}},
 "Un voyage": {"pos":"n.m. 阳性名词，复数 voyages","s":"旅行；行程。指一次具体的出行，常用 faire un voyage（去旅行）。bon voyage ! 是「一路平安，旅途愉快」。","ipa":"[vwa.jaʒ]","ph":"voy- 读 [vwa]，接着是 [j]，整词分成 vwa.jaʒ；g 读 [ʒ]。","pi":"voyage 不是 [vo.ja.ge]；g 在 a 前、e 前都读 [ʒ]（英语 beige 的音）；结尾 e 不发音。","et":"来自晚期拉丁语 viaticum（旅途用品），源自 via（路）。同族：voyager、voyageur。","ex":[["Mon voyage en Italie était super.","我的意大利之旅很棒。"],["Bon voyage !","旅途愉快！"]],"co":[["faire un voyage","去旅行"],["un voyage d'affaires","出差"],["un voyage organisé","跟团游"],["partir en voyage","出发旅行"]],"sy":[["trajet","courant","路程，一段行程（比 voyage 短）"],["séjour","courant","逗留，停留"],["déplacement","courant","出行，公务出行"]],"fq":"极高频，日常常用。","me":"voyage 源自 via（路）：走路的事。","tr":{"zh":"你上次旅行去了哪里？","fr":"Où es-tu allé lors de ton dernier voyage ?","alt":"Tu es allé où, pour ton dernier voyage ?","note":"aller 的复合过去时用 être，所以是 es-tu allé。"}},
 "Un zoo": {"pos":"n.m. 阳性名词，复数 zoos","s":"动物园。口语常用。正式全称是 jardin zoologique。法国有名的 zoo 包括 Beauval、Vincennes 等。","ipa":"[zo.o]","ph":"z 读 [z]；两个 o 分开读：zo-o，也可读成 [zo]。","pi":"zoo 的 z 读 [z]，两个 o 各自发音，不要读成 [zu]；复数加 s，不发音。","et":"来自 jardin zoologique 的缩略；zoo- 来自希腊语 zôion（动物）。","ex":[["Les enfants aiment le zoo.","孩子们喜欢动物园。"],["Nous allons au zoo dimanche.","我们周日去动物园。"]],"co":[["aller au zoo","去动物园"],["visiter un zoo","参观动物园"],["un parc zoologique","动物公园（正式说法）"]],"sy":[["parc animalier","courant","野生动物公园"],["ménagerie","soutenu","（旧）动物展览，兽栏"]],"fq":"中频，亲子话题里常见。","me":"zoo 里的两个 o，像两只圆圆的眼睛。","tr":{"zh":"周日我们带孩子去动物园。","fr":"Dimanche, nous emmenons les enfants au zoo.","alt":"Dimanche, on emmène les enfants au zoo.","note":"emmener 指带人去某处；au = à + le。"}},
 "De l'escalade": {"pos":"n.f. 阴性名词，常用部分冠词 de l'，复数 escalades","s":"攀岩；攀登。faire de l'escalade 是常见说法。escalade 也表示冲突的「升级」：l'escalade de la violence。","ipa":"[ɛs.ka.lad]","ph":"es 读 [ɛs]；-ca- 读 [ka]；-lade 读 [lad]，结尾 e 不发音。","pi":"escalade 开头 es- 读 [ɛs]；整词阴性；英语 escalade 少用，别混用法。","et":"来自意大利语 scalata（攀登），源自拉丁语 scala（梯子）。","ex":[["J'aime faire de l'escalade.","我喜欢攀岩。"],["Il y a un mur d'escalade dans ce gymnase.","这个体育馆里有一面攀岩墙。"]],"co":[["faire de l'escalade","攀岩"],["un mur d'escalade","攀岩墙"],["l'escalade de la violence","暴力升级"]],"sy":[["alpinisme","courant","登山运动"],["varappe","courant","岩壁攀登（较老）"],["grimpe","familier","攀岩（口语简称）"]],"fq":"中频，运动话题里常见。","me":"escalade → escalator：一层一层往上爬。","tr":{"zh":"周末我们去攀岩。","fr":"Ce week-end, nous faisons de l'escalade.","alt":"Ce week-end, on va grimper.","note":"faire de + 运动名词：从事某项运动。"}},
 "De la canne à sucre": {"pos":"n.f. 阴性名词，复数 cannes à sucre","s":"甘蔗。是热带地区（安的列斯、留尼汪）的重要作物，用来做糖和朗姆酒（rhum）。une canne 本身是「手杖；藤茎」。","ipa":"[kan a sykʁ]","ph":"canne [kan]；à 单独读 [a]；sucre [sykʁ]，u 读 [y]，结尾 e 不发音。","pi":"sucre 的 u 读 [y]，不是 [u]；canne 的 nn 只读一个 [n]；sucre 是阳性，canne 是阴性。","et":"canne 来自拉丁语 canna（芦苇）；sucre 经意大利语，从阿拉伯语 sukkar 而来。","ex":[["Ils cultivent de la canne à sucre.","他们种甘蔗。"],["Le rhum est fait avec de la canne à sucre.","朗姆酒用甘蔗制成。"]],"co":[["le sucre de canne","蔗糖"],["le jus de canne","甘蔗汁"],["une plantation de canne à sucre","甘蔗种植园"]],"sy":[["betterave sucrière","courant","糖用甜菜，另一种制糖原料"]],"fq":"中低频，热带和食物话题中出现。","me":"canne（杆）+ sucre（糖）：一根会出糖的杆。","tr":{"zh":"他们在岛上种甘蔗。","fr":"Ils cultivent de la canne à sucre sur l'île.","alt":"Ils font pousser de la canne à sucre sur l'île.","note":"不可数名词用部分冠词 de la。"}},
 "De la grenade": {"pos":"n.f. 阴性名词，复数 grenades","s":"石榴。作水果时说 une grenade（一个石榴），不可数时说 de la grenade。同一个词也指「手榴弹」，因为形状像石榴。le jus de grenade 是石榴汁，la grenadine 是石榴糖浆。","ipa":"[ɡʁə.nad]","ph":"gr 读 [ɡʁ]；e 轻读 [ə]；-nade 读 [nad]，结尾 e 不发音。","pi":"gre- 的 e 常轻读或几乎不发；注意 grenade 同时是水果和手榴弹，要看语境。","et":"来自拉丁语 (pomum) granatum「多籽的苹果」。手榴弹因形状像石榴得名。西班牙城市 Granada 同源。","ex":[["J'aime le jus de grenade.","我喜欢石榴汁。"],["Il a lancé une grenade.","他扔出了一枚手榴弹。"]],"co":[["un jus de grenade","石榴汁"],["une grenade dégoupillée","拔掉保险销的手榴弹"],["le sirop de grenadine","石榴糖浆"]],"sy":[["fruit rouge","courant","红色水果，范围更广"],["grenadine","courant","石榴糖浆（饮料）"]],"fq":"中低频，食物和新闻里常见。","me":"grenade 里有很多粒（grain）：满是籽的水果。","tr":{"zh":"我早上喝了一杯石榴汁。","fr":"J'ai bu un verre de jus de grenade ce matin.","alt":"Ce matin, j'ai pris un jus de grenade.","note":"boire 的过去分词是 bu。"}},
 "De la plongée (sous marine)": {"pos":"n.f. 阴性名词，复数 plongées","s":"潜水（运动）。faire de la plongée 指潜水；加 sous-marine 说明是水下潜水，用氧气瓶则说 plongée avec bouteille。plongée 也指电影或摄影里的「俯拍」。","ipa":"[plɔ̃.ʒe]","ph":"pl 连读 [pl]；on 读鼻化 [ɔ̃]；g 在 e 前读 [ʒ]；ée 读 [e]。","pi":"on 是鼻化音，不发 n；g 读 [ʒ]；结尾 -ée 读 [e]，不是 [i]。","et":"来自动词 plonger；plonger 来自通俗拉丁语 plumbicare，源自 plumbum（铅，沉下去）。","ex":[["Elle fait de la plongée en vacances.","她度假时去潜水。"],["La plongée sous-marine est un sport populaire.","潜水是一项受欢迎的运动。"]],"co":[["faire de la plongée","去潜水"],["la plongée sous-marine","水下潜水"],["un club de plongée","潜水俱乐部"],["une bouteille de plongée","潜水氧气瓶"]],"sy":[["snorkeling","courant","浮潜，不带氧气瓶"],["apnée","courant","屏气潜水（自由潜水）"]],"fq":"中频，度假和运动话题里常见。","me":"plonger → plomb（铅）：像铅一样沉下去。","tr":{"zh":"去年夏天我第一次潜水。","fr":"L'été dernier, j'ai fait de la plongée pour la première fois.","alt":"L'été dernier, j'ai plongé pour la première fois.","note":"pour la première fois = 第一次。"}},
 "De la voile": {"pos":"n.f. 阴性名词，复数 voiles；注意：le voile（阳性）是面纱","s":"帆船运动；帆。faire de la voile 是玩帆船。une voile 是一张帆：hisser la voile（升帆）。le voile（阳性）是面纱、头巾，意思完全不同。","ipa":"[vwal]","ph":"oi 读 [wa]；-le 的 l 要读出来，e 不发音，整词一个音节 [vwal]。","pi":"la voile（帆）和 le voile（面纱）读音相同，只靠冠词区分；别忘了 l 要发音。","et":"来自拉丁语 vela（velum 的复数），后来变成阴性单数。le voile（面纱）则来自 velum。","ex":[["Il fait de la voile le week-end.","他周末玩帆船。"],["Le bateau a une grande voile blanche.","这艘船有一张白色大帆。"]],"co":[["faire de la voile","玩帆船"],["un bateau à voile","帆船"],["hisser la voile","升帆"],["le voile","面纱（阳性，另一个词）"]],"sy":[["navigation","courant","航行"],["planche à voile","courant","帆板"]],"fq":"中频，运动和海边话题里常见。","me":"la voile 是帆，le voile 是面纱：看冠词。","tr":{"zh":"夏天他们在布列塔尼玩帆船。","fr":"En été, ils font de la voile en Bretagne.","alt":"L'été, ils font de la voile en Bretagne.","note":"地区名 la Bretagne 前用 en：en Bretagne。"}},
 "La région Île-de-France": {"pos":"n.f. 阴性名词（la région），Île-de-France 为专有名称","s":"法兰西岛大区。是以巴黎为中心的行政大区，包括巴黎和周围八个省，人口最多。名称里 Île 开头的 Î 要大写，且常说 en Île-de-France（在法兰西岛大区）。","ipa":"[ʁe.ʒjɔ̃ il.də.fʁɑ̃s]","ph":"région [ʁe.ʒjɔ̃]；Île [il]，î 读 [i]；de 轻读；France [fʁɑ̃s]。","pi":"Île 的 î 读 [i]，和 île（岛）同音；France 的 an 读 [ɑ̃]，c 读 [s]。","et":"région 来自拉丁语 regio（区域）；Île-de-France 字面「法兰西之岛」，指被河流围绕的核心地带。","ex":[["Paris est dans la région Île-de-France.","巴黎在法兰西岛大区。"],["J'habite en Île-de-France.","我住在法兰西岛大区。"]],"co":[["en Île-de-France","在法兰西岛大区"],["la région parisienne","巴黎地区"],["les transports en Île-de-France","法兰西岛的交通"]],"sy":[["région parisienne","courant","巴黎地区，说法更口语"],["banlieue","courant","郊区"]],"fq":"专有名词，新闻和生活里常见。","me":"Île + de + France：以巴黎为中心的「岛」。","tr":{"zh":"我在法兰西岛大区工作。","fr":"Je travaille en Île-de-France.","alt":"Je bosse en Île-de-France.","note":"大区名前用 en，不加冠词。"}},
 "La Seine": {"pos":"n.f. 阴性专有名词（la Seine）","s":"塞纳河，穿过巴黎的大河，从勃艮第流到英吉利海峡，是 fleuve（直接入海的大河）。沿岸有埃菲尔铁塔、卢浮宫、圣母院。","ipa":"[sɛn]","ph":"S 读 [s]；ei 读 [ɛ]；n 要发出来；结尾 e 不发音。","pi":"Seine 读 [sɛn]，ei 不是 [ei]，也不是 [ai]；不要写成 Scène（场景，也读 [sɛn]）。","et":"来自古拉丁语 Sequana，是高卢的河神与河名。","ex":[["La Seine traverse Paris.","塞纳河穿过巴黎。"],["On se promène le long de la Seine.","我们沿着塞纳河散步。"]],"co":[["les bords de Seine","塞纳河畔"],["une promenade sur la Seine","塞纳河上的游船"],["la rive gauche / droite","左岸 / 右岸"]],"sy":[["Loire","courant","卢瓦尔河，法国最长的河"],["Rhône","courant","罗讷河"]],"fq":"专有名词，法国话题中极常见。","me":"Seine 读成 scène：河边也是一幕风景。","tr":{"zh":"塞纳河穿过巴黎市中心。","fr":"La Seine traverse le centre de Paris.","alt":"La Seine passe au milieu de Paris.","note":"河流名前加 la；traverser 是及物动词。"}},
 "Une agence de voyage": {"pos":"n.f. 阴性名词，复数 agences de voyage(s)","s":"旅行社。你可以在这里订机票、酒店和线路。也说 une agence de voyages，复数 s 可有可无。网上订票则是 une agence en ligne。","ipa":"[a.ʒɑ̃s də vwa.jaʒ]","ph":"agence 读 [a.ʒɑ̃s]，g 在 e 前读 [ʒ]，c 读 [s]；de 轻读；voyage [vwa.jaʒ]。","pi":"agence 的 an 是鼻化音 [ɑ̃]；g 读 [ʒ]；注意是阴性：une agence。","et":"agence 经意大利语 agenzia，来自拉丁语 agens（行动者），与 agir（行动）同族。","ex":[["J'ai réservé avec une agence de voyage.","我通过旅行社预订。"],["L'agence de voyage est fermée le dimanche.","旅行社周日不营业。"]],"co":[["réserver dans une agence de voyage","在旅行社预订"],["une agence en ligne","网络旅行社"],["un agent de voyage","旅行社职员"]],"sy":[["voyagiste","courant","旅游运营商，组织旅游的公司"],["tour-opérateur","courant","旅游经营商"]],"fq":"中频，旅行话题里常用。","me":"agence ← agir：替你办事的地方。","tr":{"zh":"我们想在旅行社订一次旅行。","fr":"Nous voulons réserver un voyage dans une agence de voyage.","alt":"On veut réserver un voyage en agence.","note":"vouloir + 不定式：想要做某事。"}},
 "Une anecdote": {"pos":"n.f. 阴性名词，复数 anecdotes","s":"轶事；趣闻。一个短小、有意思的小故事，常用来活跃气氛。常说 raconter une anecdote。","ipa":"[a.nɛk.dɔt]","ph":"a [a]；ne 读 [nɛk]，c 读 [k]；-dote 读 [dɔt]，t 要发音，结尾 e 不发音。","pi":"anecdote 的 c 读 [k]，t 要发音；不要写成 anectode。","et":"来自希腊语 anekdota（未出版的东西），指没有正式发表的小故事。英语 anecdote 同源。","ex":[["Il a raconté une anecdote amusante.","他讲了一个有趣的轶事。"],["J'ai une anecdote sur ce village.","关于这个村子我有个小故事。"]],"co":[["raconter une anecdote","讲一个轶事"],["une anecdote amusante","有趣的轶事"],["une petite anecdote","一个小插曲"]],"sy":[["histoire","courant","故事"],["blague","familier","笑话"],["souvenir","courant","回忆，往事"]],"fq":"中频，聊天和叙述里常见。","me":"anecdote ≈ anecdote：拼写和英语几乎一样。","tr":{"zh":"他总是讲有趣的小故事。","fr":"Il raconte toujours des anecdotes amusantes.","alt":"Il a toujours une petite anecdote à raconter.","note":"toujours 放在动词后面。"}},
 "Une aventure": {"pos":"n.f. 阴性名词，复数 aventures","s":"冒险；奇遇。指刺激、不寻常的经历。也可指一段短暂的感情：une aventure amoureuse。partir à l'aventure = 毫无计划地出发。","ipa":"[a.vɑ̃.tyʁ]","ph":"a [a]；ven 读 [vɑ̃]；tu 读 [ty]，u 读 [y]；r 小舌音；结尾 e 不发音。","pi":"aven 的 en 读 [ɑ̃]，不是 [ɛn]；tu 的 u 读 [y]，不是 [u]；英语 adventure 多一个 d，法语没有。","et":"来自拉丁语 adventura（将要发生的事），由 advenire（到来）而来。英语 adventure 同源。","ex":[["C'est une grande aventure !","这是一次大冒险！"],["Ils partent à l'aventure.","他们没有计划就出发了。"]],"co":[["partir à l'aventure","出发冒险"],["vivre une aventure","经历一次冒险"],["un film d'aventure","冒险片"],["une aventure extraordinaire","非凡的历险"]],"sy":[["expédition","courant","探险远征"],["péripétie","soutenu","意外波折"],["épopée","littéraire","史诗般的经历"]],"fq":"中高频，日常和叙述里常用。","me":"a-ven-ture：英语 adventure 去掉 d。","tr":{"zh":"这趟旅行是一次大冒险。","fr":"Ce voyage est une grande aventure.","alt":"Ce voyage, c'est toute une aventure.","note":"grande 放在名词前：une grande aventure。"}},
 "Une bêtise": {"pos":"n.f. 阴性名词，复数 bêtises","s":"蠢事；傻话；孩子的小淘气。faire une bêtise 指犯傻、闯小祸，常用于孩子。dire des bêtises 是说傻话。语气比 erreur（错误）轻，比 stupidité 更日常。","ipa":"[bɛ.tiz]","ph":"ê 读 [ɛ]；-ti- 读 [ti]；-se 读 [z]，s 在元音间读 [z]。","pi":"bêtise 的 s 读 [z]，不是 [s]；ê 读 [ɛ]；不是「蠢人」，蠢人是 un idiot / une idiote。","et":"由 bête（笨的；动物）加后缀 -ise 构成，表示笨的行为；bête 来自拉丁语 bestia（野兽）。","ex":[["L'enfant a fait une bêtise.","孩子干了件蠢事。"],["Arrête de dire des bêtises !","别说傻话了！"]],"co":[["faire une bêtise","做蠢事，闯小祸"],["dire des bêtises","说傻话"],["faire des bêtises","捣蛋，调皮"],["quelle bêtise !","真蠢！"]],"sy":[["erreur","courant","错误"],["sottise","soutenu","蠢话，蠢事"],["connerie","argot","蠢事（粗俗）"]],"fq":"高频，日常常用。","me":"bête + -ise：做了「bête」的事。","tr":{"zh":"我儿子又闯祸了。","fr":"Mon fils a encore fait une bêtise.","alt":"Mon fils a fait une nouvelle bêtise.","note":"encore 放在 a 与过去分词之间。"}},
 "Une boîte aux lettres": {"pos":"n.f. 阴性名词，复数 boîtes aux lettres","s":"信箱；邮筒。家门口收信的信箱和街上的邮筒都用这个词。也可以简称 une boîte。电子邮箱说 une boîte mail。","ipa":"[bwat o lɛtʁ]","ph":"boîte 读 [bwat]；aux 读 [o]；lettres 读 [lɛtʁ]，结尾 -es 不发音。","pi":"boîte 的 î 读 [wa]，t 要发音；aux 读 [o]；lettres 的 tt 读一个 [t]。","et":"boîte 来自晚期拉丁语 buxida（盒子）；lettre 来自拉丁语 littera（字母）。","ex":[["Il y a une boîte aux lettres au coin de la rue.","街角有一个邮筒。"],["J'ai vérifié ma boîte aux lettres ce matin.","我今早查看了信箱。"]],"co":[["mettre une lettre dans la boîte aux lettres","把信投进信箱"],["relever sa boîte aux lettres","取信"],["une boîte mail","电子邮箱"]],"sy":[["boîte à lettres","courant","信箱（较少用的变体）"],["courrier","courant","信件，邮件"]],"fq":"中频，生活里常用。","me":"boîte（盒）+ aux lettres（装信）：装信的盒。","tr":{"zh":"我在信箱里找到了一封信。","fr":"J'ai trouvé une lettre dans la boîte aux lettres.","alt":"Il y avait une lettre dans ma boîte aux lettres.","note":"dans + 地点，表示在里面。"}},
 "Une bonne nuit de sommeil": {"pos":"n.f. 阴性名词词组，复数 de bonnes nuits de sommeil","s":"睡个好觉；一晚好眠。nuit 是整夜，sommeil 是睡眠，合起来强调睡得足、睡得好。常说 avoir besoin d'une bonne nuit de sommeil。","ipa":"[bɔn nɥi də sɔ.mɛj]","ph":"bonne [bɔn]；nuit [nɥi]，u 圆唇 [ɥ]；sommeil [sɔ.mɛj]，-eil 读 [ɛj]。","pi":"bonne 要读出 n；nuit 的 t 不发音；sommeil 的 -eil 读 [ɛj]，不是 [ɛl]。","et":"nuit 来自拉丁语 nox, noctis；sommeil 与拉丁语 somnus（睡眠）同族。","ex":[["J'ai besoin d'une bonne nuit de sommeil.","我需要一晚好觉。"],["Après une bonne nuit de sommeil, ça va mieux.","睡个好觉后感觉好多了。"]],"co":[["une bonne nuit de sommeil","一夜好眠"],["avoir sommeil","犯困"],["manquer de sommeil","缺觉"],["bonne nuit !","晚安！"]],"sy":[["repos","courant","休息"],["dodo","familier","睡觉（儿语、口语）"]],"fq":"中频，健康和日常话题里常见。","me":"好夜晚 + 睡眠：睡饱了精神好。","tr":{"zh":"明天有考试，你需要睡个好觉。","fr":"Demain, tu as un examen, tu as besoin d'une bonne nuit de sommeil.","alt":"Tu as un examen demain, dors bien cette nuit.","note":"avoir besoin de + 名词。"}},
 "Une brochure": {"pos":"n.f. 阴性名词，复数 brochures","s":"宣传册；小册子。酒店、景点和旅行社发放的彩色介绍册，一般是几页装订的薄册。也可指简短的说明册。","ipa":"[bʁɔ.ʃyʁ]","ph":"br [bʁ]；o 读 [ɔ]；ch 读 [ʃ]；u 读 [y]；结尾 e 不发音。","pi":"ch 读 [ʃ]，不是 [k]；u 读 [y]；英语 brochure 重音在前，法语重音在后。","et":"来自动词 brocher（装订、缝合），再往前与 broche（针、扦子）有关。","ex":[["J'ai pris une brochure à l'hôtel.","我在酒店拿了一本宣传册。"],["La brochure est en français et en anglais.","这本宣传册有法语和英语版。"]],"co":[["une brochure touristique","旅游宣传册"],["prendre une brochure","拿一本宣传册"],["une brochure gratuite","免费宣传册"]],"sy":[["dépliant","courant","折页宣传单"],["prospectus","courant","传单，广告单"],["catalogue","courant","商品目录"]],"fq":"中频，旅游和购物时常见。","me":"brochure 与 broché（平装）同族：把页缝在一起。","tr":{"zh":"我想要一份关于这座城市的宣传册。","fr":"Je voudrais une brochure sur cette ville.","alt":"Vous avez une brochure sur la ville ?","note":"sur 加话题：关于……"}},
 "Une carte postale": {"pos":"n.f. 阴性名词，复数 cartes postales（形容词 postale 也要加 s）","s":"明信片。旅行时寄给亲友的小卡片，常说 envoyer une carte postale。carte 另有「地图；菜单；卡」的意思，要看语境。","ipa":"[kaʁt pɔs.tal]","ph":"carte [kaʁt]，t 要发音；postale 读 [pɔs.tal]，s 读 [s]，结尾 e 不发音。","pi":"carte 的 t 要发音（不同于 port）；postale 的 -ale 读 [al]；复数两个词都加 s。","et":"carte 来自拉丁语 charta（纸）；postale 来自 poste，poste 源自意大利语 posta。","ex":[["J'ai envoyé une carte postale à ma mère.","我给妈妈寄了一张明信片。"],["Il achète des cartes postales de Paris.","他买了巴黎的明信片。"]],"co":[["envoyer une carte postale","寄明信片"],["recevoir une carte postale","收到明信片"],["écrire une carte postale","写明信片"]],"sy":[["carte","courant","卡片，也指明信片（简称）"],["lettre","courant","信"]],"fq":"中频，旅行话题里常用。","me":"carte（卡片）+ postale（邮寄的）：邮寄的卡片。","tr":{"zh":"我会从罗马给你寄明信片。","fr":"Je vais t'envoyer une carte postale de Rome.","alt":"Je t'enverrai une carte postale depuis Rome.","note":"aller + 不定式表示近将来；t' 是 te 的省音，作间接宾语。"}},
 "Une chambre d'hôte": {"pos":"n.f. 阴性名词，复数 chambres d'hôtes","s":"民宿；住在主人家里的客房。一般由个人提供房间和早餐，比酒店亲切。常用复数 chambres d'hôtes，单数也说得通。hôte 既指「主人」也指「客人」。","ipa":"[ʃɑ̃bʁ dot]","ph":"chambre 读 [ʃɑ̃bʁ]，ch 读 [ʃ]，-am- 读 [ɑ̃]，e 不发音；d'hôte 读 [dot]，h 不发音，ô 读 [o]。","pi":"chambre 里的 am 读鼻化音 [ɑ̃]；hôte 的 h 不发音，ô 读 [o]；d'hôte 要省音。","et":"chambre 来自拉丁语 camera（房间）；hôte 来自拉丁语 hospes（主人，客人）。","ex":[["Nous dormons dans une chambre d'hôte.","我们住在民宿。"],["Cette chambre d'hôte propose un petit-déjeuner maison.","这家民宿提供自制早餐。"]],"co":[["réserver une chambre d'hôte","订民宿"],["tenir une chambre d'hôtes","经营民宿"],["petit-déjeuner compris","含早餐"]],"sy":[["gîte","courant","乡村度假屋"],["hôtel","courant","酒店"],["auberge","courant","客栈"]],"fq":"中频，旅行话题里常见。","me":"chambre（房间）+ hôte（主人）：住在主人家的房间。","tr":{"zh":"我们订了一间民宿住两晚。","fr":"Nous avons réservé une chambre d'hôte pour deux nuits.","alt":"On a réservé une chambre d'hôtes pour deux nuits.","note":"pour + 时间段，表示预计停留多久。"}},
 "Une demi-pension": {"pos":"n.f. 阴性名词，复数 demi-pensions","s":"半食宿：酒店房费包含早餐和一顿正餐（午餐或晚餐）。常说 en demi-pension。也指学校里「半寄宿」，学生中午在校用餐。","ipa":"[də.mi.pɑ̃.sjɔ̃]","ph":"demi 读 [də.mi]；pension 读 [pɑ̃.sjɔ̃]，pen 读 [pɑ̃]，-sion 读 [sjɔ̃]。","pi":"pension 的 en 读 [ɑ̃]，-sion 读 [sjɔ̃]，不是英语的 [ʃən]；demi 做前缀时不变化。","et":"由 demi（一半）和 pension 构成；pension 来自拉丁语 pensio（付款，支付）。","ex":[["L'hôtel propose la demi-pension.","酒店提供半膳食宿。"],["Nous sommes en demi-pension.","我们订的是半膳食宿。"]],"co":[["en demi-pension","订半食宿"],["prendre la demi-pension","选半食宿"],["un tarif demi-pension","半食宿价格"]],"sy":[["pension complète","courant","全食宿（三餐都含）"],["petit-déjeuner compris","courant","含早餐"]],"fq":"中频，酒店场景常见。","me":"demi（一半）+ pension：只包一半的饭。","tr":{"zh":"你们有半食宿的价格吗？","fr":"Vous avez un tarif en demi-pension ?","alt":"Est-ce que la demi-pension est possible ?","note":"en + 名词，表示以何种方式（订）。"}},
 "Une pension complète": {"pos":"n.f. 阴性名词词组，复数 pensions complètes","s":"全食宿：房费包含早、午、晚三餐。常说 en pension complète。pension 本身也有「养老金；寄宿处」的意思。","ipa":"[pɑ̃.sjɔ̃ kɔ̃.plɛt]","ph":"pension [pɑ̃.sjɔ̃]；complète 读 [kɔ̃.plɛt]，com 读 [kɔ̃]，è 读 [ɛ]，t 发音。","pi":"complète 的 -ète 读 [ɛt]，t 要发音；阳性 complet 的 t 不发；pension 是阴性，所以要用 complète。","et":"pension 来自拉丁语 pensio（支付）；complet 来自拉丁语 completus（完整的）。","ex":[["Nous avons réservé en pension complète.","我们订了全膳食宿。"],["La pension complète coûte plus cher.","全食宿更贵。"]],"co":[["en pension complète","订全食宿"],["réserver en pension complète","按全食宿预订"],["une chambre en pension complète","含三餐的房间"]],"sy":[["demi-pension","courant","半食宿（两餐）"],["tout compris","courant","全包"]],"fq":"中频，酒店场景常见。","me":"complète = 完整的：三餐都包了。","tr":{"zh":"我们想订全食宿的房间。","fr":"Nous voudrions une chambre en pension complète.","alt":"On cherche une chambre avec les trois repas compris.","note":"voudrions 是 vouloir 的条件式，更礼貌。"}},
 "Une rizière": {"pos":"n.f. 阴性名词，复数 rizières","s":"稻田。亚洲（越南、泰国、中国南方）常见的景观。riz 是「米；稻」，加 -ière 表示种植的地方。","ipa":"[ʁi.zjɛʁ]","ph":"r 小舌音；ri 读 [ʁi]；zi 读 [zj]；-ère 读 [ɛʁ]，结尾 e 不发音。","pi":"riz 的 z 不发音，但 rizière 里的 z 要读 [z]；-ière 读 [jɛʁ]，不是 [i.ɛʁ]。","et":"由 riz（稻米）加后缀 -ière（表示地点）构成。","ex":[["Les rizières sont magnifiques.","稻田非常美。"],["Nous marchons dans les rizières.","我们在稻田里走路。"]],"co":[["une rizière en terrasses","梯田式稻田"],["cultiver le riz dans une rizière","在稻田里种稻"],["les rizières du Vietnam","越南的稻田"]],"sy":[["champ de riz","courant","稻田（较口语）"],["rizière en terrasse","courant","梯田"]],"fq":"中低频，亚洲和旅行话题里出现。","me":"riz + ière：种米的地方。","tr":{"zh":"从山上可以看到绿色的稻田。","fr":"Depuis la montagne, on voit les rizières vertes.","alt":"De la montagne, on aperçoit des rizières toutes vertes.","note":"on 表示泛指的「人们 / 我们」。"}},
 "Une traduction": {"pos":"n.f. 阴性名词，复数 traductions","s":"翻译（结果或行为）。指把一种语言译成另一种语言，如 une traduction de l'anglais en français。译者是 un traducteur / une traductrice。","ipa":"[tʁa.dyk.sjɔ̃]","ph":"tr 读 [tʁ]；a [a]；-duc- 读 [dyk]，u 读 [y]；-tion 读 [sjɔ̃]。","pi":"-tion 读 [sjɔ̃]，不是 [ʃən]；u 读 [y]；不要写成 translation（英语）。","et":"来自拉丁语 traductio，由 traducere（引渡过去）而来：把意思「带过去」。","ex":[["La traduction est difficile.","翻译很难。"],["J'ai fait la traduction du texte.","我翻译了这篇文章。"]],"co":[["faire une traduction","做翻译"],["une traduction de l'anglais en français","从英语译成法语"],["une traduction littérale","直译"],["une traduction automatique","机器翻译"]],"sy":[["version","courant","译成母语的翻译练习"],["thème","courant","译成外语的翻译练习"],["interprétation","courant","口译"]],"fq":"中高频，学习和工作中常用。","me":"traduire（带过去）+ -tion：把意思带到另一种语言。","tr":{"zh":"这篇文章的翻译很好。","fr":"La traduction de ce texte est très bonne.","alt":"Ce texte est très bien traduit.","note":"traduction 阴性，所以用 bonne。"}},
 "Une usine": {"pos":"n.f. 阴性名词，复数 usines","s":"工厂。指生产产品的地方，如 une usine de voitures。口语 aller à l'usine = 去上班（在厂里）。比 entreprise（企业）更具体。","ipa":"[y.zin]","ph":"u 读 [y]；s 在元音间读 [z]；in 在这里读 [in]（不是鼻化音，因为后面有 e）。","pi":"u 读 [y]，嘴唇圆起来，不是 [u]；s 读 [z]；usine 的 in 读 [in]，不是鼻化 [ɛ̃]。","et":"来自拉丁语 officina（作坊），经过古法语演变而成。","ex":[["Il travaille dans une usine.","他在工厂工作。"],["L'usine fabrique des voitures.","这家工厂造汽车。"]],"co":[["travailler dans une usine","在工厂工作"],["une usine de voitures","汽车厂"],["un ouvrier d'usine","工厂工人"],["fermer une usine","关闭工厂"]],"sy":[["fabrique","courant","制造厂（规模较小）"],["atelier","courant","作坊，车间"],["manufacture","soutenu","手工工场"]],"fq":"中高频，工作话题里常见。","me":"usine 的 u 像 y，圆唇：嘴也像烟囱。","tr":{"zh":"我的叔叔在一家汽车工厂工作。","fr":"Mon oncle travaille dans une usine de voitures.","alt":"Mon oncle bosse dans une usine automobile.","note":"dans une usine：在工厂里（空间内）。"}},
 "Une visite guidée": {"pos":"n.f. 阴性名词，复数 visites guidées（guidée 也要加 s）","s":"导览参观；有导游带领的参观。常说 faire une visite guidée。guidée 是 guider（引导）的过去分词，作形容词，与 visite 一致，用阴性。","ipa":"[vi.zit ɡi.de]","ph":"visite 读 [vi.zit]，s 读 [z]，t 发音；guidée 读 [ɡi.de]，gu 读 [ɡ]，ée 读 [e]。","pi":"visite 的 s 读 [z]；guidée 的 u 不发音；阴性：visite guidée，不是 visite guidé。","et":"visite 来自动词 visiter，源自拉丁语 visitare；guidée 是 guider 的过去分词。","ex":[["Nous avons fait une visite guidée du musée.","我们参加了博物馆导览。"],["La visite guidée dure une heure.","导览参观持续一个小时。"]],"co":[["faire une visite guidée","参加导览参观"],["réserver une visite guidée","预订导览"],["une visite guidée en français","法语导览"],["rendre visite à quelqu'un","拜访某人（对比）"]],"sy":[["visite libre","courant","自由参观（反义）"],["tour","courant","游览一圈"]],"fq":"中频，旅游场景常见。","me":"visite（参观）+ guidée（被引导的）：有人带路。","tr":{"zh":"我们下午有一场导览参观。","fr":"Nous avons une visite guidée cet après-midi.","alt":"Cet après-midi, il y a une visite guidée.","note":"过去分词作形容词要与名词性数一致。"}},
 "Des chutes": {"pos":"n.pl. 复数名词（单数 une chute，阴性）","s":"瀑布（des chutes d'eau 的简称），尤其指大瀑布，如 les chutes du Niagara。单数 une chute 常指「跌倒；下降」，如 une chute de neige（降雪）。","ipa":"[ʃyt]","ph":"ch 读 [ʃ]；u 读 [y]；t 要发音；结尾 -es 不发音。","pi":"ch 读 [ʃ]，不是 [k]；u 读 [y]；chute 是阴性单数，复数 chutes 发音相同。","et":"来自古法语 cheoite，源自动词 choir（落下），拉丁语 cadere。","ex":[["Les chutes d'eau sont impressionnantes.","瀑布非常壮观。"],["Nous avons visité les chutes du Niagara.","我们参观了尼亚加拉瀑布。"]],"co":[["des chutes d'eau","瀑布"],["les chutes du Niagara","尼亚加拉瀑布"],["une chute de neige","降雪"],["une chute de prix","价格下跌"]],"sy":[["cascade","courant","较小的瀑布，也指连续的水流"],["cataracte","littéraire","大瀑布（文学）"]],"fq":"中频，旅游和地理话题常见。","me":"chute = 落下：水落下来就是瀑布。","tr":{"zh":"我们去看了美丽的瀑布。","fr":"Nous sommes allés voir de belles chutes d'eau.","alt":"On est allés voir les chutes d'eau.","note":"aller 的复合过去时用 être：nous sommes allés。"}},
 "Des embouteillages / Des bouchons": {"pos":"n.pl. 复数名词（单数 un embouteillage / un bouchon，阳性）","s":"堵车；交通拥堵。embouteillage 是标准词，bouchon 口语常用，字面是「瓶塞」，把路堵住就像瓶口塞住。也说 être dans les bouchons / dans les embouteillages。","ipa":"[ɑ̃.bu.tɛ.jaʒ] / [bu.ʃɔ̃]","ph":"embouteillage：em 读 [ɑ̃]，-teill- 读 [tɛj]，-age 读 [aʒ]；bouchon：ou [u]，ch [ʃ]，on [ɔ̃]。","pi":"embouteillage 里 em 读 [ɑ̃]；-eill- 读 [ɛj]；bouchon 的 ch 读 [ʃ]，不是 [k]；两词单数都是阳性。","et":"embouteillage 由 embouteiller（像把东西装进瓶子）而来，bouteille 来自晚期拉丁语 butticula；bouchon 与 bouche（塞住的东西）有关，来源不完全确定。","ex":[["Il y a beaucoup d'embouteillages ce matin.","今早很堵车。"],["On est coincés dans les bouchons.","我们被堵在车流里。"]],"co":[["être pris dans les embouteillages","被堵在路上"],["éviter les bouchons","避开堵车"],["des embouteillages sur le périphérique","环路上堵车"],["un bouchon de plusieurs kilomètres","几公里的堵车"]],"sy":[["circulation dense","courant","车流密集"],["trafic","courant","交通，车流"],["ralentissement","courant","交通缓行"]],"fq":"高频，日常、新闻都常用。","me":"bouchon = 瓶塞：路被塞住了。","tr":{"zh":"早上八点路上总是堵车。","fr":"À huit heures du matin, il y a toujours des embouteillages.","alt":"À huit heures, y a toujours des bouchons.","note":"il y a 后面接复数也不变化。"}},
 "Le petit palais / Le grand palais": {"pos":"n.m. 阳性名词（专有名称），复数 palais（单复数同形）","s":"巴黎的两座展览宫：le Petit Palais（小宫，现为巴黎市美术馆）和 le Grand Palais（大宫，大型展览馆）。两座都是为 1900 年世博会建的。palais 本身也泛指「宫殿」。","ipa":"[pə.ti.pa.lɛ] / [ɡʁɑ̃.pa.lɛ]","ph":"palais 里 ai [ɛ]；结尾 -s 不发音；grand 的 d 不发音，鼻化 [ɑ̃]。","pi":"palais 结尾的 s 不读；grand 后面接辅音，不连读。","et":"palais 来自拉丁语 Palatium（罗马的帕拉蒂尼山，皇宫所在地）。英语 palace 同源。","ex":[["Je visite le Grand Palais aujourd'hui.","我今天参观大宫。"],["Le Petit Palais est gratuit pour les collections permanentes.","小宫的常设展是免费的。"],["Ces deux palais sont près des Champs-Élysées.","这两座宫殿离香榭丽舍大街很近。"]],"co":[["visiter le Grand Palais","参观大宫"],["une exposition au Petit Palais","小宫里的一个展览"],["le palais de l'Élysée","爱丽舍宫（总统府）"]],"sy":[["château","courant","城堡；官邸"],["musée","courant","博物馆"]],"fq":"中频，旅游和文化话题常用。","me":"petit 小，grand 大；两个 palais 在巴黎面对面。","tr":{"zh":"我们明天去参观大宫。","fr":"Nous allons visiter le Grand Palais demain.","alt":"Demain, on va voir le Grand Palais.","note":"专有名称，Grand 和 Palais 都大写。"}},
 "Les Champs Élysées": {"pos":"n.m.pl. 阳性复数专有名词（常写作 les Champs-Élysées）","s":"香榭丽舍大街，巴黎最著名的大街，从协和广场通向凯旋门。说 sur les Champs-Élysées「在香榭丽舍大街上」，用 sur。","ipa":"[ʃɑ̃.ze.li.ze]","ph":"ch [ʃ]；Champs 的 p、s 不发音，但后面是元音 É，s 连读成 [z]；-ysées 读 [i.ze]。","pi":"Champs 里 p 不读，只读 [ʃɑ̃]；les 和 Champs 之间的 s 要连读成 [z]。","et":"名字来自希腊神话中的 Élysée（极乐世界，英雄死后居住的乐土）。字面意思「极乐田野」。champ 来自拉丁语 campus（田野）。","ex":[["Nous marchons sur les Champs Élysées.","我们走在香榭丽舍大街上。"],["Le défilé passe par les Champs-Élysées.","游行队伍经过香榭丽舍大街。"],["Il y a beaucoup de magasins sur cette avenue.","这条大街上有很多商店。"]],"co":[["sur les Champs-Élysées","在香榭丽舍大街上"],["remonter les Champs-Élysées","沿香榭丽舍大街往上走"],["l'avenue des Champs-Élysées","香榭丽舍大街"]],"sy":[["avenue","courant","大街（泛称）"],["boulevard","courant","林荫大道"]],"fq":"中频，旅游话题常见。","me":"Champs 是「田野」，Élysées 是「极乐世界」：天堂般的田野。","tr":{"zh":"我们昨天走在香榭丽舍大街上。","fr":"Hier, nous avons marché sur les Champs-Élysées.","alt":"Hier, on s'est promenés sur les Champs-Élysées.","note":"街道名前用 sur；marcher 用助动词 avoir。"}},
 "Les grands espaces": {"pos":"n.m.pl. 阳性复数名词词组（espace 是阳性，复数 espaces）","s":"广阔天地；辽阔的自然（草原、荒野、高山）。les grands espaces 让人想到宽广、安静、没有人群的自然环境，常用于旅行和电影。","ipa":"[ɡʁɑ̃.zɛs.pas]","ph":"grands 的 d、s 不发音；后面接元音 e-，s 连读成 [z]；espaces 读 [ɛs.pas]，ce 读 [s]。","pi":"grands espaces 要连读 [ɡʁɑ̃.zɛs.pas]；grand 的 d 不读。","et":"espace 来自拉丁语 spatium（空间、距离），加了前面的 e-。英语 space 同源。","ex":[["J'aime les grands espaces au Canada.","我喜欢加拿大的广袤天地。"],["Il rêve de grands espaces et de silence.","他向往辽阔的天地和安静。"],["On manque d'espace dans cette ville.","这座城市空间不够。"]],"co":[["rêver de grands espaces","向往广阔天地"],["les grands espaces américains","美国的广袤原野"],["manquer d'espace","空间不够"],["un espace vert","绿地、公园"]],"sy":[["nature","courant","大自然（更泛）"],["étendue","soutenu","一大片、辽阔"]],"fq":"中频，旅行、自然话题常用。","me":"grands = 大，espaces = 空间：大空间 = 大自然。","tr":{"zh":"我喜欢大自然和安静。","fr":"J'aime les grands espaces et le calme.","alt":"Moi, j'adore les grands espaces et le silence.","note":"les grands espaces 固定用复数。"}},
 "Les Invalides": {"pos":"n.m.pl. 阳性复数专有名词（l'hôtel des Invalides）","s":"荣军院，巴黎的一处古迹：十七世纪路易十四为伤残老兵建的，现在有军事博物馆和拿破仑的墓。名字总用复数、带 les。","ipa":"[ɛ̃.va.lid]","ph":"in- 读鼻化元音 [ɛ̃]；-a- [a]；-lides 读 [lid]，结尾 -es 不发音。前面 les 与 Invalides 连读成 [lez‿ɛ̃.va.lid]。","pi":"开头 in- 是鼻音 [ɛ̃]，不是「in」；les 要连读成 [z]。","et":"invalide 来自拉丁语 invalidus（没有力量的，in- 否定 + validus 强壮）。同源：valide（健康的、有效的）。","ex":[["Les Invalides est un monument à Paris.","荣军院是巴黎的一座古迹。"],["Napoléon est enterré aux Invalides.","拿破仑葬在荣军院。"],["Nous allons aux Invalides cet après-midi.","我们今天下午去荣军院。"]],"co":[["aller aux Invalides","去荣军院"],["le tombeau de Napoléon","拿破仑墓"],["le musée de l'Armée","军事博物馆"]],"sy":[["monument","courant","古迹、纪念建筑"]],"fq":"低到中频，游览巴黎时才用。","me":"invalide = 不再强壮的人：老兵在这里养老。","tr":{"zh":"我们今天下午去荣军院。","fr":"Nous allons aux Invalides cet après-midi.","alt":"On va aux Invalides cet après-midi.","note":"aux = à + les；去某个地方用 aller à。"}},
 "Les sports d'hiver": {"pos":"n.m.pl. 阳性复数名词词组（le sport d'hiver，单数少用）","s":"冬季运动，主要指滑雪、滑板、滑冰等。aller aux sports d'hiver =「去滑雪度假」，法国人常常这样说。","ipa":"[spɔʁ.di.vɛʁ]","ph":"sport 的 t 要发 [t]；d'hiver 的 h 不发音，d' 和 hiver 连读成 [di.vɛʁ]；-er 在 hiver 里读 [ɛʁ]。","pi":"sport 结尾的 t 要读（不像 sports 复数 s 不读）；hiver 的 h 不读。","et":"sport 来自古法语 desport（消遣），经英语 sport 又回到法语。hiver 来自拉丁语 hibernum（冬天的）。","ex":[["J'adore les sports d'hiver.","我爱冬季运动。"],["Nous partons aux sports d'hiver en février.","我们二月去滑雪度假。"],["Le ski est un sport d'hiver très populaire.","滑雪是很受欢迎的冬季运动。"]],"co":[["partir aux sports d'hiver","去滑雪度假"],["une station de sports d'hiver","滑雪度假村"],["faire du ski / du snowboard","滑雪 / 滑单板"]],"sy":[["sports de glisse","courant","滑行类运动（含冲浪）"],["le ski","courant","滑雪，最典型的冬季运动"]],"fq":"中频，假期话题常用。","me":"sport + d'hiver：冬天的运动 = 雪。","tr":{"zh":"我们二月去滑雪度假。","fr":"Nous partons aux sports d'hiver en février.","alt":"On part faire du ski en février.","note":"partir aux sports d'hiver 是固定说法。"}},
 "Un époux / Une épouse": {"pos":"n.m. / n.f. 名词，阳 époux，阴 épouse，复数 époux / épouses","s":"配偶：丈夫 époux，妻子 épouse。比 mari / femme 更正式，常用在表格、正式场合、介绍家人时。les époux = 夫妻（两人）。","ipa":"[e.pu] / [e.puz]","ph":"é [e]；ou [u]；阳性 époux 的 x 不发音，阴性 épouse 的 s 读 [z]。","pi":"époux 的 x 不读；épouse 要读出 [z]，是阴阳性的区别。复数 époux 与单数同形。","et":"来自拉丁语 sponsus / sponsa（许婚的人，未婚夫 / 未婚妻）。同源：épouser（嫁、娶），英语 spouse。","ex":[["Mon époux est médecin.","我丈夫是医生。"],["Son épouse travaille à l'hôpital.","他的妻子在医院工作。"],["Les futurs époux ont signé le contrat.","新婚夫妇签了合同。"]],"co":[["mon époux / mon épouse","我的丈夫 / 我的妻子"],["les jeunes époux","新婚夫妇"],["épouser quelqu'un","和某人结婚"]],"sy":[["mari / femme","courant","丈夫 / 妻子，日常更常用"],["conjoint","courant","配偶（不分性别）"],["compagnon / compagne","courant","伴侣（未必结婚）"]],"fq":"中频，偏正式。","me":"épouse 有 [z]，épouser = 嫁、娶；阴性比阳性多出一个声音。","tr":{"zh":"她的丈夫在银行工作。","fr":"Son époux travaille dans une banque.","alt":"Son mari travaille dans une banque.","note":"époux 更正式，日常说 mari。"}},
 "Un(e) local(e)": {"pos":"n. 名词，阳 un local，阴 une locale，复数 des locaux / des locales","s":"当地人，本地居民。多用在旅行、口语里：les locaux = 当地人。注意：un local（阳性名词）还有「房间、场所」的意思，des locaux = 办公场所，所以要看上下文。","ipa":"[lɔ.kal]","ph":"o [ɔ]；c 在 a 前读 [k]；结尾 -al 读 [al]。复数 locaux 读 [lɔ.ko]。","pi":"阳性复数是 locaux（不是 locals）；des locaux 也可能是「办公室、场所」，不一定是「当地人」。","et":"来自拉丁语 localis（属于某个地方的），locus 是「地方」。同源：localité、localiser。","ex":[["J'aime rencontrer des locaux quand je voyage.","旅行时我喜欢认识当地人。"],["Demandons aux locaux où manger.","我们问问当地人去哪儿吃饭。"],["Les locaux de l'entreprise sont près de la gare.","公司的办公场所在火车站附近。"]],"co":[["rencontrer des locaux","认识当地人"],["manger comme un local","像当地人那样吃"],["les locaux de l'entreprise","公司办公场所"]],"sy":[["habitant(e)","courant","居民"],["les gens du coin","familier","本地人、附近的人"],["autochtone","soutenu","土著、原住民"]],"fq":"中频，旅行话题的口语里越来越常见。","me":"local = lieu 的形容词；locaux 既是「当地人」也是「场所」。","tr":{"zh":"我们问问当地人。","fr":"Demandons aux locaux.","alt":"On va demander aux gens du coin.","note":"demander à + 人；aux = à + les。"}},
 "Atterrir": {"pos":"v. 第二组规则动词（-ir / -issant），助动词 avoir：j'atterris, nous atterrissons, j'ai atterri","s":"（飞机）降落，着陆。反义词是 décoller（起飞）。口语里也可比喻「落到某处、最后到了某个地方」：Il a atterri à Lyon.","ipa":"[a.te.ʁiʁ]","ph":"tt 读一个 [t]；rr 读一个 [ʁ]；结尾 -ir 读 [iʁ]，r 要发音。","pi":"tt、rr 都是双写字母，但只读一个音；注意 atterrir 里有两个 r，拼写别写成 aterir。","et":"由 à + terre（陆地、地面）构成：原本是航海词，指船靠岸，后来用于飞机。同族词：terre、terrain、aterrissage。","ex":[["L'avion va atterrir bientôt.","飞机即将降落。"],["Nous avons atterri à Paris à huit heures.","我们八点在巴黎降落。"],["Il a atterri dans un petit village.","他最后到了一个小村子。"]],"co":[["atterrir à Paris","在巴黎降落"],["atterrir en douceur","平稳降落"],["atterrir sur la piste","降落在跑道上"]],"sy":[["se poser","courant","（鸟、飞机）落下"],["décoller","courant","反义：起飞"]],"fq":"中频，旅行话题常用。","me":"at-terr-ir：看到 terre（地面），飞机回到地面。","tr":{"zh":"飞机十点降落。","fr":"L'avion atterrit à dix heures.","alt":"L'avion va atterrir à dix heures.","note":"降落 atterrir，起飞 décoller。"}},
 "Flotter": {"pos":"v. 第一组规则动词（-er），助动词 avoir：je flotte, nous flottons, j'ai flotté","s":"漂浮，浮在水上或空中；也可指旗子、头发等飘动。口语里 il flotte = 下雨了（familier）。","ipa":"[flɔ.te]","ph":"fl- 连读 [fl]；o [ɔ]；tt 只读一个 [t]；-er 读 [e]。","pi":"tt 只读一个 [t]；结尾 -er 不读 [ɛʁ]，读 [e]。","et":"来源不确定。同族词：flot（波浪、水流）、flotte（舰队；也有「水」的俗称）、flottant（漂浮的）。","ex":[["Le bateau flotte sur l'eau.","船浮在水上。"],["Le drapeau flotte au vent.","旗子在风中飘。"],["Il flotte depuis ce matin.","从今天早上起就一直在下雨。"]],"co":[["flotter sur l'eau","浮在水上"],["flotter au vent","在风中飘动"],["laisser flotter","任其漂浮"],["il flotte (familier)","下雨了"]],"sy":[["surnager","soutenu","浮在水面（也比喻勉强维持）"],["couler","courant","反义：沉下去"],["pleuvoir","courant","下雨，il flotte 的标准说法"]],"fq":"中频。","me":"flotter 听起来像 float：漂浮；flottant 也是同族。","tr":{"zh":"船浮在湖上。","fr":"Le bateau flotte sur le lac.","alt":"Le bateau reste à la surface du lac.","note":"flotter 是第一组动词，不及物。"}},
 "Pique-niquer": {"pos":"v. 第一组规则动词（-er），助动词 avoir：je pique-nique, nous pique-niquons, j'ai pique-niqué","s":"野餐。由名词 un pique-nique（一次野餐）变来。通常说 faire un pique-nique 或 pique-niquer，在公园、海边、草地上都行。","ipa":"[pik.ni.ke]","ph":"qu 读 [k]；i [i]；-er 读 [e]。pique 和 niquer 中间有连字符，节奏是 pik-ni-ké。","pi":"qu 不读 [kw]，读 [k]；pique-niquer 要保留连字符。","et":"来源不确定。pique-nique 是十七世纪出现的合成词，后传入英语 picnic。动词是在名词基础上加 -er。","ex":[["Nous allons pique-niquer dans le parc.","我们要去公园野餐。"],["Il fait beau, on pique-nique dehors.","天气好，我们在外面野餐。"],["Elle a apporté un panier pour le pique-nique.","她带了一个野餐篮。"]],"co":[["pique-niquer dans le parc","在公园野餐"],["faire un pique-nique","野餐"],["un panier de pique-nique","野餐篮"],["pique-niquer au bord de l'eau","在水边野餐"]],"sy":[["manger dehors","courant","在户外吃饭"],["casse-croûte","familier","简单的一餐、点心"]],"fq":"中频，天气好时常用。","me":"pik-nik = 英语 picnic 的发音一样。","tr":{"zh":"天气好，我们去野餐。","fr":"Il fait beau, nous allons pique-niquer.","alt":"Il fait beau, on va faire un pique-nique.","note":"aller + 不定式：近将来。"}},
 "Régler (payer)": {"pos":"v. 第一组动词（-er），助动词 avoir：je règle, nous réglons, j'ai réglé（词干 é 在不发音的结尾前变 è）","s":"付款，结账：régler la note / l'addition。还可以指「调整」（régler le volume）和「解决」（régler un problème）。比 payer 稍正式，在商店、酒店里常说 Je vous règle ?","ipa":"[ʁe.ɡle]","ph":"é [e]；g 在 l 前读 [ɡ]（硬 g）；结尾 -er 读 [e]。","pi":"règle（è）和 réglons（é）重音符号会变；g 读 [ɡ]，不是 [ʒ]。","et":"来自拉丁语 regula（尺、规则），règle（规则、尺）同源。régler = 按规则把事情摆好。","ex":[["Je règle la note.","我结账。"],["Vous réglez par carte ou en espèces ?","您刷卡还是付现金？"],["Il faut régler ce problème vite.","这个问题得赶快解决。"]],"co":[["régler la note / l'addition","结账"],["régler par carte","刷卡付款"],["régler un problème","解决问题"],["régler le volume","调音量"]],"sy":[["payer","courant","付钱，最常用"],["résoudre","courant","解决（问题）"],["ajuster","courant","调整"]],"fq":"高频，一词多义。","me":"régler ← règle：按「规矩」把账算清。","tr":{"zh":"我用卡付账。","fr":"Je règle par carte.","alt":"Je paie avec ma carte.","note":"régler 的 é 在 règle 里变成 è。"}},
 "Regretter": {"pos":"v. 第一组规则动词（-er），助动词 avoir：je regrette, nous regrettons, j'ai regretté","s":"后悔，遗憾。regretter + 名词 / de + 不定式 / que + 虚拟式。Je regrette = 对不起、很遗憾（客气、正式地道歉）。也可指「想念」，如 regretter le passé。","ipa":"[ʁə.ɡʁɛ.te]","ph":"re- 读 [ʁə]；gr [ɡʁ]；tt 一个 [t]；-er 读 [e]。","pi":"拼写里只有两个 r（re- 和 gr），但有双 t：regretter。regretter que 后接虚拟式。","et":"来源不确定。同族词：un regret（后悔、遗憾）、regrettable（令人遗憾的）。","ex":[["Je regrette mon erreur.","我后悔我的错误。"],["Je regrette de ne pas être venu.","我很后悔没有来。"],["Nous regrettons que vous partiez déjà.","您这么早就走，我们很遗憾。"]],"co":[["regretter son erreur","后悔自己的错误"],["regretter de + inf.","后悔做了……"],["regretter que + subj.","遗憾……"],["Je regrette.","很抱歉、很遗憾。"]],"sy":[["se repentir","soutenu","悔过（更强烈、更正式）"],["désolé","courant","很抱歉（形容词）"],["s'en vouloir","courant","责怪自己"]],"fq":"高频，日常和正式场合都用。","me":"regret 加 -er；看到 re-gret：事后又想（re-）起来的遗憾。","tr":{"zh":"我很后悔没有给你打电话。","fr":"Je regrette de ne pas t'avoir téléphoné.","alt":"Je m'en veux de ne pas t'avoir appelé.","note":"regretter de + 完成式不定式 = 后悔做过 / 没做过。"}},
 "Rouler": {"pos":"v. 第一组规则动词（-er），助动词 avoir：je roule, nous roulons, j'ai roulé","s":"（车辆）行驶；滚动。Il roule à 100 à l'heure = 他开到时速 100。也说 rouler en voiture / à vélo。口语里 Ça roule ? =「顺利吗？」，Ça roule = 一切顺利（familier）。","ipa":"[ʁu.le]","ph":"r- 是小舌音 [ʁ]；ou [u]；l [l]；-er 读 [e]。","pi":"ou 读 [u]，r 是喉音，不是卷舌。rouler 不及物时不带宾语：La voiture roule（不是 conduit）。","et":"来自拉丁语 rotulare（滚动），rotula 是「小轮子」，rota 是「轮子」。同族词：un rouleau（滚筒、卷）。","ex":[["La voiture roule vite.","车开得很快。"],["Nous avons roulé toute la nuit.","我们开了一整夜车。"],["Ça roule, ce matin ?","今天早上路上顺不顺？"]],"co":[["rouler vite / doucement","开得快 / 慢"],["rouler en voiture / à vélo","开车 / 骑车"],["rouler à droite","靠右行驶"],["Ça roule !","挺顺利的！（familier）"]],"sy":[["conduire","courant","驾驶（主语是人，带宾语）"],["circuler","courant","（车）通行"],["rouler","familier","也有「骗人」的意思：se faire rouler = 被骗"]],"fq":"高频，一词多义。","me":"rouler ← rotula（小轮子）：车轮转，车就走。","tr":{"zh":"这辆车开得很慢。","fr":"Cette voiture roule lentement.","alt":"Cette voiture avance doucement.","note":"rouler 的主语常是车；人开车用 conduire。"}},
 "S'installer": {"pos":"v. 代动词（se + 第一组），助动词 être：je m'installe, nous nous installons, je me suis installé(e)","s":"坐好，坐下来；安顿下来，在某处住下。Installez-vous ! =「请坐 / 请自便」。也指「搬进新家、开始新生活」。","ipa":"[ɛ̃s.ta.le]","ph":"in- 是鼻化元音 [ɛ̃]；st 连读 [sta]；-er 读 [e]。代动词前面是 s'，念成 [sɛ̃s.ta.le]。","pi":"开头 in- 读 [ɛ̃]，不是「in」；复合时助动词用 être，过去分词要跟主语配合：elle s'est installée。","et":"由 installer 加反身代词构成；installer 来自中世纪拉丁语 installare（安置在座位上），与 stalle（座席）同族。","ex":[["Vous pouvez vous installer ici.","您可以在这里就座。"],["Ils se sont installés à Lyon l'an dernier.","他们去年在里昂安了家。"],["Installe-toi, je prépare le café.","你坐吧，我去泡咖啡。"]],"co":[["Installez-vous !","请坐 / 请自便！"],["s'installer à + ville","在某城市安顿下来"],["s'installer dans un fauteuil","在扶手椅上坐好"],["s'installer à son compte","自己开业"]],"sy":[["s'asseoir","courant","坐下（更直接）"],["emménager","courant","搬进新家"],["se poser","familier","坐下歇一会儿"]],"fq":"高频，日常常用。","me":"s'installer：把自己「安」在一个位置，in-stall。","tr":{"zh":"请坐，我去拿水。","fr":"Installez-vous, je vais chercher de l'eau.","alt":"Asseyez-vous, je vous apporte de l'eau.","note":"命令式代动词：Installe-toi / Installez-vous。"}},
 "S'orienter": {"pos":"v. 代动词（se + 第一组），助动词 être：je m'oriente, nous nous orientons, je me suis orienté(e)","s":"辨别方向，找到路：s'orienter avec une carte。也可以比喻「选择方向」：s'orienter vers les sciences =（学业上）选择理科方向。","ipa":"[ɔ.ʁjɑ̃.te]","ph":"o [ɔ]；ri 读 [ʁj]；-en- 读鼻化元音 [ɑ̃]；-er 读 [e]。","pi":"-ent- 在这里是鼻音 [ɑ̃]（orienter 里的 en 不是 [ɛ̃]）；助动词用 être。","et":"来自 orient（东方，来自拉丁语 oriens，「升起」，指日出方向）。原义是「面向东方」，引申为辨别方向。同族词：orientation、désorienté。","ex":[["C'est difficile de s'orienter dans cette ville.","在这座城市很难辨别方向。"],["Je m'oriente avec le soleil.","我靠太阳辨别方向。"],["Elle s'est orientée vers la médecine.","她选择了医学方向。"]],"co":[["s'orienter avec une carte / une boussole","用地图 / 指南针找方向"],["s'orienter vers + 名词","朝……方向发展"],["perdre son sens de l'orientation","迷失方向感"]],"sy":[["se repérer","courant","找到位置、认路"],["se diriger","courant","朝某处走"],["se perdre","courant","反义：迷路"]],"fq":"中频，旅行、学业话题常用。","me":"orient = 东方：先面向东，再找别的方向。","tr":{"zh":"我在这个城市找不到方向。","fr":"Je n'arrive pas à m'orienter dans cette ville.","alt":"Je suis perdu dans cette ville.","note":"ne pas arriver à + 不定式 = 做不到。"}},
 "Se demander": {"pos":"v. 代动词（se + 第一组），助动词 être：je me demande, nous nous demandons, je me suis demandé","s":"心想，自问，不知道：se demander si / pourquoi / ce que...，表示心里有一个疑问。注意不是「向别人要求」（那是 demander）。","ipa":"[də.mɑ̃.de]","ph":"de- 读 [də]；-man- 读鼻化元音 [ɑ̃]；-er 读 [e]。前面有 se，念作 [sə.də.mɑ̃.de]。","pi":"se demander 后接 si 引导的疑问句，用陈述式，不用虚拟式；不要和 demander（要求、问）混淆。","et":"来自拉丁语 demandare（托付），后来变成「请求、问」。se demander 字面是「问自己」。同源：commander。","ex":[["Je me demande s'il va pleuvoir.","我在想会不会下雨。"],["Elle se demande pourquoi il est parti.","她不明白他为什么走了。"],["On se demande ce qu'on va manger.","我们在想吃点什么。"]],"co":[["se demander si + 陈述句","不知道是否……"],["se demander pourquoi","不明白为什么"],["se demander ce que + 句子","想知道……是什么"],["Je me demande.","我也不知道。（口语）"]],"sy":[["s'interroger","soutenu","自问，思索"],["se poser la question","courant","自己问自己这个问题"],["se questionner","courant","自问"]],"fq":"高频，口语常用。","me":"se demander = 问自己：没人可以回答，只有自己想。","tr":{"zh":"我在想他今晚来不来。","fr":"Je me demande s'il vient ce soir.","alt":"Je me demande s'il va venir ce soir.","note":"se demander si + 直陈式。"}},
 "Traduire": {"pos":"v. 第三组不规则动词（-uire，同 conduire），助动词 avoir：je traduis, nous traduisons, j'ai traduit","s":"翻译：traduire un texte, traduire du français en chinois。也可比喻「表达出来」：Ses yeux traduisent sa peur。名词是 une traduction（翻译），译者是 un traducteur。","ipa":"[tʁa.dɥiʁ]","ph":"tr [tʁ]；ui 读 [ɥi]（半元音 + i）；结尾 -re 的 e 不发音，读 [ɥiʁ]。","pi":"ui 读 [ɥi]，是一个音节，不是「u-i」；翻译成某语言用 en：traduire en français（不是 à）。","et":"来自拉丁语 traducere（带过去），tra(ns)- + ducere（引导）。同族词：conduire、produire、traduction。","ex":[["Peux-tu traduire ce texte ?","你能翻译这段文字吗？"],["Je traduis cette phrase en anglais.","我把这句话翻译成英语。"],["Son sourire traduit sa joie.","他的笑容表达了他的高兴。"]],"co":[["traduire un texte","翻译一段文字"],["traduire du français en chinois","把法语译成中文"],["traduire en français","翻译成法语"],["un traducteur en ligne","在线翻译器"]],"sy":[["interpréter","courant","口译；也有「解读」的意思"],["exprimer","courant","表达"],["transcrire","soutenu","转写、抄录"]],"fq":"高频，学习和工作常用。","me":"tra + duire：把意思「引导」到另一种语言。","tr":{"zh":"你能把这句话翻译成法语吗？","fr":"Peux-tu traduire cette phrase en français ?","alt":"Tu peux me traduire cette phrase en français ?","note":"traduire X en + 语言。"}},
 "Voyager": {"pos":"v. 第一组动词（-er），助动词 avoir：je voyage, nous voyageons, j'ai voyagé（nous 形式保留 e）","s":"旅行，出行。voyager en train / en avion / seul。名词：un voyage（旅行），un voyageur（旅客）。voyager 一般不接目的地做宾语，目的地用 aller à 或 voyager en / au。","ipa":"[vwa.ja.ʒe]","ph":"oy 读 [waj]；a [a]；g 在 e 前读 [ʒ]；nous voyageons 里 e 保留，让 g 保持 [ʒ]。","pi":"oy 读 [waj]，不是「oi」；nous voyageons（不是 voyagons）。去某国：voyager en France / au Japon。","et":"来自古法语 veage（旅程），来自拉丁语 viaticum（旅途所需的东西），与 via（路）同族。","ex":[["J'aime voyager en train.","我喜欢坐火车旅行。"],["Nous voyageons beaucoup en été.","我们夏天经常出去旅行。"],["Elle a voyagé seule en Italie.","她独自去意大利旅行了。"]],"co":[["voyager en train / en avion","坐火车 / 飞机旅行"],["voyager seul(e) / en famille","独自 / 全家旅行"],["voyager léger","轻装旅行"],["voyager à l'étranger","出国旅行"]],"sy":[["partir en voyage","courant","出门旅行"],["se déplacer","courant","出行、移动"],["bourlinguer","familier","到处闯荡、走南闯北"]],"fq":"极高频，日常常用。","me":"voyage 的动词：voy-ager，nous voyageons 记得多一个 e。","tr":{"zh":"我们夏天坐火车旅行。","fr":"En été, nous voyageons en train.","alt":"L'été, on voyage en train.","note":"nous voyageons 保留 e；交通工具用 en。"}},
 "Ludique": {"pos":"adj. 形容词，阴阳同形，复数 ludiques","s":"好玩的，有游戏性的，寓教于乐的：une activité ludique，un jeu ludique。常用在教育、软件、活动里，强调「像游戏一样有趣」。","ipa":"[ly.dik]","ph":"u 读 [y]（嘴唇圆、发 i 的口型）；qu 读 [k]；结尾 -e 不发音。","pi":"u 是 [y]，不是 [u]；qu 读 [k]。阴阳性同形：un jeu ludique / une activité ludique。","et":"来自拉丁语 ludus（游戏），同族词：ludothèque（玩具图书馆）、illusion（幻觉，源自 ludere「玩」）。","ex":[["Ce jeu est très ludique.","这个游戏很有趣。"],["J'apprends le français avec une appli ludique.","我用一个好玩的应用学法语。"],["Cette activité est ludique et éducative.","这个活动既好玩又有教育意义。"]],"co":[["une activité ludique","有趣的活动"],["un jeu ludique","好玩的游戏"],["un apprentissage ludique","寓教于乐的学习"],["un côté ludique","好玩的一面"]],"sy":[["amusant","courant","有趣的（更常用）"],["distrayant","courant","消遣的"],["sérieux","courant","反义：认真的"]],"fq":"中频，教育、活动话题常用。","me":"ludique ← ludus：游戏；英语 ludicrous（荒唐的）有亲缘。","tr":{"zh":"这个应用学法语很有趣。","fr":"Cette appli est un moyen ludique d'apprendre le français.","alt":"Cette appli rend le français plus amusant.","note":"ludique 阴阳性同形。"}},
 "Responsable": {"pos":"adj. / n. 形容词、名词，阴阳同形，复数 responsables","s":"负责的；有责任感的。être responsable de + 名词 = 对……负责。也可作名词：un(e) responsable = 负责人、主管（le responsable des ventes）。","ipa":"[ʁɛs.pɔ̃.sabl]","ph":"re- 读 [ʁɛ]（不是 [ʁə]）；sp [sp]；on 鼻化 [ɔ̃]；s 在 -sa- 读 [s]；-able 读 [abl]。","pi":"拼写是 -able，不是英语的 -ible；s 读 [s]，不是 [z]。","et":"来自拉丁语 respondere（回答，承担）+ -able。同族词：répondre（回答）、responsabilité（责任）。","ex":[["Il est responsable du projet.","他负责这个项目。"],["Tu dois être responsable de tes actes.","你要对自己的行为负责。"],["Je voudrais parler au responsable.","我想和负责人谈谈。"]],"co":[["être responsable de","对……负责"],["un comportement responsable","有责任感的行为"],["le responsable des ventes","销售主管"],["responsable de projet","项目负责人"]],"sy":[["chargé(e) de","courant","负责……的"],["sérieux","courant","认真的、靠得住的"],["coupable","courant","有罪的（不同：有过错）"]],"fq":"极高频，日常和工作都常用。","me":"responsable：能「回答」（répondre）后果的人。","tr":{"zh":"他对这个小组负责。","fr":"Il est responsable de cette équipe.","alt":"C'est lui qui s'occupe de cette équipe.","note":"responsable de + 名词。"}},
 "Sensible": {"pos":"adj. 形容词，阴阳同形，复数 sensibles","s":"敏感的，容易受影响的：Elle est très sensible. 也指对某事敏感：sensible au froid（怕冷）。注意：sensible 不是英语 sensible（明智的），明智、合理要说 raisonnable。","ipa":"[sɑ̃.sibl]","ph":"s [s]；en 读鼻化元音 [ɑ̃]；第二个 s 在 i 前也读 [s]；结尾 -ble 读 [bl]，e 不发音。","pi":"false friend：sensible 在法语是「敏感的」，英语 sensible 是「明智的」，法语要用 raisonnable。","et":"来自拉丁语 sensibilis（可以感觉到的），sentire 是「感觉」。同族词：sentir、sens、sensibilité。","ex":[["Elle est très sensible.","她很敏感。"],["Il est sensible au froid.","他怕冷。"],["J'ai la peau sensible.","我的皮肤很敏感。"]],"co":[["être sensible à","对……敏感"],["avoir la peau sensible","皮肤敏感"],["un sujet sensible","敏感话题"],["une personne sensible","多愁善感的人"]],"sy":[["émotif","courant","易动感情的"],["susceptible","courant","容易生气的"],["insensible","courant","反义：不敏感的"]],"fq":"高频，描写性格和身体时常用。","me":"sensible ← sens：有「感觉」，容易有感觉。","tr":{"zh":"她对噪音很敏感。","fr":"Elle est très sensible au bruit.","alt":"Le bruit la dérange facilement.","note":"sensible à + 名词。"}},
 "Touristique": {"pos":"adj. 形容词，阴阳同形，复数 touristiques","s":"旅游的，游客多的：une ville touristique，un lieu touristique。有时带一点「人太多、太商业」的意思：C'est très touristique ici.","ipa":"[tu.ʁis.tik]","ph":"ou [u]；r [ʁ]；-is- 读 [is]；qu 读 [k]；结尾 -e 不发音。","pi":"ou 读 [u]；qu 是 [k]；r 是喉音。「旅游」是 le tourisme，不要说 touriste（游客，名词）。","et":"由 touriste / tourisme 加后缀 -ique 而成；tourisme、touriste 十九世纪借自英语，词根 tour（环游）。","ex":[["C'est une ville très touristique.","这是一座旅游城市。"],["Nous avons visité les sites touristiques.","我们参观了旅游景点。"],["Je préfère éviter les endroits trop touristiques.","我更想避开游客太多的地方。"]],"co":[["une ville / un lieu touristique","旅游城市 / 旅游点"],["un site touristique","景点"],["l'office de tourisme","旅游局（注意用 tourisme）"],["très touristique","游客很多"]],"sy":[["pittoresque","courant","风景如画的"],["fréquenté","courant","人多的"],["authentique","courant","反义：真实的、不商业化的"]],"fq":"中频，旅行话题常用。","me":"touriste + -ique：touriste 的形容词。","tr":{"zh":"这个地方游客太多了。","fr":"Cet endroit est trop touristique.","alt":"Il y a trop de touristes ici.","note":"touristique 阴阳性同形。"}},
 "Tropical(e)": {"pos":"adj. 形容词，阳 tropical，阴 tropicale，阳性复数 tropicaux，阴性复数 tropicales","s":"热带的：un climat tropical，un fruit tropical，une île tropicale。阳性复数不是 tropicals，而是 tropicaux。","ipa":"[tʁɔ.pi.kal]","ph":"tr [tʁ]；o [ɔ]；c 在 a 前读 [k]；阳性复数 tropicaux 读 [tʁɔ.pi.ko]。","pi":"阳性复数是 tropicaux（-al → -aux）；tropicale 的 e 不发音。","et":"来自希腊语 tropikos（转折的），经拉丁语 tropicus；tropique 原指太阳「转向」的回归线。同源：英语 tropical、tropics。","ex":[["Le climat est tropical.","气候是热带的。"],["J'adore les fruits tropicaux.","我爱热带水果。"],["Elle rêve d'une île tropicale.","她梦想一个热带岛屿。"]],"co":[["un climat tropical","热带气候"],["des fruits tropicaux","热带水果"],["une forêt tropicale","热带雨林"],["une chaleur tropicale","热带般的炎热"]],"sy":[["équatorial","courant","赤道的"],["exotique","courant","有异国风情的"],["tempéré","courant","反义：温和的、温带的"]],"fq":"中频，旅行和自然话题常用。","me":"tropical 和英语 tropical 一样；复数 tropicaux。","tr":{"zh":"我们在热带岛上吃热带水果。","fr":"Sur l'île tropicale, nous mangeons des fruits tropicaux.","alt":"Sur cette île, on mange plein de fruits tropicaux.","note":"阳性复数用 tropicaux。"}},
 "Partout": {"pos":"adv. 副词，不变","s":"到处，处处：J'ai cherché partout. 也可以说 partout où...（无论在哪儿）。un peu partout =「到处都有一些」，de partout =「从各处」。","ipa":"[paʁ.tu]","ph":"par 读 [paʁ]；中间的 t 要发音，是 tout 的开头；ou 读 [u]；结尾 -t 不发音。","pi":"最后的 t 不读，读 [paʁ.tu]；写成一个词 partout，不要拆成 par tout。","et":"由 par（经过）+ tout（全部）合成，意为「通通经过」。同族词：partout、tout、par exemple。","ex":[["J'ai cherché partout.","我到处找过。"],["Il y a des fleurs partout dans le jardin.","花园里到处都是花。"],["Il pleut partout en France aujourd'hui.","今天法国到处都在下雨。"]],"co":[["partout dans le monde","世界各地"],["un peu partout","到处都有一些"],["de partout","从各处"],["partout où + 动词","无论在哪里"]],"sy":[["en tous lieux","soutenu","到处、各处"],["ici et là","courant","这里那里"],["nulle part","courant","反义：哪里都没有"]],"fq":"极高频，日常常用。","me":"par + tout：经过一切地方 = 到处。","tr":{"zh":"我在家里到处找钥匙。","fr":"J'ai cherché mes clés partout dans la maison.","alt":"J'ai cherché mes clés dans toute la maison.","note":"partout 是副词，位置在动词之后。"}},
 "En solo": {"pos":"loc. adv. 副词短语，不变（solo 为意大利语借词，复数 solos）","s":"独自，单独（做某事）：voyager en solo，faire du ski en solo。语气比 seul 更口语，常带「自己一个人享受」的轻松感。","ipa":"[ɑ̃.sɔ.lo]","ph":"en 读鼻化元音 [ɑ̃]；solo 读 [sɔ.lo]，o 在词尾读 [o]；en 与 solo 之间不连读。","pi":"en 是 [ɑ̃]，不是「ən」；solo 结尾 o 不要读成 [ɔ]。","et":"来自意大利语 solo（独自），源自拉丁语 solus（单独）。在法语中先用于音乐，后推广到一般场合。","ex":[["Je préfère voyager en solo.","我更喜欢独自旅行。"],["Elle a fait le tour du monde en solo.","她独自环游了世界。"],["Il chante en solo dans la chorale.","他在合唱团里独唱。"]],"co":[["voyager en solo","独自旅行"],["partir en solo","独自出发"],["un voyage en solo","一次独自旅行"],["un album solo","个人专辑"]],"sy":[["seul(e)","courant","独自的，最常用"],["en solitaire","courant","独自地（常用于比赛、航海）"],["en duo","courant","反义：双人"]],"fq":"中频，旅行话题常用。","me":"solo = 英语 solo：一个人一个声音。","tr":{"zh":"我想一个人去旅行。","fr":"Je veux partir en voyage en solo.","alt":"J'ai envie de voyager seul.","note":"en solo 不变，不分阴阳性。"}},
 "À couper le souffle": {"pos":"loc. adj. 形容词短语，不变（fém. 和复数也不变）","s":"令人屏息的，美得让人说不出话：un paysage à couper le souffle。也可形容速度、价格极夸张。字面是「切断呼吸」。","ipa":"[a.ku.pe.lə.sufl]","ph":"à [a]；couper 读 [ku.pe]；le 读 [lə]；souffle 读 [sufl]，ou [u]，ff 一个音，结尾 -e 不读。","pi":"couper 在这里是不定式，所以 -er 读 [e]；souffle 的 ff 只读一个 [f]。整个短语不变，不加 s。","et":"由 couper（切）+ souffle（呼吸）构成；souffle 来自动词 souffler，拉丁语 sufflare（吹）。","ex":[["La vue est à couper le souffle.","景色美得令人窒息。"],["Ce paysage est à couper le souffle.","这片风景令人屏息。"],["Les prix sont à couper le souffle !","价格高得吓人！"]],"co":[["une vue à couper le souffle","令人屏息的景色"],["couper le souffle à quelqu'un","让某人屏住呼吸"],["un spectacle à couper le souffle","令人叹为观止的演出"]],"sy":[["magnifique","courant","壮丽的"],["époustouflant","courant","令人惊叹的"],["à tomber par terre","familier","惊人得让人腿软"]],"fq":"中频，描写景色时常用。","me":"美得「切断」呼吸：couper le souffle。","tr":{"zh":"山上的景色美得令人屏息。","fr":"La vue depuis la montagne est à couper le souffle.","alt":"Du haut de la montagne, c'est à couper le souffle.","note":"à couper le souffle 作形容词，整体不变。"}},
 "Après l'effort, le réconfort !": {"pos":"loc. 固定说法（谚语式，感叹语气）","s":"辛苦之后就是犒劳！做完一件累人的事后，吃点好吃的、休息一下，常带玩笑口气。字面意思：努力之后，安慰（享受）。","ipa":"[a.pʁɛ.lɛ.fɔʁ.lə.ʁe.kɔ̃.fɔʁ]","ph":"après 读 [a.pʁɛ]；l'effort 连读 [lɛ.fɔʁ]；réconfort 读 [ʁe.kɔ̃.fɔʁ]，结尾 -t 不读。","pi":"effort 与 réconfort 结尾的 t 都不读；l'effort 要连读，不是 le effort。","et":"effort 来自动词 s'efforcer（努力）；réconfort 来自 réconforter，拉丁语 confortare（加强），加前缀 re-，词根 fort（强）。","ex":[["Je prends un café : après l'effort, le réconfort !","我喝杯咖啡：辛苦之后犒劳一下！"],["On a bien marché, un bon repas : après l'effort, le réconfort !","我们走了很久，去吃顿好的：辛苦之后犒劳一下！"],["Après l'effort, le réconfort : on va à la plage.","辛苦之后就是享受：我们去海滩。"]],"co":[["prendre un petit réconfort","来点安慰、犒劳（吃点东西）"],["avoir besoin de réconfort","需要安慰"],["un mot de réconfort","一句安慰的话"]],"sy":[["On l'a bien mérité !","familier","我们应得的！"],["Il faut bien se récompenser.","courant","总得奖励一下自己。"]],"fq":"中频，口语里常半开玩笑说。","me":"effort 和 réconfort 押韵：先用力，再享受。","tr":{"zh":"走了一天路，现在好好吃一顿：辛苦之后就是享受！","fr":"On a marché toute la journée, on mange bien : après l'effort, le réconfort !","alt":"Après cette journée de marche, un bon repas, on l'a bien mérité !","note":"固定说法，不能随便改词。"}},
 "Dormir chez l'habitant": {"pos":"loc. verbale（dormir 为第三组不规则动词，助动词 avoir：je dors, nous dormons, j'ai dormi）","s":"住在当地人家里，民宿式住宿。chez l'habitant 指住在当地居民家，而不是酒店。也常用名词形式：un séjour chez l'habitant。","ipa":"[dɔʁ.miʁ.ʃe.la.bi.tɑ̃]","ph":"dormir 读 [dɔʁ.miʁ]；chez ch [ʃ]，ez [e]；l'habitant 的 h 不发音，l' 与 habitant 连读，-ant 读鼻化 [ɑ̃]。","pi":"habitant 的 h 不发音；l'habitant 要读成 [la.bi.tɑ̃]。-ant 的 t 不读。","et":"dormir 来自拉丁语 dormire；habitant 来自动词 habiter（居住），拉丁语 habitare。chez 来自拉丁语 casa（房子）。","ex":[["Nous allons dormir chez l'habitant au Japon.","我们在日本要住当地人家里。"],["Ils ont dormi chez l'habitant pendant le voyage.","旅行中他们住在当地人家里。"],["J'aime les séjours chez l'habitant.","我喜欢住在当地人家里的旅行。"]],"co":[["dormir chez l'habitant","住在当地人家里"],["un séjour chez l'habitant","民宿式住宿"],["une chambre chez l'habitant","当地人家里的房间"]],"sy":[["loger chez des particuliers","courant","住在私人家里"],["à l'hôtel","courant","反义：住酒店"],["en chambre d'hôtes","courant","住民宿"]],"fq":"中频，旅行话题常用。","me":"chez l'habitant：「在居民家里」睡觉。","tr":{"zh":"我们想在意大利住当地人家里。","fr":"Nous voulons dormir chez l'habitant en Italie.","alt":"On veut loger chez l'habitant en Italie.","note":"chez + 人：在某人家里。"}},
 "Être comme un fou": {"pos":"loc. verbale（être，助动词 avoir：j'ai été）；阴性 être comme une folle，复数 être comme des fous","s":"兴奋得发狂，高兴得像疯了一样：J'étais comme un fou ! 也可以修饰动作：courir comme un fou（拼命地跑）、travailler comme un fou（疯狂工作）。","ipa":"[ɛtʁ.kɔm.œ̃.fu]","ph":"être 读 [ɛtʁ]；comme 读 [kɔm]；un 读 [œ̃]；fou 读 [fu]，ou [u]。","pi":"fou 的阴性是 folle（不是 foue）；un 读 [œ̃]，不要读成 [ɛ̃]。","et":"fou 来自拉丁语 follis（风箱、气囊），形容人「脑袋里装满风」。","ex":[["C'était génial ! J'étais comme un fou !","太棒了！我高兴得像疯了一样！"],["Elle courait comme une folle.","她拼命地跑。"],["Ils travaillent comme des fous.","他们拼命工作。"]],"co":[["courir comme un fou","拼命地跑"],["travailler comme un fou","疯狂工作"],["être comme fou / folle","高兴得发狂"]],"sy":[["être aux anges","courant","高兴得像在天堂"],["être fou de joie","courant","欣喜若狂"],["être surexcité","familier","过度兴奋"]],"fq":"中频，口语常用。","me":"fou = 疯：像疯子一样做某事。","tr":{"zh":"我们赢了，我高兴得像疯了一样！","fr":"On a gagné, j'étais comme un fou !","alt":"On a gagné, j'étais fou de joie !","note":"女生说 comme une folle。"}},
 "Sortir de sa zone de confort": {"pos":"loc. verbale（sortir 为第三组动词，助动词 être：je suis sorti(e)；sa 随主语变：ma / ta / sa / notre / votre / leur）","s":"走出舒适区：离开熟悉、安全的状态，去试新的、有点难的事。sa 要随主语变化：Je sors de ma zone de confort。常用在旅行、成长、工作话题。","ipa":"[sɔʁ.tiʁ.də.sa.zon.də.kɔ̃.fɔʁ]","ph":"sortir 读 [sɔʁ.tiʁ]；zone 读 [zon]（o [o]）；confort 读 [kɔ̃.fɔʁ]，结尾 -t 不读，on 鼻化 [ɔ̃]。","pi":"confort 的 t 不读；sa 要随主语变成 ma / ta / notre / votre，不要一律说 sa。","et":"zone 来自拉丁语 zona（带、地带，源自希腊语 zōnē）；confort 与 réconfort 同源（拉丁语 confortare，加强），现代「舒适」义受英语 comfort 影响。","ex":[["Il faut sortir de sa zone de confort.","要走出舒适区。"],["Je sors de ma zone de confort en voyageant seul.","我独自旅行，走出我的舒适区。"],["Elle est sortie de sa zone de confort pour ce nouveau travail.","为了这份新工作，她走出了舒适区。"]],"co":[["sortir de sa zone de confort","走出舒适区"],["rester dans sa zone de confort","待在舒适区里"],["quitter sa zone de confort","离开舒适区"],["pousser quelqu'un hors de sa zone de confort","推某人走出舒适区"]],"sy":[["oser","courant","敢于尝试"],["se dépasser","courant","超越自己"],["rester dans ses habitudes","courant","反义：保持老习惯"]],"fq":"中频，成长和旅行话题常用。","me":"舒适区 = zone de confort；sortir = 走出来。","tr":{"zh":"为了进步，你要走出舒适区。","fr":"Pour progresser, tu dois sortir de ta zone de confort.","alt":"Pour avancer, il faut sortir de sa zone de confort.","note":"sa / ta / ma 随主语变。"}},
 "Sur la note": {"pos":"loc. 介词短语（note 为阴性名词，复数 notes）","s":"记在账单上，记在房账上。note 在酒店、餐厅里 =「账单」：mettre sur la note = 记账，退房时一起结算。note 还有「分数」「笔记」「音符」的意思。","ipa":"[syʁ.la.nɔt]","ph":"sur 读 [syʁ]，u 是 [y]；la [la]；note 读 [nɔt]，o [ɔ]，t 要发音。","pi":"u 读 [y]，不是 [u]；note 的 t 要读（不同于 notes 复数 s 不读）。","et":"note 来自拉丁语 nota（记号、标记）。同族词：noter（记下）、notice、annoter。","ex":[["Vous pouvez mettre notre repas sur la note.","您可以把我们的餐费记在房账上。"],["Mettez le petit-déjeuner sur la note de la chambre.","请把早餐记在房账上。"],["Je demande la note, s'il vous plaît.","麻烦给我账单。"]],"co":[["mettre sur la note","记在账单上"],["demander la note","要账单"],["la note de chambre","房账"],["régler la note","结账"]],"sy":[["l'addition","courant","餐厅账单（餐厅里更常用）"],["la facture","courant","发票、账单（购物）"]],"fq":"中频，酒店和旅行话题常用。","me":"note = 账单：一起「记」在 la note 上。","tr":{"zh":"请把早餐记在房账上。","fr":"Mettez le petit-déjeuner sur la note de la chambre, s'il vous plaît.","alt":"Vous pouvez mettre ça sur ma note ?","note":"酒店、餐厅的账单：la note。"}},
 "Trouver le temps long": {"pos":"loc. verbale（trouver 为第一组动词，助动词 avoir：je trouve, j'ai trouvé）；固定说法，long 保持阳性单数","s":"觉得时间过得慢，觉得无聊难熬：Je trouve le temps long. 常用在等待或闲着没事的时候。主语不同，动词变，le temps long 不变。","ipa":"[tʁu.ve.lə.tɑ̃.lɔ̃]","ph":"trouver 读 [tʁu.ve]，ou [u]，-er [e]；temps 读 [tɑ̃]，p、s 不发音；long 读 [lɔ̃]，g 不发音。","pi":"temps 的 ps 不读；long 的 g 不读；是阳性单数：le temps long（不要写 longue）。","et":"temps 来自拉丁语 tempus；long 来自拉丁语 longus；trouver 的来源不确定。","ex":[["Je commence à trouver le temps long.","我开始觉得时间难熬。"],["Elle trouve le temps long sans lui.","没有他，她觉得时间过得很慢。"],["Les enfants trouvent le temps long dans le train.","孩子们在火车上觉得时间很长。"]],"co":[["trouver le temps long","觉得时间难熬"],["le temps me semble long","我觉得时间过得慢"],["ne pas voir le temps passer","没注意时间过去（反义）"]],"sy":[["s'ennuyer","courant","无聊"],["ne pas voir le temps passer","courant","反义：不觉得时间过去"],["languir","littéraire","苦苦等待、憔悴"]],"fq":"中频，口语里常用。","me":"时间 temps 变得 long：长 = 难熬。","tr":{"zh":"等了一个小时，我觉得时间太长了。","fr":"Après une heure d'attente, je trouve le temps long.","alt":"Une heure à attendre, le temps me paraît long.","note":"le temps long 固定，long 不变。"}},
 "Un saut en parachute / Sauter en parachute": {"pos":"n.m. / loc. verbale 阳性名词 saut（复数 sauts）；sauter 为第一组动词，助动词 avoir：je saute, j'ai sauté","s":"跳伞：un saut en parachute（一次跳伞）；sauter en parachute（跳伞这个动作）。也可以说 faire un saut en parachute 或 faire du parachutisme（跳伞运动）。","ipa":"[so.ɑ̃.pa.ʁa.ʃyt]","ph":"saut 读 [so]，au [o]，t 不读；en 读 [ɑ̃]；parachute 读 [pa.ʁa.ʃyt]，ch [ʃ]，u [y]，结尾 -e 不读；saut 和 en 之间不连读。","pi":"saut 的 t 不读；parachute 里 u 是 [y]，不是 [u]。","et":"parachute 是十八世纪造的词，para-（来自意大利语 parare「防御」）+ chute（掉落）。saut 来自拉丁语 saltus，sauter 来自 saltare。","ex":[["Je veux faire un saut en parachute.","我想跳伞。"],["Il a sauté en parachute pour la première fois.","他第一次跳伞。"],["Un saut en parachute, c'est un peu effrayant.","跳伞有点吓人。"]],"co":[["faire un saut en parachute","跳伞一次"],["sauter en parachute","跳伞"],["faire du parachutisme","玩跳伞运动"],["un saut en tandem","双人跳伞"]],"sy":[["parachutisme","courant","跳伞（运动）"],["saut à l'élastique","courant","蹦极（不同）"]],"fq":"中频，运动和冒险话题常用。","me":"para（防）+ chute（落）：防止掉落的伞。","tr":{"zh":"我想明年去跳伞。","fr":"Je veux faire un saut en parachute l'an prochain.","alt":"L'année prochaine, j'aimerais sauter en parachute.","note":"faire un saut = 跳一次。"}},
 "(Secteur) Le bien être": {"pos":"n.m. 阳性名词（正确拼写 le bien-être），通常不加复数","s":"幸福感，身心舒适，健康；也指「健康福祉」行业：le secteur du bien-être（美容、按摩、瑜伽、水疗等）。反义词是 le mal-être（不适、焦虑）。","ipa":"[bjɛ̃.nɛtʁ]","ph":"bien 读 [bjɛ̃]，鼻化；être 读 [ɛtʁ]；bien 和 être 之间会连读出一个 [n]：[bjɛ̃.nɛtʁ]。","pi":"bien-être 中间有连字符，要写 bien-être；ê 读 [ɛ]；中间的 n 来自连读。","et":"由 bien（好）+ être（存在、状态）构成，名词化的合成词。反义：mal-être。","ex":[["Le bien-être est important au travail.","工作中的幸福感很重要。"],["Elle travaille dans le secteur du bien-être.","她在健康福祉行业工作。"],["Un massage, c'est bon pour le bien-être.","按摩对身心舒适有好处。"]],"co":[["le secteur du bien-être","健康福祉行业"],["le bien-être au travail","职场幸福感"],["un centre de bien-être","养生中心"],["le bien-être animal","动物福利"]],"sy":[["confort","courant","舒适"],["épanouissement","soutenu","身心的充分发展"],["mal-être","courant","反义：不适、焦虑"]],"fq":"中频，健康和职场话题常用。","me":"bien + être = 「好好地存在」：身心都好。","tr":{"zh":"她在健康福祉行业工作。","fr":"Elle travaille dans le secteur du bien-être.","alt":"Elle bosse dans le bien-être.","note":"secteur 后用 du：le secteur du bien-être。"}},
 "(Secteur) Le nettoyage": {"pos":"n.m. 阳性名词，复数 nettoyages","s":"清洁，打扫；也指「清洁业」：le secteur du nettoyage。nettoyage 是动作或行业，打扫房间时说 faire le ménage 更口语。","ipa":"[nɛ.twa.jaʒ]","ph":"ne- 读 [nɛ]；tt 一个 [t]；oy 读 [waj]；-age 读 [aʒ]，g 读 [ʒ]。","pi":"oy 读 [waj]，不是「oi」；tt 双写、只读一个；-age 结尾 e 不读。","et":"由 nettoyer（清洁）+ -age 构成；nettoyer 来自 net（干净的，拉丁语 nitidus「闪亮的」）。同族词：net、nettement。","ex":[["Cette entreprise travaille dans le nettoyage.","这家公司做清洁业。"],["Le nettoyage de la maison prend deux heures.","打扫房子要花两个小时。"],["J'apporte ce manteau au nettoyage à sec.","我把这件大衣送去干洗。"]],"co":[["le secteur du nettoyage","清洁行业"],["le nettoyage à sec","干洗"],["un produit de nettoyage","清洁产品"],["le grand nettoyage de printemps","春季大扫除"]],"sy":[["ménage","courant","家务、打扫"],["entretien","courant","维护、保养"],["propreté","courant","清洁（状态）"]],"fq":"中频，工作话题常用。","me":"net = 干净，+ -oyer + -age：「让它变干净」这件事。","tr":{"zh":"她在清洁公司工作。","fr":"Elle travaille dans une entreprise de nettoyage.","alt":"Elle bosse dans le nettoyage.","note":"entreprise de + 名词：做……的公司。"}},
 "(Secteur) Le numérique": {"pos":"n.m. 阳性名词（也是形容词 numérique）","s":"数字产业，数字技术：le secteur du numérique = 互联网、软件、数字服务。也作形容词：une photo numérique（数码照片）。注意：digital 在法语中指「手指的」，不是「数字的」。","ipa":"[ny.me.ʁik]","ph":"u 读 [y]；é [e]；r [ʁ]；qu 读 [k]；结尾 -e 不读。","pi":"false friend：数字化要说 numérique，而不是 digital（digital = 手指的：une empreinte digitale 指纹）。u 读 [y]。","et":"来自 nombre / numéro 的词根，拉丁语 numerus（数）加 -ique。同族词：numéro、numéroter。","ex":[["Le secteur du numérique évolue vite.","数字行业发展很快。"],["J'ai un appareil photo numérique.","我有一台数码相机。"],["Elle travaille dans le numérique.","她在数字行业工作。"]],"co":[["le secteur du numérique","数字产业"],["la transition numérique","数字化转型"],["une photo numérique","数码照片"],["le numérique éducatif","教育数字化"]],"sy":[["informatique","courant","信息技术（更传统）"],["digital","courant","（营销界）数字的，借自英语"],["analogique","courant","反义：模拟的"]],"fq":"高频，工作和科技话题常用。","me":"numérique ← numerus：用「数字」表示。","tr":{"zh":"我想在数字行业工作。","fr":"Je voudrais travailler dans le numérique.","alt":"J'aimerais bosser dans le numérique.","note":"dans le numérique：在数字行业。"}},
 "(Secteur) Le sport": {"pos":"n.m. 阳性名词，复数 sports","s":"体育，运动：faire du sport（做运动），le monde du sport（体育界）。作行业时指体育产业：教练、俱乐部、体育用品。","ipa":"[spɔʁ]","ph":"sp [sp]；o 读 [ɔ]；r 读 [ʁ]；结尾 -t 不发音，读 [spɔʁ]。","pi":"sport 结尾的 t 不读（这是法语和英语的区别）；开头 sp 之间不要加 [ə]。","et":"来自古法语 desport（消遣），十九世纪经英语 sport 再回到法语。","ex":[["Il travaille dans le monde du sport.","他在体育界工作。"],["Je fais du sport trois fois par semaine.","我每周运动三次。"],["Quel sport tu préfères ?","你最喜欢什么运动？"]],"co":[["faire du sport","做运动"],["le monde du sport","体育界"],["un sport d'équipe","团体运动"],["un sportif / une sportive","运动员；爱运动的人"]],"sy":[["activité physique","courant","体育活动"],["jeu","courant","游戏"],["compétition","courant","比赛"]],"fq":"极高频，日常常用。","me":"sport 和英语 sport 一样，但 t 不读。","tr":{"zh":"他在体育行业工作。","fr":"Il travaille dans le monde du sport.","alt":"Il bosse dans le sport.","note":"faire du sport：不用 le sport。"}},
 "(Secteur) Le tourisme": {"pos":"n.m. 阳性名词，复数 tourismes（少用）","s":"旅游业，旅游：le secteur du tourisme，le tourisme de masse（大众旅游）。也指「旅游活动」。人是 un touriste，形容词是 touristique。","ipa":"[tu.ʁism]","ph":"ou [u]；r [ʁ]；-is- 读 [is]；-me 读 [m]，结尾 e 不发音。","pi":"ou 读 [u]；结尾 -sme 要读出 [sm]：[tu.ʁism]；ur 里 r 是喉音。","et":"十九世纪借自英语 tourism，词根 tour（环游，来自古法语 tour，意为「一圈、转动」）。同族词：touriste、touristique、tour。","ex":[["Le tourisme est important pour l'économie.","旅游业对经济很重要。"],["Il travaille dans le tourisme.","他在旅游业工作。"],["Le tourisme de masse abîme certains sites.","大众旅游破坏了某些景点。"]],"co":[["le secteur du tourisme","旅游业"],["l'office de tourisme","旅游局"],["le tourisme de masse","大众旅游"],["le tourisme vert","生态旅游"]],"sy":[["voyage","courant","旅行（个人）"],["hôtellerie","courant","酒店业"],["loisirs","courant","休闲活动"]],"fq":"高频，旅行和经济话题常用。","me":"tour（一圈）+ -isme：绕着地方转的活动。","tr":{"zh":"旅游业对这个地区很重要。","fr":"Le tourisme est très important pour cette région.","alt":"Le tourisme compte beaucoup pour cette région.","note":"tourisme 有 -sme 结尾。"}},
 "Le baccalauréat (bac)": {"pos":"n.m. 阳性名词，复数 baccalauréats（口语 bac，复数 bacs）","s":"高中毕业会考，法国的中学毕业文凭，相当于中国高考加毕业证书（但不是选拔性考试）。passer son bac = 参加会考；avoir / réussir son bac = 通过会考。","ipa":"[ba.ka.lɔ.ʁe.a]","ph":"cc 读 [k]（a 前）；au 读 [ɔ]；é [e]；结尾 -at 读 [a]，t 不发音。口语 bac 读 [bak]。","pi":"passer 在这里是「参加」，不是「通过」：passer le bac ≠ réussir le bac。结尾 -at 的 t 不读。","et":"来自中世纪拉丁语 baccalaureus（获得初级学位的人）。英语 baccalaureate、bachelor 同源。","ex":[["J'ai passé mon bac l'année dernière.","我去年参加了高考。"],["Elle a eu son bac avec mention.","她以优良成绩通过了会考。"],["Après le bac, il veut aller à l'université.","会考之后，他想上大学。"]],"co":[["passer le bac","参加会考"],["avoir / réussir son bac","通过会考"],["rater son bac","没通过会考"],["un bac pro / général","职业类 / 普通类会考"]],"sy":[["bac","familier","口语缩写"],["diplôme","courant","文凭"],["examen","courant","考试"]],"fq":"高频，教育话题常用。","me":"bac = 简称；passer le bac = 去考，不等于「过」。","tr":{"zh":"我明年参加会考。","fr":"Je passe le bac l'année prochaine.","alt":"L'année prochaine, je passe mon bac.","note":"passer le bac = 参加；réussir = 通过。"}},
 "Le coworking": {"pos":"n.m. 阳性名词，复数 coworkings（英语借词）","s":"共享办公：一个多人共用的办公空间，自由职业者和创业者常用。常说 un espace de coworking。也可以指这种工作方式。","ipa":"[ko.wɔʁ.kiŋ]","ph":"co [ko]；work 读 [wɔʁk]；-ing 读 [iŋ]，ng 是鼻音 [ŋ]（和英语一样）。","pi":"英语借词，读音接近英语；co 读 [ko]，不是 [kɔ̃]；结尾 -ing 是 [iŋ]。","et":"借自英语 coworking（co- 共同 + working 工作）。官方建议的法语说法是 espace de travail partagé。","ex":[["Je travaille dans un espace de coworking.","我在共享办公空间工作。"],["Le coworking est pratique pour les freelances.","共享办公对自由职业者很方便。"],["Il y a un coworking près de la gare.","火车站旁边有一个共享办公空间。"]],"co":[["un espace de coworking","共享办公空间"],["travailler en coworking","在共享空间办公"],["louer un bureau en coworking","租共享办公位"]],"sy":[["espace de travail partagé","courant","官方法语说法"],["bureau partagé","courant","共享办公室"],["télétravail","courant","远程办公（不同）"]],"fq":"中频，工作话题新兴常用。","me":"co（共同）+ working（工作）：一起工作的地方。","tr":{"zh":"我在共享办公空间工作。","fr":"Je travaille dans un espace de coworking.","alt":"Je bosse dans un coworking.","note":"espace de coworking 也可直接说 un coworking。"}},
 "Le permis de conduire": {"pos":"n.m. 阳性名词，复数 permis de conduire（permis 单复数同形）","s":"驾照：passer le permis（考驾照），avoir / obtenir son permis（拿到驾照），rater son permis（没考过）。口语常省略成 le permis。","ipa":"[pɛʁ.mi.də.kɔ̃.dɥiʁ]","ph":"permis 读 [pɛʁ.mi]，s 不发音；conduire 读 [kɔ̃.dɥiʁ]，on 鼻化，ui [ɥi]。","pi":"permis 结尾的 s 不读；ui 读 [ɥi]；复数是 des permis（s 不变）。","et":"permis 是 permettre 的过去分词（拉丁语 permittere）；conduire 来自拉丁语 conducere（带领）。字面意思「被许可开车」。","ex":[["Il vient d'obtenir son permis de conduire.","他刚拿到驾照。"],["Elle passe son permis demain.","她明天考驾照。"],["J'ai raté mon permis la première fois.","我第一次没考过驾照。"]],"co":[["passer le permis","考驾照"],["avoir / obtenir son permis","拿到驾照"],["rater son permis","没考过驾照"],["perdre des points de permis","被扣驾照分"]],"sy":[["le permis","familier","口语简称"],["la conduite","courant","驾驶（动作）"],["l'auto-école","courant","驾校"]],"fq":"高频，日常常用。","me":"permis（被许可的）+ conduire（开车）：被允许开车的证。","tr":{"zh":"他明天考驾照。","fr":"Il passe son permis de conduire demain.","alt":"Il passe son permis demain.","note":"passer 在这里是「参加考试」。"}},
 "Le SMIC": {"pos":"n.m. 阳性名词（首字母缩略词），复数 smics（少用）","s":"法国最低工资（Salaire Minimum Interprofessionnel de Croissance）。口语里说 être au SMIC =「拿最低工资」。是一个常用的社会话题。","ipa":"[smik]","ph":"整个当一个词读 [smik]：s-m-i-k，一个音节，不是逐个字母读。","pi":"不要逐字母读 S-M-I-C，要连成 [smik]；开头 sm 无元音。","et":"缩略词，来自 Salaire Minimum Interprofessionnel de Croissance（1970 年起）。smicard(e) 指拿最低工资的人（口语）。","ex":[["Il gagne le SMIC.","他拿最低工资。"],["Le SMIC augmente en janvier.","最低工资一月上涨。"],["Beaucoup de gens sont payés au SMIC.","很多人拿最低工资。"]],"co":[["gagner le SMIC","拿最低工资"],["être payé au SMIC","按最低工资付酬"],["le SMIC horaire","最低小时工资"],["augmenter le SMIC","提高最低工资"]],"sy":[["salaire minimum","courant","最低工资（泛称）"],["smicard","familier","拿最低工资的人"]],"fq":"高频，工作和社会话题常用。","me":"SMIC 读 [smik]：像一个单词，不是字母。","tr":{"zh":"他每个月拿最低工资。","fr":"Il gagne le SMIC chaque mois.","alt":"Il est payé au SMIC.","note":"SMIC 前用 le。"}},
 "Le télétravail": {"pos":"n.m. 阳性名词，复数 télétravaux（少用）","s":"远程办公，在家上班：faire du télétravail，être en télétravail。动词是 télétravailler，人是 un télétravailleur。","ipa":"[te.le.tʁa.vaj]","ph":"té [te]；lé [le]；tra [tʁa]；-vail 读 [vaj]，ai 读 [a]，il 读 [j]。","pi":"-ail 读 [aj]，l 不读成 [l]；téle- 两个 é 都是 [e]；不要把 tra 读成 [tʁɑ]。","et":"由 télé-（希腊语 tēle「远」）+ travail（工作）构成。travail 常认为来自俗拉丁语 tripalium。","ex":[["Le télétravail est très pratique.","远程办公很方便。"],["Je suis en télétravail deux jours par semaine.","我每周有两天远程办公。"],["Elle préfère le télétravail au bureau.","她更喜欢远程办公而不是去办公室。"]],"co":[["faire du télétravail","远程办公"],["être en télétravail","在远程办公"],["télétravailler deux jours par semaine","每周远程办公两天"],["le télétravail à domicile","在家远程办公"]],"sy":[["travail à distance","courant","远程工作"],["travail à domicile","courant","在家工作"],["présentiel","courant","反义：到场办公"]],"fq":"高频，工作话题常用。","me":"télé（远）+ travail：隔得远的工作。","tr":{"zh":"我每周有三天在家办公。","fr":"Je fais du télétravail trois jours par semaine.","alt":"Je télétravaille trois jours par semaine.","note":"faire du télétravail 或 télétravailler。"}},
 "Un bandit": {"pos":"n.m. 阳性名词，复数 bandits","s":"强盗，歹徒；也可以半开玩笑地叫调皮的小孩：petit bandit。un bandit manchot =「老虎机」（字面：独臂强盗）。","ipa":"[bɑ̃.di]","ph":"ban 读鼻化元音 [bɑ̃]；di 读 [di]；结尾 -t 不发音。","pi":"结尾 t 不读（不是英语 bandit 的 [t]）；ban 是 [bɑ̃]，不是「ban」。","et":"来自意大利语 bandito（被放逐、被禁的人），源自 bandire「宣布驱逐」。同族词：bannir（驱逐）。","ex":[["Les bandits ont attaqué la banque.","强盗袭击了银行。"],["Petit bandit, rends-moi mon jouet !","小淘气，把我的玩具还给我！"],["Dans ce film, le bandit est très drôle.","这部电影里的强盗很搞笑。"]],"co":[["un bandit de grand chemin","拦路强盗"],["un bandit manchot","老虎机"],["un petit bandit","小淘气（亲昵）"],["arrêter un bandit","抓捕歹徒"]],"sy":[["voleur","courant","小偷"],["brigand","littéraire","土匪"],["malfaiteur","soutenu","歹徒"]],"fq":"中频，故事和电影话题常用。","me":"bandit ← 被 banni（放逐）的人。","tr":{"zh":"警察抓到了这个歹徒。","fr":"La police a arrêté le bandit.","alt":"La police a attrapé ce bandit.","note":"bandit 结尾 t 不读。"}},
 "Un concours": {"pos":"n.m. 阳性名词，复数 concours（单复数同形）","s":"比赛；选拔考试：un concours de dessin（绘画比赛），passer un concours（参加选拔考试）。在法国，concours 常指录取名额有限的竞争性考试（如进入大学校）。","ipa":"[kɔ̃.kuʁ]","ph":"con 读鼻化 [kɔ̃]；cours 读 [kuʁ]，ou [u]，结尾 -s 不发音。","pi":"结尾 s 不读；concours 单复数同形；不是 course（赛跑）。","et":"来自拉丁语 concursus（聚集、一起跑），con-（共同）+ currere（跑）。同族词：cours、courir。","ex":[["Elle a gagné un concours de dessin.","她赢了一个绘画比赛。"],["Il prépare un concours pour entrer dans une école.","他准备选拔考试，想进一所学校。"],["Le concours a lieu en juin.","选拔考试在六月举行。"]],"co":[["gagner un concours","赢得比赛"],["passer / préparer un concours","参加 / 备考选拔考试"],["un concours de beauté","选美比赛"],["un concours d'entrée","入学选拔考试"]],"sy":[["compétition","courant","竞赛"],["épreuve","courant","考试项目、比赛项目"],["examen","courant","考试"]],"fq":"高频，学习和比赛话题常用。","me":"con + cours：大家一起「跑」，看谁赢。","tr":{"zh":"她准备参加一个选拔考试。","fr":"Elle prépare un concours.","alt":"Elle se prépare pour un concours.","note":"préparer un concours = 备考。"}},
 "Un contrôle": {"pos":"n.m. 阳性名词，复数 contrôles","s":"测验，小考（学校）；检查，查验（警察、车票、安检）；控制（contrôle de soi）。Nous avons un contrôle de maths = 我们有数学小测。","ipa":"[kɔ̃.tʁol]","ph":"con 读鼻化 [kɔ̃]；ô 读 [o]；l 读 [l]；整体 [kɔ̃.tʁol]。","pi":"ô 读 [o]，不是 [ɔ]；法语 contrôle 比英语 control 多一个重音符号 ô，意思更多（测验、检查）。","et":"来自古法语 contrerolle（副本登记册），contre-（相对）+ rôle（登记册）。同族词：contrôler。","ex":[["Nous avons un contrôle de mathématiques demain.","我们明天有数学测验。"],["La police fait un contrôle sur la route.","警察在路上查车。"],["Le contrôle des billets commence dans le train.","火车上开始查票。"]],"co":[["un contrôle de maths","数学小测"],["un contrôle d'identité","身份检查"],["un contrôle de police","警察检查"],["perdre le contrôle","失控"]],"sy":[["interrogation écrite","courant","小测（学校用语）"],["vérification","courant","核查"],["examen","courant","考试（比 contrôle 更大）"]],"fq":"高频，学习和日常常用。","me":"contrôle：不只是控制，也是学校的小测和各种检查。","tr":{"zh":"我们明天有历史测验。","fr":"Nous avons un contrôle d'histoire demain.","alt":"On a un contrôle d'histoire demain.","note":"avoir un contrôle = 有测验。"}},
 "Un doctorat": {"pos":"n.m. 阳性名词，复数 doctorats","s":"博士学位，博士课程：faire un doctorat（读博），préparer un doctorat。读博的人是 un(e) doctorant(e)，已获得博士学位的是 un docteur / une doctoresse。","ipa":"[dɔk.tɔ.ʁa]","ph":"doc 读 [dɔk]；to 读 [tɔ]；ra 读 [ʁa]；结尾 -t 不发音。","pi":"结尾 -at 的 t 不读，不是 [dɔk.tɔ.ʁat]；不要和 doctrine 混淆。","et":"由 docteur（拉丁语 doctor，「教师」，源自 docere「教」）+ -at（表示职位、学位）构成。同族词：doctorant、doctrine。","ex":[["Il fait un doctorat en biologie.","他在读生物学博士。"],["Elle a obtenu son doctorat l'an dernier.","她去年获得了博士学位。"],["Un doctorat dure trois ans en France.","在法国，博士课程为期三年。"]],"co":[["faire un doctorat en + 学科","读某学科博士"],["préparer / obtenir un doctorat","读博 / 取得博士学位"],["une thèse de doctorat","博士论文"],["un diplôme de doctorat","博士文凭"]],"sy":[["thèse","courant","论文（博士论文）"],["PhD","courant","英语说法（学术圈常用）"],["master","courant","硕士"]],"fq":"中频，学习话题常用。","me":"doctor + -at：成为 docteur 的学位。","tr":{"zh":"她在读法学博士。","fr":"Elle fait un doctorat en droit.","alt":"Elle prépare une thèse de droit.","note":"faire un doctorat en + 学科。"}},
 "Un entretien d'embauche": {"pos":"n.m. 阳性名词词组，复数 entretiens d'embauche","s":"面试，招聘面试。entretien 本身指「谈话、会谈」，也指「保养、维护」（entretien d'une voiture）。passer un entretien = 参加面试。","ipa":"[ɑ̃.tʁə.tjɛ̃.dɑ̃.boʃ]","ph":"entretien 读 [ɑ̃.tʁə.tjɛ̃]，en 鼻化 [ɑ̃]，-tien 读 [tjɛ̃]；d'embauche 读 [dɑ̃.boʃ]，em 鼻化 [ɑ̃]，au [o]，ch [ʃ]。","pi":"entretien 和 embauche 开头都是 [ɑ̃]；ien 读 [jɛ̃]；embauche 的 ch 读 [ʃ]。","et":"entretien 来自 entretenir（保持，维持）；embauche 来自 embaucher（雇用），来源不确定。","ex":[["J'ai un entretien d'embauche demain matin.","我明天早上有面试。"],["Elle prépare son entretien d'embauche.","她在准备面试。"],["Il a réussi son entretien d'embauche.","他面试成功了。"]],"co":[["passer un entretien d'embauche","参加面试"],["préparer un entretien","准备面试"],["décrocher un entretien","争取到面试机会"],["un entretien avec le directeur","与经理的面谈"]],"sy":[["entretien","courant","面谈（省略说法）"],["interview","courant","采访"],["rendez-vous","courant","约会、会面"]],"fq":"高频，工作话题常用。","me":"entretien d'embauche = 为被「雇用」的「谈话」。","tr":{"zh":"我下周有一个面试。","fr":"J'ai un entretien d'embauche la semaine prochaine.","alt":"La semaine prochaine, je passe un entretien d'embauche.","note":"avoir un entretien = 有面试。"}},
 "Un marché de Noël": {"pos":"n.m. 阳性名词词组，复数 marchés de Noël","s":"圣诞市集：十二月在广场上摆的小木屋集市，卖手工艺品、热红酒、小吃。斯特拉斯堡的圣诞市集特别有名。","ipa":"[maʁ.ʃe.də.nɔ.ɛl]","ph":"marché 读 [maʁ.ʃe]，ch [ʃ]，é [e]；Noël 读 [nɔ.ɛl]，ë 单独读成 [ɛl]（trema）。","pi":"Noël 的 ë 上面有两点，表示 o 和 ë 分开读：[nɔ.ɛl]；marché 结尾 é 读 [e]，不是 [ɛ]。","et":"marché 来自拉丁语 mercatus（市场）；Noël 来自拉丁语 natalis（出生的），指耶稣诞生日。","ex":[["J'adore me promener au marché de Noël.","我爱逛圣诞市集。"],["Nous buvons du vin chaud au marché de Noël.","我们在圣诞市集喝热红酒。"],["Le marché de Noël ouvre en décembre.","圣诞市集十二月开始。"]],"co":[["aller au marché de Noël","去圣诞市集"],["boire du vin chaud","喝热红酒"],["un chalet de marché de Noël","圣诞市集的小木屋"],["un cadeau de Noël","圣诞礼物"]],"sy":[["foire","courant","集市"],["marché","courant","市场"],["village de Noël","courant","圣诞小镇"]],"fq":"中频，冬季话题常用。","me":"Noël 的 ë：两点提醒 o 与 ë 分开读。","tr":{"zh":"我们十二月去逛圣诞市集。","fr":"En décembre, nous allons au marché de Noël.","alt":"En décembre, on va au marché de Noël.","note":"Noël 首字母大写。"}},
 "Un master (M1, M2)": {"pos":"n.m. 阳性名词，复数 masters（英语借词，M1 / M2 = 硕士第一 / 第二年）","s":"硕士学位，硕士课程：faire un master，M1 是第一年，M2 是第二年。法国学制：licence（三年）、master（两年）、doctorat（三年）。","ipa":"[mas.tɛʁ]","ph":"ma 读 [mas]；ter 读 [tɛʁ]，e 读 [ɛ]，r 要发音：[mas.tɛʁ]。","pi":"结尾 -er 在这里读 [ɛʁ]，不是 [e]，和 -er 动词不同；法语 master 是读 [mas.tɛʁ]，不是英语 [ˈmæstər]。","et":"借自英语 master's degree，英语 master 来自拉丁语 magister（老师）。2002 年起法国学制采用 LMD（licence-master-doctorat）。","ex":[["Elle prépare un master en droit.","她在读法学硕士。"],["Il est en M2 de biologie.","他读生物学硕士二年级。"],["Après la licence, elle fait un master.","读完学士之后，她读硕士。"]],"co":[["faire un master en + 学科","读某学科硕士"],["être en M1 / en M2","读硕一 / 硕二"],["un master de droit","法学硕士"],["un diplôme de master","硕士文凭"]],"sy":[["maîtrise","courant","旧制硕士一年级学位"],["licence","courant","学士（三年）"],["mastère","courant","（大学校）专业硕士"]],"fq":"高频，教育话题常用。","me":"master = 硕士：M1 + M2 = 两年。","tr":{"zh":"她今年读硕士二年级。","fr":"Elle est en M2 cette année.","alt":"Cette année, elle fait son master 2.","note":"être en M2 = 读硕二。"}},
 "Un ministre": {"pos":"n.m. 阳性名词，复数 ministres（女部长常说 la ministre）","s":"部长；政府部门的首长。le Premier ministre = 总理。也指宗教里的牧师（较少见）。","ipa":"[mi.nistʁ]","ph":"mi-nistre：s 读 [s]，结尾 -tre 读 [tʁ]，e 不发音。","pi":"结尾 -stre 要连着读 [stʁ]，中间别加元音；两个 i 都是 [i]。","et":"拉丁语 minister（仆人、助手）。同源：administrer（管理）。","ex":[["Le ministre a fait un discours.","部长发表了讲话。"],["Le ministre de l'Éducation visite l'école.","教育部长参观学校。"]],"co":[["le Premier ministre","总理"],["le ministre de la Santé","卫生部长"],["un conseil des ministres","内阁会议"]],"sy":[["secrétaire d'État","courant","国务秘书（级别低于部长）"],["ministère","courant","部（机构），不是人"]],"fq":"中频，新闻里常见。","me":"minister 看起来像英语 minister，意思也一样：为国家「服务」的人。","tr":{"zh":"部长今天下午会见记者。","fr":"Le ministre rencontre les journalistes cet après-midi.","alt":"Le ministre voit les journalistes cet après-midi.","note":"ministre 阳性；女部长可说 la ministre。"}},
 "Un porte-bagage": {"pos":"n.m. 阳性名词，复数 porte-bagages（也常写 porte-bagage）","s":"行李架：火车、公交车上方的架子，也指自行车、摩托车后座的货架。","ipa":"[pɔʁt.ba.gaʒ]","ph":"porte [pɔʁt]；bagage：g 在 a 前读 [g]，结尾 -age 读 [aʒ]。","pi":"bagage 的 g 读 [g]，最后的 ge 读 [ʒ]，一个词里两个 g 读音不同。","et":"porter（带、扛）+ bagage（行李），复合词：「扛行李的东西」。","ex":[["J'ai mis mon sac sur le porte-bagage.","我把包放在行李架上。"],["Le vélo a un porte-bagage à l'arrière.","这辆自行车后面有个货架。"]],"co":[["un porte-bagage de vélo","自行车货架"],["un porte-bagages de toit","车顶行李架"],["mettre sa valise sur le porte-bagage","把行李箱放到行李架上"]],"sy":[["galerie","courant","车顶行李架"],["filet à bagages","courant","火车座位上方的行李网"]],"fq":"中低频，旅行时会用到。","me":"porte（拿）+ bagage（行李）= 拿行李的架子。","tr":{"zh":"请把你的箱子放到行李架上。","fr":"Mets ta valise sur le porte-bagage, s'il te plaît.","alt":"Pose ta valise sur le porte-bagage.","note":"sur le porte-bagage：放在架子「上」用 sur。"}},
 "Un secteur d'activité": {"pos":"n.m. 阳性名词，复数 secteurs d'activité","s":"行业领域；经济或职业的分支，如医疗、餐饮、信息技术。单说 un secteur 也可以，意思是「部门、区域」。","ipa":"[sɛk.tœʁ da.kti.vi.te]","ph":"secteur：-eur [œʁ]；d'activité 里 d' 与 activité 连读：[da.kti.vi.te]；-té 读 [te]。","pi":"secteur 结尾 -eur 读 [œʁ]，r 要发；activité 的 c 读 [k]，t 读 [t]，结尾 é [e]。","et":"secteur 来自拉丁语 sector（切割者），源于 secare（切）。activité 来自 actif（活跃的）+ -ité。","ex":[["Il travaille dans le secteur de la santé.","他在医疗行业工作。"],["Quel est ton secteur d'activité ?","你做哪个行业？"]],"co":[["dans le secteur de + 名词","在……行业"],["changer de secteur","换行业"],["le secteur privé / public","私营 / 公共部门"]],"sy":[["domaine","courant","领域，更宽泛"],["branche","courant","分支、行业"]],"fq":"中频，求职与职场常用。","me":"secteur = 切出来的一块（secare 切），一块「行业」。","tr":{"zh":"我想换一个行业。","fr":"Je voudrais changer de secteur d'activité.","alt":"J'aimerais travailler dans un autre secteur.","note":"changer de + 名词（不带冠词）。"}},
 "Un sentier": {"pos":"n.m. 阳性名词，复数 sentiers","s":"小径；山间或林中的窄路，常指徒步用的小路。le sentier de randonnée = 徒步路线。","ipa":"[sɑ̃.tje]","ph":"s [s]；en 读鼻化音 [ɑ̃]；-tier 读 [tje]，r 不发音。","pi":"结尾 -ier 读 [je]，r 是哑音；en 是 [ɑ̃]，不是 [ɛ̃]。","et":"来自古法语 sente（小路），源于拉丁语 semita（小道）。","ex":[["Nous marchons sur un petit sentier.","我们走在一条小路上。"],["Ce sentier traverse la forêt.","这条小径穿过森林。"]],"co":[["un sentier de montagne","山间小路"],["suivre le sentier","沿着小路走"],["quitter les sentiers battus","走新路，不走老路"]],"sy":[["chemin","courant","路，比 sentier 宽"],["route","courant","公路"]],"fq":"中频。","me":"sentier 与 sentir 很像：用脚「感受」的小路。","tr":{"zh":"我们沿着小路上山。","fr":"Nous montons la colline par le sentier.","alt":"On monte la colline par le petit chemin.","note":"par le sentier：走某条路用 par。"}},
 "(Matière) L'EPS": {"pos":"n.f. 阴性名词（缩写，la EPS → l'EPS）","s":"体育课；全称 éducation physique et sportive。学校科目。口语常直接说 le sport。","ipa":"[ø.pe.ɛs]","ph":"按字母读：E [ø]，P [pe]，S [ɛs]。","pi":"E 在法语字母里读 [ø]，不是英语的 [i]；缩写前用 l'，但性别是阴性（éducation）。","et":"缩写：Éducation Physique et Sportive。éducation 来自拉丁语 educatio；physique 来自希腊语 physis（自然）。","ex":[["L'EPS est obligatoire à l'école.","学校的体育课是必修的。"],["On a EPS le jeudi matin.","我们周四上午有体育课。"]],"co":[["un cours d'EPS","一节体育课"],["un prof d'EPS","体育老师"],["avoir EPS","有体育课"]],"sy":[["le sport","familier","体育课（口语）"],["la gym","familier","体操、体育课"]],"fq":"学校里高频，其他场合少见。","me":"E-P-S：「欧 - 贝 - 艾斯」，按法语字母念。","tr":{"zh":"我们今天下午有体育课。","fr":"Nous avons EPS cet après-midi.","alt":"On a sport cet après-midi.","note":"avoir EPS：科目名前通常不加冠词。"}},
 "(Secteur) L'informatique": {"pos":"n.f. 阴性名词，无复数（常用单数）","s":"信息技术；计算机科学；IT 行业。faire de l'informatique = 搞电脑相关工作或学习。注意：「电脑」本身是 un ordinateur。","ipa":"[ɛ̃.fɔʁ.ma.tik]","ph":"in 读鼻化音 [ɛ̃]；-que 读 [k]，e 不发音。","pi":"开头 in- 是 [ɛ̃]，不读 [in]；informatique 不是「电脑」，电脑是 ordinateur。","et":"1962 年造的词，由 information + automatique 合成。","ex":[["Il est ingénieur en informatique.","他是信息工程师。"],["Elle fait des études d'informatique.","她在学计算机。"]],"co":[["un ingénieur en informatique","计算机工程师"],["faire de l'informatique","从事 / 学习信息技术"],["un service informatique","IT 部门"]],"sy":[["l'IT","courant","英语借词，职场常用"],["le numérique","courant","数字技术（更宽泛）"]],"fq":"高频，职场和学习都常用。","me":"informatique = information + automatique：自动处理信息。","tr":{"zh":"我哥哥在信息技术行业工作。","fr":"Mon frère travaille dans l'informatique.","alt":"Mon frère bosse dans l'informatique.","note":"dans l'informatique：说行业用 dans。"}},
 "(Secteur) La beauté": {"pos":"n.f. 阴性名词，复数 beautés（常用单数）","s":"美；美貌；美容行业。le secteur de la beauté = 美容业（美发、化妆品、护肤）。une beauté 也可指「美人」。","ipa":"[bo.te]","ph":"eau 读 [o]；-té 读 [te]，结尾 é 是 [e]。","pi":"beau- 里 eau 一起读 [o]，不要分开读；不要把 beauté 和 beau 的阴性 belle 弄混。","et":"来自 beau（美的）+ -té，源于拉丁语 bellus（漂亮）。阴性形容词 belle 同源。","ex":[["Le secteur de la beauté recrute.","美容行业在招人。"],["Elle travaille dans un salon de beauté.","她在一家美容院工作。"]],"co":[["un salon de beauté","美容院"],["un produit de beauté","美容产品"],["un institut de beauté","美容院（较正式）"]],"sy":[["esthétique","courant","美容、美学"],["cosmétique","courant","化妆品"]],"fq":"中高频。","me":"beau（帅、美）+ té：「美」的名词形式。","tr":{"zh":"她想在美容行业工作。","fr":"Elle veut travailler dans la beauté.","alt":"Elle voudrait bosser dans la beauté.","note":"dans la beauté：说行业用 dans。"}},
 "(Secteur) La communication": {"pos":"n.f. 阴性名词，复数 communications","s":"传播；沟通；传媒与公关行业。travailler dans la communication = 做传播、宣传、公关类工作。也指「电话接通」。","ipa":"[kɔ.my.ni.ka.sjɔ̃]","ph":"u 读 [y]；-tion 读 [sjɔ̃]；结尾鼻化。","pi":"-tion 读 [sjɔ̃]，不是 [ʃən]；n 不发，鼻化 [ɔ̃]；u 是 [y]。","et":"来自拉丁语 communicatio，源于 communis（共同的）。同源：commun, commune。","ex":[["Elle travaille dans la communication.","她在传播行业工作。"],["La communication est importante dans un couple.","沟通在夫妻之间很重要。"]],"co":[["une agence de communication","传播公司"],["un responsable communication","传播主管"],["la communication téléphonique","电话通话"]],"sy":[["information","courant","信息"],["relations publiques","courant","公共关系"]],"fq":"高频。","me":"communication = commun（共同）+ 行动：把东西变成「共有」。","tr":{"zh":"我学的是传播专业。","fr":"J'ai fait des études de communication.","alt":"J'ai étudié la communication.","note":"faire des études de + 专业名。"}},
 "(Secteur) La formation": {"pos":"n.f. 阴性名词，复数 formations","s":"培训；教育；学业。la formation continue = 继续教育。也指「成形」。le secteur de la formation = 培训行业。","ipa":"[fɔʁ.ma.sjɔ̃]","ph":"o 读 [ɔ]；-tion 读 [sjɔ̃]；结尾鼻化。","pi":"formation 不是英语 formation（队形），在法语里常指「培训、学业」；-tion 读 [sjɔ̃]。","et":"来自拉丁语 formatio，源于 forma（形状）。同源：former（培养）, forme。","ex":[["La formation continue est très utile.","继续教育很有用。"],["Il suit une formation en cuisine.","他在上烹饪培训班。"]],"co":[["suivre une formation","参加培训"],["la formation professionnelle","职业培训"],["la formation continue","继续教育"]],"sy":[["stage","courant","实习、短期培训"],["enseignement","courant","教学、教育"]],"fq":"高频，职场与教育常用。","me":"formation：把人「塑形」，培养成才。","tr":{"zh":"我想参加一个烹饪培训。","fr":"Je voudrais suivre une formation en cuisine.","alt":"J'aimerais faire une formation de cuisine.","note":"suivre une formation 是固定搭配。"}},
 "(Secteur) La restauration": {"pos":"n.f. 阴性名词，复数 restaurations","s":"餐饮业；餐馆行业。la restauration rapide = 快餐。另有「修复、整修」之意（文物、建筑）。","ipa":"[ʁɛs.to.ʁa.sjɔ̃]","ph":"r 是小舌音 [ʁ]；res- 读 [ʁɛs]；-tion 读 [sjɔ̃]。","pi":"有两个 r [ʁ]，注意发音；不是「餐厅」（餐厅是 un restaurant），而是整个行业。","et":"来自动词 restaurer（恢复），拉丁语 restaurare。restaurant 原指「恢复体力的东西」，同一词根。","ex":[["Il travaille dans la restauration rapide.","他在快餐业工作。"],["La restauration recrute beaucoup en été.","餐饮业夏天招很多人。"]],"co":[["la restauration rapide","快餐"],["la restauration collective","集体餐饮（食堂）"],["travailler dans la restauration","做餐饮"]],"sy":[["l'hôtellerie","courant","酒店业，常与餐饮并说"],["traiteur","courant","外烩、熟食店"]],"fq":"中高频。","me":"restaurant 的名词形式：「让人恢复体力」的行业。","tr":{"zh":"我在餐饮业工作了五年。","fr":"Je travaille dans la restauration depuis cinq ans.","alt":"Ça fait cinq ans que je bosse dans la restauration.","note":"depuis + 时间：持续到现在用现在时。"}},
 "De l'expérience": {"pos":"n.f. 阴性名词，复数 expériences","s":"经验；经历；实验。avoir de l'expérience = 有经验（不可数，用 de l'）。une expérience 也可以是「一次经历」或「一次实验」。","ipa":"[ɛk.spe.ʁjɑ̃s]","ph":"ex- 读 [ɛks]；-ience 读 [jɑ̃s]；en 读鼻化 [ɑ̃]。","pi":"ex- 读 [ɛks]，不是 [ɛgz]；-ience 里 en 读 [ɑ̃]；有「经验」意思时不可数，用 de l'expérience。","et":"拉丁语 experientia，源于 experiri（尝试）。同源：expert（专家）, expérimenter。","ex":[["Il a beaucoup d'expérience dans ce domaine.","他在这个领域经验丰富。"],["C'était une expérience incroyable.","那是一次难以置信的经历。"]],"co":[["avoir de l'expérience","有经验"],["manquer d'expérience","缺乏经验"],["l'expérience professionnelle","工作经验"],["tenter l'expérience","试一试"]],"sy":[["pratique","courant","实践，侧重做过"],["vécu","soutenu","亲身经历"]],"fq":"高频。","me":"expérience 与 expert 同根：多次尝试，才成「专家」。","tr":{"zh":"这个工作需要三年经验。","fr":"Ce poste demande trois ans d'expérience.","alt":"Pour ce poste, il faut trois ans d'expérience.","note":"trois ans d'expérience：时间 + de + 名词。"}},
 "De la mousse au chocolat": {"pos":"n.f. 阴性名词，复数 mousses au chocolat","s":"巧克力慕斯；法国家常甜点。mousse 本意是「泡沫」，也有「苔藓」的意思（另一个词，同形）。不可数时用 de la。","ipa":"[mus o ʃɔ.kɔ.la]","ph":"mousse：ou [u]，ss [s]，e 不发；au 读 [o]；chocolat：ch [ʃ]，结尾 t 不发音。","pi":"chocolat 结尾 t 不发音（[ʃɔ.kɔ.la]）；ou 读 [u]，不是 [mɔs]；不是「慕丝」的 [ʃ]，ch 是 [ʃ]。","et":"mousse 的来源不确定，同族词有 mousser（起泡）、mousseux（起泡的）。chocolat 经西班牙语来自阿兹特克语。","ex":[["J'adore la mousse au chocolat en dessert.","我爱巧克力慕斯做甜点。"],["Maman fait une mousse au chocolat pour le dîner.","妈妈晚餐做了巧克力慕斯。"]],"co":[["une mousse au chocolat maison","自制巧克力慕斯"],["faire une mousse au chocolat","做巧克力慕斯"],["une mousse de saumon","三文鱼慕斯"]],"sy":[["crème au chocolat","courant","巧克力奶油，更稠"],["dessert","courant","甜点"]],"fq":"中频，餐桌和菜单上常见。","me":"mousse = 泡沫：一勺「会呼吸的」巧克力。","tr":{"zh":"我想吃巧克力慕斯。","fr":"Je voudrais de la mousse au chocolat.","alt":"J'ai envie d'une mousse au chocolat.","note":"不可数用 de la；一份用 une mousse。"}},
 "La mort": {"pos":"n.f. 阴性名词，复数 morts（la mort 多用单数）","s":"死亡；死。la mort de quelqu'un = 某人的去世。注意阴阳性：la mort（死亡，阴）和 un mort（死者，阳）是不同的词义。","ipa":"[mɔʁ]","ph":"o 读 [ɔ]；r 读小舌音 [ʁ]；t 不发音。","pi":"mort 结尾的 t 不发音，r 要发 [ʁ]；mort 是阴性（la mort），但作「死者」时是阳性 un mort。","et":"拉丁语 mors, mortis（死）。同源：mourir（死）, mortel（致命的）。","ex":[["La mort fait partie de la vie.","死亡是生命的一部分。"],["Il a peur de la mort.","他害怕死亡。"]],"co":[["la mort de + 人","某人的去世"],["avoir peur de la mort","害怕死亡"],["la peine de mort","死刑"],["à mort","致命地；极度地"]],"sy":[["décès","soutenu","去世（正式、官方）"],["disparition","soutenu","逝世（委婉）"],["trépas","littéraire","死亡（文学）"]],"fq":"高频，常用于新闻与讨论。","me":"mort 与英语 mortal 同根：死亡 = mors。","tr":{"zh":"他害怕死亡。","fr":"Il a peur de la mort.","alt":"La mort lui fait peur.","note":"avoir peur de + 名词。"}},
 "La reconnaissance sociale": {"pos":"n.f. 阴性名词，复数 reconnaissances sociales","s":"社会认可；他人的尊重与认同。reconnaissance 本身还有「感激」「承认」「辨认」的意思，所以要靠搭配判断含义。","ipa":"[ʁə.kɔ.nɛ.sɑ̃s sɔ.sjal]","ph":"re- 读 [ʁə]；-naissance 读 [nɛ.sɑ̃s]，ai 读 [ɛ]；social：c 读 [s]，-cial 读 [sjal]。","pi":"reconnaissance 里 ai 读 [ɛ]，ss 读 [s]；social 里 c 读 [s]，不是 [k]，最后 l 要读。","et":"reconnaître = re- + connaître（拉丁语 cognoscere，认识）；social 来自拉丁语 socialis（同伴的）。","ex":[["La reconnaissance sociale est importante pour lui.","社会认可对他很重要。"],["Elle cherche la reconnaissance de ses collègues.","她想得到同事的认可。"]],"co":[["chercher la reconnaissance","寻求认可"],["manquer de reconnaissance","缺乏认可"],["avoir de la reconnaissance pour qqn","对某人心怀感激"]],"sy":[["considération","soutenu","尊重、重视"],["prestige","courant","声望"],["gratitude","soutenu","感激（reconnaissance 的另一义）"]],"fq":"中频，在职业与社会话题里常见。","me":"re- + connaître：别人「重新认识」你、认可你。","tr":{"zh":"对我来说，社会认可很重要。","fr":"Pour moi, la reconnaissance sociale est importante.","alt":"Je tiens à la reconnaissance sociale.","note":"pour moi：表示「就我而言」。"}},
 "La rémunération": {"pos":"n.f. 阴性名词，复数 rémunérations","s":"报酬；薪酬。比 salaire（工资）更正式、范围更广，包括工资、奖金等所有收入。常出现在招聘启事里。","ipa":"[ʁe.my.ne.ʁa.sjɔ̃]","ph":"é 读 [e]；u 读 [y]；-tion 读 [sjɔ̃]；两个 r 都读 [ʁ]。","pi":"第一个 é 和 -ration 里的 a 都要读清楚；u 读 [y]；-tion 读 [sjɔ̃]。","et":"拉丁语 remuneratio，源于 remunerare（回报），munus（礼物、职责）。动词：rémunérer。","ex":[["La rémunération pour ce poste est attractive.","这个职位的薪酬有吸引力。"],["Le contrat précise la rémunération.","合同写明了报酬。"]],"co":[["une rémunération attractive","有吸引力的薪酬"],["une rémunération mensuelle","月薪酬"],["en rémunération de","作为……的报酬"]],"sy":[["salaire","courant","工资，日常用语"],["paie / paye","courant","薪水，发薪"],["traitement","soutenu","公务员薪俸"]],"fq":"中频，书面语和招聘启事里常见。","me":"mun- 与「礼物」有关：rémunérer = 回赠一份礼，也就是付报酬。","tr":{"zh":"我想知道这份工作的薪酬。","fr":"Je voudrais connaître la rémunération de ce poste.","alt":"C'est quoi la rémunération pour ce poste ?","note":"connaître 用于「了解到」具体信息。"}},
 "Une maîtresse": {"pos":"n.f. 阴性名词，复数 maîtresses（阳性 maître）","s":"小学女老师；幼儿园女老师（孩子常这样叫）。注意：maîtresse 还有「情妇」的意思，所以用在老师时要有语境。","ipa":"[mɛ.tʁɛs]","ph":"maî 读 [mɛ]，î 是长音标记；-tresse 读 [tʁɛs]；结尾 e 不发音。","pi":"maîtresse 有「小学老师」和「情妇」两个意思，别随便单用；ai/aî 都读 [ɛ]。","et":"来自 maître（拉丁语 magister，老师、主人）+ 阴性后缀 -esse。","ex":[["La maîtresse explique la leçon aux élèves.","老师给学生讲课。"],["Ma fille adore sa maîtresse.","我女儿很喜欢她的老师。"]],"co":[["la maîtresse d'école","小学女教师"],["la maîtresse de maternelle","幼儿园女老师"],["une maîtresse de maison","女主人"]],"sy":[["institutrice","courant","小学女教师（正式）"],["professeure","courant","女教授、女教师（中学以上）"]],"fq":"中频，家长和孩子常说。","me":"maître 的阴性：孩子们说「maîtresse」，就是班里的女老师。","tr":{"zh":"我儿子的老师很温柔。","fr":"La maîtresse de mon fils est très gentille.","alt":"La maîtresse de mon fils est très douce.","note":"de mon fils：表示所属。"}},
 "Une ampoule": {"pos":"n.f. 阴性名词，复数 ampoules","s":"灯泡。也指「水泡」（脚上磨出的泡）和「安瓿」（小药瓶）。常用：changer une ampoule = 换灯泡。","ipa":"[ɑ̃.pul]","ph":"am 读鼻化 [ɑ̃]，p 要发；ou 读 [u]；l 要读；结尾 e 不发音。","pi":"am- 是 [ɑ̃]（和 an 同音）；ou 读 [u]；l 要读出来。","et":"拉丁语 ampulla（小瓶、小壶）。因为形状像小瓶，所以灯泡也叫 ampoule。","ex":[["Je dois changer l'ampoule du salon.","我得换客厅的灯泡。"],["J'ai une ampoule au pied.","我脚上起了个水泡。"]],"co":[["changer une ampoule","换灯泡"],["une ampoule électrique","电灯泡"],["avoir une ampoule au pied","脚上起水泡"],["une ampoule LED","LED 灯泡"]],"sy":[["lampe","courant","灯、台灯"],["cloque","courant","水泡、起泡"]],"fq":"中频，家庭生活常用。","me":"ampoule 像一个小瓶：灯泡也是装光的小「瓶」。","tr":{"zh":"这个灯泡坏了。","fr":"Cette ampoule est cassée.","alt":"Cette ampoule ne marche plus.","note":"cassée 要与阴性 ampoule 一致。"}},
 "Une année de césure": {"pos":"n.f. 阴性名词，复数 années de césure","s":"间隔年：高中毕业后或大学期间暂停一年，用来旅行、实习或做志愿者。césure 本意是诗句里的「顿挫」。","ipa":"[a.ne də se.zyʁ]","ph":"année：nn 读单个 [n]，结尾 e 不发音；césure：c 读 [s]，s 在元音间读 [z]，u 读 [y]。","pi":"césure 中的 s 读 [z]，不是 [s]；u 是 [y]；année 的 é 要读 [e]。","et":"césure 来自拉丁语 caesura（切开、中断），源于 caedere（切）。année 来自拉丁语 annus。","ex":[["Il prend une année de césure pour voyager.","他休一年去旅行。"],["Pendant mon année de césure, j'ai travaillé en Espagne.","我的间隔年里，我在西班牙工作了。"]],"co":[["prendre une année de césure","休一个间隔年"],["faire une année de césure","过一个间隔年"],["une année sabbatique","（工作中的）休假年"]],"sy":[["année sabbatique","courant","休假年，多指工作者"],["gap year","familier","英语说法，法国年轻人也说"]],"fq":"中低频，教育话题里常见。","me":"césure = 在年份中「切」一刀：学业中断一年。","tr":{"zh":"我打算休一个间隔年去旅行。","fr":"Je vais prendre une année de césure pour voyager.","alt":"Je compte faire une année de césure pour voyager.","note":"prendre une année de césure：固定搭配。"}},
 "Une appréciation": {"pos":"n.f. 阴性名词，复数 appréciations","s":"评语；评价；估计。老师在成绩单上写的评语就叫 appréciation。也有「欣赏」的意思。","ipa":"[a.pʁe.sja.sjɔ̃]","ph":"ap- 读 [ap]（p 只读一次）；é 读 [e]；ci 读 [sja]；-tion 读 [sjɔ̃]。","pi":"pp 只读一个 [p]；-ciation 读 [sja.sjɔ̃]，两个 s 音；é 读 [e]。","et":"来自动词 apprécier，拉丁语 appretiare（定价），源于 pretium（价格）。同源：précieux。","ex":[["Le professeur a écrit une bonne appréciation.","老师写了一条好评语。"],["Son appréciation du film est très positive.","他对这部电影的评价很正面。"]],"co":[["une appréciation positive / négative","正面 / 负面评价"],["l'appréciation du professeur","老师的评语"],["laisser une appréciation","留下评价"]],"sy":[["évaluation","courant","评估、打分"],["commentaire","courant","评论、评语"],["avis","courant","意见"]],"fq":"中频，学校里常见。","me":"apprécier 的名词：给东西「定价」，也就是评价。","tr":{"zh":"老师在作业上写了一条评语。","fr":"Le professeur a écrit une appréciation sur le devoir.","alt":"Le prof a mis un commentaire sur mon devoir.","note":"écrire une appréciation sur + 名词。"}},
 "Une compétence": {"pos":"n.f. 阴性名词，复数 compétences","s":"能力；技能；资质。职场上常指可写进简历的技能。形容词是 compétent(e)（有能力的）。","ipa":"[kɔ̃.pe.tɑ̃s]","ph":"com 读鼻化 [kɔ̃]；pé 读 [pe]；-tence 读 [tɑ̃s]，en 读 [ɑ̃]，c 读 [s]。","pi":"两个鼻化元音：com [ɔ̃] 和 en [ɑ̃]，别混；结尾 -ce 读 [s]。","et":"拉丁语 competentia，源于 competere（一起追求，适合）。形容词：compétent。","ex":[["Parler anglais est une bonne compétence.","会说英语是一项好技能。"],["Elle a des compétences en informatique.","她有信息技术方面的能力。"]],"co":[["avoir des compétences en + 领域","在某方面有能力"],["les compétences linguistiques","语言能力"],["développer ses compétences","提升自己的能力"]],"sy":[["capacité","courant","能力，更泛"],["savoir-faire","courant","实际技能"],["aptitude","soutenu","天赋、才能"]],"fq":"高频，职场与教育里常见。","me":"compétence 与英语 competence 几乎一样。","tr":{"zh":"你有哪些专业技能？","fr":"Quelles sont tes compétences professionnelles ?","alt":"C'est quoi tes compétences ?","note":"compétences 常用复数。"}},
 "Une crèche": {"pos":"n.f. 阴性名词，复数 crèches","s":"托儿所：照看三岁以下小孩（有时到入学前）。圣诞节时，la crèche 也指「马槽场景」，也就是耶稣诞生的小模型。","ipa":"[kʁɛʃ]","ph":"cr [kʁ]；è 读 [ɛ]；ch 读 [ʃ]；结尾 e 不发音。","pi":"ch 读 [ʃ]，不是 [k]；è 带重音符，读 [ɛ]；注意是三岁以下（三岁起上 maternelle）。","et":"来自法兰克语 *kripja（马槽、食槽），英语 crib 同源。","ex":[["Les enfants jouent à la crèche.","孩子们在托儿所玩。"],["Le bébé va à la crèche depuis septembre.","宝宝九月起上托儿所。"]],"co":[["mettre un enfant à la crèche","把孩子送托儿所"],["une crèche municipale","市立托儿所"],["faire la crèche de Noël","布置圣诞马槽模型"]],"sy":[["garderie","courant","托管班，时间较短"],["nounou","familier","保姆"],["maternelle","courant","幼儿园（3 到 6 岁）"]],"fq":"中频，家庭生活里常见。","me":"crèche 与 crib 同源：小宝宝睡的「小床」。","tr":{"zh":"我女儿每天上托儿所。","fr":"Ma fille va à la crèche tous les jours.","alt":"Ma fille est à la crèche toute la semaine.","note":"aller à la crèche：去托儿所用 à。"}},
 "Une étude de marché": {"pos":"n.f. 阴性名词，复数 études de marché","s":"市场调研；市场分析。公司推出新产品前，先做 une étude de marché。étude 单用是「学习」「研究」，études 复数多指「学业」。","ipa":"[e.tyd də maʁ.ʃe]","ph":"étude：é [e]，u [y]，d 读 [d]，结尾 e 不发音；de 读 [də]；marché：ch 读 [ʃ]，é [e]。","pi":"étude 里的 u 读 [y]；marché 的 ch 读 [ʃ]，不是 [k]；结尾 é 读 [e]。","et":"étude 来自拉丁语 studium（热情、研究）；marché 来自拉丁语 mercatus（市场）。","ex":[["L'entreprise réalise une étude de marché.","公司做市场调研。"],["Il faut faire une étude de marché avant de lancer ce produit.","推出这个产品之前要做市场调研。"]],"co":[["réaliser une étude de marché","进行市场调研"],["faire une étude de marché","做市场调研"],["une étude de marché approfondie","深入的市场调研"]],"sy":[["sondage","courant","民意调查"],["enquête","courant","调查"]],"fq":"中频，商业与创业话题里常见。","me":"étude（研究）+ marché（市场）：把市场当作研究对象。","tr":{"zh":"我们先做一次市场调研。","fr":"Nous allons d'abord faire une étude de marché.","alt":"On va d'abord faire une étude de marché.","note":"aller + 动词原形：近将来。"}},
 "Une interrogation": {"pos":"n.f. 阴性名词，复数 interrogations","s":"小测验（学校里的，常说 une interro）；疑问；提问。une interrogation écrite = 笔试小测。le point d'interrogation = 问号。","ipa":"[ɛ̃.te.ʁɔ.ga.sjɔ̃]","ph":"in 读鼻化 [ɛ̃]；g 在 a 前读 [g]；-tion 读 [sjɔ̃]；rr 读单个 [ʁ]。","pi":"rr 读一个 [ʁ]；g 读 [g]；-tion 读 [sjɔ̃]。不要与「审讯」混淆，学校里说的就是小测。","et":"拉丁语 interrogatio，源于 interrogare（提问）。口语缩写：une interro。","ex":[["Le professeur fait une interrogation surprise.","老师做了一次突击小测。"],["On a une interrogation de maths demain.","我们明天有数学小测。"]],"co":[["une interrogation écrite / orale","笔试 / 口试小测"],["une interrogation surprise","突击测验"],["un point d'interrogation","问号"]],"sy":[["interro","familier","小测（缩写）"],["contrôle","courant","测验，常指较正式"],["question","courant","问题"]],"fq":"中频，学校里常用。","me":"interrogation = 老师向你「提问」：一次小测。","tr":{"zh":"明天我们有一场法语小测。","fr":"Nous avons une interrogation de français demain.","alt":"On a une interro de français demain.","note":"avoir une interrogation de + 科目。"}},
 "Une lettre de motivation": {"pos":"n.f. 阴性名词，复数 lettres de motivation","s":"求职信；申请信：说明你为何想要这份工作或这所学校的信。通常与简历 (un CV) 一起寄出。","ipa":"[lɛtʁ də mɔ.ti.va.sjɔ̃]","ph":"lettre：tt 读单个 [t]，结尾 -tre 读 [tʁ]；motivation：o [ɔ]，-tion [sjɔ̃]。","pi":"lettre 里 tt 只读一个 [t]；motivation 的 -tion 读 [sjɔ̃]；lettre 是「信」也是「字母」。","et":"lettre 来自拉丁语 littera；motivation 来自 motif（动机，拉丁语 motivus）。","ex":[["Tu dois écrire une lettre de motivation pour ce travail.","你得为这份工作写求职信。"],["J'envoie mon CV et ma lettre de motivation.","我寄出简历和求职信。"]],"co":[["écrire une lettre de motivation","写求职信"],["joindre une lettre de motivation","附上求职信"],["un CV et une lettre de motivation","简历和求职信"]],"sy":[["candidature","courant","应聘申请（整份材料）"],["CV","courant","简历"]],"fq":"中频，求职时必用。","me":"lettre + motivation：一封解释「我的动力」的信。","tr":{"zh":"我正在写一封求职信。","fr":"Je suis en train d'écrire une lettre de motivation.","alt":"J'écris ma lettre de motivation.","note":"être en train de + 动词原形：正在做。"}},
 "Une licence (L1, L2, L3)": {"pos":"n.f. 阴性名词，复数 licences","s":"学士学位：在法国大学读三年（L1、L2、L3）。une licence de + 专业 = 某专业学士。注意：不是「许可证」，那个意思是 permis 或 licence（少数场合）。","ipa":"[li.sɑ̃s]","ph":"li [li]；-cence 读 [sɑ̃s]，en 读 [ɑ̃]，c 读 [s]；结尾 e 不发音。","pi":"licence 在法国多指「学士学位」，不是英语 license（执照）；en 读 [ɑ̃]。","et":"拉丁语 licentia（许可、自由）。最初指「授予教学的许可」，后来变成学位名。","ex":[["Il a obtenu sa licence d'histoire.","他获得了历史学学士学位。"],["Je suis en deuxième année de licence.","我在读学士二年级。"]],"co":[["une licence de + 专业","某专业学士"],["en première année de licence","学士一年级"],["obtenir sa licence","拿到学士学位"]],"sy":[["bachelor","courant","英语借词，常指商学院学位"],["maîtrise","courant","旧制四年级学位，现多为 master 1"]],"fq":"中频，教育话题里常见。","me":"licence = 三年（L1-L2-L3）大学学位。","tr":{"zh":"我在读法语专业的学士学位。","fr":"Je prépare une licence de lettres modernes.","alt":"Je fais une licence de lettres.","note":"préparer une licence：正在攻读。"}},
 "Une matière": {"pos":"n.f. 阴性名词，复数 matières","s":"科目（学校课程）；材料；物质。ma matière préférée = 我最喜欢的科目。la matière première = 原料。table des matières = 目录。","ipa":"[ma.tjɛʁ]","ph":"ma [ma]；-tière 读 [tjɛʁ]，r 读小舌音 [ʁ]；结尾 e 不发音。","pi":"tière 读 [tjɛʁ]，r 要发；不要读成「mà-tiè」；匹配 matière 的是 la（阴性）。","et":"拉丁语 materia（木材、材料）。同源：matériel（器材）, maternel。","ex":[["Ma matière préférée est l'histoire.","我最喜欢的科目是历史。"],["Quelle matière est-ce que tu détestes ?","你最讨厌哪一科？"]],"co":[["ma matière préférée","我最喜欢的科目"],["la matière première","原材料"],["la table des matières","目录"],["en matière de + 名词","在……方面"]],"sy":[["discipline","soutenu","学科"],["sujet","courant","主题、话题"]],"fq":"高频，学校与生活里常用。","me":"matière 与 matériel 同根：构成一门课的「材料」。","tr":{"zh":"你最喜欢哪个科目？","fr":"Quelle est ta matière préférée ?","alt":"Tu préfères quelle matière ?","note":"préféré(e) 与名词的阴阳性一致。"}},
 "Une note": {"pos":"n.f. 阴性名词，复数 notes","s":"分数；笔记；账单。une bonne note = 好成绩；prendre des notes = 做笔记；la note (d'hôtel / de restaurant) = 账单。","ipa":"[nɔt]","ph":"o 读 [ɔ]；t 读 [t]；结尾 e 不发音。","pi":"note 有三个常用意思（分数、笔记、账单），要看搭配；「做笔记」说 prendre des notes，不是 faire。","et":"拉丁语 nota（记号、标记）。同源：noter（记下）, notation。","ex":[["J'ai eu une bonne note à mon examen.","我考试得了好分数。"],["Je prends des notes pendant le cours.","我上课时做笔记。"],["Garçon, la note, s'il vous plaît !","服务员，请结账！"]],"co":[["une bonne / mauvaise note","好 / 差的分数"],["prendre des notes","做笔记"],["la note d'hôtel","酒店账单"],["une note de service","内部通知"]],"sy":[["résultat","courant","结果、成绩"],["addition","courant","餐厅账单（更常用）"],["notation","soutenu","评分"]],"fq":"极高频。","me":"note：「记号」→ 记下的分数、笔记、账目。","tr":{"zh":"我这次考试得了好分数。","fr":"J'ai eu une bonne note à cet examen.","alt":"J'ai décroché une bonne note à l'examen.","note":"avoir une bonne note：得到好分数。"}},
 "Une offre d'emploi": {"pos":"n.f. 阴性名词，复数 offres d'emploi","s":"招聘启事；职位空缺。répondre à une offre d'emploi = 应聘一则招聘。offre 也有「报价、提议」的意思。","ipa":"[ɔfʁ dɑ̃.plwa]","ph":"offre：ff 读单个 [f]，结尾 -fre 读 [fʁ]；d'emploi：em 读鼻化 [ɑ̃]，oi 读 [wa]。","pi":"emploi 里 em 读 [ɑ̃]，oi 读 [wa]；offre 的 ff 只读一个 [f]。","et":"offre 来自动词 offrir（拉丁语 offerre）；emploi 来自 employer（拉丁语 implicare）。","ex":[["J'ai répondu à une offre d'emploi sur internet.","我在网上回复了一则招聘启事。"],["Il y a beaucoup d'offres d'emploi dans ce secteur.","这个行业有很多招聘启事。"]],"co":[["répondre à une offre d'emploi","回应招聘"],["consulter les offres d'emploi","浏览招聘信息"],["déposer une offre d'emploi","发布招聘启事"]],"sy":[["annonce","courant","广告、启事"],["poste à pourvoir","soutenu","待补空缺职位"],["offre de stage","courant","实习招聘"]],"fq":"中频，求职时常见。","me":"offre（提供）+ emploi（工作）：公司「提供」的工作。","tr":{"zh":"我在找一份新的招聘启事。","fr":"Je cherche une nouvelle offre d'emploi.","alt":"Je regarde les offres d'emploi.","note":"chercher une offre：直接带宾语，不加介词。"}},
 "Une reconversion professionnelle": {"pos":"n.f. 阴性名词，复数 reconversions professionnelles","s":"职业转换；转行。faire une reconversion = 换到完全不同的行业，常需要重新培训。","ipa":"[ʁə.kɔ̃.vɛʁ.sjɔ̃ pʁɔ.fɛ.sjɔ.nɛl]","ph":"re- 读 [ʁə]；con 读 [kɔ̃]；ver 读 [vɛʁ]；-sion 读 [sjɔ̃]；professionnelle：-nn- 读 [n]，ss 读 [s]。","pi":"professionnelle 里 nn 读 [n]，ss 读 [s]；con 与 sion 两个鼻化音要清楚。","et":"reconversion = re- + conversion，拉丁语 convertere（转向）。professionnel 来自 profession（拉丁语 professio，公开声明）。","ex":[["Elle a fait une reconversion professionnelle pour devenir fleuriste.","她转行成了花店老板。"],["Il envisage une reconversion professionnelle.","他在考虑转行。"]],"co":[["faire une reconversion professionnelle","转行"],["envisager une reconversion","考虑转行"],["une formation de reconversion","转行培训"]],"sy":[["changement de carrière","courant","换职业"],["changer de métier","courant","换工作"]],"fq":"中频，职场话题里常见。","me":"re- + conversion：重新「转向」另一个职业。","tr":{"zh":"我四十岁时转了行。","fr":"J'ai changé de métier à quarante ans.","alt":"À quarante ans, j'ai fait une reconversion.","note":"changer de métier：换工作，不带冠词。"}},
 "Une révélation": {"pos":"n.f. 阴性名词，复数 révélations","s":"令人惊喜的发现；揭露；启示。une révélation 可以指一个突然让你眼前一亮的人或事。也指「泄露的秘密」。","ipa":"[ʁe.ve.la.sjɔ̃]","ph":"ré 读 [ʁe]；vé 读 [ve]；-tion 读 [sjɔ̃]；每个 é 都读 [e]。","pi":"有两个 é，都要读 [e]；-tion 读 [sjɔ̃]；révélation 不是只有「泄密」，常有惊喜意味。","et":"拉丁语 revelatio，源于 revelare（揭开，去掉面纱 velum）。动词：révéler。","ex":[["Ce film a été une vraie révélation.","这部电影真是个惊喜。"],["Cette jeune chanteuse est la révélation de l'année.","这位年轻歌手是今年的新星。"]],"co":[["une vraie révélation","真正的惊喜"],["la révélation de l'année","年度新秀"],["faire des révélations","透露内幕"]],"sy":[["découverte","courant","发现"],["surprise","courant","惊喜"],["dévoilement","soutenu","揭晓"]],"fq":"中频，文化与新闻里常见。","me":"révéler = 把面纱 (voile) 拿开：眼前一亮。","tr":{"zh":"这家餐厅是个惊喜。","fr":"Ce restaurant a été une vraie révélation.","alt":"Ce restaurant, c'était une belle surprise.","note":"a été：passé composé of être，表示过去的一次评价。"}},
 "(Secteur) Le management / Le marketing": {"pos":"n.m. 阳性名词（两个词都是阳性），复数 managements / marketings（多用单数）","s":"管理；市场营销：两个借自英语的商业词。le management = 企业管理；le marketing = 营销。Elle fait du marketing = 她做营销。","ipa":"[ma.naʒ.mɑ̃] / [maʁ.kə.tiŋ]","ph":"management：法语读法 [ma.naʒ.mɑ̃]，g 读 [ʒ]，-ment 读 [mɑ̃]；marketing：[maʁ.kə.tiŋ]，r 读 [ʁ]，-ing 读 [iŋ]。","pi":"management 不按英语读：-ment 读鼻化 [mɑ̃]；marketing 的 -ing 读 [iŋ]，r 是小舌音。","et":"两词都借自英语（management、marketing）。management 的英语词根来自意大利语 maneggiare（驯马）。","ex":[["Elle étudie le marketing.","她学市场营销。"],["Il fait du management dans une grande entreprise.","他在一家大公司做管理工作。"]],"co":[["le marketing digital","数字营销"],["un responsable marketing","营销主管"],["le management d'équipe","团队管理"],["faire du marketing","做营销"]],"sy":[["gestion","courant","管理，日常用语"],["direction","courant","领导、管理层"],["publicité","courant","广告"]],"fq":"中频，商务场合常见。","me":"两个词都来自英语，只是读音按法语走。","tr":{"zh":"我想学市场营销和管理。","fr":"Je veux étudier le marketing et le management.","alt":"J'aimerais faire du marketing et du management.","note":"étudier le marketing；faire du marketing（不可数）。"}},
 "Des congés": {"pos":"n.m.pl. 阳性复数名词，单数 un congé","s":"假期；休假（带薪的）。les congés payés = 带薪假。prendre des congés = 请假、休假。une semaine de congé 也可用单数。","ipa":"[kɔ̃.ʒe]","ph":"con 读鼻化 [ɔ̃]；g 在 é 前读 [ʒ]；结尾 -és 读 [e]，s 不发音。","pi":"congés 结尾 s 不发音（单复数同音）；g 读 [ʒ]；les congés 与 les vacances 不同，前者强调「向公司请的假」。","et":"来自拉丁语 commeatus（离开的许可），古法语 congié。","ex":[["Je prends des congés en août.","我八月休假。"],["Elle est en congé cette semaine.","她这周在休假。"]],"co":[["prendre des congés","休假"],["les congés payés","带薪假期"],["être en congé","在休假"],["un congé maladie","病假"]],"sy":[["vacances","courant","假期，更泛指玩的假期"],["repos","courant","休息"],["RTT","courant","补休日"]],"fq":"高频，职场常用。","me":"congé：公司给你「离开」的许可。","tr":{"zh":"我下个月要休假。","fr":"Je prends des congés le mois prochain.","alt":"Je suis en congé le mois prochain.","note":"prendre des congés：不可数，用 des。"}},
 "La maternelle / L'école maternelle": {"pos":"n.f. 阴性名词，复数 maternelles","s":"幼儿园：法国 3 到 6 岁孩子上的学校，从三岁起就读。la maternelle 是口语简称，l'école maternelle 是全称。","ipa":"[ma.tɛʁ.nɛl]","ph":"ma [ma]；ter 读 [tɛʁ]；nelle 读 [nɛl]，ll 读单个 [l]；结尾 e 不发音。","pi":"maternelle 读 [ma.tɛʁ.nɛl]，不是 [mə]；与 crèche（三岁以下）不同；不是「母亲的」。","et":"来自形容词 maternel（拉丁语 maternus，母亲的），源于 mater（母亲）。「母爱式」的学校。","ex":[["Mon fils entre à l'école maternelle cette année.","我儿子今年上幼儿园。"],["Elle est maîtresse en maternelle.","她是幼儿园老师。"]],"co":[["aller à la maternelle","上幼儿园"],["l'école maternelle","幼儿园"],["une classe de maternelle","幼儿园班"]],"sy":[["crèche","courant","托儿所，更小的孩子"],["jardin d'enfants","courant","幼儿园（稍旧）"]],"fq":"中频，家庭和教育话题里常用。","me":"maternelle ← mater（母亲）：像妈妈一样照顾孩子的学校。","tr":{"zh":"我女儿今年上幼儿园。","fr":"Ma fille entre à la maternelle cette année.","alt":"Ma fille commence la maternelle cette année.","note":"entrer à la maternelle：开始上幼儿园。"}},
 "Les années d'études": {"pos":"n.f.pl. 阴性复数名词，单数 une année d'études","s":"学习年限；读书的年数。常用于简历和介绍学历：quatre années d'études après le bac = 高中毕业后读了四年。études 复数指「学业」。","ipa":"[a.ne de.tyd]","ph":"années：nn 读单个 [n]，结尾 s 不发音；d'études：é [e]，u [y]，d 读 [d]。","pi":"études 的 u 读 [y]；années 结尾 s 不发音；d'études 要连读成 [de.tyd]。","et":"année 来自拉丁语 annus（年）；étude 来自拉丁语 studium（热情、学习）。","ex":[["Les années d'études sont importantes.","学习年限很重要。"],["Après cinq années d'études, il devient médecin.","读了五年书之后，他成了医生。"]],"co":[["cinq années d'études","五年的学习"],["après le bac","高中毕业后"],["faire de longues études","读很久的书"],["les années d'université","大学几年"]],"sy":[["cursus","soutenu","学业课程"],["parcours","courant","学习经历"]],"fq":"中频，描述学历时常见。","me":"année + études：读书的一年一年。","tr":{"zh":"他读了七年书才成为医生。","fr":"Il a fait sept années d'études pour devenir médecin.","alt":"Il a étudié sept ans pour devenir médecin.","note":"faire + 年数 + d'études。"}},
 "Les conditions de travail": {"pos":"n.f.pl. 阴性复数名词，单数 une condition","s":"工作条件；工作环境。包括工资、工时、安全、气氛等。conditions 多用复数。也有「条件」的一般意思。","ipa":"[kɔ̃.di.sjɔ̃ də tʁa.vaj]","ph":"con 读 [kɔ̃]；-tion 读 [sjɔ̃]；travail：ail 读 [aj]，l 不单独发音。","pi":"travail 的 -ail 读 [aj]，不要读 l；-tion 读 [sjɔ̃]；conditions 结尾 s 不发音。","et":"condition 来自拉丁语 conditio；travail 的来源有争议，常说来自 tripalium（一种刑具），但不确定。同族：travailler。","ex":[["Les conditions de travail sont excellentes ici.","这里的工作条件很好。"],["Il se plaint de ses conditions de travail.","他抱怨自己的工作条件。"]],"co":[["de bonnes conditions de travail","良好的工作条件"],["améliorer les conditions de travail","改善工作条件"],["les conditions de vie","生活条件"]],"sy":[["environnement de travail","courant","工作环境"],["ambiance","courant","气氛"]],"fq":"中频，职场与新闻里常见。","me":"condition + travail：工作的「条件」。","tr":{"zh":"这家公司的工作条件很好。","fr":"Les conditions de travail sont bonnes dans cette entreprise.","alt":"Dans cette boîte, les conditions de travail sont top.","note":"conditions 是复数，所以用 sont。"}},
 "Un animateur / Une animatrice": {"pos":"n. 名词，阳性 animateur，阴性 animatrice，复数 animateurs / animatrices","s":"活动主持人；带队辅导员（夏令营、社区中心）；电视或电台主持人。注意：不是动画师（动画师是 un animateur 3D 或 un dessinateur d'animation）。","ipa":"[a.ni.ma.tœʁ] / [a.ni.ma.tʁis]","ph":"animateur：-eur 读 [œʁ]，r 要发；animatrice：-trice 读 [tʁis]。","pi":"阳性 -eur [œʁ] 与阴性 -trice [tʁis] 变化较大；animateur 常指带活动的人，不一定是「动画」。","et":"来自动词 animer（拉丁语 animare，赋予生命），源于 anima（灵魂）。","ex":[["L'animateur organise des jeux pour les enfants.","主持人给孩子们组织游戏。"],["Elle est animatrice dans un centre de loisirs.","她在一家休闲中心当辅导员。"]],"co":[["un animateur de radio / de télévision","电台 / 电视主持人"],["un animateur de centre de loisirs","休闲中心辅导员"],["un animateur de colonie de vacances","夏令营辅导员"]],"sy":[["présentateur","courant","节目主持人"],["moniteur","courant","辅导员、教练"],["animateur-vedette","courant","明星主持人"]],"fq":"中频。","me":"anima（灵魂）：给活动「注入生命」的人。","tr":{"zh":"我姐姐在夏令营当辅导员。","fr":"Ma sœur est animatrice dans une colonie de vacances.","alt":"Ma sœur travaille comme animatrice en colo.","note":"职业名前通常不加冠词：est animatrice。"}},
 "Un recruteur / Une recruteuse": {"pos":"n. 名词，阳性 recruteur，阴性 recruteuse，复数 recruteurs / recruteuses","s":"招聘人员：负责面试和选人的人。动词 recruter = 招聘、招募。","ipa":"[ʁə.kʁy.tœʁ] / [ʁə.kʁy.tøz]","ph":"re- 读 [ʁə]；cru 读 [kʁy]，u 读 [y]；-eur 读 [œʁ]，-euse 读 [øz]。","pi":"两个 r 要发 [ʁ]；u 读 [y]；阳性 [œʁ] 与阴性 [øz] 不同。","et":"来自动词 recruter，名词 recrue（新兵）。词族：recrutement（招聘）。","ex":[["Le recruteur pose beaucoup de questions.","招聘人员问很多问题。"],["La recruteuse m'a rappelé hier.","招聘人员昨天给我回电话了。"]],"co":[["un recruteur d'une grande entreprise","大公司的招聘人员"],["contacter un recruteur","联系招聘人员"],["un cabinet de recrutement","猎头公司"]],"sy":[["chasseur de têtes","familier","猎头"],["DRH","courant","人力资源总监"],["responsable RH","courant","人事主管"]],"fq":"中频，求职话题里常见。","me":"recruter → recruteur：负责「招人」的人。","tr":{"zh":"招聘人员给我打了电话。","fr":"Le recruteur m'a téléphoné.","alt":"Le recruteur m'a appelé.","note":"téléphoner à qqn：m'a téléphoné，用间接宾语 me。"}},
 "Un(e) aide à domicile": {"pos":"n.m./n.f. 阳性或阴性名词（形式不变），复数 aides à domicile","s":"居家护理员：上门帮老人、病人、残疾人做家务和日常照料的人。les aides à domicile = 复数。","ipa":"[ɛd a dɔ.mi.sil]","ph":"aide 读 [ɛd]；à 读 [a]；domicile：o [ɔ]，c 读 [s]，结尾 le 读 [sil]。","pi":"aide 读 [ɛd]，d 要发；domicile 里 ci 读 [si]；一个词既可阳性也可阴性。","et":"aide 来自动词 aider（拉丁语 adjutare）；domicile 来自拉丁语 domicilium，源于 domus（家）。","ex":[["L'aide à domicile aide les personnes âgées.","护理员帮助老人。"],["Ma mère a une aide à domicile deux fois par semaine.","我妈妈每周有两次居家护理。"]],"co":[["une aide à domicile pour personnes âgées","老人居家护理员"],["les services à domicile","上门服务"],["à domicile","上门；在家"]],"sy":[["aide-soignant","courant","护工（医院）"],["auxiliaire de vie","courant","生活助理"],["garde-malade","soutenu","看护"]],"fq":"中频，社会与职业话题里常见。","me":"aide + domicile：到「家」里来帮忙的人。","tr":{"zh":"护理员每天来看我奶奶。","fr":"L'aide à domicile vient voir ma grand-mère tous les jours.","alt":"L'aide à domicile passe chez ma grand-mère chaque jour.","note":"tous les jours：每天，tous 的 s 读 [s]。"}},
 "Un(e) candidat(e)": {"pos":"n. 名词，阳性 candidat，阴性 candidate，复数 candidats / candidates","s":"应聘者；候选人；考生。candidat 阳性结尾不发音 [da]，阴性 candidate 的 t 要发 [dat]。","ipa":"[kɑ̃.di.da] / [kɑ̃.di.dat]","ph":"can 读鼻化 [kɑ̃]；阳性结尾 t 不发音；阴性 -date 读 [dat]。","pi":"阳性 candidat 的 t 不发音，阴性 candidate 的 t 要发；an 读 [ɑ̃]。","et":"拉丁语 candidatus（穿白袍的人）：古罗马竞选者穿白袍。","ex":[["Ce candidat a un bon profil.","这位应聘者背景不错。"],["Il y a dix candidates pour ce poste.","这个职位有十位女应聘者。"]],"co":[["un candidat à un poste","职位应聘者"],["la candidate à la présidence","女总统候选人"],["poser sa candidature","提交申请"]],"sy":[["postulant","soutenu","申请人"],["prétendant","littéraire","追求者；竞争者"]],"fq":"高频，求职与选举里常见。","me":"candidat ← candidus（白色的）：穿白袍参选的人。","tr":{"zh":"这位应聘者很有经验。","fr":"Ce candidat a beaucoup d'expérience.","alt":"Cette candidate a beaucoup d'expérience.","note":"阳 ce candidat / 阴 cette candidate。"}},
 "Un(e) comédien(ne)": {"pos":"n. 名词，阳性 comédien，阴性 comédienne，复数 comédiens / comédiennes","s":"演员（戏剧、电影）。注意：不是英语 comedian（喜剧演员），喜剧演员说 un humoriste。","ipa":"[kɔ.me.djɛ̃] / [kɔ.me.djɛn]","ph":"co [kɔ]；mé [me]；-dien 读 [djɛ̃]（阳性），-dienne 读 [djɛn]（阴性）。","pi":"comédien 是「演员」，不是 comedian；阳性鼻化 [ɛ̃]，阴性读 [ɛn]，注意变化。","et":"来自 comédie，拉丁语 comoedia，希腊语 kōmōidia（喜剧）。","ex":[["Cette comédienne joue très bien.","这位女演员演得很好。"],["Mon frère est comédien au théâtre.","我哥哥是话剧演员。"]],"co":[["un comédien de théâtre","话剧演员"],["une comédienne de cinéma","电影女演员"],["devenir comédien","成为演员"]],"sy":[["acteur / actrice","courant","演员，更常说"],["artiste","courant","艺术家"],["humoriste","courant","喜剧演员（脱口秀）"]],"fq":"中频，文化话题里常见。","me":"comédien ≠ comedian：演员，不一定搞笑。","tr":{"zh":"我姐姐想当演员。","fr":"Ma sœur veut devenir comédienne.","alt":"Ma sœur rêve d'être comédienne.","note":"devenir + 职业名，不加冠词。"}},
 "Un(e) consultant(e)": {"pos":"n. 名词，阳性 consultant，阴性 consultante，复数 consultants / consultantes","s":"顾问：给企业提供专业建议的人。un consultant en informatique = IT 顾问。口语里职场很常见。","ipa":"[kɔ̃.syl.tɑ̃]","ph":"con [kɔ̃]；su 读 [sy]，u 读 [y]；-tant 读 [tɑ̃]，结尾 t 不发音。","pi":"结尾 -ant 读 [ɑ̃]，t 不发音（阴性 consultante 才读 t）；u 读 [y]。","et":"来自动词 consulter，拉丁语 consultare（商议）。","ex":[["Le consultant donne des conseils à l'entreprise.","顾问给公司提建议。"],["Elle est consultante en marketing.","她是营销顾问。"]],"co":[["un consultant en + 领域","某领域顾问"],["un cabinet de consultants","咨询公司"],["travailler comme consultant","做顾问"]],"sy":[["conseiller","courant","顾问、辅导员"],["expert","courant","专家"]],"fq":"中频，商务里常见。","me":"consulter（咨询）→ consultant：被人「咨询」的人。","tr":{"zh":"他是一名信息技术顾问。","fr":"Il est consultant en informatique.","alt":"Il travaille comme consultant en informatique.","note":"consultant en + 领域。"}},
 "Un(e) freelance / entrepreneur / entrepreneuse / indépendant / indépendante": {"pos":"n. 名词：freelance 阳阴同形；entrepreneur / entrepreneuse；indépendant / indépendante","s":"自由职业者（freelance）；创业者（entrepreneur）；个体经营者（indépendant）。三个词都指不为单一公司打工、自己接活或自己办企业的人，侧重点略有不同。","ipa":"[fʁi.lɑ̃s]","ph":"freelance 读 [fʁi.lɑ̃s]，-lance 里 an 读 [ɑ̃]，c 读 [s]；entrepreneur：[ɑ̃.tʁə.pʁə.nœʁ]；indépendant：[ɛ̃.de.pɑ̃.dɑ̃]。","pi":"freelance 虽是英语词，但在法语里按法语读 [fʁi.lɑ̃s]，不读英语的 [lɑ:ns]；entrepreneur 有两个 r，易读错。","et":"freelance 借自英语 free-lance（原指自由雇佣兵）；entrepreneur 来自动词 entreprendre（承担）；indépendant = in- + dépendre。","ex":[["Il travaille comme freelance.","他是自由职业者。"],["Elle est entrepreneuse et elle a lancé sa marque.","她是创业者，创立了自己的品牌。"]],"co":[["travailler en freelance","做自由职业"],["être à son compte","自己当老板"],["un travailleur indépendant","个体劳动者"],["lancer son entreprise","创办企业"]],"sy":[["auto-entrepreneur","courant","个体经营者（法国特定身份）"],["pigiste","courant","自由撰稿人"],["patron","courant","老板"]],"fq":"中频，职场话题里常见。","me":"free + lance：自由的「长矛」，自己出去接活。","tr":{"zh":"她现在是自由职业者。","fr":"Elle est freelance maintenant.","alt":"Elle travaille à son compte maintenant.","note":"freelance 阴阳同形，职业名前不加冠词。"}},
 "Un(e) gagnant(e)": {"pos":"n. 名词，阳性 gagnant，阴性 gagnante，复数 gagnants / gagnantes","s":"获胜者；赢家；中奖者。也可作形容词：le numéro gagnant = 中奖号码。动词 gagner = 赢；赚钱。","ipa":"[ga.ɲɑ̃] / [ga.ɲɑ̃t]","ph":"gn 读 [ɲ]（像「尼」）；an 读 [ɑ̃]；阳性结尾 t 不发音，阴性 -ante 读 [ɑ̃t]。","pi":"gn 读 [ɲ]，不是 [gn]；阳性 t 不发音，阴性要发 [t]。","et":"来自动词 gagner，源于法兰克语 *waidanjan（放牧，后来引申为「获得」）。","ex":[["Le gagnant reçoit un prix.","获胜者得到奖品。"],["La gagnante du concours est très heureuse.","比赛的女获胜者非常高兴。"]],"co":[["le gagnant du concours","比赛获胜者"],["un numéro gagnant","中奖号码"],["gagnant-gagnant","双赢"]],"sy":[["vainqueur","soutenu","胜利者"],["lauréat","soutenu","获奖者"],["champion","courant","冠军"]],"fq":"中频。","me":"gagner（赢）→ gagnant：赢的人。","tr":{"zh":"获胜者会得到一张机票。","fr":"Le gagnant reçoit un billet d'avion.","alt":"Le gagnant gagne un billet d'avion.","note":"reçoit：recevoir 现在时第三人称。"}},
 "Un(e) professionnel(le)": {"pos":"n. 名词，阳性 professionnel，阴性 professionnelle，复数 professionnels / professionnelles","s":"专业人士；职业选手。une professionnelle 也可作形容词：专业的。c'est un pro 是口语。","ipa":"[pʁɔ.fɛ.sjɔ.nɛl]","ph":"pro [pʁɔ]；fes 读 [fɛs]；sio 读 [sjɔ]；nel 读 [nɛl]，nn 读 [n]。","pi":"ss 读 [s]；nn 读 [n]；-el 读 [ɛl]，阳阴性同音。","et":"来自 profession（拉丁语 professio，公开声明）+ -nel。口语缩写：un pro。","ex":[["C'est un vrai professionnel.","他是真正的专业人士。"],["Elle est professionnelle de tennis.","她是职业网球选手。"]],"co":[["un professionnel de santé","医疗专业人员"],["un joueur professionnel","职业选手"],["en professionnel","以专业方式"]],"sy":[["pro","familier","专业人士（缩写）"],["expert","courant","专家"],["spécialiste","courant","专业人员"]],"fq":"中频。","me":"professionnel ← profession：靠一门职业吃饭的人。","tr":{"zh":"她是真正的专业人士。","fr":"C'est une vraie professionnelle.","alt":"C'est une vraie pro.","note":"阴性要用 une professionnelle。"}},
 "Un(e) RH (Ressources Humaines)": {"pos":"n.m./n.f. 阳性或阴性名词（缩写，形式不变）；les RH = 人力资源部","s":"人力资源专员；人力资源部（les RH）。全称 les ressources humaines。口语里「去 RH 部门」就是 aller aux RH。","ipa":"[ɛʁ.aʃ]","ph":"按字母读：R [ɛʁ]，H [aʃ]。","pi":"H 在字母表里读 [aʃ]，不是英语的 [eɪtʃ]；R 读 [ɛʁ]。","et":"缩写：ressources humaines。ressource 来自动词 resourdre（再涌出），humain 来自拉丁语 humanus。","ex":[["Le RH gère les contrats des employés.","人力资源负责员工合同。"],["Je dois appeler les RH.","我得给人力资源部打电话。"]],"co":[["le service RH","人力资源部"],["un responsable RH","人力资源主管"],["les ressources humaines","人力资源"],["un DRH","人力资源总监"]],"sy":[["DRH","courant","人力资源总监"],["recruteur","courant","招聘人员"],["service du personnel","courant","人事科（旧称）"]],"fq":"中频，职场里常用。","me":"R-H：「艾尔 - 阿什」，法语字母读法。","tr":{"zh":"人力资源部今天给我回电话。","fr":"Les RH m'ont rappelé aujourd'hui.","alt":"Les RH m'ont appelé aujourd'hui.","note":"les RH 是复数，所以用 ont。"}},
 "Un cycliste": {"pos":"n.m./n.f. 阳性或阴性名词（形式不变：un cycliste / une cycliste），复数 cyclistes","s":"骑自行车的人；自行车运动员。une cycliste = 女骑行者，词形不变，只换冠词。le Tour de France = 环法自行车赛。","ipa":"[si.klist]","ph":"cy 读 [si]；cli 读 [kli]；-ste 读 [st]，e 不发音。","pi":"第一个 c 读 [s]，第二个 c 读 [k]；y 读 [i]；结尾 -iste 读 [ist]。","et":"来自 cycle（拉丁语 cyclus，希腊语 kyklos，圆圈）+ -iste。","ex":[["Le cycliste roule vite.","骑车人骑得很快。"],["Les cyclistes doivent porter un casque.","骑车人应戴头盔。"]],"co":[["un cycliste professionnel","职业自行车手"],["une piste cyclable","自行车道"],["le Tour de France cycliste","环法自行车赛"]],"sy":[["vététiste","courant","山地车手"],["coureur","courant","赛车手"],["vélo","courant","自行车（物）"]],"fq":"中频。","me":"cycle（圆圈、轮子）+ -iste：转轮子的人。","tr":{"zh":"骑车人在路边骑行。","fr":"Le cycliste roule au bord de la route.","alt":"Le cycliste roule sur le bord de la route.","note":"au bord de + 名词：在……边。"}},
 "Élargir": {"pos":"v. 动词，第二组（-ir，élargissons），助动词 avoir","s":"拓宽；扩大；放宽。élargir une route = 拓宽道路；élargir ses horizons = 开阔眼界。反义：rétrécir（变窄）。","ipa":"[e.laʁ.ʒiʁ]","ph":"é 读 [e]；lar 读 [laʁ]；gir 读 [ʒiʁ]，g 在 i 前读 [ʒ]；结尾 r 要发。","pi":"g 在 i 前读 [ʒ]，不是 [g]；结尾 -ir 的 r 要发 [ʁ]；第二组：élargissons, élargissez。","et":"é-（使成为）+ large（宽）+ -ir。large 来自拉丁语 largus（慷慨的、宽的）。","ex":[["Il faut élargir cette route.","这条路需要拓宽。"],["Voyager élargit les horizons.","旅行开阔眼界。"]],"co":[["élargir ses horizons","开阔眼界"],["élargir une route","拓宽道路"],["élargir le débat","扩大讨论范围"]],"sy":[["agrandir","courant","扩大（面积、尺寸）"],["étendre","courant","扩展"],["rétrécir","courant","（反义）变窄"]],"fq":"中频。","me":"é + large + ir：把东西变「large」，也就是变宽。","tr":{"zh":"我们想拓宽这条路。","fr":"Nous voulons élargir cette route.","alt":"On veut rendre cette route plus large.","note":"第二组动词：nous élargissons。"}},
 "Intégrer": {"pos":"v. 动词，第一组（-er，intègre / intégrons），助动词 avoir","s":"融入；纳入；考入（名校、公司）。intégrer une école = 考进一所学校；s'intégrer = 融入（社会、团队）。","ipa":"[ɛ̃.te.gʁe]","ph":"in 读鼻化 [ɛ̃]；té 读 [te]；gré 读 [gʁe]，g 在 r 前读 [g]；结尾 -er 读 [e]。","pi":"变位时重音符号变化：j'intègre, nous intégrons；g 读 [g]；-er 读 [e]，r 不发音。","et":"拉丁语 integrare（使完整），源于 integer（完整的）。同源：intégral, intégration。","ex":[["Il rêve d'intégrer une grande école.","他梦想考入一所名校。"],["Elle s'intègre bien dans l'équipe.","她很好地融入了团队。"]],"co":[["intégrer une école","考入一所学校"],["s'intégrer dans un groupe","融入一个群体"],["intégrer l'équipe","加入团队"]],"sy":[["rejoindre","courant","加入"],["incorporer","soutenu","纳入、合并"],["entrer","courant","进入"]],"fq":"中频。","me":"intégrer ← entier：让自己成为整体的一部分。","tr":{"zh":"我想考入一所好大学。","fr":"Je voudrais intégrer une bonne université.","alt":"J'aimerais entrer dans une bonne université.","note":"intégrer 直接带宾语，不加介词。"}},
 "Passer un examen": {"pos":"v. 动词短语，passer 助动词 avoir（passé）；un examen 阳性名词","s":"参加考试。注意：passer un examen = 去考，不等于通过。通过考试要说 réussir un examen 或 réussir à un examen。","ipa":"[pa.se œ̃ ɛɡ.za.mɛ̃]","ph":"passer：ss 读 [s]，-er 读 [e]；un 读 [œ̃]；examen：ex 读 [ɛɡz]，en 读 [ɛ̃]。","pi":"passer un examen 是「参加」，不是「通过」；ex 在 a 前读 [ɛɡz]；examen 的 en 读 [ɛ̃]，不读 [ɛn]。","et":"passer 来自拉丁语 passus（步），examen 来自拉丁语 examen（称量、检验）。","ex":[["Je vais passer un examen demain.","我明天要考试。"],["Elle a passé son examen de conduite.","她参加了驾照考试。"]],"co":[["passer un examen","参加考试"],["réussir un examen","通过考试"],["rater un examen","考砸了"],["se présenter à un examen","报名参加考试"]],"sy":[["se présenter à","soutenu","参加（考试）"],["réussir","courant","通过"],["rater","familier","考砸"]],"fq":"高频，学生常用。","me":"passer = 经过考试这一关，但不一定通过。","tr":{"zh":"我下周要参加一场考试。","fr":"Je vais passer un examen la semaine prochaine.","alt":"J'ai un examen la semaine prochaine.","note":"近将来：aller + 动词原形。"}},
 "Postuler": {"pos":"v. 动词，第一组（-er），助动词 avoir；常接 à 或 pour","s":"应聘；申请职位或学位。postuler à un emploi = 应聘工作；postuler pour un poste = 申请某职位。名词：une candidature。","ipa":"[pɔs.ty.le]","ph":"pos 读 [pɔs]；tu 读 [ty]，u 读 [y]；-ler 读 [le]，r 不发音。","pi":"u 读 [y]，不是 [u]；结尾 -er 读 [e]；postuler 不是「公布」（post 与 poster 要区别）。","et":"拉丁语 postulare（要求、请求）。英语 postulate 同源。","ex":[["Je vais postuler à cette offre d'emploi.","我要申请这个职位。"],["Elle a postulé dans trois entreprises.","她向三家公司投了申请。"]],"co":[["postuler à un emploi","应聘工作"],["postuler à un poste","申请职位"],["postuler dans une entreprise","向公司投申请"]],"sy":[["faire acte de candidature","soutenu","递交申请"],["candidater","courant","应聘（口语中更常用）"],["demander","courant","请求"]],"fq":"中频，求职话题里常见。","me":"postuler 与英语 postulate 同源：提出「请求」。","tr":{"zh":"我想应聘这个职位。","fr":"Je veux postuler à ce poste.","alt":"Je voudrais postuler pour ce poste.","note":"postuler à + 职位。"}},
 "Présenter": {"pos":"v. 动词（第一组，助动词 avoir），présente / présentons，过去分词 présenté","s":"介绍；呈现；展示。présenter qqn à qqn = 把某人介绍给某人；présenter un projet = 展示、汇报项目。还可指电视节目的主持：présenter le journal。","ipa":"[pʁe.zɑ̃.te]","ph":"é [e]；s 在元音间读 [z]；en [ɑ̃]；结尾 -er 读 [e]，r 不发音。","pi":"s 读 [z]，不读 [s]；不要和 présent（现在；礼物）混淆；se présenter = 自我介绍，是反身动词。","et":"来自拉丁语 praesentare（使在场、呈上）。词族：présent, présentation, représenter。","ex":[["Je vais vous présenter les conditions.","我来向您介绍条件。"],["Je te présente mon ami Paul.","我给你介绍我的朋友保罗。"],["Elle présente le journal du soir.","她主持晚间新闻。"]],"co":[["présenter qqn à qqn","把某人介绍给某人"],["se présenter","自我介绍；出现、前来"],["présenter ses excuses","道歉"],["présenter un projet","展示、汇报项目"]],"sy":[["montrer","courant","给人看，较普通"],["exposer","soutenu","陈述、阐述（观点）"]],"fq":"极高频，日常和工作都常用。","me":"présent（在场的）+ -er：把人带到你面前，就是「介绍」。","tr":{"zh":"我想把我姐姐介绍给你。","fr":"Je voudrais te présenter ma sœur.","alt":"Je te présente ma sœur.","note":"présenter A à B：介绍 A 给 B。"}},
 "Promettre": {"pos":"v. 动词（不规则，同 mettre，助动词 avoir），过去分词 promis","s":"承诺；答应；保证。promettre de + 动词原形 = 答应做某事；promettre qqch à qqn = 向某人许诺某物。口语里 Promis ! = 我保证！","ipa":"[pʁɔ.mɛtʁ]","ph":"pro [pʁɔ]；e 在 mettre 中读 [ɛ]；结尾 -tre 的 e 很轻。","pi":"变位同 mettre：je promets，nous promettons；过去分词 promis 的 s 不发音；后面接 de + 原形，不接 que + 原形。","et":"来自拉丁语 promittere（向前送出、允诺），pro- + mettre。同族：promesse（承诺）。","ex":[["Je te promets de venir demain.","我答应你明天来。"],["Il a promis de m'appeler ce soir.","他答应今晚给我打电话。"],["Promis, je ne le dirai à personne.","我保证，不告诉任何人。"]],"co":[["promettre de + 动词原形","答应做某事"],["promettre qqch à qqn","向某人许诺某物"],["tenir sa promesse","遵守诺言"],["Promis !","我保证！"]],"sy":[["jurer","courant","发誓，比 promettre 更郑重"],["assurer","courant","保证、断言"]],"fq":"高频，日常常用。","me":"pro-（向前）+ mettre（放）：把话先放出去，就是「承诺」。","tr":{"zh":"我答应你，我不会迟到。","fr":"Je te promets que je ne serai pas en retard.","alt":"Promis, je ne serai pas en retard.","note":"promettre que + 直陈式；同一主语时用 promettre de + 原形。"}},
 "Rater": {"pos":"v. 动词（第一组，助动词 avoir），过去分词 raté","s":"错过（火车、机会）；搞砸；考试没过。rater son train / un examen / un rendez-vous。口语里比 manquer 更常用，也带「失手」的意味。","ipa":"[ʁa.te]","ph":"r 是喉音 [ʁ]；a [a]；结尾 -er 读 [e]。","pi":"r 是喉音，不是中文的 l 或 r；不是英语 rate（评价）的意思，「评价」要用 évaluer / noter。","et":"来源不确定。词族：raté（失败的人或事）、ratage（失误）。","ex":[["J'ai raté mon train.","我错过了火车。"],["Il a raté son examen.","他考试没通过。"],["Ne rate pas ce film, il est génial !","别错过这部电影，太棒了！"]],"co":[["rater son train / son bus","错过火车 / 公交"],["rater un examen","考试没过"],["rater un rendez-vous","错过约会"],["Raté !","没成！失败了！"]],"sy":[["manquer","courant","错过（也有「想念」义）"],["louper","familier","错过，更口语"],["échouer","courant","失败（多指考试、计划）"]],"fq":"高频，口语和日常都常用。","me":"想象箭没射中靶：rater = 没中、没赶上。","tr":{"zh":"我错过了最后一班地铁。","fr":"J'ai raté le dernier métro.","alt":"J'ai loupé le dernier métro.","note":"rater 直接接宾语，不加介词。"}},
 "Redoubler": {"pos":"v. 动词（第一组，助动词 avoir），过去分词 redoublé","s":"留级，重读一年（redoubler une classe）；也可指加倍、加剧：redoubler d'efforts（加倍努力）、la pluie redouble（雨下得更大）。","ipa":"[ʁə.du.ble]","ph":"re 读 [ʁə]；ou [u]；bl 连读 [bl]；结尾 -er 读 [e]。","pi":"re- 读 [ʁə]，不读 [ʁe]；留级时宾语常是 une classe / son année；留级的人叫 un redoublant。","et":"re-（再）+ doubler（加倍）。词族：double, redoublement, redoublant。","ex":[["J'ai redoublé mon année d'étude car je n'ai pas assez étudié.","我因为学得不够而留级了。"],["Il a redoublé sa troisième.","他留级读了初三。"],["La pluie redouble.","雨下得更大了。"]],"co":[["redoubler une classe","留级"],["redoubler d'efforts","加倍努力"],["un redoublant / une redoublante","留级生"],["le redoublement","留级（名词）"]],"sy":[["refaire une année","courant","重读一年，较口语"],["passer dans la classe supérieure","courant","升级（反义）"]],"fq":"中频，谈学校时常用。","me":"re-（再）+ doubler（双）：同一年读两遍 = 留级。","tr":{"zh":"他数学不好，所以留级了。","fr":"Il n'était pas bon en maths, alors il a redoublé.","alt":"Il était nul en maths, du coup il a redoublé.","note":"留级用 redoubler，后面常省略宾语。"}},
 "Renoncer": {"pos":"v. 动词（第一组，助动词 avoir），nous renonçons，过去分词 renoncé","s":"放弃；不再坚持。固定搭配 renoncer à + 名词 / 动词原形。口语里 J'y renonce = 我不管了，放弃了。","ipa":"[ʁə.nɔ̃.se]","ph":"re [ʁə]；on [ɔ̃]；c 在 e 前读 [s]；结尾 -er 读 [e]。","pi":"一定要加 à：renoncer à qqch，不能直接接宾语；nous renonçons 要写 ç 保持 [s] 的音。","et":"来自拉丁语 renuntiare（声明不要）。词族：renonciation（放弃）。","ex":[["Il ne faut jamais renoncer à ses rêves.","永远不要放弃梦想。"],["J'y renonce, c'est trop difficile.","我放弃了，太难了。"],["Il a renoncé à son voyage.","他放弃了旅行。"]],"co":[["renoncer à qqch","放弃某物"],["renoncer à + 动词原形","放弃做某事"],["renoncer à fumer","戒烟"],["Je renonce !","我放弃！"]],"sy":[["abandonner","courant","放弃，最常用"],["laisser tomber","familier","算了，不管了"],["abdiquer","soutenu","放弃权位，退位"]],"fq":"高频，日常和书面都常用。","me":"re- + nonce（宣告）：宣布「我不要了」= 放弃。","tr":{"zh":"我放弃去海边的计划了。","fr":"J'ai renoncé à mon projet d'aller à la mer.","alt":"J'ai laissé tomber l'idée d'aller à la mer.","note":"renoncer à + 名词或原形。"}},
 "Réussir": {"pos":"v. 动词（第二组，助动词 avoir），je réussis / nous réussissons，过去分词 réussi","s":"成功；做成；考过。réussir à + 原形 = 成功做到；réussir un examen = 通过考试；réussir sa vie = 过得成功。","ipa":"[ʁe.y.siʁ]","ph":"é [e]；u [y]；ss 读 [s]；结尾 -ir 读 [iʁ]。","pi":"re.u.ssir 是三个音节，é 和 u 分开读；成功做到某事要用 réussir à，而不是 réussir de。","et":"16 世纪借自意大利语 riuscire（再出来、结果如何）。词族：réussite（成功）。","ex":[["Elle veut réussir dans la vie.","她想在生活中成功。"],["Il a réussi son examen.","他通过了考试。"],["J'ai réussi à ouvrir la porte.","我成功把门打开了。"]],"co":[["réussir à + 动词原形","成功做到"],["réussir un examen","通过考试"],["réussir sa vie","过上成功的人生"],["une réussite","成功"]],"sy":[["y arriver","courant","做到了，较口语"],["triompher","soutenu","大获全胜"],["échouer","courant","失败（反义）"]],"fq":"极高频，日常常用。","me":"ré-us-sir：想成每一步都「出来」了，最后就成功了。","tr":{"zh":"我终于考过了驾照。","fr":"J'ai enfin réussi mon permis de conduire.","alt":"J'ai enfin eu mon permis.","note":"réussir 直接接考试，不加介词。"}},
 "S'évanouir": {"pos":"v. 动词（反身动词，第二组，助动词 être），elle s'est évanouie","s":"昏倒；晕过去。常说 s'évanouir de peur / de fatigue / de chaleur。书面里也可指「消失、消散」：ses espoirs se sont évanouis。","ipa":"[se.va.nwiʁ]","ph":"s'é 连读为 [se]；v [v]；oui 读 [wi]，nouir = [nwiʁ]。","pi":"助动词用 être：Elle s'est évanouie；主语是女性时过去分词要加 e；ou + i 读 [wi]。","et":"古法语 esvanir，源自拉丁语 evanescere（消散）。词族：évanouissement（昏厥）。","ex":[["Elle a failli s'évanouir de peur.","她吓得差点晕过去。"],["Il s'évanouit à la vue du sang.","他一见血就晕倒。"],["Elle s'est évanouie dans la rue.","她在街上晕倒了。"]],"co":[["s'évanouir de peur / de fatigue","吓晕 / 累晕"],["tomber dans les pommes","昏倒（口语）"],["un évanouissement","昏厥"],["revenir à soi","苏醒"]],"sy":[["perdre connaissance","courant","失去知觉"],["tomber dans les pommes","familier","晕倒（口语）"]],"fq":"中频，日常讲故事时常用。","me":"é-van-ouir：像烟一样 van-ish 地「消散」，人就晕过去了。","tr":{"zh":"天太热，他晕倒了。","fr":"Il faisait très chaud, il s'est évanoui.","alt":"Il a tourné de l'œil à cause de la chaleur.","note":"反身动词，复合时态用 être。"}},
 "S'inscrire": {"pos":"v. 动词（反身动词，不规则，同 écrire，助动词 être），je m'inscris / nous nous inscrivons，过去分词 inscrit","s":"注册；报名；登记。s'inscrire à un cours / au club / à l'université。也可表示「列入」：s'inscrire sur une liste。","ipa":"[sɛ̃.skʁiʁ]","ph":"s'in 读 [sɛ̃]；sc 读 [sk]；ri [ʁi]；结尾 -re 读 [ʁ]。","pi":"变位同 écrire：nous nous inscrivons；过去分词 inscrit 的 t 不发音；报名后面用 à，不是 dans。","et":"来自拉丁语 inscribere（写在上面）。in- + écrire 的意思。词族：inscription（报名），écrire。","ex":[["Je dois m'inscrire au club de sport.","我得报名参加运动俱乐部。"],["Elle s'est inscrite à un cours de français.","她报名了法语课。"],["Tu t'es déjà inscrit à l'université ?","你已经注册大学了吗？"]],"co":[["s'inscrire à un cours / à un club","报名课程 / 俱乐部"],["s'inscrire sur une liste","登记在名单上"],["une inscription","报名；注册"],["se désinscrire","取消注册"]],"sy":[["adhérer","courant","加入（协会、党派）"],["se désinscrire","courant","取消注册（反义）"]],"fq":"高频，办手续时常用。","me":"in + écrire：把名字「写进」名单里 = 报名。","tr":{"zh":"我昨天报名参加了游泳课。","fr":"Je me suis inscrit à un cours de natation hier.","alt":"Hier, je me suis inscrit à la piscine.","note":"反身动词；s'inscrire à + 课程 / 机构。"}},
 "Se fâcher": {"pos":"v. 动词（反身动词，第一组，助动词 être），过去分词 fâché","s":"生气；发火。se fâcher contre qqn = 对某人生气；se fâcher avec qqn = 和某人闹翻、关系破裂。形容词 fâché(e) 也可表示「生气的」或「不和的」。","ipa":"[sə.fɑ.ʃe]","ph":"â 读后 [ɑ]，较长；ch 读 [ʃ]；结尾 -er 读 [e]。","pi":"â 不读成 [a]；Je suis fâché 是「我生气了」，不是「对不起」；复合时态用 être：Ils se sont fâchés。","et":"来源不确定。词族：fâché, fâcheux（令人烦恼的）。","ex":[["Il se fâche très vite.","他很容易生气。"],["Ne te fâche pas, je plaisantais.","别生气，我开玩笑的。"],["Ils se sont fâchés pour une bêtise.","他们为了一件小事闹翻了。"]],"co":[["se fâcher contre qqn","对某人发火"],["se fâcher avec qqn","和某人闹翻"],["être fâché(e)","生气的；闹僵的"],["Ne te fâche pas !","别生气！"]],"sy":[["s'énerver","courant","发火；变得烦躁"],["se mettre en colère","courant","发怒"],["s'emporter","soutenu","怒气冲冲，失控"]],"fq":"高频，日常常用。","me":"fâché 像「发脾气」的怪声：fâ-ché，一脸不高兴。","tr":{"zh":"别生我的气，我不是故意的。","fr":"Ne te fâche pas contre moi, ce n'était pas exprès.","alt":"Fâche-toi pas, je l'ai pas fait exprès.","note":"se fâcher contre qqn；否定命令式：Ne te fâche pas。"}},
 "Se retourner": {"pos":"v. 动词（反身动词，第一组，助动词 être），过去分词 retourné","s":"转过身；回头看。也可指翻身、翻转：se retourner dans son lit；une voiture s'est retournée（翻车）。","ipa":"[sə.ʁə.tuʁ.ne]","ph":"se [sə]；re [ʁə]；ou [u]；r 在 tour 中读 [ʁ]；结尾 -er 读 [e]。","pi":"retourner（回去；翻转）和 se retourner（转身）不同；反身动词复合时态用 être：Je me suis retourné。","et":"re- + tourner（来自拉丁语 tornare，车削）。词族：tourner, retour。","ex":[["La maîtresse se retourne pour voir qui parle.","老师转身看是谁在说话。"],["Je me suis retourné, mais il n'y avait personne.","我回过头，但没有人。"],["Il se retourne dans son lit toute la nuit.","他整夜在床上翻来覆去。"]],"co":[["se retourner pour + 动词原形","转身去做某事"],["se retourner vers qqn","转向某人"],["se retourner dans son lit","在床上翻身"],["une voiture qui se retourne","翻车"]],"sy":[["se tourner","courant","转向（不一定是转身）"],["faire demi-tour","courant","掉头往回走"]],"fq":"中频，日常描述动作时常用。","me":"re-（回）+ tourner（转）：身体向后「转」一圈。","tr":{"zh":"我听到有人叫我，就回头了。","fr":"J'ai entendu quelqu'un m'appeler, alors je me suis retourné.","alt":"Quelqu'un m'a appelé, je me suis retourné.","note":"反身动词：je me suis retourné。"}},
 "Troquer": {"pos":"v. 动词（第一组，助动词 avoir），过去分词 troqué","s":"以物易物；交换；把某物换成另一物。troquer A contre B = 用 A 换 B。也可指生活方式、衣服的改变：troquer le costume contre un jean。","ipa":"[tʁɔ.ke]","ph":"tr [tʁ]；o 读开口 [ɔ]；qu 读 [k]；结尾 -er 读 [e]。","pi":"qu 读 [k]，不读 [kw]；固定用 troquer A contre B；名词是 le troc（易货）。","et":"来源不确定。词族：troc（以物易物）。","ex":[["J'ai troqué mon vélo contre une trottinette.","我用自行车换了一辆滑板车。"],["Il a troqué son costume contre un jean.","他把西装换成了牛仔裤。"],["Ils ont troqué la ville contre la campagne.","他们放弃城市，搬到了乡下。"]],"co":[["troquer A contre B","用 A 换 B"],["le troc","易货"],["faire du troc","以物易物"],["troquer sa vie contre une autre","换一种生活"]],"sy":[["échanger","courant","交换，最常用"],["remplacer","courant","替换"]],"fq":"中低频，偏书面。","me":"troc（易货）+ -er：一个动词，就是「做 troc」。","tr":{"zh":"他把旧手机换成了一本书。","fr":"Il a troqué son vieux téléphone contre un livre.","alt":"Il a échangé son vieux téléphone contre un livre.","note":"troquer A contre B。"}},
 "Bienveillant(e)": {"pos":"adj. 形容词，阴性 bienveillante，复数 bienveillants / bienveillantes","s":"善意的；体贴的；友善的。形容对人宽容、愿意帮助、不带恶意。常用来形容老师、目光、语气：un regard bienveillant。","ipa":"[bjɛ̃.vɛ.jɑ̃]","ph":"bien [bjɛ̃]；ei 读 [ɛ]；ill 读 [j]；ant 读 [ɑ̃]，t 不发音。","pi":"ill 读 [j]，不是 [l]；阴性 bienveillante 要读出 t；注意和 malveillant（怀有恶意的）对照。","et":"bien（好）+ veillant，veillant 来自古义 voulant（想要）：想要别人好。名词 bienveillance。","ex":[["Mon professeur est très bienveillant.","我的老师非常体贴。"],["C'est une personne bienveillante.","她是个善良体贴的人。"],["Elle a un regard bienveillant.","她的目光很温和。"]],"co":[["un regard bienveillant","善意的目光"],["un ton bienveillant","友善的语气"],["bienveillant envers qqn","对某人友善"],["la bienveillance","善意"]],"sy":[["gentil","courant","和善的，更日常"],["attentionné","courant","体贴周到的"],["malveillant","courant","怀有恶意的（反义）"]],"fq":"中频，偏正式、书面。","me":"bien + veillant：「好好地看着你」，所以是体贴。","tr":{"zh":"我们的老板对大家都很友善。","fr":"Notre patron est bienveillant avec tout le monde.","alt":"Notre chef est vraiment sympa avec tout le monde.","note":"bienveillant avec / envers qqn。"}},
 "Captivant(e)": {"pos":"adj. 形容词，阴性 captivante，复数 captivants / captivantes","s":"引人入胜的；令人着迷的。形容书、电影、故事、演讲：un film captivant。不指「被囚禁的」，那是 captif。","ipa":"[kap.ti.vɑ̃]","ph":"c [k]；a [a]；ti 读 [ti]（不是 [si]）；ant 读 [ɑ̃]。","pi":"-ti- 读 [ti]，不读 [si]；captivant（引人入胜）和 captif（被俘的）意思不同。","et":"来自动词 captiver，词源拉丁语 captivus（被俘的）：心被「抓住」。词族：captiver, captivité。","ex":[["Ce livre est vraiment captivant.","这本书真的很吸引人。"],["J'ai vu un film captivant hier soir.","昨晚我看了一部很吸引人的电影。"],["Son histoire est captivante.","他的故事引人入胜。"]],"co":[["un livre / un film captivant","引人入胜的书 / 电影"],["captiver l'attention","吸引注意力"],["captiver le public","吸引观众"],["une histoire captivante","迷人的故事"]],"sy":[["passionnant","courant","令人着迷的"],["fascinant","courant","迷人的"],["ennuyeux","courant","无聊的（反义）"]],"fq":"中频，常用来夸书和电影。","me":"captif（被抓住）+ -ant：把你的注意力「抓住」。","tr":{"zh":"这个展览真的很吸引人。","fr":"Cette exposition est vraiment captivante.","alt":"Cette expo est super captivante.","note":"形容词跟随名词的阴阳性数：captivante。"}},
 "Collaboratif / Collaborative": {"pos":"adj. 形容词，阳性 collaboratif，阴性 collaborative，复数 collaboratifs / collaboratives","s":"协作的；合作的；多人共同完成的。常见于工作和网络：un outil collaboratif（协作工具）、l'économie collaborative（共享经济）。","ipa":"[kɔ.la.bɔ.ʁa.tif]","ph":"o 读开口 [ɔ]；ti 读 [ti]；阳性结尾 f 读 [f]，阴性 -ive 读 [iv]。","pi":"阳性 [tif]，阴性 [tiv]，f 变 v；五个音节，不要说漏 -bo-。","et":"来自 collaborer，拉丁语 com-（一起）+ laborare（工作）。词族：collaboration, collaborateur。","ex":[["C'est un travail collaboratif.","这是协作性的工作。"],["Nous utilisons un outil collaboratif.","我们使用协作工具。"],["Cette plateforme est collaborative.","这个平台是协作式的。"]],"co":[["un travail collaboratif","协作的工作"],["une plateforme collaborative","协作平台"],["l'économie collaborative","共享经济"],["un projet collaboratif","合作项目"]],"sy":[["coopératif","courant","合作的"],["participatif","courant","参与式的"]],"fq":"中频，工作和科技话题常见。","me":"col-（一起）+ labor（工作）：一起工作 = 协作。","tr":{"zh":"我们在一个协作平台上工作。","fr":"Nous travaillons sur une plateforme collaborative.","alt":"On bosse sur une plateforme collaborative.","note":"plateforme 是阴性，所以用 collaborative。"}},
 "Contraignant(e)": {"pos":"adj. 形容词，阴性 contraignante，复数 contraignants / contraignantes","s":"限制性强的；束缚的；让人受约束的。形容规定、时间表、工作：des horaires contraignants。名词是 une contrainte（限制）。","ipa":"[kɔ̃.tʁɛ.ɲɑ̃]","ph":"con [kɔ̃]；tr [tʁ]；ai [ɛ]；gn 读 [ɲ]（像「尼」）；ant [ɑ̃]。","pi":"gn 读 [ɲ]，不读 [g] + [n]；ai 读 [ɛ]；它是 contraindre（强迫）的现在分词形式的形容词。","et":"来自动词 contraindre，拉丁语 constringere（捆紧、强迫）。词族：contrainte, contraindre。","ex":[["Ce règlement est très contraignant.","这个规定限制很多。"],["Les horaires sont contraignants.","时间安排束缚很大。"],["Ce n'est pas contraignant du tout.","这一点都不麻烦。"]],"co":[["un règlement contraignant","限制很多的规定"],["des horaires contraignants","束缚人的作息"],["une obligation contraignante","强制性义务"],["une contrainte","限制；约束"]],"sy":[["astreignant","courant","费神费力的（多指工作）"],["strict","courant","严格的"],["souple","courant","灵活的（反义）"]],"fq":"中频，工作和规定话题常见。","me":"contraindre（逼迫）+ -ant：一直「逼着」你，所以束缚。","tr":{"zh":"这份工作的时间表限制太多了。","fr":"Les horaires de ce travail sont trop contraignants.","alt":"Les horaires de ce boulot sont vraiment contraignants.","note":"形容词 contraignant 随名词变阴阳性。"}},
 "Embauché(e)": {"pos":"adj. 形容词（动词 embaucher 的过去分词），阴性 embauchée，复数 embauchés / embauchées","s":"被录用的；被雇用的。être embauché(e) = 被公司录用。动词 embaucher = 雇用；名词 une embauche = 雇用。反义：être licencié（被解雇）。","ipa":"[ɑ̃.bo.ʃe]","ph":"em [ɑ̃]；au [o]；ch [ʃ]；é [e]。","pi":"em 读 [ɑ̃]；ch 读 [ʃ]；阴性 embauchée 多一个 e，但发音相同。","et":"来源不确定。词族：embaucher（雇用）、embauche（雇用）。反义：licencier。","ex":[["Il a été embauché hier.","他昨天被录用了。"],["Elle a été embauchée par une grande entreprise.","她被一家大公司录用了。"],["Tu es embauché !","你被录用了！"]],"co":[["être embauché(e) en CDI","被录用为无固定期限合同员工"],["être embauché(e) en CDD","被录用为固定期限合同员工"],["embaucher qqn","雇用某人"],["une offre d'embauche","录用通知"]],"sy":[["recruté","courant","被招聘的"],["engagé","courant","被雇用的"],["licencié","courant","被解雇的（反义）"]],"fq":"中频，求职话题常见。","me":"em-bauche：「进入」了工作岗位的人。","tr":{"zh":"她上个月被这家公司录用了。","fr":"Elle a été embauchée par cette entreprise le mois dernier.","alt":"Cette entreprise l'a embauchée le mois dernier.","note":"被动态：être + 过去分词，要和主语配合。"}},
 "Mort(e)": {"pos":"adj. 形容词，阴性 morte；也可作名词 un mort / une morte；是 mourir 的过去分词（助动词 être）","s":"死的；枯萎的；没有生气的。une feuille morte = 落叶；une plante morte = 枯死的植物。口语里 mort de fatigue / de rire = 累死了 / 笑死了。","ipa":"[mɔʁ]","ph":"o 读开口 [ɔ]；r [ʁ]；阳性 t 不发音，阴性 morte 读 [mɔʁt]。","pi":"阳性 mort 的 t 不发音，阴性 morte 才读 t；不要和 mord（咬）混淆，它们读音一样。","et":"来自拉丁语 mortuus（死去的）。词族：mourir, mortel, la mort。","ex":[["En automne, il y a beaucoup de feuilles mortes.","秋天有很多落叶。"],["Mon poisson est mort.","我的鱼死了。"],["Cette plante est morte.","这棵植物枯死了。"]],"co":[["une feuille morte","落叶"],["une nature morte","静物画"],["mort(e) de fatigue","累得要死"],["un temps mort","冷场；空档"]],"sy":[["décédé","soutenu","已故的（郑重）"],["défunt","soutenu","已逝的（书面）"],["vivant","courant","活着的（反义）"]],"fq":"极高频，日常常用。","me":"mort ≈ 「墓」：m-o-r-t 像一座小碑。","tr":{"zh":"花园里的玫瑰都枯死了。","fr":"Les roses du jardin sont toutes mortes.","alt":"Toutes les roses du jardin ont crevé.","note":"形容词与名词配合：roses 阴性复数，所以 mortes。"}},
 "Motivant(e)": {"pos":"adj. 形容词，阴性 motivante，复数 motivants / motivantes","s":"鼓舞人心的；能激发动力的。形容事物或人使你想去做：un discours motivant。对「被激励的人」要用 motivé(e)，不是 motivant。","ipa":"[mɔ.ti.vɑ̃]","ph":"mo 读开口 [mɔ]；ti [ti]；v [v]；ant [ɑ̃]。","pi":"motivant（激励他人的）和 motivé（自己有动力的）不同；-ti- 读 [ti]。","et":"来自 motiver，词根拉丁语 motivus（促使行动的），与 movere（移动）有关。词族：motivation, motif。","ex":[["Son discours était très motivant.","他的演讲很鼓舞人心。"],["Un bon prof est motivant.","好老师能激励学生。"],["C'est un travail motivant.","这是一份有激励性的工作。"]],"co":[["un discours motivant","鼓舞人心的演讲"],["un salaire motivant","有吸引力的薪资"],["être motivé(e)","有干劲"],["la motivation","动力"]],"sy":[["encourageant","courant","鼓励人的"],["stimulant","courant","令人振奋的"],["démotivant","courant","令人泄气的（反义）"]],"fq":"中频，工作和学习话题常见。","me":"motiv（动机）+ ant：给你「动起来」的力量。","tr":{"zh":"老师的话让我很有动力。","fr":"Les paroles du professeur sont très motivantes pour moi.","alt":"Ce que dit le prof me motive vraiment.","note":"motivant 形容事物；motivé 形容人。"}},
 "Performant(e)": {"pos":"adj. 形容词，阴性 performante，复数 performants / performantes","s":"性能好的；高效的；表现出色的。常形容机器、系统、公司：un ordinateur performant。不是「表演的」。","ipa":"[pɛʁ.fɔʁ.mɑ̃]","ph":"er 读 [ɛʁ]；o 读开口 [ɔ]；r [ʁ]；ant [ɑ̃]。","pi":"不是「表演」的意思；performance 在法语里常指「性能；成绩」。","et":"来自 performance 的同族词，近代借自英语 performance；词族：performance, performer（取得成绩）。","ex":[["Cet ordinateur est très performant.","这台电脑性能很强。"],["Cette entreprise est très performante.","这家公司业绩很好。"],["J'ai besoin d'un téléphone plus performant.","我需要一部性能更好的手机。"]],"co":[["un ordinateur performant","高性能电脑"],["une entreprise performante","业绩出色的公司"],["un outil performant","好用的工具"],["un moteur performant","高性能引擎"]],"sy":[["efficace","courant","有效的"],["puissant","courant","强大的"]],"fq":"中频，科技和商业话题常见。","me":"perform + -ant：表现（perform）得好，就是性能好。","tr":{"zh":"我们需要一个性能更好的系统。","fr":"Nous avons besoin d'un système plus performant.","alt":"Il nous faut un système plus performant.","note":"plus performant：比较级。"}},
 "Productif / Productive": {"pos":"adj. 形容词，阳性 productif，阴性 productive，复数 productifs / productives","s":"有成效的；多产的；有效率的。形容会议、一天、工作、人：une journée productive。名词是 la productivité。","ipa":"[pʁɔ.dyk.tif]","ph":"pro [pʁɔ]；u 读 [y]；ct 两个辅音都读；阳性 -if [if]，阴性 -ive [iv]。","pi":"u 读 [y]（嘴唇圆起来）；阳性 [tif]，阴性 [tiv]；ct 中 c 要读。","et":"来自拉丁语 producere（带出、产生）。词族：produire, produit, production, productivité。","ex":[["La réunion a été très productive.","这次会议很有成效。"],["Je suis plus productif le matin.","我早上效率更高。"],["Nous avons eu une journée productive.","我们过了高效的一天。"]],"co":[["une réunion productive","有成效的会议"],["une journée productive","高效的一天"],["être plus productif le matin","早上效率更高"],["la productivité","生产力；效率"]],"sy":[["efficace","courant","有效的"],["fructueux","soutenu","富有成果的"],["improductif","courant","无成效的（反义）"]],"fq":"中频，工作和学习话题常见。","me":"produit（产品）+ -if：能「产出东西」的。","tr":{"zh":"今天我们开了一场很有成效的会议。","fr":"Aujourd'hui, nous avons eu une réunion très productive.","alt":"On a eu une réunion super productive aujourd'hui.","note":"réunion 是阴性，所以用 productive。"}},
 "Sévère": {"pos":"adj. 形容词，阴阳性同形 sévère，复数 sévères","s":"严厉的；严格的；苛刻的。形容人、规定、批评、处罚：un professeur sévère, une punition sévère。一般不用来形容疼痛或病情。","ipa":"[se.vɛʁ]","ph":"é [e]；è 读 [ɛ]；r [ʁ]；结尾 e 不发音。","pi":"è 读开口 [ɛ]，不读 [e]；阴阳性同形，不用改。","et":"来自拉丁语 severus（严肃的、严厉的）。词族：sévérité。","ex":[["Le juge a été sévère.","法官很严厉。"],["Mon père est sévère mais juste.","我父亲严厉但公正。"],["Le prof est sévère avec nous.","老师对我们很严格。"]],"co":[["sévère avec / envers qqn","对某人严厉"],["une punition sévère","严厉的处罚"],["un jugement sévère","严苛的评判"],["la sévérité","严厉"]],"sy":[["strict","courant","严格的"],["dur","courant","严厉、苛刻的"],["indulgent","courant","宽容的（反义）"]],"fq":"中频，日常和书面都用。","me":"sévère → severus：古罗马人的「严肃脸」。","tr":{"zh":"我们的数学老师很严厉。","fr":"Notre professeur de maths est très sévère.","alt":"Notre prof de maths est vraiment sévère.","note":"sévère avec qqn：对某人严厉。"}},
 "Stimulant(e)": {"pos":"adj. 形容词，阴性 stimulante，复数 stimulants / stimulantes；也可作名词 un stimulant","s":"令人振奋的；有激励作用的；有刺激性的。形容项目、环境、挑战：un projet stimulant。作名词 un stimulant = 兴奋剂、提神之物（如咖啡）。","ipa":"[sti.my.lɑ̃]","ph":"st 在词首连读 [st]；i [i]；u 读 [y]；ant [ɑ̃]。","pi":"u 读 [y]，嘴唇要圆；词首 st 不要在中间加 [ə]。","et":"来自 stimuler，拉丁语 stimulare（刺激、催促），stimulus 本义是「刺棒」。词族：stimuler, stimulation。","ex":[["C'est un projet très stimulant.","这是一个很有激励性的项目。"],["Cette ville est très stimulante.","这座城市很有活力。"],["Le café est un stimulant.","咖啡是一种提神之物。"]],"co":[["un projet stimulant","有激励性的项目"],["un environnement stimulant","令人振奋的环境"],["un défi stimulant","刺激的挑战"],["stimuler la mémoire","刺激记忆"]],"sy":[["motivant","courant","鼓舞人的"],["passionnant","courant","令人着迷的"]],"fq":"中频，工作和学习话题常见。","me":"stimul-：像用棒子轻轻「戳」你一下，让你动起来。","tr":{"zh":"这份新工作很有挑战，也很令人振奋。","fr":"Ce nouveau travail est un défi très stimulant.","alt":"Ce nouveau boulot est un vrai défi, c'est stimulant.","note":"stimulant 随名词变阴阳性。"}},
 "(Se) prendre la tête": {"pos":"loc. 动词短语（口语），prendre 不规则，je prends / nous prenons，过去分词 pris","s":"想太多；钻牛角尖；为小事烦恼。反身用法 se prendre la tête = 自己想不开、和人争吵；及物用法 prendre la tête à qqn = 让某人心烦。属口语。","ipa":"[(sə).pʁɑ̃dʁ.la.tɛt]","ph":"prendre 读 [pʁɑ̃dʁ]，an [ɑ̃]，结尾 -dre 的 e 很轻；tête 读 [tɛt]，ê [ɛ]。","pi":"prendre 中 en 读 [ɑ̃]；tête 的 t 要读出来；Ça me prend la tête 是「这让我心烦」。","et":"字面「拿脑袋」，指脑子被占满。词族：une prise de tête（让人烦恼的事）。","ex":[["Ne te prends pas la tête avec ça.","别为这个钻牛角尖。"],["Arrête de te prendre la tête pour rien.","别为没意义的事费脑筋了。"],["Cette situation me prend la tête.","这种情况让我心烦。"]],"co":[["Ne te prends pas la tête !","别想太多！"],["prendre la tête à qqn","让某人心烦"],["une prise de tête","令人头疼的事"],["Pas de prise de tête !","别太费劲！"]],"sy":[["se tracasser","courant","操心、发愁"],["se casser la tête","courant","绞尽脑汁"],["s'embêter","familier","发愁；觉得烦"]],"fq":"高频，年轻人口语里很常用。","me":"脑袋被「拿走」又被占满，所以头疼，想太多。","tr":{"zh":"别为这么小的事想太多。","fr":"Ne te prends pas la tête pour si peu.","alt":"Te prends pas la tête pour ça.","note":"口语；否定命令式 Ne te prends pas la tête。"}},
 "Avant tout": {"pos":"loc. 副词短语","s":"首先；最重要的是；比什么都重要。用来强调最优先的事：Il faut avant tout rester calme。","ipa":"[a.vɑ̃.tu]","ph":"a [a]；van 读 [vɑ̃]；tout 读 [tu]，ou [u]，t 不发音。","pi":"tout 的 t 不发音；avant tout（最重要）和 avant tout le monde（比所有人先）意思不同。","et":"avant（前）+ tout（一切）：「在一切之前」。avant 来自拉丁语 ab ante。","ex":[["Il faut avant tout rester calme.","最重要的是保持冷静。"],["Avant tout, merci de votre aide.","首先，谢谢您的帮助。"],["Ce qui compte avant tout, c'est la santé.","最重要的是健康。"]],"co":[["avant tout","首先；最重要的是"],["avant toute chose","首先，在做任何事之前"],["avant tout le monde","比所有人先（意思不同）"],["et avant tout","而且首先"]],"sy":[["surtout","courant","尤其是"],["d'abord","courant","首先（顺序）"],["en premier lieu","soutenu","第一点"]],"fq":"高频，口语和书面都常用。","me":"avant（前面）+ tout（一切）：排在一切前面的事。","tr":{"zh":"最重要的是，你要好好休息。","fr":"Avant tout, tu dois bien te reposer.","alt":"Le plus important, c'est que tu te reposes bien.","note":"avant tout 放句首或句中都可以。"}},
 "Ça alors !": {"pos":"loc. 感叹语（口语）","s":"哎呀！天哪！表示惊讶、意外，好坏都可以，常用于出乎意料的事或人：Ça alors ! Tu es là !","ipa":"[sa.a.lɔʁ]","ph":"ça 的 ç 读 [s]；ça 和 alors 之间不连读，也不省音，分成 [sa] [a.lɔʁ]；alors 的 s 不发音，结尾读 [ɔʁ]。","pi":"不要把 ça alors 读成 c'alors；alors 末尾的 s 不发音；惊讶时语调上扬。","et":"ça（这个）+ alors（那么）：直译「这个，那么！」，口语固定感叹。","ex":[["Ça alors ! Je ne m'y attendais pas.","天哪！我没想到。"],["Ça alors, tu es déjà là !","天哪，你已经到了！"],["Ça alors, quelle surprise !","天哪，真是个惊喜！"]],"co":[["Ça alors !","天哪！"],["Ça, alors !","哎呀！（语气更强）"],["Ça alors, quelle surprise !","天哪，好惊喜！"]],"sy":[["Oh là là !","familier","哎呀、天哪"],["Mince alors !","familier","哎呀（轻度）"],["Incroyable !","courant","难以置信！"]],"fq":"中高频，口语常用。","me":"ça（这个）+ alors（那么）：「这个嘛，竟然！」","tr":{"zh":"天哪，你怎么在这儿？","fr":"Ça alors, qu'est-ce que tu fais ici ?","alt":"Ça alors, tu fais quoi ici ?","note":"Ça alors 后面常接句子，说明惊讶的原因。"}},
 "Être à la retraite": {"pos":"loc. 动词短语（être 变位：je suis, il est, ils sont）","s":"已退休；在退休状态。动作是 partir à la retraite / prendre sa retraite（退休）。une retraite 也指退休金；un retraité / une retraitée = 退休的人。","ipa":"[ɛtʁ.a.la.ʁə.tʁɛt]","ph":"être [ɛtʁ]；retraite 读 [ʁə.tʁɛt]，ai [ɛ]；结尾 e 不发音。","pi":"是 à la retraite，不是 en retraite；retraite 的 ai 读 [ɛ]；不要和 retrait（取款；撤回）混淆。","et":"retrait（撤回）+ -e：本义「撤退」，引申为「退下来」。同族：retirer。","ex":[["Mes grands-parents sont à la retraite.","我的祖父母已经退休了。"],["Mon père part à la retraite en juin.","我父亲六月退休。"],["Elle est à la retraite depuis deux ans.","她已经退休两年了。"]],"co":[["prendre sa retraite","退休"],["partir à la retraite","去退休"],["l'âge de la retraite","退休年龄"],["un retraité / une retraitée","退休人员"]],"sy":[["retraité","courant","退休的人（名词）"],["prendre sa retraite","courant","办理退休"]],"fq":"高频，日常常用。","me":"retraite = 从工作中「撤退」下来。","tr":{"zh":"我的邻居去年退休了。","fr":"Mon voisin a pris sa retraite l'année dernière.","alt":"Mon voisin est parti à la retraite l'année dernière.","note":"动作用 prendre sa retraite，状态用 être à la retraite。"}},
 "Être au chômage": {"pos":"loc. 动词短语（être 变位）；le chômage = n.m. 阳性名词","s":"失业。chômage 是名词（失业），un chômeur / une chômeuse = 失业者。口语里 toucher le chômage = 领失业救济金。","ipa":"[ɛtʁ.o.ʃo.maʒ]","ph":"au 读 [o]；chô 读 [ʃo]；ô [o]；age 读 [aʒ]。","pi":"chô- 的 ch 读 [ʃ]；不要说成 en chômage；g 在 a 后的 -age 读 [ʒ]。","et":"来自动词 chômer（停工、休息）。词族：chômage, chômeur。","ex":[["Il est au chômage depuis six mois.","他失业六个月了。"],["Elle est au chômage depuis janvier.","她从一月起一直失业。"],["Beaucoup de jeunes sont au chômage.","很多年轻人失业。"]],"co":[["le taux de chômage","失业率"],["un chômeur / une chômeuse","失业者"],["perdre son emploi","失去工作"],["toucher le chômage","领失业救济金"]],"sy":[["sans emploi","courant","无业的"],["sans travail","courant","没工作的"]],"fq":"高频，日常和新闻都常用。","me":"chômage 听起来像「休眠」：不用工作的状态。","tr":{"zh":"我哥哥失业三个月了。","fr":"Mon frère est au chômage depuis trois mois.","alt":"Mon frère n'a pas de travail depuis trois mois.","note":"depuis + 时间段，现在时表示持续。"}},
 "Faire un burn-out": {"pos":"loc. 动词短语；un burn-out = n.m. 阳性名词，复数 burn-out(s)","s":"因压力过大而职业倦怠、身心崩溃。也说 être en burn-out（处于倦怠崩溃中）。多指工作过度劳累造成的严重疲惫。","ipa":"[fɛʁ.œ̃.bœʁ.naut]","ph":"faire [fɛʁ]；un [œ̃]；bur 读 [bœʁ]；out 读 [aut]，ou 读 [au]。","pi":"burn-out 来自外来语，读 [bœʁ.naut]；ou 读 [au]，不是 [u]。","et":"借自英语 burnout（烧尽）。词族：burn-out，也写作 burnout。","ex":[["Il a fait un burn-out à cause du stress.","他因压力过大而职业倦怠。"],["Elle a fait un burn-out après des mois de travail.","她连续工作几个月后精神崩溃。"],["Il est en burn-out depuis un mois.","他倦怠崩溃已经一个月了。"]],"co":[["faire un burn-out","倦怠崩溃"],["être en burn-out","处于倦怠崩溃中"],["un arrêt maladie","病假"],["le stress au travail","工作压力"]],"sy":[["craquer","familier","撑不住、崩溃"],["s'épuiser","courant","精疲力竭"]],"fq":"中频，工作和健康话题常见。","me":"burn（烧）+ out（尽）：像蜡烛烧尽。","tr":{"zh":"她工作太多，最后崩溃了。","fr":"Elle travaillait trop, elle a fini par faire un burn-out.","alt":"Elle bossait trop, elle a fait un burn-out.","note":"finir par + 原形：最后……"}},
 "Garder le moral": {"pos":"loc. 动词短语（garder：第一组，助动词 avoir）；le moral = n.m. 阳性名词","s":"保持好心态；打起精神；不灰心。le moral = 情绪、士气。garder le moral 常用来安慰人：Gardez le moral !","ipa":"[ɡaʁ.de.lə.mɔ.ʁal]","ph":"garder [ɡaʁ.de]；le 读 [lə]；moral 读 [mɔ.ʁal]，l 要读出来。","pi":"le moral（精神状态，阳性）≠ la morale（道德；寓意，阴性）；冠词不同，意思完全不同。","et":"moral 来自拉丁语 moralis（风俗的）。le moral 指「精神状态」是近代用法。","ex":[["Il est important de garder le moral.","保持好心态很重要。"],["Gardez le moral, ça va aller !","打起精神，会好的！"],["Malgré la pluie, on a gardé le moral.","尽管下雨，我们还是保持好心情。"]],"co":[["avoir le moral","情绪好"],["ne pas avoir le moral","情绪低落"],["remonter le moral à qqn","给某人鼓劲"],["avoir le moral à zéro","情绪跌到谷底"]],"sy":[["rester positif","courant","保持积极"],["tenir bon","courant","坚持住"]],"fq":"高频，日常常用。","me":"garder（保住）+ moral（士气）：别让士气掉下去。","tr":{"zh":"尽管有困难，他还是保持着好心态。","fr":"Malgré les difficultés, il garde le moral.","alt":"Même si c'est dur, il garde le moral.","note":"malgré + 名词；garder le moral 不加冠词变化。"}},
 "Le chouchou de la maîtresse": {"pos":"loc. 名词短语；le chouchou（阳性）/ la chouchoute（阴性）","s":"老师的宠儿；被偏爱的学生。chouchou 指被偏爱的人；la maîtresse 在法国小学里指女老师（也有「情妇」的意思，要看语境）。chouchouter = 宠着。","ipa":"[lə.ʃu.ʃu.də.la.mɛ.tʁɛs]","ph":"chou 读 [ʃu]，ou [u]；chouchou [ʃu.ʃu]；maîtresse 读 [mɛ.tʁɛs]，î 读 [ɛ]。","pi":"ch 读 [ʃ]；maîtresse 的 î 读 [ɛ]；chouchou 也指「发圈」，要看语境。","et":"chouchou 大概是 chou（亲昵称呼 mon chou）的重叠形式。maîtresse 来自 maître 的阴性。","ex":[["C'est le chouchou de la maîtresse.","他是老师的宠儿。"],["Elle est la chouchoute de la prof.","她是老师的宠儿。"],["Il est le chouchou de ses parents.","他是父母的心头肉。"]],"co":[["le chouchou / la chouchoute","宠儿"],["chouchouter qqn","宠着某人"],["le chouchou du prof","老师的宠儿"],["un chouchou pour les cheveux","发圈"]],"sy":[["le préféré","courant","最受偏爱的人"],["le favori","courant","宠儿、热门人选"],["le fayot","familier","马屁精（带贬义）"]],"fq":"中频，学校话题里很常见。","me":"chou-chou 像是叠音的昵称：被偏爱的小宝贝。","tr":{"zh":"大家都说他是老师的宠儿。","fr":"Tout le monde dit que c'est le chouchou de la maîtresse.","alt":"Tout le monde dit qu'il est le chouchou de la prof.","note":"chouchou 是阳性，指女生用 chouchoute。"}},
 "Mettre un terme à": {"pos":"loc. 动词短语（mettre 不规则，过去分词 mis）；un terme = n.m. 阳性名词","s":"结束；终止。mettre un terme à qqch，后面接名词，比 arrêter 更正式，常见于新闻、公文。同义：mettre fin à。","ipa":"[mɛtʁ.œ̃.tɛʁm.a]","ph":"mettre [mɛtʁ]；un [œ̃]；terme 读 [tɛʁm]，er 读 [ɛʁ]，m 要读出来。","pi":"后面必须加 à；terme 是阳性；terme 的 m 要读出来。","et":"terme 来自拉丁语 terminus（界限）。词族：terminer, terminal, exterminer。","ex":[["Ils ont mis un terme à leur relation.","他们结束了这段关系。"],["Le gouvernement veut mettre un terme à cette crise.","政府想结束这场危机。"],["Il faut mettre un terme à ces disputes.","必须结束这些争吵。"]],"co":[["mettre un terme à qqch","结束某事"],["mettre fin à","结束"],["arriver à son terme","到期；临近结束"],["à terme","最终；长期来看"]],"sy":[["mettre fin à","courant","结束，最常用"],["arrêter","courant","停止"],["clore","soutenu","了结（郑重）"]],"fq":"中频，新闻和书面常见。","me":"mettre（放）+ terme（终点）：把终点放上去，事情就结束了。","tr":{"zh":"公司决定结束这个项目。","fr":"L'entreprise a décidé de mettre un terme à ce projet.","alt":"L'entreprise a décidé d'arrêter ce projet.","note":"mettre un terme à + 名词。"}},
 "Plus ou moins": {"pos":"loc. 副词短语","s":"差不多；大致；或多或少。表示程度不精确：J'ai plus ou moins fini。也可表示「还凑合」：C'est plus ou moins vrai。","ipa":"[ply.zu.mwɛ̃]","ph":"plus 与 ou 之间连读，s 读 [z]；ou 读 [u]；moins 读 [mwɛ̃]，oi 读 [wɛ]，ins 读 [ɛ̃]。","pi":"plus ou 要连读成 [ply.zu]；moins 的 s 不发音；oi 读 [wɛ̃] 而不是 [wa]。","et":"来自拉丁语 plus 和 minus（更多、更少），两词并列。","ex":[["J'ai plus ou moins fini mon travail.","我差不多完成了工作。"],["C'est plus ou moins vrai.","这多多少少是真的。"],["Il est plus ou moins d'accord.","他大致同意。"]],"co":[["plus ou moins","差不多；大致"],["ni plus ni moins","不多不少，恰恰就是"],["plus ou moins bien","好坏不一；还凑合"],["plus ou moins d'accord","大致同意"]],"sy":[["à peu près","courant","大约"],["environ","courant","大约（数量）"],["grosso modo","familier","大致上"]],"fq":"高频，口语常用。","me":"plus（多）or moins（少）：不多不少，差不多。","tr":{"zh":"我差不多明白了。","fr":"J'ai plus ou moins compris.","alt":"J'ai à peu près compris.","note":"plus ou moins 放在助动词和过去分词之间或句尾。"}},
 "Sous le même toit": {"pos":"loc. 副词短语（介词短语）；le toit = n.m. 阳性名词，复数 toits","s":"同住一个屋檐下；在同一屋里生活。vivre / habiter sous le même toit。也常见 sous un même toit。toit 本义是「屋顶」，在这里指「住处」。","ipa":"[su.lə.mɛm.twa]","ph":"sous 读 [su]，s 不发音；même 读 [mɛm]，ê [ɛ]；toit 读 [twa]，oi [wa]，t 不发音。","pi":"sous 的 s 不发音；même 在名词前表示「同一个」，在名词后表示「本身」；toit 末尾 t 不发音。","et":"toit 来自拉丁语 tectum（有遮盖的东西）。词族：toiture, protéger 的词源是 tegere（盖）。","ex":[["Ils vivent sous le même toit.","他们同住一个屋檐下。"],["Trois générations vivent sous le même toit.","三代人同住一个屋檐下。"],["On habite sous le même toit, mais on se voit peu.","我们同住一个屋檐下，但很少见面。"]],"co":[["vivre sous le même toit","同住"],["habiter sous un même toit","同住一个屋檐下"],["un toit","屋顶；住处"],["avoir un toit","有个住处"]],"sy":[["ensemble","courant","一起"],["cohabiter","courant","同住、共处"]],"fq":"中频，描述家庭和同住话题。","me":"toit 像一个小房子：同一个屋顶下，就是住在一起。","tr":{"zh":"他们几年来一直住在同一个屋檐下。","fr":"Ils vivent sous le même toit depuis des années.","alt":"Ça fait des années qu'ils habitent sous le même toit.","note":"depuis + 时间段，现在时表示持续。"}},
 "Un bout de ...": {"pos":"loc. 名词短语；un bout = n.m. 阳性名词，复数 bouts","s":"一小块……；一小段……。un bout de pain / de papier / de fromage。后面接不带冠词的名词。bout 的本义是「端、头」，au bout de = 在……之后。","ipa":"[œ̃.bu.də]","ph":"un [œ̃]；bout 读 [bu]，ou [u]，t 不发音；de 读 [də]。","pi":"bout 末尾 t 不发音；de 后面的名词不加冠词，说 un bout de pain，不说 un bout du pain。","et":"来自动词 bouter（推、撞）的旧义，词族：bout（端头）。来源细节不确定。","ex":[["Je voudrais un bout de fromage.","我想要一小块奶酪。"],["Tu veux un bout de pain ?","你要一小块面包吗？"],["J'ai un bout de papier dans ma poche.","我口袋里有一小张纸。"]],"co":[["un bout de pain / de papier","一小块面包 / 一小张纸"],["un bout de chemin","一小段路"],["au bout de","过了……之后"],["un petit bout de","一点点"]],"sy":[["un morceau de","courant","一块"],["un peu de","courant","一点"],["un brin de","courant","一丝（多用于抽象的事物）"]],"fq":"高频，日常口语常用。","me":"bout = 末端的小块：切下来的那一小段。","tr":{"zh":"你想要一小块蛋糕吗？","fr":"Tu veux un bout de gâteau ?","alt":"Tu veux un morceau de gâteau ?","note":"un bout de + 不加冠词的名词。"}},
 "Du venin": {"pos":"n.m. 阳性名词，复数 venins；常带部分冠词 du","s":"毒液。指蛇、蜘蛛、蝎子等动物咬或蜇时注入的毒；比 le poison（泛指的毒药）更具体。比喻义：cracher son venin = 恶言相向、毒舌。","ipa":"[və.nɛ̃]","ph":"ve 读 [və]；in 读鼻化元音 [ɛ̃]，n 不发音。","pi":"venin 结尾读 [ɛ̃]，n 不发音；du venin 里的 du = de + le，表示「一些毒液」。","et":"来自拉丁语 venenum（毒药）。词族：venimeux（有毒的）, envenimer（使恶化）。","ex":[["Ce serpent a du venin.","这条蛇有毒液。"],["Le venin de la vipère est dangereux.","蝮蛇的毒液很危险。"],["Elle crache son venin sur tout le monde.","她对所有人恶语相向。"]],"co":[["le venin d'un serpent","蛇毒"],["cracher son venin","恶语相向"],["un sérum antivenin","抗蛇毒血清"],["venimeux / venimeuse","有毒的；恶毒的"]],"sy":[["poison","courant","毒药（泛指）"],["toxine","courant","毒素"]],"fq":"中低频，谈动物时常用。","me":"venin：蛇咬人时「进入」身体的毒，和 vénéneux 同族。","tr":{"zh":"这种蜘蛛的毒液不危险。","fr":"Le venin de cette araignée n'est pas dangereux.","alt":"Cette araignée n'a pas de venin dangereux.","note":"否定后：pas de venin，du 变成 de。"}},
 "L'Homme (avec un H majuscule)": {"pos":"n.m. 阳性名词，复数 hommes；大写 L'Homme 指全人类","s":"人类；人（总称）。大写的 L'Homme 泛指整个人类，不是「男人」。小写 un homme = 男人、成年男性。les droits de l'Homme = 人权。","ipa":"[lɔm]","ph":"h 不发音，是哑音 h，所以 le 省音为 l'；o 读开口 [ɔ]；mm 读一个 [m]；结尾 e 不发音。","pi":"h 不发音；o 读 [ɔ]，不是 [o]；l'homme 里 le 要省音。","et":"来自拉丁语 homo（人）。词族：humain, humanité, homicide。","ex":[["L'Homme a un impact sur l'environnement.","人类对环境有影响。"],["Les droits de l'Homme sont universels.","人权是普遍的。"],["L'Homme a besoin de la nature.","人类需要自然。"]],"co":[["les droits de l'Homme","人权"],["l'évolution de l'Homme","人类的进化"],["l'Homme et la nature","人与自然"],["un homme","一个男人"]],"sy":[["l'humanité","courant","全人类"],["l'être humain","courant","人，人类个体"],["les humains","courant","人类（口语）"]],"fq":"高频，环境和社会话题常见。","me":"大写 H = 全人类；小写 h = 男人。","tr":{"zh":"人类必须保护地球。","fr":"L'Homme doit protéger la planète.","alt":"Les humains doivent protéger la planète.","note":"大写 H 表示人类总称。"}},
 "Le CO2": {"pos":"n.m. 阳性名词（化学符号），一般不变复数","s":"二氧化碳。法语里读字母：C-O-deux，也叫 le dioxyde de carbone 或 le gaz carbonique。常出现在环境话题：les émissions de CO2。","ipa":"[se.o.dø]","ph":"C 读 [se]；O 读 [o]；2 读 deux [dø]，eu 读 [ø]。","pi":"要按字母读：C [se]、O [o]、2 [dø]；不要读成英语的 see-oh-two。","et":"化学式。dioxyde 由 di-（二）+ oxyde 构成，carbone 来自拉丁语 carbo（炭）。","ex":[["Le CO2 pollue l'air.","二氧化碳污染空气。"],["Les voitures produisent du CO2.","汽车排放二氧化碳。"],["Les arbres absorbent le CO2.","树木吸收二氧化碳。"]],"co":[["les émissions de CO2","二氧化碳排放"],["réduire le CO2","减少二氧化碳"],["le dioxyde de carbone","二氧化碳"],["l'empreinte carbone","碳足迹"]],"sy":[["dioxyde de carbone","soutenu","二氧化碳（正式名称）"],["gaz carbonique","courant","二氧化碳（日常说法）"],["gaz à effet de serre","courant","温室气体（范围更大）"]],"fq":"中频，环境话题常见。","me":"C-O-deux，像念字母一样念出来。","tr":{"zh":"我们必须减少二氧化碳排放。","fr":"Nous devons réduire les émissions de CO2.","alt":"Il faut réduire notre CO2.","note":"les émissions 是阴性复数，de CO2 不变。"}},
 "Le comportement": {"pos":"n.m. 阳性名词，复数 comportements","s":"行为；举止；表现。指一个人或动物的做法和态度：un bon comportement。动词是 se comporter（表现、举止）。","ipa":"[kɔ̃.pɔʁ.tə.mɑ̃]","ph":"om 在 p 前读 [ɔ̃]；or 读 [ɔʁ]；-ement 读 [ə.mɑ̃]，t 要读出来。","pi":"-ement 读 [ə.mɑ̃]，不读 [mɛnt]；m 在 com- 中不单独读，它使 o 变鼻化 [ɔ̃]。","et":"来自 comporter（举止），拉丁语 comportare（带着、携带）+ -ment。词族：se comporter。","ex":[["Son comportement est étrange.","他的行为很怪。"],["Je n'aime pas son comportement.","我不喜欢他的行为。"],["Le comportement des enfants change vite.","孩子的行为变化很快。"]],"co":[["un bon / mauvais comportement","好 / 坏的行为"],["changer de comportement","改变行为"],["adopter un comportement","采取某种行为"],["un trouble du comportement","行为障碍"]],"sy":[["conduite","courant","品行、行为"],["attitude","courant","态度"]],"fq":"中高频，心理学和日常话题常用。","me":"se comporter + -ment：怎么「带着自己」做事 = 行为。","tr":{"zh":"老师不喜欢他的行为。","fr":"Le professeur n'aime pas son comportement.","alt":"Le prof n'apprécie pas son comportement.","note":"son 同时指「他的」或「她的」。"}},
 "Le réchauffement climatique": {"pos":"n.m. 阳性名词（词组），复数 réchauffements climatiques","s":"全球变暖；气候变暖。通常和 lutter contre（对抗）、causer（造成）搭配。比 le changement climatique（气候变化）更具体，专指气温升高。","ipa":"[ʁe.ʃof.mɑ̃.kli.ma.tik]","ph":"ré [ʁe]；chauff 读 [ʃof]，au 读 [o]；-ement [mɑ̃]；climatique 读 [kli.ma.tik]，c 读 [k]。","pi":"ch 读 [ʃ]；chauff 里 au 读 [o]；climatique 末尾 que 读 [k]；réchauffement 的 e 很轻。","et":"réchauffement = ré-（再）+ chauffer（加热）+ -ment；climatique 来自 climat，希腊语 klima（倾斜，地区）。","ex":[["Le réchauffement climatique est grave.","全球变暖很严重。"],["Le réchauffement climatique fait fondre les glaciers.","全球变暖使冰川融化。"],["Nous devons lutter contre le réchauffement climatique.","我们必须对抗全球变暖。"]],"co":[["lutter contre le réchauffement climatique","对抗全球变暖"],["les causes du réchauffement","变暖的原因"],["le changement climatique","气候变化"],["le dérèglement climatique","气候失调"]],"sy":[["changement climatique","courant","气候变化（范围更广）"],["dérèglement climatique","courant","气候失调"]],"fq":"中高频，环境话题常见。","me":"ré-chauff-ement：再次「加热」，地球变暖。","tr":{"zh":"全球变暖是一个全球性问题。","fr":"Le réchauffement climatique est un problème mondial.","alt":"Le réchauffement climatique concerne tout le monde.","note":"réchauffement 是阳性，所以用 le。"}},
 "Le sens de l'humour": {"pos":"n.m. 阳性名词（词组），le sens 复数 les sens","s":"幽默感。avoir le sens de l'humour = 有幽默感；ne pas avoir le sens de l'humour = 没幽默感。人也可以说 avoir de l'humour。","ipa":"[sɑ̃s.də.ly.muʁ]","ph":"sens 读 [sɑ̃s]，结尾 s 要读出来；h 不发音，所以 de 省音为 d'；humour 读 [y.muʁ]，u 读 [y]，r 读 [ʁ]。","pi":"sens 末尾的 s 要读 [s]；humour 的 h 不发音；humour 的 u 读 [y]；humeur（心情）和 humour（幽默）不同。","et":"sens 来自拉丁语 sensus（感觉）；humour 是 18 世纪从英语 humour 借回的词，而英语词又源自古法语 humeur。","ex":[["Elle a un bon sens de l'humour.","她很有幽默感。"],["Il n'a aucun sens de l'humour.","他一点幽默感都没有。"],["Il faut avoir le sens de l'humour dans la vie.","生活里要有幽默感。"]],"co":[["avoir le sens de l'humour","有幽默感"],["un bon sens de l'humour","很好的幽默感"],["avoir de l'humour","有幽默感"],["manquer d'humour","缺乏幽默感"]],"sy":[["l'humour","courant","幽默"],["l'esprit","soutenu","机智、风趣"]],"fq":"高频，聊人的性格时常用。","me":"sens（感觉）+ humour：对笑话有「感觉」。","tr":{"zh":"我男朋友很有幽默感。","fr":"Mon petit ami a un très bon sens de l'humour.","alt":"Mon copain est vraiment drôle, il a de l'humour.","note":"avoir le sens de l'humour 固定搭配。"}},
 "Le trafic": {"pos":"n.m. 阳性名词，复数 trafics","s":"非法交易；走私；也指交通流量、通信量。le trafic de drogue = 毒品交易；le trafic routier = 公路交通。堵车要说 un embouteillage，而不是 le trafic。","ipa":"[tʁa.fik]","ph":"tr [tʁ]；a [a]；f [f]；结尾 c 读 [k]。","pi":"结尾 c 要读 [k]；trafic 不是「堵车」，堵车说 embouteillage 或 bouchon。","et":"借自意大利语 traffico，具体来源不确定。词族：trafiquer, trafiquant（贩子）。","ex":[["Le trafic d'animaux exotiques est illégal.","异国动物的非法交易是违法的。"],["Il y a beaucoup de trafic sur l'autoroute.","高速公路上车流量很大。"],["La police arrête un trafiquant de drogue.","警察逮捕了一名毒贩。"]],"co":[["le trafic de drogue / d'armes","毒品 / 军火交易"],["le trafic routier / aérien","公路 / 空中交通"],["un trafiquant","贩子"],["le trafic d'influence","利用影响力谋利"]],"sy":[["commerce illégal","courant","非法买卖"],["contrebande","courant","走私"],["circulation","courant","交通流量"]],"fq":"中频，新闻里常见。","me":"trafic 末尾的 c 要读出来：[tʁa.fik]。","tr":{"zh":"走私野生动物是违法的。","fr":"Le trafic d'animaux sauvages est illégal.","alt":"Faire du trafic d'animaux sauvages, c'est illégal.","note":"trafic de + 名词：……的非法交易。"}},
 "Un ancêtre": {"pos":"n.m. 阳性名词（男女通用），复数 ancêtres","s":"祖先；先辈。常用复数 les ancêtres。引申为「前身、鼻祖」：l'ancêtre de la voiture。祖父母辈常用 grands-parents，比 ancêtre 更近。","ipa":"[ɑ̃.sɛtʁ]","ph":"an 读 [ɑ̃]；c 在 ê 前读 [s]；ê 读 [ɛ]；结尾 -tre 的 e 很轻。","pi":"c 读 [s]；ê 读 [ɛ]；结尾 -tre 不读 [tʁə]，e 很轻。","et":"古法语 ancessor，来自拉丁语 antecessor（先行者）。词族：antérieur, ancien。","ex":[["Mon ancêtre venait d'ici.","我的祖先来自这里。"],["Nos ancêtres vivaient près de la mer.","我们的祖先住在海边。"],["Le loup est l'ancêtre du chien.","狼是狗的祖先。"]],"co":[["nos ancêtres","我们的祖先"],["un ancêtre commun","共同祖先"],["l'ancêtre de la voiture","汽车的前身"],["un arbre généalogique","家谱"]],"sy":[["aïeul","littéraire","祖先（文学）"],["descendant","courant","后代（反义）"]],"fq":"中频，家族和历史话题常见。","me":"an-cêtre：「在前面」（ante）的人 = 祖先。","tr":{"zh":"我的祖先来自意大利。","fr":"Mes ancêtres viennent d'Italie.","alt":"Ma famille vient d'Italie depuis plusieurs générations.","note":"venir de + 国家名（阴性）。"}},
 "Un âne": {"pos":"n.m. 阳性名词，复数 ânes；阴性 une ânesse","s":"驴。比喻「蠢人、固执的人」：Quel âne ! têtu comme un âne = 固执得像头驴。un bonnet d'âne = 旧时罚笨学生戴的纸帽。","ipa":"[ɑn]","ph":"â 读后 [ɑ]，较长；n 要读；结尾 e 不发音。","pi":"â 读 [ɑ]，不是 [a]；ane 读 [ɑn]，不要读成 an [ɑ̃]；âne 写有 ^ 符号。","et":"来自拉丁语 asinus（驴）；asne 中 s 消失，留下 â 的 ^ 符号。","ex":[["L'âne est gris.","驴是灰色的。"],["Il est têtu comme un âne.","他固执得像头驴。"],["L'âne porte les sacs.","驴驮着袋子。"]],"co":[["têtu comme un âne","固执得像头驴"],["une ânesse","母驴"],["un bonnet d'âne","（旧时）笨学生的纸帽"],["un âne gris","一头灰驴"]],"sy":[["baudet","familier","驴（口语）"],["bourricot","familier","小驴"],["mulet","courant","骡子（不同的动物）"]],"fq":"中低频，谈动物和成语时用。","me":"âne：^ 代替了 asinus 里丢掉的 s，像驴的两只耳朵。","tr":{"zh":"那头驴驮着很重的袋子。","fr":"L'âne porte des sacs très lourds.","alt":"Cet âne porte des sacs lourds.","note":"âne 以元音开头，用 l'。"}},
 "Un bambou": {"pos":"n.m. 阳性名词，复数 bambous","s":"竹子；竹。可数时指一根竹子，作材料时用 du bambou。une canne en bambou = 竹手杖。des pousses de bambou = 竹笋。","ipa":"[bɑ̃.bu]","ph":"am 在 b 前读 [ɑ̃]；b [b]；ou 读 [u]；结尾 u 之后没有其他音。","pi":"am 读鼻化元音 [ɑ̃]，m 不单独读；复数 bambous 的 s 不发音。","et":"借自马来语 bambu，经葡萄牙语或荷兰语传入。","ex":[["Le panda mange un bambou.","熊猫吃竹子。"],["Cette chaise est en bambou.","这把椅子是竹子做的。"],["Les pandas aiment les pousses de bambou.","熊猫喜欢竹笋。"]],"co":[["une pousse de bambou","竹笋"],["une forêt de bambous","竹林"],["en bambou","竹制的"],["une canne en bambou","竹手杖"]],"sy":[["roseau","courant","芦苇（不同的植物）"]],"fq":"中低频，谈动物和自然时用。","me":"bam-bou：念起来像敲竹子的声音。","tr":{"zh":"熊猫每天吃很多竹子。","fr":"Le panda mange beaucoup de bambou chaque jour.","alt":"Les pandas mangent beaucoup de bambou tous les jours.","note":"作为材料或食物时用 du bambou 或 de bambou。"}},
 "Un cafard": {"pos":"n.m. 阳性名词，复数 cafards","s":"蟑螂。口语里 avoir le cafard = 情绪低落、闷闷不乐。在正式场合蟑螂也叫 une blatte。","ipa":"[ka.faʁ]","ph":"ca 读 [ka]；f [f]；ard 读 [aʁ]，d 不发音。","pi":"结尾 d 不发音，读 [faʁ]；avoir le cafard 和蟑螂无关，指心情不好。","et":"通常认为来自阿拉伯语 kāfir（不信教者），后引申到小虫和「阴郁」。","ex":[["Je déteste les cafards.","我讨厌蟑螂。"],["Il y a un cafard dans la cuisine.","厨房里有一只蟑螂。"],["J'ai le cafard aujourd'hui.","我今天情绪低落。"]],"co":[["avoir le cafard","情绪低落"],["un cafard dans la cuisine","厨房里的蟑螂"],["une blatte","蟑螂（正式词）"],["donner le cafard","让人情绪低落"]],"sy":[["blatte","soutenu","蟑螂（学名）"],["blues","familier","忧郁（同 avoir le cafard）"]],"fq":"中频，日常口语。","me":"cafard 的 d 不发音；想到「黑色的小虫」就想到心情黑。","tr":{"zh":"我今天心情不好。","fr":"J'ai le cafard aujourd'hui.","alt":"Je n'ai pas le moral aujourd'hui.","note":"avoir le cafard：固定表达。"}},
 "Un caméléon": {"pos":"n.m. 阳性名词，复数 caméléons","s":"变色龙。比喻「善于随环境改变态度的人」：C'est un vrai caméléon。","ipa":"[ka.me.le.ɔ̃]","ph":"ca [ka]；mé [me]；lé [le]；on 读 [ɔ̃]；五个音节中，é 和 on 分开读，是 [le.ɔ̃]。","pi":"两个 é 都读 [e]；-éon 要读成两个音 [e.ɔ̃]，不连读成一个音。","et":"来自拉丁语 chamaeleon，希腊语 khamaileon，本义「地上的狮子」。","ex":[["Le caméléon change de couleur.","变色龙会变色。"],["Le caméléon se cache dans l'arbre.","变色龙藏在树上。"],["Mon cousin est un vrai caméléon : il change d'avis tout le temps.","我表弟像变色龙一样，总是改变主意。"]],"co":[["changer de couleur comme un caméléon","像变色龙一样变色"],["un vrai caméléon","善变的人"],["un caméléon vert","绿色的变色龙"]],"sy":[["lézard","courant","蜥蜴（同类动物）"],["iguane","courant","鬣蜥（不同的动物）"]],"fq":"中低频，谈动物时用。","me":"ca-mé-lé-on：四个音节，像变色龙的颜色一格一格变。","tr":{"zh":"变色龙可以改变自己的颜色。","fr":"Le caméléon peut changer de couleur.","alt":"Un caméléon change de couleur pour se cacher.","note":"changer de + 名词，不加冠词。"}},
 "Un coffre-fort": {"pos":"n.m. 阳性名词，复数 coffres-forts","s":"保险箱；保险柜。用来放钱、贵重物品：ouvrir le coffre-fort avec un code。银行里也有 un coffre-fort。","ipa":"[kɔ.fʁə.fɔʁ]","ph":"co 读开口 [kɔ]；ff 只读一个 [f]；fort 读 [fɔʁ]，t 不发音。","pi":"fort 的 t 不发音；复数两部分都加 s：des coffres-forts；ff 只读一个 f。","et":"coffre（箱子）+ fort（坚固的）：坚固的箱子。","ex":[["L'argent est dans le coffre-fort.","钱在保险箱里。"],["Il a ouvert le coffre-fort avec un code.","他用密码打开了保险箱。"],["Les bijoux sont dans le coffre-fort de la banque.","珠宝放在银行的保险柜里。"]],"co":[["ouvrir / fermer un coffre-fort","打开 / 关上保险箱"],["le code du coffre-fort","保险箱密码"],["un coffre-fort à la banque","银行保险柜"],["des coffres-forts","保险箱（复数）"]],"sy":[["coffre","courant","箱子；也可指保险柜"]],"fq":"中低频，谈银行和家居时用。","me":"coffre（箱）+ fort（强）：很结实的箱子。","tr":{"zh":"护照在保险箱里。","fr":"Le passeport est dans le coffre-fort.","alt":"Mon passeport est dans le coffre.","note":"coffre-fort 是复合名词，阳性。"}},
 "Un coquillage": {"pos":"n.m. 阳性名词，复数 coquillages","s":"贝壳；贝类。可以指海滩上拾到的壳，也指可食用的贝类（fruits de mer 中的一部分）。贝壳本身也可以叫 une coquille。","ipa":"[kɔ.ki.jaʒ]","ph":"co 读 [kɔ]；qui 读 [ki]；ill 读 [j]；age 读 [aʒ]，g 读 [ʒ]。","pi":"ill 读 [j]，不是 [l]；-age 的 g 读 [ʒ]；qu 读 [k]。","et":"coquille + -age。coquille 来自拉丁语 conchylium（贝类，源自希腊语）。","ex":[["J'ai trouvé un coquillage.","我捡到一个贝壳。"],["On ramasse des coquillages sur la plage.","我们在海滩上捡贝壳。"],["Elle met le coquillage près de son oreille.","她把贝壳放到耳边。"]],"co":[["ramasser des coquillages","捡贝壳"],["un coquillage vide","空贝壳"],["manger des coquillages","吃贝类"],["les fruits de mer","海鲜"]],"sy":[["coquille","courant","壳（贝壳本身）"],["fruits de mer","courant","海鲜（可食用的海产）"]],"fq":"中频，谈海边和饮食时常用。","me":"coquille（壳）+ -age：许多壳的总称。","tr":{"zh":"孩子们在海滩上捡了很多贝壳。","fr":"Les enfants ont ramassé beaucoup de coquillages sur la plage.","alt":"Les enfants ont trouvé plein de coquillages à la plage.","note":"ramasser 的过去分词 ramassé。"}},
 "Un cri": {"pos":"n.m. 阳性名词，复数 cris","s":"叫声；喊叫。人和动物的叫声都可以：un cri de joie（欢呼）、le cri du corbeau（乌鸦叫）。动词是 crier（喊叫）。","ipa":"[kʁi]","ph":"c 读 [k]；r 是喉音 [ʁ]；i 读 [i]；复数 cris 的 s 不发音。","pi":"r 是喉音；cri 和 crie（动词变位）读音相同；cri 是「喊」，不是「哭」，哭用 pleurer。","et":"来源不确定，是动词 crier 的名词形式。词族：crier, écrier。","ex":[["J'ai entendu un cri.","我听到一声叫喊。"],["L'enfant a poussé un cri de joie.","孩子发出一声欢呼。"],["J'ai entendu un cri dans la nuit.","夜里我听到一声叫喊。"]],"co":[["pousser un cri","发出一声叫喊"],["un cri de joie / de peur","欢呼声 / 惊叫声"],["un cri d'alarme","警报声"],["à grands cris","大声叫喊地"]],"sy":[["hurlement","courant","嚎叫"],["clameur","soutenu","喧嚷声"]],"fq":"高频，日常常用。","me":"cri：短短一个音节，就像一声短促的喊叫。","tr":{"zh":"我听到孩子的一声尖叫。","fr":"J'ai entendu le cri d'un enfant.","alt":"J'ai entendu un enfant crier.","note":"un cri = 名词；crier = 动词。"}},
 "Un danger": {"pos":"n.m. 阳性名词，复数 dangers","s":"危险；危害。指可能造成伤害的东西或情况：en danger（处于危险中）、Danger de mort（有生命危险）。形容词是 dangereux。","ipa":"[dɑ̃.ʒe]","ph":"d [d]；an 读 [ɑ̃]；g 在 e 前读 [ʒ]；结尾 -er 读 [e]，r 不发音。","pi":"g 读 [ʒ]，不读 [g]；-er 读 [e]，r 不发音；形容词是 dangereux，不是 dangeur。","et":"来自古法语 dangier；来源细节不确定。词族：dangereux, mettre en danger。","ex":[["Attention, c'est un danger.","小心，这很危险。"],["Le feu est un danger pour la forêt.","火对森林是个危险。"],["Il y a un danger sur la route.","路上有危险。"]],"co":[["en danger","处于危险中"],["hors de danger","脱离危险"],["mettre qqn en danger","使某人陷入危险"],["Danger de mort","有生命危险"]],"sy":[["risque","courant","风险"],["péril","soutenu","危难（书面）"],["menace","courant","威胁"]],"fq":"极高频，日常常用。","me":"dan-ger：g 柔和读 [ʒ]，像「当心」！","tr":{"zh":"孩子们在马路上很危险。","fr":"Les enfants sont en danger sur la route.","alt":"La route est un danger pour les enfants.","note":"en danger：处于危险中，danger 前不加冠词。"}},
 "Un escargot": {"pos":"n.m. 阳性名词，复数 escargots","s":"蜗牛；也指做菜用的食用蜗牛（法国名菜 escargots de Bourgogne）。形容很慢常说 lent comme un escargot。","ipa":"[ɛs.kaʁ.ɡo]","ph":"es [ɛs]；c [k]；r 是小舌音 [ʁ]；g [ɡ]；结尾 -ot 读 [o]，t 不发。","pi":"结尾 t 不发音；复数 s 也不发音；开头读 [ɛs]，不是 [e]。","et":"来源不确定（可能来自奥克语 escaragol）。","ex":[["L'escargot est lent.","蜗牛很慢。"],["Il pleut, les escargots sortent.","下雨了，蜗牛出来了。"]],"co":[["lent comme un escargot","慢得像蜗牛"],["un escargot de Bourgogne","勃艮第蜗牛（名菜）"],["avancer comme un escargot","慢吞吞地前进"]],"sy":[["limace","courant","蛞蝓（没有壳）"],["colimaçon","littéraire","蜗牛（旧词）"]],"fq":"中频，日常常用。","me":"escargot 慢慢走，背着自己的「小房子」。","tr":{"zh":"我不喜欢吃蜗牛。","fr":"Je n'aime pas manger des escargots.","alt":"Les escargots, je n'aime pas ça.","note":"否定句里 des 变成 d'：pas manger d'escargots 也可以。"}},
 "Un espace protégé": {"pos":"n.m. 阳性名词，复数 espaces protégés","s":"保护区；受保护的自然区域。espace 是「空间；区域」，protégé 是过去分词作形容词，放在名词后并与名词性数配合。","ipa":"[ɛs.pas pʁɔ.te.ʒe]","ph":"es [ɛs]；c 在 e 前读 [s]；protégé 的 g 在 é 前读 [ʒ]；结尾 -é 读 [e]。","pi":"protégé 的 g 读 [ʒ]，不是 [ɡ]；espace 是阳性（un espace），别说成 une espace。","et":"espace 来自拉丁语 spatium（空间）；protégé 来自动词 protéger（拉丁语 protegere，保护）。","ex":[["C'est un espace protégé.","这是一个保护区。"],["Cet espace protégé abrite des oiseaux rares.","这个保护区里住着珍稀鸟类。"]],"co":[["un espace naturel protégé","自然保护区"],["un espace vert","绿地"],["protéger l'environnement","保护环境"]],"sy":[["réserve naturelle","courant","自然保护区"],["zone protégée","courant","受保护地带"]],"fq":"中频，环保话题常见。","me":"espace（空间）+ protégé（被保护）：被圈起来保护的一块地。","tr":{"zh":"在这个保护区里不能摘花。","fr":"On ne peut pas cueillir de fleurs dans cet espace protégé.","alt":"Dans cet espace protégé, il est interdit de cueillir les fleurs.","note":"ne… pas + de：否定句里 des fleurs 变成 de fleurs。"}},
 "Un être vivant": {"pos":"n.m. 阳性名词，复数 êtres vivants","s":"生物；有生命的存在。être 在这里是名词（「存在者」），不是动词。人、动物、植物都是 êtres vivants。","ipa":"[ɛtʁ vi.vɑ̃]","ph":"ê [ɛ]；结尾 -tre 读 [tʁ]；vivant 的 -ant 读鼻化音 [ɑ̃]，t 不发。","pi":"être 的 ê 读 [ɛ]；vivant 结尾 nt 不发，只有鼻化音。别把名词 être 和动词 être（是）混淆。","et":"être（名词）由动词 être 变来；vivant 来自动词 vivre（拉丁语 vivere，活）的现在分词。","ex":[["L'arbre est un être vivant.","树是一种生命体。"],["Nous sommes tous des êtres vivants.","我们都是生物。"]],"co":[["les êtres vivants","生物（总称）"],["un être humain","人类；一个人"],["respecter tous les êtres vivants","尊重一切生命"]],"sy":[["organisme","courant","生物体（偏科学）"],["créature","courant","生灵；造物"]],"fq":"中频，科学和环保话题。","me":"être（存在）+ vivant（活着）：「活着的存在」。","tr":{"zh":"植物也是生物。","fr":"Les plantes sont aussi des êtres vivants.","alt":"Les plantes, ce sont des êtres vivants aussi.","note":"des êtres 中 s 与 ê 之间要连音：[de.zɛtʁ]。"}},
 "Un faucon": {"pos":"n.m. 阳性名词，复数 faucons","s":"猎鹰；隼。会飞、会捕猎的猛禽，也用于驯鹰（fauconnerie）。","ipa":"[fo.kɔ̃]","ph":"au [o]；c 在 o 前读 [k]；结尾 -on 读鼻化音 [ɔ̃]，n 不单独发音。","pi":"au 读 [o]，不是 [au]；结尾 -on 是鼻音；注意与 faux [fo]（假的）同音。","et":"来自晚期拉丁语 falco；相关词：fauconnier（驯鹰人）。","ex":[["Le faucon vole haut.","猎鹰飞得很高。"],["Un faucon chasse les petits oiseaux.","一只猎鹰在捕小鸟。"]],"co":[["un faucon pèlerin","游隼"],["avoir un œil de faucon","眼力极好"],["un dresseur de faucons","驯鹰人"]],"sy":[["aigle","courant","鹰（体型更大）"],["épervier","courant","雀鹰"]],"fq":"低中频。","me":"faucon 里有 [fo]，和「faux」同音：别被假的骗了，猎鹰眼睛很尖。","tr":{"zh":"猎鹰在天空中盘旋。","fr":"Le faucon tourne dans le ciel.","alt":"Un faucon plane au-dessus de nous.","note":"tourner dans le ciel：在空中盘旋。"}},
 "Un gorille": {"pos":"n.m. 阳性名词，复数 gorilles","s":"大猩猩。也可口语指「保镖」（un gorille = 贴身保镖）。","ipa":"[ɡɔ.ʁij]","ph":"g [ɡ]；o [ɔ]；ille 读 [ij]。","pi":"-ille 在这个词里读 [ij]，不是 [il]；r 是小舌音。","et":"来自希腊语 gorillai，古代航海记里对毛茸茸野人的称呼，后来被用来命名这种猿。","ex":[["Le gorille est fort.","大猩猩很强壮。"],["Le chanteur arrive avec deux gorilles.","歌手带着两个保镖到了。"]],"co":[["un gorille des montagnes","山地大猩猩"],["un gorille mâle","雄性大猩猩"],["le gorille du président","总统的保镖"]],"sy":[["singe","courant","猴；猿（统称）"],["garde du corps","courant","保镖"]],"fq":"中频。","me":"gorille 和英语 gorilla 一眼就懂，法语结尾读 [ij]。","tr":{"zh":"这只大猩猩吃水果和叶子。","fr":"Ce gorille mange des fruits et des feuilles.","alt":"Le gorille se nourrit de fruits et de feuilles.","note":"se nourrir de：以……为食。"}},
 "Un hectare": {"pos":"n.m. 阳性名词，复数 hectares","s":"公顷，面积单位，1 hectare = 10 000 平方米。常用于农田、森林、公园的面积。","ipa":"[ɛk.taʁ]","ph":"h 不发音；e [ɛ]；ct 读 [kt]；结尾 r 读 [ʁ]。","pi":"h 不发音，所以 un hectare 要连音：[œ̃.nɛk.taʁ]；hectare 是阳性，不是 une hectare。","et":"hecto-（百，希腊语）+ are（面积单位，拉丁语 area）：100 个 are。","ex":[["Le terrain fait un hectare.","这块地有一公顷。"],["Cette ferme a vingt hectares de champs.","这个农场有二十公顷的田地。"]],"co":[["un hectare de forêt","一公顷森林"],["des milliers d'hectares","成千上万公顷"],["faire dix hectares","占地十公顷"]],"sy":[["are","courant","公亩（100 平方米）"],["mètre carré","courant","平方米"]],"fq":"中频，常见于新闻。","me":"hecto（百）+ are：一百个小单位，合起来就是一公顷。","tr":{"zh":"这片森林有五十公顷。","fr":"Cette forêt fait cinquante hectares.","alt":"Cette forêt s'étend sur cinquante hectares.","note":"faire + 面积：占地……；s'étendre sur：延伸……"}},
 "Un hippopotame": {"pos":"n.m. 阳性名词，复数 hippopotames","s":"河马。口语里常缩写成 hippo。","ipa":"[i.pɔ.pɔ.tam]","ph":"h 不发音；pp 只读一个 [p]；结尾 -me 读 [m]，e 不发。","pi":"开头 hi- 读 [i]，h 不发；字母多但只有四个音节：i-pɔ-pɔ-tam；结尾不要读成英语的 -mus。","et":"来自希腊语 hippopotamos，由 hippos（马）+ potamos（河）组成：「河里的马」。","ex":[["L'hippopotame est dans l'eau.","河马在水里。"],["Les hippopotames dorment le jour.","河马白天睡觉。"]],"co":[["un hippopotame géant","一只巨大的河马"],["être gros comme un hippopotame","胖得像河马"],["la bouche d'un hippopotame","河马的大嘴"]],"sy":[["hippo","familier","河马（简称）"],["rhinocéros","courant","犀牛（别混淆）"]],"fq":"低中频。","me":"hippo（马）+ potame（河）：河里的马。","tr":{"zh":"河马白天待在水里。","fr":"L'hippopotame reste dans l'eau pendant la journée.","alt":"Le jour, l'hippopotame reste dans l'eau.","note":"pendant la journée：整个白天。"}},
 "Un insecte": {"pos":"n.m. 阳性名词，复数 insectes","s":"昆虫。蚊子、苍蝇、蜜蜂、蚂蚁等都是 insectes。蜘蛛不是昆虫（araignée 是蛛形纲）。","ipa":"[ɛ̃.sɛkt]","ph":"in 读鼻化音 [ɛ̃]；sect 读 [sɛkt]，e 在 s 后读 [ɛ]，ct 都发音。","pi":"结尾 ct 两个音都要发 [kt]；开头 in- 是鼻音，不是 [in]；insecte 是阳性。","et":"来自拉丁语 insectum（被切开的），因为昆虫身体分节。","ex":[["C'est un petit insecte.","这是一只小昆虫。"],["Les insectes ont six pattes.","昆虫有六条腿。"]],"co":[["une piqûre d'insecte","虫咬"],["un insecte nuisible","害虫"],["chasser les insectes","赶走虫子"]],"sy":[["bestiole","familier","小虫子、小动物"],["bête","familier","虫；动物"]],"fq":"高频。","me":"insecte 来自「切开」：身体分成一节一节。","tr":{"zh":"夏天有很多昆虫。","fr":"Il y a beaucoup d'insectes en été.","alt":"En été, il y a plein d'insectes.","note":"beaucoup de + 名词，不加冠词；plein de 更口语。"}},
 "Un insecticide": {"pos":"n.m. 阳性名词，复数 insecticides","s":"杀虫剂。喷雾、药剂都可以叫 un insecticide；日常口语也说 un produit anti-insectes。","ipa":"[ɛ̃.sɛk.ti.sid]","ph":"in [ɛ̃]；sec [sɛk]；ti [ti]；cide 读 [sid]。","pi":"结尾 -cide 读 [sid]，c 读 [s]；不要读成 [kid]。","et":"insecte + -cide（拉丁语 caedere，杀）；同类词：pesticide, homicide。","ex":[["Il utilise un insecticide.","他用杀虫剂。"],["Cet insecticide est dangereux pour les abeilles.","这种杀虫剂对蜜蜂有害。"]],"co":[["pulvériser un insecticide","喷洒杀虫剂"],["un insecticide naturel","天然杀虫剂"],["sans insecticide","不使用杀虫剂"]],"sy":[["pesticide","courant","农药（范围更广）"],["anti-moustiques","courant","驱蚊产品"]],"fq":"低中频。","me":"insecte + cide（像 suicide）：杀死昆虫的东西。","tr":{"zh":"我不想在花园里用杀虫剂。","fr":"Je ne veux pas utiliser d'insecticide dans le jardin.","alt":"Je ne veux pas mettre d'insecticide dans mon jardin.","note":"否定后 de/d' 代替 du/des：pas d'insecticide。"}},
 "Un léopard": {"pos":"n.m. 阳性名词，复数 léopards","s":"豹（花豹）。身上有斑点。和 guépard（猎豹）、panthère（黑豹、美洲豹）不同。","ipa":"[le.ɔ.paʁ]","ph":"é [e]；o [ɔ]；ard 读 [aʁ]，结尾 d 不发。","pi":"结尾 d 不发音；léo- 是两个音节 [le.ɔ]，不要吞掉。","et":"来自晚期拉丁语 leopardus，由 leo（狮）+ pardus（豹）组成，古人以为豹是狮和豹的杂交。","ex":[["Le léopard est rapide.","豹跑得很快。"],["Le léopard grimpe dans l'arbre.","豹爬上树。"]],"co":[["une peau de léopard","豹皮"],["un motif léopard","豹纹图案"],["un léopard des neiges","雪豹"]],"sy":[["guépard","courant","猎豹（跑得最快）"],["panthère","courant","黑豹"]],"fq":"中频。","me":"léo（狮）+ pard（豹）：既像狮又像豹。","tr":{"zh":"豹在树上睡觉。","fr":"Le léopard dort dans un arbre.","alt":"Le léopard fait la sieste dans l'arbre.","note":"dans un arbre：在树上（法语用 dans）。"}},
 "Un mâle": {"pos":"n.m. 阳性名词，复数 mâles（也可作形容词）","s":"雄性；公的（动物）。对应的雌性是 une femelle。作形容词表示「男性的；雄的」。用于人时较生硬，一般说 un homme。","ipa":"[mɑl]","ph":"â 读 [ɑ]（也可读 [a]）；l 读 [l]，e 不发。","pi":"拼写有 ^，别写成 male；用于人时偏生物学术语，可能显得冷漠。","et":"来自拉丁语 masculus（雄的、男性的）。","ex":[["C'est un mâle.","这是雄性。"],["Le mâle est plus grand que la femelle.","雄性比雌性大。"]],"co":[["un mâle et une femelle","一雄一雌"],["un chat mâle","公猫"],["le mâle dominant","占优势的雄性"]],"sy":[["femelle","courant","雌性（反义）"],["masculin","courant","男性的；阳性的"]],"fq":"中频。","me":"mâle 带帽子（^）：想象雄性头上有角或鬃毛。","tr":{"zh":"这只猫是公的。","fr":"Ce chat est un mâle.","alt":"C'est un chat mâle.","note":"mâle 可作名词，也可放在名词后作形容词。"}},
 "Un mammifère": {"pos":"n.m. 阳性名词，复数 mammifères","s":"哺乳动物。人、狗、猫、鲸都属于哺乳动物，它们用奶喂养幼崽。","ipa":"[ma.mi.fɛʁ]","ph":"mm 只读一个 [m]；è 读 [ɛ]；结尾 r 读 [ʁ]。","pi":"拼写有双 m，发音只一个 [m]；结尾 -ère 读 [ɛʁ]，不要丢掉 r。","et":"拉丁语 mamma（乳房）+ -fère（拉丁语 ferre，带来、具有）：「有乳房的」。","ex":[["Le chat est un mammifère.","猫是哺乳动物。"],["La baleine est un mammifère marin.","鲸是海洋哺乳动物。"]],"co":[["un mammifère marin","海洋哺乳动物"],["un mammifère terrestre","陆地哺乳动物"],["les mammifères et les oiseaux","哺乳动物和鸟类"]],"sy":[["animal","courant","动物（更广）"],["reptile","courant","爬行动物（对比）"]],"fq":"中频，常见于学校和科学内容。","me":"mamma（乳房，像 maman）+ fère：妈妈给奶的动物。","tr":{"zh":"鲸不是鱼，是哺乳动物。","fr":"La baleine n'est pas un poisson, c'est un mammifère.","alt":"Une baleine, ce n'est pas un poisson : c'est un mammifère.","note":"否定后 un poisson 保持 un（用 être）。"}},
 "Un mille-pattes": {"pos":"n.m. 阳性名词，单复数同形 mille-pattes","s":"蜈蚣；千足虫（字面：「一千只脚」）。两种多足动物都可以叫 mille-pattes，也有更细的说法：scolopendre（蜈蚣）、iule（马陆）。","ipa":"[mil.pat]","ph":"mille 读 [mil]；pattes 读 [pat]；中间有连字符。","pi":"pattes 结尾 s 不发；单复数完全同形，不能写成 mille-patte。","et":"mille（一千，拉丁语 mille）+ pattes（patte，脚）。","ex":[["Le mille-pattes a beaucoup de pattes.","千足虫有很多脚。"],["J'ai vu un mille-pattes dans la salle de bain.","我在浴室看到一条千足虫。"]],"co":[["un mille-pattes noir","一条黑色的千足虫"],["des mille-pattes","几条千足虫"],["avoir peur des mille-pattes","害怕蜈蚣一类的虫"]],"sy":[["scolopendre","soutenu","蜈蚣（有毒）"],["iule","soutenu","马陆"]],"fq":"低频。","me":"mille（一千）+ pattes（脚）：一千只脚的虫。","tr":{"zh":"他看到一条很长的千足虫。","fr":"Il a vu un très long mille-pattes.","alt":"Il est tombé sur un énorme mille-pattes.","note":"mille-pattes 单复数同形。"}},
 "Un mouton": {"pos":"n.m. 阳性名词，复数 moutons","s":"绵羊；羊肉（la viande de mouton）。母羊 une brebis，公羊 un bélier，小羊 un agneau。mouton 也指灰尘团（moutons de poussière）和海上的白浪。","ipa":"[mu.tɔ̃]","ph":"ou [u]；结尾 -on 读鼻化音 [ɔ̃]。","pi":"ou 读 [u]，不是 [o]；结尾 n 不单独发音；复数 s 不发音。","et":"来源于高卢语一带的古词（可能是 *multo），来源不完全确定；英语 mutton（羊肉）借自古法语 moton。","ex":[["Le mouton est blanc.","绵羊是白色的。"],["Ils élèvent des moutons dans les montagnes.","他们在山里养绵羊。"]],"co":[["compter les moutons","数羊（帮助入睡）"],["revenons à nos moutons","言归正传"],["un mouton noir","害群之马"],["un troupeau de moutons","一群羊"]],"sy":[["brebis","courant","母羊"],["agneau","courant","小羊"]],"fq":"中频，常用成语。","me":"mouton 和英语 mutton 同源，但法语还指整只活羊。","tr":{"zh":"农民有一百只羊。","fr":"Le fermier a cent moutons.","alt":"L'agriculteur possède une centaine de moutons.","note":"cent 前面没有别的数字时不加 s：cent moutons；deux cents moutons 才加 s。"}},
 "Un ours": {"pos":"n.m. 阳性名词，单复数同形 ours；母熊 une ourse","s":"熊。un ours en peluche = 毛绒玩具熊。也可比喻「孤僻的人」（un ours = 不爱交际的人）。","ipa":"[uʁs]","ph":"ou [u]；r [ʁ]；结尾 s 要读出来 [s]。","pi":"这里的 s 要发音，与大多数词尾 s 不同；单复数同形，听发音分不出。","et":"来自拉丁语 ursus（熊）；相关词：ourse（母熊）、ourson（小熊）。","ex":[["L'ours est grand.","熊很大。"],["Les ours dorment pendant l'hiver.","熊在冬天冬眠。"]],"co":[["un ours brun / polaire","棕熊 / 北极熊"],["un ours en peluche","毛绒玩具熊"],["un ours mal léché","粗鲁笨拙的人"]],"sy":[["ourson","courant","小熊"],["grincheux","familier","脾气坏的人（比较）"]],"fq":"中频。","me":"ours 的 s 发 [s]，像熊在「嘶」地喘气。","tr":{"zh":"熊爱吃蜂蜜。","fr":"Les ours aiment le miel.","alt":"L'ours adore le miel.","note":"泛指用复数 les ours 或单数 l'ours 都可以。"}},
 "Un parc naturel": {"pos":"n.m. 阳性名词，复数 parcs naturels","s":"自然公园；自然保护公园。法国有许多 parcs naturels régionaux（大区自然公园），可以散步、骑车、观察动植物。","ipa":"[paʁk na.ty.ʁɛl]","ph":"parc 的 c 要发音 [k]；naturel 读 [na.ty.ʁɛl]，u 读 [y]。","pi":"parc 结尾 c 要发 [k]，别丢掉；naturel 中 u 读 [y]（嘴圆）。","et":"parc 借自古法语（可能源自日耳曼语，指圈起来的地方）；naturel 来自 nature（拉丁语 natura）+ -el。","ex":[["Nous visitons un parc naturel.","我们参观自然公园。"],["Ce parc naturel est ouvert toute l'année.","这个自然公园全年开放。"]],"co":[["un parc naturel régional","大区自然公园"],["un parc national","国家公园"],["se promener dans un parc naturel","在自然公园散步"]],"sy":[["parc national","courant","国家公园（级别更高）"],["réserve naturelle","courant","自然保护区"]],"fq":"中频。","me":"parc（公园）+ naturel（自然）：自然的公园。","tr":{"zh":"周末我们去自然公园散步。","fr":"Ce week-end, nous allons nous promener dans un parc naturel.","alt":"Ce week-end, on va se balader dans un parc naturel.","note":"se balader 比 se promener 更口语。"}},
 "Un perroquet": {"pos":"n.m. 阳性名词，复数 perroquets","s":"鹦鹉。会模仿人说话；比喻「只会重复别人话的人」。","ipa":"[pɛ.ʁɔ.kɛ]","ph":"per 读 [pɛ]；rr 只发一个 [ʁ]；qu 读 [k]；结尾 -et 读 [ɛ]，t 不发。","pi":"rr 只读一个 [ʁ]；结尾 t 不发音；qu 读 [k]，不读 [kw]。","et":"来源不确定；可能与人名 Perrot/Pierrot 的昵称有关。","ex":[["Le perroquet parle.","鹦鹉会说话。"],["Mon perroquet répète tout ce que je dis.","我的鹦鹉重复我说的一切。"]],"co":[["parler comme un perroquet","鹦鹉学舌"],["répéter comme un perroquet","机械地重复"],["un perroquet gris","灰鹦鹉"]],"sy":[["perruche","courant","小型鹦鹉"],["ara","courant","金刚鹦鹉"]],"fq":"中频。","me":"perroquet：学舌的鸟，记住 rr 只读一个 [ʁ]，结尾 t 不发。","tr":{"zh":"我的鹦鹉会说「你好」。","fr":"Mon perroquet sait dire « bonjour ».","alt":"Mon perroquet dit « bonjour ».","note":"savoir + 动词原形：会（做某事）。"}},
 "Un rat": {"pos":"n.m. 阳性名词，复数 rats；雌性 une rate","s":"老鼠（较大的鼠）。小的鼠是 une souris。也可比喻吝啬的人（口语：un rat），或「小舞蹈演员」(petit rat de l'Opéra)。","ipa":"[ʁa]","ph":"r 小舌音 [ʁ]；a [a]；结尾 t 不发音。","pi":"结尾 t 不发音；别和 rate（母鼠）混淆；英语里的 rat 发 [t]，法语不发。","et":"来源不确定（可能是古日耳曼语或拉丁语俗语）。","ex":[["J'ai vu un rat.","我看到一只老鼠。"],["Il y a des rats dans la cave.","地窖里有老鼠。"]],"co":[["un rat d'égout","下水道老鼠"],["un rat de laboratoire","实验鼠"],["s'ennuyer comme un rat mort","无聊透顶（口语）"],["un petit rat de l'Opéra","歌剧院的小舞蹈生"]],"sy":[["souris","courant","小老鼠"],["rongeur","courant","啮齿动物（总称）"]],"fq":"中频。","me":"rat 只有一个短音 [ʁa]，t 不发。","tr":{"zh":"实验室里有很多老鼠。","fr":"Il y a beaucoup de rats dans le laboratoire.","alt":"Dans le labo, il y a plein de rats.","note":"labo 是 laboratoire 的口语缩写。"}},
 "Un réflexe": {"pos":"n.m. 阳性名词，复数 réflexes","s":"反射；本能反应；条件反射。un bon réflexe 指「做得对的下意识反应」。常指不用思考就做出的反应：avoir de bons réflexes = 反应快。","ipa":"[ʁe.flɛks]","ph":"é [e]；x 读 [ks]；e 在 fl 后读 [ɛ]。","pi":"结尾 x 要读 [ks]；réflexe 是阳性。别和 reflet（倒影）混淆。","et":"来自拉丁语 reflexus（弯回来的）。同源：réfléchir（思考；反射）。","ex":[["C'est un bon réflexe.","这是一个好反应。"],["Il a eu le bon réflexe : il a freiné.","他反应很对：他刹了车。"]],"co":[["avoir de bons réflexes","反应敏捷"],["avoir le réflexe de + 动词","下意识地做某事"],["un réflexe de survie","求生本能"]],"sy":[["instinct","courant","本能"],["habitude","courant","习惯"]],"fq":"中频。","me":"réflexe 像 reflex：像镜子一样「反射」回来。","tr":{"zh":"在公共场所洗手是个好习惯。","fr":"Se laver les mains en public est un bon réflexe.","alt":"Se laver les mains, c'est un bon réflexe.","note":"avoir/être un bon réflexe：形容做对了的下意识动作。"}},
 "Un reptile": {"pos":"n.m. 阳性名词，复数 reptiles","s":"爬行动物。蛇、蜥蜴、鳄鱼、龟都是 reptiles。","ipa":"[ʁɛp.til]","ph":"r [ʁ]；e 在 p 前读 [ɛ]；pt 都发音；结尾 -le 读 [l]，e 不发。","pi":"p 要发音（不是 [ʁe.til]）；结尾 e 不发音。","et":"来自拉丁语 reptilis，源于 repere（爬行）。","ex":[["Le crocodile est un reptile.","鳄鱼是爬行动物。"],["Les reptiles aiment le soleil.","爬行动物喜欢太阳。"]],"co":[["un reptile venimeux","有毒的爬行动物"],["l'élevage de reptiles","饲养爬行动物"],["la peau d'un reptile","爬行动物的皮"]],"sy":[["serpent","courant","蛇（一种）"],["lézard","courant","蜥蜴（一种）"]],"fq":"中低频，科学类。","me":"reptile ≈ 英语 reptile，p 要读出来。","tr":{"zh":"蛇是爬行动物，不是哺乳动物。","fr":"Le serpent est un reptile, pas un mammifère.","alt":"Un serpent, c'est un reptile, pas un mammifère.","note":"pas un mammifère：否定对比，用 pas + 名词。"}},
 "Un requin": {"pos":"n.m. 阳性名词，复数 requins","s":"鲨鱼。比喻「无情的商人、狡猾的人」(un requin de la finance)。","ipa":"[ʁə.kɛ̃]","ph":"re 读 [ʁə]；qu 读 [k]；in 读鼻化音 [ɛ̃]。","pi":"qu 读 [k]；结尾 -in 是鼻音 [ɛ̃]，不要加 n；re 轻读成 [ʁə]。","et":"来源不确定（有人认为与 requiem 有关，但没有定论）。","ex":[["Le requin nage dans la mer.","鲨鱼在海里游。"],["Il a peur des requins.","他怕鲨鱼。"]],"co":[["un requin blanc","大白鲨"],["une attaque de requin","鲨鱼袭击"],["un requin de la finance","金融界的狠角色"]],"sy":[["squale","soutenu","鲨（科学词）"],["baleine","courant","鲸（别混淆）"]],"fq":"中频。","me":"requin 的 qu 读 [k]，结尾是鼻音 [ɛ̃]，不读 n。","tr":{"zh":"我在海里看到一条鲨鱼。","fr":"J'ai vu un requin dans la mer.","alt":"Dans la mer, j'ai aperçu un requin.","note":"apercevoir：瞥见，比 voir 更突然。"}},
 "Un rhinocéros": {"pos":"n.m. 阳性名词，单复数同形 rhinocéros","s":"犀牛。口语缩写 un rhino。","ipa":"[ʁi.nɔ.se.ʁɔs]","ph":"rh 的 h 不发音，读 [ʁ]；c 在 é 前读 [s]；结尾 -os 的 s 要读 [s]。","pi":"rh 读 [ʁ]；结尾 s 要发音；单复数同形；拼写很长，记住 rhi-no-cé-ros 四段。","et":"来自希腊语 rhinokeros，由 rhis, rhinos（鼻）+ keras（角）：「鼻子上有角」。","ex":[["Le rhinocéros a une corne.","犀牛有一只角。"],["Les rhinocéros sont en danger.","犀牛处于危险中。"]],"co":[["un rhinocéros blanc","白犀牛"],["une corne de rhinocéros","犀牛角"],["un rhinocéros en danger","濒危的犀牛"]],"sy":[["rhino","familier","犀牛（简称）"],["hippopotame","courant","河马（别混淆）"]],"fq":"低中频。","me":"rhino（鼻）+ céros（角）：鼻子上长角的动物。","tr":{"zh":"犀牛的鼻子上有一只角。","fr":"Le rhinocéros a une corne sur le nez.","alt":"Le rhinocéros porte une corne sur le nez.","note":"avoir + 部位：有……；sur le nez：在鼻子上。"}},
 "Un rongeur": {"pos":"n.m. 阳性名词，复数 rongeurs","s":"啮齿动物。老鼠、松鼠、仓鼠、河狸等都是 rongeurs，它们的门牙会不断生长，要靠啃东西磨短。来自动词 ronger（啃）。","ipa":"[ʁɔ̃.ʒœʁ]","ph":"on 读鼻化音 [ɔ̃]；g 在 e 前读 [ʒ]；eu 读 [œ]；结尾 r 读 [ʁ]。","pi":"g 读 [ʒ]；结尾 r 要读 [ʁ]；注意 -eur 的发音 [œʁ]。","et":"ronger（啃，来源不明）+ -eur（表示做某事的人或动物）。","ex":[["Le hamster est un rongeur.","仓鼠是啮齿动物。"],["Les rongeurs ont de grandes dents.","啮齿动物有大牙齿。"]],"co":[["un petit rongeur","小型啮齿动物"],["ronger un os","啃骨头"],["des dents de rongeur","啮齿动物的牙齿"]],"sy":[["rat","courant","老鼠"],["écureuil","courant","松鼠"]],"fq":"中低频。","me":"ronger（啃）+ -eur（做……的）：啃东西的家伙。","tr":{"zh":"老鼠是啮齿动物。","fr":"La souris est un rongeur.","alt":"Une souris, c'est un rongeur.","note":"C'est un + 名词 用来给出类别。"}},
 "Un serpent": {"pos":"n.m. 阳性名词，复数 serpents","s":"蛇。比喻阴险的人（un serpent）。serpent à sonnettes = 响尾蛇。","ipa":"[sɛʁ.pɑ̃]","ph":"s [s]；e 在 r 前读 [ɛ]；结尾 -ent 读鼻化 [ɑ̃]，t 不发。","pi":"结尾 -ent 读 [ɑ̃]，t 不发音；复数 s 也不发。","et":"来自拉丁语 serpens（爬行的），源于 serpere（爬）。","ex":[["Le serpent glisse.","蛇在滑行。"],["Ce serpent est très dangereux.","这条蛇非常危险。"]],"co":[["un serpent venimeux","毒蛇"],["un serpent à sonnettes","响尾蛇"],["un charmeur de serpents","弄蛇人"]],"sy":[["couleuvre","courant","游蛇（无毒）"],["vipère","courant","蝰蛇（有毒）"]],"fq":"中频。","me":"serpent 和英语 serpent 同源，一看就懂。","tr":{"zh":"蛇在草里。","fr":"Il y a un serpent dans l'herbe.","alt":"Un serpent se cache dans l'herbe.","note":"il y a + 名词：有……"}},
 "Un singe": {"pos":"n.m. 阳性名词，复数 singes","s":"猴子；猿。法语里 singe 同时包括猴和猿（gorille 也是 singe 的一种）。faire le singe = 搞怪、胡闹。","ipa":"[sɛ̃ʒ]","ph":"in 读鼻化音 [ɛ̃]；g 在 e 前读 [ʒ]；结尾 e 不发。","pi":"g 读 [ʒ]，不是 [ɡ]；in 是鼻化 [ɛ̃]，别读成 [sin]。","et":"来自拉丁语 simius（猿）。","ex":[["Le singe mange une banane.","猴子吃香蕉。"],["Arrête de faire le singe !","别胡闹了！"]],"co":[["faire le singe","搞怪、胡闹"],["malin comme un singe","像猴子一样机灵"],["un singe savant","表演的猴子"]],"sy":[["gorille","courant","大猩猩"],["chimpanzé","courant","黑猩猩"]],"fq":"高频，也用于成语。","me":"singe ← simius，英语 simian（猿猴的）同源。","tr":{"zh":"孩子们看着猴子笑。","fr":"Les enfants rient en regardant les singes.","alt":"Les enfants regardent les singes et rigolent.","note":"en + 现在分词：表示同时做两件事。"}},
 "Un tigre": {"pos":"n.m. 阳性名词，复数 tigres；雌虎 une tigresse","s":"老虎。比喻凶猛的人。le tigre de papier = 纸老虎。","ipa":"[tiɡʁ]","ph":"t [t]；i [i]；gr 读 [ɡʁ]，结尾 e 不发。","pi":"g 读 [ɡ]，不是 [ʒ]；结尾 -re 读 [ʁ]，e 不发，所以是一个音节：tigre [tiɡʁ]。","et":"来自拉丁语和希腊语 tigris，可能最早源于波斯语一带的词，来源不完全确定。","ex":[["Le tigre court vite.","老虎跑得很快。"],["Un tigre est sorti de la forêt.","一只老虎从森林里走出来。"]],"co":[["un tigre du Bengale","孟加拉虎"],["un tigre de papier","纸老虎"],["rugir comme un tigre","像老虎一样吼叫"]],"sy":[["fauve","courant","猛兽（总称）"],["félin","soutenu","猫科动物"]],"fq":"中频。","me":"tigre：和英语 tiger 一样，但 g 要发 [ɡ]，e 不发。","tr":{"zh":"老虎是濒危动物。","fr":"Le tigre est un animal en danger.","alt":"Le tigre est une espèce menacée.","note":"en danger / menacé：处于危险中。"}},
 "Un végétal": {"pos":"n.m. 阳性名词，复数 végétaux（-al 变 -aux）","s":"植物（生物学上的）。也可作形容词：végétal / végétale，意思是「植物的」。例：huile végétale（植物油）。","ipa":"[ve.ʒe.tal]","ph":"é [e]；g 在 é 前读 [ʒ]；结尾 -al 读 [al]。","pi":"复数是 végétaux [ve.ʒe.to]，不是 végétals；g 读 [ʒ]。","et":"来自拉丁语 vegetare（使有活力、生长）。同源：végétation, végétarien。","ex":[["C'est un végétal vert.","这是一种绿色植物。"],["Les végétaux ont besoin de lumière.","植物需要光。"]],"co":[["le règne végétal","植物界"],["une huile végétale","植物油"],["un végétal et un animal","一种植物和一种动物"]],"sy":[["plante","courant","植物（日常用词）"],["animal","courant","动物（反义）"]],"fq":"中低频，科学类。","me":"végétal 里有 végétarien：吃 végétaux 的人。","tr":{"zh":"植物需要水和阳光。","fr":"Les végétaux ont besoin d'eau et de soleil.","alt":"Les plantes ont besoin d'eau et de soleil.","note":"avoir besoin de + 名词；日常更常说 plantes。"}},
 "L'ingéniosité": {"pos":"n.f. 阴性名词，复数 ingéniosités（很少用复数）","s":"聪明才智；巧妙的创造力。形容想出巧妙办法的能力。形容词是 ingénieux（巧妙的）。","ipa":"[ɛ̃.ʒe.njo.zi.te]","ph":"in 读鼻化音 [ɛ̃]；g 在 é 前读 [ʒ]；ni 读 [nj]；s 在元音间读 [z]。","pi":"s 读 [z]，不是 [s]；与 ingénuité（天真）拼写相近，意思完全不同。","et":"来自 ingénieux（拉丁语 ingeniosus，源于 ingenium，天赋）+ -ité。","ex":[["J'admire son ingéniosité.","我佩服他的巧思。"],["Cette solution montre beaucoup d'ingéniosité.","这个方案很有巧思。"]],"co":[["faire preuve d'ingéniosité","表现出聪明才智"],["avec ingéniosité","巧妙地"],["l'ingéniosité humaine","人类的聪明才智"]],"sy":[["astuce","courant","巧妙的办法"],["inventivité","soutenu","创造力"]],"fq":"中低频。","me":"ingénieur（工程师）的亲戚：爱想办法的人。","tr":{"zh":"他用很巧妙的方法解决了问题。","fr":"Il a résolu le problème avec beaucoup d'ingéniosité.","alt":"Il a réglé le problème de façon très ingénieuse.","note":"résoudre → a résolu；beaucoup de + 名词，不加冠词。"}},
 "La biodiversité": {"pos":"n.f. 阴性名词，通常不用复数","s":"生物多样性。一个地方生物种类的丰富程度。新闻和环保话题里常出现，如 protéger la biodiversité。","ipa":"[bjo.di.vɛʁ.si.te]","ph":"bio 读 [bjo]；div 读 [div]；ers 读 [ɛʁs]，s 读 [s]；ité 读 [i.te]。","pi":"bio- 读 [bjo]，是一个音节；句中 s 读 [s]，不是 [z]；阴性。","et":"bio-（希腊语 bios，生命）+ diversité（拉丁语 diversitas，不同）。","ex":[["La biodiversité est importante.","生物多样性很重要。"],["La pollution menace la biodiversité.","污染威胁生物多样性。"]],"co":[["protéger la biodiversité","保护生物多样性"],["la perte de biodiversité","生物多样性的丧失"],["la biodiversité marine","海洋生物多样性"]],"sy":[["diversité","courant","多样性（更广）"],["écosystème","courant","生态系统（相关）"]],"fq":"中频，新闻和环保话题。","me":"bio（生命）+ diversité（多样）：各种各样的生命。","tr":{"zh":"我们必须保护生物多样性。","fr":"Nous devons protéger la biodiversité.","alt":"Il faut protéger la biodiversité.","note":"devoir + 动词原形 / il faut + 动词原形：必须。"}},
 "La déforestation": {"pos":"n.f. 阴性名词，通常不用复数","s":"森林砍伐；毁林。为了开垦或取木材而大量砍树。同义的日常词：le déboisement。","ipa":"[de.fɔ.ʁɛs.ta.sjɔ̃]","ph":"dé [de]；fo 读 [fɔ]；res 读 [ʁɛs]；-tion 读 [sjɔ̃]。","pi":"-tion 读 [sjɔ̃]，不是 [tjɔ̃]；forêt 有 ê，但 déforestation 拼成 fores-，没有 ^。","et":"dé-（去除）+ forest-（来自 forêt）+ -ation，表示动作。","ex":[["La déforestation détruit les forêts.","砍伐森林破坏森林。"],["La déforestation augmente en Amazonie.","亚马逊的毁林在增加。"]],"co":[["lutter contre la déforestation","对抗毁林"],["la déforestation de l'Amazonie","亚马逊的毁林"],["arrêter la déforestation","停止毁林"]],"sy":[["déboisement","courant","伐林"],["reforestation","courant","再造林（反义）"]],"fq":"中频，新闻常用。","me":"dé（去掉）+ forêt：把森林去掉。","tr":{"zh":"毁林是一个大问题。","fr":"La déforestation est un gros problème.","alt":"La déforestation, c'est un énorme problème.","note":"gros / énorme 放在名词前。"}},
 "La faune": {"pos":"n.f. 阴性名词，复数 faunes（少用）","s":"（某地区的）动物群；动物总称。常与 la flore（植物群）成对出现：la faune et la flore。","ipa":"[fon]","ph":"au 读 [o]；n [n]；结尾 e 不发。","pi":"au 读 [o]，不读 [au]；faune 与 faon（小鹿，读 [fɑ̃]）拼写相近，读音不同。","et":"来自拉丁语 Faunus，古罗马的田野森林之神。","ex":[["J'aime observer la faune.","我喜欢观察动物。"],["La faune de cette région est riche.","这个地区的动物种类丰富。"]],"co":[["la faune et la flore","动植物"],["la faune sauvage","野生动物"],["la faune marine","海洋动物"]],"sy":[["animaux","courant","动物"],["flore","courant","植物群（对照）"]],"fq":"中低频。","me":"faune：森林之神 Faunus，管动物。","tr":{"zh":"这个公园保护当地的动植物。","fr":"Ce parc protège la faune et la flore locales.","alt":"Ce parc protège les animaux et les plantes du coin.","note":"faune et flore 通常一起出现。"}},
 "La flore": {"pos":"n.f. 阴性名词，复数 flores（少用）","s":"（某地区的）植物群；植物总称。与 la faune（动物群）对应。也可指肠道菌群（la flore intestinale）。","ipa":"[flɔʁ]","ph":"fl 读 [fl]；o 读 [ɔ]；结尾 r 读 [ʁ]，e 不发。","pi":"o 读开口 [ɔ]；结尾 r 要读。","et":"来自拉丁语 Flora，古罗马的花神。同源：fleur（花）。","ex":[["La flore est magnifique ici.","这里的植物很美。"],["La flore de la montagne change avec l'altitude.","山上的植物随海拔变化。"]],"co":[["la flore locale","当地植物"],["la faune et la flore","动植物"],["la flore intestinale","肠道菌群"]],"sy":[["végétation","courant","植被"],["plantes","courant","植物（日常用词）"]],"fq":"中低频。","me":"flore 和 fleur 是亲戚：花神 Flora。","tr":{"zh":"春天，这里的植物特别美。","fr":"Au printemps, la flore est très belle ici.","alt":"Au printemps, il y a de superbes fleurs et plantes ici.","note":"au printemps：在春天。"}},
 "La joie": {"pos":"n.f. 阴性名词，复数 joies","s":"喜悦；快乐。比 bonheur（幸福）更强调当下的欣喜。Joie de vivre = 生活的乐趣。","ipa":"[ʒwa]","ph":"j [ʒ]；oi 读 [wa]；结尾 e 不发。","pi":"oi 读 [wa]；注意拼写 joie 有 e；与 joue（脸颊）读音不同。","et":"来自拉丁语 gaudia（gaudium 的复数，欢乐）。","ex":[["Je ressens de la joie.","我感到喜悦。"],["Les enfants crient de joie.","孩子们高兴得大叫。"]],"co":[["pleurer de joie","喜极而泣"],["la joie de vivre","生活的乐趣"],["avec joie","乐意地"],["sauter de joie","高兴得跳起来"]],"sy":[["bonheur","courant","幸福"],["allégresse","soutenu","欢欣"]],"fq":"高频。","me":"joie ≈ 英语 joy（同源），读 [ʒwa]。","tr":{"zh":"她高兴得哭了。","fr":"Elle a pleuré de joie.","alt":"Elle pleurait de joie.","note":"de + 无冠词名词表示原因：pleurer de joie。"}},
 "La reforestation": {"pos":"n.f. 阴性名词，通常不用复数","s":"再造林；植树造林。重新种树，恢复森林。日常也说 le reboisement。","ipa":"[ʁə.fɔ.ʁɛs.ta.sjɔ̃]","ph":"re 读 [ʁə]；fo 读 [fɔ]；res 读 [ʁɛs]；-tion 读 [sjɔ̃]。","pi":"-tion 读 [sjɔ̃]；re- 轻读 [ʁə]；与 déforestation 一对反义词，别弄混。","et":"re-（再）+ forestation（forêt 的词根 + -ation）。","ex":[["La reforestation aide la planète.","再造林帮助地球。"],["La reforestation commence par des arbres jeunes.","再造林从幼树开始。"]],"co":[["un projet de reforestation","再造林项目"],["lutter par la reforestation","用植树对抗毁林"],["la reforestation des montagnes","山区的再造林"]],"sy":[["reboisement","courant","重新植树"],["déforestation","courant","毁林（反义）"]],"fq":"中频。","me":"re（再）+ forêt：再把森林种回来。","tr":{"zh":"这个城市在做再造林。","fr":"Cette ville fait de la reforestation.","alt":"Cette ville plante de nouveaux arbres.","note":"faire de la + 抽象名词。"}},
 "La tristesse": {"pos":"n.f. 阴性名词，复数 tristesses","s":"悲伤；忧愁。对应形容词 triste。语气温和，指难过的心情。","ipa":"[tʁis.tɛs]","ph":"tr [tʁ]；i [i]；ss 读 [s]；结尾 -esse 读 [ɛs]。","pi":"结尾 -esse 读 [ɛs]，不是 [es]；ss 读 [s]，不要读 [z]。","et":"来自拉丁语 tristitia，源于 tristis（悲伤的）。","ex":[["Il cache sa tristesse.","他掩饰自己的悲伤。"],["Elle sourit, mais on voit sa tristesse.","她在笑，但能看出她的悲伤。"]],"co":[["une immense tristesse","巨大的悲伤"],["cacher sa tristesse","掩饰悲伤"],["avec tristesse","悲伤地"],["une grande tristesse","很大的悲伤"]],"sy":[["chagrin","courant","伤心、痛苦"],["mélancolie","soutenu","忧郁"]],"fq":"高频。","me":"triste + -esse：把「悲伤」变成名词。","tr":{"zh":"她眼里有悲伤。","fr":"Il y a de la tristesse dans ses yeux.","alt":"Elle a de la tristesse dans le regard.","note":"de la + 抽象名词表示一部分。"}},
 "Une abeille": {"pos":"n.f. 阴性名词，复数 abeilles","s":"蜜蜂。酿蜜、传粉的昆虫。蜂巢是 une ruche，养蜂人是 un apiculteur。","ipa":"[a.bɛj]","ph":"a [a]；b [b]；eille 读 [ɛj]。","pi":"-eille 读 [ɛj]，不是 [ɛl]；l 不发音。","et":"来自拉丁语 apicula（apis，蜂 的指小词）。","ex":[["L'abeille fait du miel.","蜜蜂酿蜜。"],["Une abeille m'a piqué.","一只蜜蜂蛰了我。"]],"co":[["une piqûre d'abeille","蜜蜂蜇伤"],["une ruche d'abeilles","一窝蜜蜂"],["travailler comme une abeille","像蜜蜂一样勤劳"]],"sy":[["guêpe","courant","黄蜂"],["bourdon","courant","熊蜂"]],"fq":"中频。","me":"abeille 的 -eille 和 bouteille、oreille 同音 [ɛj]。","tr":{"zh":"蜜蜂在花上。","fr":"Une abeille est sur la fleur.","alt":"Il y a une abeille sur la fleur.","note":"sur la fleur：在花上。"}},
 "Une araignée": {"pos":"n.f. 阴性名词，复数 araignées","s":"蜘蛛。araignée 不是昆虫，是蛛形动物。une toile d'araignée = 蜘蛛网。","ipa":"[a.ʁɛ.ɲe]","ph":"ai 读 [ɛ]；gn 读 [ɲ]；结尾 -ée 读 [e]。","pi":"gn 读 [ɲ]，像「泥」的「ni」；ai 读 [ɛ]，不是 [ai]；拼写有 ée。","et":"来自拉丁语 aranea（蜘蛛）。","ex":[["L'araignée tisse sa toile.","蜘蛛织网。"],["J'ai peur des araignées.","我怕蜘蛛。"]],"co":[["une toile d'araignée","蜘蛛网"],["avoir une araignée au plafond","有点疯疯癫癫（口语）"],["une araignée de mer","蜘蛛蟹"]],"sy":[["mygale","courant","捕鸟蛛"],["arachnide","soutenu","蛛形纲动物（科学词）"]],"fq":"中频。","me":"araignée 读 [a.ʁɛ.ɲe]：蜘蛛一步一步爬。","tr":{"zh":"墙上有一只蜘蛛。","fr":"Il y a une araignée sur le mur.","alt":"Une araignée se promène sur le mur.","note":"sur le mur：在墙上。"}},
 "Une baleine": {"pos":"n.f. 阴性名词，复数 baleines","s":"鲸；鲸鱼（其实是哺乳动物）。baleine bleue = 蓝鲸。baleine 也指伞骨、胸衣的鱼骨条。","ipa":"[ba.lɛn]","ph":"ei 读 [ɛ]；ne 读 [n]；e 不发。","pi":"ei 读 [ɛ]，不是 [ei]；结尾 -ne 的 n 要发 [n]，不是鼻音。","et":"来自拉丁语 balaena（鲸），原自希腊语。","ex":[["La baleine est énorme.","鲸鱼巨大。"],["Nous avons vu une baleine en mer.","我们在海上看到了一头鲸。"]],"co":[["une baleine bleue","蓝鲸"],["rire comme une baleine","放声大笑（口语）"],["l'observation des baleines","观鲸"],["un chant de baleine","鲸歌"]],"sy":[["cétacé","soutenu","鲸类"],["dauphin","courant","海豚"]],"fq":"中频。","me":"baleine → 英语 baleen（鲸须），同一个拉丁语词根。","tr":{"zh":"鲸鱼不是鱼。","fr":"La baleine n'est pas un poisson.","alt":"Une baleine, ce n'est pas un poisson.","note":"否定：ne… pas。"}},
 "Une balle": {"pos":"n.f. 阴性名词，复数 balles","s":"球（较小的，如网球、乒乓球）；子弹。大球（足球、篮球）用 un ballon。une balle de tennis = 网球。","ipa":"[bal]","ph":"a [a]；ll 读 [l]；结尾 e 不发。","pi":"balle（小球、子弹）vs ballon（大球）；b 与 p 要分清。","et":"来自日耳曼语 *balla（球），与英语 ball 同源。","ex":[["Je lance une balle.","我扔一个球。"],["Il joue avec une balle de tennis.","他在玩一个网球。"]],"co":[["une balle de tennis","网球"],["une balle de golf","高尔夫球"],["renvoyer la balle","把球回过去（反驳）"],["une balle perdue","流弹"]],"sy":[["ballon","courant","大球"],["boule","courant","球（圆形物）"]],"fq":"高频。","me":"balle ≈ ball：英语和法语是一家。","tr":{"zh":"孩子把球扔给狗。","fr":"L'enfant lance la balle au chien.","alt":"Le petit lance la balle à son chien.","note":"lancer qqch à qqn：把某物扔给某人。"}},
 "Une catastrophe": {"pos":"n.f. 阴性名词，复数 catastrophes","s":"灾难；灾祸；糟糕的事。catastrophe naturelle = 自然灾害。口语里夸张地说「糟了！」：C'est une catastrophe !","ipa":"[ka.ta.stʁɔf]","ph":"ca [ka]；ta [ta]；stro 读 [stʁɔ]；ph 读 [f]；结尾 e 不发。","pi":"ph 读 [f]；重音在最后一个音节；r 是小舌音。","et":"来自希腊语 katastrophē（翻转、结局）。","ex":[["C'est une catastrophe naturelle.","这是一场自然灾害。"],["J'ai oublié mon passeport, quelle catastrophe !","我忘了护照，真糟糕！"]],"co":[["une catastrophe naturelle","自然灾害"],["quelle catastrophe !","真是灾难！"],["en cas de catastrophe","万一发生灾难"],["éviter la catastrophe","避免灾难"]],"sy":[["désastre","courant","灾难"],["drame","courant","悲剧"]],"fq":"中高频。","me":"catastrophe ≈ catastrophe：ph = f。","tr":{"zh":"这场灾难让很多人无家可归。","fr":"Cette catastrophe a laissé beaucoup de gens sans maison.","alt":"À cause de cette catastrophe, beaucoup de gens n'ont plus de maison.","note":"à cause de：因为（多用于不好的原因）。"}},
 "Une espèce": {"pos":"n.f. 阴性名词，复数 espèces","s":"物种；种类。espèce menacée = 濒危物种。espèce de + 名词用于带贬义的口语：espèce d'idiot ! ；en espèces = 用现金。","ipa":"[ɛs.pɛs]","ph":"es [ɛs]；p [p]；è 读 [ɛ]；结尾 e 不发。","pi":"espèce 是阴性；开头 es- 读 [ɛs]；当「现金」时用复数 espèces。","et":"来自拉丁语 species（外观，类型）。同源：spécial, spécifique。","ex":[["Les tigres sont une espèce menacée.","老虎是濒危物种。"],["Ici, on ne trouve qu'une espèce d'oiseau.","这里只有一种鸟。"]],"co":[["une espèce menacée / protégée","濒危 / 受保护物种"],["une espèce en voie de disparition","濒临灭绝的物种"],["payer en espèces","付现金"],["espèce de + 名词","你这个……（带贬义）"]],"sy":[["sorte","courant","种类、类型"],["genre","courant","类别（分类学「属」）"]],"fq":"高频。","me":"espèce ≈ species（物种）：s 和 p 依次出现。","tr":{"zh":"这是一种很稀有的物种。","fr":"C'est une espèce très rare.","alt":"Cette espèce est vraiment très rare.","note":"très + 形容词。"}},
 "Une femelle": {"pos":"n.f. 阴性名词，复数 femelles（也可作形容词）","s":"雌性；母的（动物）。对应 un mâle。用于人时可能带贬义，指人一般说 une femme。","ipa":"[fə.mɛl]","ph":"fe 读 [fə]；m [m]；elle 读 [ɛl]；e 不发。","pi":"fe- 读 [fə]，不是 [fe]；与 femme 区分；对人使用有时不礼貌。","et":"来自拉丁语 femella（femina 的指小词，女人）。","ex":[["C'est une femelle.","这是雌性。"],["La femelle protège ses petits.","母兽保护幼崽。"]],"co":[["un mâle et une femelle","一雄一雌"],["une chienne femelle","母狗"],["la femelle du lion","母狮"],["une femelle gestante","怀孕的雌性"]],"sy":[["mâle","courant","雄性（反义）"],["femme","courant","女人（人类）"]],"fq":"中频。","me":"femelle 来自 femme：女性的小词。","tr":{"zh":"这只母猫有三只小猫。","fr":"Cette femelle a trois chatons.","alt":"Cette chatte a trois petits.","note":"chaton：小猫；petits：幼崽。"}},
 "Une gamelle": {"pos":"n.f. 阴性名词，复数 gamelles","s":"食盆（宠物的）；饭盒；军用饭盒。口语 prendre une gamelle = 摔跤。","ipa":"[ɡa.mɛl]","ph":"g [ɡ]；a [a]；m [m]；elle 读 [ɛl]。","pi":"g 读 [ɡ]；-elle 读 [ɛl]；别和 camelle 混淆。","et":"来源不确定（可能借自意大利语 gamella）。","ex":[["Le chien mange dans sa gamelle.","狗在自己的食盆里吃饭。"],["Remplis la gamelle du chat, s'il te plaît.","请把猫的食盆装满。"]],"co":[["la gamelle du chien","狗食盆"],["remplir la gamelle","把食盆装满"],["prendre une gamelle","摔了一跤（口语）"],["une gamelle de camping","露营饭盒"]],"sy":[["bol","courant","碗"],["écuelle","soutenu","木碗、盆"]],"fq":"中低频。","me":"gamelle：狗吃饭的地方，想象狗盯着食盆「嘎-咩-」地叫。","tr":{"zh":"狗的食盆是空的。","fr":"La gamelle du chien est vide.","alt":"Il n'y a plus rien dans la gamelle du chien.","note":"vide：空的；ne… plus rien：什么也没有了。"}},
 "Une graine": {"pos":"n.f. 阴性名词，复数 graines","s":"种子。种在土里会长成植物。graine 比 grain（谷粒、一粒）更像「种子」。","ipa":"[ɡʁɛn]","ph":"gr 读 [ɡʁ]；ai 读 [ɛ]；结尾 -ne 的 n 要读 [n]。","pi":"ai 读 [ɛ]，不是 [ai]；与 grain [ɡʁɛ̃]（鼻音）不同，graine 的 n 要读出。","et":"来自拉丁语 grana（granum 的复数，谷粒）。同源：grain, granule。","ex":[["Je plante une graine.","我种下一颗种子。"],["Les oiseaux mangent des graines.","鸟吃种子。"]],"co":[["planter des graines","播种"],["une graine de tournesol","葵花籽"],["une mauvaise graine","坏种子（坏人）"],["monter en graine","结籽；长得太快"]],"sy":[["semence","soutenu","种子（农业）"],["pépin","courant","果核；籽"]],"fq":"中频。","me":"graine ≈ grain，区别在 n：graine 发 [n]。","tr":{"zh":"把种子种在土里。","fr":"Plante la graine dans la terre.","alt":"Mets la graine en terre.","note":"祈使句 plante：第二人称。"}},
 "Une grenouille": {"pos":"n.f. 阴性名词，复数 grenouilles","s":"青蛙。蟾蜍是 un crapaud。Homme-grenouille = 蛙人（潜水员）。","ipa":"[ɡʁə.nuj]","ph":"gre 读 [ɡʁə]；nouille 读 [nuj]，ou 读 [u]，ille 读 [j]。","pi":"-ouille 读 [uj]，l 不发音；第一个 e 轻读 [ə]；与 nouille（面条）相近。","et":"来源不确定（可能来自拉丁语 ranuncula，rana 的指小词）。","ex":[["La grenouille saute.","青蛙跳。"],["J'entends les grenouilles dans le jardin.","我听到花园里有青蛙叫。"]],"co":[["une cuisse de grenouille","蛙腿"],["une grenouille verte","绿青蛙"],["un concert de grenouilles","蛙鸣"]],"sy":[["crapaud","courant","蟾蜍"],["batracien","soutenu","两栖动物"]],"fq":"中频。","me":"grenouille 和 nouille（面条）押韵，想象青蛙爱吃面条。","tr":{"zh":"青蛙跳进水里。","fr":"La grenouille saute dans l'eau.","alt":"La grenouille plonge dans l'eau.","note":"sauter dans：跳进。"}},
 "Une huître": {"pos":"n.f. 阴性名词，复数 huîtres","s":"牡蛎；生蚝。法国人在节日常吃生蚝，配柠檬或醋。une huître perlière = 产珍珠的牡蛎。","ipa":"[ɥitʁ]","ph":"h 不发音；u 读 [ɥ]；î 读 [i]；tre 读 [tʁ]。","pi":"h 不发音，所以 l'huître 要省音；u + i 连成 [ɥi]，要快；复数 s 不发。","et":"来自拉丁语 ostrea（希腊语 ostreon），英语 oyster 同源。","ex":[["Je mange une huître.","我吃一只牡蛎。"],["Les huîtres se mangent crues.","生蚝是生吃的。"]],"co":[["ouvrir une huître","开牡蛎"],["des huîtres de Bretagne","布列塔尼生蚝"],["une huître perlière","珍珠贝"],["manger des huîtres","吃生蚝"]],"sy":[["coquillage","courant","贝类"],["fruits de mer","courant","海鲜"]],"fq":"中频。","me":"huître ≈ oyster：两个词是同源的。","tr":{"zh":"我喜欢在圣诞节吃生蚝。","fr":"J'aime manger des huîtres à Noël.","alt":"À Noël, j'adore les huîtres.","note":"à Noël：在圣诞节。"}},
 "Une méduse": {"pos":"n.f. 阴性名词，复数 méduses","s":"水母。海边游泳时可能被蜇：une piqûre de méduse。","ipa":"[me.dyz]","ph":"mé 读 [me]；u 读 [y]；s 在元音间读 [z]。","pi":"u 读 [y]（嘴圆）；s 读 [z]；méduse 是阴性。","et":"来自希腊神话中的美杜莎 Méduse，她的头发是蛇，水母的触手像蛇发。","ex":[["La méduse est transparente.","水母是透明的。"],["Attention, il y a des méduses dans l'eau.","小心，水里有水母。"]],"co":[["une piqûre de méduse","水母蜇伤"],["une méduse transparente","透明的水母"],["un banc de méduses","一群水母"]],"sy":[["cnidaire","soutenu","刺胞动物"],["poisson","courant","鱼（对比：水母不是鱼）"]],"fq":"中低频。","me":"méduse：神话里的蛇发女妖，触手像蛇。","tr":{"zh":"水母蜇了他的腿。","fr":"Une méduse l'a piqué à la jambe.","alt":"Il s'est fait piquer à la jambe par une méduse.","note":"piquer à la jambe：蜇到腿。"}},
 "Une mouche": {"pos":"n.f. 阴性名词，复数 mouches","s":"苍蝇。也是钓鱼的假饵，或靶心。Prendre la mouche = 突然发火。","ipa":"[muʃ]","ph":"ou 读 [u]；ch 读 [ʃ]；结尾 e 不发。","pi":"ou 读 [u]；ch 读 [ʃ]；与 mouton 的 [mu] 相同。","et":"来自拉丁语 musca（苍蝇）。","ex":[["Il y a une mouche ici.","这里有一只苍蝇。"],["Une mouche tourne autour de la table.","一只苍蝇绕着桌子飞。"]],"co":[["prendre la mouche","突然发火"],["chasser une mouche","赶苍蝇"],["faire mouche","击中靶心；说中"],["quelle mouche t'a piqué ?","你吃错药了吗？"]],"sy":[["moustique","courant","蚊子"],["insecte","courant","昆虫（总称）"]],"fq":"中频，成语多。","me":"mouche 读 [muʃ]：像苍蝇嗡嗡声。","tr":{"zh":"一只苍蝇落在我的汤里。","fr":"Une mouche est tombée dans ma soupe.","alt":"Il y a une mouche dans ma soupe !","note":"tomber dans：掉进；用 être 的复合过去时。"}},
 "Une pieuvre": {"pos":"n.f. 阴性名词，复数 pieuvres","s":"章鱼。菜单上常说 un poulpe（章鱼，食材）。pieuvre 有八条腕足（bras / tentacules）。","ipa":"[pjœvʁ]","ph":"pi 读 [pj]；eu 读 [œ]；v 读 [v]；结尾 -vre 读 [vʁ]，e 不发。","pi":"pieu- 读 [pjœ]，一个音节；结尾 -vre 要读 [vʁ]。","et":"来自方言，源于拉丁语 polypus（多足的），经诺曼底方言而来；同源：poulpe。","ex":[["La pieuvre a huit bras.","章鱼有八条腕。"],["Une pieuvre se cache dans la roche.","一只章鱼躲在岩石里。"]],"co":[["une pieuvre géante","巨大的章鱼"],["huit bras","八条腕"],["un poulpe","章鱼（食材）"]],"sy":[["poulpe","courant","章鱼（做菜时）"],["calmar","courant","鱿鱼"]],"fq":"中低频。","me":"pieuvre：开头像 pieu（木桩），想象八根长长的腕。","tr":{"zh":"章鱼躲在石头后面。","fr":"La pieuvre se cache derrière une pierre.","alt":"La pieuvre est cachée derrière un caillou.","note":"se cacher：躲起来（代词式动词）。"}},
 "Une place de parking": {"pos":"n.f. 阴性名词，复数 places de parking","s":"停车位。parking 是借自英语的词，但在法语中指「停车场」。place de parking 是日常常说的「车位」，也可说 une place de stationnement。","ipa":"[plas də paʁ.kiŋ]","ph":"place 读 [plas]；de 读 [də]；parking 读 [paʁ.kiŋ]，-ing 读 [iŋ]。","pi":"parking 的 -ing 读 [iŋ]，不是 [in]；在法语里 parking 不是「停车」，而是「停车场」。","et":"place 来自拉丁语 platea（宽街）；parking 借自英语 parking。","ex":[["Je cherche une place de parking.","我在找停车位。"],["Il n'y a plus de place de parking ici.","这里没有停车位了。"]],"co":[["trouver une place de parking","找到停车位"],["un parking gratuit","免费停车场"],["se garer","停车"],["une place de parking réservée","专用车位"]],"sy":[["stationnement","courant","停车（行为或位置）"],["emplacement","courant","位置、车位"]],"fq":"中高频，日常常用。","me":"place（位置）+ parking（停车）：停车的位置。","tr":{"zh":"我没找到停车位。","fr":"Je n'ai pas trouvé de place de parking.","alt":"Je n'ai pas réussi à trouver de place pour me garer.","note":"否定后用 de：pas de place。"}},
 "Une poule": {"pos":"n.f. 阴性名词，复数 poules","s":"母鸡。也指做饭用的鸡肉（la poule au pot）。口语里 ma poule 是对女性或孩子的亲昵称呼，有点老派。公鸡是 un coq，小鸡是 un poussin。","ipa":"[pul]","ph":"ou [u]；l 要读出来；结尾 e 不发音。整个词只有一个音节。","pi":"结尾的 e 不发音，不要读成两个音节；ou 是 [u]，不是 [ɔ]。","et":"来自拉丁语 pulla（小母鸡）。同源：poulet（小鸡肉）、poulain（小马驹）。","ex":[["La poule pond un œuf.","母鸡下蛋。"],["Les poules vivent dans un poulailler.","母鸡住在鸡舍里。"]],"co":[["une poule pondeuse","产蛋母鸡"],["avoir la chair de poule","起鸡皮疙瘩"],["quand les poules auront des dents","永远不会（母鸡长牙时）"]],"sy":[["coq","courant","公鸡，与 poule 相对"],["poulet","courant","鸡（多指作为食物的鸡）"]],"fq":"中频，日常和农场话题常用。","me":"poule 的 ou 像中文「布」的元音；想象一只母鸡在咕咕叫 pou-pou。","tr":{"zh":"这只母鸡每天下一个蛋。","fr":"Cette poule pond un œuf tous les jours.","alt":"Cette poule fait un œuf par jour.","note":"pondre 是母鸡「下蛋」的专用动词。"}},
 "Une race (pour les animaux uniquement)": {"pos":"n.f. 阴性名词，复数 races","s":"（动物的）品种，如狗、猫、马的品种。用于人时指「种族」，但那个用法很敏感，一般避免。括号里的限制是提醒：品种只用于动物，植物的品种用 variété。","ipa":"[ʁas]","ph":"r 是小舌音 [ʁ]；a [a]；c 在 e 前读 [s]；结尾 e 不发音。","pi":"race 不是 course（比赛）；英语 race 的「赛跑」法语说 course。r 要用小舌音。","et":"来自意大利语 razza，更早的来源不确定。","ex":[["Quelle est ta race de chien préférée ?","你最喜欢哪个狗品种？"],["Ce chat est de race siamoise.","这只猫是暹罗品种。"]],"co":[["un chien de race","纯种狗"],["de race pure","纯种的"],["une race de chat","一种猫的品种"]],"sy":[["espèce","courant","物种，范围比 race 大（狗是一个 espèce，贵宾犬是一个 race）"],["variété","courant","（植物）品种"]],"fq":"中高频，谈宠物时很常用。","me":"race 读 [ʁas]，像「拉斯」；想到各种品种的狗在赛场上排队。","tr":{"zh":"你的狗是什么品种？","fr":"Ton chien est de quelle race ?","alt":"C'est quelle race, ton chien ?","note":"问品种用 de quelle race，race 前不加冠词。"}},
 "Une ruche": {"pos":"n.f. 阴性名词，复数 ruches","s":"蜂箱；蜂巢（蜜蜂住的地方）。比喻义：une vraie ruche 指到处忙忙碌碌、人声嘈杂的地方。","ipa":"[ʁyʃ]","ph":"r [ʁ]；u 是 [y]（嘴唇圆起来发 i）；ch 读 [ʃ]；结尾 e 不发音。","pi":"u 读 [y]，不是 [u]，也不是中文的「乌」；ch 读 [ʃ]（像「西」的卷舌），不是 [k]。","et":"常见说法是来自高卢语 *rusca（树皮），因为古时蜂箱用树皮做；这一点不完全确定。","ex":[["Les abeilles vivent dans une ruche.","蜜蜂住在蜂箱里。"],["Le bureau est une vraie ruche ce matin.","今天早上办公室像个忙碌的蜂巢。"]],"co":[["une ruche d'abeilles","一个蜂箱"],["une ruche en bois","木制蜂箱"],["un essaim quitte la ruche","一群蜂离开蜂巢"]],"sy":[["rucher","soutenu","蜂场（放很多蜂箱的地方）"],["nid","courant","鸟窝等「巢」，不用于蜂"]],"fq":"中低频，谈蜜蜂或自然时出现。","me":"ruche 的 u 要嘟嘴：想象蜜蜂 bzzz 时嘴唇圆圆的 [y]。","tr":{"zh":"这个蜂箱里有很多蜜蜂。","fr":"Il y a beaucoup d'abeilles dans cette ruche.","alt":"Cette ruche est pleine d'abeilles.","note":"Il y a ... dans ... 表示「……里有……」。"}},
 "Une tortue": {"pos":"n.f. 阴性名词，复数 tortues","s":"乌龟；龟（陆龟、海龟都叫 tortue，海龟用 tortue de mer）。le tortue 不对，永远是阴性。口语 avancer comme une tortue 指走得很慢。","ipa":"[tɔʁ.ty]","ph":"o [ɔ]；r [ʁ]；u [y]；结尾 e 不发音。两个音节：tor-tue。","pi":"ue 里的 u 读 [y]，e 不发音；不要读成 [tɔʁ.tu]。tortue 是阴性。","et":"来自中世纪拉丁语 tartaruca。形态上与 tordre（扭）无关，别混淆。","ex":[["La tortue marche doucement.","乌龟走得很慢。"],["Il a une tortue comme animal de compagnie.","他养了一只乌龟当宠物。"]],"co":[["une tortue de mer","海龟"],["avancer comme une tortue","像乌龟一样慢"],["une tortue d'eau douce","淡水龟"]],"sy":[["carapace","courant","龟壳，不是乌龟本身"],["lent(e)","courant","慢的（形容词）"]],"fq":"中频，宠物与动物话题常见。","me":"tor-tue：两个 t，想到 tortue 慢慢爬，像在说「慢慢地 tor-tue」。","tr":{"zh":"那只乌龟走得很慢。","fr":"Cette tortue avance très lentement.","alt":"Cette tortue est super lente.","note":"avancer lentement = 慢慢前进。"}},
 "Des produits ménagers": {"pos":"n.m.pl. 阳性复数名词（单数 un produit ménager）","s":"家用清洁用品（洗洁精、洗衣液、消毒水等）。固定用复数。produit 是阳性，ménager 在这里是形容词，意为「家务的」。","ipa":"[pʁɔ.dɥi me.na.ʒe]","ph":"produits 结尾 ts 不发音；ui 读 [ɥi]；ménagers 结尾 ers 读 [e]；g 在 e 前读 [ʒ]。","pi":"produits 里的 s 在句末不发音，但后面接元音时可能连读；ménagers 结尾 -ers 读 [e]，不要读出 r。","et":"produit 来自拉丁语 producere（带出来，制造）；ménager 来自 ménage（家庭、家务）。","ex":[["J'achète des produits ménagers.","我买家用清洁用品。"],["Range les produits ménagers hors de portée des enfants.","把清洁用品放在孩子够不到的地方。"]],"co":[["acheter des produits ménagers","买清洁用品"],["un produit ménager écologique","环保清洁剂"],["les tâches ménagères","家务活"]],"sy":[["produits d'entretien","courant","清洁保养用品，更常见的说法"],["détergent","soutenu","洗涤剂（专业词）"]],"fq":"中频，购物和家务场景里常用。","me":"ménage = 家；produits ménagers = 「家里用的产品」。","tr":{"zh":"我要去超市买清洁用品。","fr":"Je vais au supermarché acheter des produits ménagers.","alt":"Je vais faire les courses pour les produits ménagers.","note":"aller + 动词原形表示「去做」。"}},
 "Un(e) activiste": {"pos":"n.m./f. 名词，阴阳同形，复数 activistes","s":"积极分子；活动人士，投身某个社会或政治事业的人（环保、人权等）。阴阳同形：un activiste / une activiste。比 militant(e) 更强调行动，有时带「激进」色彩。","ipa":"[ak.ti.vist]","ph":"c [k]；t 在 i 前读 [t]（不读 [s]）；结尾 -iste 读 [ist]，e 不发音。","pi":"ti 读 [ti]，不是 [si]；结尾 e 不发音，重音在最后一个音节。阴阳同形，只改冠词。","et":"来自 actif（拉丁语 activus）加后缀 -iste（表示「持某种立场的人」）。","ex":[["Il est activiste pour le climat.","他是气候活动家。"],["Elle est activiste depuis dix ans.","她当了十年活动人士。"]],"co":[["un activiste écologiste","环保活动人士"],["un activiste des droits humains","人权活动人士"],["être activiste pour ...","为……而奔走"]],"sy":[["militant(e)","courant","党员、积极参加者，更常用"],["défenseur","soutenu","捍卫者，如 défenseur de l'environnement"]],"fq":"中频，新闻和社会话题常见。","me":"activ-iste：「积极」(actif) + 人 (-iste)。","tr":{"zh":"她是保护海洋的活动人士。","fr":"Elle est activiste pour la protection des océans.","alt":"C'est une activiste qui défend les océans.","note":"表示职业或身份时，être 后常省略冠词：Elle est activiste。"}},
 "Un(e) botaniste": {"pos":"n.m./f. 名词，阴阳同形，复数 botanistes","s":"植物学家。研究植物的人。阴阳同形：un botaniste / une botaniste。相关词：la botanique（植物学）。","ipa":"[bɔ.ta.nist]","ph":"o [ɔ]；t [t]；an 在这里不是鼻音，因为后面有 n 和元音：[ta.nist]；结尾 e 不发音。","pi":"ta-ni：这里 n 要读出来，不是鼻化元音；结尾 e 不发音，不要读成 botanisse 的两个音节。","et":"来自希腊语 botanê（草、牧草）加后缀 -iste。","ex":[["Elle est botaniste.","她是植物学家。"],["Ce botaniste étudie les plantes des montagnes.","这位植物学家研究山地植物。"]],"co":[["un jardin botanique","植物园"],["un botaniste célèbre","著名的植物学家"],["étudier la botanique","学习植物学"]],"sy":[["biologiste","courant","生物学家，范围更广"],["jardinier","courant","园丁，种植的人，不是研究者"]],"fq":"中低频，科学与自然话题里出现。","me":"botan- 像英语 botany；加 -iste 就是「植物学的人」。","tr":{"zh":"这位植物学家研究森林里的花。","fr":"Ce botaniste étudie les fleurs de la forêt.","alt":"Ce botaniste travaille sur les fleurs de la forêt.","note":"étudier + 直接宾语，不加介词。"}},
 "Appartenir": {"pos":"v. 动词，第三组，助动词 avoir；变位像 tenir","s":"属于。几乎总是 appartenir à + 人/团体：Ce livre m'appartient（这书是我的）。也可指属于某个类别或团体。注意：用 à，不用 de。","ipa":"[a.paʁ.tə.niʁ]","ph":"ap-par-te-nir：pp 读一个 [p]；ar [aʁ]；te 中的 e 是轻读 [ə]；结尾 r 读 [ʁ]。","pi":"pp 只读一个 [p]；现在时 j'appartiens [a.paʁ.tjɛ̃]，结尾 -tiens 读鼻音 [tjɛ̃]；要用 à，不要说「appartenir de」。","et":"来自拉丁语 appertinere，由 ad-（朝）+ pertinere（涉及）构成；词形上看到 tenir（拿着）。","ex":[["Ce livre m'appartient.","这本书是我的。"],["Cette maison appartient à ma famille.","这栋房子属于我家。"],["Il appartient à un club de sport.","他是一个体育俱乐部的成员。"]],"co":[["appartenir à qqn","属于某人"],["appartenir à un groupe","属于某个团体"],["Il appartient à ... de + 动词原形","……是……的责任"]],"sy":[["être à","courant","更口语：Ce livre est à moi"],["faire partie de","courant","属于（团体的一员）"]],"fq":"中频，书面和日常都会用。","me":"a-ppar-tenir：「去（à）+ 那一部分（part）+ 拿住（tenir）」，拿在手里就是你的。","tr":{"zh":"这把钥匙是我姐姐的。","fr":"Cette clé appartient à ma sœur.","alt":"Cette clé est à ma sœur.","note":"appartenir à + 名词，à 不能省略。"}},
 "Atteindre": {"pos":"v. 动词，第三组，助动词 avoir；变位像 peindre（j'atteins，atteint）","s":"达到；够到；抵达（目标、地点、数字、人）。atteindre un but = 达到目标；atteindre le sommet = 登顶；atteindre qqn au téléphone = 联系上某人。也可指「击中、影响」。","ipa":"[a.tɛ̃dʁ]","ph":"att 只读一个 [t]；ein 读鼻化 [ɛ̃]；dre 读 [dʁ]，e 不发音。","pi":"ein 读 [ɛ̃]，不是 [ɛn]；变位时有 -gn-：nous atteignons [a.tɛ.ɲɔ̃]，g 要拼出来。过去分词是 atteint，t 不发音。","et":"来自拉丁语 attingere（碰到），由 ad- + tangere（触碰）构成。同源：英语 attain。","ex":[["Je veux atteindre mon but.","我想达到我的目标。"],["Il a atteint le sommet à midi.","他中午登上了山顶。"],["Je n'arrive pas à l'atteindre au téléphone.","我联系不上他。"]],"co":[["atteindre un objectif","达到目标"],["atteindre le sommet","登顶"],["atteindre l'âge de ...","到达……岁"],["atteindre qqn au téléphone","打电话联系上某人"]],"sy":[["parvenir à","soutenu","设法达到，后接名词用 parvenir à / jusqu'à"],["arriver à","courant","到达；做到"],["rejoindre","courant","追上、与……会合"]],"fq":"中高频，B1 前后很有用。","me":"at-teindre：伸手去 touch，「够到」，英语 attain 一样。","tr":{"zh":"我们想在明年达到这个目标。","fr":"Nous voulons atteindre cet objectif l'année prochaine.","alt":"On veut atteindre ce but l'année prochaine.","note":"atteindre 后直接接宾语，不加介词。"}},
 "Compter": {"pos":"v. 动词，第一组，规则变位，助动词 avoir","s":"数数；计算；算上；打算（compter + 动词原形）。Je compte venir demain = 我打算明天来。compter sur qqn = 指望某人。compter 里的 p 不发音。","ipa":"[kɔ̃.te]","ph":"om 读鼻化 [ɔ̃]，后面的 p 不发音；t [t]；结尾 -er 读 [e]。","pi":"p 不发音：不是 [kɔ̃p.te]；om + p 这一组合只读 [ɔ̃]。","et":"来自拉丁语 computare（计算）。同源：conter（讲述）、un compte（账户）、un conte（故事）。","ex":[["Je sais compter jusqu'à dix.","我会数到十。"],["Je compte partir demain.","我打算明天走。"],["Tu peux compter sur moi.","你可以指望我。"]],"co":[["compter jusqu'à dix","数到十"],["compter sur qqn","指望某人"],["compter + 动词原形","打算做某事"],["sans compter ...","更不用说……"]],"sy":[["calculer","courant","计算，偏数学"],["avoir l'intention de","soutenu","有意做，比 compter 更正式"]],"fq":"极高频，日常必会。","me":"compter / conter / compte / conte：读音都是 [kɔ̃t]，靠上下文区分。","tr":{"zh":"你可以指望我，我会来的。","fr":"Tu peux compter sur moi, je viendrai.","alt":"Compte sur moi, je serai là.","note":"compter sur + 人；compter + 原形表示打算。"}},
 "Consister": {"pos":"v. 动词，第一组，规则变位，助动词 avoir","s":"在于；由……组成。固定搭配：consister en + 名词（由……构成），consister à + 动词原形（在于做某事）。多用于第三人称，书面语气稍正式。","ipa":"[kɔ̃.sis.te]","ph":"on 读鼻化 [ɔ̃]；s 在元音间的 ss 读 [s]；sis 的 s 都读 [s]；结尾 -er 读 [e]。","pi":"不要用 de：说 consister en 或 consister à。不要把它当作 être 的同义词乱用，只用于说明本质或组成。","et":"来自拉丁语 consistere（站在一起，稳定）。同源：consistance、résister。","ex":[["Mon travail consiste à aider les gens.","我的工作是帮助别人。"],["Ce plat consiste en riz et en légumes.","这道菜由米饭和蔬菜组成。"]],"co":[["consister à + 动词原形","在于做……"],["consister en + 名词","由……组成"],["en quoi consiste ... ?","……具体是什么？"]],"sy":[["se composer de","courant","由……组成"],["comprendre","courant","包括"]],"fq":"中频，书面和说明文常见。","me":"con-sister：和英语 consist 同形，意思也几乎一样。","tr":{"zh":"我的工作是回答客户的问题。","fr":"Mon travail consiste à répondre aux questions des clients.","alt":"Mon boulot, c'est de répondre aux questions des clients.","note":"consister à + 动词原形。"}},
 "Croître": {"pos":"v. 动词，第三组，不规则；助动词 avoir；j'ai crû（过去分词 crû）","s":"生长；增长；增加。比 pousser 书面，常用于植物、人口、数量。现在时：je croîs, il croît, nous croissons。更常用的相关词是 la croissance（增长）和 accroître（增加）。","ipa":"[kʁwatʁ]","ph":"cr [kʁ]；oî 读 [wa]；tre 读 [tʁ]，e 不发音，整个词只有一个音节。","pi":"î 的长音符不改变发音；croître 与 croire（相信）读音相近但不同：croire [kʁwaʁ]，croître [kʁwatʁ]。过去分词 crû 带音符，以区别 cru。","et":"来自拉丁语 crescere（生长）。同源：croissant（新月，也指羊角面包）、croissance。","ex":[["La plante va croître rapidement.","植物会长得很快。"],["La population croît chaque année.","人口每年增长。"]],"co":[["croître rapidement","快速增长"],["la croissance économique","经济增长"],["croître et se multiplier","繁衍生息"]],"sy":[["pousser","courant","（植物）生长，更口语"],["augmenter","courant","增加"],["grandir","courant","（人、孩子）长大"]],"fq":"中低频，书面语和科学文章中出现。","me":"croissant 就是「正在长大的月亮」；croître = 长大。","tr":{"zh":"这座城市的人口每年增长。","fr":"La population de cette ville croît chaque année.","alt":"La population de cette ville augmente chaque année.","note":"口语里常用 augmenter 代替 croître。"}},
 "Décrypter": {"pos":"v. 动词，第一组，规则变位，助动词 avoir","s":"破译（密码、文字、信息）；解读（难懂的东西）。décrypter un message = 解开一条加密的信息；也可比喻义：看懂难懂的文件或别人的意图。","ipa":"[de.kʁip.te]","ph":"dé [de]；cryp 读 [kʁip]，y 读 [i]；p 要读出来；结尾 -er 读 [e]。","pi":"y 读 [i]；p 要读出来（和 compter 的 p 不同）；不是 [de.kʁip.tœʁ]，结尾 -er 读 [e]。","et":"由前缀 dé-（去掉）+ crypter（加密，来自希腊语 kryptos「隐藏的」）构成。","ex":[["Il essaie de décrypter le message.","他试图破译这条消息。"],["Les experts ont décrypté le texte ancien.","专家们破译了这段古文。"]],"co":[["décrypter un message","破译信息"],["décrypter un code","破译密码"],["décrypter l'actualité","解读时事"]],"sy":[["déchiffrer","courant","辨认、解读（文字、手写）"],["décoder","courant","解码"],["interpréter","courant","解释、解读"]],"fq":"中低频，科技与新闻用语。","me":"dé- 去掉 + crypt- 加密：把加密去掉。英语 decrypt 一样。","tr":{"zh":"他们花了一年才破译这个密码。","fr":"Ils ont mis un an à décrypter ce code.","alt":"Il leur a fallu un an pour décrypter ce code.","note":"mettre + 时间 + à + 原形：花多长时间做某事。"}},
 "Développer": {"pos":"v. 动词，第一组，规则变位，助动词 avoir；代词式 se développer","s":"发展；扩大；开发；展开（想法）；冲洗（照片）。développer un projet = 发展一个项目；se développer = 发展、成长。","ipa":"[dev.lɔ.pe]","ph":"dé [de]；v [v]；e 轻读 [l] 前常省略，标准写作 [dev.lɔ.pe]；pp 读一个 [p]；结尾 -er 读 [e]。","pi":"拼写是双 p：développer（英语 develop 只有一个 p）；重音在最后一个音节；pp 只读一个 [p]。","et":"由 dé- + 古法语 voloper（包起来）构成，voloper 的更早来源不确定；与 envelopper（包裹）同族。","ex":[["Nous voulons développer ce projet.","我们想发展这个项目。"],["Cette ville se développe vite.","这座城市发展得很快。"],["Il faut développer vos idées.","您要展开您的想法。"]],"co":[["développer une entreprise","发展企业"],["se développer","发展；成长"],["développer des photos","冲洗照片"],["pays en voie de développement","发展中国家"]],"sy":[["agrandir","courant","扩大"],["évoluer","courant","演变"],["élaborer","soutenu","精心制定"]],"fq":"高频，工作和新闻中很常见。","me":"dé-velopper：和 envelopper 相反，把包着的东西「展开」。","tr":{"zh":"公司想在国外发展业务。","fr":"L'entreprise veut développer son activité à l'étranger.","alt":"La boîte veut se développer à l'étranger.","note":"développer 是及物动词；se développer 表示「自己发展」。"}},
 "Disparaître": {"pos":"v. 动词，第三组，助动词 avoir（也可用 être，但 avoir 最常见）；变位像 paraître","s":"消失；不见；去世（委婉）。Il a disparu = 他不见了。espèce en voie de disparition = 濒危物种。过去分词 disparu。","ipa":"[dis.pa.ʁɛtʁ]","ph":"dis [dis]；pa [pa]；raî 读 [ʁɛ]；tre 读 [tʁ]，e 不发音。","pi":"î 读 [ɛ]，所以和 paraître 一样。是 disparaître，不是 desparaître；现在时 il disparaît 需要 î。","et":"由 dis-（分开，否定）+ paraître（出现）构成；paraître 来自拉丁语 parescere。","ex":[["Le soleil va disparaître.","太阳将消失。"],["Mon portefeuille a disparu !","我的钱包不见了！"],["Cette espèce est en voie de disparition.","这个物种濒临灭绝。"]],"co":[["disparaître de la circulation","销声匿迹"],["une espèce en voie de disparition","濒危物种"],["faire disparaître qqch","使某物消失"],["la disparition","消失（名词）"]],"sy":[["s'évanouir","soutenu","消散；晕倒"],["partir","courant","离开"],["s'éteindre","littéraire","渐渐熄灭；委婉指去世"]],"fq":"中高频，日常和新闻都常用。","me":"dis + paraître：先出现 (paraître)，再「取消」(dis) = 消失。","tr":{"zh":"我的猫昨晚不见了。","fr":"Mon chat a disparu hier soir.","alt":"Mon chat a disparu hier soir, je suis inquiet.","note":"disparaître 的过去分词是 disparu，没有 î。"}},
 "Éloigner": {"pos":"v. 动词，第一组，规则变位，助动词 avoir；代词式 s'éloigner","s":"使远离；拉开距离；把……移开。éloigner qqn de qqch = 让某人远离某物。代词式 s'éloigner = 走远、远离。","ipa":"[e.lwa.ɲe]","ph":"é [e]；oi 读 [wa]；gn 读 [ɲ]，像西班牙语 ñ；结尾 -er 读 [e]。","pi":"gn 是 [ɲ]，不是 [gn]；oi 是 [wa]；注意拼写 é-loign-，不是 eloigner（要有 é）。","et":"由 é-（离开）+ loin（远，来自拉丁语 longe）构成。同源：lointain、longue。","ex":[["Il faut éloigner les enfants du feu.","要让孩子远离火。"],["Éloigne-toi de la fenêtre !","离窗户远一点！"],["Elle s'éloigne de plus en plus.","她越走越远。"]],"co":[["éloigner qqn de qqch","使某人远离某物"],["s'éloigner de ...","远离……"],["éloigner le danger","避开危险"]],"sy":[["écarter","courant","拨开；移开"],["repousser","courant","推开；击退"],["distancer","courant","拉开距离，超过"]],"fq":"中频，日常和书面均可。","me":"é + loin：让它「出到远处」。想到 loin = 远。","tr":{"zh":"请让孩子离火炉远一点。","fr":"Éloignez les enfants de la cuisinière, s'il vous plaît.","alt":"Tenez les enfants loin de la cuisinière, s'il vous plaît.","note":"éloigner ... de ...：de 引出被远离的东西。"}},
 "Germer": {"pos":"v. 动词，第一组，规则变位，助动词 avoir","s":"发芽；萌芽。种子 la graine 会 germer。也可比喻义：一个想法开始萌生（Une idée germe dans son esprit）。germer 不及物，无直接宾语。","ipa":"[ʒɛʁ.me]","ph":"g 在 e 前读 [ʒ]；er 读 [ɛʁ]；m [m]；结尾 -er 读 [e]。","pi":"第一个 er 读 [ɛʁ]（r 要读），结尾的 -er 读 [e]（r 不读）；两个 -er 读音不同。","et":"来自拉丁语 germinare（发芽），germen（芽、胚）。同源：un germe（芽；细菌）。","ex":[["La graine commence à germer.","种子开始发芽。"],["Une idée a germé dans mon esprit.","我脑中萌生了一个想法。"]],"co":[["une graine qui germe","发芽的种子"],["faire germer des haricots","让豆子发芽"],["une idée germe","一个想法萌生"]],"sy":[["pousser","courant","生长"],["éclore","littéraire","绽放；孵化"],["naître","courant","诞生"]],"fq":"中低频，园艺与科学话题里出现。","me":"germer 里有 germe（芽），像英语 germ。","tr":{"zh":"豆子在三天后发芽。","fr":"Les haricots germent au bout de trois jours.","alt":"Les haricots commencent à germer après trois jours.","note":"au bout de + 时间：经过……之后。"}},
 "Lancer": {"pos":"v. 动词，第一组，变位 c → ç：nous lançons，助动词 avoir；代词式 se lancer","s":"扔；发射；发起；启动；推出（产品、项目）。lancer un ballon = 扔球；lancer un projet = 启动项目；lancer une fusée = 发射火箭。se lancer = 投身、放手去做。","ipa":"[lɑ̃.se]","ph":"an 读鼻化 [ɑ̃]；c 在 e 前读 [s]；结尾 -er 读 [e]。","pi":"nous lançons 时 c 要写成 ç（保持 [s] 音）；lan 的 an 是鼻音，不读 n。","et":"来自晚期拉丁语 lanceare，源自 lancea（长矛）。同源：une lance、le lancement。","ex":[["Nous allons lancer ce projet l'année prochaine.","明年我们将启动这个项目。"],["Il lance la balle au chien.","他把球扔给狗。"],["Ils lancent une fusée demain.","他们明天发射火箭。"]],"co":[["lancer un produit","推出产品"],["lancer un appel","发出呼吁"],["lancer un défi","发起挑战"],["se lancer dans ...","投身于……"]],"sy":[["jeter","courant","扔（有时带丢弃意味）"],["envoyer","courant","送出、发送"],["démarrer","courant","启动、开始"]],"fq":"极高频，日常和工作都用得很多。","me":"lance + er：「用长矛扔出去」，英语 launch 同源。","tr":{"zh":"他们下个月要推出新产品。","fr":"Ils vont lancer un nouveau produit le mois prochain.","alt":"Ils sortent un nouveau produit le mois prochain.","note":"aller + 原形表示近期将来。"}},
 "Mesurer": {"pos":"v. 动词，第一组，规则变位，助动词 avoir","s":"测量；量；（人、物）有……高/长。Je mesure 1,70 m = 我身高 1.70 米。也有「衡量、权衡」的比喻义：mesurer les risques。","ipa":"[mə.zy.ʁe]","ph":"me 轻读 [mə]；s 在两个元音之间读 [z]；u [y]；结尾 -er 读 [e]。","pi":"s 读 [z]，不是 [s]；说身高时用 mesurer，不用 être：Je mesure 1,70 m。","et":"来自拉丁语 mensurare（测量），源自 mensura。同源：la mesure、la mensuration。","ex":[["Je vais mesurer la table.","我来量桌子。"],["Combien mesures-tu ?","你多高？"],["Il faut mesurer les risques.","要衡量风险。"]],"co":[["mesurer la longueur de ...","量……的长度"],["Je mesure 1,70 m.","我身高一米七。"],["mesurer ses paroles","斟酌言辞"],["sur mesure","量身定做的"]],"sy":[["évaluer","courant","评估"],["peser","courant","称重量"],["jauger","soutenu","估量、衡量"]],"fq":"高频，日常和学习都常用。","me":"mesurer 里有 mesure：英语 measure 的法语版。","tr":{"zh":"你多高？我一米六五。","fr":"Tu mesures combien ? Moi, je mesure 1,65 m.","alt":"Tu fais quelle taille ? Moi, je fais 1,65 m.","note":"问身高：Tu mesures combien ?"}},
 "Multiplier": {"pos":"v. 动词，第一组，规则变位，助动词 avoir；代词式 se multiplier","s":"乘；成倍增加；使增多。数学里 multiplier 3 par 4 = 3 乘以 4。也可指增多：Les accidents se multiplient（事故越来越多）。","ipa":"[myl.ti.pli.je]","ph":"mul 读 [myl]，u 是 [y]；ti 读 [ti]；pli [pli]；结尾 -ier 读 [je]。","pi":"u 读 [y]，不是 [u]；结尾 -ier 读 [je]；nous multiplions 里的 -ions 是 [jɔ̃]，不要漏掉 i。","et":"来自拉丁语 multiplicare，由 multus（很多）+ plicare（折叠）构成。同源：multiple、multitude。","ex":[["Il faut multiplier les efforts.","必须加倍努力。"],["Trois multiplié par quatre font douze.","三乘四等于十二。"],["Les problèmes se multiplient.","问题越来越多。"]],"co":[["multiplier par ...","乘以……"],["se multiplier","繁殖；增多"],["multiplier les efforts","加倍努力"],["la table de multiplication","乘法表"]],"sy":[["augmenter","courant","增加"],["accroître","soutenu","增加，书面"],["diviser","courant","除，是反义词"]],"fq":"中频，数学、新闻中都有。","me":"multi + plier：折叠很多次，数目就成倍增加。","tr":{"zh":"二乘以五等于十。","fr":"Deux multiplié par cinq font dix.","alt":"Deux fois cinq, ça fait dix.","note":"口语说 deux fois cinq，不用 multiplier。"}},
 "Nettoyer": {"pos":"v. 动词，第一组，-oyer 类动词：je nettoie, nous nettoyons；助动词 avoir","s":"清洁；打扫；擦干净。可用于房间、衣服、伤口、电脑数据等。le nettoyage = 清洁。nettoyer à sec = 干洗。","ipa":"[nɛ.twa.je]","ph":"ne 读 [nɛ]；tt 读一个 [t]；oy 读 [waj] 的前部 [wa]+[j]；结尾 -er 读 [e]。","pi":"单数变位里 y 变成 i：je nettoie, tu nettoies, il nettoie（不发 [j]）；nous nettoyons 才有 y。注意是双 t。","et":"由 net（干净，来自拉丁语 nitidus「发亮的」）+ 动词后缀 -oyer 构成。同源：net、nettement。","ex":[["Je dois nettoyer ma chambre.","我得打扫房间。"],["Elle nettoie les vitres chaque semaine.","她每周擦窗户。"],["Nous nettoyons la cuisine ensemble.","我们一起打扫厨房。"]],"co":[["nettoyer à fond","彻底打扫"],["nettoyer la maison","打扫房子"],["nettoyer à sec","干洗"],["un produit pour nettoyer","清洁用品"]],"sy":[["laver","courant","洗（用水）"],["balayer","courant","扫"],["astiquer","familier","擦亮"]],"fq":"极高频，日常家务必会。","me":"net = 干净；nettoyer = 让它变得 net。","tr":{"zh":"周末我们要把整个房子打扫干净。","fr":"Ce week-end, nous allons nettoyer toute la maison.","alt":"Ce week-end, on va faire le ménage dans toute la maison.","note":"on va faire le ménage 是口语常说法。"}},
 "Posséder": {"pos":"v. 动词，第一组，变位有重音变化：je possède, nous possédons；助动词 avoir","s":"拥有；占有；具有（财产、特点、能力）。比 avoir 正式，强调所有权。Elle possède une grande maison。也可指「精通」：posséder une langue。","ipa":"[pɔ.se.de]","ph":"o [ɔ]；ss 读 [s]；é [e]；结尾 -er 读 [e]。","pi":"ss 读 [s]，不是 [z]；变位时 é 在单数和第三人称复数变成 è：je possède [pɔ.sɛd]。","et":"来自拉丁语 possidere（占有），由 potis（能够）+ sedere（坐）构成。同族：possession（所有权）。","ex":[["Je possède une voiture.","我有一辆车。"],["Elle possède trois appartements.","她拥有三套公寓。"],["Il possède un grand talent.","他很有才华。"]],"co":[["posséder un bien","拥有财产"],["posséder un talent","有天赋"],["posséder la langue","精通这门语言"],["la possession de ...","对……的拥有"]],"sy":[["avoir","courant","有，日常最常用"],["détenir","soutenu","持有、保管"],["disposer de","soutenu","拥有……可用"]],"fq":"中高频，比 avoir 更书面。","me":"possède = 「坐在上面」(sedere)：占住了，就是你的。","tr":{"zh":"他拥有一家小公司。","fr":"Il possède une petite entreprise.","alt":"Il a une petite entreprise.","note":"日常口语常用 avoir，posséder 更正式。"}},
 "Pousser": {"pos":"v. 动词，第一组，规则变位，助动词 avoir","s":"1) 推；挤；促使。2) （植物、头发、牙）生长。Les fleurs poussent = 花在长。Ne me pousse pas ! = 别推我！两个意思差别很大，看上下文。","ipa":"[pu.se]","ph":"ou [u]；ss 读 [s]；结尾 -er 读 [e]。","pi":"ou 读 [u]，不是 [ɔ]；两个意思（推 / 生长）都叫 pousser；英语 push 同源，但法语还有「生长」的意思。","et":"来自拉丁语 pulsare（推、敲）。同源：英语 push，法语 la poussée（推力）、le pouls（脉搏）。","ex":[["Les fleurs poussent très vite.","花长得很快。"],["Ne me pousse pas !","别推我！"],["Mes cheveux poussent vite.","我的头发长得很快。"]],"co":[["pousser la porte","推门"],["laisser pousser ses cheveux","留长头发"],["pousser un cri","大叫一声"],["pousser qqn à + 原形","促使某人做……"]],"sy":[["croître","soutenu","（植物）生长，书面"],["tirer","courant","拉，是 pousser 的反义词"],["encourager","courant","鼓励"]],"fq":"极高频，两个意思都很常用。","me":"pousser = push；花「推」着往上长，就是 pousser。","tr":{"zh":"这些西红柿在花园里长得很好。","fr":"Ces tomates poussent très bien dans le jardin.","alt":"Les tomates, ça pousse bien dans mon jardin.","note":"植物生长用 pousser；推人用 pousser qqn。"}},
 "Ramasser": {"pos":"v. 动词，第一组，规则变位，助动词 avoir","s":"捡起；拾起；收集；收拢。ramasser les feuilles = 捡落叶；ramasser les copies = 收卷子。口语 se ramasser = 摔倒。比 prendre 强调「从地上或各处把东西拾起」。","ipa":"[ʁa.ma.se]","ph":"r [ʁ]；a [a]；m [m]；ss 读 [s]；结尾 -er 读 [e]。","pi":"ss 读 [s]，不是 [z]；不要把 ramasser 说成「收集」整套东西，那更像 collectionner。","et":"由 re- + amasser（堆积）构成；amasser 由 à + masse（堆）构成。","ex":[["Je vais ramasser les feuilles.","我去捡落叶。"],["Ramasse ton stylo, il est tombé.","把你的笔捡起来，它掉了。"],["Le prof ramasse les copies.","老师收卷子。"]],"co":[["ramasser les feuilles","捡落叶"],["ramasser les copies","收卷子"],["ramasser des champignons","采蘑菇"],["ramasser les ordures","收垃圾"]],"sy":[["prendre","courant","拿"],["cueillir","courant","采摘（花、果）"],["collecter","soutenu","收集、募集"]],"fq":"中高频，日常生活常用。","me":"ra-masser：把东西重新（re）聚成一堆（masse）。","tr":{"zh":"孩子们在公园里捡落叶。","fr":"Les enfants ramassent des feuilles dans le parc.","alt":"Les enfants font un tas de feuilles dans le parc.","note":"ramasser 后直接接宾语。"}},
 "S'empoisonner": {"pos":"v. 代词式动词，第一组，规则变位；复合时态用 être：je me suis empoisonné(e)","s":"中毒；服毒；（口语）自寻烦恼。s'empoisonner avec des champignons = 吃蘑菇中毒。他动用法：empoisonner qqn = 给某人下毒。","ipa":"[sɑ̃.pwa.zɔ.ne]","ph":"s'em 读 [sɑ̃]；oi 读 [wa]；s 在元音间读 [z]；结尾 -er 读 [e]。","pi":"em- 读鼻化 [ɑ̃]，不是 [ɛm]；s 读 [z]；注意是代词式，要有 se / me / te。复合时态助动词用 être。","et":"由 en- + poison（毒药，拉丁语 potio「饮品」）+ 动词后缀 -er 构成。poison 与 potion 同源。","ex":[["Attention à ne pas s'empoisonner.","小心别中毒。"],["Il s'est empoisonné avec des champignons.","他吃蘑菇中毒了。"],["Elle s'empoisonne la vie avec ses soucis.","她因为烦恼把自己的生活搞得很糟。"]],"co":[["s'empoisonner avec ...","因……中毒"],["empoisonner qqn","给某人下毒"],["un champignon empoisonné","毒蘑菇（带毒的）"],["s'empoisonner la vie","自寻烦恼"]],"sy":[["s'intoxiquer","soutenu","中毒（常指食物或化学物）"],["avoir une intoxication","courant","食物中毒"],["empoisonner","courant","毒害（他动）"]],"fq":"中低频，谈食物与安全时出现。","me":"en + poison + er：把毒放进身体里。","tr":{"zh":"他吃了坏掉的蘑菇，中毒了。","fr":"Il s'est empoisonné avec des champignons.","alt":"Il a eu une intoxication à cause de champignons.","note":"代词式动词的复合时态用 être，过去分词要与主语一致。"}},
 "S'engager": {"pos":"v. 代词式动词，第一组，nous nous engageons（加 e）；复合时态用 être","s":"投身；参与；承诺；参军。s'engager à + 原形 = 承诺做某事；s'engager dans l'armée = 参军；s'engager dans une cause = 投身某项事业。名词 un engagement = 承诺；投入。","ipa":"[sɑ̃.ɡa.ʒe]","ph":"s'en 读 [sɑ̃]；ga 读 [ɡa]；g 在 e 前读 [ʒ]；结尾 -er 读 [e]。","pi":"第一个 g 读 [ɡ]，第二个 g 读 [ʒ]；nous nous engageons 里 g 后要加 e，保持 [ʒ] 音。","et":"由 en- + gage（抵押、保证）+ -er 构成；gage 来自法兰克语 *wadi。","ex":[["Il veut s'engager dans l'armée.","他想入伍。"],["Je m'engage à venir demain.","我保证明天来。"],["Elle s'engage pour l'écologie.","她投身环保事业。"]],"co":[["s'engager à + 原形","承诺做……"],["s'engager dans l'armée","参军"],["s'engager pour une cause","为某项事业奋斗"],["un engagement","承诺；投入"]],"sy":[["promettre","courant","答应"],["s'investir","courant","投入精力"],["s'enrôler","soutenu","应征入伍"]],"fq":"中高频，新闻和职场常用。","me":"en + gage：把自己「押」上去，就是投身、承诺。","tr":{"zh":"我答应下周帮你搬家。","fr":"Je m'engage à t'aider à déménager la semaine prochaine.","alt":"Je te promets de t'aider à déménager la semaine prochaine.","note":"s'engager à + 原形：承诺做某事。"}},
 "Se mobiliser": {"pos":"v. 代词式动词，第一组，规则变位；复合时态用 être","s":"动员起来；行动起来；集结力量（为了某个目标）。Nous devons nous mobiliser = 我们必须行动起来。他动用法：mobiliser des forces = 调动力量。名词 la mobilisation。","ipa":"[sə mɔ.bi.li.ze]","ph":"se 轻读 [sə]；mo 读 [mɔ]；b [b]；结尾 -er 读 [e]；s 在元音间读 [z]。","pi":"mobi 的 o 读 [ɔ]；s 读 [z]；注意是代词式，别漏掉 se。","et":"来自 mobile（拉丁语 mobilis「能动的」）加后缀 -iser（使成为）。","ex":[["Nous devons nous mobiliser.","我们必须行动起来。"],["Les élèves se mobilisent contre la pollution.","学生们为反对污染行动起来。"]],"co":[["se mobiliser pour ...","为……行动起来"],["se mobiliser contre ...","起来反对……"],["mobiliser des fonds","筹集资金"],["la mobilisation générale","总动员"]],"sy":[["s'engager","courant","投身"],["se rassembler","courant","集合"],["réagir","courant","作出反应"]],"fq":"中频，新闻和社会话题常见。","me":"mobile + iser：让人动起来。","tr":{"zh":"我们必须行动起来保护森林。","fr":"Nous devons nous mobiliser pour protéger la forêt.","alt":"Il faut qu'on se mobilise pour protéger la forêt.","note":"devoir + se 动词原形，代词随主语变：nous devons nous mobiliser。"}},
 "Se situer": {"pos":"v. 代词式动词，第一组，规则变位；复合时态用 être","s":"位于；处在（某处或某个水平）。多用第三人称：La maison se situe près du lac。比 être 稍正式，也可指评价、水平：Le prix se situe autour de 10 euros。","ipa":"[sə si.tɥe]","ph":"se 轻读 [sə]；si [si]；tu 读 [tɥ]（u 变半元音）；结尾 -er 读 [e]。","pi":"situer 里的 -ue- 读 [ɥe]，像一个音节，不是 si-tu-er；注意 se 不能漏。","et":"来自拉丁语 situs（位置），situare。同源：la situation、le site。","ex":[["La maison se situe près du lac.","房子在湖附近。"],["L'hôtel se situe au centre-ville.","酒店在市中心。"],["Le prix se situe autour de dix euros.","价格大约在十欧元左右。"]],"co":[["se situer à ...","位于……"],["se situer près de ...","在……附近"],["se situer entre ... et ...","介于……和……之间"],["Où se situe ... ?","……在哪里？"]],"sy":[["se trouver","courant","位于，最常用"],["être","courant","是，在"],["se localiser","soutenu","定位"]],"fq":"中频，旅游与描述地点时常用。","me":"situer 像英语 situate；se situer = 把自己放在某个位置。","tr":{"zh":"我们的酒店在海边。","fr":"Notre hôtel se situe au bord de la mer.","alt":"Notre hôtel est au bord de la mer.","note":"日常口语常直接用 être 或 se trouver。"}},
 "Domestique": {"pos":"adj. 形容词，阴阳同形：domestique，复数 domestiques","s":"家养的（动物）；家庭的；家务的。un animal domestique = 家养动物。les tâches domestiques = 家务。作名词 un(e) domestique = 仆人，较旧、书面。","ipa":"[dɔ.mɛs.tik]","ph":"do [dɔ]；mes 读 [mɛs]；s 读 [s]；ti 读 [tik]，q 读 [k]；结尾 -que 读 [k]，e 不发音。","pi":"结尾 -que 读 [k]；s 在这里是 [s]；不要把 domestique 读成英语 [dəˈmestɪk]。","et":"来自拉丁语 domesticus，源自 domus（房子，家）。同源：domicile（住所）。","ex":[["C'est un animal domestique.","这是一种家养动物。"],["Les tâches domestiques sont partagées.","家务活是大家分担的。"],["Le chat est un animal domestique.","猫是家养动物。"]],"co":[["un animal domestique","家养动物"],["les tâches domestiques","家务活"],["un accident domestique","家庭意外"],["la violence domestique","家庭暴力"]],"sy":[["familial","courant","家庭的"],["apprivoisé","courant","驯服的"],["sauvage","courant","野生的，反义词"]],"fq":"中频，谈动物与家庭生活时用。","me":"domus = 家：domestique 的动物是住在家里的。","tr":{"zh":"狗和猫是家养动物。","fr":"Le chien et le chat sont des animaux domestiques.","alt":"Les chiens et les chats, ce sont des animaux domestiques.","note":"domestique 阴阳同形，复数加 s。"}},
 "Habitable": {"pos":"adj. 形容词，阴阳同形：habitable，复数 habitables","s":"可居住的；能住人的。Cette maison est habitable = 这房子能住。反义词 inhabitable（不能住的）。注意 h 是哑音 h，要连读/省音：une planète habitable。","ipa":"[a.bi.tabl]","ph":"h 不发音；a [a]；bi [bi]；ta [ta]；结尾 -ble 读 [bl]，e 不发音。","pi":"h 不发音：l'habitable；结尾 -able 读 [abl]，不是 [abəl]；和 habité（有人住的）要区分。","et":"来自拉丁语 habitabilis，源自 habitare（居住）。同源：habiter、habitant、habitat。","ex":[["Cette maison est habitable.","这栋房子可以住人。"],["Cet appartement n'est pas habitable.","这套公寓不能住人。"],["Il cherche une planète habitable.","他在找一颗宜居的星球。"]],"co":[["une maison habitable","可居住的房子"],["une planète habitable","宜居星球"],["une surface habitable","居住面积"],["inhabitable","不能居住的"]],"sy":[["habité(e)","courant","有人住的"],["logeable","courant","可容身的（更口语）"],["inhabitable","courant","不能住的，反义词"]],"fq":"中频，房屋与环境话题常用。","me":"habiter + able：能「住」(habiter) 的。","tr":{"zh":"这套公寓很小，但是能住。","fr":"Cet appartement est petit, mais il est habitable.","alt":"L'appartement est petit, mais on peut y habiter.","note":"habitable 形容事物，不形容人。"}},
 "Menacé(e)": {"pos":"adj. 形容词，阴性 menacée，复数 menacés / menacées","s":"受威胁的；面临危险的。une espèce menacée = 濒危物种；être menacé de ... = 面临……的危险。来自动词 menacer（威胁），过去分词作形容词。","ipa":"[mə.na.se]","ph":"me 轻读 [mə]；na [na]；c 在 e 前读 [s]；阳性 menacé 结尾 é 读 [e]；阴性 menacée 读音相同。","pi":"阴性 menacée 比阳性多一个 e，但读音一样；c 读 [s]；注意变位 nous menaçons 要加 ç。","et":"来自动词 menacer（拉丁语 minaciae「威胁」），源自 minari（威吓）。同源：英语 menace。","ex":[["Cet animal est menacé.","这种动物受到威胁。"],["Cette forêt est menacée par le feu.","这片森林受到火灾威胁。"]],"co":[["une espèce menacée","濒危物种"],["menacé de disparition","面临灭绝"],["menacé par ...","受……威胁"],["se sentir menacé","感到受威胁"]],"sy":[["en danger","courant","处于危险中"],["en péril","soutenu","危在旦夕"],["protégé","courant","受保护的，反义思路"]],"fq":"中频，环保新闻里很常见。","me":"menace + é：被「menace」(威胁) 的。","tr":{"zh":"这种鸟现在受到威胁。","fr":"Cet oiseau est menacé aujourd'hui.","alt":"Cet oiseau est en danger aujourd'hui.","note":"形容词随名词变阴阳性：une espèce menacée。"}},
 "Pollué(e)": {"pos":"adj. 形容词，阴性 polluée，复数 pollués / polluées","s":"被污染的。l'air pollué = 被污染的空气；une rivière polluée = 被污染的河。来自动词 polluer（污染）；反义词 propre。","ipa":"[pɔ.lɥe]","ph":"po 读 [pɔ]；ll 读一个 [l]；ué 读 [ɥe]（u 变半元音）；阴性 polluée 读音相同。","pi":"ll 只读一个 [l]；-ué 要连成一个音节 [ɥe]，不要读成 po-lu-é；阴性多一个 e，不改发音。","et":"来自拉丁语 polluere（弄脏），动词 polluer 的过去分词。同源：la pollution、英语 pollute。","ex":[["L'air est pollué.","空气被污染了。"],["La rivière est très polluée.","这条河污染得很严重。"]],"co":[["l'air pollué","被污染的空气"],["une ville polluée","被污染的城市"],["une eau polluée","被污染的水"],["polluer l'environnement","污染环境"]],"sy":[["sale","courant","脏的"],["contaminé","soutenu","被污染的（含细菌、化学物）"],["propre","courant","干净的，反义词"]],"fq":"中高频，环保话题常用。","me":"pollu- 像英语 pollute；加 é = 被污染的。","tr":{"zh":"这座城市的空气污染得很严重。","fr":"L'air de cette ville est très pollué.","alt":"Il y a beaucoup de pollution dans l'air de cette ville.","note":"pollué 随名词变性数：une rivière polluée。"}},
 "Sauvage": {"pos":"adj. 形容词，阴阳同形：sauvage，复数 sauvages","s":"野生的；野蛮的；荒凉的；怕生的。un animal sauvage = 野生动物；une plage sauvage = 无人开发的海滩。形容人可指「不爱交际的」。注意：它不一定含贬义，常常只是「未被驯化」。","ipa":"[so.vaʒ]","ph":"au 读 [o]；v [v]；a [a]；g 在 e 前读 [ʒ]；结尾 e 不发音。","pi":"au 读 [o]，不是 [au]；g 读 [ʒ]；和英语 savage（野蛮的）不同，法语 sauvage 常常只是「野生的」，并无贬义。","et":"来自拉丁语 silvaticus，源自 silva（森林）。同源：英语 savage、sylvestre（森林的）。","ex":[["C'est un animal sauvage.","这是一种野生动物。"],["Nous avons trouvé une plage sauvage.","我们找到了一片未开发的海滩。"],["Mon chat est un peu sauvage.","我的猫有点怕生。"]],"co":[["un animal sauvage","野生动物"],["la nature sauvage","原始自然"],["une plage sauvage","无人开发的海滩"],["camper en pleine nature, en sauvage","野外露营"]],"sy":[["domestique","courant","家养的，反义词"],["féroce","courant","凶猛的"],["timide","courant","害羞的"]],"fq":"中高频，自然和动物话题常用。","me":"sauvage ← silva（森林）：住在森林里的，就是野生的。","tr":{"zh":"这只狐狸是野生的，不要碰它。","fr":"Ce renard est sauvage, ne le touche pas.","alt":"C'est un renard sauvage, ne le touche pas.","note":"sauvage 阴阳同形；un renard / une renarde。"}},
 "Stagnant(e)": {"pos":"adj. 形容词，阴性 stagnante，复数 stagnants / stagnantes","s":"不流动的（水）；停滞的（经济、局面）。l'eau stagnante = 死水；une économie stagnante = 停滞的经济。动词 stagner（停滞，不动）。","ipa":"[staɡ.nɑ̃]","ph":"sta 读 [sta]；g 读 [ɡ]（前面有 a 后面有 n）；n 读 [n]；结尾 -ant 读鼻化 [ɑ̃]，t 不发音。","pi":"g 要读 [ɡ]，是 [staɡ.nɑ̃]，不是 [sta.ɲɑ̃]（不是 gn）；阳性结尾 t 不发音，阴性 stagnante 要读 t。","et":"来自拉丁语 stagnare（形成水潭），stagnum（池塘）。同源：英语 stagnant、stagnate。","ex":[["Des moustiques peuvent pondre des oeufs dans l'eau stagnante.","蚊子可能在死水里产卵。"],["L'économie est stagnante depuis deux ans.","经济已经停滞了两年。"]],"co":[["de l'eau stagnante","死水"],["une économie stagnante","停滞的经济"],["des prix stagnants","停滞不动的价格"],["stagner","停滞，不流动"]],"sy":[["immobile","courant","不动的"],["croupi(e)","courant","发臭的（水）"],["en panne","courant","停滞，出故障"]],"fq":"中低频，环境和经济报道里出现。","me":"stagn- 是「池塘」，水不流就成了池塘。英语 stagnant。","tr":{"zh":"不要在死水旁边坐着，有蚊子。","fr":"Ne reste pas près de l'eau stagnante, il y a des moustiques.","alt":"Évite l'eau stagnante, il y a des moustiques.","note":"stagnante 阴性，修饰 l'eau（阴性）。"}},
 "Satisfait(e)": {"pos":"adj. 形容词，阴性 satisfaite，复数 satisfaits / satisfaites","s":"满意的；满足的。être satisfait de qqch = 对某事满意。也可作「满足了」。来自动词 satisfaire（使满意）的过去分词。","ipa":"[sa.tis.fɛ]","ph":"sa [sa]；tis 读 [tis]；fait 读 [fɛ]，ai 读 [ɛ]，t 不发音；阴性 satisfaite 读 [sa.tis.fɛt]，t 要读出来。","pi":"阳性结尾 t 不发音，阴性要读 [t]；用介词 de，不是 avec：satisfait de ...。","et":"来自拉丁语 satisfacere，由 satis（足够）+ facere（做）构成。同源：英语 satisfy、satisfaction。","ex":[["Je suis satisfait de ce travail.","我对这份工作满意。"],["Elle n'est pas satisfaite du résultat.","她对结果不满意。"]],"co":[["être satisfait de ...","对……满意"],["un client satisfait","满意的顾客"],["se déclarer satisfait","表示满意"],["satisfaire un besoin","满足需要"]],"sy":[["content(e)","courant","高兴的，更口语"],["ravi(e)","courant","很高兴的，程度更强"],["comblé(e)","soutenu","满足的、心满意足的"]],"fq":"中高频，评价和服务场景常用。","me":"satis（足够）+ fait（做过了）：做够了，就满意。","tr":{"zh":"顾客们对服务很满意。","fr":"Les clients sont satisfaits du service.","alt":"Les clients sont contents du service.","note":"satisfait 随主语变性数：satisfaits。"}},
 "Touché(e)": {"pos":"adj. 形容词，阴性 touchée，复数 touchés / touchées","s":"被感动的；受触动的；（也可指）被击中的、受影响的。Je suis touché(e) par ... = 我被……打动了。在击剑或游戏里 Touché ! = 击中了！","ipa":"[tu.ʃe]","ph":"ou 读 [u]；ch 读 [ʃ]；é 读 [e]；阴性 touchée 读音相同。","pi":"ou 读 [u]，ch 读 [ʃ]；不要把「触动」和身体触摸混淆：être touché par un geste 是被感动。","et":"toucher 的过去分词；toucher 的来源是拟声词，较不确定。形态上与名词 le toucher（触觉）同族。","ex":[["J'ai vraiment été touché par ton geste.","你的举动真的打动了我。"],["Elle est très touchée par votre message.","她很感动于您的留言。"],["Touché ! Tu as raison.","说得好！你说对了。"]],"co":[["être touché par ...","被……感动 / 受……影响"],["profondément touché","深受感动"],["Touché !","击中了！/ 说中了！"],["une région touchée par la crise","受危机影响的地区"]],"sy":[["ému(e)","courant","感动的，激动的"],["bouleversé(e)","courant","深受震动的"],["affecté(e)","soutenu","受影响的"]],"fq":"中高频，表达感谢与感受时常用。","me":"touch + é：心被「touch」到了。","tr":{"zh":"你的信让我很感动。","fr":"Votre lettre m'a beaucoup touché.","alt":"Je suis très touché par votre lettre.","note":"être touché par ...：被动结构，par 引出原因。"}},
 "Urbain(e)": {"pos":"adj. 形容词，阴性 urbaine，复数 urbains / urbaines","s":"城市的；都市的。la vie urbaine = 城市生活；le paysage urbain = 城市风光；les transports urbains = 城市交通。反义词 rural(e)（乡村的）。","ipa":"[yʁ.bɛ̃]","ph":"u 读 [y]；r [ʁ]；b [b]；ain 读鼻化 [ɛ̃]；阴性 urbaine 读 [yʁ.bɛn]，n 要读出来。","pi":"u 读 [y]，不是 [u]；阳性 -ain 是鼻音 [ɛ̃]，阴性 -aine 读 [ɛn]，差别很大。","et":"来自拉丁语 urbanus，源自 urbs（城市）。同源：英语 urban、urbanisme（城市规划）。","ex":[["J'aime le paysage urbain.","我喜欢城市风光。"],["Les transports urbains sont pratiques.","城市交通很方便。"],["Cette zone urbaine est très peuplée.","这个城区人口很密集。"]],"co":[["une zone urbaine","城区"],["la vie urbaine","城市生活"],["les transports urbains","城市交通"],["l'urbanisme","城市规划"]],"sy":[["citadin(e)","courant","城里的；城里人"],["rural(e)","courant","乡村的，反义词"],["municipal(e)","courant","市政的"]],"fq":"中频，地理与社会话题常用。","me":"urb- 是「城」：英语 urban，法语 urbain。","tr":{"zh":"我更喜欢城市生活。","fr":"Je préfère la vie urbaine.","alt":"Moi, j'aime mieux la vie en ville.","note":"urbain 修饰阴性名词时写 urbaine：la vie urbaine。"}},
 "Collectivement": {"pos":"adv. 副词，来自形容词 collectif (阴性 collective) 加 -ment","s":"集体地；共同地；一起（作为一个团体）。Nous agissons collectivement = 我们共同行动。反义词 individuellement（个别地）。","ipa":"[kɔ.lɛk.tiv.mɑ̃]","ph":"co [kɔ]；llec 读 [lɛk]，ll 只读一个 [l]；ti [tiv]；结尾 -ment 读鼻化 [mɑ̃]，t 不发音。","pi":"-ment 读 [mɑ̃]，不是 [mɛnt]；ll 只读一个 [l]；副词从阴性形容词 collective 加 -ment 得来。","et":"来自 collectif（阴性 collective）+ -ment；collectif 来自拉丁语 colligere（收集，聚在一起）。","ex":[["Nous agissons collectivement.","我们共同行动。"],["La décision a été prise collectivement.","这个决定是集体做出的。"]],"co":[["agir collectivement","集体行动"],["décider collectivement","集体决定"],["travailler collectivement","集体工作"],["responsable collectivement","共同负责"]],"sy":[["ensemble","courant","一起，更日常"],["en groupe","courant","以小组形式"],["individuellement","courant","个别地，反义词"]],"fq":"中频，书面语和新闻中出现较多。","me":"collective + -ment：「集体地」，英语 collectively。","tr":{"zh":"我们应该共同决定。","fr":"Nous devons décider collectivement.","alt":"On doit décider tous ensemble.","note":"副词 collectivement 放在动词后面。"}},
 "Individuellement": {"pos":"adv. 副词，来自形容词 individuel (阴性 individuelle) 加 -ment","s":"个别地；各自地；单独地。Nous travaillons individuellement = 我们各自工作。反义词 collectivement。常用来说「一个一个地」处理。","ipa":"[ɛ̃.di.vi.dɥɛl.mɑ̃]","ph":"in 读鼻化 [ɛ̃]；di [di]；vi [vi]；duel 读 [dɥɛl]；结尾 -ment 读 [mɑ̃]。","pi":"词很长，分音节：in-di-vi-duel-le-ment 读 [ɛ̃.di.vi.dɥɛl.mɑ̃]；-ment 读 [mɑ̃]；ll 读 [l]。","et":"来自 individuel（阴性 individuelle）+ -ment；individu 来自拉丁语 individuus（不可分割的）。","ex":[["Nous travaillons individuellement.","我们各自工作。"],["Chaque élève est évalué individuellement.","每个学生都单独接受评价。"]],"co":[["travailler individuellement","独立工作"],["traiter individuellement","逐个处理"],["évaluer individuellement","逐个评估"],["chacun individuellement","每个人各自"]],"sy":[["séparément","courant","分别地"],["seul(e)","courant","独自"],["collectivement","courant","集体地，反义词"]],"fq":"中频，学习和工作场景中出现。","me":"individu（个人）+ -ellement：「一个人一个人地」。","tr":{"zh":"老师单独跟每个学生谈话。","fr":"Le professeur parle à chaque élève individuellement.","alt":"Le prof voit chaque élève un par un.","note":"副词常放在动词后面。"}},
 "Y'a pas un rat": {"pos":"loc. 口语短语（familier），y'a = il y a 的口语缩略","s":"一个人也没有（字面：连一只老鼠都没有）。口语里形容地方很空、没人。y'a 是 il y a 的口语缩略，只在说话里出现；书面应说 Il n'y a personne。","ipa":"[ja pa zœ̃ ʁa]","ph":"y'a 读 [ja]；pas 的 s 不发音；un 读 [œ̃]；pa-s-un 之间常连读成 [pa zœ̃]；rat 的 t 不发音。","pi":"rat 的 t 不发音，读 [ʁa]；pas un 之间可连读；y'a 的写法有时作 ya，但最好写成 y'a。","et":"il y a 的口语缩略加上 rat（老鼠）作夸张，意思是「连老鼠都不在」；这种夸张说法的起源不确定。","ex":[["Le magasin est vide, y'a pas un rat.","商店是空的，一个人都没有。"],["À minuit, dans la rue, y'a pas un rat.","半夜街上一个人也没有。"]],"co":[["y'a pas un chat","没有一个人（同义说法）"],["il n'y a personne","没有人（标准说法）"],["être vide, désert","空的，荒凉的"]],"sy":[["il n'y a personne","courant","没有人，标准说法"],["y'a pas un chat","familier","连只猫都没有，同义"],["désert","courant","没有人的（形容词）"]],"fq":"口语中常见，不适合书面。","me":"连老鼠 (rat) 都没有，那就是真没人。","tr":{"zh":"晚上十一点，街上一个人都没有。","fr":"À onze heures du soir, y'a pas un rat dans la rue.","alt":"À onze heures du soir, il n'y a personne dans la rue.","note":"y'a pas un rat 是口语，写作和正式场合用 il n'y a personne。"}},
 "Avoir le cafard": {"pos":"loc. 口语短语（familier），固定搭配，avoir 变位","s":"情绪低落；心情不好；闷闷不乐。字面是「有蟑螂」，指心里有只「黑色的虫」让人沮丧。不必真的有蟑螂。反义：avoir la pêche（精神很好）。","ipa":"[a.vwaʁ lə ka.faʁ]","ph":"avoir 读 [a.vwaʁ]；le 轻读 [lə]；cafard 读 [ka.faʁ]，结尾 d 不发音。","pi":"cafard 结尾 d 不发音，读 [ka.faʁ]；不要字面理解成「有蟑螂」。","et":"cafard 本义「蟑螂」，来自阿拉伯语 kāfir（不信教者）的说法，常被引用，但传播细节不完全确定；「有蟑螂=情绪低落」是比喻。","ex":[["Il pleut et j'ai le cafard.","下雨了，我心情不好。"],["Elle a le cafard depuis qu'elle a déménagé.","自从搬家后，她一直情绪低落。"]],"co":[["avoir le cafard","情绪低落"],["donner le cafard à qqn","让某人心情不好"],["avoir un coup de cafard","突然情绪低落"],["avoir le blues","心情忧郁"]],"sy":[["avoir le blues","familier","同义，心情忧郁"],["avoir le moral dans les chaussettes","familier","情绪很低落"],["être triste","courant","伤心"]],"fq":"口语常见，朋友间日常使用。","me":"想象一只黑色的蟑螂 (cafard) 趴在心上，心情当然不好。","tr":{"zh":"冬天的时候，我常常心情低落。","fr":"En hiver, j'ai souvent le cafard.","alt":"L'hiver, j'ai souvent le blues.","note":"avoir le cafard 要随主语变位：j'ai, tu as, il a。"}},
 "Avoir le choix": {"pos":"loc. 固定短语，avoir 变位；le choix 为阳性名词","s":"有选择；可以选。Tu as le choix = 你可以选。否定：Je n'ai pas le choix = 我别无选择。choix 是阳性名词，复数不变（des choix）。","ipa":"[a.vwaʁ lə ʃwa]","ph":"avoir 读 [a.vwaʁ]；le 轻读 [lə]；choix 读 [ʃwa]，ch 读 [ʃ]，oi 读 [wa]，x 不发音。","pi":"choix 结尾 x 不发音；ch 读 [ʃ]；单复数同形 choix。","et":"choix 来自动词 choisir，choisir 源自哥特语 kausjan（品尝，试）；这是常见说法。","ex":[["Je veux avoir le choix.","我想有选择。"],["Tu as le choix entre le thé et le café.","你可以在茶和咖啡之间选。"],["Je n'ai pas le choix.","我别无选择。"]],"co":[["avoir le choix entre ... et ...","在……与……之间可选"],["ne pas avoir le choix","别无选择"],["laisser le choix à qqn","让某人自己选"],["au choix","任选"]],"sy":[["choisir","courant","选择（动词）"],["pouvoir choisir","courant","可以选"],["avoir une option","courant","有一个选项"]],"fq":"极高频，日常对话必会。","me":"Tu as le choix ! = 「你有 (as) 选择」，choix 读 [ʃwa]，像中文「瓜」。","tr":{"zh":"你可以在鱼和鸡肉之间选。","fr":"Tu as le choix entre le poisson et le poulet.","alt":"Tu peux choisir entre le poisson et le poulet.","note":"avoir le choix entre A et B。"}},
 "Avoir peur pour ...": {"pos":"loc. 固定短语，avoir 变位；后接 pour + 人/物","s":"为……担心；替……害怕（担心别人或事物的安全）。注意区分：avoir peur de qqn / qqch = 害怕某人或某物；avoir peur pour qqn = 替某人担心。","ipa":"[a.vwaʁ pœʁ puʁ]","ph":"avoir [a.vwaʁ]；peur 读 [pœʁ]，eu 读 [œ]；pour 读 [puʁ]，ou 读 [u]。","pi":"peur [pœʁ] 和 pour [puʁ] 容易混；peur 是阴性名词（la peur）；pour 与 de 意思差别很大。","et":"peur 来自拉丁语 pavor；pour 来自拉丁语 pro。这两个词都是常用基础词，更早的来源不再展开。","ex":[["J'ai eu peur pour toi !","我为你担心过！"],["Elle a peur pour son fils.","她为儿子担心。"],["On a eu peur pour lui.","我们替他担心过。"]],"co":[["avoir peur pour qqn","为某人担心"],["avoir peur de qqn / qqch","害怕某人/某物"],["avoir peur de + 原形","害怕做某事"],["faire peur à qqn","吓到某人"]],"sy":[["s'inquiéter pour","courant","为……担心"],["craindre pour","soutenu","为……忧虑"],["se faire du souci pour","courant","替……操心"]],"fq":"高频，表达关心时日常常用。","me":"peur pour toi：为「你」害怕，不是怕「你」。","tr":{"zh":"你开夜车，我为你担心。","fr":"Je suis inquiet, j'ai peur pour toi quand tu conduis la nuit.","alt":"Je m'inquiète pour toi quand tu conduis la nuit.","note":"pour 引出担心的对象；de 引出害怕的对象。"}},
 "Casser trois pattes à un canard": {"pos":"loc. 习语，常用否定：ne pas casser trois pattes à un canard","s":"没什么了不起；不怎么样（字面：折断鸭子的三条腿）。通常用否定：Ce film ne casse pas trois pattes à un canard = 这部电影平平无奇。鸭子只有两条腿，所以「三条腿」是夸张的荒谬说法。","ipa":"[ka.se tʁwa pat a œ̃ ka.naʁ]","ph":"casser [ka.se]；trois 读 [tʁwa]，s 不发音；pattes 读 [pat]；à un 之间连读 [a œ̃]；canard 读 [ka.naʁ]，d 不发音。","pi":"trois 的 s 不发音；canard 的 d 不发音；pattes 有两个 t，读一个 [t]；整个习语一般用否定。","et":"来自一个夸张的民间说法：鸭子只有两条腿，「折断三条腿」本身就是荒谬的。这种说法的起源不太确定。","ex":[["Ce film ne casse pas trois pattes à un canard.","这部电影没什么了不起。"],["Franchement, ce plat ne casse pas trois pattes à un canard.","说实话，这道菜没什么特别的。"]],"co":[["ne pas casser trois pattes à un canard","没什么了不起"],["ça ne casse rien","没什么了不起（同义）"],["ce n'est pas terrible","不怎么样"]],"sy":[["ça ne casse rien","familier","没什么了不起"],["ce n'est pas terrible","familier","不怎么样"],["médiocre","courant","平庸的"]],"fq":"口语习语，较为常见，多用否定。","me":"想象折断鸭子的三条腿：太夸张，所以其实是「没什么了不起」。","tr":{"zh":"这本书没什么了不起。","fr":"Ce livre ne casse pas trois pattes à un canard.","alt":"Ce livre, ce n'est pas terrible.","note":"这个习语几乎总是用否定句。"}},
 "Cocorico": {"pos":"n.m. / interj. 阳性名词，也作拟声词；复数 cocoricos（不常用）","s":"喔喔喔（法语里公鸡的叫声）。也是对法国国家象征公鸡（le coq gaulois）的玩笑说法：喊 Cocorico ! 表示为法国的成就感到骄傲，常用于体育或经济新闻。","ipa":"[kɔ.kɔ.ʁi.ko]","ph":"co 读 [kɔ]；co 读 [kɔ]；ri 读 [ʁi]；co 读 [ko]。四个音节：co-co-ri-co，最后一个 o 读 [o]。","pi":"不是 [kokorikɔ]；第一、二个 o 是 [ɔ]，最后一个 o 读 [o]；r 是小舌音。","et":"拟声词，模仿公鸡的叫声。","ex":[["Le coq fait cocorico.","公鸡叫「喔喔喔」。"],["La France a gagné ? Cocorico !","法国赢了？为法国骄傲！"],["Le matin, on entend cocorico.","早上能听到公鸡叫。"]],"co":[["faire cocorico","（公鸡）叫；为法国自豪"],["le coq gaulois","高卢雄鸡（法国象征）"],["pousser un cocorico","喊一声喔喔喔 / 以法国为荣"]],"sy":[["coq","courant","公鸡"],["fierté nationale","soutenu","民族自豪感"],["chauvinisme","soutenu","狭隘的民族主义"]],"fq":"中低频，农场与体育新闻里偶尔出现。","me":"co-co-ri-co：像公鸡一样一口气喊出来。","tr":{"zh":"公鸡每天早上都喔喔叫。","fr":"Le coq fait cocorico tous les matins.","alt":"Tous les matins, le coq chante cocorico.","note":"拟声词不需要翻译，直接用 faire + 声音。"}},
 "En cas d'urgence": {"pos":"loc. 固定短语（介词短语）","s":"紧急情况下；万一出现紧急情况时。常见于告示：En cas d'urgence, appelez le 112。cas 阳性，d'urgence 的 urgence 为阴性名词。","ipa":"[ɑ̃ ka da.ʁyʒɑ̃s]","ph":"en 读 [ɑ̃]；cas 读 [ka]，s 不发音；d'urgence 读 [da.ʁyʒɑ̃s]；u 读 [y]；g 读 [ʒ]；结尾 -ence 读 [ɑ̃s]。","pi":"cas 的 s 不发音；d'urgence 中 d'u 要连读；urgence 中 u 读 [y]，不是 [u]。","et":"cas 来自拉丁语 casus（事件、情况）；urgence 来自拉丁语 urgere（催促，逼迫）。","ex":[["Appelez ce numéro en cas d'urgence.","紧急情况请拨这个号码。"],["En cas d'urgence, restez calme.","遇到紧急情况，请保持冷静。"]],"co":[["en cas d'urgence","紧急情况下"],["en cas de besoin","需要时"],["en cas de danger","遇到危险时"],["un numéro d'urgence","紧急电话"]],"sy":[["en cas de besoin","courant","必要时"],["en cas de problème","courant","有问题时"],["d'urgence","courant","紧急地"]],"fq":"高频，告示和安全提示中很常见。","me":"en cas de + 名词：「万一……」，比如 en cas de feu / de danger。","tr":{"zh":"遇到紧急情况，请打 112。","fr":"En cas d'urgence, appelez le 112.","alt":"Si c'est urgent, appelez le 112.","note":"en cas de + 无冠词名词。"}},
 "Le meilleur ami de l'homme": {"pos":"loc. 固定短语（名词短语），meilleur 为阳性","s":"人类最好的朋友（通常指狗）。Le chien est le meilleur ami de l'homme。meilleur 是 bon 的比较级和最高级，阴性是 meilleure。","ipa":"[lə mɛ.jœʁ a.mi də lɔm]","ph":"le [lə]；meilleur 读 [mɛ.jœʁ]，eill 读 [ɛj]，eu 读 [œ]，r 要读；ami 读 [a.mi]；de [də]；l'homme 读 [lɔm]，h 不发音。","pi":"meilleur 的 ill 读 [j]，不是 [l]；homme 的 h 不发音，所以是 l'homme；meilleur 的 r 读出来。","et":"meilleur 来自拉丁语 melior（更好的），bon 的比较级。ami 来自拉丁语 amicus（朋友）。","ex":[["Le chien est le meilleur ami de l'homme.","狗是人类最好的朋友。"],["On dit que le chien est le meilleur ami de l'homme.","人们说狗是人类最好的朋友。"]],"co":[["le meilleur ami / la meilleure amie","最好的朋友（男/女）"],["le meilleur ami de l'homme","人类最好的朋友"],["mon meilleur ami","我最好的朋友"],["le meilleur de tous","所有里最好的"]],"sy":[["le compagnon fidèle","soutenu","忠实的伙伴"],["un ami fidèle","courant","忠实的朋友"]],"fq":"中高频，谈宠物时常用的固定说法。","me":"meilleur = 最好 (best)；ami = 朋友；狗是 man's best friend。","tr":{"zh":"很多人说狗是人类最好的朋友。","fr":"Beaucoup de gens disent que le chien est le meilleur ami de l'homme.","alt":"On dit souvent que le chien est le meilleur ami de l'homme.","note":"le meilleur = 定冠词 + 最高级。"}},
 "Poser un lapin": {"pos":"loc. 口语短语（familier），poser 变位，复合时态 avoir","s":"放鸽子；爽约（约好了不来）。Il m'a posé un lapin = 他放了我鸽子。字面是「放下一只兔子」。对象用间接宾语：poser un lapin à qqn。","ipa":"[po.ze œ̃ la.pɛ̃]","ph":"poser 读 [po.ze]，s 在元音间读 [z]；un 读 [œ̃]，与 poser 之间不连读；lapin 读 [la.pɛ̃]，结尾 in 读鼻化 [ɛ̃]。","pi":"s 读 [z]；lapin 的 in 读 [ɛ̃]，不读 n；对象要用 à qqn 或间接宾语代词（me, te, lui）。","et":"这个说法的起源不确定，有多种说法，没有公认解释。","ex":[["Il m'a posé un lapin hier.","他昨天放了我鸽子。"],["Elle a posé un lapin à son ami.","她放了朋友鸽子。"],["Ne me pose pas un lapin !","别放我鸽子！"]],"co":[["poser un lapin à qqn","放某人鸽子"],["se faire poser un lapin","被人放鸽子"],["un rendez-vous","约会，约定"]],"sy":[["faire faux bond","courant","爽约，放鸽子"],["ne pas venir","courant","没有来"],["se défiler","familier","临阵退缩"]],"fq":"口语中常用，朋友之间常听到。","me":"兔子 (lapin) 跑得没影了：约好了的人也没影了，所以是放鸽子。","tr":{"zh":"我等了他一个小时，他放了我鸽子。","fr":"Je l'ai attendu une heure, il m'a posé un lapin.","alt":"Je l'ai attendu une heure, il n'est jamais venu.","note":"poser un lapin à qqn：和间接宾语 me, te, lui 搭配。"}},
 "Prendre la route": {"pos":"loc. 固定短语，prendre 为不规则动词，复合时态 avoir","s":"上路；出发；启程（通常指开车或出远门）。Nous prenons la route demain matin = 我们明天早上出发。也有「走某条路」的意思：prendre la route de Paris。","ipa":"[pʁɑ̃dʁ la ʁut]","ph":"prendre 读 [pʁɑ̃dʁ]，en 读 [ɑ̃]，e 不发音；la [la]；route 读 [ʁut]，ou 读 [u]。","pi":"prendre 的 en 读 [ɑ̃]；变位 je prends 的 s 不发音，nous prenons 读 [pʁə.nɔ̃]，ils prennent 读 [pʁɛn]。","et":"prendre 来自拉丁语 prehendere；route 来自拉丁语 (via) rupta（开辟出来的路），常见说法。","ex":[["Nous allons prendre la route demain.","我们明天上路。"],["Ils ont pris la route à six heures.","他们六点出发了。"],["Il vaut mieux prendre la route tôt.","最好早点上路。"]],"co":[["prendre la route","上路；出发"],["être sur la route","在路上"],["bonne route !","一路平安！"],["se mettre en route","动身；启动"]],"sy":[["partir","courant","出发"],["se mettre en route","courant","动身"],["démarrer","familier","出发；发动"]],"fq":"高频，旅行和日常出行常用。","me":"prendre la route = 把路「拿」起来，开始走。","tr":{"zh":"我们明早七点上路。","fr":"Nous prenons la route demain à sept heures.","alt":"On part demain matin à sept heures.","note":"prendre la route 后常接时间或目的地。"}},
 "Prendre ses responsabilités": {"pos":"loc. 固定短语，prendre 为不规则动词；ses 随主语变（mes, tes, ses...）","s":"承担责任；负起责任。所有格要和主语一致：Je prends mes responsabilités, Il prend ses responsabilités。表示不再逃避，做出决定并为后果负责。","ipa":"[pʁɑ̃dʁ se ʁɛs.pɔ̃.sa.bi.li.te]","ph":"prendre [pʁɑ̃dʁ]；ses 读 [se]，s 不发音；responsabilités 读 [ʁɛs.pɔ̃.sa.bi.li.te]；on 读鼻化 [ɔ̃]；结尾 -és 读 [e]。","pi":"responsabilités 很长，注意 r、on、sa、bi、li、té；结尾 s 不发音；所有格 ses 要随主语变。","et":"responsabilité 来自 responsable（拉丁语 respondere「回答」）加后缀 -ité。prendre 来自拉丁语 prehendere。","ex":[["Il faut prendre ses responsabilités.","必须承担责任。"],["Je prends mes responsabilités.","我承担我的责任。"],["Il est temps de prendre vos responsabilités.","是时候负起您的责任了。"]],"co":[["prendre ses responsabilités","承担责任"],["avoir des responsabilités","有职责"],["fuir ses responsabilités","逃避责任"],["une lourde responsabilité","沉重的责任"]],"sy":[["assumer","courant","承担，如 assumer ses responsabilités"],["s'engager","courant","做出承诺"],["se défiler","familier","推卸，逃避"]],"fq":"高频，职场和日常对话里常用。","me":"responsabilités：能「回答」(répondre) 的事，就要自己接住 (prendre)。","tr":{"zh":"你已经长大了，该负起责任了。","fr":"Tu es grand maintenant, il faut prendre tes responsabilités.","alt":"Tu es grand, il est temps d'assumer tes responsabilités.","note":"所有格随主语变：prendre tes responsabilités。"}},
 "Prendre soin de ...": {"pos":"loc.verbale 动词短语（prendre 第三组动词，助动词 avoir）","s":"照顾；爱护；小心对待。后面接人、动物或物品：prendre soin de sa santé（注意健康）。也可以接动词不定式：prendre soin de fermer la porte（记得把门关好）。","ipa":"[pʁɑ̃dʁ swɛ̃ də]","ph":"pre-/en- 都读鼻化音 [ɑ̃]；dre 结尾的 e 轻读；oi 读 [wa]，但 soin 里 oin 读 [wɛ̃]；de 读 [də]。","pi":"soin 不读 [swa-ɛ̃]，是 [swɛ̃]；注意是单数 soin，不是 soins。后面用 de，不是 à。","et":"prendre 来自拉丁语 prehendere（抓、拿）；soin 来自古法语 soing，源头多认为是法兰克语，细节不确定。","ex":[["Je dois prendre soin de mon chat.","我得照顾我的猫。"],["Prends soin de toi !","照顾好自己！"],["Elle prend soin de ses grands-parents.","她照顾她的祖父母。"]],"co":[["Prends soin de toi !","照顾好自己！（告别时常说）"],["prendre soin de sa santé","注意健康"],["prendre soin de + 动词不定式","小心地做某事"],["avoir soin de + 动词不定式","留意去做（较书面）"]],"sy":[["s'occuper de","courant","负责照看，语气更日常、更宽泛"],["veiller sur","soutenu","守护、看护，更温柔、更郑重"],["négliger","courant","反义：疏忽、不管"]],"fq":"高频，日常常用。","me":"prendre（拿）+ soin（关心）：把关心「拿在手里」就是照顾。","tr":{"zh":"你要照顾好你的小狗。","fr":"Tu dois prendre soin de ton chien.","alt":"Occupe-toi bien de ton chien.","note":"prendre soin de + 名词；de 后遇元音要省音：prendre soin d'un chien。"}},
 "Quand les poules auront des dents": {"pos":"loc.adv. 固定表达（引导时间从句，用将来完成式的结构）","s":"永远不会；绝无可能。字面是「等母鸡长出牙齿的时候」，母鸡没有牙，所以事情永远不会发生。口语、带点幽默，多用来拒绝或讽刺。","ipa":"[kɑ̃ le pul o.ʁɔ̃ de dɑ̃]","ph":"Quand 的 d 不发音，读 [kɑ̃]；les 读 [le]；poules 的 ou 读 [u]，s 不发音；auront 读 [o.ʁɔ̃]；dents 的 -nts 不发音，读 [dɑ̃]。","pi":"auront 是 avoir 的将来时（elles auront）。quand 后面用将来时，这点和中文习惯不同。别把 dents 的 t、s 读出来。","et":"来自母鸡没有牙齿的常识，是一句形象的民间说法。","ex":[["Il paiera quand les poules auront des dents.","等母鸡长牙他才会付钱。"],["Tu me prêteras ta voiture quand les poules auront des dents !","你借我车？等母鸡长牙吧！"],["Elle rangera sa chambre quand les poules auront des dents.","她收拾房间？除非母鸡长牙。"]],"co":[["Quand les poules auront des dents","永远不可能"],["Il paiera quand les poules auront des dents.","他永远不会付钱。"],["Jamais de la vie !","绝对不行！"]],"sy":[["jamais","courant","从不；最直接的说法"],["à la Saint-Glinglin","familier","遥遥无期（也是幽默说法）"],["quand on verra les poules avec des dents","familier","同样的意思，换一种说法"]],"fq":"中频，口语，带幽默。","me":"想象一只母鸡咧嘴露出牙齿：不可能，所以「永远不」。","tr":{"zh":"他会还我钱？等母鸡长牙吧！","fr":"Il me rendra l'argent quand les poules auront des dents !","alt":"Il me rendra mon argent à la Saint-Glinglin.","note":"quand 后接将来时（rendra / auront）。"}},
 "Reprendre son souffle": {"pos":"loc.verbale 动词短语（reprendre 第三组动词，助动词 avoir）","s":"喘口气；缓一缓。跑步或爬楼梯后让呼吸恢复，也可用于比喻（忙完一阵后歇一歇）。souffle 是「气息、呼吸」。","ipa":"[ʁə.pʁɑ̃dʁ sɔ̃ su.fl]","ph":"re- 读 [ʁə]；-prend- 读鼻化 [ɑ̃]；son 读 [sɔ̃]；souffle 的 ou 读 [u]，ff 只发一个 [f]，结尾 e 轻。","pi":"souffle 里的 ou 是 [u]，不是 [sɔ]；ff 不是两个音。son 要随主语变：reprendre mon / ton / son / notre souffle。","et":"re-（再）+ prendre（拿）；souffle 是动词 souffler 的名词，来自拉丁语 sufflare（吹气）。","ex":[["Je dois reprendre mon souffle.","我得喘口气。"],["Il s'arrête pour reprendre son souffle.","他停下来喘口气。"],["Après la course, elle reprend son souffle.","跑完步，她缓了缓气。"]],"co":[["reprendre son souffle","喘口气"],["à bout de souffle","上气不接下气；精疲力尽"],["retenir son souffle","屏住呼吸"],["avoir du souffle","气息足；有耐力"]],"sy":[["souffler","courant","歇口气，更口语"],["se reposer","courant","休息，范围更宽"],["haleter","soutenu","喘息（强调喘得厉害）"]],"fq":"中频，日常常用。","me":"re（再）+ prendre（拿）+ souffle（气）：把气「再拿回来」。","tr":{"zh":"我们停一下，让我喘口气。","fr":"Arrêtons-nous un moment, je dois reprendre mon souffle.","alt":"On s'arrête cinq minutes, que je reprenne mon souffle.","note":"物主词要和主语一致：je → mon souffle。"}},
 "Revenons à nos moutons": {"pos":"loc. 固定句（revenir 的命令式 nous 形式）","s":"言归正传；回到正题。谈话跑题之后，用它把话题拉回来。语气自然、略带幽默，朋友之间和工作场合都能说。","ipa":"[ʁə.və.nɔ̃ a no mu.tɔ̃]","ph":"Revenons 读 [ʁə.və.nɔ̃]，中间 e 轻读；à 读 [a]；nos 的 s 不发音，读 [no]；moutons 的 ou 读 [u]，s 不发音，结尾鼻化 [tɔ̃]。","pi":"moutons 是复数，别写成 mouton。nos 的 s 在这里不发音（后面是辅音 m）。revenir 的命令式 nous 形式是 revenons。","et":"出自 15 世纪的法国喜剧《巴特兰律师》（La Farce de Maître Pathelin）：一位律师不断拿羊说事，法官就说「回到我们的羊」。","ex":[["Bref, revenons à nos moutons.","总之，言归正传。"],["On s'est éloignés du sujet. Revenons à nos moutons.","我们跑题了。言归正传。"],["Bon, revenons à nos moutons : où est la clé ?","好了，言归正传：钥匙在哪里？"]],"co":[["Bref, revenons à nos moutons.","总之，言归正传。"],["revenir au sujet","回到主题"],["On s'égare.","我们跑题了。"]],"sy":[["revenons au sujet","courant","回到主题，普通说法"],["pour en revenir à...","courant","回到……（接具体话题）"],["sauter du coq à l'âne","courant","反义：东拉西扯"]],"fq":"中频，口语里常见。","me":"想象牧羊人把跑远的羊（moutons）赶回来。","tr":{"zh":"好了，言归正传：我们几点出发？","fr":"Bon, revenons à nos moutons : on part à quelle heure ?","alt":"Bref, revenons au sujet : à quelle heure on part ?","note":"命令式 nous 形式：revenons，不加主语 nous。"}},
 "Sans doute": {"pos":"loc.adv. 副词短语","s":"大概；很可能；多半。注意：法语里 sans doute 通常只是「很可能」，不是百分之百确定。要表示「毫无疑问」，要说 sans aucun doute 或 sans le moindre doute。","ipa":"[sɑ̃ dut]","ph":"sans 读 [sɑ̃]，s 结尾不发音；doute 的 ou 读 [u]，t 要读出来，结尾 e 不发音。","pi":"容易误以为是「无疑」。其实只是「大概」。doute 的 t 要发，和中文听感不同；sans 的 n、s 不发。","et":"sans 来自拉丁语 sine（没有）；doute 来自动词 douter，拉丁语 dubitare（犹豫、怀疑）。","ex":[["Il va sans doute pleuvoir.","很可能会下雨。"],["Elle est sans doute en retard.","她大概迟到了。"],["Sans aucun doute, c'est lui.","毫无疑问，就是他。"]],"co":[["sans aucun doute","毫无疑问"],["sans doute que + 从句","大概……（口语）"],["Sans doute !","很可能！"],["sans le moindre doute","毫无疑问（强调）"]],"sy":[["probablement","courant","很可能，意思最接近"],["peut-être","courant","也许，把握更小"],["certainement","courant","一定，把握更大"]],"fq":"极高频，日常常用。","me":"sans doute 看着像「没有怀疑」，其实只是「多半」，别被字面骗了。","tr":{"zh":"他大概在家。","fr":"Il est sans doute à la maison.","alt":"Il doit être à la maison.","note":"sans doute 表示很可能，不是百分之百确定。"}},
 "Sauter du coq à l'âne": {"pos":"loc.verbale 动词短语（sauter 第一组动词，助动词 avoir）","s":"东拉西扯；话题跳来跳去，没有逻辑。字面是「从公鸡跳到驴」。可以用来形容说话的人，也可以形容一场谈话。","ipa":"[so.te dy kɔk a lɑn]","ph":"sau- 读 [so]；-ter 读 [te]；du 的 u 读 [y]；coq 的 q 读 [k]，o 读 [ɔ]；l'âne 里 â 读 [ɑ]，e 不发音。","pi":"du 的 u 是 [y]，不是 [u]（和 dou 不同）。coq 结尾的 q 要发 [k]。âne 要写帽子 â，l'âne 因省音写成 l'。","et":"16 世纪起就有的说法，源自一种叫 coq-à-l'âne 的、故意东拉西扯的诗体。来源细节不必深究。","ex":[["Il a tendance à sauter du coq à l'âne.","他总是东拉西扯。"],["Tu sautes du coq à l'âne, je ne te suis plus.","你一下说这个一下说那个，我跟不上了。"],["Pendant le repas, on saute du coq à l'âne.","吃饭时我们天南海北地聊。"]],"co":[["sauter du coq à l'âne","东拉西扯"],["passer d'un sujet à l'autre","从一个话题转到另一个"],["un coq-à-l'âne","不连贯的话；跑题的话"]],"sy":[["passer du coq à l'âne","courant","同义，也常说"],["partir dans tous les sens","familier","说话漫无边际"],["revenir à nos moutons","courant","反义：回到正题"]],"fq":"中频，口语中常用。","me":"公鸡和驴毫不相干，话题也一样。","tr":{"zh":"我弟弟说话总是东拉西扯。","fr":"Mon frère saute toujours du coq à l'âne.","alt":"Mon frère passe son temps à sauter du coq à l'âne.","note":"toujours 放在动词之后；sauter de... à...。"}},
 "Un petit geste": {"pos":"n.m. 阳性名词词组，复数 des petits gestes","s":"小小的心意；小举动。指不费力但让人温暖的行为，比如帮个小忙、送点小礼物。在商店里，faire un petit geste 也可以指给点优惠。","ipa":"[œ̃ pə.ti ʒɛst]","ph":"un 读鼻化 [œ̃]；petit 的 t 在 un petit geste 里不连读，结尾不发音，读 [pə.ti]；geste 的 g 读 [ʒ]，st 都要发出来，结尾 e 不发音。","pi":"geste 是阳性，所以是 un petit geste，不是 une。geste 的 s、t 都要读：[ʒɛst]。别把 g 读成 [g]。","et":"geste 来自拉丁语 gestus（动作、姿态），源于 gerere（做、带着）。","ex":[["C'est un petit geste sympa.","这是个友好的小举动。"],["Merci pour ce petit geste !","谢谢你这份小心意！"],["Le vendeur a fait un petit geste sur le prix.","店员在价格上给了点优惠。"]],"co":[["faire un petit geste","表示一点心意；给点优惠"],["un geste d'amitié","友好的表示"],["un beau geste","高尚的举动"],["les petits gestes du quotidien","生活中的小举动"]],"sy":[["une attention","courant","一份心意、体贴"],["un cadeau","courant","礼物"],["un coup de main","familier","帮个忙"]],"fq":"中频，日常常用。","me":"petit（小）+ geste（动作）：小动作，大温暖。","tr":{"zh":"这是一份小小的心意，给你的。","fr":"C'est un petit geste pour toi.","alt":"Un petit quelque chose pour toi.","note":"geste 是阳性，用 un。"}},
 "Une bonne nouvelle": {"pos":"n.f. 阴性名词词组，复数 de bonnes nouvelles","s":"好消息。法语里 nouvelle 是可数名词：une bonne nouvelle（一条好消息）。复数 les nouvelles 还可指「新闻；近况」：donner des nouvelles（报个平安）。","ipa":"[yn bɔn nu.vɛl]","ph":"une 读 [yn]，u 是 [y]；bonne 的 nn 读 [bɔn]；nouvelle 的 ou 读 [u]，ll 读 [l]，结尾 e 不发音。","pi":"u 是 [y]，不是 [u]。nouvelle 是阴性，所以是 une bonne。复数时前面常用 de：de bonnes nouvelles。","et":"nouvelle 是形容词 nouveau（新的）的阴性，来自拉丁语 novellus，意思是「新的东西」。bonne 来自拉丁语 bonus。","ex":[["J'ai une bonne nouvelle.","我有一个好消息。"],["J'ai une bonne nouvelle et une mauvaise.","我有一个好消息，也有一个坏消息。"],["Tu as de bonnes nouvelles de ta mère ?","你妈妈有好消息吗？"]],"co":[["annoncer une bonne nouvelle","宣布一个好消息"],["apprendre une bonne nouvelle","得知一个好消息"],["Bonne nouvelle !","好消息！"],["donner des nouvelles","报告近况"]],"sy":[["une heureuse nouvelle","soutenu","喜讯，较书面"],["une mauvaise nouvelle","courant","反义：坏消息"],["une info","familier","信息、消息"]],"fq":"高频，日常常用。","me":"bonne + nouvelle：好 + 新的，每条「新」消息都可数。","tr":{"zh":"我有一个好消息要告诉你。","fr":"J'ai une bonne nouvelle à t'annoncer.","alt":"J'ai une bonne nouvelle pour toi.","note":"nouvelle 可数，用 une；复数用 de bonnes nouvelles。"}},
 "Une mauvaise nouvelle": {"pos":"n.f. 阴性名词词组，复数 de mauvaises nouvelles","s":"坏消息。和 une bonne nouvelle 相对。nouvelle 可数，常说 une mauvaise nouvelle。口语开场常说 J'ai une mauvaise nouvelle。","ipa":"[yn mo.vɛz nu.vɛl]","ph":"une 读 [yn]；mauvaise 里 au 读 [o]，ai 读 [ɛ]，s 在元音间读 [z]；nouvelle 读 [nu.vɛl]。","pi":"mauvaise 的 s 读 [z]，不是 [s]。mauvaise 是阴性形式（阳性 mauvais，词尾 s 不发音）。au 读 [o]，不要读成 [aʊ]。","et":"mauvais 来自古法语 malvais，更远的来源不确定；形容词阴性 mauvaise 由阳性加 -e 构成。nouvelle 见 une bonne nouvelle。","ex":[["C'est une mauvaise nouvelle.","这是个坏消息。"],["J'ai une mauvaise nouvelle pour toi.","我有个坏消息要告诉你。"],["Il a appris une mauvaise nouvelle hier.","他昨天得知了一个坏消息。"]],"co":[["annoncer une mauvaise nouvelle","宣布一个坏消息"],["apprendre une mauvaise nouvelle","得知一个坏消息"],["Pas de nouvelles, bonnes nouvelles.","没消息就是好消息。"],["de mauvaises nouvelles","一些坏消息"]],"sy":[["un mauvais coup","familier","打击；不好的事"],["une triste nouvelle","soutenu","令人难过的消息"],["une bonne nouvelle","courant","反义：好消息"]],"fq":"高频，日常常用。","me":"mauvaise 里的 s 要「嗡」一声，读 [z]。","tr":{"zh":"我有个坏消息，我们的航班取消了。","fr":"J'ai une mauvaise nouvelle : notre vol est annulé.","alt":"Mauvaise nouvelle, notre vol est annulé.","note":"冒号后补充内容；vol 是阳性，所以 annulé 不加 e。"}},
 "Une sorte de ...": {"pos":"loc. 短语（阴性名词 sorte，后接 de + 名词）","s":"一种……；某种……；类似……的东西。当说不出确切名字时，用它来大致描述：une sorte de gâteau。后面的名词通常不带冠词。","ipa":"[yn sɔʁt də]","ph":"une 读 [yn]；sorte 里 o 读 [ɔ]，r 是小舌音 [ʁ]，t 要发，结尾 e 不发音；de 读 [də]。","pi":"sorte 里的 r、t 都要发出来。de 后遇元音要省音：une sorte d'oiseau。sorte 和 sortie（出口）不同，别混。","et":"sorte 来自拉丁语 sors, sortis（命运、抽签得到的一份），后来引申为「种类」。","ex":[["C'est une sorte de gâteau.","这是一种蛋糕。"],["Il y a une sorte de bruit dans le salon.","客厅里有一种声音。"],["Elle porte une sorte d'écharpe verte.","她戴着一种绿色的围巾。"]],"co":[["une sorte de + 名词","一种……"],["toutes sortes de + 名词","各种各样的……"],["en quelque sorte","在某种意义上；可以说"],["de la sorte","这样；以这种方式"]],"sy":[["une espèce de","familier","一种……，口语更常用"],["un genre de","familier","一类……"],["une variété de","soutenu","……的变种、品种"]],"fq":"高频，日常常用。","me":"sorte 听起来像英语 sort：a sort of → une sorte de。","tr":{"zh":"这是一种水果，我不知道它的名字。","fr":"C'est une sorte de fruit, je ne connais pas son nom.","alt":"C'est une espèce de fruit, je ne sais pas comment ça s'appelle.","note":"une sorte de + 无冠词名词。"}},
 "Voir le jour": {"pos":"loc.verbale 动词短语（voir 第三组动词，助动词 avoir）","s":"诞生；问世；出生。字面是「看见白天的光」。可指婴儿出生，更常指项目、作品、产品开始出现：Le projet a vu le jour en 2020。","ipa":"[vwaʁ lə ʒuʁ]","ph":"voir 里 oi 读 [wa]，r 读 [ʁ]；le 读 [lə]；jour 里 j 读 [ʒ]，ou 读 [u]，r 要发。","pi":"voir 的 oi 是 [wa]，不是 [oi]。jour 的 j 是 [ʒ]，不是英语的 [dʒ]。变位要注意：il a vu le jour（vu 是过去分词）。","et":"voir 来自拉丁语 videre（看）；jour 来自拉丁语 diurnum（白天的）。「看见光」是诞生的形象说法。","ex":[["Le projet va voir le jour.","这个项目将问世。"],["Leur bébé a vu le jour en mai.","他们的宝宝五月出生。"],["Ce film n'a jamais vu le jour.","这部电影从未面世。"]],"co":[["voir le jour","诞生；问世"],["un projet qui voit le jour","一个即将诞生的项目"],["ne jamais voir le jour","从未诞生"],["faire voir le jour à","使……问世（书面）"]],"sy":[["naître","courant","出生"],["apparaître","courant","出现"],["venir au monde","courant","来到世上（指出生）"]],"fq":"中频，书面和口语都常见。","me":"新生命第一次看见白天的光：voir le jour。","tr":{"zh":"这个公司是二〇一五年成立的。","fr":"Cette entreprise a vu le jour en 2015.","alt":"Cette entreprise est née en 2015.","note":"voir 的过去分词是 vu，助动词用 avoir。"}}
});
